    [Fact]
    public void NativeGraphicsOverlayRejectsOddBaseBeforeMappingOrVectorReplacement()
    {
        const uint imageBase = 0x00F8_F000;
        const uint oddGraphicsBase = 0x00F9_0001;
        const uint nativeTarget = 0x00FE_1000;
        var image = new byte[0x2000];
        var vectorAddress = unchecked((uint)((int)oddGraphicsBase + (int)GraphicsLvo.LoadView));
        WriteJmp(image, imageBase, vectorAddress, nativeTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));

        Assert.False(services.InstallKickstartRomOverlay(oddGraphicsBase));
        Assert.False(services.IsKickstartRomOverlayInstalled);
        Assert.False(bus.HasHostGateway(vectorAddress));
        Assert.Equal(0x4E, bus.ReadByte(vectorAddress));
        Assert.Equal(0xF9, bus.ReadByte(vectorAddress + 1u));
        Assert.Equal((byte)(nativeTarget >> 24), bus.ReadByte(vectorAddress + 2u));
        Assert.Equal((byte)(nativeTarget >> 16), bus.ReadByte(vectorAddress + 3u));
        Assert.Equal(unchecked((byte)(nativeTarget >> 8)), bus.ReadByte(vectorAddress + 4u));
        Assert.Equal(unchecked((byte)nativeTarget), bus.ReadByte(vectorAddress + 5u));
    }

    [Fact]
    public void RomOverlayRestoresOriginalJumpTableBytesAndLeavesUnlistedVectorsNative()
    {
        var bus = new AmigaBus();
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var image = new byte[0x2000];
        image[(int)(graphicsBase - imageBase)] = 0x12;
        image[(int)(graphicsBase - imageBase) + 1] = 0x34;
        image[(int)(graphicsBase - imageBase - 6)] = 0x56;
        image[(int)(graphicsBase - imageBase - 5)] = 0x78;
        bus.MapReadOnlyMemory(imageBase, image);

        using (var registry = new HostLibraryGatewayRegistry(bus))
        {
            registry.AddLibrary(
                graphicsBase,
                [new HostLibraryGateway((int)GraphicsLvo.InitRastPort, _ => { })]);
            registry.InstallRomOverlays();

            Assert.True(bus.HasHostGateway(unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitRastPort))));
            Assert.Equal((ushort)0x1234, bus.ReadWord(graphicsBase));
            Assert.Equal((ushort)0x5678, bus.ReadWord(graphicsBase - 6));
        }

        Assert.False(bus.HasHostGateway(unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitRastPort))));
        Assert.Equal((ushort)0x1234, bus.ReadWord(graphicsBase));
        Assert.Equal((ushort)0x5678, bus.ReadWord(graphicsBase - 6));
    }

    [Fact]
    public void CopperStartDisplayMemoryCapabilityClassifiesChipRamOnly()
    {
        var bus = new AmigaBus();
        var memory = new HostGuestMemory(bus);
        var adapter = new CopperStartGraphicsMemoryAdapter(
            memory,
            (address, byteCount) =>
                byteCount <= int.MaxValue &&
                memory.IsDisplayDmaRange(address, (int)byteCount));

        Assert.True(memory.IsDisplayDmaRange(0x0000_0100, 4));
        Assert.False(memory.IsDisplayDmaRange(0x0000_0101, 4));
        Assert.False(memory.IsDisplayDmaRange(0x0100_0000, 4));
        Assert.True(adapter.IsDisplayDmaRange(0x0000_0100, 4));
        Assert.False(adapter.IsDisplayDmaRange(0x0000_0101, 4));
        Assert.False(adapter.IsDisplayDmaRange(0x0100_0000, 4));
    }

    [Fact]
    public void GraphicsServicesInstallsAndExecutesOnlyTheMappedNativeSafeSubset()
    {
        var bus = new AmigaBus();
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var image = new byte[0x2000];
        image[(int)(graphicsBase - imageBase - 198)] = 0x12;
        image[(int)(graphicsBase - imageBase - 198) + 1] = 0x34;
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(0x100, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var bitMapBytes = new byte[GraphicsLayouts.BitMapSize];
        bitMapBytes[GraphicsLayouts.BitMapBytesPerRow] = 0;
        bitMapBytes[GraphicsLayouts.BitMapBytesPerRow + 1] = 4;
        bitMapBytes[GraphicsLayouts.BitMapRows] = 0;
        bitMapBytes[GraphicsLayouts.BitMapRows + 1] = 9;
        bitMapBytes[GraphicsLayouts.BitMapDepth] = 3;
        bitMapBytes[GraphicsLayouts.BitMapFlags] = 0x1A;
        const uint bitMapAddress = 0x0080_0000;
        bus.MapWritableMemory(bitMapAddress, bitMapBytes);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        Assert.True(services.IsKickstartRomOverlayInstalled);

        var state = new M68kCpuState { A = { [1] = 0x100 } };
        var initAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitRastPort));
        Assert.True(bus.TryInvokeHostGatewayAt(initAddress, state));
        Assert.Equal((byte)0xFF, bus.ReadByte(0x100 + (uint)GraphicsLayouts.RastPortFgPen));
        bus.WriteWord(0x100u + (uint)GraphicsLayouts.RastPortTextWidth, 8);
        bus.WriteWord(
            0x100u + (uint)GraphicsLayouts.RastPortTextSpacing,
            unchecked((ushort)-2));

        var getPen = new M68kCpuState { A = { [0] = 0x100 }, D = { [0] = 0xFFFF_FFFF } };
        var getPenAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetAPen));
        Assert.True(bus.TryInvokeHostGatewayAt(getPenAddress, getPen));
        Assert.Equal(0xFFu, getPen.D[0]);

        var textLength = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0x100 },
            D = { [0] = 3 }
        };
        var textLengthAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.TextLength));
        Assert.True(bus.TryInvokeHostGatewayAt(textLengthAddress, textLength));
        Assert.Equal(18u, textLength.D[0]);

        var setOutline = new M68kCpuState { A = { [0] = 0x100 }, D = { [0] = 3 } };
        var setOutlineAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetOutlinePen));
        Assert.True(bus.TryInvokeHostGatewayAt(setOutlineAddress, setOutline));
        Assert.Equal(0xFFu, setOutline.D[0]);
        var getOutline = new M68kCpuState { A = { [0] = 0x100 }, D = { [0] = 0xFFFF_FFFF } };
        var getOutlineAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetOutlinePen));
        Assert.True(bus.TryInvokeHostGatewayAt(getOutlineAddress, getOutline));
        Assert.Equal(3u, getOutline.D[0]);

        var getBitmapAttr = new M68kCpuState { A = { [0] = bitMapAddress }, D = { [1] = 8 } };
        var getBitmapAttrAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetBitMapAttr));
        Assert.True(bus.TryInvokeHostGatewayAt(getBitmapAttrAddress, getBitmapAttr));
        Assert.Equal(32u, getBitmapAttr.D[0]);

        var scalerDiv = new M68kCpuState { D = { [0] = 100, [1] = 2, [2] = 1 } };
        var scalerDivAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ScalerDiv));
        Assert.True(bus.TryInvokeHostGatewayAt(scalerDivAddress, scalerDiv));
        Assert.Equal(200u, scalerDiv.D[0]);

        services.Dispose();
        Assert.False(services.IsKickstartRomOverlayInstalled);
        Assert.False(bus.HasHostGateway(initAddress));
        Assert.Equal((ushort)0x1234, bus.ReadWord(initAddress));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveStatusAwareBlitterOwnershipParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        directBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        overlayBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);

        var directOwn = 0;
        var directDisown = 0;
        var directWait = 0;
        var overlayOwn = 0;
        var overlayDisown = 0;
        var overlayWait = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            tryOwnBlitter: () =>
            {
                directOwn++;
                return true;
            },
            tryDisownBlitter: () =>
            {
                directDisown++;
                return true;
            },
            tryWaitBlit: () =>
            {
                directWait++;
                return true;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            tryOwnBlitter: () =>
            {
                overlayOwn++;
                return true;
            },
            tryDisownBlitter: () =>
            {
                overlayDisown++;
                return true;
            },
            tryWaitBlit: () =>
            {
                overlayWait++;
                return true;
            });

        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, cycles) in new[]
        {
            (GraphicsLvo.OwnBlitter, 123L),
            (GraphicsLvo.DisownBlitter, 129L),
            (GraphicsLvo.WaitBlit, 135L)
        })
        {
            var directState = new M68kCpuState
            {
                Cycles = cycles,
                D = { [0] = 0xCAFE_BABEu }
            };
            var overlayState = new M68kCpuState
            {
                Cycles = cycles,
                D = { [0] = 0xCAFE_BABEu }
            };

            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(cycles, directState.Cycles);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        Assert.Equal(1, directOwn);
        Assert.Equal(1, directDisown);
        Assert.Equal(1, directWait);
        Assert.Equal(1, overlayOwn);
        Assert.Equal(1, overlayDisown);
        Assert.Equal(1, overlayWait);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveStatusAwareQueuedBlitterParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint node = 0x200;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
            bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
            bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
            bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);
        }

        var directQueue = new List<(uint Address, bool BeamSynchronized, short BeamSync)>();
        var overlayQueue = new List<(uint Address, bool BeamSynchronized, short BeamSync)>();
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            trySubmitQueuedBlit: (address, beamSynchronized, beamSync) =>
            {
                directQueue.Add((address, beamSynchronized, beamSync));
                return true;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            trySubmitQueuedBlit: (address, beamSynchronized, beamSync) =>
            {
                overlayQueue.Add((address, beamSynchronized, beamSync));
                return true;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, cycles) in new[]
        {
            (GraphicsLvo.QBlit, 161L),
            (GraphicsLvo.QBSBlit, 167L)
        })
        {
            var directState = new M68kCpuState
            {
                A = { [1] = node },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = cycles
            };
            var overlayState = new M68kCpuState
            {
                A = { [1] = node },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = cycles
            };

            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(cycles, directState.Cycles);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        var expected = new[]
        {
            (node, false, (short)-128),
            (node, true, (short)-128)
        };
        Assert.Equal(expected, directQueue);
        Assert.Equal(expected, overlayQueue);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayWaitBlitLeavesQueuedNodePending()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint node = 0x240;
        const uint secondNode = 0x280;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            foreach (var queuedNode in new[] { node, secondNode })
            {
                bus.MapWritableMemory(queuedNode, new byte[GraphicsLayouts.BltNodeSize]);
                bus.WriteLong(queuedNode + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
                bus.WriteWord(queuedNode + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
                bus.WriteWord(queuedNode + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);
            }
        }

        var directFifo = new GraphicsBlitterFifoBackend();
        var overlayFifo = new GraphicsBlitterFifoBackend();
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            timedBlitter: directFifo);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            timedBlitter: overlayFifo);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directQueue = new M68kCpuState
        {
            A = { [1] = node },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        var overlayQueue = new M68kCpuState
        {
            A = { [1] = node },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        direct.Invoke(directQueue, (int)GraphicsLvo.QBlit);
        var qblitAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.QBlit));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(qblitAddress, overlayQueue));

        var directQbs = new M68kCpuState
        {
            A = { [1] = secondNode },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 212
        };
        var overlayQbs = new M68kCpuState
        {
            A = { [1] = secondNode },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 212
        };
        direct.Invoke(directQbs, (int)GraphicsLvo.QBSBlit);
        var qbsAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.QBSBlit));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(qbsAddress, overlayQbs));

        var directWait = new M68kCpuState
        {
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 211
        };
        var overlayWait = new M68kCpuState
        {
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 211
        };
        direct.Invoke(directWait, (int)GraphicsLvo.WaitBlit);
        var waitAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WaitBlit));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(waitAddress, overlayWait));

        Assert.Equal(0u, directQueue.D[0]);
        Assert.Equal(directQueue.D[0], overlayQueue.D[0]);
        Assert.Equal(211, directQueue.Cycles);
        Assert.Equal(directQueue.Cycles, overlayQueue.Cycles);
        Assert.Equal(0u, directWait.D[0]);
        Assert.Equal(directWait.D[0], overlayWait.D[0]);
        Assert.Equal(211, directWait.Cycles);
        Assert.Equal(directWait.Cycles, overlayWait.Cycles);
        Assert.Equal(2, directFifo.Count);
        Assert.Equal(2, overlayFifo.Count);

        Assert.True(directFifo.TryDequeueReady(212, (_, _) => true, out var directFirst));
        Assert.True(overlayFifo.TryDequeueReady(212, (_, _) => true, out var overlayFirst));
        Assert.False(directFirst.BeamSynchronized);
        Assert.Equal(directFirst, overlayFirst);
        Assert.True(directFifo.CompleteInFlight(213));
        Assert.True(overlayFifo.CompleteInFlight(213));
        Assert.True(directFifo.TryDequeueReady(213, (_, _) => true, out var directSecond));
        Assert.True(overlayFifo.TryDequeueReady(213, (_, _) => true, out var overlaySecond));
        Assert.True(directSecond.BeamSynchronized);
        Assert.Equal(directSecond, overlaySecond);
    }

