    [Fact]
    public void NativeOverlayQueuedBlitterPreflightsReadOnlyLinkedNodeBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint node = 0x200;
        const uint nativeTarget = 0x00FE_1303;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[] { GraphicsLvo.QBlit, GraphicsLvo.QBSBlit })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeNext, 0x0012_3456);
        var originalNode = Enumerable.Range(0, GraphicsLayouts.BltNodeSize)
            .Select(offset => bus.ReadByte(node + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(node, originalNode);

        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            static (_, _, _) => { });
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            timedBlitter: scheduler);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, cycles) in new[]
        {
            (GraphicsLvo.QBlit, 181L),
            (GraphicsLvo.QBSBlit, 187L)
        })
        {
            var state = new M68kCpuState
            {
                A = { [1] = node },
                D = { [0] = 0x1357_9BDFu },
                Cycles = cycles,
                ProgramCounter = 0x0012_3A21
            };

            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(cycles, state.Cycles);
        }

        for (var offset = 0; offset < originalNode.Length; offset++)
            Assert.Equal(originalNode[offset], bus.ReadByte(node + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveLayerBitmapSyncParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint layer = 0x120;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        directBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        overlayBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        var directSync = 0;
        var directCopy = 0;
        var overlaySync = 0;
        var overlayCopy = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            syncSBitMap: address =>
            {
                Assert.Equal(layer, address);
                directSync++;
                return true;
            },
            copySBitMap: address =>
            {
                Assert.Equal(layer, address);
                directCopy++;
                return true;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            syncSBitMap: address =>
            {
                Assert.Equal(layer, address);
                overlaySync++;
                return true;
            },
            copySBitMap: address =>
            {
                Assert.Equal(layer, address);
                overlayCopy++;
                return true;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, cycles) in new[]
        {
            (GraphicsLvo.SyncSBitMap, 181L),
            (GraphicsLvo.CopySBitMap, 187L)
        })
        {
            var directState = new M68kCpuState
            {
                A = { [0] = layer },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = cycles
            };
            var overlayState = new M68kCpuState
            {
                A = { [0] = layer },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = cycles
            };

            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(cycles, directState.Cycles);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        Assert.Equal(1, directSync);
        Assert.Equal(1, directCopy);
        Assert.Equal(1, overlaySync);
        Assert.Equal(1, overlayCopy);
    }

