        const uint head = 0x300;
        const uint tail = 0x380;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(gelsInfo, new byte[GraphicsLayouts.GelsInfoSize]);
            bus.MapWritableMemory(head, new byte[GraphicsLayouts.VSpriteSize]);
            bus.MapWritableMemory(tail, new byte[GraphicsLayouts.VSpriteSize]);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortGelsInfo, gelsInfo);
        }
        var directCalls = new List<string>();
        var overlayCalls = new List<string>();
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            drawGList: (rp, vp) => directCalls.Add($"draw:{rp:X}:{vp:X}"),
            doCollision: rp => directCalls.Add($"collision:{rp:X}"),
            remIBob: (_, _, _) => { });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            drawGList: (rp, vp) => overlayCalls.Add($"draw:{rp:X}:{vp:X}"),
            doCollision: rp => overlayCalls.Add($"collision:{rp:X}"),
            remIBob: (_, _, _) => { });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directInit = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 205
        };
        var overlayInit = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 205
        };
        direct.Invoke(directInit, (int)GraphicsLvo.InitGels);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitGels)),
            overlayInit));
        Assert.Equal(0u, directInit.D[0]);
        Assert.Equal(directInit.D[0], overlayInit.D[0]);
        Assert.Equal(directInit.Cycles, overlayInit.Cycles);

        var directCollision = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        var overlayCollision = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        direct.Invoke(directCollision, (int)GraphicsLvo.DoCollision);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DoCollision)),
            overlayCollision));
        Assert.Equal(0u, directCollision.D[0]);
        Assert.Equal(directCollision.D[0], overlayCollision.D[0]);
        Assert.Equal(directCollision.Cycles, overlayCollision.Cycles);

        var directDraw = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 217
        };
        var overlayDraw = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 217
        };
        direct.Invoke(directDraw, (int)GraphicsLvo.DrawGList);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DrawGList)),
            overlayDraw));
        Assert.Equal(0u, directDraw.D[0]);
        Assert.Equal(directDraw.D[0], overlayDraw.D[0]);
        Assert.Equal(directDraw.Cycles, overlayDraw.Cycles);

        Assert.Equal(new[] { $"collision:{rastPort:X}", $"draw:{rastPort:X}:{viewPort:X}" }, directCalls);
        Assert.Equal(directCalls, overlayCalls);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveGuestGelsMutationParityAndTailChain()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint guestBase = 0x00FA_0000;
        const uint head = guestBase + 0x000;
        const uint tail = guestBase + 0x080;
        const uint gelsInfo = guestBase + 0x100;
        const uint collisionTable = guestBase + 0x180;
        const uint rastPort = guestBase + 0x200;
        const uint first = guestBase + 0x300;
        const uint second = guestBase + 0x380;
        const uint imageData = guestBase + 0x500;
        const uint borderLine = guestBase + 0x580;
        const uint collisionMask = guestBase + 0x600;
        const uint nativeTarget = 0x00FE_2001;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitGels)),
            nativeTarget);

        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(guestBase, new byte[0x1000]);
            bus.WriteLong(
                gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
                collisionTable);
            bus.WriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
                gelsInfo);
            bus.WriteWord(first + (uint)GraphicsLayouts.VSpriteY, 10);
            bus.WriteWord(first + (uint)GraphicsLayouts.VSpriteX, 20);
            bus.WriteWord(second + (uint)GraphicsLayouts.VSpriteY, 5);
            bus.WriteWord(second + (uint)GraphicsLayouts.VSpriteX, 30);
            bus.WriteWord(
                first + (uint)GraphicsLayouts.VSpriteFlags,
                GraphicsLayouts.VSpriteFlag);
            bus.WriteWord(first + (uint)GraphicsLayouts.VSpriteHeight, 1);
            bus.WriteWord(first + (uint)GraphicsLayouts.VSpriteWidth, 1);
            bus.WriteWord(first + (uint)GraphicsLayouts.VSpriteDepth, 1);
            bus.WriteLong(first + (uint)GraphicsLayouts.VSpriteImageData, imageData);
            bus.WriteLong(first + (uint)GraphicsLayouts.VSpriteBorderLine, borderLine);
            bus.WriteLong(first + (uint)GraphicsLayouts.VSpriteCollMask, collisionMask);
            bus.WriteWord(imageData, 0x8000);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeAndCompare(
            GraphicsLvo vector,
            M68kCpuState directState,
            M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            Assert.True(overlayBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            Assert.Equal(
                ReadBusBytes(directBus, guestBase, 0x700),
                ReadBusBytes(overlayBus, guestBase, 0x700));
        }

        InvokeAndCompare(
            GraphicsLvo.InitGels,
            new M68kCpuState
            {
                A = { [0] = head, [1] = tail, [2] = gelsInfo },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 401
            },
            new M68kCpuState
            {
                A = { [0] = head, [1] = tail, [2] = gelsInfo },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 401
            });

        InvokeAndCompare(
            GraphicsLvo.SetCollision,
            new M68kCpuState
            {
                A = { [0] = 0x1234_5678u, [1] = gelsInfo },
                D = { [0] = 2u },
                Cycles = 403
            },
            new M68kCpuState
            {
                A = { [0] = 0x1234_5678u, [1] = gelsInfo },
                D = { [0] = 2u },
                Cycles = 403
            });

        InvokeAndCompare(
            GraphicsLvo.AddVSprite,
            new M68kCpuState
            {
                A = { [0] = first, [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 405
            },
            new M68kCpuState
            {
                A = { [0] = first, [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 405
            });

        InvokeAndCompare(
            GraphicsLvo.AddVSprite,
            new M68kCpuState
            {
                A = { [0] = second, [1] = rastPort },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 407
            },
            new M68kCpuState
            {
                A = { [0] = second, [1] = rastPort },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 407
            });

        InvokeAndCompare(
            GraphicsLvo.SortGList,
            new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0x2468_ACEEu },
                Cycles = 409
            },
            new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0x2468_ACEEu },
                Cycles = 409
            });

        InvokeAndCompare(
            GraphicsLvo.RemVSprite,
            new M68kCpuState
            {
                A = { [0] = first },
                D = { [0] = 0x0BAD_F00Du },
                Cycles = 411
            },
            new M68kCpuState
            {
                A = { [0] = first },
                D = { [0] = 0x0BAD_F00Du },
                Cycles = 411
            });

        InvokeAndCompare(
            GraphicsLvo.InitMasks,
            new M68kCpuState
            {
                A = { [0] = first },
                D = { [0] = 0xFFFF_FFFFu },
                Cycles = 413
            },
            new M68kCpuState
            {
                A = { [0] = first },
                D = { [0] = 0xFFFF_FFFFu },
                Cycles = 413
            });

        var malformed = new M68kCpuState
        {
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 415,
            ProgramCounter = 0x0012_3A11
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitGels)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformed.D[0]);
        Assert.Equal(415, malformed.Cycles);
    }

