            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 640);
            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 128);
            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObXVel, 64);
            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObYVel, 0);
            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObXAccel, 0);
            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObYAccel, 0);
            bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObClock, 0);
            bus.WriteLong(animKey, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeAndCompare(
            GraphicsLvo vector,
            M68kCpuState directState,
            M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            Assert.True(overlayBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            Assert.Equal(
                ReadBusBytes(directBus, guestBase, 0xB00),
                ReadBusBytes(overlayBus, guestBase, 0xB00));
        }

        InvokeAndCompare(
            GraphicsLvo.InitGels,
            new M68kCpuState
            {
                A = { [0] = head, [1] = tail, [2] = gelsInfo },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 501
            },
            new M68kCpuState
            {
                A = { [0] = head, [1] = tail, [2] = gelsInfo },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 501
            });

        InvokeAndCompare(
            GraphicsLvo.AddAnimOb,
            new M68kCpuState
            {
                A = { [0] = animOb, [1] = animKey, [2] = rastPort },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 503
            },
            new M68kCpuState
            {
                A = { [0] = animOb, [1] = animKey, [2] = rastPort },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 503
            });

        InvokeAndCompare(
            GraphicsLvo.Animate,
            new M68kCpuState
            {
                A = { [0] = animKey, [1] = rastPort },
                D = { [0] = 0x2468_ACEEu },
                Cycles = 505
            },
            new M68kCpuState
            {
                A = { [0] = animKey, [1] = rastPort },
                D = { [0] = 0x2468_ACEEu },
                Cycles = 505
            });

        InvokeAndCompare(
            GraphicsLvo.InitGMasks,
            new M68kCpuState
            {
                A = { [0] = animOb },
                D = { [0] = 0xFFFF_FFFFu },
                Cycles = 507
            },
            new M68kCpuState
            {
                A = { [0] = animOb },
                D = { [0] = 0xFFFF_FFFFu },
                Cycles = 507
            });

        InvokeAndCompare(
            GraphicsLvo.RemIBob,
            new M68kCpuState
            {
                A = { [0] = bob, [1] = rastPort, [2] = 0 },
                D = { [0] = 0x0BAD_F00Du },
                Cycles = 509
            },
            new M68kCpuState
            {
                A = { [0] = bob, [1] = rastPort, [2] = 0 },
                D = { [0] = 0x0BAD_F00Du },
                Cycles = 509
            });

        var malformed = new M68kCpuState
        {
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 511,
            ProgramCounter = 0x0012_3A21
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AddAnimOb)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformed.D[0]);
        Assert.Equal(511, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveExtendedNodeLifecycleParityAndTailChain()
    {
        const uint imageBase = 0x00F9_F000;
        const uint graphicsBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint ownerPointer = 0x00FC_0000;
        const uint nativeTarget = 0x00FE_2201;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GfxNew)),
            nativeTarget);

        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
            bus.MapWritableMemory(allocationBase, new byte[0x4000]);
            bus.MapWritableMemory(ownerPointer, new byte[0x40]);
        }

        var directNextAllocation = allocationBase;
        var overlayNextAllocation = allocationBase;
        var directFrees = 0;
        var overlayFrees = 0;
        static uint Allocate(ref uint next, int bytes)
        {
            var address = next;
            next += unchecked((uint)((bytes + 3) & ~3));
            return address;
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: (bytes, _) => Allocate(ref directNextAllocation, bytes),
            freeMemory: (_, _) => directFrees++,
            graphicsLibraryBase: graphicsBase);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: (bytes, _) => Allocate(ref overlayNextAllocation, bytes),
            freeMemory: (_, _) => overlayFrees++,
            graphicsLibraryBase: graphicsBase);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeAndCompare(
            GraphicsLvo vector,
            M68kCpuState directState,
            M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            Assert.True(overlayBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            Assert.Equal(
                ReadBusBytes(directBus, allocationBase, 0x100),
                ReadBusBytes(overlayBus, allocationBase, 0x100));
        }

        var directCreate = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewPortExtraType },
            Cycles = 601
        };
        var overlayCreate = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewPortExtraType },
            Cycles = 601
        };
        InvokeAndCompare(GraphicsLvo.GfxNew, directCreate, overlayCreate);
        Assert.NotEqual(0u, directCreate.D[0]);
        Assert.Equal(directCreate.D[0], overlayCreate.D[0]);
        var node = directCreate.D[0];

        InvokeAndCompare(
            GraphicsLvo.GfxAssociate,
            new M68kCpuState
            {
                A = { [0] = ownerPointer, [1] = node },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 603
            },
            new M68kCpuState
            {
                A = { [0] = ownerPointer, [1] = node },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 603
            });
        Assert.Equal(
            ownerPointer,
            directBus.ReadLong(node + (uint)GraphicsLayouts.ViewPortExtraViewPort));
        Assert.Equal(
            ownerPointer,
            overlayBus.ReadLong(node + (uint)GraphicsLayouts.ViewPortExtraViewPort));

        InvokeAndCompare(
            GraphicsLvo.GfxLookUp,
            new M68kCpuState
            {
                A = { [0] = ownerPointer },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 605
            },
            new M68kCpuState
            {
                A = { [0] = ownerPointer },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 605
            });

        InvokeAndCompare(
            GraphicsLvo.GfxFree,
            new M68kCpuState
            {
                A = { [0] = node },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 607
            },
            new M68kCpuState
            {
                A = { [0] = node },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 607
            });
        Assert.Equal(directFrees, overlayFrees);
        Assert.Equal(1, directFrees);

        var unsupported = new M68kCpuState
        {
            D = { [0] = 5u },
            Cycles = 609,
            ProgramCounter = 0x0012_3A31
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GfxNew)),
            unsupported));
        Assert.Equal(nativeTarget, unsupported.ProgramCounter);
        Assert.Equal(5u, unsupported.D[0]);
        Assert.Equal(609, unsupported.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveColorMapRgbLifecycleParityAndTailChain()
    {
        const uint imageBase = 0x00F9_F000;
        const uint graphicsBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint rgbTable = 0x00FC_0000;
        const uint nativeTarget = 0x00FE_2301;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetColorMap)),
            nativeTarget);

        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
            bus.MapWritableMemory(allocationBase, new byte[0x8000]);
            bus.MapWritableMemory(rgbTable, new byte[0x100]);
        }

        var directNextAllocation = allocationBase;
        var overlayNextAllocation = allocationBase;
        var directFrees = 0;
        var overlayFrees = 0;
        static uint Allocate(ref uint next, int bytes)
        {
            var address = next;
            next += unchecked((uint)((bytes + 3) & ~3));
            return address;
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: (bytes, _) => Allocate(ref directNextAllocation, bytes),
            freeMemory: (_, _) => directFrees++);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: (bytes, _) => Allocate(ref overlayNextAllocation, bytes),
            freeMemory: (_, _) => overlayFrees++);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeAndCompare(
            GraphicsLvo vector,
            M68kCpuState directState,
            M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            Assert.True(overlayBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            Assert.Equal(
                ReadBusBytes(directBus, allocationBase, 0x8000),
                ReadBusBytes(overlayBus, allocationBase, 0x8000));
            Assert.Equal(
                ReadBusBytes(directBus, rgbTable, 0x100),
                ReadBusBytes(overlayBus, rgbTable, 0x100));
        }

        var directEmpty = new M68kCpuState
        {
            D = { [0] = 0u },
            Cycles = 619
        };
        var overlayEmpty = new M68kCpuState
        {
            D = { [0] = 0u },
            Cycles = 619
        };
        InvokeAndCompare(GraphicsLvo.GetColorMap, directEmpty, overlayEmpty);
        Assert.Equal(0u, directEmpty.D[0]);
        Assert.Equal(0u, overlayEmpty.D[0]);

        var directCreate = new M68kCpuState
        {
            D = { [0] = 4u },
            Cycles = 621
        };
        var overlayCreate = new M68kCpuState
        {
            D = { [0] = 4u },
            Cycles = 621
        };
        InvokeAndCompare(GraphicsLvo.GetColorMap, directCreate, overlayCreate);
        Assert.NotEqual(0u, directCreate.D[0]);
        Assert.Equal(directCreate.D[0], overlayCreate.D[0]);
        var colorMap = directCreate.D[0];

        InvokeAndCompare(
            GraphicsLvo.SetRGB4CM,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 1u, [1] = 0xAu, [2] = 0x5u, [3] = 0xFu },
                Cycles = 623
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 1u, [1] = 0xAu, [2] = 0x5u, [3] = 0xFu },
                Cycles = 623
            });

        InvokeAndCompare(
            GraphicsLvo.GetRGB4,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 1u },
                Cycles = 625
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 1u },
                Cycles = 625
            });
        Assert.Equal(
            (ushort)0xA5F,
            (ushort)(directBus.ReadWord(
                directBus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable) + 2u) &
                0x0FFF));

        InvokeAndCompare(
            GraphicsLvo.SetRGB32CM,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D =
                {
                    [0] = 2u,
                    [1] = 0xAB00_0000u,
                    [2] = 0x3412_0000u,
                    [3] = 0xFF80_0000u
                },
                Cycles = 627
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D =
                {
                    [0] = 2u,
                    [1] = 0xAB00_0000u,
                    [2] = 0x3412_0000u,
                    [3] = 0xFF80_0000u
                },
                Cycles = 627
            });

        InvokeAndCompare(
            GraphicsLvo.GetRGB32,
            new M68kCpuState
            {
                A = { [0] = colorMap, [1] = rgbTable },
                D = { [0] = 1u, [1] = 2u },
                Cycles = 629
            },
            new M68kCpuState
            {
                A = { [0] = colorMap, [1] = rgbTable },
                D = { [0] = 1u, [1] = 2u },
                Cycles = 629
            });

        InvokeAndCompare(
            GraphicsLvo.FreeColorMap,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 631
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 631
            });
        Assert.Equal(directFrees, overlayFrees);
        Assert.Equal(3, directFrees);

        var malformed = new M68kCpuState
        {
            D = { [0] = 0u },
            Cycles = 633,
            ProgramCounter = 0x0012_3A41
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetColorMap)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0u, malformed.D[0]);
        Assert.Equal(633, malformed.Cycles);
    }

    [Fact]
