        }

        var directCreate = new M68kCpuState
        {
            D = { [0] = 4u },
            Cycles = 641
        };
        var overlayCreate = new M68kCpuState
        {
            D = { [0] = 4u },
            Cycles = 641
        };
        InvokeAndCompare(GraphicsLvo.GetColorMap, directCreate, overlayCreate);
        Assert.NotEqual(0u, directCreate.D[0]);
        Assert.Equal(directCreate.D[0], overlayCreate.D[0]);
        var colorMap = directCreate.D[0];

        InvokeAndCompare(
            GraphicsLvo.AttachPalExtra,
