            {
                A = { [0] = colorMap, [1] = viewPort },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 643
            },
            new M68kCpuState
            {
                A = { [0] = colorMap, [1] = viewPort },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 643
            });

        var directObtain = new M68kCpuState
        {
            A = { [0] = colorMap },
            D =
            {
                [0] = uint.MaxValue,
                [1] = 0xA000_0000u,
                [2] = 0x2000_0000u,
                [3] = 0x3000_0000u
            },
            Cycles = 645
        };
        var overlayObtain = new M68kCpuState
        {
            A = { [0] = colorMap },
            D =
            {
                [0] = uint.MaxValue,
                [1] = 0xA000_0000u,
                [2] = 0x2000_0000u,
                [3] = 0x3000_0000u
            },
            Cycles = 645
        };
        InvokeAndCompare(GraphicsLvo.ObtainPen, directObtain, overlayObtain);
        Assert.Equal(directObtain.D[0], overlayObtain.D[0]);
        var pen = directObtain.D[0];

        InvokeAndCompare(
            GraphicsLvo.ObtainBestPenA,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D =
                {
                    [1] = 0xA000_0000u,
                    [2] = 0x2000_0000u,
                    [3] = 0x3000_0000u
                },
                Cycles = 647
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D =
                {
                    [1] = 0xA000_0000u,
                    [2] = 0x2000_0000u,
                    [3] = 0x3000_0000u
                },
                Cycles = 647
            });

        InvokeAndCompare(
            GraphicsLvo.FindColor,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D =
                {
                    [1] = 0xA000_0000u,
                    [2] = 0x2000_0000u,
                    [3] = 0x3000_0000u,
                    [4] = uint.MaxValue
                },
                Cycles = 649
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D =
                {
                    [1] = 0xA000_0000u,
                    [2] = 0x2000_0000u,
                    [3] = 0x3000_0000u,
                    [4] = uint.MaxValue
                },
                Cycles = 649
            });

        InvokeAndCompare(
            GraphicsLvo.ReleasePen,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = pen },
                Cycles = 651
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = pen },
                Cycles = 651
            });

        InvokeAndCompare(
            GraphicsLvo.FreeColorMap,
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 653
            },
            new M68kCpuState
            {
                A = { [0] = colorMap },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 653
            });
        Assert.Equal(directFrees, overlayFrees);
        Assert.True(directFrees > 0);

        var foreign = new M68kCpuState
        {
            A = { [0] = foreignMap },
            D = { [0] = uint.MaxValue, [1] = 1u, [2] = 2u, [3] = 3u },
            Cycles = 655,
            ProgramCounter = 0x0012_3A51
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ObtainPen)),
            foreign));
        Assert.Equal(nativeTarget, foreign.ProgramCounter);
        Assert.Equal(uint.MaxValue, foreign.D[0]);
        Assert.Equal(655, foreign.Cycles);
    }

