            GraphicsLvo vector,
            M68kCpuState directState,
            M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            Assert.True(overlayBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            Assert.Equal(
                ReadBusBytes(directBus, allocationBase, 0x4000),
                ReadBusBytes(overlayBus, allocationBase, 0x4000));
        }

        var directCreate = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 661
        };
        var overlayCreate = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 661
        };
        InvokeAndCompare(GraphicsLvo.NewRegion, directCreate, overlayCreate);
        Assert.NotEqual(0u, directCreate.D[0]);
        Assert.Equal(directCreate.D[0], overlayCreate.D[0]);
        var region = directCreate.D[0];

        InvokeAndCompare(
            GraphicsLvo.OrRectRegion,
            new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 663
            },
            new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 663
            });

        InvokeAndCompare(
            GraphicsLvo.AndRectRegion,
            new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle },
                D = { [0] = 0x2468_ACEEu },
                Cycles = 665
            },
            new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle },
                D = { [0] = 0x2468_ACEEu },
                Cycles = 665
            });

        InvokeAndCompare(
            GraphicsLvo.ClearRegion,
            new M68kCpuState
            {
                A = { [0] = region },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 667
            },
            new M68kCpuState
            {
                A = { [0] = region },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 667
            });

        InvokeAndCompare(
            GraphicsLvo.DisposeRegion,
            new M68kCpuState
            {
                A = { [0] = region },
                D = { [0] = 0x0BAD_F00Du },
                Cycles = 669
            },
            new M68kCpuState
            {
                A = { [0] = region },
                D = { [0] = 0x0BAD_F00Du },
                Cycles = 669
            });
        Assert.Equal(directFrees, overlayFrees);
        Assert.True(directFrees > 0);

        var foreign = new M68kCpuState
        {
            A = { [0] = foreignRegion },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 671,
            ProgramCounter = 0x0012_3A61
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DisposeRegion)),
            foreign));
        Assert.Equal(nativeTarget, foreign.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, foreign.D[0]);
        Assert.Equal(671, foreign.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveFixedTextStyleAndJAM2Parity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint font = 0x600;
        const uint charData = 0x900;
        const uint text = 0xA00;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(charData, new byte[0x20]);
            bus.MapWritableMemory(text, new byte[0x10]);
            bus.MapWritableMemory(plane, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

            // A fixed-cell TextFont may omit CharLoc/CharSpace/CharKern.
            // The four-byte cells below exercise the guest decoder's
            // synthesized bit offset while keeping the strike inside the
            // declared one-byte row modulo.
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 4);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBoldSmear, 1);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);
            bus.WriteByte(charData, 0xC0, 0);
            bus.WriteByte(charData + 1, 0x60, 0);
            bus.WriteByte(charData + 2, 0x30, 0);
            bus.WriteByte(charData + 3, 0xF0, 0);
            bus.WriteByte(text, (byte)'A', 0);
            bus.WriteByte(text + 1, (byte)'A', 0);

            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0); // JAM2
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 3, 0); // bold + underline
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 1);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 5);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 3);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 2, [5] = 0xCAFE_BABEu },
            Cycles = 97
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 2, [5] = 0xCAFE_BABEu },
            Cycles = 97
        };

        direct.Invoke(directState, (int)GraphicsLvo.Text);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Text));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(0xCAFE_BABEu, directState.D[5]);
        Assert.Equal(directState.D[5], overlayState.D[5]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.NotEqual((ushort)1, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX),
            overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags),
            overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount),
            overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        var anyPlanePixel = false;
        for (var offset = 0; offset < 0x100; offset++)
        {
            var directByte = directBus.ReadByte(plane + (uint)offset);
            var overlayByte = overlayBus.ReadByte(plane + (uint)offset);
            Assert.Equal(directByte, overlayByte);
            anyPlanePixel |= directByte != 0;
        }

        // JAM2 must paint the zero-source cells and the run-wide underline;
        // a no-op implementation would leave the whole destination plane at
        // zero despite returning success.
        Assert.True(anyPlanePixel);
        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 6));
    }

    [Fact]
    public void NativeOverlayGelsVectorsTailChainWithoutAProvider()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FE_1041;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[] { GraphicsLvo.DoCollision, GraphicsLvo.DrawGList })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var collision = new M68kCpuState
        {
            A = { [1] = 0x120 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 223,
            ProgramCounter = 0x0012_3A41
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DoCollision)),
            collision));
        Assert.Equal(nativeTarget, collision.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, collision.D[0]);
        Assert.Equal(223, collision.Cycles);

        var draw = new M68kCpuState
        {
            A = { [0] = 0x180, [1] = 0x120 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 229,
            ProgramCounter = 0x0012_3A47
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DrawGList)),
            draw));
        Assert.Equal(nativeTarget, draw.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, draw.D[0]);
        Assert.Equal(229, draw.Cycles);
    }

    [Fact]
    public void NativeOverlayInitGelsPreservesReadOnlyPublicationEnvelopeForProviderFallback()
    {
        const uint imageBase = 0x00F4_F000;
        const uint graphicsBase = 0x00F5_0000;
        const uint guestBase = 0x00F6_0000;
        const uint head = guestBase + 0x000;
        const uint tail = guestBase + 0x100;
        const uint gelsInfo = guestBase + 0x200;
        const uint collisionHandler = guestBase + 0x300;
        const uint nativeTarget = 0x00F7_2A01;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitGels)),
            nativeTarget);

        var headBytes = new byte[GraphicsLayouts.VSpriteSize];
        var tailBytes = new byte[GraphicsLayouts.VSpriteSize];
        var gelsInfoBytes = new byte[GraphicsLayouts.GelsInfoSize];
        var collisionBytes = new byte[sizeof(uint)];
        WriteLong(
            gelsInfoBytes,
            GraphicsLayouts.GelsInfoCollisionHandler,
            collisionHandler);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapReadOnlyMemory(head, headBytes);
        bus.MapReadOnlyMemory(tail, tailBytes);
        bus.MapReadOnlyMemory(gelsInfo, gelsInfoBytes);
        bus.MapReadOnlyMemory(collisionHandler, collisionBytes);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 1231,
            ProgramCounter = 0x0012_3B01
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitGels)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(1231, state.Cycles);
        Assert.Equal(headBytes, ReadBusBytes(bus, head, headBytes.Length));
        Assert.Equal(tailBytes, ReadBusBytes(bus, tail, tailBytes.Length));
        Assert.Equal(
            gelsInfoBytes,
            ReadBusBytes(bus, gelsInfo, gelsInfoBytes.Length));
        Assert.Equal(
            collisionBytes,
            ReadBusBytes(bus, collisionHandler, collisionBytes.Length));

        static void WriteLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }
    }

    [Fact]
    public void NativeOverlaySetCollisionPreservesReadOnlyCollisionTableForProviderFallback()
    {
        const uint imageBase = 0x00F2_F000;
        const uint graphicsBase = 0x00F3_0000;
        const uint guestBase = 0x00F4_0000;
        const uint gelsInfo = guestBase + 0x000;
        const uint collisionHandler = guestBase + 0x100;
        const uint collisionEntry = collisionHandler + 8;
        const uint nativeTarget = 0x00F5_2A07;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetCollision)),
            nativeTarget);

        var gelsInfoBytes = new byte[GraphicsLayouts.GelsInfoSize];
        var collisionBytes = new byte[16];
        WriteLong(
            gelsInfoBytes,
            GraphicsLayouts.GelsInfoCollisionHandler,
            collisionHandler);
        WriteLong(collisionBytes, 8, 0x1122_3344u);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapReadOnlyMemory(gelsInfo, gelsInfoBytes);
        bus.MapReadOnlyMemory(collisionHandler, collisionBytes);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = 0x5566_7788u, [1] = gelsInfo },
            D = { [0] = 2u },
            Cycles = 1241,
            ProgramCounter = 0x0012_3B11
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetCollision)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(2u, state.D[0]);
        Assert.Equal(1241, state.Cycles);
        Assert.Equal(
            gelsInfoBytes,
            ReadBusBytes(bus, gelsInfo, gelsInfoBytes.Length));
        Assert.Equal(
            collisionBytes,
            ReadBusBytes(bus, collisionHandler, collisionBytes.Length));
        Assert.Equal(0x1122_3344u, bus.ReadLong(collisionEntry));

        static void WriteLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }
    }

    [Fact]
    public void NativeOverlayInitMasksPreservesReadOnlyMaskDestinationsForProviderFallback()
    {
        const uint imageBase = 0x00F0_F000;
        const uint graphicsBase = 0x00F1_0000;
        const uint guestBase = 0x00F2_0000;
        const uint sprite = guestBase + 0x000;
        const uint imageData = guestBase + 0x100;
        const uint borderLine = guestBase + 0x200;
        const uint collisionMask = guestBase + 0x300;
        const uint nativeTarget = 0x00F3_2A0D;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitMasks)),
            nativeTarget);

        var spriteBytes = new byte[GraphicsLayouts.VSpriteSize];
        var imageBytes = new byte[2];
        var borderBytes = new byte[] { 0xA5, 0x5A };
        var collisionBytes = new byte[] { 0x3C, 0xC3 };
        WriteWord(
            spriteBytes,
            GraphicsLayouts.VSpriteFlags,
            GraphicsLayouts.VSpriteFlag);
        WriteWord(spriteBytes, GraphicsLayouts.VSpriteHeight, 1);
        WriteWord(spriteBytes, GraphicsLayouts.VSpriteWidth, 1);
        WriteWord(spriteBytes, GraphicsLayouts.VSpriteDepth, 1);
        WriteLong(spriteBytes, GraphicsLayouts.VSpriteImageData, imageData);
        WriteLong(spriteBytes, GraphicsLayouts.VSpriteBorderLine, borderLine);
        WriteLong(spriteBytes, GraphicsLayouts.VSpriteCollMask, collisionMask);
        imageBytes[0] = 0x80;

        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapReadOnlyMemory(sprite, spriteBytes);
        bus.MapReadOnlyMemory(imageData, imageBytes);
        bus.MapReadOnlyMemory(borderLine, borderBytes);
        bus.MapReadOnlyMemory(collisionMask, collisionBytes);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = sprite },
            D = { [0] = 0x0BAD_F00Du },
            Cycles = 1251,
            ProgramCounter = 0x0012_3B21
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitMasks)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x0BAD_F00Du, state.D[0]);
        Assert.Equal(1251, state.Cycles);
        Assert.Equal(
            spriteBytes,
            ReadBusBytes(bus, sprite, spriteBytes.Length));
        Assert.Equal(
            borderBytes,
            ReadBusBytes(bus, borderLine, borderBytes.Length));
        Assert.Equal(
            collisionBytes,
            ReadBusBytes(bus, collisionMask, collisionBytes.Length));

        static void WriteWord(byte[] bytes, int offset, ushort value)
        {
            bytes[offset] = unchecked((byte)(value >> 8));
            bytes[offset + 1] = unchecked((byte)value);
        }

        static void WriteLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }
    }

    [Fact]
    public void NativeOverlayGelsListMutationsPreserveReadOnlyLinksForProviderFallback()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint guestBase = 0x00FA_0000;
        const uint head = guestBase + 0x000;
        const uint first = guestBase + 0x100;
        const uint second = guestBase + 0x200;
        const uint tail = guestBase + 0x300;
        const uint addSprite = guestBase + 0x400;
        const uint gelsInfo = guestBase + 0x500;
        const uint rastPort = guestBase + 0x600;
        const uint nativeAddTarget = 0x00FB_2A13;
        const uint nativeRemTarget = 0x00FB_2A19;
        const uint nativeSortTarget = 0x00FB_2A1F;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AddVSprite)),
            nativeAddTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.RemVSprite)),
            nativeRemTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SortGList)),
            nativeSortTarget);

        var headBytes = new byte[GraphicsLayouts.VSpriteSize];
        var firstBytes = new byte[GraphicsLayouts.VSpriteSize];
        var secondBytes = new byte[GraphicsLayouts.VSpriteSize];
        var tailBytes = new byte[GraphicsLayouts.VSpriteSize];
        var addSpriteBytes = new byte[GraphicsLayouts.VSpriteSize];
        var gelsInfoBytes = new byte[GraphicsLayouts.GelsInfoSize];
        var rastPortBytes = new byte[GraphicsLayouts.RastPortMinimumSize];

        WriteLong(
            headBytes,
            GraphicsLayouts.VSpriteNext,
            first);
        WriteLong(
            firstBytes,
            GraphicsLayouts.VSpritePrev,
            head);
        WriteLong(
            firstBytes,
            GraphicsLayouts.VSpriteNext,
            second);
        WriteWord(firstBytes, GraphicsLayouts.VSpriteY, 20);
        WriteWord(firstBytes, GraphicsLayouts.VSpriteX, 20);
        WriteLong(
            secondBytes,
            GraphicsLayouts.VSpritePrev,
            first);
        WriteLong(
            secondBytes,
            GraphicsLayouts.VSpriteNext,
            tail);
        WriteWord(secondBytes, GraphicsLayouts.VSpriteY, 10);
        WriteWord(secondBytes, GraphicsLayouts.VSpriteX, 10);
        WriteLong(
            tailBytes,
            GraphicsLayouts.VSpritePrev,
            second);
        WriteLong(
            gelsInfoBytes,
            GraphicsLayouts.GelsInfoHead,
            head);
        WriteLong(
            gelsInfoBytes,
            GraphicsLayouts.GelsInfoTail,
            tail);
        WriteLong(
            rastPortBytes,
            GraphicsLayouts.RastPortGelsInfo,
            gelsInfo);
        WriteWord(
            addSpriteBytes,
            GraphicsLayouts.VSpriteFlags,
            (ushort)(GraphicsLayouts.VSpriteFlag | GraphicsLayouts.VSpriteSystemFlags));
        WriteWord(addSpriteBytes, GraphicsLayouts.VSpriteY, 15);
        WriteWord(addSpriteBytes, GraphicsLayouts.VSpriteX, 15);

        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapReadOnlyMemory(head, headBytes);
        bus.MapReadOnlyMemory(first, firstBytes);
        bus.MapReadOnlyMemory(second, secondBytes);
        bus.MapReadOnlyMemory(tail, tailBytes);
        bus.MapReadOnlyMemory(addSprite, addSpriteBytes);
        bus.MapReadOnlyMemory(gelsInfo, gelsInfoBytes);
        bus.MapReadOnlyMemory(rastPort, rastPortBytes);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var add = new M68kCpuState
        {
            A = { [0] = addSprite, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 1261,
            ProgramCounter = 0x0012_3C01
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AddVSprite)),
            add));
        Assert.Equal(nativeAddTarget, add.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, add.D[0]);
        Assert.Equal(1261, add.Cycles);

        var remove = new M68kCpuState
        {
            A = { [0] = first },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 1263,
            ProgramCounter = 0x0012_3C07
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.RemVSprite)),
            remove));
        Assert.Equal(nativeRemTarget, remove.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, remove.D[0]);
        Assert.Equal(1263, remove.Cycles);

        var sort = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 1265,
            ProgramCounter = 0x0012_3C0D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SortGList)),
            sort));
        Assert.Equal(nativeSortTarget, sort.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, sort.D[0]);
        Assert.Equal(1265, sort.Cycles);

        Assert.Equal(
            headBytes,
            ReadBusBytes(bus, head, headBytes.Length));
        Assert.Equal(
            firstBytes,
            ReadBusBytes(bus, first, firstBytes.Length));
        Assert.Equal(
            secondBytes,
