    [Fact]
    public void NativeOverlayDrawGListPreservesReadOnlyRestoreRasterForProviderFallback()
    {
        const uint imageBase = 0x00F6_F000;
        const uint graphicsBase = 0x00F7_0000;
        const uint guestBase = 0x00F8_0000;
        const uint bitMap = guestBase + 0x000;
        const uint plane = guestBase + 0x100;
        const uint rastPort = guestBase + 0x200;
        const uint gelsInfo = guestBase + 0x300;
        const uint head = guestBase + 0x400;
        const uint tail = guestBase + 0x480;
        const uint bob = guestBase + 0x500;
        const uint vSprite = guestBase + 0x580;
        const uint saveBuffer = guestBase + 0x680;
        const uint viewPort = guestBase + 0x780;
        const uint nativeTarget = 0x00FA_2A01;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DrawGList)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(guestBase, new byte[0x1000]);

        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteWord(plane, 0xA55A);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortGelsInfo, gelsInfo);
        bus.WriteLong(bob + (uint)GraphicsLayouts.BobVSprite, vSprite);
        bus.WriteLong(bob + (uint)GraphicsLayouts.BobSaveBuffer, saveBuffer);
        bus.WriteWord(
            vSprite + (uint)GraphicsLayouts.VSpriteFlags,
            GraphicsLayouts.VSpriteSaveBack);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteX, 0);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteY, 0);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteWidth, 1);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteHeight, 1);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteDepth, 1);

        var drawCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            drawGList: (_, _) => drawCalls++,
            doCollision: _ => { },
            remIBob: (_, _, _) => { });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var init = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 1201
        };
        services.Invoke(init, (int)GraphicsLvo.InitGels);
        Assert.Equal(0u, init.D[0]);

        var addBob = new M68kCpuState
        {
            A = { [0] = bob, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 1203
        };
        services.Invoke(addBob, (int)GraphicsLvo.AddBob);
        Assert.Equal(0u, addBob.D[0]);

        var firstDraw = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rastPort },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 1205
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DrawGList)),
            firstDraw));
        Assert.Equal(0u, firstDraw.D[0]);
        Assert.Equal(1, drawCalls);
        Assert.Equal((ushort)0xA55A, bus.ReadWord(saveBuffer));
        Assert.Equal(
            (ushort)(GraphicsLayouts.VSpriteSaveBack |
                     GraphicsLayouts.VSpriteBackSaved),
            bus.ReadWord(vSprite + (uint)GraphicsLayouts.VSpriteFlags));

        var readOnlyPlane = ReadBusBytes(bus, plane, sizeof(ushort));
        bus.MapReadOnlyMemory(plane, readOnlyPlane);
        var secondDraw = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rastPort },
            D = { [0] = 0xCAFEBABEu },
            Cycles = 1207,
            ProgramCounter = 0x0012_3B11
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DrawGList)),
            secondDraw));
        Assert.Equal(nativeTarget, secondDraw.ProgramCounter);
        Assert.Equal(0xCAFEBABEu, secondDraw.D[0]);
        Assert.Equal(1207, secondDraw.Cycles);
        Assert.Equal(1, drawCalls);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveLayerLockParityAndSchedulerResult()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint layer = 0x120;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        directBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        overlayBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        var directBackend = new RecordingLayerGatewayBackend
        {
            LockResult = M68kHostGatewayResult.BlockCurrentTask
        };
        var overlayBackend = new RecordingLayerGatewayBackend
        {
            LockResult = M68kHostGatewayResult.BlockCurrentTask
        };
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            layers: directBackend);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            layers: overlayBackend);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, cycles) in new[]
        {
            (GraphicsLvo.LockLayerRom, 227L),
            (GraphicsLvo.AttemptLockLayerRom, 229L),
            (GraphicsLvo.UnlockLayerRom, 233L)
        })
        {
            var directState = new M68kCpuState
            {
                A = { [5] = layer },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = cycles
            };
            var overlayState = new M68kCpuState
            {
                A = { [5] = layer },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = cycles
            };

            var directResult = direct.InvokeGateway(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            var overlayResult = overlayBus.InvokeHostGateway(
                address,
                overlayBus.ReadLong(address + 2),
                overlayState);

            Assert.True(overlayResult.Handled);
            Assert.Equal(directResult, overlayResult.Result);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(cycles, directState.Cycles);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        Assert.Equal(
            new[]
            {
                (GraphicsLvo.LockLayerRom, layer),
                (GraphicsLvo.AttemptLockLayerRom, layer),
                (GraphicsLvo.UnlockLayerRom, layer)
            },
            directBackend.CompanionCalls);
        Assert.Equal(directBackend.CompanionCalls, overlayBackend.CompanionCalls);
    }

