        var overlayResult = overlayBus.InvokeHostGateway(
            address,
            overlayBus.ReadLong(address + 2),
            overlayState);

        Assert.Equal(M68kHostGatewayResult.Completed, directResult);
        Assert.True(overlayResult.Handled);
        Assert.Equal(directResult, overlayResult.Result);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(new[] { (GraphicsLvo.Draw, layerRastPort) }, directBackend.RasterCalls);
        Assert.Equal(directBackend.RasterCalls, overlayBackend.RasterCalls);
    }

    [Fact]
    public void LayerRasterGatewayRejectsOddRastPortBeforeProviderClaim()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint oddRastPort = 0x121;
        const uint nativeTarget = 0x00FE_1063;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        var directImage = new byte[0x2000];
        var overlayImage = new byte[0x2000];
        WriteJmp(
            overlayImage,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Draw)),
            nativeTarget);
        directBus.MapReadOnlyMemory(imageBase, directImage);
        overlayBus.MapReadOnlyMemory(imageBase, overlayImage);
        directBus.MapWritableMemory(oddRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        overlayBus.MapWritableMemory(oddRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);

        var directMemory = new HostGuestMemory(directBus);
        var overlayMemory = new HostGuestMemory(overlayBus);
        directMemory.WriteLong(
            oddRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180);
        overlayMemory.WriteLong(
            oddRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180);

        var directBackend = new RecordingLayerGatewayBackend
        {
            RasterLvo = GraphicsLvo.Draw
        };
        var overlayBackend = new RecordingLayerGatewayBackend
        {
            RasterLvo = GraphicsLvo.Draw
        };
        using var direct = CreateHostGraphicsServices(directMemory, layerRaster: directBackend);
        using var overlay = CreateHostGraphicsServices(overlayMemory, layerRaster: overlayBackend);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 271
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 271,
            ProgramCounter = 0x0012_3A73
        };

        var directResult = direct.InvokeGateway(directState, (int)GraphicsLvo.Draw);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Draw));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(M68kHostGatewayResult.Completed, directResult);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(271, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
        Assert.Empty(directBackend.RasterCalls);
        Assert.Empty(overlayBackend.RasterCalls);
    }

    [Fact]
    public void ProviderFallbackRejectsOddRastPortBeforeLayerClassification()
    {
        var bus = new AmigaBus();
        const uint oddRastPort = 0x121;
        const uint sourceBitMap = 0x300;
        bus.MapWritableMemory(oddRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(
            oddRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180);

        var callbackCount = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            clipBlit: _ =>
            {
                callbackCount++;
                return 99u;
            });

        var state = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = oddRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 277
        };

        services.Invoke(state, (int)GraphicsLvo.ClipBlit);

        Assert.Equal(0, callbackCount);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(277, state.Cycles);
    }

