    [Fact]
    public void NativeOverlayUsesPlainLayerBackendWhenProviderIsConfigured()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint layer = 0x120;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[]
        {
            GraphicsLvo.LockLayerRom,
            GraphicsLvo.AttemptLockLayerRom,
            GraphicsLvo.UnlockLayerRom
        })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                0x00FE_1091);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        var backend = new RecordingLayerBackend();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            layers: backend);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, expected, cycles) in new[]
        {
            (GraphicsLvo.LockLayerRom, 0u, 257L),
            (GraphicsLvo.AttemptLockLayerRom, 1u, 263L),
            (GraphicsLvo.UnlockLayerRom, 0u, 269L)
        })
        {
            var state = new M68kCpuState
            {
                A = { [5] = layer },
                D = { [0] = 0x2468_ACEDu },
                Cycles = cycles,
                ProgramCounter = 0x0012_3A81
            };

            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                state));
            Assert.Equal(expected, state.D[0]);
            Assert.Equal(cycles, state.Cycles);
            Assert.Equal(0x0012_3A81u, state.ProgramCounter);
        }

        Assert.Equal(
            new[] { "lock:120", "try:120", "unlock:120" },
            backend.Calls);
    }

