    [Fact]
    public void NativeOverlayLayerVectorsTailChainOddPointersBeforeHostCallbacks()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FE_1071;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[]
                 {
                     GraphicsLvo.LockLayerRom,
                     GraphicsLvo.AttemptLockLayerRom,
                     GraphicsLvo.UnlockLayerRom,
                     GraphicsLvo.SyncSBitMap,
                     GraphicsLvo.CopySBitMap
                 })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        var calls = new List<string>();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            lockLayerRom: address => calls.Add($"lock:{address:X}"),
            attemptLockLayerRom: address =>
            {
                calls.Add($"try:{address:X}");
                return true;
            },
            unlockLayerRom: address => calls.Add($"unlock:{address:X}"),
            syncSBitMap: address =>
            {
                calls.Add($"sync:{address:X}");
                return true;
            },
            copySBitMap: address =>
            {
                calls.Add($"copy:{address:X}");
                return true;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, register, cycles) in new[]
        {
            (GraphicsLvo.LockLayerRom, 5, 257L),
            (GraphicsLvo.AttemptLockLayerRom, 5, 263L),
            (GraphicsLvo.UnlockLayerRom, 5, 269L),
            (GraphicsLvo.SyncSBitMap, 0, 271L),
            (GraphicsLvo.CopySBitMap, 0, 277L)
        })
        {
            var state = new M68kCpuState
            {
                D = { [0] = 0x89AB_CDEFu },
                Cycles = cycles,
                ProgramCounter = 0x0012_3A81
            };
            state.A[register] = 0x121;

            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x89AB_CDEFu, state.D[0]);
            Assert.Equal(cycles, state.Cycles);
        }

        Assert.Empty(calls);
    }

    [Fact]
    public void NativeOverlayBlitterVectorsTailChainWhenStatusBackendDeclines()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FE_1011;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[]
        {
            GraphicsLvo.OwnBlitter,
            GraphicsLvo.DisownBlitter,
            GraphicsLvo.WaitBlit
        })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        var own = 0;
        var disown = 0;
        var wait = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            tryOwnBlitter: () =>
            {
                own++;
                return false;
            },
            tryDisownBlitter: () =>
            {
                disown++;
                return false;
            },
            tryWaitBlit: () =>
            {
                wait++;
                return false;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        foreach (var (vector, cycles) in new[]
        {
            (GraphicsLvo.OwnBlitter, 141L),
            (GraphicsLvo.DisownBlitter, 147L),
            (GraphicsLvo.WaitBlit, 153L)
        })
        {
            var state = new M68kCpuState
            {
                ProgramCounter = 0x0012_3A01,
                Cycles = cycles,
                D = { [0] = 0x1357_9BDFu }
            };
            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)vector)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(cycles, state.Cycles);
        }

        Assert.Equal(1, own);
        Assert.Equal(1, disown);
        Assert.Equal(1, wait);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayProduceIdenticalSafeVectorResults()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        directBus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        directBus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        directBus.MapWritableMemory(0x600, new byte[GraphicsLayouts.TextFontMinimumSize]);
        directBus.MapWritableMemory(0x900, new byte[0x100]);
        directBus.MapWritableMemory(0xA00, new byte[GraphicsLayouts.TextExtentSize]);
        directBus.MapWritableMemory(0xB00, new byte[0x20]);
        directBus.MapWritableMemory(0xD00, new byte[0x200]);
        directBus.MapWritableMemory(0x1000, new byte[0x100]);
        directBus.MapWritableMemory(0x1100, new byte[0x100]);
        directBus.MapWritableMemory(0x1200, new byte[0x100]);
        directBus.MapWritableMemory(0x1500, new byte[0x400]);
        overlayBus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        overlayBus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        overlayBus.MapWritableMemory(0x600, new byte[GraphicsLayouts.TextFontMinimumSize]);
        overlayBus.MapWritableMemory(0x900, new byte[0x100]);
        overlayBus.MapWritableMemory(0xA00, new byte[GraphicsLayouts.TextExtentSize]);
        overlayBus.MapWritableMemory(0xB00, new byte[0x20]);
        overlayBus.MapWritableMemory(0xC00, new byte[GraphicsLayouts.TextExtentSize]);
        overlayBus.MapWritableMemory(0xD00, new byte[0x200]);
        overlayBus.MapWritableMemory(0x1000, new byte[0x100]);
        overlayBus.MapWritableMemory(0x1100, new byte[0x100]);
        overlayBus.MapWritableMemory(0x1200, new byte[0x100]);
        overlayBus.MapWritableMemory(0x1500, new byte[0x400]);
        foreach (var (address, length) in new[]
        {
            (0x1300u, 0x40),
            (0x1340u, 0x40),
            (0x1380u, 0x40),
            (0x13C0u, 0x40),
            (0x1400u, 0x40),
            (0x1440u, 0x40),
            (0x1480u, 0x80)
        })
        {
            directBus.MapWritableMemory(address, new byte[length]);
            overlayBus.MapWritableMemory(address, new byte[length]);
        }

        var image = new byte[0x2000];
        directBus.MapReadOnlyMemory(imageBase, image);
        overlayBus.MapReadOnlyMemory(imageBase, image);
        directBus.MapWritableMemory(0xC00, new byte[GraphicsLayouts.TextExtentSize]);

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        directBus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        directBus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 9);
        directBus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3, 0);
        directBus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        overlayBus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        overlayBus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 9);
        overlayBus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3, 0);
        overlayBus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);

        static void WriteFixedFont(AmigaBus bus)
        {
            const uint font = 0x600;
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, 0x1500);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteByte(0xB00, (byte)'A', 0);
        }


        void InvokeBoth(GraphicsLvo vector, M68kCpuState directState, M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        InvokeBoth(
            GraphicsLvo.InitRastPort,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });
        directBus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        overlayBus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        InvokeBoth(
            GraphicsLvo.InitView,
            new M68kCpuState { A = { [1] = 0x1300 }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [1] = 0x1300 }, D = { [0] = 0xDEAD_BEEFu } });
        InvokeBoth(
            GraphicsLvo.InitVPort,
            new M68kCpuState { A = { [0] = 0x1340 }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [0] = 0x1340 }, D = { [0] = 0xDEAD_BEEFu } });
        InvokeBoth(
            GraphicsLvo.InitBitMap,
            new M68kCpuState
            {
                A = { [0] = 0x1380 },
                D = { [0] = 3, [1] = 4, [2] = 9, [3] = 0xDEAD_BEEFu }
            },
            new M68kCpuState
            {
                A = { [0] = 0x1380 },
                D = { [0] = 3, [1] = 4, [2] = 9, [3] = 0xDEAD_BEEFu }
            });
        InvokeBoth(
            GraphicsLvo.InitArea,
            new M68kCpuState
            {
                A = { [0] = 0x13C0, [1] = 0x1400 },
                D = { [0] = 4, [1] = 0xDEAD_BEEFu }
            },
            new M68kCpuState
            {
                A = { [0] = 0x13C0, [1] = 0x1400 },
                D = { [0] = 4, [1] = 0xDEAD_BEEFu }
            });
        InvokeBoth(
            GraphicsLvo.InitTmpRas,
            new M68kCpuState
            {
                A = { [0] = 0x1440, [1] = 0x1480 },
                D = { [0] = 0x40, [1] = 0xDEAD_BEEFu }
            },
            new M68kCpuState
            {
                A = { [0] = 0x1440, [1] = 0x1480 },
                D = { [0] = 0x40, [1] = 0xDEAD_BEEFu }
            });
        InvokeBoth(
            GraphicsLvo.SetAPen,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 5 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 5 } });
        InvokeBoth(
            GraphicsLvo.SetBPen,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 6 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 6 } });
        InvokeBoth(
            GraphicsLvo.SetDrMd,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 2 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 2 } });
        InvokeBoth(
            GraphicsLvo.SetABPenDrMd,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 9, [1] = 3, [2] = 1 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 9, [1] = 3, [2] = 1 } });
        InvokeBoth(
            GraphicsLvo.SetWriteMask,
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xABCD_0005 } },
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xABCD_0005 } });
        Assert.Equal((byte)0x05, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(
            directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask),
            overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
        InvokeBoth(
            GraphicsLvo.SetMaxPen,
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 3 } },
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 3 } });
        InvokeBoth(
            GraphicsLvo.Move,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 7, [1] = 9 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 7, [1] = 9 } });

        InvokeBoth(
            GraphicsLvo.GetBPen,
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });
        InvokeBoth(
            GraphicsLvo.GetDrMd,
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });
        InvokeBoth(
            GraphicsLvo.SetOutlinePen,
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 4 } },
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 4 } });
        InvokeBoth(
            GraphicsLvo.GetOutlinePen,
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });

        directBus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth, 8);
        directBus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, unchecked((ushort)-2));
        overlayBus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth, 8);
        overlayBus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, unchecked((ushort)-2));
        InvokeBoth(
            GraphicsLvo.TextLength,
            new M68kCpuState { A = { [0] = 0, [1] = rastPort }, D = { [0] = 3 } },
            new M68kCpuState { A = { [0] = 0, [1] = rastPort }, D = { [0] = 3 } });
        WriteFixedFont(directBus);
        WriteFixedFont(overlayBus);
        InvokeBoth(
            GraphicsLvo.AskSoftStyle,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });
        InvokeBoth(
            GraphicsLvo.SetSoftStyle,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 4, [1] = 4 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 4, [1] = 4 } });

        static void WriteBusTag(AmigaBus bus, uint address, uint tag, uint data)
        {
            bus.WriteLong(address, tag);
            bus.WriteLong(address + 4, data);
        }

        // Keep this tag list to the pure RastPort state subset.  Font and
        // draw-bounds tags have provider-sensitive ownership and remain
        // outside the native-safe overlay proof.
        WriteBusTag(directBus, 0xD00, GraphicsRastPortAttributeOperations.RptagAPen, 7);
        WriteBusTag(directBus, 0xD08, GraphicsRastPortAttributeOperations.RptagBPen, 2);
        WriteBusTag(directBus, 0xD10, GraphicsRastPortAttributeOperations.RptagDrMd, 1);
        WriteBusTag(directBus, 0xD18, GraphicsRastPortAttributeOperations.RptagWriteMask, 0xBCDE_0005);
        WriteBusTag(directBus, 0xD20, GraphicsRastPortAttributeOperations.RptagOutlinePen, 6);
        WriteBusTag(directBus, 0xD28, GraphicsRastPortAttributeOperations.RptagMaxPen, 3);
        WriteBusTag(directBus, 0xD30, GraphicsRastPortAttributeOperations.RptagSoftStyle, 4);
        WriteBusTag(directBus, 0xD38, GraphicsRastPortAttributeOperations.RptagFont, 0x600);
        WriteBusTag(directBus, 0xD40, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteBusTag(overlayBus, 0xD00, GraphicsRastPortAttributeOperations.RptagAPen, 7);
        WriteBusTag(overlayBus, 0xD08, GraphicsRastPortAttributeOperations.RptagBPen, 2);
        WriteBusTag(overlayBus, 0xD10, GraphicsRastPortAttributeOperations.RptagDrMd, 1);
        WriteBusTag(overlayBus, 0xD18, GraphicsRastPortAttributeOperations.RptagWriteMask, 0xBCDE_0005);
        WriteBusTag(overlayBus, 0xD20, GraphicsRastPortAttributeOperations.RptagOutlinePen, 6);
        WriteBusTag(overlayBus, 0xD28, GraphicsRastPortAttributeOperations.RptagMaxPen, 3);
        WriteBusTag(overlayBus, 0xD30, GraphicsRastPortAttributeOperations.RptagSoftStyle, 4);
        WriteBusTag(overlayBus, 0xD38, GraphicsRastPortAttributeOperations.RptagFont, 0x600);
        WriteBusTag(overlayBus, 0xD40, GraphicsRastPortAttributeOperations.TagDone, 0);
        InvokeBoth(
            GraphicsLvo.SetRPAttrsA,
            new M68kCpuState { A = { [0] = 0xD00, [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [0] = 0xD00, [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });

        WriteBusTag(directBus, 0xE00, GraphicsRastPortAttributeOperations.RptagAPen, 0xD80);
        WriteBusTag(directBus, 0xE08, GraphicsRastPortAttributeOperations.RptagBPen, 0xD84);
        WriteBusTag(directBus, 0xE10, GraphicsRastPortAttributeOperations.RptagDrMd, 0xD88);
        WriteBusTag(directBus, 0xE18, GraphicsRastPortAttributeOperations.RptagWriteMask, 0xD8C);
        WriteBusTag(directBus, 0xE20, GraphicsRastPortAttributeOperations.RptagOutlinePen, 0xD90);
        WriteBusTag(directBus, 0xE28, GraphicsRastPortAttributeOperations.RptagMaxPen, 0xD94);
        WriteBusTag(directBus, 0xE30, GraphicsRastPortAttributeOperations.RptagSoftStyle, 0xD98);
        WriteBusTag(directBus, 0xE38, GraphicsRastPortAttributeOperations.RptagFont, 0xD9C);
        WriteBusTag(directBus, 0xE40, GraphicsRastPortAttributeOperations.RptagDrawBounds, 0xDA0);
        WriteBusTag(directBus, 0xE48, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteBusTag(overlayBus, 0xE00, GraphicsRastPortAttributeOperations.RptagAPen, 0xD80);
        WriteBusTag(overlayBus, 0xE08, GraphicsRastPortAttributeOperations.RptagBPen, 0xD84);
        WriteBusTag(overlayBus, 0xE10, GraphicsRastPortAttributeOperations.RptagDrMd, 0xD88);
        WriteBusTag(overlayBus, 0xE18, GraphicsRastPortAttributeOperations.RptagWriteMask, 0xD8C);
        WriteBusTag(overlayBus, 0xE20, GraphicsRastPortAttributeOperations.RptagOutlinePen, 0xD90);
        WriteBusTag(overlayBus, 0xE28, GraphicsRastPortAttributeOperations.RptagMaxPen, 0xD94);
        WriteBusTag(overlayBus, 0xE30, GraphicsRastPortAttributeOperations.RptagSoftStyle, 0xD98);
        WriteBusTag(overlayBus, 0xE38, GraphicsRastPortAttributeOperations.RptagFont, 0xD9C);
        WriteBusTag(overlayBus, 0xE40, GraphicsRastPortAttributeOperations.RptagDrawBounds, 0xDA0);
        WriteBusTag(overlayBus, 0xE48, GraphicsRastPortAttributeOperations.TagDone, 0);
        InvokeBoth(
            GraphicsLvo.GetRPAttrsA,
            new M68kCpuState { A = { [0] = 0xE00, [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } },
            new M68kCpuState { A = { [0] = 0xE00, [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu } });
        Assert.Equal(4u, directBus.ReadLong(0xD94));
        Assert.Equal(directBus.ReadLong(0xD94), overlayBus.ReadLong(0xD94));
        Assert.Equal(0xFFFF_FFFFu, directBus.ReadLong(0xD98));
        Assert.Equal(directBus.ReadLong(0xD98), overlayBus.ReadLong(0xD98));
        Assert.Equal(0x600u, directBus.ReadLong(0xD9C));
        Assert.Equal(directBus.ReadLong(0xD9C), overlayBus.ReadLong(0xD9C));
        Assert.Equal((ushort)0, directBus.ReadWord(0xDA0 + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0, directBus.ReadWord(0xDA0 + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)31, directBus.ReadWord(0xDA0 + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)8, directBus.ReadWord(0xDA0 + (uint)GraphicsLayouts.RectangleMaxY));
        for (var offset = 0; offset < GraphicsLayouts.RectangleSize; offset++)
            Assert.Equal(
                directBus.ReadByte(0xDA0 + (uint)offset),
                overlayBus.ReadByte(0xDA0 + (uint)offset));
        InvokeBoth(
            GraphicsLvo.TextExtent,
            new M68kCpuState { A = { [0] = 0xB00, [1] = rastPort, [2] = 0xA00 }, D = { [0] = 1 } },
            new M68kCpuState { A = { [0] = 0xB00, [1] = rastPort, [2] = 0xA00 }, D = { [0] = 1 } });
        InvokeBoth(
            GraphicsLvo.FontExtent,
            new M68kCpuState { A = { [0] = 0x600, [1] = 0xA00 } },
            new M68kCpuState { A = { [0] = 0x600, [1] = 0xA00 } });
        InvokeBoth(
            GraphicsLvo.TextFit,
            new M68kCpuState { A = { [0] = 0xB00, [1] = rastPort, [2] = 0xA00 }, D = { [0] = 1, [1] = 1, [2] = 8, [3] = 8 } },
            new M68kCpuState { A = { [0] = 0xB00, [1] = rastPort, [2] = 0xA00 }, D = { [0] = 1, [1] = 1, [2] = 8, [3] = 8 } });
        InvokeBoth(
            GraphicsLvo.GetBitMapAttr,
            new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 8 } },
            new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 8 } });

        // BMA_FLAGS is a capability result, not just a copy of the guest
        // header.  Prove that the direct portable call and the native-safe
        // ROM overlay agree when all declared planes are aligned, then agree
        // again when one plane invalidates BMF_DISPLAYABLE.
        directBus.WriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x0A,
            0);
        overlayBus.WriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x0A,
            0);
        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x1000);
        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x1100);
        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8, 0x1200);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x1000);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x1100);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8, 0x1200);
        InvokeBoth(
            GraphicsLvo.GetBitMapAttr,
            new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 12 } },
            new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 12 } });

        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x1101);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x1101);
        InvokeBoth(
            GraphicsLvo.GetBitMapAttr,
            new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 12 } },
            new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 12 } });

        // ReadPixel and WritePixel are now part of the native-safe subset.
        // They only dereference the guest RastPort/BitMap/plane graph and
        // therefore provide a useful first differential proof for the future
        // native 68k overlay path.
        directBus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        overlayBus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x1000);
        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x1100);
        directBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8, 0x1200);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x1000);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x1100);
        overlayBus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8, 0x1200);
        InvokeBoth(
            GraphicsLvo.SetAPen,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 5 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 5 } });
        InvokeBoth(
            GraphicsLvo.WritePixel,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 2, [1] = 3 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 2, [1] = 3 } });
        InvokeBoth(
            GraphicsLvo.ReadPixel,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 2, [1] = 3 } },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 2, [1] = 3 } });
        InvokeBoth(
            GraphicsLvo.ScalerDiv,
            new M68kCpuState { D = { [0] = 100, [1] = 2, [2] = 1 } },
            new M68kCpuState { D = { [0] = 100, [1] = 2, [2] = 1 } });
        InvokeBoth(
            GraphicsLvo.ScalerDiv,
            new M68kCpuState { D = { [0] = 1, [1] = 1, [2] = 2 } },
            new M68kCpuState { D = { [0] = 1, [1] = 1, [2] = 2 } });

        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(rastPort + (uint)offset),
                overlayBus.ReadByte(rastPort + (uint)offset));
        }

        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(0xA00u + (uint)offset),
                overlayBus.ReadByte(0xA00u + (uint)offset));
        }

        for (var offset = 0; offset < 0x100; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(0xD00u + (uint)offset),
                overlayBus.ReadByte(0xD00u + (uint)offset));
        }

        foreach (var (address, length) in new[]
        {
            (0x1300u, 0x40),
            (0x1340u, 0x40),
            (0x1380u, 0x40),
            (0x13C0u, 0x40),
            (0x1400u, 0x40),
            (0x1440u, 0x40),
            (0x1480u, 0x80)
        })
        {
            for (var offset = 0; offset < length; offset++)
            {
                Assert.Equal(
                    directBus.ReadByte(address + (uint)offset),
                    overlayBus.ReadByte(address + (uint)offset));
            }
        }

        for (var plane = 0; plane < 3; plane++)
        {
            var planeAddress = 0x1000u + (uint)(plane * 0x100);
            for (var offset = 0; offset < 0x100; offset++)
            {
                Assert.Equal(
                    directBus.ReadByte(planeAddress + (uint)offset),
                    overlayBus.ReadByte(planeAddress + (uint)offset));
            }
        }
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveProportionalMetricParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint font = 0x600;
        const uint charData = 0x900;
        const uint text = 0xB00;
        const uint extent = 0xA00;
        const uint constraint = 0xC00;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(charData, new byte[0x100]);
            bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
            bus.MapWritableMemory(constraint, new byte[GraphicsLayouts.TextExtentSize]);
            bus.MapWritableMemory(text, new byte[0x20]);
        }

        static void WriteProportionalFont(AmigaBus bus)
        {
            const uint font = 0x600;
            const uint charData = 0x900;
            const uint charLoc = 0x920;
            const uint charSpace = 0x930;
            const uint charKern = 0x940;
            const uint rastPort = 0x100;
            const uint text = 0xB00;

            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'B', 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 2);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);

            bus.WriteWord(charLoc, 1);
            bus.WriteWord(charLoc + 2, 5);
            bus.WriteWord(charLoc + 4, 9);
            bus.WriteWord(charLoc + 6, 3);
            bus.WriteWord(charSpace, 6);
            bus.WriteWord(charSpace + 2, 4);
            bus.WriteWord(charKern, unchecked((ushort)-1));
            bus.WriteWord(charKern + 2, 0);
            bus.WriteByte(charData, 0x54, 0);
            bus.WriteByte(charData + 1, 0x70, 0);
            bus.WriteByte(charData + 2, 0x28, 0);
            bus.WriteByte(charData + 3, 0x40, 0);
            bus.WriteByte(text, (byte)'A', 0);
            bus.WriteByte(text + 1, (byte)'B', 0);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
        }

        WriteProportionalFont(directBus);
        WriteProportionalFont(overlayBus);
        foreach (var bus in new[] { directBus, overlayBus })
        {
            // The explicit rectangle is deliberately generous.  Kickstart
            // ignores the alternate rendering-box dimensions whenever this
            // pointer is non-NULL, so the mapped TextFit below must accept
            // both characters even though D2 supplies a width of one.
            bus.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentWidth, 99);
            bus.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentHeight, 4);
            bus.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinX, unchecked((ushort)-4));
            bus.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinY, unchecked((ushort)-3));
            bus.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxX, 99);
            bus.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxY, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        static void CompareState(M68kCpuState directState, M68kCpuState overlayState)
        {
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        void InvokeBoth(GraphicsLvo vector, M68kCpuState directState, M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            CompareState(directState, overlayState);
        }

        var directTextLength = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 2 }
        };
        var overlayTextLength = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 2 }
        };
        InvokeBoth(GraphicsLvo.TextLength, directTextLength, overlayTextLength);
        Assert.Equal(12u, directTextLength.D[0]);

        var directTextExtent = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent },
            D = { [0] = 2 }
        };
        var overlayTextExtent = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent },
            D = { [0] = 2 }
        };
        InvokeBoth(GraphicsLvo.TextExtent, directTextExtent, overlayTextExtent);
        Assert.Equal(0u, directTextExtent.D[0]);
        Assert.Equal((ushort)12, directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-1, unchecked((short)directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)10, unchecked((short)directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        var directTextFit = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent },
            D = { [0] = 2, [1] = 1, [2] = 10, [3] = 4 }
        };
        var overlayTextFit = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent },
            D = { [0] = 2, [1] = 1, [2] = 10, [3] = 4 }
        };
        InvokeBoth(GraphicsLvo.TextFit, directTextFit, overlayTextFit);
        Assert.Equal(1u, directTextFit.D[0]);
        Assert.Equal((ushort)7, directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));

        var directMappedConstraintTextFit = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent, [3] = constraint },
            D = { [0] = 2, [1] = 1, [2] = 0x8000, [3] = 0x8000 }
        };
        var overlayMappedConstraintTextFit = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent, [3] = constraint },
            D = { [0] = 2, [1] = 1, [2] = 0x8000, [3] = 0x8000 }
        };
        InvokeBoth(
            GraphicsLvo.TextFit,
            directMappedConstraintTextFit,
            overlayMappedConstraintTextFit);
        Assert.Equal(2u, directMappedConstraintTextFit.D[0]);
        Assert.Equal((ushort)12, directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));

        var directFontExtent = new M68kCpuState
        {
            A = { [0] = font, [1] = extent },
            D = { [0] = 0xCAFE_BABEu }
        };
        var overlayFontExtent = new M68kCpuState
        {
            A = { [0] = font, [1] = extent },
            D = { [0] = 0xCAFE_BABEu }
        };
        InvokeBoth(GraphicsLvo.FontExtent, directFontExtent, overlayFontExtent);
        Assert.Equal(0u, directFontExtent.D[0]);
        Assert.Equal((ushort)5, directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-1, unchecked((short)directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)3, unchecked((short)directBus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            Assert.Equal(directBus.ReadByte(rastPort + (uint)offset), overlayBus.ReadByte(rastPort + (uint)offset));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal(directBus.ReadByte(extent + (uint)offset), overlayBus.ReadByte(extent + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveWeighTAMatchParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint requested = 0x100;
        const uint target = 0x120;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(requested, new byte[GraphicsLayouts.TextAttrSize]);
            bus.MapWritableMemory(target, new byte[GraphicsLayouts.TextAttrSize]);
            bus.WriteLong(requested + (uint)GraphicsLayouts.TextAttrName, 0);
            bus.WriteWord(requested + (uint)GraphicsLayouts.TextAttrYSize, 10);
            bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrStyle, 0x02, 0);
            bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);
            bus.WriteLong(target + (uint)GraphicsLayouts.TextAttrName, 0);
            bus.WriteWord(target + (uint)GraphicsLayouts.TextAttrYSize, 10);
            bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrStyle, 0x02, 0);
            bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = requested, [1] = target, [2] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 179
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = requested, [1] = target, [2] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 179
        };

        direct.Invoke(directState, (int)GraphicsLvo.WeighTAMatch);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(32767u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(179, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveAskFontParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint font = 0x200;
        const uint name = 0x300;
        const uint textAttr = 0x400;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(name, new byte[0x20]);
            bus.MapWritableMemory(textAttr, new byte[GraphicsLayouts.TextAttrSize]);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0x02, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x01, 0);
            for (var index = 0; index < 9; index++)
                bus.WriteByte(name + (uint)index, (byte)"topaz.font"[index], 0);
            for (var index = 0; index < GraphicsLayouts.TextAttrSize; index++)
                bus.WriteByte(textAttr + (uint)index, (byte)(0xA0 + index), 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 181
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 181
        };

        direct.Invoke(directState, (int)GraphicsLvo.AskFont);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AskFont));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(181, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        for (var index = 0; index < GraphicsLayouts.TextAttrSize; index++)
            Assert.Equal(directBus.ReadByte(textAttr + (uint)index), overlayBus.ReadByte(textAttr + (uint)index));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyTextMetricOutputsBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint textAttr = 0x00F0_1100;
        const uint textExtent = 0x00F0_1200;
        const byte textAttrSentinel = 0xA5;
        const byte textExtentSentinel = 0xB6;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(
            textAttr,
            Enumerable.Repeat(textAttrSentinel, GraphicsLayouts.TextAttrSize).ToArray());
        bus.MapReadOnlyMemory(
            textAttr,
            Enumerable.Repeat(textAttrSentinel, GraphicsLayouts.TextAttrSize).ToArray());
        bus.MapWritableMemory(
            textExtent,
            Enumerable.Repeat(textExtentSentinel, GraphicsLayouts.TextExtentSize).ToArray());
        bus.MapReadOnlyMemory(
            textExtent,
            Enumerable.Repeat(textExtentSentinel, GraphicsLayouts.TextExtentSize).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var askFont = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = 0x00F0_1300 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 151,
            ProgramCounter = 0x0012_3711
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AskFont)),
            askFont));
        Assert.Equal(0xCAFE_BABEu, askFont.D[0]);
        Assert.Equal(151, askFont.Cycles);
        Assert.Equal(0x0012_3711u, askFont.ProgramCounter);

        var textExtentState = new M68kCpuState
        {
            A = { [0] = 0x00F0_1400, [1] = 0x00F0_1500, [2] = textExtent },
            D = { [0] = 1, [1] = 0x1357_9BDFu },
            Cycles = 153,
            ProgramCounter = 0x0012_3713
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.TextExtent)),
            textExtentState));
        Assert.Equal(1u, textExtentState.D[0]);
        Assert.Equal(153, textExtentState.Cycles);
        Assert.Equal(0x0012_3713u, textExtentState.ProgramCounter);

        var textFitState = new M68kCpuState
        {
            A = { [0] = 0x00F0_1600, [1] = 0x00F0_1700, [2] = textExtent },
            D = { [0] = 1, [1] = 1, [2] = 8, [3] = 8 },
            Cycles = 155,
            ProgramCounter = 0x0012_3715
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.TextFit)),
            textFitState));
        Assert.Equal(1u, textFitState.D[0]);
        Assert.Equal(155, textFitState.Cycles);
        Assert.Equal(0x0012_3715u, textFitState.ProgramCounter);

        var fontExtentState = new M68kCpuState
        {
            A = { [0] = 0x00F0_1800, [1] = textExtent },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 157,
            ProgramCounter = 0x0012_3717
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FontExtent)),
            fontExtentState));
        Assert.Equal(0xDEAD_BEEFu, fontExtentState.D[0]);
        Assert.Equal(157, fontExtentState.Cycles);
        Assert.Equal(0x0012_3717u, fontExtentState.ProgramCounter);

        for (var offset = 0; offset < GraphicsLayouts.TextAttrSize; offset++)
            Assert.Equal(textAttrSentinel, bus.ReadByte(textAttr + (uint)offset));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal(textExtentSentinel, bus.ReadByte(textExtent + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBitMapGeometryBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint bitMap = 0x00F0_1A00;
        const byte sentinel = 0xC7;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(
            bitMap,
            Enumerable.Repeat(sentinel, GraphicsLayouts.BitMapSize).ToArray());
        bus.MapReadOnlyMemory(
            bitMap,
            Enumerable.Repeat(sentinel, GraphicsLayouts.BitMapSize).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 3, [1] = 320, [2] = 200, [3] = 0xDEAD_BEEFu },
            Cycles = 163,
            ProgramCounter = 0x0012_3719
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitBitMap)),
            state));
        Assert.Equal(3u, state.D[0]);
        Assert.Equal(320u, state.D[1]);
        Assert.Equal(200u, state.D[2]);
        Assert.Equal(0xDEAD_BEEFu, state.D[3]);
        Assert.Equal(163, state.Cycles);
        Assert.Equal(0x0012_3719u, state.ProgramCounter);

        // The eight-byte geometry prefix and caller-owned Planes[] tail must
        // remain byte-for-byte unchanged when the native overlay sees a
        // read-only provider/image mapping.
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(bitMap + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyAreaInitializersBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
