        bus.MapReadOnlyMemory(
            tmpRas,
            Enumerable.Repeat(tmpSentinel, GraphicsLayouts.TmpRasSize).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var areaState = new M68kCpuState
        {
            A = { [0] = areaInfo, [1] = 0x00F0_1E00 },
            D = { [0] = 3, [1] = 0x1357_9BDFu },
            Cycles = 167,
            ProgramCounter = 0x0012_371B
        };
