        var tmpState = new M68kCpuState
        {
            A = { [0] = tmpRas, [1] = 0x00F0_1F00 },
            D = { [0] = 0x200, [1] = 0xCAFE_BABEu },
            Cycles = 169,
            ProgramCounter = 0x0012_371D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
