        Assert.Equal(169, tmpState.Cycles);
        Assert.Equal(0x0012_371Du, tmpState.ProgramCounter);

        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.Equal(areaSentinel, bus.ReadByte(areaInfo + (uint)offset));
        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            Assert.Equal(tmpSentinel, bus.ReadByte(tmpRas + (uint)offset));
    }

    [Fact]
    public void RomOverlayTailChainsMalformedAskFontToOriginalVector()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint invalidRastPort = 0x00F0_0000;
        const uint target = 0x00FA_F403;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AskFont)), target);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = 0x400, [1] = invalidRastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 187,
