    [Fact]
    public void NativeOverlayAndHostGatewayPreserveSetFontCacheParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint font = 0x200;
        const uint charData = 0x400;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(charData, new byte[0x100]);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
            for (var index = 0; index < GraphicsLayouts.RastPortMinimumSize; index++)
                bus.WriteByte(rastPort + (uint)index, (byte)(0x40 + index), 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = font, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 191
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = font, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 191
        };

        direct.Invoke(directState, (int)GraphicsLvo.SetFont);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetFont));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(191, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        for (var index = 0; index < GraphicsLayouts.RastPortMinimumSize; index++)
            Assert.Equal(directBus.ReadByte(rastPort + (uint)index), overlayBus.ReadByte(rastPort + (uint)index));
        Assert.Equal(font, directBus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)8, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)8, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)7, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        // SetFont clears the RastPort's algorithmic style in both mapped and
        // direct paths, while leaving caller-owned TxSpacing untouched.
        Assert.Equal((byte)0,
            directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)0x8081, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlySetFontRastPortBeforeMetricDecode()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_2600;
        const uint font = 0x00F0_2700;
        const uint charData = 0x00F0_2800;
        const uint nativeTarget = 0x00FE_1719;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetFont)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charData, new byte[0x100]);

        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            bus.WriteByte(rastPort + (uint)offset, (byte)(0x60 + offset), 0);

        var original = new byte[GraphicsLayouts.RastPortMinimumSize];
        for (var offset = 0; offset < original.Length; offset++)
            original[offset] = bus.ReadByte(rastPort + (uint)offset);
        bus.MapReadOnlyMemory(rastPort, original);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [0] = font, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 823,
            ProgramCounter = 0x0012_385B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetFont)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(823, state.Cycles);
        for (var offset = 0; offset < original.Length; offset++)
            Assert.Equal(original[offset], bus.ReadByte(rastPort + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyRastPortAttributeWritersBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_2A00;
        const uint tags = 0x00F0_2B00;
        const uint nativeTarget = 0x00FE_171F;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetSoftStyle)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRPAttrsA)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(tags, new byte[0x10]);

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagWriteMask);
        bus.WriteLong(tags + 4u, 3);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            bus.WriteByte(rastPort + (uint)offset, (byte)(0x70 + offset), 0);

        var original = new byte[GraphicsLayouts.RastPortMinimumSize];
        for (var offset = 0; offset < original.Length; offset++)
            original[offset] = bus.ReadByte(rastPort + (uint)offset);
        bus.MapReadOnlyMemory(rastPort, original);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var softStyle = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x12, [1] = 0xFF },
            Cycles = 829,
            ProgramCounter = 0x0012_3861
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetSoftStyle)),
            softStyle));
        Assert.Equal(nativeTarget, softStyle.ProgramCounter);
        Assert.Equal(0x12u, softStyle.D[0]);
        Assert.Equal(0xFFu, softStyle.D[1]);
        Assert.Equal(829, softStyle.Cycles);

        var attrs = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 833,
            ProgramCounter = 0x0012_3867
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRPAttrsA)),
            attrs));
        Assert.Equal(nativeTarget, attrs.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, attrs.D[0]);
        Assert.Equal(833, attrs.Cycles);
        for (var offset = 0; offset < original.Length; offset++)
            Assert.Equal(original[offset], bus.ReadByte(rastPort + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyDirectRastPortSettersBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_3000;
        const uint nativeTarget = 0x00FE_1731;

        var vectors = new[]
        {
            GraphicsLvo.SetAPen,
            GraphicsLvo.SetBPen,
            GraphicsLvo.SetDrMd,
            GraphicsLvo.SetABPenDrMd,
            GraphicsLvo.SetWriteMask,
            GraphicsLvo.SetMaxPen,
            GraphicsLvo.SetOutlinePen,
            GraphicsLvo.Move
        };

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in vectors)
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            bus.WriteByte(rastPort + (uint)offset, (byte)(0x86 + offset), 0);

        var original = new byte[GraphicsLayouts.RastPortMinimumSize];
        for (var offset = 0; offset < original.Length; offset++)
            original[offset] = bus.ReadByte(rastPort + (uint)offset);
        bus.MapReadOnlyMemory(rastPort, original);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        void AssertDeclined(
            GraphicsLvo vector,
            M68kCpuState state,
            uint d0,
            uint d1,
            uint d2,
            int cycles,
            uint programCounter)
        {
            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase + (int)vector)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(d0, state.D[0]);
            Assert.Equal(d1, state.D[1]);
            Assert.Equal(d2, state.D[2]);
            Assert.Equal(cycles, state.Cycles);
            Assert.NotEqual(programCounter, state.ProgramCounter);
            for (var offset = 0; offset < original.Length; offset++)
                Assert.Equal(original[offset], bus.ReadByte(rastPort + (uint)offset));
        }

        var setAPen = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 0x1111_1111u, [2] = 0xAAAA_AAAAu },
            Cycles = 847,
            ProgramCounter = 0x0012_3871
        };
        AssertDeclined(GraphicsLvo.SetAPen, setAPen, 3, 0x1111_1111u, 0xAAAA_AAAAu, 847, 0x0012_3871);

        var setBPen = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 4, [1] = 0x2222_2222u, [2] = 0xBBBB_BBBBu },
            Cycles = 849,
            ProgramCounter = 0x0012_3877
        };
        AssertDeclined(GraphicsLvo.SetBPen, setBPen, 4, 0x2222_2222u, 0xBBBB_BBBBu, 849, 0x0012_3877);

        var setDrMd = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = 0x3333_3333u, [2] = 0xCCCC_CCCCu },
            Cycles = 851,
            ProgramCounter = 0x0012_387D
        };
        AssertDeclined(GraphicsLvo.SetDrMd, setDrMd, 2, 0x3333_3333u, 0xCCCC_CCCCu, 851, 0x0012_387D);

        var setABPenDrMd = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 1, [1] = 2, [2] = 0 },
            Cycles = 853,
            ProgramCounter = 0x0012_3883
        };
        AssertDeclined(GraphicsLvo.SetABPenDrMd, setABPenDrMd, 1, 2, 0, 853, 0x0012_3883);

        var setWriteMask = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 0x12, [1] = 0x4444_4444u, [2] = 0xDDDD_DDDDu },
            Cycles = 855,
            ProgramCounter = 0x0012_3889
        };
        AssertDeclined(GraphicsLvo.SetWriteMask, setWriteMask, 0x12, 0x4444_4444u, 0xDDDD_DDDDu, 855, 0x0012_3889);

        var setMaxPen = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 5, [1] = 0x5555_5555u, [2] = 0xEEEE_EEEEu },
            Cycles = 857,
            ProgramCounter = 0x0012_388F
        };
        AssertDeclined(GraphicsLvo.SetMaxPen, setMaxPen, 5, 0x5555_5555u, 0xEEEE_EEEEu, 857, 0x0012_388F);

        var setOutlinePen = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 6, [1] = 0x6666_6666u, [2] = 0xFFFF_FFFFu },
            Cycles = 859,
            ProgramCounter = 0x0012_3895
        };
        AssertDeclined(GraphicsLvo.SetOutlinePen, setOutlinePen, 6, 0x6666_6666u, 0xFFFF_FFFFu, 859, 0x0012_3895);

        var move = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 10, [1] = 11, [2] = 0x1234_5678u },
            Cycles = 861,
            ProgramCounter = 0x0012_389B
        };
        AssertDeclined(GraphicsLvo.Move, move, 10, 11, 0x1234_5678u, 861, 0x0012_389B);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlySetRastPlanesBeforeBitmapWrite()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_3400;
        const uint bitMap = 0x00F0_3500;
        const uint plane0 = 0x00F0_3600;
        const uint plane1 = 0x00F0_3700;
        const uint nativeTarget = 0x00FE_1737;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRast)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[2]);
        bus.MapWritableMemory(plane1, new byte[2]);

        bus.WriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap);
        bus.WriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0x03,
            0);
        bus.WriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2);
        bus.WriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1);
        bus.WriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            2,
            0);
        bus.WriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            0,
            0);
        bus.WriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane0);
        bus.WriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            plane1);
        bus.WriteByte(plane0, 0x11, 0);
        bus.WriteByte(plane0 + 1u, 0x12, 0);
        bus.WriteByte(plane1, 0x21, 0);
        bus.WriteByte(plane1 + 1u, 0x22, 0);

        bus.MapReadOnlyMemory(plane0, new byte[] { 0x11, 0x12 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 0x1234_5678u, [2] = 0x89AB_CDEFu },
            Cycles = 863,
            ProgramCounter = 0x0012_38A1
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRast)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(3u, state.D[0]);
        Assert.Equal(0x1234_5678u, state.D[1]);
        Assert.Equal(0x89AB_CDEFu, state.D[2]);
        Assert.Equal(863, state.Cycles);
        Assert.Equal((byte)0x11, bus.ReadByte(plane0));
        Assert.Equal((byte)0x12, bus.ReadByte(plane0 + 1u));
        Assert.Equal((byte)0x21, bus.ReadByte(plane1));
        Assert.Equal((byte)0x22, bus.ReadByte(plane1 + 1u));
        Assert.Equal(bitMap, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap));
        Assert.Equal((byte)0x03, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
    }

