        Assert.Equal(0u, state.D[3]);
        Assert.Equal(0xDEAD_BEEFu, state.D[4]);
        Assert.Equal(871, state.Cycles);
        Assert.Equal((byte)0x31, bus.ReadByte(plane0));
        Assert.Equal((byte)0x32, bus.ReadByte(plane0 + 1u));
        Assert.Equal((byte)0x41, bus.ReadByte(plane1));
        Assert.Equal((byte)0x42, bus.ReadByte(plane1 + 1u));
    }

