        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.EraseRect)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[2]);
        bus.MapWritableMemory(plane1, new byte[2]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        for (var offset = 0; offset < 8; offset++)
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)offset, (byte)(0xB0 + offset), 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 7, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, 0x1234);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteByte(plane0, 0xB1, 0);
        bus.WriteByte(plane0 + 1u, 0xB2, 0);
        bus.WriteByte(plane1, 0xC1, 0);
        bus.WriteByte(plane1 + 1u, 0xC2, 0);
        bus.MapReadOnlyMemory(plane0, new byte[] { 0xB1, 0xB2 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 15, [3] = 0, [4] = 0xFACE_CAFEu },
            Cycles = 887,
            ProgramCounter = 0x0012_38C5
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.EraseRect)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0u, state.D[1]);
        Assert.Equal(15u, state.D[2]);
        Assert.Equal(0u, state.D[3]);
        Assert.Equal(0xFACE_CAFEu, state.D[4]);
        Assert.Equal(887, state.Cycles);
        Assert.Equal((byte)0xB1, bus.ReadByte(plane0));
        Assert.Equal((byte)0xB2, bus.ReadByte(plane0 + 1u));
        Assert.Equal((byte)0xC1, bus.ReadByte(plane1));
        Assert.Equal((byte)0xC2, bus.ReadByte(plane1 + 1u));
        Assert.Equal((byte)5, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((ushort)0x1234, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyClearPlanesBeforeTextDecode()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_5100;
        const uint bitMap = 0x00F0_5200;
        const uint plane0 = 0x00F0_5300;
        const uint plane1 = 0x00F0_5400;
        const uint nativeTarget = 0x00FE_1761;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClearEOL)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClearScreen)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[16]);
        bus.MapWritableMemory(plane1, new byte[16]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 2, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 9, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        for (var offset = 0; offset < 16; offset++)
        {
            bus.WriteByte(plane0 + (uint)offset, (byte)(0xD1 + offset), 0);
            bus.WriteByte(plane1 + (uint)offset, (byte)(0xE1 + offset), 0);
        }
        bus.MapReadOnlyMemory(
            plane0,
            Enumerable.Range(0, 16).Select(offset => (byte)(0xD1 + offset)).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var clearEol = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 893,
            ProgramCounter = 0x0012_38CB
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClearEOL)),
            clearEol));
        Assert.Equal(nativeTarget, clearEol.ProgramCounter);
        Assert.Equal(0x1234_5678u, clearEol.D[0]);
        Assert.Equal(893, clearEol.Cycles);

        var clearScreen = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 895,
            ProgramCounter = 0x0012_38D1
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClearScreen)),
            clearScreen));
        Assert.Equal(nativeTarget, clearScreen.ProgramCounter);
        Assert.Equal(0x89AB_CDEFu, clearScreen.D[0]);
        Assert.Equal(895, clearScreen.Cycles);

        for (var offset = 0; offset < 16; offset++)
        {
            Assert.Equal((byte)(0xD1 + offset), bus.ReadByte(plane0 + (uint)offset));
            Assert.Equal((byte)(0xE1 + offset), bus.ReadByte(plane1 + (uint)offset));
        }
        Assert.Equal((byte)2, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)9, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyScrollPlanesBeforeMovePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_5500;
        const uint bitMap = 0x00F0_5600;
        const uint plane0 = 0x00F0_5700;
        const uint plane1 = 0x00F0_5800;
        const uint nativeTarget = 0x00FE_1767;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ScrollRaster)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ScrollRasterBF)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[2]);
        bus.MapWritableMemory(plane1, new byte[2]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 11, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, 0x1234);
        for (var offset = 0; offset < 8; offset++)
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)offset, (byte)(0x90 + offset), 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteByte(plane0, 0x11, 0);
        bus.WriteByte(plane0 + 1u, 0x12, 0);
        bus.WriteByte(plane1, 0x21, 0);
        bus.WriteByte(plane1 + 1u, 0x22, 0);
        bus.MapReadOnlyMemory(plane0, new byte[] { 0x11, 0x12 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var scroll = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 15, [5] = 0 },
            Cycles = 899,
            ProgramCounter = 0x0012_38D7
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ScrollRaster)),
            scroll));
        Assert.Equal(nativeTarget, scroll.ProgramCounter);
        Assert.Equal(1u, scroll.D[0]);
        Assert.Equal(0u, scroll.D[1]);
        Assert.Equal(0u, scroll.D[2]);
        Assert.Equal(0u, scroll.D[3]);
        Assert.Equal(15u, scroll.D[4]);
        Assert.Equal(0u, scroll.D[5]);
        Assert.Equal(899, scroll.Cycles);

        var scrollBf = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 15, [5] = 0 },
            Cycles = 901,
            ProgramCounter = 0x0012_38DD
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ScrollRasterBF)),
            scrollBf));
        Assert.Equal(nativeTarget, scrollBf.ProgramCounter);
        Assert.Equal(1u, scrollBf.D[0]);
        Assert.Equal(0u, scrollBf.D[1]);
        Assert.Equal(0u, scrollBf.D[2]);
        Assert.Equal(0u, scrollBf.D[3]);
        Assert.Equal(15u, scrollBf.D[4]);
        Assert.Equal(0u, scrollBf.D[5]);
        Assert.Equal(901, scrollBf.Cycles);

        Assert.Equal((byte)0x11, bus.ReadByte(plane0));
        Assert.Equal((byte)0x12, bus.ReadByte(plane0 + 1u));
        Assert.Equal((byte)0x21, bus.ReadByte(plane1));
        Assert.Equal((byte)0x22, bus.ReadByte(plane1 + 1u));
        Assert.Equal((byte)11, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)3, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((ushort)0x1234, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

