        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        for (var offset = 0; offset < 4; offset++)
        {
            bus.WriteByte(plane0 + (uint)offset, (byte)(0x71 + offset), 0);
            bus.WriteByte(plane1 + (uint)offset, (byte)(0x81 + offset), 0);
        }
        bus.MapReadOnlyMemory(
            plane0,
            new byte[] { 0x71, 0x72, 0x73, 0x74 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var line = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0, [2] = lineArray },
            D = { [0] = 2, [1] = 0, [2] = 16, [3] = 0x1111_2222u },
            Cycles = 917,
            ProgramCounter = 0x0012_38F5
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.WritePixelLine8)),
            line));
        Assert.Equal(nativeTarget, line.ProgramCounter);
        Assert.Equal(2u, line.D[0]);
        Assert.Equal(0u, line.D[1]);
        Assert.Equal(16u, line.D[2]);
        Assert.Equal(0x1111_2222u, line.D[3]);
        Assert.Equal(917, line.Cycles);

        var array = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0, [2] = array8 },
            D = { [0] = 2, [1] = 0, [2] = 15, [3] = 1, [4] = 0x3333_4444u },
            Cycles = 919,
            ProgramCounter = 0x0012_38FB
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.WritePixelArray8)),
            array));
        Assert.Equal(nativeTarget, array.ProgramCounter);
        Assert.Equal(2u, array.D[0]);
        Assert.Equal(0u, array.D[1]);
        Assert.Equal(15u, array.D[2]);
        Assert.Equal(1u, array.D[3]);
        Assert.Equal(0x3333_4444u, array.D[4]);
        Assert.Equal(919, array.Cycles);

        var chunky = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = chunkyArray },
            D = { [0] = 2, [1] = 0, [2] = 15, [3] = 1, [4] = 16, [5] = 0x5555_6666u },
            Cycles = 921,
            ProgramCounter = 0x0012_3901
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.WriteChunkyPixels)),
            chunky));
        Assert.Equal(nativeTarget, chunky.ProgramCounter);
        Assert.Equal(2u, chunky.D[0]);
        Assert.Equal(0u, chunky.D[1]);
        Assert.Equal(15u, chunky.D[2]);
        Assert.Equal(1u, chunky.D[3]);
        Assert.Equal(16u, chunky.D[4]);
        Assert.Equal(0x5555_6666u, chunky.D[5]);
        Assert.Equal(921, chunky.Cycles);

        for (var offset = 0; offset < 4; offset++)
        {
            Assert.Equal((byte)(0x71 + offset), bus.ReadByte(plane0 + (uint)offset));
            Assert.Equal((byte)(0x81 + offset), bus.ReadByte(plane1 + (uint)offset));
        }
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyAreaCollectorBeforeVectorPublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_6E00;
        const uint areaInfo = 0x00F0_6F00;
        const uint vectorTable = 0x00F0_7000;
        const uint flagTable = 0x00F0_7100;
        const uint nativeTarget = 0x00FE_1785;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaMove)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaDraw)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaEllipse)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectorTable, new byte[16]);
        bus.MapWritableMemory(flagTable, new byte[4]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable, vectorTable);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectorTable + 4u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable, flagTable);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flagTable + 1u);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 0);
        bus.WriteWord(vectorTable, 0);
        bus.WriteWord(vectorTable + 2u, 0);
        bus.WriteByte(flagTable, 1, 0);
        bus.MapReadOnlyMemory(
            vectorTable,
            Enumerable.Repeat((byte)0, 16).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var move = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 5, [1] = 6, [2] = 0x1111_2222u },
            Cycles = 923,
            ProgramCounter = 0x0012_3907
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaMove)),
            move));
        Assert.Equal(nativeTarget, move.ProgramCounter);
        Assert.Equal(5u, move.D[0]);
        Assert.Equal(6u, move.D[1]);
        Assert.Equal(0x1111_2222u, move.D[2]);
        Assert.Equal(923, move.Cycles);

        var draw = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 7, [1] = 8, [2] = 0x3333_4444u },
            Cycles = 925,
            ProgramCounter = 0x0012_390D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaDraw)),
            draw));
        Assert.Equal(nativeTarget, draw.ProgramCounter);
        Assert.Equal(7u, draw.D[0]);
        Assert.Equal(8u, draw.D[1]);
        Assert.Equal(0x3333_4444u, draw.D[2]);
        Assert.Equal(925, draw.Cycles);

        var ellipse = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 9, [1] = 10, [2] = 2, [3] = 2, [4] = 0x5555_6666u },
            Cycles = 927,
            ProgramCounter = 0x0012_3913
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaEllipse)),
            ellipse));
        Assert.Equal(nativeTarget, ellipse.ProgramCounter);
        Assert.Equal(9u, ellipse.D[0]);
        Assert.Equal(10u, ellipse.D[1]);
        Assert.Equal(2u, ellipse.D[2]);
        Assert.Equal(2u, ellipse.D[3]);
        Assert.Equal(0x5555_6666u, ellipse.D[4]);
        Assert.Equal(927, ellipse.Cycles);

        Assert.Equal(1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal(vectorTable + 4u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flagTable + 1u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)0, bus.ReadWord(vectorTable));
        Assert.Equal((ushort)0, bus.ReadWord(vectorTable + 2u));
        Assert.Equal((byte)1, bus.ReadByte(flagTable));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyAreaEndPlanesBeforeFillPublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_7200;
        const uint areaInfo = 0x00F0_7300;
        const uint vectorTable = 0x00F0_7400;
        const uint flagTable = 0x00F0_7500;
        const uint bitMap = 0x00F0_7600;
        const uint plane0 = 0x00F0_7700;
        const uint plane1 = 0x00F0_7800;
        const uint nativeTarget = 0x00FE_178B;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaEnd)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectorTable, new byte[16]);
        bus.MapWritableMemory(flagTable, new byte[4]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[16]);
        bus.MapWritableMemory(plane1, new byte[16]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, 0);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable, vectorTable);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectorTable + 12u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable, flagTable);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flagTable + 3u);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 3);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 0);
        bus.WriteWord(vectorTable, 0);
        bus.WriteWord(vectorTable + 2u, 0);
        bus.WriteWord(vectorTable + 4u, 15);
        bus.WriteWord(vectorTable + 6u, 0);
        bus.WriteWord(vectorTable + 8u, 15);
        bus.WriteWord(vectorTable + 10u, 7);
        bus.WriteByte(flagTable, 0, 0);
        bus.WriteByte(flagTable + 1u, 1, 0);
        bus.WriteByte(flagTable + 2u, 1, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        for (var offset = 0; offset < 16; offset++)
        {
            bus.WriteByte(plane0 + (uint)offset, (byte)(0x91 + offset), 0);
            bus.WriteByte(plane1 + (uint)offset, (byte)(0xA1 + offset), 0);
        }
        bus.MapReadOnlyMemory(
            plane0,
            Enumerable.Range(0, 16).Select(offset => (byte)(0x91 + offset)).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 929,
            ProgramCounter = 0x0012_3919
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AreaEnd)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(929, state.Cycles);
        Assert.Equal((ushort)3, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal(vectorTable + 12u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flagTable + 3u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        for (var offset = 0; offset < 16; offset++)
        {
            Assert.Equal((byte)(0x91 + offset), bus.ReadByte(plane0 + (uint)offset));
            Assert.Equal((byte)(0xA1 + offset), bus.ReadByte(plane1 + (uint)offset));
        }
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBlitRastPortPlanesBeforeBlitPublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_7900;
        const uint destinationBitMap = 0x00F0_7A00;
        const uint destinationPlane0 = 0x00F0_7B00;
        const uint destinationPlane1 = 0x00F0_7C00;
        const uint sourceBitMap = 0x00F0_7D00;
        const uint sourcePlane0 = 0x00F0_7E00;
        const uint sourcePlane1 = 0x00F0_7F00;
        const uint blitMask = 0x00F0_8000;
        const uint nativeTarget = 0x00FE_1791;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BltBitMapRastPort)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BltMaskBitMapRastPort)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(destinationBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(destinationPlane0, new byte[2]);
        bus.MapWritableMemory(destinationPlane1, new byte[2]);
        bus.MapWritableMemory(sourceBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(sourcePlane0, new byte[2]);
        bus.MapWritableMemory(sourcePlane1, new byte[2]);
        bus.MapWritableMemory(blitMask, new byte[2]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, destinationBitMap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        foreach (var bitmapAddress in new[] { destinationBitMap, sourceBitMap })
        {
            bus.WriteWord(bitmapAddress + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitmapAddress + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitmapAddress + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteByte(bitmapAddress + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        }
        bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes, destinationPlane0);
        bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, destinationPlane1);
        bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane0);
        bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, sourcePlane1);
        bus.WriteByte(destinationPlane0, 0x11, 0);
        bus.WriteByte(destinationPlane0 + 1u, 0x12, 0);
        bus.WriteByte(destinationPlane1, 0x21, 0);
        bus.WriteByte(destinationPlane1 + 1u, 0x22, 0);
        bus.WriteByte(sourcePlane0, 0x31, 0);
        bus.WriteByte(sourcePlane0 + 1u, 0x32, 0);
        bus.WriteByte(sourcePlane1, 0x41, 0);
        bus.WriteByte(sourcePlane1 + 1u, 0x42, 0);
        bus.WriteByte(blitMask, 0xFF, 0);
        bus.WriteByte(blitMask + 1u, 0xFF, 0);
        bus.MapReadOnlyMemory(destinationPlane0, new byte[] { 0x11, 0x12 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var blit = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = rastPort },
            D = { [0] = 2, [1] = 0, [2] = 0, [3] = 0, [4] = 16, [5] = 1, [6] = 0xF0, [7] = 0x1111_2222u },
            Cycles = 931,
            ProgramCounter = 0x0012_391F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BltBitMapRastPort)),
            blit));
        Assert.Equal(nativeTarget, blit.ProgramCounter);
        Assert.Equal(2u, blit.D[0]);
        Assert.Equal(0u, blit.D[1]);
        Assert.Equal(0u, blit.D[2]);
        Assert.Equal(0u, blit.D[3]);
        Assert.Equal(16u, blit.D[4]);
        Assert.Equal(1u, blit.D[5]);
        Assert.Equal(0xF0u, blit.D[6]);
        Assert.Equal(0x1111_2222u, blit.D[7]);
        Assert.Equal(931, blit.Cycles);

        var masked = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = rastPort, [2] = blitMask },
            D = { [0] = 2, [1] = 0, [2] = 0, [3] = 0, [4] = 16, [5] = 1, [6] = 0xF0, [7] = 0x3333_4444u },
            Cycles = 933,
            ProgramCounter = 0x0012_3925
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BltMaskBitMapRastPort)),
            masked));
        Assert.Equal(nativeTarget, masked.ProgramCounter);
        Assert.Equal(2u, masked.D[0]);
        Assert.Equal(0u, masked.D[1]);
        Assert.Equal(0u, masked.D[2]);
        Assert.Equal(0u, masked.D[3]);
        Assert.Equal(16u, masked.D[4]);
        Assert.Equal(1u, masked.D[5]);
        Assert.Equal(0xF0u, masked.D[6]);
        Assert.Equal(0x3333_4444u, masked.D[7]);
        Assert.Equal(933, masked.Cycles);

        Assert.Equal((byte)0x11, bus.ReadByte(destinationPlane0));
        Assert.Equal((byte)0x12, bus.ReadByte(destinationPlane0 + 1u));
        Assert.Equal((byte)0x21, bus.ReadByte(destinationPlane1));
        Assert.Equal((byte)0x22, bus.ReadByte(destinationPlane1 + 1u));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBltBitMapDestinationBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint sourceBitMap = 0x00F0_8100;
        const uint destinationBitMap = 0x00F0_8200;
        const uint sourcePlane0 = 0x00F0_8300;
        const uint sourcePlane1 = 0x00F0_8400;
        const uint destinationPlane0 = 0x00F0_8500;
        const uint destinationPlane1 = 0x00F0_8600;
        const uint nativeTarget = 0x00FE_1791;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BltBitMap)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(sourceBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(destinationBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(sourcePlane0, new byte[2]);
        bus.MapWritableMemory(sourcePlane1, new byte[2]);
        bus.MapWritableMemory(destinationPlane0, new byte[] { 0x11, 0x12 });
        bus.MapWritableMemory(destinationPlane1, new byte[] { 0x21, 0x22 });

        foreach (var bitMap in new[] { sourceBitMap, destinationBitMap })
        {
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        }
        bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane0);
        bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, sourcePlane1);
        bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes, destinationPlane0);
        bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, destinationPlane1);
        bus.WriteByte(sourcePlane0, 0x31, 0);
        bus.WriteByte(sourcePlane1, 0x41, 0);
        bus.MapReadOnlyMemory(destinationPlane0, new byte[] { 0x11, 0x12 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 16, [5] = 1, [6] = 0xCC, [7] = 0x03 },
            Cycles = 937,
            ProgramCounter = 0x0012_3931
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BltBitMap)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0u, state.D[1]);
        Assert.Equal(0u, state.D[2]);
        Assert.Equal(0u, state.D[3]);
        Assert.Equal(16u, state.D[4]);
        Assert.Equal(1u, state.D[5]);
        Assert.Equal(0xCCu, state.D[6]);
        Assert.Equal(0x03u, state.D[7]);
        Assert.Equal(937, state.Cycles);
        Assert.Equal((byte)0x11, bus.ReadByte(destinationPlane0));
        Assert.Equal((byte)0x12, bus.ReadByte(destinationPlane0 + 1u));
        Assert.Equal((byte)0x21, bus.ReadByte(destinationPlane1));
        Assert.Equal((byte)0x22, bus.ReadByte(destinationPlane1 + 1u));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyClipBlitDestinationBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
