        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(sourceRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(destinationRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(sourceBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(destinationBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(sourcePlane, new byte[] { 0xF0, 0x00 });
        bus.MapWritableMemory(destinationPlane, new byte[] { 0x11, 0x12 });

        foreach (var pair in new[]
                 {
                     (sourceRastPort, sourceBitMap),
                     (destinationRastPort, destinationBitMap)
                 })
        {
            bus.WriteLong(pair.Item1 + (uint)GraphicsLayouts.RastPortLayer, 0);
            bus.WriteLong(pair.Item1 + (uint)GraphicsLayouts.RastPortBitMap, pair.Item2);
            bus.WriteByte(pair.Item1 + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteWord(pair.Item2 + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(pair.Item2 + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(pair.Item2 + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteByte(pair.Item2 + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        }
        bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane);
        bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes, destinationPlane);
        bus.MapReadOnlyMemory(destinationPlane, new byte[] { 0x11, 0x12 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [0] = sourceRastPort, [1] = destinationRastPort },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 16, [5] = 1, [6] = 0xCC },
            Cycles = 941,
            ProgramCounter = 0x0012_3937
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClipBlit)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0u, state.D[1]);
        Assert.Equal(0u, state.D[2]);
        Assert.Equal(0u, state.D[3]);
        Assert.Equal(16u, state.D[4]);
        Assert.Equal(1u, state.D[5]);
        Assert.Equal(0xCCu, state.D[6]);
        Assert.Equal(0u, state.D[7]);
        Assert.Equal(941, state.Cycles);
        Assert.Equal((byte)0x11, bus.ReadByte(destinationPlane));
        Assert.Equal((byte)0x12, bus.ReadByte(destinationPlane + 1u));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyGetRpAttrsOutputsBeforeRastPortRead()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_2C00;
        const uint tags = 0x00F0_2D00;
        const uint result = 0x00F0_2E00;
        const uint nativeTarget = 0x00FE_1725;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRPAttrsA)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(tags, new byte[0x10]);
        bus.MapWritableMemory(result, new byte[4]);

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagAPen);
        bus.WriteLong(tags + 4u, result);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);
        bus.WriteLong(result, 0xDEAD_BEEFu);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        bus.MapReadOnlyMemory(
            result,
            new byte[] { 0xDE, 0xAD, 0xBE, 0xEF });

        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 839,
            ProgramCounter = 0x0012_386D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRPAttrsA)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(839, state.Cycles);
        Assert.Equal((byte)0xDE, bus.ReadByte(result));
        Assert.Equal((byte)0xAD, bus.ReadByte(result + 1u));
        Assert.Equal((byte)0xBE, bus.ReadByte(result + 2u));
        Assert.Equal((byte)0xEF, bus.ReadByte(result + 3u));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRestoreAlgoStyleWhenALaterFontTagFails()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint target = 0x00FA_F405;
        const uint rastPort = 0x100;
        const uint validFont = 0x200;
        const uint charData = 0x400;
        const uint tags = 0x500;
        const uint invalidFont = 0x1800;
        const byte originalStyle = 0x07;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            if (ReferenceEquals(bus, overlayBus))
            {
                WriteJmp(
                    image,
                    imageBase,
                    unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRPAttrsA)),
                    target);
            }

            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(validFont, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(charData, new byte[0x100]);
            bus.MapWritableMemory(tags, new byte[0x18]);

            bus.WriteWord(validFont + (uint)GraphicsLayouts.TextFontYSize, 8);
            bus.WriteWord(validFont + (uint)GraphicsLayouts.TextFontXSize, 8);
            bus.WriteWord(validFont + (uint)GraphicsLayouts.TextFontBaseline, 7);
            bus.WriteByte(validFont + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
            bus.WriteByte(validFont + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
            bus.WriteByte(validFont + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
            bus.WriteLong(validFont + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(validFont + (uint)GraphicsLayouts.TextFontModulo, 0x80);
            bus.WriteLong(validFont + (uint)GraphicsLayouts.TextFontCharLoc, 0);

            // The first RPTAG_Font mutates the complete font/cache/style
            // envelope; the later invalid font forces transactional rollback.
            bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagFont);
            bus.WriteLong(tags + 4, validFont);
            bus.WriteLong(tags + 8, GraphicsRastPortAttributeOperations.RptagFont);
            bus.WriteLong(tags + 12, invalidFont);
            bus.WriteLong(tags + 16, GraphicsRastPortAttributeOperations.TagDone);
            bus.WriteLong(tags + 20, 0);

            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0x500);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, originalStyle, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 11);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth, 12);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 13);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 197
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 197,
            ProgramCounter = 0x0012_3805
        };

        direct.Invoke(directState, (int)GraphicsLvo.SetRPAttrsA);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRPAttrsA));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        // A failed portable claim preserves the caller registers.  The
        // mapped resident vector must additionally tail-chain to its target.
        Assert.Equal(0xCAFE_BABEu, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(197, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(target, overlayState.ProgramCounter);

        for (var index = 0; index < GraphicsLayouts.RastPortMinimumSize; index++)
            Assert.Equal(directBus.ReadByte(rastPort + (uint)index), overlayBus.ReadByte(rastPort + (uint)index));
        Assert.Equal(0x500u, directBus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal(originalStyle, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)11, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)12, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)13, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRejectOddRastPortAttributeBases()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint setTarget = 0x00FA_F406;
        const uint getTarget = 0x00FA_F407;
        const uint oddRastPort = 0x101;
        const uint setTags = 0x500;
        const uint getTags = 0x520;
        const uint result = 0x600;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            if (ReferenceEquals(bus, overlayBus))
            {
                WriteJmp(
                    image,
                    imageBase,
                    unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRPAttrsA)),
                    setTarget);
                WriteJmp(
                    image,
                    imageBase,
                    unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetRPAttrsA)),
                    getTarget);
            }

            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(oddRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(setTags, new byte[0x10]);
            bus.MapWritableMemory(getTags, new byte[0x10]);
            bus.MapWritableMemory(result, new byte[4]);
            for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
                bus.WriteByte(oddRastPort + (uint)offset, 0xA5, 0);

            bus.WriteLong(setTags, GraphicsRastPortAttributeOperations.RptagAPen);
            bus.WriteLong(setTags + 4, 7);
            bus.WriteLong(setTags + 8, GraphicsRastPortAttributeOperations.TagDone);
            bus.WriteLong(setTags + 12, 0);
            bus.WriteLong(getTags, GraphicsRastPortAttributeOperations.RptagAPen);
            bus.WriteLong(getTags + 4, result);
            bus.WriteLong(getTags + 8, GraphicsRastPortAttributeOperations.TagDone);
            bus.WriteLong(getTags + 12, 0);
            bus.WriteLong(result, 0xDEAD_BEEFu);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directSet = new M68kCpuState
        {
            A = { [0] = setTags, [1] = oddRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 199
        };
        var overlaySet = new M68kCpuState
        {
            A = { [0] = setTags, [1] = oddRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 199,
            ProgramCounter = 0x0012_3806
        };
        direct.Invoke(directSet, (int)GraphicsLvo.SetRPAttrsA);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRPAttrsA)),
            overlaySet));
        Assert.Equal(0xCAFE_BABEu, directSet.D[0]);
        Assert.Equal(directSet.D[0], overlaySet.D[0]);
        Assert.Equal(199, directSet.Cycles);
        Assert.Equal(directSet.Cycles, overlaySet.Cycles);
        Assert.Equal(setTarget, overlaySet.ProgramCounter);

        var directGet = new M68kCpuState
        {
            A = { [0] = getTags, [1] = oddRastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 201
        };
        var overlayGet = new M68kCpuState
        {
            A = { [0] = getTags, [1] = oddRastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 201,
            ProgramCounter = 0x0012_3807
        };
        direct.Invoke(directGet, (int)GraphicsLvo.GetRPAttrsA);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetRPAttrsA)),
            overlayGet));
        Assert.Equal(0x1234_5678u, directGet.D[0]);
        Assert.Equal(directGet.D[0], overlayGet.D[0]);
        Assert.Equal(201, directGet.Cycles);
        Assert.Equal(directGet.Cycles, overlayGet.Cycles);
        Assert.Equal(getTarget, overlayGet.ProgramCounter);

        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
        {
            Assert.Equal((byte)0xA5, directBus.ReadByte(oddRastPort + (uint)offset));
            Assert.Equal(
                directBus.ReadByte(oddRastPort + (uint)offset),
                overlayBus.ReadByte(oddRastPort + (uint)offset));
        }
        Assert.Equal(0xDEAD_BEEFu, directBus.ReadLong(result));
        Assert.Equal(directBus.ReadLong(result), overlayBus.ReadLong(result));
    }

    [Fact]
    public void SetFontNullSelectsTheGuestDefaultFont()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint rastPort = 0x100;
        const uint font = 0x600;
        const uint name = 0x500;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var core = CreateCore(memory);

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "default.font");
        Assert.True(list.Initialize(0));
        Assert.True(list.SetDefaultFont(font));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            0x07));

        var adapter = new CopperStartGraphicsRegisterAdapter(core, fontList: list);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 77
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(77, state.Cycles);
        Assert.Equal(font, ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)9,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)8,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)7,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal((byte)0,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
    }

    [Fact]
    public void DirectSetFontNullSelectsTheFontBackendDefault()
    {
        var memory = new FakeMemory(0x1000);
        const uint rastPort = 0x100;
        const uint defaultFont = 0x300;
        var core = CreateCore(memory);
        var fonts = new DefaultFontBackend(defaultFont);

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.Equal(0, core.SetFont(rastPort, 0, fonts));
        Assert.Equal(defaultFont, ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)9, ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)8, ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)7, ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void NativeOverlaySetFontNullRequiresGuestFontList()
    {
        var memory = new FakeMemory(0x1000);
        const uint font = 0x300;
        WriteFontHeader(memory, font, 0, ySize: 8, style: 0, flags: 1);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            ensureCompatibilityFont: () => font);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0x20 },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 79
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont, nativeOverlay: true));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(79, state.Cycles);
    }

    [Fact]
    public void RomOverlayTailChainsMalformedSetFontToOriginalVector()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint invalidFont = 0x00F0_0000;
        const uint target = 0x00FA_F404;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetFont)), target);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = invalidFont, [1] = 0x00F0_1000u },
            D = { [0] = 0x1234_5678u },
            Cycles = 193,
            ProgramCounter = 0x0012_3804
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetFont)),
            state));
        Assert.Equal(target, state.ProgramCounter);
        Assert.Equal(0x1234_5678u, state.D[0]);
        Assert.Equal(193, state.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveProportionalTextParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint font = 0x600;
        const uint charData = 0x900;
        const uint text = 0xB00;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(charData, new byte[0x100]);
            bus.MapWritableMemory(text, new byte[0x20]);
            bus.MapWritableMemory(plane, new byte[0x100]);
        }

        static void WriteProportionalTextFixture(AmigaBus bus)
        {
            const uint rastPort = 0x100;
            const uint bitMap = 0x200;
            const uint font = 0x600;
            const uint charData = 0x900;
            const uint charLoc = 0x920;
            const uint charSpace = 0x930;
            const uint charKern = 0x940;
            const uint text = 0xB00;
            const uint plane = 0x1000;

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 2);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);

            bus.WriteWord(charLoc, 0);
            bus.WriteWord(charLoc + 2, 4);
            bus.WriteWord(charLoc + 4, 0);
            bus.WriteWord(charLoc + 6, 4);
            bus.WriteWord(charSpace, 6);
            bus.WriteWord(charSpace + 2, 6);
            bus.WriteWord(charKern, 0);
            bus.WriteWord(charKern + 2, 0);
            bus.WriteByte(charData, 0x54, 0);
            bus.WriteByte(charData + 1, 0, 0);
            bus.WriteByte(charData + 2, 0x70, 0);
            bus.WriteByte(charData + 3, 0, 0);
            bus.WriteByte(charData + 4, 0x28, 0);
            bus.WriteByte(charData + 5, 0, 0);
            bus.WriteByte(charData + 6, 0x40, 0);
            bus.WriteByte(charData + 7, 0, 0);
            bus.WriteByte(text, (byte)'A', 0);

            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 3);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 3);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);
        }

        WriteProportionalTextFixture(directBus);
        WriteProportionalTextFixture(overlayBus);

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 23
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 23
        };

        direct.Invoke(directState, (int)GraphicsLvo.Text);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Text));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((ushort)7, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)7, overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            GraphicsLayouts.RastPortFirstDot,
            directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
            GraphicsLayouts.RastPortFirstDot);
        Assert.Equal(
            directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags),
            overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            (byte)15,
            directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount),
            overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A's bit-packed strike uses a proportional four-bit cell, while
        // JAM1 clears the complete four-row text envelope.
        var expectedPlane = new byte[] { 0x50, 0x70, 0x20, 0x40 };
        for (var row = 0; row < expectedPlane.Length; row++)
        {
            Assert.Equal(expectedPlane[row], directBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(expectedPlane[row], overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(0, directBus.ReadByte(plane + (uint)row * 2 + 1));
            Assert.Equal(0, overlayBus.ReadByte(plane + (uint)row * 2 + 1));
        }

    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarDrawParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 3 },
            Cycles = 41
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 3 },
            Cycles = 41
        };

        direct.Invoke(directState, (int)GraphicsLvo.Draw);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Draw));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((ushort)3, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((ushort)3, overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal(0, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)12, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)12, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        var expectedPlane = new byte[] { 0x80, 0x40, 0x20, 0x10 };
        for (var row = 0; row < expectedPlane.Length; row++)
        {
            Assert.Equal(expectedPlane[row], directBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(expectedPlane[row], overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(0, directBus.ReadByte(plane + (uint)row * 2 + 1));
            Assert.Equal(0, overlayBus.ReadByte(plane + (uint)row * 2 + 1));
        }

        // Exercise the bitmap clip boundary through the same direct and ROM
        // overlay gateways. Both paths must ignore x=-1 while preserving
        // the requested endpoint and line-pattern phase.
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.WriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
                unchecked((ushort)-1));
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                15,
                0);
            bus.WriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                GraphicsLayouts.RastPortFirstDot);
        }

        directState.D[0] = 1;
        directState.D[1] = 0;
        overlayState.D[0] = 1;
        overlayState.D[1] = 0;
        directState.Cycles = 67;
        overlayState.Cycles = 67;
        direct.Invoke(directState, (int)GraphicsLvo.Draw);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((ushort)1, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var row = 0; row < expectedPlane.Length; row++)
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
    }

    [Fact]
    public void AddressZeroRastPortRemainsNativeOwnedAcrossDirectAndRomOverlayDrawing()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint sentinel = 0xCAFE_BABEu;
        const long cycle = 137;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            // Host memory can expose byte zero, but a native 68000 RastPort
            // call with A1 == NULL must remain available to the resident
            // vector rather than treating low memory as a valid object.
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(0, new byte[GraphicsLayouts.RastPortMinimumSize]);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directDraw = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = sentinel, [1] = 1 },
            Cycles = cycle
        };
        direct.Invoke(directDraw, (int)GraphicsLvo.Draw);
        Assert.Equal(sentinel, directDraw.D[0]);
        Assert.Equal(cycle, directDraw.Cycles);

        var overlayDraw = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = sentinel, [1] = 1 },
            Cycles = cycle
        };
        var drawAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Draw));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(drawAddress, overlayDraw));
        Assert.Equal(sentinel, overlayDraw.D[0]);
        Assert.Equal(cycle, overlayDraw.Cycles);

        var directRead = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = sentinel, [1] = 1 },
            Cycles = cycle + 1
        };
        direct.Invoke(directRead, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(sentinel, directRead.D[0]);
        Assert.Equal(cycle + 1, directRead.Cycles);

        var overlayRead = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = sentinel, [1] = 1 },
            Cycles = cycle + 1
        };
        var readAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ReadPixel));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(readAddress, overlayRead));
        Assert.Equal(sentinel, overlayRead.D[0]);
        Assert.Equal(cycle + 1, overlayRead.Cycles);

        var directWrite = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = sentinel, [1] = 1 },
            Cycles = cycle + 2
        };
        direct.Invoke(directWrite, (int)GraphicsLvo.WritePixel);
        Assert.Equal(sentinel, directWrite.D[0]);
        Assert.Equal(cycle + 2, directWrite.Cycles);

        var overlayWrite = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = sentinel, [1] = 1 },
            Cycles = cycle + 2
        };
        var writeAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixel));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(writeAddress, overlayWrite));
        Assert.Equal(sentinel, overlayWrite.D[0]);
        Assert.Equal(cycle + 2, overlayWrite.Cycles);

        var directText = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0 },
            D = { [0] = sentinel },
            Cycles = cycle + 1
        };
        direct.Invoke(directText, (int)GraphicsLvo.Text);
        Assert.Equal(sentinel, directText.D[0]);
        Assert.Equal(cycle + 1, directText.Cycles);

        var overlayText = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0 },
            D = { [0] = sentinel },
            Cycles = cycle + 1
        };
        var textAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Text));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(textAddress, overlayText));
        Assert.Equal(sentinel, overlayText.D[0]);
        Assert.Equal(cycle + 1, overlayText.Cycles);
    }

    [Fact]
    public void PolyDrawPointTableAlignmentRemainsNativeOwnedAcrossDirectAndRomOverlay()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;
        const uint sentinel = 0xA5A5_5A5Au;
        const long cycle = 149;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(0, new byte[0x100]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(0x300, new byte[0x10]);
            bus.MapWritableMemory(plane, new byte[0x40]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteWord(0, 2);
            bus.WriteWord(2, 2);
            bus.WriteWord(0x300, 2);
            bus.WriteByte(0x301, 0, 0);
            bus.WriteByte(0x302, 2, 0);
            bus.WriteByte(0x303, 2, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        foreach (var points in new[] { 0u, 0x301u })
        {
            var directState = new M68kCpuState
            {
                A = { [0] = points, [1] = rastPort },
                D = { [0] = sentinel, [1] = 0 },
                Cycles = cycle
            };
            direct.Invoke(directState, (int)GraphicsLvo.PolyDraw);

            var overlayState = new M68kCpuState
            {
                A = { [0] = points, [1] = rastPort },
                D = { [0] = sentinel, [1] = 0 },
                Cycles = cycle
            };
            var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.PolyDraw));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

            Assert.Equal(sentinel, directState.D[0]);
            Assert.Equal(sentinel, overlayState.D[0]);
            Assert.Equal(cycle, directState.Cycles);
            Assert.Equal(cycle, overlayState.Cycles);
            Assert.Equal(0, directBus.ReadByte(plane));
            Assert.Equal(0, overlayBus.ReadByte(plane));
        }
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarPixelParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane0 = 0x1000;
        const uint plane1 = 0x1200;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane0, new byte[0x20]);
            bus.MapWritableMemory(plane1, new byte[0x20]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);

            // Seed colour 3 at (0,0) and colour 2 at (8,1), then exercise a
            // write at (3,1) through the same guest ABI on both paths.
            bus.WriteByte(plane0, 0x80, 0);
            bus.WriteByte(plane1, 0x80, 0);
            bus.WriteByte(plane1 + 2, 0x80, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        uint InvokeBoth(GraphicsLvo vector, M68kCpuState directState, M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            return directState.D[0];
        }

        Assert.Equal(3u, InvokeBoth(
            GraphicsLvo.ReadPixel,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0, [1] = 0 }, Cycles = 47 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0, [1] = 0 }, Cycles = 47 }));

        Assert.Equal(0u, InvokeBoth(
            GraphicsLvo.WritePixel,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 3, [1] = 1 }, Cycles = 53 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 3, [1] = 1 }, Cycles = 53 }));
        Assert.Equal(0x10, directBus.ReadByte(plane0 + 2) & 0x10);
        Assert.Equal(0x10, overlayBus.ReadByte(plane0 + 2) & 0x10);
        Assert.Equal(0, directBus.ReadByte(plane1 + 2) & 0x10);
        Assert.Equal(0, overlayBus.ReadByte(plane1 + 2) & 0x10);

        Assert.Equal(1u, InvokeBoth(
            GraphicsLvo.ReadPixel,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 3, [1] = 1 }, Cycles = 59 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 3, [1] = 1 }, Cycles = 59 }));

        // The direct and mapped paths must make the same one-cell minterm
        // decision for every classic drawing-mode combination.  Write the
        // mode field directly here so this differential fixture isolates the
        // WritePixel selection boundary from SetDrMd's line-phase update.
        foreach (var (mode, seed, expected) in new[]
                 {
                     ((byte)0, (byte)0x00, 1),
                     ((byte)1, (byte)0x00, 1),
                     ((byte)2, (byte)0x00, 3),
                     ((byte)3, (byte)0x00, 3),
                     ((byte)4, (byte)0xC0, 3),
                     ((byte)5, (byte)0xC0, 2),
                     ((byte)6, (byte)0xC0, 3),
                     ((byte)7, (byte)0xC0, 3)
                 })
        {
            foreach (var bus in new[] { directBus, overlayBus })
            {
                bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, mode, 0);
                bus.WriteByte(plane0, seed, 0);
                bus.WriteByte(plane1, seed, 0);
            }

            Assert.Equal(0u, InvokeBoth(
                GraphicsLvo.WritePixel,
                new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0, [1] = 0 }, Cycles = 63 },
                new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0, [1] = 0 }, Cycles = 63 }));

            var directPixel = ((directBus.ReadByte(plane0) & 0x80) != 0 ? 1 : 0) |
                ((directBus.ReadByte(plane1) & 0x80) != 0 ? 2 : 0);
            var overlayPixel = ((overlayBus.ReadByte(plane0) & 0x80) != 0 ? 1 : 0) |
                ((overlayBus.ReadByte(plane1) & 0x80) != 0 ? 2 : 0);
            Assert.Equal(expected, directPixel);
            Assert.Equal(directPixel, overlayPixel);
        }

        // ReadPixel and WritePixel retain their documented -1 failure result
        // for coordinates outside the RastPort without changing the planes.
        Assert.Equal(0xFFFF_FFFFu, InvokeBoth(
            GraphicsLvo.WritePixel,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = unchecked((uint)(short)-1), [1] = 1 }, Cycles = 61 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = unchecked((uint)(short)-1), [1] = 1 }, Cycles = 61 }));
        Assert.Equal(0x10, directBus.ReadByte(plane0 + 2) & 0x10);
        Assert.Equal(0x10, overlayBus.ReadByte(plane0 + 2) & 0x10);

        for (var row = 0; row < 4; row++)
        {
            Assert.Equal(directBus.ReadByte(plane0 + (uint)row), overlayBus.ReadByte(plane0 + (uint)row));
            Assert.Equal(directBus.ReadByte(plane1 + (uint)row), overlayBus.ReadByte(plane1 + (uint)row));
        }
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarPolyDrawParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint points = 0x3000;
        const uint plane = 0x0080_0000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(points, new byte[12]);
            bus.MapWritableMemory(plane, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteWord(points, 1);
            bus.WriteWord(points + 2, 6);
            bus.WriteWord(points + 4, 6);
            bus.WriteWord(points + 6, 6);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeBoth(GraphicsLvo vector, M68kCpuState directState, M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        InvokeBoth(
            GraphicsLvo.InitRastPort,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu }, Cycles = 7 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu }, Cycles = 7 });

        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        }

        InvokeBoth(
            GraphicsLvo.Move,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 1, [1] = 1 }, Cycles = 17 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 1, [1] = 1 }, Cycles = 17 });
        InvokeBoth(
            GraphicsLvo.PolyDraw,
            new M68kCpuState
            {
                A = { [0] = points, [1] = rastPort },
                D = { [0] = 2, [1] = 0xDEAD_BEEFu },
                Cycles = 23
            },
            new M68kCpuState
            {
                A = { [0] = points, [1] = rastPort },
                D = { [0] = 2, [1] = 0xDEAD_BEEFu },
                Cycles = 23
            });

        Assert.Equal((short)6, unchecked((short)directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)6, unchecked((short)overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)6, unchecked((short)directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((short)6, unchecked((short)overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));

        for (var offset = 0; offset < 0x100; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(plane + (uint)offset),
                overlayBus.ReadByte(plane + (uint)offset));
        }

        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 2 * 2));
        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 6 * 2));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarRectFillParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 1, [2] = 3, [3] = 2 },
            Cycles = 53
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 1, [2] = 3, [3] = 2 },
            Cycles = 53
        };

        direct.Invoke(directState, (int)GraphicsLvo.RectFill);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.RectFill));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);

        var expectedPlane = new byte[] { 0x00, 0x70, 0x70, 0x00 };
        for (var row = 0; row < expectedPlane.Length; row++)
        {
            Assert.Equal(expectedPlane[row], directBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(expectedPlane[row], overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(0, directBus.ReadByte(plane + (uint)row * 2 + 1));
            Assert.Equal(0, overlayBus.ReadByte(plane + (uint)row * 2 + 1));
        }

        // RectFill is a void no-op for an inverted rectangle. Exercise the
        // same call through the direct and mapped native-overlay paths and
        // prove that the already-published pixels and ABI state remain
        // unchanged.
        var directNoOp = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 2, [2] = 2, [3] = 3 },
            Cycles = 71
        };
        var overlayNoOp = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 2, [2] = 2, [3] = 3 },
            Cycles = 71
        };

        direct.Invoke(directNoOp, (int)GraphicsLvo.RectFill);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayNoOp));
        Assert.Equal(0u, directNoOp.D[0]);
        Assert.Equal(directNoOp.D[0], overlayNoOp.D[0]);
        Assert.Equal(directNoOp.Cycles, overlayNoOp.Cycles);
        for (var row = 0; row < expectedPlane.Length; row++)
        {
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
        }
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveMaskedMultiPlaneRectFillParity()
    {
        const uint imageBase = 0x00FA_F000;
        const uint graphicsBase = 0x00FB_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane0 = 0x1000;
        const uint plane1 = 0x1100;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane0, new byte[0x100]);
            bus.MapWritableMemory(plane1, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
            // SetABPenDrMd's JAM1 cache for FgPen=1/BPen=0. The native arm
            // admits this ordinary JAM1 form directly, while the portable
            // direct path evaluates the same cached minterms.
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + 0u, 0xEA, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + 1u, 0x2A, 0);
            bus.WriteByte(plane0 + 1u, 0x00, 0);
            bus.WriteByte(plane0 + 3u, 0x00, 0);
            bus.WriteByte(plane1 + 1u, 0x5A, 0);
            bus.WriteByte(plane1 + 3u, 0x5A, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 8, [1] = 0, [2] = 15, [3] = 1 },
            Cycles = 89
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 8, [1] = 0, [2] = 15, [3] = 1 },
            Cycles = 89
        };

        direct.Invoke(directState, (int)GraphicsLvo.RectFill);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.RectFill));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        for (var row = 0; row < 2; row++)
        {
            var offset = (uint)(row * 2 + 1);
            Assert.Equal((byte)0xFF, directBus.ReadByte(plane0 + offset));
            Assert.Equal((byte)0xFF, overlayBus.ReadByte(plane0 + offset));
            Assert.Equal((byte)0x5A, directBus.ReadByte(plane1 + offset));
            Assert.Equal((byte)0x5A, overlayBus.ReadByte(plane1 + offset));
        }
    }

    [Fact]
    public void NativeGraphicsRasterBodiesExecuteMaskedMultiPlaneEraseRect()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint rastPort = 0x00D0_0000;
        const uint bitMap = 0x00E0_0000;
        const uint plane0 = 0x00E1_0000;
        const uint plane1 = 0x00E2_0000;
        const uint stack = 0x00C0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[0x100]);
        bus.MapWritableMemory(plane1, new byte[0x100]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 0, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteByte(plane0 + 5u, 0x00, 0);
        bus.WriteByte(plane1 + 5u, 0x5A, 0);
        bus.WriteLong(stack + 0x80u, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(short xMin, short y, short xMax, uint initialD0, uint rp = rastPort)
        {
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.EraseRect],
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0 | unchecked((ushort)xMin);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.State.D[2] = unchecked((ushort)xMax);
            cpu.State.D[3] = unchecked((ushort)y);
            for (var index = 0; index < 100_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native masked EraseRect body did not return.");
        }

        Execute(8, 1, 15, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane1 + 5u));
        Assert.Equal((byte)0, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The multipane owner repeats the public RastPort admission after the
        // dispatch. A complete exact-end header must reach its selected-plane
        // publication through AccurateM68000's physical alias.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 0, 0);
        bus.WriteByte(plane0 + 5u, 0, 0);
        Execute(8, 1, 15, 0xFACE_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(plane0 + 5u, 0xA5, 0);
        bus.WriteByte(plane1 + 5u, 0x5A, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2, 0);
        Execute(8, 1, 15, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane1 + 5u));

        // An unselected plane may be absent without turning the selected
        // mask-one operation into a partial publication.
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(plane0 + 5u, 0x00, 0);
        Execute(8, 1, 15, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 5u));

        // Unsupported unaligned geometry remains available to the fallback
        // owner and preserves the caller's full D0 value.
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteByte(plane0 + 5u, 0x11, 0);
        Execute(9, 1, 16, 0xABCD_0000u);
        Assert.Equal(0xABCD_0009u, cpu.State.D[0]);
        Assert.Equal((byte)0x11, bus.ReadByte(plane0 + 5u));

    }

    [Fact]
    public void NativeGraphicsRasterBodiesExecuteMaskedMultiPlaneEraseRectTwoRows()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint rastPort = 0x00D0_0000;
        const uint bitMap = 0x00E0_0000;
        const uint plane0 = 0x00E1_0000;
        const uint plane1 = 0x00E2_0000;
        const uint stack = 0x00C0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[0x100]);
        bus.MapWritableMemory(plane1, new byte[0x100]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 0, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);

        foreach (var plane in new[] { plane0, plane1 })
        {
            bus.WriteByte(plane + 1u, 0x11, 0);
            bus.WriteByte(plane + 5u, 0x22, 0);
            bus.WriteByte(plane + 9u, 0x33, 0);
            bus.WriteByte(plane + 13u, 0x44, 0);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(short xMin, short yMin, short xMax, short yMax, uint initialD0)
        {
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.EraseRect],
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)xMin);
            cpu.State.D[1] = unchecked((ushort)yMin);
            cpu.State.D[2] = unchecked((ushort)xMax);
            cpu.State.D[3] = unchecked((ushort)yMax);
            for (var index = 0; index < 100_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native two-row masked EraseRect body did not return.");
        }

        // Mask-one publishes both rows only on plane zero and preserves every
        // row guard plus the unselected plane.
        Execute(8, 1, 15, 2, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x11, bus.ReadByte(plane0 + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 9u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane0 + 13u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane1 + 5u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane1 + 9u));
        Assert.Equal((byte)0, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Mask-three clears plane zero and fills plane one from BPen bit one.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2, 0);
        Execute(8, 1, 15, 2, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane0 + 9u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane1 + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane1 + 9u));

        // The two-row envelope is transactional when the bottom row is out
        // of range; neither row may be partially changed.
        bus.WriteByte(plane0 + 5u, 0x5A, 0);
        bus.WriteByte(plane0 + 9u, 0x6B, 0);
        Execute(8, 2, 15, 4, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0x6B, bus.ReadByte(plane0 + 9u));
    }

    [Fact]
    public void NativeGraphicsRasterBodiesExecuteMaskedMultiPlaneEraseRectThreeRows()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint rastPort = 0x00D0_0000;
        const uint bitMap = 0x00E0_0000;
        const uint plane0 = 0x00E1_0000;
        const uint plane1 = 0x00E2_0000;
        const uint plane7 = 0x00E7_0000;
        const uint stack = 0x00C0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[0x100]);
        bus.MapWritableMemory(plane1, new byte[0x100]);
        bus.MapWritableMemory(plane7, new byte[0x100]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 9, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 28u, plane7);

        foreach (var plane in new[] { plane0, plane1 })
        {
            bus.WriteByte(plane + 1u, 0x11, 0);
            bus.WriteByte(plane + 5u, 0x22, 0);
            bus.WriteByte(plane + 9u, 0x33, 0);
            bus.WriteByte(plane + 13u, 0x44, 0);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(short xMin, short yMin, short xMax, short yMax, uint initialD0)
        {
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.EraseRect],
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)xMin);
            cpu.State.D[1] = unchecked((ushort)yMin);
            cpu.State.D[2] = unchecked((ushort)xMax);
            cpu.State.D[3] = unchecked((ushort)yMax);
            for (var index = 0; index < 100_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native three-row masked EraseRect body did not return.");
        }

        Execute(8, 0, 15, 2, 0xAA55_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane0 + 9u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane0 + 13u));
        Assert.Equal((byte)0x11, bus.ReadByte(plane1 + 1u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane1 + 5u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane1 + 9u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane1 + 13u));
        Assert.Equal((byte)9, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The same row loop must remain valid at the top of the depth range;
        // a high mask bit selects only plane seven and does not require the
        // intervening unselected plane links.
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x80, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0x80, 0);
        foreach (var offset in new[] { 1u, 5u, 9u, 13u })
            bus.WriteByte(plane7 + offset, 0x22, 0);
        Execute(8, 0, 15, 2, 0x55AA_0008u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane7 + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane7 + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane7 + 9u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane7 + 13u));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarSetRastParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, Enumerable.Repeat((byte)0xAA, 0x100).ToArray());

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 67
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 67
        };

        direct.Invoke(directState, (int)GraphicsLvo.SetRast);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRast));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);

        for (var row = 0; row < 4; row++)
        {
            for (var column = 0; column < 2; column++)
            {
                var offset = (uint)(row * 2 + column);
                Assert.Equal((byte)0xFF, directBus.ReadByte(plane + offset));
                Assert.Equal((byte)0xFF, overlayBus.ReadByte(plane + offset));
                Assert.Equal(directBus.ReadByte(plane + offset), overlayBus.ReadByte(plane + offset));
            }
        }
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarClearParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);
            for (var offset = 0; offset < 0x100; offset++)
                bus.WriteByte(plane + (uint)offset, 0xFF, 0);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 3);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 3);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 1);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeBoth(GraphicsLvo vector)
        {
            var directState = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 79
            };
            var overlayState = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 79
            };

            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
            for (var offset = 0; offset < 8; offset++)
            {
                Assert.Equal(
                    directBus.ReadByte(plane + (uint)offset),
                    overlayBus.ReadByte(plane + (uint)offset));
            }
        }

        Assert.Equal((ushort)2, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((ushort)3, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal((ushort)1, directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((byte)0xFF, directBus.ReadByte(plane));
        InvokeBoth(GraphicsLvo.ClearEOL);
        Assert.Equal((byte)15, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)15, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)0xC0, directBus.ReadByte(plane));
        Assert.Equal((byte)0x00, directBus.ReadByte(plane + 1));
        for (var offset = 2; offset < 8; offset++)
            Assert.Equal((byte)0xFF, directBus.ReadByte(plane + (uint)offset));

        directBus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        overlayBus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        InvokeBoth(GraphicsLvo.ClearScreen);
        Assert.Equal((byte)15, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)15, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)0xC0, directBus.ReadByte(plane));
        Assert.Equal((byte)0x00, directBus.ReadByte(plane + 1));
        for (var offset = 2; offset < 8; offset++)
            Assert.Equal((byte)0x00, directBus.ReadByte(plane + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarEraseRectParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);
            for (var offset = 0; offset < 0x100; offset++)
                bus.WriteByte(plane + (uint)offset, 0xFF, 0);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 1, [2] = 3, [3] = 2 },
            Cycles = 89
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 1, [2] = 3, [3] = 2 },
            Cycles = 89
        };

        direct.Invoke(directState, (int)GraphicsLvo.EraseRect);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.EraseRect));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((byte)4, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)4, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // EraseRect clears the inclusive rectangle through the current
        // background pen.  Both fixtures start with BPen zero, so the three
        // selected pixels occupy bits 6..4 in rows one and two of the
        // little-endian planar fixture.
        var expectedPlane = new byte[] { 0xFF, 0x8F, 0x8F, 0xFF };
        for (var row = 0; row < expectedPlane.Length; row++)
        {
            Assert.Equal(expectedPlane[row], directBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(expectedPlane[row], overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(0xFF, directBus.ReadByte(plane + (uint)row * 2 + 1));
            Assert.Equal(0xFF, overlayBus.ReadByte(plane + (uint)row * 2 + 1));
        }

        var directNoOp = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 2, [2] = 2, [3] = 3 },
            Cycles = 101
        };
        var overlayNoOp = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 2, [2] = 2, [3] = 3 },
            Cycles = 101
        };

        // Reversed EraseRect bounds are empty geometry and must not alter the
        // pixels or line state already published by the valid erase.
        direct.Invoke(directNoOp, (int)GraphicsLvo.EraseRect);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayNoOp));
        Assert.Equal(0u, directNoOp.D[0]);
        Assert.Equal(directNoOp.D[0], overlayNoOp.D[0]);
        Assert.Equal(directNoOp.Cycles, overlayNoOp.Cycles);
        for (var row = 0; row < expectedPlane.Length; row++)
        {
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
        }
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarDrawEllipseParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 4, [1] = 4, [2] = 2, [3] = 2 },
            Cycles = 101
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 4, [1] = 4, [2] = 2, [3] = 2 },
            Cycles = 101
        };

        direct.Invoke(directState, (int)GraphicsLvo.DrawEllipse);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.DrawEllipse));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);

        // The midpoint outline is compared byte-for-byte, with cardinal
        // points called out so the fixture also guards the guest bit order.
        for (var row = 0; row < 8; row++)
        {
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(0, directBus.ReadByte(plane + (uint)row * 2 + 1));
            Assert.Equal(0, overlayBus.ReadByte(plane + (uint)row * 2 + 1));
        }

        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 2 * 2));
        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 6 * 2));
        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 4 * 2));

    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarScrollRasterParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);
            bus.WriteByte(plane, 0x81, 0);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 7, [5] = 0 },
            Cycles = 127
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 7, [5] = 0 },
            Cycles = 127
        };

        direct.Invoke(directState, (int)GraphicsLvo.ScrollRaster);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ScrollRaster));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((byte)15, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)15, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // +1 scrolls the source toward the origin.  The old rightmost pixel
        // and the BPen-filled vacated pixel occupy the two low bits.
        Assert.Equal((byte)0x03, directBus.ReadByte(plane));
        Assert.Equal((byte)0x03, overlayBus.ReadByte(plane));
        Assert.Equal(directBus.ReadByte(plane), overlayBus.ReadByte(plane));

        var directNoOp = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 3, [3] = 0, [4] = 2, [5] = 0 },
            Cycles = 149
        };
        var overlayNoOp = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 3, [3] = 0, [4] = 2, [5] = 0 },
            Cycles = 149
        };

        // Reversed bounds are an empty void operation and must not alter the
        // already-scrolled pixels or the line-state fields.
        direct.Invoke(directNoOp, (int)GraphicsLvo.ScrollRaster);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayNoOp));
        Assert.Equal(0u, directNoOp.D[0]);
        Assert.Equal(directNoOp.D[0], overlayNoOp.D[0]);
        Assert.Equal(directNoOp.Cycles, overlayNoOp.Cycles);
        Assert.Equal((byte)0x03, directBus.ReadByte(plane));
        Assert.Equal((byte)0x03, overlayBus.ReadByte(plane));
        Assert.Equal(
            directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount),
            overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

