    [Fact]
    public void NativeOverlayAndHostGatewayPreserveFullDisplacementScrollRasterParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint plane = 0x1000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);
            bus.WriteByte(plane, 0x81, 0);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 8, [1] = 0, [2] = 0, [3] = 0, [4] = 7, [5] = 0 },
            Cycles = 137
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 8, [1] = 0, [2] = 0, [3] = 0, [4] = 7, [5] = 0 },
            Cycles = 137
        };

        direct.Invoke(directState, (int)GraphicsLvo.ScrollRaster);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ScrollRaster));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        // A displacement equal to the logical width leaves ScrollRaster
        // untouched. The native overlay must preserve that no-op, including
        // the caller's line-pattern phase, while still normalizing the void
        // vector's success D0 and retaining the original cycle count.
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((byte)4, directBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)4, overlayBus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(directBus.ReadByte(plane), overlayBus.ReadByte(plane));
        Assert.Equal((byte)0x81, directBus.ReadByte(plane));
        Assert.Equal((byte)0x81, overlayBus.ReadByte(plane));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePlanarAreaPolygonParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint areaInfo = 0x1400;
        const uint areaStorage = 0x1500;
        const uint areaPattern = 0x1600;
        const uint temporaryRaster = 0x0070_0000;
        const uint plane = 0x0080_0000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);
            bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
            bus.MapWritableMemory(areaStorage, new byte[0x40]);
            bus.MapWritableMemory(areaPattern, new byte[2]);
            bus.MapWritableMemory(temporaryRaster, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteWord(areaPattern, 0xFFFF);
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: (_, _) => temporaryRaster,
            freeMemory: (_, _) => { });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: (_, _) => temporaryRaster,
            freeMemory: (_, _) => { });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeBoth(GraphicsLvo vector, M68kCpuState directState, M68kCpuState overlayState)
        {
            direct.Invoke(directState, (int)vector);
            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        InvokeBoth(
            GraphicsLvo.InitRastPort,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu }, Cycles = 7 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu }, Cycles = 7 });

        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, areaPattern);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 0, 0);
        }

        InvokeBoth(
            GraphicsLvo.InitArea,
            new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8, [1] = 0xDEAD_BEEFu },
                Cycles = 11
            },
            new M68kCpuState
            {
                A = { [0] = areaInfo, [1] = areaStorage },
                D = { [0] = 8, [1] = 0xDEAD_BEEFu },
                Cycles = 11
            });

        foreach (var (vector, x, y, cycles) in new[]
        {
            (GraphicsLvo.AreaMove, (short)1, (short)1, 17L),
            (GraphicsLvo.AreaDraw, (short)6, (short)1, 23L),
            (GraphicsLvo.AreaDraw, (short)6, (short)6, 29L),
            (GraphicsLvo.AreaDraw, (short)1, (short)6, 31L)
        })
        {
            InvokeBoth(
                vector,
                new M68kCpuState
                {
                    A = { [1] = rastPort },
                    D = { [0] = unchecked((uint)(ushort)x), [1] = unchecked((uint)(ushort)y) },
                    Cycles = cycles
                },
                new M68kCpuState
                {
                    A = { [1] = rastPort },
                    D = { [0] = unchecked((uint)(ushort)x), [1] = unchecked((uint)(ushort)y) },
                    Cycles = cycles
                });
        }

        InvokeBoth(
            GraphicsLvo.AreaEnd,
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu }, Cycles = 37 },
            new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 0xDEAD_BEEFu }, Cycles = 37 });

        for (var offset = 0; offset < 0x40; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(areaStorage + (uint)offset),
                overlayBus.ReadByte(areaStorage + (uint)offset));
        }

        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(areaInfo + (uint)offset),
                overlayBus.ReadByte(areaInfo + (uint)offset));
        }

        for (var row = 0; row < 8; row++)
        {
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2),
                overlayBus.ReadByte(plane + (uint)row * 2));
            Assert.Equal(
                directBus.ReadByte(plane + (uint)row * 2 + 1),
                overlayBus.ReadByte(plane + (uint)row * 2 + 1));
        }

        // The polygon's center is part of the filled area and therefore must
        // be visible in the first planar byte after the direct operation.
        Assert.NotEqual((byte)0, directBus.ReadByte(plane + 3 * 2));
        Assert.Equal((ushort)0, directBus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal(
            areaStorage,
            directBus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
    }

