        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x420);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagDrawBounds);
