    [Fact]
    public void RomOverlayLeavesWrappedDrawBoundsDestinationToNativeBoundary()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint tags = 0x300;
        const uint nativeTarget = 0x00FE_2041;
        const uint wrappedRectangle = 0xFFFF_FFFCu;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetRPAttrsA)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(tags, new byte[0x10]);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagDrawBounds);
        bus.WriteLong(tags + 4u, wrappedRectangle);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = 0x100 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 229,
            ProgramCounter = 0x0012_3A91
        };
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetRPAttrsA));

        Assert.True(bus.TryInvokeHostGatewayAt(address, state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(229, state.Cycles);
    }

    [Fact]
    public void GetRPAttrsRejectsWrappedRastPortFontBeforeLowAlias()
    {
        var memory = new WrappingMemory();
        const uint highRastPort = 0xFFFF_FFF0u;
        const uint tags = 0x100;
        const uint result = 0x200;

        // The unchecked Font-field addition would read this low alias.
        memory.WriteLong(0x24, 0xDEAD_BEEFu);
        memory.WriteLong(result, 0xA5A5_5A5Au);
        memory.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagFont);
        memory.WriteLong(tags + 4u, result);
        memory.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        memory.WriteLong(tags + 12u, 0);

        Assert.False(GraphicsRastPortAttributeOperations.Get(
            memory,
            highRastPort,
            tags,
            new FakeFontBackend()));
        Assert.True(memory.TryReadLong(result, out var pureResult));
        Assert.Equal(0xA5A5_5A5Au, pureResult);

        // The register boundary must preserve D0 and leave the result buffer
        // untouched so the captured native vector can handle the malformed
        // high address.
        var core = CreateCore(memory);
        memory.WriteLong(0x24, 0xDEAD_BEEFu);
        memory.WriteLong(result, 0xA5A5_5A5Au);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = highRastPort },
            D = { [0] = 0x1357_9BDFu }
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.GetRPAttrsA));
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.True(memory.TryReadLong(result, out var gatewayResult));
        Assert.Equal(0xA5A5_5A5Au, gatewayResult);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveWaitTofLifecycleParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);

        var directCalls = 0;
        var overlayCalls = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            waitTof: state =>
            {
                directCalls++;
                state.Cycles += 37;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            waitTof: state =>
            {
                overlayCalls++;
                state.Cycles += 37;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 211
        };
        var overlayState = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 211
        };

        direct.Invoke(directState, (int)GraphicsLvo.WaitTOF);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WaitTOF));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(1, directCalls);
        Assert.Equal(1, overlayCalls);
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(248, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
    }

