        Assert.Equal(1, directCalls);
        Assert.Equal(1, overlayCalls);
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(211, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(
            bitMap,
            directBus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(
            directBus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap),
            overlayBus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyChangeVPBitMapAssociationBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FC_1463;
        const uint viewPort = 0x100;
        const uint rasInfo = 0x200;
        const uint currentBitMap = 0x300;
        const uint nextBitMap = 0x400;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase +
                (int)GraphicsLvo.ChangeVPBitMap)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        foreach (var bitMap in new[] { currentBitMap, nextBitMap })
        {
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        }

        bus.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo);
        bus.WriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap);

        var readOnlyRasInfo = Enumerable.Range(0, GraphicsLayouts.RasInfoSize)
            .Select(offset => bus.ReadByte(rasInfo + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(rasInfo, readOnlyRasInfo);

        var rebuilds = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            requestDisplayRebuild: () => rebuilds++);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211,
            ProgramCounter = 0x0012_3705
        };
        var address = unchecked((uint)((int)graphicsBase +
            (int)GraphicsLvo.ChangeVPBitMap));

        Assert.True(bus.TryInvokeHostGatewayAt(address, state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(211, state.Cycles);
        Assert.Equal(0, rebuilds);
        Assert.Equal(
            currentBitMap,
            bus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void NativeOverlayLeavesMalformedDisplayableChangeVPBitMapForNativeFallback()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x100;
        const uint rasInfo = 0x200;
        const uint currentBitMap = 0x300;
        const uint malformedBitMap = 0x400;
        const uint oddPlane = 0x701;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(currentBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(malformedBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, currentBitMap);
            bus.WriteWord(currentBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
            bus.WriteByte(currentBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteWord(malformedBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
            bus.WriteWord(malformedBitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(malformedBitMap + (uint)GraphicsLayouts.BitMapFlags, 0x0A, 0);
            bus.WriteByte(malformedBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(malformedBitMap + (uint)GraphicsLayouts.BitMapPlanes, oddPlane);
        }

        var directRebuilds = 0;
        var overlayRebuilds = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            requestDisplayRebuild: () => directRebuilds++);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            requestDisplayRebuild: () => overlayRebuilds++);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = malformedBitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = malformedBitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };

        direct.Invoke(directState, (int)GraphicsLvo.ChangeVPBitMap);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ChangeVPBitMap));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(0, directRebuilds);
        Assert.Equal(0, overlayRebuilds);
        Assert.Equal(0xCAFE_BABEu, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(211, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(
            currentBitMap,
            directBus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(
            directBus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap),
            overlayBus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveDoubleBufferEnvelopeParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x100;
        const uint rasInfo = 0x200;
        const uint dbufInfo = 0x300;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(dbufInfo, new byte[GraphicsLayouts.DBufInfoSize]);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        }

        var directAllocations = 0;
        var overlayAllocations = 0;
        var directFrees = 0;
        var overlayFrees = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: (_, _) =>
            {
                directAllocations++;
                return dbufInfo;
            },
            freeMemory: (address, bytes) =>
            {
                Assert.Equal(dbufInfo, address);
                Assert.Equal(GraphicsLayouts.DBufInfoSize, bytes);
                directFrees++;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: (_, _) =>
            {
                overlayAllocations++;
                return dbufInfo;
            },
            freeMemory: (address, bytes) =>
            {
                Assert.Equal(dbufInfo, address);
                Assert.Equal(GraphicsLayouts.DBufInfoSize, bytes);
                overlayFrees++;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directAllocState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xDEAD_BEEFu }
        };
        var overlayAllocState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xDEAD_BEEFu }
        };

        direct.Invoke(directAllocState, (int)GraphicsLvo.AllocDBufInfo);
        var allocAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AllocDBufInfo));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(allocAddress, overlayAllocState));
        Assert.Equal(1, directAllocations);
        Assert.Equal(1, overlayAllocations);
        Assert.Equal(dbufInfo, directAllocState.D[0]);
        Assert.Equal(directAllocState.D[0], overlayAllocState.D[0]);

        var directFreeState = new M68kCpuState { A = { [0] = 0xA0A0_A0A1u, [1] = dbufInfo }, D = { [0] = 7 } };
        var overlayFreeState = new M68kCpuState { A = { [0] = 0xA0A0_A0A1u, [1] = dbufInfo }, D = { [0] = 7 } };
        direct.Invoke(directFreeState, (int)GraphicsLvo.FreeDBufInfo);
        var freeAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeDBufInfo));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeAddress, overlayFreeState));
        Assert.Equal(1, directFrees);
        Assert.Equal(1, overlayFrees);
        Assert.Equal(0u, directFreeState.D[0]);
        Assert.Equal(directFreeState.D[0], overlayFreeState.D[0]);
    }

    [Fact]
    public void RtgAllocDBufInfoRemainsProviderOwnedAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x100;
        const uint rasInfo = 0x200;
