        Assert.Equal(0x0012_A101u, directState.ProgramCounter);

        var overlayState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211,
            ProgramCounter = 0x0012_A102
        };
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.AllocDBufInfo));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
        Assert.Equal(0, overlayAllocations);
        Assert.Equal(0xCAFE_BABEu, overlayState.D[0]);
        Assert.Equal(211, overlayState.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveCopperConstructionParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        const uint viewPortExtra = 0x500;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(viewPortExtra, new byte[GraphicsLayouts.ViewPortExtraSize]);
            bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        }

        var directMakeCalls = 0;
        var overlayMakeCalls = 0;
        var directMergeCalls = 0;
        var overlayMergeCalls = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: (_, _) => viewPortExtra,
            makeViewPort: state =>
            {
                Assert.Equal(view, state.A[0]);
                Assert.Equal(viewPort, state.A[1]);
                directMakeCalls++;
                return 0;
            },
            mergeCopperLists: state =>
            {
                Assert.Equal(view, state.A[1]);
                directMergeCalls++;
                return 0;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: (_, _) => viewPortExtra,
            makeViewPort: state =>
            {
                Assert.Equal(view, state.A[0]);
                Assert.Equal(viewPort, state.A[1]);
                overlayMakeCalls++;
                return 0;
            },
            mergeCopperLists: state =>
            {
                Assert.Equal(view, state.A[1]);
                overlayMergeCalls++;
                return 0;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directMake = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 31
        };
        var overlayMake = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 31
        };

        direct.Invoke(directMake, (int)GraphicsLvo.MakeVPort);
        var makeAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MakeVPort));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(makeAddress, overlayMake));
        Assert.Equal(1, directMakeCalls);
        Assert.Equal(1, overlayMakeCalls);
        Assert.Equal(0u, directMake.D[0]);
        Assert.Equal(directMake.D[0], overlayMake.D[0]);
        Assert.Equal(31, directMake.Cycles);
        Assert.Equal(directMake.Cycles, overlayMake.Cycles);

        var directMerge = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 47
        };
        var overlayMerge = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 47
        };

        direct.Invoke(directMerge, (int)GraphicsLvo.MrgCop);
        var mergeAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MrgCop));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(mergeAddress, overlayMerge));
        Assert.Equal(1, directMergeCalls);
        Assert.Equal(1, overlayMergeCalls);
        Assert.Equal(0u, directMerge.D[0]);
        Assert.Equal(directMerge.D[0], overlayMerge.D[0]);
        Assert.Equal(47, directMerge.Cycles);
        Assert.Equal(directMerge.Cycles, overlayMerge.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveCopperTeardownParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x200;
        const uint cprList = 0x300;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(cprList, new byte[GraphicsLayouts.CprListSize]);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, 0x400);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns, 0x404);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns, 0x408);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns, 0x40C);
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListNext, 0);
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, 0x500);
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListMaxCount, 32);
        }

        var directFreeViewPortCalls = 0;
        var overlayFreeViewPortCalls = 0;
        var directFreeCprCalls = 0;
        var overlayFreeCprCalls = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            tryFreeVPortCopLists: address =>
            {
                Assert.Equal(viewPort, address);
                directFreeViewPortCalls++;
                return true;
            },
            tryFreeCprList: address =>
            {
                Assert.Equal(cprList, address);
                directFreeCprCalls++;
                return true;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            tryFreeVPortCopLists: address =>
            {
                Assert.Equal(viewPort, address);
                overlayFreeViewPortCalls++;
                return true;
            },
            tryFreeCprList: address =>
            {
                Assert.Equal(cprList, address);
                overlayFreeCprCalls++;
                return true;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directViewPortState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 31
        };
        var overlayViewPortState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 31
        };

        direct.Invoke(directViewPortState, (int)GraphicsLvo.FreeVPortCopLists);
        var freeViewPortAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeVPortCopLists));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeViewPortAddress, overlayViewPortState));
        Assert.Equal(1, directFreeViewPortCalls);
        Assert.Equal(1, overlayFreeViewPortCalls);
        Assert.Equal(0u, directViewPortState.D[0]);
        Assert.Equal(directViewPortState.D[0], overlayViewPortState.D[0]);
        Assert.Equal(31, directViewPortState.Cycles);
        Assert.Equal(directViewPortState.Cycles, overlayViewPortState.Cycles);
        foreach (var offset in new[]
                 {
                     GraphicsLayouts.ViewPortDspIns,
                     GraphicsLayouts.ViewPortSprIns,
                     GraphicsLayouts.ViewPortClrIns,
                     GraphicsLayouts.ViewPortUCopIns
                 })
        {
            Assert.Equal(0u, directBus.ReadLong(viewPort + (uint)offset));
            Assert.Equal(directBus.ReadLong(viewPort + (uint)offset), overlayBus.ReadLong(viewPort + (uint)offset));
        }

        var directCprState = new M68kCpuState
        {
            A = { [0] = cprList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 47
        };
        var overlayCprState = new M68kCpuState
        {
            A = { [0] = cprList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 47
        };

        direct.Invoke(directCprState, (int)GraphicsLvo.FreeCprList);
        var freeCprAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCprList));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeCprAddress, overlayCprState));
        Assert.Equal(1, directFreeCprCalls);
        Assert.Equal(1, overlayFreeCprCalls);
        Assert.Equal(0u, directCprState.D[0]);
        Assert.Equal(directCprState.D[0], overlayCprState.D[0]);
        Assert.Equal(47, directCprState.Cycles);
        Assert.Equal(directCprState.Cycles, overlayCprState.Cycles);

        var directNullCprState = new M68kCpuState
        {
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 53
        };
        var overlayNullCprState = new M68kCpuState
        {
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 53
        };
        direct.Invoke(directNullCprState, (int)GraphicsLvo.FreeCprList);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeCprAddress, overlayNullCprState));
        Assert.Equal(0u, directNullCprState.D[0]);
        Assert.Equal(directNullCprState.D[0], overlayNullCprState.D[0]);
        Assert.Equal(53, directNullCprState.Cycles);
        Assert.Equal(directNullCprState.Cycles, overlayNullCprState.Cycles);
        Assert.Equal(1, directFreeCprCalls);
        Assert.Equal(1, overlayFreeCprCalls);

        var directNullViewPortState = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 59
        };
        var overlayNullViewPortState = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 59
        };
        direct.Invoke(directNullViewPortState, (int)GraphicsLvo.FreeVPortCopLists);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeViewPortAddress, overlayNullViewPortState));
        Assert.Equal(0u, directNullViewPortState.D[0]);
        Assert.Equal(directNullViewPortState.D[0], overlayNullViewPortState.D[0]);
        Assert.Equal(59, directNullViewPortState.Cycles);
        Assert.Equal(directNullViewPortState.Cycles, overlayNullViewPortState.Cycles);
        Assert.Equal(1, directFreeViewPortCalls);
        Assert.Equal(1, overlayFreeViewPortCalls);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveUserCopperListParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint userList = 0x100;
        const uint allocationBase = 0x500;
        const ushort capacity = 2;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(userList, new byte[GraphicsLayouts.UCopListSize]);
            bus.MapWritableMemory(allocationBase, new byte[0x1000]);
        }

        uint directNextAllocation = allocationBase;
        uint overlayNextAllocation = allocationBase;
        static uint AdvanceAllocation(uint address, int bytes)
            => address + (uint)((bytes + 0x0F) & ~0x0F);
        uint DirectAllocate(int bytes, uint memoryClass)
        {
            var address = directNextAllocation;
            directNextAllocation = AdvanceAllocation(address, bytes);
            return address;
        }

        uint OverlayAllocate(int bytes, uint memoryClass)
        {
            var address = overlayNextAllocation;
            overlayNextAllocation = AdvanceAllocation(address, bytes);
            return address;
        }

        var directFrees = 0;
        var overlayFrees = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: DirectAllocate,
            freeMemory: (_, _) => directFrees++);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: OverlayAllocate,
            freeMemory: (_, _) => overlayFrees++);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directInit = new M68kCpuState
        {
            A = { [0] = userList },
            D = { [0] = capacity },
            Cycles = 11
        };
        var overlayInit = new M68kCpuState
        {
            A = { [0] = userList },
            D = { [0] = capacity },
            Cycles = 11
        };
        direct.Invoke(directInit, (int)GraphicsLvo.UCopperListInit);
        var initAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.UCopperListInit));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(initAddress, overlayInit));
        Assert.NotEqual(0u, directInit.D[0]);
        Assert.Equal(directInit.D[0], overlayInit.D[0]);
        Assert.Equal(11, directInit.Cycles);
        Assert.Equal(directInit.Cycles, overlayInit.Cycles);
        var copList = directInit.D[0];
        Assert.Equal(copList, directBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(
            directBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList),
            overlayBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));

        var directMove = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0x00DF_F180, [1] = 0x1234 },
            Cycles = 17
        };
        var overlayMove = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0x00DF_F180, [1] = 0x1234 },
            Cycles = 17
        };
        direct.Invoke(directMove, (int)GraphicsLvo.CMove);
        var moveAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CMove));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(moveAddress, overlayMove));
        Assert.Equal(0u, directMove.D[0]);
        Assert.Equal(directMove.D[0], overlayMove.D[0]);
        Assert.Equal(17, directMove.Cycles);
        Assert.Equal(directMove.Cycles, overlayMove.Cycles);

        var directBump = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 19
        };
        var overlayBump = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 19
        };
        direct.Invoke(directBump, (int)GraphicsLvo.CBump);
        var bumpAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CBump));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(bumpAddress, overlayBump));
        Assert.Equal(0u, directBump.D[0]);
        Assert.Equal(directBump.D[0], overlayBump.D[0]);
        Assert.Equal(19, directBump.Cycles);
        Assert.Equal(directBump.Cycles, overlayBump.Cycles);

        var directWait = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 42, [1] = 12 },
            Cycles = 23
        };
        var overlayWait = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 42, [1] = 12 },
            Cycles = 23
        };
        direct.Invoke(directWait, (int)GraphicsLvo.CWait);
        var waitAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CWait));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(waitAddress, overlayWait));
        Assert.Equal(0u, directWait.D[0]);
        Assert.Equal(directWait.D[0], overlayWait.D[0]);
        Assert.Equal(23, directWait.Cycles);
        Assert.Equal(directWait.Cycles, overlayWait.Cycles);

        var directSecondBump = new M68kCpuState { A = { [1] = userList }, Cycles = 29 };
        var overlaySecondBump = new M68kCpuState { A = { [1] = userList }, Cycles = 29 };
        direct.Invoke(directSecondBump, (int)GraphicsLvo.CBump);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(bumpAddress, overlaySecondBump));
        Assert.Equal(0u, directSecondBump.D[0]);
        Assert.Equal(directSecondBump.D[0], overlaySecondBump.D[0]);
        Assert.Equal(29, directSecondBump.Cycles);
        Assert.Equal(directSecondBump.Cycles, overlaySecondBump.Cycles);

        var directFree = new M68kCpuState
        {
            A = { [0] = copList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 31
        };
        var overlayFree = new M68kCpuState
        {
            A = { [0] = copList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 31
        };
        direct.Invoke(directFree, (int)GraphicsLvo.FreeCopList);
        var freeAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCopList));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeAddress, overlayFree));
        Assert.Equal(2, directFrees);
        Assert.Equal(2, overlayFrees);
        Assert.Equal(0u, directFree.D[0]);
        Assert.Equal(directFree.D[0], overlayFree.D[0]);
        Assert.Equal(31, directFree.Cycles);
        Assert.Equal(directFree.Cycles, overlayFree.Cycles);
        Assert.Equal(0u, directBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(0u, directBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(
            directBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList),
            overlayBus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        var instructions = directBus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopIns);
        var overlayInstructions = overlayBus.ReadLong(overlayInit.D[0] + (uint)GraphicsLayouts.CopListCopIns);
        Assert.Equal(directBus.ReadWord(instructions + (uint)GraphicsLayouts.CopInsOpCode), overlayBus.ReadWord(overlayInstructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal(directBus.ReadWord(instructions + (uint)GraphicsLayouts.CopInsArg0), overlayBus.ReadWord(overlayInstructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal(directBus.ReadWord(instructions + (uint)GraphicsLayouts.CopInsArg1), overlayBus.ReadWord(overlayInstructions + (uint)GraphicsLayouts.CopInsArg1));

        var directNullFree = new M68kCpuState
        {
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 37
        };
        var overlayNullFree = new M68kCpuState
        {
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 37
        };
        direct.Invoke(directNullFree, (int)GraphicsLvo.FreeCopList);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(freeAddress, overlayNullFree));
        Assert.Equal(0u, directNullFree.D[0]);
        Assert.Equal(directNullFree.D[0], overlayNullFree.D[0]);
        Assert.Equal(37, directNullFree.Cycles);
        Assert.Equal(directNullFree.Cycles, overlayNullFree.Cycles);
        Assert.Equal(2, directFrees);
        Assert.Equal(2, overlayFrees);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyViewPortCopperLinksBeforeMakeAndMergePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FC_1499;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;

        static void PrepareBus(AmigaBus bus, GraphicsLvo vector)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        }

        var makeBus = new AmigaBus();
        PrepareBus(makeBus, GraphicsLvo.MakeVPort);
        var makeOffset = (uint)GraphicsLayouts.ViewPortDspIns;
        var makeLink = viewPort + makeOffset;
        makeBus.WriteLong(makeLink, 0x410);
        makeBus.MapReadOnlyMemory(
            makeLink,
            Enumerable.Range(0, sizeof(uint))
                .Select(offset => makeBus.ReadByte(makeLink + (uint)offset))
                .ToArray());

        var makeCalls = 0;
        var makeAllocations = 0;
        using (var makeServices = CreateHostGraphicsServices(
                   new HostGuestMemory(makeBus),
                   allocateMemory: (_, _) =>
                   {
                       makeAllocations++;
                       return 0x600u;
                   },
                   makeViewPort: _ =>
                   {
                       makeCalls++;
                       return 0;
                   }))
        {
            Assert.True(makeServices.InstallKickstartRomOverlay(graphicsBase));
            var state = new M68kCpuState
            {
                A = { [0] = view, [1] = viewPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 41,
                ProgramCounter = 0x0012_3705
            };

            Assert.True(makeBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MakeVPort)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(41, state.Cycles);
            Assert.Equal(0, makeCalls);
            Assert.Equal(0, makeAllocations);
            Assert.Equal(0x410u, makeBus.ReadLong(makeLink));
        }

        var mergeBus = new AmigaBus();
        PrepareBus(mergeBus, GraphicsLvo.MrgCop);
        var mergeOffset = (uint)GraphicsLayouts.ViewPortSprIns;
        var mergeLink = viewPort + mergeOffset;
        mergeBus.WriteLong(mergeLink, 0x510);
        mergeBus.MapReadOnlyMemory(
            mergeLink,
            Enumerable.Range(0, sizeof(uint))
                .Select(offset => mergeBus.ReadByte(mergeLink + (uint)offset))
                .ToArray());

        var mergeCalls = 0;
        using (var mergeServices = CreateHostGraphicsServices(
                   new HostGuestMemory(mergeBus),
                   mergeCopperLists: _ =>
                   {
                       mergeCalls++;
                       return 0;
                   }))
        {
            Assert.True(mergeServices.InstallKickstartRomOverlay(graphicsBase));
            var state = new M68kCpuState
            {
                A = { [1] = view },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 47,
                ProgramCounter = 0x0012_3707
            };

            Assert.True(mergeBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MrgCop)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(47, state.Cycles);
            Assert.Equal(0, mergeCalls);
            Assert.Equal(0x510u, mergeBus.ReadLong(mergeLink));
        }
    }

    [Fact]
    public void NativeOverlayMakeVPortPreflightsOwnedVideoControlBatchBeforeCopperPublication()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;
        const uint tags = 0x700;

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));

        var colorMap = core.GetColorMap(2);
        Assert.NotEqual(0u, colorMap);
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));

        // VTAG_BATCH_CM_SET enables replay at MakeVPort. The list itself is
        // empty here; the admission boundary is the owned ColorMap envelope
        // that the replay would mutate.
        Assert.True(memory.TryWriteLong(tags, 0x8000_000Eu));
        Assert.True(memory.TryWriteLong(tags + 4u, 1));
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        Assert.True(core.VideoControl(colorMap, tags));
        var flagsAddress = colorMap + (uint)GraphicsLayouts.ColorMapFlags;
        Assert.NotEqual(0, ReadByte(memory, flagsAddress) & 0x10);

        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, _) =>
                address < colorMap || address >= colorMap + (uint)GraphicsLayouts.ColorMapSize);
        var state = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211,
            ProgramCounter = 0x0012_3711
        };
        var writesBeforeDecline = memory.WriteCount;

        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.MakeVPort,
            nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(211, state.Cycles);
        Assert.Equal(0x0012_3711u, state.ProgramCounter);
        Assert.Equal(writesBeforeDecline, memory.WriteCount);
        Assert.Equal(0, display.MakeCount);
        Assert.Equal(0u, core.GfxLookUp(viewPort));
        Assert.NotEqual(0, ReadByte(memory, flagsAddress) & 0x10);

        // The same owned batch remains claimable when its complete envelope
        // is writable; the admission rule is ownership-aware, not a blanket
        // native-overlay veto for MakeVPort.
        var writableAdapter = new CopperStartGraphicsRegisterAdapter(core);
        var writableState = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 223
        };
        Assert.True(writableAdapter.TryInvoke(
            writableState,
            (int)GraphicsLvo.MakeVPort,
            nativeOverlay: true));
        Assert.Equal(0u, writableState.D[0]);
        Assert.Equal(223, writableState.Cycles);
        Assert.NotEqual(0u, core.GfxLookUp(viewPort));
        Assert.Equal(1, display.MakeCount);

        const uint batchItems = 0x800;
        Assert.True(memory.TryWriteLong(
            colorMap + (uint)GraphicsLayouts.ColorMapBatchItems,
            batchItems));
        Assert.True(memory.TryWriteLong(batchItems, 0x8000_001Du)); // GET
        Assert.True(memory.TryWriteLong(batchItems + 4u, 0));
        var batchTagBeforeDecline = ReadLong(memory, batchItems);
        var batchWritesBeforeDecline = memory.WriteCount;
        var readOnlyBatchAdapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, _) =>
                address < batchItems || address >= batchItems + 8u);
        var readOnlyBatchState = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 229,
            ProgramCounter = 0x0012_3713
        };

        Assert.False(readOnlyBatchAdapter.TryInvoke(
            readOnlyBatchState,
            (int)GraphicsLvo.MakeVPort,
            nativeOverlay: true));
        Assert.Equal(0x2468_ACE0u, readOnlyBatchState.D[0]);
        Assert.Equal(229, readOnlyBatchState.Cycles);
        Assert.Equal(0x0012_3713u, readOnlyBatchState.ProgramCounter);
        Assert.Equal(batchWritesBeforeDecline, memory.WriteCount);
        Assert.Equal(batchTagBeforeDecline, ReadLong(memory, batchItems));
        Assert.Equal(1, display.MakeCount);
    }

