    [Fact]
    public void FreeVPortCopListsPreservesReadOnlyCopperLinksAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FC_15B1;
        const uint viewPort = 0x200;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var links = new uint[] { 0x410, 0x420, 0x430, 0x440 };

        static void PrepareBus(
            AmigaBus bus,
            uint imageBase,
            uint graphicsBase,
            uint nativeTarget,
            uint viewPort,
            int[] offsets,
            uint[] links)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase +
                    (int)GraphicsLvo.FreeVPortCopLists)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            for (var index = 0; index < offsets.Length; index++)
            {
                var link = viewPort + (uint)offsets[index];
                bus.WriteLong(link, links[index]);
                bus.MapReadOnlyMemory(
                    link,
                    Enumerable.Range(0, sizeof(uint))
                        .Select(offset => bus.ReadByte(link + (uint)offset))
                        .ToArray());
            }
        }

        var directBus = new AmigaBus();
        PrepareBus(
            directBus,
            imageBase,
            graphicsBase,
            nativeTarget,
            viewPort,
            offsets,
            links);
        var directFreeCalls = 0;
        using (var direct = CreateHostGraphicsServices(
                   new HostGuestMemory(directBus),
                   freeVPortCopLists: _ => directFreeCalls++))
        {
            var state = new M68kCpuState
            {
                A = { [0] = viewPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 61
            };

            direct.Invoke(state, (int)GraphicsLvo.FreeVPortCopLists);
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(61, state.Cycles);
            Assert.Equal(0, directFreeCalls);
            for (var index = 0; index < offsets.Length; index++)
                Assert.Equal(links[index], directBus.ReadLong(viewPort + (uint)offsets[index]));
        }

        var mappedBus = new AmigaBus();
        PrepareBus(
            mappedBus,
            imageBase,
            graphicsBase,
            nativeTarget,
            viewPort,
            offsets,
            links);
        var mappedFreeCalls = 0;
        using (var mapped = CreateHostGraphicsServices(
                   new HostGuestMemory(mappedBus),
                   freeVPortCopLists: _ => mappedFreeCalls++))
        {
            Assert.True(mapped.InstallKickstartRomOverlay(graphicsBase));
            var state = new M68kCpuState
            {
                A = { [0] = viewPort },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 67,
                ProgramCounter = 0x0012_3709
            };

            Assert.True(mappedBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase +
                    (int)GraphicsLvo.FreeVPortCopLists)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(67, state.Cycles);
            Assert.Equal(0, mappedFreeCalls);
            for (var index = 0; index < offsets.Length; index++)
                Assert.Equal(links[index], mappedBus.ReadLong(viewPort + (uint)offsets[index]));
        }
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyUserCopperListBeforeInternalAllocation()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FC_1471;
        const uint userList = 0x00F0_0100;
        const uint allocationBase = 0x00F0_0500;
        const ushort capacity = 2;
        const byte sentinel = 0xA5;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase +
                (int)GraphicsLvo.UCopperListInit)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapReadOnlyMemory(
            userList,
            Enumerable.Repeat(sentinel, GraphicsLayouts.UCopListSize).ToArray());
        bus.MapWritableMemory(allocationBase, new byte[0x1000]);

        var allocations = 0;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (_, _) =>
            {
                allocations++;
                return allocationBase;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
