    [Fact]
    public void NativeOverlayDeclinesReadOnlyCopperInstructionBeforeCMoveAndCWaitPublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FC_1477;
        const uint userList = 0x00F0_0100;
        const uint allocationBase = 0x00F0_0500;
        const ushort capacity = 2;
        const byte sentinel = 0xB6;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[] { GraphicsLvo.UCopperListInit, GraphicsLvo.CMove, GraphicsLvo.CWait })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(userList, new byte[GraphicsLayouts.UCopListSize]);
        bus.MapWritableMemory(allocationBase, new byte[0x1000]);

        var nextAllocation = allocationBase;
        static uint AdvanceAllocation(uint address, int bytes)
            => address + (uint)((bytes + 0x0F) & ~0x0F);

        var allocations = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                allocations++;
                var address = nextAllocation;
                nextAllocation = AdvanceAllocation(address, bytes);
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var init = new M68kCpuState
        {
            A = { [0] = userList },
            D = { [0] = capacity },
            Cycles = 11
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase +
                (int)GraphicsLvo.UCopperListInit)),
            init));
        Assert.NotEqual(0u, init.D[0]);

        var copList = init.D[0];
        var instruction = bus.ReadLong(
            copList + (uint)GraphicsLayouts.CopListCopIns);
        for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
            bus.WriteByte(instruction + (uint)offset, sentinel, 0);
        bus.MapReadOnlyMemory(
            instruction,
            Enumerable.Repeat(sentinel, GraphicsLayouts.CopInsSize).ToArray());

        var allocationsBeforeMutation = allocations;
        var move = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0x00DF_F180, [1] = 0x1234, [2] = 0xCAFEBABEu },
            Cycles = 17,
            ProgramCounter = 0x0012_3705
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CMove)),
            move));

        var wait = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 42, [1] = 12, [2] = 0x1357_9BDFu },
            Cycles = 19,
            ProgramCounter = 0x0012_3707
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CWait)),
            wait));

        Assert.Equal(nativeTarget, move.ProgramCounter);
        Assert.Equal(0x00DF_F180u, move.D[0]);
        Assert.Equal(0x1234u, move.D[1]);
        Assert.Equal(0xCAFEBABEu, move.D[2]);
        Assert.Equal(17, move.Cycles);
        Assert.Equal(nativeTarget, wait.ProgramCounter);
        Assert.Equal(42u, wait.D[0]);
        Assert.Equal(12u, wait.D[1]);
        Assert.Equal(0x1357_9BDFu, wait.D[2]);
        Assert.Equal(19, wait.Cycles);
        Assert.Equal(allocationsBeforeMutation, allocations);
        for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(instruction + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyCopperBumpStateBeforeInBlockAdvance()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FC_147D;
        const uint userList = 0x00F0_1100;
        const uint allocationBase = 0x00F0_1500;
        const ushort capacity = 2;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        foreach (var vector in new[] { GraphicsLvo.UCopperListInit, GraphicsLvo.CBump })
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)vector)),
                nativeTarget);
        }

        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(userList, new byte[GraphicsLayouts.UCopListSize]);
        bus.MapWritableMemory(allocationBase, new byte[0x1000]);
        var nextAllocation = allocationBase;
        static uint AdvanceAllocation(uint address, int bytes)
            => address + (uint)((bytes + 0x0F) & ~0x0F);

        var allocations = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                allocations++;
                var address = nextAllocation;
                nextAllocation = AdvanceAllocation(address, bytes);
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var init = new M68kCpuState
        {
            A = { [0] = userList },
            D = { [0] = capacity },
            Cycles = 11
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase +
                (int)GraphicsLvo.UCopperListInit)),
            init));
        var copList = init.D[0];
        var copPtrAddress = copList + (uint)GraphicsLayouts.CopListCopPtr;
        var countAddress = copList + (uint)GraphicsLayouts.CopListCount;
        var originalCopPtr = bus.ReadLong(copPtrAddress);
        var originalCount = bus.ReadWord(countAddress);
        bus.MapReadOnlyMemory(
            copPtrAddress,
            Enumerable.Range(0, sizeof(uint))
                .Select(offset => bus.ReadByte(copPtrAddress + (uint)offset))
                .ToArray());
        bus.MapReadOnlyMemory(
            countAddress,
            Enumerable.Range(0, sizeof(ushort))
                .Select(offset => bus.ReadByte(countAddress + (uint)offset))
                .ToArray());

        var state = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 23,
            ProgramCounter = 0x0012_3705
        };
