        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(23, state.Cycles);
        Assert.Equal(allocationsBeforeBump, allocations);
        Assert.Equal(originalCopPtr, bus.ReadLong(copPtrAddress));
        Assert.Equal(originalCount, bus.ReadWord(countAddress));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyCopperBumpLinksBeforeFullBlockAllocation()
    {
        const uint imageBase = 0x00F8_F000;
