        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(19, state.Cycles);
        Assert.Equal(allocationsBeforeBump, allocations);
        Assert.Equal(originalCopNext, bus.ReadLong(copNextAddress));
        Assert.Equal(originalUserCopList, bus.ReadLong(userCopListAddress));
        Assert.Equal(0u, originalCopNext);
        Assert.Equal(copList, originalUserCopList);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveCalcIvgAndChipRevisionParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200);
        }

        var directCalcCalls = 0;
        var overlayCalcCalls = 0;
        var directChipCalls = 0;
        var overlayChipCalls = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            calcIvg: (actualView, actualViewPort) =>
            {
                Assert.Equal(view, actualView);
                Assert.Equal(viewPort, actualViewPort);
                directCalcCalls++;
                return 37;
            },
            setChipRev: requestedBits =>
            {
                Assert.Equal(GraphicsChipRevision.SetBest, requestedBits);
                directChipCalls++;
                return GraphicsChipRevision.SetEcs;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            calcIvg: (actualView, actualViewPort) =>
            {
                Assert.Equal(view, actualView);
                Assert.Equal(viewPort, actualViewPort);
                overlayCalcCalls++;
                return 37;
            },
            setChipRev: requestedBits =>
            {
                Assert.Equal(GraphicsChipRevision.SetBest, requestedBits);
                overlayChipCalls++;
                return GraphicsChipRevision.SetEcs;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directCalc = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 61
        };
        var overlayCalc = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 61
        };
        direct.Invoke(directCalc, (int)GraphicsLvo.CalcIVG);
        var calcAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CalcIVG));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(calcAddress, overlayCalc));
        Assert.Equal(1, directCalcCalls);
        Assert.Equal(1, overlayCalcCalls);
        Assert.Equal(37u, directCalc.D[0]);
        Assert.Equal(directCalc.D[0], overlayCalc.D[0]);
        Assert.Equal(61, directCalc.Cycles);
        Assert.Equal(directCalc.Cycles, overlayCalc.Cycles);

        var directChip = new M68kCpuState
        {
            D = { [0] = GraphicsChipRevision.SetBest },
            Cycles = 67
        };
        var overlayChip = new M68kCpuState
        {
            D = { [0] = GraphicsChipRevision.SetBest },
            Cycles = 67
        };
        direct.Invoke(directChip, (int)GraphicsLvo.SetChipRev);
        var chipAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetChipRev));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(chipAddress, overlayChip));
        Assert.Equal(1, directChipCalls);
        Assert.Equal(1, overlayChipCalls);
        Assert.Equal(GraphicsChipRevision.SetEcs, directChip.D[0]);
        Assert.Equal(directChip.D[0], overlayChip.D[0]);
        Assert.Equal(67, directChip.Cycles);
        Assert.Equal(directChip.Cycles, overlayChip.Cycles);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyChipRevisionPublicationBeforeHostCallback()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const byte sentinel = 0x5A;

        var bus = new AmigaBus();
        // Keep the negative vectors in a ROM-like image, while a newer
        // writable positive GfxBase envelope supplies the native monitor-list
        // sentinels.  The one-byte overlay below then models a provider that
        // owns ChipRevBits0 but leaves the rest of the GfxBase writable.
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(
            graphicsBase,
            new byte[GraphicsLayouts.GfxBaseNativeSize]);

        var monitorList = graphicsBase +
            (uint)GraphicsLayouts.GfxBaseMonitorList;
        bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u);
        bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0);
        bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0,
            0);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0,
            0);

        var chipRevAddress = graphicsBase +
            (uint)GraphicsLayouts.GfxBaseChipRevBits0;
        bus.WriteByte(chipRevAddress, sentinel, 0);
        bus.MapReadOnlyMemory(chipRevAddress, new[] { sentinel });

        var callbackCount = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            graphicsLibraryBase: graphicsBase,
            setChipRev: requestedBits =>
            {
                callbackCount++;
                return requestedBits;
            });

        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            D = { [0] = GraphicsChipRevision.SetBest },
            Cycles = 83,
            ProgramCounter = 0x0012_3401
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetChipRev)),
            state));
        Assert.Equal(0, callbackCount);
        Assert.Equal(GraphicsChipRevision.SetBest, state.D[0]);
        Assert.Equal(83, state.Cycles);
        Assert.Equal(0x0012_3401u, state.ProgramCounter);
        Assert.Equal(sentinel, bus.ReadByte(chipRevAddress));
    }

    [Fact]
    public void RomOverlayTailChainsRtgCalcIvgAndUnboundChipRevisionToOriginalVectors()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        const uint calcTarget = 0x00FA_F001;
        const uint chipTarget = 0x00FA_F002;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CalcIVG)), calcTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetChipRev)), chipTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200);

        var calcCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            calcIvg: (_, _) =>
            {
                calcCalls++;
                return 19;
            },
            isRtgBitMap: address => address == bitMap);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var calc = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 71,
            ProgramCounter = 0x0012_3401
        };
        var chip = new M68kCpuState
        {
            D = { [0] = GraphicsChipRevision.SetBest },
            Cycles = 73,
            ProgramCounter = 0x0012_3402
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CalcIVG)),
            calc));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetChipRev)),
            chip));
        Assert.Equal(0, calcCalls);
        Assert.Equal(calcTarget, calc.ProgramCounter);
        Assert.Equal(chipTarget, chip.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, calc.D[0]);
        Assert.Equal(GraphicsChipRevision.SetBest, chip.D[0]);
        Assert.Equal(71, calc.Cycles);
        Assert.Equal(73, chip.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveDisplayModeQueryParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        directBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        overlayBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        const uint sentinelBuffer = 0x1000;
        directBus.MapWritableMemory(sentinelBuffer, new byte[0x40]);
        overlayBus.MapWritableMemory(sentinelBuffer, new byte[0x40]);
        directBus.WriteByte(sentinelBuffer, 0xA5, 0);
        overlayBus.WriteByte(sentinelBuffer, 0xA5, 0);
        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directFind = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode },
            Cycles = 79
        };
        var overlayFind = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode },
            Cycles = 79
        };
        direct.Invoke(directFind, (int)GraphicsLvo.FindDisplayInfo);
        var findAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FindDisplayInfo));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(findAddress, overlayFind));
        Assert.Equal(directFind.D[0], overlayFind.D[0]);
        Assert.Equal(directFind.Cycles, overlayFind.Cycles);

        var directDefaultFind = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.DefaultMonitor },
            Cycles = 81
        };
        var overlayDefaultFind = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.DefaultMonitor },
            Cycles = 81
        };
        direct.Invoke(directDefaultFind, (int)GraphicsLvo.FindDisplayInfo);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(findAddress, overlayDefaultFind));
        Assert.Equal(GraphicsDisplayDatabase.DefaultModeHandle, directDefaultFind.D[0]);
        Assert.Equal(directDefaultFind.D[0], overlayDefaultFind.D[0]);
        Assert.Equal(directDefaultFind.Cycles, overlayDefaultFind.Cycles);

        var directNext = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 83
        };
        var overlayNext = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 83
        };
        direct.Invoke(directNext, (int)GraphicsLvo.NextDisplayInfo);
        var nextAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.NextDisplayInfo));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(nextAddress, overlayNext));
        Assert.Equal(directNext.D[0], overlayNext.D[0]);
        Assert.Equal(directNext.Cycles, overlayNext.Cycles);

        var directAvailability = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode },
            Cycles = 89
        };
        var overlayAvailability = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode },
            Cycles = 89
        };
        direct.Invoke(directAvailability, (int)GraphicsLvo.ModeNotAvailable);
        var availabilityAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ModeNotAvailable));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(availabilityAddress, overlayAvailability));
        Assert.Equal(directAvailability.D[0], overlayAvailability.D[0]);
        Assert.Equal(directAvailability.Cycles, overlayAvailability.Cycles);

        var directInvalidFind = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 97
        };
        var overlayInvalidFind = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 97
        };
        direct.Invoke(directInvalidFind, (int)GraphicsLvo.FindDisplayInfo);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(findAddress, overlayInvalidFind));
        Assert.Equal(0u, directInvalidFind.D[0]);
        Assert.Equal(directInvalidFind.D[0], overlayInvalidFind.D[0]);
        Assert.Equal(directInvalidFind.Cycles, overlayInvalidFind.Cycles);

        var directInvalidAvailability = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 101
        };
        var overlayInvalidAvailability = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 101
        };
        direct.Invoke(directInvalidAvailability, (int)GraphicsLvo.ModeNotAvailable);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(availabilityAddress, overlayInvalidAvailability));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoMonitor, directInvalidAvailability.D[0]);
        Assert.Equal(directInvalidAvailability.D[0], overlayInvalidAvailability.D[0]);
        Assert.Equal(directInvalidAvailability.Cycles, overlayInvalidAvailability.Cycles);

        var directInvalidData = new M68kCpuState
        {
            A = { [0] = 0, [1] = sentinelBuffer },
            D =
            {
                [0] = 0x30,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = GraphicsModeIds.Invalid
            },
            Cycles = 103
        };
        var overlayInvalidData = new M68kCpuState
        {
            A = { [0] = 0, [1] = sentinelBuffer },
            D =
            {
                [0] = 0x30,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = GraphicsModeIds.Invalid
            },
            Cycles = 103
        };
        direct.Invoke(directInvalidData, (int)GraphicsLvo.GetDisplayInfoData);
        var dataAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(dataAddress, overlayInvalidData));
        Assert.Equal(0u, directInvalidData.D[0]);
        Assert.Equal(directInvalidData.D[0], overlayInvalidData.D[0]);
        Assert.Equal(directInvalidData.Cycles, overlayInvalidData.Cycles);
        Assert.Equal((byte)0xA5, directBus.ReadByte(sentinelBuffer));
        Assert.Equal(directBus.ReadByte(sentinelBuffer), overlayBus.ReadByte(sentinelBuffer));
    }

    [Fact]
    public void RomOverlayTailChainsUnknownDisplayModeQueriesToOriginalVectors()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint unknownMode = 0xDEAD_BEEFu;
        const uint findTarget = 0x00FA_F101;
        const uint nextTarget = 0x00FA_F102;
        const uint availabilityTarget = 0x00FA_F103;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FindDisplayInfo)), findTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.NextDisplayInfo)), nextTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ModeNotAvailable)), availabilityTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var find = new M68kCpuState
        {
            D = { [0] = unknownMode },
            Cycles = 97,
            ProgramCounter = 0x0012_3501
        };
        var next = new M68kCpuState
        {
            D = { [0] = unknownMode },
            Cycles = 101,
            ProgramCounter = 0x0012_3502
        };
        var availability = new M68kCpuState
        {
            D = { [0] = unknownMode },
            Cycles = 103,
            ProgramCounter = 0x0012_3503
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FindDisplayInfo)),
            find));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.NextDisplayInfo)),
            next));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ModeNotAvailable)),
            availability));
        Assert.Equal(findTarget, find.ProgramCounter);
        Assert.Equal(nextTarget, next.ProgramCounter);
        Assert.Equal(availabilityTarget, availability.ProgramCounter);
        Assert.Equal(unknownMode, find.D[0]);
        Assert.Equal(unknownMode, next.D[0]);
        Assert.Equal(unknownMode, availability.D[0]);
        Assert.Equal(97, find.Cycles);
        Assert.Equal(101, next.Cycles);
        Assert.Equal(103, availability.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveDisplayInfoDataChunkParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint buffer = 0x400;
        const uint mode = GraphicsModeIds.PalMonitor |
                          GraphicsModeIds.HiresMode |
                          GraphicsModeIds.InterlaceMode;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        directBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        overlayBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        directBus.MapWritableMemory(buffer, new byte[0x100]);
        overlayBus.MapWritableMemory(buffer, new byte[0x100]);
        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directDisplay = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D = { [0] = GraphicsDisplayDatabase.DisplayInfoChunkSize, [1] = GraphicsDisplayDatabase.DtagDisp, [2] = mode },
            Cycles = 107
        };
        var overlayDisplay = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D = { [0] = GraphicsDisplayDatabase.DisplayInfoChunkSize, [1] = GraphicsDisplayDatabase.DtagDisp, [2] = mode },
            Cycles = 107
        };
        direct.Invoke(directDisplay, (int)GraphicsLvo.GetDisplayInfoData);
        var dataAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(dataAddress, overlayDisplay));
        Assert.Equal(48u, directDisplay.D[0]);
        Assert.Equal(directDisplay.D[0], overlayDisplay.D[0]);
        Assert.Equal(107, directDisplay.Cycles);
        Assert.Equal(directDisplay.Cycles, overlayDisplay.Cycles);
        for (var offset = 0; offset < GraphicsDisplayDatabase.DisplayInfoChunkSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(buffer + (uint)offset),
                overlayBus.ReadByte(buffer + (uint)offset));
        }

        var directDimensions = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D = { [0] = 0x58, [1] = GraphicsDisplayDatabase.DtagDims, [2] = mode },
            Cycles = 109
        };
        var overlayDimensions = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D = { [0] = 0x58, [1] = GraphicsDisplayDatabase.DtagDims, [2] = mode },
            Cycles = 109
        };
        direct.Invoke(directDimensions, (int)GraphicsLvo.GetDisplayInfoData);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(dataAddress, overlayDimensions));
        Assert.Equal(66u, directDimensions.D[0]);
        Assert.Equal(directDimensions.D[0], overlayDimensions.D[0]);
        Assert.Equal(109, directDimensions.Cycles);
        Assert.Equal(directDimensions.Cycles, overlayDimensions.Cycles);
        for (var offset = 0; offset < 0x58; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(buffer + (uint)offset),
                overlayBus.ReadByte(buffer + (uint)offset));
        }
    }

    [Fact]
    public void NativeDisplayInfoDataPublishesLocalQueryHeaderDoubleLongLength()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0x400;
        var cases = new[]
        {
            (GraphicsDisplayDatabase.DtagDisp, 0x38u, 4u),
            (GraphicsDisplayDatabase.DtagDims, 0x58u, 8u),
            (GraphicsDisplayDatabase.DtagMntr, 0x60u, 9u),
            (GraphicsDisplayDatabase.DtagName, 0x38u, 5u)
        };

        foreach (var (tag, size, expectedLength) in cases)
        {
            static uint ReadLength(
                uint imageBase,
                uint graphicsBase,
                uint mode,
                uint buffer,
                uint tag,
                uint size,
                bool overlay)
            {
                var bus = new AmigaBus();
                bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
                bus.MapWritableMemory(buffer, new byte[0x100]);
                using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
                var state = new M68kCpuState
                {
                    A = { [0] = mode, [1] = buffer },
                    D = { [0] = size, [1] = tag, [2] = mode }
                };

                if (overlay)
                {
                    Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
                    Assert.True(bus.TryInvokeHostGatewayAt(
                        unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData)),
                        state));
                }
                else
                {
                    services.Invoke(state, (int)GraphicsLvo.GetDisplayInfoData);
                }

                Assert.Equal(tag switch
                {
                    GraphicsDisplayDatabase.DtagDisp => 48u,
                    GraphicsDisplayDatabase.DtagDims => 66u,
                    GraphicsDisplayDatabase.DtagMntr => 88u,
                    _ => size
                }, state.D[0]);
                return bus.ReadLong(buffer + 12u);
            }

            Assert.Equal(
                expectedLength,
                ReadLength(imageBase, graphicsBase, mode, buffer, tag, size, overlay: false));
            Assert.Equal(
                expectedLength,
                ReadLength(imageBase, graphicsBase, mode, buffer, tag, size, overlay: true));
        }
    }

    [Fact]
    public void RomOverlayTailChainsMalformedDisplayInfoDataToOriginalVector()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint nativeTarget = 0x00FA_F201;
        const uint invalidBuffer = 0x00F0_0000;
        var image = new byte[0x2000];
