    [Fact]
    public void NativeOverlayDeclinesReadOnlyDisplayInfoDataOutputBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0x00F0_0400;
        const uint size = GraphicsDisplayDatabase.DisplayInfoChunkSize;
        const byte sentinel = 0xA5;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(buffer, Enumerable.Repeat(sentinel, (int)size).ToArray());
        // A provider/image overlay masks the caller-owned output after the
        // compatibility buffer has been established.  The portable database
        // must not turn the readable bytes into a partial native-overlay win.
        bus.MapReadOnlyMemory(
            buffer,
            Enumerable.Repeat(sentinel, (int)size).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D =
            {
                [0] = size,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = mode
            },
            Cycles = 127,
            ProgramCounter = 0x0012_3701
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData)),
            state));
        Assert.Equal(size, state.D[0]);
        Assert.Equal(127, state.Cycles);
        Assert.Equal(0x0012_3701u, state.ProgramCounter);
        for (uint offset = 0; offset < size; offset++)
            Assert.Equal(sentinel, bus.ReadByte(buffer + offset));
    }

    [Fact]
    public void NativeOverlayDisplayInfoDataAdmitsOnlyTheTransferredDispSpan()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0x00F0_0400;
        const byte sentinel = 0xA5;
        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(buffer, Enumerable.Repeat(sentinel, 56).ToArray());
        // The reserved SDK terminators are not transferred. A read-only tail
        // must not prevent admission of the writable48-byte public payload.
        bus.MapReadOnlyMemory(buffer + 48, Enumerable.Repeat(sentinel, 8).ToArray());
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        var state = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D = { [0] = uint.MaxValue, [1] = GraphicsDisplayDatabase.DtagDisp, [2] = mode },
            Cycles = 127,
            ProgramCounter = 0x0012_3701
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData)), state));
        Assert.Equal(48u, state.D[0]);
        Assert.Equal(GraphicsDisplayDatabase.DtagDisp, bus.ReadLong(buffer));
        Assert.Equal(mode, bus.ReadLong(buffer + 4));
        Assert.Equal(127, state.Cycles);
        Assert.Equal(0x0012_3701u, state.ProgramCounter);
        for (uint offset = 48; offset < 56; offset++)
            Assert.Equal(sentinel, bus.ReadByte(buffer + offset));
    }

    [Theory]
    [InlineData(27u, 26u)]
    [InlineData(33u, 26u)]
    [InlineData(41u, 34u)]
    [InlineData(65u, 58u)]
    [InlineData(66u, 66u)]
    [InlineData(uint.MaxValue, 66u)]
    public void NativeOverlayDisplayInfoDataDimsIgnoresReadOnlyUntransferredRectanglesAndTail(
        uint requested, uint transferred)
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0x00F0_0400;
        const byte sentinel = 0xA5;
        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(buffer, Enumerable.Repeat(sentinel, 88).ToArray());
        // A partial rectangle and the SDK allocation tail are not public
        // output. Neither may participate in the writable-span admission.
        bus.MapReadOnlyMemory(buffer + transferred,
            Enumerable.Repeat(sentinel, checked((int)(88 - transferred))).ToArray());
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        var state = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D = { [0] = requested, [1] = GraphicsDisplayDatabase.DtagDims, [2] = mode },
            Cycles = 127,
            ProgramCounter = 0x0012_3701
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData)), state));
        Assert.Equal(transferred, state.D[0]);
        Assert.Equal(GraphicsDisplayDatabase.DtagDims, bus.ReadLong(buffer));
        Assert.Equal(mode, bus.ReadLong(buffer + 4));
        Assert.Equal(8u, bus.ReadLong(buffer + 12));
        Assert.Equal(127, state.Cycles);
        Assert.Equal(0x0012_3701u, state.ProgramCounter);
        for (var offset = transferred; offset < 88; offset++)
            Assert.Equal(sentinel, bus.ReadByte(buffer + offset));
    }

    [Theory]
    [InlineData(88u)]
    [InlineData(96u)]
    [InlineData(uint.MaxValue)]
    public void NativeOverlayDisplayInfoDataMntrIgnoresReadOnlyTailAndRetainsResidentMonitor(uint requested)
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint buffer = 0x00F0_0400;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const byte sentinel = 0xA5;
        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        var list = graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        bus.WriteLong(graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead, list + 4);
        bus.WriteLong(graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail, 0);
        bus.WriteLong(graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred, list);
        bus.MapWritableMemory(buffer, Enumerable.Repeat(sentinel, 96).ToArray());
        bus.MapReadOnlyMemory(buffer + 88, Enumerable.Repeat(sentinel, 8).ToArray());
        var nextAllocation = 0x00600000u;
        var allocations = 0;
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus),
            graphicsLibraryBase: graphicsBase,
            allocateMemory: (bytes, flags) =>
            {
                var address = nextAllocation;
                nextAllocation += checked((uint)bytes + 0x100);
                bus.MapWritableMemory(address, new byte[bytes]);
                allocations++;
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        uint residentMonitor = 0;
        var firstAllocations = 0;
        for (var query = 0; query < 2; query++)
        {
            var state = new M68kCpuState
            {
                A = { [0] = mode, [1] = buffer },
                D = { [0] = requested, [1] = GraphicsDisplayDatabase.DtagMntr, [2] = mode },
                Cycles = 127,
                ProgramCounter = 0x0012_3701
            };
            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.GetDisplayInfoData)), state));
            Assert.Equal(88u, state.D[0]);
            Assert.Equal(GraphicsDisplayDatabase.DtagMntr, bus.ReadLong(buffer));
            Assert.Equal(GraphicsModeIds.PalMonitor, bus.ReadLong(buffer + 4));
            Assert.Equal(9u, bus.ReadLong(buffer + 12));
            var monitor = bus.ReadLong(buffer + 16);
            Assert.NotEqual(0u, monitor);
            Assert.Equal(0, bus.ReadWord(monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
            if (query == 0)
            {
                residentMonitor = monitor;
                firstAllocations = allocations;
                Assert.True(allocations > 0);
            }
            else
            {
                Assert.Equal(residentMonitor, monitor);
                Assert.Equal(firstAllocations, allocations);
            }
            Assert.Equal(127, state.Cycles);
            Assert.Equal(0x0012_3701u, state.ProgramCounter);
            for (uint offset = 88; offset < 96; offset++)
                Assert.Equal(sentinel, bus.ReadByte(buffer + offset));
        }
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyNativeMonitorListBeforeDtagMntrAllocation()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_4323;
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0x00F0_0420;
        const uint size = 0x60;
        const byte sentinel = 0xA5;
        var image = new byte[0x3000];

        static void WriteImageLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }

        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase +
                             (int)GraphicsLvo.GetDisplayInfoData)),
            nativeTarget);

        var monitorList = graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorList;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListHead -
                          imageBase)),
            monitorList + 4u);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTail -
                          imageBase)),
            0);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTailPred -
                          imageBase)),
            monitorList);
        image[checked((int)(graphicsBase +
                            (uint)GraphicsLayouts.GfxBaseMonitorListType -
                            imageBase))] = 0;
        image[checked((int)(graphicsBase +
                            (uint)GraphicsLayouts.GfxBaseMonitorListPad -
                            imageBase))] = 0;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(
            buffer,
            Enumerable.Repeat(sentinel, (int)size).ToArray());

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = buffer },
            D =
            {
                [0] = size,
                [1] = GraphicsDisplayDatabase.DtagMntr,
                [2] = mode
            },
            Cycles = 137,
            ProgramCounter = 0x0012_3705
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase +
                             (int)GraphicsLvo.GetDisplayInfoData)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(size, state.D[0]);
        Assert.Equal(137, state.Cycles);
        for (uint offset = 0; offset < size; offset++)
            Assert.Equal(sentinel, bus.ReadByte(buffer + offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyRastPortBeforeDefaultStatePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x00F0_0500;
        const byte sentinel = 0xA5;
        var compatibilityFontCalls = 0;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(
            rastPort,
            Enumerable.Repeat(sentinel, GraphicsLayouts.RastPortMinimumSize).ToArray());
        bus.MapReadOnlyMemory(
            rastPort,
            Enumerable.Repeat(sentinel, GraphicsLayouts.RastPortMinimumSize).ToArray());

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            ensureCompatibilityFont: () =>
            {
                compatibilityFontCalls++;
                return 0x00F0_0600;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 131,
            ProgramCounter = 0x0012_3703
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitRastPort)),
            state));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(131, state.Cycles);
        Assert.Equal(0x0012_3703u, state.ProgramCounter);
        Assert.Equal(0, compatibilityFontCalls);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(rastPort + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveMonitorLifecycleParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint monitorSpec = 0x1000;
        const uint displayId = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(monitorSpec, new byte[GraphicsLayouts.MonitorSpecSize]);
        }

        var directFrees = 0;
        var overlayFrees = 0;
        uint DirectAllocate(int bytes, uint memoryClass)
        {
            Assert.Equal(GraphicsLayouts.MonitorSpecSize, bytes);
            return monitorSpec;
        }

        uint OverlayAllocate(int bytes, uint memoryClass)
        {
            Assert.Equal(GraphicsLayouts.MonitorSpecSize, bytes);
            return monitorSpec;
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: DirectAllocate,
            freeMemory: (_, _) => directFrees++);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: OverlayAllocate,
            freeMemory: (_, _) => overlayFrees++);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directOpen = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = displayId },
            Cycles = 127
        };
        var overlayOpen = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = displayId },
            Cycles = 127
        };
        direct.Invoke(directOpen, (int)GraphicsLvo.OpenMonitor);
        var openAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(openAddress, overlayOpen));
        Assert.Equal(monitorSpec, directOpen.D[0]);
        Assert.Equal(directOpen.D[0], overlayOpen.D[0]);
        Assert.Equal(127, directOpen.Cycles);
        Assert.Equal(directOpen.Cycles, overlayOpen.Cycles);
        for (var offset = 0; offset < GraphicsLayouts.MonitorSpecSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(monitorSpec + (uint)offset),
                overlayBus.ReadByte(monitorSpec + (uint)offset));
        }

        var directClose = new M68kCpuState
        {
            A = { [0] = directOpen.D[0] },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 131
        };
        var overlayClose = new M68kCpuState
        {
            A = { [0] = overlayOpen.D[0] },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 131
        };
        direct.Invoke(directClose, (int)GraphicsLvo.CloseMonitor);
        var closeAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CloseMonitor));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(closeAddress, overlayClose));
        Assert.Equal(0u, directClose.D[0]);
        Assert.Equal(directClose.D[0], overlayClose.D[0]);
        Assert.Equal(131, directClose.Cycles);
        Assert.Equal(directClose.Cycles, overlayClose.Cycles);
        Assert.Equal(0, directFrees);
        Assert.Equal(directFrees, overlayFrees);
    }

    [Fact]
    public void NativeOverlayDeclinesMalformedMappedMonitorListBeforeOpenMonitorAllocation()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_F304;
        const uint displayId = GraphicsModeIds.PalMonitor;
        var image = new byte[0x3000];

        static void WriteImageLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }

        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor)),
            nativeTarget);

        // Every public MonitorList field is mapped, but the head/tailpred
        // pair is neither the empty-list sentinel nor a linked resident
        // chain. A native/provider owner must retain this malformed list;
        // the portable overlay must not allocate a MonitorSpec just to fail
        // later during list publication.
        var list = graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListHead -
                          imageBase)),
            0);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTail -
                          imageBase)),
            0);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTailPred -
                          imageBase)),
            list);
        image[checked((int)(graphicsBase +
                            (uint)GraphicsLayouts.GfxBaseMonitorListType -
                            imageBase))] = 0;
        image[checked((int)(graphicsBase +
                            (uint)GraphicsLayouts.GfxBaseMonitorListPad -
                            imageBase))] = 0;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseDefaultMonitor -
                          imageBase)),
            0);

        var allocations = 0;
        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (_, _) =>
            {
                allocations++;
                return 0x1000;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = displayId },
            Cycles = 149,
            ProgramCounter = 0x0012_3711
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(displayId, state.D[0]);
        Assert.Equal(149, state.Cycles);
        Assert.Equal(0, allocations);
    }

    [Fact]
    public void RomOverlayTailChainsForeignMonitorLifecycleRequestsToOriginalVectors()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint unknownDisplayId = 0xDEAD_BEEFu;
        const uint openTarget = 0x00FA_F301;
        const uint closeTarget = 0x00FA_F302;
        const uint invalidMonitorSpec = 0x00F0_0000;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor)), openTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CloseMonitor)), closeTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var open = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = unknownDisplayId },
            Cycles = 137,
            ProgramCounter = 0x0012_3701
        };
        var close = new M68kCpuState
        {
            A = { [0] = invalidMonitorSpec },
            D = { [0] = 0x1234_5678u },
            Cycles = 139,
            ProgramCounter = 0x0012_3702
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor)),
            open));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CloseMonitor)),
            close));
        Assert.Equal(openTarget, open.ProgramCounter);
        Assert.Equal(closeTarget, close.ProgramCounter);
        Assert.Equal(unknownDisplayId, open.D[0]);
        Assert.Equal(0x1234_5678u, close.D[0]);
        Assert.Equal(137, open.Cycles);
        Assert.Equal(139, close.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveModeSelectionParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint tags = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        const uint displayId = GraphicsModeIds.PalMonitor;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(tags, new byte[0x60]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);

            bus.WriteLong(tags + 0, GraphicsDisplayDatabase.BidTagNominalWidth);
            bus.WriteLong(tags + 4, 640);
            bus.WriteLong(tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight);
            bus.WriteLong(tags + 12, 200);
            bus.WriteLong(tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth);
            bus.WriteLong(tags + 20, 640);
            bus.WriteLong(tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight);
            bus.WriteLong(tags + 28, 200);
            bus.WriteLong(tags + 32, GraphicsDisplayDatabase.BidTagDepth);
            bus.WriteLong(tags + 36, 5);
            bus.WriteLong(tags + 40, GraphicsDisplayDatabase.BidTagMonitorId);
            bus.WriteLong(tags + 44, displayId);
            bus.WriteLong(tags + 48, 0);

            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
            bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
            bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directBest = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 149
        };
        var overlayBest = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 149
        };
        direct.Invoke(directBest, (int)GraphicsLvo.BestModeIDA);
        var bestAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BestModeIDA));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(bestAddress, overlayBest));
        // The five-plane request cannot select four-plane OCS/ECS hires.
        Assert.Equal(GraphicsModeIds.PalMonitor, directBest.D[0]);
        Assert.Equal(directBest.D[0], overlayBest.D[0]);
        Assert.Equal(149, directBest.Cycles);
        Assert.Equal(directBest.Cycles, overlayBest.Cycles);

        var directCoerce = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = displayId, [1] = GraphicsDisplayDatabase.CoercePreserveColors },
            Cycles = 151
        };
        var overlayCoerce = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = displayId, [1] = GraphicsDisplayDatabase.CoercePreserveColors },
            Cycles = 151
        };
        direct.Invoke(directCoerce, (int)GraphicsLvo.CoerceMode);
        var coerceAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CoerceMode));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(coerceAddress, overlayCoerce));
        Assert.Equal(GraphicsModeIds.PalMonitor, directCoerce.D[0]);
        Assert.Equal(directCoerce.D[0], overlayCoerce.D[0]);
        Assert.Equal(151, directCoerce.Cycles);
        Assert.Equal(directCoerce.Cycles, overlayCoerce.Cycles);

        // A well-formed native request can have no matching record.  The
        // portable adapter owns that result and publishes INVALID_ID through
        // both the direct host entry point and the ROM-overlay gateway; the
        // provider fallback is reserved for malformed/foreign requests.
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.WriteLong(tags + 36, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8, 0);
        }

        var directNoMatchBest = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 173
        };
        var overlayNoMatchBest = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 173
        };
        direct.Invoke(directNoMatchBest, (int)GraphicsLvo.BestModeIDA);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(bestAddress, overlayNoMatchBest));
        Assert.Equal(GraphicsModeIds.Invalid, directNoMatchBest.D[0]);
        Assert.Equal(directNoMatchBest.D[0], overlayNoMatchBest.D[0]);
        Assert.Equal(173, directNoMatchBest.Cycles);
        Assert.Equal(directNoMatchBest.Cycles, overlayNoMatchBest.Cycles);

        var directNoMatchCoerce = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = displayId, [1] = GraphicsDisplayDatabase.CoercePreserveColors },
            Cycles = 179
        };
        var overlayNoMatchCoerce = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = displayId, [1] = GraphicsDisplayDatabase.CoercePreserveColors },
            Cycles = 179
        };
        direct.Invoke(directNoMatchCoerce, (int)GraphicsLvo.CoerceMode);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(coerceAddress, overlayNoMatchCoerce));
        Assert.Equal(GraphicsModeIds.Invalid, directNoMatchCoerce.D[0]);
        Assert.Equal(directNoMatchCoerce.D[0], overlayNoMatchCoerce.D[0]);
        Assert.Equal(179, directNoMatchCoerce.Cycles);
        Assert.Equal(directNoMatchCoerce.Cycles, overlayNoMatchCoerce.Cycles);
    }

    [Fact]
    public void NativeOverlayAcceptsAndRejectsModeTagBoundariesWithoutFrameDrift()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint validTags = 0xFFFF_FFF8u;
        const uint malformedTags = 0xFFFF_FFFEu;
        const uint nativeTarget = 0x00FA_F501;
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BestModeIDA)),
            nativeTarget);

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(validTags, new byte[8]);
            bus.WriteLong(validTags, 0);
            bus.WriteLong(validTags + 4u, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directValid = new M68kCpuState
        {
            A = { [0] = validTags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 223
        };
        var overlayValid = new M68kCpuState
        {
            A = { [0] = validTags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 223
        };
        direct.Invoke(directValid, (int)GraphicsLvo.BestModeIDA);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BestModeIDA)),
            overlayValid));
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.HiresMode,
            directValid.D[0]);
        Assert.Equal(directValid.D[0], overlayValid.D[0]);
        Assert.Equal(223, directValid.Cycles);
        Assert.Equal(directValid.Cycles, overlayValid.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = malformedTags },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 227,
            ProgramCounter = 0x0012_3A01
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BestModeIDA)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0xDEAD_BEEFu, malformed.D[0]);
        Assert.Equal(227, malformed.Cycles);

        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.WriteLong(validTags, GraphicsDisplayDatabase.BidTagNominalWidth);
            bus.WriteLong(validTags + 4u, 640);
        }

        var directWrapped = new M68kCpuState
        {
            A = { [0] = validTags },
            D = { [0] = 0x1234_5678u },
            Cycles = 229,
            ProgramCounter = 0x0012_3A11
        };
        direct.Invoke(directWrapped, (int)GraphicsLvo.BestModeIDA);
        Assert.Equal(0x1234_5678u, directWrapped.D[0]);
        Assert.Equal(229, directWrapped.Cycles);

        var overlayWrapped = new M68kCpuState
        {
            A = { [0] = validTags },
            D = { [0] = 0x1234_5678u },
            Cycles = 229,
            ProgramCounter = 0x0012_3A11
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BestModeIDA)),
            overlayWrapped));
        Assert.Equal(nativeTarget, overlayWrapped.ProgramCounter);
        Assert.Equal(0x1234_5678u, overlayWrapped.D[0]);
        Assert.Equal(229, overlayWrapped.Cycles);
    }

