        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        const uint makeTarget = 0x00FA_AAAA;
        const uint mergeTarget = 0x00FA_BBBB;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MakeVPort)), makeTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MrgCop)), mergeTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);

        var makeCalls = 0;
        var mergeCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            makeViewPort: _ =>
            {
                makeCalls++;
                return 0;
            },
            mergeCopperLists: _ =>
            {
                mergeCalls++;
                return 0;
            },
            isRtgBitMap: address => address == bitMap);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var make = new M68kCpuState
        {
            A = { [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 71,
            ProgramCounter = 0x0012_3456
        };
        var merge = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 83,
            ProgramCounter = 0x0076_5432
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MakeVPort)), make));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MrgCop)), merge));
        Assert.Equal(0, makeCalls);
        Assert.Equal(0, mergeCalls);
        Assert.Equal(makeTarget, make.ProgramCounter);
        Assert.Equal(mergeTarget, merge.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, make.D[0]);
        Assert.Equal(0x1357_9BDFu, merge.D[0]);
        Assert.Equal(71, make.Cycles);
        Assert.Equal(83, merge.Cycles);
    }

    [Fact]
    public void RomOverlayTailChainsRtgFreeViewportTeardownAndMalformedFreeCprList()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x100;
        const uint rasInfo = 0x180;
        const uint bitMap = 0x200;
        const uint freeViewPortTarget = 0x00FA_CCCC;
        const uint freeCprTarget = 0x00FA_DDDD;
        const uint malformedCprList = uint.MaxValue - 4u;
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeVPortCopLists)),
            freeViewPortTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCprList)),
            freeCprTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);

        var freeViewPortCalls = 0;
        var freeCprCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            freeVPortCopLists: _ => freeViewPortCalls++,
            freeCprList: _ => freeCprCalls++,
            isRtgBitMap: address => address == bitMap);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var freeViewPort = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 71,
            ProgramCounter = 0x0012_3456
        };
        var freeCpr = new M68kCpuState
        {
            A = { [0] = malformedCprList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 83,
            ProgramCounter = 0x0076_5432
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeVPortCopLists)),
            freeViewPort));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCprList)),
            freeCpr));
        Assert.Equal(0, freeViewPortCalls);
        Assert.Equal(0, freeCprCalls);
        Assert.Equal(freeViewPortTarget, freeViewPort.ProgramCounter);
        Assert.Equal(freeCprTarget, freeCpr.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, freeViewPort.D[0]);
        Assert.Equal(0x1357_9BDFu, freeCpr.D[0]);
        Assert.Equal(71, freeViewPort.Cycles);
        Assert.Equal(83, freeCpr.Cycles);

        const uint oddCprList = 0x300;
        bus.MapWritableMemory(oddCprList, new byte[GraphicsLayouts.CprListSize]);
        var oddFreeCpr = new M68kCpuState
        {
            A = { [0] = oddCprList + 1 },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 97,
            ProgramCounter = 0x0076_5498
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCprList)),
            oddFreeCpr));
        Assert.Equal(0, freeCprCalls);
        Assert.Equal(freeCprTarget, oddFreeCpr.ProgramCounter);
        Assert.Equal(0x2468_ACE0u, oddFreeCpr.D[0]);
        Assert.Equal(97, oddFreeCpr.Cycles);
    }

    [Fact]
    public void NativeOverlayLeavesLegacyFreeVPortCopListsOwnerToKickstart()
    {
        const uint imageBase = 0x00F8_E000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x00FA_0100;
        const uint freeTarget = 0x00FA_EEEE;
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase +
                (int)GraphicsLvo.FreeVPortCopLists)),
            freeTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        var links = new[]
        {
            (GraphicsLayouts.ViewPortDspIns, 0x400u),
            (GraphicsLayouts.ViewPortSprIns, 0x404u),
            (GraphicsLayouts.ViewPortClrIns, 0x408u),
            (GraphicsLayouts.ViewPortUCopIns, 0x40Cu)
        };
        foreach (var (offset, value) in links)
            bus.WriteLong(viewPort + (uint)offset, value);

        var freeCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            freeVPortCopLists: _ => freeCalls++);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 71,
            ProgramCounter = 0x0076_5432
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase +
                (int)GraphicsLvo.FreeVPortCopLists)),
            state));
        Assert.Equal(freeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(71, state.Cycles);
        Assert.Equal(0, freeCalls);
        foreach (var (offset, value) in links)
            Assert.Equal(value, bus.ReadLong(viewPort + (uint)offset));
    }

