    [Fact]
    public void RomOverlayTailChainsUnboundUserCopperOperationsToOriginalKickstartVectors()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint initTarget = 0x00FA_E001;
        const uint moveTarget = 0x00FA_E002;
        const uint waitTarget = 0x00FA_E003;
        const uint bumpTarget = 0x00FA_E004;
        const uint freeTarget = 0x00FA_E005;
        var image = new byte[0x2000];
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.UCopperListInit)), initTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CMove)), moveTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CWait)), waitTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CBump)), bumpTarget);
        WriteJmp(image, imageBase, unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCopList)), freeTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var init = new M68kCpuState
        {
            A = { [0] = 0x100 },
            D = { [0] = 2 },
            Cycles = 41,
            ProgramCounter = 0x0010_0001
        };
        var move = new M68kCpuState
        {
            A = { [1] = 0x100 },
            D = { [0] = 0x180, [1] = 0x1234 },
            Cycles = 43,
            ProgramCounter = 0x0010_0002
        };
        var wait = new M68kCpuState
        {
            A = { [1] = 0x100 },
            D = { [0] = 42, [1] = 12 },
            Cycles = 47,
            ProgramCounter = 0x0010_0003
        };
        var bump = new M68kCpuState
        {
            A = { [1] = 0x100 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 53,
            ProgramCounter = 0x0010_0004
        };
        var free = new M68kCpuState
        {
            A = { [0] = 0x100 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 59,
            ProgramCounter = 0x0010_0005
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.UCopperListInit)),
            init));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CMove)),
            move));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CWait)),
            wait));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CBump)),
            bump));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.FreeCopList)),
            free));

        Assert.Equal(initTarget, init.ProgramCounter);
        Assert.Equal(moveTarget, move.ProgramCounter);
        Assert.Equal(waitTarget, wait.ProgramCounter);
        Assert.Equal(bumpTarget, bump.ProgramCounter);
        Assert.Equal(freeTarget, free.ProgramCounter);
        Assert.Equal(2u, init.D[0]);
        Assert.Equal(0x180u, move.D[0]);
        Assert.Equal(42u, wait.D[0]);
        Assert.Equal(0xCAFE_BABEu, bump.D[0]);
        Assert.Equal(0x1357_9BDFu, free.D[0]);
        Assert.Equal(41, init.Cycles);
        Assert.Equal(43, move.Cycles);
        Assert.Equal(47, wait.Cycles);
        Assert.Equal(53, bump.Cycles);
        Assert.Equal(59, free.Cycles);
    }

