        };

        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(509, state.Cycles);
    }

