    [Fact]
    public void RomOverlayInitVPortRunsProjectionOnlyAfterGuardedGuestInitialization()
    {
        var bus = new AmigaBus();
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint viewPort = 0x100;
        var image = new byte[0x2000];
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        var projectionCount = 0;
        var projected = 0u;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            initializeCompatibilityViewPort: address =>
            {
                projectionCount++;
                projected = address;
            });

        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitVPort));
        var valid = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xDEAD_BEEFu }
        };
        Assert.True(bus.TryInvokeHostGatewayAt(address, valid));
        Assert.Equal(1, projectionCount);
        Assert.Equal(viewPort, projected);
        Assert.Equal(0u, valid.D[0]);
        Assert.Equal(0x24, bus.ReadByte(
            viewPort + (uint)GraphicsLayouts.ViewPortSpritePriorities));

        var invalid = new M68kCpuState
        {
            A = { [0] = 0x00FF_0000 },
            D = { [0] = 0xCAFE_BABEu }
        };
        Assert.True(bus.TryInvokeHostGatewayAt(address, invalid));
        Assert.Equal(1, projectionCount);
        Assert.Equal(0xCAFE_BABEu, invalid.D[0]);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyViewInitializersBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x00F0_0700;
        const uint viewPort = 0x00F0_0800;
        const byte viewSentinel = 0xA5;
        const byte viewPortSentinel = 0xB6;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(
            view,
            Enumerable.Repeat(viewSentinel, GraphicsLayouts.ViewSize).ToArray());
        bus.MapReadOnlyMemory(
            view,
            Enumerable.Repeat(viewSentinel, GraphicsLayouts.ViewSize).ToArray());
        bus.MapWritableMemory(
            viewPort,
            Enumerable.Repeat(viewPortSentinel, GraphicsLayouts.ViewPortSize).ToArray());
        bus.MapReadOnlyMemory(
            viewPort,
            Enumerable.Repeat(viewPortSentinel, GraphicsLayouts.ViewPortSize).ToArray());

        var projectionCount = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            initializeCompatibilityViewPort: _ => projectionCount++);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var viewState = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 137,
            ProgramCounter = 0x0012_3705
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitView)),
            viewState));
        Assert.Equal(0xCAFE_BABEu, viewState.D[0]);
        Assert.Equal(137, viewState.Cycles);
        Assert.Equal(0x0012_3705u, viewState.ProgramCounter);

        var viewPortState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 139,
            ProgramCounter = 0x0012_3707
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitVPort)),
            viewPortState));
        Assert.Equal(0x1357_9BDFu, viewPortState.D[0]);
        Assert.Equal(139, viewPortState.Cycles);
        Assert.Equal(0x0012_3707u, viewPortState.ProgramCounter);
        Assert.Equal(0, projectionCount);

        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.Equal(viewSentinel, bus.ReadByte(view + (uint)offset));
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            Assert.Equal(viewPortSentinel, bus.ReadByte(viewPort + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveViewStructureInitializationParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
                bus.WriteByte(view + (uint)offset, (byte)(0x40 + offset), 0);
            for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
                bus.WriteByte(viewPort + (uint)offset, (byte)(0x80 + offset), 0);
        }

        var directProjectionCount = 0;
        var overlayProjectionCount = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            initializeCompatibilityViewPort: _ => directProjectionCount++);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            initializeCompatibilityViewPort: _ => overlayProjectionCount++);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directView = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 181
        };
        var overlayView = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 181
        };
        direct.Invoke(directView, (int)GraphicsLvo.InitView);
        var viewAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitView));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(viewAddress, overlayView));
        Assert.Equal(0u, directView.D[0]);
        Assert.Equal(directView.D[0], overlayView.D[0]);
        Assert.Equal(directView.Cycles, overlayView.Cycles);
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(view + (uint)offset),
                overlayBus.ReadByte(view + (uint)offset));
        }

        var directViewPort = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 183
        };
        var overlayViewPort = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 183
        };
        direct.Invoke(directViewPort, (int)GraphicsLvo.InitVPort);
        var viewPortAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.InitVPort));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(viewPortAddress, overlayViewPort));
        Assert.Equal(0u, directViewPort.D[0]);
        Assert.Equal(directViewPort.D[0], overlayViewPort.D[0]);
        Assert.Equal(directViewPort.Cycles, overlayViewPort.Cycles);
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(viewPort + (uint)offset),
                overlayBus.ReadByte(viewPort + (uint)offset));
        }

        Assert.Equal(1, directProjectionCount);
        Assert.Equal(directProjectionCount, overlayProjectionCount);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveLoadViewLifecycleParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        const uint plane = 0x0080_0000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[2]);

            bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 1);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
            bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
            bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        }

        var directPublishCount = 0;
        var directPublishedView = 0u;
        var directPublishedCycle = 0L;
        var overlayPublishCount = 0;
        var overlayPublishedView = 0u;
        var overlayPublishedCycle = 0L;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            loadView: state =>
            {
                directPublishCount++;
                directPublishedView = state.A[1];
                directPublishedCycle = state.Cycles;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            loadView: state =>
            {
                overlayPublishCount++;
                overlayPublishedView = state.A[1];
                overlayPublishedCycle = state.Cycles;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        void InvokeBoth(uint requestedView, long cycles)
        {
            var directState = new M68kCpuState
            {
                A = { [1] = requestedView },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = cycles
            };
            var overlayState = new M68kCpuState
            {
                A = { [1] = requestedView },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = cycles
            };

            direct.Invoke(directState, (int)GraphicsLvo.LoadView);
            var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.LoadView));
            Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
            Assert.Equal(0u, directState.D[0]);
            Assert.Equal(directState.D[0], overlayState.D[0]);
            Assert.Equal(directState.Cycles, overlayState.Cycles);
        }

        InvokeBoth(view, 101);
        Assert.Equal(1, directPublishCount);
        Assert.Equal(1, overlayPublishCount);
        Assert.Equal(view, directPublishedView);
        Assert.Equal(view, overlayPublishedView);
        Assert.Equal(101, directPublishedCycle);
        Assert.Equal(101, overlayPublishedCycle);

        // The same validated View/signature is idempotent and must not be
        // republished through either the host dispatch or mapped jump table.
        InvokeBoth(view, 103);
        Assert.Equal(1, directPublishCount);
        Assert.Equal(1, overlayPublishCount);

        // A NULL View is the explicit blank transition and is published once
        // before subsequent identical blank requests become no-ops.
        InvokeBoth(0, 107);
        Assert.Equal(2, directPublishCount);
        Assert.Equal(2, overlayPublishCount);
        Assert.Equal(0u, directPublishedView);
        Assert.Equal(0u, overlayPublishedView);
        Assert.Equal(107, directPublishedCycle);
        Assert.Equal(107, overlayPublishedCycle);

        InvokeBoth(0, 109);
        Assert.Equal(2, directPublishCount);
        Assert.Equal(2, overlayPublishCount);
    }

    [Fact]
    public void NativeOverlayLoadViewPreservesReadOnlyGfxBaseForProviderFallback()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_4321;
        const uint originalActiveView = 0xDEAD_BEEF;
        const uint validView = 0x00FB_0000;
        var image = new byte[0x3000];

        static void WriteImageLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }

        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.LoadView)),
            nativeTarget);

        var monitorList = graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorList;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListHead -
                          imageBase)),
            monitorList + 4u);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTail -
                          imageBase)),
            0);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTailPred -
                          imageBase)),
            monitorList);
        var typeOffset = checked((int)(graphicsBase +
                                       (uint)GraphicsLayouts.GfxBaseMonitorListType -
                                       imageBase));
        var padOffset = checked((int)(graphicsBase +
                                      (uint)GraphicsLayouts.GfxBaseMonitorListPad -
                                      imageBase));
        image[typeOffset] = 0;
        image[padOffset] = 0;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseActiView -
                          imageBase)),
            originalActiveView);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 421,
            ProgramCounter = 0x0012_3891
        };
        var vectorAddress = unchecked((uint)(
            (int)graphicsBase + (int)GraphicsLvo.LoadView));

        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(421, state.Cycles);
        Assert.Equal(originalActiveView,
            bus.ReadLong(graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));

        // The same resident/provider-owned GfxBase must remain authoritative
        // for a valid non-NULL View.  A read-only native sidecar is not a
        // portable publication target, even when the View itself is a
        // perfectly addressable empty compatibility envelope.
        bus.MapWritableMemory(validView, new byte[GraphicsLayouts.ViewSize]);
        var validState = new M68kCpuState
        {
            A = { [1] = validView },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 433,
            ProgramCounter = 0x0012_3999
        };

        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, validState));
        Assert.Equal(nativeTarget, validState.ProgramCounter);
        Assert.Equal(0x2468_ACEDu, validState.D[0]);
        Assert.Equal(433, validState.Cycles);
        Assert.Equal(originalActiveView,
            bus.ReadLong(graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));
    }

    [Fact]
    public void NativeOverlayLoadViewAndChipRevisionLeaveMalformedMappedGfxBaseToNativeVector()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_4321;
        const uint chipTarget = 0x00FA_5432;
        const uint originalActiveView = 0xDEAD_BEEF;
        const uint validView = 0x00FB_0000;
        var image = new byte[0x3000];

        static void WriteImageLong(byte[] bytes, int offset, uint value)
        {
            bytes[offset] = unchecked((byte)(value >> 24));
            bytes[offset + 1] = unchecked((byte)(value >> 16));
            bytes[offset + 2] = unchecked((byte)(value >> 8));
            bytes[offset + 3] = unchecked((byte)value);
        }

        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.LoadView)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetChipRev)),
            chipTarget);

        var monitorList = graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorList;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListHead -
                          imageBase)),
            monitorList + 4u);
        // Keep every public MonitorList field mapped, but make the resident
        // list structurally invalid. This is a provider-owned envelope, not
        // the compact zero-filled compatibility suffix.
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTail -
                          imageBase)),
            0x0012_3456u);
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorListTailPred -
                          imageBase)),
            monitorList);
        var typeOffset = checked((int)(graphicsBase +
                                       (uint)GraphicsLayouts.GfxBaseMonitorListType -
                                       imageBase));
        var padOffset = checked((int)(graphicsBase +
                                      (uint)GraphicsLayouts.GfxBaseMonitorListPad -
                                      imageBase));
        image[typeOffset] = 0;
        image[padOffset] = 0;
        WriteImageLong(
            image,
            checked((int)(graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseActiView -
                          imageBase)),
            originalActiveView);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(validView, new byte[GraphicsLayouts.ViewSize]);
        var chipCallbackCount = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            setChipRev: requestedBits =>
            {
                chipCallbackCount++;
                return requestedBits;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [1] = validView },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 433,
            ProgramCounter = 0x0012_3999
        };
        var vectorAddress = unchecked((uint)(
            (int)graphicsBase + (int)GraphicsLvo.LoadView));

        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x2468_ACEDu, state.D[0]);
        Assert.Equal(433, state.Cycles);
        Assert.Equal(originalActiveView,
            bus.ReadLong(graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));

        var chipState = new M68kCpuState
        {
            D = { [0] = GraphicsChipRevision.SetBest },
            Cycles = 449,
            ProgramCounter = 0x0012_3AAA
        };
        var chipVectorAddress = unchecked((uint)(
            (int)graphicsBase + (int)GraphicsLvo.SetChipRev));

        Assert.True(bus.TryInvokeHostGatewayAt(chipVectorAddress, chipState));
        Assert.Equal(0, chipCallbackCount);
        Assert.Equal(chipTarget, chipState.ProgramCounter);
        Assert.Equal(GraphicsChipRevision.SetBest, chipState.D[0]);
        Assert.Equal(449, chipState.Cycles);
    }

