            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(firstRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
            bus.MapWritableMemory(extraRasInfo, new byte[GraphicsLayouts.RasInfoSize]);

            // Modes = 0 is the single-playfield form.  A non-null tail is
            // therefore malformed even though both nodes are readable.
            bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
            bus.WriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, extraRasInfo);
            bus.WriteLong(extraRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        }

        var directPublishCount = 0;
        var overlayPublishCount = 0;
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            loadView: _ => directPublishCount++);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            loadView: _ => overlayPublishCount++);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 409
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 409
        };

        direct.Invoke(directState, (int)GraphicsLvo.LoadView);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.LoadView));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(0xDEAD_BEEFu, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(409, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(0, directPublishCount);
        Assert.Equal(directPublishCount, overlayPublishCount);

        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
        {
            Assert.Equal(
                directBus.ReadByte(view + (uint)offset),
                overlayBus.ReadByte(view + (uint)offset));
        }
    }

    [Fact]
    public void RomOverlayForwardsRtgLoadViewToTheProviderBoundary()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);

        var providerCalls = 0;
        var providerView = 0u;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            loadView: state =>
            {
                providerCalls++;
                providerView = state.A[1];
            },
            isRtgBitMap: address => address == bitMap);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 127
        };
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.LoadView));
        Assert.True(bus.TryInvokeHostGatewayAt(address, state));
        Assert.Equal(1, providerCalls);
        Assert.Equal(view, providerView);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(127, state.Cycles);
    }

    [Fact]
    public void RomOverlayUsesStatusAwareRtgLoadViewProviderBeforeTailChaining()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_4321;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        var vectorAddress = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.LoadView));
        var offset = checked((int)(vectorAddress - imageBase));
        image[offset] = 0x4E;
        image[offset + 1] = 0xF9;
        image[offset + 2] = unchecked((byte)(nativeTarget >> 24));
        image[offset + 3] = unchecked((byte)(nativeTarget >> 16));
        image[offset + 4] = unchecked((byte)(nativeTarget >> 8));
        image[offset + 5] = unchecked((byte)nativeTarget);
        var activeViewOffset = checked(
            (int)(graphicsBase - imageBase) + GraphicsLayouts.GfxBaseActiView);
        image[activeViewOffset] = unchecked((byte)(view >> 24));
        image[activeViewOffset + 1] = unchecked((byte)(view >> 16));
        image[activeViewOffset + 2] = unchecked((byte)(view >> 8));
        image[activeViewOffset + 3] = unchecked((byte)view);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);

        var calls = 0;
        var providerView = uint.MaxValue;
        var accept = false;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            tryLoadView: callbackState =>
            {
                calls++;
                providerView = callbackState.A[1];
                if (!accept)
                {
                    // A provider may have used a scratch register/cycle while
                    // deciding to decline; the adapter must restore the
                    // classic call state before native tail chaining.
                    callbackState.D[0] = 0;
                    callbackState.Cycles += 9;
                }
                return accept;
            },
            isRtgBitMap: address => address == bitMap);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var declined = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 71,
            ProgramCounter = 0x0012_3456
        };
        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, declined));
        Assert.Equal(1, calls);
        Assert.Equal(nativeTarget, declined.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, declined.D[0]);
        Assert.Equal(71, declined.Cycles);

        accept = true;
        var accepted = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 73,
            ProgramCounter = 0x0076_5432
        };
        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, accepted));
        Assert.Equal(2, calls);
        Assert.Equal(0x0076_5432u, accepted.ProgramCounter);
        Assert.Equal(0u, accepted.D[0]);
        Assert.Equal(73, accepted.Cycles);

        var blank = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 79,
            ProgramCounter = 0x0087_6543
        };
        Assert.True(bus.TryInvokeHostGatewayAt(vectorAddress, blank));
        Assert.Equal(3, calls);
        Assert.Equal(0u, providerView);
        Assert.Equal(0x0087_6543u, blank.ProgramCounter);
        Assert.Equal(0u, blank.D[0]);
        Assert.Equal(79, blank.Cycles);
    }

    [Fact]
    public void NativeGraphicsImageBuilderWritesGuestGfxBaseAndAllVectorSlots()
    {
        const uint libraryBase = 0x0020_0000;
        const uint residentAddress = 0x0030_0000;
        const uint libraryInit = 0x0010_1000;
        const uint fallback = 0x0010_2000;
        var entryPoints = new Dictionary<GraphicsLvo, uint>();
        var nextEntry = 0x0010_0000u;
        foreach (var vector in Enum.GetValues<GraphicsLvo>())
        {
            entryPoints.Add(vector, nextEntry);
            nextEntry += 2;
        }

        var image = NativeGraphicsLibraryImageBuilder.Build(
            libraryBase,
            residentAddress,
            libraryInit,
            entryPoints,
            fallback);

        Assert.Equal(NativeGraphicsLibraryImageBuilder.VectorSlotCount, image.VectorBytes.Length / 6);
        Assert.Equal(libraryBase - (uint)image.VectorBytes.Length, image.VectorBase);
        Assert.Equal((ushort)0x4EF9, ReadImageWord(image.VectorBytes, VectorOffset(GraphicsLvo.InitRastPort)));
        Assert.Equal(entryPoints[GraphicsLvo.InitRastPort], ReadImageLong(image.VectorBytes, VectorOffset(GraphicsLvo.InitRastPort) + 2));
        // -648 is a reserved gap in the public V40 manifest and must still
        // have an explicit, deterministic native target.
        Assert.Equal((ushort)0x4EF9, ReadImageWord(image.VectorBytes, VectorOffset(-648)));
        Assert.Equal(fallback, ReadImageLong(image.VectorBytes, VectorOffset(-648) + 2));

        Assert.Equal(libraryBase + (uint)GraphicsLibraryImageLayout.DefaultNameOffset, ReadImageLong(image.PositiveBytes, 0x0A));
        Assert.Equal(libraryBase + (uint)GraphicsLibraryImageLayout.DefaultIdStringOffset, ReadImageLong(image.PositiveBytes, 0x18));
        Assert.Equal((byte)9, image.PositiveBytes[0x08]);
        Assert.Equal((ushort)NativeGraphicsLibraryImageBuilder.VectorTableSize, ReadImageWord(image.PositiveBytes, 0x10));
        Assert.Equal((ushort)NativeGraphicsLibraryImageBuilder.PositiveImageSize, ReadImageWord(image.PositiveBytes, 0x12));
        Assert.Equal(libraryBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail, ReadImageLong(image.PositiveBytes, GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(libraryBase + (uint)GraphicsLayouts.GfxBaseTextFonts, ReadImageLong(image.PositiveBytes, GraphicsLayouts.GfxBaseTextFontsTailPred));
    }

    [Fact]
    public void FullNativeGfxBaseImageInitializesTheOptionalMonitorListEnvelope()
    {
        const uint libraryBase = 0x0020_0000;
        var image = GraphicsLibraryImageLayout.CreateGuestImage(
            libraryBase,
            GraphicsLayouts.GfxBaseNativeSize,
            reportedNegativeSize: 0,
            reportedPositiveSize: GraphicsLayouts.GfxBaseNativeSize,
            version: 40,
            revision: 1,
            name: "graphics.library",
            idString: "graphics.library 40.1");

        var list = libraryBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.Equal(
            list + 4u,
            ReadImageLong(image, GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            0u,
            ReadImageLong(image, GraphicsLayouts.GfxBaseMonitorListTail));
        Assert.Equal(
            list,
            ReadImageLong(image, GraphicsLayouts.GfxBaseMonitorListTailPred));
        Assert.Equal((byte)0, image[GraphicsLayouts.GfxBaseMonitorListType]);
        Assert.Equal((byte)0, image[GraphicsLayouts.GfxBaseMonitorListPad]);
    }

