    [Fact]
    public void NativeGraphicsResidentImageCarriesAutoinitAndFunctionArray()
    {
        var entryPoints = Enum.GetValues<GraphicsLvo>()
            .ToDictionary(vector => vector, _ => 0x0010_0004u);
        entryPoints[GraphicsLvo.InitRastPort] = 0x0010_0002;
        const uint libraryBase = 0x0020_0000;
        const uint residentAddress = 0x0030_0000;
        const uint fallback = 0x0010_2000;
        var image = NativeGraphicsLibraryImageBuilder.Build(
            libraryBase,
            residentAddress,
            libraryInitAddress: 0x0010_1000,
            entryPoints: entryPoints,
            unimplementedEntry: fallback);

        Assert.Equal((ushort)0x4AFC, ReadImageWord(image.ResidentBytes, 0));
        Assert.Equal(residentAddress, ReadImageLong(image.ResidentBytes, 0x02));
        Assert.Equal(residentAddress + (uint)image.ResidentBytes.Length, ReadImageLong(image.ResidentBytes, 0x06));
        Assert.Equal((byte)0x80, image.ResidentBytes[0x0A]); // RTF_AUTOINIT
        Assert.Equal((byte)9, image.ResidentBytes[0x0C]); // NT_LIBRARY
        Assert.Equal(residentAddress + 0x50u, ReadImageLong(image.ResidentBytes, 0x16));
        Assert.Equal((uint)NativeGraphicsLibraryImageBuilder.PositiveImageSize, ReadImageLong(image.ResidentBytes, 0x50));
        Assert.Equal(image.FunctionArrayAddress, ReadImageLong(image.ResidentBytes, 0x54));
        Assert.Equal(0x0010_0002u, ReadImageLong(image.ResidentBytes, VectorArrayOffset(GraphicsLvo.InitRastPort)));
        Assert.Equal(0xFFFF_FFFFu, ReadImageLong(image.ResidentBytes, 0x60 + (NativeGraphicsLibraryImageBuilder.VectorSlotCount * 4)));
    }

    [Fact]
    public void NativeGraphicsImageBuilderRejectsImplicitOrOddNativeTargets()
    {
        var entries = Enum.GetValues<GraphicsLvo>()
            .ToDictionary(vector => vector, _ => 0x0010_0002u);
        entries[GraphicsLvo.InitRastPort] = 0x0010_0001;

        Assert.Throws<ArgumentException>(() => NativeGraphicsLibraryImageBuilder.Build(
            0x0020_0000,
            0x0030_0000,
            0x0010_1000,
            entries,
            0x0010_2000));
        Assert.Throws<ArgumentException>(() => NativeGraphicsLibraryImageBuilder.Build(
            0x0020_0000,
            0x0030_0000,
            0x0010_1000,
            new Dictionary<GraphicsLvo, uint>(),
            0));
        Assert.Throws<ArgumentException>(() => NativeGraphicsLibraryImageBuilder.Build(
            0x0020_0000,
            0x0030_0000,
            0x0010_1000,
            new Dictionary<GraphicsLvo, uint>(),
            0x0010_2000));
    }

    [Fact]
    public void NativeGraphicsCodeBuildAuditsAllSignedWordBranches()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _,
            out var audit);

        Assert.NotEmpty(nativeCode);
        Assert.True(audit.BranchCount > 0);
        Assert.All(
            audit.FragmentBoundaries,
            boundary =>
            {
                Assert.False(string.IsNullOrWhiteSpace(boundary.Name));
                Assert.Equal(0, boundary.Offset & 1);
                Assert.InRange(boundary.Offset, 0, nativeCode.Length - 2);
            });
        Assert.Equal(audit.BranchCount, audit.Patches.Count);
        Assert.All(
            audit.Patches,
            patch => Assert.InRange(
                patch.Displacement,
                (int)short.MinValue,
                (int)short.MaxValue));
        Assert.All(
            audit.Patches,
            patch => Assert.InRange(patch.TargetOffset, 0, nativeCode.Length - 2));
        Assert.InRange(
            audit.MinimumDisplacement,
            (int)short.MinValue,
            (int)short.MaxValue);
        Assert.InRange(
            audit.MaximumDisplacement,
            (int)short.MinValue,
            (int)short.MaxValue);
        Assert.InRange(
            audit.MaximumAbsoluteDisplacement,
            0,
            (int)short.MaxValue);
        // Report the complete fingerprint together after checking structural
        // safety, so a generated-code change needs only one fresh audit run.
        Assert.Equal(
            (Bytes: 1519834, Branches: 77175, Relays: 3428, Chains: 7, Boundaries: 3346),
            (Bytes: nativeCode.Length, Branches: audit.BranchCount, Relays: audit.RelayCount,
                Chains: audit.ChainCount, Boundaries: audit.FragmentBoundaryCount));
    }

    [Fact]
    public void NativeGraphicsScreenResourceConstructorPublishesOnePlaneChainOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out var screenResourceEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint view = 0x00D0_0000;
        const uint viewPort = 0x00D1_0000;
        const uint rasInfo = 0x00D2_0000;
        const uint bitMap = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 320;
        const ushort height = 200;
        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ViewSize).ToArray());
        bus.MapWritableMemory(viewPort, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ViewPortSize).ToArray());
        bus.MapWritableMemory(rasInfo, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.RasInfoSize).ToArray());
        bus.MapWritableMemory(bitMap, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.BitMapSize).ToArray());
        bus.MapWritableMemory(plane, Enumerable.Repeat((byte)0x5A, 0x100).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(stack + 0x80u, returnAddress);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(
            codeAddress + (uint)screenResourceEntryOffset,
            stack + 0x80u);
        cpu.State.A[0] = view;
        cpu.State.A[1] = viewPort;
        cpu.State.A[2] = rasInfo;
        cpu.State.A[3] = bitMap;
        cpu.State.D[0] = width;
        cpu.State.D[1] = height;
        cpu.State.D[2] = plane;

        var returned = false;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(viewPort, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal((ushort)0x002C, bus.ReadWord(view + (uint)GraphicsLayouts.ViewDyOffset));
        Assert.Equal((ushort)0x0081, bus.ReadWord(view + (uint)GraphicsLayouts.ViewDxOffset));
        Assert.Equal(width, bus.ReadWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth));
        Assert.Equal(height, bus.ReadWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight));
        Assert.Equal(GraphicsLayouts.ViewPortDefaultSpritePriorities, bus.ReadByte(viewPort + (uint)GraphicsLayouts.ViewPortSpritePriorities));
        Assert.Equal(rasInfo, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(bitMap, bus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal((ushort)40, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(height, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)8, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)1, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(plane, bus.ReadLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
    }

