    [Fact]
    public void NativeGraphicsScreenResourceConstructorRejectsOverlappingEnvelopeAndPlaneSpansBeforeMutationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out var screenResourceEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint memoryBase = 0x00D0_0000;
        const uint memoryBytes = 0x0002_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 320;
        const ushort height = 200;

        static void ExecuteCase(
            byte[] nativeCode,
            int entryOffset,
            uint view,
            uint viewPort,
            uint rasInfo,
            uint bitMap,
            uint plane,
            uint codeAddress,
            uint memoryBase,
            uint memoryBytes,
            uint stack,
            uint returnAddress,
            ushort width,
            ushort height)
        {
            var bus = new AmigaBus();
            bus.MapWritableMemory(codeAddress, nativeCode);
            bus.MapWritableMemory(
                memoryBase,
                Enumerable.Repeat((byte)0xA5, checked((int)memoryBytes)).ToArray());
            bus.MapWritableMemory(stack, new byte[0x100]);
            bus.WriteLong(stack + 0x80u, returnAddress);

            using var cpu = AmigaM68kCoreFactory.Default.Create(
                M68kBackendKind.AccurateM68000,
                bus);
            cpu.Reset(
                codeAddress + (uint)entryOffset,
                stack + 0x80u);
            cpu.State.A[0] = view;
            cpu.State.A[1] = viewPort;
            cpu.State.A[2] = rasInfo;
            cpu.State.A[3] = bitMap;
            cpu.State.D[0] = width;
            cpu.State.D[1] = height;
            cpu.State.D[2] = plane;

            var returned = false;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    returned = true;
                    break;
                }
            }

            Assert.True(returned);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((byte)0xA5, bus.ReadByte(view));
            Assert.Equal((byte)0xA5, bus.ReadByte(viewPort));
            Assert.Equal((byte)0xA5, bus.ReadByte(rasInfo));
            Assert.Equal((byte)0xA5, bus.ReadByte(bitMap));
            Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        }

        // ViewPort begins inside the View envelope.  The constructor must
        // decline before clearing either descriptor.
        ExecuteCase(
            nativeCode,
            screenResourceEntryOffset,
            memoryBase,
            memoryBase + 2u,
            memoryBase + 0x100u,
            memoryBase + 0x200u,
            memoryBase + 0x400u,
            codeAddress,
            memoryBase,
            memoryBytes,
            stack,
            returnAddress,
            width,
            height);

        // A caller-owned plane span crossing the View envelope is equally
        // invalid, even though every public descriptor is individually
        // aligned and addressable.
        ExecuteCase(
            nativeCode,
            screenResourceEntryOffset,
            memoryBase,
            memoryBase + 0x100u,
            memoryBase + 0x200u,
            memoryBase + 0x300u,
            memoryBase + 4u,
            codeAddress,
            memoryBase,
            memoryBytes,
            stack,
            returnAddress,
            width,
            height);
    }

