        bus.MapWritableMemory(plane, new byte[0x100]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, replacement);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(stack + 0x80u, returnAddress);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(
            codeAddress + (uint)teardownEntryOffset,
            stack + 0x80u);
        cpu.State.A[0] = view;
        cpu.State.A[1] = viewPort;
        cpu.State.A[2] = rasInfo;
        cpu.State.A[3] = bitMap;

        var returned = false;
        for (var index = 0; index < 2048; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(replacement, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal((byte)0xA5, bus.ReadByte(view + (uint)GraphicsLayouts.ViewModes));
        Assert.Equal((byte)0xA5, bus.ReadByte(viewPort));
        Assert.Equal((byte)0xA5, bus.ReadByte(rasInfo));
        Assert.Equal((byte)0xA5, bus.ReadByte(bitMap));
    }

    [Fact]
    public void NativeGraphicsScreenPrefixConstructorPublishesEmbeddedClassicTopologyOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
