        const uint view = 0x00D2_0000;
        const uint rasInfo = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 320;
        const ushort height = 200;
        var viewPort = screen + (uint)GraphicsLayouts.ScreenViewPort;
        var rastPort = screen + (uint)GraphicsLayouts.ScreenRastPort;
        var bitMap = screen + (uint)GraphicsLayouts.ScreenBitMap;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(screen, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ScreenSize).ToArray());
        bus.MapWritableMemory(view, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ViewSize).ToArray());
        bus.MapWritableMemory(rasInfo, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.RasInfoSize).ToArray());
        bus.MapWritableMemory(plane, Enumerable.Repeat((byte)0x5A, 0x100).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(stack + 0x80u, returnAddress);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(codeAddress + (uint)prefixEntryOffset, stack + 0x80u);
        cpu.State.A[0] = screen;
        cpu.State.A[1] = view;
        cpu.State.A[2] = rasInfo;
        cpu.State.D[0] = width;
        cpu.State.D[1] = height;
        cpu.State.D[2] = plane;

        var returned = false;
        for (var index = 0; index < 12_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(width, bus.ReadWord(screen + (uint)GraphicsLayouts.ScreenWidth));
        Assert.Equal(height, bus.ReadWord(screen + (uint)GraphicsLayouts.ScreenHeight));
        Assert.Equal(viewPort, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(rasInfo, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(bitMap, bus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(bitMap, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap));
        Assert.Equal(width, bus.ReadWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth));
        Assert.Equal(height, bus.ReadWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight));
        Assert.Equal((ushort)40, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(height, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x08, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)1, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(plane, bus.ReadLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
    }

    [Fact]
    public void NativeGraphicsScreenPrefixConstructorRejectsOverlappingEnvelopeAndPlaneSpansBeforeMutationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out var prefixEntryOffset,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint memoryBase = 0x00D0_0000;
        const uint memoryBytes = 0x0002_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 320;
        const ushort height = 200;

        static void ExecuteCase(
            byte[] nativeCode,
            int entryOffset,
            uint screen,
            uint view,
            uint rasInfo,
            uint plane,
            uint codeAddress,
            uint memoryBase,
            uint memoryBytes,
            uint stack,
            uint returnAddress,
            ushort width,
            ushort height)
        {
            var bus = new AmigaBus();
            bus.MapWritableMemory(codeAddress, nativeCode);
            bus.MapWritableMemory(
                memoryBase,
                Enumerable.Repeat((byte)0xA5, checked((int)memoryBytes)).ToArray());
            bus.MapWritableMemory(stack, new byte[0x100]);
            bus.WriteLong(stack + 0x80u, returnAddress);

            using var cpu = AmigaM68kCoreFactory.Default.Create(
                M68kBackendKind.AccurateM68000,
                bus);
            cpu.Reset(codeAddress + (uint)entryOffset, stack + 0x80u);
            cpu.State.A[0] = screen;
            cpu.State.A[1] = view;
            cpu.State.A[2] = rasInfo;
            cpu.State.D[0] = width;
            cpu.State.D[1] = height;
            cpu.State.D[2] = plane;

            var returned = false;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    returned = true;
                    break;
                }
            }

            Assert.True(returned);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((byte)0xA5, bus.ReadByte(screen));
            Assert.Equal((byte)0xA5, bus.ReadByte(view));
            Assert.Equal((byte)0xA5, bus.ReadByte(rasInfo));
            Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        }

        // The external View begins inside the embedded Screen envelope.
        ExecuteCase(
            nativeCode,
            prefixEntryOffset,
            memoryBase,
            memoryBase + 2u,
            memoryBase + 0x100u,
            memoryBase + 0x400u,
            codeAddress,
            memoryBase,
            memoryBytes,
            stack,
            returnAddress,
            width,
            height);

        // A caller-owned plane span crossing the embedded Screen envelope
        // is invalid even when the descriptor addresses are otherwise valid.
        ExecuteCase(
            nativeCode,
            prefixEntryOffset,
            memoryBase,
            memoryBase + (uint)GraphicsLayouts.ScreenSize + 0x100u,
            memoryBase + (uint)GraphicsLayouts.ScreenSize + 0x200u,
            memoryBase + 4u,
            codeAddress,
            memoryBase,
            memoryBytes,
            stack,
            returnAddress,
            width,
            height);
    }

    [Fact]
    public void NativeGraphicsScreenPrefixExecAllocatorConstructsAndReturnsFourOwnedBlocksOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var allocatorEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint execBase = 0x0070_0000;
        const uint screen = 0x00D0_0000;
        const uint view = 0x00D2_0000;
        const uint rasInfo = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 320;
        const ushort height = 200;
        const uint planeBytes = 0x100;
        var allocationAddresses = new[] { screen, view, rasInfo, plane };
        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(stack, new byte[0x200]);
        bus.WriteLong(stack + 0x180u, returnAddress);
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            var index = allocations.Count;
            allocations.Add((state.D[0], state.D[1]));
            Assert.True(index < allocationAddresses.Length);
            var address = allocationAddresses[index];
            bus.MapWritableMemory(address, new byte[checked((int)state.D[0])]);
            state.D[0] = address;
        });
        bus.RegisterHostGateway(freeAddress, state => frees.Add((state.A[1], state.D[0])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(codeAddress + (uint)allocatorEntryOffset, stack + 0x180u);
        cpu.State.A[6] = execBase;
        cpu.State.D[0] = width;
        cpu.State.D[1] = height;
        cpu.State.D[2] = planeBytes;

        var returned = false;
        for (var index = 0; index < 40_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(4, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(screen, cpu.State.D[0]);
        Assert.Equal(view, cpu.State.D[1]);
        Assert.Equal(rasInfo, cpu.State.D[2]);
        Assert.Equal(plane, cpu.State.D[3]);
        Assert.Equal(execBase, cpu.State.A[6]);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.ScreenSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.ViewSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RasInfoSize, 0x0001_0001u),
                (planeBytes, 0x0001_0003u)
            },
            allocations);
        Assert.Equal(width, bus.ReadWord(screen + (uint)GraphicsLayouts.ScreenWidth));
        Assert.Equal(height, bus.ReadWord(screen + (uint)GraphicsLayouts.ScreenHeight));
        Assert.Equal(plane, bus.ReadLong(screen + (uint)GraphicsLayouts.ScreenBitMap + (uint)GraphicsLayouts.BitMapPlanes));
    }

