        Assert.True(returned);
        Assert.Equal((depth * 2) + 2, allocations.Count);
        var expectedFrees = Enumerable.Range(2, depth - 2)
            .Select(level =>
            {
                var tableIndex = level == 2 ? 4 : 2 * level;
                return (allocationAddresses[tableIndex], (uint)(4 * level));
            })
            .ToArray();
        Assert.Equal(expectedFrees, frees);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(execBase, cpu.State.A[6]);
        Assert.Equal(screen, bus.ReadLong(result + (uint)GraphicsLayouts.ScreenPrefixExecResultScreen));
        Assert.Equal(view, bus.ReadLong(result + (uint)GraphicsLayouts.ScreenPrefixExecResultView));
        Assert.Equal(rasInfo, bus.ReadLong(result + (uint)GraphicsLayouts.ScreenPrefixExecResultRasInfo));
        var table = allocationAddresses[2 * depth];
        Assert.Equal(table, bus.ReadLong(result + (uint)GraphicsLayouts.ScreenPrefixExecResultPlaneTable));
        for (var plane = 0; plane < 8; plane++)
        {
            var field = result + (uint)(GraphicsLayouts.ScreenPrefixExecResultPlane0 + (plane * 4));
            var expected = plane < depth
                ? allocationAddresses[plane == 0 ? 3 : (2 * plane) + 3]
                : 0u;
            Assert.Equal(expected, bus.ReadLong(field));
        }

        var bitMap = screen + (uint)GraphicsLayouts.ScreenBitMap;
        Assert.Equal((byte)depth, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapDepth));
        for (var plane = 0; plane < depth; plane++)
        {
            var expected = allocationAddresses[plane == 0 ? 3 : (2 * plane) + 3];
            Assert.Equal(expected, bus.ReadLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + ((uint)plane * 4u)));
            Assert.Equal(expected, bus.ReadLong(table + ((uint)plane * 4u)));
        }
    }

    [Fact]
    public void NativeGraphicsDisplayResourceExecAllocatorPublishesClassicCopperTopologyOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var allocatorEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint execBase = 0x0070_0000;
        const uint screen = 0x00D0_0000;
        const uint view = 0x00D2_0000;
        const uint rasInfo = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint copList = 0x00E1_0000;
        const uint lofCpr = 0x00E2_0000;
        const uint shfCpr = 0x00E3_0000;
        const uint rawCopper = 0x00E4_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const uint planeBytes = 0x100;
        const uint rawBytes = 0x100;
        const ushort width = 320;
        const ushort height = 200;
        var allocationAddresses = new[]
        {
            screen,
            view,
            rasInfo,
            plane,
            copList,
            lofCpr,
            shfCpr,
            rawCopper
        };
        var allocations = new List<(uint Size, uint Flags)>();

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(stack, new byte[0x300]);
        bus.WriteLong(stack + 0x280u, returnAddress);
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var allocationIndex = 0;
        bus.RegisterHostGateway(allocAddress, state =>
        {
            var index = allocationIndex++;
            Assert.True(index < allocationAddresses.Length);
            allocations.Add((state.D[0], state.D[1]));
            var address = allocationAddresses[index];
            bus.MapWritableMemory(address, new byte[checked((int)state.D[0])]);
            state.D[0] = address;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(codeAddress + (uint)allocatorEntryOffset, stack + 0x280u);
        cpu.State.A[6] = execBase;
        cpu.State.D[0] = width;
        cpu.State.D[1] = height;
        cpu.State.D[2] = planeBytes;
        cpu.State.D[3] = rawBytes;

        var returned = false;
        for (var index = 0; index < 80_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.ScreenSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.ViewSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RasInfoSize, 0x0001_0001u),
                (planeBytes, 0x0001_0003u),
                ((uint)GraphicsLayouts.CopListSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.CprListSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.CprListSize, 0x0001_0001u),
                (rawBytes, 0x0001_0003u)
            },
            allocations);
        Assert.Equal(screen, cpu.State.D[0]);
        Assert.Equal(view, cpu.State.D[1]);
        Assert.Equal(rasInfo, cpu.State.D[2]);
        Assert.Equal(plane, cpu.State.D[3]);
        Assert.Equal(copList, cpu.State.D[4]);
        Assert.Equal(lofCpr, cpu.State.D[5]);
        Assert.Equal(shfCpr, cpu.State.D[6]);
        Assert.Equal(rawCopper, cpu.State.D[7]);
        Assert.Equal(execBase, cpu.State.A[6]);

        var viewPort = screen + (uint)GraphicsLayouts.ScreenViewPort;
        Assert.Equal(viewPort, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(lofCpr, bus.ReadLong(view + (uint)GraphicsLayouts.ViewLoFCprList));
        Assert.Equal(shfCpr, bus.ReadLong(view + (uint)GraphicsLayouts.ViewShFCprList));
        Assert.Equal(copList, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(viewPort, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListViewPort));
        Assert.Equal(rawCopper, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopIns));
        Assert.Equal(rawCopper, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopPtr));
        Assert.Equal(rawCopper, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopLStart));
        Assert.Equal(rawCopper, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopSStart));
        Assert.Equal((ushort)2, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListCount));
        Assert.Equal((ushort)2, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListMaxCount));
        Assert.Equal(rawCopper, bus.ReadLong(lofCpr + (uint)GraphicsLayouts.CprListStart));
        Assert.Equal(rawCopper, bus.ReadLong(shfCpr + (uint)GraphicsLayouts.CprListStart));
        Assert.Equal((ushort)2, bus.ReadWord(lofCpr + (uint)GraphicsLayouts.CprListMaxCount));
        Assert.Equal((ushort)2, bus.ReadWord(shfCpr + (uint)GraphicsLayouts.CprListMaxCount));
        Assert.Equal((ushort)GraphicsLayouts.CopperEndWait, bus.ReadWord(rawCopper));
        Assert.Equal((ushort)GraphicsLayouts.CopperEndMask, bus.ReadWord(rawCopper + 2u));
    }

    [Fact]
    public void NativeGraphicsLoadViewPublishesExecDisplayBundleAndRejectsForeignMarkerOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var allocatorEntryOffset,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint execBase = 0x0070_0000;
        const uint graphicsBase = 0x0060_0000;
        const uint screen = 0x00D0_0000;
        const uint view = 0x00D2_0000;
        const uint rasInfo = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint copList = 0x00E1_0000;
        const uint lofCpr = 0x00E2_0000;
        const uint shfCpr = 0x00E3_0000;
        const uint rawCopper = 0x00E4_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const uint planeBytes = 0x100;
        const uint rawBytes = 0x100;
        const ushort width = 100;
        const ushort height = 100;
        var allocationAddresses = new[]
        {
            screen,
            view,
            rasInfo,
            plane,
            copList,
            lofCpr,
            shfCpr,
            rawCopper
        };
        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.MapWritableMemory(stack, new byte[0x300]);
        var allocationIndex = 0;
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            Assert.True(allocationIndex < allocationAddresses.Length);
            var address = allocationAddresses[allocationIndex++];
            bus.MapWritableMemory(address, new byte[checked((int)state.D[0])]);
            state.D[0] = address;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(int entryOffset, Action configure, int maxInstructions = 80_000)
        {
            bus.WriteLong(stack + 0x280u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffset, stack + 0x280u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x280u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native graphics body did not return.");
        }

        Execute(allocatorEntryOffset, () =>
        {
            cpu.State.A[6] = execBase;
            cpu.State.D[0] = width;
            cpu.State.D[1] = height;
            cpu.State.D[2] = planeBytes;
            cpu.State.D[3] = rawBytes;
        });

        Assert.Equal(8, allocationIndex);
        Assert.Equal(screen, cpu.State.D[0]);
        Assert.Equal(view, cpu.State.D[1]);
        Assert.Equal(rasInfo, cpu.State.D[2]);
        Assert.Equal(plane, cpu.State.D[3]);
        Assert.Equal(copList, cpu.State.D[4]);
        Assert.Equal(lofCpr, cpu.State.D[5]);
        Assert.Equal(shfCpr, cpu.State.D[6]);
        Assert.Equal(rawCopper, cpu.State.D[7]);
        var marker = bus.ReadWord(copList + (uint)GraphicsLayouts.CopListFlags);
        Assert.Equal((ushort)0x4452, marker);

        bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView,
            0);
        Execute(entryOffsets[GraphicsLvo.LoadView], () =>
        {
            cpu.State.A[1] = view;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = 0xCAFE_0000u;
        });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(view, bus.ReadLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));

        // A foreign Count==2 CopList must remain provider-owned. LoadView
        // restores the void-vector D0 and leaves the previously active View
        // untouched when the private marker is absent.
        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListFlags, 0);
        Execute(entryOffsets[GraphicsLvo.LoadView], () =>
        {
            cpu.State.A[1] = view;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = 0xBADA_0000u;
        });
        Assert.Equal(0xBADA_0000u, cpu.State.D[0]);
        Assert.Equal(view, bus.ReadLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));

        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListFlags, marker);
        Execute(entryOffsets[GraphicsLvo.LoadView], () =>
        {
            cpu.State.A[1] = view;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = 0xFACE_0000u;
        });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(view, bus.ReadLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsEmptyDefaultAndPreservesUnsupportedRequestsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(tags, 0); // TAG_DONE
        bus.WriteLong(tags + 4u, 0xDEAD_BEEFu); // ti_Data is ignored

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint tagList, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
                stack + 0x80u);
            cpu.State.A[0] = tagList;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 200; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native BestModeIDA body did not return.");
        }

        Execute(0, sentinel);
        Assert.Equal(0x0000_8000u, cpu.State.D[0]);

        Execute(tags, sentinel);
        Assert.Equal(0x0000_8000u, cpu.State.D[0]);

        const uint boundaryTags = 0xFFFF_FFF8u;
        bus.MapWritableMemory(boundaryTags, new byte[8]);
        bus.WriteLong(boundaryTags, 0); // TAG_DONE at the final aligned start
        bus.WriteLong(boundaryTags + 4u, 0);
        Execute(boundaryTags, sentinel);
        Assert.Equal(0x0000_8000u, cpu.State.D[0]);

        bus.WriteLong(tags, GraphicsDisplayDatabase.BidTagNominalWidth);
        Execute(tags, sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        Execute(tags | 1u, sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        Execute(0xFFFF_FFFCu, sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsExactStandardTagTupleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_1000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[7 * 8]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        static void WriteTag(AmigaBus memory, uint address, uint tag, uint value)
        {
            memory.WriteLong(address, tag);
            memory.WriteLong(address + 4u, value);
        }

        WriteTag(bus, tags + 0u, GraphicsDisplayDatabase.BidTagNominalWidth, 640);
        WriteTag(bus, tags + 8u, GraphicsDisplayDatabase.BidTagNominalHeight, 256);
        WriteTag(bus, tags + 16u, GraphicsDisplayDatabase.BidTagDesiredWidth, 640);
        WriteTag(bus, tags + 24u, GraphicsDisplayDatabase.BidTagDesiredHeight, 256);
        WriteTag(bus, tags + 32u, GraphicsDisplayDatabase.BidTagDepth, 4);
        WriteTag(bus, tags + 40u, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(bus, tags + 48u, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
            stack + 0x80u);
        cpu.State.A[0] = tags;
        cpu.State.D[0] = sentinel;
        for (var index = 0; index < 2000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(0x0002_9000u, cpu.State.D[0]);

        // The fixed six-tag standard form also reaches the canonical
        // SuperHires record. It must remain unclaimed on OCS even though the
        // record stays enumerable, then become available with both ECS bits.
        bus.WriteLong(tags + 4u, 1280);
        bus.WriteLong(tags + 20u, 1280);
        bus.WriteLong(tags + 36u, 2);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
            stack + 0x80u);
        cpu.State.A[0] = tags;
        cpu.State.A[6] = graphicsBase;
        cpu.State.D[0] = sentinel;
        for (var index = 0; index < 2000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.HrAgnus,
            0);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
            stack + 0x80u);
        cpu.State.A[0] = tags;
        cpu.State.A[6] = graphicsBase;
        cpu.State.D[0] = sentinel;
        for (var index = 0; index < 2000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
            stack + 0x80u);
        cpu.State.A[0] = tags;
        cpu.State.A[6] = graphicsBase;
        cpu.State.D[0] = sentinel;
        for (var index = 0; index < 2000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);

        bus.WriteLong(tags + 4u, 640);
        bus.WriteLong(tags + 20u, 640);
        bus.WriteLong(tags + 36u, 4);
        bus.WriteLong(tags + 12u, 200);
        bus.WriteLong(tags + 28u, 200);
        bus.WriteLong(tags + 44u, GraphicsModeIds.NtscMonitor);
        bus.WriteLong(tags + 0u, GraphicsDisplayDatabase.BidTagNominalWidth);
        bus.WriteLong(tags + 16u, GraphicsDisplayDatabase.BidTagDesiredWidth);
        bus.WriteLong(tags + 32u, GraphicsDisplayDatabase.BidTagDepth);
        bus.WriteLong(tags + 24u, GraphicsDisplayDatabase.BidTagDesiredHeight);
        bus.WriteLong(tags + 8u, GraphicsDisplayDatabase.BidTagNominalHeight);
        bus.WriteLong(tags + 48u, 0);
        bus.WriteLong(tags + 52u, 0);

        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
            stack + 0x80u);
        cpu.State.A[0] = tags;
        cpu.State.D[0] = sentinel;
        for (var index = 0; index < 2000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(0x0001_9000u, cpu.State.D[0]);

        bus.WriteLong(tags + 4u, 640);
        bus.WriteLong(tags + 12u, 256);
        bus.WriteLong(tags + 44u, GraphicsModeIds.PalMonitor);
        bus.WriteLong(tags + 0u, GraphicsDisplayDatabase.BidTagNominalWidth);
        bus.WriteLong(tags + 8u, GraphicsDisplayDatabase.BidTagNominalHeight);
        bus.WriteLong(tags + 16u, GraphicsDisplayDatabase.BidTagDesiredWidth);
        bus.WriteLong(tags + 24u, GraphicsDisplayDatabase.BidTagDesiredHeight);
        bus.WriteLong(tags + 32u, GraphicsDisplayDatabase.BidTagDepth);
        bus.WriteLong(tags + 48u, GraphicsDisplayDatabase.BidTagNominalWidth);
        bus.WriteLong(tags + 52u, 0);

        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
            stack + 0x80u);
        cpu.State.A[0] = tags;
        cpu.State.D[0] = sentinel;
        for (var index = 0; index < 2000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(sentinel, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsFixedViewportTagTupleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_2000;
        const uint viewPort = 0x00D1_0000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[4 * 8]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, GraphicsModeIds.HiresMode);
        bus.WriteByte(viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);

        static void WriteTag(AmigaBus memory, uint address, uint tag, uint value)
        {
            memory.WriteLong(address, tag);
            memory.WriteLong(address + 4u, value);
        }

        WriteTag(bus, tags + 0u, GraphicsDisplayDatabase.BidTagViewPort, viewPort);
        WriteTag(bus, tags + 8u, GraphicsDisplayDatabase.BidTagDepth, 4);
        WriteTag(bus, tags + 16u, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(bus, tags + 24u, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint? port = null)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 500; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native viewport BestModeIDA body did not return.");
        }

        Execute(sentinel);
        Assert.Equal(0x0002_9000u, cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 1280);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            0,
            0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, GraphicsModeIds.LoresKey);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, GraphicsModeIds.HiresMode);
        bus.WriteLong(tags, GraphicsDisplayDatabase.BidTagNominalWidth);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsFixedSourceIdTagTupleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_3000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[4 * 8]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        static void WriteTag(AmigaBus memory, uint address, uint tag, uint value)
        {
            memory.WriteLong(address, tag);
            memory.WriteLong(address + 4u, value);
        }

        WriteTag(bus, tags + 0u, GraphicsDisplayDatabase.BidTagSourceId,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey);
        WriteTag(bus, tags + 8u, GraphicsDisplayDatabase.BidTagDepth, 6);
        WriteTag(bus, tags + 16u, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(bus, tags + 24u, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 600; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native source BestModeIDA body did not return.");
        }

        Execute(sentinel);
        Assert.Equal(0x0002_1800u, cpu.State.D[0]);

        bus.WriteLong(tags + 4u, GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey);
        Execute(sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey, cpu.State.D[0]);

        bus.WriteLong(tags + 4u,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            0,
            0);

        bus.WriteLong(tags + 4u, GraphicsModeIds.PalMonitor | 0x1234u);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        bus.WriteLong(tags + 4u, GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey);
        bus.WriteLong(tags + 20u, GraphicsModeIds.NtscMonitor);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsFixedSourceFeatureTagTupleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_4000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[4 * 8]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        static void WriteTag(AmigaBus memory, uint address, uint tag, uint value)
        {
            memory.WriteLong(address, tag);
            memory.WriteLong(address + 4u, value);
        }

        WriteTag(bus, tags + 0u, GraphicsDisplayDatabase.BidTagSourceId,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey);
        WriteTag(bus, tags + 8u, GraphicsDisplayDatabase.BidTagDipfMustHave,
            GraphicsDisplayDatabase.DipfIsHam);
        WriteTag(bus, tags + 16u, GraphicsDisplayDatabase.BidTagDipfMustNotHave, 0);
        WriteTag(bus, tags + 24u, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 800; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native source feature BestModeIDA body did not return.");
        }

        Execute(sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey, cpu.State.D[0]);

        // A dual-playfield/PF2 source exercises a combined required mask and
        // a nonzero forbidden mask without changing the returned SourceID.
        bus.WriteLong(tags + 4u, GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldTwoKey);
        bus.WriteLong(tags + 12u, GraphicsDisplayDatabase.DipfIsDualPf | GraphicsDisplayDatabase.DipfIsPf2Pri);
        bus.WriteLong(tags + 20u, GraphicsDisplayDatabase.DipfIsHam);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldTwoKey,
            cpu.State.D[0]);

        bus.WriteLong(tags + 4u,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey);
        bus.WriteLong(tags + 12u, GraphicsDisplayDatabase.DipfIsEcs);
        bus.WriteLong(tags + 20u, 0);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            0,
            0);

        // A required HAM property cannot be satisfied by a dual-playfield
        // source, so the native arm must restore D0 for the portable owner.
        bus.WriteLong(tags + 4u, GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey);
        bus.WriteLong(tags + 12u, GraphicsDisplayDatabase.DipfIsDualPf);
        bus.WriteLong(tags + 20u, 0);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsFixedSourceComponentTagTupleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_5000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[7 * 8]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        static void WriteTag(AmigaBus memory, uint address, uint tag, uint value)
        {
            memory.WriteLong(address, tag);
            memory.WriteLong(address + 4u, value);
        }

        WriteTag(bus, tags + 0u, GraphicsDisplayDatabase.BidTagSourceId,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey);
        WriteTag(bus, tags + 8u, GraphicsDisplayDatabase.BidTagDepth, 6);
        WriteTag(bus, tags + 16u, GraphicsDisplayDatabase.BidTagMonitorId,
            GraphicsModeIds.PalMonitor);
        WriteTag(bus, tags + 24u, GraphicsDisplayDatabase.BidTagRedBits, 4);
        WriteTag(bus, tags + 32u, GraphicsDisplayDatabase.BidTagBlueBits, 4);
        WriteTag(bus, tags + 40u, GraphicsDisplayDatabase.BidTagGreenBits, 4);
        WriteTag(bus, tags + 48u, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 900; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native source component BestModeIDA body did not return.");
        }

        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey,
            cpu.State.D[0]);

        // Progressive SuperHires accepts only the ECS 2-bit component/depth
        // profile represented by this native ladder.
        bus.WriteLong(tags + 4u,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey);
        bus.WriteLong(tags + 12u, 2);
        bus.WriteLong(tags + 28u, 2);
        bus.WriteLong(tags + 36u, 2);
        bus.WriteLong(tags + 44u, 2);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);

        bus.WriteLong(tags + 28u, 4);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        // Interlaced SuperHires has the wider component allowance, while its
        // depth remains capped at two planes.
        bus.WriteLong(tags + 4u,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey);
        bus.WriteLong(tags + 28u, 4);
        bus.WriteLong(tags + 36u, 4);
        bus.WriteLong(tags + 44u, 4);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey,
            cpu.State.D[0]);

        bus.WriteLong(tags + 12u, 3);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        // An ordinary SourceID request can express both eight planes and
        // RGB8. The native selector accepts it only after Alice and Lisa are
        // both published at the resident GfxBase capability byte.
        bus.WriteLong(tags + 4u,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey);
        bus.WriteLong(tags + 12u, 8);
        bus.WriteLong(tags + 28u, 8);
        bus.WriteLong(tags + 36u, 8);
        bus.WriteLong(tags + 44u, 8);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.AaAlice,
            0);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetAa,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey,
            cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsBestModeIdAdmitsFixedStandardComponentTagTupleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint tags = 0x00D0_6000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(tags, new byte[10 * 8]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        static void WriteTag(AmigaBus memory, uint address, uint tag, uint value)
        {
            memory.WriteLong(address, tag);
            memory.WriteLong(address + 4u, value);
        }

        WriteTag(bus, tags + 0u, GraphicsDisplayDatabase.BidTagNominalWidth, 640);
        WriteTag(bus, tags + 8u, GraphicsDisplayDatabase.BidTagNominalHeight, 256);
        WriteTag(bus, tags + 16u, GraphicsDisplayDatabase.BidTagDesiredWidth, 640);
        WriteTag(bus, tags + 24u, GraphicsDisplayDatabase.BidTagDesiredHeight, 256);
        WriteTag(bus, tags + 32u, GraphicsDisplayDatabase.BidTagDepth, 6);
        WriteTag(bus, tags + 40u, GraphicsDisplayDatabase.BidTagMonitorId,
            GraphicsModeIds.PalMonitor);
        WriteTag(bus, tags + 48u, GraphicsDisplayDatabase.BidTagRedBits, 4);
        WriteTag(bus, tags + 56u, GraphicsDisplayDatabase.BidTagBlueBits, 4);
        WriteTag(bus, tags + 64u, GraphicsDisplayDatabase.BidTagGreenBits, 4);
        WriteTag(bus, tags + 72u, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.BestModeIDA],
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 1100; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native standard component BestModeIDA body did not return.");
        }

        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey,
            cpu.State.D[0]);

        // Progressive ECS SuperHires is the two-plane/two-bit RGB record.
        bus.WriteLong(tags + 4u, 1280);
        bus.WriteLong(tags + 12u, 256);
        bus.WriteLong(tags + 20u, 1280);
        bus.WriteLong(tags + 28u, 256);
        bus.WriteLong(tags + 36u, 2);
        bus.WriteLong(tags + 52u, 2);
        bus.WriteLong(tags + 60u, 2);
        bus.WriteLong(tags + 68u, 2);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);

        bus.WriteLong(tags + 52u, 4);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        // Interlaced SuperHires restores the four-bit component precision but
        // retains the two-plane depth ceiling.
        bus.WriteLong(tags + 12u, 512);
        bus.WriteLong(tags + 28u, 512);
        bus.WriteLong(tags + 52u, 4);
        bus.WriteLong(tags + 60u, 4);
        bus.WriteLong(tags + 68u, 4);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey,
            cpu.State.D[0]);

        bus.WriteLong(tags + 36u, 3);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        // Ordinary AGA modes extend both the plane and component limits only
        // when Alice and Lisa are both published through GfxBase.
        bus.WriteLong(tags + 4u, 640);
        bus.WriteLong(tags + 12u, 256);
        bus.WriteLong(tags + 20u, 640);
        bus.WriteLong(tags + 28u, 256);
        bus.WriteLong(tags + 36u, 8);
        bus.WriteLong(tags + 52u, 8);
        bus.WriteLong(tags + 60u, 8);
        bus.WriteLong(tags + 68u, 8);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.AaAlice,
            0);
        Execute(sentinel);
        Assert.Equal(sentinel, cpu.State.D[0]);

        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetAa,
            0);
        Execute(sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey,
            cpu.State.D[0]);
    }

    [Theory]
    [InlineData(0u)]
    [InlineData(1u)]
    public void NativeGraphicsCoerceModeOrdinaryDepthMatchesIndependentRom(uint flags)
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(out var entries, out _);
        const uint codeAddress = 0x00800000, viewport = 0x00D00000;
        const uint rasInfo = 0x00D10000, bitmap = 0x00D20000;
        const uint stack = 0x00C00000, graphicsBase = 0x00E00000;
        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(viewport, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.WriteWord(viewport + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewport + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteLong(viewport + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitmap);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 8, 0);
        using var cpu = AmigaM68kCoreFactory.Default.Create(M68kBackendKind.AccurateM68000, bus);
        foreach (var depth in new byte[] { 5, 6 })
        {
            bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, depth, 0);
            bus.WriteLong(stack + 0x80, 0);
            cpu.Reset(codeAddress + (uint)entries[GraphicsLvo.CoerceMode], stack + 0x80);
            cpu.State.A[0] = viewport;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = 0x21000;
            cpu.State.D[1] = flags;
            for (var count = 0; count < 400 && cpu.State.ProgramCounter != 0; count++)
                cpu.ExecuteInstruction();
            Assert.Equal(0u, cpu.State.ProgramCounter);
            Assert.Equal(stack + 0x84, cpu.State.A[7]);
            // Independent original PAL3.1 result. A fallback which merely
            // retains input D0=PAL cannot masquerade as the invalid result.
            Assert.Equal(depth == 5 ? 0x21000u : uint.MaxValue, cpu.State.D[0]);
        }
    }

    [Theory]
    [InlineData(false, 0u)]
    [InlineData(false, 1u)]
    [InlineData(true, 0u)]
    [InlineData(true, 1u)]
    public void NativeGraphicsCoerceAssociatedSourceMatchesIndependentRom(bool ntsc, uint flags)
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(out var entries, out _);
        const uint codeAddress = 0x00800000, viewport = 0x00D00000;
        const uint rasInfo = 0x00D10000, bitmap = 0x00D20000, colorMap = 0x00D30000;
        const uint stack = 0x00C00000, graphicsBase = 0x00E00000;
        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(viewport, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(colorMap, new byte[GraphicsLayouts.ColorMapSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.WriteLong(viewport + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitmap);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 512);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 8, 0);
        var monitor = ntsc ? 0x11000u : 0x21000u;
        using var cpu = AmigaM68kCoreFactory.Default.Create(M68kBackendKind.AccurateM68000, bus);
        foreach (var mapState in new[] { 0, 1, 2 })
        foreach (var mode in new ushort[] { 0x8000, 0x0800, 0x0080, 0x0400 })
        foreach (var viewportMode in new ushort[] { mode, 0 })
        foreach (var width in new ushort[] { 320, 640 })
        foreach (var depth in new byte[] { 4, 5, 6, 7 })
        {
            bus.WriteWord(viewport + (uint)GraphicsLayouts.ViewPortDWidth, width);
            bus.WriteWord(viewport + (uint)GraphicsLayouts.ViewPortDHeight, ntsc ? (ushort)200 : (ushort)256);
            bus.WriteWord(viewport + (uint)GraphicsLayouts.ViewPortModes, viewportMode);
            bus.WriteLong(viewport + (uint)GraphicsLayouts.ViewPortColorMap, mapState == 0 ? 0 : colorMap);
            // Native display-info handles carry their canonical ID. This is
            // the public ColorMap association, not host registry state.
            bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapNormalDisplayInfo, mapState == 2 ? monitor | mode : 0);
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, (ushort)(width / 8));
            bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, depth, 0);
            bus.WriteLong(stack + 0x80, 0);
            cpu.Reset(codeAddress + (uint)entries[GraphicsLvo.CoerceMode], stack + 0x80);
            cpu.State.A[0] = viewport;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = monitor;
            cpu.State.D[1] = flags;
            for (var count = 0; count < 800 && cpu.State.ProgramCounter != 0; count++)
                cpu.ExecuteInstruction();
            Assert.Equal(0u, cpu.State.ProgramCounter);
            Assert.Equal(stack + 0x84, cpu.State.A[7]);
            var special = mapState == 2 && mode != 0x8000;
            var selectionWidth = mapState == 2 ? (mode == 0x8000 ? 640 : 320) : width;
            var expected = depth > (special ? 6 : 5) ? uint.MaxValue :
                monitor | (special ? mode : selectionWidth == 640 && depth == 4 ? 0x8000u : 0u);
            Assert.True(expected == cpu.State.D[0],
                $"map={mapState}, mode={mode:X4}, depth={depth}, flags={flags}: expected={expected:X8}, actual={cpu.State.D[0]:X8}");
        }
    }

    [Fact]
    public void NativeGraphicsCoerceModeAdmitsStandardPalNtscProgressiveAndInterlaceViewportsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint viewPort = 0x00D0_0000;
        const uint rasInfo = 0x00D1_0000;
        const uint bitMap = 0x00D2_0000;
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteByte(viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        const uint associatedColorMap = 0x00D3_0000;
        bus.MapWritableMemory(associatedColorMap, new byte[GraphicsLayouts.ColorMapSize]);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, associatedColorMap);

        void Execute(uint monitorId, uint flags, uint initialD0)
        {
            // These legacy feature/geometry checks describe an associated
            // source. The independent matrix separately covers absent maps.
            var sourceFamily = monitorId == GraphicsModeIds.NtscMonitor
                ? GraphicsModeIds.NtscMonitor : GraphicsModeIds.PalMonitor;
            bus.WriteLong(associatedColorMap + (uint)GraphicsLayouts.ColorMapNormalDisplayInfo,
                sourceFamily | bus.ReadWord(viewPort + (uint)GraphicsLayouts.ViewPortModes));
            bus.WriteLong(stack + 0x80u, 0);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.CoerceMode],
                stack + 0x80u);
            cpu.State.A[0] = viewPort;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = monitorId == uint.MaxValue ? initialD0 : monitorId;
            cpu.State.D[1] = flags;
            for (var index = 0; index < 400; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native CoerceMode body did not return.");
        }

        Execute(0, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 1280);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        Execute(
            GraphicsModeIds.PalMonitor,
            GraphicsDisplayDatabase.CoercePreserveColors,
            sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Execute(
            GraphicsModeIds.PalMonitor,
            GraphicsDisplayDatabase.CoercePreserveColors,
            sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);
        // Subsequent geometry checks include hires: use its valid four planes.
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 4, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode,
            cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.LoresDualPlayfieldKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.LoresDualPlayfieldKey, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200);
        Execute(GraphicsModeIds.NtscMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(GraphicsModeIds.NtscMonitor, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        Execute(GraphicsModeIds.NtscMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.HiresMode,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.InterlaceMode);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.InterlaceMode,
            cpu.State.D[0]);
        Execute(0, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.InterlaceMode,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, 0x0000_0008u, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.InterlaceMode,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoerceAvoidFlicker, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 400);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.InterlaceMode);
        Execute(GraphicsModeIds.NtscMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.InterlaceMode,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        Execute(GraphicsModeIds.NtscMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.InterlaceMode);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.InterlaceMode, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);

        // HAM/EHB are the bounded native feature-key family.  They retain the
        // lores geometry, participate in the progressive/interlace monitor
        // ladder, and still honor the interlace flicker guard.
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HamKey);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey,
            cpu.State.D[0]);
        Execute(0, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey,
            cpu.State.D[0]);

        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ExtraHalfBriteKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.ExtraHalfBriteKey,
            cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HamLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamLaceKey,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoerceAvoidFlicker, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 400);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ExtraHalfBriteLaceKey);
        Execute(GraphicsModeIds.NtscMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.ExtraHalfBriteLaceKey,
            cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.LoresDualPlayfieldKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.LoresDualPlayfieldKey,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.LoresDualPlayfieldTwoKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.LoresDualPlayfieldTwoKey,
            cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresDualPlayfieldKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldKey,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresDualPlayfieldTwoKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldTwoKey,
            cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            320);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.LoresDualPlayfieldLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.LoresDualPlayfieldLaceKey,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.LoresDualPlayfieldTwoLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.LoresDualPlayfieldTwoLaceKey,
            cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresDualPlayfieldLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldLaceKey,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresDualPlayfieldTwoLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldTwoLaceKey,
            cpu.State.D[0]);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.LoresDualPlayfieldKey);
        Execute(GraphicsModeIds.NtscMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.LoresDualPlayfieldKey,
            cpu.State.D[0]);

        // ECS SuperHires is the separate 1280-pixel standard family.  Its
        // native record has two planes, so PRESERVE_COLORS uses the stricter
        // source-depth ceiling while ordinary coercion still succeeds.
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 1280);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoerceAvoidFlicker, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey);
        Execute(GraphicsModeIds.NtscMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.SuperHiresKey,
            cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresDualPlayfieldKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresDualPlayfieldKey,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresDualPlayfieldTwoKey,
            cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresDualPlayfieldLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresDualPlayfieldLaceKey,
            cpu.State.D[0]);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey,
            cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoerceAvoidFlicker, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3, 0);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(GraphicsModeIds.Invalid, cpu.State.D[0]);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5, 0);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HamKey);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey, cpu.State.D[0]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);

        // Ordinary OCS/ECS lores has five planes. An invalid source is
        // rejected with either flag setting, not silently reinterpreted.
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 7, 0);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(GraphicsModeIds.Invalid, cpu.State.D[0]);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.Invalid, cpu.State.D[0]);

        // PRESERVE_COLORS can retain an eight-plane ordinary AGA bitmap only
        // after both public AA capability bits have been published. A
        // non-Aga or partial-Alice declaration rejects the invalid source
        // instead of publishing the Hires result.
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(GraphicsModeIds.Invalid, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.AaAlice,
            0);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(GraphicsModeIds.Invalid, cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetAa,
            0);
        Execute(GraphicsModeIds.PalMonitor, GraphicsDisplayDatabase.CoercePreserveColors, sentinel);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey,
            cpu.State.D[0]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            0,
            0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 7, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);

        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, 0);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 1);
        Execute(GraphicsModeIds.PalMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);

        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        Execute(GraphicsModeIds.NtscMonitor, 0, sentinel);
        Assert.Equal(GraphicsModeIds.NtscMonitor, cpu.State.D[0]);

        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5, 0);
        Execute(GraphicsModeIds.PalMonitor, 0x0000_0008u, sentinel);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsDisplayResourceExecTeardownReleasesOwnedBundleOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var allocatorEntryOffset,
            out var teardownEntryOffset);
        // Keep the complete generated image out of the CIA-B register window
        // at $BFD000; the x688 text support now extends the image beyond it.
        const uint codeAddress = 0x0080_0000;
        const uint execBase = 0x0070_0000;
        const uint screen = 0x00D0_0000;
        const uint view = 0x00D2_0000;
        const uint rasInfo = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint copList = 0x00E1_0000;
        const uint lofCpr = 0x00E2_0000;
        const uint shfCpr = 0x00E3_0000;
        const uint rawCopper = 0x00E4_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const uint planeBytes = 0x100;
        const uint rawBytes = 0x100;
        const ushort width = 320;
        const ushort height = 200;
        var allocationAddresses = new[]
        {
            screen,
            view,
            rasInfo,
            plane,
            copList,
            lofCpr,
            shfCpr,
            rawCopper
        };
        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(stack, new byte[0x300]);
        bus.WriteLong(stack + 0x280u, returnAddress);
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        var allocationIndex = 0;
        bus.RegisterHostGateway(allocAddress, state =>
        {
            var index = allocationIndex++;
            Assert.True(index < allocationAddresses.Length);
            allocations.Add((state.D[0], state.D[1]));
            var address = allocationAddresses[index];
            bus.MapWritableMemory(address, new byte[checked((int)state.D[0])]);
            state.D[0] = address;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[1], state.D[0]));
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(codeAddress + (uint)allocatorEntryOffset, stack + 0x280u);
        cpu.State.A[6] = execBase;
        cpu.State.D[0] = width;
        cpu.State.D[1] = height;
        cpu.State.D[2] = planeBytes;
        cpu.State.D[3] = rawBytes;

        var returned = false;
        for (var index = 0; index < 80_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal((ushort)0x4452, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListFlags));
        Assert.Equal(screen, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListSystem));

        var screenResult = cpu.State.D[0];
        var viewResult = cpu.State.D[1];
        var rasInfoResult = cpu.State.D[2];
        var planeResult = cpu.State.D[3];
        var copListResult = cpu.State.D[4];
        var lofResult = cpu.State.D[5];
        var shfResult = cpu.State.D[6];
        var rawResult = cpu.State.D[7];

        // A wrong private tag must decline before touching any owner block.
        cpu.Reset(codeAddress + (uint)teardownEntryOffset, stack + 0x280u);
        cpu.State.A[6] = execBase;
        cpu.State.A[0] = screenResult;
        cpu.State.A[1] = viewResult;
        cpu.State.A[2] = rasInfoResult;
        cpu.State.A[3] = planeResult;
        cpu.State.A[4] = copListResult;
        cpu.State.A[5] = lofResult;
        cpu.State.D[0] = shfResult;
        cpu.State.D[1] = rawResult;
        cpu.State.D[2] = planeBytes;
        cpu.State.D[3] = rawBytes;
        cpu.State.D[4] = 0;
        returned = false;
        for (var index = 0; index < 100_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Empty(frees);

        cpu.Reset(codeAddress + (uint)teardownEntryOffset, stack + 0x280u);
        cpu.State.A[6] = execBase;
        cpu.State.A[0] = screenResult;
        cpu.State.A[1] = viewResult;
        cpu.State.A[2] = rasInfoResult;
        cpu.State.A[3] = planeResult;
        cpu.State.A[4] = copListResult;
        cpu.State.A[5] = lofResult;
        cpu.State.D[0] = shfResult;
        cpu.State.D[1] = rawResult;
        cpu.State.D[2] = planeBytes;
        cpu.State.D[3] = rawBytes;
        cpu.State.D[4] = 0x4452;

        returned = false;
        for (var index = 0; index < 100_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(execBase, cpu.State.A[6]);
        Assert.Equal(
