                (shfCpr, (uint)GraphicsLayouts.CprListSize),
                (lofCpr, (uint)GraphicsLayouts.CprListSize),
                (copList, (uint)GraphicsLayouts.CopListSize),
                (rawCopper, rawBytes),
                (plane, planeBytes),
                (rasInfo, (uint)GraphicsLayouts.RasInfoSize),
                (view, (uint)GraphicsLayouts.ViewSize),
                (screen, (uint)GraphicsLayouts.ScreenSize)
            },
            frees);
        Assert.Equal(0u, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(0u, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListSystem));
        Assert.Equal(0u, bus.ReadLong(lofCpr + (uint)GraphicsLayouts.CprListStart));
        Assert.Equal(0u, bus.ReadLong(shfCpr + (uint)GraphicsLayouts.CprListStart));
    }

