        Assert.Equal((ushort)GraphicsLayouts.CopperEndMask, bus.ReadWord(rawCopper + 46u));
        Assert.Equal((ushort)12, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListCount));
        Assert.Equal((ushort)12, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListMaxCount));
        Assert.Equal((ushort)12, bus.ReadWord(lofCpr + (uint)GraphicsLayouts.CprListMaxCount));
        Assert.Equal((ushort)12, bus.ReadWord(shfCpr + (uint)GraphicsLayouts.CprListMaxCount));
    }

