    [Fact]
    public void NativeGraphicsScreenPrefixTeardownClearsExactEmbeddedTopologyOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var prefixTeardownEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint screen = 0x00D0_0000;
        const uint view = 0x00D2_0000;
        const uint rasInfo = 0x00D3_0000;
        const uint plane = 0x00E0_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        var viewPort = screen + (uint)GraphicsLayouts.ScreenViewPort;
        var rastPort = screen + (uint)GraphicsLayouts.ScreenRastPort;
        var bitMap = screen + (uint)GraphicsLayouts.ScreenBitMap;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(screen, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ScreenSize).ToArray());
        bus.MapWritableMemory(view, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ViewSize).ToArray());
        bus.MapWritableMemory(rasInfo, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.RasInfoSize).ToArray());
        bus.MapWritableMemory(plane, Enumerable.Repeat((byte)0x5A, 0x100).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(stack + 0x80u, returnAddress);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(codeAddress + (uint)prefixTeardownEntryOffset, stack + 0x80u);
        cpu.State.A[0] = screen;
        cpu.State.A[1] = view;
        cpu.State.A[2] = rasInfo;
        cpu.State.D[0] = plane;

        var returned = false;
        for (var index = 0; index < 12_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal((byte)0, bus.ReadByte(screen));
        Assert.Equal((byte)0, bus.ReadByte(view));
        Assert.Equal((byte)0, bus.ReadByte(rasInfo));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
    }

