        bus.MapWritableMemory(plane1, Enumerable.Repeat((byte)0x6A, 0x100).ToArray());
        bus.MapWritableMemory(plane2, Enumerable.Repeat((byte)0x7A, 0x100).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(planeTable, plane0);
        bus.WriteLong(planeTable + 4u, plane1);
        bus.WriteLong(planeTable + 8u, plane2);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8u, plane2);
        bus.WriteLong(stack + 0x80u, returnAddress);

