        cpu.State.A[1] = view;
        cpu.State.A[2] = rasInfo;
        cpu.State.A[3] = planeTable;
        cpu.State.D[0] = 3;

        var returned = false;
        for (var index = 0; index < 16_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal((byte)0, bus.ReadByte(screen));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane0));
        Assert.Equal((byte)0x6A, bus.ReadByte(plane1));
        Assert.Equal((byte)0x7A, bus.ReadByte(plane2));
    }

