    [Fact]
    public void NativeGraphicsDrawEllipseRadiusOneSeventyFiveKeepsTheProviderFallbackBoundary()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.DrawEllipse],
            stack + 0x80u);
        cpu.State.A[1] = 0;
        cpu.State.D[0] = 0xCAFE_BABEu;
        cpu.State.D[1] = 0x1234_5678u;
        cpu.State.D[2] = 1;
        cpu.State.D[3] = 75;

        var returned = false;
        for (var index = 0; index < 8_000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        // RTS consumes the caller's long return address; the callee must not
        // leave any additional stack traffic behind on the provider fallback.
        Assert.Equal(stack + 0x84u, cpu.State.A[7]);
    }

    [Fact]
    public void NativeGraphicsVectorStubsExecuteThroughA68000HeadlessFixture()
    {
        // Keep all guest fixtures outside the default 2 MiB chip-RAM decode
        // window: AmigaBus intentionally gives chip RAM precedence over
        // separately mapped host-backed regions.
        const uint libraryBase = 0x0080_0000;
        const uint residentAddress = 0x00B0_0000;
        const uint codeAddress = 0x0080_0000;
        const uint stackAddress = 0x00C0_0000;
        var entryPoints = Enum.GetValues<GraphicsLvo>()
            .ToDictionary(vector => vector, _ => codeAddress);
        var image = NativeGraphicsLibraryImageBuilder.Build(
            libraryBase,
            residentAddress,
            libraryInitAddress: codeAddress,
            entryPoints: entryPoints,
            unimplementedEntry: codeAddress);

        var bus = new AmigaBus();
        bus.MapWritableMemory(image.VectorBase, image.VectorBytes);
        bus.MapWritableMemory(codeAddress, [0x70, 0x2A, 0x4E, 0x71]); // MOVEQ #42,D0; NOP
        bus.MapWritableMemory(stackAddress, new byte[0x100]);

        var vectorAddress = image.VectorBase + (uint)VectorOffset(GraphicsLvo.InitRastPort);
        Assert.Equal(0x4EF9, bus.ReadWord(vectorAddress));
        Assert.Equal(codeAddress, bus.ReadLong(vectorAddress + 2));
        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(vectorAddress, stackAddress);

        cpu.ExecuteInstruction(); // JMP.L codeAddress
        Assert.Equal(codeAddress, cpu.State.ProgramCounter);
        cpu.ExecuteInstruction(); // MOVEQ #42,D0
        Assert.Equal(42u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsHunkImageRelocatesResidentAndVectorPointersBeforeExecution()
    {
        var hunk = NativeGraphicsLibraryHunkBuilder.Build([0x70, 0x2A, 0x4E, 0x71]);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });

        var program = loader.Load(hunk.Bytes);
        Assert.Equal(2, program.SegmentBases.Count);

        var codeBase = program.SegmentBases[0];
        var residentBase = program.SegmentBases[1];
        var vectorAddress = codeBase + (uint)VectorOffset(GraphicsLvo.InitRastPort);
        Assert.Equal(0x4EF9, bus.ReadWord(vectorAddress));
        Assert.Equal(codeBase + (uint)hunk.NativeCodeOffset, bus.ReadLong(vectorAddress + 2));

        var libraryBase = codeBase + (uint)NativeGraphicsLibraryImageBuilder.VectorTableSize;
        Assert.Equal(
            libraryBase + (uint)GraphicsLibraryImageLayout.DefaultNameOffset,
            bus.ReadLong(libraryBase + 0x0A));
        Assert.Equal(residentBase, bus.ReadLong(residentBase + 2));
        Assert.Equal(
            residentBase + (uint)hunk.ResidentSegmentSize,
            bus.ReadLong(residentBase + 6));
        Assert.Equal(
            codeBase + (uint)hunk.NativeCodeOffset,
            bus.ReadLong(residentBase + 0x5C));
        Assert.Equal(
            residentBase + 0x60u,
            bus.ReadLong(residentBase + 0x54));

        const uint stackAddress = 0x00C0_0000;
        bus.MapWritableMemory(stackAddress, new byte[0x100]);
        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(vectorAddress, stackAddress);
        cpu.ExecuteInstruction();
        Assert.Equal(codeBase + (uint)hunk.NativeCodeOffset, cpu.State.ProgramCounter);
        cpu.ExecuteInstruction();
        Assert.Equal(42u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsRasterBodiesPackIntoRelocatableHunkWithSharedVectorMap()
    {
        var hunk = NativeGraphicsLibraryHunkBuilder.BuildFromRasterBodies();
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });

        var program = loader.Load(hunk.Bytes);
        Assert.Equal(2, program.SegmentBases.Count);

        var codeBase = program.SegmentBases[0];
        var residentBase = program.SegmentBases[1];
        var codeStart = codeBase + (uint)hunk.NativeCodeOffset;
        var initRastPortVector = codeBase + (uint)VectorOffset(GraphicsLvo.InitRastPort);
        var vectorTarget = bus.ReadLong(initRastPortVector + 2);
        var residentTarget = bus.ReadLong(
            residentBase + (uint)VectorArrayOffset(GraphicsLvo.InitRastPort));

        Assert.True(vectorTarget >= codeStart);
        Assert.Equal(vectorTarget, residentTarget);
        Assert.NotEqual(codeStart, vectorTarget);
    }

    [Fact]
    public void NativeGraphicsMonitorMutationHunkMapsPrivateSetterWithoutChangingPublicCatalog()
    {
        var hunk = NativeGraphicsLibraryHunkBuilder.BuildFromRasterBodies(
            positiveImageSize: GraphicsLibraryImageLayout.NativeMonitorImageSize,
            profile: GraphicsLibraryImageProfile.NativePal,
            includeNativeRuntimeDescriptor: true,
            initializeAllocatedImage: true,
            publishNativeMonitorDatabase: true,
            includeNativeMonitorDescriptor: true,
            publishNativeMonitorSpec: true,
            includeNativeMonitorMutation: true);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });

        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        var residentBase = program.SegmentBases[1];
        var codeStart = codeBase + (uint)hunk.NativeCodeOffset;
        var privateVector = codeBase + (uint)VectorOffset((int)GraphicsPrivateLvo.SetDisplayInfoData);
        var privateTarget = bus.ReadLong(privateVector + 2u);
        var residentTarget = bus.ReadLong(
            residentBase + (uint)VectorArrayOffset((int)GraphicsPrivateLvo.SetDisplayInfoData));
        var fallbackTarget = bus.ReadLong(
            residentBase + (uint)VectorArrayOffset(-648));

        Assert.InRange(privateTarget, codeStart, codeBase + (uint)hunk.NativeCodeOffset + 0x00FF_FFFEu);
        Assert.Equal(privateTarget, residentTarget);
        Assert.NotEqual(fallbackTarget, privateTarget);
        Assert.Equal(fallbackTarget,
            bus.ReadLong(codeBase + (uint)VectorOffset(-648) + 2u));
    }

    [Fact]
    public void NativeGraphicsRasterBodiesBuildFixedImageWithAbsoluteVectorMap()
    {
        const uint libraryBase = 0x0080_0000;
        // The generated native body is now larger than the original 1 MiB
        // code window. Keep the resident segment above it so the two mapped
        // guest regions cannot alias as the implementation grows.
        const uint residentAddress = 0x00C0_0000;
        const uint codeAddress = 0x0080_0000;
        const uint stackAddress = 0x00D0_0000;
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var relativeEntryOffsets,
            out _);
        var image = NativeGraphicsLibraryImageBuilder.BuildFromRasterBodies(
            libraryBase,
            residentAddress,
            codeAddress,
            libraryInitAddress: codeAddress);

        var bus = new AmigaBus();
        bus.MapWritableMemory(image.VectorBase, image.VectorBytes);
        bus.MapWritableMemory(libraryBase, image.PositiveBytes);
        bus.MapWritableMemory(residentAddress, image.ResidentBytes);
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(stackAddress, new byte[0x100]);

        var vectorAddress = image.VectorBase +
            (uint)VectorOffset(GraphicsLvo.InitRastPort);
        var expectedTarget = codeAddress +
            (uint)relativeEntryOffsets[GraphicsLvo.InitRastPort];
        Assert.Equal(expectedTarget, bus.ReadLong(vectorAddress + 2));
        Assert.Equal(
            expectedTarget,
            bus.ReadLong(
                residentAddress + (uint)VectorArrayOffset(GraphicsLvo.InitRastPort)));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(vectorAddress, stackAddress);
        cpu.ExecuteInstruction();
        Assert.Equal(expectedTarget, cpu.State.ProgramCounter);
    }

    [Fact]
    public void NativeGraphicsDisplayQueriesRecognizeCanonicalOcsEcsModeIdsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        const uint stack = 0x00C0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        uint Execute(GraphicsLvo vector, uint modeId)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.D[0] = modeId;
            cpu.State.A[6] = graphicsBase;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return cpu.State.D[0];
                }
            }

            throw new InvalidOperationException(
                $"Native {vector} display-query body did not return.");
        }

        Assert.Equal(
            GraphicsDisplayDatabase.DefaultModeHandle,
            Execute(GraphicsLvo.FindDisplayInfo, GraphicsModeIds.DefaultMonitor));
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey,
            Execute(
                GraphicsLvo.FindDisplayInfo,
                GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey));
        Assert.Equal(
            0u,
            Execute(
                GraphicsLvo.ModeNotAvailable,
                GraphicsModeIds.NtscMonitor | GraphicsModeIds.HamLaceKey));
        var superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        Assert.Equal(
            GraphicsDisplayDatabase.DiAvailNoChips,
            Execute(GraphicsLvo.ModeNotAvailable, superHires));
        Assert.Equal(
            superHires,
            Execute(GraphicsLvo.FindDisplayInfo, superHires));
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Assert.Equal(
            0u,
            Execute(GraphicsLvo.ModeNotAvailable, superHires));
        Assert.Equal(
            GraphicsDisplayDatabase.DiAvailNoMonitor,
            Execute(GraphicsLvo.ModeNotAvailable, GraphicsModeIds.Invalid));
        Assert.Equal(
            0u,
            Execute(GraphicsLvo.FindDisplayInfo, GraphicsModeIds.Invalid));

        Assert.Equal(
            GraphicsModeIds.DefaultMonitor,
            Execute(GraphicsLvo.NextDisplayInfo, GraphicsModeIds.Invalid));
        Assert.Equal(
            GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresKey,
            Execute(GraphicsLvo.NextDisplayInfo, GraphicsModeIds.DefaultMonitor));
        Assert.Equal(
            GraphicsModeIds.DefaultMonitor |
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey,
            Execute(
                GraphicsLvo.NextDisplayInfo,
                GraphicsModeIds.DefaultMonitor |
                GraphicsModeIds.HiresDualPlayfieldTwoLaceKey));
        Assert.Equal(
            GraphicsModeIds.PalMonitor,
            Execute(
                GraphicsLvo.NextDisplayInfo,
                GraphicsModeIds.DefaultMonitor |
                GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey));
        Assert.Equal(
            GraphicsModeIds.NtscMonitor,
            Execute(
                GraphicsLvo.NextDisplayInfo,
                GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey));
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey,
            Execute(
                GraphicsLvo.NextDisplayInfo,
                GraphicsModeIds.NtscMonitor | GraphicsModeIds.SuperHiresLaceKey));
        Assert.Equal(
            GraphicsModeIds.Invalid,
            Execute(
                GraphicsLvo.NextDisplayInfo,
                GraphicsModeIds.NtscMonitor |
                GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey));
        // Foreign/RTG monitor IDs remain provider-owned.  The native body
        // restores the caller's D0 and returns through the shared fallback.
        Assert.Equal(
            GraphicsModeIds.VgaMonitor,
            Execute(GraphicsLvo.FindDisplayInfo, GraphicsModeIds.VgaMonitor));
        Assert.Equal(
            GraphicsModeIds.VgaMonitor,
            Execute(GraphicsLvo.NextDisplayInfo, GraphicsModeIds.VgaMonitor));
    }

    [Fact]
    public void NativeGraphicsGetDisplayInfoDataPublishesCanonicalDtagChunksOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        const uint stack = 0x00C0_0000;
        const uint buffer = 0x00D0_0000;
        const uint graphicsBase = 0x00E0_0000;
        const uint monitorSpec = 0x00E1_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(buffer, new byte[0x60]);
        bus.MapWritableMemory(
            graphicsBase,
            new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.MapWritableMemory(
            monitorSpec,
            new byte[GraphicsLayouts.MonitorSpecSize]);
        bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            monitorSpec,
            0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        uint Execute(uint handle, uint bufferSize, uint tag, uint modeId)
        {
            for (var offset = 0u; offset < 0x60u; offset++)
                bus.WriteByte(buffer + offset, 0xA5, 0);

            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.GetDisplayInfoData),
                stack + 0x80u);
            cpu.State.A[0] = handle;
            cpu.State.A[1] = buffer;
            cpu.State.A[6] = graphicsBase;
            cpu.State.D[0] = bufferSize;
            cpu.State.D[1] = tag;
            cpu.State.D[2] = modeId;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return cpu.State.D[0];
            }

            throw new InvalidOperationException(
                "Native GetDisplayInfoData body did not return.");
        }

        var mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey;
        Assert.Equal(
            48u,
            Execute(0, GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp, mode));
        Assert.Equal(GraphicsDisplayDatabase.DtagDisp, bus.ReadLong(buffer + 0x00));
        Assert.Equal(mode, bus.ReadLong(buffer + 0x04));
        Assert.Equal(3u, bus.ReadLong(buffer + 0x08));
        Assert.Equal(4u, bus.ReadLong(buffer + 0x0C));
        Assert.Equal(0, bus.ReadWord(buffer + 0x10));
        Assert.Equal(
            GraphicsDisplayDatabase.DipfIsSprites |
            GraphicsDisplayDatabase.DipfIsSpritesAttached |
            GraphicsDisplayDatabase.DipfIsWb |
            GraphicsDisplayDatabase.DipfIsDbuffer |
            GraphicsDisplayDatabase.DipfIsPal,
            bus.ReadLong(buffer + 0x12));
        Assert.Equal(2, bus.ReadWord(buffer + 0x16));
        Assert.Equal(1, bus.ReadWord(buffer + 0x18));
        Assert.Equal(70, bus.ReadWord(buffer + 0x1A));
        Assert.Equal(8, bus.ReadWord(buffer + 0x1C));
        Assert.Equal(0x1000, bus.ReadWord(buffer + 0x1E));
        Assert.Equal(4, bus.ReadWord(buffer + 0x20));
        Assert.Equal(1, bus.ReadWord(buffer + 0x22));
        Assert.Equal(4, bus.ReadByte(buffer + 0x28));
        Assert.Equal(4, bus.ReadByte(buffer + 0x29));
        Assert.Equal(4, bus.ReadByte(buffer + 0x2A));
        for (var offset = 0x24u; offset < GraphicsDisplayDatabase.DisplayInfoChunkSize; offset++)
        {
            if (offset is >= 0x28 and <= 0x2A)
                continue;

            Assert.Equal(offset < 48 ? (byte)0 : (byte)0xA5, bus.ReadByte(buffer + offset));
        }

        // The generated ROM body reads the resident ChipRevBits0 capability
        // byte. A partial Alice-only declaration remains conservative.
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.AaAlice,
            0);
        Assert.Equal(
            48u,
            Execute(0, GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp, mode));
        Assert.Equal(
            0u,
            bus.ReadLong(buffer + 0x12) & GraphicsDisplayDatabase.DipfIsAa);
        Assert.Equal(4, bus.ReadByte(buffer + 0x28));

        // Both AA bits switch the same standard ModeID to Lisa's
        // RGB8/eight-plane record without changing the PAL timing geometry.
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetAa,
            0);
        Assert.Equal(
            48u,
            Execute(0, GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp, mode));
        Assert.NotEqual(
            0u,
            bus.ReadLong(buffer + 0x12) & GraphicsDisplayDatabase.DipfIsAa);
        Assert.Equal(ushort.MaxValue, bus.ReadWord(buffer + 0x1E));
        Assert.Equal(8, bus.ReadByte(buffer + 0x28));
        Assert.Equal(8, bus.ReadByte(buffer + 0x29));
        Assert.Equal(8, bus.ReadByte(buffer + 0x2A));

        Assert.Equal(
            66u,
            Execute(0, 0x58, GraphicsDisplayDatabase.DtagDims, mode));
        Assert.Equal(8, bus.ReadWord(buffer + 0x10));
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            0,
            0);

        // The query record preserves superhires enumeration, but on OCS its
        // DtagDisp availability agrees with ModeNotAvailable.  Both ECS
        // capability bits are required to publish it as available.
        var superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        Assert.Equal(
            48u,
            Execute(0, GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp, superHires));
        Assert.Equal(
            (ushort)GraphicsDisplayDatabase.DiAvailNoChips,
            bus.ReadWord(buffer + 0x10));
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)GraphicsChipRevision.SetEcs,
            0);
        Assert.Equal(
            48u,
            Execute(0, GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp, superHires));
        Assert.Equal(0, bus.ReadWord(buffer + 0x10));
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            0,
            0);

        Assert.Equal(
            48u,
            Execute(GraphicsDisplayDatabase.DefaultModeHandle,
                GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp,
                0xDEAD_BEEFu));
        Assert.Equal(GraphicsModeIds.PalMonitor, bus.ReadLong(buffer + 0x04));

        // The reserved-tail unit now owns this partial record. Compare it
        // with the full native record already checked above, then prove that
        // every byte beyond the requested prefix stays untouched.
        Assert.Equal(
            48u,
            Execute(0, GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp, mode));
        var fullDisplayPrefix = Enumerable.Range(0, 0x30)
            .Select(offset => bus.ReadByte(buffer + (uint)offset)).ToArray();
        Assert.Equal(
            0x30u,
            Execute(0, 0x30, GraphicsDisplayDatabase.DtagDisp, mode));
        for (var offset = 0u; offset < 0x60u; offset++)
            Assert.Equal(offset < 0x30 ? fullDisplayPrefix[(int)offset] : (byte)0xA5,
                bus.ReadByte(buffer + offset));

        Assert.Equal(
            0x38u,
            Execute(0, 0x38, GraphicsDisplayDatabase.DtagName, mode));
        Assert.Equal(GraphicsDisplayDatabase.DtagName, bus.ReadLong(buffer + 0x00));
        Assert.Equal(mode, bus.ReadLong(buffer + 0x04));
        Assert.Equal(3u, bus.ReadLong(buffer + 0x08));
        Assert.Equal(5u, bus.ReadLong(buffer + 0x0C));
        const string expectedName = "PAL hires";
        for (var offset = 0; offset < 31; offset++)
        {
            var expected = offset < expectedName.Length
                ? (byte)expectedName[offset]
                : (byte)0;
            Assert.Equal(expected, bus.ReadByte(buffer + 0x10u + (uint)offset));
        }

        Assert.Equal(
            66u,
            Execute(0, 0x58, GraphicsDisplayDatabase.DtagDims,
                GraphicsModeIds.NtscMonitor |
                GraphicsModeIds.SuperHiresLaceKey));
        Assert.Equal(GraphicsDisplayDatabase.DtagDims, bus.ReadLong(buffer + 0x00));
        Assert.Equal(
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.SuperHiresLaceKey,
            bus.ReadLong(buffer + 0x04));
        Assert.Equal(3u, bus.ReadLong(buffer + 0x08));
        Assert.Equal(8u, bus.ReadLong(buffer + 0x0C));
        Assert.Equal(2, bus.ReadWord(buffer + 0x10));
        Assert.Equal(64, bus.ReadWord(buffer + 0x12)); // MinRasterWidth, not nominal width
        Assert.Equal(1, bus.ReadWord(buffer + 0x14));
        Assert.Equal(1008, bus.ReadWord(buffer + 0x16));
        Assert.Equal(1024, bus.ReadWord(buffer + 0x18));
        Assert.Equal(0, bus.ReadWord(buffer + 0x1A));
        Assert.Equal(0, bus.ReadWord(buffer + 0x1C));
        Assert.Equal(1279, bus.ReadWord(buffer + 0x1E));
        Assert.Equal(399, bus.ReadWord(buffer + 0x20));
        Assert.Equal((short)-144, (short)bus.ReadWord(buffer + 0x22));
        Assert.Equal((short)-46, (short)bus.ReadWord(buffer + 0x24));
        Assert.Equal(1295, bus.ReadWord(buffer + 0x26));
        Assert.Equal(435, bus.ReadWord(buffer + 0x28));
        Assert.Equal((short)-144, (short)bus.ReadWord(buffer + 0x2A));
        Assert.Equal((short)-46, (short)bus.ReadWord(buffer + 0x2C));
        Assert.Equal(1295, bus.ReadWord(buffer + 0x2E));
        Assert.Equal(435, bus.ReadWord(buffer + 0x30));
        Assert.Equal(0, bus.ReadWord(buffer + 0x32));
        Assert.Equal(0, bus.ReadWord(buffer + 0x34));
        Assert.Equal(1279, bus.ReadWord(buffer + 0x36));
        Assert.Equal(399, bus.ReadWord(buffer + 0x38));
        Assert.Equal(0, bus.ReadWord(buffer + 0x3A));
        Assert.Equal(0, bus.ReadWord(buffer + 0x3C));
        Assert.Equal(1279, bus.ReadWord(buffer + 0x3E));
        Assert.Equal(399, bus.ReadWord(buffer + 0x40));

        Assert.Equal(
            88u,
            Execute(0, 0x60, GraphicsDisplayDatabase.DtagMntr,
                GraphicsModeIds.DefaultMonitor));
        Assert.Equal(GraphicsDisplayDatabase.DtagMntr, bus.ReadLong(buffer + 0x00));
        Assert.Equal(GraphicsModeIds.PalMonitor, bus.ReadLong(buffer + 0x04));
        Assert.Equal(3u, bus.ReadLong(buffer + 0x08));
        Assert.Equal(9u, bus.ReadLong(buffer + 0x0C));
        Assert.Equal(monitorSpec, bus.ReadLong(buffer + 0x10));
        Assert.Equal(129, bus.ReadWord(buffer + 0x14)); // original PAL/NTSC boot Point
        Assert.Equal(44, bus.ReadWord(buffer + 0x16));
        Assert.Equal(44, bus.ReadWord(buffer + 0x18));
        Assert.Equal(44, bus.ReadWord(buffer + 0x1A));
        Assert.Equal(93, bus.ReadWord(buffer + 0x1C));
        Assert.Equal(29, bus.ReadWord(buffer + 0x1E));
        Assert.Equal(136, bus.ReadWord(buffer + 0x20));
        Assert.Equal(57, bus.ReadWord(buffer + 0x22));
        Assert.Equal(312, bus.ReadWord(buffer + 0x24));
        Assert.Equal(226, bus.ReadWord(buffer + 0x26));
        Assert.Equal(29, bus.ReadWord(buffer + 0x28));
        Assert.Equal(0, bus.ReadWord(buffer + 0x2A));
        Assert.Equal(129, bus.ReadWord(buffer + 0x50)); // original ROM365 Point
        Assert.Equal(44, bus.ReadWord(buffer + 0x52));
        Assert.Equal(0x00029000u, bus.ReadLong(buffer + 0x54));
        for (var offset = 88u; offset < 96; offset++)
            Assert.Equal(0xA5, bus.ReadByte(buffer + offset));

        Assert.Equal(
            0x60u,
            Execute(0, 0x60, GraphicsDisplayDatabase.DtagMntr,
                GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresKey));
        for (var offset = 0u; offset < 0x60u; offset++)
            Assert.Equal(0xA5, bus.ReadByte(buffer + offset));

        bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0,
            0);
        Assert.Equal(
            0x60u,
            Execute(0, 0x60, GraphicsDisplayDatabase.DtagMntr,
                GraphicsModeIds.DefaultMonitor));
        for (var offset = 0u; offset < 0x60u; offset++)
            Assert.Equal(0xA5, bus.ReadByte(buffer + offset));
    }

    [Fact]
    public void NativeGraphicsRasterBodiesExecutePenAndModeStateVectors()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });

        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        var codeStart = codeBase + (uint)hunk.NativeCodeOffset;
        const uint rastPort = 0x00D0_0000;
        const uint stack = 0x00C0_0000;
        const uint textAddress = 0x00E1_0000;
        const uint extentAddress = 0x00E2_0000;
        const uint pixelBitMap = 0x00E3_0000;
        const uint pixelPlane = 0x00E4_0000;
        const uint pixelPlane2 = 0x00E5_0000;
        const uint fontCharData = 0x00E6_0000;
        const uint polyPoints = 0x00E7_0000;
        const uint colorMap = 0x00E8_0000;
        const uint colorTable = 0x00E9_0000;
        const uint lowColorTable = 0x00EA_0000;
        const uint rgb32Output = 0x00EB_0000;
        const uint modeViewPort = 0x00EC_0000;
        const uint rgb4Input = 0x00ED_0000;
        const uint rgb32Input = 0x00EE_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapWritableMemory(textAddress, new byte[0x20]);
        bus.MapWritableMemory(extentAddress, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(pixelBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(pixelPlane, new byte[0x100]);
        bus.MapWritableMemory(pixelPlane2, new byte[0x100]);
        bus.MapWritableMemory(fontCharData, new byte[0x100]);
        bus.MapWritableMemory(polyPoints, new byte[0x20]);
        bus.MapWritableMemory(colorMap, new byte[GraphicsLayouts.ColorMapSize]);
        bus.MapWritableMemory(colorTable, new byte[0x20]);
        bus.MapWritableMemory(lowColorTable, new byte[0x20]);
        bus.MapWritableMemory(rgb32Output, new byte[12]);
        bus.MapWritableMemory(modeViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rgb4Input, new byte[0x20]);
        bus.MapWritableMemory(rgb32Input, new byte[0x80]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void ExecuteSetter(
            GraphicsLvo vector,
            uint d0,
            uint d1,
            uint d2,
            int _bodyInstructionCount,
            uint? port = null)
        {
            const uint returnAddress = 0x00F0_0000;
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            // Do not alias A0 and A1 in this mixed-vector helper.
            var argumentRegister = vector is GraphicsLvo.SetWriteMask or GraphicsLvo.SetOutlinePen or GraphicsLvo.SetMaxPen ? 0 : 1;
            cpu.State.A[0] = 0xA0A0_A0A1;
            cpu.State.A[1] = 0xA1A1_A1A1;
            cpu.State.A[argumentRegister] = port ?? rastPort;
            cpu.State.D[0] = d0;
            cpu.State.D[1] = d1;
            cpu.State.D[2] = d2;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 10_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException($"Native {vector} body did not return.");
        }

        void ExecuteInitRastPort()
        {
            const uint returnAddress = 0x00F0_0000;
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitRastPort),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.A[6] = codeBase + (uint)NativeGraphicsLibraryImageBuilder.VectorTableSize;
            cpu.State.D[0] = 0xCAFE_BABEu;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 10_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    Assert.Equal(stack + 0x84u, cpu.State.A[7]);
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native InitRastPort body did not return.");
        }

        void ExecuteInitView(uint view)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitView),
                stack + 0x80u);
            cpu.State.A[1] = view;
            cpu.State.D[0] = 0xCAFE_BABEu;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 40; index++)
                cpu.ExecuteInstruction();
        }

        void ExecuteInitVPort(uint viewPort)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitVPort),
                stack + 0x80u);
            cpu.State.A[0] = viewPort;
            cpu.State.D[0] = 0xCAFE_BABEu;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 48; index++)
                cpu.ExecuteInstruction();
        }

        void ExecuteInitBitMap(uint bitMap, byte depth, ushort width, ushort height)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitBitMap),
                stack + 0x80u);
            cpu.State.A[0] = bitMap;
            cpu.State.D[0] = depth;
            cpu.State.D[1] = width;
            cpu.State.D[2] = height;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 48; index++)
                cpu.ExecuteInstruction();
        }

        void ExecuteInitTmpRas(uint tmpRas, uint buffer, uint byteCount)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitTmpRas),
                stack + 0x80u);
            cpu.State.A[0] = tmpRas;
