        void ExecuteReadPixel(
            uint pixelRastPort,
            short x,
            short y,
            uint initialD0,
            int _bodyInstructionCount)
        {
            const uint returnAddress = 0x00F0_0000;
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.ReadPixel),
                stack + 0x80u);
            cpu.State.A[1] = pixelRastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)x);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 10_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native ReadPixel body did not return.");
        }

        void ExecuteWritePixel(
            uint pixelRastPort,
            short x,
            short y,
            uint initialD0,
            int _bodyInstructionCount)
        {
            // Native WritePixel has several draw-mode paths.  Return through
            // a mapped sentinel instead of baking one instruction count per
            // branch into the fixture.
            const uint returnAddress = 0x00F0_0000;
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.WritePixel),
                stack + 0x80u);
            cpu.State.A[1] = pixelRastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)x);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 10000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native WritePixel body did not return.");
        }

        void ExecuteSetRast(uint setRastPort, uint pen)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.SetRast),
                stack + 0x80u);
            cpu.State.A[1] = setRastPort;
            cpu.State.D[0] = pen;
            cpu.ExecuteInstruction(); // vector JMP.L

            // SetRast contains data-dependent plane and byte loops.  The
            // fixture stack is zero-filled, so the body's RTS returns to PC
            // zero; this executes the real loop count without baking an
            // instruction-count assumption into the regression.
            for (var index = 0; index < 10_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native SetRast body did not return.");
        }

