        ExecuteSetter(GraphicsLvo.SetAPen, 0xCAFE_0005u, 0, 0, 2);
        Assert.Equal((byte)5, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetBPen, 0xDEAD_0006u, 0, 0, 2);
        Assert.Equal((byte)6, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetDrMd, 0xBEEF_0007u, 0, 0, 2);
        Assert.Equal((byte)7, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal((byte)0x6A, bus.ReadByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetABPenDrMd, 2, 3, 4, 4);
        Assert.Equal((byte)2, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)3, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)4, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal(
                plane == 1 ? (byte)0xBA : (byte)0x8A,
                bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)0,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            0x4000);
        ExecuteSetter(GraphicsLvo.Move, 0xFFFE, 0x0003, 0, 9);
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)0x4001,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetWriteMask, 0xCAFE_00A5u, 0, 0, 2);
        Assert.Equal((byte)0xA5, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(uint.MaxValue, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetMaxPen, 0, 0, 0, 4);
        Assert.Equal((byte)0xA5, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetMaxPen, 1, 0, 0, 9);
        Assert.Equal((byte)0x01, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetMaxPen, 3, 0, 0, 14);
        Assert.Equal((byte)0x03, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteSetter(GraphicsLvo.SetMaxPen, 0xFF, 0, 0, 44);
        Assert.Equal((byte)0xFF, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
            0x03,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            0x4000);
        ExecuteSetter(GraphicsLvo.SetOutlinePen, 0xDEAD_0007u, 0, 0, 7);
        Assert.Equal((byte)7, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(
            (ushort)0x4008,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(3u, cpu.State.D[0]);

        // The guarded native arm must not read either published field through
        // an odd RastPort. It restores the full input for the portable owner.
        ExecuteSetter(
            GraphicsLvo.SetOutlinePen,
            0xCAFE_0009u,
            0,
            0,
            7,
            rastPort + 1u);
        Assert.Equal(0xCAFE_0009u, cpu.State.D[0]);
        Assert.Equal((byte)7, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(
            (ushort)0x4008,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));

        const uint nativeFont = 0x00E0_0000;
        bus.MapWritableMemory(nativeFont, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontXSize, 7);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontBaseline, 6);
        bus.WriteLong(
            codeBase + (uint)NativeGraphicsLibraryImageBuilder.VectorTableSize +
                (uint)GraphicsLayouts.GfxBaseDefaultFont,
            nativeFont);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            bus.WriteByte(rastPort + (uint)offset, 0xCC, 0);

        ExecuteInitRastPort();
        Assert.Equal((byte)0xFF, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal((byte)0xFF, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)0xFF, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal((byte)1, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((ushort)0xFFFF, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern));
        Assert.Equal(nativeFont, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)9, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)7, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)6, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        for (var offset = 0x44; offset < 100; offset++)
            Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)offset));
        for (var offset = 100; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            Assert.Equal((byte)0xCC, bus.ReadByte(rastPort + (uint)offset));
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)0xCA, bus.ReadByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)index));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteLong(
            codeBase + (uint)NativeGraphicsLibraryImageBuilder.VectorTableSize +
                (uint)GraphicsLayouts.GfxBaseDefaultFont,
            0);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            bus.WriteByte(rastPort + (uint)offset, 0xCC, 0);
        ExecuteInitRastPort();
        Assert.Equal(0u, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal(0u, cpu.State.D[0]);

        const uint view = 0x00D1_0000;
        const uint viewPort = 0x00D2_0000;
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            bus.WriteByte(view + (uint)offset, 0xCC, 0);
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            bus.WriteByte(viewPort + (uint)offset, 0xCC, 0);

        ExecuteInitView(view);
        Assert.Equal(0u, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(
            (ushort)GraphicsLayouts.ViewDefaultDyOffset,
            bus.ReadWord(view + (uint)GraphicsLayouts.ViewDyOffset));
        Assert.Equal(
            (ushort)GraphicsLayouts.ViewDefaultDxOffset,
            bus.ReadWord(view + (uint)GraphicsLayouts.ViewDxOffset));
        Assert.Equal((ushort)0, bus.ReadWord(view + (uint)GraphicsLayouts.ViewModes));
        Assert.Equal(0u, cpu.State.D[0]);

        ExecuteInitVPort(viewPort);
        Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortNext));
        Assert.Equal(
            GraphicsLayouts.ViewPortDefaultSpritePriorities,
            bus.ReadByte(viewPort + (uint)GraphicsLayouts.ViewPortSpritePriorities));
        Assert.Equal((byte)0, bus.ReadByte(viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes));
        Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(0u, cpu.State.D[0]);

        const uint bitMap = 0x00D3_0000;
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            bus.WriteByte(bitMap + (uint)offset, 0xCC, 0);
        ExecuteInitBitMap(bitMap, 5, 320, 200);
        Assert.Equal((ushort)40, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)200, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)8, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)5, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal((ushort)0, bus.ReadWord(bitMap + 6u));
        Assert.Equal((byte)0xCC, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal(0u, cpu.State.D[0]);

        const uint tmpRas = 0x00D4_0000;
        const uint tmpBuffer = 0x00D5_0000;
        bus.MapWritableMemory(tmpRas, new byte[GraphicsLayouts.TmpRasSize]);
        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            bus.WriteByte(tmpRas + (uint)offset, 0xCC, 0);
        ExecuteInitTmpRas(tmpRas, tmpBuffer, 1234);
        Assert.Equal(tmpBuffer, bus.ReadLong(tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(1234u, bus.ReadLong(tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));
        Assert.Equal(0u, cpu.State.D[0]);

        const uint areaInfo = 0x00D6_0000;
        const uint areaBuffer = 0x00D7_0000;
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(areaBuffer, new byte[0x40]);
        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            bus.WriteByte(areaInfo + (uint)offset, 0xCC, 0);
        for (var offset = 0; offset < 0x40; offset++)
            bus.WriteByte(areaBuffer + (uint)offset, 0xAA, 0);

        ExecuteInitArea(areaInfo, areaBuffer, 4);
        Assert.Equal(areaBuffer, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(areaBuffer, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(areaBuffer + 16u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));
        Assert.Equal(areaBuffer + 16u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)4, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));
        for (var offset = 0; offset < 0x40; offset++)
            Assert.Equal((byte)0xAA, bus.ReadByte(areaBuffer + (uint)offset));
        Assert.Equal(0u, cpu.State.D[0]);

        // An empty collector is a native AreaEnd no-op: no bitmap or area
        // storage is consumed, and the void result is cleared.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        ExecuteAreaEnd(rastPort, 0xFACE_B000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((byte)0xAA, bus.ReadByte(areaBuffer));

        // Native AreaMove claims only a fresh first MOVE in an empty,
        // initialized AreaInfo. The vector/flag cells and collector metadata
        // are published in one compact guest-layout transaction.
        bus.WriteByte(areaBuffer + 0u, 0xAA, 0);
        bus.WriteByte(areaBuffer + 1u, 0xAA, 0);
        bus.WriteByte(areaBuffer + 2u, 0xAA, 0);
        bus.WriteByte(areaBuffer + 3u, 0xAA, 0);
        bus.WriteByte(areaBuffer + 16u, 0xAA, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        ExecuteAreaMove(rastPort, 10, -4, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)10, bus.ReadWord(areaBuffer + 0u));
        Assert.Equal(unchecked((ushort)-4), bus.ReadWord(areaBuffer + 2u));
        Assert.Equal((byte)0, bus.ReadByte(areaBuffer + 16u));
        Assert.Equal(areaBuffer + 4u, bus.ReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(areaBuffer + 17u, bus.ReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)1, bus.ReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)10, bus.ReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal(unchecked((ushort)-4), bus.ReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        // Recorded geometry remains on the portable/provider AreaEnd path.
        ExecuteAreaEnd(rastPort, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);

        // A fresh one-point chain admits exactly one AreaDraw append.
        ExecuteAreaDraw(rastPort, 20, 6, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)20, bus.ReadWord(areaBuffer + 4u));
        Assert.Equal((ushort)6, bus.ReadWord(areaBuffer + 6u));
        Assert.Equal((byte)1, bus.ReadByte(areaBuffer + 17u));
        Assert.Equal(areaBuffer + 8u, bus.ReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(areaBuffer + 18u, bus.ReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)2, bus.ReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        // A second DRAW append is native when the collector has capacity.
        ExecuteAreaDraw(rastPort, 30, 7, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(areaBuffer + 8u));
        Assert.Equal((ushort)7, bus.ReadWord(areaBuffer + 10u));
        Assert.Equal((byte)1, bus.ReadByte(areaBuffer + 18u));
        Assert.Equal(areaBuffer + 12u, bus.ReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(areaBuffer + 19u, bus.ReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)3, bus.ReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        // A third or later chain point remains on the portable/provider owner
        // and preserves the incoming void-vector D0.
        ExecuteAreaDraw(rastPort, 40, 8, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u | 40u, cpu.State.D[0]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, 0);
        ExecuteAreaDraw(rastPort, 40, 8, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u | 40u, cpu.State.D[0]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, pixelPlane2);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, pixelBitMap);
        bus.WriteByte(pixelPlane + 2u, 0x10, 0); // y=1, x=3 (MSB-first)
        ExecuteReadPixel(rastPort, 3, 1, 0xCAFE_0000u, 33);
        Assert.Equal(1u, cpu.State.D[0]);

        bus.WriteByte(pixelPlane + 2u, 0, 0);
        ExecuteReadPixel(rastPort, 3, 1, 0xBEEF_0000u, 33);
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(pixelPlane + 2u, 0x10, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0, 0);
        ExecuteReadPixel(rastPort, 3, 1, 0xDEAD_0000u, 43);
        Assert.Equal(1u, cpu.State.D[0]);
        bus.WriteByte(pixelPlane2 + 2u, 0x10, 0);
        ExecuteReadPixel(rastPort, 3, 1, 0xFACE_0000u, 43);
        Assert.Equal(3u, cpu.State.D[0]);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, 0);
        ExecuteReadPixel(rastPort, 3, 1, 0xFACE_0000u, 3);
        Assert.Equal(0xFACE_0003u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, pixelBitMap);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        for (var offset = 0; offset < 16; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x5A, 0);
        }

        ExecuteSetRast(rastPort, 2);
        for (var offset = 0; offset < 16; offset++)
        {
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + (uint)offset));
        }
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        for (var offset = 0; offset < 16; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x5A, 0);
        }

        ExecuteSetRast(rastPort, 1);
        for (var offset = 0; offset < 16; offset++)
        {
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + (uint)offset));
        }
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0, 0);
        for (var offset = 0; offset < 16; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0x3C, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0xC3, 0);
        }

        ExecuteSetRast(rastPort, 3);
        for (var offset = 0; offset < 16; offset++)
        {
            Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane2 + (uint)offset));
        }
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, 0);
        ExecuteSetRast(rastPort, 0xCAFE_0002u);
        Assert.Equal(0xCAFE_0002u, cpu.State.D[0]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, pixelBitMap);

        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 0, 0);
        ExecuteSetRast(rastPort, 0xDEAD_0001u);
        Assert.Equal(0xDEAD_0001u, cpu.State.D[0]);

        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
        ExecuteSetRast(rastPort, 0xBEEF_0001u);
        Assert.Equal(0xBEEF_0001u, cpu.State.D[0]);
        for (var offset = 0; offset < 16; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + (uint)offset));

        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, pixelPlane2);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        // Native EraseRect claims the exact one-pixel BPen/JAM1 form. The
        // write uses the same MSB-first planar bit convention as ReadPixel
        // and preserves the caller's line-pattern phase. Rectangles and
        // malformed state remain transparent.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        bus.WriteByte(pixelPlane + 2u, 0, 0); // y=1, x=3
        ExecuteEraseRect(rastPort, 3, 1, 3, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)4, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        ExecuteEraseRect(rastPort, 3, 1, 3, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));

        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        ExecuteEraseRect(rastPort, 3, 1, 4, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0003u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));

        // The native EraseRect body also claims an exact aligned eight-pixel
        // row slice.  It clears or fills one complete MSB-first planar byte,
        // while preserving the same JAM1/BPen and phase-preservation
        // semantics as the one-pixel form.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 6, 0);
        bus.WriteByte(pixelPlane + 3u, 0xA5, 0); // y=1, x=8..15
        ExecuteEraseRect(rastPort, 8, 1, 15, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)6, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(pixelPlane + 3u, 0xA5, 0);
        ExecuteEraseRect(rastPort, 8, 1, 15, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 3u));

        // The same guarded arm admits an exact aligned sixteen-pixel row when
        // the public stride provides two destination bytes.  Both bytes are
        // published only after the BPen value has been normalized.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(pixelPlane + 5u, 0xA5, 0); // y=1, x=8..15
        bus.WriteByte(pixelPlane + 6u, 0x5A, 0); // x=16..23
        ExecuteEraseRect(rastPort, 8, 1, 23, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 6u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(pixelPlane + 5u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 6u, 0x5A, 0);
        ExecuteEraseRect(rastPort, 8, 1, 23, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 6u));

        bus.WriteByte(pixelPlane + 5u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 6u, 0x5A, 0);
        ExecuteEraseRect(rastPort, 8, 1, 24, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 6u));

        // Widths other than one pixel or one aligned byte stay on the
        // portable/fallback owner and retain the caller's xMin in D0.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(pixelPlane + 3u, 0xA5, 0);
        ExecuteEraseRect(rastPort, 8, 1, 16, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 3u));

        // The same native arm admits an exact aligned thirty-two-pixel row
        // when the public stride provides four destination bytes.  All four
        // bytes share the BPen and line-pattern transaction of the narrower
        // forms; the following width remains on the fallback owner.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 6);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(pixelPlane + 7u, 0xA5, 0); // y=1, x=8..15
        bus.WriteByte(pixelPlane + 8u, 0x5A, 0); // x=16..23
        bus.WriteByte(pixelPlane + 9u, 0x3C, 0); // x=24..31
        bus.WriteByte(pixelPlane + 10u, 0xC3, 0); // x=32..39
        ExecuteEraseRect(rastPort, 8, 1, 39, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 7u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 9u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 10u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(pixelPlane + 7u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 8u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 9u, 0x3C, 0);
        bus.WriteByte(pixelPlane + 10u, 0xC3, 0);
        ExecuteEraseRect(rastPort, 8, 1, 39, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 7u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 9u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 10u));

        bus.WriteByte(pixelPlane + 7u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 8u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 9u, 0x3C, 0);
        bus.WriteByte(pixelPlane + 10u, 0xC3, 0);
        ExecuteEraseRect(rastPort, 8, 1, 40, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 7u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane + 9u));
        Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane + 10u));

        // Complete the native width family with an exact aligned sixty-four-
        // pixel row.  The ten-byte public stride places the eight-byte span
        // at offsets 11..18 for y=1 and leaves a guard byte untouched.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 10);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(pixelPlane + 10u, 0x11, 0); // guard before x=8
        bus.WriteByte(pixelPlane + 11u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 12u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 13u, 0x3C, 0);
        bus.WriteByte(pixelPlane + 14u, 0xC3, 0);
        bus.WriteByte(pixelPlane + 15u, 0x96, 0);
        bus.WriteByte(pixelPlane + 16u, 0x69, 0);
        bus.WriteByte(pixelPlane + 17u, 0xF0, 0);
        bus.WriteByte(pixelPlane + 18u, 0x0F, 0);
        bus.WriteByte(pixelPlane + 19u, 0x22, 0); // guard after x=71
        ExecuteEraseRect(rastPort, 8, 1, 71, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 11u; offset <= 18u; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + offset));
        Assert.Equal((byte)0x11, bus.ReadByte(pixelPlane + 10u));
        Assert.Equal((byte)0x22, bus.ReadByte(pixelPlane + 19u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(pixelPlane + 11u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 12u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 13u, 0x3C, 0);
        bus.WriteByte(pixelPlane + 14u, 0xC3, 0);
        bus.WriteByte(pixelPlane + 15u, 0x96, 0);
        bus.WriteByte(pixelPlane + 16u, 0x69, 0);
        bus.WriteByte(pixelPlane + 17u, 0xF0, 0);
        bus.WriteByte(pixelPlane + 18u, 0x0F, 0);
        ExecuteEraseRect(rastPort, 8, 1, 71, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 11u; offset <= 18u; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + offset));
        Assert.Equal((byte)0x11, bus.ReadByte(pixelPlane + 10u));
        Assert.Equal((byte)0x22, bus.ReadByte(pixelPlane + 19u));

        bus.WriteByte(pixelPlane + 11u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 12u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 13u, 0x3C, 0);
        bus.WriteByte(pixelPlane + 14u, 0xC3, 0);
        bus.WriteByte(pixelPlane + 15u, 0x96, 0);
        bus.WriteByte(pixelPlane + 16u, 0x69, 0);
        bus.WriteByte(pixelPlane + 17u, 0xF0, 0);
        bus.WriteByte(pixelPlane + 18u, 0x0F, 0);
        ExecuteEraseRect(rastPort, 8, 1, 72, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 11u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 12u));
        Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane + 13u));
        Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane + 14u));
        Assert.Equal((byte)0x96, bus.ReadByte(pixelPlane + 15u));
        Assert.Equal((byte)0x69, bus.ReadByte(pixelPlane + 16u));
        Assert.Equal((byte)0xF0, bus.ReadByte(pixelPlane + 17u));
        Assert.Equal((byte)0x0F, bus.ReadByte(pixelPlane + 18u));

        // The aligned width family extends to a sixteen-byte, 128-pixel
        // one-plane row.  Keep guards on both sides of the y=1 span and
        // verify that BPen selects the complete byte value without touching
        // adjacent storage.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 18);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 40; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        bus.WriteByte(pixelPlane + 18u, 0x11, 0);
        bus.WriteByte(pixelPlane + 35u, 0x22, 0);
        ExecuteEraseRect(rastPort, 8, 1, 135, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 19u; offset <= 34u; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + offset));
        Assert.Equal((byte)0x11, bus.ReadByte(pixelPlane + 18u));
        Assert.Equal((byte)0x22, bus.ReadByte(pixelPlane + 35u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 19u; offset <= 34u; offset++)
            bus.WriteByte(pixelPlane + offset, 0xA5, 0);
        ExecuteEraseRect(rastPort, 8, 1, 135, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 19u; offset <= 34u; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + offset));

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteByte(pixelPlane + 1u, 0x5A, 0);
        ExecuteEraseRect(rastPort, 8, 1, 135, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 1u));

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 18);
        bus.WriteByte(pixelPlane + 19u, 0xA5, 0);
        ExecuteEraseRect(rastPort, 8, 1, 136, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 19u));

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        for (var offset = 0; offset < 32; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteRectFill(rastPort, 3, 1, 10, 2, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 5u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteRectFill(rastPort, 3, 1, 10, 2, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 5u));

        // With a NULL area pattern, ordinary JAM2 is the same foreground
        // source as JAM1 for RectFill.  The native one-plane arm admits it
        // without consuming BPen or changing the provider boundary.
        bus.WriteByte(pixelPlane + 2u, 0x00, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        ExecuteRectFill(rastPort, 3, 1, 3, 1, 0xDEAD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));

        // COMPLEMENT remains outside this bounded arm and must preserve the
        // caller's void-vector register state and destination bytes.
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 2, 0);
        ExecuteRectFill(rastPort, 3, 1, 3, 1, 0xDEAD_0000u);
        Assert.Equal(0xDEAD_0003u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        ExecuteRectFill(rastPort, 10, 1, 3, 1, 0xFACE_0000u);
        Assert.Equal(0xFACE_000Au, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));

        // The native RectFill dispatch now has a guarded depth-2..8 form for
        // one aligned eight-pixel row. APen selects each plane bit while the
        // complete plane-link preflight prevents partial publication.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 2, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 16);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, pixelPlane2);
        for (var index = 0; index < 16; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 15, 0, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + 1u));
        // yMax is an inclusive coordinate, not a depth-derived row count.
        // Keep every later row as a guard so the multi-plane native loop
        // cannot publish depth+1 rows when the request is one row tall.
        for (var row = 1; row < 4; row++)
        {
            var byteOffset = (uint)(row * 4 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + byteOffset));
        }

        // Complete the guarded multi-plane width family with an exact aligned
        // 128-pixel span.  An eighteen-byte public stride carries two rows at
        // offsets 1..16 and 19..34; sentinels immediately outside and between
        // the rows prove that the inner DBRA stops at 16.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 18);
        for (var index = 0; index < 64; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }
        bus.WriteByte(pixelPlane + 0u, 0x11, 0);
        bus.WriteByte(pixelPlane + 17u, 0x22, 0);
        bus.WriteByte(pixelPlane + 35u, 0x44, 0);
        bus.WriteByte(pixelPlane2 + 0u, 0x55, 0);
        bus.WriteByte(pixelPlane2 + 17u, 0x66, 0);
        bus.WriteByte(pixelPlane2 + 35u, 0x88, 0);

        ExecuteRectFill(rastPort, 8, 0, 135, 1, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 1u; offset <= 16u; offset++)
        {
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + offset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + offset));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 18u + offset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + 18u + offset));
        }
        Assert.Equal((byte)0x11, bus.ReadByte(pixelPlane + 0u));
        Assert.Equal((byte)0x22, bus.ReadByte(pixelPlane + 17u));
        Assert.Equal((byte)0x44, bus.ReadByte(pixelPlane + 35u));
        Assert.Equal((byte)0x55, bus.ReadByte(pixelPlane2 + 0u));
        Assert.Equal((byte)0x66, bus.ReadByte(pixelPlane2 + 17u));
        Assert.Equal((byte)0x88, bus.ReadByte(pixelPlane2 + 35u));

        // A stride one byte short cannot contain the complete marker and must
        // decline transactionally.  Width 129 is likewise outside the exact
        // aligned native form even when the stride is wide enough.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 15);
        bus.WriteByte(pixelPlane + 1u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0x5A, 0);
        ExecuteRectFill(rastPort, 8, 0, 135, 0, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 1u));

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 18);
        bus.WriteByte(pixelPlane + 1u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0x5A, 0);
        ExecuteRectFill(rastPort, 8, 0, 136, 0, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 1u));

        // Restore the narrower stride for the remaining transactional cases.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);

        // A zero write mask is a successful no-op after native geometry/state
        // admission; it must not require or mutate any selected plane bytes.
        bus.WriteByte(pixelPlane + 1u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0x5A, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0, 0);
        ExecuteRectFill(rastPort, 8, 0, 15, 0, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 1u));
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF, 0);

        // A partial write mask publishes only the selected plane. The
        // unselected plane link is intentionally absent to prove that its
        // storage is neither required nor touched by the native arm.
        bus.WriteByte(pixelPlane + 1u, 0x00, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0x5A, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        ExecuteRectFill(rastPort, 8, 0, 15, 0, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 1u));
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, pixelPlane2);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 2, 0);

        // Nonzero ordered y bounds use the same guarded multi-plane arm. The
        // first and fourth rows remain sentinels while rows one and two are
        // selected through the public planar stride.
        for (var index = 0; index < 16; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 1, 15, 2, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 1u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + 5u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 9u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + 9u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 13u));

        // Ordered geometry and the public row envelope remain transactional:
        // inverted bounds and yMax==Rows preserve D0 and every plane byte.
        ExecuteRectFill(rastPort, 8, 3, 15, 2, 0xABCD_0000u);
        Assert.Equal(0xABCD_0008u, cpu.State.D[0]);
        ExecuteRectFill(rastPort, 8, 0, 15, 16, 0xABCD_0000u);
        Assert.Equal(0xABCD_0008u, cpu.State.D[0]);

        // A final-row address carry declines before any selected plane can be
        // published, even though the pointer links themselves are readable.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 0xFFFE);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, 0xFFFF_FFF0u);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, 0xFFFF_FFF0u);
        ExecuteRectFill(rastPort, 8, 0, 15, 15, 0xABCD_0000u);
        Assert.Equal(0xABCD_0008u, cpu.State.D[0]);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, pixelPlane2);

        // The same guarded native form now admits a top-aligned multi-row
        // span. Each row advances by the declared planar stride, while the
        // complete plane preflight and APen selection remain unchanged.
        for (var index = 0; index < 16; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 15, 3, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 4 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
        }

        // The bounded multi-plane y envelope includes the first row beyond
        // the original 0..15 contract.  A seventeen-row request reaches row
        // sixteen exactly and must not publish row seventeen.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 17);
        for (var index = 0; index < 72; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 15, 16, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 17; row++)
        {
            var byteOffset = (uint)(row * 4 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
        }

        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 69u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 69u));
        for (var index = 0; index < 72; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 16);

        // The native arm now relies on the signed WORD geometry plus the
        // public row count rather than an artificial yMax ceiling.  Prove the
        // first post-ceiling span through row thirty-two and keep row thirty-
        // three untouched.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 33);
        for (var index = 0; index < 136; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 15, 32, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 33; row++)
        {
            var byteOffset = (uint)(row * 4 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
        }

        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 133u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 133u));
        for (var index = 0; index < 136; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 16);

        // The same native admission also owns an exact two-byte, sixteen-
        // pixel aligned span. Both bytes in every admitted row receive the
        // selected plane value, while the unsupported seventeen-pixel form
        // remains transparent to the fallback owner.
        for (var index = 0; index < 16; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 23, 3, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 4 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 1u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 1u));
        }

        // The same native admission also owns an exact three-byte,
        // twenty-four-pixel aligned span. The byte-count marker drives the
        // nested 68000 byte loop, while the unsupported twenty-five-pixel
        // form remains transparent to the fallback owner.
        for (var index = 0; index < 16; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 31, 3, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 4 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 1u));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 2u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 1u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 2u));
        }
        // The inclusive yMax bound must not spill into the following row.
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 17u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 17u));

        // The same native admission also owns an exact four-byte,
        // thirty-two-pixel aligned span. The widened row stride admits all
        // four byte stores, while the unsupported widths below remain on the
        // strict fallback path.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 8);
        for (var index = 0; index < 32; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 39, 3, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 8 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 1u));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 2u));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 3u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 1u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 2u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 3u));
        }
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 33u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 33u));

        // Exact five-, six-, and seven-byte aligned spans extend the same
        // guarded native row marker without changing the strict fallback
        // boundary.  The byte offset remains one because xMin is byte
        // aligned at eight pixels.
        for (var index = 0; index < 32; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 47, 3, 0x5000_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 8 + 1);
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 1u));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 2u));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 3u));
            Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + 4u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 1u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 2u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 3u));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + 4u));
        }

        for (var index = 0; index < 32; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 55, 3, 0x6000_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 8 + 1);
            for (var byteIndex = 0; byteIndex < 6; byteIndex++)
            {
                Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + (uint)byteIndex));
                Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + (uint)byteIndex));
            }
        }

        for (var index = 0; index < 32; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 8, 0, 63, 3, 0x7000_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 8 + 1);
            for (var byteIndex = 0; byteIndex < 7; byteIndex++)
            {
                Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + (uint)byteIndex));
                Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + (uint)byteIndex));
            }
        }

        // The eight-byte form starts at byte zero so the declared eight-byte
        // stride is fully consumed without touching the following row.
        for (var index = 0; index < 32; index++)
        {
            bus.WriteByte(pixelPlane + (uint)index, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)index, 0, 0);
        }

        ExecuteRectFill(rastPort, 0, 0, 63, 3, 0x8000_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 4; row++)
        {
            var byteOffset = (uint)(row * 8);
            for (var byteIndex = 0; byteIndex < 8; byteIndex++)
            {
                Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + byteOffset + (uint)byteIndex));
                Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + byteOffset + (uint)byteIndex));
            }
        }
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 32u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane2 + 32u));

        // The ninth-byte boundary remains on the shared fallback: no plane
        // byte may be published when the exact-width dispatch declines it.
        for (var byteIndex = 0; byteIndex < 8; byteIndex++)
        {
            bus.WriteByte(pixelPlane + (uint)byteIndex, (byte)(0x10 + byteIndex), 0);
            bus.WriteByte(pixelPlane2 + (uint)byteIndex, (byte)(0x80 + byteIndex), 0);
        }
        ExecuteRectFill(rastPort, 0, 0, 71, 0, 0xABCD_9000u);
        Assert.Equal(0xABCD_9000u, cpu.State.D[0]);
        for (var byteIndex = 0; byteIndex < 8; byteIndex++)
        {
            Assert.Equal((byte)(0x10 + byteIndex), bus.ReadByte(pixelPlane + (uint)byteIndex));
            Assert.Equal((byte)(0x80 + byteIndex), bus.ReadByte(pixelPlane2 + (uint)byteIndex));
        }

        bus.WriteByte(pixelPlane + 1u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x3C, 0);
        bus.WriteByte(pixelPlane + 4u, 0xC3, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x5A, 0);
        bus.WriteByte(pixelPlane2 + 3u, 0xC3, 0);
        bus.WriteByte(pixelPlane2 + 4u, 0x3C, 0);
        ExecuteRectFill(rastPort, 8, 0, 40, 0, 0xABCD_4000u);
        Assert.Equal(0xABCD_4008u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane2 + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 2u));
        Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane2 + 3u));
        Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane2 + 4u));

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 8);

        bus.WriteByte(pixelPlane + 1u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x3C, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x5A, 0);
        bus.WriteByte(pixelPlane2 + 3u, 0xC3, 0);
        ExecuteRectFill(rastPort, 8, 0, 32, 0, 0xABCD_3000u);
        Assert.Equal(0xABCD_3008u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane2 + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 2u));
        Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane2 + 3u));

        bus.WriteByte(pixelPlane + 1u, 0x5A, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x5A, 0);
        ExecuteRectFill(rastPort, 8, 0, 24, 0, 0xABCD_2000u);
        Assert.Equal(0xABCD_2008u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane2 + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 2u));

        // Richer depth-2 geometry remains transparent to the portable/native
        // owner and must preserve the caller result and both plane bytes.
        bus.WriteByte(pixelPlane + 1u, 0x5A, 0);
        bus.WriteByte(pixelPlane2 + 1u, 0xA5, 0);
        ExecuteRectFill(rastPort, 3, 0, 10, 0, 0xABCD_1000u);
        Assert.Equal(0xABCD_1003u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane2 + 1u));

        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 8);

        // RectFill dispatch owns both depth-specialized native arms. Its
        // initial header admission must accept public headers that end at the
        // 32-bit guest limit while declining ones that wrap into low memory.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint wrappedRastPort = 0xFFFF_FFFCu;
        const uint wrappedBitMap = 0xFFFF_FFFCu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        uint PhysicalAlias(uint address) => address & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(0, new byte[GraphicsLayouts.RastPortMinimumSize]);

        bus.WriteLong(topRastPortPhysical + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(pixelPlane, 0, 0);
        ExecuteRectFill(topRastPort, 0, 0, 0, 0, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(pixelPlane));

        // The last four physical bytes of that accepted header are also the
        // high fragment of a logically wrapped header. Populate its low
        // alias so the old byte-only dispatch would have filled the plane;
        // the complete-envelope check must instead preserve D0 and pixels.
        bus.WriteLong(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortBitMap)), pixelBitMap, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortDrawMode)), 0, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortMask)), 1, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortFgPen)), 1, 0);
        bus.WriteByte(pixelPlane, 0x5A, 0);
        ExecuteRectFill(wrappedRastPort, 0, 0, 0, 0, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane));

        // The same rule covers the complete BitMap header rather than only
        // the depth byte selected by the dispatcher.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            wrappedBitMap, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapDepth)), 1, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapBytesPerRow)), 2, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapRows)), 8, 0);
        bus.WriteLong(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapPlanes)),
            pixelPlane, 0);
        bus.WriteByte(pixelPlane, 0xA5, 0);
        ExecuteRectFill(rastPort, 0, 0, 0, 0, 0xCAFE_0000u);
        Assert.Equal(0xCAFE_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane));
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);

        // EraseRect shares the same one-/multi-row dispatcher contract. Its
        // byte-valued background pen proves that exact-end headers still
        // enter the one-plane owner, while wrapped headers remain untouched.
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortBgPen,
            1, 0);
        bus.WriteByte(pixelPlane, 0, 0);
        ExecuteEraseRect(topRastPort, 0, 0, 0, 0, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(pixelPlane));

        // The aligned one-plane row body performs its own full RastPort
        // admission after dispatch and must retain exact-end acceptance.
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortBgPen,
            1, 0);
        bus.WriteByte(pixelPlane + 3u, 0, 0); // y=1, x=8..15
        ExecuteEraseRect(topRastPort, 8, 1, 15, 1, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 3u));

        bus.WriteLong(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortBitMap)), pixelBitMap, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortDrawMode)), 0, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortMask)), 1, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortBgPen)), 1, 0);
        bus.WriteByte(pixelPlane, 0x5A, 0);
        ExecuteEraseRect(wrappedRastPort, 0, 0, 0, 0, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            wrappedBitMap, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapDepth)), 1, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapBytesPerRow)), 2, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapRows)), 8, 0);
        bus.WriteLong(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapPlanes)), pixelPlane, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(pixelPlane, 0xA5, 0);
        ExecuteEraseRect(rastPort, 0, 0, 0, 0, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane));
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortCurrentX + 1u, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortCurrentY + 1u, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        ExecuteDraw(rastPort, 10, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)1, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(
            (byte)8,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            0,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
                GraphicsLayouts.RastPortFirstDot);

        // Non-all-ones JAM1 samples the same MSB-first line pattern phase;
        // clear pattern cells leave the destination untouched.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            3);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0x0F0F);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(pixelPlane + 2u, 0, 0);
        bus.WriteByte(pixelPlane + 3u, 0, 0);

        ExecuteDraw(rastPort, 10, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x01, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)8, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // COMPLEMENT|JAM1 applies BCHG only to pattern-one samples; the
        // clear cells above therefore remain unchanged in the second pass.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            3);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            2,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x5A, 0);

        ExecuteDraw(rastPort, 10, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA4, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xBA, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)8, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Vertical JAM1 uses the same per-dot phase while stepping by the
        // bitmap row stride; a single high bit proves later rows are skipped.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            3);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0x8000);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        ExecuteDraw(rastPort, 3, 4, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((byte)12, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Reverse horizontal lines are admitted with the same one-plane,
        // all-one source envelope.  The native loop walks the MSB-first bit
        // cursor backwards while publishing the positive major distance.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            10);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        ExecuteDraw(rastPort, 3, 1, 0xC0DE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(
            (byte)8,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            0,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
                GraphicsLayouts.RastPortFirstDot);

        // The reverse complement selector must preserve BCHG semantics across
        // the same byte boundary; both touched bytes therefore invert to BA.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            10);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            2,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x5A, 0);

        ExecuteDraw(rastPort, 3, 1, 0xC0DE_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xBA, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xBA, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(
            (byte)8,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // INVERSVID|JAM2 uses the reverse selector too, sourcing the span
        // from BPen rather than APen.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            10);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            5,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            0,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            1,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(pixelPlane + 2u, 0, 0);
        bus.WriteByte(pixelPlane + 3u, 0, 0);

        ExecuteDraw(rastPort, 3, 1, 0xC0DE_0002u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(
            (byte)8,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            3);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        ExecuteDraw(rastPort, 3, 4, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal(
            (byte)12,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Reverse vertical traversal starts at the current row and subtracts
        // the bitmap row stride after every sample, while phase publication
        // still uses the positive major distance.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            3);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            4);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        ExecuteDraw(rastPort, 3, 1, 0xC0DE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((short)1, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(
            (byte)12,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Reverse vertical COMPLEMENT follows the same stride direction and
        // toggles only the all-one source sample in each touched row.
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            4);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            2,
            0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15,
            0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);

        ExecuteDraw(rastPort, 3, 1, 0xC0DE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((short)1, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(
            (byte)12,
            bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            3);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1);
        // COMPLEMENT|INVERSVID remains on the shared fallback for this
        // native Draw slice; the non-inverse COMPLEMENT forms are native.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 6, 0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        ExecuteDraw(rastPort, 10, 1, 0xDEAD_0000u);
        Assert.Equal(0xDEAD_000Au, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // ONE_DOT/SING has row-suppression semantics outside this native
        // fresh-line body; admission must preserve the call for fallback.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot | GraphicsLayouts.RastPortOneDot);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x5A, 0);
        ExecuteDraw(rastPort, 10, 1, 0xD0D0_0000u);
        Assert.Equal(0xD0D0_000Au, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // Non-inverse COMPLEMENT toggles the all-one source span without
        // consulting either pen.  Exercise both sides of the byte boundary
        // and retain nonzero destination bits to prove this is BCHG, not a
        // set/clear alias.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 2, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x5A, 0);
        ExecuteDraw(rastPort, 10, 1, 0xD201_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xBA, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xBA, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)8, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // JAM2 is immaterial for COMPLEMENT, and the vertical loop must
        // preserve the same major-axis line phase.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 3, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
        ExecuteDraw(rastPort, 3, 4, 0xD202_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((short)4, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((byte)12, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // INVERSVID keeps the line-state publication but reverses the
        // all-one source.  JAM1 is therefore a no-op for pixels.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 4, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteDraw(rastPort, 10, 1, 0xA400_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)8, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // INVERSVID|JAM2 paints the same source span from BPen.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteDraw(rastPort, 10, 1, 0xA500_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)8, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The same inverse JAM2 dispatch applies to a positive vertical
        // segment, including its major-axis line-pattern phase.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteDraw(rastPort, 3, 4, 0xA600_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 8u));
        Assert.Equal((short)4, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((byte)12, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);

        bus.WriteByte(pixelPlane + 2u, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xCAFE_0000u, 39);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xBEEF_0000u, 39);
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        // JAM2 still uses APen for the implicit source-one cell.
        bus.WriteByte(pixelPlane + 2u, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xDEAD_0000u, 12);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        // INVERSVID|JAM2 selects BPen for the implicit source-zero cell.
        bus.WriteByte(pixelPlane + 2u, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xD00D_0000u, 12);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        // INVERSVID without JAM2 is a successful source-zero no-op.
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 4, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xB00B_0000u, 12);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        // COMPLEMENT toggles the selected bit and ignores both pens.
        bus.WriteByte(pixelPlane + 2u, 0x10, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 2, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xC0DE_0000u, 12);
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 2u));
        ExecuteWritePixel(rastPort, 3, 1, 0xC0DF_0000u, 12);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));

        // COMPLEMENT|INVERSVID has a zero effective source and is a no-op.
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 6, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xC0E0_0000u, 12);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xFACE_0000u, 16);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x5A, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xABCD_0000u, 8);
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        // A selected two-plane APen writes both destination bits, while an
        // unselected plane remains byte-for-byte untouched.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 3, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x4A, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0x1234_0000u, 8);
        Assert.Equal((byte)0xB5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 2u));
        Assert.Equal(0u, cpu.State.D[0]);

        // A late malformed selected plane must decline transactionally before
        // the earlier plane is changed.
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            0x00E5_0001u);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xABCD_0000u, 8);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal(0xABCD_0003u, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            pixelPlane2);

        // The guarded depth-2 arm keeps the classic mode matrix per selected
        // plane: COMPLEMENT toggles both selected bits, while INVERSVID|JAM2
        // publishes BPen and INVERSVID|JAM1 remains a successful no-op.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 2, 0);
        bus.WriteByte(pixelPlane + 2u, 0x10, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x00, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xACDC_0000u, 8);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane2 + 2u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 3, 0);
        bus.WriteByte(pixelPlane + 2u, 0x00, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x00, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xACDD_0000u, 8);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x10, bus.ReadByte(pixelPlane2 + 2u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 4, 0);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane2 + 2u, 0x5A, 0);
        ExecuteWritePixel(rastPort, 3, 1, 0xACDE_0000u, 8);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + 2u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);

        // Native PolyDraw claims one fresh orthogonal segment by reusing the
        // proven Draw body.  Longer chains, sloped geometry, and richer state
        // remain on the shared fallback with the incoming void D0 preserved.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, pixelBitMap);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteWord(polyPoints, 10);
        bus.WriteWord(polyPoints + 2u, 1);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);

        ExecutePolyDraw(polyPoints, rastPort, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)8, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
            GraphicsLayouts.RastPortFirstDot);

        // Count zero is the classic no-read success.  A two-point stream and
        // a sloped one-point segment are deliberately declined before any
        // cursor or pixel publication.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(pixelPlane + 2u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 3u, 0x5A, 0);
        ExecutePolyDraw(polyPoints, rastPort, 0, 0xDADA_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 3u));

        bus.WriteWord(polyPoints + 4u, 10);
        bus.WriteWord(polyPoints + 6u, 1);
        ExecutePolyDraw(polyPoints, rastPort, 2, 0xDADA_0000u);
        Assert.Equal(0xDADA_0002u, cpu.State.D[0]);
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 3u));

        bus.WriteWord(polyPoints, 10);
        bus.WriteWord(polyPoints + 2u, 2);
        ExecutePolyDraw(polyPoints, rastPort, 1, 0xDADA_0000u);
        Assert.Equal(0xDADA_0001u, cpu.State.D[0]);
        Assert.Equal((short)3, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // Native ClearEOL owns the fixed one-row cached-geometry form.  It
        // clears or fills from CurrentX through the row edge, resets the
        // line-pattern phase, and leaves richer font/mode/depth forms on
        // fallback.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 1);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 16);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);

        ExecuteClearEol(rastPort, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 7u));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // ClearEOL first enters the multi-plane selector and then dispatches
        // depth one to its bit-tail owner. Both entries must agree on the
        // full header envelopes: a top-of-address-space RastPort is valid,
        // but wrapped descriptors cannot clear a low-memory alias.
        bus.WriteLong(topRastPortPhysical + (uint)GraphicsLayouts.RastPortFont,
            0, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortTextHeight,
            1, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortTextBaseline,
            0, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortCurrentX,
            0, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortCurrentY,
            0, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortDrawMode,
            0, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortMask,
            1, 0);
        bus.WriteLong(topRastPortPhysical + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);
        for (var offset = 0; offset < 4; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearEol(topRastPort, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < 4; offset++)
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));

        bus.WriteLong(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortFont)), 0, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortTextHeight)), 1, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortTextBaseline)), 0, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortCurrentX)), 0, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortCurrentY)), 0, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortDrawMode)), 0, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortMask)), 1, 0);
        bus.WriteLong(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortBitMap)), pixelBitMap, 0);
        bus.WriteByte(pixelPlane, 0xA5, 0);
        ExecuteClearEol(wrappedRastPort, 0xBEEF_1000u);
        Assert.Equal(0xBEEF_1000u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            wrappedBitMap, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapDepth)), 1, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapBytesPerRow)), 4, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapRows)), 16, 0);
        bus.WriteLong(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapPlanes)), pixelPlane, 0);
        bus.WriteByte(pixelPlane, 0x5A, 0);
        ExecuteClearEol(rastPort, 0xBEEF_2000u);
        Assert.Equal(0xBEEF_2000u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane));
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);

        bus.WriteByte(pixelPlane + 4u, 0xA5, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 2);
        ExecuteClearEol(rastPort, 0xDADA_0000u);
        Assert.Equal(0xDADA_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 4u));

        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearEol(rastPort, 0xDADA_1000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 7u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteClearEol(rastPort, 0xDADA_1100u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 6u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 7u));

        // Only base JAM2 BPen values are resident-owned; other pens remain
        // available to the portable/provider implementation.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2, 0);
        bus.WriteByte(pixelPlane + 4u, 0xA5, 0);
        ExecuteClearEol(rastPort, 0xDADA_1200u);
        Assert.Equal(0xDADA_1200u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 4u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        ExecuteClearEol(rastPort, 0xDADA_2000u);
        Assert.Equal(0xDADA_2000u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 4u));

        // The native ClearEOL extension owns the exact origin/full-row
        // standard-planar depth-2 form. The existing ClearScreen transaction
        // is reused with a strict one-row guard, so every selected plane is
        // preflighted before either plane is published.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            pixelPlane2);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 12, 0);
        for (var offset = 0; offset < 4; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x5A, 0);
        }
        ExecuteClearEol(rastPort, 0xDADA_2100u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 0; offset < 4; offset++)
        {
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane2 + (uint)offset));
        }

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 13, 0);
        for (var offset = 0; offset < 4; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x3C, 0);
        }
        ExecuteClearEol(rastPort, 0xDADA_2110u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 0; offset < 4; offset++)
        {
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane2 + (uint)offset));
        }

        // Multi-row ClearEOL remains outside this one-row native unit.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(pixelPlane + 0u, 0xA5, 0);
        ExecuteClearEol(rastPort, 0xDADA_2120u);
        Assert.Equal(0xDADA_2120u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 0u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);

        // Native ClearScreen keeps the fixed one-row ClearEOL tail for the
        // one-row origin form while the dedicated full-raster arm below owns
        // the common multi-row origin case.
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteByte(pixelPlane + 0u, 0xFF, 0);
        bus.WriteByte(pixelPlane + 1u, 0xFF, 0);
        bus.WriteByte(pixelPlane + 2u, 0xFF, 0);
        bus.WriteByte(pixelPlane + 3u, 0xFF, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 0u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The one-row resident tail also admits base JAM2 with BPen=1.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 16; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_0100u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1F, bus.ReadByte(pixelPlane + 0u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + 3u));

        // The resident ClearScreen arm also owns the common origin/full-raster
        // form.  It writes every byte of the two-row one-plane bitmap and
        // resets the line-pattern phase without touching the caller result.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 6, 0);
        for (var offset = 0; offset < 8; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 0; offset < 8; offset++)
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));

        // ClearScreen has its own full-raster entry, separate from the
        // ClearEOL selector. Preserve exact-end header support there as well
        // and reject every wrapped alias before its first row is touched.
        bus.WriteLong(topRastPortPhysical + (uint)GraphicsLayouts.RastPortFont,
            0, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortTextHeight,
            1, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortTextBaseline,
            0, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortCurrentX,
            0, 0);
        bus.WriteWord(topRastPortPhysical + (uint)GraphicsLayouts.RastPortCurrentY,
            0, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortDrawMode,
            0, 0);
        bus.WriteByte(topRastPortPhysical + (uint)GraphicsLayouts.RastPortMask,
            1, 0);
        bus.WriteLong(topRastPortPhysical + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);
        for (var offset = 0; offset < 8; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearScreen(topRastPort, 0xBEEF_1020u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < 8; offset++)
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));

        bus.WriteLong(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortFont)), 0, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortTextHeight)), 1, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortTextBaseline)), 0, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortCurrentX)), 0, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortCurrentY)), 0, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortDrawMode)), 0, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortMask)), 1, 0);
        bus.WriteLong(PhysicalAlias(unchecked(wrappedRastPort +
            (uint)GraphicsLayouts.RastPortBitMap)), pixelBitMap, 0);
        bus.WriteByte(pixelPlane, 0xA5, 0);
        ExecuteClearScreen(wrappedRastPort, 0xBEEF_1030u);
        Assert.Equal(0xBEEF_1030u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            wrappedBitMap, 0);
        bus.WriteByte(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapDepth)), 1, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapBytesPerRow)), 4, 0);
        bus.WriteWord(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapRows)), 2, 0);
        bus.WriteLong(PhysicalAlias(unchecked(wrappedBitMap +
            (uint)GraphicsLayouts.BitMapPlanes)), pixelPlane, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteByte(pixelPlane, 0x5A, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1040u);
        Assert.Equal(0xBEEF_1040u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane));
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            pixelBitMap, 0);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 7, 0);
        for (var offset = 0; offset < 8; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1050u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 0; offset < 8; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + (uint)offset));

        // A nonzero current row is admitted when the cursor remains at the
        // byte-aligned left edge: rows above CurrentY survive, while the
        // current and remaining rows are cleared as one native transaction.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 8, 0);
        bus.WriteByte(pixelPlane + 0u, 0xA5, 0);
        for (var offset = 4; offset < 12; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1080u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 0u));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 4; offset < 12; offset++)
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));

        // A byte-aligned nonzero CurrentX owns the current-row tail while
        // later rows still clear from their left edge.  The byte before the
        // tail remains untouched, and the operation remains rollback-safe.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 9, 0);
        bus.WriteByte(pixelPlane + 4u, 0xA5, 0);
        bus.WriteByte(pixelPlane + 5u, 0xFF, 0);
        bus.WriteByte(pixelPlane + 6u, 0xFF, 0);
        bus.WriteByte(pixelPlane + 7u, 0xFF, 0);
        for (var offset = 8; offset < 12; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1090u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 4u));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 5; offset < 12; offset++)
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));

        // The exact row width is a successful empty tail: the current row
        // remains intact while the following row still receives a full walk.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 32);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 10, 0);
        for (var offset = 4; offset < 8; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
        for (var offset = 8; offset < 12; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_10C0u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 4; offset < 8; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + (uint)offset));
        for (var offset = 8; offset < 12; offset++)
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A non-byte-aligned current-row tail now uses the same MSB-first bit
        // semantics as ClearEOL.  Bits before CurrentX survive; the tail and
        // every following row are cleared atomically.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 10, 0);
        for (var offset = 0; offset < 4; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1100u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE0, bus.ReadByte(pixelPlane + 0u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 1u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 2u));
        Assert.Equal((byte)0, bus.ReadByte(pixelPlane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A byte-aligned cursor beyond the row envelope declines before the
        // plane pointer is published, preserving D0, line state, and bytes.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 40);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 11, 0);
        bus.WriteByte(pixelPlane + 0u, 0xA5, 0);
        ExecuteClearScreen(rastPort, 0xBEEF_1150u);
        Assert.Equal(0xBEEF_1150u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 0u));
        Assert.Equal((byte)11, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 1);
        ExecuteClearScreen(rastPort, 0xBEEF_2000u);
        Assert.Equal(0xBEEF_2000u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 0u));

        // The multi-plane resident arm owns an origin-only standard planar
        // screen.  A depth-sized mask clears only selected inline plane
        // links, and all selected spans are preflighted before publication.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            pixelPlane2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 12, 0);
        for (var offset = 0; offset < 12; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x5A, 0);
        }
        for (var offset = 12; offset < 16; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0xC3, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x3C, 0);
        }
        ExecuteClearScreen(rastPort, 0xBEEF_3000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 0; offset < 12; offset++)
        {
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0, bus.ReadByte(pixelPlane2 + (uint)offset));
        }
        for (var offset = 12; offset < 16; offset++)
        {
            Assert.Equal((byte)0xC3, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane2 + (uint)offset));
        }

        // A one-bit mask leaves the unselected plane byte-for-byte intact;
        // JAM2/BPen=1 fills only the selected plane.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x01, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 13, 0);
        for (var offset = 0; offset < 12; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x3C, 0);
        }
        ExecuteClearScreen(rastPort, 0xBEEF_3010u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < 12; offset++)
        {
            Assert.Equal((byte)0xFF, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0x3C, bus.ReadByte(pixelPlane2 + (uint)offset));
        }

        // A malformed selected link declines before either plane is written.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 14, 0);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            pixelPlane2 + 1u);
        for (var offset = 0; offset < 12; offset++)
        {
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
            bus.WriteByte(pixelPlane2 + (uint)offset, 0x5A, 0);
        }
        ExecuteClearScreen(rastPort, 0xBEEF_3020u);
        Assert.Equal(0xBEEF_3020u, cpu.State.D[0]);
        Assert.Equal((byte)14, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var offset = 0; offset < 12; offset++)
        {
            Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + (uint)offset));
            Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane2 + (uint)offset));
        }

        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            pixelPlane2);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);

        // Native Text admits only the fixed-cell, byte-aligned JAM1/JAM2/
        // INVERSVID(4/5) slice.
        // The glyph strike is one byte per row; the portable path remains the
        // owner for proportional tables, styles, spacing, and clipping.
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontModulo, 0x20);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontLoChar, 0x40, 0);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontHiChar, 0x5A, 0);
        bus.WriteLong(
            nativeFont + (uint)GraphicsLayouts.TextFontCharData,
            fontCharData);
        bus.WriteLong(nativeFont + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        bus.WriteLong(nativeFont + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        bus.WriteLong(nativeFont + (uint)GraphicsLayouts.TextFontCharKern, 0);
        for (var offset = 0; offset < 0x100; offset++)
            bus.WriteByte(fontCharData + (uint)offset, 0, 0);
        for (var row = 0; row < 8; row++)
        {
            bus.WriteByte(fontCharData + 1u + (uint)(row * 0x20), 0x81, 0); // 'A'
            bus.WriteByte(fontCharData + 2u + (uint)(row * 0x20), 0x18, 0); // 'B'
            bus.WriteByte(fontCharData + 27u + (uint)(row * 0x20), 0x24, 0); // default slot
        }
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(pixelBitMap + (uint)GraphicsLayouts.BitMapRows, 16);
        bus.WriteByte(pixelBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes, pixelPlane);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, nativeFont);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 4);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 2);
        bus.WriteByte(textAddress, 0x41, 0);
        bus.WriteByte(textAddress + 1u, 0x42, 0);
        Assert.Equal((byte)0x81, bus.ReadByte(fontCharData + 1u));
        Assert.Equal((byte)0x18, bus.ReadByte(fontCharData + 2u));
        Assert.Equal(pixelBitMap, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap));
        ExecuteText(textAddress, rastPort, 2, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x81, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0x18, bus.ReadByte(rowAddress + 2u));
        }
        Assert.Equal((short)24, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)4, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((byte)15, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            GraphicsLayouts.RastPortFirstDot,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
                GraphicsLayouts.RastPortFirstDot);

        // COMPLEMENT|INVERSVID remains on the shared fallback; the
        // non-inverse COMPLEMENT modes are native for this fixed-cell slice.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 6, 0);
        bus.WriteByte(pixelPlane + 9u, 0xA5, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        ExecuteText(textAddress, rastPort, 1, 0xDEAD_0000u);
        Assert.Equal(0xDEAD_0001u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(pixelPlane + 9u));
        Assert.Equal((short)8, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // Non-inverse COMPLEMENT toggles only source-one glyph cells and
        // leaves source-zero template cells untouched.  Retain nonzero
        // destination bytes to prove the native path uses BCHG.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 2, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xA5, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        ExecuteText(textAddress, rastPort, 2, 0xD301_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x24, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0xBD, bus.ReadByte(rowAddress + 2u));
        }
        Assert.Equal((short)24, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // JAM2|COMPLEMENT toggles the complete fixed-cell template once,
        // including source-zero cells, without consulting either pen.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 3, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0x5A, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        ExecuteText(textAddress, rastPort, 2, 0xD302_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0xA5, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0xA5, bus.ReadByte(rowAddress + 2u));
        }
        Assert.Equal((short)24, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // JAM1 with a zero foreground pen clears source-one glyph bits while
        // leaving source-zero cells unchanged.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0xFF, 0);
        ExecuteText(textAddress, rastPort, 2, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x7E, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0xE7, bus.ReadByte(rowAddress + 2u));
        }
        Assert.Equal((short)24, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // Fixed-cell JAM2 writes source-one cells from APen and source-zero
        // cells from BPen.  APen=0/BPen=1 therefore produces the complement
        // of each source glyph in this depth-one fixture.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        ExecuteText(textAddress, rastPort, 2, 0xABCD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x7E, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0xE7, bus.ReadByte(rowAddress + 2u));
        }
        Assert.Equal((short)24, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // INVERSVID reverses the source phase.  JAM1 paints the former
        // source-zero cells with APen; JAM2 swaps APen/BPen roles for the
        // reversed template.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 4, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        ExecuteText(textAddress, rastPort, 2, 0xA1B2_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x7E, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0xE7, bus.ReadByte(rowAddress + 2u));
        }

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        ExecuteText(textAddress, rastPort, 2, 0xA3B4_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x81, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0x18, bus.ReadByte(rowAddress + 2u));
        }

        // Bytes outside LoChar..HiChar use the extra fixed-cell default slot.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        for (var offset = 0; offset < 64; offset++)
            bus.WriteByte(pixelPlane + (uint)offset, 0, 0);
        bus.WriteByte(pixelPlane + 40u, 0x5A, 0);
        bus.WriteByte(textAddress + 1u, 0x7F, 0);
        ExecuteText(textAddress, rastPort, 2, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(pixelPlane + 40u));
        Assert.Equal((short)24, unchecked((short)bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        for (var row = 0; row < 8; row++)
        {
            var rowAddress = pixelPlane + (uint)((2 + row) * 4);
            Assert.Equal((byte)0x81, bus.ReadByte(rowAddress + 1u));
            Assert.Equal((byte)0x24, bus.ReadByte(rowAddress + 2u));
        }
        bus.WriteByte(textAddress + 1u, 0x42, 0);

        // Restore the scalar fixture used by the metric vectors below.
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontXSize, 7);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0xFF, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth, 8);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, unchecked((ushort)-2));
        ExecuteTextLength(rastPort, 3, 0xCAFE_0000u, 27);
        Assert.Equal(18u, cpu.State.D[0]);

        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);
        ExecuteTextLength(rastPort, 2, 0xBEEF_0000u, 27);
        Assert.Equal(18u, cpu.State.D[0]);

        // A selected fixed-cell font uses its XSize plus RastPort spacing in
        // the native body, while a proportional font uses only the bounded
        // one-glyph arm and richer strings remain on the shared fallback.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, nativeFont);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, unchecked((ushort)-2));
        ExecuteTextLength(rastPort, 3, 0xCAFE_0000u, 35);
        Assert.Equal(15u, cpu.State.D[0]);

        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontStyle, 3, 0);
        ExecuteTextLength(rastPort, 3, 0xCAFE_B000u, 27);
        Assert.Equal(0xCAFE_B003u, cpu.State.D[0]);

        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xCC, 0);
        ExecuteTextExtent(textAddress, rastPort, 3, extentAddress, 0xCAFE_0000u, 45);
        Assert.Equal((ushort)15, bus.ReadWord(extentAddress + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(extentAddress + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-6, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)14, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)2, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxY)));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xA5, 0);
        ExecuteTextExtent(textAddress, rastPort, 3, extentAddress, 0xDEAD_0000u, 20);
        Assert.Equal(0xDEAD_0003u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extentAddress + (uint)offset));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0);
        ExecuteTextExtent(textAddress, rastPort, 3, extentAddress, 0xBEEF_0000u, 3);
        Assert.Equal(0xBEEF_0003u, cpu.State.D[0]);

        // Native FontExtent claims a bounded declared fixed-cell range with
        // no proportional, reverse-path, spacing, or kerning tables.  It
        // publishes the complete TextExtent envelope directly from the
        // guest TextFont prefix; richer ranges remain on fallback.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, nativeFont);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontLoChar, 0x41, 0);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontHiChar, 0x41, 0);
        bus.WriteLong(nativeFont + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        bus.WriteLong(nativeFont + (uint)GraphicsLayouts.TextFontCharKern, 0);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontXSize, 7);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(nativeFont + (uint)GraphicsLayouts.TextFontBaseline, 6);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xCC, 0);
        ExecuteFontExtent(nativeFont, extentAddress, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)7, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-6, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)2, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxY)));

        // A fixed-cell REVPATH font publishes the signed negative movement
        // and the origin-relative rectangle on the native body.
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0x04, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xCC, 0);
        ExecuteFontExtent(nativeFont, extentAddress, 0xFACE_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentWidth)));
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-1, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxX)));

        // REVPATH must not accidentally claim the proportional arm.
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0x24, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xA5, 0);
        ExecuteFontExtent(nativeFont, extentAddress, 0xFACE_0002u);
        Assert.Equal(0xFACE_0002u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extentAddress + (uint)offset));
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);

        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontHiChar, 0x42, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xA5, 0);
        ExecuteFontExtent(nativeFont, extentAddress, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)7, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-6, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)2, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxY)));

        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontHiChar, 0x41, 0);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        ExecuteFontExtent(nativeFont, extentAddress, 0xD00D_0001u);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);

        ExecuteFontExtent(nativeFont + 1u, extentAddress, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        ExecuteFontExtent(0, extentAddress, 0xD00D_0003u);
        Assert.Equal(0xD00D_0003u, cpu.State.D[0]);

        // Native GetBitMapAttr claims the ordinary scalar height/depth/width
        // selectors and non-displayable standard flags; interleaved flags and
        // malformed/provider forms remain on the portable query boundary.
        ExecuteGetBitMapAttr(pixelBitMap, 0, 0xFACE_0000u);
        Assert.Equal(16u, cpu.State.D[0]);
        ExecuteGetBitMapAttr(pixelBitMap, 4, 0xFACE_0001u);
        Assert.Equal(1u, cpu.State.D[0]);
        ExecuteGetBitMapAttr(pixelBitMap, 8, 0xFACE_0002u);
        Assert.Equal(32u, cpu.State.D[0]);
        bus.WriteWord(
            pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            0);
        ExecuteGetBitMapAttr(pixelBitMap, 8, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        bus.WriteWord(
            pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            3);
        ExecuteGetBitMapAttr(pixelBitMap, 8, 0xD00D_0003u);
        Assert.Equal(0xD00D_0003u, cpu.State.D[0]);
        bus.WriteWord(
            pixelBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x09,
            0); // BMF_CLEAR|BMF_STANDARD; private bit is masked out
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0004u);
        Assert.Equal(0x08u, cpu.State.D[0]);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x04,
            0); // BMF_INTERLEAVED remains portable/provider-owned
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0005u);
        Assert.Equal(0xD00D_0005u, cpu.State.D[0]);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x0A,
            0); // depth-one standard-planar displayable form
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0006u);
        Assert.Equal(0x0Au, cpu.State.D[0]);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2,
            0);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            pixelPlane2);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0007u);
        Assert.Equal(0x0Au, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            0);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0008u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            pixelPlane2 + 1u);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0009u);
        Assert.Equal(0xD00D_0009u, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            pixelPlane2);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapDepth,
            3,
            0); // standard-planar depth three remains displayable
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + (2 * sizeof(uint)),
            pixelPlane2 + 2u);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0010u);
        Assert.Equal(0x0Au, cpu.State.D[0]);
        for (var plane = 3; plane < 8; plane++)
        {
            bus.WriteLong(
                pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * sizeof(uint)),
                pixelPlane + (uint)(plane * 2));
        }
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapDepth,
            8,
            0); // the complete standard-planar depth range is displayable
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0011u);
        Assert.Equal(0x0Au, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + (7 * sizeof(uint)),
            pixelPlane + 1u);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0012u);
        Assert.Equal(0xD00D_0012u, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes + (7 * sizeof(uint)),
            pixelPlane + 14u);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapDepth,
            9,
            0); // depths beyond the standard planar range remain fallback
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0013u);
        Assert.Equal(0xD00D_0013u, cpu.State.D[0]);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapDepth,
            1,
            0);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0014u);
        Assert.Equal(0xD00D_0014u, cpu.State.D[0]);
        bus.WriteLong(
            pixelBitMap + (uint)GraphicsLayouts.BitMapPlanes,
            pixelPlane);
        bus.WriteWord(
            pixelBitMap + (uint)GraphicsLayouts.BitMapRows,
            0);
        ExecuteGetBitMapAttr(pixelBitMap, 12, 0xD00D_0015u);
        Assert.Equal(0xD00D_0015u, cpu.State.D[0]);
        bus.WriteWord(
            pixelBitMap + (uint)GraphicsLayouts.BitMapRows,
            16);
        bus.WriteByte(
            pixelBitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x08,
            0);
        ExecuteGetBitMapAttr(pixelBitMap + 1u, 0, 0xD00D_0016u);
        Assert.Equal(0xD00D_0016u, cpu.State.D[0]);
        ExecuteGetBitMapAttr(0, 4, 0xD00D_0017u);
        Assert.Equal(0xD00D_0017u, cpu.State.D[0]);

        // Native GetRGB4 owns only the legacy ColorTable UWORD read.  It
        // validates the public ColorMap count and table envelope, masks the
        // RGB4 result, and preserves the entry in D0 for malformed forms.
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 4);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);
        bus.WriteWord(colorTable + 0u, 0xF123);
        bus.WriteWord(colorTable + 4u, 0x0A5F);
        ExecuteGetRgb4(colorMap, 2);
        Assert.Equal(0x0A5Fu, cpu.State.D[0]);
        ExecuteGetRgb4(colorMap, 0);
        Assert.Equal(0x0123u, cpu.State.D[0]);
        ExecuteGetRgb4(colorMap, 4);
        Assert.Equal(4u, cpu.State.D[0]);
        ExecuteGetRgb4(colorMap, 0x0001_0000u);
        Assert.Equal(0x0001_0000u, cpu.State.D[0]);
        ExecuteGetRgb4(0, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteGetRgb4(colorMap + 1u, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 0);
        ExecuteGetRgb4(colorMap, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 4);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, 0);
        ExecuteGetRgb4(colorMap, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable + 1u);
        ExecuteGetRgb4(colorMap, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, 0xFFFF_FFFEu);
        ExecuteGetRgb4(colorMap, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);

        // Native SetRGB4CM claims the transactional legacy write envelope.
        // It preserves the ColorTable high nibble, writes the RGB4 nibbles,
        // and clears LowColorBits for V36/V39 maps only after all addresses
        // are preflighted.
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteWord(colorTable + 4u, 0xF123);
        ExecuteSetRgb4Cm(colorMap, 2, 0x0A, 0x05, 0x0F);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0xFA5F, bus.ReadWord(colorTable + 4u));
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(lowColorTable + 4u, 0xABCD);
        bus.WriteWord(colorTable + 4u, 0x1000);
        ExecuteSetRgb4Cm(colorMap, 2, 0x01, 0x02, 0x03);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1123, bus.ReadWord(colorTable + 4u));
        Assert.Equal((ushort)0, bus.ReadWord(lowColorTable + 4u));
        bus.WriteWord(colorTable + 4u, 0xCAFE);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        ExecuteSetRgb4Cm(colorMap, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable + 1u);
        ExecuteSetRgb4Cm(colorMap, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 1, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        ExecuteSetRgb4Cm(colorMap, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));

        // Native GetRGB32 claims a single-entry RGB32 read.  Type 0 maps
        // expose the legacy nibbles as the upper half of each byte; Type 2
        // combines the optional LowColorBits nibbles, then expands each
        // byte across its LONG result.  Multi-entry and malformed envelopes
        // preserve D0 and leave the destination untouched.
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteWord(colorTable + 4u, 0x0A5F);
        bus.WriteLong(rgb32Output + 0u, 0xDEAD_BEEFu);
        bus.WriteLong(rgb32Output + 4u, 0xDEAD_BEEFu);
        bus.WriteLong(rgb32Output + 8u, 0xDEAD_BEEFu);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0xA0A0_A0A0u, bus.ReadLong(rgb32Output + 0u));
        Assert.Equal(0x5050_5050u, bus.ReadLong(rgb32Output + 4u));
        Assert.Equal(0xF0F0_F0F0u, bus.ReadLong(rgb32Output + 8u));

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(lowColorTable + 4u, 0x0B7C);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0xABAB_ABABu, bus.ReadLong(rgb32Output + 0u));
        Assert.Equal(0x5757_5757u, bus.ReadLong(rgb32Output + 4u));
        Assert.Equal(0xFCFC_FCFCu, bus.ReadLong(rgb32Output + 8u));

        bus.WriteLong(rgb32Output + 0u, 0xCAFE_BABEu);
        bus.WriteLong(rgb32Output + 4u, 0xCAFE_BABEu);
        bus.WriteLong(rgb32Output + 8u, 0xCAFE_BABEu);
        ExecuteGetRgb32(colorMap, 2, 2, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(rgb32Output + 0u));
        ExecuteGetRgb32(colorMap, 4, 1, rgb32Output);
        Assert.Equal(4u, cpu.State.D[0]);
        ExecuteGetRgb32(colorMap, 0x0001_0000u, 1, rgb32Output);
        Assert.Equal(0x0001_0000u, cpu.State.D[0]);
        ExecuteGetRgb32(colorMap, 2, 1, 0);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output + 1u);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteGetRgb32(colorMap, 2, 1, 0xFFFF_FFF8u);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteGetRgb32(0, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteGetRgb32(colorMap + 1u, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, 0);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable + 1u);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0xFFFF_FFFEu);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 1, 0);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable + 1u);
        ExecuteGetRgb32(colorMap, 2, 1, rgb32Output);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(rgb32Output + 0u));
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(rgb32Output + 4u));
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(rgb32Output + 8u));
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);

        // Native GetVPModeID claims only an assembling standard ViewPort with
        // no attached ColorMap or ExtendedModes provider state.  It reads the
        // UWORD vp_Modes field directly and preserves D0 for foreign,
        // malformed, or wrapped ViewPort envelopes.
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteWord(modeViewPort + (uint)GraphicsLayouts.ViewPortModes, 0x0100);
        ExecuteGetVpModeId(modeViewPort, 0xCAFE_0001u);
        Assert.Equal(0x0100u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorTable);
        ExecuteGetVpModeId(modeViewPort, 0xCAFE_0002u);
        Assert.Equal(0xCAFE_0002u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 1, 0);
        ExecuteGetVpModeId(modeViewPort, 0xCAFE_0003u);
        Assert.Equal(0xCAFE_0003u, cpu.State.D[0]);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        ExecuteGetVpModeId(modeViewPort + 1u, 0xCAFE_0004u);
        Assert.Equal(0xCAFE_0004u, cpu.State.D[0]);
        ExecuteGetVpModeId(0, 0xCAFE_0005u);
        Assert.Equal(0xCAFE_0005u, cpu.State.D[0]);
        ExecuteGetVpModeId(0xFFFF_FFFEu, 0xCAFE_0006u);
        Assert.Equal(0xCAFE_0006u, cpu.State.D[0]);

        // Native SetRGB32CM claims the same checked ColorMap entry envelope.
        // It preserves the reserved high ColorTable nibble, converts the
        // upper/lower nibbles of each RGB32 channel, and only touches
        // LowColorBits for a Type-2 map.
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteWord(colorTable + 4u, 0xF123);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0xFA3F, bus.ReadWord(colorTable + 4u));

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(colorTable + 4u, 0x1000);
        bus.WriteWord(lowColorTable + 4u, 0xCAFE);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1A3F, bus.ReadWord(colorTable + 4u));
        Assert.Equal((ushort)0x0B4F, bus.ReadWord(lowColorTable + 4u));

        bus.WriteWord(colorTable + 4u, 0xCAFE);
        bus.WriteWord(lowColorTable + 4u, 0xBABE);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal((ushort)0xCA3F, bus.ReadWord(colorTable + 4u));
        Assert.Equal((ushort)0x0B4F, bus.ReadWord(lowColorTable + 4u));
        bus.WriteWord(colorTable + 4u, 0xCAFE);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable + 1u);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0xFFFF_FFFEu);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 1, 0);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 0);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 4);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, 0);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable + 1u);
        ExecuteSetRgb32Cm(colorMap, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, 0xFFFF_FFFEu);
        ExecuteSetRgb32Cm(colorMap, 1, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);

        // Native SetRGB32 claims the ViewPort-facing ABI only after its
        // standard-planar ViewPort/ColorMap link passes the same envelope
        // checks as the direct ColorMap writer.  The writer body then shares
        // Type-0/Type-2 conversion and high-nibble preservation.
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(colorTable + 4u, 0x1000);
        bus.WriteWord(lowColorTable + 4u, 0xCAFE);
        ExecuteSetRgb32(modeViewPort, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1A3F, bus.ReadWord(colorTable + 4u));
        Assert.Equal((ushort)0x0B4F, bus.ReadWord(lowColorTable + 4u));

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteWord(colorTable + 4u, 0xF123);
        ExecuteSetRgb32(modeViewPort, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0xFA3F, bus.ReadWord(colorTable + 4u));

        bus.WriteWord(colorTable + 4u, 0xCAFE);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 1, 0);
        ExecuteSetRgb32(modeViewPort, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        ExecuteSetRgb32(modeViewPort + 1u, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteSetRgb32(0, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteSetRgb32(0xFFFF_FFFEu, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0);
        ExecuteSetRgb32(modeViewPort, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap + 1u);
        ExecuteSetRgb32(modeViewPort, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0xFFFF_FFFEu);
        ExecuteSetRgb32(modeViewPort, 2, 0xAB00_0000u, 0x3412_0000u, 0xFF80_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        // Native SetRGB4 claims the ViewPort-facing ABI only after its
        // standard-planar ViewPort/ColorMap link passes the same envelope
        // checks as the direct ColorMap writer.  The writer body then shares
        // the legacy nibble packing and Type-2 low-entry clearing contract.
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(colorTable + 4u, 0x1000);
        bus.WriteWord(lowColorTable + 4u, 0xCAFE);
        ExecuteSetRgb4(modeViewPort, 2, 0x0A, 0x02, 0x0F);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1A2F, bus.ReadWord(colorTable + 4u));
        Assert.Equal((ushort)0x0000, bus.ReadWord(lowColorTable + 4u));

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteWord(colorTable + 4u, 0xF123);
        ExecuteSetRgb4(modeViewPort, 2, 0x04, 0x05, 0x06);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0xF456, bus.ReadWord(colorTable + 4u));

        bus.WriteWord(colorTable + 4u, 0xCAFE);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 1, 0);
        ExecuteSetRgb4(modeViewPort, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 4u));
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        ExecuteSetRgb4(modeViewPort + 1u, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteSetRgb4(0, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        ExecuteSetRgb4(0xFFFF_FFFEu, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0);
        ExecuteSetRgb4(modeViewPort, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap + 1u);
        ExecuteSetRgb4(modeViewPort, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0xFFFF_FFFEu);
        ExecuteSetRgb4(modeViewPort, 2, 0x04, 0x05, 0x06);
        Assert.Equal(2u, cpu.State.D[0]);
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        // Native LoadRGB4 claims the bounded bulk legacy palette form.  It
        // stages the source span and destination envelopes before publishing
        // ColorTable words, preserving each reserved high nibble; Type-2
        // maps also receive cleared LowColorBits entries.
        bus.WriteLong(modeViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 4);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteWord(rgb4Input + 0u, 0x0123);
        bus.WriteWord(rgb4Input + 2u, 0x0456);
        bus.WriteWord(rgb4Input + 4u, 0x0A0B);
        bus.WriteWord(colorTable + 0u, 0xF000);
        bus.WriteWord(colorTable + 2u, 0xA000);
        bus.WriteWord(colorTable + 4u, 0x5000);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 3, 0xCAFE_0003u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0xF123, bus.ReadWord(colorTable + 0u));
        Assert.Equal((ushort)0xA456, bus.ReadWord(colorTable + 2u));
        Assert.Equal((ushort)0x5A0B, bus.ReadWord(colorTable + 4u));

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(rgb4Input + 0u, 0x0ABC);
        bus.WriteWord(rgb4Input + 2u, 0x0123);
        bus.WriteWord(colorTable + 0u, 0x1000);
        bus.WriteWord(colorTable + 2u, 0xC000);
        bus.WriteWord(lowColorTable + 0u, 0xCAFE);
        bus.WriteWord(lowColorTable + 2u, 0xBABE);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 2, 0xCAFE_0002u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1ABC, bus.ReadWord(colorTable + 0u));
        Assert.Equal((ushort)0xC123, bus.ReadWord(colorTable + 2u));
        Assert.Equal((ushort)0x0000, bus.ReadWord(lowColorTable + 0u));
        Assert.Equal((ushort)0x0000, bus.ReadWord(lowColorTable + 2u));

        ExecuteLoadRgb4(0, 0, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, -1, 0xCAFE_0000u);
        Assert.Equal(0xCAFE_FFFFu, cpu.State.D[0]);

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteWord(colorTable + 0u, 0xCAFE);
        ExecuteLoadRgb4(modeViewPort, rgb4Input + 1u, 1, 0xD00D_0001u);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
        Assert.Equal((ushort)0xCAFE, bus.ReadWord(colorTable + 0u));
        ExecuteLoadRgb4(modeViewPort, 0xFFFF_FFFEu, 2, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, 0xFFFF_FFFEu);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 2, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0xFFFF_FFFEu);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 2, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 1, 0);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 1, 0xD00D_0001u);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 1);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 2, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 4);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 1, 0);
        ExecuteLoadRgb4(modeViewPort, rgb4Input, 1, 0xD00D_0001u);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
        bus.WriteByte(modeViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);

        // Native LoadRGB32 claims the bounded Kickstart interleaved table
        // form.  It validates the complete descriptor stream first, then
        // publishes legacy ColorTable and Type-2 LowColorBits words.
        bus.WriteWord(colorMap + (uint)GraphicsLayouts.ColorMapCount, 4);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable, colorTable);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, 0);
        bus.WriteLong(rgb32Input + 0u, (1u << 16) | 1u);
        bus.WriteLong(rgb32Input + 4u, 0xABCD_0000u);
        bus.WriteLong(rgb32Input + 8u, 0x1234_0000u);
        bus.WriteLong(rgb32Input + 12u, 0xFEDC_0000u);
        bus.WriteLong(rgb32Input + 16u, 0);
        bus.WriteWord(colorTable + 2u, 0x5000);
        ExecuteLoadRgb32(modeViewPort, rgb32Input, 0x1357_9BDFu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x5A1F, bus.ReadWord(colorTable + 2u));

        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);
        bus.WriteLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits, lowColorTable);
        bus.WriteWord(colorTable + 2u, 0x1000);
        bus.WriteWord(colorTable + 4u, 0xC000);
        bus.WriteWord(lowColorTable + 2u, 0xCAFE);
        bus.WriteWord(lowColorTable + 4u, 0xBABE);
        bus.WriteLong(rgb32Input + 0u, (2u << 16) | 1u);
        bus.WriteLong(rgb32Input + 4u, 0x0ABC_0000u);
        bus.WriteLong(rgb32Input + 8u, 0x0DEF_0000u);
        bus.WriteLong(rgb32Input + 12u, 0x0123_0000u);
        bus.WriteLong(rgb32Input + 16u, 0xFEDC_0000u);
        bus.WriteLong(rgb32Input + 20u, 0x4567_0000u);
        bus.WriteLong(rgb32Input + 24u, 0x89AB_0000u);
        bus.WriteLong(rgb32Input + 28u, 0);
        ExecuteLoadRgb32(modeViewPort, rgb32Input, 0x2468_ACEDu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1000, bus.ReadWord(colorTable + 2u));
        Assert.Equal((ushort)0xCF48, bus.ReadWord(colorTable + 4u));
        Assert.Equal((ushort)0x0AD1, bus.ReadWord(lowColorTable + 2u));
        Assert.Equal((ushort)0x0E59, bus.ReadWord(lowColorTable + 4u));

        ExecuteLoadRgb32(0, 0, 0xDEAD_BEEFu);
        Assert.Equal(0u, cpu.State.D[0]);
        ExecuteLoadRgb32(modeViewPort, rgb32Input + 1u, 0xD00D_0001u);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
        bus.WriteLong(rgb32Input + 0u, (1u << 16) | 4u);
        ExecuteLoadRgb32(modeViewPort, rgb32Input, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        ExecuteLoadRgb32(modeViewPort, 0xFFFF_FFFCu, 0xD00D_0003u);
        Assert.Equal(0xD00D_0003u, cpu.State.D[0]);
        bus.WriteLong(rgb32Input + 0u, (1u << 16) | 1u);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 1, 0);
        ExecuteLoadRgb32(modeViewPort, rgb32Input, 0xD00D_0004u);
        Assert.Equal(0xD00D_0004u, cpu.State.D[0]);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 2, 0);

        // Native ScalerDiv owns the pure UWORD arithmetic form.  Its
        // restoring divide avoids DIVU overflow, preserves the nearest-
        // integer rule, promotes a nonzero sub-unit result to one, and
        // publishes the low word of a widened quotient.
        ExecuteScalerDiv(640, 3, 2, 0xFACE_0000u);
        Assert.Equal(960u, cpu.State.D[0]);
        ExecuteScalerDiv(100, 1, 3, 0xFACE_0001u);
        Assert.Equal(33u, cpu.State.D[0]);
        ExecuteScalerDiv(100, 2, 3, 0xFACE_0002u);
        Assert.Equal(67u, cpu.State.D[0]);
        ExecuteScalerDiv(1, 1, 2, 0xFACE_0003u);
        Assert.Equal(1u, cpu.State.D[0]);
        ExecuteScalerDiv(0x3FFF, 0x3FFF, 1, 0xFACE_0004u);
        Assert.Equal(0x8001u, cpu.State.D[0]);
        ExecuteScalerDiv(0, 2, 3, 0xFACE_0005u);
        Assert.Equal(0u, cpu.State.D[0]);
        ExecuteScalerDiv(100, 1, 0, 0xFACE_0006u);
        Assert.Equal(0u, cpu.State.D[0]);
        ExecuteScalerDiv(0x4000, 1, 1, 0xFACE_0007u);
        Assert.Equal(0u, cpu.State.D[0]);

        // Native TextFit owns the bounded fixed-cell forward and reverse
        // forms with the alternate width/height constraint.  A seven-pixel
        // cell plus one pixel of TxSpacing fits once in a fifteen-pixel box
        // and publishes the same fixed TextExtent envelope as TextExtent.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, nativeFont);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xCC, 0);
        ExecuteTextFit(
            textAddress,
            rastPort,
            3,
            extentAddress,
            0,
            1,
            15,
            9,
            0xFACE_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-6, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)7, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)2, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxY)));

        ExecuteTextFit(
            textAddress,
            rastPort,
            2,
            extentAddress,
            0,
            1,
            0,
            9,
            0xDADA_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0, bus.ReadByte(extentAddress + (uint)offset));

        // Explicit TextExtent constraints remain on the portable/provider
        // path until their richer envelope is native.  Reverse fixed-cell
        // measurement is now claimed by the bounded native arm.
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extentAddress + (uint)offset, 0xA5, 0);
        ExecuteTextFit(
            textAddress,
            rastPort,
            2,
            extentAddress,
            extentAddress,
            1,
            15,
            9,
            0xDADA_0000u);
        Assert.Equal(0xDADA_0002u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extentAddress + (uint)offset));

        ExecuteTextFit(
            textAddress + 1u,
            rastPort,
            2,
            extentAddress,
            0,
            -1,
            16,
            9,
            0xDADA_0000u);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)15, unchecked((short)bus.ReadWord(
            extentAddress + (uint)GraphicsLayouts.TextExtentMaxX)));

        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        ExecuteTextFit(
            textAddress,
            rastPort,
            2,
            extentAddress,
            0,
            1,
            15,
            9,
            0xDADA_0000u);
        Assert.Equal(0xDADA_0002u, cpu.State.D[0]);
        bus.WriteByte(nativeFont + (uint)GraphicsLayouts.TextFontFlags, 0, 0);

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 1, 0);
        ExecuteTextFit(
            textAddress,
            rastPort,
            2,
            extentAddress,
            0,
            1,
            15,
            9,
            0xDADA_0000u);
        Assert.Equal(0xDADA_0002u, cpu.State.D[0]);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0xCAFE_BABEu);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0x7F, 0);
        ExecuteSetFont(nativeFont, rastPort, 0xDEAD_BEEFu, 35);
        Assert.Equal(nativeFont, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)9, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)7, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)6, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0xCAFE_BABEu);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0x5A, 0);
        ExecuteSetFont(0, rastPort, 0xCAFE_0000u, 10);
        Assert.Equal(0xCAFE_0000u, cpu.State.D[0]);
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((byte)0x5A, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, nativeFont);
        ExecuteAskSoftStyle(rastPort, 0xCAFE_BEEFu, 27);
        Assert.Equal(0xFFFF_FFFCu, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0);
        ExecuteAskSoftStyle(rastPort, 0xDEAD_BEEFu, 15);
        Assert.Equal(0u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, nativeFont);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 1, 0);
        ExecuteSetSoftStyle(rastPort, 6, 7, 47);
        Assert.Equal((byte)5, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal(7u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0x5A, 0);
        ExecuteSetSoftStyle(rastPort, 6, 7, 15);
        Assert.Equal(6u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        Assert.Equal((byte)0xFF, ReadNativeByte(GraphicsLvo.GetAPen));
        Assert.Equal((byte)0, ReadNativeByte(GraphicsLvo.GetBPen));
        Assert.Equal((byte)1, ReadNativeByte(GraphicsLvo.GetDrMd));
        Assert.Equal((byte)0xFF, ReadNativeByte(GraphicsLvo.GetOutlinePen));

        byte ReadNativeByte(GraphicsLvo vector)
        {
            const uint returnAddress = 0x00F0_0000;
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[0] = rastPort;
            cpu.State.A[1] = 0xA1A1_A1A1;
            cpu.State.D[0] = 0xCAFE_BABEu;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return (byte)cpu.State.D[0];
                }
            }

            throw new InvalidOperationException($"Native {vector} body did not return.");
        }
    }

    [Fact]
    public void NativeGraphicsEraseRectAlignedByteMultiRowUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00E0_0000;
        const uint bitmap = 0x00E1_0000;
        const uint plane = 0x00E2_0000;
        const uint stack = 0x00E3_0000;
        const uint returnAddress = 0x00EF_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[64]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            short xMin,
            short yMin,
            short xMax,
            short yMax,
            uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.EraseRect),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)xMin);
            cpu.State.D[1] = unchecked((ushort)yMin);
            cpu.State.D[2] = unchecked((ushort)xMax);
            cpu.State.D[3] = unchecked((ushort)yMax);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native two-row EraseRect body did not return.");
        }

        // BPen=1 fills both selected bytes while preserving guards and
        // the caller's line-pattern phase.
        bus.WriteByte(plane + 0u, 0x11, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x22, 0);
        bus.WriteByte(plane + 5u, 0x5A, 0);
        bus.WriteByte(plane + 6u, 0x33, 0);
        Execute(8, 0, 15, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x11, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)3, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // BPen=0 clears the same two bytes without widening the write span.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 5u, 0x5A, 0);
        bus.WriteByte(plane + 6u, 0x33, 0);
        Execute(8, 0, 15, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x11, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 7u));

        // The companion sixteen-pixel form publishes two consecutive bytes
        // in each row and leaves both outside guard bytes untouched.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(plane + 0u, 0x11, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0x22, 0);
        bus.WriteByte(plane + 4u, 0x33, 0);
        bus.WriteByte(plane + 5u, 0x3C, 0);
        bus.WriteByte(plane + 6u, 0xC3, 0);
        bus.WriteByte(plane + 7u, 0x44, 0);
        Execute(8, 0, 23, 1, 0x1357_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x11, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane + 7u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 5u, 0x3C, 0);
        bus.WriteByte(plane + 6u, 0xC3, 0);
        Execute(8, 0, 23, 1, 0x2468_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x11, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane + 7u));

        // The thirty-two-pixel companion drives four bytes per row through
        // the same bounded byte-count loop.
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 6);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 12; offset++)
            bus.WriteByte(plane + (uint)offset, (byte)(0x20 + offset), 0);
        Execute(8, 0, 39, 1, 0x369C_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 0u));
        for (var offset = 1; offset <= 4; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x25, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x26, bus.ReadByte(plane + 6u));
        for (var offset = 7; offset <= 10; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x2B, bus.ReadByte(plane + 11u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 1; offset <= 4; offset++)
            bus.WriteByte(plane + (uint)offset, 0xA5, 0);
        for (var offset = 7; offset <= 10; offset++)
            bus.WriteByte(plane + (uint)offset, 0x5A, 0);
        Execute(8, 0, 39, 1, 0x47AC_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 1; offset <= 4; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        for (var offset = 7; offset <= 10; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x25, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x26, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x2B, bus.ReadByte(plane + 11u));

        // The maximum sixty-four-pixel companion drives eight bytes per row
        // and keeps the two row guards outside the selected span untouched.
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 10);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 20; offset++)
            bus.WriteByte(plane + (uint)offset, (byte)(0x40 + offset), 0);
        Execute(8, 0, 71, 1, 0x58B0_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 0u));
        for (var offset = 1; offset <= 8; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x49, bus.ReadByte(plane + 9u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 10u));
        for (var offset = 11; offset <= 18; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x53, bus.ReadByte(plane + 19u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 1; offset <= 8; offset++)
            bus.WriteByte(plane + (uint)offset, 0xA5, 0);
        for (var offset = 11; offset <= 18; offset++)
            bus.WriteByte(plane + (uint)offset, 0x5A, 0);
        Execute(8, 0, 71, 1, 0x6C20_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 1; offset <= 8; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        for (var offset = 11; offset <= 18; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x49, bus.ReadByte(plane + 9u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 10u));
        Assert.Equal((byte)0x53, bus.ReadByte(plane + 19u));

        // The row loop also publishes an exact three-row height without
        // widening the byte-span or touching the outside guards.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 30; offset++)
            bus.WriteByte(plane + (uint)offset, (byte)(0x30 + offset), 0);
        Execute(8, 0, 71, 2, 0x5A10_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x30, bus.ReadByte(plane + 0u));
        for (var offset = 1; offset <= 8; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x39, bus.ReadByte(plane + 9u));
        Assert.Equal((byte)0x3A, bus.ReadByte(plane + 10u));
        for (var offset = 11; offset <= 18; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x43, bus.ReadByte(plane + 19u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane + 20u));
        for (var offset = 21; offset <= 28; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x4D, bus.ReadByte(plane + 29u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 1; offset <= 8; offset++)
            bus.WriteByte(plane + (uint)offset, 0xA5, 0);
        for (var offset = 11; offset <= 18; offset++)
            bus.WriteByte(plane + (uint)offset, 0x5A, 0);
        for (var offset = 21; offset <= 28; offset++)
            bus.WriteByte(plane + (uint)offset, 0xC3, 0);
        Execute(8, 0, 71, 2, 0x5B20_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 1; offset <= 8; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        for (var offset = 11; offset <= 18; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        for (var offset = 21; offset <= 28; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x30, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x39, bus.ReadByte(plane + 9u));
        Assert.Equal((byte)0x3A, bus.ReadByte(plane + 10u));
        Assert.Equal((byte)0x43, bus.ReadByte(plane + 19u));
        Assert.Equal((byte)0x44, bus.ReadByte(plane + 20u));
        Assert.Equal((byte)0x4D, bus.ReadByte(plane + 29u));

        // The same exact row-span family also accepts a nonzero yMin when the
        // bitmap row envelope contains both rows.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var offset = 0; offset < 30; offset++)
            bus.WriteByte(plane + (uint)offset, (byte)(0x60 + offset), 0);
        Execute(8, 1, 71, 2, 0x7A40_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x6A, bus.ReadByte(plane + 10u));
        for (var offset = 11; offset <= 18; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x73, bus.ReadByte(plane + 19u));
        Assert.Equal((byte)0x74, bus.ReadByte(plane + 20u));
        for (var offset = 21; offset <= 28; offset++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x7D, bus.ReadByte(plane + 29u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        for (var offset = 11; offset <= 18; offset++)
            bus.WriteByte(plane + (uint)offset, 0xA5, 0);
        for (var offset = 21; offset <= 28; offset++)
            bus.WriteByte(plane + (uint)offset, 0x5A, 0);
        Execute(8, 1, 71, 2, 0x7B50_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 11; offset <= 18; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        for (var offset = 21; offset <= 28; offset++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + (uint)offset));
        Assert.Equal((byte)0x6A, bus.ReadByte(plane + 10u));
        Assert.Equal((byte)0x73, bus.ReadByte(plane + 19u));
        Assert.Equal((byte)0x74, bus.ReadByte(plane + 20u));
        Assert.Equal((byte)0x7D, bus.ReadByte(plane + 29u));

        // yMax beyond the bitmap row envelope declines before publication.
        bus.WriteByte(plane + 11u, 0xA5, 0);
        bus.WriteByte(plane + 21u, 0x5A, 0);
        Execute(8, 1, 71, 3, 0x7C60_0000u);
        Assert.Equal(0x7C60_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 11u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 21u));

        // Inverted vertical bounds remain on the transactional fallback.
        Execute(8, 2, 71, 1, 0x7D70_0000u);
        Assert.Equal(0x7D70_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 11u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 21u));

        // Width, height, and stride-boundary forms remain transactional on
        // the existing fallback owner and preserve the caller's xMin seed.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 5u, 0x5A, 0);
        Execute(8, 0, 16, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 5u));

        Execute(8, 0, 15, 3, 0xFACE_0000u);
        Assert.Equal(0xFACE_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 5u));

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        Execute(8, 0, 15, 1, 0xABCD_0000u);
        Assert.Equal(0xABCD_0008u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 5u));
    }

    [Fact]
    public void NativeGraphicsTextFitPublishesBoundedProportionalOneGlyphEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00F0_0000;
        const uint text = 0x00F1_0000;
        const uint extent = 0x00F2_0000;
        const uint font = 0x00F3_0000;
        const uint charLoc = 0x00F4_0000;
        const uint charSpace = 0x00F5_0000;
        const uint charKern = 0x00F6_0000;
        const uint stack = 0x00C1_0000;

        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(text, new byte[256]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charLoc, new byte[1028]);
        bus.MapWritableMemory(charSpace, new byte[514]);
        bus.MapWritableMemory(charKern, new byte[514]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 2);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0x41, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x43, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteByte(text, 0x42, 0); // B: 7-cell space + 1-cell kern
        for (var index = 1; index < 32; index++)
            bus.WriteByte(text + (uint)index, (byte)('A' + index), 0);
        for (var index = 0; index < 32; index++)
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
        bus.WriteWord(charSpace + 0u, 5);
        bus.WriteWord(charSpace + 2u, 7);
        bus.WriteWord(charSpace + 4u, 6);
        for (var index = 3; index < 32; index++)
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        bus.WriteWord(charSpace + 6u, 4); // default slot after HiChar 'C'
        bus.WriteWord(charSpace + 64u, 4); // default slot after HiChar '`'
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 1);
        bus.WriteWord(charKern + 4u, 0);
        for (var index = 3; index < 32; index++)
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        bus.WriteWord(charKern + 6u, 0); // default slot

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void ExecuteTextFit(
            ushort count,
            ushort width,
            uint constraints,
            uint initialD0,
            short direction = 1)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.TextFit),
                stack + 0x80u);
            cpu.State.A[0] = text;
            cpu.State.A[1] = rastPort;
            cpu.State.A[2] = extent;
            cpu.State.A[3] = constraints;
            cpu.State.D[0] = initialD0 | count;
            cpu.State.D[1] = unchecked((ushort)direction);
            cpu.State.D[2] = width;
            cpu.State.D[3] = 9;
            cpu.ExecuteInstruction();
            for (var index = 0; index < 100_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native proportional TextFit body did not return.");
        }

        ExecuteTextFit(1, 8, 0, 0xFACE_0001u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)7, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // The bounded reverse arm claims one declared proportional glyph
        // with a negative movement cell and publishes the signed envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0x42, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x42, 0);
        bus.WriteWord(charSpace + 0u, unchecked((ushort)-7));
        bus.WriteWord(charSpace + 2u, 4); // default slot
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 0); // default slot
        ExecuteTextFit(1, 8, 0, 0xBEEF_0000u, -1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth)));
        Assert.Equal((ushort)9, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-1, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // Nonnegative movement, a wider declared range, and a box that is
        // too narrow remain transparent fallback/no-fit boundaries.
        bus.WriteWord(charSpace + 0u, 7);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xA5, 0);
        ExecuteTextFit(1, 8, 0, 0xCAFE_0000u, -1);
        Assert.Equal(0xCAFE_0001u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)offset));

        bus.WriteWord(charSpace + 0u, unchecked((ushort)-7));
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x43, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0x5A, 0);
        ExecuteTextFit(1, 8, 0, 0xD00D_0000u, -1);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0x5A, bus.ReadByte(extent + (uint)offset));

        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x42, 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0x3C, 0);
        ExecuteTextFit(1, 6, 0, 0xFACE_0000u, -1);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0, bus.ReadByte(extent + (uint)offset));

        // Restore the richer range for the existing forward/default-slot
        // coverage below.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0x41, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x43, 0);
        bus.WriteWord(charSpace + 0u, 5);
        bus.WriteWord(charSpace + 2u, 7);
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 1);

        // An undeclared byte uses the extra default table slot.
        bus.WriteByte(text, 0x5A, 0);
        ExecuteTextFit(1, 4, 0, 0xFACE_0001u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));

        // A valid movement that exceeds the alternate box is an empty fit,
        // not a provider decline.
        bus.WriteByte(text, 0x42, 0);
        ExecuteTextFit(1, 3, 0, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0, bus.ReadByte(extent + (uint)offset));

        // A bounded forward walk accumulates each positive proportional cell.
        bus.WriteByte(text + 1u, 0x43, 0); // C: 6-cell space + no kern
        ExecuteTextFit(2, 16, 0, 0xFACE_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)14, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)13, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // The extra default slot participates in a bounded multi-glyph walk.
        bus.WriteByte(text, 0x5A, 0);
        Assert.Equal((byte)0x5A, bus.ReadByte(text));
        Assert.Equal((byte)0x43, bus.ReadByte(text + 1u));
        Assert.Equal((byte)0x41, bus.ReadByte(font + (uint)GraphicsLayouts.TextFontLoChar));
        Assert.Equal((byte)0x43, bus.ReadByte(font + (uint)GraphicsLayouts.TextFontHiChar));
        ExecuteTextFit(2, 16, 0, 0xFACE_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)10, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));

        // Width exhaustion publishes an empty fit, while a negative movement
        // remains a transparent decline and preserves the caller-owned extent.
        bus.WriteByte(text, 0x42, 0);
        ExecuteTextFit(2, 10, 0, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charKern + 2u, unchecked((ushort)-8));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xA5, 0);
        ExecuteTextFit(1, 8, 0, 0xDADA_0000u);
        Assert.Equal(0xDADA_0001u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charKern + 2u, 1);
        bus.WriteWord(charKern + 2u, unchecked((ushort)-8));
        ExecuteTextFit(2, 16, 0, 0xDADA_0000u);
        Assert.Equal(0xDADA_0002u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charKern + 2u, 1);
        ExecuteTextFit(1, 8, extent, 0xDADA_0000u);
        Assert.Equal(0xDADA_0001u, cpu.State.D[0]);

        // Counts nine through thirty-two use the shared guarded accumulation
        // with the expanded source/table envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'`', 0);
        bus.WriteWord(charSpace + 6u, 8); // declared D slot when HiChar is '`'
        for (var index = 0; index < 64; index++)
            bus.WriteByte(text + (uint)index, (byte)('A' + index), 0);
        ExecuteTextFit(32, 300, 0, 0x6789_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)251, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)250, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // A malformed thirty-second movement declines without publishing a
        // partial fit or extent.
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xA5, 0);
        bus.WriteWord(charSpace + 62u, unchecked((ushort)-1));
        ExecuteTextFit(32, 300, 0, 0x789A_0000u);
        Assert.Equal(0x789A_0020u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charSpace + 62u, 8);

        // The native TextFit accumulation now admits the complete
        // sixty-four-glyph source/table envelope.  A malformed final cell
        // declines without publishing a partial fit or extent.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x80, 0);
        for (var index = 0; index <= 64; index++)
        {
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
            bus.WriteWord(charSpace + (uint)(index * 2), 5);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 64; index++)
            bus.WriteByte(text + (uint)index, (byte)'A', 0);
        ExecuteTextFit(64, 400, 0, 0x89AB_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)320, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));

        bus.WriteByte(text + 63u, 0x80, 0);
        bus.WriteWord(charSpace + 126u, unchecked((ushort)-1));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xB6, 0);
        ExecuteTextFit(64, 400, 0, 0x9ABC_0000u);
        Assert.Equal(0x9ABC_0040u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xB6, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charSpace + 126u, 5);

        // The native TextFit accumulation now admits the complete one-hundred-
        // twenty-eight-glyph source/table envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xC0, 0);
        for (var index = 65; index <= 128; index++)
        {
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
            bus.WriteWord(charSpace + (uint)(index * 2), 5);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 128; index++)
            bus.WriteByte(text + (uint)index, (byte)'A', 0);
        ExecuteTextFit(128, 1000, 0, 0xABCD_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)640, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));

        bus.WriteByte(text + 127u, 0xC0, 0);
        bus.WriteWord(charSpace + 254u, unchecked((ushort)-1));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xD6, 0);
        ExecuteTextFit(128, 1000, 0, 0xBCDE_0000u);
        Assert.Equal(0xBCDE_0080u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xD6, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charSpace + 254u, 5);

        // The native TextFit accumulation now admits the complete
        // two-hundred-fifty-six-glyph source/table envelope.  A malformed
        // final cell declines without publishing a partial fit or extent.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xFF, 0);
        for (var index = 0; index <= 256; index++)
        {
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
            bus.WriteWord(charSpace + (uint)(index * 2), 5);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 96; index++)
            bus.WriteByte(text + (uint)index, 0, 0);
        ExecuteTextFit(256, 2000, 0, 0xCDEF_0000u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)1280, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)1279, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        bus.WriteByte(text + 255u, 0xFF, 0);
        bus.WriteWord(charSpace + 510u, unchecked((ushort)-1));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xE7, 0);
        ExecuteTextFit(256, 2000, 0, 0xFEDC_0000u);
        Assert.Equal(0xFEDC_0100u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xE7, bus.ReadByte(extent + (uint)offset));
        bus.WriteWord(charSpace + 510u, 5);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);

        // Counts beyond two hundred fifty-six preserve the complete caller D0.
        ExecuteTextFit(257, 300, 0, 0xDADA_0000u);
        Assert.Equal(0xDADA_0101u, cpu.State.D[0]);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        bus.WriteWord(charSpace + 6u, 4);

        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 1, 0);
        ExecuteTextFit(1, 8, 0, 0xDADA_0000u);
        Assert.Equal(0xDADA_0001u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsTextExtentPublishesBoundedReverseProportionalOneGlyphEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00F7_0000;
        const uint text = 0x00F8_0000;
        const uint extent = 0x00F9_0000;
        const uint font = 0x00FA_0000;
        const uint charLoc = 0x00FB_0000;
        const uint charSpace = 0x00FC_0000;
        const uint charKern = 0x00FD_0000;
        const uint stack = 0x00C2_0000;

        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(text, new byte[2]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charLoc, new byte[16]);
        bus.MapWritableMemory(charSpace, new byte[8]);
        bus.MapWritableMemory(charKern, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x24, 0); // proportional + REVPATH
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 2);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0x41, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x43, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteByte(text, 0x42, 0); // B: selected reverse cell
        bus.WriteLong(charLoc + 0u, 0);
        bus.WriteLong(charLoc + 4u, 4);
        bus.WriteLong(charLoc + 8u, 8);
        bus.WriteLong(charLoc + 12u, 12);
        bus.WriteWord(charSpace + 0u, 5);
        bus.WriteWord(charSpace + 2u, unchecked((ushort)-7));
        bus.WriteWord(charSpace + 4u, 6);
        bus.WriteWord(charSpace + 6u, 4); // default slot
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 0);
        bus.WriteWord(charKern + 4u, 0);
        bus.WriteWord(charKern + 6u, 0); // default slot

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void ExecuteTextExtent(ushort count, uint initialD0)
        {
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.TextExtent),
                stack + 0x80u);
            cpu.State.A[0] = text;
            cpu.State.A[1] = rastPort;
            cpu.State.A[2] = extent;
            cpu.State.D[0] = initialD0 | count;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 100_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == 0)
                    return;
            }

            throw new InvalidOperationException("Native reverse proportional TextExtent body did not return.");
        }

        ExecuteTextExtent(1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth)));
        Assert.Equal((ushort)9, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-1, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // Counts beyond the bounded native claim remain transparent to the
        // portable/provider owner and preserve the caller's extent bytes.
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xA5, 0);
        ExecuteTextExtent(2, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0002u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)offset));
    }

    [Fact]
    public void NativeGraphicsFontExtentPublishesBoundedReverseProportionalOneGlyphEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0084_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint extent = 0x00F9_0000;
        const uint font = 0x00FA_0000;
        const uint charLoc = 0x00FB_0000;
        const uint charSpace = 0x00FC_0000;
        const uint charKern = 0x00FD_0000;
        const uint stack = 0x00C3_0000;
        const uint returnAddress = 0x00FE_0000;

        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charLoc, new byte[8]);
        bus.MapWritableMemory(charSpace, new byte[4]);
        bus.MapWritableMemory(charKern, new byte[4]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x24, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 2);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'B', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'B', 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteLong(charLoc + 0u, 0);
        bus.WriteLong(charLoc + 4u, 4);
        bus.WriteWord(charSpace + 0u, unchecked((ushort)-7));
        bus.WriteWord(charSpace + 2u, 4); // default slot
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 0); // default slot

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint? port = null)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FontExtent),
                stack + 0x80u);
            cpu.State.A[0] = font;
            cpu.State.A[1] = extent;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 100_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native reverse proportional FontExtent body did not return.");
        }

        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xCC, 0);
        Execute(0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth)));
        Assert.Equal((ushort)9, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)-7, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-1, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // Nonnegative movement and a multi-glyph declared range remain on the
        // portable/provider owner and preserve both D0 and the result.
        bus.WriteWord(charSpace + 0u, 7);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0xA5, 0);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)offset));

        bus.WriteWord(charSpace + 0u, unchecked((ushort)-7));
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            bus.WriteByte(extent + (uint)offset, 0x5A, 0);
        Execute(0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0x5A, bus.ReadByte(extent + (uint)offset));
    }

    [Fact]
    public void NativeGraphicsBltClearScalarZeroFillUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint buffer = 0x00D5_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(buffer, new byte[0x100]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint destination, uint byteCount, uint flags)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.BltClear),
                stack + 0x80u);
            cpu.State.A[1] = destination;
            cpu.State.D[0] = byteCount;
            cpu.State.D[1] = flags;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native BltClear body did not return.");
        }

        for (var index = 0u; index < 8; index++)
            bus.WriteByte(buffer + index, 0xA5, 0);
        Execute(buffer, 4, 0);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0u; index < 4; index++)
            Assert.Equal((byte)0, bus.ReadByte(buffer + index));
        for (var index = 4u; index < 8; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(buffer + index));

        for (var index = 0u; index < 8; index++)
            bus.WriteByte(buffer + index, 0xA5, 0);
        Execute(buffer, 1, 0);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0, bus.ReadByte(buffer));
        for (var index = 1u; index < 8; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(buffer + index));

        Execute(0, 0, 0);
        Assert.Equal(0u, cpu.State.D[0]);

        for (var index = 0u; index < 4; index++)
            bus.WriteByte(buffer + index, 0, 0);
        Execute(buffer, 4, 0xA55A_0004u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(buffer));
        Assert.Equal((byte)0x5A, bus.ReadByte(buffer + 1u));
        Assert.Equal((byte)0xA5, bus.ReadByte(buffer + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(buffer + 3u));

        for (var index = 0u; index < 8; index++)
            bus.WriteByte(buffer + index, 0x5A, 0);
        Execute(buffer, 1, 0xA55A_0004u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(buffer));
        for (var index = 1u; index < 8; index++)
            Assert.Equal((byte)0x5A, bus.ReadByte(buffer + index));

        for (var index = 0u; index < 8; index++)
            bus.WriteByte(buffer + index, 0xA5, 0);
        Execute(buffer, 3, 0);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0u; index < 3; index++)
            Assert.Equal((byte)0, bus.ReadByte(buffer + index));
        for (var index = 3u; index < 8; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(buffer + index));

        for (var index = 0u; index < 8; index++)
            bus.WriteByte(buffer + index, 0x5A, 0);
        Execute(buffer, 3, 0xA55A_0004u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(buffer));
        Assert.Equal((byte)0x5A, bus.ReadByte(buffer + 1u));
        Assert.Equal((byte)0xA5, bus.ReadByte(buffer + 2u));
        for (var index = 3u; index < 8; index++)
            Assert.Equal((byte)0x5A, bus.ReadByte(buffer + index));

        foreach (var (destination, byteCount, flags) in new[]
        {
            (buffer + 1u, 2u, 0u),
            (buffer, 4u, 2u),
            (buffer, 4u, 0xA55A_0000u),
            (buffer, 0x0001_0000u, 0u),
            (0u, 2u, 0u)
        })
        {
            for (var index = 0u; index < 8; index++)
                bus.WriteByte(buffer + index, 0x5A, 0);

            Execute(destination, byteCount, flags);
            Assert.Equal(byteCount, cpu.State.D[0]);
            for (var index = 0u; index < 8; index++)
                Assert.Equal((byte)0x5A, bus.ReadByte(buffer + index));
        }

        // A scalar word walk ending exactly at $FFFF_FFFF is valid. The
        // accurate 68000 core accesses the corresponding 24-bit bus alias;
        // the native span guard must not discard that legal endpoint merely
        // because base + byteCount wraps to zero.
        const uint topBuffer = 0xFFFF_FFFCu;
        const uint topBufferPhysical = topBuffer & 0x00FF_FFFFu;
        bus.MapWritableMemory(topBufferPhysical, new byte[4]);
        for (var index = 0u; index < 4; index++)
            bus.WriteByte(topBufferPhysical + index, 0x5A, 0);
        Execute(topBuffer, 4, 0);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0u; index < 4; index++)
            Assert.Equal((byte)0, bus.ReadByte(topBufferPhysical + index));

        // Extending that same request past the address limit remains a clean
        // fallback and cannot publish a prefix in high memory.
        for (var index = 0u; index < 4; index++)
            bus.WriteByte(topBufferPhysical + index, 0x5A, 0);
        Execute(topBuffer, 6, 0);
        Assert.Equal(6u, cpu.State.D[0]);
        for (var index = 0u; index < 4; index++)
            Assert.Equal((byte)0x5A, bus.ReadByte(topBufferPhysical + index));
    }

    [Fact]
    public void NativeGraphicsBltTemplatePublishesAlignedAllOnRowOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint template = 0x00D0_0000;
        const uint rastPort = 0x00D1_0000;
        const uint bitmap = 0x00D2_0000;
        const uint plane = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(template, new byte[2]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[20]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(template, 0xFF, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            uint sourceX,
            uint width,
            uint height,
            uint targetRastPort = rastPort,
            uint sourceTemplate = template)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.BltTemplate),
                stack + 0x80u);
            cpu.State.A[0] = sourceTemplate;
            cpu.State.A[1] = targetRastPort;
            cpu.State.D[0] = sourceX;
            cpu.State.D[1] = 0;
            cpu.State.D[2] = 0;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = width;
            cpu.State.D[5] = height;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native BltTemplate body did not return.");
        }

        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        Execute(0, 8, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteByte(plane, 0x5A, 0);
        Execute(0, 8, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));

        foreach (var (source, widthValue, heightValue, expectedD0) in new[]
        {
            (1u, 8u, 1u, 1u),
            (0u, 16u, 1u, 0u),
            (0u, 8u, 2u, 0u)
        })
        {
            bus.WriteByte(plane, 0x5A, 0);
            bus.WriteByte(template, source == 1 ? (byte)0xFF : (byte)0xF0, 0);
            Execute(source, widthValue, heightValue);
            Assert.Equal(expectedD0, cpu.State.D[0]);
            Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        }

        // A high RastPort base once passed the coarse native high-address
        // guard and let its BitMap/pen fields alias this valid-looking low
        // structure. The complete 0xB4-byte public envelope must be checked
        // before the first displacement load.
        const uint wrappedRastPort = 0xFFFF_FFFCu;
        bus.MapWritableMemory(0, new byte[0x40]);
        bus.WriteLong(0, bitmap); // wrapped rp_BitMap
        bus.WriteByte(0x14, 1, 0); // wrapped rp_Mask
        bus.WriteByte(0x15, 1, 0); // wrapped rp_FgPen
        bus.WriteByte(0x18, 0, 0); // wrapped rp_DrawMode
        bus.WriteWord(0x1C, 0); // wrapped rp_Flags
        bus.WriteByte(template, 0xFF, 0);
        bus.WriteByte(plane, 0x5A, 0);
        Execute(0, 8, 1, wrappedRastPort);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));

        // Width 32 consumes four template bytes. An even source at
        // $FFFF_FFFE must not borrow its last two bytes from low memory.
        const uint wrappedTemplate = 0xFFFF_FFFEu;
        bus.MapWritableMemory(wrappedTemplate, new byte[2]);
        bus.WriteByte(wrappedTemplate, 0xFF, 0);
        bus.WriteByte(uint.MaxValue, 0xFF, 0);
        bus.WriteByte(0, 0xFF, 0);
        bus.WriteByte(1, 0xFF, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(plane, 0x5A, 0);
        Execute(0, 32, 1, sourceTemplate: wrappedTemplate);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));

        // A full public BitMap envelope may logically end exactly at the
        // top of the 32-bit guest address space. The accurate 68000 core
        // presents the corresponding 24-bit physical alias to the bus; the
        // precise logical span guard must still accept the pointer.
        const uint topBitMap = 0xFFFF_FFD8u;
        const uint topBitMapPhysical = topBitMap & 0x00FF_FFFFu;
        bus.MapWritableMemory(topBitMapPhysical, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteWord(topBitMapPhysical + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(topBitMapPhysical + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(topBitMapPhysical + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(topBitMapPhysical + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, topBitMap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(template, 0xFF, 0);
        bus.WriteByte(plane, 0x5A, 0);
        Assert.Equal((ushort)2, bus.ReadWord(topBitMapPhysical + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)1, bus.ReadWord(topBitMapPhysical + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)1, bus.ReadByte(topBitMapPhysical + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(plane, bus.ReadLong(topBitMapPhysical + (uint)GraphicsLayouts.BitMapPlanes));
        Execute(0, 8, 1);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane));
    }

    [Fact]
    public void NativeGraphicsBltTemplatePublishesAlignedAllOnRowsWithZeroSourceModuloOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint template = 0x00D8_0000;
        const uint rastPort = 0x00D9_0000;
        const uint bitmap = 0x00DA_0000;
        const uint plane = 0x00DB_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(template, new byte[2]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(template, 0xFF, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 4);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(ushort height, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.BltTemplate),
                stack + 0x80u);
            cpu.State.A[0] = template;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0; // source X low word remains zero
            cpu.State.D[1] = 0; // zero source modulo repeats the source byte
            cpu.State.D[2] = 0xFACE_0000u; // destination X low word zero
            cpu.State.D[3] = 0xD00D_0000u; // destination Y zero
            cpu.State.D[4] = 0x1234_0008u; // eight-pixel aligned cell
            cpu.State.D[5] = 0xBEEF_0000u | height;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native BltTemplate multi-row body did not return.");
        }

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        for (var index = 0; index < 8; index++)
            bus.WriteByte(plane + (uint)index, 0x5A, 0);
        Execute(3, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)(index % 2 == 0 ? 0xFF : 0x5A), bus.ReadByte(plane + (uint)index));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        Execute(3, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)(index % 2 == 0 ? 0x00 : 0x5A), bus.ReadByte(plane + (uint)index));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        for (var index = 0; index < 8; index++)
            bus.WriteByte(plane + (uint)index, 0xA5, 0);
        Execute(5, 0xFACE_0000u);
        Assert.Equal(0xFACE_0000u, cpu.State.D[0]);
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(plane + (uint)index));

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 0xFFFE);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 0xFFFF);
        Execute(0xFFFE, 0xABCD_0000u);
        Assert.Equal(0xABCD_0000u, cpu.State.D[0]);
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(plane + (uint)index));
    }

    [Fact]
    public void NativeGraphicsBltTemplatePublishesAlignedRowsThrough128PixelsAndDeclinesOtherWidthsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint template = 0x00DC_0000;
        const uint rastPort = 0x00DD_0000;
        const uint bitmap = 0x00DE_0000;
        const uint plane = 0x00DF_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(template, new byte[16]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[34]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(template + 0u, 0xFF, 0);
        bus.WriteByte(template + 1u, 0xFF, 0);
        for (var index = 0; index < 16; index++)
            bus.WriteByte(template + (uint)index, 0xFF, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(ushort width, ushort bytesPerRow, uint initialD0)
        {
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, bytesPerRow);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.BltTemplate),
                stack + 0x80u);
            cpu.State.A[0] = template;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0;
            cpu.State.D[1] = 0;
            cpu.State.D[2] = 0;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = 0x1234_0000u | width;
            cpu.State.D[5] = 1;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native BltTemplate sixteen-pixel body did not return.");
        }

        bus.WriteByte(plane + 0u, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0x5A, 0);
        bus.WriteByte(plane + 4u, 0xA5, 0);
        Execute(16, 2, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 4u));

        bus.WriteByte(template + 2u, 0xFF, 0);
        bus.WriteByte(template + 3u, 0xFF, 0);
        for (var index = 0; index < 12; index++)
            bus.WriteByte(plane + (uint)index, 0x5A, 0);
        bus.WriteByte(plane + 8u, 0xA5, 0);
        Execute(32, 4, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)index));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 8u));

        for (var index = 4; index < 8; index++)
            bus.WriteByte(template + (uint)index, 0xFF, 0);
        for (var index = 0; index < 20; index++)
            bus.WriteByte(plane + (uint)index, 0x5A, 0);
        bus.WriteByte(plane + 16u, 0xA5, 0);
        Execute(64, 8, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 16; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)index));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 16u));

        // Exact aligned 128-pixel rows validate all sixteen source bytes and
        // publish four longs per row, preserving the post-row guard.
        for (var index = 0; index < 34; index++)
            bus.WriteByte(plane + (uint)index, 0x5A, 0);
        bus.WriteByte(plane + 32u, 0xA5, 0);
        Execute(128, 16, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 32; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)index));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 33u));

        bus.WriteByte(plane + 0u, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0x5A, 0);
        Execute(14, 2, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));

        Execute(16, 1, 0xFACE_0000u);
        Assert.Equal(0xFACE_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));

        for (var index = 0; index < 34; index++)
            bus.WriteByte(plane + (uint)index, 0xA5, 0);
        Execute(128, 15, 0xABCD_0000u);
        Assert.Equal(0xABCD_0000u, cpu.State.D[0]);
        for (var index = 0; index < 34; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(plane + (uint)index));

        Execute(129, 16, 0xDCBA_0000u);
        Assert.Equal(0xDCBA_0000u, cpu.State.D[0]);
        for (var index = 0; index < 34; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(plane + (uint)index));
    }

    [Fact]
    public void NativeGraphicsFloodZeroMaskSeedIsSuccessfulNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint bitmap = 0x00D2_0000;
        const uint plane = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[4]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteByte(plane, 0xA5, 0);
        bus.WriteByte(plane + 1u, 0x5A, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint x, uint y, uint mode)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.Flood),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = x;
            cpu.State.D[1] = y;
            cpu.State.D[2] = mode;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native Flood body did not return.");
        }

        Execute(0, 0, 0);
        Assert.Equal(1u, cpu.State.D[0]);
        Execute(1, 1, 0);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));

        foreach (var (x, y, mode) in new[]
        {
            (1u, 0u, 0u), // active mask
            (1u, 0u, 1u), // border mode remains on the portable owner
            (16u, 0u, 0u), // x == bytesPerRow * 8
            (1u, 2u, 0u) // y == rows
        })
        {
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0, 0);
            bus.WriteByte(plane, 0xA5, 0);
            bus.WriteByte(plane + 1u, 0x5A, 0);
            if (x == 1u && y == 0u && mode == 0u)
                bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);

            Execute(x, y, mode);
            Assert.Equal(x, cpu.State.D[0]);
            Assert.Equal((byte)0xA5, bus.ReadByte(plane));
            Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));
        }

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x00D4_0000u);
        Execute(1, 0, 0);
        Assert.Equal(1u, cpu.State.D[0]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);

        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        Execute(1, 0, 0);
        Assert.Equal(1u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsInitGelsPublishesSentinelsAndDeclinesOverlapsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint guestBase = 0x00D5_0000;
        const uint head = guestBase + 0x000;
        const uint tail = guestBase + 0x100;
        const uint gelsInfo = guestBase + 0x200;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(guestBase, new byte[0x400]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            bus.WriteByte(head + (uint)index, 0xA5, 0);
            bus.WriteByte(tail + (uint)index, 0x5A, 0);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint headAddress, uint tailAddress, uint gelsAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitGels),
                stack + 0x80u);
            cpu.State.A[0] = headAddress;
            cpu.State.A[1] = tailAddress;
            cpu.State.A[2] = gelsAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native InitGels body did not return.");
        }

        Execute(head, tail, gelsInfo, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteClearPath));
        Assert.Equal(0u, bus.ReadLong(head + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpriteNext));
        foreach (var offset in new[]
        {
            GraphicsLayouts.VSpriteOldY,
            GraphicsLayouts.VSpriteOldX,
            GraphicsLayouts.VSpriteY,
            GraphicsLayouts.VSpriteX
        })
        {
            Assert.Equal((ushort)0x8000, bus.ReadWord(head + (uint)offset));
            Assert.Equal((ushort)0x7FFF, bus.ReadWord(tail + (uint)offset));
        }

        Assert.Equal(head, bus.ReadLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoHead));
        Assert.Equal(tail, bus.ReadLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoTail));
        Assert.Equal((byte)0, bus.ReadByte(gelsInfo + (uint)GraphicsLayouts.GelsInfoFlags));
        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            if (index is >= GraphicsLayouts.VSpriteNext and < GraphicsLayouts.VSpriteNext + sizeof(uint) or
                >= GraphicsLayouts.VSpriteClearPath and < GraphicsLayouts.VSpriteClearPath + sizeof(uint) or
                >= GraphicsLayouts.VSpritePrev and < GraphicsLayouts.VSpritePrev + sizeof(uint) or
                >= GraphicsLayouts.VSpriteOldY and < GraphicsLayouts.VSpriteOldY + 2 or
                >= GraphicsLayouts.VSpriteOldX and < GraphicsLayouts.VSpriteOldX + 2 or
                >= GraphicsLayouts.VSpriteY and < GraphicsLayouts.VSpriteY + 2 or
                >= GraphicsLayouts.VSpriteX and < GraphicsLayouts.VSpriteX + 2)
                continue;

            Assert.Equal((byte)0, bus.ReadByte(head + (uint)index));
            Assert.Equal((byte)0, bus.ReadByte(tail + (uint)index));
        }

        // A resident collision table belongs to the portable/provider owner;
        // the narrow native arm must decline without clearing either sentinel.
        bus.WriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            guestBase + 0x300u);
        var handlerHead = new byte[GraphicsLayouts.VSpriteSize];
        var handlerTail = new byte[GraphicsLayouts.VSpriteSize];
        var handlerGels = new byte[GraphicsLayouts.GelsInfoSize];
        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            bus.WriteByte(head + (uint)index, 0x3C, 0);
            bus.WriteByte(tail + (uint)index, 0xC3, 0);
            handlerHead[index] = bus.ReadByte(head + (uint)index);
            handlerTail[index] = bus.ReadByte(tail + (uint)index);
        }

        for (var index = 0; index < GraphicsLayouts.GelsInfoSize; index++)
        {
            handlerGels[index] = bus.ReadByte(gelsInfo + (uint)index);
        }

        Execute(head, tail, gelsInfo, 0x2468_ACEEu);
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            Assert.Equal(handlerHead[index], bus.ReadByte(head + (uint)index));
            Assert.Equal(handlerTail[index], bus.ReadByte(tail + (uint)index));
        }

        for (var index = 0; index < GraphicsLayouts.GelsInfoSize; index++)
        {
            Assert.Equal(handlerGels[index], bus.ReadByte(gelsInfo + (uint)index));
        }

        bus.WriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            0);

        // An overlapping tail must decline before either sentinel is touched,
        // restoring the caller's D0 as it returns through the native fallback.
        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            bus.WriteByte(head + (uint)index, 0xA5, 0);
            bus.WriteByte(head + 2u + (uint)index, 0x5A, 0);
        }
        var overlapHead = new byte[GraphicsLayouts.VSpriteSize];
        var overlapTail = new byte[GraphicsLayouts.VSpriteSize];
        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            overlapHead[index] = bus.ReadByte(head + (uint)index);
            overlapTail[index] = bus.ReadByte(head + 2u + (uint)index);
        }

        Execute(head, head + 2u, gelsInfo, 0x1357_9BDFu);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.VSpriteSize; index++)
        {
            Assert.Equal(overlapHead[index], bus.ReadByte(head + (uint)index));
            Assert.Equal(overlapTail[index], bus.ReadByte(head + 2u + (uint)index));
        }
    }

    [Fact]
    public void NativeGraphicsSetCollisionPublishesSelectedRoutineAndDeclinesMalformedTablesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint guestBase = 0x00D6_0000;
        const uint gelsInfo = guestBase;
        const uint collisionTable = guestBase + 0x100u;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(guestBase, new byte[0x200]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            collisionTable);
        for (var index = 0; index < GraphicsLayouts.CollisionTableEntries; index++)
            bus.WriteLong(collisionTable + (uint)(index * sizeof(uint)), 0x1000_0000u + (uint)index);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint number, uint routine, uint gelsAddress)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.SetCollision),
                stack + 0x80u);
            cpu.State.A[0] = routine;
            cpu.State.A[1] = gelsAddress;
            cpu.State.D[0] = number;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native SetCollision body did not return.");
        }

        const uint selectedNumber = 4;
        const uint selectedEntry = collisionTable + selectedNumber * sizeof(uint);
        const uint selectedRoutine = 0xCAFE_BABEu;
        Execute(selectedNumber, selectedRoutine, gelsInfo);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(selectedRoutine, bus.ReadLong(selectedEntry));
        Assert.Equal(0x1000_0003u, bus.ReadLong(collisionTable + 3u * sizeof(uint)));
        Assert.Equal(0x1000_0005u, bus.ReadLong(collisionTable + 5u * sizeof(uint)));

        // The 16th selector is outside the public table and must return
        // through the compatibility tail without changing the table or D0.
        var beforeOutOfRange = bus.ReadLong(selectedEntry);
        Execute(GraphicsLayouts.CollisionTableEntries, 0x0BAD_F00Du, gelsInfo);
        Assert.Equal((uint)GraphicsLayouts.CollisionTableEntries, cpu.State.D[0]);
        Assert.Equal(beforeOutOfRange, bus.ReadLong(selectedEntry));

        // An odd GelsInfo base is not safe for direct 68000 LONG accesses.
        // The native admission must decline before dereferencing it.
        Execute(selectedNumber, 0x0BAD_C0DEu, gelsInfo + 1u);
        Assert.Equal(selectedNumber, cpu.State.D[0]);
        Assert.Equal(beforeOutOfRange, bus.ReadLong(selectedEntry));

        // A handler table whose final possible entry would wrap is also
        // declined without touching the table.
        bus.WriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            0xFFFF_FFC2u);
        Execute(selectedNumber, 0x0BAD_C0DEu, gelsInfo);
        Assert.Equal(selectedNumber, cpu.State.D[0]);
        Assert.Equal(beforeOutOfRange, bus.ReadLong(selectedEntry));
    }

    [Fact]
    public void NativeGraphicsInitMasksPublishesOneWordAndDeclinesRicherFormsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint guestBase = 0x00D7_0000;
        const uint sprite = guestBase;
        const uint imageData = guestBase + 0x100u;
        const uint borderLine = guestBase + 0x102u;
        const uint collisionMask = guestBase + 0x104u;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(guestBase, new byte[0x200]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteFlags, GraphicsLayouts.VSpriteFlag);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteHeight, 1);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteWidth, 1);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteDepth, 1);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteImageData, imageData);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteBorderLine, borderLine);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteCollMask, collisionMask);
        bus.WriteWord(imageData, 0xA55A);
        bus.WriteWord(borderLine, 0x1111);
        bus.WriteWord(collisionMask, 0x2222);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint spriteAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.InitMasks),
                stack + 0x80u);
            cpu.State.A[0] = spriteAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native InitMasks body did not return.");
        }

        Execute(sprite, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0xA55A, bus.ReadWord(borderLine));
        Assert.Equal((ushort)0xA55A, bus.ReadWord(collisionMask));

        bus.WriteWord(borderLine, 0x1111);
        bus.WriteWord(collisionMask, 0x2222);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteWidth, 2);
        Execute(sprite, 0x1357_9BDFu);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);
        Assert.Equal((ushort)0x1111, bus.ReadWord(borderLine));
        Assert.Equal((ushort)0x2222, bus.ReadWord(collisionMask));

        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteWidth, 1);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteImageData, imageData + 1u);
        Execute(sprite, 0x2468_ACEEu);
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);
        Assert.Equal((ushort)0x1111, bus.ReadWord(borderLine));
        Assert.Equal((ushort)0x2222, bus.ReadWord(collisionMask));

        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteImageData, imageData);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteFlags, 0);
        Execute(sprite, 0xDEAD_BEEFu);
        Assert.Equal(0xDEAD_BEEFu, cpu.State.D[0]);
        Assert.Equal((ushort)0x1111, bus.ReadWord(borderLine));
        Assert.Equal((ushort)0x2222, bus.ReadWord(collisionMask));
    }

    [Fact]
    public void NativeGraphicsRemVSpriteUnlinksReciprocalNeighborsAndDeclinesBrokenChainsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint guestBase = 0x00D8_0000;
        const uint head = guestBase;
        const uint sprite = guestBase + 0x100u;
        const uint tail = guestBase + 0x200u;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(guestBase, new byte[0x300]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        void LinkChain()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, sprite);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, sprite);
        }

        LinkChain();

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint spriteAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.RemVSprite),
                stack + 0x80u);
            cpu.State.A[0] = spriteAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 512; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native RemVSprite body did not return.");
        }

        Execute(sprite, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));

        // A non-reciprocal neighbor must decline before any link is touched.
        LinkChain();
        bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, tail);
        Execute(sprite, 0x1357_9BDFu);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));

        // Odd neighbor addresses are rejected before the reciprocal reads.
        LinkChain();
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, head + 1u);
        Execute(sprite, 0x2468_ACEEu);
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);
        Assert.Equal(head + 1u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
    }

    [Fact]
    public void NativeGraphicsAddVSpritePublishesBoundedListInsertionAndDeclinesLongerListsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint guestBase = 0x00D9_0000;
        const uint rastPort = guestBase + 0x300u;
        const uint gelsInfo = guestBase + 0x400u;
        const uint head = guestBase + 0x500u;
        const uint tail = guestBase + 0x600u;
        const uint sprite = guestBase + 0x700u;
        const uint existingSprite = guestBase + 0x780u;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(guestBase, new byte[0x900]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortGelsInfo, gelsInfo);
        bus.WriteLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoHead, head);
        bus.WriteLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoTail, tail);
        bus.WriteWord(
            sprite + (uint)GraphicsLayouts.VSpriteFlags,
            (ushort)(GraphicsLayouts.VSpriteFlag | 0x00A5));

        void LinkEmpty()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, 0);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, 0);
        }

        void LinkPopulated()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, sprite);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, sprite);
        }

        void LinkSingleton()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, existingSprite);
            bus.WriteLong(existingSprite + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(existingSprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, existingSprite);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpriteNext, 0);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, 0);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, 0);
        }

        LinkEmpty();

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint spriteAddress, uint rastPortAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.AddVSprite),
                stack + 0x80u);
            cpu.State.A[0] = spriteAddress;
            cpu.State.A[1] = rastPortAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 2048; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native AddVSprite body did not return.");
        }

        Execute(sprite, rastPort, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal((ushort)0x00A5, bus.ReadWord(sprite + (uint)GraphicsLayouts.VSpriteFlags));

        LinkSingleton();
        bus.WriteWord(existingSprite + (uint)GraphicsLayouts.VSpriteY, 10);
        bus.WriteWord(existingSprite + (uint)GraphicsLayouts.VSpriteX, 20);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 5);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 30);
        Execute(sprite, rastPort, 0x1111_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(existingSprite, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(existingSprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(existingSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(existingSprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal((ushort)0x00A5, bus.ReadWord(sprite + (uint)GraphicsLayouts.VSpriteFlags));

        LinkSingleton();
        bus.WriteWord(existingSprite + (uint)GraphicsLayouts.VSpriteY, 5);
        bus.WriteWord(existingSprite + (uint)GraphicsLayouts.VSpriteX, 20);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 30);
        Execute(sprite, rastPort, 0x1111_0002u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(existingSprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(existingSprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(sprite, bus.ReadLong(existingSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(existingSprite, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));

        // Lists with two or more existing nodes are reserved for the portable
        // sorted insertion path; the native bounded arm leaves them intact.
        LinkPopulated();
        var originalFlags = bus.ReadWord(sprite + (uint)GraphicsLayouts.VSpriteFlags);
        Execute(sprite, rastPort, 0x1357_9BDFu);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(originalFlags, bus.ReadWord(sprite + (uint)GraphicsLayouts.VSpriteFlags));

        LinkEmpty();
        Execute(sprite, rastPort + 1u, 0x2468_ACEEu);
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));

        // Stale outer sentinel links are malformed even when the inner empty
        // topology looks reciprocal; admission must leave the list untouched.
        LinkEmpty();
        bus.WriteLong(head + (uint)GraphicsLayouts.VSpritePrev, tail);
        Execute(sprite, rastPort, 0x3579_BDF1u);
        Assert.Equal(0x3579_BDF1u, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpritePrev));

        LinkEmpty();
        bus.WriteLong(tail + (uint)GraphicsLayouts.VSpriteNext, head);
        Execute(sprite, rastPort, 0x468A_CEE2u);
        Assert.Equal(0x468A_CEE2u, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpriteNext));
    }

    [Fact]
    public void NativeGraphicsSortGListSortsBoundedChainsAndDeclinesMalformedFormsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint guestBase = 0x00D9_0000;
        const uint rastPort = guestBase + 0x300u;
        const uint gelsInfo = guestBase + 0x400u;
        const uint head = guestBase + 0x500u;
        const uint tail = guestBase + 0x600u;
        const uint sprite = guestBase + 0x700u;
        const uint secondSprite = guestBase + 0x780u;
        const uint thirdSprite = guestBase + 0x800u;
        const uint fourthSprite = guestBase + 0x880u;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(guestBase, new byte[0x900]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortGelsInfo, gelsInfo);
        bus.WriteLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoHead, head);
        bus.WriteLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoTail, tail);

        void LinkEmpty()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpriteNext, 0);
        }

        void LinkSingleton()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, sprite);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, sprite);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpriteNext, 0);
        }

        void LinkTwoNode()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, sprite);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, secondSprite);
            bus.WriteLong(secondSprite + (uint)GraphicsLayouts.VSpritePrev, sprite);
            bus.WriteLong(secondSprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, secondSprite);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpriteNext, 0);
        }

        void LinkThreeNode()
        {
            bus.WriteLong(head + (uint)GraphicsLayouts.VSpriteNext, sprite);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, head);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, secondSprite);
            bus.WriteLong(secondSprite + (uint)GraphicsLayouts.VSpritePrev, sprite);
            bus.WriteLong(secondSprite + (uint)GraphicsLayouts.VSpriteNext, thirdSprite);
            bus.WriteLong(thirdSprite + (uint)GraphicsLayouts.VSpritePrev, secondSprite);
            bus.WriteLong(thirdSprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, thirdSprite);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpriteNext, 0);
        }

        void LinkFourNode()
        {
            LinkThreeNode();
            bus.WriteLong(thirdSprite + (uint)GraphicsLayouts.VSpriteNext, fourthSprite);
            bus.WriteLong(fourthSprite + (uint)GraphicsLayouts.VSpritePrev, thirdSprite);
            bus.WriteLong(fourthSprite + (uint)GraphicsLayouts.VSpriteNext, tail);
            bus.WriteLong(tail + (uint)GraphicsLayouts.VSpritePrev, fourthSprite);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint rastPortAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.SortGList),
                stack + 0x80u);
            cpu.State.A[1] = rastPortAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException("Native SortGList body did not return.");
        }

        LinkEmpty();
        Execute(rastPort, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpriteNext));

        LinkSingleton();
        Execute(rastPort, 0x1357_9BDFu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));

        LinkTwoNode();
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 20);
        bus.WriteWord(secondSprite + (uint)GraphicsLayouts.VSpriteY, 0xFFFF);
        bus.WriteWord(secondSprite + (uint)GraphicsLayouts.VSpriteX, 30);
        Execute(rastPort, 0x2468_ACEEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(secondSprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(secondSprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(sprite, bus.ReadLong(secondSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(secondSprite, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));

        LinkThreeNode();
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 20);
        bus.WriteWord(secondSprite + (uint)GraphicsLayouts.VSpriteY, 5);
        bus.WriteWord(secondSprite + (uint)GraphicsLayouts.VSpriteX, 20);
        bus.WriteWord(thirdSprite + (uint)GraphicsLayouts.VSpriteY, 0xFFFF);
        bus.WriteWord(thirdSprite + (uint)GraphicsLayouts.VSpriteX, 30);
        Execute(rastPort, 0x1357_9BDFu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(thirdSprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(thirdSprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(secondSprite, bus.ReadLong(thirdSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(thirdSprite, bus.ReadLong(secondSprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(sprite, bus.ReadLong(secondSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(secondSprite, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));

        // Equal positions are stable: the original sprite order remains
        // third -> second -> first after the successful reorder above.
        bus.WriteWord(thirdSprite + (uint)GraphicsLayouts.VSpriteY, 7);
        bus.WriteWord(thirdSprite + (uint)GraphicsLayouts.VSpriteX, 9);
        bus.WriteWord(secondSprite + (uint)GraphicsLayouts.VSpriteY, 7);
        bus.WriteWord(secondSprite + (uint)GraphicsLayouts.VSpriteX, 9);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 7);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 9);
        Execute(rastPort, 0x2468_ACEEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(thirdSprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(secondSprite, bus.ReadLong(thirdSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(sprite, bus.ReadLong(secondSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));

        void SetPosition(uint address, ushort y, ushort x)
        {
            bus.WriteWord(address + (uint)GraphicsLayouts.VSpriteY, y);
            bus.WriteWord(address + (uint)GraphicsLayouts.VSpriteX, x);
        }

        void AssertThreeOrder(uint first, uint second, uint third)
        {
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal(first, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
            Assert.Equal(head, bus.ReadLong(first + (uint)GraphicsLayouts.VSpritePrev));
            Assert.Equal(second, bus.ReadLong(first + (uint)GraphicsLayouts.VSpriteNext));
            Assert.Equal(first, bus.ReadLong(second + (uint)GraphicsLayouts.VSpritePrev));
            Assert.Equal(third, bus.ReadLong(second + (uint)GraphicsLayouts.VSpriteNext));
            Assert.Equal(second, bus.ReadLong(third + (uint)GraphicsLayouts.VSpritePrev));
            Assert.Equal(tail, bus.ReadLong(third + (uint)GraphicsLayouts.VSpriteNext));
            Assert.Equal(third, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        }

        // Exercise every strict ordering branch of the three-node insertion
        // sorter, always rebuilding the original [sprite, second, third]
        // topology before the call.
        LinkThreeNode();
        SetPosition(sprite, 1, 0);
        SetPosition(secondSprite, 2, 0);
        SetPosition(thirdSprite, 3, 0);
        Execute(rastPort, 0x1111_0001u);
        AssertThreeOrder(sprite, secondSprite, thirdSprite);

        LinkThreeNode();
        SetPosition(sprite, 1, 0);
        SetPosition(secondSprite, 3, 0);
        SetPosition(thirdSprite, 2, 0);
        Execute(rastPort, 0x1111_0002u);
        AssertThreeOrder(sprite, thirdSprite, secondSprite);

        LinkThreeNode();
        SetPosition(sprite, 2, 0);
        SetPosition(secondSprite, 1, 0);
        SetPosition(thirdSprite, 3, 0);
        Execute(rastPort, 0x1111_0003u);
        AssertThreeOrder(secondSprite, sprite, thirdSprite);

        LinkThreeNode();
        SetPosition(sprite, 3, 0);
        SetPosition(secondSprite, 1, 0);
        SetPosition(thirdSprite, 2, 0);
        Execute(rastPort, 0x1111_0004u);
        AssertThreeOrder(secondSprite, thirdSprite, sprite);

        LinkThreeNode();
        SetPosition(sprite, 2, 0);
        SetPosition(secondSprite, 3, 0);
        SetPosition(thirdSprite, 1, 0);
        Execute(rastPort, 0x1111_0005u);
        AssertThreeOrder(thirdSprite, sprite, secondSprite);

        LinkThreeNode();
        SetPosition(sprite, 3, 0);
        SetPosition(secondSprite, 2, 0);
        SetPosition(thirdSprite, 1, 0);
        Execute(rastPort, 0x1111_0006u);
        AssertThreeOrder(thirdSprite, secondSprite, sprite);

        // A four-node chain is outside the native bounded arm and must retain
        // the caller's D0 and topology for the portable/provider sorter.
        LinkFourNode();
        Execute(rastPort, 0x369C_DF02u);
        Assert.Equal(0x369C_DF02u, cpu.State.D[0]);
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(secondSprite, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(thirdSprite, bus.ReadLong(secondSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(fourthSprite, bus.ReadLong(thirdSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, bus.ReadLong(fourthSprite + (uint)GraphicsLayouts.VSpriteNext));

        LinkEmpty();
        Execute(rastPort + 1u, 0x369C_DF02u);
        Assert.Equal(0x369C_DF02u, cpu.State.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));

        bus.WriteLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoHead, tail);
        Execute(rastPort, 0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsScrollRasterZeroDisplacementNoOpUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, short deltaX, short deltaY, uint initialD0, uint rp = rastPort)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0 | unchecked((ushort)deltaX);
            cpu.State.D[1] = unchecked((ushort)deltaY);
            cpu.State.D[2] = 1;
            cpu.State.D[3] = 2;
            cpu.State.D[4] = 8;
            cpu.State.D[5] = 9;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native ScrollRaster no-op body did not return.");
        }

        Execute(GraphicsLvo.ScrollRaster, 0, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Execute(GraphicsLvo.ScrollRasterBF, 0, 0, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);

        // Both zero-displacement vectors accept a complete RastPort ending at
        // the logical address limit; AccurateM68000 reaches its 24-bit alias.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        Execute(GraphicsLvo.ScrollRaster, 0, 0, 0xBEEF_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Execute(GraphicsLvo.ScrollRasterBF, 0, 0, 0xFACE_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);

        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xFACE_0000u);
        Assert.Equal(0xFACE_0001u, cpu.State.D[0]);
        Execute(GraphicsLvo.ScrollRasterBF, 0, 1, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 1);
        Execute(GraphicsLvo.ScrollRaster, 0, 0, 0xABCD_0000u);
        Assert.Equal(0xABCD_0000u, cpu.State.D[0]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        Execute(GraphicsLvo.ScrollRasterBF, 0, 0, 0x1234_0000u, rastPort + 1u);
        Assert.Equal(0x1234_0000u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsScrollRasterOnePixelHorizontalUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D3_0000;
        const uint bitmap = 0x00D4_0000;
        const uint plane = 0x00D5_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            GraphicsLvo vector,
            short deltaX,
            byte backgroundPen,
            uint initialD0,
            ushort xMax = 7,
            uint rp = rastPort)
        {
            var physicalRastPort = rp & 0x00FF_FFFFu;
            bus.WriteByte(
                physicalRastPort + (uint)GraphicsLayouts.RastPortBgPen,
                backgroundPen,
                0);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0 | unchecked((ushort)deltaX);
            cpu.State.D[1] = 0;
            cpu.State.D[2] = 0;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = xMax;
            cpu.State.D[5] = 0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 512; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native ScrollRaster one-pixel body did not return.");
        }

        bus.WriteByte(plane, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x5A, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x62, bus.ReadByte(plane));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The full standard-planar RastPort remains valid when its final byte
        // is the logical address limit; execution reaches this storage via the
        // AccurateM68000 24-bit alias.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        bus.WriteByte(plane, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x5A, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xBEEF_0000u, rp: topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x62, bus.ReadByte(plane));
        Assert.Equal((byte)15, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        bus.WriteByte(plane, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        Execute(
            GraphicsLvo.ScrollRaster,
            1,
            0,
            0x1122_0000u,
            15,
            topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x62, bus.ReadByte(plane));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)15, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(plane, 0xB1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xD8, bus.ReadByte(plane));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(plane, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x1122_0000u, 15);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x62, bus.ReadByte(plane));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 1u));

        bus.WriteByte(plane, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x3344_0000u, 15);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xD8, bus.ReadByte(plane));
        Assert.Equal((byte)0x9E, bus.ReadByte(plane + 1u));

        bus.WriteByte(plane, 0xA5, 0);
        Execute(GraphicsLvo.ScrollRaster, 2, 0, 0xFACE_0000u);
        Assert.Equal(0xFACE_0002u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));

        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0001u, cpu.State.D[0]);
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));

        // The complete 32-pixel byte-span uses the same full RastPort
        // envelope at the 24-bit address limit.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(
            GraphicsLvo.ScrollRaster,
            1,
            0,
            0x1020_0000u,
            31,
            topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x62, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xB5, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The generic native byte-span arm extends the same exact one-row
        // contract to complete 32- and 64-pixel rows.  Each case is kept
        // byte-aligned so overlap is resolved entirely in the relocatable
        // 68000 body; richer rectangles continue through the portable owner.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0); // BMF_STANDARD
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x1020_0000u, 31);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x62, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xB5, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 3u));

        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x3040_0000u, 31);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xD8, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x9E, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x2D, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x52, bus.ReadByte(plane + 3u));

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 8);
        var wideSource = new byte[] { 0x81, 0x24, 0x5A, 0xA5, 0xF0, 0x0F, 0x33, 0xC6 };
        for (var index = 0; index < wideSource.Length; index++)
            bus.WriteByte(plane + (uint)index, wideSource[index], 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x5060_0000u, 63);
        Assert.Equal(0u, cpu.State.D[0]);
        var positiveWide = new byte[] { 0x02, 0x48, 0xB5, 0x4B, 0xE0, 0x1E, 0x67, 0x8C };
        for (var index = 0; index < positiveWide.Length; index++)
            Assert.Equal(positiveWide[index], bus.ReadByte(plane + (uint)index));

        for (var index = 0; index < wideSource.Length; index++)
            bus.WriteByte(plane + (uint)index, wideSource[index], 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x7080_0000u, 63);
        Assert.Equal(0u, cpu.State.D[0]);
        var negativeWide = new byte[] { 0xC0, 0x92, 0x2D, 0x52, 0xF8, 0x07, 0x99, 0xE3 };
        for (var index = 0; index < negativeWide.Length; index++)
            Assert.Equal(negativeWide[index], bus.ReadByte(plane + (uint)index));
    }

    [Fact]
    public void NativeGraphicsScrollRasterVerticalOneRowUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D3_0000;
        const uint bitmap = 0x00D4_0000;
        const uint plane = 0x00D5_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[16]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            GraphicsLvo vector,
            short deltaY,
            byte backgroundPen,
            uint initialD0,
            ushort xMax = 7,
            uint rp = rastPort)
        {
            var physicalRastPort = rp & 0x00FF_FFFFu;
            bus.WriteByte(
                physicalRastPort + (uint)GraphicsLayouts.RastPortBgPen,
                backgroundPen,
                0);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0;
            cpu.State.D[1] = unchecked((ushort)deltaY);
            cpu.State.D[2] = 0;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = xMax;
            cpu.State.D[5] = 1;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 768; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native vertical ScrollRaster body did not return.");
        }

        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A complete exact-end RastPort enters the distinct vertical body via
        // AccurateM68000's 24-bit alias before its two-row copy/fill stores.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xBEEF_0000u, rp: topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)15, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        bus.WriteByte(plane + 0u, 0x81, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(
            GraphicsLvo.ScrollRaster,
            1,
            0,
            0x1020_0000u,
            15,
            topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0); // BMF_STANDARD
        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0x3C, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The wider vertical arms reuse the same exact two-row contract for
        // 16-, 32-, and 64-pixel rows.  The destination row is copied before
        // its vacated counterpart is filled, and the BMF_STANDARD form is
        // admitted without changing the portable/provider ownership rules.
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        var sixteenSource = new byte[] { 0x81, 0x24, 0x5A, 0xA5 };
        for (var index = 0; index < sixteenSource.Length; index++)
            bus.WriteByte(plane + (uint)index, sixteenSource[index], 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x1020_0000u, 15);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 3u));

        bus.WriteByte(plane + 0u, 0x81, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x5A, 0);
        bus.WriteByte(plane + 3u, 0xA5, 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x3040_0000u, 15);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 3u));

        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        var thirtyTwoSource = new byte[] { 0x81, 0x24, 0x5A, 0xA5, 0xF0, 0x0F, 0x33, 0xC6 };
        for (var index = 0; index < thirtyTwoSource.Length; index++)
            bus.WriteByte(plane + (uint)index, thirtyTwoSource[index], 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x5060_0000u, 31);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 4; index++)
            Assert.Equal((byte)0, bus.ReadByte(plane + (uint)index));
        for (var index = 0; index < 4; index++)
            Assert.Equal(thirtyTwoSource[index], bus.ReadByte(plane + (uint)(index + 4)));

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 8);
        var sixtyFourSource = new byte[]
        {
            0x81, 0x24, 0x5A, 0xA5, 0xF0, 0x0F, 0x33, 0xC6,
            0x11, 0x22, 0x44, 0x88, 0x7E, 0xE7, 0x18, 0x81
        };
        for (var index = 0; index < sixtyFourSource.Length; index++)
            bus.WriteByte(plane + (uint)index, sixtyFourSource[index], 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x7080_0000u, 63);
        Assert.Equal(0u, cpu.State.D[0]);
        for (var index = 0; index < 8; index++)
            Assert.Equal(sixtyFourSource[index + 8], bus.ReadByte(plane + (uint)index));
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + (uint)(index + 8)));

        bus.WriteByte(plane + 0u, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x34, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane + 3u, 0x78, 0);
        Execute(GraphicsLvo.ScrollRaster, 2, 0, 0xFACE_0000u);
        Assert.Equal(0xFACE_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x34, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 3u));
    }

    [Fact]
    public void NativeGraphicsScrollRasterDiagonalOnePixelUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D6_0000;
        const uint bitmap = 0x00D7_0000;
        const uint plane = 0x00D8_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0); // BMF_STANDARD
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Seed()
        {
            bus.WriteByte(plane + 0u, 0xB1, 0);
            bus.WriteByte(plane + 1u, 0x3C, 0);
            bus.WriteByte(plane + 2u, 0x5A, 0);
            bus.WriteByte(plane + 3u, 0xA5, 0);
        }

        void Execute(
            GraphicsLvo vector,
            short deltaX,
            short deltaY,
            byte backgroundPen,
            uint initialD0,
            uint rp = rastPort)
        {
            var physicalRastPort = rp & 0x00FF_FFFFu;
            bus.WriteByte(
                physicalRastPort + (uint)GraphicsLayouts.RastPortBgPen,
                backgroundPen,
                0);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0 | unchecked((ushort)deltaX);
            cpu.State.D[1] = unchecked((ushort)deltaY);
            cpu.State.D[2] = 0;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = 7;
            cpu.State.D[5] = 1;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native diagonal ScrollRaster body did not return.");
        }

        Seed();
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x62, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A complete RastPort at the logical address limit follows the same
        // bounded diagonal body through the AccurateM68000 physical alias.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 1, 0, 0xBEEF_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x62, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xD8, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, -1, 0, 0x1020_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xB4, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, -1, 1, 0x3040_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xAD, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));

        Seed();
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 7, 0);
        Execute(GraphicsLvo.ScrollRaster, 2, 1, 0, 0xFACE_0000u);
        Assert.Equal(0xFACE_0002u, cpu.State.D[0]);
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeGraphicsScrollRasterClippedOnePixelUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D9_0000;
        const uint bitmap = 0x00DA_0000;
        const uint plane = 0x00DB_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[12]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0); // BMF_STANDARD
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Seed(uint rp = rastPort)
        {
            bus.WriteByte(plane + 0u, 0xB1, 0);
            bus.WriteByte(plane + 1u, 0xA5, 0);
            bus.WriteByte(
                (rp & 0x00FF_FFFFu) + (uint)GraphicsLayouts.RastPortLinePatternCount,
                3,
                0);
        }

        void Execute(
            GraphicsLvo vector,
            short deltaX,
            byte backgroundPen,
            uint initialD0,
            ushort xMin = 1,
            ushort xMax = 6,
            uint rp = rastPort)
        {
            var physicalRastPort = rp & 0x00FF_FFFFu;
            bus.WriteByte(
                physicalRastPort + (uint)GraphicsLayouts.RastPortBgPen,
                backgroundPen,
                0);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0 | unchecked((ushort)deltaX);
            cpu.State.D[1] = 0;
            cpu.State.D[2] = xMin;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = xMax;
            cpu.State.D[5] = 0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 768; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native clipped ScrollRaster body did not return.");
        }

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA3, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A complete public RastPort ending at the 24-bit address boundary
        // must enter the clipped one-pixel arm instead of tail-chaining.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(
            topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        Seed(topRastPort);
        Execute(
            GraphicsLvo.ScrollRaster,
            1,
            0,
            0xBEEF_0000u,
            rp: topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xA3, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal(
            (byte)15,
            bus.ReadByte(topRastPortPhysical +
                (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xDB, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x1020_0000u, 1, 14);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE3, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x4B, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x3040_0000u, 1, 14);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xD8, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xD3, bus.ReadByte(plane + 1u));

        Seed();
        bus.WriteByte(plane + 0u, 0x80, 0);
        bus.WriteByte(plane + 1u, 0x00, 0);
        Execute(GraphicsLvo.ScrollRaster, 1, 1, 0x4050_0000u, 1, 14);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xC0, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));

        Seed();
        bus.WriteByte(plane + 0u, 0x00, 0);
        bus.WriteByte(plane + 1u, 0x01, 0);
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x6070_0000u, 1, 14);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x03, bus.ReadByte(plane + 1u));

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 1, 0xFACE_0000u, 1, 7);
        Assert.Equal(0xFACE_0001u, cpu.State.D[0]);
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)3, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

