            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00DC_0000;
        const uint bitmap = 0x00DD_0000;
        const uint plane = 0x00DE_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0); // BMF_STANDARD
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Seed(uint rp = rastPort)
        {
            bus.WriteByte(plane + 0u, 0xB1, 0);
            bus.WriteByte(plane + 1u, 0x3C, 0);
            bus.WriteByte(plane + 2u, 0x5A, 0);
            bus.WriteByte(plane + 3u, 0xA5, 0);
            bus.WriteByte(
                (rp & 0x00FF_FFFFu) + (uint)GraphicsLayouts.RastPortLinePatternCount,
                3,
                0);
        }

        void Execute(
            GraphicsLvo vector,
            short deltaY,
            byte backgroundPen,
            uint initialD0,
            ushort xMin = 1,
            ushort xMax = 6,
            uint rp = rastPort)
        {
            var physicalRastPort = rp & 0x00FF_FFFFu;
            bus.WriteByte(
                physicalRastPort + (uint)GraphicsLayouts.RastPortBgPen,
                backgroundPen,
                0);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0;
            cpu.State.D[1] = unchecked((ushort)deltaY);
            cpu.State.D[2] = xMin;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = xMax;
            cpu.State.D[5] = 1;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native clipped vertical ScrollRaster body did not return.");
        }

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x30, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xDB, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x7E, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0x1020_0000u, 1, 14);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x31, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x3D, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0x3040_0000u, 1, 14);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xDA, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA4, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x7F, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 3u));

        // A complete public RastPort ending at the 24-bit address boundary
        // must enter the clipped vertical arm instead of tail-chaining. Its
        // final byte is at physical $FFFFFF.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(
            topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        Seed(topRastPort);
        Execute(
            GraphicsLvo.ScrollRaster,
            1,
            0,
            0xBEEF_0000u,
            rp: topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x30, bus.ReadByte(plane + 2u));
        Assert.Equal(
            (byte)15,
            bus.ReadByte(topRastPortPhysical +
                (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed(topRastPort);
        Execute(
            GraphicsLvo.ScrollRaster,
            1,
            0,
            0x1020_0000u,
            xMax: 14,
            rp: topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x31, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x3D, bus.ReadByte(plane + 3u));
        Assert.Equal(
            (byte)15,
            bus.ReadByte(topRastPortPhysical +
                (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xFACE_0000u, 1, 7);
        Assert.Equal(0xFACE_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)3, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeGraphicsScrollRasterClippedThirtyPixelInteriorUsesAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00E0_0000;
        const uint bitmap = 0x00E1_0000;
        const uint plane = 0x00E2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0x08, 0); // BMF_STANDARD
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Seed()
        {
            bus.WriteByte(plane + 0u, 0xB1, 0);
            bus.WriteByte(plane + 1u, 0xA5, 0);
            bus.WriteByte(plane + 2u, 0x3C, 0);
            bus.WriteByte(plane + 3u, 0x62, 0);
            bus.WriteByte(plane + 4u, 0x5A, 0); // outside-row guard
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 3, 0);
        }

        void Execute(GraphicsLvo vector, short deltaX, byte backgroundPen, uint initialD0)
        {
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortBgPen,
                backgroundPen,
                0);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)deltaX);
            cpu.State.D[1] = 0;
            cpu.State.D[2] = 1;
            cpu.State.D[3] = 0;
            cpu.State.D[4] = 30;
            cpu.State.D[5] = 0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native thirty-pixel clipped ScrollRaster body did not return.");
        }

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE3, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC4, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xD8, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xD2, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x9E, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x32, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 4u));

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE3, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC4, bus.ReadByte(plane + 3u));

        // The exact thirty-pixel arm is transactional: a different width
        // remains available to the portable/provider owner.
        bus.WriteByte(plane + 0u, 0xB1, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        bus.WriteByte(plane + 3u, 0x62, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 7, 0);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeBase + (uint)VectorOffset(GraphicsLvo.ScrollRaster), stack + 0x80u);
        cpu.State.A[1] = rastPort;
        cpu.State.D[0] = 0x1234_0001u;
        cpu.State.D[1] = 0;
        cpu.State.D[2] = 1;
        cpu.State.D[3] = 0;
        cpu.State.D[4] = 31;
        cpu.ExecuteInstruction();
        for (var index = 0; index < 512 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();
        Assert.Equal(0x1234_0001u, cpu.State.D[0]);
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x62, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

