                }
            }

            throw new InvalidOperationException("Native sixty-two-pixel clipped ScrollRaster body did not return.");
        }

        Seed();
        Execute(GraphicsLvo.ScrollRaster, 1, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE3, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC4, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0xB5, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x8F, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0xD0, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x33, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0xD4, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        Seed();
        Execute(GraphicsLvo.ScrollRasterBF, -1, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xD8, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xD2, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x9E, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x31, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x2D, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x63, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0xF4, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x0F, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0xD4, bus.ReadByte(plane + 8u));

        // The sixty-two-pixel arm is exact; a neighboring width remains a
        // transactional fallback with bytes, D0, and pattern state intact.
        Seed();
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeBase + (uint)VectorOffset(GraphicsLvo.ScrollRaster), stack + 0x80u);
        cpu.State.A[1] = rastPort;
        cpu.State.D[0] = 0x1234_0001u;
        cpu.State.D[1] = 0;
        cpu.State.D[2] = 1;
        cpu.State.D[3] = 0;
        cpu.State.D[4] = 61;
        cpu.State.D[5] = 0;
        cpu.ExecuteInstruction();
        for (var index = 0; index < 512 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();
        Assert.Equal(0x1234_0001u, cpu.State.D[0]);
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 0u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x62, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0xC7, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0xE8, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x19, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)3, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeGraphicsMrgCopEmptyViewReturnsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint view = 0x00D1_0000;
        const uint hiddenViewPort = 0x00D2_0000;
        const uint secondHiddenViewPort = 0x00D3_0000;
        const uint thirdHiddenViewPort = 0x00D4_0000;
        const uint fourthHiddenViewPort = 0x00D5_0000;
        const uint fifthHiddenViewPort = 0x00D6_0000;
        const uint sixthHiddenViewPort = 0x00D7_0000;
        const uint seventhHiddenViewPort = 0x00D8_0000;
        const uint eighthHiddenViewPort = 0x00D9_0000;
        const uint ninthHiddenViewPort = 0x00DA_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(
            hiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            secondHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            thirdHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            fourthHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            fifthHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            sixthHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            seventhHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            eighthHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(
            ninthHiddenViewPort,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint viewPort, uint initialD0, uint viewAddress = view)
        {
            bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
                stack + 0x80u);
            cpu.State.A[1] = viewAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                $"Native MrgCop empty-View body did not return (PC={cpu.State.ProgramCounter:X8}, offset={cpu.State.ProgramCounter - codeBase:X}, entry={entryOffsets[GraphicsLvo.MrgCop]:X}, SP={cpu.State.A[7]:X8}).");
        }

        Execute(0, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));

        Execute(0x00D2_0000u, 0xD00D_BEEFu);
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
        Assert.Equal(0x00D2_0000u, bus.ReadLong(view + (uint)GraphicsLayouts.ViewViewPort));

        Execute(0, 0xFACE_1234u, view + 1u);
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);
        Execute(0, 0xABCD_5678u, 0xFFFF_FFF0u);
        Assert.Equal(0xABCD_5678u, cpu.State.D[0]);

        bus.WriteWord(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        Execute(hiddenViewPort, 0x1357_9BDFu);
        Assert.Equal(2u, cpu.State.D[0]); // MCOP_NOP

        bus.WriteLong(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            secondHiddenViewPort);
        bus.WriteWord(
            secondHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            secondHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        Execute(hiddenViewPort, 0x1357_2468u);
        Assert.Equal(2u, cpu.State.D[0]); // MCOP_NOP for two hidden nodes

        bus.WriteLong(
            secondHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            thirdHiddenViewPort);
        bus.WriteWord(
            thirdHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            thirdHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        Execute(hiddenViewPort, 0x1357_1357u);
        Assert.Equal(2u, cpu.State.D[0]); // MCOP_NOP for three hidden nodes

        bus.WriteLong(
            thirdHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            fourthHiddenViewPort);
        bus.WriteWord(
            fourthHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            fourthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            fifthHiddenViewPort);
        bus.WriteWord(
            fifthHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            fifthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        bus.WriteWord(
            sixthHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            sixthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        Execute(hiddenViewPort, 0x1357_0246u);
        Assert.Equal(2u, cpu.State.D[0]); // MCOP_NOP for five hidden nodes

        bus.WriteLong(
            fifthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            sixthHiddenViewPort);
        Execute(hiddenViewPort, 0x1357_0247u);
        Assert.Equal(2u, cpu.State.D[0]); // MCOP_NOP for six hidden nodes

        bus.WriteLong(
            sixthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            seventhHiddenViewPort);
        bus.WriteWord(
            seventhHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            seventhHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            eighthHiddenViewPort);
        bus.WriteWord(
            eighthHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            eighthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            ninthHiddenViewPort);
        bus.WriteWord(
            ninthHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            ninthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        Execute(hiddenViewPort, 0x1357_0248u);
        Assert.Equal(2u, cpu.State.D[0]); // MCOP_NOP for nine hidden nodes

        bus.WriteLong(
            ninthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            ninthHiddenViewPort);
        Execute(hiddenViewPort, 0x1357_0249u);
        Assert.Equal(0x1357_0249u, cpu.State.D[0]);
        bus.WriteLong(
            ninthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        bus.WriteLong(
            eighthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);

        bus.WriteLong(
            sixthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            sixthHiddenViewPort);
        Execute(hiddenViewPort, 0x1357_0123u);
        Assert.Equal(0x1357_0123u, cpu.State.D[0]);

        bus.WriteLong(
            sixthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        bus.WriteLong(
            fourthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            fourthHiddenViewPort);
        Execute(hiddenViewPort, 0x1357_0124u);
        Assert.Equal(0x1357_0124u, cpu.State.D[0]);

        bus.WriteLong(
            fifthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        bus.WriteLong(
            fourthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        bus.WriteLong(
            fourthHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);
        bus.WriteLong(
            thirdHiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0);

        bus.WriteWord(
            secondHiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        Execute(hiddenViewPort, 0x2468_ACEDu);
        Assert.Equal(0x2468_ACEDu, cpu.State.D[0]);

        bus.WriteWord(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        Execute(hiddenViewPort, 0x2468_ACEDu);
        Assert.Equal(0x2468_ACEDu, cpu.State.D[0]);

        bus.WriteWord(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ViewPortHidden);
        bus.WriteLong(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            hiddenViewPort);
        Execute(hiddenViewPort, 0xDEAD_BEEFu);
        Assert.Equal(0xDEAD_BEEFu, cpu.State.D[0]);

        Execute(hiddenViewPort + 1u, 0xA5A5_5A5Au);
        Assert.Equal(0xA5A5_5A5Au, cpu.State.D[0]);
        // vp_Modes is a WORD at +0x20; FFFF:FFDF would wrap its second byte.
        Execute(0xFFFF_FFDFu, 0x5A5A_5A5Au);
        Assert.Equal(0x5A5A_5A5Au, cpu.State.D[0]);
        Execute(0xFFFF_FFE0u, 0x5A5A_A5A5u);
        Assert.Equal(0x5A5A_A5A5u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsMrgCopAdmitsVisiblePreallocatedSingletonOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint view = 0x00D8_0000;
        const uint viewPort = 0x00D8_0100;
        const uint rasInfo = 0x00D8_0200;
        const uint lofCpr = 0x00D8_0300;
        const uint shfCpr = 0x00D8_0400;
        const uint copList = 0x00D8_0500;
        const uint rawCopper = 0x00D8_0600;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        bus.MapWritableMemory(view, Enumerable.Repeat((byte)0xA5, GraphicsLayouts.ViewSize).ToArray());
        bus.MapWritableMemory(viewPort, Enumerable.Repeat((byte)0x5A, GraphicsLayouts.ViewPortSize).ToArray());
        bus.MapWritableMemory(rasInfo, Enumerable.Repeat((byte)0x6A, GraphicsLayouts.RasInfoSize).ToArray());
        bus.MapWritableMemory(lofCpr, Enumerable.Repeat((byte)0x7A, GraphicsLayouts.CprListSize).ToArray());
        bus.MapWritableMemory(shfCpr, Enumerable.Repeat((byte)0x8A, GraphicsLayouts.CprListSize).ToArray());
        bus.MapWritableMemory(copList, Enumerable.Repeat((byte)0x9A, GraphicsLayouts.CopListSize).ToArray());
        bus.MapWritableMemory(rawCopper, Enumerable.Repeat((byte)0xAA, 0x40).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, rawCopper);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, rawCopper);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);
        bus.WriteWord(lofCpr + (uint)GraphicsLayouts.CprListMaxCount, 12);
        bus.WriteWord(shfCpr + (uint)GraphicsLayouts.CprListMaxCount, 12);
        bus.WriteLong(lofCpr + (uint)GraphicsLayouts.CprListStart, rawCopper);
        bus.WriteLong(shfCpr + (uint)GraphicsLayouts.CprListStart, rawCopper);

        var beforeView = ReadBusBytes(bus, view, GraphicsLayouts.ViewSize);
        var beforeViewPort = ReadBusBytes(bus, viewPort, GraphicsLayouts.ViewPortSize);
        var beforeRasInfo = ReadBusBytes(bus, rasInfo, GraphicsLayouts.RasInfoSize);
        var beforeLof = ReadBusBytes(bus, lofCpr, GraphicsLayouts.CprListSize);
        var beforeShf = ReadBusBytes(bus, shfCpr, GraphicsLayouts.CprListSize);
        var beforeCopList = ReadBusBytes(bus, copList, GraphicsLayouts.CopListSize);
        var beforeRaw = ReadBusBytes(bus, rawCopper, 0x40);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
            stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xCAFE_0000u;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 4096 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]); // MCOP_OK
        Assert.Equal(beforeView, ReadBusBytes(bus, view, GraphicsLayouts.ViewSize));
        Assert.Equal(beforeViewPort, ReadBusBytes(bus, viewPort, GraphicsLayouts.ViewPortSize));
        Assert.Equal(beforeRasInfo, ReadBusBytes(bus, rasInfo, GraphicsLayouts.RasInfoSize));
        Assert.Equal(beforeLof, ReadBusBytes(bus, lofCpr, GraphicsLayouts.CprListSize));
        Assert.Equal(beforeShf, ReadBusBytes(bus, shfCpr, GraphicsLayouts.CprListSize));
        Assert.Equal(beforeCopList, ReadBusBytes(bus, copList, GraphicsLayouts.CopListSize));
        Assert.Equal(beforeRaw, ReadBusBytes(bus, rawCopper, 0x40));

        // The singleton body reads vp_RasInfo at +0x24 after the mode and
        // next fields.  Reject a high aligned ViewPort before that field can
        // wrap into unrelated low memory.
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, 0xFFFF_FFDAu);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
            stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0x89AB_CDEFu;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 128 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0x89AB_CDEFu, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsMrgCopRejectsOverlappingViewAndViewPortBeforeAdmissionOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint view = 0x00D8_0000;
        const uint viewPort = view + 0x10u;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        // The viewport begins inside the View envelope.  Keep the entire
        // malformed span mapped so the admission guard, rather than a bus
        // fault, decides the result before any resource reads or writes.
        bus.MapWritableMemory(view, Enumerable.Repeat((byte)0xA5, 0x100).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        bus.WriteLong(stack + 0x80u, returnAddress);

        var before = ReadBusBytes(bus, view, 0x100);
        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
            stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0x1357_9BDFu;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 256 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);
        Assert.Equal(before, ReadBusBytes(bus, view, 0x100));
    }

    [Fact]
    public void NativeGraphicsMrgCopRejectsRasInfoAliasingViewBeforeCopperReadsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint view = 0x00D8_1000;
        const uint viewPort = view + 0x100u;
        const uint stack = 0x00C0_1000;
        const uint returnAddress = 0x00F0_1000;

        // Keep the valid View/ViewPort pair and the malformed RasInfo alias
        // in one mapped island.  MrgCop must decline before it can inspect a
        // CopList or publish any copper state.
        bus.MapWritableMemory(view, Enumerable.Repeat((byte)0x5A, 0x200).ToArray());
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, view + 4u);
        bus.WriteLong(stack + 0x80u, returnAddress);

        var before = ReadBusBytes(bus, view, 0x200);
        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
            stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0x2468_ACEDu;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 256 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0x2468_ACEDu, cpu.State.D[0]);
        Assert.Equal(before, ReadBusBytes(bus, view, 0x200));

        // Repeat with the RasInfo beginning inside the selected ViewPort.
        // Both sides of the root/ViewPort separation must be rejected before
        // the native body can inspect a CopList.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, viewPort + 4u);
        before = ReadBusBytes(bus, view, 0x200);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
            stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0x9753_1BDFu;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 256 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0x9753_1BDFu, cpu.State.D[0]);
        Assert.Equal(before, ReadBusBytes(bus, view, 0x200));
    }

    [Fact]
    public void NativeGraphicsMrgCopLeavesLinkedVisibleViewportToMergeOwnerOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0084_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint view = 0x00D9_0000;
        const uint viewPort = 0x00D9_0100;
        const uint secondViewPort = 0x00D9_0200;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(secondViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, secondViewPort);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        var beforeView = ReadBusBytes(bus, view, GraphicsLayouts.ViewSize);
        var beforeViewPort = ReadBusBytes(bus, viewPort, GraphicsLayouts.ViewPortSize);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.MrgCop),
            stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xBEEF_0000u;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 4096 && cpu.State.ProgramCounter != returnAddress; index++)
            cpu.ExecuteInstruction();

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(beforeView, ReadBusBytes(bus, view, GraphicsLayouts.ViewSize));
        Assert.Equal(beforeViewPort, ReadBusBytes(bus, viewPort, GraphicsLayouts.ViewPortSize));
    }

    [Fact]
    public void NativeGraphicsMrgCopAdmitsTwoVisiblePreMergedViewPortsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var mrgCopMultiViewportEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint view = 0x00DA_0000;
        const uint firstViewPort = 0x00DA_0100;
        const uint secondViewPort = 0x00DA_0200;
        const uint firstRasInfo = 0x00DA_0300;
        const uint secondRasInfo = 0x00DA_0400;
        const uint firstCopList = 0x00DA_0500;
        const uint secondCopList = 0x00DA_0600;
        const uint lofCpr = 0x00DA_0700;
        const uint shfCpr = 0x00DA_0800;
        const uint rawCopper = 0x00DA_0900;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(firstViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(secondViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(firstRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(secondRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(firstCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(secondCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(lofCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(shfCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(rawCopper, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, firstViewPort);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);
        bus.WriteWord(firstViewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteWord(secondViewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortNext, secondViewPort);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortRasInfo, secondRasInfo);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns, firstCopList);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns, secondCopList);
        bus.WriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);

        foreach (var (copList, viewPort) in new[]
        {
            (firstCopList, firstViewPort),
            (secondCopList, secondViewPort)
        })
        {
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListNext, 0);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 12);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, 12);
        }

        foreach (var cprList in new[] { lofCpr, shfCpr })
        {
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, rawCopper);
            bus.WriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, 12);
        }

        var beforeView = ReadBusBytes(bus, view, GraphicsLayouts.ViewSize);
        var beforeFirstViewPort = ReadBusBytes(bus, firstViewPort, GraphicsLayouts.ViewPortSize);
        var beforeSecondViewPort = ReadBusBytes(bus, secondViewPort, GraphicsLayouts.ViewPortSize);
        var beforeRaw = ReadBusBytes(bus, rawCopper, 0x40);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xCAFE_0000u;

        var returned = false;
        for (var index = 0; index < 8192; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(beforeView, ReadBusBytes(bus, view, GraphicsLayouts.ViewSize));
        Assert.Equal(beforeFirstViewPort, ReadBusBytes(bus, firstViewPort, GraphicsLayouts.ViewPortSize));
        Assert.Equal(beforeSecondViewPort, ReadBusBytes(bus, secondViewPort, GraphicsLayouts.ViewPortSize));
        Assert.Equal(beforeRaw, ReadBusBytes(bus, rawCopper, 0x40));

        // vp_RasInfo is read at +0x24.  This aligned pointer passes the old
        // modes-only bound but wraps that later field into low memory, so the
        // native arm must decline before dereferencing it.
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, 0xFFFF_FFDAu);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0x89AB_CDEFu;
        returned = false;
        for (var index = 0; index < 128; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0x89AB_CDEFu, cpu.State.D[0]);
    }

