    [Fact]
    public void NativeGraphicsMrgCopMergesTwoVisibleCanonicalStreamsInPlaceOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out _,
            out var mrgCopMultiViewportEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint view = 0x00DC_0000;
        const uint firstViewPort = 0x00DC_0100;
        const uint secondViewPort = 0x00DC_0200;
        const uint firstRasInfo = 0x00DC_0300;
        const uint secondRasInfo = 0x00DC_0400;
        const uint firstCopList = 0x00DC_0500;
        const uint secondCopList = 0x00DC_0600;
        const uint lofCpr = 0x00DC_0700;
        const uint shfCpr = 0x00DC_0800;
        const uint firstRaw = 0x00DC_0900;
        const uint secondRaw = 0x00DC_0A00;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(firstViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(secondViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(firstRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(secondRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(firstCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(secondCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(lofCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(shfCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(firstRaw, new byte[0x80]);
        bus.MapWritableMemory(secondRaw, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, firstViewPort);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortNext, secondViewPort);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        bus.WriteWord(firstViewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteWord(secondViewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortRasInfo, secondRasInfo);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns, firstCopList);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns, secondCopList);

        foreach (var (copList, viewPort, raw, maxCount) in new[]
        {
            (firstCopList, firstViewPort, firstRaw, (ushort)24),
            (secondCopList, secondViewPort, secondRaw, (ushort)12)
        })
        {
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, raw);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, raw);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, raw);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 12);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, maxCount);
        }
        foreach (var cprList in new[] { lofCpr, shfCpr })
        {
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, firstRaw);
            bus.WriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, 24);
        }

        var firstBody = new ushort[22];
        var secondBody = new ushort[22];
        for (var index = 0; index < 22; index++)
        {
            firstBody[index] = (ushort)(0x1000 + index);
            secondBody[index] = (ushort)(0x2000 + index);
            if (index == 1)
            {
                firstBody[index] = 0x2C81;
                secondBody[index] = 0x2D41;
            }
            bus.WriteWord(firstRaw + (uint)(index * 2), firstBody[index]);
            bus.WriteWord(secondRaw + (uint)(index * 2), secondBody[index]);
        }
        bus.WriteWord(firstRaw + 44u, GraphicsLayouts.CopperEndWait);
        bus.WriteWord(firstRaw + 46u, GraphicsLayouts.CopperEndMask);
        bus.WriteWord(secondRaw + 44u, GraphicsLayouts.CopperEndWait);
        bus.WriteWord(secondRaw + 46u, GraphicsLayouts.CopperEndMask);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xCAFE_0000u;

        var returned = false;
        for (var index = 0; index < 12000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)24, bus.ReadWord(
            firstCopList + (uint)GraphicsLayouts.CopListCount));
        for (var index = 0; index < 22; index++)
        {
            Assert.Equal(firstBody[index], bus.ReadWord(firstRaw + (uint)(index * 2)));
            Assert.Equal(secondBody[index], bus.ReadWord(firstRaw + (uint)(48 + index * 2)));
        }
        Assert.Equal((ushort)0x2D00, bus.ReadWord(firstRaw + 44u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(firstRaw + 46u));
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(firstRaw + 92u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(firstRaw + 94u));
        for (var index = 0; index < 22; index++)
            Assert.Equal(secondBody[index], bus.ReadWord(secondRaw + (uint)(index * 2)));
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(secondRaw + 44u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(secondRaw + 46u));
    }

