        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, firstViewPort);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortNext, secondViewPort);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, thirdViewPort);
        bus.WriteLong(thirdViewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        foreach (var viewPort in new[] { firstViewPort, secondViewPort, thirdViewPort })
        {
            bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                viewPort == firstViewPort ? firstRasInfo :
                viewPort == secondViewPort ? secondRasInfo : thirdRasInfo);
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
                viewPort == firstViewPort ? firstCopList :
                viewPort == secondViewPort ? secondCopList : thirdCopList);
        }

        foreach (var (copList, viewPort, raw, maxCount) in new[]
        {
            (firstCopList, firstViewPort, firstRaw, (ushort)36),
            (secondCopList, secondViewPort, secondRaw, (ushort)12),
            (thirdCopList, thirdViewPort, thirdRaw, (ushort)12)
        })
        {
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, raw);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, raw);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, raw);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 12);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, maxCount);
        }
        foreach (var cprList in new[] { lofCpr, shfCpr })
        {
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, firstRaw);
            bus.WriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, 36);
        }

        var firstBody = new ushort[22];
        var secondBody = new ushort[22];
        var thirdBody = new ushort[22];
        for (var index = 0; index < 22; index++)
        {
            firstBody[index] = (ushort)(0x1100 + index);
            secondBody[index] = (ushort)(0x2200 + index);
            thirdBody[index] = (ushort)(0x3300 + index);
            if (index == 1)
            {
                firstBody[index] = 0x2C81;
                secondBody[index] = 0x2D41;
                thirdBody[index] = 0x2E01;
            }
            bus.WriteWord(firstRaw + (uint)(index * 2), firstBody[index]);
            bus.WriteWord(secondRaw + (uint)(index * 2), secondBody[index]);
            bus.WriteWord(thirdRaw + (uint)(index * 2), thirdBody[index]);
        }
        foreach (var raw in new[] { firstRaw, secondRaw, thirdRaw })
        {
            bus.WriteWord(raw + 44u, GraphicsLayouts.CopperEndWait);
            bus.WriteWord(raw + 46u, GraphicsLayouts.CopperEndMask);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xCAFE_0000u;

        var returned = false;
        for (var index = 0; index < 20000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)36, bus.ReadWord(
            firstCopList + (uint)GraphicsLayouts.CopListCount));
        for (var index = 0; index < 22; index++)
        {
            Assert.Equal(firstBody[index], bus.ReadWord(firstRaw + (uint)(index * 2)));
            Assert.Equal(secondBody[index], bus.ReadWord(firstRaw + (uint)(48 + index * 2)));
            Assert.Equal(thirdBody[index], bus.ReadWord(firstRaw + (uint)(96 + index * 2)));
        }
        Assert.Equal((ushort)0x2D00, bus.ReadWord(firstRaw + 44u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(firstRaw + 46u));
        Assert.Equal((ushort)0x2E00, bus.ReadWord(firstRaw + 92u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(firstRaw + 94u));
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(firstRaw + 140u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(firstRaw + 142u));
        for (var index = 0; index < 22; index++)
        {
            Assert.Equal(secondBody[index], bus.ReadWord(secondRaw + (uint)(index * 2)));
            Assert.Equal(thirdBody[index], bus.ReadWord(thirdRaw + (uint)(index * 2)));
        }

        // A later capacity decline must not touch the already-published
        // destination stream or consume the caller's result register.
        var mergedBytes = ReadBusBytes(bus, firstRaw, 0x100);
        bus.WriteWord(firstCopList + (uint)GraphicsLayouts.CopListCount, 12);
        bus.WriteWord(firstCopList + (uint)GraphicsLayouts.CopListMaxCount, 12);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xABCD_0000u;
        returned = false;
        for (var index = 0; index < 20000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0xABCD_0000u, cpu.State.D[0]);
        Assert.Equal(mergedBytes, ReadBusBytes(bus, firstRaw, 0x100));

        // Re-publish the actual three-viewport merge output and prove that
        // FreeVPortCopLists accepts this owned shape only after MrgCop has
        // completed it.  The release must leave all descriptor/raw storage
        // alone while clearing the public links as one transaction.
        bus.WriteWord(firstCopList + (uint)GraphicsLayouts.CopListCount, 36);
        bus.WriteWord(firstCopList + (uint)GraphicsLayouts.CopListMaxCount, 36);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
            stack + 0x80u);
        cpu.State.A[0] = firstViewPort;
        cpu.State.D[0] = 0x5A5A_0000u;
        returned = false;
        for (var index = 0; index < 20000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var viewPort in new[] { firstViewPort, secondViewPort, thirdViewPort })
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(mergedBytes, ReadBusBytes(bus, firstRaw, 0x100));

        // A late preflight failure cannot retire the earlier ViewPorts.  The
        // third descriptor's split public start pointer leaves all three
        // DspIns links and the caller's void-vector register unchanged.
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns, firstCopList);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns, secondCopList);
        bus.WriteLong(thirdViewPort + (uint)GraphicsLayouts.ViewPortDspIns, thirdCopList);
        bus.WriteLong(thirdCopList + (uint)GraphicsLayouts.CopListCopLStart, thirdRaw + 2u);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
            stack + 0x80u);
        cpu.State.A[0] = firstViewPort;
        cpu.State.D[0] = 0xBEEF_0000u;
        returned = false;
        for (var index = 0; index < 20000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }
        Assert.True(returned);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(firstCopList, bus.ReadLong(firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(secondCopList, bus.ReadLong(secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(thirdCopList, bus.ReadLong(thirdViewPort + (uint)GraphicsLayouts.ViewPortDspIns));
    }

    [Fact]
    public void NativeGraphicsMrgCopMergesFourVisibleCanonicalStreamsInPlaceOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets, out _, out _, out _, out _, out _, out _, out _, out _, out _, out _, out _,
            out var mrgCopMultiViewportEntryOffset);
        const uint codeAddress = 0x00B0_0000;
        const uint view = 0x00DE_0000;
        var viewPorts = new[] { 0x00DE_0100u, 0x00DE_0200u, 0x00DE_0300u, 0x00DE_0400u };
        var rasInfos = new[] { 0x00DE_0500u, 0x00DE_0600u, 0x00DE_0700u, 0x00DE_0800u };
        var copLists = new[] { 0x00DE_0900u, 0x00DE_0A00u, 0x00DE_0B00u, 0x00DE_0C00u };
        const uint lofCpr = 0x00DE_0D00;
        const uint shfCpr = 0x00DE_0E00;
        var raws = new[] { 0x00DE_1000u, 0x00DE_1200u, 0x00DE_1400u, 0x00DE_1600u };
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        foreach (var address in viewPorts)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.ViewPortSize]);
        foreach (var address in rasInfos)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.RasInfoSize]);
        foreach (var address in copLists)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(lofCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(shfCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(raws[0], new byte[0x100]);
        foreach (var address in raws.Skip(1))
            bus.MapWritableMemory(address, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPorts[0]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);
        for (var index = 0; index < viewPorts.Length; index++)
        {
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortNext,
                index + 1 < viewPorts.Length ? viewPorts[index + 1] : 0u);
            bus.WriteWord(viewPorts[index] + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfos[index]);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortDspIns, copLists[index]);
            bus.WriteLong(rasInfos[index] + (uint)GraphicsLayouts.RasInfoNext, 0);
        }
        for (var index = 0; index < copLists.Length; index++)
        {
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListViewPort, viewPorts[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopPtr, raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopLStart, raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopSStart, raws[index]);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListCount, 12);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListMaxCount, index == 0 ? (ushort)48 : (ushort)12);
        }
        foreach (var cprList in new[] { lofCpr, shfCpr })
        {
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, raws[0]);
            bus.WriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, 48);
        }

        var bodies = new ushort[4][];
        for (var stream = 0; stream < bodies.Length; stream++)
        {
            bodies[stream] = new ushort[22];
            for (var index = 0; index < bodies[stream].Length; index++)
                bodies[stream][index] = (ushort)((stream + 1) * 0x1100 + index);
            bodies[stream][1] = (ushort)(0x2D01 + stream * 0x0100);
            for (var index = 0; index < bodies[stream].Length; index++)
                bus.WriteWord(raws[stream] + (uint)(index * 2), bodies[stream][index]);
            bus.WriteWord(raws[stream] + 44u, GraphicsLayouts.CopperEndWait);
            bus.WriteWord(raws[stream] + 46u, GraphicsLayouts.CopperEndMask);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(M68kBackendKind.AccurateM68000, bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xCAFE_0000u;
        var returned = false;
        for (var index = 0; index < 30000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)48, bus.ReadWord(copLists[0] + (uint)GraphicsLayouts.CopListCount));
        for (var stream = 0; stream < bodies.Length; stream++)
        {
            var destinationOffset = stream * 48;
            for (var index = 0; index < 22; index++)
                Assert.Equal(bodies[stream][index], bus.ReadWord(raws[0] + (uint)(destinationOffset + index * 2)));
            if (stream > 0)
            {
                var waitOffset = destinationOffset - 4;
                Assert.Equal((ushort)(0x2D00 + stream * 0x0100), bus.ReadWord(raws[0] + (uint)waitOffset));
                Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(raws[0] + (uint)(waitOffset + 2)));
            }
        }
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(raws[0] + 188u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(raws[0] + 190u));

        var mergedBytes = ReadBusBytes(bus, raws[0], 0x100);
        bus.WriteWord(copLists[0] + (uint)GraphicsLayouts.CopListCount, 12);
        bus.WriteWord(copLists[0] + (uint)GraphicsLayouts.CopListMaxCount, 12);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset, stack + 0x80u);
        cpu.State.A[1] = view;
        cpu.State.D[0] = 0xABCD_0000u;
        returned = false;
        for (var index = 0; index < 30000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }
        Assert.True(returned);
        Assert.Equal(0xABCD_0000u, cpu.State.D[0]);
        Assert.Equal(mergedBytes, ReadBusBytes(bus, raws[0], 0x100));

        bus.WriteWord(copLists[0] + (uint)GraphicsLayouts.CopListCount, 48);
        bus.WriteWord(copLists[0] + (uint)GraphicsLayouts.CopListMaxCount, 48);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
            stack + 0x80u);
        cpu.State.A[0] = viewPorts[0];
        cpu.State.D[0] = 0x5A5A_0000u;
        returned = false;
        for (var index = 0; index < 30000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }
        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var viewPort in viewPorts)
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(mergedBytes, ReadBusBytes(bus, raws[0], 0x100));
    }

