            codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
            stack + 0x80u);
        cpu.State.A[0] = viewPorts[0];
        cpu.State.A[6] = originalA6;
        cpu.State.D[0] = 0x5A5A_0000u;
        returned = false;
        for (var index = 0; index < 40000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }
        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(originalA6, cpu.State.A[6]);
        foreach (var viewPort in viewPorts)
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(mergedBytes, ReadBusBytes(bus, raws[0], 0x120));
    }

    [Fact]
    public void NativeGraphicsMrgCopAndFreeVPortCopListsRoundTripSevenVisibleCanonicalStreamsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _, out _, out _, out _, out _, out _, out _, out _, out _, out _, out _,
            out var mrgCopMultiViewportEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint view = 0x00DF_0000;
        const uint viewPortsBase = 0x00DF_0100;
        const uint rasInfosBase = 0x00DF_1000;
        const uint copListsBase = 0x00DF_2000;
        const uint rawsBase = 0x00DF_3000;
        const uint lofCpr = 0x00DF_5000;
        const uint shfCpr = 0x00DF_5100;
        const uint stack = 0x00C9_0000;
        const uint returnAddress = 0x00F9_0000;
        const uint originalA6 = 0x00A6_1234;
        const int viewPortCount = 7;
        const ushort mergedCount = 84;
        const uint mergedByteCount = 0x180;

        var viewPorts = new uint[viewPortCount];
        var rasInfos = new uint[viewPortCount];
        var copLists = new uint[viewPortCount];
        var raws = new uint[viewPortCount];
        for (var index = 0; index < viewPortCount; index++)
        {
            viewPorts[index] = viewPortsBase + (uint)(index * 0x100);
            rasInfos[index] = rasInfosBase + (uint)(index * 0x100);
            copLists[index] = copListsBase + (uint)(index * 0x100);
            raws[index] = rawsBase + (uint)(index * 0x200);
        }

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        foreach (var address in viewPorts)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.ViewPortSize]);
        foreach (var address in rasInfos)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.RasInfoSize]);
        foreach (var address in copLists)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(lofCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(shfCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(raws[0], new byte[mergedByteCount]);
        foreach (var address in raws.Skip(1))
            bus.MapWritableMemory(address, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPorts[0]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);

        for (var index = 0; index < viewPortCount; index++)
        {
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortNext,
                index + 1 < viewPortCount ? viewPorts[index + 1] : 0u);
            bus.WriteWord(viewPorts[index] + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortRasInfo,
                rasInfos[index]);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortDspIns,
                copLists[index]);
            bus.WriteLong(rasInfos[index] + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListViewPort,
                viewPorts[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopPtr,
                raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopLStart,
                raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopSStart,
                raws[index]);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListCount,
                12);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListMaxCount,
                index == 0 ? mergedCount : (ushort)12);
        }

        for (var stream = 0; stream < viewPortCount; stream++)
        {
            for (var word = 0; word < 22; word++)
                bus.WriteWord(raws[stream] + (uint)(word * 2),
                    word == 1
                        ? (ushort)(0x2D01 + stream * 0x0100)
                        : (ushort)((stream + 1) * 0x1100 + word));
            bus.WriteWord(raws[stream] + 44u, GraphicsLayouts.CopperEndWait);
            bus.WriteWord(raws[stream] + 46u, GraphicsLayouts.CopperEndMask);
        }
        foreach (var cprList in new[] { lofCpr, shfCpr })
        {
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, raws[0]);
            bus.WriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, mergedCount);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000, bus);
        bool ExecuteMrgCop(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.MrgCop],
                stack + 0x80u);
            cpu.State.A[1] = view;
            cpu.State.A[6] = originalA6;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 80000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return true;
            }

            return false;
        }
        bool Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
                stack + 0x80u);
            cpu.State.A[0] = viewPorts[0];
            cpu.State.A[6] = originalA6;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 80000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return true;
            }

            return false;
        }

        // The final source is part of the all-or-nothing publication
        // preflight. A short seventh CopList cannot leave a five-node prefix
        // committed before the private call reports failure.
        var rawBeforeMalformedMerge = ReadBusBytes(bus, raws[0], (int)mergedByteCount);
        bus.WriteWord(copLists[6] + (uint)GraphicsLayouts.CopListMaxCount, 11);
        Assert.True(ExecuteMrgCop(0xBAD0_0000u));
        Assert.Equal(rawBeforeMalformedMerge,
            ReadBusBytes(bus, raws[0], (int)mergedByteCount));
        Assert.Equal(viewPorts[6], bus.ReadLong(
            viewPorts[5] + (uint)GraphicsLayouts.ViewPortNext));

        bus.WriteWord(copLists[6] + (uint)GraphicsLayouts.CopListMaxCount, 12);
        Assert.True(ExecuteMrgCop(0xCAFE_0000u));
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(originalA6, cpu.State.A[6]);
        Assert.Equal(mergedCount, bus.ReadWord(
            copLists[0] + (uint)GraphicsLayouts.CopListCount));
        for (var stream = 0; stream < viewPortCount; stream++)
        {
            var destinationOffset = stream * 48;
            Assert.Equal((ushort)((stream + 1) * 0x1100), bus.ReadWord(
                raws[0] + (uint)destinationOffset));
            Assert.Equal((ushort)(0x2D01 + stream * 0x0100), bus.ReadWord(
                raws[0] + (uint)(destinationOffset + 2)));
            if (stream == 0)
                continue;
            Assert.Equal((ushort)(0x2D00 + stream * 0x0100), bus.ReadWord(
                raws[0] + (uint)(destinationOffset - 4)));
            Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(
                raws[0] + (uint)(destinationOffset - 2)));
        }
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(raws[0] + 332u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(raws[0] + 334u));
        var rawBefore = ReadBusBytes(bus, raws[0], (int)mergedByteCount);

        // The final source is part of the all-or-nothing teardown preflight.
        bus.WriteWord(copLists[6] + (uint)GraphicsLayouts.CopListMaxCount, 11);
        Assert.True(Execute(0xBAD0_0000u));
        Assert.Equal(rawBefore, ReadBusBytes(bus, raws[0], (int)mergedByteCount));
        foreach (var viewPort in viewPorts)
        {
            Assert.NotEqual(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }

        bus.WriteWord(copLists[6] + (uint)GraphicsLayouts.CopListMaxCount, 12);
        Assert.True(Execute(0x5A5A_0000u));
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(originalA6, cpu.State.A[6]);
        foreach (var viewPort in viewPorts)
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(rawBefore, ReadBusBytes(bus, raws[0], (int)mergedByteCount));
    }

