    [InlineData(14)]
    public void NativeGraphicsFreeVPortCopListsRetiresBoundedVisiblePreMergedCanonicalStreamsOnAccurateM68000(
        int viewPortCount)
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out _, out _, out _, out _, out _, out _, out _, out _, out _, out _, out _,
            out _);
        const uint codeAddress = 0x0080_0000;
        const uint viewPortsBase = 0x00E0_0100;
        const uint rasInfosBase = 0x00E0_1000;
        const uint copListsBase = 0x00E0_2000;
        const uint rawsBase = 0x00E0_3000;
        const uint stack = 0x00C9_0000;
        const uint returnAddress = 0x00F9_0000;
        const uint originalA6 = 0x00A6_1234;
        var mergedCount = checked((ushort)(viewPortCount * 12));
        var mergedByteCount = checked((uint)(viewPortCount * 48 + 0x20));

        var viewPorts = new uint[viewPortCount];
        var rasInfos = new uint[viewPortCount];
        var copLists = new uint[viewPortCount];
        var raws = new uint[viewPortCount];
        for (var index = 0; index < viewPortCount; index++)
        {
            viewPorts[index] = viewPortsBase + (uint)(index * 0x100);
            rasInfos[index] = rasInfosBase + (uint)(index * 0x100);
            copLists[index] = copListsBase + (uint)(index * 0x100);
            // An eleven-stream destination is 528 bytes; keep the retained
            // source streams outside its caller-owned raw envelope.
            raws[index] = rawsBase + (uint)(index * 0x400);
        }

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        foreach (var address in viewPorts)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.ViewPortSize]);
        foreach (var address in rasInfos)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.RasInfoSize]);
        foreach (var address in copLists)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(raws[0], new byte[mergedByteCount]);
        foreach (var address in raws.Skip(1))
            bus.MapWritableMemory(address, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        for (var index = 0; index < viewPortCount; index++)
        {
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortNext,
                index + 1 < viewPortCount ? viewPorts[index + 1] : 0u);
            bus.WriteWord(viewPorts[index] + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortRasInfo,
                rasInfos[index]);
            bus.WriteLong(rasInfos[index] + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortDspIns,
                copLists[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListViewPort,
                viewPorts[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopPtr,
                raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopLStart,
                raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopSStart,
                raws[index]);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListCount,
                index == 0 ? mergedCount : (ushort)12);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListMaxCount,
                index == 0 ? mergedCount : (ushort)12);

            for (var word = 0; word < 22; word++)
                bus.WriteWord(raws[index] + (uint)(word * 2),
                    (ushort)((index + 1) * 0x1100 + word));
            bus.WriteWord(raws[index] + 44u, GraphicsLayouts.CopperEndWait);
            bus.WriteWord(raws[index] + 46u, GraphicsLayouts.CopperEndMask);
        }
        var destinationTerminator = checked((uint)(viewPortCount * 48 - 4));
        bus.WriteWord(raws[0] + destinationTerminator, GraphicsLayouts.CopperEndWait);
        bus.WriteWord(raws[0] + destinationTerminator + 2u, GraphicsLayouts.CopperEndMask);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000, bus);
        bool Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
                stack + 0x80u);
            cpu.State.A[0] = viewPorts[0];
            cpu.State.A[6] = originalA6;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 100000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return true;
            }

            return false;
        }

        var rawBefore = ReadBusBytes(bus, raws[0], (int)mergedByteCount);
        bus.WriteWord(copLists[^1] + (uint)GraphicsLayouts.CopListMaxCount, 11);
        Assert.True(Execute(0xBAD0_0000u));
        Assert.Equal(0xBAD0_0000u, cpu.State.D[0]);
        Assert.Equal(rawBefore, ReadBusBytes(bus, raws[0], (int)mergedByteCount));
        foreach (var viewPort in viewPorts)
            Assert.NotEqual(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));

        bus.WriteWord(copLists[^1] + (uint)GraphicsLayouts.CopListMaxCount, 12);
        if (viewPortCount >= 14)
        {
            // The generic native walker must decline a repeated public node
            // without clearing any link, then leave the cyclic chain for the
            // ownership-aware fallback exactly as supplied.
            bus.WriteLong(viewPorts[^1] + (uint)GraphicsLayouts.ViewPortNext,
                viewPorts[0]);
            Assert.True(Execute(0xD15C_A11Eu));
            Assert.Equal(0xD15C_A11Eu, cpu.State.D[0]);
            Assert.Equal(rawBefore, ReadBusBytes(bus, raws[0], (int)mergedByteCount));
            foreach (var viewPort in viewPorts)
                Assert.NotEqual(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            bus.WriteLong(viewPorts[^1] + (uint)GraphicsLayouts.ViewPortNext, 0);
        }

        Assert.True(Execute(0x5A5A_0000u));
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(originalA6, cpu.State.A[6]);
        foreach (var viewPort in viewPorts)
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(rawBefore, ReadBusBytes(bus, raws[0], (int)mergedByteCount));
    }

