            Assert.Equal((ushort)(0x2D00 + stream * 0x0100), bus.ReadWord(
                raws[0] + (uint)(destinationOffset - 4)));
            Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(
                raws[0] + (uint)(destinationOffset - 2)));
        }
        var terminator = checked((uint)(viewPortCount * 48 - 4));
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(raws[0] + terminator));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(raws[0] + terminator + 2u));
    }

    [Fact]
    public void NativeGraphicsMrgCopAndFreeVPortCopListsRoundTripSixVisibleCanonicalStreamsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets, out _, out _, out _, out _, out _, out _, out _, out _, out _, out _, out _,
            out var mrgCopMultiViewportEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint view = 0x00DE_0000;
        var viewPorts = new[]
        {
            0x00DE_0100u, 0x00DE_0200u, 0x00DE_0300u,
            0x00DE_0400u, 0x00DE_0500u, 0x00DE_0600u
        };
        var rasInfos = new[]
        {
            0x00DE_0700u, 0x00DE_0800u, 0x00DE_0900u,
            0x00DE_0A00u, 0x00DE_0B00u, 0x00DE_0C00u
        };
        var copLists = new[]
        {
            0x00DE_0D00u, 0x00DE_0E00u, 0x00DE_0F00u,
            0x00DE_1000u, 0x00DE_1100u, 0x00DE_1200u
        };
        var raws = new[]
        {
            0x00DE_1400u, 0x00DE_1600u, 0x00DE_1800u,
            0x00DE_1A00u, 0x00DE_1C00u, 0x00DE_1E00u
        };
        const uint lofCpr = 0x00DE_2100;
        const uint shfCpr = 0x00DE_2200;
        const uint stack = 0x00C8_0000;
        const uint returnAddress = 0x00F8_0000;
        const uint originalA6 = 0x00A6_1234;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        foreach (var address in viewPorts)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.ViewPortSize]);
        foreach (var address in rasInfos)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.RasInfoSize]);
        foreach (var address in copLists)
            bus.MapWritableMemory(address, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(lofCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(shfCpr, new byte[GraphicsLayouts.CprListSize]);
        bus.MapWritableMemory(raws[0], new byte[0x140]);
        foreach (var address in raws.Skip(1))
            bus.MapWritableMemory(address, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPorts[0]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCpr);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCpr);

        for (var index = 0; index < viewPorts.Length; index++)
        {
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortNext,
                index + 1 < viewPorts.Length ? viewPorts[index + 1] : 0u);
            bus.WriteWord(viewPorts[index] + (uint)GraphicsLayouts.ViewPortModes, 0);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfos[index]);
            bus.WriteLong(viewPorts[index] + (uint)GraphicsLayouts.ViewPortDspIns, copLists[index]);
            bus.WriteLong(rasInfos[index] + (uint)GraphicsLayouts.RasInfoNext, 0);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListViewPort, viewPorts[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopPtr, raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopLStart, raws[index]);
            bus.WriteLong(copLists[index] + (uint)GraphicsLayouts.CopListCopSStart, raws[index]);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListCount,
                12);
            bus.WriteWord(copLists[index] + (uint)GraphicsLayouts.CopListMaxCount,
                index == 0 ? (ushort)72 : (ushort)12);
        }

        for (var stream = 0; stream < raws.Length; stream++)
        {
            for (var word = 0; word < 22; word++)
                bus.WriteWord(raws[stream] + (uint)(word * 2),
                    (ushort)((stream + 1) * 0x1100 + word));
            bus.WriteWord(raws[stream] + 2u, (ushort)(0x2D01 + stream * 0x0100));
            bus.WriteWord(raws[stream] + 44u, GraphicsLayouts.CopperEndWait);
            bus.WriteWord(raws[stream] + 46u, GraphicsLayouts.CopperEndMask);
        }
        foreach (var cprList in new[] { lofCpr, shfCpr })
        {
            bus.WriteLong(cprList + (uint)GraphicsLayouts.CprListStart, raws[0]);
            bus.WriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, 72);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000, bus);
        bool ExecuteMrgCop(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)mrgCopMultiViewportEntryOffset,
                stack + 0x80u);
            cpu.State.A[1] = view;
            cpu.State.A[6] = originalA6;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 40000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return true;
            }

            return false;
        }

        // A malformed sixth source must decline before it calls the guarded
        // five-viewport prefix; neither the prefix stream nor ViewPort five's
        // continuation can be left temporarily changed.
        var rawBeforeMalformedMerge = ReadBusBytes(bus, raws[0], 0x140);
        bus.WriteWord(copLists[5] + (uint)GraphicsLayouts.CopListMaxCount, 11);
        Assert.True(ExecuteMrgCop(0xBAD0_0000u));
        Assert.Equal(0xBAD0_0000u, cpu.State.D[0]);
        Assert.Equal(viewPorts[5], bus.ReadLong(
            viewPorts[4] + (uint)GraphicsLayouts.ViewPortNext));
        Assert.Equal(rawBeforeMalformedMerge, ReadBusBytes(bus, raws[0], 0x140));

        bus.WriteWord(copLists[5] + (uint)GraphicsLayouts.CopListMaxCount, 12);
        Assert.True(ExecuteMrgCop(0xCAFE_0000u));
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(originalA6, cpu.State.A[6]);
        Assert.Equal((ushort)72, bus.ReadWord(
            copLists[0] + (uint)GraphicsLayouts.CopListCount));
        for (var stream = 0; stream < raws.Length; stream++)
        {
            var destinationOffset = stream * 48;
            for (var word = 0; word < 22; word++)
            {
                var expected = word == 1
                    ? (ushort)(0x2D01 + stream * 0x0100)
                    : (ushort)((stream + 1) * 0x1100 + word);
                var actual = bus.ReadWord(
                    raws[0] + (uint)(destinationOffset + word * 2));
                Assert.True(expected == actual,
                    $"stream {stream}, word {word}: expected {expected:X4}, actual {actual:X4}, source {bus.ReadWord(raws[stream] + (uint)(word * 2)):X4}");
            }
            if (stream == 0)
                continue;
            Assert.Equal((ushort)(0x2D00 + stream * 0x0100),
                bus.ReadWord(raws[0] + (uint)(destinationOffset - 4)));
            Assert.Equal(GraphicsLayouts.CopperEndMask,
                bus.ReadWord(raws[0] + (uint)(destinationOffset - 2)));
        }
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(raws[0] + 284u));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(raws[0] + 286u));
        var rawBefore = ReadBusBytes(bus, raws[0], 0x140);

        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.FreeVPortCopLists],
            stack + 0x80u);
        cpu.State.A[0] = viewPorts[0];
        cpu.State.A[6] = originalA6;
        cpu.State.D[0] = 0x5A5A_0000u;
        var returned = false;
        for (var index = 0; index < 40000; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter != returnAddress)
                continue;
            returned = true;
            break;
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(originalA6, cpu.State.A[6]);
        foreach (var viewPort in viewPorts)
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(rawBefore, ReadBusBytes(bus, raws[0], 0x140));
    }

    [Fact]
    public void NativeGraphicsUserCopperOneSlotInstructionsAndBumpPublishOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint userList = 0x00B0_0100;
        const uint copList = 0x00B0_0200;
        const uint instructions = 0x00B0_0300;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const byte sentinel = 0xA5;
        bus.MapWritableMemory(userList, new byte[GraphicsLayouts.UCopListSize]);
        bus.MapWritableMemory(copList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(instructions, new byte[GraphicsLayouts.CopInsSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(
            userList + (uint)GraphicsLayouts.UCopListCopList,
            copList);
        bus.WriteLong(
            copList + (uint)GraphicsLayouts.CopListCopIns,
            instructions);
        bus.WriteLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr,
            instructions);
        bus.WriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            0);
        bus.WriteWord(
            copList + (uint)GraphicsLayouts.CopListMaxCount,
            1);
        bus.WriteLong(
            copList + (uint)GraphicsLayouts.CopListNext,
            0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void FillInstructions()
        {
            for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
                bus.WriteByte(instructions + (uint)offset, sentinel, 0);
        }

        void Execute(GraphicsLvo vector, uint d0, uint d1, uint a1 = userList)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = a1;
            cpu.State.D[0] = d0;
            cpu.State.D[1] = d1;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                $"Native {vector} one-slot body did not return.");
        }

        FillInstructions();
        Execute(GraphicsLvo.CMove, 0x00DF_F181u, 0x1234u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            instructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)0x0180, bus.ReadWord(
            instructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)0x1234, bus.ReadWord(
            instructions + (uint)GraphicsLayouts.CopInsArg1));

        FillInstructions();
        Execute(GraphicsLvo.CWait, 42u, 12u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(
            instructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)42, bus.ReadWord(
            instructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)12, bus.ReadWord(
            instructions + (uint)GraphicsLayouts.CopInsArg1));

        // The matching first CBump transition advances only the resident
        // one-slot block.  It publishes CopPtr+6 and Count==1, with no
        // allocation or linked successor.
        bus.WriteLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr,
            instructions);
        bus.WriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            0);
        FillInstructions();
        Execute(GraphicsLvo.CBump, 0xABCD_0000u, 0x2468u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(instructions + (uint)GraphicsLayouts.CopInsSize, bus.ReadLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr));
        Assert.Equal((ushort)1, bus.ReadWord(
            copList + (uint)GraphicsLayouts.CopListCount));
        for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(instructions + (uint)offset));

        // A non-current CopPtr is provider-owned state.  The native arm must
        // restore the caller's registers and leave the six-byte record intact.
        FillInstructions();
        bus.WriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            0);
        bus.WriteLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr,
            instructions + 2u);
        Execute(GraphicsLvo.CMove, 0xDEAD_BEEFu, 0x1357u);
        Assert.Equal(0xDEAD_BEEFu, cpu.State.D[0]);
        Assert.Equal(0x1357u, cpu.State.D[1]);
        for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(instructions + (uint)offset));

        // Count != 0 likewise declines without consuming the one-slot body.
        bus.WriteLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr,
            instructions);
        bus.WriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            1);
        Execute(GraphicsLvo.CWait, 0xFACEu, 0x2468u);
        Assert.Equal(0xFACEu, cpu.State.D[0]);
        Assert.Equal(0x2468u, cpu.State.D[1]);
        for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(instructions + (uint)offset));

        bus.WriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            0);
        FillInstructions();
        Execute(GraphicsLvo.CMove, 0xFACE_B00Cu, 0x7777u, userList + 1u);
        Assert.Equal(0xFACE_B00Cu, cpu.State.D[0]);
        Assert.Equal(0x7777u, cpu.State.D[1]);
        for (var offset = 0; offset < GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal(sentinel, bus.ReadByte(instructions + (uint)offset));
    }

    [Fact]
    public void NativeGraphicsFreeVPortCopListsEmptyLinksReturnsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint viewPort = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        var linkOffsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint viewPortAddress = viewPort)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FreeVPortCopLists),
                stack + 0x80u);
            cpu.State.A[0] = viewPortAddress;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native FreeVPortCopLists empty-link body did not return.");
        }

        foreach (var offset in linkOffsets)
            bus.WriteLong(viewPort + (uint)offset, 0);

        Execute(0xCAFE_BABEu, 0);
        Assert.Equal(0u, cpu.State.D[0]);

        Execute(0xD00D_BEEFu);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        bus.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
            0x1122_3344u);
        Execute(0xFACE_1234u);
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);
        Assert.Equal(
            0x1122_3344u,
            bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));

        Execute(0xABCD_5678u, viewPort + 1u);
        Assert.Equal(0xABCD_5678u, cpu.State.D[0]);
        Execute(0x1357_9BDFu, 0xFFFF_FFF0u);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsFreeVPortCopListsTearsDownPreallocatedBlankCopperResourcesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint viewPort = 0x00D3_1000;
        const uint rasInfo = 0x00D3_1100;
        const uint copList = 0x00D3_1200;
        const uint rawCopper = 0x00D3_1300;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(copList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(rawCopper, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        var linkOffsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };

        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, rawCopper);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, rawCopper);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);
        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 0);
        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, 1);
        bus.WriteWord(rawCopper + 0u, GraphicsLayouts.CopperEndWait);
        bus.WriteWord(rawCopper + 2u, GraphicsLayouts.CopperEndMask);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FreeVPortCopLists),
                stack + 0x80u);
            cpu.State.A[0] = viewPort;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native FreeVPortCopLists preallocated teardown did not return.");
        }

        Execute(0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));
        Assert.Equal(viewPort, bus.ReadLong(
            copList + (uint)GraphicsLayouts.CopListViewPort));
        Assert.Equal(rawCopper, bus.ReadLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr));
        Assert.Equal(GraphicsLayouts.CopperEndWait, bus.ReadWord(rawCopper));
        Assert.Equal(GraphicsLayouts.CopperEndMask, bus.ReadWord(rawCopper + 2u));

        // Rebuild the public link for each malformed-resource rollback case.
        void Relink()
        {
            bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 0);
            bus.WriteWord(rawCopper + 0u, GraphicsLayouts.CopperEndWait);
            bus.WriteWord(rawCopper + 2u, GraphicsLayouts.CopperEndMask);
        }

        Relink();
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper + 2u);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(copList, bus.ReadLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);

        bus.WriteWord(rawCopper, 0x1234);
        Execute(0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        Assert.Equal(copList, bus.ReadLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        bus.WriteWord(rawCopper, GraphicsLayouts.CopperEndWait);

        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 1);
        Execute(0xFACE_0000u);
        Assert.Equal(0xFACE_0000u, cpu.State.D[0]);
        Assert.Equal(copList, bus.ReadLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
    }

    [Fact]
    public void NativeGraphicsFreeVPortCopListsTearsDownGeneratedCopperResourcesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint viewPort = 0x00D3_2000;
        const uint rasInfo = 0x00D3_2100;
        const uint bitMap = 0x00D3_2200;
        const uint plane = 0x00D3_2300;
        const uint copList = 0x00D3_2400;
        const uint rawCopper = 0x00D3_2500;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[4]);
        bus.MapWritableMemory(copList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(rawCopper, new byte[48]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        var linkOffsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };

        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, rawCopper);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, rawCopper);
        bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);
        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, 12);
        bus.WriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, 12);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        var generatedCopperChecks = new (int Offset, ushort Value)[]
        {
            (0, 0x008E), (2, 0x2C81), (4, 0x0090), (6, 0x2D00),
            (8, 0x0092), (10, 0x0038), (12, 0x0094), (14, 0x0038),
            (16, 0x0108), (18, 0x0000), (20, 0x010A), (22, 0x0000),
            (24, 0x0100), (26, 0x1000), (28, 0x0102), (30, 0x0000),
            (32, 0x0104), (34, 0x0000), (36, 0x00E0),
            (40, 0x00E2), (44, GraphicsLayouts.CopperEndWait),
            (46, GraphicsLayouts.CopperEndMask)
        };
        foreach (var (offset, value) in generatedCopperChecks)
            bus.WriteWord(rawCopper + (uint)offset, value);
        bus.WriteWord(rawCopper + 38u, (ushort)(plane >> 16));
        bus.WriteWord(rawCopper + 42u, unchecked((ushort)plane));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FreeVPortCopLists),
                stack + 0x80u);
            cpu.State.A[0] = viewPort;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native FreeVPortCopLists generated teardown did not return.");
        }

        var copListSnapshot = ReadBusBytes(bus, copList, GraphicsLayouts.CopListSize);
        var rawSnapshot = ReadBusBytes(bus, rawCopper, 48);
        Execute(0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));
        Assert.Equal(copListSnapshot, ReadBusBytes(bus, copList, GraphicsLayouts.CopListSize));
        Assert.Equal(rawSnapshot, ReadBusBytes(bus, rawCopper, 48));

        // The same teardown owner accepts the common 320x200 lores variant.
        // Only the two DIW/DDF stop words and the bitmap envelope differ.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 200);
        bus.WriteWord(rawCopper + 6u, 0xF4C1);
        bus.WriteWord(rawCopper + 14u, 0x00D0);
        Execute(0x369C_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // PAL 320x256 keeps the same lores copper words but carries the
        // complete 256-row bitmap envelope.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteWord(rawCopper + 10u, 0x0038);
        bus.WriteWord(rawCopper + 14u, 0x00D0);
        bus.WriteWord(rawCopper + 26u, 0x1000);
        Execute(0x3B00_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // The same teardown owner also accepts the standard 640x200 hires
        // signature, including its DDF timing and BPLCON0 mode bit.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 80);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 200);
        bus.WriteWord(rawCopper + 10u, 0x003C);
        bus.WriteWord(rawCopper + 14u, 0x00D4);
        bus.WriteWord(rawCopper + 26u, 0x9000);
        Execute(0x48AC_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // PAL 640x256 keeps the hires copper signature but carries the full
        // 256-row bitmap envelope.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 80);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteWord(rawCopper + 10u, 0x003C);
        bus.WriteWord(rawCopper + 14u, 0x00D4);
        bus.WriteWord(rawCopper + 26u, 0x9000);
        Execute(0x48AD_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // PAL 320x512 lores interlace keeps the lores timing while using the
        // lace BPLCON0 bit and a full 512-row bitmap envelope.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 512);
        bus.WriteWord(rawCopper + 10u, 0x0038);
        bus.WriteWord(rawCopper + 14u, 0x00D0);
        bus.WriteWord(rawCopper + 26u, 0x1004);
        Execute(0x48AE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // NTSC 320x400 lores interlace uses the same interlace copper words
        // with the NTSC 400-row bitmap envelope.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 400);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 400);
        bus.WriteWord(rawCopper + 10u, 0x0038);
        bus.WriteWord(rawCopper + 14u, 0x00D0);
        bus.WriteWord(rawCopper + 26u, 0x1004);
        Execute(0x48AF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // PAL 640x512 hires interlace keeps the hires timing while using the
        // lace BPLCON0 bit and a full 512-row bitmap envelope.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 80);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 512);
        bus.WriteWord(rawCopper + 10u, 0x003C);
        bus.WriteWord(rawCopper + 14u, 0x00D4);
        bus.WriteWord(rawCopper + 26u, 0x9004);
        Execute(0x48B0_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // NTSC 640x400 hires interlace uses the same copper signature with
        // the NTSC 400-row bitmap envelope.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 400);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 80);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 400);
        Execute(0x48B1_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var offset in linkOffsets)
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)offset));

        // A single generated word mutation must keep the public link and D0
        // available to the allocator/provider owner.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList);
        bus.WriteWord(rawCopper + 24u, 0x1234);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(copList, bus.ReadLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
    }

    [Fact]
    public void NativeGraphicsFreeVPortCopListsTearsDownNativeMrgCopTwoVisibleOutputOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint firstViewPort = 0x00D3_3000;
        const uint secondViewPort = 0x00D3_3100;
        const uint firstCopList = 0x00D3_3200;
        const uint secondCopList = 0x00D3_3300;
        const uint destinationRawCopper = 0x00D3_3400;
        const uint secondRawCopper = 0x00D3_3500;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(firstViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(secondViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(firstCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(secondCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(destinationRawCopper, new byte[0x80]);
        bus.MapWritableMemory(secondRawCopper, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortNext, secondViewPort);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        bus.WriteWord(firstViewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteWord(secondViewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteByte(firstViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteByte(secondViewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns, firstCopList);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns, secondCopList);

        foreach (var (copList, viewPort, rawCopper, count, maxCount) in new[]
        {
            (firstCopList, firstViewPort, destinationRawCopper, (ushort)24, (ushort)24),
            (secondCopList, secondViewPort, secondRawCopper, (ushort)12, (ushort)12)
        })
        {
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, rawCopper);
            bus.WriteLong(copList + (uint)GraphicsLayouts.CopListNext, 0);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListCount, count);
            bus.WriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, maxCount);
        }
        bus.WriteWord(destinationRawCopper + 92u, 0xFFFF);
        bus.WriteWord(destinationRawCopper + 94u, GraphicsLayouts.CopperEndMask);
        bus.WriteWord(secondRawCopper + 44u, 0xFFFF);
        bus.WriteWord(secondRawCopper + 46u, GraphicsLayouts.CopperEndMask);

        var firstBefore = ReadBusBytes(bus, firstViewPort, GraphicsLayouts.ViewPortSize);
        var secondBefore = ReadBusBytes(bus, secondViewPort, GraphicsLayouts.ViewPortSize);
        var firstCopBefore = ReadBusBytes(bus, firstCopList, GraphicsLayouts.CopListSize);
        var secondCopBefore = ReadBusBytes(bus, secondCopList, GraphicsLayouts.CopListSize);
        var destinationRawBefore = ReadBusBytes(bus, destinationRawCopper, 0x80);
        var secondRawBefore = ReadBusBytes(bus, secondRawCopper, 0x40);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.FreeVPortCopLists),
            stack + 0x80u);
        cpu.State.A[0] = firstViewPort;
        cpu.State.D[0] = 0xCAFE_0000u;
        cpu.ExecuteInstruction(); // vector JMP.L
        var returned = false;
        for (var index = 0; index < 2048; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0u, cpu.State.D[0]);
        foreach (var viewPort in new[] { firstViewPort, secondViewPort })
        {
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
            Assert.Equal(0u, bus.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        }
        Assert.Equal(secondViewPort, bus.ReadLong(
            firstViewPort + (uint)GraphicsLayouts.ViewPortNext));
        Assert.Equal(firstBefore[..GraphicsLayouts.ViewPortDspIns],
            ReadBusBytes(bus, firstViewPort, GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(secondBefore[..GraphicsLayouts.ViewPortDspIns],
            ReadBusBytes(bus, secondViewPort, GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(firstCopBefore, ReadBusBytes(bus, firstCopList, GraphicsLayouts.CopListSize));
        Assert.Equal(secondCopBefore, ReadBusBytes(bus, secondCopList, GraphicsLayouts.CopListSize));
        Assert.Equal(destinationRawBefore, ReadBusBytes(bus, destinationRawCopper, 0x80));
        Assert.Equal(secondRawBefore, ReadBusBytes(bus, secondRawCopper, 0x40));

        // An odd source pointer is outside the native MrgCop teardown owner
        // and must preserve both public DspIns links and the caller's D0.
        bus.WriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns, firstCopList);
        bus.WriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns, secondCopList);
        bus.WriteLong(secondCopList + (uint)GraphicsLayouts.CopListCopPtr, secondRawCopper + 1u);
        bus.WriteLong(secondCopList + (uint)GraphicsLayouts.CopListCopLStart, secondRawCopper + 1u);
        bus.WriteLong(secondCopList + (uint)GraphicsLayouts.CopListCopSStart, secondRawCopper + 1u);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.FreeVPortCopLists),
            stack + 0x80u);
        cpu.State.A[0] = firstViewPort;
        cpu.State.D[0] = 0xBEEF_0000u;
        cpu.ExecuteInstruction();
        returned = false;
        for (var index = 0; index < 2048; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(firstCopList, bus.ReadLong(
            firstViewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(secondCopList, bus.ReadLong(
            secondViewPort + (uint)GraphicsLayouts.ViewPortDspIns));
    }

    [Fact]
    public void NativeGraphicsFreeColorMapNullReturnsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint colorMap, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FreeColorMap),
                stack + 0x80u);
            cpu.State.A[0] = colorMap;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 64; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native FreeColorMap NULL body did not return.");
        }

        Execute(0, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);

        // Non-NULL values are deliberately unmapped: the native body must
        // decline before reading a ColorMap envelope and preserve D0.
        Execute(0x00D4_0100u, 0xD00D_BEEFu);
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);

        Execute(0x00D4_0101u, 0xFACE_1234u);
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);

        Execute(0xFFFF_FFFCu, 0xABCD_9876u);
        Assert.Equal(0xABCD_9876u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsFreeBitMapNullReturnsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint bitMap, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FreeBitMap),
                stack + 0x80u);
            cpu.State.A[0] = bitMap;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            // The public vector now probes the native depth ladder before
            // chaining foreign forms into the depth-one/provider arm.
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native FreeBitMap NULL body did not return.");
        }

        Execute(0, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);

        // Non-NULL values are deliberately unmapped: the native body must
        // decline before reading or releasing a BitMap envelope.
        Execute(0x00D5_0100u, 0xD00D_BEEFu);
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);

        Execute(0x00D5_0101u, 0xFACE_1234u);
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);

        Execute(0xFFFF_FFFCu, 0xABCD_9876u);
        Assert.Equal(0xABCD_9876u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsRasterAllocatorUsesExecHeaderOwnershipAndChainsDeclinesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        const uint execBase = 0x0070_0000;
        const uint rasterBase = 0x00D0_0000;
        const uint foreignBase = 0x00D1_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 17;
        const ushort height = 3;
        const uint payloadBytes = 12;
        const uint headerBytes = 10;
        const uint allocationBytes = payloadBytes + headerBytes;

        var bus = new AmigaBus();
        var nextCodeAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextCodeAllocation;
                nextCodeAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        // Map the low page so wrapped high-address descriptors can be made
        // intentionally valid-looking below.  The native body must reject
        // their original public envelope before it can consume these aliases.
        bus.MapWritableMemory(0, new byte[0x100]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(rasterBase, new byte[checked((int)allocationBytes)]);
        bus.MapWritableMemory(foreignBase, new byte[checked((int)allocationBytes)]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocationResult = rasterBase;
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResult;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A1;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0xD0D0_D0D0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A1;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 512)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            configure();
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    Assert.Equal(stack + 0x84u, cpu.State.A[7]);
                    return;
                }
            }

            throw new InvalidOperationException(
                $"Native {vector} raster body did not return.");
        }

        Execute(
            GraphicsLvo.AllocRaster,
            () =>
            {
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
            });
        Assert.Equal(rasterBase + headerBytes, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBytes, 0x0001_0003u) },
            allocations);
        Assert.Equal((ushort)0x5253, bus.ReadWord(rasterBase));
        Assert.Equal(width, bus.ReadWord(rasterBase + 2u));
        Assert.Equal(height, bus.ReadWord(rasterBase + 4u));
        Assert.Equal(allocationBytes, bus.ReadLong(rasterBase + 6u));

        Execute(
            GraphicsLvo.FreeRaster,
            () =>
            {
                cpu.State.A[0] = rasterBase + headerBytes;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[] { (rasterBase, allocationBytes) },
            frees);

        // A dimension mismatch and a foreign marker remain available to the
        // provider/fallback path without issuing a second FreeMem call.
        Execute(
            GraphicsLvo.FreeRaster,
            () =>
            {
                cpu.State.A[0] = rasterBase + headerBytes;
                cpu.State.D[0] = width;
                cpu.State.D[1] = (ushort)(height + 1);
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Single(frees);

        Execute(
            GraphicsLvo.FreeRaster,
            () =>
            {
                cpu.State.A[0] = foreignBase + headerBytes;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Single(frees);

        // A zero Exec allocation result declines without publishing a
        // payload or issuing a compensating FreeMem call.
        allocationResult = 0;
        Execute(
            GraphicsLvo.AllocRaster,
            () =>
            {
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Single(frees);

        // An allocator that violates Exec's word-alignment contract is
        // cleaned up and declined rather than publishing an odd PLANEPTR.
        allocationResult = rasterBase + 1u;
        Execute(
            GraphicsLvo.AllocRaster,
            () =>
            {
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (rasterBase, allocationBytes),
                (rasterBase + 1u, allocationBytes)
            },
            frees);
    }

    [Fact]
    public void NativeGraphicsSinglePlaneBitMapAllocatorUsesExecEnvelopeAndChainsDeclinesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        const uint execBase = 0x0070_0000;
        const uint allocationBase = 0x00D2_0000;
        const uint foreignBase = 0x00D2_1000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 17;
        const ushort height = 3;
        const uint rowBytes = 4;
        const uint planeBytes = rowBytes * height;
        const uint headerAndBitmapBytes = 16u + (uint)GraphicsLayouts.BitMapSize;
        const uint allocationBytes = headerAndBitmapBytes + planeBytes;

        var bus = new AmigaBus();
        var nextCodeAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextCodeAllocation;
                nextCodeAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(allocationBase, new byte[checked((int)allocationBytes)]);
        bus.MapWritableMemory(foreignBase, new byte[checked((int)allocationBytes)]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocationResult = allocationBase;
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResult;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0xD0D0_D0D0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 384)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            configure();
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} single-plane BitMap body did not return.");
        }

        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0; // no Friend_BitMap
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 1;
                cpu.State.D[3] = 3; // BMF_CLEAR | BMF_DISPLAYABLE
            });
        var publicBitMap = allocationBase + 16u;
        var plane = allocationBase + headerAndBitmapBytes;
        Assert.Equal(publicBitMap, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBytes, 0x0001_0003u) },
            allocations);
        Assert.Equal((ushort)0x424D, bus.ReadWord(allocationBase));
        Assert.Equal(width, bus.ReadWord(allocationBase + 2u));
        Assert.Equal(height, bus.ReadWord(allocationBase + 4u));
        Assert.Equal(allocationBytes, bus.ReadLong(allocationBase + 8u));
        Assert.Equal(rowBytes, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(height, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x0A, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)1, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(plane, bus.ReadLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes));

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xCAFE_BABEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBase, allocationBytes) },
            frees);

        // Interleaved requests remain outside this standard-planar native
        // slice even when BMF_DISPLAYABLE is also present.
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 1;
                cpu.State.D[3] = 7; // CLEAR | DISPLAYABLE | INTERLEAVED
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Single(allocations);

        // A foreign marker and a corrupted plane link preserve D0 and never
        // call Exec, leaving ownership available to the portable/provider arm.
        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = foreignBase + 16u;
                cpu.State.D[0] = 0xD00D_BEEFu;
            });
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
        Assert.Single(frees);

        bus.WriteLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes, plane + 2u);
        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xFACE_1234u;
            });
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);
        Assert.Single(frees);

        // Friend-backed requests remain outside the native standard-planar
        // arm and must preserve D0 for the portable/provider implementation.
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = foreignBase + 16u;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 1;
                cpu.State.D[3] = 0;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Single(allocations);

        allocationResult = allocationBase + 1u;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 1;
                cpu.State.D[3] = 0;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, allocationBytes),
                (allocationBase + 1u, allocationBytes)
            },
            frees);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = 7;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(2, frees.Count);
    }

    [Fact]
    public void NativeGraphicsTwoPlaneBitMapAllocatorPublishesContiguousPlanesAndChainsOnePlaneOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        const uint execBase = 0x0070_0000;
        const uint allocationBase = 0x00D2_0000;
        const uint foreignBase = 0x00D2_1000;
        const uint onePlaneBase = 0x00D2_2000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 17;
        const ushort height = 3;
        const uint rowBytes = 4;
        const uint planeBytes = rowBytes * height;
        const uint headerAndBitmapBytes = 16u + (uint)GraphicsLayouts.BitMapSize;
        const uint twoPlaneBytes = headerAndBitmapBytes + (planeBytes * 2u);
        const uint onePlaneBytes = headerAndBitmapBytes + planeBytes;

        var bus = new AmigaBus();
        var nextCodeAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextCodeAllocation;
                nextCodeAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(allocationBase, new byte[checked((int)twoPlaneBytes)]);
        bus.MapWritableMemory(foreignBase, new byte[checked((int)twoPlaneBytes)]);
        bus.MapWritableMemory(onePlaneBase, new byte[checked((int)onePlaneBytes)]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocationResult = allocationBase;
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResult;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0xD0D0_D0D0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 512)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            configure();
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} two-plane BitMap body did not return.");
        }

        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 2;
                cpu.State.D[3] = 3; // BMF_CLEAR | BMF_DISPLAYABLE
            });
        var publicBitMap = allocationBase + 16u;
        var firstPlane = allocationBase + headerAndBitmapBytes;
        var secondPlane = firstPlane + planeBytes;
        Assert.Equal(publicBitMap, cpu.State.D[0]);
        Assert.Equal(
            new[] { (twoPlaneBytes, 0x0001_0003u) },
            allocations);
        Assert.Equal((ushort)0x424D, bus.ReadWord(allocationBase));
        Assert.Equal(width, bus.ReadWord(allocationBase + 2u));
        Assert.Equal(height, bus.ReadWord(allocationBase + 4u));
        Assert.Equal((ushort)2, bus.ReadWord(allocationBase + 6u));
        Assert.Equal(twoPlaneBytes, bus.ReadLong(allocationBase + 8u));
        Assert.Equal(rowBytes, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(height, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x0A, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)2, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(firstPlane, bus.ReadLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal(secondPlane, bus.ReadLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u));

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xCAFE_BABEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBase, twoPlaneBytes) },
            frees);

        // Corrupting either plane link keeps the aggregate allocation alive.
        bus.WriteLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, secondPlane + 2u);
        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xD00D_BEEFu;
            });
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
        Assert.Single(frees);

        // Depth one chains through the pre-existing native arm, so the vector
        // remains a single public entry while the implementation grows in
        // independent layout-compatible units.
        allocationResult = onePlaneBase;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 1;
                cpu.State.D[3] = 0;
            });
        var onePlanePublic = onePlaneBase + 16u;
        Assert.Equal(onePlanePublic, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (twoPlaneBytes, 0x0001_0003u),
                (onePlaneBytes, 0x0000_0003u)
            },
            allocations);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = onePlanePublic;
                cpu.State.D[0] = 7;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, twoPlaneBytes),
                (onePlaneBase, onePlaneBytes)
            },
            frees);

        // Odd allocator results are released with the depth-two aggregate
        // span and then declined without publishing a guest BitMap.
        allocationResult = allocationBase + 1u;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 2;
                cpu.State.D[3] = 0;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, twoPlaneBytes),
                (onePlaneBase, onePlaneBytes),
                (allocationBase + 1u, twoPlaneBytes)
            },
            frees);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = 9;
            });
        Assert.Equal(0u, cpu.State.D[0]);
    }

