        Assert.Equal((ushort)0x424D, bus.ReadWord(allocationBase));
        Assert.Equal(width, bus.ReadWord(allocationBase + 2u));
        Assert.Equal(height, bus.ReadWord(allocationBase + 4u));
        Assert.Equal((ushort)4, bus.ReadWord(allocationBase + 6u));
        Assert.Equal(fourPlaneBytes, bus.ReadLong(allocationBase + 8u));
        Assert.Equal(rowBytes, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(height, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x0A, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)4, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapDepth));
        for (var plane = 0; plane < 4; plane++)
        {
            Assert.Equal(
                firstPlane + (planeBytes * (uint)plane),
                bus.ReadLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4)));
        }

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xCAFE_BABEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(new[] { (allocationBase, fourPlaneBytes) }, frees);

        bus.WriteLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes + 12u, firstPlane + (planeBytes * 4u));
        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xD00D_BEEFu;
            });
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
        Assert.Single(frees);

        // Depth two chains through the lower native arm, preserving one
        // public vector while each depth ladder unit stays independently
        // auditable.
        allocationResult = depthTwoBase;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 2;
                cpu.State.D[3] = 0;
            });
        Assert.Equal(depthTwoBase + 16u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (fourPlaneBytes, 0x0001_0003u),
                (twoPlaneBytes, 0x0000_0003u)
            },
            allocations);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = depthTwoBase + 16u;
                cpu.State.D[0] = 7;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, fourPlaneBytes),
                (depthTwoBase, twoPlaneBytes)
            },
            frees);

        allocationResult = allocationBase + 1u;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 4;
                cpu.State.D[3] = 0;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, fourPlaneBytes),
                (depthTwoBase, twoPlaneBytes),
                (allocationBase + 1u, fourPlaneBytes)
            },
            frees);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = 9;
            });
        Assert.Equal(0u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsEightPlaneBitMapAllocatorPublishesAllPlanesAndChainsLowerDepthsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        const uint execBase = 0x0070_0000;
        const uint allocationBase = 0x00D8_0000;
        const uint fourPlaneBase = 0x00D8_1000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const ushort width = 17;
        const ushort height = 3;
        const uint rowBytes = 4;
        const uint planeBytes = rowBytes * height;
        const uint headerAndBitmapBytes = 16u + (uint)GraphicsLayouts.BitMapSize;
        const uint eightPlaneBytes = headerAndBitmapBytes + (planeBytes * 8u);
        const uint fourPlaneBytes = headerAndBitmapBytes + (planeBytes * 4u);

        var bus = new AmigaBus();
        var nextCodeAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextCodeAllocation;
                nextCodeAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(allocationBase, new byte[checked((int)eightPlaneBytes)]);
        bus.MapWritableMemory(fourPlaneBase, new byte[checked((int)fourPlaneBytes)]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocationResult = allocationBase;
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResult;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0xD0D0_D0D0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 1024)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            configure();
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} eight-plane BitMap body did not return.");
        }

        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 8;
                cpu.State.D[3] = 3; // BMF_CLEAR | BMF_DISPLAYABLE
            });

        var publicBitMap = allocationBase + 16u;
        var firstPlane = allocationBase + headerAndBitmapBytes;
        Assert.Equal(publicBitMap, cpu.State.D[0]);
        Assert.Equal(new[] { (eightPlaneBytes, 0x0001_0003u) }, allocations);
        Assert.Equal((ushort)0x424D, bus.ReadWord(allocationBase));
        Assert.Equal(width, bus.ReadWord(allocationBase + 2u));
        Assert.Equal(height, bus.ReadWord(allocationBase + 4u));
        Assert.Equal((ushort)8, bus.ReadWord(allocationBase + 6u));
        Assert.Equal(eightPlaneBytes, bus.ReadLong(allocationBase + 8u));
        Assert.Equal(rowBytes, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(height, bus.ReadWord(publicBitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x0A, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)8, bus.ReadByte(publicBitMap + (uint)GraphicsLayouts.BitMapDepth));
        for (var plane = 0; plane < 8; plane++)
        {
            Assert.Equal(
                firstPlane + (planeBytes * (uint)plane),
                bus.ReadLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4)));
        }

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xCAFE_BABEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(new[] { (allocationBase, eightPlaneBytes) }, frees);

        bus.WriteLong(publicBitMap + (uint)GraphicsLayouts.BitMapPlanes + 28u, firstPlane + (planeBytes * 8u));
        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = publicBitMap;
                cpu.State.D[0] = 0xD00D_BEEFu;
            });
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
        Assert.Single(frees);

        allocationResult = fourPlaneBase;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 4;
                cpu.State.D[3] = 0;
            });
        Assert.Equal(fourPlaneBase + 16u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (eightPlaneBytes, 0x0001_0003u),
                (fourPlaneBytes, 0x0000_0003u)
            },
            allocations);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = fourPlaneBase + 16u;
                cpu.State.D[0] = 7;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, eightPlaneBytes),
                (fourPlaneBase, fourPlaneBytes)
            },
            frees);

        allocationResult = allocationBase + 1u;
        Execute(
            GraphicsLvo.AllocBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = width;
                cpu.State.D[1] = height;
                cpu.State.D[2] = 8;
                cpu.State.D[3] = 0;
            });
        Assert.Equal((uint)width, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, eightPlaneBytes),
                (fourPlaneBase, fourPlaneBytes),
                (allocationBase + 1u, eightPlaneBytes)
            },
            frees);

        Execute(
            GraphicsLvo.FreeBitMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = 9;
            });
        Assert.Equal(0u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsRegionLifecycleUsesPrivatePrefixAndExecTeardownOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0080_0000;
        const uint execBase = 0x0070_0000;
        const uint allocationBase = 0x00D2_0000;
        const uint node = 0x00D2_1000;
        const uint nodeB = 0x00D2_1100;
        const uint nodeC = 0x00D2_1200;
        const uint rectangle = 0x00D2_2500;
        const uint allocationBase2 = 0x00D2_3000;
        const uint node2 = 0x00D2_4000;
        const uint foreignAllocationBase = 0x00D2_2000;
        const uint foreignRegion = foreignAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(
            allocationBase,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(nodeB, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(nodeC, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(rectangle, new byte[GraphicsLayouts.RectangleSize]);
        bus.MapWritableMemory(
            allocationBase2,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(node2, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(
            foreignAllocationBase,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { allocationBase, allocationBase2 });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 4096)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[vector],
                stack + 0x80u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} Region body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(
            GraphicsLvo.NewRegion,
            () => cpu.State.D[0] = 0xCAFE_BABEu);
        var region = allocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Assert.Equal(region, cpu.State.D[0]);
        Assert.Equal(
            new[] { ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u) },
            allocations);
        Assert.Equal(GraphicsLayouts.NativeRegionMarker, bus.ReadWord(allocationBase));
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));

        // Three guest-created rectangles allow native AndRectRegion to prove
        // the no-allocation path compacts a surviving interior node into the
        // public prefix and retires only the discarded suffix through Exec.
        bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
        bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
        bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 9);
        bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 9);
        bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, node);
        bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, nodeB);
        bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious,
            region + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX, 0);
        bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY, 0);
        bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX, 2);
        bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY, 2);
        bus.WriteLong(nodeB + (uint)GraphicsLayouts.RegionRectangleNext, nodeC);
        bus.WriteLong(nodeB + (uint)GraphicsLayouts.RegionRectanglePrevious, node);
        bus.WriteWord(nodeB + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX, 5);
        bus.WriteWord(nodeB + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY, 5);
        bus.WriteWord(nodeB + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX, 7);
        bus.WriteWord(nodeB + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY, 7);
        bus.WriteLong(nodeC + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(nodeC + (uint)GraphicsLayouts.RegionRectanglePrevious, nodeB);
        bus.WriteWord(nodeC + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX, 8);
        bus.WriteWord(nodeC + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY, 8);
        bus.WriteWord(nodeC + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX, 9);
        bus.WriteWord(nodeC + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY, 9);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 4);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 4);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 8);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 8);
        Execute(
            GraphicsLvo.AndRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1357_9BDFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)5, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)5, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)8, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)8, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(nodeB, bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(region + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)2, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal(0u, bus.ReadLong(nodeB + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(node, bus.ReadLong(nodeB + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)3, bus.ReadWord(nodeB + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)3, bus.ReadWord(nodeB + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal(
            new[] { (nodeC, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u) },
            frees);

        // A disjoint clip removes the compacted chain, publishes the empty
        // header before retirement, and leaves DisposeRegion only the private
        // public Region allocation to return.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 21);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 21);
        Execute(
            GraphicsLvo.AndRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x2468_ACEEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));

        Execute(
            GraphicsLvo.DisposeRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.D[0] = 0x1357_9BDFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (nodeC, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (node, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (nodeB, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (allocationBase, (uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0000_0001u)
            },
            frees);

        Execute(
            GraphicsLvo.NewRegion,
            () => cpu.State.D[0] = 0xDEAD_BEEFu);
        var region2 = allocationBase2 + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Assert.Equal(region2, cpu.State.D[0]);
        bus.WriteLong(region2 + (uint)GraphicsLayouts.RegionRectangle, node2);
        bus.WriteLong(node2 + (uint)GraphicsLayouts.RegionRectangleNext, 0);

        // A tagged Region with a malformed predecessor link also declines
        // before mutation, leaving the provider/portable path authoritative.
        Execute(
            GraphicsLvo.AndRectRegion,
            () =>
            {
                cpu.State.A[0] = region2;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x89AB_CDEFu;
            });
        Assert.Equal(0x89AB_CDEFu, cpu.State.D[0]);
        Assert.Equal(node2, bus.ReadLong(region2 + (uint)GraphicsLayouts.RegionRectangle));

        Execute(
            GraphicsLvo.ClearRegion,
            () =>
            {
                cpu.State.A[0] = region2;
                cpu.State.D[0] = 0x0BAD_F00Du;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(region2 + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(region2 + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Equal(0u, bus.ReadLong(region2 + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Contains(
            (node2, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        Execute(
            GraphicsLvo.DisposeRegion,
            () =>
            {
                cpu.State.A[0] = region2;
                cpu.State.D[0] = 0x1357_9BDFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Contains(
            (allocationBase2, (uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0000_0001u),
            frees);

        // The native Region body reads the marker four bytes before A0 and
        // the complete 12-byte public header.  $FFFF_FFF4 is therefore the
        // final valid aligned public address; the next aligned address must
        // decline before its final header byte could wrap into low memory.
        const uint topRegion = 0xFFFF_FFF4u;
        const uint topRegionPrivatePhysical =
            (topRegion - (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize) &
            0x00FF_FFFFu;
        const uint topRegionPhysical = topRegion & 0x00FF_FFFFu;
        bus.MapWritableMemory(
            topRegionPrivatePhysical,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.WriteWord(topRegionPrivatePhysical, GraphicsLayouts.NativeRegionMarker);
        bus.WriteLong(topRegionPhysical + (uint)GraphicsLayouts.RegionRectangle, 0);
        Execute(
            GraphicsLvo.AndRectRegion,
            () =>
            {
                cpu.State.A[0] = topRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xA0B0_C0D0u;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(topRegionPhysical +
            (uint)GraphicsLayouts.RegionRectangle));
        Execute(
            GraphicsLvo.AndRectRegion,
            () =>
            {
                cpu.State.A[0] = 0xFFFF_FFF6u;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x5566_7788u;
            });
        Assert.Equal(0x5566_7788u, cpu.State.D[0]);

        // A foreign/untagged Region remains available to the resident owner,
        // including through the newly admitted AndRectRegion vector.
        Execute(
            GraphicsLvo.AndRectRegion,
            () =>
            {
                cpu.State.A[0] = foreignRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1020_3040u;
            });
        Assert.Equal(0x1020_3040u, cpu.State.D[0]);
        Assert.Equal(6, frees.Count);

        Execute(
            GraphicsLvo.DisposeRegion,
            () =>
            {
                cpu.State.A[0] = foreignRegion;
                cpu.State.D[0] = 0x2468_ACEEu;
            });
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);
        Assert.Equal(6, frees.Count);
    }

