        bus.MapWritableMemory(clearInteriorHoleFailureMiddleNode,
            new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            allocationBase,
            node,
            0u,
            0u,
            topNode,
            xorAllocationBase,
            xorNode,
            xorEvilAllocationBase,
            andSourceAllocationBase,
            andDestinationAllocationBase,
            andSourceNode,
            andDestinationNode,
            andDestinationNode,
            andDestinationNode,
            clearSplitTopNode,
            clearSplitBottomNode,
            clearVerticalSplitLeftNode,
            clearVerticalSplitRightNode,
            clearUpperLeftCornerRightNode,
            clearUpperLeftCornerBottomNode,
            clearLowerLeftCornerUpperNode,
            clearLowerLeftCornerRightNode,
            clearUpperRightCornerLeftNode,
            clearUpperRightCornerBottomNode,
            clearLowerRightCornerUpperNode,
            clearLowerRightCornerLeftNode,
            clearLowerInteriorTopNode,
            clearLowerInteriorLeftNode,
            clearLowerInteriorRightNode,
            clearUpperInteriorLeftNode,
            clearUpperInteriorRightNode,
            clearUpperInteriorLowerNode,
            clearLeftInteriorTopNode,
            clearLeftInteriorRightNode,
            clearLeftInteriorBottomNode,
            clearRightInteriorTopNode,
            clearRightInteriorMiddleNode,
            clearRightInteriorBottomNode,
            clearInteriorHoleTopNode,
            clearInteriorHoleMiddleNode,
            clearInteriorHoleRightNode,
            clearInteriorHoleBottomNode,
            clearInteriorHoleFailureTopNode,
            clearInteriorHoleFailureMiddleNode,
            0u,
            clearVerticalSplitRollbackNode,
            0u
        });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 1024)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[vector],
                stack + 0x80u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} Region body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xC001_C0DEu);
        Assert.Equal(region, cpu.State.D[0]);

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x89AB_CDEFu;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 9);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 19);
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1020_3040u;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1357_9BDFu;
            });

        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u)
            },
            allocations);
        Assert.Equal((ushort)10, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(
            region + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)4, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)5, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));

        // A canonical one-node Region can claim a contained union as a
        // no-growth success without another allocation or a header rewrite.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 11);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 21);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 13);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 24);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x2468_ACEEu;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));

        // A containing input remains one rectangle, so the native body
        // rewrites the existing node and publishes the expanded header.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 8);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 18);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 16);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 27);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1357_9BDFu;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Equal((ushort)8, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)27, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)8, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)9, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));

        // Equal vertical spans with horizontal overlap still form one
        // rectangle, so the native body coalesces the horizontal envelope.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 15);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 18);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 19);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 27);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xA1B2_C3D4u;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)8, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)19, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)11, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 8);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 25);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 19);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 30);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xA1B2_C3D4u;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)12, bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));

        // A disjoint ClearRectRegion has no pixels to subtract. The native
        // no-op arm validates the one-node canonical list and returns TRUE
        // without allocating or touching the public Region.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 45);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 45);
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x7654_3210u;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)8, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)19, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)30, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));

        // A second disjoint no-op must remain allocation-free after the
        // earlier Region envelope changes.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 45);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 45);
        Execute(
            GraphicsLvo.ClearRectRegion,
