        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 5);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 15);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 12);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 32);
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1357_9BDFu;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(3, allocations.Count);
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)13, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)19, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)30, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)6, bus.ReadWord(node +
            (uint)GraphicsLayouts.RegionRectangleBounds +
