        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 5);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 27);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 22);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 32);
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x5566_7788u;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(3, allocations.Count);
        Assert.Equal(node, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)13, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)23, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)15, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)26, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)3, bus.ReadWord(node +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));

        // A clear Rectangle covering the validated canonical node has the
        // empty result. Native code publishes the portable canonical empty
        // header [0,0,-1,-1] and null head before retiring the old node.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 5);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 15);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 22);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 32);
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xBADC_0DE0u;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(3, allocations.Count);
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(region + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0xFFFF_FFFFu, bus.ReadLong(region + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (node, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // A native-owned empty Region retains its empty header when Exec
        // cannot allocate the first node, and the vector returns FALSE.
        bus.WriteWord(failedAllocationBase, GraphicsLayouts.NativeRegionMarker);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = failedRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xDEAD_BEEFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(4, allocations.Count);
        Assert.Equal(0u, bus.ReadLong(failedRegion + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Single(frees);

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);

        // The full Region header plus its private prefix ends exactly at the
        // 32-bit address limit. The final aligned pointer is valid; the next
        // aligned value must decline before its header would wrap into low
        // memory.
        const uint topRegion = 0xFFFF_FFF4u;
        const uint topRegionPrivatePhysical =
            (topRegion - (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize) &
            0x00FF_FFFFu;
        const uint topRegionPhysical = topRegion & 0x00FF_FFFFu;
        bus.MapWritableMemory(
            topRegionPrivatePhysical,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.WriteWord(topRegionPrivatePhysical, GraphicsLayouts.NativeRegionMarker);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = topRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x0BAD_F00Du;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(5, allocations.Count);
        Assert.Equal(topNode, bus.ReadLong(topRegionPhysical +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(topRegionPhysical +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)25, bus.ReadWord(topRegionPhysical +
            (uint)GraphicsLayouts.RectangleMaxY));

        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = 0xFFFF_FFF6u;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x5566_7788u;
