        Assert.Equal(5, allocations.Count);

        // XOR of an empty native-owned Region is the OR allocation identity.
        var xorRegion = xorAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x5566_7788u);
        Assert.Equal(xorRegion, cpu.State.D[0]);
        Execute(
            GraphicsLvo.XorRectRegion,
            () =>
            {
                cpu.State.A[0] = xorRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1020_3040u;
