        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(7, allocations.Count);
        Assert.Equal(xorNode, bus.ReadLong(xorRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(xorRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(xorRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(xorRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(xorRegion + (uint)GraphicsLayouts.RectangleMaxY));

        // Equal canonical rectangles XOR to empty. The native arm retires the
        // validated public node and clears the Region header without an
        // allocation or a general overlap-subtraction transaction.
        Execute(
            GraphicsLvo.XorRectRegion,
            () =>
            {
                cpu.State.A[0] = xorRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xF00D_CAFEu;
