        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(7, allocations.Count);
        Assert.Equal(0u, bus.ReadLong(xorRegion + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(xorRegion + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(xorRegion + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (xorNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
