        var xorEvilRegion = xorEvilAllocationBase +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x0BAD_F00Du);
        Assert.Equal(xorEvilRegion, cpu.State.D[0]);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 9);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 19);
        Execute(
            GraphicsLvo.XorRectRegion,
            () =>
            {
                cpu.State.A[0] = xorEvilRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x5566_7788u;
