        var andSource = andSourceAllocationBase +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var andDestination = andDestinationAllocationBase +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x0123_4567u);
        Assert.Equal(andSource, cpu.State.D[0]);
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x7654_3210u);
        Assert.Equal(andDestination, cpu.State.D[0]);
