        bus.WriteWord(clearSplitRegion + (uint)GraphicsLayouts.RectangleMaxY, 30);
        bus.WriteLong(clearSplitRegion + (uint)GraphicsLayouts.RegionRectangle, clearSplitOriginalNode);
        bus.WriteLong(clearSplitOriginalNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
