        Assert.Equal((ushort)13, bus.ReadWord(clearSplitRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(clearSplitRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)15, bus.ReadWord(clearSplitRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)30, bus.ReadWord(clearSplitRegion + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(clearSplitBottomNode, bus.ReadLong(clearSplitTopNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(clearSplitRegion + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(clearSplitTopNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u, bus.ReadLong(clearSplitBottomNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(clearSplitTopNode, bus.ReadLong(clearSplitBottomNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0, bus.ReadWord(clearSplitTopNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)3, bus.ReadWord(clearSplitTopNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)6, bus.ReadWord(clearSplitBottomNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10, bus.ReadWord(clearSplitBottomNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Contains(
            (clearSplitOriginalNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // The symmetric full-height clear must publish the left/right chain
        // in x order while retaining the public header and retiring the
        // former canonical node only after both replacements are ready.
        bus.WriteWord(clearVerticalSplitAllocationBase, GraphicsLayouts.NativeRegionMarker);
        bus.WriteWord(clearVerticalSplitRegion + (uint)GraphicsLayouts.RectangleMinX, 13);
