        bus.WriteWord(clearVerticalSplitFailureRegion + (uint)GraphicsLayouts.RectangleMaxX, 15);
        bus.WriteWord(clearVerticalSplitFailureRegion + (uint)GraphicsLayouts.RectangleMaxY, 30);
        bus.WriteLong(clearVerticalSplitFailureRegion + (uint)GraphicsLayouts.RegionRectangle,
            clearVerticalSplitFailureOriginalNode);
        bus.WriteLong(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious,
            clearVerticalSplitFailureRegion + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteWord(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX, 0);
        bus.WriteWord(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY, 0);
        bus.WriteWord(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX, 2);
        bus.WriteWord(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY, 10);
        var allocationsBeforeVerticalSplitFailure = allocations.Count;
        Execute(
            GraphicsLvo.ClearRectRegion,
            () =>
            {
                cpu.State.A[0] = clearVerticalSplitFailureRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0xBADC_0DEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(allocationsBeforeVerticalSplitFailure + 2, allocations.Count);
        Assert.Equal(clearVerticalSplitFailureOriginalNode,
            bus.ReadLong(clearVerticalSplitFailureRegion +
                (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)0, bus.ReadWord(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)2, bus.ReadWord(clearVerticalSplitFailureOriginalNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Contains(
            (clearVerticalSplitRollbackNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.DoesNotContain(
            (clearVerticalSplitFailureOriginalNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
    }

    [Fact]
    public void NativeGraphicsOrAndXorRegionRegionPublishDisjointCanonicalReplacementListsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0085_0000;
        const uint execBase = 0x0075_0000;
        const uint sourceAllocation = 0x00D7_0000;
        const uint sourceNode = 0x00D7_1000;
        const uint containedDestinationAllocation = 0x00D7_D000;
        const uint containedDestinationNode = 0x00D7_E000;
        const uint disjointDestinationAllocation = 0x00D7_F000;
        const uint disjointDestinationNode = 0x00D8_0000;
        const uint equalXorDestinationNode = 0x00D8_1000;
        const uint overlapDestinationAllocation = 0x00D7_B000;
        const uint overlapDestinationNode = 0x00D7_C000;
        const uint orDestinationAllocation = 0x00D7_2000;
        const uint orDestinationNode = 0x00D7_3000;
        const uint orFirstReplacement = 0x00D7_4000;
        const uint orSecondReplacement = 0x00D7_5000;
        const uint xorDestinationAllocation = 0x00D7_6000;
        const uint xorDestinationNode = 0x00D7_7000;
        const uint xorFirstReplacement = 0x00D7_8000;
        const uint xorSecondReplacement = 0x00D7_9000;
        const uint rectangle = 0x00D7_A000;
        const uint stack = 0x00C5_0000;
        const uint returnAddress = 0x00F5_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var containedDestination = containedDestinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var disjointDestination = disjointDestinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var overlapDestination = overlapDestinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var orDestination = orDestinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var xorDestination = xorDestinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                      sourceAllocation, sourceNode, containedDestinationAllocation,
                      containedDestinationNode, disjointDestinationAllocation,
                      disjointDestinationNode, equalXorDestinationNode,
                      overlapDestinationAllocation,
                     overlapDestinationNode, orDestinationAllocation,
                     orDestinationNode, orFirstReplacement, orSecondReplacement,
                     xorDestinationAllocation, xorDestinationNode,
                     xorFirstReplacement, xorSecondReplacement, rectangle, stack
                 })
        {
            var bytes = address is sourceAllocation or containedDestinationAllocation or
                disjointDestinationAllocation or overlapDestinationAllocation or
                orDestinationAllocation or xorDestinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : address == rectangle ? GraphicsLayouts.RectangleSize
                : address == stack ? 0x200 : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            sourceAllocation, sourceNode,
            containedDestinationAllocation, containedDestinationNode,
            disjointDestinationAllocation, disjointDestinationNode,
            equalXorDestinationNode,
            overlapDestinationAllocation, overlapDestinationNode,
            orDestinationAllocation, orDestinationNode,
            orFirstReplacement, orSecondReplacement,
            xorDestinationAllocation, xorDestinationNode,
            xorFirstReplacement, xorSecondReplacement
        });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 4096)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} Region body did not return (fallback {fallbackEntryOffset}).");
        }

        void WriteRectangle(short minX, short minY, short maxX, short maxY)
        {
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void Seed(uint region, short minX, short minY, short maxX, short maxY)
        {
            WriteRectangle(minX, minY, maxX, maxY);
            Execute(GraphicsLvo.OrRectRegion, () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
            });
            Assert.Equal(1u, cpu.State.D[0]);
        }

        void AssertDisjointTransaction(
            GraphicsLvo vector,
            uint destination,
            uint oldNode,
            uint firstReplacement,
            uint secondReplacement)
        {
            Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xA1B2_C3D4u);
            Assert.Equal(destination, cpu.State.D[0]);
            Seed(destination, 30, 40, 34, 45);
            Execute(vector, () =>
            {
                cpu.State.A[0] = source;
                cpu.State.A[1] = destination;
                cpu.State.D[0] = 0x5566_7788u;
            });

            Assert.Equal(1u, cpu.State.D[0]);
            Assert.Equal((ushort)10, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)20, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)34, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)45, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(firstReplacement, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(secondReplacement, bus.ReadLong(firstReplacement +
                (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(firstReplacement + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u, bus.ReadLong(secondReplacement +
                (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(firstReplacement, bus.ReadLong(secondReplacement +
                (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal((ushort)0, bus.ReadWord(firstReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)0, bus.ReadWord(firstReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)4, bus.ReadWord(firstReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)5, bus.ReadWord(firstReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal((ushort)20, bus.ReadWord(secondReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)20, bus.ReadWord(secondReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)24, bus.ReadWord(secondReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)25, bus.ReadWord(secondReplacement +
                (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Contains(
                (oldNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                frees);
        }

        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x0102_0304u);
        Assert.Equal(source, cpu.State.D[0]);
        Seed(source, 10, 20, 14, 25);
        Assert.Equal(sourceNode, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // The source and destination may alias for OR.  The union is already
        // complete; the native arm must not reinterpret the Region header as
        // a Rectangle or allocate/retire its sole public node.
        Execute(GraphicsLvo.OrRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = source;
            cpu.State.D[0] = 0x1357_9BDFu;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(sourceNode, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(source + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(source + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(source + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(source + (uint)GraphicsLayouts.RectangleMaxY));

        // A canonical destination wholly inside the canonical source is
        // already the AND result and must not allocate or rewrite either
        // public envelope.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x1020_3040u);
        Assert.Equal(containedDestination, cpu.State.D[0]);
        Seed(containedDestination, 11, 21, 13, 24);
        Execute(GraphicsLvo.AndRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = containedDestination;
            cpu.State.D[0] = 0x5566_7788u;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(4, allocations.Count);
        Assert.Equal(containedDestinationNode, bus.ReadLong(containedDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)11, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)21, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)13, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)24, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMaxY));

        // The complementary containment still has a single-rectangle result.
        // The native AND body rewrites the existing destination node to the
        // source envelope without changing ownership or allocating storage.
        Seed(containedDestination, 8, 18, 16, 27);
        Execute(GraphicsLvo.AndRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = containedDestination;
            cpu.State.D[0] = 0xA1B2_C3D4u;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(4, allocations.Count);
        Assert.Equal(containedDestinationNode, bus.ReadLong(containedDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(containedDestination +
            (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)4, bus.ReadWord(containedDestinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)5, bus.ReadWord(containedDestinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY));

        // Disjoint canonical rectangles have an empty AND result. The native
        // arm retires precisely the admitted destination node, then clears
        // both its bounds words and the public list head without allocation.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x0BAD_F00Du);
        Assert.Equal(disjointDestination, cpu.State.D[0]);
        Seed(disjointDestination, 30, 40, 34, 45);
        Execute(GraphicsLvo.AndRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = disjointDestination;
            cpu.State.D[0] = 0xDEAD_BEEFu;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(6, allocations.Count);
        Assert.Equal(0u, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (disjointDestinationNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // Equal canonical Regions XOR to an empty destination. The native arm
        // retires only its fully admitted destination node; source ownership
        // and bounds remain unchanged.
        Seed(disjointDestination, 10, 20, 14, 25);
        Assert.Equal(equalXorDestinationNode, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Execute(GraphicsLvo.XorRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = disjointDestination;
            cpu.State.D[0] = 0xCAFE_BABEu;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(7, allocations.Count);
        Assert.Equal(0u, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(disjointDestination +
            (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (equalXorDestinationNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // Union alone may reuse the same canonical Rectangle publisher for
        // overlap: unlike XOR, it does not require the no-overlap identity.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x1122_3344u);
        Assert.Equal(overlapDestination, cpu.State.D[0]);
        Seed(overlapDestination, 12, 20, 18, 25);
        Execute(GraphicsLvo.AndRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = overlapDestination;
            cpu.State.D[0] = 0x5566_7788u;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(9, allocations.Count);
        Assert.Equal(overlapDestinationNode, bus.ReadLong(overlapDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)12, bus.ReadWord(overlapDestination +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)14, bus.ReadWord(overlapDestination +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)2, bus.ReadWord(overlapDestinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));

        // Restore the wider destination before exercising the separate OR
        // coalescing path below.
        Seed(overlapDestination, 12, 20, 18, 25);
        Execute(GraphicsLvo.OrRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = overlapDestination;
            cpu.State.D[0] = 0x5566_7788u;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(9, allocations.Count);
        Assert.Equal(overlapDestinationNode, bus.ReadLong(overlapDestination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(overlapDestination +
            (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(overlapDestination +
            (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)8, bus.ReadWord(overlapDestinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX));

        AssertDisjointTransaction(
            GraphicsLvo.OrRegionRegion,
            orDestination,
            orDestinationNode,
            orFirstReplacement,
            orSecondReplacement);
        AssertDisjointTransaction(
            GraphicsLvo.XorRegionRegion,
            xorDestination,
            xorDestinationNode,
            xorFirstReplacement,
            xorSecondReplacement);
        Assert.Equal(17, allocations.Count);
        Assert.Equal(4, frees.Count);

        // XOR of a Region with itself is the empty set.  The existing native
        // identical-rectangle arm must retire the shared node exactly once
        // and publish the empty destination header.
        Execute(GraphicsLvo.XorRegionRegion, () =>
        {
            cpu.State.A[0] = source;
            cpu.State.A[1] = source;
            cpu.State.D[0] = 0x2468_ACE0u;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(source + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(source + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (sourceNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.Equal(5, frees.Count);

        // Aliasing alone is not sufficient admission: a null/foreign pair
        // must retain the caller's D0 and remain on the shared fallback.
        Execute(GraphicsLvo.OrRegionRegion, () =>
        {
            cpu.State.A[0] = 0;
            cpu.State.A[1] = 0;
            cpu.State.D[0] = 0x0BAD_F00Du;
        });
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsOrAndXorRegionRegionPrependAndInsertOneSourceNodeIntoCanonicalTwoNodeDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0088_0000;
        const uint execBase = 0x0078_0000;
        const uint sourceAllocation = 0x00E0_0000;
        const uint sourceNode = 0x00E0_1000;
        const uint destinationAllocation = 0x00E0_2000;
        const uint destinationFirstNode = 0x00E0_3000;
        const uint destinationSecondNode = 0x00E0_4000;
        const uint orReplacementNode = 0x00E0_5000;
        const uint xorReplacementNode = 0x00E0_6000;
        const uint stack = 0x00C8_0000;
        const uint returnAddress = 0x00F8_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode,
                     orReplacementNode, xorReplacementNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { orReplacementNode, xorReplacementNode });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} one/two-node body did not return (fallback {fallbackEntryOffset}).");
        }

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint head)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 10);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, head);
        }

        void ResetDestinationChain()
        {
            WriteRegion(destinationAllocation, destination, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                0, 10, 8, 13);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                2, 20, 10, 25);
        }

        void SetSourceVerticalSpan(short minY, short maxY)
        {
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                0, minY, 8, maxY);
        }

        void AssertMiddleInsertion(uint insertedNode)
        {
            // The strict-gap native publisher tightens Region.Bounds and
            // rebases all three relative rectangles to that new origin.
            Assert.Equal((ushort)0,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)10,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)10,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)25,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(insertedNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(insertedNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal((ushort)0,
                bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)3,
                bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal((ushort)10,
                bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)15,
                bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal((ushort)0,
                bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)5,
                bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)8,
                bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            0, 0, 8, 4);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            0, 10, 8, 13);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            2, 20, 10, 25);

        Execute(GraphicsLvo.OrRegionRegion, 0x1122_3344u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Empty(frees);
        Assert.Equal(orReplacementNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(orReplacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(orReplacementNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(orReplacementNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)8, bus.ReadWord(orReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)4, bus.ReadWord(orReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Restore the original public head and predecessor before exercising
        // the XOR wrapper; the strict vertical gaps make its result identical.
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        Execute(GraphicsLvo.XorRegionRegion, 0x5566_7788u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(xorReplacementNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(xorReplacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(xorReplacementNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // A failed allocation must leave the original public destination
        // chain untouched and return FALSE without retiring any node.
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xA1B2_C3D4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Empty(frees);
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Insert a strictly separated source between the two destination
        // nodes. OR and XOR share the same sorted replacement topology here.
        SetSourceVerticalSpan(15, 18);
        ResetDestinationChain();
        allocationResults.Enqueue(orReplacementNode);
        Execute(GraphicsLvo.OrRegionRegion, 0x3141_5926u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(4, allocations.Count);
        AssertMiddleInsertion(orReplacementNode);
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        ResetDestinationChain();
        allocationResults.Enqueue(xorReplacementNode);
        Execute(GraphicsLvo.XorRegionRegion, 0x2718_2818u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(5, allocations.Count);
        AssertMiddleInsertion(xorReplacementNode);
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Failure on this ordering is also atomic: neither old reciprocal link
        // changes, and no public node is retired.
        ResetDestinationChain();
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0x6A09_E667u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(6, allocations.Count);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Empty(frees);

    }

    [Fact]
    public void NativeGraphicsOrAndXorRegionRegionAppendOneSourceNodeBelowCanonicalTwoNodeDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x009A_0000;
        const uint execBase = 0x0082_0000;
        const uint sourceAllocation = 0x00F2_0000;
        const uint sourceNode = 0x00F2_1000;
        const uint destinationAllocation = 0x00F2_2000;
        const uint destinationFirstNode = 0x00F2_3000;
        const uint destinationSecondNode = 0x00F2_4000;
        const uint orReplacementNode = 0x00F2_5000;
        const uint xorReplacementNode = 0x00F2_6000;
        const uint stack = 0x00D6_0000;
        const uint returnAddress = 0x00FF_2000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode,
                     orReplacementNode, xorReplacementNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { orReplacementNode, xorReplacementNode });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void SeedRegions()
        {
            bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 10);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            }
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceNode);
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                0, 20, 8, 25);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                0, 0, 8, 4);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                2, 10, 10, 15);
        }

        void Execute(GraphicsLvo vector, uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} reverse one/two-node body did not return (fallback {fallbackEntryOffset}).");
        }

        void AssertAppended(uint replacement)
        {
            Assert.Equal(1u, cpu.State.D[0]);
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(replacement,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(replacement + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u,
                bus.ReadLong(replacement + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal((ushort)0,
                bus.ReadWord(replacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)20,
                bus.ReadWord(replacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)8,
                bus.ReadWord(replacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)25,
                bus.ReadWord(replacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(sourceNode,
                bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        }

        SeedRegions();
        Execute(GraphicsLvo.OrRegionRegion, 0x1122_3344u);
        AssertAppended(orReplacementNode);
        Assert.Single(allocations);
        Assert.Empty(frees);

        SeedRegions();
        Execute(GraphicsLvo.XorRegionRegion, 0x5566_7788u);
        AssertAppended(xorReplacementNode);
        Assert.Equal(2, allocations.Count);
        Assert.Empty(frees);

        SeedRegions();
        allocationResults.Enqueue(0u);
        Execute(GraphicsLvo.OrRegionRegion, 0xA1B2_C3D4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(3, allocations.Count);
        Assert.Empty(frees);
    }

    [Fact]
    public void NativeGraphicsOrRegionRegionReplacesFirstOrWidensSecondCanonicalTwoNodeDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0089_0000;
        const uint execBase = 0x0079_0000;
        const uint sourceAllocation = 0x00E8_0000;
        const uint sourceNode = 0x00E8_1000;
        const uint destinationAllocation = 0x00E8_2000;
        const uint destinationFirstNode = 0x00E8_3000;
        const uint destinationSecondNode = 0x00E8_4000;
        const uint replacementNode = 0x00E8_5000;
        const uint stack = 0x00C9_0000;
        const uint returnAddress = 0x00F9_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode, replacementNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { replacementNode });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native OrRegionRegion contained overlap did not return (fallback {fallbackEntryOffset}).");
        }

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint head)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, head);
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            0, 0, 10, 10);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            2, 2, 8, 8);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            0, 20, 20, 25);

        Execute(0x1122_3344u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Equal((ushort)25,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(replacementNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(replacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(replacementNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(replacementNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Contains(
            (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.Equal((ushort)0, bus.ReadWord(replacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)10, bus.ReadWord(replacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)10, bus.ReadWord(replacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Reset the old destination chain and verify a failed replacement
        // leaves it public and does not retire the old first node again.
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            2, 2, 8, 8);
        bus.WriteLong(
            destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destinationFirstNode);
        allocationResults.Enqueue(0);
        Execute(0xA1B2_C3D4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Single(frees);

        // Mirror the transaction: preserve the upper node and widen only the
        // lower node in place to cover the source rectangle.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            0, 20, 20, 28);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            0, 0, 20, 10);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            2, 22, 18, 26);
        Execute(0x5566_7788u);

        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)28,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)28,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(2, allocations.Count);
        Assert.Single(frees);
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)0,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)28,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));

    }

    [Fact]
    public void NativeGraphicsOrRegionRegionCollapsesSourceContainingBothDestinationNodesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0092_0000;
        const uint execBase = 0x007E_8000;
        const uint sourceAllocation = 0x00EA_0000;
        const uint sourceNode = 0x00EA_1000;
        const uint destinationAllocation = 0x00EA_2000;
        const uint destinationFirstNode = 0x00EA_3000;
        const uint destinationSecondNode = 0x00EA_4000;
        const uint replacementNode = 0x00EA_5000;
        const uint stack = 0x00CE_8000;
        const uint returnAddress = 0x00FE_8000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode, replacementNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegions()
        {
            bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 24);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 34);
            }
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceNode);
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                0, 0, 20, 30);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                2, 2, 8, 8);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                4, 20, 10, 25);
        }

        WriteRegions();
        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { replacementNode });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native OrRegionRegion source-containing-both body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(0x1357_9BDFu);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Contains(
            (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u),
            frees);
        Assert.Contains(
            (destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u),
            frees);
        Assert.Equal(replacementNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(replacementNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u,
            bus.ReadLong(replacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0x0000_0000u,
            bus.ReadLong(replacementNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0014_001Eu,
            bus.ReadLong(replacementNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        WriteRegions();
        allocationResults.Enqueue(0);
        Execute(0x2468_ACE0u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(2, frees.Count);
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
    }

