    [Fact]
    public void NativeGraphicsOrRegionRegionAcceptsTwoNodeSourceContainedByOneNodeDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
