            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        _ = fallbackEntryOffset;
    }

    [Fact]
    public void NativeGraphicsOrAndXorRegionRegionAppendsTwoNodeSourceAfterCanonicalTwoNodeDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0099_0000;
        const uint execBase = 0x0081_0000;
        const uint sourceAllocation = 0x00F1_0000;
        const uint sourceFirstNode = 0x00F1_1000;
        const uint sourceSecondNode = 0x00F1_2000;
        const uint destinationAllocation = 0x00F1_3000;
        const uint destinationFirstNode = 0x00F1_4000;
        const uint destinationSecondNode = 0x00F1_5000;
        const uint orFirstReplacement = 0x00F1_6000;
        const uint orSecondReplacement = 0x00F1_7000;
        const uint xorFirstReplacement = 0x00F1_8000;
        const uint xorSecondReplacement = 0x00F1_9000;
        const uint stack = 0x00D5_0000;
        const uint returnAddress = 0x00FF_1000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceFirstNode, sourceSecondNode,
                     destinationAllocation, destinationFirstNode, destinationSecondNode,
                     orFirstReplacement, orSecondReplacement,
                     xorFirstReplacement, xorSecondReplacement
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void SeedRegions()
        {
            bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 24);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 34);
            }
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceFirstNode);
            WriteNode(
                sourceFirstNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                sourceSecondNode,
                2, 20, 8, 24);
            WriteNode(
                sourceSecondNode,
                sourceFirstNode,
                0,
                10, 26, 18, 32);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                0, 0, 20, 10);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                0, 12, 20, 18);
        }

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            orFirstReplacement, orSecondReplacement,
            xorFirstReplacement, xorSecondReplacement
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[vector],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} reverse two-node disjoint body did not return (fallback {fallbackEntryOffset}).");
        }

        void AssertAppended(uint firstReplacement, uint secondReplacement)
        {
            Assert.Equal(1u, cpu.State.D[0]);
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(firstReplacement,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(firstReplacement + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(secondReplacement,
                bus.ReadLong(firstReplacement + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(firstReplacement,
                bus.ReadLong(secondReplacement + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u,
                bus.ReadLong(secondReplacement + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal((ushort)2,
                bus.ReadWord(firstReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)20,
                bus.ReadWord(firstReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)8,
                bus.ReadWord(firstReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)24,
                bus.ReadWord(firstReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal((ushort)10,
                bus.ReadWord(secondReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)26,
                bus.ReadWord(secondReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)18,
                bus.ReadWord(secondReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)32,
                bus.ReadWord(secondReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(sourceFirstNode,
                bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(sourceSecondNode,
                bus.ReadLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0u,
                bus.ReadLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        }

        SeedRegions();
        Execute(GraphicsLvo.OrRegionRegion, 0x1357_9BDFu);
        AssertAppended(orFirstReplacement, orSecondReplacement);
        Assert.Equal(2, allocations.Count);
        Assert.Empty(frees);

        SeedRegions();
        Execute(GraphicsLvo.XorRegionRegion, 0x2468_ACF0u);
        AssertAppended(xorFirstReplacement, xorSecondReplacement);
        Assert.Equal(4, allocations.Count);
        Assert.Empty(frees);

        // A first-allocation failure must restore the six-word private frame
        // and leave the destination chain unpublished.
        SeedRegions();
        allocationResults.Enqueue(0u);
        Execute(GraphicsLvo.OrRegionRegion, 0xDEAD_BEEFu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(5, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
    }

