                bus.ReadWord(secondReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)26,
                bus.ReadWord(secondReplacement + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(sourceFirstNode,
                bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(sourceSecondNode,
                bus.ReadLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0u,
                bus.ReadLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        }

        SeedRegions();
        Execute(GraphicsLvo.OrRegionRegion, 0x1357_9BDFu);
        AssertAppended(orFirstReplacement, orSecondReplacement);
        Assert.Equal(2, allocations.Count);
        Assert.Empty(frees);

        SeedRegions();
        Execute(GraphicsLvo.XorRegionRegion, 0x2468_ACF0u);
        AssertAppended(xorFirstReplacement, xorSecondReplacement);
        Assert.Equal(4, allocations.Count);
        Assert.Empty(frees);

        SeedRegions();
        allocationResults.Enqueue(0u);
        Execute(GraphicsLvo.OrRegionRegion, 0xDEAD_BEEFu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(5, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(destinationNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
    }

    [Fact]
    public void NativeGraphicsOrRegionRegionCoalescesEqualSpanOverlapIntoCanonicalTwoNodeDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x008E_0000;
        const uint execBase = 0x007E_0000;
        const uint sourceAllocation = 0x00E9_0000;
        const uint sourceNode = 0x00E9_1000;
        const uint destinationAllocation = 0x00E9_2000;
        const uint destinationFirstNode = 0x00E9_3000;
        const uint destinationSecondNode = 0x00E9_4000;
        const uint stack = 0x00CE_0000;
        const uint returnAddress = 0x00FE_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint head)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 40);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 40);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, head);
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            15, 10, 25, 20);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            10, 10, 20, 20);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            0, 25, 20, 30);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
            stack + 0x80u);
        cpu.State.A[0] = source;
        cpu.State.A[1] = destination;
        cpu.State.D[0] = 0xC0DE_5340u;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMinX)));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMinY)));
        Assert.Equal((short)25, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMaxX)));
        Assert.Equal((short)30, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMaxY)));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)10, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)25, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)0, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));

        // The vertical mirror keeps the equal X span and widens the first
        // node's Y range while preserving the lower second node.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            10, 15, 20, 25);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            10, 10, 20, 20);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            0, 30, 20, 35);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
            stack + 0x80u);
        cpu.State.A[0] = source;
        cpu.State.A[1] = destination;
        cpu.State.D[0] = 0xC0DE_5350u;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMinX)));
        Assert.Equal((short)10, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMinY)));
        Assert.Equal((short)20, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMaxX)));
        Assert.Equal((short)35, unchecked((short)bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMaxY)));
        Assert.Equal((ushort)10, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)0, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)15, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        _ = fallbackEntryOffset;
    }

    [Fact]
