            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint head)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 35);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, head);
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            8, 20, 20, 30);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            0, 0, 20, 10);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            0, 20, 12, 30);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
            stack + 0x80u);
        cpu.State.A[0] = source;
        cpu.State.A[1] = destination;
        cpu.State.D[0] = 0xC0DE_58A0u;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)30,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)8,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));

        // The vertical mirror overlaps the second destination node while the
        // first node remains above it. Only the second node widens in place.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            0, 18, 20, 26);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            0, 0, 20, 10);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            0, 20, 20, 30);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
            stack + 0x80u);
        cpu.State.A[0] = source;
        cpu.State.A[1] = destination;
        cpu.State.D[0] = 0xC0DE_58B0u;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(
            destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)18,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)30,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)18,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)26,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        _ = fallbackEntryOffset;
    }

    [Fact]
    public void NativeGraphicsOrRegionRegionCoalescesEqualSpanCrossingOneNodeOverlapOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0096_0000;
        const uint sourceAllocation = 0x00F0_0000;
        const uint sourceNode = 0x00F0_1000;
        const uint destinationAllocation = 0x00F0_2000;
        const uint destinationNode = 0x00F0_3000;
        const uint stack = 0x00D6_0000;
        const uint returnAddress = 0x0106_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, 0); // the coalescing arm must not resolve Exec
        foreach (var address in new[] { sourceAllocation, sourceNode, destinationAllocation, destinationNode })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        void WriteNode(uint node, uint previous, short minX, short maxX)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, 10);
        }

        void WriteRegion(uint allocation, uint region, uint node)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 10);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, node);
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 8, 20);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 12);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion], stack + 0x80u);
        cpu.State.A[0] = source;
        cpu.State.A[1] = destination;
        cpu.State.D[0] = 0xC0DE_5660u;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal(destinationNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)10,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)8,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        _ = fallbackEntryOffset;
    }

    [Fact]
    public void NativeGraphicsOrRegionRegionInsertsGapAndTopBottomResidualStripsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0094_0000;
        const uint execBase = 0x007A_0000;
        const uint sourceAllocation = 0x00F8_0000;
        const uint sourceNode = 0x00F8_1000;
        const uint destinationAllocation = 0x00F8_2000;
        const uint destinationFirstNode = 0x00F8_3000;
        const uint destinationSecondNode = 0x00F8_4000;
        const uint insertedNode = 0x00F8_5000;
        const uint bottomResidualNode = 0x00F8_6000;
        const uint stack = 0x00DE_0000;
        const uint returnAddress = 0x010E_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode, insertedNode,
                     bottomResidualNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>();
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegions(
            bool bottomOverlap = false,
            bool topOverlap = false,
            bool bothProtrusions = false,
            bool rightXOverhang = false,
            bool leftXOverhang = false,
            bool bothXOverhang = false)
        {
            foreach (var allocation in new[] { sourceAllocation, destinationAllocation })
                bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX,
                    leftXOverhang || bothXOverhang ? unchecked((ushort)-5) : (ushort)0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX,
                    rightXOverhang || leftXOverhang || bothXOverhang ? (ushort)25 : (ushort)20);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            }
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceNode);
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                bothXOverhang || leftXOverhang ? (short)0 : rightXOverhang ? (short)15 : (short)4,
                rightXOverhang || leftXOverhang || bothXOverhang ? (short)2 :
                    topOverlap || bottomOverlap || bothProtrusions ? (short)3 : (short)10,
                bothXOverhang ? (short)30 : leftXOverhang ? (short)10 : rightXOverhang ? (short)25 : (short)16,
                rightXOverhang || leftXOverhang || bothXOverhang ? (short)3 :
                    bothProtrusions ? (short)12 :
                        topOverlap ? (short)7 : bottomOverlap ? (short)10 : (short)16);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                leftXOverhang || bothXOverhang ? (short)5 : (short)0,
                topOverlap || bothProtrusions ? (short)5 : (short)0,
                leftXOverhang || bothXOverhang ? (short)25 : (short)20,
                topOverlap || bothProtrusions ? (short)10 : (short)5);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                leftXOverhang || bothXOverhang ? (short)5 : (short)0,
                20,
                leftXOverhang || bothXOverhang ? (short)30 : (short)20,
                30);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native OrRegionRegion insertion did not return (fallback {fallbackEntryOffset}).");
        }

        (ushort MinX, ushort MinY, ushort MaxX, ushort MaxY) ReadNodeBounds(uint node)
        {
            var bounds = node + (uint)GraphicsLayouts.RegionRectangleBounds;
            return (
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMinX),
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMinY),
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMaxX),
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMaxY));
        }

        void AssertOldRightOverhangChain()
        {
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(((ushort)0, (ushort)0, (ushort)20, (ushort)5),
                ReadNodeBounds(destinationFirstNode));
            Assert.Equal((ushort)25,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        }

        void AssertOldLeftOverhangChain()
        {
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(((ushort)5, (ushort)0, (ushort)25, (ushort)5),
                ReadNodeBounds(destinationFirstNode));
            Assert.Equal(unchecked((ushort)-5),
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)25,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal(((ushort)5, (ushort)20, (ushort)30, (ushort)30),
                ReadNodeBounds(destinationSecondNode));
        }

        void AssertOldBothOverhangChain()
        {
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(((ushort)5, (ushort)0, (ushort)25, (ushort)5),
                ReadNodeBounds(destinationFirstNode));
            Assert.Equal(((ushort)5, (ushort)20, (ushort)30, (ushort)30),
                ReadNodeBounds(destinationSecondNode));
            Assert.Equal(unchecked((ushort)-5),
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)25,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        }

        WriteRegions();
        allocationResults.Enqueue(insertedNode);
        Execute(0xBEEF_1001u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Equal((uint)GraphicsLayouts.RegionRectangleSize, allocations[0].Size);
        Assert.Equal(1u, allocations[0].Flags);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)4,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)10,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // A strictly interior source that overlaps the first node and
        // protrudes below it contributes only the lower residual strip.
        WriteRegions(bottomOverlap: true);
        allocationResults.Enqueue(insertedNode);
        Execute(0xBEEF_1002u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)4,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)6,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)10,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)3,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)20,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)30,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));

        // A source protruding above the first node is prepended as only its
        // exposed top strip, with the destination head's sentinel backlink.
        WriteRegions(topOverlap: true);
        allocationResults.Enqueue(insertedNode);
        Execute(0xBEEF_1003u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(3, allocations.Count);
        Assert.Equal(insertedNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)4,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)1,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)2,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)7,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)17,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)27,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)3,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)30,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)7,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));

        // Both partial-overlap orientations must roll back without publishing
        // any provisional node when Exec cannot allocate it.
        WriteRegions(bottomOverlap: true);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1002u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(4, allocations.Count);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        WriteRegions(topOverlap: true);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1004u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(5, allocations.Count);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        // A source spanning both sides of the first node contributes two
        // exposed bands. Both allocations and their addresses must validate
        // before any node links or the destination head are published.
        WriteRegions(bothProtrusions: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode);
        Execute(0xBEEF_1005u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(7, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(insertedNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)4,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)1,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)4,
            bus.ReadWord(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)8,
            bus.ReadWord(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16,
            bus.ReadWord(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)9,
            bus.ReadWord(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)2,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)7,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)17,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)27,
            bus.ReadWord(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)3,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)30,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)3,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)12,
            bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));

        // First-allocation failure changes nothing and requires no FreeMem.
        WriteRegions(bothProtrusions: true);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1006u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(8, allocations.Count);
        Assert.Empty(frees);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        // Second-allocation failure releases the first private node and still
        // preserves the old destination head/list.
        WriteRegions(bothProtrusions: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1007u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(10, allocations.Count);
        Assert.Single(frees);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        // A bad second allocation is freed along with the valid first node;
        // neither provisional rectangle may become reachable from the list.
        WriteRegions(bothProtrusions: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode + 1u);
        Execute(0xBEEF_1008u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(12, allocations.Count);
        Assert.Equal(3, frees.Count);
        Assert.Equal((bottomResidualNode + 1u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[1]);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[2]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        // The first allocation's address-class rejection also frees its
        // provisional result and leaves the old destination unchanged.
        WriteRegions(bothProtrusions: true);
        allocationResults.Enqueue(0xFFFF_FFF8u);
        Execute(0xBEEF_1009u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(13, allocations.Count);
        Assert.Equal(4, frees.Count);
        Assert.Equal((0xFFFF_FFF8u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[3]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        // The bounded right-overhang case canonicalizes to upper, widened
        // middle, lower, then the unchanged second destination rectangle.
        WriteRegions(rightXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode);
        Execute(0xBEEF_1010u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(15, allocations.Count);
        Assert.Equal(4, frees.Count);
        Assert.Equal(insertedNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(((ushort)0, (ushort)0, (ushort)20, (ushort)1),
            ReadNodeBounds(insertedNode));
        Assert.Equal(((ushort)0, (ushort)2, (ushort)25, (ushort)3),
            ReadNodeBounds(destinationFirstNode));
        Assert.Equal(((ushort)0, (ushort)4, (ushort)20, (ushort)5),
            ReadNodeBounds(bottomResidualNode));
        Assert.Equal(((ushort)0, (ushort)20, (ushort)20, (ushort)30),
            ReadNodeBounds(destinationSecondNode));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(((ushort)15, (ushort)2, (ushort)25, (ushort)3),
            ReadNodeBounds(sourceNode));

        WriteRegions(rightXOverhang: true);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1011u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(16, allocations.Count);
        Assert.Equal(4, frees.Count);
        AssertOldRightOverhangChain();

        WriteRegions(rightXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1012u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(18, allocations.Count);
        Assert.Equal(5, frees.Count);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[4]);
        AssertOldRightOverhangChain();

        WriteRegions(rightXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode + 1u);
        Execute(0xBEEF_1013u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(20, allocations.Count);
        Assert.Equal(7, frees.Count);
        Assert.Equal((bottomResidualNode + 1u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[5]);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[6]);
        AssertOldRightOverhangChain();

        WriteRegions(rightXOverhang: true);
        allocationResults.Enqueue(0xFFFF_FFF8u);
        Execute(0xBEEF_1014u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(21, allocations.Count);
        Assert.Equal(8, frees.Count);
        Assert.Equal((0xFFFF_FFF8u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[7]);
        AssertOldRightOverhangChain();

        // The left-edge mirror uses the same private two-node transaction,
        // retaining old-width upper/lower bands around a middle band widened
        // to the source's minimum X.
        WriteRegions(leftXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode);
        Execute(0xBEEF_1020u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(23, allocations.Count);
        Assert.Equal(8, frees.Count);
        Assert.Equal(insertedNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(((ushort)5, (ushort)0, (ushort)25, (ushort)1),
            ReadNodeBounds(insertedNode));
        Assert.Equal(((ushort)0, (ushort)2, (ushort)25, (ushort)3),
            ReadNodeBounds(destinationFirstNode));
        Assert.Equal(((ushort)5, (ushort)4, (ushort)25, (ushort)5),
            ReadNodeBounds(bottomResidualNode));
        Assert.Equal(((ushort)5, (ushort)20, (ushort)30, (ushort)30),
            ReadNodeBounds(destinationSecondNode));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(((ushort)0, (ushort)2, (ushort)10, (ushort)3),
            ReadNodeBounds(sourceNode));
        Assert.Equal(unchecked((ushort)-5),
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));

        WriteRegions(leftXOverhang: true);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1021u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(24, allocations.Count);
        Assert.Equal(8, frees.Count);
        AssertOldLeftOverhangChain();

        WriteRegions(leftXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1022u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(26, allocations.Count);
        Assert.Equal(9, frees.Count);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[8]);
        AssertOldLeftOverhangChain();

        WriteRegions(leftXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode + 1u);
        Execute(0xBEEF_1023u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(28, allocations.Count);
        Assert.Equal(11, frees.Count);
        Assert.Equal((bottomResidualNode + 1u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[9]);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[10]);
        AssertOldLeftOverhangChain();

        WriteRegions(leftXOverhang: true);
        allocationResults.Enqueue(0xFFFF_FFF8u);
        Execute(0xBEEF_1024u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(29, allocations.Count);
        Assert.Equal(12, frees.Count);
        Assert.Equal((0xFFFF_FFF8u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[11]);
        AssertOldLeftOverhangChain();

        WriteRegions(bothXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode);
        Execute(0xBEEF_1030u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(31, allocations.Count);
        Assert.Equal(12, frees.Count);
        Assert.Equal(insertedNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(bottomResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(bottomResidualNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(((ushort)5, (ushort)0, (ushort)25, (ushort)1),
            ReadNodeBounds(insertedNode));
        Assert.Equal(((ushort)0, (ushort)2, (ushort)30, (ushort)3),
            ReadNodeBounds(destinationFirstNode));
        Assert.Equal(((ushort)5, (ushort)4, (ushort)25, (ushort)5),
            ReadNodeBounds(bottomResidualNode));
        Assert.Equal(((ushort)5, (ushort)20, (ushort)30, (ushort)30),
            ReadNodeBounds(destinationSecondNode));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(((ushort)0, (ushort)2, (ushort)30, (ushort)3),
            ReadNodeBounds(sourceNode));
        Assert.Equal(unchecked((ushort)-5),
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));

        WriteRegions(bothXOverhang: true);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1031u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(32, allocations.Count);
        Assert.Equal(12, frees.Count);
        AssertOldBothOverhangChain();

        WriteRegions(bothXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1032u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(34, allocations.Count);
        Assert.Equal(13, frees.Count);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[12]);
        AssertOldBothOverhangChain();

        WriteRegions(bothXOverhang: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(bottomResidualNode + 1u);
        Execute(0xBEEF_1033u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(36, allocations.Count);
        Assert.Equal(15, frees.Count);
        Assert.Equal((bottomResidualNode + 1u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[13]);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[14]);
        AssertOldBothOverhangChain();

        WriteRegions(bothXOverhang: true);
        allocationResults.Enqueue(0xFFFF_FFF8u);
        Execute(0xBEEF_1034u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(37, allocations.Count);
        Assert.Equal(16, frees.Count);
        Assert.Equal((0xFFFF_FFF8u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[15]);
        AssertOldBothOverhangChain();

        // A high second result is rejected after the first private node is
        // valid; cleanup frees both results and leaves the old chain public.
        WriteRegions(bothProtrusions: true);
        allocationResults.Enqueue(insertedNode);
        allocationResults.Enqueue(0xFFFF_FFF8u);
        Execute(0xBEEF_1035u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(39, allocations.Count);
        Assert.Equal(18, frees.Count);
        Assert.Equal((0xFFFF_FFF8u, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[16]);
        Assert.Equal((insertedNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees[17]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)20,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)30,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        _ = fallbackEntryOffset;
    }

    [Fact]
    public void NativeGraphicsOrRegionRegionInsertsVerticalOverhangBandsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0096_0000;
        const uint execBase = 0x007C_0000;
        const uint sourceAllocation = 0x00F9_0000;
        const uint sourceNode = 0x00F9_1000;
        const uint destinationAllocation = 0x00F9_2000;
        const uint destinationFirstNode = 0x00F9_3000;
        const uint destinationSecondNode = 0x00F9_4000;
        const uint upperResidualNode = 0x00F9_5000;
        const uint lowerResidualNode = 0x00F9_6000;
        const uint stack = 0x00DF_0000;
        const uint returnAddress = 0x010F_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode,
                     upperResidualNode, lowerResidualNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x400]);

        var allocations = new List<(uint Address, uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>();
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            var address = allocationResults.Dequeue();
            allocations.Add((address, state.D[0], state.D[1]));
            state.D[0] = address;
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegions(
            bool extendsLeft,
            bool extendsRight,
            bool protrudesAboveFirst,
            bool protrudesBelowFirst = false)
        {
            foreach (var allocation in new[] { sourceAllocation, destinationAllocation })
                bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);

            var minX = extendsLeft ? (short)-5 : (short)0;
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)-3));
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 25);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            }

            var sourceMinX = extendsLeft ? (short)0 : (short)15;
            var sourceMaxX = extendsLeft && extendsRight
                ? (short)30
                : extendsLeft ? (short)10 : (short)25;
            var firstMinX = extendsLeft ? (short)5 : (short)0;
            var firstMaxX = extendsLeft ? (short)25 : (short)20;
            var secondMinX = firstMinX;
            var secondMaxX = extendsLeft ? (short)30 : (short)20;
            var sourceMinY = protrudesAboveFirst ? (short)0 : (short)2;
            var sourceMaxY = protrudesBelowFirst ? (short)8 : protrudesAboveFirst ? (short)5 : (short)3;
            var firstMinY = protrudesAboveFirst ? (short)3 : (short)0;
            var firstMaxY = protrudesBelowFirst ? (short)5 : protrudesAboveFirst ? (short)8 : (short)5;
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceNode);
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                sourceMinX, sourceMinY, sourceMaxX, sourceMaxY);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                firstMinX, firstMinY, firstMaxX, firstMaxY);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                secondMinX, 23, secondMaxX, 33);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native vertical-overhang OrRegionRegion did not return (fallback {fallbackEntryOffset}).");
        }

        (ushort MinX, ushort MinY, ushort MaxX, ushort MaxY) ReadNodeBounds(uint node)
        {
            var bounds = node + (uint)GraphicsLayouts.RegionRectangleBounds;
            return (
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMinX),
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMinY),
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMaxX),
                bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMaxY));
        }

        void AssertOldOverhangChain(
            bool extendsLeft,
            bool protrudesAboveFirst,
            bool protrudesBelowFirst = false)
        {
            var firstMinX = extendsLeft ? (ushort)5 : (ushort)0;
            var firstMaxX = extendsLeft ? (ushort)25 : (ushort)20;
            var secondMaxX = extendsLeft ? (ushort)30 : (ushort)20;
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal((firstMinX,
                    protrudesAboveFirst ? (ushort)3 : (ushort)0,
                    firstMaxX,
                    protrudesBelowFirst ? (ushort)5 : protrudesAboveFirst ? (ushort)8 : (ushort)5),
                ReadNodeBounds(destinationFirstNode));
            Assert.Equal((firstMinX, (ushort)23, secondMaxX, (ushort)33),
                ReadNodeBounds(destinationSecondNode));
        }

        var expectedAllocations = 0;
        foreach (var protrudesAboveFirst in new[] { true, false })
        foreach (var orientation in new[] { (false, true), (true, false), (true, true) })
        {
            var (extendsLeft, extendsRight) = orientation;
            var coalescedTopBand = extendsLeft && extendsRight;
            var orientationAllocations = coalescedTopBand ? 1 : 2;
            var protrudesBelowFirst = !protrudesAboveFirst;
            WriteRegions(extendsLeft, extendsRight, protrudesAboveFirst, protrudesBelowFirst);
            allocationResults.Enqueue(upperResidualNode);
            if (!coalescedTopBand)
                allocationResults.Enqueue(lowerResidualNode);
            Execute(0xBEEF_1100u + (extendsLeft ? 1u : 0u) + (extendsRight ? 2u : 0u));

            Assert.Equal(1u, cpu.State.D[0]);
            expectedAllocations += orientationAllocations;
            Assert.Equal(expectedAllocations, allocations.Count);
            Assert.Equal((uint)GraphicsLayouts.RegionRectangleSize, allocations[^1].Size);
            Assert.Equal(1u, allocations[^1].Flags);
            if (!coalescedTopBand)
            {
                Assert.Equal((uint)GraphicsLayouts.RegionRectangleSize, allocations[^2].Size);
                Assert.Equal(1u, allocations[^2].Flags);
            }
            Assert.Empty(frees);
            if (coalescedTopBand && protrudesAboveFirst)
            {
                Assert.Equal(upperResidualNode,
                    bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
                Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                    bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(destinationFirstNode,
                    bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(upperResidualNode,
                    bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(destinationSecondNode,
                    bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(destinationFirstNode,
                    bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            }
            else if (coalescedTopBand)
            {
                Assert.Equal(destinationFirstNode,
                    bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
                Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                    bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(upperResidualNode,
                    bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(destinationFirstNode,
                    bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(destinationSecondNode,
                    bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(upperResidualNode,
                    bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            }
            else
            {
                Assert.Equal(upperResidualNode,
                    bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
                Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                    bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(destinationFirstNode,
                    bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(upperResidualNode,
                    bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(lowerResidualNode,
                    bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(destinationFirstNode,
                    bus.ReadLong(lowerResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
                Assert.Equal(destinationSecondNode,
                    bus.ReadLong(lowerResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
                Assert.Equal(lowerResidualNode,
                    bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            }

            var sourceMinX = extendsLeft ? (ushort)0 : (ushort)15;
            var sourceMaxX = extendsLeft && extendsRight
                ? (ushort)30
                : extendsLeft ? (ushort)10 : (ushort)25;
            var firstMinX = extendsLeft ? (ushort)5 : (ushort)0;
            var firstMaxX = extendsLeft ? (ushort)25 : (ushort)20;
            var sourceMinY = protrudesAboveFirst ? (ushort)0 : (ushort)2;
            var sourceMaxY = protrudesBelowFirst ? (ushort)8 : protrudesAboveFirst ? (ushort)5 : (ushort)3;
            var firstMinY = protrudesAboveFirst ? (ushort)3 : (ushort)0;
            var firstMaxY = protrudesBelowFirst ? (ushort)5 : protrudesAboveFirst ? (ushort)8 : (ushort)5;
            if (coalescedTopBand)
            {
                if (protrudesAboveFirst)
                {
                    Assert.Equal((sourceMinX, sourceMinY, sourceMaxX, sourceMaxY),
                        ReadNodeBounds(upperResidualNode));
                    Assert.Equal((firstMinX, (ushort)6, firstMaxX, firstMaxY),
                        ReadNodeBounds(destinationFirstNode));
                }
                else
                {
                    Assert.Equal((firstMinX, firstMinY, firstMaxX, (ushort)1),
                        ReadNodeBounds(destinationFirstNode));
                    Assert.Equal((sourceMinX, sourceMinY, sourceMaxX, sourceMaxY),
                        ReadNodeBounds(upperResidualNode));
                }
            }
            else
            {
                if (protrudesAboveFirst)
                {
                    Assert.Equal((sourceMinX, sourceMinY, sourceMaxX, (ushort)2),
                        ReadNodeBounds(upperResidualNode));
                    Assert.Equal(((ushort)Math.Min(sourceMinX, firstMinX), firstMinY,
                        (ushort)Math.Max(sourceMaxX, firstMaxX), sourceMaxY),
                        ReadNodeBounds(destinationFirstNode));
                    Assert.Equal((firstMinX, (ushort)6, firstMaxX, firstMaxY),
                        ReadNodeBounds(lowerResidualNode));
                }
                else
                {
                    Assert.Equal((firstMinX, firstMinY, firstMaxX, (ushort)1),
                        ReadNodeBounds(upperResidualNode));
                    Assert.Equal(((ushort)Math.Min(sourceMinX, firstMinX), sourceMinY,
                        (ushort)Math.Max(sourceMaxX, firstMaxX), firstMaxY),
                        ReadNodeBounds(destinationFirstNode));
                    Assert.Equal((sourceMinX, (ushort)6, sourceMaxX, sourceMaxY),
                        ReadNodeBounds(lowerResidualNode));
                }
            }
            Assert.Equal((firstMinX, (ushort)23,
                (extendsLeft ? (ushort)30 : (ushort)20), (ushort)33),
                ReadNodeBounds(destinationSecondNode));
            Assert.Equal((ushort)0xFFFD,
                bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal(sourceNode,
                bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal((sourceMinX, sourceMinY, sourceMaxX, sourceMaxY),
                ReadNodeBounds(sourceNode));
        }

        foreach (var protrudesAboveFirst in new[] { true, false })
        {
            var protrudesBelowFirst = !protrudesAboveFirst;
            WriteRegions(
                extendsLeft: true,
                extendsRight: true,
                protrudesAboveFirst: protrudesAboveFirst,
                protrudesBelowFirst: protrudesBelowFirst);
            allocationResults.Enqueue(0u);
            Execute(0xBEEF_1110u + (protrudesAboveFirst ? 0u : 1u));
            Assert.Equal(0u, cpu.State.D[0]);
            expectedAllocations++;
            Assert.Equal(expectedAllocations, allocations.Count);
            Assert.Empty(frees);
            AssertOldOverhangChain(
                extendsLeft: true,
                protrudesAboveFirst: protrudesAboveFirst,
                protrudesBelowFirst: protrudesBelowFirst);
            Assert.Equal((ushort)0,
                bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)30,
                bus.ReadWord(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                    (uint)GraphicsLayouts.RectangleMaxX));
        }

        // A source spanning both Y edges and one X edge produces source-width
        // top/bottom residuals around the widened original middle node.
        foreach (var orientation in new[] { (false, true), (true, false) })
        {
            var (extendsLeft, extendsRight) = orientation;
            WriteRegions(
                extendsLeft,
                extendsRight,
                protrudesAboveFirst: true,
                protrudesBelowFirst: true);
            allocationResults.Enqueue(upperResidualNode);
            allocationResults.Enqueue(lowerResidualNode);
            Execute(0xBEEF_1130u + (extendsLeft ? 1u : 0u));
            Assert.Equal(1u, cpu.State.D[0]);
            expectedAllocations += 2;
            Assert.Equal(expectedAllocations, allocations.Count);
            Assert.Equal(upperResidualNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(upperResidualNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(lowerResidualNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(lowerResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(lowerResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(lowerResidualNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

            var sourceMinX = extendsLeft ? (ushort)0 : (ushort)15;
            var sourceMaxX = extendsLeft ? (ushort)10 : (ushort)25;
            var firstMinX = extendsLeft ? (ushort)5 : (ushort)0;
            var firstMaxX = extendsLeft ? (ushort)25 : (ushort)20;
            Assert.Equal((sourceMinX, (ushort)0, sourceMaxX, (ushort)2),
                ReadNodeBounds(upperResidualNode));
            Assert.Equal(((ushort)Math.Min(sourceMinX, firstMinX), (ushort)3,
                    (ushort)Math.Max(sourceMaxX, firstMaxX), (ushort)5),
                ReadNodeBounds(destinationFirstNode));
            Assert.Equal((sourceMinX, (ushort)6, sourceMaxX, (ushort)8),
                ReadNodeBounds(lowerResidualNode));
            Assert.Equal(sourceNode,
                bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal((sourceMinX, (ushort)0, sourceMaxX, (ushort)8),
                ReadNodeBounds(sourceNode));
        }

        // When the source spans both X and Y edges, it contains the old first
        // node completely; preserve the established replacement semantics.
        WriteRegions(
            extendsLeft: true,
            extendsRight: true,
            protrudesAboveFirst: true,
            protrudesBelowFirst: true);
        allocationResults.Enqueue(upperResidualNode);
        Execute(0xBEEF_1132u);
        Assert.Equal(1u, cpu.State.D[0]);
        expectedAllocations++;
        Assert.Equal(expectedAllocations, allocations.Count);
        Assert.Equal(upperResidualNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(upperResidualNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(upperResidualNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(((ushort)0, (ushort)0, (ushort)30, (ushort)8),
            ReadNodeBounds(upperResidualNode));
        Assert.Equal(
            new[] { (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u) },
            frees);
        frees.Clear();

        // Two-allocation bottom and combined top/bottom failures discard
        // provisional residuals and preserve the original chain and source.
        foreach (var verticalMode in new[] { (Above: false, Below: true), (Above: true, Below: true) })
        foreach (var orientation in new[] { (false, true), (true, false) })
        {
            var (extendsLeft, extendsRight) = orientation;
            WriteRegions(
                extendsLeft,
                extendsRight,
                verticalMode.Above,
                verticalMode.Below);
            allocationResults.Enqueue(upperResidualNode);
            allocationResults.Enqueue(0u);
            Execute(0xBEEF_1140u + (verticalMode.Above ? 4u : 0u) + (extendsLeft ? 1u : 0u));
            Assert.Equal(0u, cpu.State.D[0]);
            expectedAllocations += 2;
            Assert.Equal(expectedAllocations, allocations.Count);
            Assert.Equal(
                new[] { (upperResidualNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u) },
                frees);
            AssertOldOverhangChain(extendsLeft, verticalMode.Above, verticalMode.Below);
            Assert.Equal((extendsLeft ? (ushort)0 : (ushort)15,
                    verticalMode.Above ? (ushort)0 : (ushort)2,
                    extendsLeft ? (ushort)10 : (ushort)25,
                    verticalMode.Below ? (ushort)8 : (ushort)3),
                ReadNodeBounds(sourceNode));
            frees.Clear();
        }

        WriteRegions(extendsLeft: true, extendsRight: false, protrudesAboveFirst: false, protrudesBelowFirst: true);
        allocationResults.Enqueue(upperResidualNode);
        allocationResults.Enqueue(lowerResidualNode + 1u);
        Execute(0xBEEF_1122u);
        Assert.Equal(0u, cpu.State.D[0]);
        expectedAllocations += 2;
        Assert.Equal(expectedAllocations, allocations.Count);
        Assert.Equal(
            new[]
            {
                (lowerResidualNode + 1u, (uint)GraphicsLayouts.RegionRectangleSize, 1u),
                (upperResidualNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u)
            },
            frees);
        AssertOldOverhangChain(extendsLeft: true, protrudesAboveFirst: false, protrudesBelowFirst: true);
        Assert.Equal(((ushort)0, (ushort)2, (ushort)10, (ushort)8),
            ReadNodeBounds(sourceNode));
        frees.Clear();

        WriteRegions(
            extendsLeft: true,
            extendsRight: false,
            protrudesAboveFirst: true,
            protrudesBelowFirst: true);
        allocationResults.Enqueue(upperResidualNode);
        allocationResults.Enqueue(lowerResidualNode + 1u);
        Execute(0xBEEF_1142u);
        Assert.Equal(0u, cpu.State.D[0]);
        expectedAllocations += 2;
        Assert.Equal(expectedAllocations, allocations.Count);
        Assert.Equal(
            new[]
            {
                (lowerResidualNode + 1u, (uint)GraphicsLayouts.RegionRectangleSize, 1u),
                (upperResidualNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u)
            },
            frees);
        AssertOldOverhangChain(
            extendsLeft: true,
            protrudesAboveFirst: true,
            protrudesBelowFirst: true);
        Assert.Equal(((ushort)0, (ushort)0, (ushort)10, (ushort)8),
            ReadNodeBounds(sourceNode));

        // Reject a high lower-band allocation after the upper residual has
        // been allocated; clean up both private results before publication.
        frees.Clear();
        WriteRegions(
            extendsLeft: false,
            extendsRight: true,
            protrudesAboveFirst: true,
            protrudesBelowFirst: true);
        allocationResults.Enqueue(upperResidualNode);
        allocationResults.Enqueue(0xFFFF_FFF8u);
        Execute(0xBEEF_1143u);
        Assert.Equal(0u, cpu.State.D[0]);
        expectedAllocations += 2;
        Assert.Equal(expectedAllocations, allocations.Count);
        Assert.Equal(
            new[]
            {
                (0xFFFF_FFF8u, (uint)GraphicsLayouts.RegionRectangleSize, 1u),
                (upperResidualNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u)
            },
            frees);
        AssertOldOverhangChain(
            extendsLeft: false,
            protrudesAboveFirst: true,
            protrudesBelowFirst: true);
        Assert.Equal(((ushort)15, (ushort)0, (ushort)25, (ushort)8),
            ReadNodeBounds(sourceNode));
        _ = fallbackEntryOffset;
    }
    [Fact]
    public void NativeGraphicsXorRegionRegionInsertsStrictVerticalGapNodeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0095_0000;
        const uint execBase = 0x007B_0000;
        const uint sourceAllocation = 0x00F7_0000;
        const uint sourceNode = 0x00F7_1000;
        const uint destinationAllocation = 0x00F7_2000;
        const uint destinationFirstNode = 0x00F7_3000;
        const uint destinationSecondNode = 0x00F7_4000;
        const uint insertedNode = 0x00F7_5000;
        const uint stack = 0x00DD_0000;
        const uint returnAddress = 0x010D_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode, insertedNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { insertedNode, 0u });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegions()
        {
            foreach (var allocation in new[] { sourceAllocation, destinationAllocation })
                bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            }
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceNode);
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                4, 10, 16, 16);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                0, 0, 20, 5);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                0, 20, 20, 30);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.XorRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native XorRegionRegion gap insertion did not return (fallback {fallbackEntryOffset}).");
        }

        WriteRegions();
        Execute(0xBEEF_1001u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Equal((uint)GraphicsLayouts.RegionRectangleSize, allocations[0].Size);
        Assert.Equal(1u, allocations[0].Flags);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(insertedNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(insertedNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)4,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)10,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)16,
            bus.ReadWord(insertedNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Allocation failure must leave the original two-node destination
        // public and must not publish a partially initialized middle node.
        WriteRegions();
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1002u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        _ = fallbackEntryOffset;
    }
    [Fact]
    public void NativeGraphicsXorRegionRegionSplitsSourceContainedByFirstNodeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0096_0000;
        const uint execBase = 0x007D_0000;
        const uint sourceAllocation = 0x00F8_0000;
        const uint sourceNode = 0x00F8_1000;
        const uint destinationAllocation = 0x00F8_2000;
        const uint destinationFirstNode = 0x00F8_3000;
        const uint destinationSecondNode = 0x00F8_4000;
        const uint splitNode = 0x00F8_5000;
        const uint stack = 0x00DE_0000;
        const uint returnAddress = 0x010E_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode, splitNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { splitNode, 0u });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegions()
        {
            foreach (var allocation in new[] { sourceAllocation, destinationAllocation })
                bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            foreach (var region in new[] { source, destination })
            {
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
                bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            }
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceNode);
            WriteNode(
                sourceNode,
                source + (uint)GraphicsLayouts.RegionRectangle,
                0,
                0, 4, 20, 8);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            WriteNode(
                destinationFirstNode,
                destination + (uint)GraphicsLayouts.RegionRectangle,
                destinationSecondNode,
                0, 0, 20, 12);
            WriteNode(
                destinationSecondNode,
                destinationFirstNode,
                0,
                0, 18, 20, 30);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.XorRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native XorRegionRegion contained split did not return (fallback {fallbackEntryOffset}).");
        }

        WriteRegions();
        Execute(0xBEEF_1101u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Single(allocations);
        Assert.Equal((uint)GraphicsLayouts.RegionRectangleSize, allocations[0].Size);
        Assert.Equal(1u, allocations[0].Flags);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(splitNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(splitNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(splitNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(splitNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)3,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)9,
            bus.ReadWord(splitNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)12,
            bus.ReadWord(splitNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Allocation failure must leave the original destination topology and
        // first-node bounds untouched.
        WriteRegions();
        allocationResults.Enqueue(0u);
        Execute(0xBEEF_1102u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)12,
            bus.ReadWord(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
    }

    [Fact]
    public void NativeGraphicsOrRegionRegionCollapsesExactVerticalBridgeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0097_0000;
        const uint execBase = 0x007F_0000;
        const uint sourceAllocation = 0x00F9_0000;
