    [Fact]
    public void NativeGraphicsOrRegionRegionHandlesEqualSpanContainmentOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x009C_0000;
        const uint sourceAllocation = 0x00F6_0000;
        const uint sourceNode = 0x00F6_1000;
        const uint destinationAllocation = 0x00F6_2000;
        const uint destinationNode = 0x00F6_3000;
        const uint stack = 0x00DC_0000;
        const uint returnAddress = 0x010C_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, 0); // containment is allocation-free
        foreach (var address in new[] { sourceAllocation, sourceNode, destinationAllocation, destinationNode })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        void WriteNode(
            uint node,
            uint previous,
            short minX,
            short maxX,
            short minY = 0,
            short maxY = 10)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint node)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 10);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, node);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native OrRegionRegion containment body did not return (fallback {fallbackEntryOffset}).");
        }

        // Source strictly inside destination is an allocation-free identity.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 8, 12);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 20);
        Execute(0xC0DE_5710u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));

        // Destination strictly inside source widens the existing node in place.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 20);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 8, 12);
        Execute(0xFACE_5711u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Shared horizontal edges are still containment: the union remains
        // one node and must not allocate or touch the source.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 12);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 20);
        Execute(0xFACE_5714u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 20);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 8, 20);
        Execute(0xFACE_5715u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));

        // The vertical mirror keeps the full X span and contains only the Y
        // interval. The source-inside-destination form is still an identity.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 2, 8);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 0, 10);
        Execute(0xFACE_5712u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));

        // Destination strictly inside source widens the existing node in place
        // for the vertical mirror as well.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 0, 10);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 2, 8);
        Execute(0xFACE_5713u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u,
            bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        // Shared vertical edges are admitted symmetrically.
        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 0, 8);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 0, 10);
        Execute(0xFACE_5716u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 0, 10);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 0, 20, 2, 10);
        Execute(0xFACE_5717u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
    }

    [Fact]
    public void NativeGraphicsXorRegionRegionPublishesTwoBandsForEqualSpanVerticalCrossingOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0096_0000;
        const uint execBase = 0x0086_0000;
        const uint sourceAllocation = 0x00F0_0000;
        const uint sourceNode = 0x00F0_1000;
        const uint destinationAllocation = 0x00F0_2000;
        const uint destinationNode = 0x00F0_3000;
        const uint firstReplacementNode = 0x00F0_4000;
        const uint secondReplacementNode = 0x00F0_5000;
        const uint stack = 0x00D6_0000;
        const uint returnAddress = 0x0106_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation, destinationNode,
                     firstReplacementNode, secondReplacementNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[] { firstReplacementNode, secondReplacementNode, 0u });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        void WriteNode(uint node, uint previous, short minY, short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, 10);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint node)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 10);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 20);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, node);
        }

        void SeedRegions(bool reverse = false)
        {
            WriteRegion(sourceAllocation, source, sourceNode);
            WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle,
                reverse ? (short)0 : (short)8,
                reverse ? (short)12 : (short)20);
            WriteRegion(destinationAllocation, destination, destinationNode);
            WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle,
                reverse ? (short)8 : (short)0,
                reverse ? (short)20 : (short)12);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.XorRegionRegion], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native XorRegionRegion vertical crossing body did not return (fallback {fallbackEntryOffset}).");
        }

        SeedRegions();
        Execute(0xC0DE_5700u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(firstReplacementNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(secondReplacementNode,
            bus.ReadLong(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u,
            bus.ReadLong(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(firstReplacementNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(firstReplacementNode,
            bus.ReadLong(secondReplacementNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0,
            bus.ReadWord(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0,
            bus.ReadWord(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)7,
            bus.ReadWord(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)0,
            bus.ReadWord(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)13,
            bus.ReadWord(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)10,
            bus.ReadWord(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)20,
            bus.ReadWord(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationNode, frees.Single().Address);
        Assert.Equal(2, allocations.Count);

        allocationResults.Enqueue(0u);
        SeedRegions();
        frees.Clear();
        Execute(0xFACE_5701u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(destinationNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Empty(frees);
        Assert.Equal(3, allocations.Count);

        allocationResults.Clear();
        allocationResults.Enqueue(firstReplacementNode);
        allocationResults.Enqueue(secondReplacementNode);
        allocationResults.Enqueue(0u);
        SeedRegions(reverse: true);
        frees.Clear();
        Execute(0xC0DE_5702u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(firstReplacementNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(secondReplacementNode,
            bus.ReadLong(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)0,
            bus.ReadWord(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)7,
            bus.ReadWord(firstReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)13,
            bus.ReadWord(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20,
            bus.ReadWord(secondReplacementNode + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationNode, frees.Single().Address);
        Assert.Equal(5, allocations.Count);
    }

