            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 10);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, node);
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(sourceNode, source + (uint)GraphicsLayouts.RegionRectangle, 8);
        WriteRegion(destinationAllocation, destination, destinationNode);
        WriteNode(destinationNode, destination + (uint)GraphicsLayouts.RegionRectangle, 20);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
