        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)9,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0,
            bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20,
