        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} two-node source/empty destination body did not return (fallback {fallbackEntryOffset}).");
        }

        void AssertPublished(uint first, uint second)
        {
            Assert.Equal(10u, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal(20u, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal(34u, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal(45u, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(first, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(second, bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(first, bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u, bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0x0000_0000u,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0004_0005u,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x0014_0014u,
                bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0018_0019u,
                bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        }

        Execute(GraphicsLvo.OrRegionRegion, 0x1122_3344u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
        Assert.Empty(frees);
        AssertPublished(orReplacementFirst, orReplacementSecond);
        Assert.Equal(sourceFirstNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u, 0);
        Execute(GraphicsLvo.XorRegionRegion, 0x5566_7788u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(4, allocations.Count);
        Assert.Empty(frees);
        AssertPublished(xorReplacementFirst, xorReplacementSecond);

        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u, 0);
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xA1B2_C3D4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Empty(frees);
        Assert.Equal(sourceFirstNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
    }

    [Fact]
    public void NativeGraphicsOrAndXorRegionRegionTransfersCanonicalThreeNodeSourceIntoEmptyDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0093_0000;
        const uint execBase = 0x0083_0000;
        const uint sourceAllocation = 0x00E7_0000;
        const uint sourceFirstNode = 0x00E7_1000;
        const uint sourceSecondNode = 0x00E7_2000;
        const uint sourceThirdNode = 0x00E7_3000;
        const uint destinationAllocation = 0x00E7_4000;
        const uint orReplacementFirst = 0x00E7_5000;
        const uint orReplacementSecond = 0x00E7_6000;
        const uint orReplacementThird = 0x00E7_7000;
        const uint xorReplacementFirst = 0x00E7_8000;
        const uint xorReplacementSecond = 0x00E7_9000;
        const uint xorReplacementThird = 0x00E7_A000;
        const uint stack = 0x00D0_0000;
        const uint returnAddress = 0x00F0_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceFirstNode, sourceSecondNode, sourceThirdNode,
                     destinationAllocation, orReplacementFirst, orReplacementSecond,
                     orReplacementThird, xorReplacementFirst, xorReplacementSecond,
                     xorReplacementThird
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x300]);

        void WriteSource()
        {
            bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 10);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 20);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 44);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 70);
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceFirstNode);

            bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                source + (uint)GraphicsLayouts.RegionRectangle);
            bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleNext, sourceSecondNode);
            bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0000u);
            bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0004_0005u);

            bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious, sourceFirstNode);
            bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, sourceThirdNode);
            bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0008_0008u);
            bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0010_000Fu);

            bus.WriteLong(sourceThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious, sourceSecondNode);
            bus.WriteLong(sourceThirdNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteLong(sourceThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0014_0014u);
            bus.WriteLong(sourceThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x001C_001Du);
        }

        void WriteEmptyDestination()
        {
            bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 0);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 0);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, 0);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds, 0);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u, 0);
        }

        WriteSource();
        WriteEmptyDestination();

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            orReplacementFirst, orReplacementSecond, orReplacementThird,
            xorReplacementFirst, xorReplacementSecond, xorReplacementThird
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed, int maxInstructions = 16384)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} three-node source/empty destination body did not return " +
                $"(fallback {fallbackEntryOffset}).");
        }

        void AssertPublished(uint first, uint second, uint third)
        {
            Assert.Equal((ushort)10, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)20, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)44, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)70, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(first, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(second, bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(third, bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(first, bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(second, bus.ReadLong(third + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u, bus.ReadLong(third + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0x0000_0000u,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0004_0005u,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x0008_0008u,
                bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0010_000Fu,
                bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x0014_0014u,
                bus.ReadLong(third + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x001C_001Du,
                bus.ReadLong(third + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        }

        Execute(GraphicsLvo.OrRegionRegion, 0x1122_3344u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(3, allocations.Count);
        Assert.Empty(frees);
        AssertPublished(orReplacementFirst, orReplacementSecond, orReplacementThird);

        WriteSource();
        WriteEmptyDestination();
        Execute(GraphicsLvo.XorRegionRegion, 0x5566_7788u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(6, allocations.Count);
        Assert.Empty(frees);
        AssertPublished(xorReplacementFirst, xorReplacementSecond, xorReplacementThird);

        WriteSource();
        WriteEmptyDestination();
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xA1B2_C3D4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(7, allocations.Count);
        Assert.Empty(frees);

        WriteSource();
        WriteEmptyDestination();
        allocationResults.Enqueue(orReplacementFirst);
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xB1C2_D3E4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(9, allocations.Count);
        Assert.Contains((orReplacementFirst, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);
        Assert.Single(frees);

        WriteSource();
        WriteEmptyDestination();
        allocationResults.Enqueue(orReplacementFirst);
        allocationResults.Enqueue(orReplacementSecond);
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xC1D2_E3F4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(12, allocations.Count);
        Assert.Contains((orReplacementSecond, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);
        Assert.Equal(3, frees.Count);

        WriteSource();
        WriteEmptyDestination();
        bus.WriteLong(sourceThirdNode + (uint)GraphicsLayouts.RegionRectangleNext, sourceFirstNode);
        Execute(GraphicsLvo.OrRegionRegion, 0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(12, allocations.Count);

        WriteSource();
        WriteEmptyDestination();
        bus.WriteLong(4, 0);
        Execute(GraphicsLvo.XorRegionRegion, 0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(12, allocations.Count);
        Assert.Equal(3, frees.Count);
    }

    [Fact]
    public void NativeGraphicsOrAndXorRegionRegionTransfersCanonicalFourNodeSourceIntoEmptyDestinationOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x00A6_0000;
        const uint execBase = 0x0088_0000;
        const uint sourceAllocation = 0x00F7_0000;
        const uint sourceFirstNode = 0x00F7_1000;
        const uint sourceSecondNode = 0x00F7_2000;
        const uint sourceThirdNode = 0x00F7_3000;
        const uint sourceFourthNode = 0x00F7_4000;
        const uint destinationAllocation = 0x00F7_5000;
        const uint orReplacementFirst = 0x00F7_6000;
        const uint orReplacementSecond = 0x00F7_7000;
        const uint orReplacementThird = 0x00F7_8000;
        const uint orReplacementFourth = 0x00F7_9000;
        const uint xorReplacementFirst = 0x00F7_A000;
        const uint xorReplacementSecond = 0x00F7_B000;
        const uint xorReplacementThird = 0x00F7_C000;
        const uint xorReplacementFourth = 0x00F7_D000;
        const uint stack = 0x00DA_0000;
        const uint returnAddress = 0x00FF_7000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceFirstNode, sourceSecondNode, sourceThirdNode,
                     sourceFourthNode, destinationAllocation, orReplacementFirst,
                     orReplacementSecond, orReplacementThird, orReplacementFourth,
                     xorReplacementFirst, xorReplacementSecond, xorReplacementThird,
                     xorReplacementFourth
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x300]);

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            ushort minX,
            ushort minY,
            ushort maxX,
            ushort maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds, minX);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 2u, minY);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, maxX);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 6u, maxY);
        }

        void WriteSource()
        {
            bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 10);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 20);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 44);
            bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 80);
            bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceFirstNode);
            WriteNode(sourceFirstNode, source + (uint)GraphicsLayouts.RegionRectangle, sourceSecondNode,
                0, 0, 4, 5);
            WriteNode(sourceSecondNode, sourceFirstNode, sourceThirdNode, 8, 8, 16, 15);
            WriteNode(sourceThirdNode, sourceSecondNode, sourceFourthNode, 20, 20, 28, 29);
            WriteNode(sourceFourthNode, sourceThirdNode, 0, 4, 36, 12, 45);
        }

        void WriteEmptyDestination()
        {
            bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 0);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 0);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, 0);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds, 0);
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u, 0);
        }

        WriteSource();
        WriteEmptyDestination();

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            orReplacementFirst, orReplacementSecond, orReplacementThird, orReplacementFourth,
            xorReplacementFirst, xorReplacementSecond, xorReplacementThird, xorReplacementFourth
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 210)), state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed, int maxInstructions = 24576)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    return;
                }
            }

            throw new InvalidOperationException(
                $"Native {vector} four-node source/empty destination body did not return " +
                $"(fallback {fallbackEntryOffset}).");
        }

        void AssertPublished(uint first, uint second, uint third, uint fourth)
        {
            Assert.Equal((ushort)10, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal((ushort)20, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal((ushort)44, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal((ushort)80, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
            Assert.Equal(first, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(second, bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(third, bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(fourth, bus.ReadLong(third + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0u, bus.ReadLong(fourth + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(first + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(first, bus.ReadLong(second + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(second, bus.ReadLong(third + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(third, bus.ReadLong(fourth + (uint)GraphicsLayouts.RegionRectanglePrevious));
            var expected = new[] { 0x0000_0000u, 0x0008_0008u, 0x0014_0014u, 0x0004_0024u };
            var expectedMax = new[] { 0x0004_0005u, 0x0010_000Fu, 0x001C_001Du, 0x000C_002Du };
            foreach (var (node, index) in new[] { (first, 0), (second, 1), (third, 2), (fourth, 3) })
            {
                Assert.Equal(expected[index],
                    bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectangleBounds));
                Assert.Equal(expectedMax[index],
                    bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            }
        }

        Execute(GraphicsLvo.OrRegionRegion, 0x1122_3344u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destination, cpu.State.A[1]);
        Assert.Equal(4, allocations.Count);
        Assert.Empty(frees);
        AssertPublished(orReplacementFirst, orReplacementSecond, orReplacementThird, orReplacementFourth);

        WriteSource();
        WriteEmptyDestination();
        Execute(GraphicsLvo.XorRegionRegion, 0x5566_7788u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(8, allocations.Count);
        Assert.Empty(frees);
        AssertPublished(xorReplacementFirst, xorReplacementSecond, xorReplacementThird, xorReplacementFourth);

        WriteSource();
        WriteEmptyDestination();
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xA1B2_C3D4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(9, allocations.Count);
        Assert.Empty(frees);

        WriteSource();
        WriteEmptyDestination();
        allocationResults.Enqueue(orReplacementFirst);
        allocationResults.Enqueue(orReplacementSecond);
        allocationResults.Enqueue(orReplacementThird);
        allocationResults.Enqueue(0);
        Execute(GraphicsLvo.OrRegionRegion, 0xB1C2_D3E4u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(13, allocations.Count);
        Assert.Equal(3, frees.Count);

        WriteSource();
        WriteEmptyDestination();
        bus.WriteLong(sourceFourthNode + (uint)GraphicsLayouts.RegionRectangleNext, sourceFirstNode);
        Execute(GraphicsLvo.XorRegionRegion, 0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(13, allocations.Count);

        WriteSource();
        WriteEmptyDestination();
        bus.WriteLong(4, 0);
        Execute(GraphicsLvo.XorRegionRegion, 0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(13, allocations.Count);
    }

    [Fact]
    public void NativeGraphicsAndRegionRegionAcceptsCanonicalTwoNodeSourceIntoEmptyDestinationOnAccurateM68000()
