        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 45);
        bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, sourceFirstNode);
        bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleNext, sourceSecondNode);
        bus.WriteLong(
            sourceFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            source + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteWord(
            sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX,
            0);
        bus.WriteWord(
            sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY,
            0);
        bus.WriteWord(
            sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX,
            4);
        bus.WriteWord(
            sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY,
            5);
        bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            sourceFirstNode);
        bus.WriteWord(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX,
            20);
        bus.WriteWord(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY,
            20);
        bus.WriteWord(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX,
            24);
        bus.WriteWord(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY,
            25);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.AndRegionRegion], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native AndRegionRegion body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(sourceFirstNode, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(sourceSecondNode, bus.ReadLong(sourceFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(sourceFirstNode, bus.ReadLong(sourceSecondNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u));

        // A non-terminating second link is outside the canonical two-node
        // admission and must retain the caller's D0 through shared fallback.
        bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, sourceFirstNode);
        Execute(0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);

        bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteWord(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX,
            25);
        Execute(0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);

        // A canonical destination wholly inside the first source node is the
        // existing AND result and must remain untouched without allocation.
        bus.WriteWord(
            sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX,
            24);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 11);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 21);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 13);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 24);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationNode);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(
            destinationNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0002_0003u);
        Execute(0x1020_3040u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)11, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)24, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));

        // The same read-only identity is valid when the destination is
        // wholly contained in the second source node.
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 30);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 44);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 45);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0004_0005u);
        Execute(0x2030_4050u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)45, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));

        // A destination that contains only the first source node reduces to
        // that node without allocation; overlap with the other source node
        // would require a multi-node result and therefore remains portable.
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 8);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 18);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 16);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 27);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0002_0002u);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0006_0007u);
        Execute(0x4050_6070u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)10, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(0u, bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0004_0005u, bus.ReadLong(destinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));

        // The mirror form contains only the second source node and has the
        // same in-place single-node result.
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 28);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 38);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 36);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 47);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0002_0002u);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0006_0007u);
        Execute(0x5060_7080u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)40, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)34, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)45, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(0u, bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0004_0005u, bus.ReadLong(destinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));

        // A partially overlapping destination can still be reduced in place
        // when its intersection is confined to one source node.
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 12);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 22);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 18);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 28);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0006_0006u);
        Execute(0x6070_8090u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)12, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)22, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)14, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(0u, bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0002_0003u, bus.ReadLong(destinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));

        // The second source node uses the same single-node intersection arm.
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 28);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 38);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 36);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 43);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0008_0005u);
        Execute(0x7080_90A0u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)30, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)40, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)34, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)43, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(0u, bus.ReadLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0004_0003u, bus.ReadLong(destinationNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));

        // Crossing the gap between source nodes is not a contained identity;
        // the native arm must preserve D0 and leave the destination intact.
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 13);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 30);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 40);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(destinationNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0011_0014u);
        Execute(0x3040_5060u);
        Assert.Equal(0x3040_5060u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsAndRegionRegionReturnsSuccessForIdenticalCanonicalTwoNodeRegionsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0091_0000;
        const uint execBase = 0x007D_0000;
        const uint sourceAllocation = 0x00E5_0000;
        const uint sourceFirstNode = 0x00E5_1000;
        const uint sourceSecondNode = 0x00E5_2000;
        const uint destinationAllocation = 0x00E5_3000;
        const uint destinationFirstNode = 0x00E5_4000;
        const uint destinationSecondNode = 0x00E5_5000;
        const uint orReplacementFirstNode = 0x00E5_6000;
        const uint orReplacementSecondNode = 0x00E5_7000;
        const uint xorReplacementFirstNode = 0x00E5_8000;
        const uint xorReplacementSecondNode = 0x00E5_9000;
        const uint stack = 0x00CD_0000;
        const uint returnAddress = 0x00FD_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[0], state.D[0], state.D[1]));
        });
        bus.MapWritableMemory(sourceAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(sourceFirstNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(sourceSecondNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(destinationAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(destinationFirstNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(destinationSecondNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(orReplacementFirstNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(orReplacementSecondNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(xorReplacementFirstNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(xorReplacementSecondNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocationResults = new Queue<uint>(new[]
        {
            orReplacementFirstNode,
            orReplacementSecondNode,
            xorReplacementFirstNode,
            xorReplacementSecondNode
        });
        var allocations = new List<(uint Size, uint Flags)>();
        bus.RegisterHostGateway(unchecked((uint)((int)execBase - 198)), state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });

        void WriteRegion(
            uint allocation,
            uint region,
            uint firstNode,
            uint secondNode,
            ushort maxX = 34)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 10);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, maxX);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 45);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, firstNode);
            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectangleNext, secondNode);
            bus.WriteLong(
                firstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                region + (uint)GraphicsLayouts.RegionRectangle);
            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0000u);
            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x000A_000Au);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectanglePrevious, firstNode);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x000F_000Fu);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0018_0019u);
        }

        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode);
        WriteRegion(destinationAllocation, destination, destinationFirstNode, destinationSecondNode);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.AndRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native AndRegionRegion body did not return (fallback {fallbackEntryOffset}).");
        }

        void ExecuteOr(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.OrRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native OrRegionRegion body did not return (fallback {fallbackEntryOffset}).");
        }

        void ExecuteXor(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.XorRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native XorRegionRegion body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(0x1357_9BDFu);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(sourceFirstNode, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(sourceSecondNode, bus.ReadLong(sourceFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)34, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal(0x000F_000Fu, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0018_0019u, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));

        ExecuteOr(0x2468_ACE0u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)34, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));

        // XOR of identical canonical two-node Regions is empty. The native
        // identity arm retires both destination nodes and publishes a clean
        // header while leaving the source Region untouched.
        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode);
        WriteRegion(destinationAllocation, destination, destinationFirstNode, destinationSecondNode);
        ExecuteXor(0x369C_F258u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Equal(sourceFirstNode, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(sourceSecondNode, bus.ReadLong(sourceFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Contains((destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);
        Assert.Contains((destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);

        // When the public envelopes match and each destination node is
        // contained by its corresponding source node, the destination is
        // already the exact AND result. The native arm must accept it without
        // allocation, retirement, or public mutation.
        var freesBeforeContained = frees.Count;
        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode);
        WriteRegion(destinationAllocation, destination, destinationFirstNode, destinationSecondNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds,
            0x0002_0002u);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
            0x0008_0008u);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds,
            0x0011_0011u);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
            0x0016_0017u);
        Execute(0x5A5A_A5A5u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0x0002_0002u, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0008_0008u, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Equal(0x0011_0011u, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0016_0017u, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Equal(freesBeforeContained, frees.Count);

        // A same-envelope destination that escapes even one corresponding
        // source node must still decline without mutation.
        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode);
        WriteRegion(destinationAllocation, destination, destinationFirstNode, destinationSecondNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
            0x000B_0008u);
        Execute(0xC3C3_3C3Cu);
        Assert.Equal(0xC3C3_3C3Cu, cpu.State.D[0]);
        Assert.Equal(0x000B_0008u, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));

        // The bounded two-node replacement form copies a vertically earlier
        // source chain into two fresh nodes and publishes it ahead of the
        // existing destination chain. OR and XOR share this disjoint result.
        void WriteDisjointTwoNodeRegions()
        {
            WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode);
            WriteRegion(destinationAllocation, destination, destinationFirstNode, destinationSecondNode);
            bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0000_0000u);
            bus.WriteLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0008_0004u);
            bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0002_0007u);
            bus.WriteLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x000A_000Bu);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0000_0010u);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0008_0013u);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0002_0016u);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x000A_0018u);
        }

        WriteDisjointTwoNodeRegions();
        ExecuteOr(0xABCD_1234u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(orReplacementFirstNode, bus.ReadLong(destination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(orReplacementSecondNode, bus.ReadLong(orReplacementFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode, bus.ReadLong(orReplacementSecondNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(orReplacementFirstNode +
                (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(orReplacementFirstNode, bus.ReadLong(orReplacementSecondNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(orReplacementSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(sourceFirstNode, bus.ReadLong(source +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(sourceSecondNode, bus.ReadLong(sourceFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(2, allocations.Count);

        WriteDisjointTwoNodeRegions();
        ExecuteXor(0xDCBA_4321u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(xorReplacementFirstNode, bus.ReadLong(destination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(xorReplacementSecondNode, bus.ReadLong(xorReplacementFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode, bus.ReadLong(xorReplacementSecondNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(4, allocations.Count);

        // A valid but non-identical public envelope must restore the caller's
        // seed and leave the destination untouched through the shared path.
        WriteRegion(destinationAllocation, destination, destinationFirstNode, destinationSecondNode, maxX: 35);
        Execute(0x2468_ACE0u);
        Assert.Equal(0x2468_ACE0u, cpu.State.D[0]);
        Assert.Equal((ushort)35, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
    }

    [Fact]
    public void NativeGraphicsOrXorRegionRegionLeavesCanonicalTwoNodeDestinationForEmptySourceOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x008B_8000;
        const uint execBase = 0x007B_8000;
        const uint sourceAllocation = 0x00E2_8000;
        const uint destinationAllocation = 0x00E2_9000;
        const uint destinationFirstNode = 0x00E2_A000;
        const uint destinationSecondNode = 0x00E2_B000;
        const uint stack = 0x00CA_8000;
        const uint returnAddress = 0x00FA_8000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(sourceAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(destinationAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(destinationFirstNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(destinationSecondNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
        bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
        bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, 0);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 45);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext,
            destinationSecondNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0000u);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0004_0005u);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destinationFirstNode);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0008_000Au);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0018_0019u);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} empty-source two-node identity did not return (fallback {fallbackEntryOffset}).");
        }

        void AssertUnchanged()
        {
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0x0000_0000u,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0004_0005u,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x0008_000Au,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0018_0019u,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        }

        Execute(GraphicsLvo.OrRegionRegion, 0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        AssertUnchanged();
        Execute(GraphicsLvo.XorRegionRegion, 0x9ABC_DEF0u);
        Assert.Equal(1u, cpu.State.D[0]);
        AssertUnchanged();

        // A broken second predecessor must decline without changing the
        // caller's result register or the public destination chain.
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(GraphicsLvo.OrRegionRegion, 0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));

    }

