        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 60);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);

        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext,
            destinationSecondNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0000u);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0004_0005u);

        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destinationFirstNode);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext,
            destinationThirdNode);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0008_0008u);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0010_000Fu);

        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destinationSecondNode);
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0014_0014u);
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0018_001Eu);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} empty-source three-node identity did not return " +
                $"(fallback {fallbackEntryOffset}).");
        }

        void AssertUnchanged()
        {
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destinationThirdNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationFirstNode,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(destinationSecondNode,
                bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
            Assert.Equal(0u,
                bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext));
            Assert.Equal(0x0000_0000u,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0004_0005u,
                bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x0008_0008u,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0010_000Fu,
                bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x0014_0014u,
                bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0018_001Eu,
                bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        }

        Execute(GraphicsLvo.OrRegionRegion, 0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        AssertUnchanged();
        Execute(GraphicsLvo.XorRegionRegion, 0x9ABC_DEF0u);
        Assert.Equal(1u, cpu.State.D[0]);
        AssertUnchanged();

        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext,
            destinationFirstNode);
        Execute(GraphicsLvo.OrRegionRegion, 0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));

        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(GraphicsLvo.XorRegionRegion, 0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(destinationThirdNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
    }

