            Assert.Equal(0x0018_001Eu,
                bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
            Assert.Equal(0x001C_0020u,
                bus.ReadLong(destinationFourthNode + (uint)GraphicsLayouts.RegionRectangleBounds));
            Assert.Equal(0x0020_0027u,
                bus.ReadLong(destinationFourthNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
