        bus.WriteLong(destinationFourthNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(destinationFourthNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(GraphicsLvo.XorRegionRegion, 0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(destinationFourthNode,
            bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext));
    }

    [Fact]
    public void NativeGraphicsAndOrXorRegionRegionHandleIdenticalCanonicalThreeNodeRegionsOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0092_0000;
        const uint execBase = 0x007E_0000;
        const uint sourceAllocation = 0x00E6_0000;
        const uint sourceFirstNode = 0x00E6_1000;
        const uint sourceSecondNode = 0x00E6_2000;
        const uint sourceThirdNode = 0x00E6_3000;
        const uint destinationAllocation = 0x00E6_4000;
        const uint destinationFirstNode = 0x00E6_5000;
        const uint destinationSecondNode = 0x00E6_6000;
        const uint destinationThirdNode = 0x00E6_7000;
        const uint stack = 0x00CE_0000;
        const uint returnAddress = 0x00FE_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(sourceAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(destinationAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        foreach (var node in new[]
                     {
                         sourceFirstNode, sourceSecondNode, sourceThirdNode,
                         destinationFirstNode, destinationSecondNode, destinationThirdNode
                     })
            bus.MapWritableMemory(node, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x240]);

        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        void WriteRegion(
            uint allocation,
            uint region,
            uint firstNode,
            uint secondNode,
            uint thirdNode)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 10);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 44);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 70);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, firstNode);

            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                region + (uint)GraphicsLayouts.RegionRectangle);
            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectangleNext, secondNode);
            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0000_0000u);
            bus.WriteLong(firstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0004_0005u);

            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                firstNode);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectangleNext, thirdNode);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0008_0008u);
            bus.WriteLong(secondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0010_000Fu);

            bus.WriteLong(thirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                secondNode);
            bus.WriteLong(thirdNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteLong(thirdNode + (uint)GraphicsLayouts.RegionRectangleBounds,
                0x0014_0014u);
            bus.WriteLong(thirdNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u,
                0x0018_001Eu);
        }

        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode, sourceThirdNode);
        WriteRegion(
            destinationAllocation,
            destination,
            destinationFirstNode,
            destinationSecondNode,
            destinationThirdNode);
        Assert.Equal(0u, bus.ReadLong(sourceThirdNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[vector],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} three-node identity did not return " +
                $"(fallback {fallbackEntryOffset}).");
        }

        // OR identity is read-only: equal canonical Regions remain linked,
        // no node is retired, and the operation succeeds without Exec.
        bus.WriteLong(4, 0);
        Execute(GraphicsLvo.OrRegionRegion, 0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationThirdNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Empty(frees);

        // AND identity is also read-only for equal canonical operands and
        // must not depend on Exec when no destination storage is retired.
        Execute(GraphicsLvo.AndRegionRegion, 0x2468_ACE0u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationThirdNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Empty(frees);

        bus.WriteLong(4, execBase);
        Execute(GraphicsLvo.XorRegionRegion, 0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Equal(sourceFirstNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(sourceSecondNode,
            bus.ReadLong(sourceFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(sourceThirdNode,
            bus.ReadLong(sourceSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Contains((destinationThirdNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);
        Assert.Contains((destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);
        Assert.Contains((destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 1u), frees);
        Assert.Equal(3, frees.Count);

        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode, sourceThirdNode);
        WriteRegion(
            destinationAllocation,
            destination,
            destinationFirstNode,
            destinationSecondNode,
            destinationThirdNode);
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(GraphicsLvo.OrRegionRegion, 0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationThirdNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(3, frees.Count);

        WriteRegion(sourceAllocation, source, sourceFirstNode, sourceSecondNode, sourceThirdNode);
        WriteRegion(
            destinationAllocation,
            destination,
            destinationFirstNode,
            destinationSecondNode,
            destinationThirdNode);
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext,
            destinationFirstNode);
        Execute(GraphicsLvo.XorRegionRegion, 0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(3, frees.Count);
    }

    [Fact]
    public void NativeGraphicsAndRegionRegionClearsCanonicalTwoNodeDestinationForEmptySourceOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x008B_0000;
        const uint execBase = 0x007B_0000;
        const uint sourceAllocation = 0x00E2_0000;
        const uint destinationAllocation = 0x00E2_1000;
        const uint destinationFirstNode = 0x00E2_2000;
        const uint destinationSecondNode = 0x00E2_3000;
        const uint stack = 0x00CA_0000;
        const uint returnAddress = 0x00FA_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(
            sourceAllocation,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(
            destinationAllocation,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(
            destinationFirstNode,
            new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(
            destinationSecondNode,
            new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
        bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
        bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext, destinationSecondNode);
        bus.WriteLong(
            destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(
            destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destinationFirstNode);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 45);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0005u);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0004_0005u);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0014_0014u);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0018_0019u);

        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.AndRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native AndRegionRegion body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.Contains(
            (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // A malformed second predecessor is not an owned canonical chain;
        // the shared fallback must preserve the seed and all public bytes.
        bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
        bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext, destinationSecondNode);
        bus.WriteLong(
            destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destination + (uint)GraphicsLayouts.RegionRectangle);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));

        bus.WriteLong(
            destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
            destinationFirstNode);
        bus.WriteWord(
            destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX,
            25);
        Execute(0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(2, frees.Count);
    }

    [Fact]
    public void NativeGraphicsAndRegionRegionClearsCanonicalThreeNodeDestinationForEmptySourceOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x008D_0000;
        const uint execBase = 0x007D_0000;
        const uint sourceAllocation = 0x00E5_0000;
        const uint destinationAllocation = 0x00E5_1000;
        const uint destinationFirstNode = 0x00E5_2000;
        const uint destinationSecondNode = 0x00E5_3000;
        const uint destinationThirdNode = 0x00E5_4000;
        const uint stack = 0x00CD_0000;
        const uint returnAddress = 0x00FD_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(sourceAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(destinationAllocation, new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        foreach (var node in new[] { destinationFirstNode, destinationSecondNode, destinationThirdNode })
            bus.MapWritableMemory(node, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        bus.WriteWord(sourceAllocation, GraphicsLayouts.NativeRegionMarker);
        bus.WriteWord(destinationAllocation, GraphicsLayouts.NativeRegionMarker);
        bus.WriteLong(source + (uint)GraphicsLayouts.RegionRectangle, 0);

        void WriteCanonicalDestination()
        {
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 10);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 20);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 34);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 60);

            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                destination + (uint)GraphicsLayouts.RegionRectangle);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext,
                destinationSecondNode);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0000u);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0004_0005u);

            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                destinationFirstNode);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext,
                destinationThirdNode);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0008_0008u);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0010_000Fu);

            bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                destinationSecondNode);
            bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0014_0014u);
            bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0018_001Eu);
        }

        WriteCanonicalDestination();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.AndRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native AndRegionRegion three-node clear did not return " +
                $"(fallback {fallbackEntryOffset}).");
        }

        Execute(0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal(0u, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Contains(
            (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.Contains(
            (destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.Contains(
            (destinationThirdNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // A malformed third predecessor must retain the seed and public chain.
        WriteCanonicalDestination();
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationThirdNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(3, frees.Count);

        // A non-terminal third node is also outside this bounded arm.
        WriteCanonicalDestination();
        bus.WriteLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext,
            destinationFirstNode);
        Execute(0x0BAD_F00Du);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationThirdNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(3, frees.Count);
    }

