        void WriteDestinationNodes()
        {
            bus.WriteLong(destination + (uint)GraphicsLayouts.RegionRectangle, destinationFirstNode);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext, destinationSecondNode);
            bus.WriteLong(
                destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                destination + (uint)GraphicsLayouts.RegionRectangle);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext, 0);
            bus.WriteLong(
                destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious,
                destinationFirstNode);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinX, 10);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMinY, 20);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxX, 34);
            bus.WriteWord(destination + (uint)GraphicsLayouts.RectangleMaxY, 45);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x0000_0000u);
            bus.WriteLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x000A_000Au);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0x000F_000Fu);
            bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0018_0019u);
        }

        void Execute(uint seed)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.AndRegionRegion],
                stack + 0x80u);
            cpu.State.A[0] = source;
            cpu.State.A[1] = destination;
            cpu.State.D[0] = seed;
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native AndRegionRegion body did not return (fallback {fallbackEntryOffset}).");
        }

        WriteDestinationNodes();
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 12);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 22);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 18);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 28);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0006_0006u);
        Execute(0x1234_5678u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destination + (uint)GraphicsLayouts.RegionRectangle,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0006_0006u, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Contains(
            (destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        WriteDestinationNodes();
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 27);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 37);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 32);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 42);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0005_0005u);
        Execute(0x2345_6789u);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationSecondNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(0u, bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0005_0005u, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Contains(
            (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // A partial source intersection confined to the first destination
        // node rewrites that node to the exact inclusive intersection.
        WriteDestinationNodes();
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 8);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 18);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 18);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 28);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x000A_000Au);
        Execute(0x3456_789Au);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)10, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)18, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)28, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(0u, bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0008_0008u, bus.ReadLong(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Contains(
            (destinationSecondNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);

        // The same partial reduction works when the second destination node
        // is the selected one; the first node is the only retired object.
        WriteDestinationNodes();
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 25);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 33);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 32);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 42);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0007_0009u);
        Execute(0x4567_89ABu);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(destinationSecondNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)25, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)35, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)32, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)42, bus.ReadWord(destination + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(0u, bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal(0x0007_0007u, bus.ReadLong(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Contains(
            (destinationFirstNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
            frees);
        Assert.Equal(4, frees.Count);

        WriteDestinationNodes();
        bus.WriteLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious, 0);
        Execute(0x5678_9ABCu);
        Assert.Equal(0x5678_9ABCu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(4, frees.Count);

        // A source spanning both destination nodes requires a multi-node
        // result and must remain on the portable builder.
        WriteDestinationNodes();
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinX, 19);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMinY, 29);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxX, 26);
        bus.WriteWord(source + (uint)GraphicsLayouts.RectangleMaxY, 35);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds, 0);
        bus.WriteLong(sourceNode + (uint)GraphicsLayouts.RegionRectangleBounds + 4u, 0x0007_0006u);
        Execute(0x6789_ABCDu);
        Assert.Equal(0x6789_ABCDu, cpu.State.D[0]);
        Assert.Equal(destinationFirstNode, bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(4, frees.Count);

    }

    [Fact]
    public void NativeGraphicsAndRegionRegionAcceptsSourceContainingBothCanonicalDestinationNodesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x008D_0000;
        const uint execBase = 0x007D_0000;
        const uint sourceAllocation = 0x00E5_0000;
        const uint sourceNode = 0x00E5_1000;
        const uint destinationAllocation = 0x00E5_2000;
        const uint destinationFirstNode = 0x00E5_3000;
        const uint destinationSecondNode = 0x00E5_4000;
        const uint stack = 0x00CD_0000;
        const uint returnAddress = 0x00FD_0000;
        var source = sourceAllocation + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var destination = destinationAllocation +
            (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     sourceAllocation, sourceNode, destinationAllocation,
                     destinationFirstNode, destinationSecondNode
                 })
        {
            var bytes = address is sourceAllocation or destinationAllocation
                ? GraphicsLayouts.NativeRegionAllocationSize
                : GraphicsLayouts.RegionRectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }
        bus.MapWritableMemory(stack, new byte[0x200]);

        void WriteNode(
            uint node,
            uint previous,
            uint next,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectanglePrevious, previous);
            bus.WriteLong(node + (uint)GraphicsLayouts.RegionRectangleNext, next);
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(node + (uint)GraphicsLayouts.RegionRectangleBounds +
                (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void WriteRegion(uint allocation, uint region, uint head)
        {
            bus.WriteWord(allocation, GraphicsLayouts.NativeRegionMarker);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinX, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMinY, 0);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxX, 20);
            bus.WriteWord(region + (uint)GraphicsLayouts.RectangleMaxY, 30);
            bus.WriteLong(region + (uint)GraphicsLayouts.RegionRectangle, head);
        }

        WriteRegion(sourceAllocation, source, sourceNode);
        WriteNode(
            sourceNode,
            source + (uint)GraphicsLayouts.RegionRectangle,
            0,
            0, 0, 20, 30);
        WriteRegion(destinationAllocation, destination, destinationFirstNode);
        WriteNode(
            destinationFirstNode,
            destination + (uint)GraphicsLayouts.RegionRectangle,
            destinationSecondNode,
            0, 0, 10, 10);
        WriteNode(
            destinationSecondNode,
            destinationFirstNode,
            0,
            0, 20, 20, 25);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeAddress + (uint)entryOffsets[GraphicsLvo.AndRegionRegion],
            stack + 0x80u);
        cpu.State.A[0] = source;
        cpu.State.A[1] = destination;
        cpu.State.D[0] = 0xC0DE_5330u;
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(sourceNode,
            bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(destinationSecondNode,
            bus.ReadLong(destinationFirstNode + (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(destinationFirstNode,
            bus.ReadLong(destinationSecondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)10, bus.ReadWord(destinationFirstNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(destinationSecondNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));
        _ = fallbackEntryOffset;
    }

    [Fact]
    public void NativeGraphicsOrRectRegionPublishesTwoFreshNodesForDisjointCanonicalUnionOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0086_0000;
        const uint execBase = 0x0076_0000;
        const uint allocationBase = 0x00D8_0000;
        const uint existingNode = 0x00D8_1000;
        const uint firstReplacementNode = 0x00D8_2000;
        const uint secondReplacementNode = 0x00D8_3000;
        const uint rectangle = 0x00D8_4000;
        const uint failedAllocationBase = 0x00D8_5000;
        const uint failedExistingNode = 0x00D8_6000;
        const uint failedFirstReplacementNode = 0x00D8_7000;
        const uint oddAllocationBase = 0x00D8_8000;
        const uint oddExistingNode = 0x00D8_9000;
        const uint oddReplacementNode = 0x00D8_A001;
        const uint highAllocationBase = 0x00D8_B000;
        const uint highExistingNode = 0x00D8_C000;
        const uint wrappingReplacementNode = 0xFFFF_FFF2u;
        const uint stack = 0x00C6_0000;
        const uint returnAddress = 0x00F6_0000;
        var region = allocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(
            allocationBase,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(existingNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(firstReplacementNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(secondReplacementNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(rectangle, new byte[GraphicsLayouts.RectangleSize]);
        bus.MapWritableMemory(
            failedAllocationBase,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(failedExistingNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(failedFirstReplacementNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(
            oddAllocationBase,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(oddExistingNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(
            highAllocationBase,
            new byte[GraphicsLayouts.NativeRegionAllocationSize]);
        bus.MapWritableMemory(highExistingNode, new byte[GraphicsLayouts.RegionRectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            allocationBase,
            existingNode,
            firstReplacementNode,
            secondReplacementNode,
            failedAllocationBase,
            failedExistingNode,
            failedFirstReplacementNode,
            0u,
            oddAllocationBase,
            oddExistingNode,
            oddReplacementNode,
            highAllocationBase,
            highExistingNode,
            wrappingReplacementNode
        });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 2048)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[vector],
                stack + 0x80u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} Region body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xC001_C0DEu);
        Assert.Equal(region, cpu.State.D[0]);

        // Seed the canonical one-node Region below and to the right of the
        // input. The replacement list must sort the input first by minY.
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 30);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 45);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(existingNode, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = region;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1357_9BDFu;
            });

        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations);
        Assert.Equal(
            new[] { (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u) },
            frees);
        Assert.Equal((ushort)10, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)34, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)45, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(firstReplacementNode, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(secondReplacementNode, bus.ReadLong(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(region + (uint)GraphicsLayouts.RegionRectangle, bus.ReadLong(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u, bus.ReadLong(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(firstReplacementNode, bus.ReadLong(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)0, bus.ReadWord(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)0, bus.ReadWord(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)4, bus.ReadWord(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)5, bus.ReadWord(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal((ushort)20, bus.ReadWord(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)20, bus.ReadWord(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)24, bus.ReadWord(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleBounds + (uint)GraphicsLayouts.RectangleMaxY));

        // If the second replacement allocation fails, the provisional first
        // node is released and the old list remains published verbatim.
        var failedRegion = failedAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xA1B2_C3D4u);
        Assert.Equal(failedRegion, cpu.State.D[0]);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 30);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 45);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = failedRegion;
                cpu.State.A[1] = rectangle;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(failedExistingNode, bus.ReadLong(failedRegion +
            (uint)GraphicsLayouts.RegionRectangle));

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = failedRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x2468_ACEEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(8, allocations.Count);
        Assert.Equal(
            new[]
            {
                (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedFirstReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            frees);
        Assert.Equal((ushort)30, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)40, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)34, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)45, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(failedExistingNode, bus.ReadLong(failedRegion +
            (uint)GraphicsLayouts.RegionRectangle));

        // A malformed odd result from the first replacement allocation is
        // released immediately.  As with an ordinary allocation failure, it
        // cannot disturb the canonical old node or the caller stack frame.
        var oddRegion = oddAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x55AA_55AAu);
        Assert.Equal(oddRegion, cpu.State.D[0]);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 30);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 45);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = oddRegion;
                cpu.State.A[1] = rectangle;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(oddExistingNode, bus.ReadLong(oddRegion +
            (uint)GraphicsLayouts.RegionRectangle));

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = oddRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x89AB_CDEFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(11, allocations.Count);
        Assert.Equal(
            new[]
            {
                (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedFirstReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (oddReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            frees);
        Assert.Equal((ushort)30, bus.ReadWord(oddRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)40, bus.ReadWord(oddRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)34, bus.ReadWord(oddRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)45, bus.ReadWord(oddRegion + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(oddExistingNode, bus.ReadLong(oddRegion +
            (uint)GraphicsLayouts.RegionRectangle));

        // A result that cannot contain the complete 16-byte node envelope is
        // the same transaction failure: it is released without publishing a
        // wrapping guest pointer or altering the existing Region.
        var highRegion = highAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xAA55_AA55u);
        Assert.Equal(highRegion, cpu.State.D[0]);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 30);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 40);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 34);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 45);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = highRegion;
                cpu.State.A[1] = rectangle;
            });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(highExistingNode, bus.ReadLong(highRegion +
            (uint)GraphicsLayouts.RegionRectangle));

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 10);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 20);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 14);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 25);
        Execute(
            GraphicsLvo.OrRectRegion,
            () =>
            {
                cpu.State.A[0] = highRegion;
                cpu.State.A[1] = rectangle;
                cpu.State.D[0] = 0x1020_3040u;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(14, allocations.Count);
        Assert.Equal(
            new[]
            {
                (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedFirstReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (oddReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (wrappingReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            frees);
        Assert.Equal((ushort)30, bus.ReadWord(highRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)40, bus.ReadWord(highRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)34, bus.ReadWord(highRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)45, bus.ReadWord(highRegion + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(highExistingNode, bus.ReadLong(highRegion +
            (uint)GraphicsLayouts.RegionRectangle));
    }

    [Fact]
    public void NativeGraphicsOrRectRegionPublishesThreeFreshNodesForCanonicalLShapedUnionOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x0087_0000;
        const uint execBase = 0x0077_0000;
        const uint allocationBase = 0x00D9_0000;
        const uint existingNode = 0x00D9_1000;
        const uint firstReplacementNode = 0x00D9_2000;
        const uint secondReplacementNode = 0x00D9_3000;
        const uint thirdReplacementNode = 0x00D9_4000;
        const uint failedAllocationBase = 0x00D9_5000;
        const uint failedExistingNode = 0x00D9_6000;
        const uint failedFirstReplacementNode = 0x00D9_7000;
        const uint failedSecondReplacementNode = 0x00D9_8000;
        const uint rectangle = 0x00D9_9000;
        const uint mirroredAllocationBase = 0x00D9_A000;
        const uint mirroredExistingNode = 0x00D9_B000;
        const uint mirroredFirstReplacementNode = 0x00D9_C000;
        const uint mirroredSecondReplacementNode = 0x00D9_D000;
        const uint mirroredThirdReplacementNode = 0x00D9_E000;
        const uint lowerLeftAllocationBase = 0x00D9_F000;
        const uint lowerLeftExistingNode = 0x00DA_0000;
        const uint lowerLeftFirstReplacementNode = 0x00DA_1000;
        const uint lowerLeftSecondReplacementNode = 0x00DA_2000;
        const uint lowerLeftThirdReplacementNode = 0x00DA_3000;
        const uint lowerRightAllocationBase = 0x00DA_4000;
        const uint lowerRightExistingNode = 0x00DA_5000;
        const uint lowerRightFirstReplacementNode = 0x00DA_6000;
        const uint lowerRightSecondReplacementNode = 0x00DA_7000;
        const uint lowerRightThirdReplacementNode = 0x00DA_8000;
        const uint crossingBarAllocationBase = 0x00DA_9000;
        const uint crossingBarExistingNode = 0x00DA_A000;
        const uint crossingBarFirstReplacementNode = 0x00DA_B000;
        const uint crossingBarSecondReplacementNode = 0x00DA_C000;
        const uint crossingBarThirdReplacementNode = 0x00DA_D000;
        const uint verticalBarAllocationBase = 0x00DA_E000;
        const uint verticalBarExistingNode = 0x00DA_F000;
        const uint verticalBarFirstReplacementNode = 0x00DB_0000;
        const uint verticalBarSecondReplacementNode = 0x00DB_1000;
        const uint verticalBarThirdReplacementNode = 0x00DB_2000;
        const uint leftTBarAllocationBase = 0x00DB_3000;
        const uint leftTBarExistingNode = 0x00DB_4000;
        const uint leftTBarFirstReplacementNode = 0x00DB_5000;
        const uint leftTBarSecondReplacementNode = 0x00DB_6000;
        const uint leftTBarThirdReplacementNode = 0x00DB_7000;
        const uint rightTBarAllocationBase = 0x00DB_8000;
        const uint rightTBarExistingNode = 0x00DB_9000;
        const uint rightTBarFirstReplacementNode = 0x00DB_A000;
        const uint rightTBarSecondReplacementNode = 0x00DB_B000;
        const uint rightTBarThirdReplacementNode = 0x00DB_C000;
        const uint stack = 0x00C7_0000;
        const uint returnAddress = 0x00F7_0000;
        var region = allocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var failedRegion = failedAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var mirroredRegion = mirroredAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var lowerLeftRegion = lowerLeftAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var lowerRightRegion = lowerRightAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var crossingBarRegion = crossingBarAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var verticalBarRegion = verticalBarAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var leftTBarRegion = leftTBarAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;
        var rightTBarRegion = rightTBarAllocationBase + (uint)GraphicsLayouts.NativeRegionPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        foreach (var address in new[]
                 {
                     allocationBase, existingNode, firstReplacementNode,
                     secondReplacementNode, thirdReplacementNode,
                     failedAllocationBase, failedExistingNode,
                     failedFirstReplacementNode, failedSecondReplacementNode,
                     mirroredAllocationBase, mirroredExistingNode,
                     mirroredFirstReplacementNode, mirroredSecondReplacementNode,
                     mirroredThirdReplacementNode,
                     lowerLeftAllocationBase, lowerLeftExistingNode,
                     lowerLeftFirstReplacementNode, lowerLeftSecondReplacementNode,
                     lowerLeftThirdReplacementNode,
                     lowerRightAllocationBase, lowerRightExistingNode,
                     lowerRightFirstReplacementNode, lowerRightSecondReplacementNode,
                     lowerRightThirdReplacementNode,
                     crossingBarAllocationBase, crossingBarExistingNode,
                     crossingBarFirstReplacementNode, crossingBarSecondReplacementNode,
                     crossingBarThirdReplacementNode,
                     verticalBarAllocationBase, verticalBarExistingNode,
                     verticalBarFirstReplacementNode, verticalBarSecondReplacementNode,
                     verticalBarThirdReplacementNode,
                     leftTBarAllocationBase, leftTBarExistingNode,
                     leftTBarFirstReplacementNode, leftTBarSecondReplacementNode,
                     leftTBarThirdReplacementNode,
                     rightTBarAllocationBase, rightTBarExistingNode,
                     rightTBarFirstReplacementNode, rightTBarSecondReplacementNode,
                     rightTBarThirdReplacementNode,
                     rectangle, stack
                 })
        {
            var bytes = address is allocationBase or failedAllocationBase or mirroredAllocationBase or lowerLeftAllocationBase or lowerRightAllocationBase or crossingBarAllocationBase or verticalBarAllocationBase or leftTBarAllocationBase or rightTBarAllocationBase
                ? GraphicsLayouts.NativeRegionAllocationSize
                : address == stack ? 0x200 : GraphicsLayouts.RegionRectangleSize;
            if (address == rectangle)
                bytes = GraphicsLayouts.RectangleSize;
            bus.MapWritableMemory(address, new byte[bytes]);
        }

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size, uint Flags)>();
        var allocationResults = new Queue<uint>(new[]
        {
            allocationBase, existingNode, firstReplacementNode,
            secondReplacementNode, thirdReplacementNode,
            failedAllocationBase, failedExistingNode,
            failedFirstReplacementNode, failedSecondReplacementNode, 0u,
            failedFirstReplacementNode, failedSecondReplacementNode,
            mirroredAllocationBase, mirroredExistingNode,
            mirroredFirstReplacementNode, mirroredSecondReplacementNode,
            mirroredThirdReplacementNode,
            lowerLeftAllocationBase, lowerLeftExistingNode,
            lowerLeftFirstReplacementNode, lowerLeftSecondReplacementNode,
            lowerLeftThirdReplacementNode,
            lowerRightAllocationBase, lowerRightExistingNode,
            lowerRightFirstReplacementNode, lowerRightSecondReplacementNode,
            lowerRightThirdReplacementNode,
            crossingBarAllocationBase, crossingBarExistingNode,
            crossingBarFirstReplacementNode, crossingBarSecondReplacementNode,
            crossingBarThirdReplacementNode,
            verticalBarAllocationBase, verticalBarExistingNode,
            verticalBarFirstReplacementNode, verticalBarSecondReplacementNode,
            verticalBarThirdReplacementNode,
            leftTBarAllocationBase, leftTBarExistingNode,
            leftTBarFirstReplacementNode, leftTBarSecondReplacementNode,
            leftTBarThirdReplacementNode,
            rightTBarAllocationBase, rightTBarExistingNode,
            rightTBarFirstReplacementNode, rightTBarSecondReplacementNode,
            rightTBarThirdReplacementNode
        });
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResults.Dequeue();
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[0], state.D[0], state.D[1])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 4096)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(codeAddress + (uint)entryOffsets[vector], stack + 0x80u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} Region body did not return (fallback {fallbackEntryOffset}).");
        }

        void WriteInput(short minX, short minY, short maxX, short maxY)
        {
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, unchecked((ushort)minX));
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, unchecked((ushort)minY));
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, unchecked((ushort)maxX));
            bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, unchecked((ushort)maxY));
        }

        void SeedCanonicalRegion(uint target)
        {
            WriteInput(8, 18, 19, 30);
            Execute(GraphicsLvo.OrRectRegion, () =>
            {
                cpu.State.A[0] = target;
                cpu.State.A[1] = rectangle;
            });
            Assert.Equal(1u, cpu.State.D[0]);
        }

        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x0102_0304u);
        Assert.Equal(region, cpu.State.D[0]);
        SeedCanonicalRegion(region);
        WriteInput(15, 25, 21, 32);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = region;
            cpu.State.A[1] = rectangle;
            cpu.State.D[0] = 0xDEAD_BEEFu;
        });

        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(firstReplacementNode, bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(secondReplacementNode, bus.ReadLong(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(thirdReplacementNode, bus.ReadLong(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(thirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(region + (uint)GraphicsLayouts.RegionRectangle, bus.ReadLong(firstReplacementNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(firstReplacementNode, bus.ReadLong(secondReplacementNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(secondReplacementNode, bus.ReadLong(thirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal((ushort)8, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)21, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)32, bus.ReadWord(region + (uint)GraphicsLayouts.RectangleMaxY));

        void AssertBounds(uint node, short minX, short minY, short maxX, short maxY)
        {
            var bounds = node + (uint)GraphicsLayouts.RegionRectangleBounds;
            Assert.Equal(unchecked((ushort)minX), bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal(unchecked((ushort)minY), bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal(unchecked((ushort)maxX), bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal(unchecked((ushort)maxY), bus.ReadWord(bounds + (uint)GraphicsLayouts.RectangleMaxY));
        }

        AssertBounds(firstReplacementNode, 0, 0, 11, 6);
        AssertBounds(secondReplacementNode, 0, 7, 13, 12);
        AssertBounds(thirdReplacementNode, 7, 13, 13, 14);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Take(5));
        Assert.Equal(
            new[] { (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u) },
            frees);

        // Third allocation failure must retire both provisional nodes while
        // keeping the old one-node header observable without alteration.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x0A0B_0C0Du);
        Assert.Equal(failedRegion, cpu.State.D[0]);
        SeedCanonicalRegion(failedRegion);
        WriteInput(15, 25, 21, 32);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = failedRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(failedExistingNode, bus.ReadLong(failedRegion + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal((ushort)8, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)19, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)30, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(
            new[]
            {
                (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedSecondReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedFirstReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            frees);

        // XOR of disjoint sets is their union. The native XOR front end may
        // therefore restore its frame and reuse the tested OR replacement
        // transaction, without applying OR semantics to an overlap.
        WriteInput(40, 40, 45, 45);
        Execute(GraphicsLvo.XorRectRegion, () =>
        {
            cpu.State.A[0] = failedRegion;
            cpu.State.A[1] = rectangle;
            cpu.State.D[0] = 0x0246_8ACEu;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(failedFirstReplacementNode, bus.ReadLong(failedRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(failedSecondReplacementNode, bus.ReadLong(failedFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)8, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)45, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)45, bus.ReadWord(failedRegion + (uint)GraphicsLayouts.RectangleMaxY));
        Assert.Equal(
            new[]
            {
                (existingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedSecondReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedFirstReplacementNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                (failedExistingNode, (uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            frees);

        // Horizontal mirror of the original L: the existing rectangle is
        // upper-right and the input rectangle is lower-left. The native path
        // shares the same three-node transaction but must choose the input
        // minimum X as the new relative-coordinate origin.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x1020_3040u);
        Assert.Equal(mirroredRegion, cpu.State.D[0]);
        WriteInput(15, 18, 26, 30);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = mirroredRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);

        WriteInput(8, 25, 21, 32);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = mirroredRegion;
            cpu.State.A[1] = rectangle;
        });

        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(mirroredFirstReplacementNode, bus.ReadLong(mirroredRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(mirroredSecondReplacementNode, bus.ReadLong(mirroredFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(mirroredThirdReplacementNode, bus.ReadLong(mirroredSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(mirroredThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)8, bus.ReadWord(mirroredRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(mirroredRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)26, bus.ReadWord(mirroredRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)32, bus.ReadWord(mirroredRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(mirroredFirstReplacementNode, 7, 0, 18, 6);
        AssertBounds(mirroredSecondReplacementNode, 0, 7, 18, 12);
        AssertBounds(mirroredThirdReplacementNode, 0, 13, 13, 14);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(12).Take(5));
        Assert.Equal(mirroredExistingNode, frees[^1].Address);

        // Vertical mirror: old lower-left plus input upper-right. This
        // changes the Region's minimum Y and maximum X, while retaining the
        // old minimum X and maximum Y for the lower-left band.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x5060_7080u);
        Assert.Equal(lowerLeftRegion, cpu.State.D[0]);
        WriteInput(8, 25, 19, 37);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = lowerLeftRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(lowerLeftRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)25, bus.ReadWord(lowerLeftRegion + (uint)GraphicsLayouts.RectangleMinY));

        WriteInput(15, 18, 21, 30);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = lowerLeftRegion;
            cpu.State.A[1] = rectangle;
        });

        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(lowerLeftFirstReplacementNode, bus.ReadLong(lowerLeftRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(lowerLeftSecondReplacementNode, bus.ReadLong(lowerLeftFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(lowerLeftThirdReplacementNode, bus.ReadLong(lowerLeftSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(lowerLeftThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)8, bus.ReadWord(lowerLeftRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(lowerLeftRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)21, bus.ReadWord(lowerLeftRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)37, bus.ReadWord(lowerLeftRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(lowerLeftFirstReplacementNode, 7, 0, 13, 6);
        AssertBounds(lowerLeftSecondReplacementNode, 0, 7, 13, 12);
        AssertBounds(lowerLeftThirdReplacementNode, 0, 13, 11, 19);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(17).Take(5));
        Assert.Equal(lowerLeftExistingNode, frees[^1].Address);

        // Final L mirror: old lower-right plus input upper-left. Both Region
        // minima become input-driven, while the old maxima close the lower-right band.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0x90A0_B0C0u);
        Assert.Equal(lowerRightRegion, cpu.State.D[0]);
        WriteInput(15, 25, 26, 37);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = lowerRightRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        WriteInput(8, 18, 21, 30);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = lowerRightRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(lowerRightFirstReplacementNode, bus.ReadLong(lowerRightRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(lowerRightSecondReplacementNode, bus.ReadLong(lowerRightFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(lowerRightThirdReplacementNode, bus.ReadLong(lowerRightSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(lowerRightThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)8, bus.ReadWord(lowerRightRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)18, bus.ReadWord(lowerRightRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)26, bus.ReadWord(lowerRightRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)37, bus.ReadWord(lowerRightRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(lowerRightFirstReplacementNode, 0, 0, 13, 6);
        AssertBounds(lowerRightSecondReplacementNode, 0, 7, 18, 12);
        AssertBounds(lowerRightThirdReplacementNode, 7, 13, 18, 19);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(22).Take(5));
        Assert.Equal(lowerRightExistingNode, frees[^1].Address);

        // A horizontal bar that crosses both X edges of the old one-node
        // Region creates the same three-node transaction, but with the
        // middle bar expanding the Region's two X bounds.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xD0E0_F001u);
        Assert.Equal(crossingBarRegion, cpu.State.D[0]);
        WriteInput(10, 10, 20, 20);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = crossingBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        WriteInput(5, 14, 25, 16);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = crossingBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(crossingBarFirstReplacementNode, bus.ReadLong(crossingBarRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(crossingBarSecondReplacementNode, bus.ReadLong(crossingBarFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(crossingBarThirdReplacementNode, bus.ReadLong(crossingBarSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(crossingBarThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)5, bus.ReadWord(crossingBarRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)10, bus.ReadWord(crossingBarRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)25, bus.ReadWord(crossingBarRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)20, bus.ReadWord(crossingBarRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(crossingBarFirstReplacementNode, 5, 0, 15, 3);
        AssertBounds(crossingBarSecondReplacementNode, 0, 4, 20, 6);
        AssertBounds(crossingBarThirdReplacementNode, 5, 7, 15, 10);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(27).Take(5));
        Assert.Equal(crossingBarExistingNode, frees[^1].Address);

        // Vertical counterpart: the input crosses both Y edges but remains
        // strictly inside the old X span.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xD0E0_F002u);
        Assert.Equal(verticalBarRegion, cpu.State.D[0]);
        WriteInput(10, 10, 20, 20);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = verticalBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        WriteInput(14, 5, 16, 25);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = verticalBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(verticalBarFirstReplacementNode, bus.ReadLong(verticalBarRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(verticalBarSecondReplacementNode, bus.ReadLong(verticalBarFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(verticalBarThirdReplacementNode, bus.ReadLong(verticalBarSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(verticalBarThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)10, bus.ReadWord(verticalBarRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)5, bus.ReadWord(verticalBarRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20, bus.ReadWord(verticalBarRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)25, bus.ReadWord(verticalBarRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(verticalBarFirstReplacementNode, 4, 0, 6, 4);
        AssertBounds(verticalBarSecondReplacementNode, 0, 5, 10, 15);
        AssertBounds(verticalBarThirdReplacementNode, 4, 16, 6, 20);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(32).Take(5));
        Assert.Equal(verticalBarExistingNode, frees[^1].Address);

        // A one-sided horizontal T extends only the old left edge. Its middle
        // band stops at the original right edge, while the upper and lower
        // bands remain the old rectangle.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xD0E0_F003u);
        Assert.Equal(leftTBarRegion, cpu.State.D[0]);
        WriteInput(10, 10, 20, 20);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = leftTBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        WriteInput(5, 14, 15, 16);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = leftTBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(leftTBarFirstReplacementNode, bus.ReadLong(leftTBarRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(leftTBarSecondReplacementNode, bus.ReadLong(leftTBarFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(leftTBarThirdReplacementNode, bus.ReadLong(leftTBarSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(leftTBarThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)5, bus.ReadWord(leftTBarRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)10, bus.ReadWord(leftTBarRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)20, bus.ReadWord(leftTBarRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)20, bus.ReadWord(leftTBarRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(leftTBarFirstReplacementNode, 5, 0, 15, 3);
        AssertBounds(leftTBarSecondReplacementNode, 0, 4, 15, 6);
        AssertBounds(leftTBarThirdReplacementNode, 5, 7, 15, 10);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(37).Take(5));
        Assert.Equal(leftTBarExistingNode, frees[^1].Address);

        // Right-side mirror of the one-sided T: the middle band extends the
        // old right edge while the upper and lower bands retain the old width.
        Execute(GraphicsLvo.NewRegion, () => cpu.State.D[0] = 0xD0E0_F004u);
        Assert.Equal(rightTBarRegion, cpu.State.D[0]);
        WriteInput(10, 10, 20, 20);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = rightTBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        WriteInput(15, 14, 25, 16);
        Execute(GraphicsLvo.OrRectRegion, () =>
        {
            cpu.State.A[0] = rightTBarRegion;
            cpu.State.A[1] = rectangle;
        });
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(rightTBarFirstReplacementNode, bus.ReadLong(rightTBarRegion +
            (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(rightTBarSecondReplacementNode, bus.ReadLong(rightTBarFirstReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(rightTBarThirdReplacementNode, bus.ReadLong(rightTBarSecondReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal(0u, bus.ReadLong(rightTBarThirdReplacementNode +
            (uint)GraphicsLayouts.RegionRectangleNext));
        Assert.Equal((ushort)10, bus.ReadWord(rightTBarRegion + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((ushort)10, bus.ReadWord(rightTBarRegion + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((ushort)25, bus.ReadWord(rightTBarRegion + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((ushort)20, bus.ReadWord(rightTBarRegion + (uint)GraphicsLayouts.RectangleMaxY));
        AssertBounds(rightTBarFirstReplacementNode, 0, 0, 10, 3);
        AssertBounds(rightTBarSecondReplacementNode, 0, 4, 15, 6);
        AssertBounds(rightTBarThirdReplacementNode, 0, 7, 10, 10);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.NativeRegionAllocationSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u),
                ((uint)GraphicsLayouts.RegionRectangleSize, 0x0000_0001u)
            },
            allocations.Skip(42).Take(5));
        Assert.Equal(rightTBarExistingNode, frees[^1].Address);
    }

    [Fact]
    public void NativeGraphicsColorMapLifecycleUsesContiguousExecEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x00A2_0000;
        const uint execBase = 0x0072_0000;
        const uint allocationBase = 0x00D4_0000;
        const uint foreignMap = 0x00D5_0000;
        const uint stack = 0x00C2_0000;
        const uint returnAddress = 0x00F2_0000;
        const uint entries = 3;
        var allocationSize = (uint)GraphicsLayouts.NativeColorMapBaseSize + (entries * 4u);
        var map = allocationBase + (uint)GraphicsLayouts.NativeColorMapPrivatePrefixSize;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(allocationBase, new byte[(int)allocationSize]);
        bus.MapWritableMemory(foreignMap, new byte[GraphicsLayouts.ColorMapSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationBase;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A1;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            // Match production Exec: A1 is the allocation, D0 its size.
            // D1 is volatile scratch, not a FreeMem flags argument.
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A1;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 768)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[vector],
                stack + 0x80u);
            configure();
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    Assert.Equal(stack + 0x84u, cpu.State.A[7]);
                    return;
                }
            }

            throw new InvalidOperationException(
                $"Native {vector} ColorMap body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(
            GraphicsLvo.GetColorMap,
            () => cpu.State.D[0] = entries);
        Assert.Equal(map, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationSize, 0x0001_0001u) },
            allocations);
        Assert.Equal(GraphicsLayouts.NativeColorMapMarker, bus.ReadWord(allocationBase));
        Assert.Equal(allocationSize, bus.ReadLong(allocationBase + 4u));
        Assert.Equal((byte)0x02, bus.ReadByte(map + (uint)GraphicsLayouts.ColorMapType));
        Assert.Equal((ushort)entries, bus.ReadWord(map + (uint)GraphicsLayouts.ColorMapCount));
        var colorTable = map + (uint)GraphicsLayouts.ColorMapSize;
        var lowColorBits = colorTable + (entries * 2u);
        Assert.Equal(colorTable, bus.ReadLong(map + (uint)GraphicsLayouts.ColorMapColorTable));
        Assert.Equal(lowColorBits, bus.ReadLong(map + (uint)GraphicsLayouts.ColorMapLowColorBits));
        Assert.Equal(0u, bus.ReadLong(map + (uint)GraphicsLayouts.ColorMapModeId));
        for (var index = 0u; index < entries * 4u; index++)
            Assert.Equal((byte)0, bus.ReadByte(colorTable + index));

        Execute(
            GraphicsLvo.FreeColorMap,
            () =>
            {
                cpu.State.A[0] = map;
                cpu.State.D[0] = 0xCAFE_BABEu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBase, allocationSize) },
            frees);

        Execute(
            GraphicsLvo.FreeColorMap,
            () =>
            {
                cpu.State.A[0] = 0;
                cpu.State.D[0] = 0x1357_9BDFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Single(frees);

        Execute(
            GraphicsLvo.FreeColorMap,
            () =>
            {
                cpu.State.A[0] = foreignMap;
                cpu.State.D[0] = 0x2468_ACEEu;
            });
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);
        Assert.Single(frees);
    }

    [Fact]
    public void NativeGraphicsGetColorMapOddAllocationUsesExecFreeMemA1BeforeFallback()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x00A2_0000;
        const uint execBase = 0x0072_0000;
        const uint oddAllocation = 0x00D4_0001;
        const uint stackPointer = 0x00C2_0080;
        const uint returnAddress = 0x00F2_0000;
        const uint entries = 2;
        const uint allocationSize = GraphicsLayouts.NativeColorMapBaseSize + entries * 4;
        var originalBytes = Enumerable.Repeat((byte)0xA5, (int)allocationSize + 2).ToArray();
        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(oddAllocation - 1, originalBytes.ToArray());
        bus.MapWritableMemory(stackPointer - 0x80, new byte[0x200]);
        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();

        void AssertAllocationUntouched()
            => Assert.Equal(originalBytes, Enumerable.Range(0, originalBytes.Length)
                .Select(index => bus.ReadByte(oddAllocation - 1 + (uint)index)).ToArray());

        bus.RegisterHostGateway(execBase - 198, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = oddAllocation;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A1;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(execBase - 210, state =>
        {
            AssertAllocationUntouched();
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A1;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000, bus);
        bus.WriteLong(stackPointer, returnAddress);
        cpu.Reset(codeAddress + (uint)entryOffsets[GraphicsLvo.GetColorMap], stackPointer);
        cpu.State.D[0] = entries;
        var usedFallback = false;
        var returned = false;
        for (var instruction = 0; instruction < 512; instruction++)
        {
            // A distant decline can use a local copy of the shared RTS.
            if (cpu.State.ProgramCounter == codeAddress + (uint)fallbackEntryOffset ||
                (cpu.State.D[0] == entries && bus.ReadWord(cpu.State.ProgramCounter) == 0x4E75))
            {
                usedFallback = true;
                Assert.Equal(entries, cpu.State.D[0]);
                Assert.Equal(stackPointer, cpu.State.A[7]);
            }

            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
            {
                returned = true;
                break;
            }
        }

        Assert.True(returned,
            $"ColorMap rollback did not return: PC={cpu.State.ProgramCounter:X8}, " +
            $"SR={cpu.State.StatusRegister:X4}, A7={cpu.State.A[7]:X8}.");
        Assert.True(usedFallback);
        Assert.Equal(entries, cpu.State.D[0]);
        Assert.Equal(stackPointer + 4, cpu.State.A[7]);
        Assert.Equal(new[] { (allocationSize, 0x0001_0001u) }, allocations);
        Assert.Equal(new[] { (oddAllocation, allocationSize) }, frees);
        AssertAllocationUntouched();
    }

    [Fact]
    public void NativeGraphicsSetChipRevPublishesAccumulatedCapabilitiesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x00A4_0000;
        const uint graphicsBase = 0x00E4_0000;
        const uint stack = 0x00C4_0000;
        const uint returnAddress = 0x00F4_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(graphicsBase, new byte[GraphicsLibraryImageLayout.MinimumImageSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);
        bus.WriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0,
            (byte)(GraphicsChipRevision.HrAgnus | GraphicsChipRevision.HrDenise),
            0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint request, uint expectedD0, uint baseAddress = graphicsBase)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.SetChipRev],
                stack + 0x80u);
            cpu.State.A[6] = baseAddress;
            cpu.State.D[0] = request;
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    Assert.Equal(expectedD0, cpu.State.D[0]);
                    return;
                }
            }

            throw new InvalidOperationException(
                $"Native {GraphicsLvo.SetChipRev} body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(GraphicsChipRevision.SetBest, GraphicsChipRevision.SetEcs);
        Assert.Equal(GraphicsChipRevision.SetEcs, cpu.State.D[0]);
        Assert.Equal(
            (byte)GraphicsChipRevision.SetEcs,
            bus.ReadByte(graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0));

        Execute(GraphicsChipRevision.SetAa, GraphicsChipRevision.SetEcs);
        Assert.Equal(GraphicsChipRevision.SetEcs, cpu.State.D[0]);
        Assert.Equal(
            (byte)GraphicsChipRevision.SetEcs,
            bus.ReadByte(graphicsBase + (uint)GraphicsLayouts.GfxBaseChipRevBits0));

        Execute(GraphicsChipRevision.SetA, GraphicsChipRevision.SetEcs);
        Assert.Equal(GraphicsChipRevision.SetEcs, cpu.State.D[0]);

        Execute(GraphicsChipRevision.SetEcs, GraphicsChipRevision.SetEcs, graphicsBase + 1u);
        Assert.Equal(GraphicsChipRevision.SetEcs, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsCalcIvgEmptyDisplayListReturnsZeroOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x00A6_0000;
        const uint view = 0x00E6_0000;
        const uint viewPort = 0x00E6_0100;
        const uint stack = 0x00C6_0000;
        const uint returnAddress = 0x00F6_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint viewAddress = view, uint viewPortAddress = viewPort)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.CalcIVG],
                stack + 0x80u);
            cpu.State.A[0] = viewAddress;
            cpu.State.A[1] = viewPortAddress;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {GraphicsLvo.CalcIVG} body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);

        // CalcIVG only consumes vp_DspIns, whose long spans +0x08..+0x0B.
        // The final valid aligned guest base is therefore $FFFF_FFF4; the
        // native arm must reach that exact-end field through the 24-bit alias.
        const uint topViewPort = 0xFFFF_FFF4u;
        const uint topViewPortPhysical = topViewPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topViewPortPhysical, new byte[0x0C]);
        bus.WriteLong(topViewPortPhysical +
            (uint)GraphicsLayouts.ViewPortDspIns, 0);
        Execute(0x1020_3040u, viewPortAddress: topViewPort);
        Assert.Equal(0u, cpu.State.D[0]);

        // This higher aligned pointer makes the four-byte DspIns read wrap
        // after the 32-bit guest limit and must decline before dereference.
        Execute(0x5566_7788u, viewPortAddress: 0xFFFF_FFF6u);
        Assert.Equal(0x5566_7788u, cpu.State.D[0]);

        // A complete preallocated blank CopList remains an empty display
        // list: CalcIVG can claim the timing-neutral zero result when its
        // ViewPort backlink and capacity are intact.
        const uint blankCopList = 0x00E6_0200;
        bus.MapWritableMemory(blankCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.WriteLong(
            blankCopList + (uint)GraphicsLayouts.CopListViewPort,
            viewPort);
        bus.WriteWord(
            blankCopList + (uint)GraphicsLayouts.CopListCount,
            0);
        bus.WriteWord(
            blankCopList + (uint)GraphicsLayouts.CopListMaxCount,
            1);
        bus.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
            blankCopList);
        Execute(0x1357_9BDFu);
        Assert.Equal(0u, cpu.State.D[0]);

        // A non-empty list is timing/provider-owned; the native empty arm
        // must decline without changing the caller's D0 sentinel.
        bus.WriteWord(
            blankCopList + (uint)GraphicsLayouts.CopListCount,
            1);
        Execute(0x1357_9BDFu);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);

        bus.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
            1u);
        Execute(0x2468_ACEEu);
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);

        Execute(0x0BAD_F00Du, viewAddress: view + 1u);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
        Execute(0xD00D_BEEFu, viewPortAddress: viewPort + 1u);
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsScrollVPortEmptyDisplayListSingleRasInfoIsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        const uint codeAddress = 0x00A8_0000;
        const uint viewPort = 0x00E8_0000;
        const uint rasInfo = 0x00E8_0100;
        const uint blankCopList = 0x00E8_0200;
        const uint stack = 0x00C8_0000;
        const uint returnAddress = 0x00F8_0000;

        var bus = new AmigaBus();
        bus.MapWritableMemory(codeAddress, nativeCode);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(blankCopList, new byte[GraphicsLayouts.CopListSize]);
        bus.MapWritableMemory(stack, new byte[0x200]);
        bus.WriteByte(viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 12);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 24);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint viewPortAddress = viewPort)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeAddress + (uint)entryOffsets[GraphicsLvo.ScrollVPort],
                stack + 0x80u);
            cpu.State.A[0] = viewPortAddress;
            cpu.State.D[0] = initialD0;
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {GraphicsLvo.ScrollVPort} body did not return (fallback {fallbackEntryOffset}).");
        }

        Execute(0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);

        // A standard ViewPort is 0x28 bytes.  Its exact-end logical header
        // remains valid through the accurate 68000's 24-bit bus alias.
        const uint topViewPort = 0xFFFF_FFD8u;
        const uint topViewPortPhysical = topViewPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topViewPortPhysical,
            new byte[GraphicsLayouts.ViewPortSize]);
        bus.WriteByte(topViewPortPhysical +
            (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteLong(topViewPortPhysical +
            (uint)GraphicsLayouts.ViewPortDspIns, 0);
        bus.WriteLong(topViewPortPhysical +
            (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        Execute(0x1020_3040u, topViewPort);
        Assert.Equal(0u, cpu.State.D[0]);

        // A complete RasInfo occupies twelve bytes.  The last valid aligned
        // guest header starts at $FFFF_FFF4 and must be readable through the
        // AccurateM68000 24-bit alias, including its Rx/Ry offsets.
        const uint topRasInfo = 0xFFFF_FFF4u;
        const uint topRasInfoPhysical = topRasInfo & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRasInfoPhysical, new byte[GraphicsLayouts.RasInfoSize]);
        bus.WriteLong(topRasInfoPhysical + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(topRasInfoPhysical + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        bus.WriteWord(topRasInfoPhysical + (uint)GraphicsLayouts.RasInfoRxOffset, 12);
        bus.WriteWord(topRasInfoPhysical + (uint)GraphicsLayouts.RasInfoRyOffset, 24);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, topRasInfo);
        Execute(0x89AB_CDEFu);
        Assert.Equal(0u, cpu.State.D[0]);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);

        // A preallocated blank CopList has no stream to rebuild, so the
        // native ScrollVPort arm preserves the same successful no-op result.
        bus.WriteLong(
            blankCopList + (uint)GraphicsLayouts.CopListViewPort,
            viewPort);
        bus.WriteWord(
            blankCopList + (uint)GraphicsLayouts.CopListCount,
            0);
        bus.WriteWord(
            blankCopList + (uint)GraphicsLayouts.CopListMaxCount,
            1);
        bus.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
            blankCopList);
        Execute(0x1357_9BDFu);
        Assert.Equal(0u, cpu.State.D[0]);

        // Populated display lists remain with the copper/display owner.
        bus.WriteWord(
            blankCopList + (uint)GraphicsLayouts.CopListCount,
            1);
        Execute(0x1357_9BDFu);
        Assert.Equal(0x1357_9BDFu, cpu.State.D[0]);

        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0x00E8_0300u);
        Execute(0x2468_ACEEu);
        Assert.Equal(0x2468_ACEEu, cpu.State.D[0]);

        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        Execute(0x0BAD_F00Du, viewPortAddress: viewPort + 1u);
        Assert.Equal(0x0BAD_F00Du, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsFreeDBufInfoNullReturnsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint dbufInfo, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FreeDBufInfo),
                stack + 0x80u);
            cpu.State.A[0] = 0xA0A0_A0A1u;
            cpu.State.A[1] = dbufInfo;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 32; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native FreeDBufInfo NULL body did not return.");
        }

        Execute(0, 0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);

        // Non-NULL values are deliberately unmapped: the native body must
        // decline before reading message envelopes or touching cancellation
        // state owned by the portable/provider path.
        Execute(0x00D6_0100u, 0xD00D_BEEFu);
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);

        Execute(0x00D6_0101u, 0xFACE_1234u);
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);

        Execute(0xFFFF_FFFCu, 0xABCD_9876u);
        Assert.Equal(0xABCD_9876u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsDBufInfoAllocatorUsesExecEnvelopeAndChainsDeclinesOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        const uint execBase = 0x0070_0000;
        const uint viewPort = 0x00D0_0000;
        const uint rasInfo = 0x00D0_1000;
        const uint allocationBase = 0x00D0_2000;
        const uint foreignBase = 0x00D0_3000;
        const uint linkedRasInfo = 0x00D0_4000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        const uint allocationBytes = GraphicsLayouts.DBufInfoSize + 4u;

        var bus = new AmigaBus();
        var nextCodeAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextCodeAllocation;
                nextCodeAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        bus.MapWritableMemory(4, new byte[4]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(linkedRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(allocationBase, new byte[checked((int)allocationBytes)]);
        bus.MapWritableMemory(foreignBase, new byte[checked((int)allocationBytes)]);
        bus.MapWritableMemory(stack, new byte[0x200]);
        bus.WriteByte(viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes, 0, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 3);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 4);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocationResult = allocationBase;
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            state.D[0] = allocationResult;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });
        bus.RegisterHostGateway(freeAddress, state =>
        {
            frees.Add((state.A[1], state.D[0]));
            state.D[0] = 0xD0D0_D0D0;
            state.D[1] = 0xD1D1_D1D1;
            state.A[0] = 0xA0A0_A0A0;
            state.A[1] = 0xA1A1_A1A1;
        });

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, Action configure, int maxInstructions = 256)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            configure();
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < maxInstructions; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                    return;
            }

            throw new InvalidOperationException(
                $"Native {vector} DBufInfo body did not return.");
        }

        Execute(
            GraphicsLvo.AllocDBufInfo,
            () =>
            {
                cpu.State.A[0] = viewPort;
                cpu.State.D[0] = 0xCAFE_BABEu;
            });
        Assert.Equal(allocationBase + 4u, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBytes, 0x0001_0001u) },
            allocations);
        Assert.Equal((ushort)0x4442, bus.ReadWord(allocationBase));
        Assert.Equal(
            (ushort)GraphicsLayouts.ExecMessageSize,
            bus.ReadWord(
                allocationBase + 4u + (uint)GraphicsLayouts.DBufInfoSafeMessage +
                (uint)GraphicsLayouts.ExecMessageLength));
        Assert.Equal(
            (ushort)GraphicsLayouts.ExecMessageSize,
            bus.ReadWord(
                allocationBase + 4u + (uint)GraphicsLayouts.DBufInfoDispMessage +
                (uint)GraphicsLayouts.ExecMessageLength));

        // A ViewPort near the 32-bit boundary can make its ordinary field
        // displacements alias a complete low-memory RasInfo.  It is not a
        // valid public descriptor and must decline before Exec allocation.
        const uint wrappedViewPort = 0xFFFF_FFFEu;
        const uint wrappedRasInfo = 0x40;
        bus.WriteByte(0x21, 0, 0); // wrapped vp_ExtendedModes
        bus.WriteLong(0x22, wrappedRasInfo); // wrapped vp_RasInfo
        bus.WriteLong(wrappedRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(wrappedRasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        bus.WriteWord(wrappedRasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        bus.WriteWord(wrappedRasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        Execute(
            GraphicsLvo.AllocDBufInfo,
            () =>
            {
                cpu.State.A[0] = wrappedViewPort;
                cpu.State.D[0] = 0xBADC_0010u;
            });
        Assert.Equal(0xBADC_0010u, cpu.State.D[0]);
        Assert.Single(allocations);

        // The RasInfo link itself has the same native address-envelope rule.
        // Its unreadable high fields must not be interpreted as a zeroed
        // low-memory descriptor and admitted to Exec allocation.
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, 0xFFFF_FFF6u);
        Execute(
            GraphicsLvo.AllocDBufInfo,
            () =>
            {
                cpu.State.A[0] = viewPort;
                cpu.State.D[0] = 0xBADC_0020u;
            });
        Assert.Equal(0xBADC_0020u, cpu.State.D[0]);
        Assert.Single(allocations);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);

        Execute(
            GraphicsLvo.FreeDBufInfo,
            () =>
            {
                cpu.State.A[0] = 0xA0A0_A0A1u;
                cpu.State.A[1] = allocationBase + 4u;
                cpu.State.D[0] = 0xDEAD_BEEFu;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[] { (allocationBase, allocationBytes) },
            frees);

        // The paired body owns only its marked envelope.  A foreign pointer
        // must preserve D0 and leave Exec untouched for the provider path.
        Execute(
            GraphicsLvo.FreeDBufInfo,
            () =>
            {
                cpu.State.A[0] = 0xA0A0_A0A1u;
                cpu.State.A[1] = foreignBase + 4u;
                cpu.State.D[0] = 0xD00D_BEEFu;
            });
        Assert.Equal(0xD00D_BEEFu, cpu.State.D[0]);
        Assert.Single(frees);

        // A linked RasInfo is outside the standard planar display envelope;
        // decline before Exec allocation while preserving the caller's D0.
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, linkedRasInfo);
        Execute(
            GraphicsLvo.AllocDBufInfo,
            () =>
            {
                cpu.State.A[0] = viewPort;
                cpu.State.D[0] = 0xFACE_1234u;
            });
        Assert.Equal(0xFACE_1234u, cpu.State.D[0]);
        Assert.Single(allocations);

        // Exec returning an odd address is rolled back with the exact span
        // and never published as a DBufInfo pointer.
        allocationResult = allocationBase + 1u;
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        Execute(
            GraphicsLvo.AllocDBufInfo,
            () =>
            {
                cpu.State.A[0] = viewPort;
                cpu.State.D[0] = 0xABCD_9876u;
            });
        Assert.Equal(0xABCD_9876u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (allocationBase, allocationBytes),
                (allocationBase + 1u, allocationBytes)
            },
            frees);

        Execute(
            GraphicsLvo.FreeDBufInfo,
            () =>
            {
                cpu.State.A[0] = 0xA0A0_A0A1u;
                cpu.State.A[1] = 0;
                cpu.State.D[0] = 7;
            });
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(2, frees.Count);
    }

    [Fact]
    public void NativeGraphicsFreeSpriteDataNullReturnsNoOpOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
