                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint graphicsBase = 0x00D0_0000;
        const uint monitorSpec = 0x00D1_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(
            graphicsBase,
            new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.MapWritableMemory(
            monitorSpec,
            new byte[GraphicsLayouts.MonitorSpecSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            uint monitorName,
            uint displayId,
            ushort openCount,
            bool residentDefault,
            uint libraryBase = graphicsBase,
            uint defaultMonitor = monitorSpec)
        {
            bus.WriteLong(
                graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
                residentDefault ? defaultMonitor : 0);
            bus.WriteWord(
                monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount,
                openCount);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.OpenMonitor),
                stack + 0x80u);
            cpu.State.A[1] = monitorName;
            cpu.State.A[6] = libraryBase;
            cpu.State.D[0] = displayId;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native OpenMonitor body did not return.");
        }

        Execute(0, GraphicsModeIds.Invalid, 1, true);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(0, 0u, 1, true);
        Assert.Equal(monitorSpec, cpu.State.D[0]);
        Assert.Equal(
            (ushort)2,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0x00D2_0000u,
            GraphicsModeIds.Invalid,
            2,
            true);
        Assert.Equal(GraphicsModeIds.Invalid, cpu.State.D[0]);
        Assert.Equal(
            (ushort)2,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            GraphicsModeIds.PalMonitor,
            3,
            true);
        Assert.Equal(GraphicsModeIds.PalMonitor, cpu.State.D[0]);
        Assert.Equal(
            (ushort)3,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            0u,
            0xFFFF,
            true);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)0xFFFF,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            0u,
            4,
            false);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)4,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            0u,
            5,
            true,
            graphicsBase + 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)5,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            0u,
            6,
            true,
            0xFFFF_FF00u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)6,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            0u,
            7,
            true,
            graphicsBase,
            monitorSpec + 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)7,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        Execute(
            0,
            0u,
            8,
            true,
            graphicsBase,
            0xFFFF_FF80u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)8,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
    }

