            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            uint monitorAddress,
            uint libraryBase,
            uint defaultMonitor,
            ushort openCount,
            uint initialD0)
        {
            bus.WriteLong(
                graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
