    [Fact]
    public void NativeGraphicsOpenFontClaimsResidentDefaultOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint graphicsBase = 0x00D0_0000;
        const uint textAttr = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint fontName = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(
            graphicsBase,
            new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.MapWritableMemory(textAttr, new byte[GraphicsLayouts.TextAttrSize]);
        bus.MapWritableMemory(
            font,
            new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        void SetAttributes(
            uint name,
            ushort ySize,
            byte style,
            byte flags)
        {
            bus.WriteLong(
                textAttr + (uint)GraphicsLayouts.TextAttrName,
                name);
            bus.WriteWord(
                textAttr + (uint)GraphicsLayouts.TextAttrYSize,
                ySize);
            bus.WriteByte(
                textAttr + (uint)GraphicsLayouts.TextAttrStyle,
                style,
                0);
            bus.WriteByte(
                textAttr + (uint)GraphicsLayouts.TextAttrFlags,
                flags,
                0);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            uint requestAddress,
            uint libraryBase,
            uint defaultFont,
            ushort accessors,
            uint initialD0)
        {
            bus.WriteLong(
                graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultFont,
                defaultFont);
            bus.WriteWord(
                font + (uint)GraphicsLayouts.TextFontAccessors,
                accessors);
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.OpenFont),
                stack + 0x80u);
            cpu.State.A[0] = requestAddress;
            cpu.State.A[6] = libraryBase;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 160; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native OpenFont body did not return.");
        }

        SetAttributes(fontName, 8, 1, 2);
        bus.WriteLong(
            font + (uint)GraphicsLayouts.TextFontName,
            fontName);
        bus.WriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            8);
        bus.WriteByte(
            font + (uint)GraphicsLayouts.TextFontStyle,
            1,
            0);
        bus.WriteByte(
            font + (uint)GraphicsLayouts.TextFontFlags,
            2,
            0);
        Execute(textAttr, graphicsBase, font, 3, 0xCAFE_0000u);
        Assert.Equal(font, cpu.State.D[0]);
        Assert.Equal(
            (ushort)4,
            bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        SetAttributes(fontName + 4, 8, 1, 2);
        Execute(textAttr, graphicsBase, font, 4, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(
            (ushort)4,
            bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        SetAttributes(fontName, 9, 1, 2);
        Execute(textAttr, graphicsBase, font, 4, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);

        SetAttributes(fontName, 8, 2, 2);
        Execute(textAttr, graphicsBase, font, 4, 0x1234_0000u);
        Assert.Equal(0x1234_0000u, cpu.State.D[0]);

        SetAttributes(fontName, 8, 1, 3);
        Execute(textAttr, graphicsBase, font, 4, 0x5678_0000u);
        Assert.Equal(0x5678_0000u, cpu.State.D[0]);

        SetAttributes(fontName, 8, 1, 2);
        Execute(textAttr, graphicsBase, font, 0xFFFF, 0x9ABC_0000u);
        Assert.Equal(0x9ABC_0000u, cpu.State.D[0]);

        Execute(textAttr + 1, graphicsBase, font, 4, 0xAAAA_0000u);
        Assert.Equal(0xAAAA_0000u, cpu.State.D[0]);
        Execute(0xFFFF_FFF8u, graphicsBase, font, 4, 0xBBBB_0000u);
        Assert.Equal(0xBBBB_0000u, cpu.State.D[0]);
        Execute(textAttr, graphicsBase + 1, font, 4, 0xCCCC_0000u);
        Assert.Equal(0xCCCC_0000u, cpu.State.D[0]);
        Execute(textAttr, 0xFFFF_FF00u, font, 4, 0xDDDD_0000u);
        Assert.Equal(0xDDDD_0000u, cpu.State.D[0]);
        Execute(textAttr, graphicsBase, font + 1, 4, 0xEEEE_0000u);
        Assert.Equal(0xEEEE_0000u, cpu.State.D[0]);
        Execute(textAttr, graphicsBase, 0xFFFF_FFC0u, 4, 0xF000_0000u);
        Assert.Equal(0xF000_0000u, cpu.State.D[0]);
        Execute(textAttr, graphicsBase, 0, 4, 0xF111_0000u);
        Assert.Equal(0xF111_0000u, cpu.State.D[0]);
    }

