    [Fact]
    public void NativeGraphicsWeighTAMatchExactOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint requested = 0x00D0_0000;
        const uint target = 0x00D1_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(requested, new byte[GraphicsLayouts.TextAttrSize]);
        bus.MapWritableMemory(target, new byte[GraphicsLayouts.TextAttrSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        void SetAttributes(uint address, ushort ySize, byte style, byte flags)
        {
            bus.WriteLong(address + (uint)GraphicsLayouts.TextAttrName, 0x00E0_0000u);
            bus.WriteWord(address + (uint)GraphicsLayouts.TextAttrYSize, ySize);
            bus.WriteByte(address + (uint)GraphicsLayouts.TextAttrStyle, style, 0);
            bus.WriteByte(address + (uint)GraphicsLayouts.TextAttrFlags, flags, 0);
        }

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint requestAddress, uint targetAddress, uint targetTags, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.WeighTAMatch),
                stack + 0x80u);
            cpu.State.A[0] = requestAddress;
            cpu.State.A[1] = targetAddress;
            cpu.State.A[2] = targetTags;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 128; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native WeighTAMatch body did not return.");
        }

        SetAttributes(requested, 8, 1, 2);
        SetAttributes(target, 8, 1, 2);
        Execute(requested, target, 0, 0xCAFE_0000u);
        Assert.Equal(0x7FFFu, cpu.State.D[0]);

        SetAttributes(target, 9, 1, 2);
        Execute(requested, target, 0, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);

        SetAttributes(target, 8, 2, 2);
        Execute(requested, target, 0, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);

        SetAttributes(target, 8, 1, 3);
        Execute(requested, target, 0, 0x1234_0000u);
        Assert.Equal(0x1234_0000u, cpu.State.D[0]);

        SetAttributes(requested, 8, 0x80, 2);
        SetAttributes(target, 8, 1, 2);
        Execute(requested, target, 0, 0x5678_0000u);
        Assert.Equal(0x5678_0000u, cpu.State.D[0]);

        SetAttributes(requested, 8, 1, 2);
        SetAttributes(target, 8, 0x80, 2);
        Execute(requested, target, 0, 0x9ABC_0000u);
        Assert.Equal(0x9ABC_0000u, cpu.State.D[0]);

        Execute(requested, target, 0x00D2_0000u, 0xAAAA_0000u);
        Assert.Equal(0xAAAA_0000u, cpu.State.D[0]);
        Execute(0, target, 0, 0xBBBB_0000u);
        Assert.Equal(0xBBBB_0000u, cpu.State.D[0]);
        Execute(requested + 1, target, 0, 0xCCCC_0000u);
        Assert.Equal(0xCCCC_0000u, cpu.State.D[0]);
        Execute(0xFFFF_FFF9u, target, 0, 0xDDDD_0000u);
        Assert.Equal(0xDDDD_0000u, cpu.State.D[0]);
        Execute(requested, 0, 0, 0xEEEE_0000u);
        Assert.Equal(0xEEEE_0000u, cpu.State.D[0]);
        Execute(requested, target + 1, 0, 0xF000_0000u);
        Assert.Equal(0xF000_0000u, cpu.State.D[0]);
        Execute(requested, 0xFFFF_FFF9u, 0, 0xF111_0000u);
        Assert.Equal(0xF111_0000u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsUCopperListInitAndFreeOneSlotOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint execBase = 0x0070_0000;
        const uint userList = 0x00D0_0000;
        const uint copList = 0x00D1_0000;
        const uint instructions = 0x00D2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(0, new byte[8]);
        bus.WriteLong(4, execBase);
        bus.MapWritableMemory(userList, new byte[GraphicsLayouts.UCopListSize]);
        bus.MapWritableMemory(stack, new byte[0x300]);

        var allocations = new List<(uint Size, uint Flags)>();
        var frees = new List<(uint Address, uint Size)>();
        var allocationAddresses = new[] { copList, instructions };
        var allocationIndex = 0;
        var allocAddress = unchecked((uint)((int)execBase - 198));
        var freeAddress = unchecked((uint)((int)execBase - 210));
        bus.RegisterHostGateway(allocAddress, state =>
        {
            allocations.Add((state.D[0], state.D[1]));
            if (allocationIndex >= allocationAddresses.Length)
            {
                state.D[0] = 0;
                return;
            }

            var address = allocationAddresses[allocationIndex++];
            bus.MapWritableMemory(address, new byte[checked((int)state.D[0])]);
            state.D[0] = address;
        });
        bus.RegisterHostGateway(freeAddress, state =>
            frees.Add((state.A[1], state.D[0])));

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint listAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x180u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x180u);
            cpu.State.A[0] = listAddress;
            cpu.State.A[6] = 0x00E0_0000u; // graphics base is not consumed by this arm
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 512; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x180u, 0);
                    return;
                }
            }

            throw new InvalidOperationException($"Native {vector} body did not return.");
        }

        Execute(GraphicsLvo.UCopperListInit, userList, 1);
        Assert.Equal(copList, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                ((uint)GraphicsLayouts.CopListSize, 0x0001_0001u),
                ((uint)GraphicsLayouts.CopInsSize, 0x0001_0001u)
            },
            allocations);
        Assert.Equal(copList, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(copList, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(instructions, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopIns));
        Assert.Equal(instructions, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopPtr));
        Assert.Equal((ushort)0, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListCount));
        Assert.Equal((ushort)1, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListMaxCount));
        Assert.Equal(userList, bus.ReadLong(copList + (uint)GraphicsLayouts.CopListSystem));
        Assert.Equal(
            (ushort)0x5543,
            bus.ReadWord(copList + (uint)GraphicsLayouts.CopListFlags));

        Execute(GraphicsLvo.FreeCopList, copList, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(
            new[]
            {
                (instructions, (uint)GraphicsLayouts.CopInsSize),
                (copList, (uint)GraphicsLayouts.CopListSize)
            },
            frees);
        Assert.Equal(0u, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(0u, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListCopList));

        Execute(GraphicsLvo.UCopperListInit, userList, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Execute(GraphicsLvo.UCopperListInit, userList + 1u, 1);
        Assert.Equal(1u, cpu.State.D[0]);

        bus.WriteLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList, 0x00D3_0000u);
        Execute(GraphicsLvo.UCopperListInit, userList, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal(2, allocations.Count);
    }

    [Fact]
    public void NativeGraphicsGetRpAttrsAPenPublishesSingleScalarOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint tags = 0x00D0_0000;
        const uint rastPort = 0x00D1_0000;
        const uint output = 0x00D2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(tags, new byte[0x18]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(output, new byte[4]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagAPen);
        bus.WriteLong(tags + 4u, output);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            7,
            0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint tagList, uint rp, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.GetRPAttrsA),
                stack + 0x80u);
            cpu.State.A[0] = tagList;
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 96; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native GetRPAttrsA body did not return.");
        }

        bus.WriteLong(output, 0xCAFE_BABEu);
        Execute(tags, rastPort, 0x1234_5678u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(7u, bus.ReadLong(output));

        bus.WriteLong(output, 0xCAFE_BABEu);
        Execute(0, rastPort, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(output));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(output, 0xCAFE_BABEu);
        Execute(tags, rastPort, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(output));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagDrawBounds);
        bus.WriteLong(output, 0xCAFE_BABEu);
        Execute(tags, rastPort, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(0xCAFE_BABEu, bus.ReadLong(output));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagAPen);
        bus.WriteLong(tags + 4u, output + 1u);
        Execute(tags, rastPort, 0x0BAD_0000u);
        Assert.Equal(0x0BAD_0000u, cpu.State.D[0]);

        bus.WriteLong(tags + 4u, output);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.RptagAPen);
        Execute(tags, rastPort, 0x0ACE_0000u);
        Assert.Equal(0x0ACE_0000u, cpu.State.D[0]);

        Execute(tags + 1u, rastPort, 0x1111_0000u);
        Assert.Equal(0x1111_0000u, cpu.State.D[0]);
        Execute(tags, rastPort + 1u, 0x2222_0000u);
        Assert.Equal(0x2222_0000u, cpu.State.D[0]);
    }

