    [Fact]
    public void NativeGraphicsGetRpAttrsDrawBoundsPublishesPlanarBitmapEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint tags = 0x00D0_0000;
        const uint rastPort = 0x00D1_0000;
        const uint bitmap = 0x00D2_0000;
        const uint rectangle = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(tags, new byte[0x18]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(rectangle, new byte[GraphicsLayouts.RectangleSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagDrawBounds);
        bus.WriteLong(tags + 4u, rectangle);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 200);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapFlags, 0, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint tagList, uint rp, uint result, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.GetRPAttrsA),
                stack + 0x80u);
            cpu.State.A[0] = tagList;
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0;
            bus.WriteLong(tagList + 4u, result);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 512; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native GetRPAttrsA DrawBounds body did not return.");
        }

        bus.WriteWord(rectangle, 0xCAFE);
        bus.WriteWord(rectangle + 2u, 0xBABE);
        bus.WriteWord(rectangle + 4u, 0xCAFE);
        bus.WriteWord(rectangle + 6u, 0xBABE);
        Execute(tags, rastPort, rectangle, 0x1234_5678u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(0u, bus.ReadWord(rectangle));
        Assert.Equal(0u, bus.ReadWord(rectangle + 2u));
        Assert.Equal(319u, bus.ReadWord(rectangle + 4u));
        Assert.Equal(199u, bus.ReadWord(rectangle + 6u));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 1);
        bus.WriteWord(rectangle, 0xCAFE);
        bus.WriteWord(rectangle + 2u, 0xBABE);
        bus.WriteWord(rectangle + 4u, 0xCAFE);
        bus.WriteWord(rectangle + 6u, 0xBABE);
        Execute(tags, rastPort, rectangle, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        Assert.Equal(0xCAFEu, bus.ReadWord(rectangle));
        Assert.Equal(0xBABEu, bus.ReadWord(rectangle + 2u));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 41);
        Execute(tags, rastPort, rectangle, 0xFACE_0000u);
        Assert.Equal(0xFACE_0000u, cpu.State.D[0]);

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        Execute(tags, rastPort, rectangle + 1u, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
    }

