    [Fact]
    public void NativeGraphicsSetRpAttrsAPenPublishesDerivedStateOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint tags = 0x00D0_0000;
        const uint rastPort = 0x00D1_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(tags, new byte[0x18]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagAPen);
        bus.WriteLong(tags + 4u, 0xCAFE_BABEu);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint tagList, uint rp, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.SetRPAttrsA),
                stack + 0x80u);
            cpu.State.A[0] = tagList;
            cpu.State.A[1] = rp;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1_024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native SetRPAttrsA body did not return.");
        }

        static byte ExpectedMinterm(byte foreground, byte background, byte drawMode, int plane)
        {
            if ((drawMode & 0x10) != 0)
                return (byte)(((drawMode & 0x04) != 0 ? 0x6 : 0x9) << 4 | 0x0A);

            var minA = ((foreground >> plane) & 1) * 3;
            var minB = (drawMode & 0x02) != 0
                ? ((background >> plane) & 1) * 3
                : 2;
            var selector = (drawMode & 0x04) != 0
                ? (minB << 2) | minA
                : (minA << 2) | minB;
            return (byte)((selector << 4) | 0x0A);
        }

        foreach (var drawMode in new byte[] { 0x00, 0x02, 0x04, 0x06, 0x12, 0x16 })
        {
            const byte oldForeground = 1;
            const byte background = 0xA5;
            const ushort oldFlags = 0xC123;
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                oldForeground,
                0);
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortBgPen,
                background,
                0);
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
                drawMode,
                0);
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                3,
                0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, oldFlags);
            for (var plane = 0; plane < 8; plane++)
                bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane, 0x55, 0);

            Execute(tags, rastPort, 0x1234_5678u);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((byte)0xBE, bus.ReadByte(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen));
            Assert.Equal((byte)15, bus.ReadByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
            Assert.Equal((ushort)(oldFlags & ~0x4000), bus.ReadWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags));
            for (var plane = 0; plane < 8; plane++)
                Assert.Equal(
                    ExpectedMinterm(0xBE, background, drawMode, plane),
                    bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
        }

        var oldForegroundAfterValidCalls = bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.TagDone);
        Execute(tags, rastPort, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(oldForegroundAfterValidCalls, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen));

        bus.WriteLong(tags, 0);
        Execute(0, rastPort, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(oldForegroundAfterValidCalls, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagDrawBounds);
        Execute(tags, rastPort, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(oldForegroundAfterValidCalls, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagAPen);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.RptagAPen);
        Execute(tags, rastPort, 0x0ACE_0000u);
        Assert.Equal(0x0ACE_0000u, cpu.State.D[0]);
        Execute(tags + 1u, rastPort, 0x1111_0000u);
        Assert.Equal(0x1111_0000u, cpu.State.D[0]);
        Execute(tags, rastPort + 1u, 0x2222_0000u);
        Assert.Equal(0x2222_0000u, cpu.State.D[0]);
    }

