            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint tags = 0x00D0_0000;
        const uint rastPort = 0x00D1_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(tags, new byte[0x18]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.SetRPAttrsA),
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 2_048; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native SetRPAttrsA scalar body did not return.");
        }

        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, 0x8123);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagOutlinePen);
        bus.WriteLong(tags + 4u, 0x0000_00FEu);
        Execute(0x1234_5678u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFE, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(
            (ushort)(0x8123 | GraphicsLayouts.RastPortAreaOutline),
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagWriteMask);
        bus.WriteLong(tags + 4u, 0x0000_005Au);
        Execute(0xCAFE_BABEu);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagMaxPen);
        bus.WriteLong(tags + 4u, 5u);
        Execute(0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x07, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));

        bus.WriteLong(tags + 4u, 0u);
        Execute(0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x07, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));

        bus.WriteLong(tags + 4u, 0x100u);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal((byte)0x07, bus.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagDrawBounds);
        Execute(0x0ACE_0000u);
        Assert.Equal(0x0ACE_0000u, cpu.State.D[0]);

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagOutlinePen);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.RptagAPen);
        Execute(0x1111_0000u);
        Assert.Equal(0x1111_0000u, cpu.State.D[0]);
    }

