        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0x05, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 11);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 7);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 9);
        bus.WriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont, font);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0x00D3_0000u);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0x7F, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        var activeGfxBase = gfxBase;
        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.SetRPAttrsA),
                stack + 0x80u);
            cpu.State.A[0] = tags;
            cpu.State.A[1] = rastPort;
            cpu.State.A[6] = activeGfxBase;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1_024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native SetRPAttrsA Font=0 body did not return.");
        }

