            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)11, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)7, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));

        bus.WriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont, 0);
        Execute(0xCAFE_BABEu);
        Assert.Equal(0xCAFE_BABEu, cpu.State.D[0]);
        Assert.Equal(font, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));

        bus.WriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont, font + 1u);
        Execute(0xABCD_0000u);
        Assert.Equal(0xABCD_0000u, cpu.State.D[0]);
        Assert.Equal(font, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));

        bus.WriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont, 0xFFFF_FFE0u);
        Execute(0x1357_0000u);
        Assert.Equal(0x1357_0000u, cpu.State.D[0]);
        Assert.Equal(font, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));

        bus.WriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont, font);
        activeGfxBase = gfxBase + 1u;
        Execute(0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        Assert.Equal(font, bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
    }

