            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint d0, uint d1 = 0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = d0;
            cpu.State.D[1] = d1;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 96; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native soft-style body did not return.");
        }

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font + 1u);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0x5A, 0);
        Execute(GraphicsLvo.AskSoftStyle, 0xCAFE_BEEFu);
        Assert.Equal(0xCAFE_BEEFu, cpu.State.D[0]);
        Execute(GraphicsLvo.SetSoftStyle, 0x1234u, 0x00FFu);
        Assert.Equal(0x1234u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0xFFFF_FFFCu);
        Execute(GraphicsLvo.AskSoftStyle, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        Execute(GraphicsLvo.SetSoftStyle, 0x4321u, 0x00FFu);
        Assert.Equal(0x4321u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 1, 0);
        Execute(GraphicsLvo.AskSoftStyle, 0xBEEF_0000u);
        Assert.Equal(0xFFFF_FFFFu, cpu.State.D[0]);
        Execute(GraphicsLvo.SetSoftStyle, 6, 7);
        Assert.Equal(6u, cpu.State.D[0]);
        Assert.Equal((byte)6, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
    }

    [Fact]
    public void NativeGraphicsTextMetricsGuardSelectedTextFontEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint extent = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 7);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 6);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint initialD0, int bodyInstructionCount)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.A[2] = extent;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < bodyInstructionCount; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native text-metric body did not return.");
        }

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font + 1u);
        Execute(GraphicsLvo.TextLength, 0xCAFE_0003u, 64);
        Assert.Equal(0xCAFE_0003u, cpu.State.D[0]);
        Execute(GraphicsLvo.TextExtent, 0xBEEF_0003u, 96);
        Assert.Equal(0xBEEF_0003u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0xFFFF_FFFCu);
        Execute(GraphicsLvo.TextLength, 0xD00D_0002u, 64);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        Execute(GraphicsLvo.TextExtent, 0xFACE_0002u, 96);
        Assert.Equal(0xFACE_0002u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        Execute(GraphicsLvo.TextLength, 0x0000_0003u, 64);
        Assert.Equal(24u, cpu.State.D[0]);
        Execute(GraphicsLvo.TextExtent, 0x0000_0003u, 128);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)24, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)-6, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)23, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));
    }

    [Fact]
    public void NativeGraphicsFontExtentPublishesBoundedFixedCellDeclaredRangeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint font = 0x00D2_0000;
        const uint extent = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 2);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FontExtent),
                stack + 0x80u);
            cpu.State.A[0] = font;
            cpu.State.A[1] = extent;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 256; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native bounded FontExtent body did not return.");
        }

        Execute(0xCAFE_0003u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)7, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);

        // A ninth declared byte is outside this fixed-cell native slice and
        // must leave both the result envelope and D0 untouched.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'I', 0);
        Execute(0xBEEF_0009u);
        Assert.Equal(0xBEEF_0009u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)index));

        // Reversed declared ranges are likewise transparent.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'Z', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
        Execute(0xD00D_0001u);
        Assert.Equal(0xD00D_0001u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsFontExtentPublishesBoundedProportionalMovementEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
