            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint font = 0x00D2_0000;
        const uint charLoc = 0x00D3_0000;
        const uint charSpace = 0x00D4_0000;
        const uint charKern = 0x00D5_0000;
        const uint extent = 0x00D6_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charLoc, new byte[12]);
        bus.MapWritableMemory(charSpace, new byte[6]);
        bus.MapWritableMemory(charKern, new byte[6]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 2);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteLong(charLoc + 0u, 0);
        bus.WriteLong(charLoc + 4u, 8);
        bus.WriteLong(charLoc + 8u, 16);
        bus.WriteWord(charSpace + 0u, 5);
        bus.WriteWord(charSpace + 2u, 7);
        bus.WriteWord(charSpace + 4u, 6);
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 1);
        bus.WriteWord(charKern + 4u, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.FontExtent),
                stack + 0x80u);
            cpu.State.A[0] = font;
            cpu.State.A[1] = extent;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 512; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native proportional FontExtent body did not return.");
        }

        Execute(0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)7, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);
        bus.WriteWord(charKern + 2u, unchecked((ushort)-8));
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)index));

        bus.WriteWord(charKern + 2u, 1);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'I', 0);
        Execute(0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)index));
    }

    [Fact]
    public void NativeGraphicsTextLengthPublishesBoundedProportionalSlotsAndWalkOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint text = 0x00D3_0000;
        const uint charSpace = 0x00D4_0000;
        const uint charKern = 0x00D5_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(text, new byte[256]);
        bus.MapWritableMemory(charSpace, new byte[514]);
        bus.MapWritableMemory(charKern, new byte[514]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(text, (byte)'A', 0);
        bus.WriteByte(text + 1u, (byte)'B', 0);
        bus.WriteByte(text + 2u, (byte)'C', 0);
        for (var index = 3; index < 32; index++)
            bus.WriteByte(text + (uint)index, (byte)('A' + index), 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteWord(charSpace + 0u, 7);
        bus.WriteWord(charSpace + 2u, 11);
        bus.WriteWord(charSpace + 4u, 13);
        bus.WriteWord(charSpace + 6u, unchecked((ushort)-4));
        bus.WriteWord(charKern + 0u, unchecked((ushort)-2));
        bus.WriteWord(charKern + 2u, 1);
        bus.WriteWord(charKern + 4u, unchecked((ushort)-1));
        bus.WriteWord(charKern + 6u, 5);
        for (var index = 4; index < 32; index++)
        {
            bus.WriteWord(charSpace + (uint)(index * 2), 10);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        bus.WriteWord(charSpace + 32u, 1); // default slot after HiChar 'P'
        bus.WriteWord(charSpace + 64u, 1); // default slot after HiChar '`'
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 3);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, ushort count = 1)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.TextLength),
                stack + 0x80u);
            cpu.State.A[0] = text;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = (initialD0 & 0xFFFF_0000u) | count;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 8192; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native proportional TextLength body did not return.");
        }

        Execute(0xCAFE_0000u);
        Assert.Equal(8u, cpu.State.D[0]);

        // Declared glyphs select their corresponding signed table entries.
        bus.WriteByte(text, (byte)'B', 0);
        Execute(0xBEEF_0000u);
        Assert.Equal(15u, cpu.State.D[0]);

        // Out-of-range bytes use the documented extra default slot.
        bus.WriteByte(text, (byte)'Z', 0);
        Execute(0xFACE_0000u);
        Assert.Equal(4u, cpu.State.D[0]);

        // The bounded forward walk applies each declared/default movement and
        // TxSpacing, excluding only a leading negative kern.
        bus.WriteByte(text + 0u, (byte)'A', 0);
        bus.WriteByte(text + 1u, (byte)'B', 0);
        bus.WriteByte(text + 2u, (byte)'C', 0);
        Execute(0x1234_0000u, 3);
        Assert.Equal(40u, cpu.State.D[0]);

        // The proportional TextLength walk now admits the wide sixteen-glyph
        // source envelope while preserving signed CharSpace/CharKern rules.
        Execute(0x4567_0000u, 16);
        Assert.Equal(200u, cpu.State.D[0]);

        // The proportional TextLength walk now admits the wide thirty-two-
        // glyph source/table envelope while preserving signed movement rules.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'`', 0);
        bus.WriteWord(charSpace + 32u, 10); // declared Q slot when HiChar is '`'
        Execute(0x6789_0000u, 32);
        Assert.Equal(408u, cpu.State.D[0]);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        bus.WriteWord(charSpace + 32u, 1); // restore default slot after HiChar 'P'

        // The native TextLength walk now admits the complete sixty-four-glyph
        // source/table envelope.  A malformed final table pointer declines
        // before publishing a partial native result.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x80, 0);
        bus.WriteWord(charKern + 0u, 0);
        for (var index = 3; index <= 64; index++)
        {
            bus.WriteWord(charSpace + (uint)(index * 2), 10);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 64; index++)
            bus.WriteByte(text + (uint)index, (byte)'A', 0);
        Execute(0x789A_0000u, 64);
        Assert.Equal(640u, cpu.State.D[0]);

        bus.WriteByte(text + 63u, 0x80, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern + 1u);
        Execute(0x89AB_0000u, 64);
        Assert.Equal(0x89AB_0040u, cpu.State.D[0]);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        bus.WriteWord(charSpace + 32u, 1); // restore default slot after HiChar 'P'
        bus.WriteWord(charSpace + 6u, unchecked((ushort)-4));
        bus.WriteWord(charKern + 6u, 5);

        // The native TextLength walk now admits the complete one-hundred-
        // twenty-eight-glyph source/table envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xC0, 0);
        for (var index = 65; index <= 128; index++)
        {
            bus.WriteWord(charSpace + (uint)(index * 2), 10);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 128; index++)
            bus.WriteByte(text + (uint)index, (byte)'A', 0);
        Execute(0x9ABC_0000u, 128);
        Assert.Equal(1280u, cpu.State.D[0]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern + 1u);
        Execute(0xABCD_0000u, 128);
        Assert.Equal(0xABCD_0080u, cpu.State.D[0]);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        bus.WriteWord(charSpace + 32u, 1); // restore default slot after HiChar 'P'

        // The native TextLength walk now admits the complete two-hundred-
        // fifty-six-glyph source/table envelope.  A malformed final table
        // pointer still declines before publishing a partial result.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xFF, 0);
        for (var index = 0; index <= 256; index++)
        {
            bus.WriteWord(charSpace + (uint)(index * 2), 7);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 256; index++)
            bus.WriteByte(text + (uint)index, 0, 0);
        Execute(0xCDEF_0000u, 256);
        Assert.Equal(2560u, cpu.State.D[0]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern + 1u);
        Execute(0xFEDC_0000u, 256);
        Assert.Equal(0xFEDC_0100u, cpu.State.D[0]);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        bus.WriteWord(charSpace + 0u, 7);
        bus.WriteWord(charSpace + 2u, 11);
        bus.WriteWord(charSpace + 4u, 13);
        bus.WriteWord(charSpace + 6u, unchecked((ushort)-4));
        bus.WriteWord(charKern + 0u, unchecked((ushort)-2));
        bus.WriteWord(charKern + 2u, 1);
        bus.WriteWord(charKern + 4u, unchecked((ushort)-1));
        bus.WriteWord(charKern + 6u, 5);
        bus.WriteWord(charSpace + 32u, 1); // restore default slot after HiChar 'P'

        bus.WriteByte(text, (byte)'A', 0);
        bus.WriteByte(text + 1u, (byte)'Z', 0);
        bus.WriteByte(text + 2u, (byte)'Z', 0);
        Execute(0x2345_0000u, 3);
        Assert.Equal(18u, cpu.State.D[0]);
        Execute(0x3456_0000u, 257);
        Assert.Equal(0x3456_0101u, cpu.State.D[0]);

        bus.WriteByte(text, (byte)'A', 0);
        bus.WriteByte(text + 1u, 0, 0);
        bus.WriteByte(text + 2u, 0, 0);

        // A reversed declared range is malformed and must remain on fallback.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'@', 0);
        Execute(0xABCD_0000u);
        Assert.Equal(0xABCD_0001u, cpu.State.D[0]);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);

        Execute(0xD00D_0000u, 2);
        Assert.Equal(14u, cpu.State.D[0]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern + 1u);
        Execute(0xFACE_0000u);
        Assert.Equal(0xFACE_0001u, cpu.State.D[0]);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);

        // The native reverse proportional slice claims one negative movement
        // cell and returns the signed LONG advance directly.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x24, 0);
        bus.WriteByte(text, (byte)'B', 0);
        bus.WriteWord(charSpace + 2u, unchecked((ushort)-7));
        bus.WriteWord(charKern + 2u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        Execute(0xCAFE_0000u);
        Assert.Equal(0xFFFF_FFF9u, cpu.State.D[0]);

        // Nonnegative reverse movement and longer counts remain transparent
        // to the portable/provider owner.
        bus.WriteWord(charSpace + 2u, 7);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0001u, cpu.State.D[0]);
        bus.WriteWord(charSpace + 2u, unchecked((ushort)-7));
        Execute(0xD00D_0000u, 2);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsTextExtentPublishesBoundedProportionalMovementEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint text = 0x00D3_0000;
        const uint charLoc = 0x00D4_0000;
        const uint charSpace = 0x00D5_0000;
        const uint charKern = 0x00D6_0000;
        const uint extent = 0x00D7_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(text, new byte[256]);
        bus.MapWritableMemory(charLoc, new byte[1028]);
        bus.MapWritableMemory(charSpace, new byte[514]);
        bus.MapWritableMemory(charKern, new byte[514]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(text + 0u, (byte)'A', 0);
        bus.WriteByte(text + 1u, (byte)'B', 0);
        bus.WriteByte(text + 2u, (byte)'Z', 0);
        for (var index = 3; index < 32; index++)
            bus.WriteByte(text + (uint)index, (byte)('A' + index), 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 9);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 2);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
        for (var index = 0; index < 32; index++)
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
        bus.WriteWord(charSpace + 0u, 5);
        bus.WriteWord(charSpace + 2u, 6);
        bus.WriteWord(charSpace + 4u, 7);
        for (var index = 3; index < 32; index++)
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        bus.WriteWord(charSpace + 6u, 4); // default slot after HiChar 'C'
        bus.WriteWord(charKern + 0u, 0);
        bus.WriteWord(charKern + 2u, 1);
        bus.WriteWord(charKern + 4u, 0);
        for (var index = 3; index < 32; index++)
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        bus.WriteWord(charKern + 6u, 0); // default slot
        bus.WriteWord(charSpace + 64u, 4); // default slot after HiChar '`'
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 2);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, ushort count)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.TextExtent),
                stack + 0x80u);
            cpu.State.A[0] = text;
            cpu.State.A[1] = rastPort;
            cpu.State.A[2] = extent;
            cpu.State.D[0] = (initialD0 & 0xFFFF_0000u) | count;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 16384; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException(
                "Native proportional TextExtent body did not return.");
        }

        Execute(0xCAFE_0003u, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)22, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)21, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);
        bus.WriteWord(charKern + 2u, unchecked((ushort)-1));
        Execute(0xBEEF_0003u, 3);
        Assert.Equal(0xBEEF_0003u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)index));

        bus.WriteWord(charKern + 2u, 1);
        // Counts nine through thirty-two share the same movement-cell
        // preflight with a conservative thirty-two-byte source envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'`', 0);
        bus.WriteWord(charSpace + 6u, 8); // declared D slot when HiChar is '`'
        Execute(0x6789_0000u, 32);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)316, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)9, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-2, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)315, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)6, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        // A malformed thirty-second movement declines after complete
        // preflight and leaves the prior extent publication untouched.
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0x5A, 0);
        bus.WriteWord(charSpace + 62u, unchecked((ushort)-1));
        Execute(0x789A_0000u, 32);
        Assert.Equal(0x789A_0020u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0x5A, bus.ReadByte(extent + (uint)index));
        bus.WriteWord(charSpace + 62u, 8);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        bus.WriteWord(charSpace + 6u, 4);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);

        // The native TextExtent walk now admits the complete sixty-four-glyph
        // source/table envelope.  A malformed final cell declines after the
        // full preflight, preserving the caller-owned extent.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0x80, 0);
        for (var index = 0; index <= 64; index++)
        {
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
            bus.WriteWord(charSpace + (uint)(index * 2), 5);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 64; index++)
            bus.WriteByte(text + (uint)index, (byte)'A', 0);
        Execute(0x89AB_0000u, 64);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)448, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)447, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        bus.WriteByte(text + 63u, 0x80, 0);
        bus.WriteWord(charSpace + 126u, unchecked((ushort)-1));
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xC3, 0);
        Execute(0x9ABC_0000u, 64);
        Assert.Equal(0x9ABC_0040u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xC3, bus.ReadByte(extent + (uint)index));
        bus.WriteWord(charSpace + 126u, 5);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);

        // The native TextExtent walk now admits the complete one-hundred-
        // twenty-eight-glyph source/table envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xC0, 0);
        for (var index = 0; index <= 128; index++)
        {
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
            bus.WriteWord(charSpace + (uint)(index * 2), 5);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 128; index++)
            bus.WriteByte(text + (uint)index, (byte)'A', 0);
        Execute(0xABCD_0000u, 128);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)896, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)895, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        bus.WriteByte(text + 127u, 0xC0, 0);
        bus.WriteWord(charSpace + 254u, unchecked((ushort)-1));
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xD6, 0);
        Execute(0xBCDE_0000u, 128);
        Assert.Equal(0xBCDE_0080u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xD6, bus.ReadByte(extent + (uint)index));
        bus.WriteWord(charSpace + 254u, 5);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);

        // The native TextExtent walk now admits the complete two-hundred-
        // fifty-six-glyph source/table envelope.  A malformed final cell
        // declines after the full preflight and preserves the extent.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xFF, 0);
        for (var index = 0; index <= 256; index++)
        {
            bus.WriteLong(charLoc + (uint)(index * 4), (uint)(index * 8));
            bus.WriteWord(charSpace + (uint)(index * 2), 5);
            bus.WriteWord(charKern + (uint)(index * 2), 0);
        }
        for (var index = 0; index < 256; index++)
            bus.WriteByte(text + (uint)index, 0, 0);
        Execute(0xCDEF_0000u, 256);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)1792, bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)1791, unchecked((short)bus.ReadWord(
            extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        bus.WriteByte(text + 255u, 0xFF, 0);
        bus.WriteWord(charSpace + 510u, unchecked((ushort)-1));
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xE7, 0);
        Execute(0xFEDC_0000u, 256);
        Assert.Equal(0xFEDC_0100u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xE7, bus.ReadByte(extent + (uint)index));
        bus.WriteWord(charSpace + 510u, 5);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        bus.WriteWord(charSpace + 6u, 4);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            bus.WriteByte(extent + (uint)index, 0xA5, 0);

        Execute(0xD00D_0000u, 257);
        Assert.Equal(0xD00D_0101u, cpu.State.D[0]);
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)0xA5, bus.ReadByte(extent + (uint)index));
    }

    [Fact]
    public void NativeGraphicsTextRenderingAndFitGuardSelectedTextFontEnvelopeOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint text = 0x00D3_0000;
        const uint extent = 0x00D4_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(text, new byte[4]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteByte(text, (byte)'A', 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(GraphicsLvo vector, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(vector),
                stack + 0x80u);
            cpu.State.A[0] = text;
            cpu.State.A[1] = rastPort;
            cpu.State.A[2] = extent;
            cpu.State.A[3] = 0;
            cpu.State.D[0] = initialD0;
            cpu.State.D[1] = 1;
            cpu.State.D[2] = 16;
            cpu.State.D[3] = 9;
            cpu.ExecuteInstruction(); // vector JMP.L
            // The fixed-cell native Text dispatch grows with each admitted
            // byte-aligned cell; keep this bounded guard above the complete
            // fallback walk without treating a malformed path as unbounded.
            for (var index = 0; index < 2048; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native text/fitting body did not return.");
        }

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font + 1u);
        Execute(GraphicsLvo.Text, 0xCAFE_0001u);
        Assert.Equal(0xCAFE_0001u, cpu.State.D[0]);
        Execute(GraphicsLvo.TextFit, 0xBEEF_0001u);
        Assert.Equal(0xBEEF_0001u, cpu.State.D[0]);
        Execute(GraphicsLvo.FontExtent, 0xD00D_0000u);
        Assert.Equal(0xD00D_0000u, cpu.State.D[0]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0xFFFF_FFFCu);
        Execute(GraphicsLvo.Text, 0xFACE_0001u);
        Assert.Equal(0xFACE_0001u, cpu.State.D[0]);
        Execute(GraphicsLvo.TextFit, 0xABCD_0001u);
        Assert.Equal(0xABCD_0001u, cpu.State.D[0]);
        Execute(GraphicsLvo.FontExtent, 0x1234_0000u);
        Assert.Equal(0x1234_0000u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsTextPublishesBoundedFixedCellSpanAndCursorOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint text = 0x00D3_0000;
        const uint charData = 0x00D4_0000;
        const uint plane = 0x00D5_0000;
        const uint plane2 = 0x00D5_1000;
        const uint bitmap = 0x00D6_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(text, new byte[4096]);
        bus.MapWritableMemory(charData, new byte[2]);
        bus.MapWritableMemory(plane, new byte[4096]);
        bus.MapWritableMemory(plane2, new byte[4096]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(text, (byte)'A', 0);
        bus.WriteByte(text + 1u, (byte)'B', 0);
        for (var index = 2; index < 4096; index++)
            bus.WriteByte(text + (uint)index, (byte)(index % 2 == 0 ? 'A' : 'B'), 0);
        bus.WriteByte(charData, 0x81, 0);
        bus.WriteByte(charData + 1u, 0x42, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'B', 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint textAddress, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.Text),
                stack + 0x80u);
            cpu.State.A[0] = textAddress;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 3_000_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native bounded Text body did not return.");
        }

        Execute(text, 2);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortFirstDot,
            (ushort)(bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
                GraphicsLayouts.RastPortFirstDot));
        Assert.Equal((byte)0x81, bus.ReadByte(plane));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 1u));

        // The first multi-plane Text arm is deliberately one fixed-cell
        // glyph at the origin.  Both selected inline PLANEPTRs are
        // preflighted before the first byte is changed.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 1);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane2, 0, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x81, bus.ReadByte(plane));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2));

        // The companion two-glyph arm keeps the same origin-only contract
        // while advancing over two contiguous one-byte fixed cells.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane2, 0, 0);
        bus.WriteByte(plane2 + 1u, 0, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x81, bus.ReadByte(plane));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 1u));

        // The byte-aligned three-glyph arm starts at CurrentX=8, preserving
        // the first destination byte and committing both selected planes only
        // after the complete source/plane span is readable.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        bus.WriteByte(plane + 3u, 0, 0);
        bus.WriteByte(plane2, 0xA5, 0);
        bus.WriteByte(plane2 + 1u, 0, 0);
        bus.WriteByte(plane2 + 2u, 0, 0);
        bus.WriteByte(plane2 + 3u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)32, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane2));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 3u));

        // A late odd selected-plane link declines before either destination
        // plane or the cursor is published.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteByte(plane + 1u, 0x12, 0);
        bus.WriteByte(plane + 2u, 0x24, 0);
        bus.WriteByte(plane + 3u, 0x48, 0);
        bus.WriteByte(plane2 + 1u, 0x56, 0);
        bus.WriteByte(plane2 + 2u, 0x78, 0);
        bus.WriteByte(plane2 + 3u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 3u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The next byte-aligned three-glyph arm begins at CurrentX=16. It
        // preserves the two-byte prefix and commits strikes at offsets two
        // through four only after the complete selected-plane span is safe.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 16);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 5);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        bus.WriteByte(plane + 3u, 0, 0);
        bus.WriteByte(plane + 4u, 0, 0);
        bus.WriteByte(plane2, 0x96, 0);
        bus.WriteByte(plane2 + 1u, 0x69, 0);
        bus.WriteByte(plane2 + 2u, 0, 0);
        bus.WriteByte(plane2 + 3u, 0, 0);
        bus.WriteByte(plane2 + 4u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)40, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x96, bus.ReadByte(plane2));
        Assert.Equal((byte)0x69, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 4u));

        // A late odd selected-plane link still declines atomically at the
        // wider byte-aligned span.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 16);
        bus.WriteByte(plane + 2u, 0x12, 0);
        bus.WriteByte(plane + 3u, 0x24, 0);
        bus.WriteByte(plane + 4u, 0x48, 0);
        bus.WriteByte(plane2 + 2u, 0x56, 0);
        bus.WriteByte(plane2 + 3u, 0x78, 0);
        bus.WriteByte(plane2 + 4u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 4u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The third byte-aligned three-glyph arm begins at CurrentX=24. It
        // preserves the three-byte prefix and publishes offsets three through
        // five only after the complete selected-plane span is readable.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 24);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 6);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        bus.WriteByte(plane + 3u, 0, 0);
        bus.WriteByte(plane + 4u, 0, 0);
        bus.WriteByte(plane + 5u, 0, 0);
        bus.WriteByte(plane2, 0x96, 0);
        bus.WriteByte(plane2 + 1u, 0x69, 0);
        bus.WriteByte(plane2 + 2u, 0xC3, 0);
        bus.WriteByte(plane2 + 3u, 0, 0);
        bus.WriteByte(plane2 + 4u, 0, 0);
        bus.WriteByte(plane2 + 5u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)48, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x96, bus.ReadByte(plane2));
        Assert.Equal((byte)0x69, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0xC3, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 4u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 5u));

        // A late odd selected-plane link still declines before changing any
        // byte in the wider CurrentX=24 transaction.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 24);
        bus.WriteByte(plane + 3u, 0x12, 0);
        bus.WriteByte(plane + 4u, 0x24, 0);
        bus.WriteByte(plane + 5u, 0x48, 0);
        bus.WriteByte(plane2 + 3u, 0x56, 0);
        bus.WriteByte(plane2 + 4u, 0x78, 0);
        bus.WriteByte(plane2 + 5u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)24, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 4u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 5u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The fourth byte-aligned three-glyph arm begins at CurrentX=32. It
        // preserves the four-byte prefix and publishes offsets four through
        // six only after the complete selected-plane span is readable.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 32);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 7);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        bus.WriteByte(plane + 3u, 0xC3, 0);
        bus.WriteByte(plane + 4u, 0, 0);
        bus.WriteByte(plane + 5u, 0, 0);
        bus.WriteByte(plane + 6u, 0, 0);
        bus.WriteByte(plane2, 0x96, 0);
        bus.WriteByte(plane2 + 1u, 0x69, 0);
        bus.WriteByte(plane2 + 2u, 0x78, 0);
        bus.WriteByte(plane2 + 3u, 0x87, 0);
        bus.WriteByte(plane2 + 4u, 0, 0);
        bus.WriteByte(plane2 + 5u, 0, 0);
        bus.WriteByte(plane2 + 6u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)56, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC3, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x96, bus.ReadByte(plane2));
        Assert.Equal((byte)0x69, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x87, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 4u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 5u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 6u));

        // A late odd selected-plane link still declines before changing any
        // byte in the wider CurrentX=32 transaction.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 32);
        bus.WriteByte(plane + 4u, 0x12, 0);
        bus.WriteByte(plane + 5u, 0x24, 0);
        bus.WriteByte(plane + 6u, 0x48, 0);
        bus.WriteByte(plane2 + 4u, 0x56, 0);
        bus.WriteByte(plane2 + 5u, 0x78, 0);
        bus.WriteByte(plane2 + 6u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)32, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 4u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 5u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 6u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The fifth byte-aligned three-glyph arm begins at CurrentX=40. It
        // preserves the five-byte prefix and publishes offsets five through
        // seven only after the complete selected-plane span is readable.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 40);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 8);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        bus.WriteByte(plane + 3u, 0xC3, 0);
        bus.WriteByte(plane + 4u, 0x69, 0);
        bus.WriteByte(plane + 5u, 0, 0);
        bus.WriteByte(plane + 6u, 0, 0);
        bus.WriteByte(plane + 7u, 0, 0);
        bus.WriteByte(plane2, 0x96, 0);
        bus.WriteByte(plane2 + 1u, 0x69, 0);
        bus.WriteByte(plane2 + 2u, 0x78, 0);
        bus.WriteByte(plane2 + 3u, 0x87, 0);
        bus.WriteByte(plane2 + 4u, 0x3C, 0);
        bus.WriteByte(plane2 + 5u, 0, 0);
        bus.WriteByte(plane2 + 6u, 0, 0);
        bus.WriteByte(plane2 + 7u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)64, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC3, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x69, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0x96, bus.ReadByte(plane2));
        Assert.Equal((byte)0x69, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x87, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane2 + 4u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 5u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 6u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 7u));

        // A late odd selected-plane link still declines before changing any
        // byte in the wider CurrentX=40 transaction.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 40);
        bus.WriteByte(plane + 5u, 0x12, 0);
        bus.WriteByte(plane + 6u, 0x24, 0);
        bus.WriteByte(plane + 7u, 0x48, 0);
        bus.WriteByte(plane2 + 5u, 0x56, 0);
        bus.WriteByte(plane2 + 6u, 0x78, 0);
        bus.WriteByte(plane2 + 7u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)40, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 5u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 6u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 7u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The sixth byte-aligned three-glyph arm begins at CurrentX=48. It
        // preserves the six-byte prefix and publishes offsets six through
        // eight only after the complete selected-plane span is readable.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 48);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 9);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        bus.WriteByte(plane + 3u, 0xC3, 0);
        bus.WriteByte(plane + 4u, 0x69, 0);
        bus.WriteByte(plane + 5u, 0x96, 0);
        bus.WriteByte(plane + 6u, 0, 0);
        bus.WriteByte(plane + 7u, 0, 0);
        bus.WriteByte(plane + 8u, 0, 0);
        bus.WriteByte(plane2, 0x96, 0);
        bus.WriteByte(plane2 + 1u, 0x69, 0);
        bus.WriteByte(plane2 + 2u, 0x78, 0);
        bus.WriteByte(plane2 + 3u, 0x87, 0);
        bus.WriteByte(plane2 + 4u, 0x3C, 0);
        bus.WriteByte(plane2 + 5u, 0xC3, 0);
        bus.WriteByte(plane2 + 6u, 0, 0);
        bus.WriteByte(plane2 + 7u, 0, 0);
        bus.WriteByte(plane2 + 8u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)72, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC3, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x69, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x96, bus.ReadByte(plane + 5u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)0x96, bus.ReadByte(plane2));
        Assert.Equal((byte)0x69, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x87, bus.ReadByte(plane2 + 3u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane2 + 4u));
        Assert.Equal((byte)0xC3, bus.ReadByte(plane2 + 5u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 6u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 7u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 8u));

        // A late odd selected-plane link still declines before changing any
        // byte in the wider CurrentX=48 transaction.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 48);
        bus.WriteByte(plane + 6u, 0x12, 0);
        bus.WriteByte(plane + 7u, 0x24, 0);
        bus.WriteByte(plane + 8u, 0x48, 0);
        bus.WriteByte(plane2 + 6u, 0x56, 0);
        bus.WriteByte(plane2 + 7u, 0x78, 0);
        bus.WriteByte(plane2 + 8u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)48, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 6u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 7u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 8u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The seventh byte-aligned three-glyph arm begins at CurrentX=56. It
        // preserves the seven-byte prefix and publishes offsets seven through
        // nine only after the complete selected-plane span is readable.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 56);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 10);
        bus.WriteByte(plane, 0x5A, 0);
