        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)1360, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));

        // The runtime byte-aligned three-glyph arm removes the fixed-selector
        // ceiling while retaining a bounded complete plane envelope.  Its
        // final admitted position starts at byte 253 (CurrentX=2024).
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2024);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 256);
        var planePrefix2024 = new byte[253];
        var plane2Prefix2024 = new byte[253];
        for (var index = 0; index < planePrefix2024.Length; index++)
        {
            planePrefix2024[index] = (byte)(0x27 + index * 31);
            plane2Prefix2024[index] = (byte)(0xD4 ^ index * 61);
            bus.WriteByte(plane + (uint)index, planePrefix2024[index], 0);
            bus.WriteByte(plane2 + (uint)index, plane2Prefix2024[index], 0);
        }

        bus.WriteByte(plane + 253u, 0, 0);
        bus.WriteByte(plane + 254u, 0, 0);
        bus.WriteByte(plane + 255u, 0, 0);
        bus.WriteByte(plane2 + 253u, 0, 0);
        bus.WriteByte(plane2 + 254u, 0, 0);
        bus.WriteByte(plane2 + 255u, 0, 0);
        Execute(text, 3);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)2048, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < planePrefix2024.Length; index++)
        {
            Assert.Equal(planePrefix2024[index], bus.ReadByte(plane + (uint)index));
            Assert.Equal(plane2Prefix2024[index], bus.ReadByte(plane2 + (uint)index));
        }

        Assert.Equal((byte)0x81, bus.ReadByte(plane + 253u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 254u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 255u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 253u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 254u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 255u));

        // A late selected-plane failure leaves the same maximum-offset
        // transaction untouched, proving the runtime offset has not widened
        // the publication boundary.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2024);
        bus.WriteByte(plane + 253u, 0x12, 0);
        bus.WriteByte(plane + 254u, 0x24, 0);
        bus.WriteByte(plane + 255u, 0x48, 0);
        bus.WriteByte(plane2 + 253u, 0x56, 0);
        bus.WriteByte(plane2 + 254u, 0x78, 0);
        bus.WriteByte(plane2 + 255u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)2024, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane + 253u));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 254u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 255u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2 + 253u));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 254u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 255u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The next byte-aligned position is deliberately outside the
        // three-glyph native envelope and remains fallback-owned.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2032);
        bus.WriteByte(plane + 253u, 0x5A, 0);
        bus.WriteByte(plane + 254u, 0xA5, 0);
        bus.WriteByte(plane + 255u, 0x3C, 0);
        Execute(text, 3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)2032, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 253u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 254u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 255u));

        // One- and two-glyph calls use the same runtime byte-offset path,
        // with their own final in-envelope byte positions.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2040);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 256);
        bus.WriteByte(plane + 255u, 0, 0);
        bus.WriteByte(plane2 + 255u, 0, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)2048, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 255u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 255u));

        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2032);
        bus.WriteByte(plane + 254u, 0, 0);
        bus.WriteByte(plane + 255u, 0, 0);
        bus.WriteByte(plane2 + 254u, 0, 0);
        bus.WriteByte(plane2 + 255u, 0, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)2048, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 254u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 255u));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 254u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 255u));

        // The bounded chain continues through four, eight, nine, and sixteen
        // fixed cells;
        // each generated entry retains the same all-plane transaction.
        foreach (var glyphCount in new[] { 4, 8, 9, 16 })
        {
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                (ushort)glyphCount);
            for (var index = 0; index < glyphCount; index++)
            {
                bus.WriteByte(plane + (uint)index, 0, 0);
                bus.WriteByte(plane2 + (uint)index, 0, 0);
            }

            Execute(text, (uint)glyphCount);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((ushort)(glyphCount * 8), bus.ReadWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            for (var index = 0; index < glyphCount; index++)
            {
                var expected = (byte)(index % 2 == 0 ? 0x81 : 0x42);
                Assert.Equal(expected, bus.ReadByte(plane + (uint)index));
                Assert.Equal(expected, bus.ReadByte(plane2 + (uint)index));
            }
        }

        // A one-pixel non-origin cell shifts the eight source bits across two
        // destination bytes while preserving the surrounding bits.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 1);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0x24, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane2, 0x5A, 0);
        bus.WriteByte(plane2 + 1u, 0, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)9, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x64, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));
        Assert.Equal((byte)0x80, bus.ReadByte(plane2 + 1u));

        // The bit-offset arm preflights the full two-byte selected-plane span
        // before changing either destination byte.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 1);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // A two-pixel non-origin cell uses the generalized MSB-first shift:
        // the source MSB lands at 0x20 and the source LSB crosses to 0x40 in
        // the next destination byte while neighboring bits remain intact.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane2, 0x11, 0);
        bus.WriteByte(plane2 + 1u, 0x08, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)10, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x31, bus.ReadByte(plane2));
        Assert.Equal((byte)0x48, bus.ReadByte(plane2 + 1u));

        // The two-pixel arm preflights the complete selected-plane span before
        // either destination byte is changed.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)2, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // A three-pixel non-origin cell shifts the source MSB to 0x10 and
        // the source LSB to 0x20 in the next byte, preserving both neighbors.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane2, 0x11, 0);
        bus.WriteByte(plane2 + 1u, 0x08, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)11, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x14, bus.ReadByte(plane));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x11, bus.ReadByte(plane2));
        Assert.Equal((byte)0x28, bus.ReadByte(plane2 + 1u));

        // The three-pixel arm keeps the same all-selected-plane rollback
        // boundary when the later plane link becomes odd.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)3, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // A four-pixel non-origin cell maps the source MSB to 0x08 and its
        // source LSB to 0x10 in the following byte.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 4);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane2, 0x11, 0);
        bus.WriteByte(plane2 + 1u, 0x08, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)12, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x0C, bus.ReadByte(plane));
        Assert.Equal((byte)0x10, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x19, bus.ReadByte(plane2));
        Assert.Equal((byte)0x18, bus.ReadByte(plane2 + 1u));

        // The four-pixel arm also declines atomically on a late odd link.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 4);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The remaining in-byte offsets use the same generalized two-byte
        // transaction. Verify each destination mask and cursor publication.
        foreach (var (offset, expectedFirst, expectedSecond,
                      expectedPlane2First, expectedPlane2Second) in new[]
        {
            (Offset: 5,
                ExpectedFirst: (byte)0x24, ExpectedSecond: (byte)0x48,
                ExpectedPlane2First: (byte)0x34, ExpectedPlane2Second: (byte)0x88),
            (Offset: 6,
                ExpectedFirst: (byte)0x22, ExpectedSecond: (byte)0x44,
                ExpectedPlane2First: (byte)0x32, ExpectedPlane2Second: (byte)0x84),
            (Offset: 7,
                ExpectedFirst: (byte)0x21, ExpectedSecond: (byte)0x42,
                ExpectedPlane2First: (byte)0x31, ExpectedPlane2Second: (byte)0x82)
        })
        {
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, (ushort)offset);
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteByte(plane, 0x20, 0);
            bus.WriteByte(plane + 1u, 0x40, 0);
            bus.WriteByte(plane2, 0x30, 0);
            bus.WriteByte(plane2 + 1u, 0x80, 0);
            Execute(text, 1);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((ushort)(offset + 8), bus.ReadWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            Assert.Equal(expectedFirst, bus.ReadByte(plane));
            Assert.Equal(expectedSecond, bus.ReadByte(plane + 1u));
            Assert.Equal(expectedPlane2First, bus.ReadByte(plane2));
            Assert.Equal(expectedPlane2Second, bus.ReadByte(plane2 + 1u));
        }

        // Offset seven still preflights both selected planes before changing
        // either byte when the later link is malformed.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 7);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)7, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The two-glyph bit-offset arm keeps the full fixed-cell span
        // transactional: both glyphs begin at CurrentX=1, so the first
        // strike crosses into byte one and the second strike shares that
        // byte before ending in the same selected-plane row.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 1);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0x10, 0);
        bus.WriteByte(plane + 2u, 0x80, 0);
        bus.WriteByte(plane2, 0x08, 0);
        bus.WriteByte(plane2 + 1u, 0x04, 0);
        bus.WriteByte(plane2 + 2u, 0x20, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)17, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x44, bus.ReadByte(plane));
        Assert.Equal((byte)0xB1, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane2));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x20, bus.ReadByte(plane2 + 2u));

        // A malformed later plane declines before either glyph touches the
        // selected span, including the byte shared by both bit-offset cells.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 1);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteByte(plane2 + 2u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 2u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The two-glyph x=2 arm uses the same three-byte transaction with a
        // different MSB-first mask sequence; the second glyph ends in byte
        // two while the first and second strikes share byte one.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0x01, 0);
        bus.WriteByte(plane + 2u, 0x08, 0);
        bus.WriteByte(plane2, 0x08, 0);
        bus.WriteByte(plane2 + 1u, 0x02, 0);
        bus.WriteByte(plane2 + 2u, 0x20, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)18, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x51, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x88, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x28, bus.ReadByte(plane2));
        Assert.Equal((byte)0x52, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane2 + 2u));

        // A malformed later plane still declines before the shared byte or
        // the final byte can be changed by either glyph.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteByte(plane2 + 2u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)2, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 2u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The two-glyph x=3 arm shifts the first strike to 0x10/0x20 and
        // keeps the second strike's 0x08 mask in the shared byte before its
        // low source bit reaches 0x40 in byte two.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0x01, 0);
        bus.WriteByte(plane + 2u, 0x08, 0);
        bus.WriteByte(plane2, 0x08, 0);
        bus.WriteByte(plane2 + 1u, 0x02, 0);
        bus.WriteByte(plane2 + 2u, 0x20, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)19, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x14, bus.ReadByte(plane));
        Assert.Equal((byte)0x29, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x48, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x18, bus.ReadByte(plane2));
        Assert.Equal((byte)0x2A, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x60, bus.ReadByte(plane2 + 2u));

        // A malformed later plane declines before either glyph changes the
        // shared byte or the final byte of the selected span.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 3);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteByte(plane2 + 2u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)3, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 2u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The two-glyph x=4 arm maps the first strike to 0x08/0x10 and the
        // second to 0x04 in the shared byte plus 0x20 in byte two.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 4);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        bus.WriteByte(plane, 0x04, 0);
        bus.WriteByte(plane + 1u, 0x01, 0);
        bus.WriteByte(plane + 2u, 0x08, 0);
        bus.WriteByte(plane2, 0x01, 0);
        bus.WriteByte(plane2 + 1u, 0x02, 0);
        bus.WriteByte(plane2 + 2u, 0x40, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)20, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x0C, bus.ReadByte(plane));
        Assert.Equal((byte)0x15, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x28, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x09, bus.ReadByte(plane2));
        Assert.Equal((byte)0x16, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x60, bus.ReadByte(plane2 + 2u));

        // A malformed later plane declines before either glyph changes the
        // shared byte or the final byte of the selected span.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 4);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteByte(plane2 + 2u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 2u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The remaining in-byte offsets use the same three-byte transaction
        // for two glyphs. Verify each shared-byte mask and cursor publication.
        foreach (var (offset, expectedFirst, expectedSecond, expectedThird,
                      expectedPlane2First, expectedPlane2Second, expectedPlane2Third) in new[]
        {
            (Offset: 5,
                ExpectedFirst: (byte)0x05, ExpectedSecond: (byte)0x0B,
                ExpectedThird: (byte)0x18,
                ExpectedPlane2First: (byte)0x0C, ExpectedPlane2Second: (byte)0x0A,
                ExpectedPlane2Third: (byte)0x30),
            (Offset: 6,
                ExpectedFirst: (byte)0x03, ExpectedSecond: (byte)0x07,
                ExpectedThird: (byte)0x0C,
                ExpectedPlane2First: (byte)0x0A, ExpectedPlane2Second: (byte)0x15,
                ExpectedPlane2Third: (byte)0x28),
            (Offset: 7,
                ExpectedFirst: (byte)0x03, ExpectedSecond: (byte)0x06,
                ExpectedThird: (byte)0x8C,
                ExpectedPlane2First: (byte)0x05, ExpectedPlane2Second: (byte)0x12,
                ExpectedPlane2Third: (byte)0xA4)
        })
        {
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, (ushort)offset);
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
            bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
            bus.WriteByte(plane, (byte)(offset == 5 ? 0x01 : offset == 6 ? 0x01 : 0x02), 0);
            bus.WriteByte(plane + 1u, (byte)(offset == 5 ? 0x01 : offset == 6 ? 0x02 : 0x04), 0);
            bus.WriteByte(plane + 2u, (byte)(offset == 5 ? 0x08 : offset == 6 ? 0x04 : 0x08), 0);
            bus.WriteByte(plane2, (byte)(offset == 5 ? 0x08 : offset == 6 ? 0x08 : 0x04), 0);
            bus.WriteByte(plane2 + 1u, (byte)(offset == 5 ? 0x02 : offset == 6 ? 0x10 : 0x10), 0);
            bus.WriteByte(plane2 + 2u, (byte)(offset == 5 ? 0x20 : offset == 6 ? 0x20 : 0x20), 0);
            Execute(text, 2);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((ushort)(offset + 16), bus.ReadWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            Assert.Equal(expectedFirst, bus.ReadByte(plane));
            Assert.Equal(expectedSecond, bus.ReadByte(plane + 1u));
            Assert.Equal(expectedThird, bus.ReadByte(plane + 2u));
            Assert.Equal(expectedPlane2First, bus.ReadByte(plane2));
            Assert.Equal(expectedPlane2Second, bus.ReadByte(plane2 + 1u));
            Assert.Equal(expectedPlane2Third, bus.ReadByte(plane2 + 2u));
        }

        // Offset seven still preflights both selected planes before either
        // glyph writes when the later inline link is malformed.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 7);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteByte(plane2 + 2u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)7, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 2u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The byte-aligned two-glyph arm preserves the prefix byte and
        // publishes both fixed-cell bytes at offsets one and two.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        bus.WriteByte(plane, 0x24, 0);
        bus.WriteByte(plane + 1u, 0x10, 0);
        bus.WriteByte(plane + 2u, 0x08, 0);
        bus.WriteByte(plane2, 0x5A, 0);
        bus.WriteByte(plane2 + 1u, 0x04, 0);
        bus.WriteByte(plane2 + 2u, 0x20, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)24, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x91, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x4A, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));
        Assert.Equal((byte)0x85, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x62, bus.ReadByte(plane2 + 2u));

        // A malformed later plane declines before either byte-aligned glyph
        // can change the selected span or the preserved prefix.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane + 2u, 0x56, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteByte(plane2 + 2u, 0x9A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0x9A, bus.ReadByte(plane2 + 2u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The remaining in-byte two-glyph entries start in byte one at
        // CurrentX=9..15. Each one spans four destination bytes; calculate
        // the MSB-first source placement here so every generated mask is
        // checked while surrounding destination bits remain intact.
        foreach (var bitOffset in Enumerable.Range(1, 7))
        {
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
                (ushort)(8 + bitOffset));
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
            bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

            var firstPlane = new byte[] { 0x24, 0x10, 0x08, 0x80 };
            var secondPlane = new byte[] { 0x5A, 0x04, 0x20, 0x40 };
            foreach (var (address, values) in new[]
            {
                (plane, firstPlane),
                (plane2, secondPlane)
            })
            {
                for (var index = 0; index < values.Length; index++)
                    bus.WriteByte(address + (uint)index, values[index], 0);
            }

            static void ApplyGlyph(byte[] destination, int startBit, byte glyph)
            {
                for (var sourceBit = 0; sourceBit < 8; sourceBit++)
                {
                    if ((glyph & (0x80 >> sourceBit)) == 0)
                        continue;

                    var destinationBit = startBit + sourceBit;
                    destination[destinationBit >> 3] |=
                        (byte)(0x80 >> (destinationBit & 7));
                }
            }

            ApplyGlyph(firstPlane, 8 + bitOffset, 0x81);
            ApplyGlyph(firstPlane, 16 + bitOffset, 0x42);
            ApplyGlyph(secondPlane, 8 + bitOffset, 0x81);
            ApplyGlyph(secondPlane, 16 + bitOffset, 0x42);

            Execute(text, 2);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((ushort)(24 + bitOffset), bus.ReadWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            for (var index = 0; index < 4; index++)
            {
                Assert.Equal(firstPlane[index], bus.ReadByte(plane + (uint)index));
                Assert.Equal(secondPlane[index], bus.ReadByte(plane2 + (uint)index));
            }
        }

        // Offset fifteen still preflights the complete four-byte span before
        // touching either selected plane when the later link is malformed.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 15);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        for (var index = 0; index < 4; index++)
        {
            bus.WriteByte(plane + (uint)index, (byte)(0x20 + index), 0);
            bus.WriteByte(plane2 + (uint)index, (byte)(0x50 + index), 0);
        }

        Execute(text, 0xBAD0_0002u);
        Assert.Equal(0xBAD0_0002u, cpu.State.D[0]);
        Assert.Equal((ushort)15, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 4; index++)
        {
            Assert.Equal((byte)(0x20 + index), bus.ReadByte(plane + (uint)index));
            Assert.Equal((byte)(0x50 + index), bus.ReadByte(plane2 + (uint)index));
        }
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The next byte-aligned two-glyph entry starts at CurrentX=16. It
        // preserves the two-byte prefix and publishes the strikes at offsets
        // two and three across both selected planes.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 16);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);
        var x16FirstPlane = new byte[] { 0x24, 0x10, 0x08, 0x80 };
        var x16SecondPlane = new byte[] { 0x5A, 0x04, 0x20, 0x40 };
        for (var index = 0; index < 4; index++)
        {
            bus.WriteByte(plane + (uint)index, x16FirstPlane[index], 0);
            bus.WriteByte(plane2 + (uint)index, x16SecondPlane[index], 0);
        }

        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)32, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x10, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x89, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC2, bus.ReadByte(plane + 3u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));
        Assert.Equal((byte)0x04, bus.ReadByte(plane2 + 1u));
        Assert.Equal((byte)0xA1, bus.ReadByte(plane2 + 2u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane2 + 3u));

        // A malformed later plane still declines atomically at the new
        // byte-aligned offset before either strike or prefix is changed.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 16);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        for (var index = 0; index < 4; index++)
        {
            bus.WriteByte(plane + (uint)index, (byte)(0x20 + index), 0);
            bus.WriteByte(plane2 + (uint)index, (byte)(0x50 + index), 0);
        }

        Execute(text, 0xBADA_0010u);
        Assert.Equal(0xBADA_0010u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 4; index++)
        {
            Assert.Equal((byte)(0x20 + index), bus.ReadByte(plane + (uint)index));
            Assert.Equal((byte)(0x50 + index), bus.ReadByte(plane2 + (uint)index));
        }
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // A byte-aligned non-origin cell uses the next byte in every selected
        // plane while preserving the prefix before CurrentX.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0x24, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane2, 0x5A, 0);
        bus.WriteByte(plane2 + 1u, 0, 0);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x81, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));
        Assert.Equal((byte)0x81, bus.ReadByte(plane2 + 1u));

        // The non-origin arm preflights the shifted selected-plane span before
        // touching the preserved prefix or the destination byte.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 8);
        bus.WriteByte(plane, 0x12, 0);
        bus.WriteByte(plane + 1u, 0x24, 0);
        bus.WriteByte(plane2, 0x56, 0);
        bus.WriteByte(plane2 + 1u, 0x78, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal(1u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x12, bus.ReadByte(plane));
        Assert.Equal((byte)0x24, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x56, bus.ReadByte(plane2));
        Assert.Equal((byte)0x78, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // The sixteen-glyph source envelope is still transactional when its
        // final character falls outside the admitted fixed-cell range.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        for (var index = 0; index < 16; index++)
        {
            bus.WriteByte(plane + (uint)index, 0x24, 0);
            bus.WriteByte(plane2 + (uint)index, 0x5A, 0);
        }

        bus.WriteByte(text + 15u, (byte)'C', 0);
        Execute(text, 16);
        Assert.Equal(16u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 16; index++)
        {
            Assert.Equal((byte)0x24, bus.ReadByte(plane + (uint)index));
            Assert.Equal((byte)0x5A, bus.ReadByte(plane2 + (uint)index));
        }

        bus.WriteByte(text + 15u, (byte)'B', 0);

        // The second selected plane is still part of the transaction for the
        // two-glyph form; an odd link declines before either glyph is written.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteByte(plane, 0x24, 0);
        bus.WriteByte(plane + 1u, 0x35, 0);
        bus.WriteByte(plane2, 0x5A, 0);
        bus.WriteByte(plane2 + 1u, 0x6B, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 2);
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x35, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));
        Assert.Equal((byte)0x6B, bus.ReadByte(plane2 + 1u));
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2);

        // An unselected plane is preserved even when a second plane is
        // present in the bitmap.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane2, 0x5A, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 1);
        Execute(text, 1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x81, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));

        // A malformed selected plane declines before any selected plane is
        // modified, preserving the preflight transaction boundary.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3, 0);
        bus.WriteByte(plane, 0x24, 0);
        bus.WriteByte(plane2, 0x5A, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane2 + 1u);
        Execute(text, 1);
        Assert.Equal((byte)0x24, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane2));

        // Restore the one-plane fixture for the existing spacing and mode
        // coverage below.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        // The retained native spacing cells are byte-aligned JAM1 extensions.
        // Each admitted value keeps the glyph byte-aligned while adding blank
        // cells; richer modes remain fallback-owned until their own bounded
        // arm is admitted.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 8);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        for (var index = 0; index < 4; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)32, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x81, bus.ReadByte(plane));
        Assert.Equal((byte)0, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x42, bus.ReadByte(plane + 2u));

        // The next byte-aligned spacing cell keeps the same JAM1 contract
        // while advancing over two blank bytes per glyph.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 16);
