            (88, 12),
            (96, 13)
        })
        {
            bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, (ushort)(requiredBytes - 1));
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, (ushort)spacing);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
            for (var index = 0; index < 16; index++)
                bus.WriteByte(plane + (uint)index, 0xA5, 0);

            Execute(text, 0xABCD_0001u);

            Assert.Equal(0xABCD_0001u, cpu.State.D[0]);
            Assert.Equal((ushort)0, bus.ReadWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            for (var index = 0; index < 16; index++)
                Assert.Equal((byte)0xA5, bus.ReadByte(plane + (uint)index));
        }

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);

        // The same two-byte JAM2 arm publishes a set-valued BPen gap without
        // changing the glyph source or cursor contract.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 16);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1, 0);
        for (var index = 0; index < 3; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xCAFE_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)24, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 2u));

        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);

        // The native source envelope admits a complete 16-byte form.  Each
        // fixed-cell glyph consumes one destination byte in this one-row
        // fixture, so the cursor and alternating strike bytes expose the
        // bounded walk rather than only the first eight cells.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 16; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0010u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)128, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 16; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // The widened 128-byte envelope admits the complete longer fixture.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 128; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0080u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)1024, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 128; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // The next bounded source cell keeps the same fixed-cell/JAM1
        // contract while admitting a full 256-byte source span.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 256; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0100u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)2048, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 256; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // The 512-byte source cell retains the same complete preflight and
        // cursor contract while proving the larger forward envelope.
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 512; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0200u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4096, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 512; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // The widened source cell keeps the same complete preflight and
        // cursor contract while proving the next exact forward envelope.
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 1024);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 1024; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0400u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8192, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 1024; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // The next exact source envelope remains on the native fixed-cell
        // path.  It exercises both the 2048-byte preflight and the complete
        // destination walk rather than only the first few glyphs.
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2048);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 2048; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0800u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16384, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 2048; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // The widened fixed-cell source envelope admits the next exact
        // non-wrapping span.  Keep the destination row equal to the source
        // count so this case exercises the source walk and byte-aligned
        // strike publication without relying on extra padding.
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3072);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 3072; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(text, 0xBEEF_0C00u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)24576, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 3072; index++)
        {
            Assert.Equal(
                (byte)(index % 2 == 0 ? 0x81 : 0x42),
                bus.ReadByte(plane + (uint)index));
        }

        // Counts above the widened native source envelope decline before any
        // glyph or RastPort publication, preserving the caller's D0/state.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0x1234);
        bus.WriteByte(plane, 0xA5, 0);
        bus.WriteByte(plane + 1u, 0x5A, 0);
        Execute(text, 0xCAFE_0201u);
        Assert.Equal(0xCAFE_0201u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1234, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));

        Execute(text, 0xCAFE_0401u);
        Assert.Equal(0xCAFE_0401u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1234, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));

        Execute(text, 0xCAFE_0801u);
        Assert.Equal(0xCAFE_0801u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1234, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));

        // NULL and wrapping source envelopes take the same transparent path.
        Execute(0, 0xBEEF_0002u);
        Assert.Equal(0xBEEF_0002u, cpu.State.D[0]);
        Execute(0xFFFF_FFFEu, 0xD00D_0002u);
        Assert.Equal(0xD00D_0002u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1234, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 1u));
    }

    [Fact]
    public void NativeGraphicsTextPublishesBoundedProportionalOneGlyphOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_8000;
        const uint font = 0x00D2_8000;
        const uint text = 0x00D3_8000;
        const uint charLoc = 0x00D4_8000;
        const uint charSpace = 0x00D4_B000;
        const uint charData = 0x00D4_C000;
        const uint plane = 0x00D5_8000;
        const uint bitmap = 0x00D6_8000;
        const uint wrappedText = 0xFFFF_FC00;
        const uint stack = 0x00C0_8000;
        const uint returnAddress = 0x00F0_8000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(text, new byte[1024]);
        bus.MapWritableMemory(wrappedText, new byte[1024]);
        bus.MapWritableMemory(charLoc, new byte[4100]);
        bus.MapWritableMemory(charSpace, new byte[2050]);
        bus.MapWritableMemory(charData, new byte[1]);
        bus.MapWritableMemory(plane, new byte[1024]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        for (var index = 0; index < 1024; index++)
            bus.WriteByte(text + (uint)index, (byte)('A' + index), 0);
        bus.WriteWord(charLoc, 0); // MSB-first bit offset
        bus.WriteWord(charLoc + 2u, 3); // variable glyph width
        bus.WriteWord(charLoc + 4u, 0); // B uses the same bounded strike form
        bus.WriteWord(charLoc + 6u, 3);
        bus.WriteWord(charLoc + 8u, 0); // C uses the same bounded strike form
        bus.WriteWord(charLoc + 10u, 3);
        bus.WriteWord(charLoc + 12u, 0); // D uses the same bounded strike form
        bus.WriteWord(charLoc + 14u, 3);
        bus.WriteWord(charLoc + 16u, 0); // E uses the same bounded strike form
        bus.WriteWord(charLoc + 18u, 3);
        bus.WriteWord(charLoc + 20u, 0); // F uses the same bounded strike form
        bus.WriteWord(charLoc + 22u, 3);
        bus.WriteWord(charLoc + 24u, 0); // G uses the same bounded strike form
        bus.WriteWord(charLoc + 26u, 3);
        bus.WriteWord(charLoc + 28u, 0); // H uses the same bounded strike form
        bus.WriteWord(charLoc + 30u, 3);
        for (var index = 8; index < 16; index++)
        {
            bus.WriteWord(charLoc + (uint)(index * 4), 0);
            bus.WriteWord(charLoc + (uint)(index * 4 + 2), 3);
        }
        bus.WriteWord(charSpace, 5); // variable advance
        bus.WriteWord(charSpace + 2u, 8); // aligned second-glyph advance
        bus.WriteWord(charSpace + 4u, 8); // aligned third-glyph advance
        bus.WriteWord(charSpace + 6u, 8); // aligned fourth-glyph advance
        bus.WriteWord(charSpace + 8u, 8); // aligned fifth-glyph advance
        bus.WriteWord(charSpace + 10u, 8); // aligned sixth-glyph advance
        bus.WriteWord(charSpace + 12u, 8); // aligned seventh-glyph advance
        bus.WriteWord(charSpace + 14u, 8); // aligned eighth-glyph advance
        for (var index = 8; index < 16; index++)
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        for (var index = 16; index < 1024; index++)
        {
            bus.WriteWord(charLoc + (uint)(index * 4), 0);
            bus.WriteWord(charLoc + (uint)(index * 4 + 2), 3);
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        }
        bus.WriteWord(charSpace + 1024u, 8);
        bus.WriteByte(charData, 0xA0, 0); // 101 in the first three strike bits
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0); // FPF_PROPORTIONAL
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 128);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint sourcePointer = text)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.Text),
                stack + 0x80u);
            cpu.State.A[0] = sourcePointer;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0;
            // The native arm must zero-extend its WORD cursor/advance inputs
            // before longword arithmetic; caller register high halves are not
            // part of the graphics ABI contract.
            cpu.State.D[2] = 0xDEAD_0000u;
            cpu.State.D[5] = 0xBEEF_0000u;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1_000_000; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native proportional Text body did not return.");
        }

        Execute(1);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)5, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));
        Assert.Equal((byte)15, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortFirstDot,
            (ushort)(bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
                GraphicsLayouts.RastPortFirstDot));

        // A standard public BitMap is 0x28 bytes. A complete header beginning
        // at $FFFF_FFD8 must remain readable through AccurateM68000's 24-bit
        // alias; the glyph path only needs that published header and plane.
        const uint topBitMap = 0xFFFF_FFD8u;
        const uint topBitMapPhysical = topBitMap & 0x00FF_FFFFu;
        bus.MapWritableMemory(topBitMapPhysical, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteWord(topBitMapPhysical +
            (uint)GraphicsLayouts.BitMapBytesPerRow, 128);
        bus.WriteWord(topBitMapPhysical +
            (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(topBitMapPhysical +
            (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(topBitMapPhysical +
            (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, topBitMap);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0, 0);
        Execute(1);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)5, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));

        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'B', 0);
        bus.WriteWord(charSpace, 8);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        Execute(2);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 1u));
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
        bus.WriteWord(charSpace, 5);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);

        // The bounded proportional arm admits the same byte-aligned spacing
        // cells as the fixed-cell renderer. The glyph remains at the same
        // destination byte while the cursor includes the extra eight pixels.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 8);
        bus.WriteByte(plane, 0, 0);
        Execute(1);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)13, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));

        // An unaligned spacing value remains on the provider owner, with no
        // partial cursor or bitmap publication.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 7);
        bus.WriteByte(plane, 0x5A, 0);
        Execute(0xCAFE_0001u);
        Assert.Equal(0xCAFE_0001u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));

        // A two-glyph proportional walk preflights both table slots before
        // publishing either strike. The second glyph begins on the next
        // aligned byte and contributes its own CharSpace advance.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x20, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'B', 0);
        bus.WriteWord(charSpace, 8);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        Execute(2);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 1u));

        // The bounded arm also admits a three-glyph forward walk with the
        // same complete preflight and aligned one-byte destination cells.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'C', 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        Execute(3);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)24, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 2u));

        // A malformed third advance declines after the complete preflight,
        // leaving the first two destination bytes untouched.
        bus.WriteWord(charSpace + 4u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        Execute(3);
        Assert.Equal(3u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        bus.WriteWord(charSpace + 4u, 8);

        // The bounded arm also admits a four-glyph forward walk after the
        // same complete preflight and aligned one-byte destination cells.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'D', 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        bus.WriteByte(plane + 3u, 0, 0);
        Execute(4);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)32, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 3u));

        // A malformed fourth advance declines after the complete preflight,
        // leaving the first three destination bytes untouched.
        bus.WriteWord(charSpace + 6u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        bus.WriteByte(plane + 2u, 0x3C, 0);
        bus.WriteByte(plane + 3u, 0xC3, 0);
        Execute(4);
        Assert.Equal(4u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0xC3, bus.ReadByte(plane + 3u));
        bus.WriteWord(charSpace + 6u, 8);

        // The bounded arm also admits the complete eight-glyph selector span;
        // source/table/destination preflight still completes before any write.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'H', 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 8; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(8);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)64, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 8; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // Counts nine through sixteen share the same preflighted transaction
        // with a conservative sixteen-byte source envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 16; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(16);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)128, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 16; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // A malformed sixteenth advance declines after the complete wide
        // preflight and leaves every earlier destination cell untouched.
        bus.WriteWord(charSpace + 30u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var sixteenthSentinels = new byte[]
        {
            0x5A, 0xA5, 0x3C, 0xC3, 0x96, 0x69, 0xF0, 0x0F,
            0x12, 0x21, 0x34, 0x43, 0x56, 0x65, 0x78, 0x87,
        };
        for (var index = 0; index < sixteenthSentinels.Length; index++)
            bus.WriteByte(plane + (uint)index, sixteenthSentinels[index], 0);
        Execute(16);
        Assert.Equal(16u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < sixteenthSentinels.Length; index++)
            Assert.Equal(sixteenthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 30u, 8);

        // Counts seventeen through thirty-two reuse the same preflighted
        // transaction with a conservative thirty-two-byte source envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'`', 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 32; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(32);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)256, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 32; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // A malformed thirty-second advance declines after the complete
        // wide preflight and leaves every earlier destination cell untouched.
        bus.WriteWord(charSpace + 62u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var thirtySecondSentinels = new byte[]
        {
            0x5A, 0xA5, 0x3C, 0xC3, 0x96, 0x69, 0xF0, 0x0F,
            0x12, 0x21, 0x34, 0x43, 0x56, 0x65, 0x78, 0x87,
            0x18, 0x81, 0x27, 0x72, 0x39, 0x93, 0x4B, 0xB4,
            0x5D, 0xD5, 0x6E, 0xE6, 0x7F, 0xF7, 0x8A, 0xA8,
        };
        for (var index = 0; index < thirtySecondSentinels.Length; index++)
            bus.WriteByte(plane + (uint)index, thirtySecondSentinels[index], 0);
        Execute(32);
        Assert.Equal(32u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < thirtySecondSentinels.Length; index++)
            Assert.Equal(thirtySecondSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 62u, 8);

        // Counts thirty-three through sixty-four reuse the same preflighted
        // transaction with a conservative sixty-four-byte source envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)('A' + 63), 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 64; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(64);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)512, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 64; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // A malformed sixty-fourth advance declines after the complete wide
        // preflight and leaves every earlier destination cell untouched.
        bus.WriteWord(charSpace + 126u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var sixtyFourthSentinels = new byte[64];
        for (var index = 0; index < sixtyFourthSentinels.Length; index++)
        {
            sixtyFourthSentinels[index] = (byte)(0x5A + (index * 37));
            bus.WriteByte(plane + (uint)index, sixtyFourthSentinels[index], 0);
        }
        Execute(64);
        Assert.Equal(64u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < sixtyFourthSentinels.Length; index++)
            Assert.Equal(sixtyFourthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 126u, 8);

        // Counts sixty-five through one hundred twenty-eight reuse the same
        // preflighted transaction with a conservative one-hundred-twenty-eight-
        // byte source and destination envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xC0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 128; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(128);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)1024, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 128; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // A malformed one-hundred-twenty-eighth advance declines after the
        // complete preflight and leaves every earlier destination cell untouched.
        bus.WriteWord(charSpace + 254u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var oneHundredTwentyEighthSentinels = new byte[128];
        for (var index = 0; index < oneHundredTwentyEighthSentinels.Length; index++)
        {
            oneHundredTwentyEighthSentinels[index] = (byte)(0x5A + (index * 37));
            bus.WriteByte(plane + (uint)index, oneHundredTwentyEighthSentinels[index], 0);
        }
        Execute(128);
        Assert.Equal(128u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < oneHundredTwentyEighthSentinels.Length; index++)
            Assert.Equal(oneHundredTwentyEighthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 254u, 8);

        // Counts one hundred twenty-nine through two hundred fifty-six reuse
        // the same preflighted transaction with a widened 256-byte source and
        // destination envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xFF, 0);
        for (var index = 0; index <= 256; index++)
        {
            bus.WriteWord(charLoc + (uint)(index * 4), 0);
            bus.WriteWord(charLoc + (uint)(index * 4 + 2), 3);
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        }
        for (var index = 0; index < 256; index++)
            bus.WriteByte(text + (uint)index, 0, 0);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 256);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 256; index++)
            bus.WriteByte(plane + (uint)index, 0, 0);
        Execute(256);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)2048, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 256; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // A malformed two-hundred-fifty-sixth advance declines after the
        // complete preflight and leaves every earlier destination cell
        // untouched.
        bus.WriteByte(text + 255u, 1, 0);
        bus.WriteWord(charSpace + 2u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var twoHundredFiftySixthSentinels = new byte[256];
        for (var index = 0; index < twoHundredFiftySixthSentinels.Length; index++)
        {
            twoHundredFiftySixthSentinels[index] = (byte)(0x5A + (index * 37));
            bus.WriteByte(plane + (uint)index, twoHundredFiftySixthSentinels[index], 0);
        }
        Execute(256);
        Assert.Equal(256u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < twoHundredFiftySixthSentinels.Length; index++)
            Assert.Equal(twoHundredFiftySixthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 2u, 8);

        // Counts two hundred fifty-seven through five hundred twelve reuse
        // the same preflighted transaction with the widened 512-byte source
        // and destination envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xFF, 0);
        for (var index = 0; index <= 512; index++)
        {
            bus.WriteWord(charLoc + (uint)(index * 4), 0);
            bus.WriteWord(charLoc + (uint)(index * 4 + 2), 3);
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        }
        for (var index = 0; index < 512; index++)
        {
            bus.WriteByte(text + (uint)index, 0, 0);
            bus.WriteByte(plane + (uint)index, 0, 0);
        }
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        Execute(512);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4096, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 512; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // The widened source envelope admits a complete 512-byte stream at
        // the final non-wrapping address, then declines the first wrapping
        // address before any destination or cursor publication.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 512; index++)
        {
            bus.WriteByte(wrappedText + (uint)index, 0, 0);
            bus.WriteByte(plane + (uint)index, 0, 0);
        }
        Execute(512, wrappedText);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4096, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 512; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var wrappedSourceSentinels = new byte[] { 0x5A, 0xA5 };
        for (var index = 0; index < wrappedSourceSentinels.Length; index++)
            bus.WriteByte(plane + (uint)index, wrappedSourceSentinels[index], 0);
        Execute(512, wrappedText + 1u);
        Assert.Equal(512u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < wrappedSourceSentinels.Length; index++)
            Assert.Equal(wrappedSourceSentinels[index], bus.ReadByte(plane + (uint)index));

        // A malformed five-hundred-twelfth advance declines after the
        // complete preflight and leaves every earlier destination cell
        // untouched.
        bus.WriteByte(text + 511u, 1, 0);
        bus.WriteWord(charSpace + 2u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var fiveHundredTwelfthSentinels = new byte[512];
        for (var index = 0; index < fiveHundredTwelfthSentinels.Length; index++)
        {
            fiveHundredTwelfthSentinels[index] = (byte)(0x5A + (index * 37));
            bus.WriteByte(plane + (uint)index, fiveHundredTwelfthSentinels[index], 0);
        }
        Execute(512);
        Assert.Equal(512u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < fiveHundredTwelfthSentinels.Length; index++)
            Assert.Equal(fiveHundredTwelfthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 2u, 8);

        // Counts five hundred thirteen through one thousand twenty-four reuse
        // the same preflighted transaction with the widened 1024-byte source
        // and destination envelope.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 0xFF, 0);
        for (var index = 0; index <= 1024; index++)
        {
            bus.WriteWord(charLoc + (uint)(index * 4), 0);
            bus.WriteWord(charLoc + (uint)(index * 4 + 2), 3);
            bus.WriteWord(charSpace + (uint)(index * 2), 8);
        }
        for (var index = 0; index < 1024; index++)
        {
            bus.WriteByte(text + (uint)index, 0, 0);
            bus.WriteByte(plane + (uint)index, 0, 0);
        }
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 1024);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        Execute(1024);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8192, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 1024; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        // The widened source envelope admits the complete 1024-byte stream at
        // the final non-wrapping address, then declines the first wrapping
        // address before any destination or cursor publication.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        for (var index = 0; index < 1024; index++)
        {
            bus.WriteByte(wrappedText + (uint)index, 0, 0);
            bus.WriteByte(plane + (uint)index, 0, 0);
        }
        Execute(1024, wrappedText);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8192, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < 1024; index++)
            Assert.Equal((byte)0xA0, bus.ReadByte(plane + (uint)index));

        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var wrappedSource1024Sentinels = new byte[] { 0x5A, 0xA5 };
        for (var index = 0; index < wrappedSource1024Sentinels.Length; index++)
            bus.WriteByte(plane + (uint)index, wrappedSource1024Sentinels[index], 0);
        Execute(1024, wrappedText + 1u);
        Assert.Equal(1024u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < wrappedSource1024Sentinels.Length; index++)
            Assert.Equal(wrappedSource1024Sentinels[index], bus.ReadByte(plane + (uint)index));

        // A malformed final advance declines after the complete preflight and
        // leaves every earlier destination cell untouched.
        bus.WriteByte(text + 1023u, 1, 0);
        bus.WriteWord(charSpace + 2u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var oneThousandTwentyFourthSentinels = new byte[1024];
        for (var index = 0; index < oneThousandTwentyFourthSentinels.Length; index++)
        {
            oneThousandTwentyFourthSentinels[index] = (byte)(0x5A + (index * 37));
            bus.WriteByte(plane + (uint)index, oneThousandTwentyFourthSentinels[index], 0);
        }
        Execute(1024);
        Assert.Equal(1024u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < oneThousandTwentyFourthSentinels.Length; index++)
            Assert.Equal(oneThousandTwentyFourthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 2u, 8);

        // Counts beyond one thousand twenty-four remain transparent and
        // preserve the complete incoming D0 value.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        Execute(1025);
        Assert.Equal(1025u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'P', 0);
        for (var index = 0; index < 16; index++)
            bus.WriteByte(text + (uint)index, (byte)('A' + index), 0);
        // A nonzero CharLoc bit offset is accepted when the complete glyph
        // remains inside its single source strike byte.  Both glyphs use
        // source bits 5..3 (101) from 0x28 and publish the same destination
        // pixels as the byte-aligned form.
        bus.WriteWord(charLoc, 2);
        bus.WriteWord(charLoc + 4u, 2);
        bus.WriteByte(charData, 0x28, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        Execute(2);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane));
        Assert.Equal((byte)0xA0, bus.ReadByte(plane + 1u));

        // The upper in-byte boundary (offset seven, width one) is admitted
        // as well and still publishes the source LSB into the destination MSB.
        bus.WriteWord(charLoc, 7);
        bus.WriteWord(charLoc + 2u, 1);
        bus.WriteWord(charLoc + 4u, 7);
        bus.WriteWord(charLoc + 6u, 1);
        bus.WriteByte(charData, 0x01, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 1u, 0, 0);
        Execute(2);
        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)16, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 1u));

        bus.WriteWord(charLoc, 2);
        bus.WriteWord(charLoc + 2u, 3);
        bus.WriteWord(charLoc + 4u, 2);
        bus.WriteWord(charLoc + 6u, 3);
        bus.WriteByte(charData, 0x28, 0);

        // A nonzero offset whose width would cross the one-byte strike is a
        // preflight decline, so neither glyph can partially publish.
        bus.WriteWord(charLoc, 6);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        Execute(2);
        Assert.Equal(2u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));

        // Restore the byte-aligned fixture for the remaining bounded-count
        // and ownership tests.
        bus.WriteWord(charLoc, 0);
        bus.WriteWord(charLoc + 4u, 0);
        bus.WriteByte(charData, 0xA0, 0);

        // A malformed eighth advance declines after the complete preflight,
        // leaving all seven earlier destination bytes untouched.
        bus.WriteWord(charSpace + 14u, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        var eighthSentinels = new byte[] { 0x5A, 0xA5, 0x3C, 0xC3, 0x96, 0x69, 0xF0, 0x0F };
        for (var index = 0; index < eighthSentinels.Length; index++)
            bus.WriteByte(plane + (uint)index, eighthSentinels[index], 0);
        Execute(8);
        Assert.Equal(8u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        for (var index = 0; index < eighthSentinels.Length; index++)
            Assert.Equal(eighthSentinels[index], bus.ReadByte(plane + (uint)index));
        bus.WriteWord(charSpace + 14u, 8);

        // A high-word count remains transparent and preserves the complete
        // incoming D0 value even when its low word is inside the selector.
        // remain transparent and preserve the complete incoming D0 value.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0x5A, 0);
        bus.WriteByte(plane + 1u, 0xA5, 0);
        Execute(0xCAFE_0021u);
        Assert.Equal(0xCAFE_0021u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 1u));

        // A styled proportional font remains on the portable/provider owner,
        // preserving the caller's D0, cursor, and destination bytes.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x21, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        bus.WriteByte(plane, 0x5A, 0);
        Execute(0xCAFE_0001u);
        Assert.Equal(0xCAFE_0001u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x5A, bus.ReadByte(plane));
    }

    [Fact]
    public void NativeGraphicsTextUsesFixedCellDefaultGlyphForOutOfRangeCharacterOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint font = 0x00D2_0000;
        const uint text = 0x00D3_0000;
        const uint charData = 0x00D4_0000;
        const uint plane = 0x00D5_0000;
        const uint bitmap = 0x00D6_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(text, new byte[1]);
        bus.MapWritableMemory(charData, new byte[2]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(bitmap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteByte(text, (byte)'B', 0);
        bus.WriteByte(charData, 0x81, 0);
        bus.WriteByte(charData + 1u, 0x42, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitmap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);

        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitmap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.Text),
            stack + 0x80u);
        cpu.State.A[0] = text;
        cpu.State.A[1] = rastPort;
        cpu.State.D[0] = 1;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)8, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0x42, bus.ReadByte(plane));
        Assert.Equal((byte)0, bus.ReadByte(plane + 1u));

        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'Z', 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteByte(plane, 0xA5, 0);
        bus.WriteLong(stack + 0x80u, returnAddress);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.Text),
            stack + 0x80u);
        cpu.State.A[0] = text;
        cpu.State.A[1] = rastPort;
        cpu.State.D[0] = 0xDEAD_0001u;
        cpu.ExecuteInstruction(); // vector JMP.L
        for (var index = 0; index < 4096; index++)
        {
            cpu.ExecuteInstruction();
            if (cpu.State.ProgramCounter == returnAddress)
                break;
        }

        Assert.Equal(returnAddress, cpu.State.ProgramCounter);
        Assert.Equal(0xDEAD_0001u, cpu.State.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane));
    }

    [Fact]
    public void NativeGraphicsAreaMoveReplacesPendingMoveOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint areaInfo = 0x00D2_0000;
        const uint vectors = 0x00E1_0000;
        const uint flags = 0x00E2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectors, new byte[0x20]);
        bus.MapWritableMemory(flags, new byte[0x10]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void PreparePending(byte marker, ushort maxCount = 2, uint vectorPointer = vectors + 4u)
        {
            bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectorPointer);
            bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags + 1u);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, maxCount);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 9);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 10);
            bus.WriteWord(vectors + 0u, 9);
            bus.WriteWord(vectors + 2u, 10);
            bus.WriteByte(flags + 0u, marker, 0);
            bus.WriteByte(flags + 1u, 0xB2, 0);
        }

        void Execute(short x, short y, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.AreaMove),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)x);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 768; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native AreaMove pending-move body did not return.");
        }

        PreparePending(0);
        Execute(4, 5, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)5, bus.ReadWord(vectors + 2u));
        Assert.Equal((byte)0, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)0xB2, bus.ReadByte(flags + 1u));
        Assert.Equal(vectors + 4u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 1u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)4, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)5, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        PreparePending(1);
        Execute(6, 7, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0006u, cpu.State.D[0]);
        Assert.Equal((ushort)9, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)10, bus.ReadWord(vectors + 2u));
        Assert.Equal((byte)1, bus.ReadByte(flags + 0u));
        Assert.Equal((ushort)9, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)10, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        PreparePending(0, maxCount: 1);
        Execute(6, 7, 0xD00D_0000u);
        Assert.Equal(0xD00D_0006u, cpu.State.D[0]);

        PreparePending(0, vectorPointer: 2u);
        Execute(6, 7, 0xFACE_0000u);
        Assert.Equal(0xFACE_0006u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsAreaDrawPublishesOneSegmentAfterMoveOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_2000;
        const uint areaInfo = 0x00D2_2000;
        const uint vectors = 0x00E1_2000;
        const uint flags = 0x00E2_2000;
        const uint stack = 0x00C0_2000;
        const uint returnAddress = 0x00F0_2000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectors, new byte[0x20]);
        bus.MapWritableMemory(flags, new byte[0x10]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Prepare(ushort count = 1, ushort maxCount = 2, uint vectorPointer = vectors + 4u, uint flagPointer = flags + 1u)
        {
            bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectorPointer);
            bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flagPointer);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, count);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, maxCount);
            bus.WriteWord(vectors + 0u, 9);
            bus.WriteWord(vectors + 2u, 10);
            bus.WriteByte(flags + 0u, 0xB2, 0);
            bus.WriteByte(flags + 1u, 0xC3, 0);
        }

        void Execute(short x, short y, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.AreaDraw),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)x);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 768; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native AreaDraw segment body did not return.");
        }

        Prepare();
        Execute(4, 5, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)9, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)10, bus.ReadWord(vectors + 2u));
        Assert.Equal((ushort)4, bus.ReadWord(vectors + 4u));
        Assert.Equal((ushort)5, bus.ReadWord(vectors + 6u));
        Assert.Equal((byte)0xB2, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)1, bus.ReadByte(flags + 1u));
        Assert.Equal(vectors + 8u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 2u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)2, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        Prepare(count: 2, maxCount: 3);
        Execute(6, 7, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)9, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)10, bus.ReadWord(vectors + 2u));
        Assert.Equal((ushort)6, bus.ReadWord(vectors + 4u));
        Assert.Equal((ushort)7, bus.ReadWord(vectors + 6u));
        Assert.Equal((byte)0xB2, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)1, bus.ReadByte(flags + 1u));
        Assert.Equal((byte)0, bus.ReadByte(flags + 2u));
        Assert.Equal(vectors + 8u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 2u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)3, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        // A full collector remains on the provider/portable owner and keeps
        // the caller's D0 and published state unchanged.
        Prepare(count: 2, maxCount: 2);
        bus.WriteWord(vectors + 4u, 0x1357);
        bus.WriteWord(vectors + 6u, 0x2468);
        Execute(6, 7, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0006u, cpu.State.D[0]);
        Assert.Equal((ushort)0x1357, bus.ReadWord(vectors + 4u));
        Assert.Equal((ushort)0x2468, bus.ReadWord(vectors + 6u));
        Assert.Equal((ushort)2, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        // An odd vector or NULL flag pointer is declined before either table
        // is touched. The flag table is byte-addressed, so odd flag pointers
        // are valid and are intentionally not rejected by this unit.
        Prepare(vectorPointer: vectors + 5u);
        Execute(6, 7, 0xD00D_0000u);
        Assert.Equal(0xD00D_0006u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Prepare(flagPointer: 0);
        Execute(6, 7, 0xFACE_0000u);
        Assert.Equal(0xFACE_0006u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void NativeGraphicsAreaEndResetsZeroMaskCollectorOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint areaInfo = 0x00D2_0000;
        const uint vectors = 0x00E1_0000;
        const uint flags = 0x00E2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectors, new byte[0x20]);
        bus.MapWritableMemory(flags, new byte[0x10]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0, 0);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable, vectors);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable, flags);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectors + 4u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags + 1u);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 2);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 9);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 10);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint initialD0, uint? port = null)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.AreaEnd),
                stack + 0x80u);
            cpu.State.A[1] = port ?? rastPort;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 768; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native AreaEnd body did not return.");
        }

        Execute(0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(vectors, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        // A complete public RastPort may start at the final valid logical
        // address. The accurate 68000 core accesses its 24-bit alias, while
        // AreaEnd must retain the complete 32-bit caller envelope.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 0, 0);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer,
            vectors + 4u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer,
            flags + 1u);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 9);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 10);
        Execute(0xBEEF_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal(vectors, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)0, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectors + 4u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags + 1u);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 13);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 14);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 1);
        Execute(0x1234_0000u);
        Assert.Equal(0x1234_0000u, cpu.State.D[0]);
        Assert.Equal(vectors + 4u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 1u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)13, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)14, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        // A nonzero mask leaves the collector untouched and preserves the
        // caller's D0 while the portable renderer handles the recorded shape.
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectors + 4u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags + 1u);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 11);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 12);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0000u, cpu.State.D[0]);
        Assert.Equal(vectors + 4u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 1u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)11, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)12, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));
    }

    [Fact]
