        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectors, new byte[0x20]);
        bus.MapWritableMemory(flags, new byte[0x10]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectors);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 0x5555);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 0x6666);
        bus.WriteWord(vectors + 0u, 0x1111);
        bus.WriteWord(vectors + 2u, 0x2222);
        bus.WriteByte(flags + 0u, 0xA1, 0);
        bus.WriteByte(flags + 1u, 0xB2, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            short x,
            short y,
            short radiusX,
            short radiusY,
            uint initialD0,
            uint? port = null)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.AreaEllipse),
                stack + 0x80u);
            cpu.State.A[1] = port ?? rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)x);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.State.D[2] = unchecked((ushort)radiusX);
            cpu.State.D[3] = unchecked((ushort)radiusY);
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 512; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native AreaEllipse body did not return.");
        }

        Execute(4, 5, 2, 3, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)5, bus.ReadWord(vectors + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(vectors + 4u));
        Assert.Equal((ushort)3, bus.ReadWord(vectors + 6u));
        Assert.Equal((byte)3, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)3, bus.ReadByte(flags + 1u));
        Assert.Equal(vectors + 8u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 2u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)2, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)4, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)5, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        // The pair itself occupies eight bytes, but AreaEllipse then publishes
        // the advanced VectorPointer.  $FFFF_FFF6 is the final aligned base
        // whose one-past cursor remains representable; $FFFF_FFF8 must
        // decline before any write could publish a wrapped null pointer.
        const uint topVectors = 0xFFFF_FFF6u;
        const uint topVectorsPhysical = topVectors & 0x00FF_FFFFu;
        bus.MapWritableMemory(topVectorsPhysical, new byte[8]);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer,
            topVectors);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer,
            flags);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);
        Execute(4, 5, 2, 3, 0xACED_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(topVectorsPhysical + 0u));
        Assert.Equal((ushort)5, bus.ReadWord(topVectorsPhysical + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(topVectorsPhysical + 4u));
        Assert.Equal((ushort)3, bus.ReadWord(topVectorsPhysical + 6u));
        Assert.Equal(0xFFFF_FFFEu, bus.ReadLong(areaInfo +
            (uint)GraphicsLayouts.AreaInfoVectorPointer));

        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer,
            0xFFFF_FFF8u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer,
            flags);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);
        Execute(4, 5, 2, 3, 0xD00D_0000u);
        Assert.Equal(0xD00D_0004u, cpu.State.D[0]);

        // A complete public RastPort may start at the final valid logical
        // address. The accurate 68000 core accesses its 24-bit alias, while
        // native AreaEllipse must retain the complete 32-bit envelope.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer,
            vectors);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer,
            flags);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);
        bus.WriteWord(vectors + 0u, 0x1111);
        bus.WriteWord(vectors + 2u, 0x2222);
        bus.WriteByte(flags + 0u, 0xA1, 0);
        bus.WriteByte(flags + 1u, 0xB2, 0);
        Execute(4, 5, 2, 3, 0xBEEF_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)5, bus.ReadWord(vectors + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(vectors + 4u));
        Assert.Equal((ushort)3, bus.ReadWord(vectors + 6u));
        Assert.Equal((byte)3, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)3, bus.ReadByte(flags + 1u));

        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
        // Model a real pending AreaMove: the current pointers are the slot
        // after the pending center vector/flag, and the preceding flag is
        // deliberately nonzero so this remains an unsupported polygon form.
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectors + 4u);
        bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags + 1u);
        bus.WriteByte(flags + 0u, 0xA1, 0);
        bus.WriteByte(flags + 1u, 0xB2, 0);
        Execute(4, 5, 2, 3, 0xBEEF_0000u);
        Assert.Equal(0xBEEF_0004u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((byte)0xA1, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)0xB2, bus.ReadByte(flags + 1u));

        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 0);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 1);
        Execute(4, 5, 2, 3, 0xD00D_0000u);
        Assert.Equal(0xD00D_0004u, cpu.State.D[0]);
        bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, 4);

        Execute(4, 5, 0, 3, 0xFACE_0000u);
        Assert.Equal(0xFACE_0004u, cpu.State.D[0]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo + 1u);
        Execute(4, 5, 2, 3, 0xABCD_0000u);
        Assert.Equal(0xABCD_0004u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsAreaEllipseReplacesPendingMoveOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint areaInfo = 0x00D2_0000;
        const uint vectors = 0x00E1_0000;
        const uint flags = 0x00E2_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(vectors, new byte[0x20]);
        bus.MapWritableMemory(flags, new byte[0x10]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void PreparePending(byte marker, ushort maxCount = 4)
        {
            bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer, vectors + 4u);
            bus.WriteLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer, flags + 1u);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount, 1);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount, maxCount);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX, 9);
            bus.WriteWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY, 10);
            bus.WriteWord(vectors + 0u, 0x1111);
            bus.WriteWord(vectors + 2u, 0x2222);
            bus.WriteWord(vectors + 4u, 9);
            bus.WriteWord(vectors + 6u, 10);
            bus.WriteByte(flags + 0u, marker, 0);
            bus.WriteByte(flags + 1u, 0xB2, 0);
        }

        void Execute(uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.AreaEllipse),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | 4u;
            cpu.State.D[1] = 5;
            cpu.State.D[2] = 2;
            cpu.State.D[3] = 3;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 4096; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native AreaEllipse pending-move body did not return.");
        }

        PreparePending(0);
        Execute(0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)4, bus.ReadWord(vectors + 0u));
        Assert.Equal((ushort)5, bus.ReadWord(vectors + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(vectors + 4u));
        Assert.Equal((ushort)3, bus.ReadWord(vectors + 6u));
        Assert.Equal((byte)3, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)3, bus.ReadByte(flags + 1u));
        Assert.Equal(vectors + 8u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 2u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)2, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)9, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)10, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));

        PreparePending(1);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0004u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((byte)1, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)0xB2, bus.ReadByte(flags + 1u));
        Assert.Equal(vectors + 4u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 1u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));

        PreparePending(1);
        // A marker-1 point that differs from FirstX/FirstY requires the
        // portable closure path and must not be partially appended natively.
        bus.WriteWord(vectors + 4u, 8);
        Execute(0xBEEF_0000u);
        Assert.Equal(0xBEEF_0004u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((byte)1, bus.ReadByte(flags + 0u));
        Assert.Equal((byte)0xB2, bus.ReadByte(flags + 1u));
        Assert.Equal(vectors + 4u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(flags + 1u, bus.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));

        PreparePending(0, maxCount: 2);
        Execute(0xD00D_0000u);
        Assert.Equal(0xD00D_0004u, cpu.State.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void NativeGraphicsDrawDiagonalOnePublishesFreshSegmentOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint bitMap = 0x00D2_0000;
        const uint plane = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[34]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint targetX, uint targetY, uint initialD0, uint? port = null)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.Draw),
                stack + 0x80u);
            cpu.State.A[1] = port ?? rastPort;
            cpu.State.D[0] = initialD0 | (targetX & 0xFFFFu);
            cpu.State.D[1] = targetY & 0xFFFFu;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 2048; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native Draw diagonal body did not return.");
        }

        Execute(1, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)14, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The direct diagonal arm admits a complete RastPort at the final
        // logical address, while the AccurateM68000 core dereferences its
        // normal 24-bit physical alias.
        const uint topRastPort = 0xFFFF_FF4Cu;
        const uint topRastPortPhysical = topRastPort & 0x00FF_FFFFu;
        bus.MapWritableMemory(topRastPortPhysical,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        Execute(1, 1, 0xD00D_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)1, bus.ReadWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentY));

        // The shared shallow-slope arm has the same complete public header
        // admission. Reset the exact-end cursor and route its three inclusive
        // samples through the native `(0,0)` to `(2,1)` body.
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        Execute(2, 1, 0xC0DE_0000u, topRastPort);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xC0, bus.ReadByte(plane));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((byte)13, bus.ReadByte(topRastPortPhysical +
            (uint)GraphicsLayouts.RastPortLinePatternCount));

        // APen zero clears the same two MSB-first samples and preserves the
        // cursor state produced by the preceding segment.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(plane, 0xFF, 0);
        bus.WriteByte(plane + 2u, 0xFF, 0);
        Execute(1, 1, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x7F, bus.ReadByte(plane));
        Assert.Equal((byte)0xBF, bus.ReadByte(plane + 2u));

        // The bounded shallow slope claims the inclusive
        // `(0,0)`, `(1,0)`, `(2,1)` Bresenham samples natively.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteByte(plane, 0, 0);
        bus.WriteByte(plane + 2u, 0, 0);
        Execute(2, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xC0, bus.ReadByte(plane));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The transposed shallow slope claims `(0,0)`, `(0,1)`, `(1,2)` on
        // the same standard planar profile once the three rows are present.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 6; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(1, 2, 0xA55A_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 4u));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

