        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(210, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 14u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 29; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x7F, bus.ReadByte(plane + 29u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)210, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(211,1)` consumes the same visible clipped raster as `(212,1)`:
        // x=0..105 on row zero and x=106..127 on row one. Its off-raster tail
        // differs only in the endpoint and line-pattern phase.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(211, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xC0, bus.ReadByte(plane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 14u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 29; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x3F, bus.ReadByte(plane + 29u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)211, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(212,1)` renders the entire clipped 16-byte planar envelope:
        // x=0..105 on row zero, then x=106..127 on row one. The native body
        // keeps consuming the clipped remainder for cursor/phase parity.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(212, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xC0, bus.ReadByte(plane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 14u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 29; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x3F, bus.ReadByte(plane + 29u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)212, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)11, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(239,1)` is beyond the generated 16-byte terminal ladder. The
        // runtime form draws the row-zero x=0..119 prefix and only the
        // visible row-one x=120..127 suffix while preserving the full
        // endpoint and phase.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(239, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 15; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 31; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)239, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // A declined BPR=16 runtime admission must remain transparent to the
        // generic Draw owner after the former exact terminal bodies retire.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0x5A, 0);
        Execute(208, 1, 0xD00D_0000u);
        Assert.Equal(0xD00D_00D0u, cpu.State.D[0]);
        for (uint index = 0; index < 32; index++)
            Assert.Equal((byte)0x5A, bus.ReadByte(plane + index));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(GraphicsLayouts.RastPortFirstDot,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);

        // `(213,1)` is the first native 17-byte-row diagonal: x=0..106 is
        // on row zero and x=107..135 is on row one.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(213, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xE0, bus.ReadByte(plane + 13u));
        for (uint index = 14; index < 30; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x1F, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)213, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)10, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(214,1)` has its own exact endpoint body and phase, even though
        // the 17-byte visible prefix matches `(213,1)`.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(214, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xE0, bus.ReadByte(plane + 13u));
        for (uint index = 14; index < 30; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x1F, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)214, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)9, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(215,1)` reaches row one after x=107, so unlike the preceding
        // endpoints it exposes both nibbles of the seventeenth byte while
        // retaining the same complete two-row storage envelope.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(215, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xF0, bus.ReadByte(plane + 13u));
        for (uint index = 14; index < 30; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x0F, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)215, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)8, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Verify every later terminal at the Draw vector itself. These use
        // the same complete 17-byte, two-row admission envelope as their
        // PolyDraw wrappers but must not depend on that wrapper for coverage.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        for (uint targetX = 216; targetX <= 255; targetX++)
        {
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
            for (uint index = 0; index < 34; index++)
                bus.WriteByte(plane + index, 0, 0);
            Execute(targetX, 1, 0xD00D_0000u);
            Assert.Equal(0u, cpu.State.D[0]);
            Assert.Equal((ushort)targetX, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
            Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
            Assert.Equal((byte)((15 - targetX) & 0x0F),
                bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
            if (targetX == 255)
            {
                // No generated terminal exists beyond 224. This verifies the
                // runtime body’s clipped raster: row zero owns x=0..127 and
                // row one owns only the visible x=128..135 suffix.
                for (uint index = 0; index < 16; index++)
                    Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
                Assert.Equal((byte)0x00, bus.ReadByte(plane + 16u));
                for (uint index = 17; index < 33; index++)
                    Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
                Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
            }
        }

        // The same runtime path must retain the generated arms' low-bit
        // FgPen selection. Start from set pixels so FgPen zero proves actual
        // native clears rather than a no-op/fallback result.
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0xFF, 0);
        Execute(255, 1, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 16; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        for (uint index = 16; index < 33; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)255, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeGraphicsDrawOrthogonalSpansPublishRasterAndCursorOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint bitMap = 0x00D2_0000;
        const uint plane = 0x00D3_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[8]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void ResetState(ushort currentX, ushort currentY)
        {
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, currentX);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, currentY);
            for (uint index = 0; index < 8; index++)
                bus.WriteByte(plane + index, 0, 0);
        }

        void Execute(ushort targetX, ushort targetY, uint initialD0)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.Draw),
                stack + 0x80u);
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0 | targetX;
            cpu.State.D[1] = targetY;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 1024; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native Draw orthogonal body did not return.");
        }

        // Forward horizontal: x=0..10 crosses the first planar byte and
        // leaves the inclusive endpoint/cursor at (10,0).
        ResetState(0, 0);
        Execute(10, 0, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane));
        Assert.Equal((byte)0xE0, bus.ReadByte(plane + 1u));
        Assert.Equal((ushort)10, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((byte)5, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Reverse horizontal traverses the same inclusive span from x=10
        // back to x=0 and publishes the reverse endpoint.
        ResetState(10, 0);
        Execute(0, 0, 0xBEEF_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xFF, bus.ReadByte(plane));
        Assert.Equal((byte)0xE0, bus.ReadByte(plane + 1u));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((byte)5, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Forward vertical writes the four row samples at x=0.
        ResetState(0, 0);
        Execute(0, 3, 0xD00D_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 6u));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Reverse vertical traverses the same inclusive four-row span.
        ResetState(0, 3);
        Execute(0, 0, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 6u));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeGraphicsPolyDrawDiagonalOneReusesDrawBodyOnAccurateM68000()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D1_0000;
        const uint bitMap = 0x00D2_0000;
        const uint plane = 0x00D3_0000;
        const uint points = 0x00D4_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[34]);
        bus.MapWritableMemory(points, new byte[4]);
        bus.MapWritableMemory(stack, new byte[0x100]);

        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteWord(points, 1);
        bus.WriteWord(points + 2u, 1);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(uint targetX, uint targetY, uint initialD0)
        {
            bus.WriteWord(points, unchecked((ushort)targetX));
            bus.WriteWord(points + 2u, unchecked((ushort)targetY));
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.PolyDraw),
                stack + 0x80u);
            cpu.State.A[0] = points;
            cpu.State.A[1] = rastPort;
            cpu.State.D[0] = initialD0;
            cpu.ExecuteInstruction(); // vector JMP.L
            for (var index = 0; index < 2048; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native PolyDraw diagonal body did not return.");
        }

        Execute(1, 1, 0xCAFE_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)14, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The same Count=1 owner reuses the bounded shallow `(2,1)` arm.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 6; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(2, 1, 0xA55A_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xC0, bus.ReadByte(plane));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The transposed `(1,2)` arm is admitted after the third row is
        // present in the guest bitmap envelope.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 6; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(1, 2, 0xBEEF_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 4u));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The single-segment PolyDraw owner now reuses the bounded `(2,2)`
        // Draw arm when the guest map exposes the required third row.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 6; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(2, 2, 0xA55A_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 4u));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The single-segment PolyDraw owner also reuses the bounded `(3,1)`
        // Draw arm when the guest map exposes the exact two-row profile.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 6; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(3, 1, 0xA55A_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xE0, bus.ReadByte(plane));
        Assert.Equal((byte)0x10, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)3, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
