        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 6u));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The complementary Count=1 `(3,2)` arm reuses the shared Draw
        // selector with the repeated middle-row samples.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 3);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 6; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(3, 2, 0xBEEF_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x60, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x10, bus.ReadByte(plane + 4u));
        Assert.Equal((ushort)3, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)2, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // The equal Count=1 diagonal reuses the bounded `(3,3)` Draw arm
        // across the exact four-row bitmap envelope.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 8; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(3, 3, 0xCAFE_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x10, bus.ReadByte(plane + 6u));
        Assert.Equal((ushort)3, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Count=1 PolyDraw reuses the five-sample `(4,1)` Draw arm.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 8; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(4, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0xF0, bus.ReadByte(plane));
        Assert.Equal((byte)0x08, bus.ReadByte(plane + 2u));
        Assert.Equal((ushort)4, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)11, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Count=1 PolyDraw also reuses the transposed five-sample `(1,4)` arm.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 5);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 10; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(1, 4, 0xA55A_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 8u));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)4, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)11, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

