        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
