        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x80, bus.ReadByte(plane));
        Assert.Equal((byte)0x40, bus.ReadByte(plane + 2u));
        Assert.Equal((byte)0x20, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x10, bus.ReadByte(plane + 6u));
