        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)14, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(210,1)` reuses `(209,1)`'s complete clipped raster for one-segment
        // PolyDraw, with its own endpoint and phase thirteen.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(210, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x80, bus.ReadByte(plane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 14u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 29; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x7F, bus.ReadByte(plane + 29u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)210, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)13, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(211,1)` reuses Draw's complete clipped planar raster for the
        // one-segment PolyDraw path, while retaining its phase twelve.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(211, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xC0, bus.ReadByte(plane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 14u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 29; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x3F, bus.ReadByte(plane + 29u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)211, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)12, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(212,1)` reuses Draw's complete clipped planar envelope for the
        // one-segment PolyDraw path, including phase eleven.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 16);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 32; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(212, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xC0, bus.ReadByte(plane + 13u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 14u));
        Assert.Equal((byte)0x00, bus.ReadByte(plane + 15u));
        for (uint index = 16; index < 29; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x3F, bus.ReadByte(plane + 29u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((ushort)212, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)11, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(213,1)` reuses the exact seventeen-byte Draw body through the
        // guarded PolyDraw storage envelope. The write map remains the
        // shallow Bresenham result, including the non-contiguous row-one
        // tail caused by the y=1 rise after x=106.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(213, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xE0, bus.ReadByte(plane + 13u));
        for (uint index = 14; index < 30; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x1F, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)213, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)10, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(214,1)` uses its distinct terminal body and phase through the
        // same guarded 17-byte envelope. The clipped byte prefix is shared
        // with `(213,1)`, but the published endpoint/phase is not.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(214, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xE0, bus.ReadByte(plane + 13u));
        for (uint index = 14; index < 30; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x1F, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)214, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)9, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(215,1)` exposes both final-byte nibbles through its own direct
        // Draw body and publishes phase eight only after the full envelope
        // has been admitted.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(215, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        for (uint index = 0; index < 13; index++)
            Assert.Equal((byte)0xFF, bus.ReadByte(plane + index));
        Assert.Equal((byte)0xF0, bus.ReadByte(plane + 13u));
        for (uint index = 14; index < 30; index++)
            Assert.Equal((byte)0x00, bus.ReadByte(plane + index));
        Assert.Equal((byte)0x0F, bus.ReadByte(plane + 30u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 31u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 32u));
        Assert.Equal((byte)0xFF, bus.ReadByte(plane + 33u));
        Assert.Equal((ushort)215, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)8, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(216,1)` is the next 17-byte-row terminal form. It publishes the
        // endpoint only after the same full two-row envelope is admitted.
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 17);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(216, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)216, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(217,1)` advances the native shallow terminal family by one
        // sample while retaining the same validated 17-byte, two-row span.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(217, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)217, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)6, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(218,1)` is a separate terminal selector over the same bounded
        // 17-byte, two-row standard-planar envelope. It must claim this
        // exact endpoint and advance the classic line phase by 218 samples.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(218, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)218, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)5, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(219,1)` remains an independently selected 17-byte terminal
        // form. It differs only in its requested endpoint and resultant
        // line phase; all richer geometry must still fall through.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(219, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)219, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)4, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(220,1)` is the next independently selected terminal form over
        // the same complete standard-planar envelope.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(220, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)220, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)3, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(221,1)` completes the next terminal selector while retaining the
        // same complete standard-planar, two-row admission envelope.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(221, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)221, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)2, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(222,1)` must take the matching one-segment selector rather than
        // falling through once the Draw family advances.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(222, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)222, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)1, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // `(223,1)` is the next paired one-segment endpoint.
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
        bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 15, 0);
        for (uint index = 0; index < 34; index++)
            bus.WriteByte(plane + index, 0, 0);
        Execute(223, 1, 0xD00D_0001u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((ushort)223, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)1, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) & GraphicsLayouts.RastPortFirstDot);
        Assert.Equal((byte)0, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void NativeGraphicsDrawEllipseRadiusOneUsesAccurateM68000PlanarCardinals()
    {
        var nativeCode = NativeGraphicsRasterBodies.BuildCode(
            out var entryOffsets,
            out var fallbackEntryOffset);
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entryOffsets,
            fallbackEntryOffset);

        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });
        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];

        const uint rastPort = 0x00D0_0000;
        const uint bitMap = 0x00E3_0000;
        const uint plane = 0x00E4_0000;
        const uint stack = 0x00C0_0000;
        const uint returnAddress = 0x00F0_0000;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[0x40]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);

        void Execute(
            short x,
            short y,
            short radiusX,
            short radiusY,
            uint initialD0,
            uint? port = null)
        {
            bus.WriteLong(stack + 0x80u, returnAddress);
            cpu.Reset(
                codeBase + (uint)VectorOffset(GraphicsLvo.DrawEllipse),
                stack + 0x80u);
            cpu.State.A[1] = port ?? rastPort;
            cpu.State.D[0] = initialD0 | unchecked((ushort)x);
            cpu.State.D[1] = unchecked((ushort)y);
            cpu.State.D[2] = unchecked((ushort)radiusX);
            cpu.State.D[3] = unchecked((ushort)radiusY);
            cpu.ExecuteInstruction(); // vector JMP.L
            // The Draw selector now includes the extended storage-boundary
            // family; keep the execution envelope above the generated path.
            for (var index = 0; index < 2048; index++)
            {
                cpu.ExecuteInstruction();
                if (cpu.State.ProgramCounter == returnAddress)
                {
                    bus.WriteLong(stack + 0x80u, 0);
                    return;
                }
            }

            throw new InvalidOperationException("Native DrawEllipse body did not return.");
        }

        for (var offset = 0; offset < 0x20; offset++)
            bus.WriteByte(plane + (uint)offset, 0, 0);
        Execute(4, 4, 1, 1, 0xCAFE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x08, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x14, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)0x08, bus.ReadByte(plane + 10u));
        Assert.Equal((byte)0, bus.ReadByte(plane + 7u));
        Assert.Equal((byte)0, bus.ReadByte(plane + 9u));

        // The native equal-radius extension follows the portable integer
        // symmetry for radius two: a twelve-pixel outline over five rows.
        for (var offset = 0; offset < 0x20; offset++)
            bus.WriteByte(plane + (uint)offset, 0, 0);
        Execute(4, 4, 2, 2, 0xFACE_0000u);
        Assert.Equal(0u, cpu.State.D[0]);
        Assert.Equal((byte)0x1C, bus.ReadByte(plane + 4u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)0x22, bus.ReadByte(plane + 10u));
        Assert.Equal((byte)0x1C, bus.ReadByte(plane + 12u));

