        Execute(4, 4, 5, 1, 0xABCD_0000u);
        Assert.Equal(0xABCD_0004u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 10u));

        // Radius-Y-fourteen with a raster that cannot represent its full
        // outline remains on the shared fallback owner.
        Execute(4, 4, 1, 14, 0xABCD_0000u);
        Assert.Equal(0xABCD_0004u, cpu.State.D[0]);
        Assert.Equal((byte)0x5A, bus.ReadByte(plane + 6u));
        Assert.Equal((byte)0xA5, bus.ReadByte(plane + 8u));
        Assert.Equal((byte)0x3C, bus.ReadByte(plane + 10u));

        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        Execute(4, 4, 1, 1, 0xABCD_0000u);
        Assert.Equal(0xABCD_0004u, cpu.State.D[0]);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortLayer, 1, 0);
        Execute(4, 4, 1, 1, 0x1234_0000u);
        Assert.Equal(0x1234_0004u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsHunkBuilderRoutesExplicitPerVectorEntriesAndReservedFallback()
    {
        var nativeCode = new byte[0x20];
        nativeCode[0x04] = 0x70; // MOVEQ #$11,D0
        nativeCode[0x05] = 0x11;
        nativeCode[0x06] = 0x4E; // NOP
        nativeCode[0x07] = 0x71;
        nativeCode[0x08] = 0x70; // MOVEQ #$22,D0
        nativeCode[0x09] = 0x22;
        nativeCode[0x0A] = 0x4E; // NOP
        nativeCode[0x0B] = 0x71;
        nativeCode[0x0C] = 0x70; // MOVEQ #$33,D0 (reserved fallback)
        nativeCode[0x0D] = 0x33;
        nativeCode[0x0E] = 0x4E; // NOP
        nativeCode[0x0F] = 0x71;
        var entries = Enum.GetValues<GraphicsLvo>()
            .ToDictionary(vector => vector, _ => 0);
        entries[GraphicsLvo.InitRastPort] = 0x04;
        entries[GraphicsLvo.Text] = 0x08;
        const int fallbackEntryOffset = 0x0C;

        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            entries,
            fallbackEntryOffset);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });

        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        var residentBase = program.SegmentBases[1];
        var codeStart = codeBase + (uint)hunk.NativeCodeOffset;

        Assert.Equal(
            codeStart + 0x04u,
            bus.ReadLong(codeBase + (uint)VectorOffset(GraphicsLvo.InitRastPort) + 2u));
        Assert.Equal(
            codeStart + 0x08u,
            bus.ReadLong(codeBase + (uint)VectorOffset(GraphicsLvo.Text) + 2u));
        Assert.Equal(
            codeStart + (uint)fallbackEntryOffset,
            bus.ReadLong(codeBase + (uint)VectorOffset(-648) + 2u));

        Assert.Equal(
            codeStart + 0x04u,
            bus.ReadLong(residentBase + (uint)VectorArrayOffset(GraphicsLvo.InitRastPort)));
        Assert.Equal(
            codeStart + 0x08u,
            bus.ReadLong(residentBase + (uint)VectorArrayOffset(GraphicsLvo.Text)));
        Assert.Equal(
            codeStart + (uint)fallbackEntryOffset,
            bus.ReadLong(residentBase + (uint)VectorArrayOffset(-648)));

        const uint stackAddress = 0x00C0_0000;
        bus.MapWritableMemory(stackAddress, new byte[0x100]);
        using var cpu = AmigaM68kCoreFactory.Default.Create(
            M68kBackendKind.AccurateM68000,
            bus);
        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.InitRastPort),
            stackAddress);
        cpu.ExecuteInstruction(); // JMP.L -> native offset $04
        cpu.ExecuteInstruction(); // MOVEQ #$11,D0
        Assert.Equal(0x11u, cpu.State.D[0]);

        cpu.Reset(
            codeBase + (uint)VectorOffset(GraphicsLvo.Text),
            stackAddress);
        cpu.ExecuteInstruction(); // JMP.L -> native offset $08
        cpu.ExecuteInstruction(); // MOVEQ #$22,D0
        Assert.Equal(0x22u, cpu.State.D[0]);
    }

    [Fact]
    public void NativeGraphicsHunkBuilderRejectsMissingOrInvalidVectorEntryOffsets()
    {
        var nativeCode = new byte[0x10];
        var complete = Enum.GetValues<GraphicsLvo>()
            .ToDictionary(vector => vector, _ => 0);

        var missing = new Dictionary<GraphicsLvo, int>(complete);
        missing.Remove(GraphicsLvo.Text);
        Assert.Throws<ArgumentException>(() => NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            missing,
            fallbackEntryOffset: 0));

        var odd = new Dictionary<GraphicsLvo, int>(complete)
        {
            [GraphicsLvo.Text] = 1
        };
        Assert.Throws<ArgumentException>(() => NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            odd,
            fallbackEntryOffset: 0));

        Assert.Throws<ArgumentException>(() => NativeGraphicsLibraryHunkBuilder.Build(
            nativeCode,
            complete,
            fallbackEntryOffset: 0x10));
    }

    [Fact]
    public void NativeGraphicsHunkBuilderCanOptIntoTheFullGfxBaseEnvelope()
    {
        var hunk = NativeGraphicsLibraryHunkBuilder.Build(
            [0x70, 0x2A, 0x4E, 0x71],
            positiveImageSize: GraphicsLayouts.GfxBaseNativeSize);
        var bus = new AmigaBus();
        var nextAllocation = 0x0080_0000u;
        var loader = new AmigaHunkProgramLoader(
            bus,
            byteCount =>
            {
                var address = nextAllocation;
                nextAllocation += (uint)byteCount + 0x100u;
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            });

        var program = loader.Load(hunk.Bytes);
        var codeBase = program.SegmentBases[0];
        var residentBase = program.SegmentBases[1];
        var libraryBase = codeBase + (uint)NativeGraphicsLibraryImageBuilder.VectorTableSize;
        var list = libraryBase + (uint)GraphicsLayouts.GfxBaseMonitorList;

        Assert.Equal(GraphicsLayouts.GfxBaseNativeSize, hunk.NativeCodeOffset - NativeGraphicsLibraryImageBuilder.VectorTableSize);
        Assert.Equal(list + 4u, bus.ReadLong(libraryBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(0u, bus.ReadLong(libraryBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail));
        Assert.Equal(list, bus.ReadLong(libraryBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
        Assert.Equal((uint)GraphicsLayouts.GfxBaseNativeSize, bus.ReadLong(residentBase + 0x50));
    }

    private static int VectorOffset(GraphicsLvo vector)
        => VectorOffset((int)vector);

    private static int VectorOffset(int displacement)
        => NativeGraphicsLibraryImageBuilder.VectorTableSize + displacement;

    private static int VectorArrayOffset(GraphicsLvo vector)
        => VectorArrayOffset((int)vector);

    private static int VectorArrayOffset(int displacement)
        => 0x60 + (((displacement * -1) / NativeGraphicsLibraryImageBuilder.VectorStubSize - 1) * 4);

    private static ushort ReadImageWord(byte[] image, int offset)
        => (ushort)((image[offset] << 8) | image[offset + 1]);

    private static uint ReadImageLong(byte[] image, int offset)
        => ((uint)image[offset] << 24) | ((uint)image[offset + 1] << 16) | ((uint)image[offset + 2] << 8) | image[offset + 3];

