        var copyState = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 1011
        };
        Assert.False(adapter.TryInvoke(copyState, (int)GraphicsLvo.CopySBitMap));
        Assert.Equal(0x2468_ACE0u, copyState.D[0]);
        Assert.Equal(1011, copyState.Cycles);
        Assert.Empty(backend.Calls);
    }

    [Fact]
    public void LayerRomVectorsRejectOddLayerPointersBeforeProviderCallback()
    {
        var backend = new RecordingLayerBackend();
        var core = new GraphicsLibraryCore(
            new FakeMemory(0x1000),
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            backend);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        foreach (var vector in new[]
                 {
                     GraphicsLvo.LockLayerRom,
                     GraphicsLvo.AttemptLockLayerRom,
                     GraphicsLvo.UnlockLayerRom
                 })
        {
            var state = new M68kCpuState
            {
                A = { [5] = 0x121 },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 1777
            };

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(1777, state.Cycles);
        }

        foreach (var vector in new[] { GraphicsLvo.SyncSBitMap, GraphicsLvo.CopySBitMap })
        {
            var state = new M68kCpuState
            {
                A = { [0] = 0x121 },
                D = { [0] = 0x2468_ACE0u },
                Cycles = 1781
            };

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0x2468_ACE0u, state.D[0]);
            Assert.Equal(1781, state.Cycles);
        }

        core.LockLayerRom(0x121);
        Assert.False(core.AttemptLockLayerRom(0x121));
        core.UnlockLayerRom(0x121);
        Assert.False(core.SyncSBitMap(0x121));
        Assert.False(core.CopySBitMap(0x121));
        Assert.Empty(backend.Calls);
    }

    [Fact]
    public void HostSuperBitmapCallbacksDoNotSeeNullLayerHandles()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var hostMemory = new HostGuestMemory(machine.Bus);
        var calls = new List<string>();
        using var services = CreateHostGraphicsServices(
            hostMemory,
            syncSBitMap: address =>
            {
                calls.Add($"sync:{address:X}");
                return true;
            },
            copySBitMap: address =>
            {
                calls.Add($"copy:{address:X}");
                return true;
            });

        var syncState = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 1007
        };
        services.Invoke(syncState, (int)GraphicsLvo.SyncSBitMap);
        Assert.Equal(0x1357_9BDFu, syncState.D[0]);
        Assert.Equal(1007, syncState.Cycles);

        var copyState = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 1011
        };
        services.Invoke(copyState, (int)GraphicsLvo.CopySBitMap);
        Assert.Equal(0x2468_ACE0u, copyState.D[0]);
        Assert.Equal(1011, copyState.Cycles);
        Assert.Empty(calls);
    }

    [Fact]
    public void HostLayerCallbacksDoNotSeeOddLayerPointers()
    {
        var calls = new List<string>();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(new AmigaBus()),
            lockLayerRom: address => calls.Add($"lock:{address:X}"),
            attemptLockLayerRom: address =>
            {
                calls.Add($"try:{address:X}");
                return true;
            },
            unlockLayerRom: address => calls.Add($"unlock:{address:X}"),
            syncSBitMap: address =>
            {
                calls.Add($"sync:{address:X}");
                return true;
            },
            copySBitMap: address =>
            {
                calls.Add($"copy:{address:X}");
                return true;
            });

        foreach (var vector in new[]
                 {
                     GraphicsLvo.LockLayerRom,
                     GraphicsLvo.AttemptLockLayerRom,
                     GraphicsLvo.UnlockLayerRom
                 })
        {
            var state = new M68kCpuState
            {
                A = { [5] = 0x121 },
                D = { [0] = 0x89AB_CDEFu },
                Cycles = 1801
            };

            services.Invoke(state, (int)vector);
            Assert.Equal(0x89AB_CDEFu, state.D[0]);
            Assert.Equal(1801, state.Cycles);
        }

        foreach (var vector in new[] { GraphicsLvo.SyncSBitMap, GraphicsLvo.CopySBitMap })
        {
            var state = new M68kCpuState
            {
                A = { [0] = 0x121 },
                D = { [0] = 0x7654_3210u },
                Cycles = 1807
            };

            services.Invoke(state, (int)vector);
            Assert.Equal(0x7654_3210u, state.D[0]);
            Assert.Equal(1807, state.Cycles);
        }

        Assert.Empty(calls);
    }

    [Fact]
    public void HostLayerLockCallbacksOwnTheCopperStartLockBoundary()
    {
        var bus = new AmigaBus();
        var calls = new List<string>();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            lockLayerRom: address => calls.Add($"lock:{address:X}"),
            attemptLockLayerRom: address =>
            {
                calls.Add($"try:{address:X}");
                return address == 0x120;
            },
            unlockLayerRom: address => calls.Add($"unlock:{address:X}"));

        var lockState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x120 },
            D = { [0] = 0xFFFF_FFFFu }
        };
        services.Invoke(lockState, (int)GraphicsLvo.LockLayerRom);
        Assert.Equal(0u, lockState.D[0]);

        var tryState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x120 },
            D = { [0] = 0xFFFF_FFFFu }
        };
        services.Invoke(tryState, (int)GraphicsLvo.AttemptLockLayerRom);
        Assert.Equal(1u, tryState.D[0]);

        var rejectedState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x121 },
            D = { [0] = 0xFFFF_FFFFu }
        };
        services.Invoke(rejectedState, (int)GraphicsLvo.AttemptLockLayerRom);
        Assert.Equal(0xFFFF_FFFFu, rejectedState.D[0]);

        var unlockState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x120 },
            D = { [0] = 0xFFFF_FFFFu }
        };
        services.Invoke(unlockState, (int)GraphicsLvo.UnlockLayerRom);
        Assert.Equal(0u, unlockState.D[0]);

        Assert.Equal(
            new[] { "lock:120", "try:120", "unlock:120" },
            calls);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void MonitorViewPositionCorePreservesOwnershipAcrossAliasesAndMonitorClose(bool ntsc)
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay { IsNtsc = ntsc };
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), display);
        Assert.False(core.TrySetMonitorViewPosition(0, 8, 9));
        Assert.True(core.TrySetMonitorViewPosition(0x11000, 130, 46));
        Assert.True(core.TrySetMonitorViewPosition(0x21000, -2, 7));
        var monitor = AssertPosition(0x19000, 130, 46);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(monitor, core.OpenMonitor(0, 0x11000));
        Assert.Equal(0, core.CloseMonitor(monitor));
        Assert.Equal(monitor, AssertPosition(0x11000, 130, 46));
        Assert.True(core.TrySetMonitorViewPosition(0x11000, null, 43));
        Assert.Equal(monitor, AssertPosition(0x19020, 130, 43));
        AssertPosition(0x29000, -2, 7);
        AssertPosition(0, ntsc ? (short)130 : (short)-2, ntsc ? (short)43 : (short)7);
        display.IsNtsc = !ntsc;
        AssertPosition(0x8000, ntsc ? (short)-2 : (short)130, ntsc ? (short)7 : (short)43);

        var otherMemory = new FakeMemory(0x10000);
        var other = new GraphicsLibraryCore(otherMemory, new BitmapAllocator(), new FakeBlitter(), display);
        Assert.Equal(88, other.GetDisplayInfoData(0, 0x900, 88, 0x80002000, 0x11000));
        Assert.Equal((ushort)129, ReadWord(otherMemory, 0x914));
        Assert.Equal((ushort)44, ReadWord(otherMemory, 0x916));

        uint AssertPosition(uint mode, short x, short y)
        {
            Assert.Equal(88, core.GetDisplayInfoData(0, 0x900, 88, 0x80002000, mode));
            Assert.Equal(unchecked((ushort)x), ReadWord(memory, 0x914));
            Assert.Equal(unchecked((ushort)y), ReadWord(memory, 0x916));
            return ReadLong(memory, 0x910);
        }
    }

    [Fact]
    public void ColorMapStoresRgb4AndRgb32WithGuestCompatibleLayout()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        var colorMap = core.GetColorMap(4);
        Assert.NotEqual(0u, colorMap);
        Assert.Equal((byte)0x02, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapType));
        Assert.Equal((ushort)4, ReadWord(memory, colorMap + (uint)GraphicsLayouts.ColorMapCount));
        var colors = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        var lowColors = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits);
        Assert.NotEqual(0u, colors);
        Assert.NotEqual(0u, lowColors);
        Assert.Equal((ushort)0, ReadWord(memory, colors));
        Assert.Equal((ushort)0, ReadWord(memory, lowColors));

        Assert.True(core.SetRGB4CM(colorMap, 1, 0x0A, 0x05, 0x0F));
        Assert.Equal(0x0A5Fu, core.GetRGB4(colorMap, 1));
        Assert.True(core.SetRGB32CM(colorMap, 2, 0xAB000000, 0x34120000, 0xFF800000));
        Assert.Equal(0x0A3Fu, core.GetRGB4(colorMap, 2));

        // The top ColorTable nibble is reserved legacy state and survives
        // both CM setters while the RGB nibbles are replaced.
        Assert.True(memory.TryWriteWord(colors + 6, 0xB000));
        Assert.True(core.SetRGB4CM(colorMap, 3, 1, 2, 3));
        Assert.Equal(0xB123u, ReadWord(memory, colors + 6));
        Assert.True(core.SetRGB32CM(colorMap, 3, 0x4000_0000, 0x5000_0000, 0x6000_0000));
        Assert.Equal(0xB456u, ReadWord(memory, colors + 6));

        Assert.True(core.GetRGB32(colorMap, 1, 2, 0x900));
        Assert.Equal(0xA0A0_A0A0u, ReadLong(memory, 0x900));
        Assert.Equal(0x5050_5050u, ReadLong(memory, 0x904));
        Assert.Equal(0xF0F0_F0F0u, ReadLong(memory, 0x908));
        Assert.Equal(0xABAB_ABABu, ReadLong(memory, 0x90C));
        Assert.Equal(0x3434_3434u, ReadLong(memory, 0x910));
        Assert.Equal(0xFFFF_FFFFu, ReadLong(memory, 0x914));

        Assert.True(core.FreeColorMap(colorMap));
        Assert.Equal(3, allocator.Freed.Count);
        Assert.False(core.FreeColorMap(colorMap));
    }

    [Fact]
    public void GetRgb32ZeroCountIsANoOpWithoutAnOutputTable()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.NotEqual(0u, colorMap);

        // No RGB32 records are requested, so the output pointer is not part
        // of the native access envelope.  A zero table must remain a clean
        // success rather than an address-error/provider handoff.
        Assert.True(core.GetRGB32(colorMap, 0, 0, 0));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = 0 },
            D = { [0] = 0, [1] = 0, [2] = 0xCAFE_BABEu },
            Cycles = 173
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetRGB32));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0xCAFE_BABEu, state.D[2]);
        Assert.Equal(173, state.Cycles);
    }

