    [Fact]
    public void GetColorMapRestoresAllGuestEnvelopesWhenMapPublicationFails()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialLongWriteMemory(backing);
        var allocator = new SequenceAddressAllocator(0x1000, 0x1100, 0x1200);
        const uint map = 0x1000;
        const uint colors = 0x1100;
        const uint lowColors = 0x1200;

        for (var offset = 0; offset < GraphicsLayouts.ColorMapSize; offset++)
            Assert.True(backing.TryWriteByte(map + (uint)offset, (byte)(0xA0 + offset)));
        for (var offset = 0; offset < 4; offset++)
        {
            Assert.True(backing.TryWriteByte(colors + (uint)offset, (byte)(0xB0 + offset)));
            Assert.True(backing.TryWriteByte(lowColors + (uint)offset, (byte)(0xC0 + offset)));
        }

        memory.PartialLongAddress = map + (uint)GraphicsLayouts.ColorMapColorTable;
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        Assert.Equal(0u, core.GetColorMap(2));
        Assert.Equal(3, allocator.FreeCount);
        for (var offset = 0; offset < GraphicsLayouts.ColorMapSize; offset++)
            Assert.Equal((byte)(0xA0 + offset), ReadByte(backing, map + (uint)offset));
        for (var offset = 0; offset < 4; offset++)
        {
            Assert.Equal((byte)(0xB0 + offset), ReadByte(backing, colors + (uint)offset));
            Assert.Equal((byte)(0xC0 + offset), ReadByte(backing, lowColors + (uint)offset));
        }

        memory.PartialLongAddress = null;
        var retryAllocator = new SequenceAddressAllocator(map, colors, lowColors);
        var retryCore = new GraphicsLibraryCore(memory, retryAllocator, new FakeBlitter(), new FakeDisplay());
        Assert.Equal(map, retryCore.GetColorMap(2));
        Assert.True(retryCore.FreeColorMap(map));
        Assert.Equal(3, retryAllocator.FreeCount);
    }

    [Fact]
    public void AttachPalExtraRejectsOddViewportAndNativeEnvelopeAllocationsBeforePublishing()
    {
