        var oddEnvelopeCases = new[]
        {
            new[] { 0x1000u, 0x2000u, 0x3000u, 0x4001u, 0x5000u, 0x6000u },
            new[] { 0x1000u, 0x2000u, 0x3000u, 0x4000u, 0x5001u, 0x6000u },
