    [Fact]
    public void LoadRgbTablesPreserveReservedColorTableHighNibbles()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        const uint viewPort = 0x200;
        const uint rgb4 = 0x900;
        const uint rgb32 = 0xA00;
        var colors = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapColorTable);

        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap));
        Assert.True(memory.TryWriteWord(colors, 0xA000));
        Assert.True(memory.TryWriteWord(rgb4, 0x0123));
        Assert.True(core.LoadRGB4(viewPort, rgb4, 1));
        Assert.Equal(0xA123, ReadWord(memory, colors));

        Assert.True(memory.TryWriteWord(colors + 2, 0xB000));
        Assert.True(memory.TryWriteLong(rgb32, (1u << 16) | 1u));
        Assert.True(memory.TryWriteLong(rgb32 + 4, 0x4000_0000));
        Assert.True(memory.TryWriteLong(rgb32 + 8, 0x5000_0000));
        Assert.True(memory.TryWriteLong(rgb32 + 12, 0x6000_0000));
        Assert.True(memory.TryWriteLong(rgb32 + 16, 0));
        Assert.True(core.LoadRGB32(viewPort, rgb32));
        Assert.Equal(0xB456, ReadWord(memory, colors + 2));
    }

    [Fact]
    public void Rgb32PalettePublicationUsesExactTimedRgb8WhenTheDisplaySupportsIt()
    {
        var memory = new FakeMemory(0x10000);
        var display = new Rgb32PaletteDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            display);
        var colorMap = core.GetColorMap(2);
        const uint viewPort = 0x200;
        const uint table = 0x900;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));

        Assert.True(core.SetRGB32(
            viewPort,
            1,
            0xABCD_0000,
            0x1234_0000,
            0xFEDC_0000,
            cycle: 457));
        Assert.Collection(
            display.Updates,
            update => Assert.Equal(
                (viewPort, 1u, (byte)0xAB, (byte)0x12, (byte)0xFE, 457L),
                update));
        Assert.Equal(0xA1Fu, core.GetRGB4(colorMap, 1));

        Assert.True(memory.TryWriteLong(table, (2u << 16) | 0u));
        Assert.True(memory.TryWriteLong(table + 4, 0x1020_0000));
        Assert.True(memory.TryWriteLong(table + 8, 0x3040_0000));
        Assert.True(memory.TryWriteLong(table + 12, 0x5060_0000));
        Assert.True(memory.TryWriteLong(table + 16, 0x7080_0000));
        Assert.True(memory.TryWriteLong(table + 20, 0x90A0_0000));
        Assert.True(memory.TryWriteLong(table + 24, 0xB0C0_0000));
        Assert.True(memory.TryWriteLong(table + 28, 0));

        Assert.True(core.LoadRGB32(viewPort, table, cycle: 463));
        Assert.Equal(3, display.Updates.Count);
        Assert.Equal(
            (viewPort, 0u, (byte)0x10, (byte)0x30, (byte)0x50, 463L),
            display.Updates[1]);
        Assert.Equal(
            (viewPort, 1u, (byte)0x70, (byte)0x90, (byte)0xB0, 463L),
            display.Updates[2]);
        Assert.Equal(0x135u, core.GetRGB4(colorMap, 0));
        Assert.Equal(0x79Bu, core.GetRGB4(colorMap, 1));
    }

    [Fact]
    public async Task ViewPortPaletteCallbacksSerializeOnTheOwnedColorMapLock()
    {
        var memory = new FakeMemory(0x10000);
        var display = new BlockingPaletteDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            display);
        var colorMap = core.GetColorMap(1);
        const uint viewPort = 0x200;
        const uint colors = 0x900;

        Assert.NotEqual(0u, colorMap);
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        Assert.True(memory.TryWriteWord(colors, 0x0123));

        var first = Task.Run(() => core.LoadRGB4(viewPort, colors, 1));
        Assert.True(display.FirstEntered.Wait(TimeSpan.FromSeconds(5)));

        var secondStarted = new ManualResetEventSlim();
        var second = Task.Run(() =>
        {
            secondStarted.Set();
            return core.LoadRGB4(viewPort, colors, 1);
        });
        Assert.True(secondStarted.Wait(TimeSpan.FromSeconds(5)));

        // The second operation may be scheduled, but it cannot enter the
        // host callback until the first operation releases the ColorMap lock.
        Assert.False(display.SecondEntered.Wait(TimeSpan.FromMilliseconds(500)));
        Assert.Equal(1, Volatile.Read(ref display.MaxActive));

        display.Release.Set();
        var results = await Task.WhenAll(first, second);
        Assert.All(results, Assert.True);
        Assert.Equal(2, Volatile.Read(ref display.CallCount));
        Assert.Equal(1, Volatile.Read(ref display.MaxActive));
    }

    [Fact]
    public void GetRgb32RestoresTheOutputTableWhenALaterEntryWriteFails()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new FailingByteWriteMemory(backing);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        const uint table = 0x900;

        for (var offset = 0; offset < 24; offset++)
            Assert.True(backing.TryWriteByte(table + (uint)offset, 0xCC));

        // One RGB32 entry publishes twelve bytes.  Fail at the first byte of
        // the second entry, then allow the rollback writes to complete.
        memory.FailOnNextByteWrite(13);
        Assert.False(core.GetRGB32(colorMap, 0, 2, table));

        for (var offset = 0; offset < 24; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, table + (uint)offset));
    }

    [Fact]
    public void Rgb32TablesRejectOddLongwordPointersBeforeGuestAccess()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display, new BitmapAllocator());
        var colorMap = core.GetColorMap(1);
        const uint viewPort = 0x200;
        const uint oddTable = 0x901;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        for (var offset = 0; offset < 16; offset++)
            Assert.True(memory.TryWriteByte(oddTable + (uint)offset, 0xA5));

        Assert.False(core.GetRGB32(colorMap, 0, 1, oddTable));
        Assert.False(core.LoadRGB32(viewPort, oddTable));
        for (var offset = 0; offset < 16; offset++)
            Assert.Equal((byte)0xA5, ReadByte(memory, oddTable + (uint)offset));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var get = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = oddTable },
            D = { [0] = 0, [1] = 1, [2] = 0xDEAD_BEEFu },
            Cycles = 137
        };
        Assert.False(adapter.TryInvoke(get, (int)GraphicsLvo.GetRGB32));
        Assert.Equal(0u, get.D[0]);
        Assert.Equal(0xDEAD_BEEFu, get.D[2]);
        Assert.Equal(137, get.Cycles);

        var load = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = oddTable },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 139
        };
        Assert.False(adapter.TryInvoke(load, (int)GraphicsLvo.LoadRGB32));
        Assert.Equal(0x1357_9BDFu, load.D[0]);
        Assert.Equal(139, load.Cycles);
        Assert.Equal(0u, display.LoadedViewPort);
    }

    [Fact]
    public void LoadRgb4RejectsAnOddWordTableBeforeGuestAccess()
    {
