    [Fact]
    public void LoadRgb4RestoresEarlierColorMapEntriesWhenALaterWriteFails()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new FailingByteWriteMemory(backing);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display, new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint viewPort = 0x200;
        const uint colors = 0x900;

        Assert.True(backing.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        Assert.True(core.SetRGB4CM(colorMap, 0, 1, 2, 3));
        Assert.True(core.SetRGB4CM(colorMap, 1, 4, 5, 6));
        Assert.True(backing.TryWriteWord(colors, 0x0ABC));
        Assert.True(backing.TryWriteWord(colors + 2, 0x0123));

        // Entry zero consumes four byte writes.  Fail at entry one's first
        // byte, then allow the complete map rollback to finish.
        memory.FailOnNextByteWrite(5);
        Assert.False(core.LoadRGB4(viewPort, colors, 2));
        Assert.Equal(0x123u, core.GetRGB4(colorMap, 0));
        Assert.Equal(0x456u, core.GetRGB4(colorMap, 1));
        Assert.Equal(0u, display.LoadedViewPort);
    }

    [Fact]
    public void LoadRgb32StagesAllRecordsBeforeColorMapAndDisplayPublication()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new FailingByteWriteMemory(backing);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display, new BitmapAllocator());
        var colorMap = core.GetColorMap(4);
        const uint viewPort = 0x200;
        const uint table = 0xA00;

        Assert.True(backing.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        Assert.True(core.SetRGB4CM(colorMap, 2, 1, 2, 3));
        Assert.True(core.SetRGB4CM(colorMap, 3, 4, 5, 6));

        // Two interleaved RGB32 records, starting at ColorMap entry two,
        // followed by the required zero-count terminator.
        Assert.True(backing.TryWriteLong(table, (2u << 16) | 2u));
        Assert.True(backing.TryWriteLong(table + 4, 0xFF00_0000));
        Assert.True(backing.TryWriteLong(table + 8, 0x1000_0000));
        Assert.True(backing.TryWriteLong(table + 12, 0x2000_0000));
        Assert.True(backing.TryWriteLong(table + 16, 0x3000_0000));
        Assert.True(backing.TryWriteLong(table + 20, 0x4000_0000));
        Assert.True(backing.TryWriteLong(table + 24, 0x5000_0000));
        Assert.True(backing.TryWriteLong(table + 28, 0));

        // Entry two consumes four byte writes.  A failure on entry three must
        // leave both ColorMap entries unchanged and must not call SetRgb4.
        memory.FailOnNextByteWrite(5);
        Assert.False(core.LoadRGB32(viewPort, table));
        Assert.Equal(0x123u, core.GetRGB4(colorMap, 2));
        Assert.Equal(0x456u, core.GetRGB4(colorMap, 3));
        Assert.Equal((short)0, display.SetIndex);
    }

