    [Fact]
    public void LoadRgb32DoesNotPublishEarlierRecordsWhenTheTerminatorIsMalformed()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display, new BitmapAllocator());
        var colorMap = core.GetColorMap(1);
        const uint viewPort = 0x200;
        const uint table = 0x1FF0;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        Assert.True(core.SetRGB4CM(colorMap, 0, 1, 2, 3));
        Assert.True(memory.TryWriteLong(table, 1u << 16));
        Assert.True(memory.TryWriteLong(table + 4, 0xFF00_0000));
        Assert.True(memory.TryWriteLong(table + 8, 0x1000_0000));
        Assert.True(memory.TryWriteLong(table + 12, 0x2000_0000));

        // The valid record ends exactly at the guest-memory boundary, so the
        // required zero-count descriptor cannot be read.  No earlier record
        // may reach ColorMap storage or the display callback.
        Assert.False(core.LoadRGB32(viewPort, table));
        Assert.Equal(0x123u, core.GetRGB4(colorMap, 0));
        Assert.Equal((short)0, display.SetIndex);
    }

    [Fact]
    public void VideoControlDoesNotApplyEarlierTagsWhenALaterContinuationIsMalformed()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint tags = 0x900;
        const uint malformedContinuation = 0x1FFC;

        Assert.True(memory.TryWriteLong(
            tags,
            0x8000_000A)); // VTAG_CHROMA_PLANE_SET
        Assert.True(memory.TryWriteLong(tags + 4, 7));
        Assert.True(memory.TryWriteLong(tags + 8, 2)); // TAG_MORE
        Assert.True(memory.TryWriteLong(tags + 12, malformedContinuation));
        Assert.True(memory.TryWriteLong(malformedContinuation, 0x8000_000A));

        // The first tag is valid, but the continuation contains only a tag
        // word; its data word is outside guest memory.  Precollection must
        // fail before the earlier transparency-plane write is published.
        Assert.False(core.VideoControl(colorMap, tags));
        Assert.Equal((byte)0, ReadByte(
            memory,
            colorMap + (uint)GraphicsLayouts.ColorMapTransparencyPlane));
    }

    [Fact]
    public void VideoControlTagsAcceptTheFinalGuestItemAndRejectImplicitWrap()
    {
        var memory = new WrappingMemory();
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint tags = 0xFFFF_FFF8u;

        // BitmapAllocator returns the ColorMap and its two short tables from
        // the 0x1000 range.  WrappingMemory is sparse, so make that complete
        // guest envelope readable before the portable allocation claims it.
        for (var address = 0x1000u; address < 0x1100u; address++)
            memory.WriteByte(address, 0);

        var colorMap = core.GetColorMap(3);
        Assert.NotEqual(0u, colorMap);

        // A terminal TagItem at the final aligned guest address is complete
        // and must remain a valid no-op VideoControl request.
        memory.WriteLong(tags, 0);
        memory.WriteLong(tags + 4u, 0);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 401
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(401, state.Cycles);

        // A normal item at the same address cannot continue through a low
        // alias after cursor + 8 wraps.  Map that alias to TAG_END so a
        // permissive host memory adapter would otherwise accept the list;
        // the parser must decline before mutating the ColorMap.
        memory.WriteLong(0, 0);
        memory.WriteLong(tags, 0x8000_000A); // VTAG_CHROMA_PLANE_SET
        memory.WriteLong(tags + 4u, 7);
        state.D[0] = 0x1357_9BDFu;
        state.Cycles = 409;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(409, state.Cycles);
        Assert.Equal(
            (byte)0,
            ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapTransparencyPlane));
        Assert.False(core.IsNativeOverlayVideoControlSafe(tags));
    }

    [Fact]
    public void VideoControlHonorsTagSkipBeforeApplyingTheFollowingCommand()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint tags = 0x900;

        WriteTag(memory, tags, 3, 1); // TAG_SKIP: skip one command.
        WriteTag(memory, tags + 8, 0x8000_0001, 0); // skipped CHROMAKEY_SET.
        WriteTag(memory, tags + 16, 0x8000_0003, 1); // BITPLANEKEY_SET.
        WriteTag(memory, tags + 24, 0, 0);

        Assert.True(core.VideoControl(colorMap, tags));
        Assert.Equal(
            0x02u,
            (uint)(ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags) & 0x02));

        // The same valid chain remains claimed through the CopperStart
        // register gateway and retains the command's published state.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 213
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(213, state.Cycles);
    }

    [Fact]
    public void VideoControlPreflightsExternalQueryOutputsBeforeApplyingEarlierSetters()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint tags = 0x900;

        Assert.True(memory.TryWriteLong(tags, 0x8000_000A)); // CHROMA_PLANE_SET
        Assert.True(memory.TryWriteLong(tags + 4, 7));
        Assert.True(memory.TryWriteLong(tags + 8, 0x8000_0083)); // VC_NoColorPaletteLoad_Query
        Assert.True(memory.TryWriteLong(tags + 12, 0x1FFE)); // four-byte output crosses the end
        Assert.True(memory.TryWriteLong(tags + 16, 0));

        Assert.False(core.VideoControl(colorMap, tags));
        Assert.Equal((byte)0, ReadByte(
            memory,
            colorMap + (uint)GraphicsLayouts.ColorMapTransparencyPlane));
    }

    [Fact]
    public void VideoControlRewritesGetterTagItemsWithTheQueriedValue()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(4);
        const uint tags = 0x900;

        // Establish two values, then query them with the classic in-place
        // GET ABI.  The data words are not output pointers: VideoControl must
        // replace each TagItem with its SET/CLR form and its scalar value.
        Assert.True(memory.TryWriteLong(tags, 0x8000_0005)); // BORDERBLANK_SET
        Assert.True(memory.TryWriteLong(tags + 4, 1));
        Assert.True(memory.TryWriteLong(tags + 8, 0x8000_002A)); // PF1_BASE_SET
        Assert.True(memory.TryWriteLong(tags + 12, 0x1234));
        Assert.True(memory.TryWriteLong(tags + 16, 0));
        Assert.True(core.VideoControl(colorMap, tags));

        Assert.True(memory.TryWriteLong(tags, 0x8000_0017)); // BORDERBLANK_GET
        Assert.True(memory.TryWriteLong(tags + 4, 0));
        Assert.True(memory.TryWriteLong(tags + 8, 0x8000_0026)); // PF1_BASE_GET
        Assert.True(memory.TryWriteLong(tags + 12, 0));
        Assert.True(memory.TryWriteLong(tags + 16, 0));

        Assert.True(core.VideoControl(colorMap, tags));
        Assert.Equal(0x8000_0005u, ReadLong(memory, tags));
        Assert.Equal(1u, ReadLong(memory, tags + 4));
        Assert.Equal(0x8000_002Au, ReadLong(memory, tags + 8));
        Assert.Equal(0x1234u, ReadLong(memory, tags + 12));
    }

    [Fact]
    public void VideoControlRollsBackInPlaceGetterRewritesWhenALaterTagFails()
