    [Fact]
    public void VideoControlCommitsAllGuestWritesAtomicallyOnLateMemoryFailure()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint tags = 0x900;

        Assert.True(backing.TryWriteLong(tags, 0x8000_000A)); // CHROMA_PLANE_SET
        Assert.True(backing.TryWriteLong(tags + 4, 7));
        Assert.True(backing.TryWriteLong(tags + 8, 0x8000_0005)); // BORDER_BLANK_SET
        Assert.True(backing.TryWriteLong(tags + 12, 1));
        Assert.True(backing.TryWriteLong(tags + 16, 0));

        // Let the first staged byte publish, then reject the next commit
        // byte.  The transaction must restore the first write as well.
        memory.FailOnNextByteWrite(2);
        Assert.False(core.VideoControl(colorMap, tags));
        Assert.Equal(
            (byte)0,
            ReadByte(backing, colorMap + (uint)GraphicsLayouts.ColorMapTransparencyPlane));
        Assert.Equal((byte)0, ReadByte(backing, colorMap + (uint)GraphicsLayouts.ColorMapFlags));
    }

    [Fact]
    public void AttachPalExtraRestoresAllocatedEnvelopesWhenTheFinalLinkWriteIsPartial()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialLongWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(4);
        const uint viewPort = 0x400;
        const uint originalPaletteExtra = 0xCAFE_BABEu;
        var paletteExtraField = colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra;

        Assert.True(backing.TryWriteLong(paletteExtraField, originalPaletteExtra));
        memory.PartialLongAddress = paletteExtraField;
        Assert.Equal(1, core.AttachPalExtra(colorMap, viewPort));
        Assert.Equal(originalPaletteExtra, ReadLong(backing, paletteExtraField));
        Assert.Equal(3, allocator.Freed.Count);

        memory.PartialLongAddress = null;
        Assert.Equal(0, core.AttachPalExtra(colorMap, viewPort));
        Assert.NotEqual(0u, ReadLong(backing, paletteExtraField));
        Assert.True(core.FreeColorMap(colorMap));
        Assert.Equal(9, allocator.Freed.Count);
    }

    [Fact]
    public void AttachPalExtraAllocatesAndPublishesTheGuestPaletteSharingEnvelope()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(4);
        const uint viewPort = 0x400;

        Assert.Equal(0, core.AttachPalExtra(colorMap, viewPort));
        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        Assert.NotEqual(0u, extra);
        Assert.Equal(
            (byte)15,
            ReadByte(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreNodeType));
        Assert.Equal(
            extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreWaitQueue + 4,
            ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreWaitQueue));
        Assert.Equal(
            0u,
            ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreWaitQueue + 4));
        Assert.Equal(
            extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreWaitQueue,
            ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreWaitQueue + 8));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreNestCount));
        Assert.Equal(
            0u,
            ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreOwner));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreQueueCount));
        Assert.Equal((ushort)3, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)4, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
        Assert.Equal((ushort)0, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNShared));
        Assert.NotEqual(0u, ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraRefCount));
        Assert.NotEqual(0u, ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraAllocList));
        Assert.Equal(viewPort, ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraViewPort));
        Assert.Equal((ushort)3, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraSharableColors));

        var refCount = ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraRefCount);
        var allocList = ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraAllocList);
        var shared = core.ObtainPen(colorMap, uint.MaxValue, 0xFFFF_FFFF, 0, 0, 0);
        Assert.Equal(3, shared);
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)3, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.Equal((ushort)3, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNShared));
        Assert.Equal((ushort)1, ReadWord(memory, refCount + 6));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, allocList + 6));

        var exclusive = core.ObtainPen(colorMap, 1, 0, 0xFFFF_FFFF, 0, 1);
        Assert.Equal(1, exclusive);
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.Equal((ushort)3, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNShared));
        Assert.Equal((ushort)0, ReadWord(memory, refCount + 2));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, allocList + 2));
        Assert.True(core.ReleasePen(colorMap, (uint)shared));
        Assert.True(core.ReleasePen(colorMap, (uint)exclusive));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)4, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.Equal((ushort)0, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNShared));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));

        // Attaching the same viewport is idempotent; a different association
        // is rejected rather than leaking a second private palette envelope.
        Assert.Equal(0, core.AttachPalExtra(colorMap, viewPort));
        Assert.Equal(1, core.AttachPalExtra(colorMap, 0x500));

        var secondMap = core.GetColorMap(2);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { A = { [0] = secondMap, [1] = viewPort } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AttachPalExtra));
        Assert.Equal(0u, state.D[0]);
        Assert.NotEqual(0u, ReadLong(memory, secondMap + (uint)GraphicsLayouts.ColorMapPaletteExtra));
        Assert.True(core.FreeColorMap(secondMap));

        Assert.True(core.FreeColorMap(colorMap));
        Assert.Equal(12, allocator.Freed.Count);
    }

    [Fact]
    public void PaletteExtraPublishesLifoFreeAndSharedListTransitions()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(4);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var allocList = ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraAllocList);

        Assert.Equal(1, core.ObtainPen(colorMap, 1, 0x1000_0000, 0, 0, 0));
        Assert.Equal((ushort)3, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, allocList + 2));

        Assert.Equal(2, core.ObtainPen(colorMap, 2, 0x2000_0000, 0, 0, 0));
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
        Assert.Equal((ushort)1, ReadWord(memory, allocList + 4));

        Assert.True(core.ReleasePen(colorMap, 1));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
        Assert.Equal((ushort)3, ReadWord(memory, allocList + 2));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, allocList + 4));

        Assert.True(core.ReleasePen(colorMap, 2));
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstFree));
        Assert.Equal((ushort)4, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
    }

    [Fact]
    public void ObtainPenAnyUsesFreeHeadAndSharedHeadOrder()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(3);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        // Explicit claims build a shared list 1 -> 0.  An any-entry request
        // must match the list head, not the lowest numeric duplicate.
        Assert.Equal(0, core.ObtainPen(colorMap, 0, 0x2200_0000, 0, 0, 0));
        Assert.Equal(1, core.ObtainPen(colorMap, 1, 0x2200_0000, 0, 0, 0));
        Assert.Equal(1, core.ObtainPen(colorMap, uint.MaxValue, 0x2200_0000, 0, 0, 0));

        Assert.True(core.ReleasePen(colorMap, 1));
        Assert.True(core.ReleasePen(colorMap, 1));
        Assert.True(core.ReleasePen(colorMap, 0));
    }

    [Fact]
    public void AttachPalExtraLimitsSharableEntriesToViewportPlanarDepth()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(16);
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3);

        Assert.Equal(0, core.AttachPalExtra(colorMap, viewPort));
        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        Assert.Equal((ushort)7, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraSharableColors));

        Assert.Equal(-1, core.ObtainPen(colorMap, 8, 0, 0, 0, 0));
        var exclusive = core.ObtainPen(colorMap, 8, 0, 0, 0, 1);
        Assert.Equal(8, exclusive);
        Assert.True(core.SetRGB4CM(colorMap, 8, 0x0F, 0, 0));
        Assert.Equal(0, core.FindColor(colorMap, 0xF000_0000, 0, 0, -1));
        Assert.Equal(8, core.FindColor(colorMap, 0xF000_0000, 0, 0, 15));
        Assert.True(core.ReleasePen(colorMap, (uint)exclusive));
        Assert.True(core.FreeColorMap(colorMap));
    }

    [Fact]
    public void FindColorTreatsOnlyAllOnesMaxPenAsTheSharableSentinel()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(16);
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3);

        Assert.Equal(0, core.AttachPalExtra(colorMap, viewPort));
        Assert.True(core.SetRGB4CM(colorMap, 8, 0x0F, 0, 0));

        // FindColor receives an ULONG maxpen.  Only 0xFFFFFFFF selects the
        // PaletteExtra sharable span; other high-bit values clamp to the
        // complete ColorMap and may see sprite/pointer entries.
        Assert.Equal(0, core.FindColor(colorMap, 0xF000_0000, 0, 0, -1));
        Assert.Equal(8, core.FindColor(colorMap, 0xF000_0000, 0, 0, -2));
        Assert.Equal(8, core.FindColor(colorMap, 0xF000_0000, 0, 0, int.MinValue));
    }

    [Fact]
    public void FindColorIgnoresLegacyV12LowNibblesAcrossCoreAndRegisterDispatch()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        var colorTable = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        var lowColorBits = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits);

        // Both entries have the same V1.2 high-nibble red.  In a V36/V39
        // map entry 1 is the exact 8-bit match, while a V1.2 map must ignore
        // the extension table and retain entry 0 on the native tie.
        memory.TryWriteWord(colorTable, 0x0F00);
        memory.TryWriteWord(lowColorBits, 0x000F);
        memory.TryWriteWord(colorTable + 2, 0x0F00);
        memory.TryWriteWord(lowColorBits + 2, 0x0F00);
        Assert.Equal(1, core.FindColor(colorMap, 0xFF00_0000, 0, 0, 1));

        Assert.True(memory.TryWriteByte(
            colorMap + (uint)GraphicsLayouts.ColorMapType,
            0));
        Assert.Equal(0, core.FindColor(colorMap, 0xFF00_0000, 0, 0, 1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0xCAFE_BABEu, [1] = 0xFF00_0000u, [2] = 0, [3] = 0, [4] = 1 },
            Cycles = 977
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FindColor));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(977, state.Cycles);
    }

    [Fact]
    public void LegacyV12RgbOperationsIgnoreAndPreserveLowColorBits()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(1);
        var colorTable = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        var lowColorBits = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits);
        const uint rgb32 = 0x2000;

        memory.TryWriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0);
        memory.TryWriteWord(colorTable, 0xA123);
        memory.TryWriteWord(lowColorBits, 0x0ABC);

        Assert.True(core.GetRGB32(colorMap, 0, 1, rgb32));
        Assert.Equal(0x1010_1010u, ReadLong(memory, rgb32));
        Assert.Equal(0x2020_2020u, ReadLong(memory, rgb32 + 4));
        Assert.Equal(0x3030_3030u, ReadLong(memory, rgb32 + 8));

        Assert.True(core.SetRGB4CM(colorMap, 0, 0x0F, 0x0E, 0x0D));
        Assert.Equal((ushort)0xAFED, ReadWord(memory, colorTable));
        Assert.Equal((ushort)0x0ABC, ReadWord(memory, lowColorBits));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0, [1] = 0x1200_0000u, [2] = 0x3400_0000u, [3] = 0x5600_0000u },
            Cycles = 983
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetRGB32CM));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(983, state.Cycles);
        Assert.Equal((ushort)0xA135, ReadWord(memory, colorTable));
        Assert.Equal((ushort)0x0ABC, ReadWord(memory, lowColorBits));
    }

    [Fact]
    public void ColorMapViewportAndRgb32TableOperationsUsePortableGateway()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), display);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var viewPort = 0x200u;
        var colorMap = InvokeGetColorMap(adapter, 4);
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap));

        Assert.True(memory.TryWriteWord(0x800, 0x0123));
        Assert.True(memory.TryWriteWord(0x802, 0x0ABC));
        var load = new M68kCpuState { A = { [0] = viewPort, [1] = 0x800 }, D = { [0] = 2 } };
        load.Cycles = 123;
        Assert.True(adapter.TryInvoke(load, (int)GraphicsLvo.LoadRGB4));
        Assert.Equal(0x123u, core.GetRGB4(colorMap, 0));
        Assert.Equal(0xABCu, core.GetRGB4(colorMap, 1));
        Assert.Equal(viewPort, display.LoadedViewPort);
        Assert.Equal((short)2, display.LoadedCount);
        Assert.Equal(123, display.LoadedCycle);

        var set = new M68kCpuState { A = { [0] = viewPort }, D = { [0] = 2, [1] = 0x0F, [2] = 0x01, [3] = 0x08 } };
        set.Cycles = 234;
        Assert.True(adapter.TryInvoke(set, (int)GraphicsLvo.SetRGB4));
        Assert.Equal(0xF18u, core.GetRGB4(colorMap, 2));
        Assert.Equal((short)2, display.SetIndex);
        Assert.Equal(234, display.SetCycle);

        Assert.True(memory.TryWriteLong(0x900, (1u << 16) | 3u));
        Assert.True(memory.TryWriteLong(0x904, 0xFFFFFFFF));
        Assert.True(memory.TryWriteLong(0x908, 0x80000000));
        Assert.True(memory.TryWriteLong(0x90C, 0));
        Assert.True(memory.TryWriteLong(0x910, 0));
        var load32 = new M68kCpuState { A = { [0] = viewPort, [1] = 0x900 } };
        load32.Cycles = 345;
        Assert.True(adapter.TryInvoke(load32, (int)GraphicsLvo.LoadRGB32));
        Assert.Equal(0xF80u, core.GetRGB4(colorMap, 3));
        Assert.Equal(345, display.SetCycle);

        var set32 = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 1, [1] = 0x12000000, [2] = 0x34000000, [3] = 0x56000000 } };
        set32.Cycles = 456;
        Assert.True(adapter.TryInvoke(set32, (int)GraphicsLvo.SetRGB32CM));
        var get32 = new M68kCpuState { A = { [0] = colorMap, [1] = 0x980 }, D = { [0] = 1, [1] = 1 } };
        Assert.True(adapter.TryInvoke(get32, (int)GraphicsLvo.GetRGB32));
        Assert.Equal(0x1212_1212u, ReadLong(memory, 0x980));
        Assert.Equal(0x3434_3434u, ReadLong(memory, 0x984));
        Assert.Equal(0x5656_5656u, ReadLong(memory, 0x988));
    }

