    [Fact]
    public void PaletteViewportAcceptsAColorMapLongwordEndingAtGuestMaximum()
    {
        var memory = new WrappingMemory();
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            display);
        const uint viewPort = 0xFFFF_FFF8;
        var colorMap = core.GetColorMap(3);
        Assert.NotEqual(0u, colorMap);
        memory.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap);

        // vp_ColorMap is at offset 4, so this even base ends the public
        // longword exactly at $FFFFFFFF.  It is valid guest memory despite
        // the unrelated ViewPort tail lying beyond the 32-bit envelope.
        Assert.True(core.IsOwnedViewPortColorMap(viewPort));
        Assert.True(core.SetRGB4(viewPort, 1, 0x0F, 0x02, 0x01));
        Assert.Equal(0xF21u, core.GetRGB4(colorMap, 1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 2, [1] = 0x01, [2] = 0x0E, [3] = 0x07 },
            Cycles = 611
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetRGB4, nativeOverlay: true));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(611, state.Cycles);
        Assert.Equal(0x1E7u, core.GetRGB4(colorMap, 2));
    }

