    [Fact]
    public void ObtainPenRestoresPaletteSidecarsAfterAPartialSyncWrite()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new FailingByteWriteMemory(backing);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(3);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        var paletteExtra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var refCount = ReadLong(memory, paletteExtra + (uint)GraphicsLayouts.PaletteExtraRefCount);
        var allocationList = ReadLong(memory, paletteExtra + (uint)GraphicsLayouts.PaletteExtraAllocList);
        var originalPaletteExtra = ReadBytes(
            memory,
            paletteExtra,
            (uint)GraphicsLayouts.PaletteExtraSize);
        var originalRefCount = ReadBytes(memory, refCount, 6);
        var originalAllocationList = ReadBytes(memory, allocationList, 6);

        // PEN_NO_SETCOLOR routes the operation directly to SyncPaletteExtra.
        // Fail on its second byte write so the first byte of FirstFree is
        // published before the adapter rejects the WORD.  The transactional
        // sync must restore the complete guest envelope and leave the host
        // shadow available for a clean retry.
        memory.FailOnNextByteWrite(2);
        Assert.Equal(
            -1,
            core.ObtainPen(
                colorMap,
                1,
                0xA000_0000,
                0x2000_0000,
                0x3000_0000,
                2));
        Assert.Equal(
            originalPaletteExtra,
            ReadBytes(memory, paletteExtra, (uint)GraphicsLayouts.PaletteExtraSize));
        Assert.Equal(originalRefCount, ReadBytes(memory, refCount, 6));
        Assert.Equal(originalAllocationList, ReadBytes(memory, allocationList, 6));

        Assert.Equal(
            1,
            core.ObtainPen(
                colorMap,
                1,
                0xA000_0000,
                0x2000_0000,
                0x3000_0000,
                2));
        Assert.True(core.ReleasePen(colorMap, 1));
    }

