    [Fact]
    public void PalettePenOperationsDeclineCorruptedPrivateSidecarPointers()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var refCount = ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraRefCount);
        Assert.NotEqual(0u, refCount);
        Assert.True(memory.TryWriteLong(
            extra + (uint)GraphicsLayouts.PaletteExtraRefCount,
            refCount + 2));

        // A private pointer no longer owned by the allocation is a native
        // sidecar boundary, not an empty free-pen result.  No ColorMap word,
        // list head, or ref-count state may be changed before fallback.
        Assert.Equal(-1, core.ObtainPen(colorMap, uint.MaxValue, 0xA000_0000, 0, 0, 0));
        Assert.Equal(0u, core.GetRGB4(colorMap, 0));
        Assert.Equal(refCount + 2, ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraRefCount));
        Assert.Equal((ushort)2, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraFirstShared));
    }

