    [Fact]
    public void SharedPenPathsHonorPaletteExtraSharableColorCount()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(3);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));
        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        Assert.True(memory.TryWriteWord(
            extra + (uint)GraphicsLayouts.PaletteExtraSharableColors,
            0));

        // Shared acquisition can use only the first advertised entry; an
        // exclusive request may still use the complete ColorMap.
        Assert.Equal(-1, core.ObtainPen(colorMap, 1, 0, 0, 0, 0));
        var exclusive = core.ObtainPen(colorMap, 1, 0, 0xFFFF_FFFF, 0, 1);
        Assert.Equal(1, exclusive);
        Assert.True(core.ReleasePen(colorMap, (uint)exclusive));

        // ObtainBestPenA must not select the free but non-sharable entry as
        // its nearest match.  With EXACT precision it allocates the one
        // advertised sharable entry instead.
        Assert.True(core.SetRGB32CM(colorMap, 1, 0, 0xFFFF_FFFF, 0));
        const uint tags = 0xA00;
        WriteTag(memory, tags, 0x8400_0000, unchecked((uint)GraphicsColorOperations.PrecisionExact));
        WriteTag(memory, tags + 8, 0, 0);
        var best = core.ObtainBestPenA(colorMap, 0, 0xFFFF_FFFF, 0, tags);
        Assert.Equal(0, best);
        Assert.Equal((ushort)0, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
        Assert.True(core.ReleasePen(colorMap, (uint)best));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNFree));
    }

