    [Fact]
    public void ColorMapPensShareExactColorsAndReleaseOwnership()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(3);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));
        const uint red = 0xFF000000;
        const uint green = 0xFF000000;

        var shared = core.ObtainPen(colorMap, uint.MaxValue, red, 0, 0, 0);
        Assert.Equal(2, shared);
        Assert.Equal(0xF00u, core.GetRGB4(colorMap, shared));
        Assert.Equal(shared, core.ObtainPen(colorMap, uint.MaxValue, red, 0, 0, 0));
        Assert.Equal(0, core.ObtainPen(colorMap, 0, green, 0, 0, 1));
        Assert.True(core.ReleasePen(colorMap, (uint)shared));
        Assert.True(core.ReleasePen(colorMap, (uint)shared));
        Assert.True(core.ReleasePen(colorMap, 0));
        Assert.True(core.ReleasePen(colorMap, uint.MaxValue));
        Assert.False(core.ReleasePen(colorMap, (uint)shared));
        var best = core.ObtainBestPenA(colorMap, red, 0, 0, 0);
        Assert.Equal(0, best);
        Assert.True(core.ReleasePen(colorMap, (uint)best));

        var exclusive = core.ObtainPen(colorMap, 1, 0, green, 0, 1);
        Assert.Equal(1, exclusive);
        Assert.Equal(0x0F0u, core.GetRGB4(colorMap, exclusive));
        Assert.Equal(-1, core.ObtainPen(colorMap, 1, 0, 0, red, 1));
        Assert.Equal(1, core.FindColor(colorMap, 0, 0xFF000000, 0, -1));
        Assert.True(core.ReleasePen(colorMap, (uint)exclusive));
    }

    [Fact]
    public void ObtainBestPenHonorsPrecisionToleranceAndFailIfBad()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));
        var black = core.ObtainPen(colorMap, uint.MaxValue, 0, 0, 0, 0);
        var white = core.ObtainPen(colorMap, uint.MaxValue, 0xFFFF_FFFF, 0xFFFF_FFFF, 0xFFFF_FFFF, 0);
        Assert.Equal(1, black);
        Assert.Equal(0, white);

        const uint tags = 0xA00;
        WriteTag(memory, tags, 0x8400_0000, unchecked((uint)GraphicsColorOperations.PrecisionExact));
        WriteTag(memory, tags + 8, 0x8400_0001, 1);
        WriteTag(memory, tags + 16, 0, 0);
        Assert.Equal(-1, core.ObtainBestPenA(colorMap, 0x2000_0000, 0, 0, tags));

        // PRECISION_IMAGE is zero, so a non-exact request uses a free pen
        // instead of sharing the nearest occupied entry.
        var imageMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(imageMap, 0x240));
        Assert.Equal(1, core.ObtainPen(imageMap, uint.MaxValue, 0, 0, 0, 0));
        WriteTag(memory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionImage);
        Assert.Equal(0, core.ObtainBestPenA(imageMap, 0x0800_0000, 0, 0, tags));
        Assert.True(core.ReleasePen(imageMap, 0));
        Assert.True(core.ReleasePen(imageMap, 1));

        // PRECISION_ICON accepts a nearby shared color when the palette has
        // no free sharable entries.  The native comparison deliberately
        // relaxes matching in that exhausted-palette case.
        WriteTag(memory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionIcon);
        Assert.Equal(black, core.ObtainBestPenA(colorMap, 0x0800_0000, 0, 0, tags));
        Assert.True(core.ReleasePen(colorMap, (uint)black));

        // PRECISION_GUI uses the public value 32 as the squared-distance
        // precision term; with no free entry it also shares the nearest pen.
        WriteTag(memory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionGui);
        Assert.Equal(black, core.ObtainBestPenA(colorMap, 0x2000_0000, 0, 0, tags));

        WriteTag(memory, tags + 8, 0x8400_0001, 0);
        Assert.Equal(black, core.ObtainBestPenA(colorMap, 0x2000_0000, 0, 0, tags));
        Assert.True(core.ReleasePen(colorMap, (uint)black));
        Assert.True(core.ReleasePen(colorMap, (uint)white));
    }

    [Fact]
    public void ObtainBestPenIgnoresUnallocatedEntriesWhenChoosingTheNearestSharedColor()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(3);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        // Keep pen 2 shared at a nearby color, while a free lower entry has
        // an exact but stale ColorMap value.  Best-pen matching must inspect
        // the shared list first and return pen 2 rather than claiming pen 0.
        Assert.Equal(2, core.ObtainPen(colorMap, 2, 0x3C00_0000, 0, 0, 0));
        Assert.True(core.SetRGB4CM(colorMap, 0, 0x04, 0, 0));

        const uint tags = 0xA00;
        WriteTag(memory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionGui);
        WriteTag(memory, tags + 8, 0x8400_0001, 1);
        WriteTag(memory, tags + 16, 0, 0);

        Assert.Equal(2, core.ObtainBestPenA(colorMap, 0x3D00_0000, 0, 0, tags));
        Assert.True(core.ReleasePen(colorMap, 2));
    }

    [Fact]
    public void ObtainBestPenLeavesUnreadableSharedColorForNativeProvider()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RangeReadFaultMemory(backing);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var colorMap = core.GetColorMap(4);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        // ObtainPen inserts the newest shared entry at the shared-list head.
        // Fault that head's ColorMap word while leaving the older entry valid.
        Assert.Equal(3, core.ObtainPen(colorMap, uint.MaxValue, 0x1000_0000, 0, 0, 0));
        Assert.Equal(2, core.ObtainPen(colorMap, uint.MaxValue, 0x2000_0000, 0, 0, 0));
        var colorTable = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        memory.FailReads(colorTable + 4, 2);

        const uint tags = 0xA00;
        WriteTag(backing, tags, 0x8400_0000, unchecked((uint)GraphicsColorOperations.PrecisionExact));
        WriteTag(backing, tags + 8, 0, 0);
        var paletteExtra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var freeBefore = ReadWord(backing, paletteExtra + (uint)GraphicsLayouts.PaletteExtraNFree);

        // The direct helper reports the classic failure result but must not
        // skip the malformed shared entry and claim another free pen.
        Assert.Equal(-1, core.ObtainBestPenA(colorMap, 0x2000_0000, 0, 0, tags));
        Assert.Equal(freeBefore, ReadWord(backing, paletteExtra + (uint)GraphicsLayouts.PaletteExtraNFree));

        // The mapped gateway keeps D0/cycles available for the native or
        // provider owner when the shared ColorMap read is malformed.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xDEAD_BEEFu, [1] = 0x2000_0000u },
            Cycles = 97
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ObtainBestPenA));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(97, state.Cycles);
        Assert.Equal(freeBefore, ReadWord(backing, paletteExtra + (uint)GraphicsLayouts.PaletteExtraNFree));
    }

    [Fact]
    public void ObtainBestPenScalesToleranceByTheRemainingSharablePalette()
    {
        const uint target = 0x3200_0000; // 50/255 in the red channel.
        const uint tags = 0xA00;

        var plentifulMemory = new FakeMemory(0x10000);
        var plentifulCore = new GraphicsLibraryCore(
            plentifulMemory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var plentifulMap = plentifulCore.GetColorMap(4);
        Assert.Equal(0, plentifulCore.AttachPalExtra(plentifulMap, 0x200));
        Assert.Equal(0, plentifulCore.ObtainPen(plentifulMap, 0, 0, 0, 0, 0));
        WriteTag(plentifulMemory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionGui);
        WriteTag(plentifulMemory, tags + 8, 0x8400_0001, 1);
        WriteTag(plentifulMemory, tags + 16, 0, 0);

        // Three free sharable entries keep the scaled tolerance tight, so a
        // 50/255 red request takes a fresh pen instead of sharing black.
        Assert.Equal(3, plentifulCore.ObtainBestPenA(plentifulMap, target, 0, 0, tags));

        var sparseMemory = new FakeMemory(0x10000);
        var sparseCore = new GraphicsLibraryCore(
            sparseMemory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var sparseMap = sparseCore.GetColorMap(4);
        Assert.Equal(0, sparseCore.AttachPalExtra(sparseMap, 0x200));
        Assert.Equal(0, sparseCore.ObtainPen(sparseMap, 0, 0, 0, 0, 0));
        Assert.Equal(1, sparseCore.ObtainPen(sparseMap, 1, 0xFFFF_FFFF, 0xFFFF_FFFF, 0xFFFF_FFFF, 0));
        Assert.Equal(2, sparseCore.ObtainPen(sparseMap, 2, 0xFFFF_FFFF, 0xFFFF_FFFF, 0xFFFF_FFFF, 0));
        WriteTag(sparseMemory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionGui);
        WriteTag(sparseMemory, tags + 8, 0x8400_0001, 1);
        WriteTag(sparseMemory, tags + 16, 0, 0);

        // With one free entry, the same request falls within the relaxed
        // free-entry-scaled threshold and shares the closest occupied pen.
        Assert.Equal(0, sparseCore.ObtainBestPenA(sparseMap, target, 0, 0, tags));

        var adapter = new CopperStartGraphicsRegisterAdapter(sparseCore);
        var state = new M68kCpuState
        {
            A = { [0] = sparseMap, [1] = tags },
            D = { [1] = target, [2] = 0, [3] = 0 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ObtainBestPenA));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void ObtainBestPenAcceptsAValidNonPresetPrecisionTolerance()
    {
        const uint target = 0x0800_0000; // eight in the top RGB byte.
        const uint tags = 0xA00;

        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));
        Assert.Equal(1, core.ObtainPen(colorMap, uint.MaxValue, 0, 0, 0, 0));

        // The ROM arithmetic is not limited to the four named presets.  A
        // precision of eight gives 8^2 == 64, exactly matching the squared
        // red error here, so the occupied black pen is a valid shared match.
        WriteTag(memory, tags, 0x8400_0000, 8);
        WriteTag(memory, tags + 8, 0x8400_0001, 1);
        WriteTag(memory, tags + 16, 0, 0);
        Assert.Equal(1, core.ObtainBestPenA(colorMap, target, 0, 0, tags));

        var stricterMemory = new FakeMemory(0x10000);
        var stricterCore = new GraphicsLibraryCore(
            stricterMemory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var stricterMap = stricterCore.GetColorMap(2);
        Assert.Equal(0, stricterCore.AttachPalExtra(stricterMap, 0x240));
        Assert.Equal(1, stricterCore.ObtainPen(stricterMap, uint.MaxValue, 0, 0, 0, 0));

        // Seven is still a valid arithmetic tolerance, but 64 > 7^2, so
        // the remaining free pen is selected instead of sharing black.
        WriteTag(stricterMemory, tags, 0x8400_0000, 7);
        WriteTag(stricterMemory, tags + 8, 0x8400_0001, 1);
        WriteTag(stricterMemory, tags + 16, 0, 0);
        Assert.Equal(0, stricterCore.ObtainBestPenA(stricterMap, target, 0, 0, tags));
    }

    [Fact]
    public void ObtainBestPenHonorsTagSkipBeforeReadingFollowingPrecision()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        // Exhaust the sharable palette so PRECISION_EXACT has a visible
        // result: a non-exact request must fail instead of sharing the
        // nearest entry under the default PRECISION_IMAGE policy.
        Assert.Equal(1, core.ObtainPen(colorMap, uint.MaxValue, 0, 0, 0, 0));
        Assert.Equal(0, core.ObtainPen(
            colorMap,
            uint.MaxValue,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0xFFFF_FFFF,
            0));

        const uint tags = 0xA00;
        WriteTag(memory, tags, 3, 1); // TAG_SKIP: skip the next item.
        WriteTag(memory, tags + 8, 0x8400_0001, 1); // skipped FAIL_IF_BAD.
        WriteTag(
            memory,
            tags + 16,
            0x8400_0000,
            unchecked((uint)GraphicsColorOperations.PrecisionExact));
        WriteTag(memory, tags + 24, 0x8400_0001, 1);
        WriteTag(memory, tags + 32, 0, 0);

        const uint target = 0x0800_0000;
        Assert.Equal(-1, core.ObtainBestPenA(colorMap, target, 0, 0, tags));

        // The register adapter must consume the same valid list and keep the
        // vector claimed; TAG_SKIP is not a provider/native fallback case.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [1] = target }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ObtainBestPenA));
        Assert.Equal(uint.MaxValue, state.D[0]);
    }

    [Fact]
    public void ObtainBestPenTreatsNullTagMoreAsAnEndOfList()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        const uint tags = 0xA00;
        WriteTag(memory, tags, 2, 0); // TAG_MORE with a null continuation.

        // A null TAG_MORE is the clean end of the tag chain, so the empty
        // PaletteExtra takes its normal first-free shared pen path.
        var direct = core.ObtainBestPenA(colorMap, 0x1000_0000, 0, 0, tags);
        Assert.Equal(1, direct);
        Assert.True(core.ReleasePen(colorMap, (uint)direct));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xDEAD_BEEFu, [1] = 0x1000_0000u }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ObtainBestPenA));
        Assert.Equal(1u, state.D[0]);
        Assert.True(core.ReleasePen(colorMap, state.D[0]));
    }

    [Fact]
    public void ObtainBestPenRejectsAWrappingTagItemBeforeAllocating()
    {
        var memory = new WrappingMemory();
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.NotEqual(0u, colorMap);

        const uint viewPort = 0x200;
        for (var offset = 0u; offset < (uint)GraphicsLayouts.ViewPortSize; offset++)
            memory.WriteByte(viewPort + offset, 0);
        Assert.Equal(0, core.AttachPalExtra(colorMap, viewPort));

        // The first TagItem would wrap from $FFFF_FFFE through address zero
        // in a permissive host map.  A native 68000 must leave this malformed
        // request to the resident/provider owner instead of claiming it and
        // allocating the first free shared pen.
        const uint wrappingTags = 0xFFFF_FFFEu;
        memory.WriteLong(wrappingTags, 0);
        Assert.True(memory.TryReadLong(
            colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra,
            out var paletteExtra));
        Assert.True(memory.TryReadWord(
            paletteExtra + (uint)GraphicsLayouts.PaletteExtraNFree,
            out var freeBefore));

        Assert.Equal(
            -1,
            core.ObtainBestPenA(
                colorMap,
                0x1000_0000,
                0,
                0,
                wrappingTags));
        Assert.True(memory.TryReadWord(
            paletteExtra + (uint)GraphicsLayouts.PaletteExtraNFree,
            out var freeAfter));
        Assert.Equal(freeBefore, freeAfter);
    }

    [Fact]
    public void SharedPenReferenceCountsUseTheNativeWordRange()
    {
        var memory = new FakeMemory(0x20000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        const uint red = 0xA000_0000;
        Assert.Equal(1, core.ObtainPen(colorMap, uint.MaxValue, red, 0, 0, 0));

        // The native PaletteExtra private reference table is WORD-sized.  A
        // 256th shared acquisition must therefore remain valid instead of
        // being rejected at the host shadow's old byte-sized ceiling.
        for (var acquisition = 1; acquisition < 256; acquisition++)
            Assert.Equal(1, core.ObtainPen(colorMap, uint.MaxValue, red, 0, 0, 0));

        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var refs = ReadLong(memory, extra + (uint)GraphicsLayouts.PaletteExtraRefCount);
        Assert.Equal((ushort)256, ReadWord(memory, refs + 2));
        Assert.Equal((ushort)1, ReadWord(memory, extra + (uint)GraphicsLayouts.PaletteExtraNShared));
    }

    [Fact]
    public void PaletteSemaphoreTracksTaskOwnershipNestingAndContention()
    {
        var memory = new FakeMemory(0x20000);
        var currentTask = 0x700u;
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            currentTask: () => currentTask);
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        var extra = ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var owner = extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreOwner;
        var nest = extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreNestCount;

        // A normal portable call acquires and releases the guest semaphore
        // around the host operation, leaving the public fields clear.
        Assert.True(core.SetRGB4CM(colorMap, 0, 1, 2, 3));
        Assert.Equal(0u, ReadLong(memory, owner));
        Assert.Equal((ushort)0, ReadWord(memory, nest));

        // A different current task must not steal a native-owned semaphore;
        // the portable result declines with all palette state untouched.
        var before = core.GetRGB4(colorMap, 0);
        Assert.True(memory.TryWriteLong(owner, 0x900));
        Assert.True(memory.TryWriteWord(nest, 1));
        var foreign = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0, [1] = 0xF, [2] = 0, [3] = 0 },
            Cycles = 19
        };
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        Assert.False(adapter.TryInvoke(foreign, (int)GraphicsLvo.SetRGB4CM));
        Assert.Equal(0u, foreign.D[0]);
        Assert.Equal(19, foreign.Cycles);
        Assert.Equal(before, ReadWord(
            memory,
            ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapColorTable)));
        Assert.Equal(0x900u, ReadLong(memory, owner));
        Assert.Equal((ushort)1, ReadWord(memory, nest));

        // An owned semaphore with a zero nest count is an impossible Exec
        // state.  The portable path must leave it for native/provider
        // recovery rather than repairing ownership and mutating the palette.
        Assert.True(memory.TryWriteLong(owner, currentTask));
        Assert.True(memory.TryWriteWord(nest, 0));
        var malformedBefore = core.GetRGB4(colorMap, 0);
        Assert.False(core.SetRGB4CM(colorMap, 0, 7, 8, 9));
        Assert.Equal(malformedBefore, core.GetRGB4(colorMap, 0));
        var malformed = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0xABCD_1234u, [1] = 0xF, [2] = 0, [3] = 0 },
            Cycles = 23
        };
        Assert.False(adapter.TryInvoke(malformed, (int)GraphicsLvo.SetRGB4CM));
        Assert.Equal(0xABCD_1234u, malformed.D[0]);
        Assert.Equal(23, malformed.Cycles);
        Assert.Equal(malformedBefore, core.GetRGB4(colorMap, 0));
        Assert.Equal(currentTask, ReadLong(memory, owner));
        Assert.Equal((ushort)0, ReadWord(memory, nest));

        // Re-entry by the owning task increments and then restores the
        // native nest count, without releasing ownership prematurely.
        Assert.True(memory.TryWriteLong(owner, currentTask));
        Assert.True(memory.TryWriteWord(nest, 1));
        Assert.True(core.SetRGB4CM(colorMap, 0, 4, 5, 6));
        Assert.Equal(currentTask, ReadLong(memory, owner));
        Assert.Equal((ushort)1, ReadWord(memory, nest));
        Assert.Equal(0x456u, core.GetRGB4(colorMap, 0));

        Assert.True(memory.TryWriteWord(nest, 0));
        Assert.True(memory.TryWriteLong(owner, 0));
    }

    [Fact]
    public void PaletteSemaphoreRestoresOwnerAfterARejectedNestPublicationRollback()
    {
        var backing = new FakeMemory(0x20000);
        var memory = new ProbeLongThenFailWordWriteMemory(backing);
        const uint currentTask = 0x701;
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            currentTask: () => currentTask);
        var colorMap = core.GetColorMap(2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));

        var extra = ReadLong(backing, colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        var owner = extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreOwner;
        var nest = extra + (uint)GraphicsLayouts.PaletteExtraSemaphoreNestCount;
        memory.ProbeLongAddress = owner;
        memory.FailWordAddress = nest;

        Assert.False(core.SetRGB4CM(colorMap, 0, 1, 2, 3));
        Assert.Equal(0u, ReadLong(backing, owner));
        Assert.Equal((ushort)0, ReadWord(backing, nest));

        memory.ProbeLongAddress = null;
        memory.FailWordAddress = null;
        Assert.True(core.SetRGB4CM(colorMap, 0, 1, 2, 3));
        Assert.Equal(0u, ReadLong(backing, owner));
        Assert.Equal((ushort)0, ReadWord(backing, nest));
    }

    [Fact]
    public void PaletteSemaphoreRestoresOwnerAndNestAfterARejectedReleaseLong()
    {
        var backing = new FakeMemory(0x20000);
        var memory = new ProbeThenFailLongWriteMemory(backing);
        const uint currentTask = 0x701;
        var core = new GraphicsLibraryCore(
            memory,
