    [Fact]
    public void ObtainBestPenRegisterVectorReadsPrecisionTagsAndAllocatesFreePen()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = InvokeGetColorMap(adapter, 2);
        Assert.Equal(0, core.AttachPalExtra(colorMap, 0x200));
        var black = core.ObtainPen(colorMap, uint.MaxValue, 0, 0, 0, 0);
        Assert.Equal(1, black);

        const uint tags = 0xA00;
        WriteTag(memory, tags, 0x8400_0000, GraphicsColorOperations.PrecisionGui);
        WriteTag(memory, tags + 8, 0x8400_0001, 1);
        WriteTag(memory, tags + 16, 0, 0);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [1] = 0xFFFF_0000, [2] = 0, [3] = 0 }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ObtainBestPenA));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0xF00u, core.GetRGB4(colorMap, 0));
        Assert.True(core.ReleasePen(colorMap, (uint)black));
        Assert.True(core.ReleasePen(colorMap, 0));
    }

    [Fact]
    public void VideoControlAttachesViewportAndProcessesPaletteFlags()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = InvokeGetColorMap(adapter, 2);
        const uint viewPort = 0x300;
        const uint tags = 0xA00;
        Assert.True(memory.TryWriteLong(tags, 0x8000_000B)); // VTAG_ATTACH_CM_SET
        Assert.True(memory.TryWriteLong(tags + 4, viewPort));
        Assert.True(memory.TryWriteLong(tags + 8, 0x8000_0005)); // VTAG_BORDERBLANK_SET
        Assert.True(memory.TryWriteLong(tags + 12, 1));
        Assert.True(memory.TryWriteLong(tags + 16, 0));
        Assert.True(memory.TryWriteLong(tags + 20, 0));

        var set = new M68kCpuState { A = { [0] = colorMap, [1] = tags } };
        Assert.True(adapter.TryInvoke(set, (int)GraphicsLvo.VideoControl));
        Assert.Equal(0u, set.D[0]);
        Assert.Equal(viewPort, ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapViewPort));
        Assert.Equal(colorMap, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortColorMap));
        Assert.NotEqual((byte)0, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags));

        Assert.True(memory.TryWriteLong(tags, 0x8000_0017)); // VTAG_BORDERBLANK_GET
        Assert.True(memory.TryWriteLong(tags + 4, 0));
        Assert.True(memory.TryWriteLong(tags + 8, 0x8000_001B)); // VTAG_ATTACH_CM_GET
        Assert.True(memory.TryWriteLong(tags + 12, 0));
        Assert.True(memory.TryWriteLong(tags + 16, 0));
        Assert.True(memory.TryWriteLong(tags + 20, 0));
        Assert.True(adapter.TryInvoke(set, (int)GraphicsLvo.VideoControl));
        Assert.Equal(0x8000_0005u, ReadLong(memory, tags));
        Assert.Equal(1u, ReadLong(memory, tags + 4));
        Assert.Equal(0x8000_000Bu, ReadLong(memory, tags + 8));
        Assert.Equal(viewPort, ReadLong(memory, tags + 12));
    }

    [Fact]
    public void VideoControlFollowsNextBufferAndKeepsTheTransactionAtomic()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = InvokeGetColorMap(adapter, 2);
        const uint tags = 0xA00;
        const uint nextBuffer = 0xC00;
        const uint immediate = 0xD00;

        WriteTag(memory, tags + 0, 0x8000_0005, 1); // BORDERBLANK_SET
        WriteTag(memory, tags + 8, 0x8000_000C, nextBuffer); // VTAG_NEXTBUF_CM
        WriteTag(memory, nextBuffer + 0, 0x8000_0007, 1); // BORDERNOTRANS_SET
        WriteTag(memory, nextBuffer + 8, 0x8000_0037, immediate); // VTAG_IMMEDIATE
        WriteTag(memory, nextBuffer + 16, 0, 0);
        Assert.True(memory.TryWriteLong(immediate, 0xCAFE_BABE));

        var state = new M68kCpuState { A = { [0] = colorMap, [1] = tags } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0x0C, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags));
        Assert.Equal(1u, ReadLong(memory, immediate));
    }

    [Fact]
    public void VideoControlRejectsMalformedNextBufferBeforePublishingEarlierTags()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = InvokeGetColorMap(adapter, 2);
        const uint tags = 0x900;
        const uint malformedNextBuffer = 0x1FFC;

        WriteTag(memory, tags + 0, 0x8000_0005, 1); // BORDERBLANK_SET
        WriteTag(memory, tags + 8, 0x8000_000C, malformedNextBuffer); // VTAG_NEXTBUF_CM
        Assert.True(memory.TryWriteLong(malformedNextBuffer, 0x8000_0007));

        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xA5A5_5A5A },
            Cycles = 83
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(83, state.Cycles);
        Assert.Equal((byte)0, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags));
    }

    [Fact]
    public void VideoControlRejectsOddTagListHeadWithoutPublishingState()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = InvokeGetColorMap(adapter, 2);
        const uint oddTags = 0x901;

        // FakeMemory deliberately permits byte-addressed setup so the
        // portable collector, rather than the fixture, owns the 68000
        // word-alignment boundary.
        WriteTag(memory, oddTags, 0x8000_0005, 1); // BORDERBLANK_SET
        Assert.False(core.IsNativeOverlayVideoControlSafe(oddTags));

        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = oddTags },
            D = { [0] = 0xA5A5_5A5A },
            Cycles = 97
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(97, state.Cycles);
        Assert.Equal((byte)0, ReadByte(
            memory,
            colorMap + (uint)GraphicsLayouts.ColorMapFlags));
    }

    [Fact]
    public void VideoControlPublishesLayoutBackedV39StateTags()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = InvokeGetColorMap(adapter, 4);
        const uint tags = 0xA00;

        WriteTag(memory, tags + 0, 0x8000_0001, 1); // VTAG_CHROMAKEY_SET
        WriteTag(memory, tags + 8, 0x8000_0003, 1); // VTAG_BITPLANEKEY_SET
        WriteTag(memory, tags + 16, 0x8000_000A, 5); // VTAG_CHROMA_PLANE_SET
        WriteTag(memory, tags + 24, 0x8000_000E, 1); // VTAG_BATCH_CM_SET
        WriteTag(memory, tags + 32, 0x8000_001E, 0xC00); // VTAG_BATCH_ITEMS_SET
        WriteTag(memory, tags + 40, 0x8000_0024, 1); // VTAG_USERCLIP_SET
        WriteTag(memory, tags + 48, 0x8000_002F, 1); // VTAG_BORDERSPRITE_SET
        WriteTag(memory, tags + 56, 0x8000_0031, 3); // VTAG_SPRITERESN_SET
        WriteTag(memory, tags + 64, 0x8000_003B, 2); // VTAG_DEFSPRITERESN_SET
        WriteTag(memory, tags + 72, 0x8000_002A, 0x1234); // VTAG_PF1_BASE_SET
        WriteTag(memory, tags + 80, 0x8000_002B, 0x2345); // VTAG_PF2_BASE_SET
        WriteTag(memory, tags + 88, 0x8000_002C, 0x3456); // VTAG_SPEVEN_BASE_SET
        WriteTag(memory, tags + 96, 0x8000_002D, 0x4567); // VTAG_SPODD_BASE_SET
        WriteTag(memory, tags + 104, 0x8000_0038, 1); // VTAG_FULLPALETTE_SET
        WriteTag(memory, tags + 112, 0x8000_0009, 3); // VTAG_CHROMA_PEN_SET
        WriteTag(memory, tags + 120, 0x8000_0033, 1); // VTAG_PF1_TO_SPRITEPRI_SET
        WriteTag(memory, tags + 128, 0x8000_0035, 0); // VTAG_PF2_TO_SPRITEPRI_SET
        WriteTag(memory, tags + 136, 0, 0);

        var state = new M68kCpuState { A = { [0] = colorMap, [1] = tags } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));
        Assert.Equal(0u, state.D[0]);

        var flags = ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags);
        Assert.Equal(0x73u, (uint)(flags & 0x73));
        Assert.Equal(5u, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapTransparencyPlane));
        Assert.Equal(3u, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapSpriteResolution));
        Assert.Equal(2u, ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapSpriteResDefault));
