        Assert.Equal(0x1234u, ReadWord(memory, colorMap + (uint)GraphicsLayouts.ColorMapBitPlane0Base));
        Assert.Equal(0x2345u, ReadWord(memory, colorMap + (uint)GraphicsLayouts.ColorMapBitPlane1Base));
