        Assert.Equal(0x4567u, ReadWord(memory, colorMap + (uint)GraphicsLayouts.ColorMapSpriteBaseOdd));
        Assert.True((ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapAuxFlags) & 1) != 0);

        WriteTag(memory, tags + 0, 0x8000_0015, 0); // VTAG_CHROMAKEY_GET
        WriteTag(memory, tags + 8, 0x8000_0016, 0); // VTAG_BITPLANEKEY_GET
        WriteTag(memory, tags + 16, 0x8000_001A, 0); // VTAG_CHROMA_PLANE_GET
        WriteTag(memory, tags + 24, 0x8000_001C, 0); // VTAG_BATCH_CM_GET
        WriteTag(memory, tags + 32, 0x8000_001D, 0); // VTAG_BATCH_ITEMS_GET
        WriteTag(memory, tags + 40, 0x8000_0023, 0); // VTAG_USERCLIP_GET
        WriteTag(memory, tags + 48, 0x8000_002E, 0); // VTAG_BORDERSPRITE_GET
        WriteTag(memory, tags + 56, 0x8000_0032, 0); // VTAG_SPRITERESN_GET
        WriteTag(memory, tags + 64, 0x8000_003C, 0); // VTAG_DEFSPRITERESN_GET
        WriteTag(memory, tags + 72, 0x8000_0026, 0); // VTAG_PF1_BASE_GET
        WriteTag(memory, tags + 80, 0x8000_0027, 0); // VTAG_PF2_BASE_GET
        WriteTag(memory, tags + 88, 0x8000_0028, 0); // VTAG_SPEVEN_BASE_GET
        WriteTag(memory, tags + 96, 0x8000_0029, 0); // VTAG_SPODD_BASE_GET
        WriteTag(memory, tags + 104, 0x8000_0039, 0); // VTAG_FULLPALETTE_GET
        WriteTag(memory, tags + 112, 0x8000_0019, 0); // VTAG_CHROMA_PEN_GET
        WriteTag(memory, tags + 120, 0x8000_0034, 0); // VTAG_PF1_TO_SPRITEPRI_GET
        WriteTag(memory, tags + 128, 0x8000_0036, 0); // VTAG_PF2_TO_SPRITEPRI_GET
        WriteTag(memory, tags + 136, 0, 0);
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.VideoControl));

        Assert.Equal(0x8000_0001u, ReadLong(memory, tags + 0));
        Assert.Equal(1u, ReadLong(memory, tags + 4));
        Assert.Equal(0x8000_0003u, ReadLong(memory, tags + 8));
        Assert.Equal(1u, ReadLong(memory, tags + 12));
        Assert.Equal(0x8000_000Au, ReadLong(memory, tags + 16));
        Assert.Equal(5u, ReadLong(memory, tags + 20));
