        Assert.Equal(1u, ReadLong(memory, tags + 28));
        Assert.Equal(0x8000_001Eu, ReadLong(memory, tags + 32));
        Assert.Equal(0xC00u, ReadLong(memory, tags + 36));
        Assert.Equal(0x8000_0024u, ReadLong(memory, tags + 40));
        Assert.Equal(1u, ReadLong(memory, tags + 44));
        Assert.Equal(0x8000_002Fu, ReadLong(memory, tags + 48));
        Assert.Equal(1u, ReadLong(memory, tags + 52));
        Assert.Equal(0x8000_0031u, ReadLong(memory, tags + 56));
        Assert.Equal(3u, ReadLong(memory, tags + 60));
        Assert.Equal(0x8000_003Bu, ReadLong(memory, tags + 64));
        Assert.Equal(2u, ReadLong(memory, tags + 68));
        Assert.Equal(0x8000_002Au, ReadLong(memory, tags + 72));
        Assert.Equal(0x1234u, ReadLong(memory, tags + 76));
        Assert.Equal(0x8000_002Bu, ReadLong(memory, tags + 80));
        Assert.Equal(0x2345u, ReadLong(memory, tags + 84));
        Assert.Equal(0x8000_002Cu, ReadLong(memory, tags + 88));
