    [Fact]
    public void QBlitAndQBSBlitValidateClassicNodeAndPreserveQueueClass()
    {
        var memory = new FakeMemory(0x100);
        var blitter = new FakeBlitter();
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), blitter, new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint node = 0x20;

        Assert.True(memory.TryWriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000));
        Assert.True(memory.TryWriteByte(node + (uint)GraphicsLayouts.BltNodeStatus, 0x40));
        Assert.True(memory.TryWriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234));
        Assert.True(memory.TryWriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80));
        Assert.True(memory.TryWriteLong(node + (uint)GraphicsLayouts.BltNodeCleanup, 0x5000));

        var state = new M68kCpuState();
        state.A[1] = node;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.QBlit));
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.QBSBlit));
        Assert.Equal(2, blitter.Queued.Count);
        Assert.Equal((node, false, (short)-128), blitter.Queued[0]);
        Assert.Equal((node, true, (short)-128), blitter.Queued[1]);
    }

    [Fact]
    public void TimedBlitterFifoPreservesSubmissionOrderBeamGateAndCompletion()
    {
        var memory = new FakeMemory(0x200);
        const uint firstNode = 0x20;
        const uint secondNode = 0x40;
        const uint thirdNode = 0x60;
        foreach (var node in new[] { firstNode, secondNode, thirdNode })
        {
            Assert.True(memory.TryWriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000));
            Assert.True(memory.TryWriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234));
            Assert.True(memory.TryWriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80));
        }

        var fifo = new GraphicsBlitterFifoBackend(capacity: 2);
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), fifo, new FakeDisplay());

        Assert.True(core.QBlit(firstNode, cycle: 10));
        Assert.True(core.QBSBlit(secondNode, cycle: 11));
        Assert.False(core.QBlit(thirdNode, cycle: 12));
        Assert.Equal(2, fifo.Count);

        // WaitBlit synchronizes only the hardware operation currently in
        // flight; it does not drain QBlit/QBSBlit nodes that are still queued.
        Assert.True(core.WaitBlit(12, out var queuedCompletion));
        Assert.Equal(12, queuedCompletion);
        Assert.Equal(2, fifo.Count);
        Assert.True(fifo.TryDequeueReady(10, beamReady: null, out var first));
        Assert.Equal(
            new GraphicsQueuedBlitOperation(firstNode, false, -128, 10),
            first);
        Assert.False(fifo.TryDequeueReady(11, beamReady: null, out _));
        Assert.True(fifo.CompleteInFlight(15));

        Assert.False(fifo.TryDequeueReady(19, (beam, cycle) => beam == -128 && cycle >= 20, out _));
        Assert.True(fifo.TryDequeueReady(20, (beam, cycle) => beam == -128 && cycle >= 20, out var second));
        Assert.Equal(
            new GraphicsQueuedBlitOperation(secondNode, true, -128, 11),
            second);
        Assert.True(fifo.CompleteInFlight(24));
        Assert.True(core.WaitBlit(30, out var completionCycle));
        Assert.Equal(30, completionCycle);
    }

    [Fact]
    public void TimedBlitterFifoKeepsQBlitAndQBSBlitInSubmissionOrder()
    {
        var fifo = new GraphicsBlitterFifoBackend(capacity: 4);
        const uint ordinary = 0x20;
        const uint beam = 0x40;

        Assert.True(fifo.TrySubmitQueued(
            ordinary,
            beamSynchronized: false,
            beamSync: 0,
            cycle: 1));
        Assert.True(fifo.TrySubmitQueued(
            beam,
            beamSynchronized: true,
            beamSync: 42,
            cycle: 2));

        // V39+ keeps both request classes in one FIFO.  A ready QBS request
        // submitted second does not jump over the ordinary head.
        Assert.True(fifo.TryDequeueReady(
            10,
            (target, cycle) => target == 42 && cycle >= 10,
            out var readyOrdinary));
        Assert.Equal(ordinary, readyOrdinary.OperationAddress);
        Assert.True(fifo.CompleteInFlight(11));

        Assert.True(fifo.TryDequeueReady(
            11,
            (target, cycle) => target == 42 && cycle >= 10,
            out var readyBeam));
        Assert.Equal(beam, readyBeam.OperationAddress);
        Assert.True(fifo.CompleteInFlight(12));

        // A QBS request waiting for its beam gates later ordinary work in the
        // same FIFO until the beam predicate is satisfied.
        Assert.True(fifo.TrySubmitQueued(
            beam,
            beamSynchronized: true,
            beamSync: 99,
            cycle: 12));
        Assert.True(fifo.TrySubmitQueued(
            ordinary,
            beamSynchronized: false,
            beamSync: 0,
            cycle: 13));
        Assert.False(fifo.TryDequeueReady(
            13,
            (_, _) => false,
            out _));
        Assert.True(fifo.TryDequeueReady(
            20,
            (target, cycle) => target == 99 && cycle >= 20,
            out var laterBeam));
        Assert.Equal(beam, laterBeam.OperationAddress);
        Assert.True(fifo.CompleteInFlight(21));
        Assert.True(fifo.TryDequeueReady(
            21,
            (_, _) => false,
            out var laterOrdinary));
        Assert.Equal(ordinary, laterOrdinary.OperationAddress);
    }

    [Fact]
    public void TimedBlitterFifoSchedulePeekHonorsDueCycleBeamPredicateAndInFlightBoundary()
    {
        var fifo = new GraphicsBlitterFifoBackend(capacity: 4);
        const uint beam = 0x40;
        const uint ordinary = 0x20;

        Assert.True(fifo.TrySubmitQueued(
            beam,
            beamSynchronized: true,
            beamSync: 42,
            cycle: 20));

        // A scheduler boundary before submission cannot advertise the node as
        // ready.  With no predicate, the profile-aware owner may still inspect
        // the due QBS head and apply its own beam/frame policy.
        Assert.False(fifo.TryPeekForSchedule(19, beamReady: null, out _));
        Assert.True(fifo.TryPeekForSchedule(20, beamReady: null, out var candidate));
        Assert.Equal(beam, candidate.OperationAddress);

        // When the owner supplies a predicate, a blocked QBS head remains the
        // FIFO gate; later ordinary work cannot be observed around it.
        Assert.False(fifo.TryPeekForSchedule(
            20,
            (target, cycle) => target == 42 && cycle >= 21,
            out _));
        Assert.True(fifo.TrySubmitQueued(
            ordinary,
            beamSynchronized: false,
            beamSync: 0,
            cycle: 21));
        Assert.False(fifo.TryPeekForSchedule(
            21,
            (_, _) => false,
            out _));

        Assert.True(fifo.TryDequeueReady(
            21,
            (target, cycle) => target == 42 && cycle >= 21,
            out var readyBeam));
        Assert.Equal(beam, readyBeam.OperationAddress);

        // The in-flight node is not exposed as another schedulable head until
        // the custom-chip owner reports completion.
        Assert.False(fifo.TryPeekForSchedule(21, beamReady: null, out _));
        Assert.True(fifo.CompleteInFlight(22));
        Assert.True(fifo.TryPeekForSchedule(22, beamReady: null, out var readyOrdinary));
        Assert.Equal(ordinary, readyOrdinary.OperationAddress);
    }

    [Fact]
    public void PortableQueuedBlitterPublishesSystemOwnedGuestNextLinksTransactionally()
    {
        var memory = new FakeMemory(0x200);
        const uint firstNode = 0x20;
        const uint secondNode = 0x40;
        const uint thirdNode = 0x60;
        foreach (var node in new[] { firstNode, secondNode, thirdNode })
        {
            Assert.True(memory.TryWriteLong(
                node + (uint)GraphicsLayouts.BltNodeFunction,
                0x4000));
            Assert.True(memory.TryWriteWord(
                node + (uint)GraphicsLayouts.BltNodeBlitSize,
                0x1234));
        }

        // The system owns bn_Next. A queued node is terminated first, then
        // the previous pending tail points at it.
        Assert.True(memory.TryWriteLong(
            secondNode + (uint)GraphicsLayouts.BltNodeNext,
            0x00ABCDEF));
        var fifo = new GraphicsBlitterFifoBackend(capacity: 2);
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            fifo,
            new FakeDisplay());

        Assert.True(core.QBlit(firstNode, cycle: 1));
        Assert.Equal(0u, ReadLong(memory, firstNode + (uint)GraphicsLayouts.BltNodeNext));

        Assert.True(core.QBSBlit(secondNode, cycle: 2));
        Assert.Equal(secondNode, ReadLong(memory, firstNode + (uint)GraphicsLayouts.BltNodeNext));
        Assert.Equal(0u, ReadLong(memory, secondNode + (uint)GraphicsLayouts.BltNodeNext));

        // Capacity is checked before guest mutation. The rejected third node
        // retains its caller bytes and the existing tail link is unchanged.
        Assert.True(memory.TryWriteLong(
            thirdNode + (uint)GraphicsLayouts.BltNodeNext,
            0x00123456));
        Assert.False(core.QBlit(thirdNode, cycle: 3));
        Assert.Equal(0x00123456u, ReadLong(memory, thirdNode + (uint)GraphicsLayouts.BltNodeNext));
        Assert.Equal(secondNode, ReadLong(memory, firstNode + (uint)GraphicsLayouts.BltNodeNext));
    }

    [Fact]
    public void PortableQueuedBlitterRestoresTheFirstNodeLinkAfterARejectedPartialLongWrite()
    {
        var backing = new FakeMemory(0x200);
        var memory = new PartialThenRejectLongWriteMemory(backing);
        const uint node = 0x20;
        var nextAddress = node + (uint)GraphicsLayouts.BltNodeNext;
        memory.PartialLongAddress = nextAddress;
        Assert.True(backing.TryWriteLong(
            node + (uint)GraphicsLayouts.BltNodeFunction,
            0x4000));
        Assert.True(backing.TryWriteWord(
            node + (uint)GraphicsLayouts.BltNodeBlitSize,
            0x1234));
        Assert.True(backing.TryWriteLong(nextAddress, 0x00ABCDEF));

        var fifo = new GraphicsBlitterFifoBackend(capacity: 2);
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            fifo,
            new FakeDisplay());

        Assert.False(core.QBlit(node, cycle: 1));
        Assert.Equal(0x00ABCDEFu, ReadLong(backing, nextAddress));
        Assert.Equal(0, fifo.Count);

        memory.PartialLongAddress = null;
        Assert.True(core.QBlit(node, cycle: 2));
        Assert.Equal(0u, ReadLong(backing, nextAddress));
        Assert.Equal(1, fifo.Count);
    }

    [Fact]
