    [Fact]
    public void TimedRegisterAdapterPublishesGuestCycleToBlitterFifo()
    {
        var memory = new FakeMemory(0x100);
        const uint node = 0x20;
        Assert.True(memory.TryWriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000));
        Assert.True(memory.TryWriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234));

        var fifo = new GraphicsBlitterFifoBackend();
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), fifo, new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            Cycles = 37,
            A = { [1] = node },
            D = { [0] = 0xCAFE_BABEu }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.QBlit));
        Assert.Equal(0u, state.D[0]);
        var queuedWait = new M68kCpuState
        {
            Cycles = 37,
            D = { [0] = 0xFFFF_FFFFu }
        };
        Assert.True(adapter.TryInvoke(queuedWait, (int)GraphicsLvo.WaitBlit));
        Assert.Equal(0u, queuedWait.D[0]);
        Assert.Equal(37, queuedWait.Cycles);
        Assert.Equal(1, fifo.Count);

        Assert.True(fifo.TryDequeueReady(37, beamReady: null, out var operation));
        Assert.Equal(37, operation.SubmittedCycle);
        Assert.Equal(node, operation.OperationAddress);
        Assert.True(fifo.CompleteInFlight(52));

        var wait = new M68kCpuState
        {
            Cycles = 37,
            D = { [0] = 0xFFFF_FFFFu }
        };
        Assert.True(adapter.TryInvoke(wait, (int)GraphicsLvo.WaitBlit));
        Assert.Equal(0u, wait.D[0]);
        Assert.Equal(52, wait.Cycles);
    }

    [Fact]
    public void CopperStartBlitterSchedulerRunsGuestCallbackContractAtGatewayBoundary()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        const uint stack = 0x8000;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);

        var starts = new List<(uint Entry, uint CustomBase, uint Node)>();
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (state, entry, continuation) =>
            {
                starts.Add((entry, state.A[0], state.A[1]));
                state.ProgramCounter = entry;
            });

        Assert.True(scheduler.TrySubmitQueued(node, beamSynchronized: false, beamSync: 0, cycle: 10));
        // The node is queued but no hardware callback has started yet.  The
        // synchronous wait returns at the current cycle and leaves the queued
        // request for the scheduler boundary.
        Assert.True(scheduler.TryWait(10, out var queuedCompletion));
        Assert.Equal(10, queuedCompletion);
        var state = new M68kCpuState
        {
            A = { [7] = stack + 0x80 },
            Cycles = 10
        };

        scheduler.ProcessPending(state);
        Assert.Single(starts);
        Assert.Equal((function, 0x00DFF000u, node), starts[0]);

        // A nonzero D0 requests another callback when the blitter is idle.
        state.D[0] = 1;
        state.ProgramCounter = CopperStartGraphicsBlitterScheduler.ContinuationAddress;
        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));
        state.Cycles = 11;
        scheduler.ProcessPending(state);
        Assert.Equal(2, starts.Count);
        Assert.Equal((function, 0x00DFF000u, node), starts[1]);

        // Zero D0 completes the node.  With no cleanup flag the FIFO is
        // released at the same continuation boundary.
        state.D[0] = 0;
        state.ProgramCounter = CopperStartGraphicsBlitterScheduler.ContinuationAddress;
        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));
        Assert.True(scheduler.TryWait(state.Cycles, out var completionCycle));
        Assert.Equal(state.Cycles, completionCycle);
    }

    [Fact]
    public void CopperStartBlitterSchedulerDeclinesAnUnmappedCallbackStack()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);

        var callbackCount = 0;
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (_, _, _) => callbackCount++);

        Assert.True(scheduler.TrySubmitQueued(
            node,
            beamSynchronized: false,
            beamSync: 0,
            cycle: 1));

        // StartGuestSubroutine would push the continuation at A7-4.  An
        // unmapped stack must therefore decline before the callback is
        // entered, while still retiring the malformed in-flight node so the
        // FIFO cannot remain wedged.
        var state = new M68kCpuState
        {
            A = { [7] = 0xFFFF_FFFC },
            Cycles = 1
        };
        scheduler.ProcessPending(state);

        Assert.Equal(0, callbackCount);
        Assert.True(scheduler.TryWait(state.Cycles, out var completionCycle));
        Assert.Equal(state.Cycles, completionCycle);
    }

    [Fact]
    public void CopperStartBlitterSchedulerDeclinesAReadOnlyCallbackStack()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        const uint stack = 0x00F0_0000;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.MapReadOnlyMemory(stack, new byte[0x100]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);

        var callbackCount = 0;
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (_, _, _) => callbackCount++);

        Assert.True(scheduler.TrySubmitQueued(
            node,
            beamSynchronized: false,
            beamSync: 0,
            cycle: 1));

        // A mapped ROM/image is readable but cannot accept the continuation
        // LONG that StartGuestSubroutine pushes at A7-4.  The scheduler must
        // decline before the callback and retire the FIFO entry cleanly.
        var state = new M68kCpuState
        {
            A = { [7] = stack + 0x80 },
            Cycles = 1
        };
        scheduler.ProcessPending(state);

        Assert.Equal(0, callbackCount);
        Assert.True(scheduler.TryWait(state.Cycles, out var completionCycle));
        Assert.Equal(state.Cycles, completionCycle);
    }

    [Fact]
    public void CopperStartBlitterSchedulerHonorsAReadOnlyOverlayOverWritableStack()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        const uint stack = 0x00F0_0000;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.MapReadOnlyMemory(stack, new byte[0x100]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        Assert.False(bus.IsWritableMemoryRange(stack + 0x7C, 4));

        var callbackCount = 0;
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (_, _, _) => callbackCount++);

        Assert.True(scheduler.TrySubmitQueued(
            node,
            beamSynchronized: false,
            beamSync: 0,
            cycle: 1));

        // The newer read-only image masks the older writable mapping.  The
        // continuation LONG at A7-4 must therefore remain outside the guest
        // callback claim, and the lower mapping must stay untouched.
        var state = new M68kCpuState
        {
            A = { [7] = stack + 0x80 },
            Cycles = 1
        };
        scheduler.ProcessPending(state);

        Assert.Equal(0, callbackCount);
        Assert.Equal(0u, bus.ReadLong(stack + 0x7C));
        Assert.True(scheduler.TryWait(state.Cycles, out var completionCycle));
        Assert.Equal(state.Cycles, completionCycle);
    }

    [Fact]
    public void CopperStartBlitterSchedulerQbsUsesProfileLineWakeAndFrameCatchUp()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        const uint stack = 0x8000;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);

        var callbackCount = 0;
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (state, entry, continuation) =>
            {
                Assert.Equal(function, entry);
                Assert.Equal(node, state.A[1]);
                callbackCount++;
                state.D[0] = 0xCAFE_BABEu;
                state.ProgramCounter = continuation;
            });
        var state = new M68kCpuState
        {
            A = { [7] = stack + 0x80 },
            Cycles = 0
        };

        // VBeamPos is profile-bounded.  PAL has no line 400, so the classic
        // QBS catch-up rule releases this node at the next frame boundary
        // instead of spinning on an unreachable line forever.
        const short unrepresentableLine = 400;
        Assert.True(scheduler.TrySubmitQueued(
            node,
            beamSynchronized: true,
            beamSync: unrepresentableLine,
            cycle: 0));
        var nextFrame = bus.GetNextFrameStartCycle(0);
        Assert.Equal(
            nextFrame,
            scheduler.GetNextBoundaryCycle(0, nextFrame + 10));
        scheduler.ProcessPending(state);
        Assert.Equal(0, callbackCount);

        state.Cycles = nextFrame;
        Assert.False(bus.Blitter.Busy);
        scheduler.ProcessPending(state);
        Assert.Equal(1, callbackCount);
        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));

        // A representable target wakes on its exact profile line start.
        scheduler.Reset();
        callbackCount = 0;
        state.Cycles = 0;
        const short targetLine = 20;
        Assert.True(scheduler.TrySubmitQueued(
            node,
            beamSynchronized: true,
            beamSync: targetLine,
            cycle: 0));
        var targetCycle = bus.GetLineStartCycle(0, targetLine);
        Assert.Equal(
            targetCycle,
            scheduler.GetNextBoundaryCycle(0, targetCycle + 10));
        state.Cycles = targetCycle - 1;
        scheduler.ProcessPending(state);
        Assert.Equal(0, callbackCount);
        state.Cycles = targetCycle;
        scheduler.ProcessPending(state);
        Assert.Equal(1, callbackCount);
        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));
    }

    [Fact]
    public void CopperStartBlitterSchedulerRunsCleanupOnlyAfterFunctionCompletes()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        const uint cleanup = 0x5000;
        const uint stack = 0x8000;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.MapReadOnlyMemory(cleanup, new byte[2]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteByte(node + (uint)GraphicsLayouts.BltNodeStatus, 0x40, 0);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeCleanup, cleanup);

        var starts = new List<(uint Entry, uint CustomBase, uint Node)>();
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (state, entry, continuation) =>
            {
                starts.Add((entry, state.A[0], state.A[1]));
                state.ProgramCounter = entry;
            });
        Assert.True(scheduler.TrySubmitQueued(node, false, 0, 4));

        var state = new M68kCpuState
        {
            A = { [7] = stack + 0x80 },
            Cycles = 4
        };
        scheduler.ProcessPending(state);
        Assert.Equal(new[] { (function, 0x00DFF000u, node) }, starts);

        state.D[0] = 0;
        state.ProgramCounter = CopperStartGraphicsBlitterScheduler.ContinuationAddress;
        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));
        Assert.Equal(
            new[]
            {
                (function, 0x00DFF000u, node),
                (cleanup, 0x00DFF000u, node)
            },
            starts);
        Assert.False(scheduler.TryWait(state.Cycles, out _));

        state.ProgramCounter = CopperStartGraphicsBlitterScheduler.ContinuationAddress;
        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));
        Assert.True(scheduler.TryWait(state.Cycles, out var completionCycle));
        Assert.Equal(state.Cycles, completionCycle);
    }

    [Fact]
    public void CopperStartBlitterSchedulerGuestCallbackCanProgramTheCustomChipEngine()
    {
        var bus = new AmigaBus();
        const uint node = 0x0200;
        const uint function = 0x4000;
        const uint stack = 0x8000;
        const uint source = 0x1000;
        const uint destination = 0x1100;

        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.MapReadOnlyMemory(function, new byte[2]);
        bus.MapWritableMemory(stack, new byte[0x100]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, function);
        bus.WriteWord(source, 0xA55A);
        bus.WriteWord(destination, 0);

        var callbackCount = 0;
        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            (state, entry, continuation) =>
            {
                Assert.Equal(function, entry);
                Assert.Equal(0x00DFF000u, state.A[0]);
                Assert.Equal(node, state.A[1]);

                // Model the classic bltnode callback through the public A0
                // custom-register ABI.  The 1x1 A-only blit is deliberately
                // tiny, but it still exercises the real Agnus blitter and
                // must keep the queue in flight until BBUSY clears.
                var custom = state.A[0];
                var cycle = state.Cycles;
                WritePointer(bus, custom + 0x050, source, ref cycle);
                WritePointer(bus, custom + 0x054, destination, ref cycle);
                bus.WriteWord(custom + 0x040, 0x09F0, ref cycle, AmigaBusAccessKind.CpuDataWrite);
                bus.WriteWord(custom + 0x096, 0x8240, ref cycle, AmigaBusAccessKind.CpuDataWrite);
                bus.WriteWord(custom + 0x058, 0x0041, ref cycle, AmigaBusAccessKind.CpuDataWrite);
                state.Cycles = cycle;

                callbackCount++;
                state.D[0] = 0;
                state.ProgramCounter = continuation;
            });

        Assert.True(scheduler.TrySubmitQueued(node, beamSynchronized: false, beamSync: 0, cycle: 4));
        var state = new M68kCpuState
        {
            A = { [7] = stack + 0x80 },
            Cycles = 4
        };

        scheduler.ProcessPending(state);
        Assert.Equal(1, callbackCount);
        Assert.True(bus.Blitter.Busy);
        Assert.Equal((ushort)0, bus.ReadWord(destination));

        Assert.True(bus.TryInvokeHostGatewayAt(
            CopperStartGraphicsBlitterScheduler.ContinuationAddress,
            state));
        Assert.False(scheduler.TryWait(state.Cycles, out _));

        var predictedCompletion = bus.Blitter.GetPredictedCompletionCycle();
        Assert.NotEqual(long.MaxValue, predictedCompletion);
        bus.AdvanceDmaTo(predictedCompletion);
        state.Cycles = predictedCompletion;
        scheduler.ProcessPending(state);

        Assert.False(bus.Blitter.Busy);
        Assert.Equal((ushort)0xA55A, bus.ReadWord(destination));
        Assert.True(scheduler.TryWait(state.Cycles, out var completionCycle));
        Assert.Equal(state.Cycles, completionCycle);
    }

    [Fact]
    public void CopperStartBlitterSchedulerOwnBlitterAcquiresBeforePreviousBlitFinishes()
    {
        var bus = new AmigaBus();
        const uint source = 0x1000;
        const uint destination = 0x1100;
        bus.MapWritableMemory(source, new byte[2]);
        bus.MapWritableMemory(destination, new byte[2]);
        bus.WriteWord(source, 0xA55A);
        bus.WriteWord(destination, 0);

        // Start a real custom-chip blit owned by the previous graphics user.
        // OwnBlitter's contract is to acquire the software ownership gate
        // while that operation finishes; the caller then uses WaitBlit before
        // touching the registers.  The scheduler must therefore not reject
        // ownership merely because BBUSY is still asserted.
        long hardwareCycle = 0;
        WritePointer(bus, 0x00DFF050, source, ref hardwareCycle);
        WritePointer(bus, 0x00DFF054, destination, ref hardwareCycle);
        bus.WriteWord(
            0x00DFF040,
            0x09F0,
            ref hardwareCycle,
            AmigaBusAccessKind.CpuDataWrite);
        bus.WriteWord(
            0x00DFF096,
            0x8240,
            ref hardwareCycle,
            AmigaBusAccessKind.CpuDataWrite);
        bus.WriteWord(
            0x00DFF058,
            0x0041,
            ref hardwareCycle,
            AmigaBusAccessKind.CpuDataWrite);
        Assert.True(bus.Blitter.Busy);

        var scheduler = new CopperStartGraphicsBlitterScheduler(
            bus,
            static (_, _, _) => { });

        Assert.True(scheduler.TryOwn(hardwareCycle));
        Assert.False(scheduler.TryOwn(hardwareCycle));
        Assert.True(scheduler.TryWait(hardwareCycle, out var completionCycle));
        Assert.True(completionCycle > hardwareCycle);
        Assert.False(bus.Blitter.Busy);
        Assert.Equal((ushort)0xA55A, bus.ReadWord(destination));
        Assert.True(scheduler.TryDisown(completionCycle));
    }

    [Fact]
