    [Fact]
    public void HostBlitterVectorsDeclineWithoutAConnectedScheduler()
    {
        var bus = new AmigaBus();
        const uint node = 0x200;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        foreach (var vector in new[]
        {
            GraphicsLvo.OwnBlitter,
            GraphicsLvo.DisownBlitter,
            GraphicsLvo.WaitBlit
        })
        {
            var state = new M68kCpuState
            {
                Cycles = 33,
                D = { [0] = 0xCAFE_BABEu }
            };
            services.Invoke(state, (int)vector);
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(33, state.Cycles);
        }

        foreach (var vector in new[] { GraphicsLvo.QBlit, GraphicsLvo.QBSBlit })
        {
            var state = new M68kCpuState
            {
                Cycles = 41,
                A = { [1] = node },
                D = { [0] = 0x1357_2468u }
            };
            services.Invoke(state, (int)vector);
            Assert.Equal(0x1357_2468u, state.D[0]);
            Assert.Equal(41, state.Cycles);
        }
    }

    [Fact]
    public void HostBlitterCallbacksClaimOwnershipAndPreserveQueueMetadata()
    {
        var bus = new AmigaBus();
        const uint node = 0x200;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);

        var ownCount = 0;
        var disownCount = 0;
        var waitCount = 0;
        var queued = new List<(uint Address, bool BeamSynchronized, short BeamSync)>();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            ownBlitter: () => ownCount++,
            disownBlitter: () => disownCount++,
            waitBlit: () => waitCount++,
            submitQueuedBlit: (address, beamSynchronized, beamSync) =>
                queued.Add((address, beamSynchronized, beamSync)));

        var own = new M68kCpuState { D = { [0] = 0xFFFF_FFFFu } };
        services.Invoke(own, (int)GraphicsLvo.OwnBlitter);
        var wait = new M68kCpuState { D = { [0] = 0xFFFF_FFFFu } };
        services.Invoke(wait, (int)GraphicsLvo.WaitBlit);
        var disown = new M68kCpuState { D = { [0] = 0xFFFF_FFFFu } };
        services.Invoke(disown, (int)GraphicsLvo.DisownBlitter);

        Assert.Equal(1, ownCount);
        Assert.Equal(1, waitCount);
        Assert.Equal(1, disownCount);
        Assert.Equal(0u, own.D[0]);
        Assert.Equal(0u, wait.D[0]);
        Assert.Equal(0u, disown.D[0]);

        var qblit = new M68kCpuState { A = { [1] = node }, D = { [0] = 0xFFFF_FFFFu } };
        services.Invoke(qblit, (int)GraphicsLvo.QBlit);
        var qbsBlit = new M68kCpuState { A = { [1] = node }, D = { [0] = 0xFFFF_FFFFu } };
        services.Invoke(qbsBlit, (int)GraphicsLvo.QBSBlit);

        Assert.Equal(0u, qblit.D[0]);
        Assert.Equal(0u, qbsBlit.D[0]);
        Assert.Equal(
            new[]
            {
                (node, false, (short)-128),
                (node, true, (short)-128)
            },
            queued);
    }

    [Fact]
    public void HostBlitterStatusCallbacksCanDeclineContentionAndQueueSubmission()
    {
        var bus = new AmigaBus();
        const uint node = 0x200;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);

        var legacyOwnCalls = 0;
        var queued = new List<(uint Address, bool BeamSynchronized, short BeamSync)>();
        var allowOwnership = false;
        var allowQueue = false;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            ownBlitter: () => legacyOwnCalls++,
            tryOwnBlitter: () => allowOwnership,
            tryDisownBlitter: () => allowOwnership,
            tryWaitBlit: () => allowOwnership,
            trySubmitQueuedBlit: (address, beamSynchronized, beamSync) =>
            {
                if (!allowQueue)
                    return false;

                queued.Add((address, beamSynchronized, beamSync));
                return true;
            });

        var own = new M68kCpuState
        {
            Cycles = 17,
            D = { [0] = 0xCAFE_BABEu }
        };
        services.Invoke(own, (int)GraphicsLvo.OwnBlitter);
        Assert.Equal(0xCAFE_BABEu, own.D[0]);
        Assert.Equal(17, own.Cycles);
        Assert.Equal(0, legacyOwnCalls);

        var qblit = new M68kCpuState
        {
            Cycles = 23,
            A = { [1] = node },
            D = { [0] = 0x1357_2468u }
        };
        services.Invoke(qblit, (int)GraphicsLvo.QBlit);
        Assert.Equal(0x1357_2468u, qblit.D[0]);
        Assert.Equal(23, qblit.Cycles);
        Assert.Empty(queued);

        allowOwnership = true;
        allowQueue = true;
        services.Invoke(own, (int)GraphicsLvo.OwnBlitter);
        Assert.Equal(0u, own.D[0]);

        var qbsBlit = new M68kCpuState
        {
            Cycles = 29,
            A = { [1] = node },
            D = { [0] = 0x2468_1357u }
        };
        services.Invoke(qbsBlit, (int)GraphicsLvo.QBSBlit);
        Assert.Equal(0u, qbsBlit.D[0]);
        Assert.Equal(29, qbsBlit.Cycles);
        Assert.Equal(new[] { (node, true, (short)-128) }, queued);
    }

    [Fact]
    public void RegisterAdapterLeavesForeignOwnedDisposalsAndMalformedQueuesUnclaimed()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { D = { [0] = 0xCAFE_BABEu } };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeColorMap));
        Assert.Equal(0u, state.D[0]);

        state.D[0] = unchecked((uint)-1);
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FreeSprite));
        Assert.Equal(unchecked((uint)-1), state.D[0]);

        state.A[0] = 0;
        state.D[0] = 0x1357_2468u;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.DisposeRegion));
        Assert.Equal(0x1357_2468u, state.D[0]);

        state.A[1] = 0;
        state.D[0] = 0x2468_1357u;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.QBlit));
        Assert.Equal(0x2468_1357u, state.D[0]);
    }

    [Fact]
    public void RastPortAndViewInitializationClearGuestStateAndSetDocumentedDefaults()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            memory.TryWriteByte(0x20u + (uint)offset, 0xCC);

        Assert.True(core.InitializeRastPort(0x20));
        Assert.Equal((byte)0xFF, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal(255, core.GetAPen(0x20));
        Assert.Equal(0, core.GetBPen(0x20));
        Assert.Equal(1, core.GetDrawMode(0x20));
        Assert.Equal((ushort)0, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)0, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortPenWidth));
        Assert.Equal((ushort)0, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortPenHeight));

        Assert.True(core.InitializeView(0x180));
        Assert.True(core.InitializeViewPort(0x1A0));
        Assert.Equal(0u, ReadLong(memory, 0x180u + (uint)GraphicsLayouts.ViewLoFCprList));
        Assert.Equal(
            unchecked((ushort)GraphicsLayouts.ViewDefaultDyOffset),
            ReadWord(memory, 0x180u + (uint)GraphicsLayouts.ViewDyOffset));
        Assert.Equal(
            unchecked((ushort)GraphicsLayouts.ViewDefaultDxOffset),
            ReadWord(memory, 0x180u + (uint)GraphicsLayouts.ViewDxOffset));
        Assert.Equal(0u, ReadLong(memory, 0x1A0u + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal((byte)0x24, ReadByte(memory, 0x1A0u + (uint)GraphicsLayouts.ViewPortSpritePriorities));
        Assert.Equal((byte)0, ReadByte(memory, 0x1A0u + (uint)GraphicsLayouts.ViewPortExtendedModes));

        // Structure initialization probes the full guest envelope before
        // clearing it; a truncated tail must not be partially overwritten.
        for (var offset = 0; offset < 4; offset++)
            memory.TryWriteByte(0x3FCu + (uint)offset, 0xA5);
        Assert.False(core.InitializeRastPort(0x3FC));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0x3FC));
        Assert.False(core.InitializeView(0x3FC));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0x3FC));
    }

    [Fact]
    public void ScreenResourceChainPublishesAndRetiresOwnedLinksTransactionally()
    {
        var memory = new FakeMemory(0x4000);
        const uint view = 0x200;
        const uint viewPort = 0x240;
        const uint rasInfo = 0x280;
        const uint bitMap = 0x2A0;
        const uint plane = 0x1000;

        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            memory.TryWriteByte(view + (uint)offset, 0xCC);
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            memory.TryWriteByte(viewPort + (uint)offset, 0xCC);
        for (var offset = 0; offset < GraphicsLayouts.RasInfoSize; offset++)
            memory.TryWriteByte(rasInfo + (uint)offset, 0xCC);
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            memory.TryWriteByte(bitMap + (uint)offset, 0xCC);
        memory.TryWriteByte(plane, 0x5A);

        Assert.True(GraphicsRasterOperations.InitializeScreenResourceChain(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 1,
            width: 320,
            height: 200,
            plane0: plane));
        Assert.Equal(viewPort, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(rasInfo, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(bitMap, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal((ushort)40, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)200, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)1, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(plane, ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));

        Assert.True(GraphicsRasterOperations.TeardownScreenResourceChain(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap));
        Assert.Equal(0u, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(0u, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(0u, ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));

        // The first lifecycle unit is intentionally one-plane. A richer
        // depth must remain available to the future multi-plane owner rather
        // than publishing a chain with missing plane links.
        Assert.False(GraphicsRasterOperations.InitializeScreenResourceChain(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 2,
            width: 320,
            height: 200,
            plane0: plane));
    }

    [Fact]
    public void ScreenResourceChainPublishesAndRetiresCallerOwnedMultiPlaneLinks()
    {
        var memory = new FakeMemory(0x4000);
        const uint view = 0x200;
        const uint viewPort = 0x240;
        const uint rasInfo = 0x280;
        const uint bitMap = 0x2A0;
        var planes = new[] { 0x1000u, 0x1100u, 0x1200u };

        foreach (var (address, size) in new[]
        {
            (view, GraphicsLayouts.ViewSize),
            (viewPort, GraphicsLayouts.ViewPortSize),
            (rasInfo, GraphicsLayouts.RasInfoSize),
            (bitMap, GraphicsLayouts.BitMapSize)
        })
        {
            for (var offset = 0; offset < size; offset++)
                memory.TryWriteByte(address + (uint)offset, 0xCC);
        }
        foreach (var plane in planes)
            memory.TryWriteByte(plane, 0x5A);

        Assert.True(GraphicsRasterOperations.InitializeScreenResourceChainPlanes(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 3,
            width: 320,
            height: 200,
            planes));
        Assert.Equal((byte)3, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapDepth));
        for (var index = 0; index < planes.Length; index++)
        {
            Assert.Equal(
                planes[index],
                ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes +
                    ((uint)index * sizeof(uint))));
            Assert.Equal((byte)0x5A, ReadByte(memory, planes[index]));
        }

        Assert.True(GraphicsRasterOperations.TeardownScreenResourceChainPlanes(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            planes));
        Assert.Equal(0u, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(0u, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        for (var index = 0; index < planes.Length; index++)
        {
            Assert.Equal(
                0u,
                ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes +
                    ((uint)index * sizeof(uint))));
            Assert.Equal((byte)0x5A, ReadByte(memory, planes[index]));
        }

        // A caller-owned plane span may not alias a public screen envelope,
        // even when its starting address is merely an interior field rather
        // than the exact View/ViewPort/RasInfo/BitMap base.
        var aliasedPlane = view + 2u;
        Assert.False(GraphicsRasterOperations.InitializeScreenResourceChainPlanes(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 1,
            width: 320,
            height: 200,
            new[] { aliasedPlane }));
        Assert.Equal(0u, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));

        var wrappingPlane = uint.MaxValue - 10u;
        Assert.False(GraphicsRasterOperations.InitializeScreenResourceChainPlanes(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 1,
            width: 320,
            height: 200,
            new[] { wrappingPlane }));
        Assert.Equal(0u, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));
    }

    [Fact]
    public void ScreenResourceChainMultiPlaneTeardownDeclinesReplacedPlaneLink()
    {
        var memory = new FakeMemory(0x4000);
        const uint view = 0x200;
        const uint viewPort = 0x240;
        const uint rasInfo = 0x280;
        const uint bitMap = 0x2A0;
        var planes = new[] { 0x1000u, 0x1100u, 0x1200u };

        Assert.True(GraphicsRasterOperations.InitializeScreenResourceChainPlanes(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 3,
            width: 17,
            height: 2,
            planes));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            0x1800));

        Assert.False(GraphicsRasterOperations.TeardownScreenResourceChainPlanes(
            memory,
            view,
            viewPort,
            rasInfo,
            bitMap,
            planes));
        Assert.Equal(viewPort, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(rasInfo, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(bitMap, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(0x1800u, ReadLong(
            memory,
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint)));
    }

    [Fact]
    public void ScreenResourceChainRejectsOverlappingPublicEnvelopeSpansBeforeMutation()
    {
        var memory = new FakeMemory(0x4000);
        const uint view = 0x200;
        const uint overlappingViewPort = view + 8u;
        const uint rasInfo = 0x280;
        const uint bitMap = 0x2A0;
        const uint plane = 0x1000;

        foreach (var address in new[] { view, overlappingViewPort, rasInfo, bitMap })
        {
            for (var offset = 0; offset < 0x40; offset++)
                memory.TryWriteByte(address + (uint)offset, 0xA5);
        }
        memory.TryWriteByte(plane, 0x5A);
        var beforeView = ReadBytes(memory, view, GraphicsLayouts.ViewSize);
        var beforeViewPort = ReadBytes(
            memory,
            overlappingViewPort,
            GraphicsLayouts.ViewPortSize);
        var beforeRasInfo = ReadBytes(memory, rasInfo, GraphicsLayouts.RasInfoSize);
        var beforeBitMap = ReadBytes(memory, bitMap, GraphicsLayouts.BitMapSize);

        Assert.False(GraphicsRasterOperations.InitializeScreenResourceChain(
            memory,
            view,
            overlappingViewPort,
            rasInfo,
            bitMap,
            depth: 1,
            width: 320,
            height: 200,
            plane0: plane));

        Assert.Equal(beforeView, ReadBytes(memory, view, GraphicsLayouts.ViewSize));
        Assert.Equal(
            beforeViewPort,
            ReadBytes(memory, overlappingViewPort, GraphicsLayouts.ViewPortSize));
        Assert.Equal(beforeRasInfo, ReadBytes(memory, rasInfo, GraphicsLayouts.RasInfoSize));
        Assert.Equal(beforeBitMap, ReadBytes(memory, bitMap, GraphicsLayouts.BitMapSize));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));
    }

    [Fact]
    public void ScreenResourceChainRestoresAllEnvelopesWhenLinkPublicationFails()
    {
        var backing = new FakeMemory(0x4000);
        const uint view = 0x200;
        const uint viewPort = 0x240;
        const uint rasInfo = 0x280;
        const uint bitMap = 0x2A0;
        const uint plane = 0x1000;
        var before = new Dictionary<uint, byte[]>();
        foreach (var (address, size) in new[]
        {
            (view, GraphicsLayouts.ViewSize),
            (viewPort, GraphicsLayouts.ViewPortSize),
            (rasInfo, GraphicsLayouts.RasInfoSize),
            (bitMap, GraphicsLayouts.BitMapSize)
        })
        {
            var bytes = new byte[size];
            for (var offset = 0; offset < size; offset++)
            {
                bytes[offset] = (byte)(0x40 + (offset & 0x1F));
                backing.TryWriteByte(address + (uint)offset, bytes[offset]);
            }
            before[address] = bytes;
        }

        var rejecting = new RejectingWriteMemory(
            backing,
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo + sizeof(uint));
        Assert.False(GraphicsRasterOperations.InitializeScreenResourceChain(
            rejecting,
            view,
            viewPort,
            rasInfo,
            bitMap,
            depth: 1,
            width: 320,
            height: 200,
            plane0: plane));

        foreach (var (address, bytes) in before)
            for (var offset = 0; offset < bytes.Length; offset++)
                Assert.Equal(bytes[offset], ReadByte(backing, address + (uint)offset));
    }

    [Fact]
    public void AllocatorBackedScreenResourceChainOwnsAndClosesAllEnvelopes()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new SequenceAddressAllocator(0x200, 0x240, 0x280, 0x2A0);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint plane = 0x1000;
        Assert.True(memory.TryWriteByte(plane, 0x6B));

        Assert.True(core.TryAllocateScreenResourceChain(
            depth: 1,
            width: 320,
            height: 200,
            plane0: plane,
            out var allocation));
        Assert.Equal(0x200u, allocation.View);
        Assert.Equal(0x240u, allocation.ViewPort);
        Assert.Equal(0x280u, allocation.RasInfo);
        Assert.Equal(0x2A0u, allocation.BitMap);
        Assert.True(core.IsOwnedScreenResourceChain(allocation.View));
        Assert.Equal(allocation.ViewPort, ReadLong(memory, allocation.View + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(allocation.RasInfo, ReadLong(memory, allocation.ViewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(allocation.BitMap, ReadLong(memory, allocation.RasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(plane, ReadLong(memory, allocation.BitMap + (uint)GraphicsLayouts.BitMapPlanes));

        // A replaced link is not this owner's close path.  The chain and its
        // allocator spans stay live until the exact topology is restored.
        Assert.True(memory.TryWriteLong(
            allocation.ViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0));
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.FreeScreenResourceChain(allocation.View));
        Assert.True(core.IsOwnedScreenResourceChain(allocation.View));
        Assert.Equal(0, allocator.FreeCount);
        Assert.True(memory.TryWriteLong(
            allocation.ViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            allocation.RasInfo));

        Assert.Equal(
            GraphicsRasterOperations.Success,
            core.FreeScreenResourceChain(allocation.View));
        Assert.False(core.IsOwnedScreenResourceChain(allocation.View));
        Assert.Equal(4, allocator.FreeCount);
        Assert.Equal(0u, ReadLong(memory, allocation.View + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(0u, ReadLong(memory, allocation.ViewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(0u, ReadLong(memory, allocation.RasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal((byte)0x6B, ReadByte(memory, plane));
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.FreeScreenResourceChain(allocation.View));
    }

    [Fact]
    public void AllocatorBackedScreenResourceChainCanCloseCallerOwnedMultiPlaneTable()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new SequenceAddressAllocator(0x200, 0x240, 0x280, 0x2A0);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var planes = new[] { 0x1000u, 0x1100u, 0x1200u };
        foreach (var plane in planes)
            Assert.True(memory.TryWriteByte(plane, 0x6B));

        Assert.True(core.TryAllocateScreenResourceChainPlanes(
            depth: 3,
            width: 17,
            height: 2,
            planes,
            out var allocation));
        Assert.False(allocation.OwnsPlane);
        Assert.Equal(planes[0], allocation.Plane0);
        Assert.Equal(planes, allocation.PlanePointers);
        for (var index = 0; index < planes.Length; index++)
        {
            Assert.Equal(
                planes[index],
                ReadLong(memory, allocation.BitMap +
                    (uint)GraphicsLayouts.BitMapPlanes +
                    ((uint)index * sizeof(uint))));
            Assert.Equal((byte)0x6B, ReadByte(memory, planes[index]));
        }

        Assert.True(memory.TryWriteLong(
            allocation.BitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            0x1800));
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.FreeScreenResourceChain(allocation.View));
        Assert.True(core.IsOwnedScreenResourceChain(allocation.View));
        Assert.Equal(0, allocator.FreeCount);
        Assert.True(memory.TryWriteLong(
            allocation.BitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            planes[1]));

        Assert.Equal(
            GraphicsRasterOperations.Success,
            core.FreeScreenResourceChain(allocation.View));
        Assert.Equal(4, allocator.FreeCount);
        Assert.False(core.IsOwnedScreenResourceChain(allocation.View));
        foreach (var plane in planes)
            Assert.Equal((byte)0x6B, ReadByte(memory, plane));
    }

