    [Fact]
    public void AllocatorBackedScreenResourceChainRollsBackAllEnvelopesOnAllocationFailure()
    {
        var memory = new FakeMemory(0x4000);
        // The fourth envelope has no address.  The first three allocations
        // must be returned in reverse order without publishing a link.
        var allocator = new SequenceAddressAllocator(0x200, 0x240, 0x280);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        Assert.False(core.TryAllocateScreenResourceChain(
            depth: 1,
