        Assert.Equal(default, allocation);
        Assert.Equal(3, allocator.FreeCount);
        Assert.False(core.IsOwnedScreenResourceChain(0x200));
        Assert.Equal(0u, ReadLong(memory, 0x200u + (uint)GraphicsLayouts.ViewViewPort));
    }

