        Assert.Equal(0x540u, allocation.RasInfo);
        Assert.Equal(
            allocation.Screen + (uint)GraphicsLayouts.ScreenViewPort,
            allocation.ViewPort);
        Assert.Equal(
            allocation.Screen + (uint)GraphicsLayouts.ScreenRastPort,
            allocation.RastPort);
        Assert.Equal(
            allocation.Screen + (uint)GraphicsLayouts.ScreenBitMap,
            allocation.BitMap);
        Assert.Equal(allocation.ViewPort, ReadLong(
            memory,
            allocation.View + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(allocation.RasInfo, ReadLong(
            memory,
            allocation.ViewPort + (uint)GraphicsLayouts.ViewPortRasInfo));
        Assert.Equal(allocation.BitMap, ReadLong(
            memory,
