        Assert.Equal(allocation.BitMap, ReadLong(
            memory,
            allocation.RastPort + (uint)GraphicsLayouts.RastPortBitMap));
        Assert.Equal(320, ReadWord(
            memory,
            allocation.Screen + (uint)GraphicsLayouts.ScreenWidth));
        Assert.Equal(200, ReadWord(
            memory,
            allocation.Screen + (uint)GraphicsLayouts.ScreenHeight));
        Assert.Equal(
            GraphicsRasterOperations.Success,
            core.FreeScreenPrefix(allocation.Screen));
        Assert.Equal(3, allocator.FreeCount);
        Assert.False(core.IsOwnedScreenPrefix(allocation.Screen));
        Assert.Equal(0u, ReadLong(
            memory,
            allocation.View + (uint)GraphicsLayouts.ViewViewPort));
        Assert.Equal(0u, ReadLong(
            memory,
            allocation.RasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void AllocatorBackedScreenPrefixCanCloseCallerOwnedMultiPlaneTable()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new SequenceAddressAllocator(0x200, 0x500, 0x540);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var planes = new[] { 0x1800u, 0x1900u, 0x1A00u };
        foreach (var plane in planes)
            Assert.True(memory.TryWriteByte(plane, 0x4D));

        Assert.True(core.TryAllocateScreenPrefixPlanes(
            depth: 3,
            width: 17,
            height: 2,
            planes,
            out var allocation));
        Assert.False(allocation.OwnsPlane);
        Assert.Equal(planes[0], allocation.Plane0);
        Assert.Equal(planes, allocation.PlanePointers);
        for (var index = 0; index < planes.Length; index++)
        {
            Assert.Equal(
                planes[index],
                ReadLong(memory, allocation.BitMap +
                    (uint)GraphicsLayouts.BitMapPlanes +
                    ((uint)index * sizeof(uint))));
            Assert.Equal((byte)0x4D, ReadByte(memory, planes[index]));
        }

        Assert.True(memory.TryWriteLong(
            allocation.BitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            0x1C00));
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.FreeScreenPrefix(allocation.Screen));
        Assert.True(core.IsOwnedScreenPrefix(allocation.Screen));
        Assert.Equal(0, allocator.FreeCount);
        Assert.True(memory.TryWriteLong(
            allocation.BitMap + (uint)GraphicsLayouts.BitMapPlanes + sizeof(uint),
            planes[1]));

        Assert.Equal(
            GraphicsRasterOperations.Success,
            core.FreeScreenPrefix(allocation.Screen));
        Assert.Equal(3, allocator.FreeCount);
        Assert.False(core.IsOwnedScreenPrefix(allocation.Screen));
        foreach (var plane in planes)
            Assert.Equal((byte)0x4D, ReadByte(memory, plane));
    }

