    [Fact]
    public void StructureInitializationRestoresGuestBytesWhenAClearWriteFails()
    {
        var backing = new FakeMemory(0x400);
        const uint view = 0x180;
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.True(backing.TryWriteByte(view + (uint)offset, 0xCC));

        // The portable clear preflights the complete range, then restores the
        // original snapshot if a provider rejects a later byte write.
        var rejecting = new RejectingWriteMemory(backing, view + 2, view + 3);
        var core = CreateCore(rejecting);

        Assert.False(core.InitializeView(view));
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, view + (uint)offset));
    }

    [Fact]
    public void StructureInitializersRejectNullBasesBeforeGuestMemoryAccess()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);

        // A zero guest address is the native NULL pointer, even when a host
        // memory adapter happens to expose byte zero.  Every public
        // initializer must leave that ownership boundary to Kickstart or a
        // provider instead of clearing the low page.
        Assert.False(core.InitializeRastPort(0));
        Assert.False(core.InitializeView(0));
        Assert.False(core.InitializeViewPort(0));
        Assert.False(core.InitializeRasInfo(0));
        Assert.False(core.InitializeBitMap(0, 1, 16, 1));
        Assert.False(core.InitializeArea(0, 0x100, 1));
        Assert.False(core.InitializeTmpRas(0, 0x100, 4));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var cases = new[]
        {
            (GraphicsLvo.InitRastPort, new M68kCpuState { D = { [0] = 0x1111_2222u }, A = { [1] = 0 } }),
            (GraphicsLvo.InitView, new M68kCpuState { D = { [0] = 0x2222_3333u }, A = { [1] = 0 } }),
            (GraphicsLvo.InitVPort, new M68kCpuState { D = { [0] = 0x3333_4444u }, A = { [0] = 0 } }),
            (GraphicsLvo.InitBitMap, new M68kCpuState { D = { [0] = 1, [1] = 16, [2] = 1 }, A = { [0] = 0 } }),
            (GraphicsLvo.InitArea, new M68kCpuState { D = { [0] = 1 }, A = { [0] = 0, [1] = 0x100 } }),
            (GraphicsLvo.InitTmpRas, new M68kCpuState { D = { [0] = 4 }, A = { [0] = 0, [1] = 0x100 } })
        };

        foreach (var (lvo, state) in cases)
        {
            var originalD0 = state.D[0];
            var originalCycles = state.Cycles;
            Assert.False(adapter.TryInvoke(state, (int)lvo));
            Assert.Equal(originalD0, state.D[0]);
            Assert.Equal(originalCycles, state.Cycles);
        }
    }

    [Fact]
    public void InitViewRestoresGuestBytesWhenDefaultOriginWriteFails()
    {
        var backing = new FakeMemory(0x400);
        const uint view = 0x180;
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.True(backing.TryWriteByte(view + (uint)offset, 0xCC));

        // Byte clears are allowed, but the final default-origin word is
        // rejected.  InitView must restore both the cleared envelope and the
        // first default word it already published.
        var rejecting = new RejectingWordWriteMemory(
            backing,
            view + (uint)GraphicsLayouts.ViewDxOffset);
        var core = CreateCore(rejecting);

        Assert.False(core.InitializeView(view));
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, view + (uint)offset));
    }

    [Fact]
    public void InitViewRestoresGuestBytesAfterPartialDefaultOriginPublication()
    {
        var backing = new FakeMemory(0x400);
        const uint view = 0x180;
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.True(backing.TryWriteByte(view + (uint)offset, 0xCC));

        // The first default-origin WORD is accepted, then the second one
        // publishes only its high byte before the guest bridge rejects the
        // access.  InitView must restore the entire cleared envelope
        // byte-wise, leaving a clean retry available to the native/provider
        // path rather than exposing a half-default View.
        var memory = new PartialThenRejectWordWriteMemory(backing)
        {
            PartialWordAddress = view + (uint)GraphicsLayouts.ViewDxOffset
        };
        var core = CreateCore(memory);

        Assert.False(core.InitializeView(view));
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, view + (uint)offset));

        memory.PartialWordAddress = null;
        Assert.True(core.InitializeView(view));
        Assert.Equal(
            unchecked((ushort)GraphicsLayouts.ViewDefaultDyOffset),
            ReadWord(backing, view + (uint)GraphicsLayouts.ViewDyOffset));
        Assert.Equal(
            unchecked((ushort)GraphicsLayouts.ViewDefaultDxOffset),
            ReadWord(backing, view + (uint)GraphicsLayouts.ViewDxOffset));
    }

    [Fact]
    public void InitVPortRestoresGuestBytesWhenDefaultSpritePriorityWriteFails()
    {
        var backing = new FakeMemory(0x400);
        const uint viewPort = 0x180;
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            Assert.True(backing.TryWriteByte(viewPort + (uint)offset, 0xCC));

        // InitVPort clears the complete public descriptor before publishing
        // its sole nonzero default.  A refused final byte must not leave the
        // caller with a cleared but invalid ViewPort envelope.
        var memory = new FailingByteWriteMemory(backing);
        memory.FailOnNextByteWrite(GraphicsLayouts.ViewPortSize + 1);
        var core = CreateCore(memory);

        Assert.False(core.InitializeViewPort(viewPort));
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, viewPort + (uint)offset));

        Assert.True(core.InitializeViewPort(viewPort));
        Assert.Equal(
            GraphicsLayouts.ViewPortDefaultSpritePriorities,
            ReadByte(backing, viewPort + (uint)GraphicsLayouts.ViewPortSpritePriorities));
    }

    [Fact]
    public void InitRastPortCanPublishTheGuestDefaultFontAndCachedMetrics()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        var metrics = new GraphicsFontMetrics(
            height: 9,
            width: 7,
            baseline: 6,
            spacing: 1,
            style: 2,
            boldSmear: 2,
            flags: 0);

        Assert.True(core.InitializeRastPort(0x20, 0x300, metrics));
        Assert.Equal(0x300u, ReadLong(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)9, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)7, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)6, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextBaseline));
        // InitRastPort clears the structure before selecting the default
        // font.  SetFont leaves the caller-owned TxSpacing word untouched,
        // so it remains the cleared zero even when backend metadata carries
        // a non-zero compatibility value.
        Assert.Equal((ushort)0, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextSpacing));
        Assert.Equal((byte)0, ReadByte(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));
    }

    [Fact]
