    [Fact]
    public void InitBitMapRejectsZeroAndMoreThanEightPlanesWithoutMutatingGuestState()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint bitmap = 0x120;
        var original = Enumerable.Range(0, GraphicsLayouts.BitMapSize)
            .Select(offset => (byte)(0xA0 + offset))
            .ToArray();
        for (var offset = 0; offset < original.Length; offset++)
            Assert.True(memory.TryWriteByte(bitmap + (uint)offset, original[offset]));

        Assert.False(core.InitializeBitMap(bitmap, 0, 320, 200));
        Assert.False(core.InitializeBitMap(bitmap, 9, 320, 200));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = bitmap },
            D = { [0] = 9, [1] = 320, [2] = 200, [3] = 0xDEAD_BEEFu }
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitBitMap));
        Assert.Equal(9u, state.D[0]);
        Assert.Equal(0xDEAD_BEEFu, state.D[3]);

        for (var offset = 0; offset < original.Length; offset++)
            Assert.Equal(original[offset], ReadByte(memory, bitmap + (uint)offset));
    }

    [Fact]
    public void HostRegisterAdapterLeavesMalformedViewLifecycleCallsUnclaimed()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint malformed = 0x3FC;

        for (var offset = 0; offset < 4; offset++)
            Assert.True(memory.TryWriteByte(malformed + (uint)offset, 0xA5));

        var state = new M68kCpuState
        {
            A = { [0] = malformed, [1] = malformed },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 123
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitView));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(123, state.Cycles);
        Assert.Equal((byte)0xA5, ReadByte(memory, malformed));

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitVPort));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(123, state.Cycles);
        Assert.Equal((byte)0xA5, ReadByte(memory, malformed));

        // LoadView is void on success, but the portable adapter must leave a
        // malformed View unclaimed so native Kickstart or another provider
        // can handle it without observing a fabricated display publication.
        state.A[1] = malformed;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.LoadView));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(123, state.Cycles);
    }

    [Fact]
    public void HostRegisterAdapterLeavesOddViewLifecycleAddressesForNativeOwnership()
    {
        var memory = new FakeMemory(0x500);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint oddView = 0x21;
        const uint oddViewPort = 0x121;
        const uint oddRasInfo = 0x221;

        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            Assert.True(memory.TryWriteByte(oddView + (uint)offset, 0xA5));
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            Assert.True(memory.TryWriteByte(oddViewPort + (uint)offset, 0xB6));
        for (var offset = 0; offset < GraphicsLayouts.RasInfoSize; offset++)
            Assert.True(memory.TryWriteByte(oddRasInfo + (uint)offset, 0xC7));

        var state = new M68kCpuState
        {
            A = { [0] = oddViewPort, [1] = oddView },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 137
        };

        Assert.False(core.InitializeView(oddView));
        Assert.False(core.InitializeViewPort(oddViewPort));
        Assert.False(core.InitializeRasInfo(oddRasInfo));
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitView));
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitVPort));
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.LoadView));

        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(137, state.Cycles);
        Assert.Equal((byte)0xA5, ReadByte(memory, oddView));
        Assert.Equal((byte)0xB6, ReadByte(memory, oddViewPort));
        Assert.Equal((byte)0xC7, ReadByte(memory, oddRasInfo));
    }

    [Fact]
    public void HostRegisterAdapterLeavesMalformedAuxiliaryInitializersUnclaimed()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu, [1] = 17, [2] = 9 },
            Cycles = 321
        };

        // The public BitMap envelope crosses the end of guest memory.
        state.A[0] = 0x3E0;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitBitMap));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(321, state.Cycles);

        // The AreaInfo envelope is mapped. InitArea publishes the caller-owned
        // vector/flag descriptor without probing its currently unmapped span;
        // AreaMove/AreaDraw/AreaEllipse own the strict consumer checks.
        state.A[0] = 0x100;
        state.A[1] = 0x3FE;
        state.D[0] = 1;
        state.D[1] = 0x1357_2468u;
        state.Cycles = 322;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitArea));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(322, state.Cycles);

        // The temporary-raster descriptor itself is truncated.
        state.A[0] = 0x3FC;
        state.A[1] = 0x100;
        state.D[0] = 0x20;
        state.Cycles = 323;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitTmpRas));
        Assert.Equal(0x20u, state.D[0]);
        Assert.Equal(323, state.Cycles);

        // RastPort initialization follows the same provider ownership rule.
        state.A[1] = 0x3FC;
        state.D[0] = 0xCAFE_BABEu;
        state.Cycles = 324;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitRastPort));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(324, state.Cycles);

        // A mapped but odd RastPort is a native 68k address-error case, not
        // a host byte-clear opportunity.
        const uint oddRastPort = 0x121;
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            Assert.True(memory.TryWriteByte(oddRastPort + (uint)offset, 0xD4));
        state.A[1] = oddRastPort;
        state.D[0] = 0xFACE_CAFEu;
        state.Cycles = 325;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitRastPort));
        Assert.Equal(0xFACE_CAFEu, state.D[0]);
        Assert.Equal(325, state.Cycles);
        Assert.Equal((byte)0xD4, ReadByte(memory, oddRastPort));
    }

    [Fact]
    public void RastPortPenAndModeSettersFailAtomicallyOnTruncatedPatternState()
    {
        // FgPen is in range, but linpatcnt at 0x1E is outside this guest
        // allocation.  The setter must not publish a new pen before the
        // associated line-pattern state can be updated.
        var memory = new FakeMemory(0x1E);
        Assert.True(memory.TryWriteByte((uint)GraphicsLayouts.RastPortFgPen, 3));
        var core = CreateCore(memory);

        Assert.Equal(-1, core.SetAPen(0, 7));
        Assert.Equal((byte)3, ReadByte(memory, (uint)GraphicsLayouts.RastPortFgPen));

        Assert.True(memory.TryWriteByte((uint)GraphicsLayouts.RastPortBgPen, 4));
        Assert.True(memory.TryWriteByte((uint)GraphicsLayouts.RastPortDrawMode, 1));
        Assert.Equal(-1, core.SetABPenDrMd(0, 7, 8, 2));
        Assert.Equal((byte)3, ReadByte(memory, (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)4, ReadByte(memory, (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)1, ReadByte(memory, (uint)GraphicsLayouts.RastPortDrawMode));
    }

    [Fact]
    public void RasInfoInitializationClearsTheGuestChainNodeAndRejectsPartialRanges()
    {
        var memory = new FakeMemory(0x200);
        var core = CreateCore(memory);
        const uint rasInfo = 0x100;

        for (var offset = 0; offset < GraphicsLayouts.RasInfoSize; offset++)
            Assert.True(memory.TryWriteByte(rasInfo + (uint)offset, 0xA5));

        Assert.True(core.InitializeRasInfo(rasInfo));
        for (var offset = 0; offset < GraphicsLayouts.RasInfoSize; offset++)
            Assert.Equal((byte)0, ReadByte(memory, rasInfo + (uint)offset));

        const uint malformed = 0x1F8;
        Assert.True(memory.TryWriteByte(malformed, 0x5A));
        Assert.False(core.InitializeRasInfo(malformed));
        Assert.Equal((byte)0x5A, ReadByte(memory, malformed));
    }

    [Fact]
    public void TmpRasInitializationPublishesGuestBufferAndSizeWithoutReadingIt()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint tmpRas = 0x100;
        const uint buffer = 0x180;

        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            memory.TryWriteByte(tmpRas + (uint)offset, 0xA5);
        Assert.True(core.InitializeTmpRas(tmpRas, buffer, 0x20));
        Assert.Equal(buffer, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(0x20u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));

        Assert.True(core.InitializeTmpRas(tmpRas, 0x3F0, 0x20));
        Assert.Equal(0x3F0u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(0x20u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));
        // The native initializer does not dereference an empty backing span;
        // the zero-capacity form is therefore valid, including a NULL buffer.
        Assert.True(core.InitializeTmpRas(tmpRas, 0, 0));
        Assert.Equal(0u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(0u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));
        Assert.False(core.InitializeTmpRas(0x3FC, buffer, 0x20));
    }

    [Fact]
    public void InitTmpRasPublishesAnUnmappedBackingSpanWithoutDereferencingIt()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint tmpRas = 0x100;
        const uint unmappedBuffer = 0xF000_0000;
        const uint byteCount = 0x2000;

        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            Assert.True(memory.TryWriteByte(tmpRas + (uint)offset, 0xA5));

        // InitTmpRas only publishes the caller-owned pointer/size pair.  The
        // later AreaEnd/Flood/Text consumers own temporary-storage capacity
        // checks, so an unmapped backing span must not steal this constructor
        // from the native/provider implementation.
        Assert.True(core.InitializeTmpRas(tmpRas, unmappedBuffer, byteCount));
        Assert.Equal(
            unmappedBuffer,
            ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(
            byteCount,
            ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = tmpRas, [1] = unmappedBuffer },
            D = { [0] = byteCount, [1] = 0xCAFE_BABEu },
            Cycles = 271
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitTmpRas));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(271, state.Cycles);
    }

    [Fact]
    public void InitTmpRasZeroCapacityAcceptsANullBufferThroughTheRegisterGateway()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint tmpRas = 0x100;

        var state = new M68kCpuState
        {
            A = { [0] = tmpRas, [1] = 0 },
            D = { [0] = 0 },
            Cycles = 317
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitTmpRas));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(317, state.Cycles);
        Assert.Equal(0u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(0u, ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));
    }

    [Fact]
    public void InitTmpRasRestoresGuestBytesWhenTheSizeWriteFails()
    {
        var backing = new FakeMemory(0x400);
        const uint tmpRas = 0x300;
        const uint buffer = 0x180;
        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            Assert.True(backing.TryWriteByte(tmpRas + (uint)offset, (byte)(offset * 5 + 3)));

        var rejecting = new RejectingWriteMemory(
            backing,
            tmpRas + (uint)GraphicsLayouts.TmpRasByteCount,
            tmpRas + (uint)GraphicsLayouts.TmpRasByteCount + 4u);
        var core = CreateCore(rejecting);

        Assert.False(core.InitializeTmpRas(tmpRas, buffer, 0x20));
        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            Assert.Equal((byte)(offset * 5 + 3), ReadByte(backing, tmpRas + (uint)offset));
    }

    [Fact]
    public void InitTmpRasPublishesAnUnstageableMaximumSpanWithoutWalkingIt()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint tmpRas = 0x100;
        const uint buffer = 0x200;

        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            Assert.True(memory.TryWriteByte(tmpRas + (uint)offset, 0xA5));

        // The descriptor is readable, but this valid ULONG byte count has an
        // intentionally unmapped backing span.  The resident initializer
        // stores the pair without walking that span; consumer operations own
        // the later capacity/readability decision.
        Assert.True(core.InitializeTmpRas(
            tmpRas,
            buffer,
            uint.MaxValue));
        Assert.Equal(
            buffer,
            ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(
            uint.MaxValue,
            ReadLong(memory, tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState();
        state.A[0] = tmpRas;
        state.A[1] = buffer;
        state.D[0] = uint.MaxValue;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitTmpRas));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void InitBitMapSetsGeometryAndPreservesReusedPlanes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitMap = 0x1200;
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x1800));
        Assert.True(core.InitializeBitMap(bitMap, 3, 17, 9));
        Assert.Equal((ushort)4, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)9, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x08, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)3, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal(0x1800u, ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        // InitBitMap owns only the fixed eight-byte header.  A header ending
        // exactly at the guest-memory boundary is valid even when the
        // caller-owned Planes[] table is currently unmapped.
        Assert.True(core.InitializeBitMap(0x1FF8, 1, 16, 1));
        Assert.Equal((ushort)2, ReadWord(memory, 0x1FF8));
    }

    [Fact]
    public void InitBitMapAcceptsAPlaneTableTruncatedToTheDeclaredDepth()
    {
        const uint bitMap = 0x100;
        const int depth = 1;
        var compactBytes = GraphicsLayouts.BitMapPlanes + (depth * sizeof(uint));
        var memory = new FakeMemory(checked((int)(bitMap + (uint)compactBytes)));
        var core = CreateCore(memory);

        // A classic BitMap may end immediately after the declared Planes[0]
        // entry.  The initializer must not probe the unused Planes[1..7]
        // tail, while the caller-owned plane link itself remains intact.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x0C00));
        Assert.True(core.InitializeBitMap(bitMap, (byte)depth, 17, 9));
        Assert.Equal((ushort)4, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)9, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x08, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal(0x0C00u, ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes));
    }

    [Fact]
    public void InitBitMapPublishesGeometryWithoutReadingAnUnmappedPlaneTable()
    {
        const uint bitMap = 0x100;
