        // resident initializer leaves caller-owned Planes[] untouched, so an
        // unmapped plane table must not make this constructor decline.
        var memory = new FakeMemory(checked((int)(bitMap + (uint)GraphicsLayouts.BitMapPlanes)));
        var core = CreateCore(memory);

        for (var offset = 0; offset < GraphicsLayouts.BitMapPlanes; offset++)
            Assert.True(memory.TryWriteByte(bitMap + (uint)offset, 0xA5));

        Assert.True(core.InitializeBitMap(bitMap, 3, 17, 9));
        Assert.Equal((ushort)4, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)9, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x08, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal((byte)3, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.Equal((ushort)0, ReadWord(memory, bitMap + 6u));
    }

    [Fact]
    public void InitBitMapGatewayPublishesGeometryWithAnUnmappedPlaneTable()
