    [Fact]
    public void InitBitMapGatewayClaimsTheCompactDeclaredDepthEnvelope()
    {
        const uint bitMap = 0x100;
        const int depth = 2;
        var compactBytes = GraphicsLayouts.BitMapPlanes + (depth * sizeof(uint));
        var memory = new FakeMemory(checked((int)(bitMap + (uint)compactBytes)));
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x0C00));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            0x0E00));

        var state = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = (uint)depth, [1] = 31, [2] = 11 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitBitMap));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)4, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)11, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal(0x0C00u, ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes));
        Assert.Equal(0x0E00u, ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u));
    }

    [Fact]
    public void GetBitMapAttrAcceptsACompactStandardHeaderAtTheGuestMemoryEnd()
    {
        var memory = new FakeMemory(0x3FC);
        var core = CreateCore(memory);
        const uint bitMap = 0x3F0;

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            9));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            0x08));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x100));

        // The standard marker is retained, but only the depth-one plane link
        // exists in guest memory.  GetBitMapAttr must use the compact fallback
        // instead of demanding the unused eight-plane tail.
        Assert.Equal(9u, core.GetBitMapAttr(bitMap, 0));
        Assert.Equal(1u, core.GetBitMapAttr(bitMap, 4));
        Assert.Equal(16u, core.GetBitMapAttr(bitMap, 8));
        Assert.Equal(8u, core.GetBitMapAttr(bitMap, 12));
    }

    [Fact]
    public void ChangeVPBitMapRejectsNullBitmapEvenWhenAddressZeroLooksLikeAHeader()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint viewPort = 0x100;
        const uint rasInfo = 0x180;
        const uint currentBitMap = 0x200;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap));
        Assert.True(memory.TryWriteWord(
            currentBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            currentBitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            currentBitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));

        // Deliberately make guest address zero look like a geometry-only
        // bitmap.  A NULL BitMap is still the absent association sentinel;
        // the portable reader must not reinterpret mapped address zero as a
        // publishable replacement surface.
        Assert.True(memory.TryWriteWord(
            (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            (uint)GraphicsLayouts.BitMapDepth,
            1));

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.ChangeViewPortBitMap(viewPort, 0));
        Assert.Equal(
            currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 431,
            ProgramCounter = 0x0012_40B1
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(431, state.Cycles);
        Assert.Equal(
            currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void ChangeVPBitMapRejectsNullViewPortEvenWhenAddressZeroLooksLikeAnEnvelope()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint rasInfo = 0x100;
        const uint currentBitMap = 0x180;
        const uint nextBitMap = 0x200;

        // Deliberately make guest address zero look like a complete standard
        // ViewPort/RasInfo envelope.  A NULL ViewPort is still the absent
        // display-object sentinel and must not become a publishable link just
        // because page zero is mapped by this host memory adapter.
        Assert.True(memory.TryWriteLong(
            (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteByte(
            (uint)GraphicsLayouts.ViewPortExtendedModes,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap));
        Assert.True(memory.TryWriteWord(
            currentBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteByte(
            currentBitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteWord(
            nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteByte(
            nextBitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.ChangeViewPortBitMap(0, nextBitMap));
        Assert.Equal(
            currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = nextBitMap },
            D = { [0] = 0xFACE_CAFEu },
            Cycles = 439,
            ProgramCounter = 0x0012_40C1
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(0xFACE_CAFEu, state.D[0]);
        Assert.Equal(439, state.Cycles);
        Assert.Equal(
            currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void InitBitMapRestoresGuestBytesWhenAPlaneWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        const uint bitMap = 0x1200;
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            Assert.True(backing.TryWriteByte(bitMap + (uint)offset, (byte)(offset * 3 + 1)));

        // InitBitMap publishes geometry and flags as one guest update.  A
        // rejected flag write must not expose the earlier geometry fields to
        // a native/provider caller; caller-owned plane links are untouched.
        var rejecting = new RejectingWriteMemory(
            backing,
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            bitMap + (uint)GraphicsLayouts.BitMapFlags + 1u);
        var core = CreateCore(rejecting);

        Assert.False(core.InitializeBitMap(bitMap, 3, 17, 9));
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            Assert.Equal((byte)(offset * 3 + 1), ReadByte(backing, bitMap + (uint)offset));
    }

    [Fact]
    public void AreaInfoInitializesFiveByteVectorStorageAndClosesPreviousPolygon()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 4));
        Assert.Equal(buffer, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(buffer, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(buffer + 16, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));
        Assert.Equal(buffer + 16, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)4, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount));

        Assert.Equal(0, core.AreaMove(rastPort, (short)1, (short)2));
        Assert.Equal((ushort)1, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)1, ReadWord(memory, buffer));
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 2));
        Assert.Equal((byte)0, ReadByte(memory, buffer + 16));

        Assert.Equal(0, core.AreaDraw(rastPort, 4, 5));
        Assert.Equal((ushort)2, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)4, ReadWord(memory, buffer + 4));
        Assert.Equal((ushort)5, ReadWord(memory, buffer + 6));
        Assert.Equal((byte)1, ReadByte(memory, buffer + 17));

        // AreaMove closes (1,2), then starts the next polygon at (8,9).
        Assert.Equal(0, core.AreaMove(rastPort, 8, 9));
        Assert.Equal((ushort)4, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 8));
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 10));
        Assert.Equal((byte)2, ReadByte(memory, buffer + 18));
        Assert.Equal((ushort)8, ReadWord(memory, buffer + 12));
        Assert.Equal((ushort)9, ReadWord(memory, buffer + 14));
        Assert.Equal((byte)0, ReadByte(memory, buffer + 19));
        Assert.Equal(-1, core.AreaDraw(rastPort, 10, 11));

        // InitArea publishes the caller-owned pointer/size pair without
        // dereferencing the vector storage.  The consumer boundary remains
        // strict for the odd coordinate/flag addresses.
        Assert.True(core.InitializeArea(areaInfo, buffer + 1, 4));
        Assert.Equal(buffer + 1u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(buffer + 17u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));
        Assert.Equal(-1, core.AreaMove(rastPort, 1, 2));
        Assert.False(core.InitializeArea(areaInfo, buffer, -1));
        Assert.False(core.InitializeArea(0xFF0, buffer, 1));
    }

    [Fact]
    public void ZeroCapacityAreaInfoIsAValidEmptyCollector()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 0));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount));

        // No vector can be recorded, but the empty collector remains a
        // coherent AreaInfo and AreaEnd is the documented empty no-op.
        Assert.Equal(-1, core.AreaMove(rastPort, 1, 2));
        Assert.Equal(-1, core.AreaDraw(rastPort, 3, 4));
        Assert.Equal(-1, core.AreaEllipse(rastPort, 5, 6, 1, 1));
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void ZeroCapacityAreaInfoAcceptsANullVectorBuffer()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;

        // InitArea has no vector storage to touch when MaxCount is zero.
        // The native empty-collector form therefore permits a NULL buffer
        // and publishes NULL vector/flag pointers for a later retry.
        Assert.True(core.InitializeArea(areaInfo, 0, 0));
        Assert.Equal(0u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(0u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(0u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));
        Assert.Equal(0u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount));

        // The same null-buffer descriptor is consumable by the empty AreaEnd
        // no-op; it must not require a dummy vector/flag allocation merely to
        // close an already-empty collector.
        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaInfoAcceptsAnExactEndOfAddressSpaceVectorBuffer()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint areaInfo = 0x300;
        const uint buffer = 0xFFFF_FFF6;

        // Two vectors occupy ten bytes: the final flag byte lands at
        // $FFFFFFFF, so the exclusive buffer end is exactly $1_0000_0000.
        // A native 68000 can address every byte in that envelope; the
        // one-past-the-end arithmetic must not reject it as a wrap.
        for (var offset = 0u; offset < (uint)GraphicsLayouts.AreaInfoSize; offset++)
            memory.WriteByte(areaInfo + offset, 0);
        for (var offset = 0u; offset < 10u; offset++)
            memory.WriteByte(buffer + offset, 0xA0);
        Assert.True(core.InitializeArea(areaInfo, buffer, 2));
        Assert.True(memory.TryReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable,
            out var vectorTable));
        Assert.True(memory.TryReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer,
            out var vectorPointer));
        Assert.True(memory.TryReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable,
            out var flagTable));
        Assert.True(memory.TryReadLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer,
            out var flagPointer));
        Assert.True(memory.TryReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount,
            out var maxCount));
        Assert.Equal(buffer, vectorTable);
        Assert.Equal(buffer, vectorPointer);
        Assert.Equal(0xFFFF_FFFEu, flagTable);
        Assert.Equal(0xFFFF_FFFEu, flagPointer);
        Assert.Equal((ushort)2, maxCount);

        // Moving the same ten-byte request two bytes higher would put its
        // exclusive end beyond the guest address space and must remain
        // available to the native/provider owner.
        Assert.False(core.InitializeArea(areaInfo, 0xFFFF_FFF8, 2));
    }

    [Fact]
    public void HostRegisterAdapterClaimsNullBufferZeroCapacityAreaEndAsAnEmptyNoOp()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));

        var state = new M68kCpuState
        {
            A = { [0] = areaInfo, [1] = 0 },
            D = { [0] = 0 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitArea));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(0u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));

        state.A[1] = rastPort;
        state.D[0] = 0xCAFE_BABEu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaInfoLeavesOddStructureAndVectorAddressesForNativeOwnership()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint oddAreaInfo = 0x101;
        const uint buffer = 0x200;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            oddAreaInfo));

        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.True(memory.TryWriteByte(oddAreaInfo + (uint)offset, (byte)(0xA0 + offset)));

        Assert.False(core.InitializeArea(oddAreaInfo, buffer, 2));
        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.Equal((byte)(0xA0 + offset), ReadByte(memory, oddAreaInfo + (uint)offset));
        Assert.Equal(-1, core.AreaMove(rastPort, 1, 2));

        const uint areaInfo = 0x120;
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 2));
        Assert.True(memory.TryWriteLong(
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable,
            buffer + 1u));

        // A forged odd coordinate stream must not be byte-decoded by the
        // portable collector; native 68k ownership can handle the address
        // error according to its own boundary contract.
        Assert.Equal(-1, core.AreaMove(rastPort, 3, 4));
    }

    [Fact]
    public void AreaVectorsRejectWrappedHighRastPortAreaInfoAddresses()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint highRastPort = 0xFFFF_FFF0;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        // A wrapping guest-memory implementation exposes the old failure
        // mode directly: high RastPort + rp_AreaInfo aliases the low address.
        // The portable collector must reject the high address before reading
        // or mutating that unrelated low-memory AreaInfo link.
        Assert.True(memory.TryWriteLong(
            0,
            areaInfo));
        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            memory.WriteByte(areaInfo + (uint)offset, 0);
        for (var offset = 0; offset < 10; offset++)
            memory.WriteByte(buffer + (uint)offset, 0);
        Assert.True(core.InitializeArea(areaInfo, buffer, 2));

        Assert.Equal(-1, core.AreaMove(highRastPort, 1, 2));
        Assert.True(memory.TryReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount,
            out var pureCount));
        Assert.Equal((ushort)0, pureCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = highRastPort },
            D = { [0] = 0xDEAD_BEEFu, [1] = 2 }
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AreaMove));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.True(memory.TryReadWord(
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount,
            out var gatewayCount));
        Assert.Equal((ushort)0, gatewayCount);
    }

    [Fact]
    public void InitAreaPublishesAnUnmappedVectorBufferWithoutDereferencingIt()
    {
        var memory = new FakeMemory(0x300);
        var core = CreateCore(memory);
        const uint areaInfo = 0x100;
        const uint buffer = 0x2FE;

        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.True(memory.TryWriteByte(areaInfo + (uint)offset, 0xA5));

        // One vector needs four coordinate bytes plus one flag byte, but the
        // resident InitArea initializer only publishes the descriptor.  The
        // later AreaMove/AreaDraw consumers own the readable-span decision.
        Assert.True(core.InitializeArea(areaInfo, buffer, 1));
        Assert.Equal(
            buffer,
            ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(
            buffer + 4u,
            ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));

        var rastPort = 0x20u;
        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.Equal(-1, core.AreaMove(rastPort, 1, 2));
    }

    [Fact]
    public void InitAreaPublishesAnOddUnmappedVectorBufferThroughTheRegisterGateway()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint areaInfo = 0x100;
        const uint buffer = 0xF000_0001;
        const short maxVectors = 2;

        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.True(memory.TryWriteByte(areaInfo + (uint)offset, 0xA5));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = areaInfo, [1] = buffer },
            D = { [0] = unchecked((uint)(ushort)maxVectors), [1] = 0xCAFE_BABEu },
            Cycles = 271
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitArea));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(271, state.Cycles);
        Assert.Equal(
            buffer,
            ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(
            buffer + 8u,
            ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));
    }

    [Fact]
    public void InitAreaRestoresGuestBytesWhenACollectorWriteFails()
    {
        var backing = new FakeMemory(0x400);
        const uint areaInfo = 0x300;
        const uint buffer = 0x200;
        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.True(backing.TryWriteByte(areaInfo + (uint)offset, (byte)(offset * 7 + 5)));

        var rejecting = new RejectingWriteMemory(
            backing,
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer,
            areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer + 4u);
        var core = CreateCore(rejecting);

        Assert.False(core.InitializeArea(areaInfo, buffer, 4));
        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            Assert.Equal((byte)(offset * 7 + 5), ReadByte(backing, areaInfo + (uint)offset));
    }

    [Fact]
    public void AreaEllipseConsumesTwoVectorsAndAllowsAFollowingPolygonStart()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 3));

        Assert.Equal(0, core.AreaEllipse(rastPort, 10, 11, 4, 5));
        Assert.Equal((ushort)2, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)10, ReadWord(memory, buffer));
        Assert.Equal((ushort)11, ReadWord(memory, buffer + 2));
        Assert.Equal((byte)3, ReadByte(memory, buffer + 12));
        Assert.Equal((ushort)4, ReadWord(memory, buffer + 4));
        Assert.Equal((ushort)5, ReadWord(memory, buffer + 6));
        Assert.Equal((byte)3, ReadByte(memory, buffer + 13));

        // An ellipse is already a closed area item, so AreaMove only consumes
        // one additional vector for the next polygon's first point.
        Assert.Equal(0, core.AreaMove(rastPort, (short)20, (short)21));
        Assert.Equal((ushort)3, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)20, ReadWord(memory, buffer + 8));
        Assert.Equal((ushort)21, ReadWord(memory, buffer + 10));
        Assert.Equal((byte)0, ReadByte(memory, buffer + 14));
        Assert.Equal(-1, core.AreaEllipse(rastPort, 0, 0, 1, 1));
        Assert.Equal(-1, core.AreaEllipse(rastPort, 0, 0, 0, 1));
    }

    [Fact]
    public void AreaEllipseClosesThePrecedingDrawPolygonWithNativeFlags()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 5));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 1));

        // AreaEllipse closes the open polygon before appending its two
        // ELLIPSE vectors.  The first flag remains MOVE, the line is DRAW,
        // the explicit return is CLOSEDRAW, and both ellipse entries carry
        // the same native ELLIPSE value.
        Assert.Equal(0, core.AreaEllipse(rastPort, 8, 8, 2, 2));
        Assert.Equal((ushort)5, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((byte)0, ReadByte(memory, buffer + 20));
        Assert.Equal((byte)1, ReadByte(memory, buffer + 21));
        Assert.Equal((byte)2, ReadByte(memory, buffer + 22));
        Assert.Equal((byte)3, ReadByte(memory, buffer + 23));
        Assert.Equal((byte)3, ReadByte(memory, buffer + 24));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 8));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 10));
    }

    [Fact]
    public void AreaEllipseReservesTwoSlotsBeforeReplacingAPendingMove()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 4));
        Assert.Equal(0, core.AreaEllipse(rastPort, 10, 11, 2, 2));
        Assert.Equal(0, core.AreaMove(rastPort, (short)20, (short)21));
        Assert.Equal((ushort)3, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        // One free vector is insufficient for the two-vector ellipse, even
        // though the trailing AreaMove is otherwise replaceable.
        Assert.Equal(-1, core.AreaEllipse(rastPort, 30, 31, 1, 1));
        Assert.Equal((ushort)3, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)20, ReadWord(memory, buffer + 8));
        Assert.Equal((ushort)21, ReadWord(memory, buffer + 10));
    }

    [Fact]
    public void AreaEllipseReplacesAPendingAreaMoveInsteadOfLeavingAnEmptyPolygon()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 4));
        Assert.Equal(0, core.AreaMove(rastPort, (short)1, (short)2));
        Assert.Equal((ushort)1, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        // A pending move is only a polygon start marker.  AreaEllipse must
        // reuse that slot, matching the native two-vector ellipse stream.
        Assert.Equal(0, core.AreaEllipse(rastPort, 8, 9, 2, 3));
        Assert.Equal((ushort)2, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal(buffer + 8u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(buffer + 18u, ReadLong(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)8, ReadWord(memory, buffer));
        Assert.Equal((ushort)9, ReadWord(memory, buffer + 2));
        Assert.Equal((byte)3, ReadByte(memory, buffer + 16));
        Assert.Equal((byte)3, ReadByte(memory, buffer + 17));

        // The ellipse is already closed, so a following polygon consumes one
        // additional vector rather than closing the discarded move again.
        Assert.Equal(0, core.AreaMove(rastPort, (short)20, (short)21));
        Assert.Equal((ushort)3, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)20, ReadWord(memory, buffer + 8));
        Assert.Equal((ushort)21, ReadWord(memory, buffer + 10));
        Assert.Equal((byte)0, ReadByte(memory, buffer + 18));
    }

    [Fact]
    public void AreaMoveAppliesCapacityCheckBeforeReplacingAConsecutivePendingMove()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 1));

        Assert.Equal(0, core.AreaMove(rastPort, (short)1, (short)2));
        Assert.Equal((ushort)1, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        // Kickstart performs the one-slot capacity check before it considers
        // replacing a pending MOVE, so a full one-vector collector declines.
        Assert.Equal(-1, core.AreaMove(rastPort, (short)8, (short)9));
        Assert.Equal((ushort)1, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal((ushort)1, ReadWord(memory, buffer));
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 2));
        Assert.Equal((byte)0, ReadByte(memory, buffer + 4));
    }

