    [Fact]
    public void AreaCollectorsRejectAnOddRastPortBeforeReadingAreaInfo()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x21;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(core.InitializeArea(areaInfo, buffer, 2));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));

        // A host byte map can read the odd fields, but the native collector
        // reaches them with 68000 word/long accesses and must take an address
        // error instead of publishing a vector.
        Assert.Equal(-1, core.AreaMove(rastPort, 3, 4));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 4 },
            Cycles = 123
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AreaMove));
        Assert.Equal(3u, state.D[0]);
        Assert.Equal(4u, state.D[1]);
        Assert.Equal(123, state.Cycles);
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaConstructionRestoresVectorAndCollectorStateWhenMetadataPublicationFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x100;
        const uint buffer = 0x200;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 4));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 2));

        var originalCount = ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount);
        var originalVectorPointer = ReadLong(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer);
        var originalFlagPointer = ReadLong(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer);
        var originalX = ReadWord(backing, buffer);
        var originalY = ReadWord(backing, buffer + 2);
        var originalFlag = ReadByte(backing, buffer + 16);

        // AreaDraw publishes five bytes for the new vector, then advances the
        // AreaInfo pointers. Fail at that first metadata byte; the complete
        // guest operation must roll back the already-written vector.
        memory.FailOnNextByteWrite(6);
        Assert.Equal(-1, core.AreaDraw(rastPort, 4, 5));

        Assert.Equal(originalCount, ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal(originalVectorPointer, ReadLong(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(originalFlagPointer, ReadLong(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal(originalX, ReadWord(backing, buffer));
        Assert.Equal(originalY, ReadWord(backing, buffer + 2));
        Assert.Equal(originalFlag, ReadByte(backing, buffer + 16));
        Assert.Equal(0, ReadWord(backing, buffer + 4));
        Assert.Equal(0, ReadWord(backing, buffer + 6));
        Assert.Equal((byte)0, ReadByte(backing, buffer + 17));
    }

    [Fact]
    public void AreaEndFillsRecordedPolygonAndResetsTheAreaCollector()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, 0x100));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 6));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 6));
        Assert.True(GraphicsRasterOperations.TryReadBitmap(memory, rastPort, out _));
        Assert.Equal(3, core.GetAPen(rastPort));
        Assert.Equal(1, core.GetDrawMode(rastPort));

        Assert.Equal(0, core.AreaEnd(rastPort));
