    [Fact]
    public void AreaEndWithoutAreaPatternDoesNotRequireAreaPatternSize()
    {
        var backing = new FakeMemory(0x2000);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        var setup = CreateCore(backing);
        Assert.True(setup.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(setup.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, setup.SetAPen(rastPort, 3));
        Assert.Equal(0, setup.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, setup.AreaDraw(rastPort, 6, 1));
        Assert.Equal(0, setup.AreaDraw(rastPort, 6, 6));
        Assert.Equal(0, setup.AreaDraw(rastPort, 1, 6));

        // The no-pattern AreaEnd path only needs AreaPtrn, pens, and the
        // draw mode. Keep AreaPtSz unreadable and exercise both direct and
        // CopperStart register dispatch without changing the guest shape.
        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            sizeof(byte));
        var core = CreateCore(memory);

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(3, core.ReadPixel(rastPort, 3, 3));

        // Use a fresh guest image for the mapped ABI case because AreaEnd
        // intentionally resets the collector after the direct call.
        var mappedBacking = new FakeMemory(0x2000);
        var mappedSetup = CreateCore(mappedBacking);
        Assert.True(mappedSetup.InitializeRastPort(rastPort));
        Assert.True(mappedBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(mappedBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(mappedSetup.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, mappedSetup.SetAPen(rastPort, 3));
        Assert.Equal(0, mappedSetup.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, mappedSetup.AreaDraw(rastPort, 6, 1));
        Assert.Equal(0, mappedSetup.AreaDraw(rastPort, 6, 6));
        Assert.Equal(0, mappedSetup.AreaDraw(rastPort, 1, 6));

        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            sizeof(byte));
        var mappedCore = CreateCore(mappedMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void AreaEndComplementJam2DoesNotRequireBackgroundOrPatternStorageAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;
        const uint unusablePattern = 0x801;

        static void Prepare(
            RangeReadFaultMemory memory,
            FakeMemory backing,
            GraphicsLibraryCore core,
            uint rastPort,
            uint areaInfo,
            uint buffer,
            uint unusablePattern)
        {
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
                areaInfo));
            Assert.True(core.InitializeArea(areaInfo, buffer, 8));
            Assert.Equal(0, core.SetAPen(rastPort, 3));
            Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2 | COMPLEMENT
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                unusablePattern));
            Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
            Assert.Equal(0, core.AreaDraw(rastPort, 6, 1));
            Assert.Equal(0, core.AreaDraw(rastPort, 6, 6));
            Assert.Equal(0, core.AreaDraw(rastPort, 1, 6));

            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortBgPen,
                sizeof(byte));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte));
            memory.FailReads(unusablePattern, sizeof(ushort));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
                sizeof(byte));
        }

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(memory, backing, core, rastPort, areaInfo, buffer, unusablePattern);

        // COMPLEMENT|JAM2 inverts every selected area cell without consulting
        // the unrelated BPen or the attached area-pattern source.
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(3, core.ReadPixel(rastPort, 3, 3));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(
            mappedMemory,
            mappedBacking,
            mappedCore,
            rastPort,
            areaInfo,
            buffer,
            unusablePattern);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(3, mappedCore.ReadPixel(rastPort, 3, 3));
    }

    [Fact]
    public void AreaEndOnEmptyAreaInfoSucceedsWithoutAResidentBitmap()
    {
        var memory = new FakeMemory(0x1000);
