        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 4));

        // An empty collector is a valid completed AreaEnd boundary.  It does
        // not need a destination bitmap or a temporary raster because there
        // is no geometry to process.
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndRejectsAggregateShapeWorkBeforeTemporaryRasterOrPlaneProbe()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF8);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        const uint plane = 0x1FF8;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4096));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            32768));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(backing.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 6));

        // A 32768-by-32768 shape is representable in the signed-WORD guest
        // coordinate stream, but its mask/rasterize/snapshot/fill work is
        // well beyond the portable Int32 host-work envelope. The plane is
        // intentionally only barely mapped; AreaEnd must decline before
        // touching it or acquiring a 134-MB temporary raster.
        Assert.Equal(0, core.AreaMove(rastPort, 0, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, short.MaxValue, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, short.MaxValue, short.MaxValue));
        Assert.Equal(0, core.AreaDraw(rastPort, 0, short.MaxValue));
        var baselinePlaneReads = memory.TrackedReadCount;
        var originalCount = ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount);

        Assert.Equal(-1, core.AreaEnd(rastPort));
        Assert.Equal(baselinePlaneReads, memory.TrackedReadCount);
        Assert.Equal(
            originalCount,
            ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 981
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(981, state.Cycles);

        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_2468u },
            Cycles = 983
        };
        Assert.False(adapter.TryInvoke(
            overlayState,
            (int)GraphicsLvo.AreaEnd,
            nativeOverlay: true));
        Assert.Equal(0x1357_2468u, overlayState.D[0]);
        Assert.Equal(983, overlayState.Cycles);
    }

    [Fact]
    public void AreaEndAppliesComplementOncePerOverlappingRecordedShape()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(core.InitializeArea(areaInfo, buffer, 12));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));

        // Seed the selected plane so a single complement is observable.
        for (var row = 0u; row < 8; row++)
            Assert.True(memory.TryWriteByte(0x400u + (row * 2u), 0xFF));

        // The two identical polygons overlap completely.  Kickstart builds
        // and applies one area mask per recorded shape, so the shared pixel
        // is complemented twice and returns to its original value.
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 4));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 4));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 4));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 4));

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(1, core.ReadPixel(rastPort, 2, 2));
        Assert.Equal(1, core.ReadPixel(rastPort, 0, 0));
    }

    [Fact]
    public void AreaEndPreservesNoCrossFillFlagAndUsesPerShapeMaskBoundaries()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        Assert.Equal(0x0020, GraphicsLayouts.RastPortNoCrossFill);
        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(core.InitializeArea(areaInfo, buffer, 12));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)GraphicsLayouts.RastPortNoCrossFill));
        for (var row = 0u; row < 8; row++)
            Assert.True(memory.TryWriteByte(0x400u + (row * 2u), 0xFF));

        // NOCROSSFILL is a public area-filler state bit.  The portable path
        // applies one temporary mask per recorded shape, which is the
        // no-crossover transaction boundary.  Two identical shapes therefore
        // complement the shared pixel twice, while AreaEnd leaves the caller's
        // flag word intact for the next operation/native owner.
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 4));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 4));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 4));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 4));

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(1, core.ReadPixel(rastPort, 2, 2));
        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortNoCrossFill,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void AreaEndEmitsEachShapeOutlineBeforeTheNextShapeFill()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 12));
        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetWriteMask(rastPort, 3));
        Assert.Equal(255, core.SetOutlinePen(rastPort, 2));
        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortAreaOutline,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        // The second fill overlaps the first polygon's left outline.  Native
        // AreaEnd fills and outlines shape one before filling shape two, so
        // the later fill replaces that shared outline pixel.
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 6));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 6));
        Assert.Equal(0, core.AreaMove(rastPort, 0, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, 3, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, 3, 3));
        Assert.Equal(0, core.AreaDraw(rastPort, 0, 3));

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(1, core.ReadPixel(rastPort, 1, 2));
        Assert.Equal(2, core.ReadPixel(rastPort, 1, 5));
    }

    [Fact]
    public void AreaEndDoesNotToggleAClosedOutlineVertexTwiceInComplementMode()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;
        const uint areaPattern = 0x800;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.Equal(255, core.SetOutlinePen(rastPort, 1));

        // A zero area-pattern source suppresses the complement fill, leaving
        // the outline as the only operation at the first vertex.  The
        // CLOSEDRAW record already contains that vertex and must not add a
        // second zero-length segment that toggles it back.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            areaPattern));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            0));
        Assert.True(memory.TryWriteWord(areaPattern, 0));

        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 4, 4));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 4));

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(1, core.ReadPixel(rastPort, 1, 1));
    }

    [Fact]
    public void AreaEndPolygonOutlinesUseLinePatternPhaseAndRestoreTheCursor()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;
        const uint areaPattern = 0x800;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 0));
        Assert.Equal(255, core.SetOutlinePen(rastPort, 1));

        // Suppress the area fill so the outline is the only visible pass.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            areaPattern));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            0));
        Assert.True(memory.TryWriteWord(areaPattern, 0));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xA000));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            4));
        Assert.Equal(0, core.Move(rastPort, 9, 9));

        Assert.Equal(0, core.AreaMove(rastPort, 0, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, 3, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, 3, 3));
        Assert.Equal(0, core.AreaDraw(rastPort, 0, 3));

        Assert.Equal(0, core.AreaEnd(rastPort));

        // SetAPen(outline) restarts the line phase before PolyDraw.  The top
        // horizontal edge therefore consumes A000 from bit 15: on, off, on,
        // off.  A later connected edge must continue from that phase rather
        // than restarting at every Draw call.
        Assert.Equal(1, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 1, 0));
        Assert.Equal(1, core.ReadPixel(rastPort, 2, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 3, 0));
        Assert.Equal((short)9, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((short)9, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(
            (byte)15,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void AreaEndRestoresOutlineCursorAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;
        const uint areaPattern = 0x800;
        var cursorAddress = rastPort + (uint)GraphicsLayouts.RastPortCurrentX;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 0));
        Assert.Equal(255, core.SetOutlinePen(rastPort, 1));

        // Keep the fill pass empty so this fixture isolates the outline
        // cursor journal.
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            areaPattern));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            0));
        Assert.True(backing.TryWriteWord(areaPattern, 0));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xA000));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            4));
        Assert.Equal(0, core.Move(rastPort, 9, 9));
        Assert.Equal(0, core.AreaMove(rastPort, 0, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, 3, 0));
        Assert.Equal(0, core.AreaDraw(rastPort, 3, 3));
        Assert.Equal(0, core.AreaDraw(rastPort, 0, 3));

        var oldFlags = ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags);
        var oldPatternCount = ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount);
        memory.PartialWordAddress = cursorAddress;

        Assert.Equal(-1, core.AreaEnd(rastPort));
        Assert.Equal((short)9, ReadSignedWord(backing, cursorAddress));
        Assert.Equal(
            (short)9,
            ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(
            oldFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            oldPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal((short)9, ReadSignedWord(backing, cursorAddress));
    }

    [Fact]
    public void TryReadBitmapRejectsWrappedRastPortAndBitmapHeaders()
    {
        var rastPortMemory = new WrappingMemory();
        const uint wrappedRastPort = 0xFFFF_FFFCu;
        rastPortMemory.WriteLong(0, 0x100);
        rastPortMemory.WriteWord(0x100, 2);
        rastPortMemory.WriteWord(0x102, 1);
        rastPortMemory.WriteByte(0x105, 1);

        // The legacy unchecked addition would read the low address zero after
        // RastPortBitMap crossed the 32-bit guest boundary.
        Assert.False(GraphicsRasterOperations.TryReadBitmap(
            rastPortMemory,
            wrappedRastPort,
            out _));

        var envelopeMemory = new WrappingMemory();
        const uint highRastPort = 0xFFFF_FF80u;
        envelopeMemory.WriteLong(
            highRastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100);
        envelopeMemory.WriteWord(0x100, 2);
        envelopeMemory.WriteWord(0x102, 1);
        envelopeMemory.WriteByte(0x104, 0);
        envelopeMemory.WriteByte(0x105, 1);

        // The classic 100-byte envelope ends at FFFFFFE3 and is valid.
        // Seed every consumed bitmap field, including Flags, so a missing
        // field cannot mask an obsolete 180-byte rejection.
        Assert.True(GraphicsRasterOperations.TryReadBitmap(
            envelopeMemory,
            highRastPort,
            out var highBitmap));
        Assert.Equal((0x100u, 2, 2, 1, 1, (byte)0, 16),
            (highBitmap.Address, highBitmap.GuestBytesPerRow, highBitmap.PlaneBytesPerRow,
                highBitmap.Rows, highBitmap.Depth, highBitmap.Flags, highBitmap.Width));

        var wrappedEnvelopeMemory = new WrappingMemory();
        const uint wrappedEnvelopeRastPort = 0xFFFF_FF9Eu;
        wrappedEnvelopeMemory.WriteLong(wrappedEnvelopeRastPort + 4, 0x100);
        wrappedEnvelopeMemory.WriteWord(0x100, 2);
        wrappedEnvelopeMemory.WriteWord(0x102, 1);
        wrappedEnvelopeMemory.WriteByte(0x104, 0);
        wrappedEnvelopeMemory.WriteByte(0x105, 1);
        // All consumed fields fit; only the complete logical envelope wraps.
        Assert.False(GraphicsRasterOperations.TryReadBitmap(
            wrappedEnvelopeMemory, wrappedEnvelopeRastPort, out var wrappedEnvelopeBitmap));
        Assert.Equal((0u, 0, 0, 0, 0, (byte)0, 0),
            (wrappedEnvelopeBitmap.Address, wrappedEnvelopeBitmap.GuestBytesPerRow,
                wrappedEnvelopeBitmap.PlaneBytesPerRow, wrappedEnvelopeBitmap.Rows,
                wrappedEnvelopeBitmap.Depth, wrappedEnvelopeBitmap.Flags, wrappedEnvelopeBitmap.Width));

        var bitmapMemory = new WrappingMemory();
        const uint rastPort = 0x20;
        const uint wrappedBitmap = 0xFFFF_FFFEu;
        bitmapMemory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, wrappedBitmap);
        bitmapMemory.WriteWord(0, 2);
        bitmapMemory.WriteWord(2, 1);
        bitmapMemory.WriteByte(5, 1);

        // The bitmap header itself is also a guest envelope; its fields must
        // not wrap into an unrelated low-memory object.
        Assert.False(GraphicsRasterOperations.TryReadBitmap(
            bitmapMemory,
            rastPort,
            out _));

        var freeMemory = new WrappingMemory();
        const uint wrappedAllocatedBitmap = 0xFFFF_FFFEu;
        freeMemory.WriteWord(0, 2);
        freeMemory.WriteWord(2, 1);
        freeMemory.WriteByte(4, 0);
        freeMemory.WriteByte(5, 1);
        freeMemory.WriteLong(6, 0x200);
        var allocator = new FakeAllocator();
        Assert.Equal(
            -1,
            GraphicsRasterOperations.FreeBitMap(
                freeMemory,
                allocator,
                wrappedAllocatedBitmap));
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void AreaEndRestoresEarlierPixelsWhenALaterPlaneWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 6));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 6));

        Assert.True(backing.TryWriteByte(plane0 + 2u, 0xA5));
        Assert.True(backing.TryWriteByte(plane1 + 2u, 0x5A));
        memory.FailOnNextByteWrite(4);
        Assert.Equal(-1, core.AreaEnd(rastPort));
        Assert.Equal((byte)0xA5, ReadByte(backing, plane0 + 2u));
        Assert.Equal((byte)0x5A, ReadByte(backing, plane1 + 2u));
        Assert.Equal((ushort)4, ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndRestoresRasterAndCollectorWhenResetPublicationFails()
    {
        var backing = new FakeMemory(0x2000);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;
        var rejectedFirstX = areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX;
        var memory = new RejectingWordWriteMemory(backing, 0);
        var core = CreateCore(memory);

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 8));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 6, 6));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 6));
        memory.RejectedAddress = rejectedFirstX;

        Assert.Equal(-1, core.AreaEnd(rastPort));

        // The fill happened before AreaInfo reset.  A rejected late reset
        // field must roll the destination back and leave the vectors intact
        // so the caller can retry after repairing the guest descriptor.
        Assert.Equal(0, core.ReadPixel(rastPort, 3, 3));
        Assert.Equal((ushort)4, ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.Equal(buffer + 16, ReadLong(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(buffer + 36, ReadLong(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoFlagPointer));
        Assert.Equal((ushort)1, ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoFirstX));
        Assert.Equal((ushort)1, ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoFirstY));
    }

