    [Fact]
    public void AreaEndWithZeroWriteMaskConsumesOutOfRasterShapeWithoutProbingPlanes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            8));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        // The plane pointer is readable, but its 16-byte raster ends at the
        // guest-memory boundary. A zero mask must not probe that storage.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF8));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, buffer, 2));

        // The ellipse extends outside the non-layered bitmap. With no
        // selected planes AreaEnd still consumes the collector, but it must
        // not reject the shape or touch the unreadable destination raster.
        Assert.Equal(0, core.AreaEllipse(rastPort, 0, 0, 2, 2));
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndWithZeroEffectiveMaskDoesNotReadPublicPensAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        static void Prepare(
            GraphicsLibraryCore core,
            FakeMemory backing,
            uint rastPort,
            uint areaInfo,
            uint buffer)
        {
            Assert.True(core.InitializeArea(areaInfo, buffer, 2));
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
                areaInfo));
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.Equal(0, core.AreaEllipse(rastPort, 0, 0, 2, 2));
        }

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(core, backing, rastPort, areaInfo, buffer);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            sizeof(uint));

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((ushort)0, ReadWord(
            backing,
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(mappedCore, mappedBacking, rastPort, areaInfo, buffer);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            sizeof(uint));

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 79
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(79, state.Cycles);
        Assert.Equal(0, mappedMemory.FaultedReadCount);
        Assert.Equal((ushort)0, ReadWord(
            mappedBacking,
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndDeclinesPrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint buffer = 0x700;

        static void Prepare(
            GraphicsLibraryCore core,
            FakeMemory backing,
            uint rastPort,
            uint areaInfo,
            uint buffer)
        {
            Assert.True(core.InitializeArea(areaInfo, buffer, 2));
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
                areaInfo));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.Equal(0, core.AreaEllipse(rastPort, 1, 1, 2, 2));
        }

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(core, backing, rastPort, areaInfo, buffer);
        var originalCount = ReadWord(
            backing,
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            sizeof(uint));

        Assert.Equal(-1, core.AreaEnd(rastPort));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal(
            originalCount,
            ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(mappedCore, mappedBacking, rastPort, areaInfo, buffer);
        var mappedOriginalCount = ReadWord(
            mappedBacking,
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            sizeof(uint));

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 89
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(89, state.Cycles);
        Assert.Equal(0, mappedMemory.FaultedReadCount);
        Assert.Equal(
            mappedOriginalCount,
            ReadWord(
                mappedBacking,
                areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndInverseVideoJam1ConsumesNullPatternWithoutProbingPlanes()
    {
        var memory = new FakeMemory(0x2000);
