        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndSizesTemporaryRasterFromTheLargestRecordedEllipse()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x800;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        const uint tmpRas = 0x900;
        const uint tmpBuffer = 0xA00;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            16));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 4));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortTmpRas,
            tmpRas));
        Assert.True(memory.TryWriteLong(
            tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr,
            tmpBuffer));

        // Each radius-one ellipse needs a 16-pixel-aligned 2-byte row for
        // three rows (6 bytes).  The two centers are deliberately separated
        // so a union-sized scratch calculation would incorrectly require
        // twelve bytes.
        Assert.True(memory.TryWriteLong(
            tmpRas + (uint)GraphicsLayouts.TmpRasByteCount,
            6));
        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.AreaEllipse(rastPort, 4, 4, 1, 1));
        Assert.Equal(0, core.AreaCircle(rastPort, 24, 4, 1));

        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(1, core.ReadPixel(rastPort, 4, 4));
        Assert.Equal(1, core.ReadPixel(rastPort, 24, 4));
        Assert.Equal(0, core.ReadPixel(rastPort, 14, 4));
        Assert.Equal((ushort)0, ReadWord(memory, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void AreaEndAcceptsTemporaryRasterSizedForTheLargestShape()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x800;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        const uint tmpRas = 0x900;
        const uint tmpBuffer = 0xA00;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 16));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));

        // The 2x2 polygon needs two bytes per row and four bytes total after
        // the classic 16-pixel word rounding.  The destination bitmap is
        // deliberately much larger (8 bytes would be required for its full
        // 16-row envelope), proving AreaEnd uses the shape bounds.
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortTmpRas, tmpRas));
        Assert.True(memory.TryWriteLong(tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr, tmpBuffer));
        Assert.True(memory.TryWriteLong(tmpRas + (uint)GraphicsLayouts.TmpRasByteCount, 4));

        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 2, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 2, 2));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 2));
        Assert.Equal(0, core.AreaEnd(rastPort));
        Assert.Equal(1, core.ReadPixel(rastPort, 1, 1));
        Assert.Equal(0, core.ReadPixel(rastPort, 8, 8));
    }

    [Fact]
    public void AreaEndConsumesTheAttachedTemporaryRasterAsItsFillMask()
    {
        var backing = new FakeMemory(0x4000);
