        const uint plane = 0x800;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        const uint tmpRas = 0x900;
        const uint tmpBuffer = 0xA00;

        var memory = new RejectingWriteMemory(backing, tmpBuffer, tmpBuffer + 4);
        var core = CreateCore(memory);
        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8));
        Assert.True(backing.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(backing.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane));
        Assert.True(backing.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));
        Assert.True(backing.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortTmpRas, tmpRas));
        Assert.True(backing.TryWriteLong(tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr, tmpBuffer));
