    [Fact]
    public void AllocRasterRoundsRowsToWordsAndFreeRasterMirrorsTheByteCount()
    {
        var memory = new FakeMemory(0x100);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        Assert.Equal(0x1000u, core.AllocRaster(17, 3));
        Assert.Equal(12u, allocator.LastAllocatedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastAllocatedClass);

        Assert.Equal(0, core.FreeRaster(0x1000, 17, 3));
        Assert.Equal(0x1000u, allocator.LastFreedAddress);
        Assert.Equal(12u, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastFreedClass);

        Assert.Equal(0u, core.AllocRaster(uint.MaxValue, uint.MaxValue));
        Assert.Equal(-1, core.FreeRaster(0, 17, 3));

        var wrappingAllocator = new FixedAddressAllocator(uint.MaxValue - 1u);
        var wrappingCore = new GraphicsLibraryCore(
            memory,
            wrappingAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, wrappingCore.AllocRaster(17, 3));
        Assert.Equal(1, wrappingAllocator.FreeCount);

        var oddAllocator = new FixedAddressAllocator(0x1001);
        var oddCore = new GraphicsLibraryCore(
            memory,
            oddAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, oddCore.AllocRaster(17, 3));
        Assert.Equal(1, oddAllocator.FreeCount);
    }

    [Fact]
    public void RasSizeUsesGuestWordRoundingAndUlongWrapSemantics()
    {
        var memory = new FakeMemory(0x2000);
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay());

        // 17 pixels occupy two 16-bit words per row.
        Assert.Equal(12u, core.RasSize(17, 3));
        Assert.Equal(8000u, core.RasSize(320, 200));

        // The macro is pure ULONG arithmetic, so zero dimensions produce a
        // zero byte count without touching guest memory.
        Assert.Equal(0u, core.RasSize(0, 200));
        Assert.Equal(0u, core.RasSize(320, 0));

        var expectedWrapped = unchecked(
            ((((uint.MaxValue + 15u) >> 3) & 0xFFFEu) * uint.MaxValue));
        Assert.Equal(expectedWrapped, core.RasSize(uint.MaxValue, uint.MaxValue));
    }

    [Fact]
    public void AllocRasterConsumesOnlyUwordDimensionsAtTheMappedBoundary()
    {
        var memory = new FakeMemory(0x200);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        // The public vector receives UWORD width/height values.  High words
        // are caller/register residue and must not make the portable gateway
        // reject an otherwise valid 17x3 allocation.
        var allocate = new M68kCpuState
        {
            D = { [0] = 0xABCD_0011u, [1] = 0x1234_0003u },
            Cycles = 389
        };
        Assert.True(adapter.TryInvoke(allocate, (int)GraphicsLvo.AllocRaster));
        Assert.Equal(0x1000u, allocate.D[0]);
        Assert.Equal(389, allocate.Cycles);
        Assert.Equal(12u, allocator.LastAllocatedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastAllocatedClass);

        // FreeRaster is the matching UWORD/UWORD vector; its existing
        // low-word normalization must accept the same high-word residue.
        var free = new M68kCpuState
        {
            A = { [0] = allocate.D[0] },
            D = { [0] = 0xDEAD_0011u, [1] = 0xBEEF_0003u },
            Cycles = 391
        };
        Assert.True(adapter.TryInvoke(free, (int)GraphicsLvo.FreeRaster));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(391, free.Cycles);
        Assert.Equal(0x1000u, allocator.LastFreedAddress);
        Assert.Equal(12u, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastFreedClass);
    }

    [Fact]
    public void FreeRasterRejectsOddPlaneptrBeforePortableOrMappedOwnershipCanClaimIt()
    {
        const uint oddRaster = 0x1001;
        const uint width = 17;
        const uint height = 3;

        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            new FakeMemory(0x100),
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        // Exercise the portable free helper directly as well as the
        // instance-owned registry boundary.  Neither path may reconstruct or
        // release a chip span for a native-invalid odd base.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            GraphicsRasterOperations.FreeRaster(
                allocator,
                oddRaster,
                width,
                height));
        Assert.Equal(-1, core.FreeRaster(oddRaster, width, height));
        Assert.Equal(0, allocator.FreeCount);

        // The host register path must leave the caller's D0/cycle frame
        // untouched so an overlaid native/provider implementation can claim
        // a non-standard pointer policy.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = oddRaster },
            D = { [0] = width, [1] = height },
            Cycles = 421,
            ProgramCounter = 0x0012_40A1
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FreeRaster));
        Assert.Equal(width, state.D[0]);
        Assert.Equal(height, state.D[1]);
        Assert.Equal(421, state.Cycles);
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void AllocRasterReleasesAProvisionalAddressWhenTheAllocatorDeclines()
    {
        var allocator = new DecliningRasterAllocator();
        var core = new GraphicsLibraryCore(
            new FakeMemory(0x100),
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        Assert.Equal(0u, core.AllocRaster(17, 3));
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x2000 &&
                          allocation.Bytes == 12 &&
                          allocation.MemoryClass == GraphicsMemoryClass.Chip);
    }

    [Fact]
    public void GetBitMapAttrReportsAlignedGeometryFlagsAndUnknownAsZero()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint bitMap = 0x180;

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 9);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0x1A);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 3);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x200);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x280);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8, 0x300);

        Assert.Equal(9u, core.GetBitMapAttr(bitMap, 0));
        Assert.Equal(3u, core.GetBitMapAttr(bitMap, 4));
        Assert.Equal(32u, core.GetBitMapAttr(bitMap, 8));
        // BMA_FLAGS exposes only the public display/storage classification;
        // allocator request bits (BMF_CLEAR/BMF_MINPLANES) are not reported.
        Assert.Equal(0x0Au, core.GetBitMapAttr(bitMap, 12));
        Assert.Equal(0u, core.GetBitMapAttr(bitMap, 99));
        Assert.Equal(0u, core.GetBitMapAttr(0, 8));
    }

    [Fact]
    public void GetBitMapAttrReadsOnlyTheRequestedScalarField()
    {
        var backing = new FakeMemory(0x2000);
        const uint bitMap = 0x100;
        _ = CreateCore(backing);
        Assert.True(backing.TryWriteLong(
            0x20u + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));

        // BMA_WIDTH/BMA_HEIGHT/BMA_DEPTH are independent scalar queries.
        // An unavailable flags byte and plane-pointer tail must not make a
        // valid width query fall through to the native/provider owner.
        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            sizeof(byte));
        memory.FailReads(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            8u);
        var core = CreateCore(memory);

        Assert.Equal(16u, core.GetBitMapAttr(bitMap, 8));
        Assert.Equal(8u, core.GetBitMapAttr(bitMap, 0));
        Assert.Equal(2u, core.GetBitMapAttr(bitMap, 4));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 0xCAFE_BABEu, [1] = 8 },
            Cycles = 73
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetBitMapAttr));
        Assert.Equal(16u, state.D[0]);
        Assert.Equal(73, state.Cycles);

        // BMA_FLAGS still owns the capability check when the flag is
        // readable; the unrelated faulted plane tail must not affect a
        // non-displayable public flag result.
        Assert.Equal(0u, core.GetBitMapAttr(bitMap, 12));
    }

    [Fact]
    public void GetBitMapAttrClearsDisplayableForMisalignedGuestPlanes()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x100;
        const uint bmfDisplayable = 1u << 1;
        const uint bmfStandard = 1u << 3;

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(bmfDisplayable | bmfStandard));
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x301);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x401);

        // BMF_DISPLAYABLE is a capability result.  A stale/request bit in a
        // guest header must not survive BMA_FLAGS when either plane starts on
        // an odd address.
        Assert.Equal(bmfStandard, core.GetBitMapAttr(bitMap, 12));

        var state = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 0xCAFE_BABEu, [1] = 12 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetBitMapAttr));
        Assert.Equal(bmfStandard, state.D[0]);

        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x300);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x400);
        Assert.Equal(bmfDisplayable | bmfStandard, core.GetBitMapAttr(bitMap, 12));
    }

    [Fact]
    public void GetBitMapAttrClearsDisplayableForMappedNonDmaGuestPlanes()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new DisplayClassMemory(
            backing,
            (address, _) => address >= 0x0800);
        var core = CreateCore(memory);
        const uint bitMap = 0x100;
        const uint bmfDisplayable = 1u << 1;
        const uint bmfStandard = 1u << 3;

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(bmfDisplayable | bmfStandard));
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x0300);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x0400);

        // The ranges are mapped and aligned, but the active memory provider
        // explicitly says they are not addressable by native display DMA.
        Assert.Equal(bmfStandard, core.GetBitMapAttr(bitMap, 12));

        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x0800);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x0900);
        Assert.Equal(bmfDisplayable | bmfStandard, core.GetBitMapAttr(bitMap, 12));
    }

    [Fact]
    public void BltBitMapCopiesPlanarPixelsAndPreservesOverlapWithMinterms()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane0 = 0x400;
        const uint sourcePlane1 = 0x500;
        const uint destinationPlane0 = 0x600;
        const uint destinationPlane1 = 0x700;

        WritePlanarBitmap(memory, source, sourcePlane0, sourcePlane1, rows: 4);
        WritePlanarBitmap(memory, destination, destinationPlane0, destinationPlane1, rows: 4);
        memory.TryWriteByte(sourcePlane0, 0xA5);
        memory.TryWriteByte(sourcePlane1, 0x3C);
        memory.TryWriteByte(destinationPlane0, 0);
        memory.TryWriteByte(destinationPlane1, 0);

        Assert.Equal(2, core.BltBitMap(source, 0, 0, destination, 0, 0, 8, 1, 0xC0, 0xFF, 0));
        Assert.Equal((byte)0xA5, ReadByte(memory, destinationPlane0));
        Assert.Equal((byte)0x3C, ReadByte(memory, destinationPlane1));

        memory.TryWriteByte(destinationPlane0, 0xFF);
        memory.TryWriteByte(destinationPlane1, 0xFF);
        Assert.Equal(2, core.BltBitMap(source, 0, 0, destination, 0, 0, 8, 1, 0x30, 0xFF, 0));
        Assert.Equal(unchecked((byte)~0xA5), ReadByte(memory, destinationPlane0));
        Assert.Equal(unchecked((byte)~0x3C), ReadByte(memory, destinationPlane1));

        memory.TryWriteByte(sourcePlane0, 0x80);
        memory.TryWriteByte(sourcePlane1, 0);
        Assert.Equal(2, core.BltBitMap(source, 0, 0, source, 1, 0, 7, 1, 0xC0, 0xFF, 0));
        Assert.Equal((byte)0xC0, ReadByte(memory, sourcePlane0));
    }

    [Fact]
    public void BltBitMapTreatsV36ConstantSourcePlanesAsZeroAndAllOnes()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint destinationPlane0 = 0x500;
        const uint destinationPlane1 = 0x600;

        // V36 permits a source plane link of zero or $FFFFFFFF as a cheap
        // constant plane. Neither value is guest storage and therefore must
        // not be probed as an ordinary byte span.
        WritePlanarBitmap(memory, source, 0, uint.MaxValue, rows: 1);
        WritePlanarBitmap(
            memory,
            destination,
            destinationPlane0,
            destinationPlane1,
            rows: 1);
        memory.TryWriteByte(destinationPlane0, 0xAA);
        memory.TryWriteByte(destinationPlane1, 0x55);

        Assert.Equal(
            2,
            core.BltBitMap(
                source,
                0,
                0,
                destination,
                0,
                0,
                8,
                1,
                0xC0,
                0x03,
                0));

        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane0));
        Assert.Equal((byte)0xFF, ReadByte(memory, destinationPlane1));
    }

    [Fact]
    public void BltBitMapAcceptsACompactDepthSizedHeaderAtTheGuestMemoryEnd()
    {
        // Leave the historical eight-plane tail unmapped.  A depth-one
        // BMF_MINPLANES-style header still has its fixed fields and one plane
        // link fully available, so the portable blitter must claim it.
        var memory = new FakeMemory(0x3FC);
        var core = CreateCore(memory);
        const uint source = 0x3E0;
        const uint destination = 0x3F0;
        const uint sourcePlane = 0x100;
        const uint destinationPlane = 0x120;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(sourcePlane, 0xA5));
        Assert.True(memory.TryWriteByte(destinationPlane, 0));

        Assert.Equal(
            1,
            core.BltBitMap(source, 0, 0, destination, 0, 0, 8, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0xA5, ReadByte(memory, destinationPlane));
    }

    [Fact]
    public void BltBitMapKeepsLargeGuestRowOffsetsWide()
    {
        // A native BitMap may expose a large WORD stride and a full UWORD
        // row count.  The clipped blit coordinates are signed WORDs, so a
        // request beginning at 32767 can still visit rows above 32767.  The
        // guest byte address must remain wide until the final 32-bit check;
        // an int multiplication would wrap into an unrelated low address.
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x1000;
        const uint destinationPlane = 0x2000;
        const ushort bytesPerRow = 0xFFFE;
        const ushort rows = ushort.MaxValue;
        const short startY = short.MaxValue;
        const short height = short.MaxValue;

        WriteWideBitmap(memory, source, sourcePlane, bytesPerRow, rows);
        WriteWideBitmap(memory, destination, destinationPlane, bytesPerRow, rows);

        var span = ((ulong)bytesPerRow * rows) - 1u;
        memory.WriteByte(sourcePlane, 0);
        memory.WriteByte(sourcePlane + (uint)span, 0);
        memory.WriteByte(destinationPlane, 0);
        memory.WriteByte(destinationPlane + (uint)span, 0);

        for (var row = 0; row < height; row++)
        {
            var y = (uint)(startY + row);
            var offset = (uint)((ulong)y * bytesPerRow);
            memory.WriteByte(sourcePlane + offset, 0x80);
            memory.WriteByte(destinationPlane + offset, 0);
        }

        Assert.Equal(
            1,
            core.BltBitMap(
                source,
                0,
                startY,
                destination,
                0,
                startY,
                1,
                height,
                0xC0,
                0x01,
                0));

        var lastY = (uint)(startY + height - 1);
        var lastOffset = (uint)((ulong)lastY * bytesPerRow);
        Assert.True(memory.TryReadByte(destinationPlane + lastOffset, out var lastValue));
        Assert.Equal((byte)0x80, lastValue);
    }

    [Fact]
    public void BltBitMapRejectsAggregateWorkBeforeTempAOrPlaneProbe()
    {
        // The public width/height arguments are signed words, but a valid
        // BitMap can expose the full 32767x32767 request.  BltBitMap stages
        // two pixel arrays, a destination rollback snapshot, and the final
        // publication; reject that aggregate host workload before reading a
        // plane pointer or allocating an overlap TempA.
        var backing = new FakeMemory(0x2000);
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint sourcePlane = 0x1000;
        const uint destinationPlane = 0x1200;
        foreach (var (bitMap, plane) in new[]
                 { (source, sourcePlane), (destination, destinationPlane) })
        {
            Assert.True(backing.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                0xFFFE));
            Assert.True(backing.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                ushort.MaxValue));
            Assert.True(backing.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapFlags,
                0));
            Assert.True(backing.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                plane));
        }

        var memory = new AddressReadTrackingMemory(
            backing,
            source + (uint)GraphicsLayouts.BitMapPlanes);
        var allocator = new FakeAllocator();
        var core = CreateCore(memory, allocator: allocator);

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltBitMap(
                source,
                0,
                0,
                destination,
                0,
                0,
                short.MaxValue,
                short.MaxValue,
                0xC0,
                0x01,
                0));
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal(0, allocator.FreeCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var registerState = new M68kCpuState
        {
            A = { [0] = source, [1] = destination, [2] = 0xDEAD_0000u },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = 0,
                [3] = 0,
                [4] = 32767u,
                [5] = 32767u,
                [6] = 0xC0,
                [7] = 0x01
            },
            Cycles = 971,
            ProgramCounter = 0x0012_4001
        };
        Assert.False(adapter.TryInvoke(registerState, (int)GraphicsLvo.BltBitMap));
        Assert.Equal(0u, registerState.D[0]);
        Assert.Equal(971, registerState.Cycles);
        Assert.Equal(0x0012_4001u, registerState.ProgramCounter);
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal(0, allocator.FreeCount);

        var overlayState = new M68kCpuState
        {
            A = { [0] = source, [1] = destination, [2] = 0xDEAD_0000u },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = 0,
                [3] = 0,
                [4] = 32767u,
                [5] = 32767u,
                [6] = 0xC0,
                [7] = 0x01
            },
            Cycles = 973,
            ProgramCounter = 0x0012_4003
        };
        Assert.False(adapter.TryInvoke(
            overlayState,
            (int)GraphicsLvo.BltBitMap,
            nativeOverlay: true));
        Assert.Equal(0u, overlayState.D[0]);
        Assert.Equal(973, overlayState.Cycles);
        Assert.Equal(0x0012_4003u, overlayState.ProgramCounter);
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void BltBitMapValidatesTempAOnlyForOverlappingPlanarSpans()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitMap = 0x100;
        const uint plane = 0x400;
        const uint tempA = 0x1200;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(plane, 0x80));

        // The source and destination share one plane and the one-byte
        // raster spans overlap. An odd caller workspace must therefore leave
        // the bitmap untouched and remain available to native ownership.
        Assert.Equal(
            -1,
            core.BltBitMap(bitMap, 0, 0, bitMap, 1, 0, 7, 1, 0xC0, 0x01, tempA + 1));
        Assert.Equal((byte)0x80, ReadByte(memory, plane));

        // A readable, word-aligned TempA is accepted for the same overlap;
        // the host still stages the source transactionally, so the visible
        // result matches the native copy contract.
        Assert.Equal(
            1,
            core.BltBitMap(bitMap, 0, 0, bitMap, 1, 0, 7, 1, 0xC0, 0x01, tempA));
        Assert.Equal((byte)0xC0, ReadByte(memory, plane));

        // A malformed TempA is irrelevant to a non-overlapping copy.
        Assert.True(memory.TryWriteByte(plane, 0x80));
        Assert.Equal(
            1,
            core.BltBitMap(bitMap, 0, 0, bitMap, 8, 0, 1, 1, 0xC0, 0x01, tempA + 1));
        Assert.Equal((byte)0x80, ReadByte(memory, plane));
    }

    [Fact]
    public void BltBitMapRequiresChipVisibleTempABeforeGuestProbe()
    {
        var backing = new FakeMemory(0x4000);
        const uint bitMap = 0x100;
        const uint plane = 0x400;
        const uint tempA = 0x1200;

        WritePlanarBitmap(backing, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteByte(plane, 0x80));
        Assert.True(backing.TryWriteByte(tempA, 0));

        var displayChecks = 0;
        var memory = new DisplayClassMemory(
            backing,
            (address, _) =>
            {
                displayChecks++;
                return address != tempA;
            });
        var core = CreateCore(memory);

        // The source and destination spans overlap, so TempA is a live
        // blitter workspace.  The mapped address is readable and aligned but
        // is deliberately outside the optional chip/display-DMA class.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltBitMap(
                bitMap,
                0,
                0,
                bitMap,
                1,
                0,
                7,
                1,
                0xC0,
                0x01,
                tempA));
        Assert.Equal(1, displayChecks);
        Assert.Equal((byte)0x80, ReadByte(backing, plane));
    }

    [Fact]
    public void BltBitMapRequiresChipVisibleBitmapPlanesBeforeStaging()
    {
        var backing = new FakeMemory(0x4000);
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x600;
        var rejectedAddress = sourcePlane;

        WritePlanarBitmap(backing, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(backing, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteByte(sourcePlane, 0xA5));
        Assert.True(backing.TryWriteByte(destinationPlane, 0x5A));

        var displayChecks = 0;
        var memory = new DisplayClassMemory(
            backing,
            (address, _) =>
            {
                displayChecks++;
                return address != rejectedAddress;
            });
        var core = CreateCore(memory);

        // Readable, aligned source/destination planes are still unavailable
        // to the portable blitter when the active adapter classifies the
        // source plane as non-chip/display-DMA memory.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltBitMap(
                source,
                0,
                0,
                destination,
                0,
                0,
                8,
                1,
                0xC0,
                0x01,
                0));
        Assert.Equal(1, displayChecks);
        Assert.Equal((byte)0x5A, ReadByte(backing, destinationPlane));

        // The destination plane is checked separately after a valid source
        // admission; it must be rejected before any pixel staging as well.
        rejectedAddress = destinationPlane;
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltBitMap(
                source,
                0,
                0,
                destination,
                0,
                0,
                8,
                1,
                0xC0,
                0x01,
                0));
        Assert.Equal(3, displayChecks);
        Assert.Equal((byte)0x5A, ReadByte(backing, destinationPlane));
    }

    [Fact]
    public void BltBitMapAllocatesAndReleasesAChipTempAForNullOverlappingWorkspace()
    {
        var memory = new FakeMemory(0x2000);
        var allocator = new FakeAllocator();
        var core = CreateCore(memory, allocator: allocator);
        const uint bitMap = 0x100;
        const uint plane = 0x400;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(plane, 0x80));

        // A null TempA is a request for graphics.library to obtain one
        // word-aligned Chip scan line when the source and destination spans
        // overlap.  The portable implementation stages the pixels itself,
        // but the guest allocator ownership boundary remains observable.
        Assert.Equal(
            1,
            core.BltBitMap(bitMap, 0, 0, bitMap, 1, 0, 7, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0xC0, ReadByte(memory, plane));
        Assert.Equal((uint)2, allocator.LastAllocatedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastAllocatedClass);
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal((uint)0x1000, allocator.LastFreedAddress);
        Assert.Equal((uint)2, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastFreedClass);
    }

    [Fact]
    public void BltBitMapReleasesAProvisionalTempAWhenTheAllocatorDeclines()
    {
        var memory = new FakeMemory(0x2000);
        var allocator = new DecliningRasterAllocator();
        var core = CreateCore(memory, allocator: allocator);
        const uint bitMap = 0x100;
        const uint plane = 0x400;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(plane, 0x80));

        Assert.Equal(
            -1,
            core.BltBitMap(bitMap, 0, 0, bitMap, 1, 0, 7, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0x80, ReadByte(memory, plane));
        var freed = Assert.Single(allocator.Freed);
        Assert.Equal((uint)0x2000, freed.Address);
        Assert.Equal((uint)2, freed.Bytes);
        Assert.Equal(GraphicsMemoryClass.Chip, freed.MemoryClass);
    }

    [Fact]
    public void BltBitMapReleasesAnOverlappingTempAThatWrapsTheGuestAddressSpace()
    {
        var memory = new FakeMemory(0x2000);
        // BytesPerRow is widened below to four bytes, so this even address's
        // temporary scan-line span would end beyond the 32-bit guest space.
        var allocator = new SequenceAddressAllocator(0xFFFF_FFFEu);
        var core = CreateCore(memory, allocator: allocator);
        const uint bitMap = 0x100;
        const uint plane = 0x400;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(plane, 0x80));

        // The source and destination share one planar span, forcing the
        // allocator-backed TempA path.  The native workspace envelope must be
        // rejected and released before any destination byte is published.
        Assert.Equal(
            -1,
            core.BltBitMap(bitMap, 0, 0, bitMap, 1, 0, 7, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0x80, ReadByte(memory, plane));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Fact]
    public void BltBitMapDetectsOverlappingPlanarSpansWhenPlaneBasesDiffer()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x402;
        const uint tempA = 0x1200;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteWord(
            source + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteWord(
            destination + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(sourcePlane, 0xA5));
        Assert.True(memory.TryWriteByte(sourcePlane + 1, 0x3C));
        Assert.True(memory.TryWriteByte(sourcePlane + 2, 0x7E));
        Assert.True(memory.TryWriteByte(sourcePlane + 3, 0x81));

        // The two word-aligned headers point into the same backing span with
        // a two-byte offset.  A base-address equality check would miss this
        // alias even though a four-byte blit overlaps the source and
        // destination ranges.
        Assert.Equal(
            -1,
            core.BltBitMap(source, 0, 0, destination, 0, 0, 32, 1, 0xC0, 0x01, tempA + 1));
        Assert.Equal((byte)0xA5, ReadByte(memory, sourcePlane));
        Assert.Equal((byte)0x3C, ReadByte(memory, sourcePlane + 1));

        Assert.Equal(
            1,
            core.BltBitMap(source, 0, 0, destination, 0, 0, 32, 1, 0xC0, 0x01, tempA));
        Assert.Equal((byte)0xA5, ReadByte(memory, destinationPlane));
        Assert.Equal((byte)0x3C, ReadByte(memory, destinationPlane + 1));
        Assert.Equal((byte)0x7E, ReadByte(memory, destinationPlane + 2));
        Assert.Equal((byte)0x81, ReadByte(memory, destinationPlane + 3));
    }

    [Fact]
    public void BltBitMapRejectsOddGuestBitmapHeadersBeforeReadingPlanes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint oddSource = 0x101;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x600;

        // A BitMap header is word-addressed on 68k.  The host memory model
        // can represent an odd address, but the portable vector must leave
        // that malformed structure to native/provider ownership.
        WritePlanarBitmap(memory, oddSource, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(sourcePlane, 0xF0));
        Assert.True(memory.TryWriteByte(destinationPlane, 0x5A));

        Assert.Equal(
            -1,
            core.BltBitMap(oddSource, 0, 0, destination, 0, 0, 8, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0x5A, ReadByte(memory, destinationPlane));
    }

    [Fact]
    public void BltBitMapRejectsOddNativePlanePointersBeforeMutation()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint source = 0x100;
        const uint destination = 0x180;
