        Assert.True(memory.TryWriteByte(oddSourcePlane, 0xF0));
        Assert.True(memory.TryWriteByte(destinationPlane, 0x5A));

        Assert.Equal(
            -1,
            core.BltBitMap(source, 0, 0, destination, 0, 0, 8, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0x5A, ReadByte(memory, destinationPlane));

        var state = new M68kCpuState
        {
            A = { [0] = source, [1] = destination },
            D =
            {
                [0] = 1,
                [1] = 0,
                [2] = 0,
                [3] = 0,
                [4] = 8,
                [5] = 1,
                [6] = 0xC0,
                [7] = 0x01
            },
            Cycles = 911
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BltBitMap));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(911, state.Cycles);
