    }

    [Fact]
    public void BltBitMapSupportsDifferentDepthsAndClipsNegativeOrigins()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane0 = 0x600;
        const uint destinationPlane1 = 0x700;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 2, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane0, destinationPlane1, rows: 2, depth: 2);
        memory.TryWriteByte(sourcePlane, 0xF0);
        memory.TryWriteByte(destinationPlane0, 0);
        memory.TryWriteByte(destinationPlane1, 0xAA);

        // Only plane zero participates when the source and destination depths differ.
        Assert.Equal(1, core.BltBitMap(source, 0, 0, destination, 0, 0, 8, 1, 0xC0, 0xFF, 0));
        Assert.Equal((byte)0xF0, ReadByte(memory, destinationPlane0));
        Assert.Equal((byte)0xAA, ReadByte(memory, destinationPlane1));

        memory.TryWriteByte(destinationPlane0, 0);
        // Source X=-2 clips the six-pixel intersection into destination X=2.
        Assert.Equal(1, core.BltBitMap(source, -2, 0, destination, 0, 0, 8, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0x3C, ReadByte(memory, destinationPlane0));

        memory.TryWriteByte(destinationPlane0, 0x5A);
        Assert.Equal(0, core.BltBitMap(source, 16, 0, destination, 0, 0, 1, 1, 0xC0, 0x01, 0));
        Assert.Equal((byte)0x5A, ReadByte(memory, destinationPlane0));
    }

    [Fact]
    public void BltBitMapRestoresEarlierPixelsWhenALaterPlaneWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint sourcePlane0 = 0x600;
        const uint sourcePlane1 = 0x700;
        const uint destinationPlane0 = 0x800;
        const uint destinationPlane1 = 0x900;

        WritePlanarBitmap(backing, source, sourcePlane0, sourcePlane1, rows: 1);
        WritePlanarBitmap(backing, destination, destinationPlane0, destinationPlane1, rows: 1);
        Assert.True(backing.TryWriteByte(sourcePlane0, 0xFF));
        Assert.True(backing.TryWriteByte(sourcePlane1, 0xFF));
        Assert.True(backing.TryWriteByte(destinationPlane0, 0xA5));
        Assert.True(backing.TryWriteByte(destinationPlane1, 0x5A));

        memory.FailOnNextByteWrite(4);
        Assert.Equal(
            -1,
            core.BltBitMap(source, 0, 0, destination, 0, 0, 8, 1, 0xC0, 0x03, 0));
        Assert.Equal((byte)0xA5, ReadByte(backing, destinationPlane0));
        Assert.Equal((byte)0x5A, ReadByte(backing, destinationPlane1));
    }

    [Fact]
    public void BltClearSupportsByteCountRowsAndV36FillWords()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        for (var index = 0u; index < 12; index++)
            memory.TryWriteByte(0x200 + index, 0xCC);

        Assert.Equal(0, core.BltClear(0x200, 4, 0));
        Assert.Equal((byte)0, ReadByte(memory, 0x200));
        Assert.Equal((byte)0, ReadByte(memory, 0x203));
        Assert.Equal((byte)0xCC, ReadByte(memory, 0x204));

        // Rows mode encodes rows in the upper half and bytes-per-row below.
        Assert.Equal(0, core.BltClear(0x204, (2u << 16) | 2u, 0x2));
        Assert.Equal((byte)0, ReadByte(memory, 0x204));
        Assert.Equal((byte)0, ReadByte(memory, 0x205));
        Assert.Equal((byte)0, ReadByte(memory, 0x206));
        Assert.Equal((byte)0, ReadByte(memory, 0x207));

        for (var index = 0u; index < 4; index++)
            memory.TryWriteByte(0x220 + index, 0);
        Assert.Equal(0, core.BltClear(0x220, 4, (uint)(0xA55Au << 16) | 0x4));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0x220));
        Assert.Equal((byte)0x5A, ReadByte(memory, 0x221));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0x222));
        Assert.Equal((byte)0x5A, ReadByte(memory, 0x223));

        Assert.Equal(-1, core.BltClear(0x200, 3, 0));
        // Row mode still describes word-oriented blitter rows: an odd
        // bytes-per-row value is malformed even when the row count is valid.
        Assert.Equal(-1, core.BltClear(0x200, (2u << 16) | 3u, 0x2));
        // V36 fill-word mode composes with rows mode: the low/high halves of
        // byteCount still select the row geometry, while Flags' high word is
        // repeated into each row.
        Assert.Equal(0, core.BltClear(0x200, (2u << 16) | 2u, (uint)(0x0002u << 16) | 0x6));
        Assert.Equal((byte)0x00, ReadByte(memory, 0x200));
        Assert.Equal((byte)0x02, ReadByte(memory, 0x201));
        Assert.Equal((byte)0x00, ReadByte(memory, 0x202));
        Assert.Equal((byte)0x02, ReadByte(memory, 0x203));
        Assert.Equal(-1, core.BltClear(0x201, 2, 0));
    }

    [Fact]
    public void BltClearRequiresChipVisibleMemBlockBeforeGuestProbe()
    {
        var backing = new FakeMemory(0x1000);
        const uint address = 0x200;
        for (var offset = 0u; offset < 4; offset++)
            Assert.True(backing.TryWriteByte(address + offset, 0xA5));

        var displayChecks = 0;
        var memory = new DisplayClassMemory(
            backing,
            (candidate, _) =>
            {
                displayChecks++;
                return candidate != address;
            });
        var core = CreateCore(memory);

        // The complete span is mapped, even, and readable, but the active
        // adapter classifies it as non-chip memory.  Decline before the first
        // destination read or clear publication.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltClear(address, 4, 0));
        Assert.Equal(1, displayChecks);
        for (var offset = 0u; offset < 4; offset++)
            Assert.Equal((byte)0xA5, ReadByte(backing, address + offset));
    }

    [Fact]
    public void BltClearTreatsAnEmptySpanAsAClaimedNoOp()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);

        // The classic loop does not dereference memBlock when scalar bytecount
        // is zero.  Row mode has the same empty-loop result after its required
        // even-pointer envelope is admitted.
        Assert.Equal(0, core.BltClear(0, 0, 0));
        Assert.Equal(0, core.BltClear(0x200, 0x0001_0000u, 0x2));
        Assert.Equal(0, core.BltClear(0x200, 0x0000_0002u, 0x2));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState();
        state.A[1] = 0;
        state.D[0] = 0;
        state.D[1] = 0x0000_0004u;

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltClear));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void BltClearRejectsAnUnstageableMaximumSpanBeforeWalkingIt()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint address = 0x1FFE;
        var byteCount = (unchecked((uint)ushort.MaxValue) << 16) |
            (uint)(ushort.MaxValue - 1);

        // Rows mode describes an even 65534-byte stride and 65535 rows. The
        // guest span is arithmetically valid but exceeds the transactional
        // host staging contract; it must fail immediately rather than
        // entering a multi-billion-byte preflight walk.
        Assert.Equal(-1, core.BltClear(address, byteCount, 0x2));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState();
        state.A[1] = address;
        state.D[0] = byteCount;
        state.D[1] = 0x2;

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BltClear));
        Assert.Equal(byteCount, state.D[0]);
    }

    [Fact]
    public void BltClearRejectsAggregateWorkBeforeReadingTheDestination()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FFE);
        var core = CreateCore(memory);
        const uint address = 0x1FFE;
        var byteCount = (unchecked((uint)ushort.MaxValue) << 16) | 16384u;

        // The span is valid in the 32-bit guest envelope and below the
        // Int32 snapshot-size limit, but probe + rollback snapshot + publish
        // exceed the portable three-pass byte budget. The destination is
        // intentionally unmapped so the guard must run before any byte read.
        Assert.Equal(-1, core.BltClear(address, byteCount, 0x2));
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void BltClearRestoresEarlierRowsWhenALaterByteWriteFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint address = 0x200;

        Assert.True(backing.TryWriteByte(address, 0xA1));
        Assert.True(backing.TryWriteByte(address + 1u, 0xB2));
        Assert.True(backing.TryWriteByte(address + 2u, 0xC3));
        Assert.True(backing.TryWriteByte(address + 3u, 0xD4));
        memory.FailOnNextByteWrite(3);
        Assert.Equal(
            -1,
            core.BltClear(address, (2u << 16) | 2u, 0));
        Assert.Equal((byte)0xA1, ReadByte(backing, address));
        Assert.Equal((byte)0xB2, ReadByte(backing, address + 1u));
        Assert.Equal((byte)0xC3, ReadByte(backing, address + 2u));
        Assert.Equal((byte)0xD4, ReadByte(backing, address + 3u));
    }

    [Fact]
    public void ClipBlitUsesRastPortBitMapsAndRejectsLayeredPorts()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint sourceRastPort = 0x20;
        const uint destinationRastPort = 0xB0;
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint sourcePlane = 0x500;
        const uint destinationPlane = 0x600;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 2, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 2, depth: 1);
        memory.TryWriteByte(sourcePlane, 0xF0);
        memory.TryWriteLong(sourceRastPort + (uint)GraphicsLayouts.RastPortBitMap, source);
        memory.TryWriteLong(destinationRastPort + (uint)GraphicsLayouts.RastPortBitMap, destination);
        memory.TryWriteByte(destinationRastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF);

        Assert.Equal(1, core.ClipBlit(sourceRastPort, 0, 0, destinationRastPort, 0, 0, 8, 1, 0xC0));
        Assert.Equal((byte)0xF0, ReadByte(memory, destinationPlane));

        memory.TryWriteByte(destinationPlane, 0);
        memory.TryWriteByte(destinationRastPort + (uint)GraphicsLayouts.RastPortMask, 0);
        Assert.Equal(0, core.ClipBlit(sourceRastPort, 0, 0, destinationRastPort, 0, 0, 8, 1, 0xC0));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane));

        memory.TryWriteLong(destinationRastPort + (uint)GraphicsLayouts.RastPortLayer, 0x1234);
        Assert.Equal(-1, core.ClipBlit(sourceRastPort, 0, 0, destinationRastPort, 0, 0, 8, 1, 0xC0));
    }

