    [Fact]
    public void BltMaskBitMapRastPortRequiresItsExternalMaskEvenWhenRastPortMaskIsZero()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint rastPort = 0x20;
        const uint malformedBlitMask = 0x2000;
        const uint validBlitMask = 0x1FF0;

        Assert.True(memory.TryWriteWord(source + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(source + (uint)GraphicsLayouts.BitMapRows, 1));
        Assert.True(memory.TryWriteByte(source + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(memory.TryWriteLong(source + (uint)GraphicsLayouts.BitMapPlanes, 0x500));
        Assert.True(memory.TryWriteWord(destination + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(destination + (uint)GraphicsLayouts.BitMapRows, 1));
        Assert.True(memory.TryWriteByte(destination + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(memory.TryWriteLong(destination + (uint)GraphicsLayouts.BitMapPlanes, 0x700));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, destination));
        Assert.True(memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0));
        Assert.True(memory.TryWriteByte(0x500, 0xA5));
        Assert.True(memory.TryWriteByte(0x700, 0x5A));
        Assert.True(memory.TryWriteByte(validBlitMask, 0xFF));
        Assert.True(memory.TryWriteByte(validBlitMask + 1, 0xFF));

        Assert.Equal(
            -1,
            core.BltMaskBitMapRastPort(
