    }

    [Fact]
    public void BltMaskBitMapRastPortRequiresChipVisibleExternalMaskBeforeGuestProbe()
    {
        var backing = new FakeMemory(0x4000);
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint rastPort = 0x20;
        const uint sourcePlane = 0x500;
        const uint destinationPlane = 0x600;
        const uint blitMask = 0x800;

        WritePlanarBitmap(backing, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(backing, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteByte(sourcePlane, 0xF0));
        Assert.True(backing.TryWriteByte(destinationPlane, 0x5A));
        Assert.True(backing.TryWriteByte(blitMask, 0xFF));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            destination));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));

        var displayChecks = 0;
        var memory = new DisplayClassMemory(
            backing,
            (address, _) =>
            {
                displayChecks++;
                return address != blitMask;
            });
        var core = CreateCore(memory);
        // CreateCore installs its ordinary fixture RastPort. Rebind the
        // operation under test after that shared setup has completed.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            destination));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltMaskBitMapRastPort(
                source,
                0,
                0,
                rastPort,
                0,
                0,
                8,
                1,
                0xC0,
                blitMask));
        Assert.Equal(1, displayChecks);
        Assert.Equal((byte)0x5A, ReadByte(backing, destinationPlane));
    }

