    [Fact]
    public void BltPatternUsesAreaPatternAndContiguousStencilWithClipping()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint areaPattern = 0x800;
        const uint stencil = 0x900;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 2, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, areaPattern);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 1);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1);
        memory.TryWriteWord(areaPattern, 0xAAAA);
        memory.TryWriteWord(areaPattern + 2, 0x5555);
        memory.TryWriteByte(stencil, 0xF0);
        memory.TryWriteByte(stencil + 2, 0x0F);

        Assert.Equal(0, core.BltPattern(rastPort, stencil, 0, 0, 7, 1, 2));
        Assert.Equal((byte)0xA0, ReadByte(memory, plane));
        Assert.Equal((byte)0x05, ReadByte(memory, plane + 2));

        memory.TryWriteByte(plane, 0);
        Assert.Equal(0, core.RectFill(rastPort, 0, 0, 7, 0));
        Assert.Equal((byte)0xAA, ReadByte(memory, plane));

        memory.TryWriteByte(plane, 0);
        memory.TryWriteByte(plane + 2, 0);
        Assert.Equal(0, core.BltPattern(rastPort, 0, -2, 0, 7, 0, 0));
        Assert.Equal((byte)0xAA, ReadByte(memory, plane));

        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 0);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, 0);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0);
        Assert.Equal(0, core.BltPattern(rastPort, 0, 0, 0, 7, 0, 0));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane));

        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, areaPattern);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, unchecked((byte)-1));
        const uint multicolorBitmap = 0xA00;
        const uint multicolorPlane0 = 0xC00;
        const uint multicolorPlane1 = 0xD00;
        WritePlanarBitmap(memory, multicolorBitmap, multicolorPlane0, multicolorPlane1, rows: 2, depth: 2);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, multicolorBitmap);
        memory.TryWriteWord(areaPattern, 0xFFFF);
        memory.TryWriteWord(areaPattern + 2, 0x0000);
        memory.TryWriteWord(areaPattern + 4, 0x0000);
        memory.TryWriteWord(areaPattern + 6, 0xFFFF);
        Assert.Equal(0, core.BltPattern(rastPort, 0, 0, 0, 7, 1, 0));
        Assert.Equal((byte)0xFF, ReadByte(memory, multicolorPlane0));
        Assert.Equal((byte)0x00, ReadByte(memory, multicolorPlane0 + 2));
        Assert.Equal((byte)0x00, ReadByte(memory, multicolorPlane1));
        Assert.Equal((byte)0xFF, ReadByte(memory, multicolorPlane1 + 2));

        // JAM1 treats a nonzero multicolor source as a stencil and deposits
        // APen, rather than the encoded source color.
        memory.TryWriteByte(multicolorPlane0, 0);
        memory.TryWriteByte(multicolorPlane0 + 2, 0);
        memory.TryWriteByte(multicolorPlane1, 0);
        memory.TryWriteByte(multicolorPlane1 + 2, 0);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0);
        Assert.Equal(0, core.BltPattern(rastPort, 0, 0, 0, 7, 1, 0));
        Assert.Equal((byte)0xFF, ReadByte(memory, multicolorPlane0));
        Assert.Equal((byte)0xFF, ReadByte(memory, multicolorPlane0 + 2));
        Assert.Equal((byte)0x00, ReadByte(memory, multicolorPlane1));
        Assert.Equal((byte)0x00, ReadByte(memory, multicolorPlane1 + 2));

        // INVERSVID reverses every source plane of a multicolor pattern
        // before JAM2 deposits the resulting color.
        memory.TryWriteByte(multicolorPlane0, 0);
        memory.TryWriteByte(multicolorPlane0 + 2, 0);
        memory.TryWriteByte(multicolorPlane1, 0);
        memory.TryWriteByte(multicolorPlane1 + 2, 0);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 5);
        Assert.Equal(0, core.BltPattern(rastPort, 0, 0, 0, 7, 1, 0));
        Assert.Equal((byte)0x00, ReadByte(memory, multicolorPlane0));
        Assert.Equal((byte)0xFF, ReadByte(memory, multicolorPlane0 + 2));
        Assert.Equal((byte)0xFF, ReadByte(memory, multicolorPlane1));
        Assert.Equal((byte)0x00, ReadByte(memory, multicolorPlane1 + 2));

        Assert.Equal(-1, core.BltPattern(rastPort, stencil, 0, 0, 7, 0, 3));
    }

    [Fact]
    public void BltPatternMulticolorJam2DepositsEncodedPlanesWithoutReadingPens()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane0 = 0x500;
        const uint plane1 = 0x600;
        const uint areaPattern = 0x800;

        WritePlanarBitmap(memory, bitMap, plane0, plane1, rows: 8, depth: 2);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0x03));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            areaPattern));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            unchecked((byte)-1)));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            1)); // JAM2

        // A negative AreaPtSz is a multicolor pattern: each declared plane
        // contributes one contiguous power-of-two-height word table.  JAM2
        // deposits those encoded planes directly and therefore has no pen
        // phase.  Make both public pen bytes unreadable to prove that the
        // portable ownership boundary does not consume them.
        Assert.True(memory.TryWriteWord(areaPattern, 0xFF00));
        Assert.True(memory.TryWriteWord(areaPattern + 2, 0x0000));
        Assert.True(memory.TryWriteWord(areaPattern + 4, 0x0000));
        Assert.True(memory.TryWriteWord(areaPattern + 6, 0xFF00));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            2);

        Assert.Equal(0, core.BltPattern(rastPort, 0, 0, 0, 7, 1, 0));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0xFF, ReadByte(memory, plane0));
        Assert.Equal((byte)0x00, ReadByte(memory, plane1));
        Assert.Equal((byte)0x00, ReadByte(memory, plane0 + 2));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane1 + 2));

        Assert.True(memory.TryWriteByte(plane0, 0));
        Assert.True(memory.TryWriteByte(plane1, 0));
        Assert.True(memory.TryWriteByte(plane0 + 2, 0));
        Assert.True(memory.TryWriteByte(plane1 + 2, 0));

        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 1, [4] = 0xA5A5_0000u },
            Cycles = 617
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltPattern));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(617, state.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0xFF, ReadByte(memory, plane0));
        Assert.Equal((byte)0x00, ReadByte(memory, plane1));
        Assert.Equal((byte)0x00, ReadByte(memory, plane0 + 2));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane1 + 2));
    }

    [Fact]
    public void FloodMulticolorJam2DepositsEncodedPlanesWithoutReadingPens()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint areaPattern = 0x800;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        // Mode 0 uses OutlinePen as the source boundary. Keep the encoded
        // multicolour values below that pen so the complete zero-valued
        // region remains connected while Flood deposits the pattern.
        Assert.Equal(0, core.SetOutlinePen(rastPort, 3));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1)); // JAM2
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            areaPattern));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            unchecked((byte)-1)));
        Assert.True(memory.TryWriteWord(areaPattern, 0xFF00));
        Assert.True(memory.TryWriteWord(areaPattern + 2, 0x0000));
        Assert.True(memory.TryWriteWord(areaPattern + 4, 0x0000));
        Assert.True(memory.TryWriteWord(areaPattern + 6, 0xFF00));

        // Negative AreaPtSz selects encoded planes directly. Flood must not
        // claim either public pen byte, even though ordinary JAM2 consumes
        // both fields.
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            2);

        Assert.Equal(1, core.Flood(rastPort, 0, 0, 0));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0xFF, ReadByte(memory, plane0));
        Assert.Equal((byte)0x00, ReadByte(memory, plane1));
        Assert.Equal((byte)0x00, ReadByte(memory, plane0 + 2));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane1 + 2));

        // Re-run through the register ABI on a fresh source region after the
        // direct call has consumed its connected pixels.
        Assert.True(memory.TryWriteByte(plane0, 0));
        Assert.True(memory.TryWriteByte(plane1, 0));
        Assert.True(memory.TryWriteByte(plane0 + 2, 0));
        Assert.True(memory.TryWriteByte(plane1 + 2, 0));
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0xA5A5_0000u },
            Cycles = 619
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(619, state.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0xFF, ReadByte(memory, plane0));
        Assert.Equal((byte)0x00, ReadByte(memory, plane1));
        Assert.Equal((byte)0x00, ReadByte(memory, plane0 + 2));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane1 + 2));
    }

    [Fact]
    public void AreaEndMulticolorJam2DepositsEncodedPlanesWithoutReadingPens()
    {
        var backing = new FakeMemory(0x4000);
