    [Fact]
    public void RectFillInverseVideoJam1SkipsUnselectedPlanarStorage()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            8));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        // A valid header with a row span that crosses the guest boundary.
        // INVERSVID|JAM1 selects no source cells, so RectFill must not probe
        // or mutate this plane.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF8));
        Assert.Equal(0, core.SetDrawMode(rastPort, 4));

        Assert.Equal(0, core.RectFill(rastPort, 0, 0, 7, 7));
    }

    [Fact]
    public void RectFillWithoutAreaPatternDoesNotRequireAreaPatternSize()
    {
        var backing = new FakeMemory(0x2000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;

        WritePlanarBitmap(backing, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            0));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0)); // JAM1

        // Native RectFill reads AreaPtrn to choose its no-pattern fast path,
        // but does not consume AreaPtSz unless a real area pattern is
        // attached. Keep that trailing byte unavailable and exercise both
        // the pure core and the mapped CopperStart gateway.
        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            sizeof(byte));
        var core = CreateCore(memory);

        Assert.Equal(0, core.RectFill(rastPort, 0, 0, 7, 0));
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));

        Assert.True(backing.TryWriteByte(plane, 0));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 0 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RectFill));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));
    }

    [Fact]
    public void RectFillJam1WithoutAreaPatternDoesNotRequireBackgroundPen()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
