            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0)); // JAM1

        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(backgroundPenAddress, sizeof(byte));
        var core = CreateCore(memory);

        // Native no-pattern JAM1 writes APen and never needs BPen.
        Assert.Equal(0, core.RectFill(rastPort, 0, 0, 7, 0));
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));

        Assert.True(backing.TryWriteByte(plane, 0));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 0 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RectFill));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));
    }

    [Fact]
    public void RectFillAndBltPatternDeclinePrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        static void SeedPrivatePens(
            FakeMemory backing,
            RangeReadFaultMemory memory,
            uint rastPort,
            uint plane0,
            uint plane1)
        {
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.True(backing.TryWriteByte(plane0, 0x3C));
            Assert.True(backing.TryWriteByte(plane1, 0xC3));
            // A private-colour decline must precede the public bitmap
            // pointer as well as the later mode/pen fields.
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                sizeof(uint));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                2u);
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            SeedPrivatePens(backing, memory, rastPort, plane0, plane1);

            Assert.Equal(-1, core.RectFill(rastPort, 0, 0, 3, 0));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal(-1, core.BltPattern(rastPort, 0, 0, 0, 3, 0, 0));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x3C, ReadByte(backing, plane0));
            Assert.Equal((byte)0xC3, ReadByte(backing, plane1));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            SeedPrivatePens(backing, memory, rastPort, plane0, plane1);
            var adapter = new CopperStartGraphicsRegisterAdapter(core);

            var rect = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0, [1] = 0, [2] = 3, [3] = 0 },
                Cycles = 47
            };
            Assert.False(adapter.TryInvoke(rect, (int)GraphicsLvo.RectFill));
            Assert.Equal(0u, rect.D[0]);
            Assert.Equal(47, rect.Cycles);
            Assert.Equal(0, memory.FaultedReadCount);

            var pattern = new M68kCpuState
            {
                A = { [0] = 0, [1] = rastPort },
                D = { [0] = 0, [1] = 0, [2] = 3, [3] = 0, [4] = 0 },
                Cycles = 53
            };
            Assert.False(adapter.TryInvoke(pattern, (int)GraphicsLvo.BltPattern));
            Assert.Equal(0u, pattern.D[0]);
            Assert.Equal(53, pattern.Cycles);
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x3C, ReadByte(backing, plane0));
            Assert.Equal((byte)0xC3, ReadByte(backing, plane1));
        }
    }

