    [Fact]
    public void NegativeMulticolorJam1LeavesZeroSourceCellsUntouched()
    {
        var memory = new FakeMemory(0x3000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane0 = 0x500;
        const uint plane1 = 0x600;
        const uint areaPattern = 0x800;

        WritePlanarBitmap(memory, bitMap, plane0, plane1, rows: 1, depth: 2);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, areaPattern);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, unchecked((byte)-1));
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 3);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0); // JAM1
        memory.TryWriteByte(plane0, 0x5A);
        memory.TryWriteByte(plane1, 0xA5);
        // Both multicolor source planes are zero: JAM1 must have no stencil
        // hits, rather than treating the decoded value as an all-one fill.
        memory.TryWriteWord(areaPattern, 0);
        memory.TryWriteWord(areaPattern + 2, 0);

        Assert.Equal(0, core.BltPattern(rastPort, 0, 0, 0, 7, 0, 0));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane0));
        Assert.Equal((byte)0xA5, ReadByte(memory, plane1));
    }

