    [Fact]
    public void BltPatternInversVidInvertsANullAreaPatternMaskExceptComplementJam2()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint mask = 0x700;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteByte(mask, 0xA0));
        Assert.True(memory.TryWriteByte(mask + 1, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 1));

        // Null AreaPtrn uses the external mask as a BltTemplate source.
        // INVERSVID selects the zero mask cells for JAM1, just as the native
        // template path does.
        Assert.Equal(0, core.SetDrawMode(rastPort, 4)); // JAM1 | INVERSVID
        Assert.Equal(0, core.BltPattern(rastPort, mask, 0, 0, 7, 0, 2));
        Assert.Equal((byte)0x5F, ReadByte(memory, plane));

        // The external-mask JAM2 path is reduced to the same template/JAM1
        // operation before INVERSVID is applied; BPen must not fill the
        // unselected source-zero cells.
        Assert.True(memory.TryWriteByte(plane, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 5)); // JAM2 | INVERSVID
        Assert.Equal(0, core.BltPattern(rastPort, mask, 0, 0, 7, 0, 2));
        Assert.Equal((byte)0x5F, ReadByte(memory, plane));

        // The same inverted mask selects the destination for COMPLEMENT.
        Assert.True(memory.TryWriteByte(plane, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 6)); // COMPLEMENT | INVERSVID
        Assert.Equal(0, core.BltPattern(rastPort, mask, 0, 0, 7, 0, 2));
        Assert.Equal((byte)0x5F, ReadByte(memory, plane));

        // COMPLEMENT|JAM2 is the native whole-region shortcut; its supplied
        // mask remains the selected stencil rather than being inverted.
        Assert.True(memory.TryWriteByte(plane, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 7));
        Assert.Equal(0, core.BltPattern(rastPort, mask, 0, 0, 7, 0, 2));
        Assert.Equal((byte)0xA0, ReadByte(memory, plane));
    }

