    [Fact]
    public void ComplementJam2DoesNotRequireAreaPatternStorageAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint unusablePattern = 0x801;

        var backing = new FakeMemory(0x2000);
        WritePlanarBitmap(backing, bitMap, plane, 0, rows: 1, depth: 1);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            unusablePattern));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            3)); // JAM2 | COMPLEMENT

        // The whole-region inversion shortcut does not consume either the
        // attached AreaPtrn words or AreaPtSz.  Make both source envelopes
        // unreadable so any accidental preflight would claim the wrong path.
        memory.FailReads(unusablePattern, sizeof(ushort));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            sizeof(byte));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        Assert.Equal(0, core.RectFill(rastPort, 0, 0, 7, 0));
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));

        Assert.True(backing.TryWriteByte(plane, 0));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 0 }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RectFill));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));
    }

    [Fact]
    public void HostRegisterAdapterRoutesMaskedAndPatternBlits()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint rastPort = 0x20;
        const uint sourcePlane = 0x500;
        const uint destinationPlane = 0x600;
        const uint blitMask = 0x800;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);
        memory.TryWriteByte(sourcePlane, 0xC0);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, destination);
        memory.TryWriteByte(blitMask, 0xC0);

        var state = new M68kCpuState();
        state.A[0] = source;
        state.A[1] = rastPort;
        state.D[0] = 0;
        state.D[1] = 0;
        state.D[2] = 0;
        state.D[3] = 0;
        state.A[2] = blitMask;
        state.D[4] = 8;
        state.D[5] = 1;
        state.D[6] = 0xC0;

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltBitMapRastPort));
        Assert.Equal(1u, state.D[0]);

        state.D[0] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltMaskBitMapRastPort));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane));

        state.A[0] = 0;
        state.A[1] = rastPort;
        state.D[0] = 0;
        state.D[1] = 0;
        state.D[2] = 7;
        state.D[3] = 0;
        state.D[4] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltPattern));
        Assert.Equal(0u, state.D[0]);
    }

