    [Fact]
    public void BltPatternWithZeroEffectiveMaskDoesNotRequirePensOrPatternFields()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint unusableStencil = 0x1FF8;

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);

        // Re-apply this test's sparse one-plane envelope after CreateCore's
        // conventional two-plane fixture setup.
        WritePlanarBitmap(backing, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));
        Assert.True(backing.TryWriteByte(plane, 0xA5));

        // Pens cannot affect a zero-effective-mask operation. Keep both
        // public pen bytes unreadable to prove the admission envelope stops
        // after the valid RastPort/BitMap header and mask.
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            2u);

        Assert.Equal(
            0,
            core.BltPattern(
                rastPort,
                unusableStencil,
                0,
                0,
                7,
                0,
                2));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0xA5, ReadByte(backing, plane));

        // RPF_NO_PENS remains a provider/native ownership marker even when
        // no destination plane is selected.
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)GraphicsLayouts.RastPortNoPens));
        Assert.Equal(
            -1,
            core.BltPattern(
                rastPort,
                unusableStencil,
                0,
                0,
                7,
                0,
                2));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            0));

        // The register path must make the same direct-vs-mapped ownership
        // decision and must not consume the caller's cycle frame.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = unusableStencil, [1] = rastPort },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = 7,
                [3] = 0,
                [4] = 2,
                [5] = 0xCAFE_BABEu
            },
            Cycles = 67
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltPattern));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0xCAFE_BABEu, state.D[5]);
        Assert.Equal(67, state.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0xA5, ReadByte(backing, plane));
    }

    [Fact]
    public void BltPatternRejectsAnUnstageableMaximumPixelWalkBeforeVisibilityPreflight()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        var visibilityCalls = 0;

        WriteWideBitmap(memory, bitMap, 0x0030_0000, bytesPerRow: 8192, rows: ushort.MaxValue);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 0);

        // The signed-word request is 65536 x 65536 pixels and the linked
        // bitmap is itself above the portable Int32 pixel budget.  Decline
        // before invoking the layer visibility predicate (and before the
        // first pattern/plane probe).
        Assert.Equal(
            -1,
            GraphicsRasterOperations.BltPattern(
                memory,
                rastPort,
                0,
                unchecked((short)short.MinValue),
                unchecked((short)short.MinValue),
                short.MaxValue,
                short.MaxValue,
                0,
                (_, _) =>
                {
                    visibilityCalls++;
                    return false;
                }));
        Assert.Equal(0, visibilityCalls);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D =
            {
                [0] = 0x0000_8000u,
                [1] = 0x0000_8000u,
                [2] = 0x0000_7FFFu,
                [3] = 0x0000_7FFFu,
                [4] = 0,
                [5] = 0xCAFE_BABEu
            },
            Cycles = 91
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BltPattern));
        Assert.Equal(0x0000_8000u, state.D[0]);
        Assert.Equal(0xCAFE_BABEu, state.D[5]);
        Assert.Equal(91, state.Cycles);

        // The implicit all-one source under INVERSVID|JAM1 is a genuine
        // bounded no-op, even for the same maximal geometry.  Keep that
        // semantic shortcut ahead of the general pixel-walk budget.
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 4);
        Assert.Equal(
            0,
            GraphicsRasterOperations.BltPattern(
                memory,
                rastPort,
                0,
                unchecked((short)short.MinValue),
                unchecked((short)short.MinValue),
                short.MaxValue,
                short.MaxValue,
                0));
    }

    [Fact]
    public void BltPatternRejectsAggregateWorkBeforeReadingTheDestination()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2048));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(backing.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF0));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            0));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            0));

        // The clipped 16384 x 65535 destination is below Int32.MaxValue as
        // a pixel count, but its pattern preflight, rollback snapshot, and
        // publication exceed the three-pass host budget. The plane target is
        // intentionally unmapped so admission must precede its first read.
        Assert.Equal(
            -1,
            core.BltPattern(
                rastPort,
                0,
                0,
                0,
                short.MaxValue,
                short.MaxValue,
                0));
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void HostRegisterAdapterRoutesInitTmpRas()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState();
        state.A[0] = 0x100;
        state.A[1] = 0x200;
        state.D[0] = 0x20;

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitTmpRas));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0x200u, ReadLong(memory, 0x100));
        Assert.Equal(0x20u, ReadLong(memory, 0x104));

        state.A[1] = 0;
        state.D[0] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitTmpRas));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0u, ReadLong(memory, 0x100));
        Assert.Equal(0u, ReadLong(memory, 0x104));
    }

    [Fact]
    public void BltTemplateUsesBitOffsetDrawModeAndRastPortClipping()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint template = 0x700;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 2, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(template, 0xA0);
        memory.TryWriteByte(template + 2, 0x50);

        Assert.Equal(0, core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 2));
        Assert.Equal((byte)0xA0, ReadByte(memory, plane));
        Assert.Equal((byte)0x50, ReadByte(memory, plane + 2));

        memory.TryWriteByte(plane, 0);
        memory.TryWriteByte(plane + 2, 0);
        Assert.Equal(0, core.BltTemplate(template, 0, 2, rastPort, -2, 0, 8, 1));
        Assert.Equal((byte)0x80, ReadByte(memory, plane));

        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x1234);
        Assert.Equal(-1, core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 1));
    }

