    [Fact]
    public void BltTemplateSupportsNegativeEvenSourceModulo()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint template = 0x704;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 2, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(template, 0x80);
        memory.TryWriteByte(template - 2u, 0x40);

        // BLTxMOD is signed: the second source row is two bytes before the
        // aligned first-row pointer.
        Assert.Equal(0, core.BltTemplate(template, 0, -2, rastPort, 0, 0, 1, 2));
        Assert.Equal((byte)0x80, ReadByte(memory, plane));
        // The reverse row contains bit 1 (0x40), outside the one-pixel
        // destination at source bit offset zero, so row one remains clear.
        Assert.Equal((byte)0x00, ReadByte(memory, plane + 2));
    }

    [Fact]
    public void BltTemplateRejectsAnOddSourcePointerAtTheWordBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint oddTemplate = 0x701;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(oddTemplate, 0xFF);
        memory.TryWriteByte(plane, 0x5A);

        // BltTemplate's source points at an aligned UWORD on the native
        // blitter boundary.  An odd guest pointer must remain available to a
        // native/provider implementation instead of being read as a byte
        // template by the portable path.
        Assert.Equal(-1, core.BltTemplate(oddTemplate, 0, 2, rastPort, 0, 0, 8, 1));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));
    }

    [Fact]
    public void BltTemplateTreatsEmptyAndFullyClippedDestinationsAsSourceFreeNoOps()
    {
        var backing = new FakeMemory(0x4000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint unreadableTemplate = 0x1FFE;

        WritePlanarBitmap(backing, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteByte(plane, 0xA5));

        var memory = new AddressReadTrackingMemory(backing, unreadableTemplate);
        var core = CreateCore(memory);

        // A zero/negative template extent is a clipped void-blit no-op.  The
        // source pointer and modulo are deliberately malformed: no template
        // byte should be admitted when no destination cell can be touched.
        Assert.Equal(
            GraphicsRasterOperations.Success,
            core.BltTemplate(
                0,
                7,
                1,
                rastPort,
                0,
                0,
                0,
                1));
        Assert.Equal(
            GraphicsRasterOperations.Success,
            core.BltTemplate(
                0,
                7,
                1,
                rastPort,
                100,
                0,
                8,
                1));
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal((byte)0xA5, ReadByte(backing, plane));

        // The register gateway keeps the same source-free admission rule and
        // still publishes the documented void result.  Its cycle count and
        // source/template memory remain untouched for both empty forms.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D =
            {
                [0] = 7,
                [1] = 1,
                [2] = 0,
                [3] = 0,
                [4] = 0,
                [5] = 1
            },
            Cycles = 37
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(37, state.Cycles);

        state.A[0] = 0;
        state.D[0] = 7;
        state.D[1] = 1;
        state.D[2] = 100;
        state.D[4] = 8;
        state.D[5] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(37, state.Cycles);
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal((byte)0xA5, ReadByte(backing, plane));
    }

    [Fact]
    public void BltTemplateRequiresChipVisibleSourceBeforeGuestProbe()
    {
        var backing = new FakeMemory(0x4000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint template = 0x700;

        WritePlanarBitmap(backing, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            1));
        Assert.True(backing.TryWriteByte(template, 0xF0));
        Assert.True(backing.TryWriteByte(plane, 0x5A));

        var displayChecks = 0;
        var memory = new DisplayClassMemory(
            backing,
            (address, _) =>
            {
                displayChecks++;
                return address != template;
            });
        var core = CreateCore(memory);

        // The template bytes are readable and word-aligned, but the active
        // CopperStart address-class adapter reports fast/non-chip memory. The
        // source must be declined before the first template byte is read or
        // the destination plane is changed.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 1));
        Assert.Equal(1, displayChecks);
        Assert.Equal((byte)0x5A, ReadByte(backing, plane));
    }

    [Fact]
