    [Fact]
    public void BltTemplateAppliesComplementToJam2BackgroundCells()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint template = 0x700;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(template, 0xA0);
        memory.TryWriteByte(plane, 0x00);
        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetBPen(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2 | COMPLEMENT

        // Both template phases are subject to COMPLEMENT.  Starting from a
        // clear byte therefore toggles every cell, not only the source-one
        // foreground bits.
        Assert.Equal(0, core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 1));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane));
    }

    [Fact]
    public void BltTemplateComplementJam2DoesNotRequireBackgroundPenAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint template = 0x700;

        static void Prepare(
            GraphicsLibraryCore core,
            FakeMemory memory,
            uint rastPort,
            uint bitMap,
            uint plane,
            uint template)
        {
            WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(memory.TryWriteByte(template, 0xA0));
            Assert.Equal(0, core.SetAPen(rastPort, 1));
            Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2 | COMPLEMENT
        }

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(core, backing, rastPort, bitMap, plane, template);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            sizeof(byte));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        Assert.Equal(0, core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 1));
        Assert.Equal((byte)0xFF, ReadByte(backing, plane));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(mappedCore, mappedBacking, rastPort, bitMap, plane, template);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            sizeof(byte));
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0, [1] = 2, [2] = 0, [3] = 0, [4] = 8, [5] = 1 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xFF, ReadByte(mappedBacking, plane));
    }

    [Fact]
    public void BltTemplateDeclinesPrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane0 = 0x500;
        const uint plane1 = 0x600;
        const uint template = 0x700;

        static void Prepare(
            FakeMemory backing,
            GraphicsLibraryCore core,
            uint rastPort,
            uint bitMap,
            uint plane0,
            uint plane1,
            uint template)
        {
            WritePlanarBitmap(backing, bitMap, plane0, plane1, rows: 1, depth: 2);
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(backing.TryWriteByte(template, 0xF0));
            Assert.Equal(0, core.SetDrawMode(rastPort, 1)); // JAM2
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Prepare(backing, core, rastPort, bitMap, plane0, plane1, template);
            Assert.True(backing.TryWriteByte(plane0, 0x3C));
            Assert.True(backing.TryWriteByte(plane1, 0xC3));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte) * 2u);
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                sizeof(uint));

            Assert.Equal(
                GraphicsRasterOperations.Failure,
                core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 1));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x3C, ReadByte(backing, plane0));
            Assert.Equal((byte)0xC3, ReadByte(backing, plane1));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Prepare(backing, core, rastPort, bitMap, plane0, plane1, template);
            Assert.True(backing.TryWriteByte(plane0, 0x3C));
            Assert.True(backing.TryWriteByte(plane1, 0xC3));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte) * 2u);
            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            var state = new M68kCpuState
            {
                A = { [0] = template, [1] = rastPort },
                D = { [0] = 0xDEAD_BEEFu, [1] = 2, [2] = 0, [3] = 0, [4] = 8, [5] = 1 },
                Cycles = 83
            };

            Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BltTemplate));
            Assert.Equal(0xDEAD_BEEFu, state.D[0]);
            Assert.Equal(83, state.Cycles);
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x3C, ReadByte(backing, plane0));
            Assert.Equal((byte)0xC3, ReadByte(backing, plane1));
        }
    }

    [Fact]
    public void BltTemplatePreflightsEveryDestinationRowBeforePublishingWrites()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x1FFE;
        const uint template = 0x700;

        // The first row is addressable, but the second row starts beyond the
        // guest memory boundary.  Both template rows select a pixel so a
        // non-atomic implementation would publish the first row before
        // discovering the late destination failure.
        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 2, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(plane, 0x5A);
        memory.TryWriteByte(template, 0x80);
        memory.TryWriteByte(template + 2, 0x80);

        Assert.Equal(-1, core.BltTemplate(template, 0, 2, rastPort, 0, 0, 1, 2));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));
    }

    [Fact]
    public void BltTemplateRestoresEarlierPixelsWhenALaterPlaneWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane0 = 0x500;
        const uint plane1 = 0x600;
        const uint template = 0x700;

        WritePlanarBitmap(backing, bitMap, plane0, plane1, rows: 1);
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteByte(plane0, 0xA5));
        Assert.True(backing.TryWriteByte(plane1, 0x5A));
        Assert.True(backing.TryWriteByte(template, 0xFF));

        memory.FailOnNextByteWrite(4);
        Assert.Equal(
            -1,
            core.BltTemplate(template, 0, 2, rastPort, 0, 0, 8, 1));
        Assert.Equal((byte)0xA5, ReadByte(backing, plane0));
        Assert.Equal((byte)0x5A, ReadByte(backing, plane1));
    }

    [Fact]
    public void HostRegisterAdapterRoutesBltTemplate()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x500;
        const uint template = 0x700;

        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(template, 0xC0);
        var state = new M68kCpuState();
        state.A[0] = template;
        state.A[1] = rastPort;
        state.D[0] = 0;
        state.D[1] = 2;
        state.D[2] = 0;
        state.D[3] = 0;
        state.D[4] = 8;
        state.D[5] = 1;

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xC0, ReadByte(memory, plane));
    }

    [Fact]
    public void BltTemplateWithZeroWriteMaskSkipsHugeTemplateStaging()
    {
        static void ConfigureLargeMaskedRaster(GraphicsLibraryCore core, FakeMemory memory)
        {
            const uint rastPort = 0x20;
            const uint bitMap = 0x100;

            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                8192));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                ushort.MaxValue));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                0x1FF8));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0));
        }

        var directMemory = new FakeMemory(0x2000);
        var directCore = CreateCore(directMemory);
        ConfigureLargeMaskedRaster(directCore, directMemory);
        Assert.Equal(
            0,
            directCore.BltTemplate(
                0x1FF8,
                0,
                0,
                0x20,
                0,
                0,
                short.MaxValue,
                short.MaxValue));

        var gatewayMemory = new FakeMemory(0x2000);
        var gatewayCore = CreateCore(gatewayMemory);
        ConfigureLargeMaskedRaster(gatewayCore, gatewayMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(gatewayCore);
        var state = new M68kCpuState
        {
            A = { [0] = 0x1FF8, [1] = 0x20 },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = 0,
                [3] = 0,
                [4] = 32767u,
                [5] = 32767u
            },
            Cycles = 904
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(904, state.Cycles);
    }

