    [Fact]
    public void BltTemplateRejectsAggregateWorkBeforeTemplateProbeOrScratchGrowth()
    {
        var backing = new FakeMemory(0x4000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane = 0x3800;
        const uint template = 0x2800;

        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            0xFFFE));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            0));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(backing.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));

        var memory = new AddressReadTrackingMemory(backing, template);
        var core = CreateCore(memory);
        // CreateCore installs its ordinary fixture bitmap; replace that link
        // after construction so the nonzero write mask reaches the aggregate
        // guard rather than the zero-mask fast path.
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0x01));

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.BltTemplate(
                template,
                0,
                0,
                rastPort,
                0,
                0,
                short.MaxValue,
                short.MaxValue));
        Assert.Equal(0, memory.TrackedReadCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var registerState = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = 0,
                [3] = 0,
                [4] = 32767u,
                [5] = 32767u
            },
            Cycles = 983,
            ProgramCounter = 0x0012_4021
        };
        Assert.False(adapter.TryInvoke(registerState, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0u, registerState.D[0]);
        Assert.Equal(983, registerState.Cycles);
        Assert.Equal(0x0012_4021u, registerState.ProgramCounter);
        Assert.Equal(0, memory.TrackedReadCount);

        var overlayState = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = 0,
                [3] = 0,
                [4] = 32767u,
                [5] = 32767u
            },
            Cycles = 985,
            ProgramCounter = 0x0012_4023
        };
        Assert.False(adapter.TryInvoke(
            overlayState,
            (int)GraphicsLvo.BltTemplate,
            nativeOverlay: true));
        Assert.Equal(0u, overlayState.D[0]);
        Assert.Equal(985, overlayState.Cycles);
        Assert.Equal(0x0012_4023u, overlayState.ProgramCounter);
        Assert.Equal(0, memory.TrackedReadCount);
    }

