    [Fact]
    public void HostRegisterAdapterLeavesMalformedBlitVectorsForNativeOwnership()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        var clearState = new M68kCpuState
        {
            A = { [1] = 0x221 },
            D = { [0] = 2, [1] = 0xA55A_11EEu }
        };
        Assert.False(adapter.TryInvoke(clearState, (int)GraphicsLvo.BltClear));
        Assert.Equal(2u, clearState.D[0]);

        const uint destinationRastPort = 0x20;
        const uint destinationBitMap = 0x300;
        WritePlanarBitmap(memory, destinationBitMap, 0x500, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteLong(
            destinationRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(memory.TryWriteLong(
            destinationRastPort + (uint)GraphicsLayouts.RastPortBitMap,
            destinationBitMap));

        var bitmapRastPortState = new M68kCpuState
        {
            A = { [0] = 0x101, [1] = destinationRastPort },
            D = { [0] = 0xDEAD_BEEFu }
        };
        WritePlanarBitmap(memory, 0x101, 0x700, 0, rows: 1, depth: 1);
        Assert.False(adapter.TryInvoke(
            bitmapRastPortState,
            (int)GraphicsLvo.BltBitMapRastPort));
        Assert.Equal(0xDEAD_BEEFu, bitmapRastPortState.D[0]);

        var maskState = new M68kCpuState
        {
            A = { [0] = destinationBitMap, [1] = destinationRastPort, [2] = 0 },
            D = { [0] = 0xCAFEBABEu }
        };
        Assert.False(adapter.TryInvoke(
            maskState,
            (int)GraphicsLvo.BltMaskBitMapRastPort));
        Assert.Equal(0xCAFEBABEu, maskState.D[0]);

        var clipState = new M68kCpuState
        {
            A = { [0] = 0, [1] = destinationRastPort },
            D = { [0] = 0x1357_9BDFu }
        };
        Assert.False(adapter.TryInvoke(clipState, (int)GraphicsLvo.ClipBlit));
        Assert.Equal(0x1357_9BDFu, clipState.D[0]);

        var patternState = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0x2468_ACEEu }
        };
        Assert.False(adapter.TryInvoke(patternState, (int)GraphicsLvo.BltPattern));
        Assert.Equal(0x2468_ACEEu, patternState.D[0]);

        var templateState = new M68kCpuState
        {
            A = { [0] = 0x700, [1] = 0 },
            D = { [0] = 0x2468_ACEEu }
        };
        Assert.False(adapter.TryInvoke(templateState, (int)GraphicsLvo.BltTemplate));
        Assert.Equal(0x2468_ACEEu, templateState.D[0]);
    }

    [Fact]
    public void AllocBitMapBuildsPlanarGeometryClearsInterleavedPlanesAndFreesAsOneBlock()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bmfClear = 1u << 0;
        const uint bmfInterleaved = 1u << 2;

        var bitMap = core.AllocBitMap(17, 3, 2, bmfClear | bmfInterleaved, 0);
        Assert.NotEqual(0u, bitMap);
        Assert.Equal((ushort)8, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)3, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)2, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapDepth));
        var flags = ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapFlags);
        Assert.Equal((byte)0x0D, flags); // CLEAR | INTERLEAVED | STANDARD

        var plane0 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes);
        var plane1 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4);
        // Interleaved links point at each plane's slice in the first row;
        // the aggregate BytesPerRow supplies the row-to-row stride.
        Assert.Equal(4u, plane1 - plane0);
        for (var offset = 0u; offset < 24; offset++)
            Assert.Equal((byte)0, ReadByte(memory, plane0 + offset));

        Assert.Equal(0, core.FreeBitMap(bitMap));
        Assert.Contains(allocator.Freed, allocation => allocation.Address == plane0 && allocation.Bytes == 24);
        Assert.Contains(allocator.Freed, allocation => allocation.Address == bitMap && allocation.Bytes == GraphicsLayouts.BitMapSize);
    }

