    [Fact]
    public void InterleavedBitmapBlitUsesAggregateRowStrideAtLaterRows()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = CreateCore(memory, allocator: allocator);
        const uint bmfClear = 1u << 0;
        const uint bmfInterleaved = 1u << 2;

        var source = core.AllocBitMap(17, 3, 2, bmfClear | bmfInterleaved, 0);
        var destination = core.AllocBitMap(17, 3, 2, bmfClear | bmfInterleaved, 0);
        Assert.NotEqual(0u, source);
        Assert.NotEqual(0u, destination);

        var sourcePlane0 = ReadLong(memory, source + (uint)GraphicsLayouts.BitMapPlanes);
        var sourcePlane1 = ReadLong(memory, source + (uint)GraphicsLayouts.BitMapPlanes + 4);
        var destinationPlane0 = ReadLong(memory, destination + (uint)GraphicsLayouts.BitMapPlanes);
        var destinationPlane1 = ReadLong(memory, destination + (uint)GraphicsLayouts.BitMapPlanes + 4);
        Assert.True(memory.TryWriteByte(sourcePlane0 + 18, 0x80));
        Assert.True(memory.TryWriteByte(sourcePlane1 + 18, 0x80));

        Assert.Equal(
            2,
            core.BltBitMap(source, 16, 2, destination, 16, 2, 1, 1, 0xC0, 0x03, 0));
        Assert.Equal((byte)0x80, ReadByte(memory, destinationPlane0 + 18));
        Assert.Equal((byte)0x80, ReadByte(memory, destinationPlane1 + 18));

        Assert.Equal(0, core.FreeBitMap(source));
        Assert.Equal(0, core.FreeBitMap(destination));
    }

    [Fact]
    public void BltMaskBitMapRastPortPreservesKickstart31InterleavedSourceWidthQuirk()
    {
        var memory = new FakeMemory(0x8000);
        var core = CreateCore(memory);
        const uint source = 0x300;
        const uint destination = 0x400;
        const uint rastPort = 0x20;
        const uint sourceStorage = 0x1000;
        const uint destinationPlane0 = 0x2000;
        const uint destinationPlane1 = 0x2100;
        const uint blitMask = 0x3000;

        // Kickstart 3.1 constructs the temporary mask bitmap for an
        // interleaved source from the aggregate guest BytesPerRow.  With a
        // two-plane, four-byte aggregate row that exposes 32 source pixels,
        // even though each linked plane's normal geometry is 16 pixels.
        WriteInterleavedBitmap(
            memory,
            source,
            sourceStorage,
            aggregateBytesPerRow: 4,
            rows: 1,
            depth: 2);
        Assert.True(memory.TryWriteWord(
            destination + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteWord(
            destination + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            destination + (uint)GraphicsLayouts.BitMapDepth,
            2));
        Assert.True(memory.TryWriteLong(
            destination + (uint)GraphicsLayouts.BitMapPlanes,
            destinationPlane0));
        Assert.True(memory.TryWriteLong(
            destination + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            destinationPlane1));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            destination));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));

        // The first two bytes are the ordinary 16-pixel plane rows.  The
        // following aggregate bytes are deliberately distinct: the V40
        // temporary-mask geometry consumes them for source pixels 16..23.
        Assert.True(memory.TryWriteByte(sourceStorage + 0u, 0xFF));
        Assert.True(memory.TryWriteByte(sourceStorage + 1u, 0xFF));
        Assert.True(memory.TryWriteByte(sourceStorage + 2u, 0x00));
        Assert.True(memory.TryWriteByte(sourceStorage + 3u, 0x00));
        Assert.True(memory.TryWriteByte(sourceStorage + 4u, 0xFF));
        Assert.True(memory.TryWriteByte(sourceStorage + 5u, 0xFF));
        for (var offset = 0u; offset < 4u; offset++)
        {
            Assert.True(memory.TryWriteByte(blitMask + offset, 0xFF));
            Assert.True(memory.TryWriteByte(destinationPlane0 + offset, 0));
            Assert.True(memory.TryWriteByte(destinationPlane1 + offset, 0));
        }

        Assert.Equal(
            0,
            core.BltMaskBitMapRastPort(
                source,
                0,
                0,
                rastPort,
                0,
                0,
                24,
                1,
                0xC0,
                blitMask));

        // Pixels 16..23 are sourced from the aggregate interleaved row: the
        // source-plane bytes resolve to plane 1, reproducing the documented
        // Kickstart 3.1/V40 temporary-mask width behavior.
        Assert.Equal((byte)0xFF, ReadByte(memory, destinationPlane0 + 0u));
        Assert.Equal((byte)0xFF, ReadByte(memory, destinationPlane0 + 1u));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane0 + 2u));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane1 + 0u));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane1 + 1u));
        Assert.Equal((byte)0xFF, ReadByte(memory, destinationPlane1 + 2u));

        // The CopperStart register seam must expose the same guest-width
        // geometry and mapped result as the direct helper.
        for (var offset = 0u; offset < 4u; offset++)
        {
            Assert.True(memory.TryWriteByte(destinationPlane0 + offset, 0));
            Assert.True(memory.TryWriteByte(destinationPlane1 + offset, 0));
        }

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = source, [1] = rastPort, [2] = blitMask },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 24, [5] = 1, [6] = 0xC0 },
            Cycles = 73
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BltMaskBitMapRastPort));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(73, state.Cycles);
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane0 + 2u));
        Assert.Equal((byte)0xFF, ReadByte(memory, destinationPlane1 + 2u));
    }

