    [Fact]
    public void AllocBitMapOcsInterleavedRollbackFreesEachPublishedPlane()
    {
        var backing = new FakeMemory(0x20_000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay { SupportsEcsDisplay = false });
        const uint bmfInterleaved = 1u << 2;

        // The OCS path ignores BMF_INTERLEAVED and allocates two independent
        // planes.  Fail the second plane-pointer publication after both
        // allocations exist, forcing the late rollback path to release the
        // storage according to the published (non-interleaved) header.
        memory.FailOnNextByteWrite(GraphicsLayouts.BitMapSize + 6 + 2 + 4);
        Assert.Equal(
            0u,
            core.AllocBitMap(
                width: 17,
                height: 3,
                depth: 2,
                flags: bmfInterleaved,
                friendBitMap: 0));

        Assert.Equal(3, allocator.Freed.Count);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x1028u && allocation.Bytes == 12u);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x1034u && allocation.Bytes == 12u);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x1000u &&
                          allocation.Bytes == GraphicsLayouts.BitMapSize);
        Assert.DoesNotContain(allocator.Freed, allocation => allocation.Bytes == 24u);
    }

    [Fact]
    public void AllocBitMapAppliesTheEcsWidthLimitButLeavesOcsCompatibilityUnchanged()
    {
        const uint widthBeyondEcsLimit = 32761;

        var ecsMemory = new FakeMemory(0x20_000);
        var ecsAllocator = new BitmapAllocator();
        var ecsCore = new GraphicsLibraryCore(
            ecsMemory,
            ecsAllocator,
