            new FakeDisplay { SupportsEcsDisplay = true });

        Assert.Equal(
            0u,
            ecsCore.AllocBitMap(
                widthBeyondEcsLimit,
                height: 1,
                depth: 1,
                flags: 0,
                friendBitMap: 0));
        Assert.Empty(ecsAllocator.Freed);

        var ocsMemory = new FakeMemory(0x20_000);
        var ocsAllocator = new BitmapAllocator();
        var ocsCore = new GraphicsLibraryCore(
            ocsMemory,
            ocsAllocator,
            new FakeBlitter(),
            new FakeDisplay { SupportsEcsDisplay = false });

        var bitMap = ocsCore.AllocBitMap(
            widthBeyondEcsLimit,
            height: 1,
            depth: 1,
            flags: 0,
            friendBitMap: 0);
        Assert.NotEqual(0u, bitMap);
        Assert.Equal((ushort)4096, ReadWord(
            ocsMemory,
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(0, ocsCore.FreeBitMap(bitMap));
    }

    [Fact]
    public void AllocBitMapRejectsAnAllocatorEnvelopeThatWrapsIntoLowGuestMemory()
    {
        var memory = new WrappingMemory();
        var allocator = new SequenceAddressAllocator(0x100u, uint.MaxValue - 1u);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const byte sentinel = 0xA5;
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            memory.WriteByte(0x100u + (uint)offset, 0xCC);
        memory.WriteByte(0, sentinel);

        var bitMap = core.AllocBitMap(
            width: 16,
            height: 2,
            depth: 1,
            flags: (1u << 0) | (1u << 2), // BMF_CLEAR | BMF_INTERLEAVED
            friendBitMap: 0);

        Assert.Equal(0u, bitMap);
        Assert.True(memory.TryReadByte(0, out var preserved));
        Assert.Equal(sentinel, preserved);
        Assert.Equal(2, allocator.FreeCount);
    }

    [Fact]
    public void AllocBitMapHonorsMinPlanesStructureSizeAndStillSupportsPortablePlaneReads()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bmfClear = 1u << 0;
        const uint bmfMinPlanes = 1u << 4;

        var bitMap = core.AllocBitMap(17, 2, 2, bmfClear | bmfMinPlanes, 0);
        Assert.NotEqual(0u, bitMap);
        Assert.Equal((byte)0x19, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapFlags));

        var plane0 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes);
        var plane1 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4);
        Assert.NotEqual(0u, plane0);
        Assert.NotEqual(0u, plane1);
        for (var offset = 0u; offset < 4; offset++)
        {
            Assert.Equal((byte)0, ReadByte(memory, plane0 + offset));
            Assert.Equal((byte)0, ReadByte(memory, plane1 + offset));
        }

        Assert.Equal(0, core.FreeBitMap(bitMap));
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == bitMap &&
                          allocation.Bytes == (uint)GraphicsLayouts.BitMapPlanes + 8u);
    }

    [Fact]
    public void AllocBitMapFailsWhenInterleavedBlockIsUnavailable()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new RejectingInterleavedAllocator(planeBytesToReject: 24);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bmfClear = 1u << 0;
        const uint bmfInterleaved = 1u << 2;

        var bitMap = core.AllocBitMap(17, 3, 2, bmfClear | bmfInterleaved, 0);
        Assert.Equal(0u, bitMap);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.MemoryClass == GraphicsMemoryClass.Public &&
                          allocation.Bytes == (uint)GraphicsLayouts.BitMapSize);
        Assert.DoesNotContain(
            allocator.Freed,
            allocation => allocation.MemoryClass == GraphicsMemoryClass.Chip);
    }

    [Fact]
    public void AllocBitMapReleasesAProvisionalInterleavedAddressWhenTheAllocatorDeclines()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new DecliningInterleavedAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bmfClear = 1u << 0;
        const uint bmfInterleaved = 1u << 2;

        // The interleaved request reports failure but leaves a provisional
        // address in the out slot.  The portable boundary must release that
        // span before rolling back the bitmap header; it must not silently
        // publish a separate-plane replacement.
        var bitMap = core.AllocBitMap(17, 3, 2, bmfClear | bmfInterleaved, 0);
        Assert.Equal(0u, bitMap);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x2000 &&
                          allocation.Bytes == 24 &&
                          allocation.MemoryClass == GraphicsMemoryClass.Chip);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x1000 &&
                          allocation.Bytes == (uint)GraphicsLayouts.BitMapSize &&
                          allocation.MemoryClass == GraphicsMemoryClass.Public);
    }

    [Fact]
    public void NativeOverlayChainsUnavailableInterleavedAllocationAfterPortableRollback()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint nativeTarget = 0x00FE_1321;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                // Width 17, height 3, depth 2 produces a 24-byte
                // contiguous interleaved chip request after the public
                // header has been allocated.
                if (bytes == 24)
                    return 0;

                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            D = { [0] = 17, [1] = 3, [2] = 2, [3] = (1u << 0) | (1u << 2) },
            Cycles = 373,
            ProgramCounter = 0x0012_3841
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(17u, state.D[0]);
        Assert.Equal(373, state.Cycles);
        Assert.Equal(1, frees);
    }

    [Fact]
    public void AllocBitMapClearsDisplayableWhenChipPlanesAreNotWordAligned()
    {
        var memory = new FakeMemory(0x20_000);
        // The public BitMap header itself must remain word-aligned; the
        // capability result is cleared because the separately allocated
        // chip planes are deliberately odd.
        var allocator = new SequenceAddressAllocator(0x1000, 0x1001, 0x1101);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bmfDisplayable = 1u << 1;

        var bitMap = core.AllocBitMap(17, 3, 2, bmfDisplayable, 0);
        Assert.NotEqual(0u, bitMap);
        Assert.Equal((byte)0x08, ReadByte(memory, bitMap + (uint)GraphicsLayouts.BitMapFlags));

        var plane0 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes);
        var plane1 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4);
        Assert.Equal(1u, plane0 & 1u);
        Assert.Equal(1u, plane1 & 1u);
        Assert.Equal(0u, core.GetBitMapAttr(bitMap, 12) & bmfDisplayable);
        Assert.Equal(0, core.FreeBitMap(bitMap));
    }

    [Fact]
    public void AllocBitMapClearsDisplayableForMappedNonDmaPlaneRanges()
    {
