        Assert.Equal(bmfStandard, core.GetBitMapAttr(bitMap, 12));
        Assert.Equal(0, core.FreeBitMap(bitMap));
    }

    [Fact]
    public void AllocBitMapUsesReadableFriendStrideAndRejectsMalformedFriend()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint friend = 0x200;

        // The requested 17-pixel raster needs only four bytes per row, but a
        // standard friend with an eight-byte stride should be blit-compatible
        // without narrowing the destination allocation.
        Assert.True(memory.TryWriteWord(friend + (uint)GraphicsLayouts.BitMapBytesPerRow, 8));
        Assert.True(memory.TryWriteWord(friend + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(memory.TryWriteByte(friend + (uint)GraphicsLayouts.BitMapDepth, 1));
        var bitMap = core.AllocBitMap(17, 2, 2, 0, friend);
        Assert.NotEqual(0u, bitMap);
        Assert.Equal((ushort)8, ReadWord(memory, bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));

        var plane0 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes);
        var plane1 = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4);
        Assert.Equal(16u, plane1 - plane0);
        Assert.Equal(0, core.FreeBitMap(bitMap));
        Assert.Contains(allocator.Freed, allocation => allocation.Address == plane0 && allocation.Bytes == 16);

        var malformedMemory = new FakeMemory(0x4000);
        var malformedAllocator = new BitmapAllocator();
        var malformedCore = new GraphicsLibraryCore(
            malformedMemory,
            malformedAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, malformedCore.AllocBitMap(17, 2, 2, 0, 0x3FFF));
        Assert.Empty(malformedAllocator.Freed);
    }

    [Fact]
    public void AllocBitMapRejectsAnOddGuestHeaderBeforePublishingOrClaimingTheVector()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new SequenceAddressAllocator(0x1001, 0x1200);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        // The BitMap header contains WORD/LONG fields and must be addressable
        // by the native 68000.  An allocator that returns an odd public
        // address is malformed even though a byte-addressable host could
        // still write the structure; release that provisional header before
        // any guest bytes or plane ownership are published.
        Assert.Equal(0u, core.AllocBitMap(17, 2, 1, 0, 0));
        Assert.Equal(1, allocator.FreeCount);

        var registerAllocator = new SequenceAddressAllocator(0x1001, 0x1200);
        var registerCore = new GraphicsLibraryCore(
            memory,
            registerAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(registerCore);
        var state = new M68kCpuState
        {
            D = { [0] = 17, [1] = 2, [2] = 1, [3] = 0, [4] = 0xCAFE_BABEu },
            Cycles = 73
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AllocBitMap));
        Assert.Equal(17u, state.D[0]);
        Assert.Equal(73, state.Cycles);
        Assert.Equal(1, registerAllocator.FreeCount);
    }

    [Fact]
    public void BitmapLifecycleVectorsUseClassicDAndARegisterAbi()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bmfClear = 1u << 0;

        var state = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 17, [1] = 3, [2] = 2, [3] = bmfClear }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocBitMap));
        var bitMap = state.D[0];
        Assert.NotEqual(0u, bitMap);

        state.A[0] = bitMap;
        state.D[1] = 8; // BMA_WIDTH
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetBitMapAttr));
        Assert.Equal(32u, state.D[0]);

        state.A[0] = bitMap;
        state.D[1] = 12; // BMA_FLAGS
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetBitMapAttr));
        Assert.Equal(core.GetBitMapAttr(bitMap, 12), state.D[0]);
        Assert.Equal(0u, state.D[0] & ((1u << 0) | (1u << 4)));

        state.A[0] = bitMap;
        state.D[0] = 0xFFFF_FFFF;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeBitMap));
        Assert.Equal(0u, state.D[0]);
        Assert.Contains(allocator.Freed, allocation => allocation.Address == bitMap);
    }

    [Fact]
    public void FreeBitMapNullIsSuccessfulNoOp()
    {
        var memory = new FakeMemory(0x1000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        Assert.Equal(GraphicsRasterOperations.Success, core.FreeBitMap(0));
        Assert.Empty(allocator.Freed);

        var rtgProbeCalls = 0;
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: _ =>
            {
                rtgProbeCalls++;
                return true;
            });
        var state = new M68kCpuState
        {
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 43
        };
        Assert.True(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.FreeBitMap,
            nativeOverlay: true));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(43, state.Cycles);
        Assert.Equal(0, rtgProbeCalls);
        Assert.Empty(allocator.Freed);
    }

    [Fact]
    public void AllocBitMapRollsBackAlreadyAllocatedPlanesOnFailure()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator { FailAfterAllocations = 2 };
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        Assert.Equal(0u, core.AllocBitMap(32, 4, 2, 0, 0));
        Assert.Equal(2, allocator.Freed.Count); // one plane and the BitMap structure
    }

    [Fact]
    public void AllocBitMapRestoresEnvelopeWhenALatePlanePointerWriteFails()
    {
        var backing = new FakeMemory(0x20_000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bitMap = 0x1000;
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            Assert.True(backing.TryWriteByte(bitMap + (uint)offset, (byte)(0x20 + offset)));

        // Bitmap header publication is 40 bytes plus six header bytes; fail
        // the second byte of the second plane pointer after the first plane
        // and the first half of the second pointer have published.
        memory.FailOnNextByteWrite(GraphicsLayouts.BitMapSize + 6 + 2 + 4);
        Assert.Equal(0u, core.AllocBitMap(17, 2, 2, 0, 0));
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            Assert.Equal((byte)(0x20 + offset), ReadByte(backing, bitMap + (uint)offset));
        Assert.Equal(3, allocator.Freed.Count);
    }

    [Fact]
    public void FreeBitMapRejectsAnInterleavedSpanThatOverflowsTheGuestAllocatorRangeAndRetainsOwnership()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var bitMap = core.AllocBitMap(16, 2, 1, 0, 0);
        Assert.NotEqual(0u, bitMap);

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            ushort.MaxValue));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(1u << 2))); // BMF_INTERLEAVED
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            8));

        Assert.Equal(-1, core.FreeBitMap(bitMap));
        Assert.Empty(allocator.Freed);

        // Structural failure must not consume the ownership token: repair the
        // public geometry and release the original allocation normally.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(1u << 3))); // BMF_STANDARD
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.Equal(0, core.FreeBitMap(bitMap));
        Assert.Equal(2, allocator.Freed.Count);
    }

    [Fact]
    public void FreeBitMapRequiresOwnershipFromTheSameGraphicsLibraryAndRejectsDoubleFree()
    {
        var memory = new FakeMemory(0x20_000);
        var ownerAllocator = new BitmapAllocator();
        var foreignAllocator = new BitmapAllocator();
        var owner = new GraphicsLibraryCore(memory, ownerAllocator, new FakeBlitter(), new FakeDisplay());
        var foreign = new GraphicsLibraryCore(memory, foreignAllocator, new FakeBlitter(), new FakeDisplay());

        var bitMap = owner.AllocBitMap(17, 3, 1, 0, 0);
        Assert.NotEqual(0u, bitMap);

        // A valid portable bitmap envelope is still foreign to another
        // graphics-library instance; no allocator call may escape here.
        Assert.Equal(-1, foreign.FreeBitMap(bitMap));
        Assert.Empty(foreignAllocator.Freed);

        Assert.Equal(0, owner.FreeBitMap(bitMap));
        Assert.Equal(-1, owner.FreeBitMap(bitMap));
        Assert.Equal(2, ownerAllocator.Freed.Count);
    }

    [Fact]
    public void FreeBitMapRejectsCorruptedOwnedPlaneBeforeAllocatorRelease()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var bitMap = core.AllocBitMap(17, 3, 2, 0, 0);
        Assert.NotEqual(0u, bitMap);

        var firstPlane = ReadLong(memory, bitMap + (uint)GraphicsLayouts.BitMapPlanes);
        var secondPlaneAddress = bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u;
        var secondPlane = ReadLong(memory, secondPlaneAddress);

        // A registered bitmap can be corrupted by guest code after
        // allocation. The teardown path must decline the malformed plane
        // span without consuming ownership or freeing the public envelope.
        Assert.True(memory.TryWriteLong(secondPlaneAddress, 0xFFFF_FFFFu));
        Assert.Equal(-1, core.FreeBitMap(bitMap));
        Assert.Empty(allocator.Freed);

        Assert.True(memory.TryWriteLong(secondPlaneAddress, secondPlane));
        Assert.Equal(0, core.FreeBitMap(bitMap));
        Assert.Equal(3, allocator.Freed.Count);
        Assert.NotEqual(0u, firstPlane);
    }

    [Fact]
    public void FreeBitMapRejectsAlteredOwnedGeometryBeforeAllocatorRelease()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var bitMap = core.AllocBitMap(17, 3, 1, 0, 0);
        Assert.NotEqual(0u, bitMap);

        // The altered layout remains readable, but it no longer describes
        // the chip span AllocBitMap actually acquired. FreeBitMap must retain
        // its ownership token rather than release an eight-byte prefix of the
        // original twelve-byte plane allocation.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.Equal(-1, core.FreeBitMap(bitMap));
        Assert.Empty(allocator.Freed);

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            3));
        Assert.Equal(0, core.FreeBitMap(bitMap));
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == bitMap &&
                          allocation.Bytes == GraphicsLayouts.BitMapSize);
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Bytes == 12 &&
                          allocation.MemoryClass == GraphicsMemoryClass.Chip);
    }

    [Fact]
    public void FreeBitMapRejectsAnOddHeaderBeforeAllocatorRelease()
    {
        var memory = new FakeMemory(0x2000);
        var allocator = new BitmapAllocator();
        const uint bitMap = 0x101;
        const uint plane = 0x400;

        // The host memory is byte-addressable, so all fields would otherwise
        // be readable from this odd base.  The public BitMap still contains
        // WORD/LONG members and must remain on the native/provider path.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(1u << 3))); // BMF_STANDARD
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(memory.TryWriteByte(plane, 0xA5));

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            GraphicsRasterOperations.FreeBitMap(memory, allocator, bitMap));
        Assert.Empty(allocator.Freed);
        Assert.Equal((byte)0xA5, ReadByte(memory, plane));
    }

    [Fact]
    public void FreeBitMapGatewayPreservesRegistersForCorruptedOwnedPlane()
    {
        var memory = new FakeMemory(0x20_000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var bitMap = core.AllocBitMap(17, 3, 2, 0, 0);
        Assert.NotEqual(0u, bitMap);

        var secondPlaneAddress = bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u;
        var secondPlane = ReadLong(memory, secondPlaneAddress);
        Assert.True(memory.TryWriteLong(secondPlaneAddress, 0xFFFF_FFFFu));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 77
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FreeBitMap));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(77, state.Cycles);
        Assert.Empty(allocator.Freed);

        Assert.True(memory.TryWriteLong(secondPlaneAddress, secondPlane));
        state.D[0] = 0xCAFE_BABEu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeBitMap));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(3, allocator.Freed.Count);
    }

    [Fact]
    public void ChangeViewPortBitMapUpdatesOnlyTheGuestRasInfoAssociation()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint firstBitMap = 0x1200;
        const uint nextBitMap = 0x1400;

        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, firstBitMap);
        memory.TryWriteWord(firstBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteByte(firstBitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.TryWriteWord(nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteByte(nextBitMap + (uint)GraphicsLayouts.BitMapDepth, 2);

        Assert.Equal(0, core.ChangeViewPortBitMap(viewPort, nextBitMap));
        Assert.Equal(nextBitMap, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        memory.TryWriteWord(nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        Assert.Equal(-1, core.ChangeViewPortBitMap(viewPort, firstBitMap));
        Assert.Equal(nextBitMap, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(-1, core.ChangeViewPortBitMap(viewPort, 0));
        Assert.Equal(-1, core.ChangeViewPortBitMap(0, nextBitMap));
    }

