    [Fact]
    public void ChangeViewPortBitMapDoesNotProbePresentationForMalformedViewport()
    {
        var memory = new FakeMemory(0x2000);
        var display = new PresentationStatusDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        const uint nextBitMap = 0x1400;

        // The zero RasInfo link is malformed for a presentation operation.
        // Capability discovery must not run before this portable envelope
        // gate, otherwise an unclaimed native request could notify a host
        // provider even though no guest state can be interpreted.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.ChangeViewPortBitMap(viewPort, nextBitMap, 0));
        Assert.Equal(0, display.CanChangeQueries);
        Assert.Equal(0, display.ChangeCount);
    }

    [Fact]
    public void ChangeViewPortBitMapDoesNotProbePresentationForMalformedBitmapOrDbufInfo()
    {
        var memory = new FakeMemory(0x2000);
        var display = new PresentationStatusDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint currentBitMap = 0x1200;
        const uint nextBitMap = 0x1400;
        const uint malformed = 0x1FF0;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap));
        foreach (var bitMap in new[] { currentBitMap, nextBitMap })
        {
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                4));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                2));
        }

        // A valid viewport with an unreadable replacement must not reach the
        // presentation owner merely because capability is available.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.ChangeViewPortBitMap(viewPort, malformed, 0));
        Assert.Equal(0, display.CanChangeQueries);
        Assert.Equal(
            currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));

        // The same ordering applies to the optional DBufInfo envelope.
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.ChangeViewPortBitMap(viewPort, nextBitMap, malformed));
        Assert.Equal(0, display.CanChangeQueries);
        Assert.Equal(0, display.ChangeCount);
    }

