    [Fact]
    public void ChangeViewPortBitMapLeavesRtgSurfacesToCyberGraphX()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint currentBitMap = 0x1200;
        const uint nextBitMap = 0x1400;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap));

        var newRtgAdapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: bitMap => bitMap == nextBitMap);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap },
            D = { [0] = 0xDEAD_BEEFu }
        };

        Assert.False(newRtgAdapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));

        // A non-RTG replacement is still owned by CyberGraphX when the
        // viewport already exposes an RTG bitmap.
        var attachedRtgAdapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: bitMap => bitMap == currentBitMap);
        state.A[1] = 0x1500;
        Assert.False(attachedRtgAdapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(currentBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void HostChangeVPBitMapLeavesMalformedTimedSwapsToTheProviderBoundary()
    {
        var memory = new FakeMemory(0x2400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint firstBitMap = 0x1200;
        const uint nextBitMap = 0x1400;
        const uint truncatedDbufInfo = 0x23D0;
        const uint sentinel = 0xCAFE_BABEu;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            firstBitMap));
        Assert.True(memory.TryWriteWord(
            firstBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(
            firstBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));
        Assert.True(memory.TryWriteWord(
            nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(
            nextBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));

        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap, [2] = truncatedDbufInfo },
            D = { [0] = sentinel },
            Cycles = 91
        };

        // The timed core validates the complete public DBufInfo envelope
        // before touching RasInfo or notifying the display scheduler.  A
        // malformed swap must therefore remain available to native graphics
        // or CyberGraphX rather than being converted into a successful void
        // call with an altered cycle.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(sentinel, state.D[0]);
        Assert.Equal(91, state.Cycles);
        Assert.Equal(firstBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void HostChangeVPBitMapRejectsAnOddMappedDbufInfoEnvelope()
    {
        var memory = new HostGuestMemory(new AmigaBus());
        var rebuilds = 0;
        var services = CreateHostGraphicsServices(
            memory,
            requestDisplayRebuild: () => rebuilds++,
            allowGuestOwnedDbufInfo: true);
        const uint viewPort = 0x700;
        const uint rasInfo = 0x780;
        const uint currentBitMap = 0x800;
        const uint nextBitMap = 0x880;
        const uint oddDbufInfo = 0x1801;

        memory.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, currentBitMap);
        foreach (var bitMap in new[] { currentBitMap, nextBitMap })
        {
            memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
            memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        }

        // The mapped guest path accepts a caller-supplied DBufInfo envelope,
        // but the public structure still has 16/32-bit fields and must start
        // on an even 68k address.  Make the complete odd span readable so a
        // byte-only probe cannot accidentally turn it into a native swap.
        for (var offset = 0; offset < GraphicsLayouts.DBufInfoSize; offset++)
            memory.WriteByte(oddDbufInfo + (uint)offset, 0xA5);

        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap, [2] = oddDbufInfo },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 91
        };

        services.Invoke(state, (int)GraphicsLvo.ChangeVPBitMap);

        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(91, state.Cycles);
        Assert.Equal(0, rebuilds);
        Assert.Equal(currentBitMap,
            memory.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void RtgBitmapOwnershipAndAttributeVectorsFallThroughToCyberGraphX()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rtgBitMap = 0x1400;
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: bitMap => bitMap == rtgBitMap);

        var free = new M68kCpuState
        {
            A = { [0] = rtgBitMap },
            D = { [0] = 0xA5A5_A5A5u }
        };
        Assert.False(adapter.TryInvoke(free, (int)GraphicsLvo.FreeBitMap));
        Assert.Equal(0xA5A5_A5A5u, free.D[0]);

        var attr = new M68kCpuState
        {
            A = { [0] = rtgBitMap },
            D = { [0] = 0x5A5A_5A5Au, [1] = 8 }
        };
        Assert.False(adapter.TryInvoke(attr, (int)GraphicsLvo.GetBitMapAttr));
        Assert.Equal(0x5A5A_5A5Au, attr.D[0]);

        // A standard bitmap owned by another graphics-library/native path
        // must also fall through instead of being claimed as a successful
        // no-op by this registry-scoped allocator.
        var foreign = new M68kCpuState
        {
            A = { [0] = 0x1500 },
            D = { [0] = 0x1122_3344u }
        };
        Assert.False(adapter.TryInvoke(foreign, (int)GraphicsLvo.FreeBitMap));
        Assert.Equal(0x1122_3344u, foreign.D[0]);
    }

