        Assert.True(core.InitGels(head, tail, gelsInfo));

        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: address => address == rastPort);

        var collision = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 431,
            ProgramCounter = 0x0012_3901
        };
        Assert.False(adapter.TryInvoke(collision, (int)GraphicsLvo.DoCollision));
        Assert.Equal(0x1357_9BDFu, collision.D[0]);
        Assert.Equal(431, collision.Cycles);
        Assert.Equal(0x0012_3901u, collision.ProgramCounter);

        var draw = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 433,
            ProgramCounter = 0x0012_3903
        };
        Assert.False(adapter.TryInvoke(draw, (int)GraphicsLvo.DrawGList));
        Assert.Equal(0x2468_ACEEu, draw.D[0]);
        Assert.Equal(433, draw.Cycles);
        Assert.Equal(0x0012_3903u, draw.ProgramCounter);
        Assert.Equal(0, backend.CollisionCount);
        Assert.Empty(backend.Drawn);
    }

    [Fact]
    public void RtgRastPortsLeaveMoveToCyberGraphX()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: rastPort => rastPort == 0x20);
        var state = new M68kCpuState
        {
            A = { [1] = 0x20 },
            D = { [0] = 7, [1] = 9 },
            Cycles = 59
        };

        // CyberGraphX patches Move for RTG RastPorts.  The portable adapter
        // must decline before it reads or writes the cursor fields, keeping
        // the provider's incoming register/cycle frame intact.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Move));
        Assert.Equal(7u, state.D[0]);
        Assert.Equal(9u, state.D[1]);
        Assert.Equal(59, state.Cycles);
    }

    [Fact]
    public void RtgRastPortsLeaveStateFontStyleAndAttributeVectorsToCyberGraphX()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: rastPort => rastPort == 0x20);

        var a1Vectors = new[]
        {
            GraphicsLvo.SetAPen,
            GraphicsLvo.SetBPen,
            GraphicsLvo.SetDrMd,
            GraphicsLvo.SetFont,
            GraphicsLvo.AskFont,
            GraphicsLvo.AskSoftStyle,
            GraphicsLvo.SetSoftStyle,
            GraphicsLvo.SetRPAttrsA,
            GraphicsLvo.GetRPAttrsA
        };
        var a0Vectors = new[]
        {
            GraphicsLvo.GetAPen,
            GraphicsLvo.GetBPen,
            GraphicsLvo.GetDrMd,
            GraphicsLvo.SetABPenDrMd,
            GraphicsLvo.SetWriteMask,
            GraphicsLvo.SetMaxPen,
            GraphicsLvo.GetOutlinePen,
            GraphicsLvo.SetOutlinePen
        };

        foreach (var vector in a1Vectors.Concat(a0Vectors))
        {
            var state = new M68kCpuState
            {
                A =
                {
                    [0] = a0Vectors.Contains(vector) ? 0x20u : 0xDEADu,
                    [1] = a1Vectors.Contains(vector) ? 0x20u : 0xDEADu
                },
                D = { [0] = 0xA5A5_5A5Au, [1] = 0x1357_9BDFu, [2] = 0x2468_ACEDu },
                Cycles = 73
            };

            Assert.False(adapter.TryInvoke(state, (int)vector), vector.ToString());
            Assert.Equal(0xA5A5_5A5Au, state.D[0]);
            Assert.Equal(0x1357_9BDFu, state.D[1]);
            Assert.Equal(0x2468_ACEDu, state.D[2]);
            Assert.Equal(73, state.Cycles);
        }
    }

    [Fact]
    public void LayerBackedRtgRastPortsKeepPortableFontStyleMetadata()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint layer = 0x180;
        const uint font = 0x300;
        const uint textAttr = 0x700;
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            layer));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontName,
            0x600));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            8));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontXSize,
            8));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBaseline,
            7));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontStyle,
            0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBoldSmear,
            1));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontLoChar,
            (byte)'A'));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontHiChar,
            (byte)'A'));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0x600));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            2));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharLoc,
            0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharSpace,
            0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharKern,
            0));

        // The bitmap owner is intentionally reported as RTG.  The nonzero
        // guest Layer link is the narrow exception that keeps metadata-only
        // font/style vectors available to the portable Layers text path.
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: address => address == rastPort);

        var setFont = new M68kCpuState
        {
            A = { [0] = font, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 101
        };
        Assert.True(adapter.TryInvoke(setFont, (int)GraphicsLvo.SetFont));
        Assert.Equal(0u, setFont.D[0]);
        Assert.Equal(101, setFont.Cycles);
        Assert.Equal(
            font,
            ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortFont));

        var askFont = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = rastPort },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 102
        };
        Assert.True(adapter.TryInvoke(askFont, (int)GraphicsLvo.AskFont));
        Assert.Equal(0u, askFont.D[0]);
        Assert.Equal(
            0x600u,
            ReadLong(memory, textAttr + (uint)GraphicsLayouts.TextAttrName));
        Assert.Equal(
            (ushort)8,
            ReadWord(memory, textAttr + (uint)GraphicsLayouts.TextAttrYSize));
        Assert.Equal(102, askFont.Cycles);

        var ask = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 103
        };
        Assert.True(adapter.TryInvoke(ask, (int)GraphicsLvo.AskSoftStyle));
        Assert.Equal(uint.MaxValue, ask.D[0]);
        Assert.Equal(103, ask.Cycles);

        var set = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x07, [1] = 0x07 },
            Cycles = 107
        };
        Assert.True(adapter.TryInvoke(set, (int)GraphicsLvo.SetSoftStyle));
        Assert.Equal(0x07u, set.D[0]);
        Assert.Equal(
            (byte)0x07,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal(107, set.Cycles);
    }

