    [Fact]
    public void LayerBackedRtgRastPortsKeepPortableAttributeTagMetadata()
    {
        static void WriteTag(FakeMemory memory, uint address, uint tag, uint data)
        {
            Assert.True(memory.TryWriteLong(address, tag));
            Assert.True(memory.TryWriteLong(address + 4u, data));
        }

        static void Exercise(bool nativeOverlay)
        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            const uint rastPort = 0x20;
            const uint layer = 0x180;
            const uint setTags = 0x900;
            const uint getTags = 0xA00;
            const uint outputs = 0xB00;

            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortLayer,
                layer));

            WriteTag(memory, setTags + 0x00,
                GraphicsRastPortAttributeOperations.RptagAPen, 5);
            WriteTag(memory, setTags + 0x08,
                GraphicsRastPortAttributeOperations.RptagBPen, 6);
            WriteTag(memory, setTags + 0x10,
                GraphicsRastPortAttributeOperations.RptagDrMd, 1);
            WriteTag(memory, setTags + 0x18,
                GraphicsRastPortAttributeOperations.RptagWriteMask, 3);
            WriteTag(memory, setTags + 0x20,
                GraphicsRastPortAttributeOperations.RptagOutlinePen, 7);
            WriteTag(memory, setTags + 0x28,
                GraphicsRastPortAttributeOperations.RptagMaxPen, 4);
            WriteTag(memory, setTags + 0x30,
                GraphicsRastPortAttributeOperations.TagDone, 0);

            WriteTag(memory, getTags + 0x00,
                GraphicsRastPortAttributeOperations.RptagAPen, outputs + 0x00);
            WriteTag(memory, getTags + 0x08,
                GraphicsRastPortAttributeOperations.RptagBPen, outputs + 0x04);
            WriteTag(memory, getTags + 0x10,
                GraphicsRastPortAttributeOperations.RptagDrMd, outputs + 0x08);
            WriteTag(memory, getTags + 0x18,
                GraphicsRastPortAttributeOperations.RptagWriteMask, outputs + 0x0C);
            WriteTag(memory, getTags + 0x20,
                GraphicsRastPortAttributeOperations.RptagOutlinePen, outputs + 0x10);
            WriteTag(memory, getTags + 0x28,
                GraphicsRastPortAttributeOperations.RptagMaxPen, outputs + 0x14);
            WriteTag(memory, getTags + 0x30,
                GraphicsRastPortAttributeOperations.TagDone, 0);

            var adapter = new CopperStartGraphicsRegisterAdapter(
                core,
                isRtgRastPort: address => address == rastPort);
            var set = new M68kCpuState
            {
                A = { [0] = setTags, [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 201
            };
            Assert.True(adapter.TryInvoke(
                set,
                (int)GraphicsLvo.SetRPAttrsA,
                nativeOverlay));
            Assert.Equal(0u, set.D[0]);
            Assert.Equal((byte)5,
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
            Assert.Equal((byte)6,
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortBgPen));
            Assert.Equal((byte)1,
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
            Assert.Equal((byte)0x07,
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortMask));
            Assert.Equal((byte)7,
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));

            var get = new M68kCpuState
            {
                A = { [0] = getTags, [1] = rastPort },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 202
            };
            Assert.True(adapter.TryInvoke(
                get,
                (int)GraphicsLvo.GetRPAttrsA,
                nativeOverlay));
            Assert.Equal(0u, get.D[0]);
            Assert.Equal(5u, ReadLong(memory, outputs + 0x00));
            Assert.Equal(6u, ReadLong(memory, outputs + 0x04));
            Assert.Equal(1u, ReadLong(memory, outputs + 0x08));
            Assert.Equal(0x07u, ReadLong(memory, outputs + 0x0C));
            Assert.Equal(7u, ReadLong(memory, outputs + 0x10));
            Assert.Equal(8u, ReadLong(memory, outputs + 0x14));
        }

        Exercise(nativeOverlay: false);
        Exercise(nativeOverlay: true);
    }

    [Fact]
    public void NativeOverlayLeavesRtgRastPortAttributeVectorsTransparent()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint rtgBitMap = 0x200;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(rtgBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, rtgBitMap);

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var a1Vectors = new[]
        {
            GraphicsLvo.SetAPen,
            GraphicsLvo.SetBPen,
            GraphicsLvo.SetDrMd,
            GraphicsLvo.SetFont,
            GraphicsLvo.AskFont,
            GraphicsLvo.AskSoftStyle,
            GraphicsLvo.SetSoftStyle,
            GraphicsLvo.SetRPAttrsA,
            GraphicsLvo.GetRPAttrsA
        };
        var a0Vectors = new[]
        {
            GraphicsLvo.GetAPen,
            GraphicsLvo.GetBPen,
            GraphicsLvo.GetDrMd,
            GraphicsLvo.SetABPenDrMd,
            GraphicsLvo.SetWriteMask,
            GraphicsLvo.SetMaxPen,
            GraphicsLvo.GetOutlinePen,
            GraphicsLvo.SetOutlinePen
        };

        foreach (var vector in a1Vectors.Concat(a0Vectors))
        {
            var state = new M68kCpuState
            {
                A =
                {
                    [0] = a0Vectors.Contains(vector) ? rastPort : 0xDEADu,
                    [1] = a1Vectors.Contains(vector) ? rastPort : 0xDEADu
                },
                D = { [0] = sentinel, [1] = 0x1357_9BDFu, [2] = 0x2468_ACEDu },
                Cycles = 79
            };

            var address = unchecked((uint)((int)graphicsBase + (int)vector));
            Assert.True(bus.TryInvokeHostGatewayAt(address, state), vector.ToString());
            Assert.Equal(sentinel, state.D[0]);
            Assert.Equal(0x1357_9BDFu, state.D[1]);
            Assert.Equal(0x2468_ACEDu, state.D[2]);
            Assert.Equal(79, state.Cycles);
        }
    }

