    [Fact]
    public void RtgRastPortsLeaveEmptyTextToCyberGraphXBeforeThePortableNoOp()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: rastPort => rastPort == 0x20);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0x20 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 53
        };

        // The planar implementation has a valid empty-string no-op, but the
        // provider ownership decision must happen first so CyberGraphX can
        // observe even an empty text vector without losing the caller frame.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0xA5A5_5A5Au, state.D[0]);
        Assert.Equal(53, state.Cycles);
    }

    [Fact]
    public void RtgRastPortsLeaveEmptyPolyDrawToCyberGraphXBeforeThePortableNoOp()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: rastPort => rastPort == 0x20);
        var state = new M68kCpuState
        {
            A = { [0] = 0x180, [1] = 0x20 },
            D = { [0] = 0xA5A5_0000u },
            Cycles = 61
        };

        // PolyDraw consumes only the low UWORD count, so the standard-planar
        // count-zero form is a valid no-read success.  Provider ownership is
        // still decided first for RTG RastPorts so CyberGraphX receives the
        // original D0/cycle frame rather than a host no-op result.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.PolyDraw));
        Assert.Equal(0xA5A5_0000u, state.D[0]);
        Assert.Equal(61, state.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveRtgEmptyPolyDrawOwnership()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint rtgBitMap = 0x200;
        const uint sentinel = 0xCAFE_BABEu;
        const long cycle = 67;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(rtgBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, rtgBitMap);
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D = { [0] = sentinel },
            Cycles = cycle
        };
        direct.Invoke(directState, (int)GraphicsLvo.PolyDraw);

        var overlayState = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D = { [0] = sentinel },
            Cycles = cycle
        };
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.PolyDraw));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(sentinel, directState.D[0]);
        Assert.Equal(sentinel, overlayState.D[0]);
        Assert.Equal(cycle, directState.Cycles);
        Assert.Equal(cycle, overlayState.Cycles);
    }

    [Fact]
    public void RtgBitmapBackedRastPortsLeavePlanarDrawingFamilyToCyberGraphX()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint rtgBitMap = 0x300;
        const uint rtgPlane = 0x500;
        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteWord(
            rtgBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            rtgBitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            rtgBitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(1u << 3))); // BMF_STANDARD
        Assert.True(memory.TryWriteByte(
            rtgBitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            rtgBitMap + (uint)GraphicsLayouts.BitMapPlanes,
            rtgPlane));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            rtgBitMap));

        // Only the bitmap callback is installed.  The adapter must still
        // recognize the RastPort as provider-owned through rp_BitMap rather
        // than requiring a second callback for every aliasing RastPort.
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        Assert.True(adapter.IsProviderRastPort(rastPort));
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 37
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Draw));
        Assert.Equal(0x2468_ACEDu, state.D[0]);
        Assert.Equal(37, state.Cycles);
    }

    [Fact]
    public void ChangeViewPortBitMapValidatesDbufInfoBeforeChangingTheGuestAssociation()
    {
        var memory = new FakeMemory(0x2400);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint firstBitMap = 0x1200;
        const uint nextBitMap = 0x1400;
        const uint dbufInfoAddress = 0x1000;

        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, firstBitMap);
        memory.TryWriteWord(firstBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteByte(firstBitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.TryWriteWord(nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteByte(nextBitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        var dbufInfo = core.AllocDBufInfo(viewPort);
        Assert.Equal(dbufInfoAddress, dbufInfo);
        for (var offset = 0; offset < GraphicsLayouts.DBufInfoSize; offset++)
            memory.TryWriteByte(dbufInfo + (uint)offset, 0xA5);

        Assert.Equal(0, core.ChangeViewPortBitMap(viewPort, nextBitMap, dbufInfo));
        Assert.Equal(nextBitMap, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(viewPort, display.ChangedViewPort);
        Assert.Equal(nextBitMap, display.ChangedBitMap);
        Assert.Equal(dbufInfo, display.ChangedDBufInfo);
        Assert.Equal(1, display.ChangeCount);

        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, firstBitMap);
        Assert.Equal(-1, core.ChangeViewPortBitMap(viewPort, nextBitMap, dbufInfo + 1));
        Assert.Equal(firstBitMap, ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(1, display.ChangeCount);
    }

    [Fact]
    public void ChangeViewPortBitMapDeclinesMappedButUnownedDbufInfo()
    {
        var memory = new FakeMemory(0x2400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint firstBitMap = 0x1200;
        const uint nextBitMap = 0x1400;
        const uint foreignDbufInfo = 0x1800;

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            firstBitMap));
        Assert.True(memory.TryWriteWord(
            firstBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(
            firstBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));
        Assert.True(memory.TryWriteWord(
            nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(
            nextBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));
        for (var offset = 0; offset < GraphicsLayouts.DBufInfoSize; offset++)
            Assert.True(memory.TryWriteByte(
                foreignDbufInfo + (uint)offset,
                0xA5));

        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap, [2] = foreignDbufInfo },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 17
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(17, state.Cycles);
        Assert.Equal(
            firstBitMap,
            ReadLong(memory, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void ChangeViewPortBitMapReadsOnlyTheRasInfoAndBitmapExchangeFields()
    {
        static (FakeMemory Backing, RangeReadFaultMemory Memory, FakeDisplay Display, GraphicsLibraryCore Core, uint RasInfo, uint FirstBitMap, uint NextBitMap, uint DbufInfo)
            Prepare()
        {
            var backing = new FakeMemory(0x2400);
            var memory = new RangeReadFaultMemory(backing);
            var display = new FakeDisplay();
            var core = CreateCore(memory, display);
            const uint viewPort = 0x180;
            const uint rasInfo = 0x1C0;
            const uint firstBitMap = 0x1200;
            const uint nextBitMap = 0x1400;

            Assert.True(backing.TryWriteLong(
                viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                rasInfo));
            Assert.True(backing.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoNext,
                0));
            Assert.True(backing.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
                firstBitMap));
            foreach (var bitMap in new[] { firstBitMap, nextBitMap })
            {
                Assert.True(backing.TryWriteWord(
                    bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                    4));
                Assert.True(backing.TryWriteWord(
                    bitMap + (uint)GraphicsLayouts.BitMapRows,
                    8));
                Assert.True(backing.TryWriteByte(
                    bitMap + (uint)GraphicsLayouts.BitMapDepth,
                    2));
            }

            var dbufInfo = core.AllocDBufInfo(viewPort);
            Assert.NotEqual(0u, dbufInfo);

            // DWidth through SpritePriorities are not ChangeVPBitMap inputs.
            // Fault that unrelated scalar span after DBufInfo setup while
            // leaving ExtendedModes readable for its standard-planar guard;
            // the focused exchange preflight must still claim the operation.
            memory.FailReads(
                viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
                (uint)(GraphicsLayouts.ViewPortExtendedModes - GraphicsLayouts.ViewPortDWidth));
            return (backing, memory, display, core, rasInfo, firstBitMap, nextBitMap, dbufInfo);
        }

        var direct = Prepare();
        Assert.Equal(
            0,
            direct.Core.ChangeViewPortBitMap(
                0x180,
                direct.NextBitMap,
                direct.DbufInfo));
        Assert.Equal(
            direct.NextBitMap,
            ReadLong(
                direct.Backing,
                direct.RasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(1, direct.Display.ChangeCount);

        var mapped = Prepare();
        var adapter = new CopperStartGraphicsRegisterAdapter(mapped.Core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x180, [1] = mapped.NextBitMap, [2] = mapped.DbufInfo },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 137
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeVPBitMap));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(137, state.Cycles);
        Assert.Equal(
            mapped.NextBitMap,
            ReadLong(
                mapped.Backing,
                mapped.RasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(1, mapped.Display.ChangeCount);
    }

