    [Fact]
    public void PlanarPixelsLinesAndRectanglesUseRastPortState()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.Move(0x20, 1, 1));
        Assert.Equal(0, core.Draw(0x20, 1, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 1));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 4));
        Assert.Equal((short)1, unchecked((short)ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)4, unchecked((short)ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentY)));

        // Draw continues across the non-layered bitmap clip boundary: the
        // off-raster prefix is ignored while the visible suffix is painted,
        // and the public pen still advances to the requested endpoint.
        Assert.Equal(0, core.Move(0x20, -2, 0));
        Assert.Equal(0, core.Draw(0x20, 2, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 0));
        Assert.Equal((short)2, ReadSignedWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX));

        Assert.Equal(0, core.SetAPen(0x20, 2));
        Assert.Equal(0, core.RectFill(0x20, 2, 2, 3, 3));
        Assert.Equal(2, core.ReadPixel(0x20, 2, 2));
        Assert.Equal(2, core.ReadPixel(0x20, 3, 3));
    }

    [Fact]
    public void PureDrawAndPolyDrawDeclineLayeredRastPortsWithoutAProviderBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint points = 0x300;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.True(memory.TryWriteWord(points, 2));
        Assert.True(memory.TryWriteWord(points + 2u, 1));

        // Move only updates the guest cursor; the actual line operation must
        // remain behind the explicit layers/native claim boundary.  Calling
        // the portable core directly must not bypass that split by painting
        // the backing planar bitmap.
        Assert.Equal(0, core.Move(rastPort, 1, 1));
        Assert.Equal(-1, core.Draw(rastPort, 2, 1));
        Assert.Equal((short)1, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(0, ReadByte(memory, 0x402));
        Assert.Equal(0, ReadByte(memory, 0x502));

        Assert.Equal(-1, core.PolyDraw(rastPort, 1, points));
        Assert.Equal((short)1, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(-1, core.ReadPixel(rastPort, 2, 1));
        Assert.Equal(-1, core.WritePixel(rastPort, 2, 1));
        Assert.Equal(-1, core.SetRast(rastPort, 1));
        // Even an empty PolyDraw must remain behind the layer ownership
        // boundary when the layer link is readable.  The standard-planar
        // empty no-op remains covered separately with an unreadable endpoint.
        Assert.Equal(-1, core.PolyDraw(rastPort, 0, 0));
        Assert.Equal(-1, core.AreaMove(rastPort, 2, 1));
        Assert.Equal(-1, core.AreaEnd(rastPort));
        Assert.Equal(-1, core.Flood(rastPort, 0, 2, 1));
        var fonts = new FakeFontBackend();
        // Empty geometry does not bypass the direct/core layer ownership
        // boundary. The register adapter may hand these vectors to a layer
        // provider, but a pure call without a visibility predicate declines.
        Assert.Equal(-1, core.Text(rastPort, 0, 0, fonts));
        Assert.Equal(-1, core.RectFill(rastPort, 2, 1, 1, 1));
        Assert.Equal(-1, core.ScrollRaster(rastPort, 1, 0, 2, 1, 1, 1));
        Assert.Equal(-1, core.ScrollRasterBF(rastPort, 1, 0, 2, 1, 1, 1));
        Assert.Equal(-1, core.EraseRect(rastPort, 2, 1, 1, 1));
        Assert.Equal(-1, core.BltPattern(rastPort, 0, 2, 1, 1, 1, 0));
        Assert.True(memory.TryWriteByte(0x320, (byte)'A'));
        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(-1, core.Text(rastPort, 0x320, 1, fonts));
        Assert.Equal(0, ReadByte(memory, 0x402));
        Assert.Equal(0, ReadByte(memory, 0x502));
    }

    [Fact]
    public void PurePixelArrayHelpersDeclineLayeredRastPortsWithoutAProviderBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint array = 0x900;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.True(memory.TryWriteByte(array, 3));

        // The register adapter routes this case to an explicit layers
        // provider.  Direct portable/core callers must observe the same
        // ownership boundary instead of writing through the backing planes.
        Assert.Equal(-1, core.ReadPixelLine8(rastPort, 0, 0, 1, array, 0));
        Assert.Equal(-1, core.WritePixelLine8(rastPort, 0, 0, 1, array, 0));
        Assert.Equal(-1, core.ReadPixelArray8(rastPort, 0, 0, 0, 0, array, 0));
        Assert.Equal(-1, core.WritePixelArray8(rastPort, 0, 0, 0, 0, array, 0));
        Assert.Equal(-1, core.WriteChunkyPixels(rastPort, 0, 0, 0, 0, array, 1));

        Assert.False(core.TryReadPixelLine8(
            rastPort,
            0,
            0,
            1,
            array,
            0,
            out var status));
        Assert.Equal(-1, status);
        Assert.Equal(-1, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal((byte)3, ReadByte(memory, array));
    }

    [Fact]
    public void RectFillAcceptsAPlanarRowSpanEndingAtTheGuestAddressLimit()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane0 = 0xFFFF_FFFE;
        const uint plane1 = 0xFFFF_FFFC;

        // WrappingMemory is sparse, so initialize the RastPort fields that
        // FakeMemory would otherwise provide as zero-filled storage.
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, 0));
        Assert.True(memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0));
        Assert.True(memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 0));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
        Assert.True(memory.TryWriteByte(plane0, 0));
        Assert.True(memory.TryWriteByte(unchecked(plane0 + 1u), 0));
        Assert.True(memory.TryWriteByte(plane1, 0));
        Assert.True(memory.TryWriteByte(unchecked(plane1 + 1u), 0));

        // Two bytes per plane are touched by x=0..15; the second byte of
        // plane0 ends exactly at 0xFFFFFFFF and must remain addressable.
        Assert.Equal(0, core.RectFill(rastPort, 0, 0, 15, 0));
        Assert.True(memory.TryReadByte(plane0, out var plane0First));
        Assert.True(memory.TryReadByte(unchecked(plane0 + 1u), out var plane0Last));
        Assert.True(memory.TryReadByte(plane1, out var plane1First));
        Assert.True(memory.TryReadByte(unchecked(plane1 + 1u), out var plane1Last));
        Assert.Equal((byte)0xFF, plane0First);
        Assert.Equal((byte)0xFF, plane0Last);
        Assert.Equal((byte)0xFF, plane1First);
        Assert.Equal((byte)0xFF, plane1Last);
    }

    [Fact]
    public void SetRastAcceptsAPlanarSpanEndingAtTheGuestAddressLimitThroughBothGateways()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane0 = 0xFFFF_FFFE;
        const uint plane1 = 0xFFFF_FFFC;

        // CreateCore's dense-memory fixture defaults do not populate the
        // optional fields in a sparse wrapping guest memory, so publish the
        // complete non-layered envelope explicitly before the SetRast probe.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            0));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane0));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4,
            plane1));
        Assert.True(memory.TryWriteByte(plane0, 0));
        Assert.True(memory.TryWriteByte(unchecked(plane0 + 1u), 0));
        Assert.True(memory.TryWriteByte(plane1, 0));
        Assert.True(memory.TryWriteByte(unchecked(plane1 + 1u), 0));

        // A two-byte plane row ending at $FFFFFFFF is a valid inclusive
        // guest span.  SetRast must snapshot and publish both selected
        // planes instead of rejecting the address arithmetic before the
        // first write.
        Assert.Equal(0, core.SetRast(rastPort, 3));
        Assert.True(memory.TryReadByte(plane0, out var plane0First));
        Assert.True(memory.TryReadByte(unchecked(plane0 + 1u), out var plane0Last));
        Assert.True(memory.TryReadByte(plane1, out var plane1First));
        Assert.True(memory.TryReadByte(unchecked(plane1 + 1u), out var plane1Last));
        Assert.Equal((byte)0xFF, plane0First);
        Assert.Equal((byte)0xFF, plane0Last);
        Assert.Equal((byte)0xFF, plane1First);
        Assert.Equal((byte)0xFF, plane1Last);

        // The CopperStart register path must preserve the same legal result
        // and publish the void-vector D0 convention after dispatch.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3u },
            Cycles = 19
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetRast));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(19, state.Cycles);
    }

    [Fact]
    public void SetRastSetsTheRequestedPenEvenWhenComplementModeIsActive()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 0));

        // SetRast initializes the complete planar raster; it is not a
        // draw-mode operation.  COMPLEMENT must therefore not toggle the
        // existing value when the requested pen is written.
        Assert.Equal(0, core.SetDrawMode(0x20, 2));
        Assert.Equal(0, core.SetRast(0x20, 1));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 15, 7));
    }

    [Fact]
    public void SetRastHonorsTheRastPortWriteMaskAcrossSelectedPlanes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetWriteMask(rastPort, 0x01));
        Assert.Equal(0, core.SetRast(rastPort, 3));

        // SetRast uses copy semantics, but the RastPort mask still protects
        // planes that are not selected.  Plane zero receives pen bit 1;
        // plane one remains the earlier zero, so the logical pixel is 1.
        Assert.Equal(1, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(1, core.ReadPixel(rastPort, 15, 7));
    }

    [Fact]
    public void SetRastWithZeroWriteMaskDoesNotWalkAFullGuestRaster()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        // 65536 columns x 65535 rows is a valid 16-bit guest geometry, but
        // the plane span is deliberately not mapped. A zero mask must be a
        // bounded success rather than a multi-billion-pixel host walk.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF8));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));

        Assert.Equal(0, core.SetRast(rastPort, 3));
    }

    [Fact]
    public void SetRastRejectsAnUnstageableMaximumPlaneSpanBeforeWalkingIt()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        // 65534 bytes per row x 65535 rows exceeds Int32.MaxValue while
        // remaining a valid UWORD bitmap envelope.  The selected plane is
        // intentionally unavailable: SetRast must reject the unstageable
        // transaction before entering its multi-billion-byte preflight.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            65534));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x3FF0));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        Assert.Equal(-1, core.SetRast(rastPort, 1));
    }

    [Fact]
    public void SetRastRejectsAnUnstageableMaximumPixelWalkEvenWhenPlaneBytesFit()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        // One plane with 8192 bytes per row and 65535 rows keeps the
        // per-plane byte span below Int32.MaxValue, but the SetRast pixel
        // walk still contains 65536 * 65535 samples.  The plane storage is
        // deliberately unavailable so the guard must decline before any
        // byte or pixel traversal.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x3FF0));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        Assert.Equal(-1, core.SetRast(rastPort, 1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 41
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetRast));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(41, state.Cycles);
    }

    [Fact]
    public void SetRastRejectsSelectedPlaneAggregateWorkBeforeReadingThePlanes()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        // One plane remains individually representable: the row span and
        // logical pixel count are both below Int32.MaxValue. Selecting all
        // eight planes makes probe + rollback + publication exceed the
        // aggregate transaction budget. Plane pointers are intentionally
        // mapped at the tracked edge; an early admission check must decline
        // before reading any of them.
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            512));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            8));
        for (var plane = 0; plane < 8; plane++)
        {
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                0x1FF0));
        }

        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));
        Assert.Equal(-1, core.SetRast(rastPort, 3));
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRejectSetRastSelectedPlaneAggregateWork()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x300;
        const uint nativeTarget = 0x00FE_1A01;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRast)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, ushort.MaxValue);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8, 0);
            for (var plane = 0; plane < 8; plane++)
            {
                bus.WriteLong(
                    bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                    0xDEAD_AD00);
            }

            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [5] = 0xA5A5_5A5Au },
            Cycles = 719,
            ProgramCounter = 0x0012_38B1
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [5] = 0xA5A5_5A5Au },
            Cycles = 719,
            ProgramCounter = 0x0012_38B1
        };

        direct.Invoke(directState, (int)GraphicsLvo.SetRast);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.SetRast)),
            overlayState));
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(3u, directState.D[0]);
        Assert.Equal(0xA5A5_5A5Au, directState.D[5]);
        Assert.Equal(directState.D[5], overlayState.D[5]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
    }

    [Fact]
    public void SetRastTreatsMaskBitsAboveBitmapDepthAsAZeroMask()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
