        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 43
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetRast));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(43, state.Cycles);
    }

