    }

    [Fact]
    public void ClearEraseAndScrollDeclinePrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;

        static void Prepare(GraphicsLibraryCore core, FakeMemory backing)
        {
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
                1));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
                0));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
                1));
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                1));
        }

        static void AssertDeclined(
            GraphicsLvo vector,
            Func<GraphicsLibraryCore, int> direct,
            Action<M68kCpuState> setArguments,
            uint expectedD0)
        {
            var backing = new FakeMemory(0x4000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Prepare(core, backing);
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte) * 2u);

            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                sizeof(uint));

            Assert.Equal(-1, direct(core));
            Assert.Equal(0, memory.FaultedReadCount);

            var mappedBacking = new FakeMemory(0x4000);
            var mappedMemory = new RangeReadFaultMemory(mappedBacking);
            var mappedCore = CreateCore(mappedMemory);
            Prepare(mappedCore, mappedBacking);
            mappedMemory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte) * 2u);
            mappedMemory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                sizeof(uint));

            var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 103
            };
            setArguments(state);

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(expectedD0, state.D[0]);
            Assert.Equal(103, state.Cycles);
            Assert.Equal(0, mappedMemory.FaultedReadCount);
        }

        AssertDeclined(
            GraphicsLvo.ClearEOL,
            core => core.ClearEOL(rastPort),
            _ => { },
            0xCAFE_BABEu);
        AssertDeclined(
            GraphicsLvo.ClearScreen,
            core => core.ClearScreen(rastPort),
            _ => { },
            0xCAFE_BABEu);
        AssertDeclined(
            GraphicsLvo.EraseRect,
            core => core.EraseRect(rastPort, 0, 0, 1, 1),
            state =>
            {
                state.D[0] = 0;
                state.D[1] = 0;
                state.D[2] = 1;
                state.D[3] = 1;
            },
            0);
        AssertDeclined(
            GraphicsLvo.ScrollRaster,
            core => core.ScrollRaster(rastPort, 1, 0, 0, 0, 1, 1),
            state =>
            {
                state.D[0] = 1;
                state.D[1] = 0;
                state.D[2] = 0;
                state.D[3] = 0;
                state.D[4] = 1;
                state.D[5] = 1;
            },
            1);
        AssertDeclined(
            GraphicsLvo.ScrollRasterBF,
            core => core.ScrollRasterBF(rastPort, 1, 0, 0, 0, 1, 1),
            state =>
            {
                state.D[0] = 1;
                state.D[1] = 0;
                state.D[2] = 0;
                state.D[3] = 0;
                state.D[4] = 1;
                state.D[5] = 1;
            },
            1);
    }

