    [Fact]
    public void ClearVectorsWithZeroWriteMaskDoNotWalkAFullGuestRaster()
    {
        static void AssertBoundedClear(Func<IGraphicsMemory, int> clear)
        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            const uint rastPort = 0x20;
            const uint bitMap = 0x100;

            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            // 65536 columns x 65535 rows is a valid 16-bit guest geometry,
            // but the plane span is deliberately not mapped.  ClearEOL and
            // ClearScreen must publish their line-state result without
            // walking a multi-billion-pixel zero-mask destination.
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                8192));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                ushort.MaxValue));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                0x1FF8));
            Assert.True(memory.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
                1));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));

            Assert.Equal(0, clear(memory));
            Assert.Equal(
                (byte)15,
                ReadByte(
                    memory,
                    rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        }

        AssertBoundedClear(memory => GraphicsRasterOperations.ClearEOL(memory, 0x20));
        AssertBoundedClear(memory => GraphicsRasterOperations.ClearScreen(memory, 0x20));
    }

    [Fact]
    public void ClearVectorsWithZeroEffectiveMaskDoNotReadPublicPensOrGeometryAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint patternCount = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        static (FakeMemory Backing, RangeReadFaultMemory Memory, GraphicsLibraryCore Core)
            Prepare(uint rastPort, uint bitMap)
        {
            var backing = new FakeMemory(0x2000);
            var setup = CreateCore(backing);
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(backing.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                8192));
            Assert.True(backing.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                ushort.MaxValue));
            Assert.True(backing.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                0x1FF8));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
                1));
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0x80));
            Assert.True(backing.TryWriteByte(
                patternCount,
                4));

            var memory = new RangeReadFaultMemory(backing);
            // The zero-effective-mask path must not require the public mode,
            // either pen, text geometry, or CurrentX/CurrentY. Make the
            // contiguous mode/pen range unreadable so a stale
            // SetAPen/RectFill preflight cannot accidentally satisfy the test
            // while the mask byte remains readable.
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                4u);
            // Text geometry and CurrentX are also outside the zero-mask
            // ownership boundary. The native clear vectors can reset their
            // line phase without consuming either the selected font fields
            // or the cursor position.
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
                sizeof(ushort));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
                sizeof(ushort));
            var core = new GraphicsLibraryCore(
                memory,
                new FakeAllocator(),
                new FakeBlitter(),
                new FakeDisplay());
            return (backing, memory, core);
        }

        static void AssertDirect(
            Func<GraphicsLibraryCore, int> clear,
            uint rastPort,
            uint patternCount,
            uint bitMap)
        {
            var prepared = Prepare(rastPort, bitMap);
            Assert.Equal(0, clear(prepared.Core));
            Assert.Equal(0, prepared.Memory.FaultedReadCount);
            Assert.Equal((byte)15, ReadByte(prepared.Backing, patternCount));
        }

        static void AssertMapped(
            GraphicsLvo vector,
            uint rastPort,
            uint patternCount,
            uint bitMap)
        {
            var prepared = Prepare(rastPort, bitMap);
            var adapter = new CopperStartGraphicsRegisterAdapter(prepared.Core);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 43
            };

            Assert.True(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(43, state.Cycles);
            Assert.Equal(0, prepared.Memory.FaultedReadCount);
            Assert.Equal((byte)15, ReadByte(prepared.Backing, patternCount));
        }

        AssertDirect(
            core => core.ClearEOL(rastPort),
            rastPort,
            patternCount,
            bitMap);
        AssertDirect(
            core => core.ClearScreen(rastPort),
            rastPort,
            patternCount,
            bitMap);
        AssertMapped(GraphicsLvo.ClearEOL, rastPort, patternCount, bitMap);
        AssertMapped(GraphicsLvo.ClearScreen, rastPort, patternCount, bitMap);
    }

    [Fact]
    public void ClearVectorsRejectBitmapCoordinateEndpointsOutsideSignedWordEnvelopeAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint patternCount = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        static (FakeMemory Memory, GraphicsLibraryCore Core) Prepare(
            uint rastPort,
            uint bitMap)
        {
            var memory = new FakeMemory(0x3000);
            var core = CreateCore(memory);
            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            // 65536 pixels make the right edge 65535, which cannot be
            // represented by the signed WORD coordinates used by RectFill.
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                8192));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                1));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                0x2000));
            Assert.True(memory.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
                1));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                1));
            Assert.True(memory.TryWriteByte(patternCount, 4));
            return (memory, core);
        }

        static void AssertDirect(
            Func<GraphicsLibraryCore, int> clear,
            uint rastPort,
            uint bitMap,
            uint patternCount)
        {
            var prepared = Prepare(rastPort, bitMap);
            Assert.Equal(-1, clear(prepared.Core));
            Assert.Equal((byte)4, ReadByte(prepared.Memory, patternCount));
        }

        static void AssertMapped(
            GraphicsLvo vector,
            uint rastPort,
            uint bitMap,
            uint patternCount)
        {
            var prepared = Prepare(rastPort, bitMap);
            var adapter = new CopperStartGraphicsRegisterAdapter(prepared.Core);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 47
            };

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(47, state.Cycles);
            Assert.Equal((byte)4, ReadByte(prepared.Memory, patternCount));
        }

        AssertDirect(core => core.ClearEOL(rastPort), rastPort, bitMap, patternCount);
        AssertDirect(core => core.ClearScreen(rastPort), rastPort, bitMap, patternCount);
        AssertMapped(GraphicsLvo.ClearEOL, rastPort, bitMap, patternCount);
        AssertMapped(GraphicsLvo.ClearScreen, rastPort, bitMap, patternCount);
    }

    [Fact]
    public void ClearScreenRejectsAnUnstageableMaximumPlaneSpanBeforeWalkingIt()
    {
        var memory = new FakeMemory(0x20000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            8));

        // Keep the one-row text prefix readable so the guard is exercised on
        // the remaining full-width span rather than on an earlier plane
        // pointer.  The eight selected planes and 65535 rows exceed the
        // portable transactional limit.
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            1));
        for (var plane = 0; plane < 8; plane++)
        {
            var planeAddress = 0x4000u + ((uint)plane * 0x2000u);
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + ((uint)plane * 4u),
                planeAddress));
            for (var offset = 0u; offset < 8192u; offset++)
                Assert.True(memory.TryWriteByte(planeAddress + offset, 0));
        }

        Assert.Equal(-1, core.ClearScreen(rastPort));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { D = { [0] = 0xA5A5_A5A5u } };
        state.A[1] = rastPort;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ClearScreen));
        Assert.Equal(0xA5A5_A5A5u, state.D[0]);
    }

    [Fact]
    public void ClearScreenRejectsAnUnstageableMaximumPixelWalkEvenWhenPlaneBytesFit()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        // The selected plane's byte span is below Int32.MaxValue, but the
        // logical 65536 x 65535 fill still exceeds the portable pixel-walk
        // budget. The plane is intentionally unavailable so the shared
        // region guard must decline before any row or pixel probe.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x3FF0));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        Assert.Equal(-1, core.ClearScreen(rastPort));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 41
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ClearScreen));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(41, state.Cycles);
    }

    [Fact]
    public void ClearScreenRejectsAggregateWorkBeforePlaneStaging()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4098));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(backing.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF0));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            1));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
            1));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            32767));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        // The two clipped halves are each individually below Int32.MaxValue,
        // but their complete probe/fill transaction exceeds the four-pass
        // ClearScreen budget. The plane is deliberately unmapped so an early
        // aggregate guard must decline before reading its pointer target.
        Assert.Equal(-1, core.ClearScreen(rastPort));
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void ClearEolRejectsSelectedPlaneAggregateWorkBeforePlaneStaging()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            512));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            8));
        for (var plane = 0; plane < 8; plane++)
        {
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                0x1FF0));
        }

        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            ushort.MaxValue));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
            0));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            0));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            0));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));

        // The one-plane logical and row spans fit independently, but the
        // outer rollback plus nested FillRectangle transaction multiplied by
        // all eight selected planes exceeds the host work contract. The
        // plane targets are deliberately unmapped/tracked to prove the guard
        // runs before destination staging.
        Assert.Equal(-1, core.ClearEOL(rastPort));
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRejectClearEolSelectedPlaneAggregateWork()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x300;
        const uint nativeTarget = 0x00FE_1A01;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ClearEOL)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 512);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, ushort.MaxValue);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8, 0);
            for (var plane = 0; plane < 8; plane++)
            {
                bus.WriteLong(
                    bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                    0xDEAD_AD00);
            }

            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, ushort.MaxValue);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 727,
            ProgramCounter = 0x0012_38B1
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 727,
            ProgramCounter = 0x0012_38B1
        };

        direct.Invoke(directState, (int)GraphicsLvo.ClearEOL);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ClearEOL)),
            overlayState));
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(0xA5A5_5A5Au, directState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
    }

    [Fact]
    public void EraseRectRejectsCombinedOuterAndDelegatedPlaneWorkBeforeStaging()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2048));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));
        for (var plane = 0; plane < 2; plane++)
        {
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                0x1FF0));
        }

        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            3));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            0));

        // BltPattern's local budget admits this rectangle, but EraseRect's
        // outer rollback makes the complete delegated transaction exceed the
        // host envelope. Plane pointers remain unread at the tracked edge.
        Assert.Equal(
            -1,
            core.EraseRect(rastPort, 0, 0, short.MaxValue, short.MaxValue));
        Assert.Equal(0, memory.TrackedReadCount);
    }

