    [Fact]
    public void LayeredSetRastProbesAndSnapshotsOnlyVisibleBitmapFragments()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        // Keep the first row of plane one addressable, but make the next row
        // cross the guest-memory envelope.  A layer clip exposing only row
        // zero must not fault while probing or snapshotting the hidden rows.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            0x1FFE));
        Assert.True(memory.TryWriteByte(0x1FFE, 0));
        Assert.True(memory.TryWriteByte(0x1FFF, 0));

        Assert.Equal(
            0,
            GraphicsRasterOperations.SetRast(
                memory,
                rastPort,
                3,
                pixelVisible: static (_, y) => y == 0));

        Assert.Equal((byte)0xFF, ReadByte(memory, 0x1FFE));
        Assert.Equal((byte)0xFF, ReadByte(memory, 0x1FFF));
    }

    [Fact]
    public void LayeredSetRastReusesVisibilityBetweenSnapshotAndPublication()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));

        var visibilityCalls = 0;
        var visibilityCoordinates = new List<(int X, int Y)>();

        bool IsVisible(int x, int y)
        {
            visibilityCalls++;
            visibilityCoordinates.Add((x, y));
            // Admit only the first visible cell.  SetRast must reuse that
            // result between its visible snapshot and publication walk.
            return visibilityCalls == 1;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.SetRast(
                memory,
                rastPort,
                3,
                pixelVisible: IsVisible));

        Assert.True(visibilityCalls > 1);
        Assert.Equal(1, visibilityCoordinates.Count(point =>
            point.X == visibilityCoordinates[0].X &&
            point.Y == visibilityCoordinates[0].Y));

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));
    }

    [Fact]
    public void LayeredTextPreflightSkipsInvisibleBitmapFragments()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint text = 0x320;

        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0, core.Move(rastPort, 0, 3));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            0x1FFE));
        Assert.True(memory.TryWriteByte(0x1FFE, 0));
        Assert.True(memory.TryWriteByte(0x1FFF, 0));

        // The glyph reaches rows one and two, but only row zero belongs to
        // the layer's visible fragment.  A provider visibility predicate
        // must suppress hidden-row probes before the malformed plane span is
        // touched.
        Assert.Equal(
            0,
            GraphicsTextOperations.Text(
                memory,
                rastPort,
                text,
                1,
                fonts,
                pixelVisible: static (_, y) => y == 0));
    }

    [Fact]
    public void LayeredHiddenColorTextAdvancesCursorWithoutColorStrikeAdmission()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var fonts = new CountingHiddenColorFontBackend();
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.Equal(0, core.Move(rastPort, 0, 3));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            (uint)(GraphicsLayouts.RastPortBgPen - GraphicsLayouts.RastPortFgPen + 1));

        // Text still consumes the guest stream and publishes its cursor, but
        // a fully hidden provider destination must not claim the ColorTextFont
        // strike representation or touch the planar backing bitmap.
        Assert.Equal(
            0,
            GraphicsTextOperations.Text(
                memory,
                rastPort,
                text,
                1,
                fonts,
                pixelVisible: static (_, _) => false));
        Assert.Equal(0, fonts.ColorFontRequests);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((short)4, ReadSignedWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(0, ReadByte(backing, 0x400));
    }

