        const uint rastPort = 0x20;
        const uint text = 0x320;

        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1));
        Assert.Equal(0, core.Move(rastPort, -3, 3));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));

        var visibilityCalls = new List<(int X, int Y)>();
        bool IsVisible(int x, int y)
        {
            visibilityCalls.Add((x, y));
            return y == 0;
        }

        // The glyph starts three pixels left of the bitmap.  Text traversal
        // and cursor publication still consume the complete character cell,
        // but the layer predicate may observe only in-bitmap destinations.
        Assert.Equal(
            0,
            GraphicsTextOperations.Text(
                memory,
                rastPort,
                text,
                1,
                fonts,
                pixelVisible: IsVisible));

        Assert.NotEmpty(visibilityCalls);
        Assert.All(visibilityCalls, call =>
        {
            Assert.InRange(call.X, 0, 15);
            Assert.InRange(call.Y, 0, 7);
        });
    }

    [Fact]
    public void LayeredTextReusesVisibilityBetweenPreflightAndPublication()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint text = 0x320;

        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0, core.SetBPen(rastPort, 2));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1));
        Assert.Equal(0, core.Move(rastPort, 0, 3));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));

        var visibilityCalls = 0;
        var firstX = 0;
        var firstY = 0;
        var visibilityCoordinates = new List<(int X, int Y)>();

        bool IsVisible(int x, int y)
        {
            visibilityCalls++;
            visibilityCoordinates.Add((x, y));
            if (visibilityCalls == 1)
            {
                firstX = x;
                firstY = y;
                return true;
            }

            // Only the first provider cell is admitted.  Its cached decision
            // must survive Text's later snapshot and publication passes.
            return false;
        }

        Assert.Equal(
            0,
            GraphicsTextOperations.Text(
                memory,
                rastPort,
                text,
                1,
                fonts,
                pixelVisible: IsVisible));

        Assert.True(visibilityCalls > 1);
        Assert.Equal(1, visibilityCoordinates.Count(point =>
            point.X == firstX && point.Y == firstY));

        // ReadPixel remains provider-owned while the layer is attached.  The
        // admitted cell was JAM2-filled with BPen=2, so inspect it after
        // clearing only the test layer link.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.Equal(3, core.ReadPixel(rastPort, (short)firstX, (short)firstY));
    }

