    [Fact]
    public void LayeredBltBitMapReusesVisibilityAcrossStagingSnapshotAndPublication()
    {
        var memory = new FakeMemory(0x2000);
        const uint source = 0x100;
        const uint destination = 0x180;
        WritePlanarBitmap(memory, source, 0x400, 0, rows: 2, depth: 1);
        WritePlanarBitmap(memory, destination, 0x600, 0, rows: 2, depth: 1);
        Assert.True(memory.TryWriteByte(0x400, 0x80));
        Assert.True(memory.TryWriteByte(0x402, 0x80));

        var providerCalls = new Dictionary<(int X, int Y), int>();
        bool IsVisible(int x, int y)
        {
            var key = (x, y);
            providerCalls.TryGetValue(key, out var calls);
            providerCalls[key] = calls + 1;
            // Every destination cell is admitted once. A second query for a
            // cell would hide it and expose a non-transactional blit.
            return calls == 0;
        }

        Assert.Equal(
            1,
            GraphicsBlitOperations.BltBitMap(
                memory,
                source,
                0,
                0,
                destination,
                0,
                0,
                8,
                2,
                0xC0,
                0x01,
                0,
                pixelVisible: IsVisible));

        Assert.Equal(16, providerCalls.Count);
        Assert.All(providerCalls.Values, calls => Assert.Equal(1, calls));
        Assert.NotEqual((byte)0, ReadByte(memory, 0x600));
        Assert.NotEqual((byte)0, ReadByte(memory, 0x602));
    }

