    [Fact]
    public void LayeredFloodPreflightSkipsInvisibleBitmapFragments()
    {
        var memory = new FakeMemory(0x2000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane0 = 0x500;
        const uint plane1 = 0x1FFC;

        // Rows zero and one of plane one are mapped; row two crosses the
        // guest-memory boundary.  The seed row is connected only to row one,
        // whose zero colour is the outline stop, so Flood never needs the
        // hidden row as a source sample.  Its destination preflight must
        // nevertheless skip that row through the provider visibility hook.
        WritePlanarBitmap(memory, bitMap, plane0, plane1, rows: 3);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            3));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane0 + 1, 0));
        Assert.True(memory.TryWriteByte(plane0 + 2, 0));
        Assert.True(memory.TryWriteByte(plane0 + 3, 0));
        Assert.True(memory.TryWriteByte(plane1, 0));
        Assert.True(memory.TryWriteByte(plane1 + 1, 0));
        Assert.True(memory.TryWriteByte(plane1 + 2, 0));
        Assert.True(memory.TryWriteByte(plane1 + 3, 0));

        Assert.Equal(
            1,
            GraphicsRasterOperations.Flood(
                memory,
                allocator: null,
                rastPort: rastPort,
                mode: 0,
                x: 0,
                y: 0,
                scratch: null,
                allowLayered: true,
             pixelVisible: static (_, y) => y == 0));
    }

