        Assert.True(backing.TryWriteByte(plane0, 0x5A));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            sizeof(uint));

        // A provider-owned destination is fully hidden.  Neither the
        // AreaPtrn decoder nor the external stencil may be admitted merely
        // because their guest pointers are unusable.
        Assert.Equal(
            0,
            GraphicsRasterOperations.BltPattern(
                memory,
                rastPort,
                unusableStencil,
                0,
                0,
                7,
                1,
                2,
                pixelVisible: static (_, _) => false));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0x5A, ReadByte(backing, plane0));
    }

    [Fact]
    public void LayeredBltPatternClipsHiddenRowsBeforeStencilProbe()
    {
        var memory = new FakeMemory(0x2000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane0 = 0x400;
        const uint stencil = 0x1FFE;

        WritePlanarBitmap(memory, bitMap, plane0, 0, rows: 2, depth: 1);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(memory.TryWriteByte(stencil, 0xFF));
        Assert.True(memory.TryWriteByte(stencil + 1u, 0xFF));

        // The second row would walk beyond the guest-memory envelope.  The
        // provider exposes only row zero, so the partial path must skip the
        // hidden row instead of probing the complete contiguous stencil.
        Assert.Equal(
            0,
            GraphicsRasterOperations.BltPattern(
                memory,
                rastPort,
                stencil,
                0,
                0,
                7,
                1,
                2,
                pixelVisible: static (_, y) => y == 0));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane0));
        Assert.Equal((byte)0x00, ReadByte(memory, plane0 + 2u));
    }

    [Fact]
    public void LayeredAreaEndCompletesComplementOutlineUndoThroughProviderAdmission()
    {
        var memory = new FakeMemory(0x4000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        const uint tmpRas = 0x900;
        const uint tmpBuffer = 0xA00;
        var visibilityCalls = new List<(int X, int Y)>();

        var core = CreateCore(memory);
        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)GraphicsLayouts.RastPortAreaOutline));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            3)); // JAM2 | COMPLEMENT
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            0));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
            1));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortTmpRas,
            tmpRas));
        Assert.True(memory.TryWriteLong(
            tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr,
            tmpBuffer));
        Assert.True(memory.TryWriteLong(
            tmpRas + (uint)GraphicsLayouts.TmpRasByteCount,
            8));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaMove(
                memory,
                rastPort,
                -1,
                1,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                4,
                1,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                4,
                4,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                -1,
                4,
                scratch: null,
                allowLayered: true));

        bool IsVisible(int x, int y)
        {
            visibilityCalls.Add((x, y));
            return true;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaEnd(
                memory,
                allocator: null,
                rastPort,
                scratch: null,
                allowLayered: true,
                pixelVisible: IsVisible));

        Assert.NotEmpty(visibilityCalls);
        Assert.All(visibilityCalls, call =>
        {
            Assert.InRange(call.X, 0, 15);
            Assert.InRange(call.Y, 0, 7);
        });
        Assert.Equal((ushort)0, ReadWord(
            memory,
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void LayeredAreaEndComplementUndoReusesTheClosingEndpointVisibilityDecision()
    {
        var memory = new FakeMemory(0x4000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        var core = CreateCore(memory);

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)GraphicsLayouts.RastPortAreaOutline));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            3)); // JAM2 | COMPLEMENT
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaMove(
                memory,
                rastPort,
                1,
                1,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                4,
                1,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                4,
                4,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                1,
                4,
                scratch: null,
                allowLayered: true));

        var closingEndpointCalls = 0;
        bool IsVisible(int x, int y)
        {
            if (x == 1 && y == 1)
            {
                closingEndpointCalls++;
                // The area destination preflight/fill visits the endpoint
                // before the outline. Let those samples remain hidden, then
                // admit the closing outline; any extra outline-phase query
                // exposes the bug.
                return closingEndpointCalls == 2;
            }

            return true;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaEnd(
                memory,
                allocator: null,
                rastPort,
                scratch: null,
                allowLayered: true,
                pixelVisible: IsVisible));

        // The complete AreaEnd transaction now shares one endpoint admission
        // across destination preflight, snapshot, outline publication, and
        // the COMPLEMENT undo.
        Assert.Equal(1, closingEndpointCalls);
    }

    [Fact]
    public void LayeredAreaEndReusesVisibilityAcrossShapePreflightSnapshotAndPublication()
    {
        var memory = new FakeMemory(0x4000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        var core = CreateCore(memory);

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            1)); // JAM2
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaMove(
                memory, rastPort, 1, 1, scratch: null, allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory, rastPort, 6, 1, scratch: null, allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory, rastPort, 6, 6, scratch: null, allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory, rastPort, 1, 6, scratch: null, allowLayered: true));

        var callsByCell = new Dictionary<(int X, int Y), int>();
        var providerCalls = 0;
        bool IsVisible(int x, int y)
        {
            providerCalls++;
            var key = (x, y);
            callsByCell.TryGetValue(key, out var count);
            callsByCell[key] = count + 1;
            return count == 0;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaEnd(
                memory,
                allocator: null,
                rastPort,
                scratch: null,
                allowLayered: true,
                pixelVisible: IsVisible));

        // The shape bounds are six by six. The provider admits every cell on
        // its first decision; later fill/snapshot/outline phases must reuse
        // those decisions rather than hide the admitted pixels.
        Assert.Equal(36, providerCalls);
        Assert.NotEqual((byte)0, ReadByte(memory, 0x402));
    }

    [Fact]
    public void LayeredAreaEndSkipsProviderHiddenShapeBeforePatternAndPenAdmission()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x300;
        const uint areaBuffer = 0x700;
        const uint plane0 = 0x400;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(backing.TryWriteByte(plane0, 0x5A));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            0x1FFE));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaMove(
                memory,
                rastPort,
                1,
                1,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                6,
                1,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                6,
                6,
                scratch: null,
                allowLayered: true));
        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaDraw(
                memory,
                rastPort,
                1,
                6,
                scratch: null,
                allowLayered: true));

        // The provider owns both public pen bytes for this hidden shape.  The
        // invalid pattern address additionally proves AreaPtrn is not decoded
        // after visibility establishes that no destination can publish.
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            (uint)(GraphicsLayouts.RastPortBgPen - GraphicsLayouts.RastPortFgPen + 1));

        Assert.Equal(
            0,
            GraphicsRasterOperations.AreaEnd(
                memory,
                allocator: null,
                rastPort,
                scratch: null,
                allowLayered: true,
                pixelVisible: static (_, _) => false));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0x5A, ReadByte(backing, plane0));
        Assert.Equal(
            (ushort)0,
            ReadWord(backing, areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

