        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        var visibilityCalls = 0;
        var firstOutlinePointCalls = 0;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x420));

        bool IsVisible(int x, int y)
        {
            visibilityCalls++;
            if (x == 4 && y == 6)
                firstOutlinePointCalls++;

            // Admit only the first provider sample.  The cached decision must
            // survive the later snapshot and publication passes, otherwise
            // the first outline point would be hidden by this stateful clip.
            return visibilityCalls == 1;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.DrawEllipse(
                memory,
                rastPort,
                4,
                4,
                2,
                2,
                pixelVisible: IsVisible));

        Assert.True(visibilityCalls > 1);
        Assert.Equal(1, firstOutlinePointCalls);
        // The public ReadPixel vector remains provider-owned while the layer
        // is non-null; inspect the admitted planar row directly instead.
        Assert.NotEqual((byte)0, ReadByte(memory, 0x40C));
    }

