    [Fact]
    public void RectFillInvertedBoundsDoNotRequireAReadableRastPortAcrossDirectAndMappedPaths()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint partiallyMappedRastPort = 0x1FFE;

        // The RastPort layer/bitmap fields fall outside this guest image. A
        // native-compatible inverted RectFill must still be a successful
        // no-op because the geometry is rejected before rp_Layer is read.
        Assert.Equal(
            0,
            core.RectFill(partiallyMappedRastPort, 7, 4, 6, 9));

        var state = new M68kCpuState
        {
            A = { [1] = partiallyMappedRastPort },
            D = { [0] = 7, [1] = 4, [2] = 6, [3] = 9 },
            Cycles = 83
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RectFill));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(4u, state.D[1]);
        Assert.Equal(6u, state.D[2]);
        Assert.Equal(9u, state.D[3]);
        Assert.Equal(83, state.Cycles);
    }

