        foreach (var vector in new[] { GraphicsLvo.ScrollRaster, GraphicsLvo.ScrollRasterBF })
        {
            var state = new M68kCpuState
            {
                A = { [1] = partiallyMappedRastPort },
                D = { [0] = 1, [1] = 2, [2] = 7, [3] = 4, [4] = 6, [5] = 9 },
                Cycles = 97
            };

            Assert.True(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(97, state.Cycles);
        }
    }

