    [Fact]
    public void RegisterPixelVectorsKeepMalformedRastPortsAvailableToNativeOwnership()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint oddRastPort = 0x301;
        const uint evenRastPort = 0x400;
        const uint bitMap = 0x500;
        const uint plane = 0x600;

        foreach (var rastPort in new[] { oddRastPort, evenRastPort })
        {
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortLayer,
                0));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                1));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
                0));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                1));
        }

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));

        var malformedRead = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 2, [1] = 1 },
            Cycles = 97
        };
        Assert.False(adapter.TryInvoke(malformedRead, (int)GraphicsLvo.ReadPixel));
        Assert.Equal(2u, malformedRead.D[0]);
        Assert.Equal(97, malformedRead.Cycles);

        var malformedWrite = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 2, [1] = 1 },
            Cycles = 101
        };
        Assert.False(adapter.TryInvoke(malformedWrite, (int)GraphicsLvo.WritePixel));
        Assert.Equal(2u, malformedWrite.D[0]);
        Assert.Equal(101, malformedWrite.Cycles);

        // A valid even RastPort still claims the documented -1 result for an
        // outside coordinate; this is distinct from malformed ownership.
        var outsideRead = new M68kCpuState
        {
            A = { [1] = evenRastPort },
            D = { [0] = unchecked((uint)(short)-1), [1] = 1 },
            Cycles = 103
        };
        Assert.True(adapter.TryInvoke(outsideRead, (int)GraphicsLvo.ReadPixel));
        Assert.Equal(0xFFFF_FFFFu, outsideRead.D[0]);
        Assert.Equal(103, outsideRead.Cycles);
    }

    [Fact]
    public void DrawEllipseUsesIntegerSymmetryAndRejectsNonPositiveRadii()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.DrawEllipse(0x20, 4, 4, 2, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 6, 4));
        Assert.Equal(-1, core.DrawEllipse(0x20, 4, 4, 0, 2));

        // Non-layered DrawEllipse does not software-clip.  The portable
        // memory boundary rejects the complete outline before publishing any
        // point when an ellipse would leave the bitmap.
        Assert.Equal(-1, core.DrawEllipse(0x20, 0, 4, 2, 2));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 2));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 4));
    }

    [Fact]
    public void DrawCircleUsesTheEqualRadiusEllipsePath()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.DrawCircle(0x20, 4, 4, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 6, 4));

        // The macro expands directly to DrawEllipse, so its existing
        // positive-radius admission remains visible for both zero and
        // negative radii.
        Assert.Equal(-1, core.DrawCircle(0x20, 4, 4, 0));
        Assert.Equal(-1, core.DrawCircle(0x20, 4, 4, -1));
    }

    [Fact]
    public void DrawEllipseDeclinesPrivateNoPensBeforePublicForegroundReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)GraphicsLayouts.RastPortNoPens));
        Assert.True(backing.TryWriteByte(plane0, 0x12));
        Assert.True(backing.TryWriteByte(plane1, 0x34));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 4u);

        Assert.Equal(-1, core.DrawEllipse(rastPort, 3, 3, 1, 1));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0x12, ReadByte(backing, plane0));
        Assert.Equal((byte)0x34, ReadByte(backing, plane1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 3, [2] = 1, [3] = 1 },
            Cycles = 61
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.DrawEllipse));
        Assert.Equal(3u, state.D[0]);
        Assert.Equal(61, state.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0x12, ReadByte(backing, plane0));
        Assert.Equal((byte)0x34, ReadByte(backing, plane1));
    }

    [Fact]
    public void DrawEllipseTreatsUnreadableFlagsAsAnOptionalProviderHintAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;
        const uint flags = rastPort + (uint)GraphicsLayouts.RastPortFlags;

        var directBacking = new FakeMemory(0x2000);
        var directMemory = new RangeReadFaultMemory(directBacking);
        var directCore = CreateCore(directMemory);
        directMemory.FailReads(flags, sizeof(ushort));

        Assert.Equal(0, directCore.DrawEllipse(rastPort, 3, 3, 1, 1));
        Assert.Equal((byte)0x10, ReadByte(directBacking, plane0 + 4));
        Assert.Equal((byte)0x10, ReadByte(directBacking, plane1 + 4));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        mappedMemory.FailReads(flags, sizeof(ushort));
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 3, [2] = 1, [3] = 1 },
            Cycles = 83
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.DrawEllipse));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(83, state.Cycles);
        Assert.Equal((byte)0x10, ReadByte(mappedBacking, plane0 + 4));
        Assert.Equal((byte)0x10, ReadByte(mappedBacking, plane1 + 4));
        Assert.True(directMemory.FaultedReadCount > 0);
        Assert.True(mappedMemory.FaultedReadCount > 0);
    }

