    [Fact]
    public void ScrollRasterSnapshotsOverlapAndFillsTheVacatedAreaWithBPen()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        Assert.Equal(0, core.SetAPen(0x20, 1));
        Assert.Equal(0, core.RectFill(0x20, 0, 0, 7, 0));
        Assert.Equal(0, core.SetBPen(0x20, 2));

        Assert.Equal(0, core.ScrollRaster(0x20, 1, 0, 0, 0, 7, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 7, 0));

        Assert.Equal(0, core.ScrollRaster(0x20, -1, 0, 0, 0, 7, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 6, 0));

        Assert.Equal(0, core.SetRast(0x20, 1));
        Assert.Equal(0, core.ScrollRasterBF(0x20, 1, 0, 0, 0, 7, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 7, 0));
        // Reversed bounds describe an empty affected rectangle for the void
        // scroll vectors; the raster remains unchanged.
        Assert.Equal(0, core.ScrollRaster(0x20, 1, 0, 3, 0, 2, 0));
        Assert.Equal(0, core.ScrollRasterBF(0x20, 1, 0, 3, 0, 2, 0));
    }

    [Fact]
    public void ScrollRasterWithZeroWriteMaskDoesNotStageAFullSourceRectangle()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        // A source plane that is not mapped is harmless when no destination
        // plane is selected. The large signed-WORD rectangle would otherwise
        // require an impractical source staging walk.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF8));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));

        Assert.Equal(
            0,
            core.ScrollRaster(rastPort, 1, 1, 0, 0, short.MaxValue, short.MaxValue));
    }

    [Fact]
    public void ScrollRasterBfPublishesTheNativeLinePhaseAfterBackfill()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        var phase = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        // ScrollRasterBF temporarily routes its vacated strips through
        // EraseRect/BPen.  The public line state must finish at the native
        // fresh-pattern phase even when the caller entered with a stale
        // preshift.
        Assert.True(memory.TryWriteByte(phase, 4));
        Assert.Equal(0, core.ScrollRasterBF(rastPort, 1, 0, 0, 0, 7, 0));
        Assert.Equal((byte)15, ReadByte(memory, phase));
    }

    [Fact]
    public void ScrollRasterBFRollsBackWhenFinalLinePhasePublicationFails()
    {
        const uint rastPort = 0x20;
        const uint phase = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        // First run the exact operation once to learn how many writes target
        // the public line-phase byte.  The second run rejects only the next
        // write to that address, allowing the rollback publication itself to
        // succeed.  This isolates the final ScrollRasterBF guard from the
        // unrelated planar writes in the move/backfill transaction.
        var baselineBacking = new FakeMemory(0x2000);
        var baselineMemory = new AddressWriteFaultMemory(baselineBacking, phase);
        var baselineCore = CreateCore(baselineMemory);
        Assert.Equal(0, baselineCore.SetRast(rastPort, 3));
        Assert.Equal(0, baselineCore.SetBPen(rastPort, 2));
        Assert.True(baselineBacking.TryWriteByte(phase, 4));
        Assert.Equal(0, baselineCore.ScrollRasterBF(rastPort, 1, 0, 0, 0, 7, 0));
        var phaseWrites = baselineMemory.TargetWriteCount;
        Assert.True(phaseWrites > 0);

        var failingBacking = new FakeMemory(0x2000);
        var failingMemory = new AddressWriteFaultMemory(failingBacking, phase)
        {
            RejectAfterTargetWrites = phaseWrites - 1
        };
        var failingCore = CreateCore(failingMemory);
        Assert.Equal(0, failingCore.SetRast(rastPort, 3));
        Assert.Equal(0, failingCore.SetBPen(rastPort, 2));
        Assert.True(failingBacking.TryWriteByte(phase, 4));

        var result = failingCore.ScrollRasterBF(rastPort, 1, 0, 0, 0, 7, 0);
        Assert.True(
            result == -1,
            $"phaseWrites={phaseWrites}; attempted={failingMemory.TargetWriteCount}; result={result}");
        Assert.Equal((byte)4, ReadByte(failingBacking, phase));
        for (short x = 0; x < 8; x++)
            Assert.Equal(3, failingCore.ReadPixel(rastPort, x, 0));
    }

    [Fact]
    public void RealZeroMaskScrollRestartsLinePhaseButZeroDisplacementDoesNot()
    {
        static void AssertPhase(
            Func<GraphicsLibraryCore, int> movedScroll,
            Func<GraphicsLibraryCore, int> zeroDisplacementScroll,
            GraphicsLibraryCore core,
            FakeMemory memory,
            uint phase)
        {
            Assert.True(memory.TryWriteByte(
                0x20u + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.True(memory.TryWriteByte(phase, 4));

            // A real move still crosses the native SetABPenDrMd/RectFill
            // boundary, so its line pattern restarts even though no plane is
            // selected and no source rectangle may be staged.
            Assert.Equal(0, movedScroll(core));
            Assert.Equal((byte)15, ReadByte(memory, phase));

            Assert.True(memory.TryWriteByte(phase, 4));
            // A true zero-displacement request remains a complete no-op.
            Assert.Equal(0, zeroDisplacementScroll(core));
            Assert.Equal((byte)4, ReadByte(memory, phase));
        }

        var normalMemory = new FakeMemory(0x2000);
        var normalCore = CreateCore(normalMemory);
        AssertPhase(
            core => core.ScrollRaster(0x20, 1, 0, 0, 0, 7, 0),
            core => core.ScrollRaster(0x20, 0, 0, 0, 0, 7, 0),
            normalCore,
            normalMemory,
            0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount);

        var backgroundMemory = new FakeMemory(0x2000);
        var backgroundCore = CreateCore(backgroundMemory);
        AssertPhase(
            core => core.ScrollRasterBF(0x20, 1, 0, 0, 0, 7, 0),
            core => core.ScrollRasterBF(0x20, 0, 0, 0, 0, 7, 0),
            backgroundCore,
            backgroundMemory,
            0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount);
    }

    [Fact]
    public void ScrollRasterLeavesAFullExtentDisplacementUntouchedWhileScrollRasterBFClears()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.SetAPen(0x20, 3));
        Assert.Equal(0, core.RectFill(0x20, 0, 0, 7, 0));

        // The native ScrollRaster move boundary is strict: a displacement
        // equal to the logical width leaves the rectangle exactly as-is.
        Assert.Equal(0, core.ScrollRaster(0x20, 8, 0, 0, 0, 7, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 7, 0));

        // ScrollRasterBF shares the same move boundary but uses the
        // EraseRect/BPen path for the fully vacated rectangle.  BPen is zero
        // in this default RastPort fixture.
        Assert.Equal(0, core.ScrollRasterBF(0x20, 8, 0, 0, 0, 7, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 7, 0));
    }

    [Fact]
    public void ScrollRasterBFClearsEveryVisiblePixelWhenClippedSourceIsEmpty()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(0, core.SetBPen(0x20, 2));

        // The visible part of the logical rectangle is x=0..5, but a
        // displacement of nine pixels leaves no source coordinate inside
        // the logical x=-2..5 range.  ScrollRasterBF must backfill the whole
        // visible rectangle; a one-sided strip formula would clear only its
        // left edge and leave stale pixels behind.
        Assert.Equal(0, core.ScrollRasterBF(0x20, 9, 0, -2, 0, 5, 0));
        for (short x = 0; x <= 5; x++)
            Assert.Equal(2, core.ReadPixel(0x20, x, 0));

        // Pixels outside the requested rectangle remain untouched.
        Assert.Equal(3, core.ReadPixel(0x20, 6, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 7, 0));
    }

