        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.True(backing.TryWriteByte(plane0, 0x55));
        Assert.True(backing.TryWriteByte(plane1, 0xAA));
        memory.FailOnNextByteWrite(4);
        Assert.Equal(-1, core.ScrollRaster(rastPort, 1, 0, 0, 0, 7, 0));
        Assert.Equal((byte)0x55, ReadByte(backing, plane0));
        Assert.Equal((byte)0xAA, ReadByte(backing, plane1));
