    [Fact]
    public void FloodWithoutAreaPatternDoesNotRequireAreaPatternSize()
    {
        const uint rastPort = 0x20;
        const uint areaPatternSizeAddress =
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz;

        var backing = new FakeMemory(0x4000);
        var setup = CreateCore(backing);
        Assert.True(setup.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            0));
        Assert.Equal(0, setup.SetAPen(rastPort, 3));
        Assert.Equal(0, setup.SetDrawMode(rastPort, 1));

        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(areaPatternSizeAddress, sizeof(byte));
        var core = CreateCore(memory);

        Assert.Equal(1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));

        // Exercise the same boundary through the CopperStart register ABI on
        // an independent guest image because Flood mutates its connected
        // region and consumes any attached scratch state.
        var mappedBacking = new FakeMemory(0x4000);
        var mappedSetup = CreateCore(mappedBacking);
        Assert.True(mappedSetup.InitializeRastPort(rastPort));
        Assert.True(mappedBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.True(mappedBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            0));
        Assert.Equal(0, mappedSetup.SetAPen(rastPort, 3));
        Assert.Equal(0, mappedSetup.SetDrawMode(rastPort, 1));

        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        mappedMemory.FailReads(areaPatternSizeAddress, sizeof(byte));
        var mappedCore = CreateCore(mappedMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1u, [1] = 0u, [2] = 0u, [3] = 0xCAFE_BABEu }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(3, mappedCore.ReadPixel(rastPort, 0, 0));
    }

    [Fact]
    public void FloodComplementJam2DoesNotRequireBackgroundPenAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint areaPatternSizeAddress =
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz;
        const uint backgroundPenAddress =
            rastPort + (uint)GraphicsLayouts.RastPortBgPen;

        static void Prepare(GraphicsLibraryCore core, FakeMemory memory, uint rastPort)
        {
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                0x100));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
                0));
            Assert.Equal(0, core.SetAPen(rastPort, 3));
            Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2 | COMPLEMENT
        }

        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(core, backing, rastPort);
        memory.FailReads(backgroundPenAddress, sizeof(byte));
        memory.FailReads(areaPatternSizeAddress, sizeof(byte));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        Assert.Equal(1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));

        var mappedBacking = new FakeMemory(0x4000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(mappedCore, mappedBacking, rastPort);
        mappedMemory.FailReads(backgroundPenAddress, sizeof(byte));
        mappedMemory.FailReads(areaPatternSizeAddress, sizeof(byte));
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            // CopperStart's Flood gateway receives X in D0, Y in D1, and
            // mode in D2.  Keep the mapped invocation equivalent to the
            // direct Flood(rp, mode: 1, x: 0, y: 0) call above.
            D = { [0] = 0u, [1] = 0u, [2] = 1u, [3] = 0xCAFE_BABEu },
            Cycles = 53
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(53, state.Cycles);
        Assert.Equal(3, mappedCore.ReadPixel(rastPort, 0, 0));
    }

    [Fact]
    public void FloodSeedColorModeDoesNotRequireOutlinePenStorage()
    {
        const uint rastPort = 0x20;
        const uint outlinePenAddress =
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen;

        var backing = new FakeMemory(0x4000);
        var setup = CreateCore(backing);
        Assert.True(setup.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.Equal(0, setup.SetAPen(rastPort, 3));
        Assert.Equal(0, setup.SetDrawMode(rastPort, 1));

        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(outlinePenAddress, sizeof(byte));
        var core = CreateCore(memory);

        // Mode 1 compares against the seed colour, so the unrelated
        // OutlinePen field must not be part of the portable claim envelope.
        Assert.Equal(1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));

        var mappedBacking = new FakeMemory(0x4000);
        var mappedSetup = CreateCore(mappedBacking);
        Assert.True(mappedSetup.InitializeRastPort(rastPort));
        Assert.True(mappedBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            0x100));
        Assert.Equal(0, mappedSetup.SetAPen(rastPort, 3));
        Assert.Equal(0, mappedSetup.SetDrawMode(rastPort, 1));

        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        mappedMemory.FailReads(outlinePenAddress, sizeof(byte));
        var adapter = new CopperStartGraphicsRegisterAdapter(CreateCore(mappedMemory));
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            // Flood's mapped ABI receives X in D0, Y in D1, and mode in D2.
            D = { [0] = 0u, [1] = 0u, [2] = 1u }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(3, GraphicsRasterOperations.ReadPixel(mappedMemory, rastPort, 0, 0));
    }

    [Fact]
    public void FloodDeclinesPrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;

        static void Prepare(GraphicsLibraryCore core, FakeMemory backing, uint rastPort)
        {
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                1));
            Assert.Equal(0, core.SetDrawMode(rastPort, 1));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
        }

        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(core, backing, rastPort);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);

        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            sizeof(uint));

        Assert.Equal(-1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(0, memory.FaultedReadCount);

        var mappedBacking = new FakeMemory(0x4000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(mappedCore, mappedBacking, rastPort);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);

        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            sizeof(uint));

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0u, [1] = 0u, [2] = 1u, [3] = 0xCAFE_BABEu },
            Cycles = 97
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(97, state.Cycles);
        Assert.Equal(0, mappedMemory.FaultedReadCount);
    }

    [Fact]
    public void FloodContinuesThroughPatternSuppressedPixels()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaPattern = 0x800;

        // JAM2 uses the one-bit AreaPt pattern as a write stencil.  The
        // middle pixel is suppressed, but it still belongs to the connected
        // seed-colour region and must not block traversal to the third pixel.
        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            areaPattern));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            0));
        Assert.True(memory.TryWriteWord(areaPattern, 0xA000));

        Assert.Equal(1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 1, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 2, 0));
    }

    [Fact]
    public void FloodPreflightsTheCompleteDestinationBeforePublishingSeedWrites()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x1FFE;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane));
        Assert.True(memory.TryWriteByte(plane, 0x5A));

        // The seed row is readable and would be written first, but the second
        // row falls beyond guest memory.  Flood must fail before changing the
        // seed row or partially traversing the connected region.
        Assert.Equal(-1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));
    }

    [Fact]
    public void FloodRejectsAggregateCellWorkBeforeDestinationPlaneProbe()
    {
        var backing = new FakeMemory(0x1000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        var planePointer = bitMap + (uint)GraphicsLayouts.BitMapPlanes;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        // 131072 * 8192 is below Int32.MaxValue, but three complete Flood
        // passes exceed the portable host work contract.  No plane storage is
        // mapped: the aggregate guard must decline before probing it.
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            16384));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            8192));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        var memory = new AddressReadTrackingMemory(backing, planePointer);
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay());

        Assert.Equal(-1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void HostRegisterAdapterLeavesAggregateFloodWorkForNativeOwnership()
    {
        var memory = new FakeMemory(0x1000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            16384));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            8192));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu, [1] = 0u, [2] = 1u },
            Cycles = 41
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(41, state.Cycles);
    }

    [Fact]
    public void FloodRejectsAnExplicitlyAttachedTemporaryRasterThatIsTooSmall()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tmpRas = 0x300;
        const uint tmpBuffer = 0x380;
        const uint plane0 = 0x400;

        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortTmpRas, tmpRas));
        Assert.True(memory.TryWriteLong(tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr, tmpBuffer));
        Assert.True(memory.TryWriteLong(tmpRas + (uint)GraphicsLayouts.TmpRasByteCount, 1));
        Assert.Equal(-1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal((byte)0, ReadByte(memory, plane0));
    }

    [Fact]
    public void FloodRejectsOddTemporaryRasterDescriptorBeforeMutatingTheBitmap()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint oddTmpRas = 0x301;
        const uint tmpBuffer = 0x380;
        const uint plane0 = 0x400;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortTmpRas,
            oddTmpRas));
        Assert.True(memory.TryWriteLong(
            oddTmpRas + (uint)GraphicsLayouts.TmpRasRasPtr,
            tmpBuffer));
        Assert.True(memory.TryWriteLong(
            oddTmpRas + (uint)GraphicsLayouts.TmpRasByteCount,
            16));

        // TmpRas is a guest longword structure.  The host memory model can
        // expose it at an odd address, but native 68k must leave this malformed
        // descriptor to the fallback path before Flood writes the bitmap.
        Assert.Equal(-1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal((byte)0, ReadByte(memory, plane0));
    }

    [Fact]
    public void HostRegisterAdapterLeavesAreaEndUnclaimedForAnOddTemporaryRasterDescriptor()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint areaInfo = 0x700;
        const uint areaBuffer = 0x900;
        const uint oddTmpRas = 0xA01;
        const uint tmpBuffer = 0xB00;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaInfo,
            areaInfo));
        Assert.True(core.InitializeArea(areaInfo, areaBuffer, 8));
        Assert.Equal(0, core.AreaMove(rastPort, 1, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 2, 1));
        Assert.Equal(0, core.AreaDraw(rastPort, 2, 2));
        Assert.Equal(0, core.AreaDraw(rastPort, 1, 2));

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortTmpRas,
            oddTmpRas));
        Assert.True(memory.TryWriteLong(
            oddTmpRas + (uint)GraphicsLayouts.TmpRasRasPtr,
            tmpBuffer));
        Assert.True(memory.TryWriteLong(
            oddTmpRas + (uint)GraphicsLayouts.TmpRasByteCount,
            16));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu }
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AreaEnd));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(0, core.ReadPixel(rastPort, 1, 1));
        Assert.NotEqual((ushort)0, ReadWord(
            memory,
            areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
    }

    [Fact]
    public void FloodUsesAnAttachedTemporaryRasterAsItsGuestVisitedBitmap()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tmpRas = 0x300;
        const uint tmpBuffer = 0x380;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortTmpRas,
            tmpRas));
        Assert.True(memory.TryWriteLong(
            tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr,
            tmpBuffer));
        // CreateCore's bitmap is 2 bytes per row and 8 rows, so the attached
        // descriptor supplies exactly one visited bit per destination pixel.
        Assert.True(memory.TryWriteLong(
            tmpRas + (uint)GraphicsLayouts.TmpRasByteCount,
            16));
        for (var offset = 0u; offset < 16; offset++)
            Assert.True(memory.TryWriteByte(tmpBuffer + offset, 0xA5));

        Assert.Equal(1, core.Flood(rastPort, 1, 0, 0));

        // The all-zero source bitmap is one connected region.  Flood must
        // clear and then mark every guest scratch bit while traversing it,
        // rather than hiding the visit state in a host-only bool array.
        for (var offset = 0u; offset < 16; offset++)
            Assert.Equal((byte)0xFF, ReadByte(memory, tmpBuffer + offset));
    }

    [Fact]
    public void FloodAllocatesAndReleasesGuestTemporaryRasterWhenTmpRasIsUnset()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = CreateCore(memory, allocator: allocator);
        const uint rastPort = 0x20;

        // CreateCore leaves RastPort.TmpRas unset. The portable core must use
        // the allocator-backed guest scratch path rather than a host bool[].
        Assert.Equal(0u, ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortTmpRas));
        Assert.Equal(1, core.Flood(rastPort, 1, 0, 0));
        Assert.Equal(16u, allocator.LastAllocatedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastAllocatedClass);
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(0x1000u, allocator.LastFreedAddress);
        Assert.Equal(16u, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastFreedClass);
        Assert.Equal(0u, ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortTmpRas));
    }

    [Fact]
    public void FloodReleasesAnUnusableGuestScratchAllocationBeforeDeclining()
    {
        // The allocator returns 0x1000, but this deliberately small guest
        // address space cannot map that scratch span. Flood must roll the
        // allocation back instead of falling through to a host work buffer.
        var memory = new FakeMemory(0x800);
        var allocator = new FakeAllocator();
        var core = CreateCore(memory, allocator: allocator);

        Assert.Equal(-1, core.Flood(0x20, 1, 0, 0));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(0x1000u, allocator.LastFreedAddress);
        Assert.Equal(16u, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastFreedClass);
    }

    [Fact]
    public void RegionsPreserveGuestLinkedLayoutAcrossRectangleAndRegionBooleanOperations()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint rectangle = 0x300;
        const uint rectangle2 = 0x320;

        var region = core.NewRegion();
        Assert.NotEqual(0u, region);
        Assert.Equal(0u, ReadLong(memory, region + (uint)GraphicsLayouts.RegionRectangle));
        WriteRectangle(memory, rectangle, 1, 1, 3, 3);
        Assert.True(core.OrRectRegion(region, rectangle));
        Assert.True(RegionContains(memory, region, 1, 1));
        Assert.True(RegionContains(memory, region, 3, 3));
        Assert.False(RegionContains(memory, region, 0, 0));
        Assert.Equal((short)1, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal((short)3, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds + 6));

        WriteRectangle(memory, rectangle2, 3, 2, 5, 4);
        Assert.True(core.OrRectRegion(region, rectangle2));
        Assert.True(RegionContains(memory, region, 5, 4));
        Assert.True(RegionContains(memory, region, 2, 2));

        WriteRectangle(memory, rectangle2, 2, 2, 4, 3);
        Assert.True(core.ClearRectRegion(region, rectangle2));
        Assert.True(RegionContains(memory, region, 1, 1));
        Assert.False(RegionContains(memory, region, 3, 2));
        Assert.True(RegionContains(memory, region, 5, 4));

        WriteRectangle(memory, rectangle2, 1, 1, 2, 1);
        Assert.True(core.XorRectRegion(region, rectangle2));
        Assert.False(RegionContains(memory, region, 1, 1));
        Assert.False(RegionContains(memory, region, 2, 1));

        WriteRectangle(memory, rectangle2, 0, 0, 4, 4);
        Assert.True(core.AndRectRegion(region, rectangle2));
        Assert.False(RegionContains(memory, region, 5, 4));

        var source = core.NewRegion();
        var destination = core.NewRegion();
        WriteRectangle(memory, rectangle, 0, 0, 2, 2);
        WriteRectangle(memory, rectangle2, 1, 1, 3, 3);
        Assert.True(core.OrRectRegion(source, rectangle));
        Assert.True(core.OrRectRegion(destination, rectangle2));
        Assert.True(core.AndRegionRegion(source, destination));
        Assert.True(RegionContains(memory, destination, 1, 1));
        Assert.False(RegionContains(memory, destination, 0, 0));
        Assert.False(RegionContains(memory, destination, 3, 3));

        Assert.True(core.ClearRegion(destination));
        Assert.Equal(0u, ReadLong(memory, destination + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(GraphicsRasterOperations.Success, core.DisposeRegion(region));
        Assert.Equal(GraphicsRasterOperations.Success, core.DisposeRegion(source));
        Assert.Equal(GraphicsRasterOperations.Success, core.DisposeRegion(destination));
        Assert.True(allocator.Freed.Count >= 6);
    }

    [Fact]
    public void OrRectRegionCanonicalizesAnLShapedUnionIntoThreeVerticallyBandedNodes()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint firstRectangle = 0x300;
        const uint secondRectangle = 0x320;

        var region = core.NewRegion();
        WriteRectangle(memory, firstRectangle, 8, 18, 19, 30);
        WriteRectangle(memory, secondRectangle, 15, 25, 21, 32);
        Assert.True(core.OrRectRegion(region, firstRectangle));
        Assert.True(core.OrRectRegion(region, secondRectangle));

        Assert.Equal((short)8, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RectangleMinX));
        Assert.Equal((short)18, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RectangleMinY));
        Assert.Equal((short)21, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RectangleMaxX));
        Assert.Equal((short)32, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RectangleMaxY));

        var firstNode = ReadLong(memory, region + (uint)GraphicsLayouts.RegionRectangle);
        var secondNode = ReadLong(memory, firstNode + (uint)GraphicsLayouts.RegionRectangleNext);
        var thirdNode = ReadLong(memory, secondNode + (uint)GraphicsLayouts.RegionRectangleNext);
        Assert.NotEqual(0u, firstNode);
        Assert.NotEqual(0u, secondNode);
        Assert.NotEqual(0u, thirdNode);
        Assert.Equal(region + (uint)GraphicsLayouts.RegionRectangle,
            ReadLong(memory, firstNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(firstNode,
            ReadLong(memory, secondNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(secondNode,
            ReadLong(memory, thirdNode + (uint)GraphicsLayouts.RegionRectanglePrevious));
        Assert.Equal(0u, ReadLong(memory, thirdNode + (uint)GraphicsLayouts.RegionRectangleNext));

        static void AssertRelativeBounds(
            FakeMemory target,
            uint node,
            short minX,
            short minY,
            short maxX,
            short maxY)
        {
            var bounds = node + (uint)GraphicsLayouts.RegionRectangleBounds;
            Assert.Equal(minX, ReadSignedWord(target, bounds + (uint)GraphicsLayouts.RectangleMinX));
            Assert.Equal(minY, ReadSignedWord(target, bounds + (uint)GraphicsLayouts.RectangleMinY));
            Assert.Equal(maxX, ReadSignedWord(target, bounds + (uint)GraphicsLayouts.RectangleMaxX));
            Assert.Equal(maxY, ReadSignedWord(target, bounds + (uint)GraphicsLayouts.RectangleMaxY));
        }

        AssertRelativeBounds(memory, firstNode, 0, 0, 11, 6);
        AssertRelativeBounds(memory, secondNode, 0, 7, 13, 12);
        AssertRelativeBounds(memory, thirdNode, 7, 13, 13, 14);
    }

    [Fact]
    public void NewRegionReleasesAProvisionalHeaderWhenTheAllocatorDeclines()
    {
        var memory = new FakeMemory(0x1000);
        var allocator = new DecliningRegionAllocator(declineHeader: true);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        // A failed public allocation may still leave an address in the
        // allocator out slot.  Region creation must release that provisional
        // envelope instead of leaking it before returning the native failure.
        Assert.Equal(0u, core.NewRegion());
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x1000 &&
                          allocation.Bytes == (uint)GraphicsLayouts.RegionSize &&
                          allocation.MemoryClass == GraphicsMemoryClass.Public);
    }

    [Fact]
    public void NewRegionRestoresExistingHeaderWhenPublicationFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new FixedAddressAllocator(0x200);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        for (var offset = 0; offset < GraphicsLayouts.RegionSize; offset++)
        {
            Assert.True(backing.TryWriteByte(
                0x200u + (uint)offset,
                (byte)(0x50 + offset)));
        }

        // The third header byte fails after the first two have published.
        // Region creation must restore the caller-visible envelope before
        // releasing the provisional allocation.
        memory.FailOnNextByteWrite(3);
        Assert.Equal(0u, core.NewRegion());
        Assert.Equal(1, allocator.FreeCount);
        for (var offset = 0; offset < GraphicsLayouts.RegionSize; offset++)
        {
            Assert.Equal(
                (byte)(0x50 + offset),
                ReadByte(backing, 0x200u + (uint)offset));
        }
    }

    [Fact]
    public void RegionBooleanPublicationReleasesAProvisionalRectangleNodeWhenTheAllocatorDeclines()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new DecliningRegionAllocator(declineFirstNode: true);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint rectangle = 0x300;

        var region = core.NewRegion();
        Assert.NotEqual(0u, region);
        WriteRectangle(memory, rectangle, 1, 1, 3, 3);

        Assert.False(core.OrRectRegion(region, rectangle));
        Assert.Equal(0u, ReadLong(memory, region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == 0x2000 &&
                          allocation.Bytes == (uint)GraphicsLayouts.RegionRectangleSize &&
                          allocation.MemoryClass == GraphicsMemoryClass.Public);
        Assert.Equal(GraphicsRegionOperations.Success, core.DisposeRegion(region));
    }

    [Fact]
    public void RegionsRejectOddNativeHeaderAndRectangleAllocationsBeforePublication()
    {
        var headerMemory = new FakeMemory(0x4000);
        var oddHeaderAllocator = new SequenceAddressAllocator(0x1001);
        var oddHeaderCore = new GraphicsLibraryCore(
            headerMemory,
            oddHeaderAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, oddHeaderCore.NewRegion());
        Assert.Equal(1, oddHeaderAllocator.FreeCount);

        var nodeMemory = new FakeMemory(0x4000);
        var oddNodeAllocator = new SequenceAddressAllocator(0x1000, 0x2001);
        var oddNodeCore = new GraphicsLibraryCore(
            nodeMemory,
            oddNodeAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var region = oddNodeCore.NewRegion();
        Assert.NotEqual(0u, region);
        const uint rectangle = 0x300;
        WriteRectangle(nodeMemory, rectangle, 1, 1, 3, 3);

        Assert.False(oddNodeCore.OrRectRegion(region, rectangle));
        Assert.Equal(0u, ReadLong(
            nodeMemory,
            region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(1, oddNodeAllocator.FreeCount);
        Assert.Equal(GraphicsRegionOperations.Success, oddNodeCore.DisposeRegion(region));
        Assert.Equal(2, oddNodeAllocator.FreeCount);

        var rectangleMemory = new FakeMemory(0x4000);
        var rectangleAllocator = new SequenceAddressAllocator(0x1000);
        var rectangleCore = new GraphicsLibraryCore(
            rectangleMemory,
            rectangleAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var rectangleRegion = rectangleCore.NewRegion();
        Assert.NotEqual(0u, rectangleRegion);
        const uint oddRectangle = 0x301;
        WriteRectangle(rectangleMemory, oddRectangle, 1, 1, 3, 3);
        Assert.False(rectangleCore.OrRectRegion(rectangleRegion, oddRectangle));
        Assert.Equal(0u, ReadLong(
            rectangleMemory,
            rectangleRegion + (uint)GraphicsLayouts.RegionRectangle));
        Assert.Equal(GraphicsRegionOperations.Success, rectangleCore.DisposeRegion(rectangleRegion));
        Assert.Equal(1, rectangleAllocator.FreeCount);
    }

    [Fact]
    public void RegionRectangleStoresBoundsRelativeToNegativeRegionOrigin()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint rectangle = 0x300;

        var region = core.NewRegion();
        WriteRectangle(memory, rectangle, -10, -20, -3, -5);
        Assert.True(core.OrRectRegion(region, rectangle));

        Assert.Equal((short)-10, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds));
        Assert.Equal((short)-20, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds + 2u));
        Assert.Equal((short)-3, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds + 4u));
        Assert.Equal((short)-5, ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds + 6u));

        var node = ReadLong(memory, region + (uint)GraphicsLayouts.RegionRectangle);
        Assert.NotEqual(0u, node);
        Assert.Equal((short)0, ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds));
        Assert.Equal((short)0, ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds + 2u));
        Assert.Equal((short)7, ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
        Assert.Equal((short)15, ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds + 6u));
        Assert.True(RegionContains(memory, region, -10, -20));
        Assert.True(RegionContains(memory, region, -3, -5));
        Assert.False(RegionContains(memory, region, -2, -5));
    }

    [Fact]
    public void AndRectRegionClipsInPlaceWhenAllocatorCannotGrow()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator { FailAfterAllocations = 2 };
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint regionRectangle = 0x300;
        const uint clipRectangle = 0x320;

        var region = core.NewRegion();
        WriteRectangle(memory, regionRectangle, 0, 0, 10, 10);
        Assert.True(core.OrRectRegion(region, regionRectangle));

        // The region header and its one node consume both permitted
        // allocations.  AndRectRegion must still succeed by clipping the
        // existing node rather than allocating a replacement list.
        WriteRectangle(memory, clipRectangle, 2, 3, 5, 6);
        Assert.True(core.AndRectRegion(region, clipRectangle));
        Assert.True(RegionContains(memory, region, 2, 3));
        Assert.True(RegionContains(memory, region, 5, 6));
        Assert.False(RegionContains(memory, region, 1, 3));
    }

    [Fact]
    public void RegionBooleanVectorsHandleEvilRectanglesPerNativeContract()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint sourceRectangle = 0x300;
        const uint evilRectangle = 0x320;

        WriteRectangle(memory, sourceRectangle, 1, 2, 6, 7);
        WriteRectangle(memory, evilRectangle, 8, 9, 7, 8);

        var orRegion = core.NewRegion();
        Assert.True(core.OrRectRegion(orRegion, sourceRectangle));
        Assert.True(core.OrRectRegion(orRegion, evilRectangle));
        Assert.True(RegionContains(memory, orRegion, 1, 2));
        Assert.False(RegionContains(memory, orRegion, 7, 8));

        var xorRegion = core.NewRegion();
        Assert.True(core.OrRectRegion(xorRegion, sourceRectangle));
        Assert.True(core.XorRectRegion(xorRegion, evilRectangle));
        Assert.True(RegionContains(memory, xorRegion, 1, 2));

        var clearRegion = core.NewRegion();
        Assert.True(core.OrRectRegion(clearRegion, sourceRectangle));
        Assert.True(core.ClearRectRegion(clearRegion, evilRectangle));
        Assert.True(RegionContains(memory, clearRegion, 6, 7));

        var andRegion = core.NewRegion();
        Assert.True(core.OrRectRegion(andRegion, sourceRectangle));
        Assert.True(core.AndRectRegion(andRegion, evilRectangle));
        Assert.Equal(0u, ReadLong(memory, andRegion + (uint)GraphicsLayouts.RegionRectangle));
    }

    [Fact]
    public void DisposeRegionRequiresOwnershipFromTheSameGraphicsLibraryAndRejectsDoubleDispose()
    {
        var memory = new FakeMemory(0x10000);
        var ownerAllocator = new BitmapAllocator();
        var foreignAllocator = new BitmapAllocator();
        var owner = new GraphicsLibraryCore(memory, ownerAllocator, new FakeBlitter(), new FakeDisplay());
        var foreign = new GraphicsLibraryCore(memory, foreignAllocator, new FakeBlitter(), new FakeDisplay());

        var region = owner.NewRegion();
        Assert.NotEqual(0u, region);

        Assert.Equal(GraphicsRegionOperations.Failure, foreign.DisposeRegion(region));
        Assert.Empty(foreignAllocator.Freed);

        Assert.Equal(GraphicsRegionOperations.Success, owner.DisposeRegion(region));
        Assert.Equal(GraphicsRegionOperations.Failure, owner.DisposeRegion(region));
        Assert.Single(ownerAllocator.Freed);
    }

    [Fact]
    public void ClearRegionRestoresTheGuestHeaderWhenThePointerWriteFails()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        const uint rectangle = 0x300;

        var region = core.NewRegion();
        WriteRectangle(backing, rectangle, 1, 1, 3, 3);
        Assert.True(core.OrRectRegion(region, rectangle));

        var original = new byte[GraphicsLayouts.RegionSize];
        for (var offset = 0; offset < original.Length; offset++)
            original[offset] = ReadByte(backing, region + (uint)offset);

        // Clearing writes the empty bounds first (eight bytes), then the
        // RegionRectangle pointer.  Fail on that pointer byte and verify the
        // prior linked region remains intact after rollback.
        memory.FailOnNextByteWrite(9);
        Assert.False(core.ClearRegion(region));
        for (var offset = 0; offset < original.Length; offset++)
            Assert.Equal(original[offset], ReadByte(backing, region + (uint)offset));
        Assert.True(RegionContains(backing, region, 1, 1));
    }

    [Fact]
    public void ChangeVPBitMapRestoresTheOldRasInfoPointerWhenTheLongWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        const uint viewPort = 0x200;
        const uint rasInfo = 0x240;
        const uint currentBitMap = 0x300;
        const uint nextBitMap = 0x380;

        WritePlanarBitmap(backing, currentBitMap, 0x500, 0, rows: 1, depth: 1);
        WritePlanarBitmap(backing, nextBitMap, 0x600, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(backing.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(backing.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap));
        Assert.True(backing.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
            0));
        Assert.True(backing.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
            0));

        // A long write publishes two bytes before failing.  The portable
        // transaction must restore the old bitmap association.
        memory.FailOnNextByteWrite(3);
        Assert.False(core.TryChangeViewPortBitMap(
            viewPort,
            nextBitMap,
            0,
            0,
            out _));
        Assert.Equal(
            currentBitMap,
            ReadLong(backing, rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void ChangeVPBitMapRestoresTheOldRasInfoPointerAfterPartialLongPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialLongWriteMemory(backing);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        const uint viewPort = 0x200;
        const uint rasInfo = 0x240;
        const uint currentBitMap = 0x300;
        const uint nextBitMap = 0x380;

        WritePlanarBitmap(backing, currentBitMap, 0x500, 0, rows: 1, depth: 1);
        WritePlanarBitmap(backing, nextBitMap, 0x600, 0, rows: 1, depth: 1);
        Assert.True(backing.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(backing.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        var bitmapLink = rasInfo + (uint)GraphicsLayouts.RasInfoBitMap;
        Assert.True(backing.TryWriteLong(bitmapLink, currentBitMap));
        Assert.True(backing.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
            0));
        Assert.True(backing.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
            0));

        memory.PartialLongAddress = bitmapLink;
        Assert.False(core.TryChangeViewPortBitMap(
            viewPort,
            nextBitMap,
            0,
            0,
            out _));
        Assert.Equal(currentBitMap, ReadLong(backing, bitmapLink));

        memory.PartialLongAddress = null;
        Assert.True(core.TryChangeViewPortBitMap(
            viewPort,
            nextBitMap,
            0,
            0,
            out _));
        Assert.Equal(nextBitMap, ReadLong(backing, bitmapLink));
    }

    [Fact]
    public void SetABPenDrMdRestoresEarlierFieldsWhenPatternRestartFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 3));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4));
        for (var plane = 0; plane < 8; plane++)
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                (byte)(0x80 + plane)));

        // Fg, Bg, and DrawMode publish first; fail the derived minterm
        // publication and require every guest field to roll back.
        memory.FailOnNextByteWrite(4);
        Assert.Equal(-1, core.SetABPenDrMd(rastPort, 8, 9, 10));
        Assert.Equal((byte)1, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)2, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)3, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        Assert.Equal((byte)4, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal(
                (byte)(0x80 + plane),
                ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
    }

    [Fact]
    public void SetABPenDrMdRestoresMintermsWhenTheLatePatternRestartFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 3));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 4));
        for (var plane = 0; plane < 8; plane++)
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                (byte)(0x90 + plane)));

        // Three pen/mode bytes and eight minterms publish before the line
        // phase reset.  Fail that final write and require a full rollback.
        memory.FailOnNextByteWrite(12);
        Assert.Equal(-1, core.SetABPenDrMd(rastPort, 8, 9, 10));
        Assert.Equal((byte)4, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal(
                (byte)(0x90 + plane),
                ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
    }

    [Fact]
    public void SetABPenDrMdRestoresFlagsAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort oldFlags = 0x5200;

        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            2));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            3));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            4));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));
        for (var plane = 0; plane < 8; plane++)
        {
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                (byte)(0xB0 + plane)));
        }

        var flagsAddress = rastPort + (uint)GraphicsLayouts.RastPortFlags;
        memory.PartialWordAddress = flagsAddress;
        Assert.Equal(-1, core.SetABPenDrMd(rastPort, 8, 9, 10));

        Assert.Equal((byte)1, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)2, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)3, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        Assert.Equal((byte)4, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(oldFlags, ReadWord(
            backing,
            flagsAddress));
        for (var plane = 0; plane < 8; plane++)
        {
            Assert.Equal(
                (byte)(0xB0 + plane),
                ReadByte(
                    backing,
                    rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
        }

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.SetABPenDrMd(rastPort, 8, 9, 10));
    }

    [Fact]
    public void IndividualPenAndModeSettersPreflightTheirCompleteStateEnvelope()
    {
        static void Seed(FakeMemory memory, uint rastPort)
        {
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                1));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortBgPen,
                2));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
                3));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));
            Assert.True(memory.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                0x8200));
            for (var plane = 0; plane < 8; plane++)
            {
                Assert.True(memory.TryWriteByte(
                    rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                    (byte)(0xA0 + plane)));
            }
        }

        static byte[] Snapshot(FakeMemory memory, uint rastPort)
        {
            var result = new byte[GraphicsLayouts.RastPortMinterms + 8];
            for (var offset = 0; offset < result.Length; offset++)
                result[offset] = ReadByte(memory, rastPort + (uint)offset);

            return result;
        }

        const uint rastPort = 0x20;

        // A mapped RastPort whose Flags word is outside the guest envelope
        // must fail before publishing the requested pen.  This exercises the
        // direct portable contract independently of the write-fault path.
        var truncated = new FakeMemory(GraphicsLayouts.RastPortFlags + 1);
        var truncatedCore = CreateCore(truncated);
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            truncatedCore.SetAPen(rastPort, 7));

        // A provider can fault a byte write after the complete envelope was
        // successfully probed.  The transaction must still restore every
        // derived field, and the register gateway must leave the request
        // available to the native/provider owner.
        var directBacking = new FakeMemory(0x1000);
        Seed(directBacking, rastPort);
        var directMemory = new FailingByteWriteMemory(directBacking);
        var directCore = CreateCore(directMemory);
        var directBefore = Snapshot(directBacking, rastPort);
        directMemory.FailOnNextByteWrite(12); // flags word, after value/minterms/phase
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            directCore.SetAPen(rastPort, 7));
        Assert.Equal(directBefore, Snapshot(directBacking, rastPort));

        var mappedBacking = new FakeMemory(0x1000);
        Seed(mappedBacking, rastPort);
        var mappedMemory = new FailingByteWriteMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        var mappedBefore = Snapshot(mappedBacking, rastPort);
        mappedMemory.FailOnNextByteWrite(12);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 7 }
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetAPen));
        Assert.Equal(7u, state.D[0]);
        Assert.Equal(mappedBefore, Snapshot(mappedBacking, rastPort));
    }

    [Fact]
    public void RastPortSettersDoNotReadPrivateMintermCacheAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const ushort otherFlags = 0x8200;
        var noPens = (ushort)GraphicsLayouts.RastPortNoPens;

        static void Seed(FakeMemory memory, uint address, ushort flags)
        {
            Assert.True(memory.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortFgPen,
                1));
            Assert.True(memory.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortBgPen,
                2));
            Assert.True(memory.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortDrawMode,
                1));
            Assert.True(memory.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));
            Assert.True(memory.TryWriteWord(
                address + (uint)GraphicsLayouts.RastPortFlags,
                flags));
            for (var plane = 0; plane < 8; plane++)
                Assert.True(memory.TryWriteByte(
                    address + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                    (byte)(0xC0 + plane)));
        }

        static byte ExpectedMinterm(byte foreground, byte background, byte drawMode, int plane)
        {
            if ((drawMode & 2) != 0)
                return (byte)((drawMode & 4) != 0 ? 0x6A : 0x9A);

            var minA = ((foreground >> plane) & 1) * 3;
            var minB = (drawMode & 1) != 0
                ? ((background >> plane) & 1) * 3
                : 2;
            var selector = (drawMode & 4) != 0
                ? (minB << 2) | minA
                : (minA << 2) | minB;
            return (byte)((selector << 4) | 0x0A);
        }

        static void AssertPublished(
            FakeMemory memory,
            uint address,
            byte foreground,
            byte background,
            byte drawMode,
            ushort expectedFlags)
        {
            Assert.Equal(
                foreground,
                ReadByte(memory, address + (uint)GraphicsLayouts.RastPortFgPen));
            Assert.Equal(
                background,
                ReadByte(memory, address + (uint)GraphicsLayouts.RastPortBgPen));
            Assert.Equal(
                drawMode,
                ReadByte(memory, address + (uint)GraphicsLayouts.RastPortDrawMode));
            Assert.Equal(
                (byte)15,
                ReadByte(memory, address + (uint)GraphicsLayouts.RastPortLinePatternCount));
            Assert.Equal(
                expectedFlags,
                ReadWord(memory, address + (uint)GraphicsLayouts.RastPortFlags));
            for (var plane = 0; plane < 8; plane++)
                Assert.Equal(
                    ExpectedMinterm(foreground, background, drawMode, plane),
                    ReadByte(memory, address + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
        }

        void RunDirect(
            Func<GraphicsLibraryCore, int> invoke,
            byte foreground,
            byte background,
            byte drawMode)
        {
            var backing = new FakeMemory(0x1000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, rastPort, (ushort)(otherFlags | noPens));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms,
                8);

            Assert.Equal(0, invoke(core));
            AssertPublished(backing, rastPort, foreground, background, drawMode, otherFlags);
        }

        void RunMapped(
            GraphicsLvo vector,
            Action<M68kCpuState> configure,
            byte foreground,
            byte background,
            byte drawMode)
        {
            var backing = new FakeMemory(0x1000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, rastPort, (ushort)(otherFlags | noPens));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms,
                8);

            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xDEAD_BEEFu },
                Cycles = 97
            };
            configure(state);

            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            Assert.True(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(97, state.Cycles);
            AssertPublished(backing, rastPort, foreground, background, drawMode, otherFlags);
        }

        RunDirect(core => core.SetAPen(rastPort, 7), 7, 2, 1);
        RunMapped(
            GraphicsLvo.SetAPen,
            state => state.D[0] = 7,
            7,
            2,
            1);

        RunDirect(core => core.SetBPen(rastPort, 6), 1, 6, 1);
        RunMapped(
            GraphicsLvo.SetBPen,
            state => state.D[0] = 6,
            1,
            6,
            1);

        RunDirect(core => core.SetDrawMode(rastPort, 4), 1, 2, 4);
        RunMapped(
            GraphicsLvo.SetDrMd,
            state => state.D[0] = 4,
            1,
            2,
            4);

        RunDirect(core => core.SetABPenDrMd(rastPort, 8, 9, 1), 8, 9, 1);
        RunMapped(
            GraphicsLvo.SetABPenDrMd,
            state =>
            {
                state.A[0] = rastPort;
                state.D[0] = 8;
                state.D[1] = 9;
                state.D[2] = 1;
            },
            8,
            9,
            1);
    }

    [Fact]
    public void ClearAndScrollPathsReconstructUnreadableMintermRollbackAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint minterms = rastPort + (uint)GraphicsLayouts.RastPortMinterms;

        static void Seed(FakeMemory backing, uint address)
        {
            for (var plane = 0; plane < 8; plane++)
                Assert.True(backing.TryWriteByte(
                    address + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                    (byte)(0xD0 + plane)));
            Assert.True(backing.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortBgPen,
                2));
            Assert.True(backing.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, rastPort);
            memory.FailReads(minterms, 8);

            Assert.Equal(0, core.EraseRect(rastPort, 0, 0, 1, 0));
            Assert.Equal(0, core.ScrollRaster(rastPort, 1, 0, 0, 0, 7, 0));
            Assert.Equal(0, core.ScrollRasterBF(rastPort, -1, 0, 0, 0, 7, 0));
            Assert.True(memory.FaultedReadCount > 0);
            Assert.Equal((byte)15, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, rastPort);
            memory.FailReads(minterms, 8);
            var adapter = new CopperStartGraphicsRegisterAdapter(core);

            var erase = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0, [1] = 0, [2] = 1, [3] = 0 },
                Cycles = 71
            };
            Assert.True(adapter.TryInvoke(erase, (int)GraphicsLvo.EraseRect));
            Assert.Equal(71, erase.Cycles);

            var scroll = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 7, [5] = 0 },
                Cycles = 73
            };
            Assert.True(adapter.TryInvoke(scroll, (int)GraphicsLvo.ScrollRaster));
            Assert.Equal(73, scroll.Cycles);

            var scrollBf = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = unchecked((uint)-1), [1] = 0, [2] = 0, [3] = 0, [4] = 7, [5] = 0 },
                Cycles = 79
            };
            Assert.True(adapter.TryInvoke(scrollBf, (int)GraphicsLvo.ScrollRasterBF));
            Assert.Equal(79, scrollBf.Cycles);
            Assert.True(memory.FaultedReadCount > 0);
            Assert.Equal((byte)15, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        }
    }

    [Fact]
    public void PenAndModeSettersClearPrivateNoPensFlagAndPreserveOtherFlags()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort otherFlags = 0x8200;
        var noPens = (ushort)GraphicsLayouts.RastPortNoPens;

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(otherFlags | noPens)));
        Assert.Equal(0, core.SetAPen(rastPort, 5));
        Assert.Equal(
            otherFlags,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(otherFlags | noPens)));
        Assert.Equal(0, core.SetBPen(rastPort, 6));
        Assert.Equal(
            otherFlags,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(otherFlags | noPens)));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.Equal(
            otherFlags,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(otherFlags | noPens)));
        Assert.Equal(0, core.SetABPenDrMd(rastPort, 7, 8, 1));
        Assert.Equal(
            otherFlags,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void SetAPenRestoresPrivateNoPensFlagWhenItsLateFlagsWriteFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort originalFlags = 0xC200;
        const byte originalForeground = 1;
        const byte originalPatternCount = 4;

        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            originalForeground));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            originalPatternCount));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            originalFlags));
        for (var plane = 0; plane < 8; plane++)
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                (byte)(0xA0 + plane)));

        // SetAPen publishes the pen, eight minterms, the restarted pattern
        // phase, and then the two-byte Flags word.  Fail the low Flags byte
        // after the high byte has published and require a complete rollback.
        memory.FailOnNextByteWrite(12);
        Assert.Equal(-1, core.SetAPen(rastPort, 9));
        Assert.Equal(
            originalForeground,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal(
            originalPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            originalFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal(
                (byte)(0xA0 + plane),
                ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));
    }

    [Fact]
    public void SetAPenRestoresFlagsAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort originalFlags = 0xC200;
        const byte originalForeground = 1;
        const byte originalPatternCount = 4;
        var flagsAddress = rastPort + (uint)GraphicsLayouts.RastPortFlags;

        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            originalForeground));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            originalPatternCount));
        Assert.True(backing.TryWriteWord(flagsAddress, originalFlags));
        for (var plane = 0; plane < 8; plane++)
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane,
                (byte)(0xA0 + plane)));

        // The final Flags WORD accepts its high byte and rejects the call.
        // RestoreByteSetter must bypass that rejected WORD path, then the
        // same SetAPen call must succeed after the bridge is repaired.
        memory.PartialWordAddress = flagsAddress;

        Assert.Equal(-1, core.SetAPen(rastPort, 9));
        Assert.Equal(
            originalForeground,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal(
            originalPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(originalFlags, ReadWord(backing, flagsAddress));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal(
                (byte)(0xA0 + plane),
                ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)plane));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.SetAPen(rastPort, 9));
        Assert.Equal(
            (byte)9,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal(
            (ushort)(originalFlags & ~GraphicsLayouts.RastPortNoPens),
            ReadWord(backing, flagsAddress));
    }

    [Fact]
    public void RastPortAttributeSetRestoresPrivateNoPensFlagWhenALaterTagFails()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tags = 0x300;
        const ushort originalFlags = 0xC200;

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            originalFlags));
        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.RptagAPen, 5);
        // A null font is a semantic failure after SetAPen has already
        // published its derived state; the tag-list transaction must restore
        // the private Flags word as well.
        WriteTag(memory, tags + 8, GraphicsRastPortAttributeOperations.RptagFont, 0);
        WriteTag(memory, tags + 16, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.False(core.SetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.Equal(
            originalFlags,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void RastPortAttributeGetIgnoresUnknownZeroDataTagsButRejectsKnownNullOutputs()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint unknownTags = 0x300;
        const uint knownTags = 0x320;

        // Exec/graphics tag lists are forward-compatible.  An unknown
        // private tag is ignored even when its data word is zero; it must not
        // make the portable path claim a call that a native/provider owner
        // understands.
        WriteTag(memory, unknownTags, 0xDEAD_BEEFu, 0);
        WriteTag(memory, unknownTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        Assert.True(core.GetRPAttrs(rastPort, unknownTags, new FakeFontBackend()));

        // Recognised output tags still require a writable destination.  Keep
        // the null-output no-op only for RPTAG_MaxPen, matching the existing
        // compatibility boundary.
        WriteTag(memory, knownTags, GraphicsRastPortAttributeOperations.RptagAPen, 0);
        WriteTag(memory, knownTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        Assert.False(core.GetRPAttrs(rastPort, knownTags, new FakeFontBackend()));
    }

