    [Fact]
    public void MoveRestoresTheOldCursorWhenTheSecondCoordinateWriteFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            1));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            2));

        memory.FailOnNextByteWrite(3);
        Assert.Equal(-1, core.Move(rastPort, 8, 9));
        Assert.Equal((short)1, ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((short)2, ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
    }

    [Fact]
    public void MoveRestoresTheOldCursorAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        var currentX = rastPort + (uint)GraphicsLayouts.RastPortCurrentX;
        const ushort oldFlags = 0x1200;

        Assert.True(backing.TryWriteWord(currentX, 0x1234));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            0x2345));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            6));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));

        // The first cursor WORD accepts its high byte and then declines.
        // Byte-wise rollback must restore the original cursor and flags even
        // though the adapter rejects a repeated WORD operation.
        memory.PartialWordAddress = currentX;
        Assert.Equal(-1, core.Move(rastPort, 0x3456, 0x4567));
        Assert.Equal((ushort)0x1234, ReadWord(backing, currentX));
        Assert.Equal(
            (ushort)0x2345,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(
            (byte)6,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            oldFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.Move(rastPort, 0x3456, 0x4567));
        Assert.Equal((ushort)0x3456, ReadWord(backing, currentX));
    }

    [Fact]
    public void MoveDoesNotReadOldCursorOrPatternPhaseAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const ushort oldFlags = 0x1200;

        static void Seed(FakeMemory memory, uint address, ushort flags)
        {
            Assert.True(memory.TryWriteWord(
                address + (uint)GraphicsLayouts.RastPortCurrentX,
                1));
            Assert.True(memory.TryWriteWord(
                address + (uint)GraphicsLayouts.RastPortCurrentY,
                2));
            Assert.True(memory.TryWriteByte(
                address + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));
            Assert.True(memory.TryWriteWord(
                address + (uint)GraphicsLayouts.RastPortFlags,
                flags));
        }

        void RunDirect(int faultOffset, int faultLength)
        {
            var backing = new FakeMemory(0x1000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, rastPort, oldFlags);
            memory.FailReads(rastPort + (uint)faultOffset, (uint)faultLength);

            Assert.Equal(0, core.Move(rastPort, 8, 9));
            Assert.Equal(
                (short)8,
                ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            Assert.Equal(
                (short)9,
                ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
            Assert.Equal(
                (byte)15,
                ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
            Assert.Equal(
                (ushort)(oldFlags | GraphicsLayouts.RastPortFirstDot),
                ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        }

        void RunMapped(int faultOffset, int faultLength)
        {
            var backing = new FakeMemory(0x1000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, rastPort, oldFlags);
            memory.FailReads(rastPort + (uint)faultOffset, (uint)faultLength);

            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 8, [1] = 9 },
                Cycles = 57
            };

            Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Move));
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(57, state.Cycles);
            Assert.Equal(
                (short)8,
                ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
            Assert.Equal(
                (short)9,
                ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
            Assert.Equal(
                (byte)15,
                ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
            Assert.Equal(
                (ushort)(oldFlags | GraphicsLayouts.RastPortFirstDot),
                ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        }

        // Fault the old cursor words, then fault only the old pattern phase.
        // Both are write-valid destinations and are not native Move inputs.
        RunDirect(GraphicsLayouts.RastPortCurrentX, sizeof(ushort) * 2);
        RunDirect(GraphicsLayouts.RastPortLinePatternCount, sizeof(byte));
        RunMapped(GraphicsLayouts.RastPortCurrentX, sizeof(ushort) * 2);
        RunMapped(GraphicsLayouts.RastPortLinePatternCount, sizeof(byte));
    }

