    [Fact]
    public void SetOutlinePenDoesNotReadUnrelatedRastPortStateAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const ushort flags = 0x1200;

        var directBacking = new FakeMemory(0x1000);
        Assert.True(directBacking.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
            3));
        Assert.True(directBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            flags));

        var directMemory = new RangeReadFaultMemory(directBacking);
        directMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            GraphicsLayouts.RastPortFlags - GraphicsLayouts.RastPortDrawMode);
        var directCore = CreateCore(directMemory);

        Assert.Equal(3, directCore.SetOutlinePen(rastPort, 7));
        Assert.Equal(
            (byte)7,
            ReadByte(directBacking, rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(
            (ushort)(flags | GraphicsLayouts.RastPortAreaOutline),
            ReadWord(directBacking, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        var mappedBacking = new FakeMemory(0x1000);
        Assert.True(mappedBacking.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
            4));
        Assert.True(mappedBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            flags));

        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            GraphicsLayouts.RastPortFlags - GraphicsLayouts.RastPortDrawMode);
        var mappedCore = CreateCore(mappedMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 9 },
            Cycles = 47
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetOutlinePen));
        Assert.Equal(4u, state.D[0]);
        Assert.Equal(47, state.Cycles);
        Assert.Equal(
            (byte)9,
            ReadByte(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(
            (ushort)(flags | GraphicsLayouts.RastPortAreaOutline),
            ReadWord(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void HostRegisterAdapterRoutesRegionLifecycleAndBooleanVectors()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rectangle = 0x300;
        WriteRectangle(memory, rectangle, 2, 3, 4, 5);

        var state = new M68kCpuState { A = { [1] = rectangle } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.NewRegion));
        var region = state.D[0];
        Assert.NotEqual(0u, region);

        state.A[0] = region;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.OrRectRegion));
        Assert.Equal(1u, state.D[0]);
        Assert.True(RegionContains(memory, region, 3, 4));

        state.D[0] = 0xCAFE_BABEu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AndRectRegion));
        Assert.Equal(0u, state.D[0]);
        Assert.True(RegionContains(memory, region, 3, 4));

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ClearRegion));
        Assert.Equal(0u, ReadLong(memory, region + (uint)GraphicsLayouts.RegionRectangle));
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.DisposeRegion));
    }

    [Fact]
    public void NativeOverlayRoutesOwnedRegionLifecycleAndTailChainsForeignRegion()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint rectangle = 0x00FC_0000;
        const uint foreignRegion = 0x00FD_0000;
        const uint nativeNewRegionTarget = 0x00FE_1001;
        const uint nativeDisposeTarget = 0x00FE_1007;
        const uint nativeOrRectTarget = 0x00FE_100D;
        const uint nativeAndRectTarget = 0x00FE_1010;
        const uint nativeClearTarget = 0x00FE_1013;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.NewRegion)),
            nativeNewRegionTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.DisposeRegion)),
            nativeDisposeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OrRectRegion)),
            nativeOrRectTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AndRectRegion)),
            nativeAndRectTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClearRegion)),
            nativeClearTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);
        bus.MapWritableMemory(rectangle, new byte[0x20]);
        bus.MapWritableMemory(foreignRegion, new byte[0x20]);

        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 1);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 1);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 3);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 3);

        var nextAllocation = allocationBase;
        var freeCount = 0;
        var memory = new HostGuestMemory(bus);
        using var services = CreateHostGraphicsServices(
            memory,
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => freeCount++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState
        {
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 271
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.NewRegion)),
            create));
        var region = create.D[0];
        Assert.NotEqual(0u, region);
        Assert.Equal(271, create.Cycles);

        var add = new M68kCpuState
        {
            A = { [0] = region, [1] = rectangle },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 277
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OrRectRegion)),
            add));
        Assert.Equal(1u, add.D[0]);
        Assert.Equal(277, add.Cycles);
        var node = bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle);
        Assert.NotEqual(0u, node);
        // RegionRectangle bounds are stored relative to Region.Bounds in the
        // Kickstart guest layout; this rectangle therefore starts at zero
        // and spans two pixels in each dimension.
        Assert.Equal((short)0,
            unchecked((short)bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds)));
        Assert.Equal((short)2,
            unchecked((short)bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 6u)));

        var intersect = new M68kCpuState
        {
            A = { [0] = region, [1] = rectangle },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 279
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AndRectRegion)),
            intersect));
        Assert.Equal(0u, intersect.D[0]);
        Assert.Equal(279, intersect.Cycles);

        var clear = new M68kCpuState
        {
            A = { [0] = region },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 281
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ClearRegion)),
            clear));
        Assert.Equal(0u, clear.D[0]);
        Assert.Equal(281, clear.Cycles);
        Assert.Equal(0u,
            bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle));

        var dispose = new M68kCpuState
        {
            A = { [0] = region },
            D = { [0] = 0x0BAD_F00Du },
            Cycles = 283
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.DisposeRegion)),
            dispose));
        Assert.Equal(0u, dispose.D[0]);
        Assert.Equal(283, dispose.Cycles);
        Assert.True(freeCount >= 2);

        // A foreign/native Region is never passed to the portable allocator.
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignRegion },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 287,
            ProgramCounter = 0x0012_3811
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.DisposeRegion)),
            foreign));
        Assert.Equal(nativeDisposeTarget, foreign.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, foreign.D[0]);
        Assert.Equal(287, foreign.Cycles);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyRegionOutputsBeforeBooleanPublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint allocationBase = 0x00FA_0000;
        const uint rectangle = 0x00FB_0000;
        const uint nativeNewRegionTarget = 0x00FC_144B;
        const uint nativeOrRectTarget = 0x00FC_1451;
        const uint nativeAndRectTarget = 0x00FC_1457;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.NewRegion)),
            nativeNewRegionTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OrRectRegion)),
            nativeOrRectTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AndRectRegion)),
            nativeAndRectTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);
        bus.MapWritableMemory(rectangle, new byte[GraphicsLayouts.RectangleSize]);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinX, 1);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMinY, 1);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxX, 4);
        bus.WriteWord(rectangle + (uint)GraphicsLayouts.RectangleMaxY, 4);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        uint NewRegion()
        {
            var state = new M68kCpuState { D = { [0] = 2 }, Cycles = 449 };
            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase + (int)GraphicsLvo.NewRegion)),
                state));
            Assert.NotEqual(0u, state.D[0]);
            return state.D[0];
        }

        void AddRectangle(uint region)
        {
            var state = new M68kCpuState
            {
                A = { [0] = region, [1] = rectangle },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 451
            };
            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OrRectRegion)),
                state));
            Assert.Equal(1u, state.D[0]);
        }

        var headerRegion = NewRegion();
        var nodeRegion = NewRegion();
        AddRectangle(headerRegion);
        AddRectangle(nodeRegion);

        var headerBefore = Enumerable.Range(0, GraphicsLayouts.RegionSize)
            .Select(offset => bus.ReadByte(headerRegion + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(headerRegion, headerBefore);

        var headerState = new M68kCpuState
        {
            A = { [0] = headerRegion, [1] = rectangle },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 457,
            ProgramCounter = 0x0012_3965
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OrRectRegion)),
            headerState));
        Assert.Equal(nativeOrRectTarget, headerState.ProgramCounter);
        Assert.Equal(0xDEAD_BEEFu, headerState.D[0]);
        Assert.Equal(457, headerState.Cycles);
        for (var offset = 0; offset < headerBefore.Length; offset++)
            Assert.Equal(headerBefore[offset], bus.ReadByte(headerRegion + (uint)offset));

        var node = bus.ReadLong(nodeRegion + (uint)GraphicsLayouts.RegionRectangle);
        var nodeBefore = Enumerable.Range(0, GraphicsLayouts.RegionRectangleSize)
            .Select(offset => bus.ReadByte(node + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(node, nodeBefore);

        var nodeState = new M68kCpuState
        {
            A = { [0] = nodeRegion, [1] = rectangle },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 461,
            ProgramCounter = 0x0012_396B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AndRectRegion)),
            nodeState));
        Assert.Equal(nativeAndRectTarget, nodeState.ProgramCounter);
        Assert.Equal(0x2468_ACE0u, nodeState.D[0]);
        Assert.Equal(461, nodeState.Cycles);
        for (var offset = 0; offset < nodeBefore.Length; offset++)
            Assert.Equal(nodeBefore[offset], bus.ReadByte(node + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveTemplatePatternParityAndTailChainMalformedTemplate()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x300;
        const uint plane = 0x1000;
        const uint template = 0x2000;
        const uint nativeTemplateTarget = 0x00FE_1A01;
        const uint nativePatternTarget = 0x00FE_1A07;
        var rejectTemplateDisplayDma = false;
        var displayDmaChecks = 0;
        var lastDisplayDmaAddress = 0u;
        Func<uint, uint, bool> displayDmaRange = (address, _) =>
        {
            displayDmaChecks++;
            lastDisplayDmaAddress = address;
            return !rejectTemplateDisplayDma || address != template;
        };

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltTemplate)),
                nativeTemplateTarget);
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltPattern)),
                nativePatternTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(plane, new byte[0x100]);
            bus.MapWritableMemory(template, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1, 0);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, 0);
            bus.WriteByte(template, 0xF0, 0);
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            isDisplayDmaRange: displayDmaRange);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            isDisplayDmaRange: displayDmaRange);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directTemplate = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0, [1] = 2, [2] = 0, [3] = 0, [4] = 4, [5] = 1 },
            Cycles = 695
        };
        var overlayTemplate = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0, [1] = 2, [2] = 0, [3] = 0, [4] = 4, [5] = 1 },
            Cycles = 695
        };
        direct.Invoke(directTemplate, (int)GraphicsLvo.BltTemplate);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltTemplate)),
            overlayTemplate));
        Assert.Equal(0u, directTemplate.D[0]);
        Assert.Equal(directTemplate.D[0], overlayTemplate.D[0]);
        Assert.Equal(directTemplate.Cycles, overlayTemplate.Cycles);
        Assert.Equal((byte)0xF0, directBus.ReadByte(plane));
        Assert.Equal(directBus.ReadByte(plane), overlayBus.ReadByte(plane));

        // A readable, aligned template remains available to the resident
        // vector when the active display-DMA adapter classifies its A source
        // as fast memory.  The void D0/cycle frame is unchanged and the
        // mapped call tail-chains to the captured native implementation.
        rejectTemplateDisplayDma = true;
        directBus.WriteByte(plane, 0xA5, 0);
        overlayBus.WriteByte(plane, 0xA5, 0);
        var checksBeforeTemplateDmaDecline = displayDmaChecks;
        var directTemplateDmaDecline = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0xA5A5_0000u, [1] = 2, [2] = 0, [3] = 0, [4] = 4, [5] = 1 },
            Cycles = 697
        };
        var overlayTemplateDmaDecline = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0xA5A5_0000u, [1] = 2, [2] = 0, [3] = 0, [4] = 4, [5] = 1 },
            Cycles = 697,
            ProgramCounter = 0x0012_38AE
        };
        direct.Invoke(directTemplateDmaDecline, (int)GraphicsLvo.BltTemplate);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltTemplate)),
            overlayTemplateDmaDecline));
        Assert.Equal(0xA5A5_0000u, directTemplateDmaDecline.D[0]);
        Assert.Equal(directTemplateDmaDecline.D[0], overlayTemplateDmaDecline.D[0]);
        Assert.Equal(697, directTemplateDmaDecline.Cycles);
        Assert.Equal(697, overlayTemplateDmaDecline.Cycles);
        Assert.Equal(nativeTemplateTarget, overlayTemplateDmaDecline.ProgramCounter);
        Assert.Equal((byte)0xA5, directBus.ReadByte(plane));
        Assert.Equal(directBus.ReadByte(plane), overlayBus.ReadByte(plane));
        Assert.True(
            displayDmaChecks >= checksBeforeTemplateDmaDecline + 2,
            $"display checks {displayDmaChecks}, before {checksBeforeTemplateDmaDecline}, last {lastDisplayDmaAddress:X8}");
        Assert.Equal(template, lastDisplayDmaAddress);

        directBus.WriteByte(plane, 0, 0);
        overlayBus.WriteByte(plane, 0, 0);
        rejectTemplateDisplayDma = false;
        var directPattern = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 0, [4] = 2 },
            Cycles = 701
        };
        var overlayPattern = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 0, [4] = 2 },
            Cycles = 701
        };
        direct.Invoke(directPattern, (int)GraphicsLvo.BltPattern);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltPattern)),
            overlayPattern));
        Assert.Equal(0u, directPattern.D[0]);
        Assert.Equal(directPattern.D[0], overlayPattern.D[0]);
        Assert.Equal(directPattern.Cycles, overlayPattern.Cycles);
        Assert.Equal((byte)0xF0, directBus.ReadByte(plane));
        Assert.Equal(directBus.ReadByte(plane), overlayBus.ReadByte(plane));

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0001u, [1] = rastPort },
            D = { [0] = 0, [1] = 2, [2] = 0, [3] = 0, [4] = 4, [5] = 1 },
            Cycles = 707,
            ProgramCounter = 0x0012_38AF
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltTemplate)),
            malformed));
        Assert.Equal(nativeTemplateTarget, malformed.ProgramCounter);
        Assert.Equal(0u, malformed.D[0]);
        Assert.Equal(707, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRejectBltPatternAggregateWorkBeforeReading()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x300;
        const uint nativeTarget = 0x00FE_1A01;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltPattern)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2048);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, ushort.MaxValue);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x00DE_AD00);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 0, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = (uint)short.MaxValue,
                [3] = (uint)short.MaxValue,
                [4] = 0,
                [5] = 0xA5A5_5A5Au
            },
            Cycles = 713,
            ProgramCounter = 0x0012_38B1
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort },
            D =
            {
                [0] = 0,
                [1] = 0,
                [2] = (uint)short.MaxValue,
                [3] = (uint)short.MaxValue,
                [4] = 0,
                [5] = 0xA5A5_5A5Au
            },
            Cycles = 713,
            ProgramCounter = 0x0012_38B1
        };

        direct.Invoke(directState, (int)GraphicsLvo.BltPattern);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltPattern)),
            overlayState));
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(0xA5A5_5A5Au, directState.D[5]);
        Assert.Equal(directState.D[5], overlayState.D[5]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveBltClearParityAndTailChainMalformedBuffer()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint buffer = 0x7000;
        const uint nativeTarget = 0x00FE_1A01;

        var rejectDisplayDma = false;
        var displayDmaChecks = 0;
        var lastDisplayDmaAddress = 0u;
        Func<uint, uint, bool> displayDmaRange = (address, _) =>
        {
            displayDmaChecks++;
            lastDisplayDmaAddress = address;
            return !rejectDisplayDma || address != buffer;
        };

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(buffer, Enumerable.Repeat((byte)0xA5, 0x100).ToArray());
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            isDisplayDmaRange: displayDmaRange);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            isDisplayDmaRange: displayDmaRange);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = (2u << 16) | 4u, [1] = 0x0000_0002u },
            Cycles = 683
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = (2u << 16) | 4u, [1] = 0x0000_0002u },
            Cycles = 683
        };
        direct.Invoke(directState, (int)GraphicsLvo.BltClear);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        for (var offset = 0; offset < 8; offset++)
        {
            Assert.Equal((byte)0, directBus.ReadByte(buffer + (uint)offset));
            Assert.Equal(directBus.ReadByte(buffer + (uint)offset), overlayBus.ReadByte(buffer + (uint)offset));
        }

        // A readable, aligned memBlock remains available to the resident
        // vector when the active display-DMA adapter classifies it as fast
        // memory.  D0/cycles stay unchanged and the overlay tail-chains.
        rejectDisplayDma = true;
        for (var offset = 0u; offset < 4; offset++)
        {
            directBus.WriteByte(buffer + offset, 0xA5, 0);
            overlayBus.WriteByte(buffer + offset, 0xA5, 0);
        }
        var checksBeforeDmaDecline = displayDmaChecks;
        var directDmaDecline = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = 4, [1] = 0 },
            Cycles = 685
        };
        var overlayDmaDecline = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = 4, [1] = 0 },
            Cycles = 685,
            ProgramCounter = 0x0012_38A7
        };
        direct.Invoke(directDmaDecline, (int)GraphicsLvo.BltClear);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            overlayDmaDecline));
        Assert.Equal(4u, directDmaDecline.D[0]);
        Assert.Equal(4u, overlayDmaDecline.D[0]);
        Assert.Equal(685, directDmaDecline.Cycles);
        Assert.Equal(685, overlayDmaDecline.Cycles);
        Assert.Equal(nativeTarget, overlayDmaDecline.ProgramCounter);
        for (var offset = 0u; offset < 4; offset++)
        {
            Assert.Equal((byte)0xA5, directBus.ReadByte(buffer + offset));
            Assert.Equal((byte)0xA5, overlayBus.ReadByte(buffer + offset));
        }
        Assert.True(displayDmaChecks >= checksBeforeDmaDecline + 2);
        Assert.Equal(buffer, lastDisplayDmaAddress);

        // Rows/bytes-per-row mode remains transparent for an odd row span:
        // the portable core declines before touching the buffer, allowing
        // the captured Kickstart vector to own the malformed call.
        for (var offset = 0u; offset < 8; offset++)
            overlayBus.WriteByte(buffer + offset, 0xA5, 0);
        var oddRow = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = (2u << 16) | 3u, [1] = 0x0000_0002u },
            Cycles = 687,
            ProgramCounter = 0x0012_38A8
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            oddRow));
        Assert.Equal(nativeTarget, oddRow.ProgramCounter);
        Assert.Equal((2u << 16) | 3u, oddRow.D[0]);
        Assert.Equal(687, oddRow.Cycles);
        for (var offset = 0u; offset < 8; offset++)
            Assert.Equal((byte)0xA5, overlayBus.ReadByte(buffer + offset));

        var malformed = new M68kCpuState
        {
            A = { [1] = 0xDEAD_0001u },
            D = { [0] = 0x0002_0004u, [1] = 2 },
            Cycles = 689,
            ProgramCounter = 0x0012_38A9
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0x0002_0004u, malformed.D[0]);
        Assert.Equal(689, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRejectBltClearAggregateWorkBeforeReading()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint buffer = 0x7000;
        const uint nativeTarget = 0x00FE_1A01;
        var byteCount = (unchecked((uint)ushort.MaxValue) << 16) | 16384u;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = byteCount, [1] = 0x2u },
            Cycles = 701,
            ProgramCounter = 0x0012_38B0
        };
        var overlayState = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = byteCount, [1] = 0x2u },
            Cycles = 701,
            ProgramCounter = 0x0012_38B0
        };

        direct.Invoke(directState, (int)GraphicsLvo.BltClear);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            overlayState));
        Assert.Equal(byteCount, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBltClearDestinationBeforePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint buffer = 0x00F0_8D00;
        const uint nativeTarget = 0x00FE_1A01;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
        bus.MapWritableMemory(buffer, new byte[] { 0xA1, 0xB2, 0xC3, 0xD4 });
        bus.MapReadOnlyMemory(buffer, new byte[] { 0xA1, 0xB2, 0xC3, 0xD4 });

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var state = new M68kCpuState
        {
            A = { [1] = buffer },
            D = { [0] = 4, [1] = 0 },
            Cycles = 703,
            ProgramCounter = 0x0012_38B7
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltClear)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(4u, state.D[0]);
        Assert.Equal(0u, state.D[1]);
        Assert.Equal(703, state.Cycles);
        Assert.Equal((byte)0xA1, bus.ReadByte(buffer));
        Assert.Equal((byte)0xB2, bus.ReadByte(buffer + 1u));
        Assert.Equal((byte)0xC3, bus.ReadByte(buffer + 2u));
        Assert.Equal((byte)0xD4, bus.ReadByte(buffer + 3u));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveBitmapRastPortBlitParityAndTailChainMalformedBitmap()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint sourceBitMap = 0x100;
        const uint destinationRastPort = 0x300;
        const uint destinationBitMap = 0x500;
        const uint sourcePlane = 0x1000;
        const uint destinationPlane = 0x1200;
        const uint maskPlane = 0x3000;
        const uint nativeTarget = 0x00FE_1A01;
        const uint nativeMaskTarget = 0x00FE_1A07;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        var rejectMaskDma = false;
        var displayDmaChecks = 0;
        var lastDisplayDmaAddress = 0u;
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMapRastPort)),
                nativeTarget);
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltMaskBitMapRastPort)),
                nativeMaskTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(sourceBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(destinationRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(destinationBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(sourcePlane, new byte[0x100]);
            bus.MapWritableMemory(destinationPlane, new byte[0x100]);
            bus.MapWritableMemory(maskPlane, new byte[0x100]);

            foreach (var bitMap in new[] { sourceBitMap, destinationBitMap })
            {
                bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
                bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
                bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            }
            bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane);
            bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes, destinationPlane);
            bus.WriteLong(destinationRastPort + (uint)GraphicsLayouts.RastPortBitMap, destinationBitMap);
            bus.WriteByte(destinationRastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteByte(sourcePlane, 0xF0, 0);
            bus.WriteByte(maskPlane, 0xF0, 0);
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            isDisplayDmaRange: (address, _) =>
            {
                displayDmaChecks++;
                lastDisplayDmaAddress = address;
                return !rejectMaskDma || address != maskPlane;
            });
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            isDisplayDmaRange: (address, _) =>
            {
                displayDmaChecks++;
                lastDisplayDmaAddress = address;
                return !rejectMaskDma || address != maskPlane;
            });
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directBlit = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 665
        };
        var overlayBlit = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 665
        };
        direct.Invoke(directBlit, (int)GraphicsLvo.BltBitMapRastPort);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMapRastPort)),
            overlayBlit));
        Assert.Equal(1u, directBlit.D[0]);
        Assert.Equal(directBlit.D[0], overlayBlit.D[0]);
        Assert.Equal(directBlit.Cycles, overlayBlit.Cycles);
        for (var offset = 0; offset < 0x100; offset++)
            Assert.Equal(directBus.ReadByte(destinationPlane + (uint)offset), overlayBus.ReadByte(destinationPlane + (uint)offset));
        Assert.Equal((byte)0xF0, directBus.ReadByte(destinationPlane));

        for (var offset = 0; offset < 0x100; offset++)
        {
            directBus.WriteByte(destinationPlane + (uint)offset, 0, 0);
            overlayBus.WriteByte(destinationPlane + (uint)offset, 0, 0);
        }
        var directMask = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort, [2] = maskPlane },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 671
        };
        var overlayMask = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort, [2] = maskPlane },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 671
        };
        direct.Invoke(directMask, (int)GraphicsLvo.BltMaskBitMapRastPort);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltMaskBitMapRastPort)),
            overlayMask));
        Assert.Equal(0u, directMask.D[0]);
        Assert.Equal(directMask.D[0], overlayMask.D[0]);
        Assert.Equal(directMask.Cycles, overlayMask.Cycles);
        for (var offset = 0; offset < 0x100; offset++)
            Assert.Equal(directBus.ReadByte(destinationPlane + (uint)offset), overlayBus.ReadByte(destinationPlane + (uint)offset));
        Assert.Equal((byte)0xF0, directBus.ReadByte(destinationPlane));

        // The external mask is a chip-memory plane in Kickstart 3.1. Once
        // the display-DMA classifier rejects it, direct dispatch must leave
        // the void frame untouched and the mapped overlay must tail-chain to
        // the captured resident vector.
        rejectMaskDma = true;
        var rejectedDirect = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort, [2] = maskPlane },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 673
        };
        var rejectedOverlay = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort, [2] = maskPlane },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 673,
            ProgramCounter = 0x0012_38A1
        };
        direct.Invoke(rejectedDirect, (int)GraphicsLvo.BltMaskBitMapRastPort);
        Assert.True(displayDmaChecks > 0, $"display DMA checks: {displayDmaChecks}");
        Assert.Equal(maskPlane, lastDisplayDmaAddress);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltMaskBitMapRastPort)),
            rejectedOverlay));
        Assert.Equal(0u, rejectedDirect.D[0]);
        Assert.Equal(rejectedDirect.D[0], rejectedOverlay.D[0]);
        Assert.Equal(rejectedDirect.Cycles, rejectedOverlay.Cycles);
        Assert.Equal(nativeMaskTarget, rejectedOverlay.ProgramCounter);
        Assert.True(displayDmaChecks >= 2);
        Assert.Equal((byte)0xF0, directBus.ReadByte(destinationPlane));
        Assert.Equal((byte)0xF0, overlayBus.ReadByte(destinationPlane));

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u, [1] = destinationRastPort },
            D = { [0] = 3, [1] = 2, [2] = 1, [3] = 2, [4] = 4, [5] = 1, [6] = 0xCC },
            Cycles = 677,
            ProgramCounter = 0x0012_38A3
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMapRastPort)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(3u, malformed.D[0]);
        Assert.Equal(677, malformed.Cycles);
    }

