    [Fact]
    public void NativeOverlayAndHostGatewayPreserveBltBitMapParityAndTailChainMalformedBitmap()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint sourceBitMap = 0x100;
        const uint destinationBitMap = 0x300;
        const uint sourcePlanes = 0x1000;
        const uint destinationPlanes = 0x1200;
        const uint tempA = 0x1600;
        const uint nativeTarget = 0x00FE_1A01;

        var rejectTempA = false;
        var rejectPlane = false;
        var displayDmaChecks = 0;
        var lastDisplayDmaAddress = 0u;
        Func<uint, uint, bool> displayDmaRange = (address, _) =>
        {
            displayDmaChecks++;
            lastDisplayDmaAddress = address;
            return (!rejectTempA || address != tempA) &&
                   (!rejectPlane || address != sourcePlanes);
        };

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMap)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(sourceBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(destinationBitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(sourcePlanes, new byte[0x200]);
            bus.MapWritableMemory(destinationPlanes, new byte[0x200]);
            bus.MapWritableMemory(tempA, new byte[0x100]);

            foreach (var bitMap in new[] { sourceBitMap, destinationBitMap })
            {
                bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
                bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
                bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            }
            bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlanes);
            bus.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, sourcePlanes + 0x100);
            bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes, destinationPlanes);
            bus.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, destinationPlanes + 0x100);
            bus.WriteByte(sourcePlanes, 0xA0, 0);
            bus.WriteByte(sourcePlanes + 0x100, 0x50, 0);
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            isDisplayDmaRange: displayDmaRange);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            isDisplayDmaRange: displayDmaRange);
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC, [7] = 0x03 },
            Cycles = 641
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xCC, [7] = 0x03 },
            Cycles = 641
        };
        direct.Invoke(directState, (int)GraphicsLvo.BltBitMap);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMap)),
            overlayState));
        Assert.Equal(2u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(destinationPlanes + (uint)offset), overlayBus.ReadByte(destinationPlanes + (uint)offset));
        Assert.Equal((byte)0xA0, directBus.ReadByte(destinationPlanes));
        Assert.Equal((byte)0x50, directBus.ReadByte(destinationPlanes + 0x100));

        // A caller-supplied TempA is relevant only when the source and
        // destination scan-line spans overlap.  Keep the workspace readable
        // and aligned, then reject it solely through the display-DMA class so
        // both the direct gateway and the ROM overlay remain unclaimed.
        rejectTempA = true;
        var directOverlap = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = sourceBitMap, [2] = tempA },
            D = { [0] = 0xCAFE_0000u, [1] = 0, [2] = 1, [3] = 0, [4] = 7, [5] = 1, [6] = 0xC0, [7] = 0x03 },
            Cycles = 653
        };
        var overlayOverlap = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = sourceBitMap, [2] = tempA },
            D = { [0] = 0xCAFE_0000u, [1] = 0, [2] = 1, [3] = 0, [4] = 7, [5] = 1, [6] = 0xC0, [7] = 0x03 },
            Cycles = 653,
            ProgramCounter = 0x0012_389A
        };
        direct.Invoke(directOverlap, (int)GraphicsLvo.BltBitMap);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMap)),
            overlayOverlap));
        Assert.Equal(0xCAFE_0000u, directOverlap.D[0]);
        Assert.Equal(0xCAFE_0000u, overlayOverlap.D[0]);
        Assert.Equal(653, directOverlap.Cycles);
        Assert.Equal(653, overlayOverlap.Cycles);
        Assert.Equal(nativeTarget, overlayOverlap.ProgramCounter);
        Assert.Equal((byte)0xA0, directBus.ReadByte(sourcePlanes));
        Assert.Equal((byte)0x50, directBus.ReadByte(sourcePlanes + 0x100));
        Assert.Equal((byte)0xA0, overlayBus.ReadByte(sourcePlanes));
        Assert.Equal((byte)0x50, overlayBus.ReadByte(sourcePlanes + 0x100));
        Assert.True(displayDmaChecks >= 2);
        Assert.Equal(tempA, lastDisplayDmaAddress);

        // The shared planar validator also owns the source/destination bitmap
        // address class.  A readable source plane outside the chip-DMA class
        // must decline before the destination is staged, even when TempA is
        // not involved in this non-overlapping copy.
        rejectTempA = false;
        rejectPlane = true;
        directBus.WriteByte(destinationPlanes, 0x5A, 0);
        directBus.WriteByte(destinationPlanes + 0x100, 0xC3, 0);
        overlayBus.WriteByte(destinationPlanes, 0x5A, 0);
        overlayBus.WriteByte(destinationPlanes + 0x100, 0xC3, 0);
        var checksBeforePlane = displayDmaChecks;
        var directPlaneDecline = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0xFACE_0000u, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xC0, [7] = 0x03 },
            Cycles = 659
        };
        var overlayPlaneDecline = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0xFACE_0000u, [1] = 0, [2] = 0, [3] = 0, [4] = 4, [5] = 1, [6] = 0xC0, [7] = 0x03 },
            Cycles = 659,
            ProgramCounter = 0x0012_3898
        };
        direct.Invoke(directPlaneDecline, (int)GraphicsLvo.BltBitMap);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMap)),
            overlayPlaneDecline));
        Assert.Equal(0xFACE_0000u, directPlaneDecline.D[0]);
        Assert.Equal(0xFACE_0000u, overlayPlaneDecline.D[0]);
        Assert.Equal(659, directPlaneDecline.Cycles);
        Assert.Equal(659, overlayPlaneDecline.Cycles);
        Assert.Equal(nativeTarget, overlayPlaneDecline.ProgramCounter);
        Assert.Equal((byte)0x5A, directBus.ReadByte(destinationPlanes));
        Assert.Equal((byte)0xC3, directBus.ReadByte(destinationPlanes + 0x100));
        Assert.Equal((byte)0x5A, overlayBus.ReadByte(destinationPlanes));
        Assert.Equal((byte)0xC3, overlayBus.ReadByte(destinationPlanes + 0x100));
        Assert.True(displayDmaChecks >= checksBeforePlane + 2);
        Assert.Equal(sourcePlanes, lastDisplayDmaAddress);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u, [1] = destinationBitMap },
            D = { [0] = 3, [1] = 2, [2] = 1, [3] = 2, [4] = 4, [5] = 1, [6] = 0xCC, [7] = 0x03 },
            Cycles = 647,
            ProgramCounter = 0x0012_3897
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.BltBitMap)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(3u, malformed.D[0]);
        Assert.Equal(647, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePixelLineParityAndTailChainMalformedRastPort()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint planes = 0x1000;
        const uint sourcePixels = 0x2000;
        const uint destinationPixels = 0x2100;
        const uint sourceArray = 0x2200;
        const uint destinationArray = 0x2300;
        const uint oddTemporaryRastPort = 0x2601;
        const uint nativeReadTarget = 0x00FE_1A01;
        const uint nativeWriteTarget = 0x00FE_1A07;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ReadPixelLine8)),
                nativeReadTarget);
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixelLine8)),
                nativeWriteTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(planes, new byte[0x200]);
            bus.MapWritableMemory(sourcePixels, new byte[0x100]);
            bus.MapWritableMemory(destinationPixels, new byte[0x100]);
            bus.MapWritableMemory(sourceArray, new byte[0x100]);
            bus.MapWritableMemory(destinationArray, new byte[0x100]);
            bus.MapWritableMemory(oddTemporaryRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, planes);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, planes + 0x100);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
            bus.WriteByte(sourcePixels, 1, 0);
            bus.WriteByte(sourcePixels + 1, 2, 0);
            bus.WriteByte(sourcePixels + 2, 3, 0);
            bus.WriteByte(sourcePixels + 3, 0, 0);
            bus.WriteByte(sourceArray + 0, 1, 0);
            bus.WriteByte(sourceArray + 1, 2, 0);
            bus.WriteByte(sourceArray + 2, 3, 0);
            bus.WriteByte(sourceArray + 16, 3, 0);
            bus.WriteByte(sourceArray + 17, 2, 0);
            bus.WriteByte(sourceArray + 18, 1, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directWrite = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourcePixels },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 601
        };
        var overlayWrite = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourcePixels },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 601
        };
        direct.Invoke(directWrite, (int)GraphicsLvo.WritePixelLine8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixelLine8)),
            overlayWrite));
        Assert.Equal(4u, directWrite.D[0]);
        Assert.Equal(directWrite.D[0], overlayWrite.D[0]);
        Assert.Equal(directWrite.Cycles, overlayWrite.Cycles);

        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(planes + (uint)offset), overlayBus.ReadByte(planes + (uint)offset));

        // Pixel-array coordinates are UWORDs.  A low word of $fffe is the
        // large coordinate 65534, so the request is wholly outside this
        // 16-pixel bitmap.  The mapped overlay must preserve that low-word
        // unsigned value and the same no-write result as direct dispatch.
        for (var offset = 0; offset < 0x200; offset++)
        {
            directBus.WriteByte(planes + (uint)offset, 0, 0);
            overlayBus.WriteByte(planes + (uint)offset, 0, 0);
        }
        var highBitDirect = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourcePixels },
            D = { [0] = 0xFFFE, [1] = 0, [2] = 4 },
            Cycles = 605
        };
        var highBitOverlay = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourcePixels },
            D = { [0] = 0xFFFE, [1] = 0, [2] = 4 },
            Cycles = 605
        };
        direct.Invoke(highBitDirect, (int)GraphicsLvo.WritePixelLine8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixelLine8)),
            highBitOverlay));
        // ReadPixelLine8/WritePixelLine8 report the number of pixels actually
        // read/plotted, so a large unsigned coordinate outside the bitmap
        // produces a zero count while still consuming the low UWORD inputs.
        Assert.Equal(0u, highBitDirect.D[0]);
        Assert.Equal(highBitDirect.D[0], highBitOverlay.D[0]);
        Assert.Equal(highBitDirect.Cycles, highBitOverlay.Cycles);
        var highBitPixel0 = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0 }
        };
        direct.Invoke(highBitPixel0, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(0u, highBitPixel0.D[0]);
        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(planes + (uint)offset), overlayBus.ReadByte(planes + (uint)offset));
        var highBitRead0 = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0 }
        };
        direct.Invoke(highBitRead0, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(0u, highBitRead0.D[0]);
        var highBitRead1 = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0 }
        };
        direct.Invoke(highBitRead1, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(0u, highBitRead1.D[0]);

        for (var offset = 0; offset < 0x200; offset++)
        {
            directBus.WriteByte(planes + (uint)offset, 0, 0);
            overlayBus.WriteByte(planes + (uint)offset, 0, 0);
        }
        var highBitArrayDirect = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0xFFFE, [1] = 0, [2] = 0xFFFF, [3] = 0 },
            Cycles = 611
        };
        var highBitArrayOverlay = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0xFFFE, [1] = 0, [2] = 0xFFFF, [3] = 0 },
            Cycles = 611
        };
        direct.Invoke(highBitArrayDirect, (int)GraphicsLvo.WritePixelArray8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixelArray8)),
            highBitArrayOverlay));
        Assert.Equal(0u, highBitArrayDirect.D[0]);
        Assert.Equal(highBitArrayDirect.D[0], highBitArrayOverlay.D[0]);
        Assert.Equal(highBitArrayDirect.Cycles, highBitArrayOverlay.Cycles);
        var highBitArrayRead = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0 }
        };
        direct.Invoke(highBitArrayRead, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(0u, highBitArrayRead.D[0]);
        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(planes + (uint)offset), overlayBus.ReadByte(planes + (uint)offset));

        var directRead = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = destinationPixels },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 607
        };
        var overlayRead = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = destinationPixels },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 607
        };
        direct.Invoke(directRead, (int)GraphicsLvo.ReadPixelLine8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ReadPixelLine8)),
            overlayRead));
        Assert.Equal(4u, directRead.D[0]);
        Assert.Equal(directRead.D[0], overlayRead.D[0]);
        Assert.Equal(directRead.Cycles, overlayRead.Cycles);
        for (var offset = 0; offset < 4; offset++)
            Assert.Equal(directBus.ReadByte(destinationPixels + (uint)offset), overlayBus.ReadByte(destinationPixels + (uint)offset));

        var directArrayWrite = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2 },
            Cycles = 619
        };
        var overlayArrayWrite = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2 },
            Cycles = 619
        };
        direct.Invoke(directArrayWrite, (int)GraphicsLvo.WritePixelArray8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixelArray8)),
            overlayArrayWrite));
        Assert.Equal(directArrayWrite.D[0], overlayArrayWrite.D[0]);
        Assert.Equal(directArrayWrite.Cycles, overlayArrayWrite.Cycles);
        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(planes + (uint)offset), overlayBus.ReadByte(planes + (uint)offset));

        var directArrayRead = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = destinationArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2 },
            Cycles = 623
        };
        var overlayArrayRead = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = destinationArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2 },
            Cycles = 623
        };
        direct.Invoke(directArrayRead, (int)GraphicsLvo.ReadPixelArray8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ReadPixelArray8)),
            overlayArrayRead));
        Assert.Equal(directArrayRead.D[0], overlayArrayRead.D[0]);
        Assert.Equal(directArrayRead.Cycles, overlayArrayRead.Cycles);
        for (var offset = 0; offset < 0x20; offset++)
            Assert.Equal(directBus.ReadByte(destinationArray + (uint)offset), overlayBus.ReadByte(destinationArray + (uint)offset));

        // V40 WriteChunkyPixels uses the same guest-only planar destination
        // boundary, with an explicit source modulo and signed coordinates.
        for (var offset = 0; offset < 0x200; offset++)
        {
            directBus.WriteByte(planes + (uint)offset, 0, 0);
            overlayBus.WriteByte(planes + (uint)offset, 0, 0);
        }
        var directChunky = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2, [4] = 16 },
            Cycles = 629
        };
        var overlayChunky = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2, [4] = 16 },
            Cycles = 629
        };
        direct.Invoke(directChunky, (int)GraphicsLvo.WriteChunkyPixels);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WriteChunkyPixels)),
            overlayChunky));
        Assert.Equal(0u, directChunky.D[0]);
        Assert.Equal(directChunky.D[0], overlayChunky.D[0]);
        Assert.Equal(directChunky.Cycles, overlayChunky.Cycles);
        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(planes + (uint)offset), overlayBus.ReadByte(planes + (uint)offset));

        // An explicitly supplied temporary RastPort with an odd base is a
        // native address-error/provider case.  Both direct and ROM-overlay
        // paths must leave the input/result register and planar bytes alone.
        for (var offset = 0; offset < 0x200; offset++)
        {
            directBus.WriteByte(planes + (uint)offset, 0, 0);
            overlayBus.WriteByte(planes + (uint)offset, 0, 0);
        }
        var oddTemporaryDirect = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = oddTemporaryRastPort, [2] = sourcePixels },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 633
        };
        var oddTemporaryOverlay = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = oddTemporaryRastPort, [2] = sourcePixels },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 633
        };
        direct.Invoke(oddTemporaryDirect, (int)GraphicsLvo.WritePixelLine8);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WritePixelLine8)),
            oddTemporaryOverlay));
        Assert.Equal(0u, oddTemporaryDirect.D[0]);
        Assert.Equal(oddTemporaryDirect.D[0], oddTemporaryOverlay.D[0]);
        Assert.Equal(oddTemporaryDirect.Cycles, oddTemporaryOverlay.Cycles);
        for (var offset = 0; offset < 0x200; offset++)
            Assert.Equal(directBus.ReadByte(planes + (uint)offset), overlayBus.ReadByte(planes + (uint)offset));

        // A malformed standard RastPort remains available to the captured
        // resident vector when the overlaid portable path declines it.
        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u, [2] = destinationPixels },
            D = { [0] = 7, [1] = 1, [2] = 1 },
            Cycles = 613,
            ProgramCounter = 0x0012_3891
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ReadPixelLine8)),
            malformed));
        Assert.Equal(nativeReadTarget, malformed.ProgramCounter);
        Assert.Equal(7u, malformed.D[0]);
        Assert.Equal(613, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedRasterAllocationAndTailChainsForeignFree()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint raster = 0x00FB_0000;
        const uint nativeAllocTarget = 0x00FE_1101;
        const uint nativeFreeTarget = 0x00FE_1107;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocRaster)),
            nativeAllocTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeRaster)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(raster, new byte[0x100]);

        var allocations = 0;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (_, _) =>
            {
                allocations++;
                return raster;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var allocate = new M68kCpuState
        {
            D = { [0] = 17, [1] = 3 },
            Cycles = 293
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocRaster)),
            allocate));
        Assert.Equal(raster, allocate.D[0]);
        Assert.Equal(1, allocations);
        Assert.Equal(293, allocate.Cycles);

        var free = new M68kCpuState
        {
            A = { [0] = raster },
            D = { [0] = 17, [1] = 3 },
            Cycles = 299
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeRaster)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(1, frees);
        Assert.Equal(299, free.Cycles);

        // The same address is now foreign to this graphics instance.  A
        // repeated or mismatched free must not reach the allocator.
        var foreign = new M68kCpuState
        {
            A = { [0] = raster },
            D = { [0] = 17, [1] = 3 },
            Cycles = 301,
            ProgramCounter = 0x0012_3817
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeRaster)),
            foreign));
        Assert.Equal(nativeFreeTarget, foreign.ProgramCounter);
        Assert.Equal(17u, foreign.D[0]);
        Assert.Equal(1, frees);
        Assert.Equal(301, foreign.Cycles);

        // An odd address is malformed even when it lands inside the mapped
        // chip span.  The mapped overlay must preserve the native target and
        // allocator count rather than interpreting it as the owned raster.
        var odd = new M68kCpuState
        {
            A = { [0] = raster + 1u },
            D = { [0] = 17, [1] = 3 },
            Cycles = 304,
            ProgramCounter = 0x0012_381A
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeRaster)),
            odd));
        Assert.Equal(nativeFreeTarget, odd.ProgramCounter);
        Assert.Equal(17u, odd.D[0]);
        Assert.Equal(3u, odd.D[1]);
        Assert.Equal(1, frees);
        Assert.Equal(304, odd.Cycles);

        var malformed = new M68kCpuState
        {
            // Zero is the invalid low-word geometry; the high words are
            // deliberately nonzero residue that the UWORD ABI must ignore.
            D = { [0] = 0xFFFF_0000u, [1] = 0x1234_0000u },
            Cycles = 307,
            ProgramCounter = 0x0012_381D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocRaster)),
            malformed));
        Assert.Equal(nativeAllocTarget, malformed.ProgramCounter);
        Assert.Equal(0xFFFF_0000u, malformed.D[0]);
        Assert.Equal(0x1234_0000u, malformed.D[1]);
        Assert.Equal(1, allocations);
        Assert.Equal(307, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedColorMapRgbOperationsAndTailChainsForeignMap()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint rgbTable = 0x00FC_0000;
        const uint foreignMap = 0x00FD_0000;
        const uint nativeGetColorMapTarget = 0x00FE_1201;
        const uint nativeFreeColorMapTarget = 0x00FE_1207;
        const uint nativeGetRgb4Target = 0x00FE_120D;
        const uint nativeGetRgb32Target = 0x00FE_1213;
        const uint nativeLoadRgb32Target = 0x00FE_1219;
        const uint viewPort = 0x00FD_8000;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            nativeGetColorMapTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeColorMap)),
            nativeFreeColorMapTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB4)),
            nativeGetRgb4Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB32)),
            nativeGetRgb32Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            nativeLoadRgb32Target);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);
        bus.MapWritableMemory(rgbTable, new byte[0x100]);
        bus.MapWritableMemory(foreignMap, new byte[0x40]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState
        {
            D = { [0] = 4 },
            Cycles = 313
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);
        Assert.Equal(313, create.Cycles);

        var setRgb4 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1, [1] = 0xA, [2] = 0x5, [3] = 0xF },
            Cycles = 317
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4CM)),
            setRgb4));
        Assert.Equal(0u, setRgb4.D[0]);
        Assert.Equal(317, setRgb4.Cycles);
        var colors = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        Assert.Equal(0xA5Fu,
            (uint)(bus.ReadWord(colors + 2u) & 0x0FFF));
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        var getRgb4 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1 },
            Cycles = 319
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB4)),
            getRgb4));
        Assert.Equal(0xA5Fu, getRgb4.D[0]);
        Assert.Equal(319, getRgb4.Cycles);

        var setRgb32 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 2, [1] = 0xAB00_0000u, [2] = 0x3412_0000u, [3] = 0xFF80_0000u },
            Cycles = 323
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32CM)),
            setRgb32));
        Assert.Equal(0u, setRgb32.D[0]);

        var lowColors = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits);
        bus.WriteWord(lowColors + 4u, 0x0ABC);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        var legacySetRgb32 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 2, [1] = 0x1200_0000u, [2] = 0x3400_0000u, [3] = 0x5600_0000u },
            Cycles = 327
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32CM)),
            legacySetRgb32));
        Assert.Equal(0u, legacySetRgb32.D[0]);
        Assert.Equal(327, legacySetRgb32.Cycles);
        Assert.Equal((ushort)0x0ABC, bus.ReadWord(lowColors + 4u));

        var getRgb32 = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = rgbTable },
            D = { [0] = 1, [1] = 2 },
            Cycles = 329
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB32)),
            getRgb32));
        Assert.Equal(0u, getRgb32.D[0]);
        Assert.NotEqual(0u, bus.ReadLong(rgbTable));
        Assert.Equal(329, getRgb32.Cycles);

        var oddGetRgb32 = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = rgbTable + 1u },
            D = { [0] = 1, [1] = 1, [2] = 0xCAFE_BABEu },
            Cycles = 330,
            ProgramCounter = 0x0012_380F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB32)),
            oddGetRgb32));
        Assert.Equal(nativeGetRgb32Target, oddGetRgb32.ProgramCounter);
        Assert.Equal(1u, oddGetRgb32.D[0]);
        Assert.Equal(0xCAFE_BABEu, oddGetRgb32.D[2]);
        Assert.Equal(330, oddGetRgb32.Cycles);

        var oddLoadRgb32 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rgbTable + 1u },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 330,
            ProgramCounter = 0x0012_3810
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            oddLoadRgb32));
        Assert.Equal(nativeLoadRgb32Target, oddLoadRgb32.ProgramCounter);
        Assert.Equal(0x2468_ACE0u, oddLoadRgb32.D[0]);
        Assert.Equal(330, oddLoadRgb32.Cycles);

        var free = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 331
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeColorMap)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(331, free.Cycles);
        Assert.True(frees >= 3);

        // Kickstart treats a NULL ColorMap as a successful void no-op.  The
        // reversible overlay may claim that form without swallowing a
        // non-null foreign map or changing the caller's cycle frame.
        var nullFree = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 333,
            ProgramCounter = 0x0012_3811
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeColorMap)),
            nullFree));
        Assert.Equal(0u, nullFree.D[0]);
        Assert.Equal(333, nullFree.Cycles);
        Assert.Equal(0x0012_3811u, nullFree.ProgramCounter);

        var foreign = new M68kCpuState
        {
            A = { [0] = foreignMap },
            D = { [0] = 1 },
            Cycles = 337,
            ProgramCounter = 0x0012_3823
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB4)),
            foreign));
        Assert.Equal(nativeGetRgb4Target, foreign.ProgramCounter);
        Assert.Equal(1u, foreign.D[0]);
        Assert.Equal(337, foreign.Cycles);

        var malformed = new M68kCpuState
        {
            D = { [0] = 0 },
            Cycles = 341,
            ProgramCounter = 0x0012_3829
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            malformed));
        Assert.Equal(nativeGetColorMapTarget, malformed.ProgramCounter);
        Assert.Equal(0u, malformed.D[0]);
        Assert.Equal(341, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyPaletteMutationBeforeColorMapWrite()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint viewPort = 0x00FC_0000;
        const uint nativeSetRgb4CmTarget = 0x00FE_1431;
        const uint nativeSetRgb32CmTarget = 0x00FE_1437;
        const uint nativeSetRgb4Target = 0x00FE_143D;
        const uint nativeSetRgb32Target = 0x00FE_1443;
        const byte sentinel = 0xA7;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4CM)),
            nativeSetRgb4CmTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32CM)),
            nativeSetRgb32CmTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4)),
            nativeSetRgb4Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32)),
            nativeSetRgb32Target);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 2 }, Cycles = 409 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        var colorTable = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        bus.WriteWord(colorTable + 2u, 0x1357);
        bus.MapReadOnlyMemory(
            colorTable,
            Enumerable.Repeat(sentinel, 4).ToArray());

        var directSet4 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1, [1] = 0x0A, [2] = 0x05, [3] = 0x0F },
            Cycles = 413,
            ProgramCounter = 0x0012_3941
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4CM)),
            directSet4));
        Assert.Equal(nativeSetRgb4CmTarget, directSet4.ProgramCounter);
        Assert.Equal(1u, directSet4.D[0]);
        Assert.Equal(0x0Au, directSet4.D[1]);
        Assert.Equal(0x05u, directSet4.D[2]);
        Assert.Equal(0x0Fu, directSet4.D[3]);
        Assert.Equal(413, directSet4.Cycles);
        Assert.Equal(sentinel, bus.ReadByte(colorTable + 2u));

        var directSet32 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1, [1] = 0xAB00_0000u, [2] = 0x3400_0000u, [3] = 0xFF80_0000u },
            Cycles = 417,
            ProgramCounter = 0x0012_3947
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32CM)),
            directSet32));
        Assert.Equal(nativeSetRgb32CmTarget, directSet32.ProgramCounter);
        Assert.Equal(1u, directSet32.D[0]);
        Assert.Equal(0xAB00_0000u, directSet32.D[1]);
        Assert.Equal(0x3400_0000u, directSet32.D[2]);
        Assert.Equal(0xFF80_0000u, directSet32.D[3]);
        Assert.Equal(417, directSet32.Cycles);

        var viewSet4 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 1, [1] = 1, [2] = 2, [3] = 3 },
            Cycles = 421,
            ProgramCounter = 0x0012_394D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4)),
            viewSet4));
        Assert.Equal(nativeSetRgb4Target, viewSet4.ProgramCounter);
        Assert.Equal(1u, viewSet4.D[0]);
        Assert.Equal(1u, viewSet4.D[1]);
        Assert.Equal(2u, viewSet4.D[2]);
        Assert.Equal(3u, viewSet4.D[3]);
        Assert.Equal(421, viewSet4.Cycles);

        var viewSet32 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 1, [1] = 0x1200_0000u, [2] = 0x3400_0000u, [3] = 0x5600_0000u },
            Cycles = 425,
            ProgramCounter = 0x0012_3953
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32)),
            viewSet32));
        Assert.Equal(nativeSetRgb32Target, viewSet32.ProgramCounter);
        Assert.Equal(1u, viewSet32.D[0]);
        Assert.Equal(0x1200_0000u, viewSet32.D[1]);
        Assert.Equal(0x3400_0000u, viewSet32.D[2]);
        Assert.Equal(0x5600_0000u, viewSet32.D[3]);
        Assert.Equal(425, viewSet32.Cycles);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBulkPaletteMutationBeforeColorMapWrite()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint allocationBase = 0x00FA_0000;
        const uint viewPort = 0x00FB_0000;
        const uint colors = 0x00FC_0000;
        const uint rgb32 = 0x00FC_0100;
        const uint nativeLoadRgb4Target = 0x00FD_1451;
        const uint nativeLoadRgb32Target = 0x00FD_1457;
        const byte sentinel = 0xB3;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB4)),
            nativeLoadRgb4Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            nativeLoadRgb32Target);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(colors, new byte[8]);
        bus.MapWritableMemory(rgb32, new byte[24]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 2 }, Cycles = 433 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        var colorTable = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        bus.WriteWord(colors, 0x0123);
        bus.WriteWord(colors + 2u, 0x0456);
        bus.MapReadOnlyMemory(
            colorTable,
            Enumerable.Repeat(sentinel, 4).ToArray());

        var load4 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = colors },
            D = { [0] = 2, [1] = 0xCAFE_BABEu },
            Cycles = 437,
            ProgramCounter = 0x0012_3959
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB4)),
            load4));
        Assert.Equal(nativeLoadRgb4Target, load4.ProgramCounter);
        Assert.Equal(2u, load4.D[0]);
        Assert.Equal(0xCAFE_BABEu, load4.D[1]);
        Assert.Equal(437, load4.Cycles);

        var load32 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rgb32 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 441,
            ProgramCounter = 0x0012_395F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            load32));
        Assert.Equal(nativeLoadRgb32Target, load32.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, load32.D[0]);
        Assert.Equal(441, load32.Cycles);
        Assert.Equal(sentinel, bus.ReadByte(colorTable));
        Assert.Equal(sentinel, bus.ReadByte(colorTable + 2u));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyRgb32OutputBeforePaletteRead()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint rgbTable = 0x00F0_2200;
        const uint nativeTarget = 0x00FE_1425;
        const byte sentinel = 0xA7;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB32)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);
        bus.MapWritableMemory(
            rgbTable,
            Enumerable.Repeat(sentinel, 12).ToArray());
        bus.MapReadOnlyMemory(
            rgbTable,
            Enumerable.Repeat(sentinel, 12).ToArray());

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => { });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState
        {
            D = { [0] = 2 },
            Cycles = 397
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);

        var get = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = rgbTable },
            D = { [0] = 0, [1] = 1, [2] = 0xCAFE_BABEu },
            Cycles = 401,
            ProgramCounter = 0x0012_382B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetRGB32)),
            get));

        // The output overlay owns the call before ColorMap entry decoding or
        // rollback staging.  The original vector remains reachable with the
        // caller's frame intact.
        Assert.Equal(nativeTarget, get.ProgramCounter);
        Assert.Equal(0u, get.D[0]);
        Assert.Equal(1u, get.D[1]);
        Assert.Equal(0xCAFE_BABEu, get.D[2]);
        Assert.Equal(401, get.Cycles);
        for (var offset = 0; offset < 12; offset++)
            Assert.Equal(sentinel, bus.ReadByte(rgbTable + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyPixelArrayOutputsBeforePlanarRead()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint planes = 0x1000;
        // Pixel arrays are byte-addressed guest buffers, so odd starts are
        // valid and must still be admitted only when the complete span is
        // writable.
        const uint lineOutput = 0x00F0_2201;
        const uint arrayOutput = 0x00F0_2303;
        const uint nativeTarget = 0x00FE_1B01;
        const byte lineSentinel = 0xB6;
        const byte arraySentinel = 0xC7;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ReadPixelLine8)),
            nativeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ReadPixelArray8)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(planes, new byte[0x200]);
        bus.MapReadOnlyMemory(
            lineOutput,
            Enumerable.Repeat(lineSentinel, 16).ToArray());
        bus.MapReadOnlyMemory(
            arrayOutput,
            Enumerable.Repeat(arraySentinel, 32).ToArray());

        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, planes);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, planes + 0x100);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x03, 0);
        bus.WriteByte(planes, 0x5A, 0);
        bus.WriteByte(planes + 0x100, 0xA5, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var line = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0, [2] = lineOutput },
            D = { [0] = 7, [1] = 1, [2] = 4 },
            Cycles = 701,
            ProgramCounter = 0x0012_3841
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ReadPixelLine8)),
            line));
        Assert.Equal(nativeTarget, line.ProgramCounter);
        Assert.Equal(7u, line.D[0]);
        Assert.Equal(1u, line.D[1]);
        Assert.Equal(4u, line.D[2]);
        Assert.Equal(701, line.Cycles);
        for (var offset = 0; offset < 16; offset++)
            Assert.Equal(lineSentinel, bus.ReadByte(lineOutput + (uint)offset));

        var array = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0, [2] = arrayOutput },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 1 },
            Cycles = 707,
            ProgramCounter = 0x0012_3847
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ReadPixelArray8)),
            array));
        Assert.Equal(nativeTarget, array.ProgramCounter);
        Assert.Equal(0u, array.D[0]);
        Assert.Equal(0u, array.D[1]);
        Assert.Equal(3u, array.D[2]);
        Assert.Equal(1u, array.D[3]);
        Assert.Equal(707, array.Cycles);
        for (var offset = 0; offset < 32; offset++)
            Assert.Equal(arraySentinel, bus.ReadByte(arrayOutput + (uint)offset));

        Assert.Equal((byte)0x5A, bus.ReadByte(planes));
        Assert.Equal((byte)0xA5, bus.ReadByte(planes + 0x100));
    }

    [Fact]
    public void NativeOverlayRoutesOwnedPaletteSharingAndTailChainsForeignMap()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint viewPort = 0x00FC_0000;
        const uint foreignMap = 0x00FD_0000;
        const uint nativeAttachTarget = 0x00FE_1401;
        const uint nativeObtainTarget = 0x00FE_1407;
        const uint nativeBestTarget = 0x00FE_140D;
        const uint nativeReleaseTarget = 0x00FE_1413;
        const uint nativeFindTarget = 0x00FE_1419;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AttachPalExtra)),
            nativeAttachTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainPen)),
            nativeObtainTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainBestPenA)),
            nativeBestTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ReleasePen)),
            nativeReleaseTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FindColor)),
            nativeFindTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(foreignMap, new byte[0x40]);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 4 }, Cycles = 373 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);

        var attach = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = viewPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 379
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AttachPalExtra)),
            attach));
        Assert.Equal(0u, attach.D[0]);
        Assert.Equal(379, attach.Cycles);

        var obtain = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = uint.MaxValue, [1] = 0xA000_0000u, [2] = 0x2000_0000u, [3] = 0x3000_0000u },
            Cycles = 383
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainPen)),
            obtain));
        var pen = obtain.D[0];
        Assert.Equal(3u, pen);
        Assert.Equal(383, obtain.Cycles);

        var best = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [1] = 0xA000_0000u, [2] = 0x2000_0000u, [3] = 0x3000_0000u },
            Cycles = 389
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainBestPenA)),
            best));
        Assert.Equal(pen, best.D[0]);
        Assert.Equal(389, best.Cycles);

        var malformedTags = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = 0xFFFF_FFFEu },
            D = { [0] = 0xDEAD_BEEFu, [1] = 0xA000_0000u, [2] = 0x2000_0000u, [3] = 0x3000_0000u },
            Cycles = 391,
            ProgramCounter = 0x0012_3837
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainBestPenA)),
            malformedTags));
        Assert.Equal(nativeBestTarget, malformedTags.ProgramCounter);
        Assert.Equal(0xDEAD_BEEFu, malformedTags.D[0]);
        Assert.Equal(391, malformedTags.Cycles);

        var find = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [1] = 0xA000_0000u, [2] = 0x2000_0000u, [3] = 0x3000_0000u, [4] = uint.MaxValue },
            Cycles = 397
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FindColor)),
            find));
        Assert.Equal(pen, find.D[0]);
        Assert.Equal(397, find.Cycles);

        var colorTable = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        var lowColorBits = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits);
        bus.WriteWord(colorTable, 0x0F00);
        bus.WriteWord(lowColorBits, 0x000F);
        bus.WriteWord(colorTable + 2, 0x0F00);
        bus.WriteWord(lowColorBits + 2, 0x0F00);
        bus.WriteByte(colorMap + (uint)GraphicsLayouts.ColorMapType, 0, 0);
        var legacyFind = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [1] = 0xFF00_0000u, [2] = 0, [3] = 0, [4] = 1 },
            Cycles = 399
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FindColor)),
            legacyFind));
        Assert.Equal(0u, legacyFind.D[0]);
        Assert.Equal(399, legacyFind.Cycles);

        var release = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = pen },
            Cycles = 401
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ReleasePen)),
            release));
        Assert.Equal(0u, release.D[0]);
        Assert.Equal(401, release.Cycles);

        // Foreign maps remain transparent for every ownership-sensitive pen
        // vector; the captured native targets receive the original state.
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignMap },
            D = { [0] = uint.MaxValue, [1] = 1, [2] = 2, [3] = 3, [4] = 0 },
            Cycles = 409,
            ProgramCounter = 0x0012_3841
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainPen)),
            foreign));
        Assert.Equal(nativeObtainTarget, foreign.ProgramCounter);
        Assert.Equal(uint.MaxValue, foreign.D[0]);
        Assert.Equal(409, foreign.Cycles);

        var malformedMap = new M68kCpuState { D = { [0] = 2 }, Cycles = 419, ProgramCounter = 0x0012_3847 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            malformedMap));
        var secondMap = malformedMap.D[0];
        var malformedAttach = new M68kCpuState
        {
            A = { [0] = secondMap, [1] = 0xDEAD_0000u },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 421,
            ProgramCounter = 0x0012_384D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AttachPalExtra)),
            malformedAttach));
        Assert.Equal(nativeAttachTarget, malformedAttach.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, malformedAttach.D[0]);
        Assert.Equal(421, malformedAttach.Cycles);

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeColorMap)),
            new M68kCpuState { A = { [0] = colorMap } }));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeColorMap)),
            new M68kCpuState { A = { [0] = secondMap } }));
        Assert.True(frees >= 9);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveReleasePenNoOpSentinelParity()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u },
            D = { [0] = uint.MaxValue },
            Cycles = 431
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u },
            D = { [0] = uint.MaxValue },
            Cycles = 431
        };

        // ReleasePen(-1) is an explicit no-op in the public ABI. It does not
        // inspect the ColorMap, so both the direct host path and the mapped
        // native overlay must claim it even for a foreign/unmapped A0.
        direct.Invoke(directState, (int)GraphicsLvo.ReleasePen);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.ReleasePen));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));

        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(431, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedVideoControlScalarsAndTailChainsForeignOrPointerTags()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint tags = 0x00FD_0000;
        const uint foreignMap = 0x00FE_0000;
        const uint nativeMapTarget = 0x00FE_1601;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            nativeMapTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(tags, new byte[0x100]);
        bus.MapWritableMemory(foreignMap, new byte[0x40]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 2 }, Cycles = 443 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);

        const uint viewPort = 0x00FC_0000;
        const uint modeOutput = tags + 0x80;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, GraphicsModeIds.HiresMode);

        // The default monitor ModeID is zero, but VTAG_VPMODEID_SET(0) is a
        // real override.  Prove the mapped overlay keeps the set/clear state
        // distinct from the CLR form and publishes the zero result through
        // GetVPModeID.
        bus.WriteLong(tags + 0, 0x8000_0021); // VTAG_VPMODEID_SET
        bus.WriteLong(tags + 4, GraphicsModeIds.DefaultMonitor);
        bus.WriteLong(tags + 8, 0);
        var defaultOverride = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xCAFE_0001u },
            Cycles = 445
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            defaultOverride));
        Assert.Equal(0u, defaultOverride.D[0]);

        var zeroMode = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_0002u },
            Cycles = 446
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetVPModeID)),
            zeroMode));
        Assert.Equal(GraphicsModeIds.DefaultMonitor, zeroMode.D[0]);

        bus.WriteLong(tags + 0, 0x8000_0020); // VTAG_VPMODEID_GET
        bus.WriteLong(tags + 4, modeOutput);
        bus.WriteLong(tags + 8, 0);
        var getDefaultOverride = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xCAFE_0003u },
            Cycles = 447
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            getDefaultOverride));
        Assert.Equal(0x8000_0021u, bus.ReadLong(tags));
        Assert.Equal(GraphicsModeIds.DefaultMonitor, bus.ReadLong(tags + 4));
        Assert.Equal(0u, bus.ReadLong(modeOutput));

        bus.WriteLong(tags + 0, 0x8000_0022); // VTAG_VPMODEID_CLR
        bus.WriteLong(tags + 4, 0);
        bus.WriteLong(tags + 8, 0);
        var clearDefaultOverride = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xCAFE_0004u },
            Cycles = 448
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            clearDefaultOverride));

        var fallbackMode = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_0005u },
            Cycles = 448
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetVPModeID)),
            fallbackMode));
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode, fallbackMode.D[0]);

        // Scalar flags and the in-place getter snapshot stay within the owned
        // ColorMap and guest memory, so this native path may publish the
        // transaction.
        bus.WriteLong(tags + 0, 0x8000_0001); // VTAG_CHROMAKEY_SET
        bus.WriteLong(tags + 4, 1);
        bus.WriteLong(tags + 8, 0x8000_000C); // VTAG_NEXTBUF_CM
        bus.WriteLong(tags + 12, tags + 0x40);
        bus.WriteLong(tags + 0x40, 0x8000_0005); // VTAG_BORDERBLANK_SET
        bus.WriteLong(tags + 0x44, 1);
        bus.WriteLong(tags + 0x48, 0x8000_0017); // VTAG_BORDERBLANK_GET
        bus.WriteLong(tags + 0x4C, 0);
        bus.WriteLong(tags + 0x50, 0);

        var scalars = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 449
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            scalars));
        Assert.Equal(0u, scalars.D[0]);
        Assert.Equal(449, scalars.Cycles);
        Assert.Equal((byte)5, bus.ReadByte(colorMap + (uint)GraphicsLayouts.ColorMapFlags));
        Assert.Equal(0x8000_0005u, bus.ReadLong(tags + 0x48));
        Assert.Equal(1u, bus.ReadLong(tags + 0x4C));

        // Batch-list chaining mutates caller-owned TagItems, so the mapped
        // overlay leaves VTAG_BATCH_ITEMS_ADD on the resident vector even
        // when the ColorMap itself belongs to this instance.
        bus.WriteLong(tags + 0, 0x8000_001F); // VTAG_BATCH_ITEMS_ADD
        bus.WriteLong(tags + 4, tags + 0x60);
        bus.WriteLong(tags + 8, 0);
        var batchAdd = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0x1020_3040u },
            Cycles = 453,
            ProgramCounter = 0x0012_3851
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            batchAdd));
        Assert.Equal(nativeMapTarget, batchAdd.ProgramCounter);
        Assert.Equal(0x1020_3040u, batchAdd.D[0]);
        Assert.Equal(453, batchAdd.Cycles);

        // A foreign map is not consumed even when the tag list itself is
        // scalar-safe; the resident vector receives its original registers.
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignMap, [1] = tags },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 457,
            ProgramCounter = 0x0012_3853
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            foreign));
        Assert.Equal(nativeMapTarget, foreign.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, foreign.D[0]);
        Assert.Equal(457, foreign.Cycles);

        // ViewPort and list attachment tags are pointer-bearing provider
        // state, even when the ColorMap itself is instance-owned.
        bus.WriteLong(tags + 0, 0x8000_000B); // VTAG_ATTACH_CM_SET
        bus.WriteLong(tags + 4, 0x00FF_0000);
        bus.WriteLong(tags + 8, 0);
        var pointerTag = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 461,
            ProgramCounter = 0x0012_3859
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            pointerTag));
        Assert.Equal(nativeMapTarget, pointerTag.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, pointerTag.D[0]);
        Assert.Equal(461, pointerTag.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = 0xDEAD_0000u },
            D = { [0] = 0x1122_3344u },
            Cycles = 467,
            ProgramCounter = 0x0012_385F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            malformed));
        Assert.Equal(nativeMapTarget, malformed.ProgramCounter);
        Assert.Equal(0x1122_3344u, malformed.D[0]);
        Assert.Equal(467, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayVideoControlPreflightsReadOnlyQueryOutputBeforeTransaction()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint tags = 0x00FD_0000;
        const uint output = tags + 0x80;
        const uint nativeTarget = 0x00FE_1601;
        const uint sentinel = 0xCAFE_BABEu;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(tags, new byte[0x100]);
        bus.WriteLong(tags, 0x8000_0081); // VC_INTERMEDIATE_UPDATE_QUERY
        bus.WriteLong(tags + 4u, output);
        bus.WriteLong(tags + 8u, 0);
        bus.WriteLong(output, sentinel);
        bus.MapReadOnlyMemory(
            output,
            Enumerable.Range(0, sizeof(uint))
                .Select(offset => bus.ReadByte(output + (uint)offset))
                .ToArray());

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 2 }, Cycles = 521 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);

        var state = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 523,
            ProgramCounter = 0x0012_3861
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.VideoControl)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(523, state.Cycles);
        Assert.Equal(sentinel, bus.ReadLong(output));
    }

    [Fact]
    public void NativeOverlayRoutesOwnedBulkPaletteLoadsAndTailChainsUnassociatedViewPorts()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint viewPort = 0x00FC_0000;
        const uint colors = 0x00FD_0000;
        const uint rgb32 = 0x00FD_0100;
        const uint foreignViewPort = 0x00FE_0000;
        const uint nativeRgb4Target = 0x00FE_1801;
        const uint nativeRgb32Target = 0x00FE_1807;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB4)),
            nativeRgb4Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            nativeRgb32Target);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(colors, new byte[0x200]);
        bus.MapWritableMemory(foreignViewPort, new byte[GraphicsLayouts.ViewPortSize]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 2 }, Cycles = 509 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        bus.WriteWord(colors, 0x0123);
        bus.WriteWord(colors + 2, 0x0ABC);
        var load4 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = colors },
            D = { [0] = 2, [1] = 0xCAFE_BABEu },
            Cycles = 521
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB4)),
            load4));
        Assert.Equal(0u, load4.D[0]);
        Assert.Equal(521, load4.Cycles);
        var colorTable = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        Assert.Equal((ushort)0x0123, (ushort)(bus.ReadWord(colorTable) & 0x0FFF));
        Assert.Equal((ushort)0x0ABC, (ushort)(bus.ReadWord(colorTable + 2) & 0x0FFF));

        var oddLoad4 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = colors + 1u },
            D = { [0] = 1, [1] = 0xCAFE_BABEu },
            Cycles = 523,
            ProgramCounter = 0x0012_386F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB4)),
            oddLoad4));
        Assert.Equal(nativeRgb4Target, oddLoad4.ProgramCounter);
        Assert.Equal(1u, oddLoad4.D[0]);
        Assert.Equal(0xCAFE_BABEu, oddLoad4.D[1]);
        Assert.Equal(523, oddLoad4.Cycles);

        bus.WriteLong(rgb32 + 0, (1u << 16) | 1u);
        bus.WriteLong(rgb32 + 4, 0x4000_0000);
        bus.WriteLong(rgb32 + 8, 0x5000_0000);
        bus.WriteLong(rgb32 + 12, 0x6000_0000);
        bus.WriteLong(rgb32 + 16, 0);
        var load32 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rgb32 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 527
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            load32));
        Assert.Equal(0u, load32.D[0]);
        Assert.Equal(527, load32.Cycles);
        Assert.Equal((ushort)0x0456, (ushort)(bus.ReadWord(colorTable + 2) & 0x0FFF));

        // A readable viewport with no instance-owned ColorMap remains
        // available to resident Kickstart or a provider callback.
        bus.WriteLong(foreignViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0x00FF_0000);
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignViewPort, [1] = colors },
            D = { [0] = 2, [1] = 0x2468_ACEEu },
            Cycles = 533,
            ProgramCounter = 0x0012_3871
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB4)),
            foreign));
        Assert.Equal(nativeRgb4Target, foreign.ProgramCounter);
        Assert.Equal(2u, foreign.D[0]);
        Assert.Equal(533, foreign.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u, [1] = colors },
            D = { [0] = 2 },
            Cycles = 541,
            ProgramCounter = 0x0012_3877
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.LoadRGB32)),
            malformed));
        Assert.Equal(nativeRgb32Target, malformed.ProgramCounter);
        Assert.Equal(2u, malformed.D[0]);
        Assert.Equal(541, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedPerPenPaletteSettersAndTailChainsForeignOrMalformedViewPorts()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint viewPort = 0x00FC_0000;
        const uint foreignViewPort = 0x00FE_0000;
        const uint oddViewPort = 0x00FE_0201;
        const uint nativeRgb4Target = 0x00FE_1901;
        const uint nativeRgb32Target = 0x00FE_1907;
        const uint nativeObtainPenTarget = 0x00FE_190D;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4)),
            nativeRgb4Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32)),
            nativeRgb32Target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainPen)),
            nativeObtainPenTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x8000]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(foreignViewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(oddViewPort, new byte[GraphicsLayouts.ViewPortSize]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var create = new M68kCpuState { D = { [0] = 4 }, Cycles = 547 };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetColorMap)),
            create));
        var colorMap = create.D[0];
        Assert.NotEqual(0u, colorMap);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);
        var colorTable = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapColorTable);
        bus.WriteWord(colorTable + 2, 0xA000);
        bus.WriteWord(colorTable + 4, 0xB000);

        var set4 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 1, [1] = 0x0A, [2] = 0x05, [3] = 0x0F },
            Cycles = 553
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4)),
            set4));
        Assert.Equal(0u, set4.D[0]);
        Assert.Equal(553, set4.Cycles);
        Assert.Equal((ushort)0xAA5F, bus.ReadWord(colorTable + 2));

        var set32 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 2, [1] = 0xB300_0000u, [2] = 0x3400_0000u, [3] = 0x7800_0000u },
            Cycles = 557
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32)),
            set32));
        Assert.Equal(0u, set32.D[0]);
        Assert.Equal(557, set32.Cycles);
        Assert.Equal((ushort)0xBB37, bus.ReadWord(colorTable + 4));

        // A readable viewport linked to a non-owned map remains transparent
        // to this instance, even though the setter arguments are scalar.
        bus.WriteLong(foreignViewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0x00FF_0000);
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignViewPort },
            D = { [0] = 3, [1] = 1, [2] = 2, [3] = 3 },
            Cycles = 563,
            ProgramCounter = 0x0012_3883
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4)),
            foreign));
        Assert.Equal(nativeRgb4Target, foreign.ProgramCounter);
        Assert.Equal(3u, foreign.D[0]);
        Assert.Equal(563, foreign.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u },
            D = { [0] = 2, [1] = 0x1200_0000u, [2] = 0x3400_0000u, [3] = 0x5600_0000u },
            Cycles = 569,
            ProgramCounter = 0x0012_3889
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB32)),
            malformed));
        Assert.Equal(nativeRgb32Target, malformed.ProgramCounter);
        Assert.Equal(2u, malformed.D[0]);
        Assert.Equal(569, malformed.Cycles);

        // An odd ViewPort base is an address-error/native-provider form even
        // when its byte-readable ColorMap field names an owned map.  The
        // mapped gateway must tail-chain before taking the host palette lock
        // or changing the guest ColorTable.
        bus.WriteLong(oddViewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);
        var odd = new M68kCpuState
        {
            A = { [0] = oddViewPort },
            D = { [0] = 2, [1] = 0x0C, [2] = 0x03, [3] = 0x0E },
            Cycles = 571,
            ProgramCounter = 0x0012_3891
        };
        var beforeOdd = bus.ReadWord(colorTable + 2);
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRGB4)),
            odd));
        Assert.Equal(nativeRgb4Target, odd.ProgramCounter);
        Assert.Equal(2u, odd.D[0]);
        Assert.Equal(571, odd.Cycles);
        Assert.Equal(beforeOdd, bus.ReadWord(colorTable + 2));

        // A corrupted public SignalSemaphore prefix must remain available to
        // native/provider recovery.  Direct dispatch declines before pen
        // allocation, while the mapped overlay performs the same ownership
        // check and tail-chains without changing D0 or cycles.
        var attach = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = viewPort },
            Cycles = 577
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AttachPalExtra)),
            attach));
        Assert.Equal(0u, attach.D[0]);
        var paletteExtra = bus.ReadLong(colorMap + (uint)GraphicsLayouts.ColorMapPaletteExtra);
        Assert.NotEqual(0u, paletteExtra);
        bus.WriteByte(
            paletteExtra + (uint)GraphicsLayouts.PaletteExtraSemaphoreNodeType,
            0,
            0);

        var directCorrupt = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = uint.MaxValue, [1] = 0xF000_0000u, [2] = 0, [3] = 0, [4] = 0 },
            Cycles = 579
        };
        services.ObtainPen(directCorrupt);
        Assert.Equal(uint.MaxValue, directCorrupt.D[0]);
        Assert.Equal(579, directCorrupt.Cycles);

        var mappedCorrupt = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = uint.MaxValue, [1] = 0xF000_0000u, [2] = 0, [3] = 0, [4] = 0 },
            Cycles = 581,
            ProgramCounter = 0x0012_3897
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ObtainPen)),
            mappedCorrupt));
        Assert.Equal(nativeObtainPenTarget, mappedCorrupt.ProgramCounter);
        Assert.Equal(uint.MaxValue, mappedCorrupt.D[0]);
        Assert.Equal(581, mappedCorrupt.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedBitMapAllocationAndTailChainsForeignFree()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint foreignBitMap = 0x00FC_0000;
        const uint nativeAllocTarget = 0x00FE_1301;
        const uint nativeFreeTarget = 0x00FE_1307;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            nativeAllocTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeBitMap)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);
        bus.MapWritableMemory(foreignBitMap, new byte[0x40]);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var allocate = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 17, [1] = 3, [2] = 2, [3] = 1u << 0 },
            Cycles = 347
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            allocate));
        var bitMap = allocate.D[0];
        Assert.NotEqual(0u, bitMap);
        Assert.Equal(347, allocate.Cycles);
        Assert.Equal((ushort)4, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal((ushort)3, bus.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)2, bus.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapDepth));
        Assert.NotEqual(0u, bus.ReadLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes));

        var free = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 353
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeBitMap)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(353, free.Cycles);
        Assert.True(frees >= 3);

        var nullFree = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 357,
            ProgramCounter = 0x0012_3831
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeBitMap)),
            nullFree));
        Assert.Equal(0u, nullFree.D[0]);
        Assert.Equal(357, nullFree.Cycles);
        Assert.Equal(0x0012_3831u, nullFree.ProgramCounter);
        Assert.True(frees >= 3);

        // A foreign/native BitMap must remain available to Kickstart rather
        // than being interpreted as a portable allocator-owned envelope.
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignBitMap },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 359,
            ProgramCounter = 0x0012_3835
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeBitMap)),
            foreign));
        Assert.Equal(nativeFreeTarget, foreign.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, foreign.D[0]);
        Assert.Equal(359, foreign.Cycles);

        // A malformed friend is a portable allocation decline, so native
        // Kickstart retains the original AllocBitMap call and register state.
        var malformed = new M68kCpuState
        {
            A = { [0] = foreignBitMap },
            D = { [0] = 17, [1] = 3, [2] = 2, [3] = 0x10u },
            Cycles = 367,
            ProgramCounter = 0x0012_383B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            malformed));
        Assert.Equal(nativeAllocTarget, malformed.ProgramCounter);
        Assert.Equal(17u, malformed.D[0]);
        Assert.Equal(367, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedBitMapScaleAndTailChainsForeignOrMalformedEndpoints()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint bitScaleArgs = 0x00FD_0000;
        const uint foreignBitMap = 0x00FE_0000;
        const uint nativeTarget = 0x00FE_1701;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x20_000]);
        bus.MapWritableMemory(bitScaleArgs, new byte[GraphicsLayouts.BitScaleArgsSize]);
        bus.MapWritableMemory(foreignBitMap, new byte[0x40]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var sourceCreate = new M68kCpuState
        {
            D = { [0] = 16, [1] = 2, [2] = 1, [3] = 1 },
            Cycles = 479
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            sourceCreate));
        var source = sourceCreate.D[0];
        Assert.NotEqual(0u, source);

        var destinationCreate = new M68kCpuState
        {
            D = { [0] = 32, [1] = 4, [2] = 1, [3] = 1 },
            Cycles = 487
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            destinationCreate));
        var destination = destinationCreate.D[0];
        Assert.NotEqual(0u, destination);

        var sourcePlane = bus.ReadLong(source + (uint)GraphicsLayouts.BitMapPlanes);
        bus.WriteByte(sourcePlane, 0x80, 0);
        bus.WriteByte(sourcePlane + 2, 0x01, 0);

        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcX, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcY, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcWidth, 16);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcHeight, 2);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsXSrcFactor, 1);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsYSrcFactor, 1);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestX, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestY, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth, 0xAAAA);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight, 0xBBBB);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsXDestFactor, 2);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsYDestFactor, 2);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcBitMap, source);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestBitMap, destination);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsFlags, 0);

        var scale = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 491
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            scale));
        Assert.Equal(0u, scale.D[0]);
        Assert.Equal(491, scale.Cycles);
        Assert.Equal((ushort)32,
            bus.ReadWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)4,
            bus.ReadWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));

        // A standard-shaped but foreign endpoint is still resident-owned;
        // native overlay admission is based on allocator ownership, not just
        // whether the guest header happens to be readable.
        bus.WriteWord(foreignBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(foreignBitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(foreignBitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(foreignBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcBitMap, foreignBitMap);
        var foreign = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 499,
            ProgramCounter = 0x0012_3865
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            foreign));
        Assert.Equal(nativeTarget, foreign.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, foreign.D[0]);
        Assert.Equal(499, foreign.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xDEAD_0000u },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 503,
            ProgramCounter = 0x0012_386B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, malformed.D[0]);
        Assert.Equal(503, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBitScaleArgsBeforeEndpointDecode()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint bitScaleArgs = 0x00F0_2400;
        const uint nativeTarget = 0x00FE_1713;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(
            bitScaleArgs,
            new byte[GraphicsLayouts.BitScaleArgsSize]);

        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcX, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcY, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcWidth, 8);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcHeight, 2);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsXSrcFactor, 1);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsYSrcFactor, 1);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestX, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestY, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth, 0xAAAA);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight, 0xBBBB);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsXDestFactor, 2);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsYDestFactor, 2);
        bus.WriteLong(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcBitMap,
            0x00FE_0000);
        bus.WriteLong(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestBitMap,
            0x00FE_1000);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsFlags, 0);

        var original = new byte[GraphicsLayouts.BitScaleArgsSize];
        for (var offset = 0; offset < original.Length; offset++)
            original[offset] = bus.ReadByte(bitScaleArgs + (uint)offset);

        // The guest record is byte-readable but not writable; the complete
        // public envelope must remain available to native/provider ownership.
        bus.MapReadOnlyMemory(bitScaleArgs, original);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 811,
            ProgramCounter = 0x0012_3851
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            state));

        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(811, state.Cycles);
        for (var offset = 0; offset < original.Length; offset++)
            Assert.Equal(original[offset], bus.ReadByte(bitScaleArgs + (uint)offset));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyBitScaleDestinationBeforePublication()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint bitScaleArgs = 0x00FD_0000;
        const uint nativeTarget = 0x00FE_1719;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(allocationBase, new byte[0x20_000]);
        bus.MapWritableMemory(bitScaleArgs, new byte[GraphicsLayouts.BitScaleArgsSize]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var sourceCreate = new M68kCpuState
        {
            D = { [0] = 16, [1] = 2, [2] = 1, [3] = 1 },
            Cycles = 467
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            sourceCreate));
        var source = sourceCreate.D[0];
        Assert.NotEqual(0u, source);

        var destinationCreate = new M68kCpuState
        {
            D = { [0] = 32, [1] = 4, [2] = 1, [3] = 1 },
            Cycles = 469
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocBitMap)),
            destinationCreate));
        var destination = destinationCreate.D[0];
        Assert.NotEqual(0u, destination);

        var sourcePlane = bus.ReadLong(source + (uint)GraphicsLayouts.BitMapPlanes);
        var destinationPlane = bus.ReadLong(destination + (uint)GraphicsLayouts.BitMapPlanes);
        bus.WriteByte(sourcePlane, 0x80, 0);
        bus.WriteByte(sourcePlane + 2u, 0x01, 0);
        var destinationBefore = Enumerable.Range(0, 16)
            .Select(offset => bus.ReadByte(destinationPlane + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(destinationPlane, destinationBefore);

        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcX, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcY, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcWidth, 16);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcHeight, 2);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsXSrcFactor, 1);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsYSrcFactor, 1);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestX, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestY, 0);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth, 0xAAAA);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight, 0xBBBB);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsXDestFactor, 2);
        bus.WriteWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsYDestFactor, 2);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsSrcBitMap, source);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestBitMap, destination);
        bus.WriteLong(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsFlags, 0);

        var state = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 473,
            ProgramCounter = 0x0012_3971
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.BitMapScale)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(473, state.Cycles);
        Assert.Equal((ushort)0xAAAA,
            bus.ReadWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)0xBBBB,
            bus.ReadWord(bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        for (var offset = 0; offset < destinationBefore.Length; offset++)
            Assert.Equal(destinationBefore[offset], bus.ReadByte(destinationPlane + (uint)offset));
    }

    [Fact]
    public void NativeOverlayRoutesOwnedGfxNodeLifecycleAndTailChainsForeignOrUnsupportedCalls()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint foreignNode = 0x00FC_0000;
        const uint ownerPointer = 0x00FD_0000;
        const uint nativeNewTarget = 0x00FE_1501;
        const uint nativeFreeTarget = 0x00FE_1507;
        const uint nativeAssociateTarget = 0x00FE_150D;
        const uint nativeLookupTarget = 0x00FE_1513;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            nativeNewTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxFree)),
            nativeFreeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxAssociate)),
            nativeAssociateTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxLookUp)),
            nativeLookupTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        var nativeMonitorList = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            nativeMonitorList + 4u);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            nativeMonitorList);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0,
            0);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0,
            0);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);
        bus.MapWritableMemory(foreignNode, new byte[0x40]);
        bus.MapWritableMemory(ownerPointer, new byte[0x40]);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var nativeDisplayDatabase = bus.ReadLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase);
        Assert.NotEqual(0u, nativeDisplayDatabase);
        Assert.Equal(
            GraphicsDisplayDatabase.NativeDatabaseMagic,
            bus.ReadLong(nativeDisplayDatabase));

        var create = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewPortExtraType },
            Cycles = 401
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            create));
        var node = create.D[0];
        Assert.NotEqual(0u, node);
        Assert.Equal(401, create.Cycles);
        Assert.Equal((byte)18, bus.ReadByte(node + (uint)GraphicsLayouts.ExtendedNodeType));
        Assert.Equal((byte)GraphicsExtendedNodeOperations.ViewPortExtraType,
            bus.ReadByte(node + (uint)GraphicsLayouts.ExtendedNodeSubtype));
        Assert.Equal(
            nativeBase,
            bus.ReadLong(node + (uint)GraphicsLayouts.ExtendedNodeLibrary));

        var associate = new M68kCpuState
        {
            A = { [0] = ownerPointer, [1] = node },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 405
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxAssociate)),
            associate));
        Assert.Equal(0u, associate.D[0]);
        Assert.Equal(405, associate.Cycles);
        Assert.Equal(ownerPointer,
            bus.ReadLong(node + (uint)GraphicsLayouts.ViewPortExtraViewPort));

        var lookup = new M68kCpuState
        {
            A = { [0] = ownerPointer },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 407
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxLookUp)),
            lookup));
        Assert.Equal(node, lookup.D[0]);
        Assert.Equal(407, lookup.Cycles);

        var free = new M68kCpuState
        {
            A = { [0] = node },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 409
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxFree)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(409, free.Cycles);
        Assert.True(frees >= 1);

        // SpecialMonitor has no public backwards-link field, but GfxAssociate
        // still owns an opaque lookup entry for every graphics extended node.
        var specialCreate = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.SpecialMonitorType },
            Cycles = 410
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            specialCreate));
        var specialNode = specialCreate.D[0];
        Assert.NotEqual(0u, specialNode);

        var specialAssociate = new M68kCpuState
        {
            A = { [0] = ownerPointer + 2u, [1] = specialNode },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 411
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxAssociate)),
            specialAssociate));
        Assert.Equal(0u, specialAssociate.D[0]);
        Assert.Equal(411, specialAssociate.Cycles);

        var specialLookup = new M68kCpuState
        {
            A = { [0] = ownerPointer + 2u },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 412
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxLookUp)),
            specialLookup));
        Assert.Equal(specialNode, specialLookup.D[0]);
        Assert.Equal(412, specialLookup.Cycles);

        var specialFree = new M68kCpuState
        {
            A = { [0] = specialNode },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 413
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxFree)),
            specialFree));
        Assert.Equal(0u, specialFree.D[0]);
        Assert.Equal(413, specialFree.Cycles);
        Assert.True(frees >= 2);

        var malformedNode = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewExtraType },
            Cycles = 413
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            malformedNode));
        var ownedMalformedNode = malformedNode.D[0];
        Assert.NotEqual(0u, ownedMalformedNode);
        bus.WriteByte(
            ownedMalformedNode + (uint)GraphicsLayouts.ExtendedNodeSubsystem,
            0,
            0);
        var malformedFree = new M68kCpuState
        {
            A = { [0] = ownedMalformedNode },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 415,
            ProgramCounter = 0x0012_383F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxFree)),
            malformedFree));
        Assert.Equal(nativeFreeTarget, malformedFree.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, malformedFree.D[0]);
        Assert.Equal(415, malformedFree.Cycles);
        bus.WriteByte(
            ownedMalformedNode + (uint)GraphicsLayouts.ExtendedNodeSubsystem,
            2,
            0);
        var retryFree = new M68kCpuState
        {
            A = { [0] = ownedMalformedNode },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 417
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxFree)),
            retryFree));
        Assert.Equal(0u, retryFree.D[0]);
        Assert.Equal(417, retryFree.Cycles);
        Assert.True(frees >= 2);

        // A foreign or already-freed node remains owned by the resident
        // Kickstart implementation; the overlay must preserve its ABI state.
        var foreign = new M68kCpuState
        {
            A = { [0] = foreignNode },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 419,
            ProgramCounter = 0x0012_3841
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxFree)),
            foreign));
        Assert.Equal(nativeFreeTarget, foreign.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, foreign.D[0]);
        Assert.Equal(419, foreign.Cycles);

        var foreignAssociate = new M68kCpuState
        {
            A = { [0] = ownerPointer, [1] = foreignNode },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 421,
            ProgramCounter = 0x0012_3843
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxAssociate)),
            foreignAssociate));
        Assert.Equal(nativeAssociateTarget, foreignAssociate.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, foreignAssociate.D[0]);
        Assert.Equal(421, foreignAssociate.Cycles);

        var malformedLookup = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 423,
            ProgramCounter = 0x0012_3849
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxLookUp)),
            malformedLookup));
        Assert.Equal(0u, malformedLookup.D[0]);
        Assert.Equal(423, malformedLookup.Cycles);

        // A non-null key that is absent from this compatibility registry may
        // still be associated by the resident/provider implementation.  The
        // overlay must leave that lookup available instead of fabricating a
        // successful zero result.
        var foreignLookup = new M68kCpuState
        {
            A = { [0] = foreignNode },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 425,
            ProgramCounter = 0x0012_384B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxLookUp)),
            foreignLookup));
        Assert.Equal(nativeLookupTarget, foreignLookup.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, foreignLookup.D[0]);
        Assert.Equal(425, foreignLookup.Cycles);

        var unsupported = new M68kCpuState
        {
            D = { [0] = 5u },
            Cycles = 431,
            ProgramCounter = 0x0012_3847
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            unsupported));
        Assert.Equal(nativeNewTarget, unsupported.ProgramCounter);
        Assert.Equal(5u, unsupported.D[0]);
        Assert.Equal(431, unsupported.Cycles);
    }

    [Fact]
    public void NativeOverlayRebindsPortableRegistriesWhenGfxBaseEnvelopeAppearsAfterInstall()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint allocationBase = 0x00FB_0000;
        const uint nativeNewTarget = 0x00FE_1521;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            nativeNewTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
        bus.MapWritableMemory(allocationBase, new byte[0x4000]);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            });

        // The ROM gateway table may be installed before Exec has finished
        // constructing the native MonitorList envelope.  Keep the portable
        // owner on the compatibility base until that envelope is proven.
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        Assert.Equal(
            0u,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));

        var before = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewPortExtraType },
            Cycles = 601
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            before));
        var compatibilityNode = before.D[0];
        Assert.NotEqual(0u, compatibilityNode);
        Assert.Equal(0u, bus.ReadLong(
            compatibilityNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));

        var nativeMonitorList = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            nativeMonitorList + 4u);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            nativeMonitorList);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0,
            0);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0,
            0);

        // Idempotent installation is the native-cutover retry boundary.  It
        // must rebind the portable registries and publish their database even
        // though the ROM gateway table is already active.
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        var nativeDisplayDatabase = bus.ReadLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase);
        Assert.NotEqual(0u, nativeDisplayDatabase);
        Assert.Equal(
            GraphicsDisplayDatabase.NativeDatabaseMagic,
            bus.ReadLong(nativeDisplayDatabase));

        var after = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewPortExtraType },
            Cycles = 603
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GfxNew)),
            after));
        var nativeNode = after.D[0];
        Assert.NotEqual(0u, nativeNode);
        Assert.Equal(nativeBase, bus.ReadLong(
            nativeNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));
    }

    [Fact]
    public void NativeOverlayRoutesSimpleSpritePoolAndTailChainsMalformedRequests()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint sprite = 0x00FA_0000;
        const uint newData = 0x00FA_0100;
        const uint nativeGetTarget = 0x00FB_1601;
        const uint nativeMoveTarget = 0x00FB_1607;
        const uint nativeChangeTarget = 0x00FB_160D;
        const uint nativeFreeTarget = 0x00FB_1613;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetSprite)),
            nativeGetTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.MoveSprite)),
            nativeMoveTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ChangeSprite)),
            nativeChangeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSprite)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(sprite, new byte[GraphicsLayouts.SimpleSpriteSize]);
        bus.MapWritableMemory(newData, new byte[0x20]);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteHeight, 1);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var get = new M68kCpuState
        {
            A = { [0] = sprite },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 503
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetSprite)),
            get));
        Assert.Equal(0u, get.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(503, get.Cycles);

        var move = new M68kCpuState
        {
            A = { [0] = 0, [1] = sprite },
            D = { [0] = 12u, [1] = 34u },
            Cycles = 505
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.MoveSprite)),
            move));
        Assert.Equal(0u, move.D[0]);
        Assert.Equal((ushort)12,
            bus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)34,
            bus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        Assert.Equal(505, move.Cycles);

        var change = new M68kCpuState
        {
            A = { [0] = 0, [1] = sprite, [2] = newData },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 507
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ChangeSprite)),
            change));
        Assert.Equal(0u, change.D[0]);
        Assert.Equal(newData,
            bus.ReadLong(sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal(507, change.Cycles);

        var free = new M68kCpuState
        {
            D = { [0] = 0 },
            Cycles = 509
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSprite)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(509, free.Cycles);

        var malformedGet = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 521,
            ProgramCounter = 0x0012_3851
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetSprite)),
            malformedGet));
        Assert.Equal(nativeGetTarget, malformedGet.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, malformedGet.D[0]);
        Assert.Equal(521, malformedGet.Cycles);

        var malformedMove = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0 },
            D = { [0] = 0xA5A5_5A5Au, [1] = 10u },
            Cycles = 522,
            ProgramCounter = 0x0012_3855
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.MoveSprite)),
            malformedMove));
        Assert.Equal(nativeMoveTarget, malformedMove.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformedMove.D[0]);
        Assert.Equal(522, malformedMove.Cycles);

        var malformedFree = new M68kCpuState
        {
            D = { [0] = 8u },
            Cycles = 523,
            ProgramCounter = 0x0012_3857
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSprite)),
            malformedFree));
        Assert.Equal(nativeFreeTarget, malformedFree.ProgramCounter);
        Assert.Equal(8u, malformedFree.D[0]);
        Assert.Equal(523, malformedFree.Cycles);
    }

    [Fact]
    public void NativeOverlayLeavesUnownedFreeSpriteToKickstart()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint nativeFreeTarget = 0x00FB_1621;
        const uint originalD0 = 0x1357_0000u;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSprite)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        // Slot zero was never acquired through this graphics instance.  A
        // resident/provider owner may still have it reserved, so the mapped
        // overlay must tail-chain instead of claiming a successful release.
        var state = new M68kCpuState
        {
            D = { [0] = originalD0 },
            Cycles = 527,
            ProgramCounter = 0x0012_3861
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSprite)),
            state));
        Assert.Equal(nativeFreeTarget, state.ProgramCounter);
        Assert.Equal(originalD0, state.D[0]);
        Assert.Equal(527, state.Cycles);
    }

    [Fact]
    public void GetSpritePreservesReadOnlyNumberAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FB_1651;
        const uint sprite = 0x00FA_0000;
        const ushort originalNumber = 0xBEEF;
        const uint originalD0 = 0x1357_9BDFu;

        static void PrepareBus(
            AmigaBus bus,
            uint imageBase,
            uint nativeBase,
            uint nativeTarget,
            uint sprite,
            ushort originalNumber)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.GetSprite)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(nativeBase, new byte[0xA0]);
            bus.MapWritableMemory(sprite, new byte[GraphicsLayouts.SimpleSpriteSize]);
            bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteNum, originalNumber);
            bus.MapReadOnlyMemory(
                sprite + (uint)GraphicsLayouts.SimpleSpriteNum,
                Enumerable.Range(0, sizeof(ushort))
                    .Select(offset => bus.ReadByte(
                        sprite + (uint)GraphicsLayouts.SimpleSpriteNum +
                        (uint)offset))
                    .ToArray());
        }

        var directBus = new AmigaBus();
        PrepareBus(
            directBus,
            imageBase,
            nativeBase,
            nativeTarget,
            sprite,
            originalNumber);
        using (var direct = CreateHostGraphicsServices(
                   new HostGuestMemory(directBus)))
        {
            var state = new M68kCpuState
            {
                A = { [0] = sprite },
                D = { [0] = originalD0 },
                Cycles = 79
            };

            direct.GetSprite(state);
            Assert.Equal(unchecked((uint)-1), state.D[0]);
            Assert.Equal(79, state.Cycles);
            Assert.Equal(
                originalNumber,
                directBus.ReadWord(
                    sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        }

        var mappedBus = new AmigaBus();
        PrepareBus(
            mappedBus,
            imageBase,
            nativeBase,
            nativeTarget,
            sprite,
            originalNumber);
        using (var mapped = CreateHostGraphicsServices(
                   new HostGuestMemory(mappedBus)))
        {
            Assert.True(mapped.InstallKickstartRomOverlay(nativeBase));
            var state = new M68kCpuState
            {
                A = { [0] = sprite },
                D = { [0] = originalD0 },
                Cycles = 83,
                ProgramCounter = 0x0012_3A51
            };

            Assert.True(mappedBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.GetSprite)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(originalD0, state.D[0]);
            Assert.Equal(83, state.Cycles);
            Assert.Equal(
                originalNumber,
                mappedBus.ReadWord(
                    sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        }
    }

    [Fact]
    public void MoveSpritePreservesReadOnlySimpleSpriteAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FB_1621;
        const uint viewPort = 0x200;
        const uint sprite = 0x300;
        var xAddress = sprite + (uint)GraphicsLayouts.SimpleSpriteX;

        static void PrepareBus(
            AmigaBus bus,
            uint imageBase,
            uint nativeBase,
            uint nativeTarget,
            uint viewPort,
            uint sprite)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.MoveSprite)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
            bus.MapWritableMemory(sprite, new byte[GraphicsLayouts.SimpleSpriteSize]);
            bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteHeight, 1);
            bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteX, 5);
            bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteY, 6);
            bus.WriteLong(sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData, 0);
            bus.MapReadOnlyMemory(
                sprite + (uint)GraphicsLayouts.SimpleSpriteX,
                Enumerable.Range(0, sizeof(ushort))
                    .Select(offset => bus.ReadByte(
                        sprite + (uint)GraphicsLayouts.SimpleSpriteX +
                        (uint)offset))
                    .ToArray());
        }

        var directBus = new AmigaBus();
        PrepareBus(
            directBus,
            imageBase,
            nativeBase,
            nativeTarget,
            viewPort,
            sprite);
        var directMoveCalls = 0;
        using (var direct = CreateHostGraphicsServices(
                   new HostGuestMemory(directBus),
                   moveSprite: (_, _, _, _) => directMoveCalls++))
        {
            var state = new M68kCpuState
            {
                A = { [0] = viewPort, [1] = sprite },
                D = { [0] = 0xCAFE_BABEu, [1] = 34u },
                Cycles = 71
            };

            direct.Invoke(state, (int)GraphicsLvo.MoveSprite);
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(71, state.Cycles);
            Assert.Equal(0, directMoveCalls);
            Assert.Equal((ushort)5, directBus.ReadWord(xAddress));
            Assert.Equal((ushort)6,
                directBus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        }

        var mappedBus = new AmigaBus();
        PrepareBus(
            mappedBus,
            imageBase,
            nativeBase,
            nativeTarget,
            viewPort,
            sprite);
        var mappedMoveCalls = 0;
        using (var mapped = CreateHostGraphicsServices(
                   new HostGuestMemory(mappedBus),
                   moveSprite: (_, _, _, _) => mappedMoveCalls++))
        {
            Assert.True(mapped.InstallKickstartRomOverlay(nativeBase));
            var state = new M68kCpuState
            {
                A = { [0] = viewPort, [1] = sprite },
                D = { [0] = 0x1357_9BDFu, [1] = 34u },
                Cycles = 73,
                ProgramCounter = 0x0012_3A11
            };

            Assert.True(mappedBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.MoveSprite)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(73, state.Cycles);
            Assert.Equal(0, mappedMoveCalls);
            Assert.Equal((ushort)5, mappedBus.ReadWord(xAddress));
            Assert.Equal((ushort)6,
                mappedBus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        }
    }

    [Fact]
    public void ChangeSpritePreservesReadOnlyAssociationAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FB_1631;
        const uint sprite = 0x300;
        const uint oldData = 0x400;
        const uint newData = 0x500;
        var association = sprite +
            (uint)GraphicsLayouts.SimpleSpritePosCtlData;

        static void PrepareBus(
            AmigaBus bus,
            uint imageBase,
            uint nativeBase,
            uint nativeTarget,
            uint sprite,
            uint oldData,
            uint newData)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.ChangeSprite)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(nativeBase, new byte[0xA0]);
            bus.MapWritableMemory(sprite, new byte[GraphicsLayouts.SimpleSpriteSize]);
            bus.MapWritableMemory(newData, new byte[0x20]);
            bus.MapWritableMemory(oldData, new byte[0x20]);
            bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteHeight, 1);
            var association = sprite +
                (uint)GraphicsLayouts.SimpleSpritePosCtlData;
            bus.WriteLong(association, oldData);
            bus.MapReadOnlyMemory(
                association,
                Enumerable.Range(0, sizeof(uint))
                    .Select(offset => bus.ReadByte(association + (uint)offset))
                    .ToArray());
        }

        var directBus = new AmigaBus();
        PrepareBus(
            directBus,
            imageBase,
            nativeBase,
            nativeTarget,
            sprite,
            oldData,
            newData);
        var directChangeCalls = 0;
        using (var direct = CreateHostGraphicsServices(
                   new HostGuestMemory(directBus),
                   changeSprite: (_, _, _) => directChangeCalls++))
        {
            var state = new M68kCpuState
            {
                A = { [0] = 0, [1] = sprite, [2] = newData },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 79
            };

            direct.Invoke(state, (int)GraphicsLvo.ChangeSprite);
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(79, state.Cycles);
            Assert.Equal(0, directChangeCalls);
            Assert.Equal(oldData, directBus.ReadLong(association));
        }

        var mappedBus = new AmigaBus();
        PrepareBus(
            mappedBus,
            imageBase,
            nativeBase,
            nativeTarget,
            sprite,
            oldData,
            newData);
        var mappedChangeCalls = 0;
        using (var mapped = CreateHostGraphicsServices(
                   new HostGuestMemory(mappedBus),
                   changeSprite: (_, _, _) => mappedChangeCalls++))
        {
            Assert.True(mapped.InstallKickstartRomOverlay(nativeBase));
            var state = new M68kCpuState
            {
                A = { [0] = 0, [1] = sprite, [2] = newData },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 83,
                ProgramCounter = 0x0012_3A21
            };

            Assert.True(mappedBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.ChangeSprite)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(83, state.Cycles);
            Assert.Equal(0, mappedChangeCalls);
            Assert.Equal(oldData, mappedBus.ReadLong(association));
        }
    }

    [Fact]
    public void ChangeExtSpritePreservesReadOnlyOldEnvelopeAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FB_1641;
        const uint oldSprite = 0x300;
        const uint newSprite = 0x400;
        const uint oldData = 0x500;
        const uint newData = 0x600;
        var oldAssociation = oldSprite +
            (uint)GraphicsLayouts.SimpleSpritePosCtlData;

        static void PrepareBus(
            AmigaBus bus,
            uint imageBase,
            uint nativeBase,
            uint nativeTarget,
            uint oldSprite,
            uint newSprite,
            uint oldData,
            uint newData)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.ChangeExtSpriteA)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(nativeBase, new byte[0xA0]);
            bus.MapWritableMemory(oldSprite, new byte[GraphicsLayouts.ExtSpriteSize]);
            bus.MapWritableMemory(newSprite, new byte[GraphicsLayouts.ExtSpriteSize]);
            bus.MapWritableMemory(oldData, new byte[0x20]);
            bus.MapWritableMemory(newData, new byte[0x20]);

            bus.WriteLong(
                oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
                oldData);
            bus.WriteWord(
                oldSprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
                1);
            bus.WriteWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteX, 3);
            bus.WriteWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteY, 4);
            bus.WriteWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteNum, 0);
            bus.WriteWord(oldSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth, 1);

            bus.WriteLong(
                newSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
                newData);
            bus.WriteWord(
                newSprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
                1);
            bus.WriteWord(newSprite + (uint)GraphicsLayouts.SimpleSpriteX, 7);
            bus.WriteWord(newSprite + (uint)GraphicsLayouts.SimpleSpriteY, 8);
            bus.WriteWord(newSprite + (uint)GraphicsLayouts.SimpleSpriteNum, 1);
            bus.WriteWord(newSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth, 1);

            bus.MapReadOnlyMemory(
                oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
                Enumerable.Range(0, sizeof(uint))
                    .Select(offset => bus.ReadByte(
                        oldSprite +
                        (uint)GraphicsLayouts.SimpleSpritePosCtlData +
                        (uint)offset))
                    .ToArray());
        }

        var directBus = new AmigaBus();
        PrepareBus(
            directBus,
            imageBase,
            nativeBase,
            nativeTarget,
            oldSprite,
            newSprite,
            oldData,
            newData);
        var directProviderCalls = 0;
        using (var direct = CreateHostGraphicsServices(
                   new HostGuestMemory(directBus),
                   tryChangeExtSprite: (_, _, _, _, _, _, _) =>
                   {
                       directProviderCalls++;
                       return (true, true);
                   }))
        {
            var state = new M68kCpuState
            {
                A = { [0] = 0, [1] = oldSprite, [2] = newSprite },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 89
            };

            direct.Invoke(state, (int)GraphicsLvo.ChangeExtSpriteA);
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(89, state.Cycles);
            Assert.Equal(0, directProviderCalls);
            Assert.Equal(oldData, directBus.ReadLong(oldAssociation));
            Assert.Equal((ushort)3,
                directBus.ReadWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteX));
        }

        var mappedBus = new AmigaBus();
        PrepareBus(
            mappedBus,
            imageBase,
            nativeBase,
            nativeTarget,
            oldSprite,
            newSprite,
            oldData,
            newData);
        var mappedProviderCalls = 0;
        using (var mapped = CreateHostGraphicsServices(
                   new HostGuestMemory(mappedBus),
                   tryChangeExtSprite: (_, _, _, _, _, _, _) =>
                   {
                       mappedProviderCalls++;
                       return (true, true);
                   }))
        {
            Assert.True(mapped.InstallKickstartRomOverlay(nativeBase));
            var state = new M68kCpuState
            {
                A = { [0] = 0, [1] = oldSprite, [2] = newSprite },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 97,
                ProgramCounter = 0x0012_3A31
            };

            Assert.True(mappedBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.ChangeExtSpriteA)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(97, state.Cycles);
            Assert.Equal(0, mappedProviderCalls);
            Assert.Equal(oldData, mappedBus.ReadLong(oldAssociation));
            Assert.Equal((ushort)3,
                mappedBus.ReadWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteX));
        }
    }

    [Fact]
    public void NativeOverlayDefersProviderOwnedSpriteAndBobPublication()
    {
        const uint imageBase = 0x00F0_F000;
        const uint nativeBase = 0x00F1_0000;
        const uint nativeMoveTarget = 0x00F2_1611;
        const uint nativeRemBobTarget = 0x00F2_1617;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.MoveSprite)),
            nativeMoveTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemIBob)),
            nativeRemBobTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            moveSprite: static (_, _, _, _) => { },
            drawGList: static (_, _) => { },
            doCollision: static _ => { },
            remIBob: static (_, _, _) => { });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var move = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0 },
            D = { [0] = 12u, [1] = 34u },
            Cycles = 531,
            ProgramCounter = 0x0012_3891
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.MoveSprite)),
            move));
        Assert.Equal(nativeMoveTarget, move.ProgramCounter);
        Assert.Equal(12u, move.D[0]);
        Assert.Equal(531, move.Cycles);

        var remBob = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0, [2] = 0 },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 533,
            ProgramCounter = 0x0012_3897
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemIBob)),
            remBob));
        Assert.Equal(nativeRemBobTarget, remBob.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, remBob.D[0]);
        Assert.Equal(533, remBob.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesExtendedSpriteQueryAndOwnedFreeWithTailChainBoundaries()
    {
        const uint imageBase = 0x00F2_F000;
        const uint nativeBase = 0x00F3_0000;
        const uint bitMap = 0x00F4_0000;
        const uint plane0 = 0x00F4_0100;
        const uint plane1 = 0x00F4_0110;
        const uint allocationBase = 0x00F5_0000;
        const uint foreignSprite = 0x00F6_0000;
        const uint nativeAllocTarget = 0x00F7_15F5;
        const uint nativeGetTarget = 0x00F7_1601;
        const uint nativeChangeTarget = 0x00F7_1607;
        const uint nativeFreeTarget = 0x00F7_160D;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocSpriteDataA)),
            nativeAllocTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            nativeGetTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ChangeExtSpriteA)),
            nativeChangeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(bitMap, new byte[0x40]);
        bus.MapWritableMemory(plane0, new byte[0x10]);
        bus.MapWritableMemory(plane1, new byte[0x10]);
        bus.MapWritableMemory(allocationBase, new byte[0x1000]);
        bus.MapWritableMemory(foreignSprite, new byte[GraphicsLayouts.ExtSpriteSize]);

        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1);
        bus.WriteByte(plane0, 0x80, 0);
        bus.WriteByte(plane1, 0x40, 0);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var allocate = new M68kCpuState
        {
            A = { [1] = 0, [2] = bitMap },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 601
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocSpriteDataA)),
            allocate));
        var extSprite = allocate.D[0];
        Assert.NotEqual(0u, extSprite);
        Assert.Equal(601, allocate.Cycles);

        var allocateSecond = new M68kCpuState
        {
            A = { [1] = 0, [2] = bitMap },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 603
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocSpriteDataA)),
            allocateSecond));
        var secondSprite = allocateSecond.D[0];
        Assert.NotEqual(0u, secondSprite);
        Assert.Equal(603, allocateSecond.Cycles);

        var get = new M68kCpuState
        {
            A = { [0] = extSprite, [1] = 0 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 607
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            get));
        Assert.Equal(0u, get.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(extSprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(607, get.Cycles);

        var change = new M68kCpuState
        {
            A = { [0] = 0, [1] = extSprite, [2] = secondSprite, [3] = 0 },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 609
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ChangeExtSpriteA)),
            change));
        Assert.Equal(1u, change.D[0]);
        Assert.Equal(609, change.Cycles);
        Assert.Equal(
            bus.ReadLong(secondSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData),
            bus.ReadLong(extSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));

        var malformedAlloc = new M68kCpuState
        {
            A = { [1] = 0xDEAD_0000u, [2] = 0 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 611,
            ProgramCounter = 0x0012_385B
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocSpriteDataA)),
            malformedAlloc));
        Assert.Equal(nativeAllocTarget, malformedAlloc.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformedAlloc.D[0]);
        Assert.Equal(611, malformedAlloc.Cycles);

        var malformedChange = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0, [2] = 0, [3] = 0 },
            D = { [0] = 0x5A5A_A5A5u },
            Cycles = 612,
            ProgramCounter = 0x0012_385D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ChangeExtSpriteA)),
            malformedChange));
        Assert.Equal(nativeChangeTarget, malformedChange.ProgramCounter);
        Assert.Equal(0x5A5A_A5A5u, malformedChange.D[0]);
        Assert.Equal(612, malformedChange.Cycles);

        var free = new M68kCpuState
        {
            A = { [2] = extSprite },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 613
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(613, free.Cycles);
        Assert.True(frees >= 2);

        var freeSecond = new M68kCpuState
        {
            A = { [2] = secondSprite },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 615
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            freeSecond));
        Assert.Equal(0u, freeSecond.D[0]);
        Assert.Equal(615, freeSecond.Cycles);
        Assert.True(frees >= 4);

        var foreignFree = new M68kCpuState
        {
            A = { [2] = foreignSprite },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 619,
            ProgramCounter = 0x0012_3861
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            foreignFree));
        Assert.Equal(nativeFreeTarget, foreignFree.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, foreignFree.D[0]);
        Assert.Equal(619, foreignFree.Cycles);

        var nullFree = new M68kCpuState
        {
            A = { [2] = 0 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 621
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            nullFree));
        Assert.Equal(0u, nullFree.D[0]);
        Assert.Equal(621, nullFree.Cycles);

        var malformedGet = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 623,
            ProgramCounter = 0x0012_3867
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            malformedGet));
        Assert.Equal(nativeGetTarget, malformedGet.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformedGet.D[0]);
        Assert.Equal(623, malformedGet.Cycles);
    }

    [Fact]
    public void AllocSpriteDataRemainsProviderOwnedForRtgBitmapAcrossDirectAndMappedDispatch()
    {
        const uint imageBase = 0x00F8_F000;
        const uint nativeBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FB_1651;
        const uint bitMap = 0x300;
        const uint plane0 = 0x400;
        const uint plane1 = 0x410;
        const uint allocationBase = 0x500;

        static void PrepareBus(
            AmigaBus bus,
            uint imageBase,
            uint nativeBase,
            uint nativeTarget,
            uint bitMap,
            uint plane0,
            uint plane1,
            uint allocationBase)
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.AllocSpriteDataA)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(nativeBase, new byte[0xA0]);
            bus.MapWritableMemory(bitMap, new byte[0x40]);
            bus.MapWritableMemory(plane0, new byte[0x10]);
            bus.MapWritableMemory(plane1, new byte[0x10]);
            bus.MapWritableMemory(allocationBase, new byte[0x1000]);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
            bus.WriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
                plane1);
        }

        var directBus = new AmigaBus();
        PrepareBus(
            directBus,
