        var directAllocations = 0;
        using (var direct = CreateHostGraphicsServices(
                   new HostGuestMemory(directBus),
                   allocateMemory: (bytes, _) =>
                   {
                       directAllocations++;
                       return allocationBase;
                   },
                   isRtgBitMap: address => address == bitMap))
        {
            var state = new M68kCpuState
            {
                A = { [2] = bitMap },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 101
            };

            direct.Invoke(state, (int)GraphicsLvo.AllocSpriteDataA);
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(101, state.Cycles);
            Assert.Equal(0, directAllocations);
        }

        var mappedBus = new AmigaBus();
        PrepareBus(
            mappedBus,
            imageBase,
            nativeBase,
            nativeTarget,
            bitMap,
            plane0,
            plane1,
            allocationBase);
        var mappedAllocations = 0;
        using (var mapped = CreateHostGraphicsServices(
                   new HostGuestMemory(mappedBus),
                   allocateMemory: (bytes, _) =>
                   {
                       mappedAllocations++;
                       return allocationBase;
                   },
                   isRtgBitMap: address => address == bitMap))
        {
            Assert.True(mapped.InstallKickstartRomOverlay(nativeBase));
            var state = new M68kCpuState
            {
                A = { [2] = bitMap },
                D = { [0] = 0x1357_9BDFu },
                Cycles = 103,
                ProgramCounter = 0x0012_3A41
            };

            Assert.True(mappedBus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)nativeBase +
                    (int)GraphicsLvo.AllocSpriteDataA)),
                state));
            Assert.Equal(nativeTarget, state.ProgramCounter);
            Assert.Equal(0x1357_9BDFu, state.D[0]);
            Assert.Equal(103, state.Cycles);
            Assert.Equal(0, mappedAllocations);
        }
    }

    [Fact]
    public void NativeOverlayRoutesAttachedExtendedSpritePairAndTailChainsMalformedPair()
    {
        const uint imageBase = 0x00F0_F000;
        const uint nativeBase = 0x00F1_0000;
        const uint bitMap = 0x00F2_0000;
        const uint plane0 = 0x00F2_0100;
        const uint plane1 = 0x00F2_0110;
        const uint allocationBase = 0x00F3_0000;
        const uint tags = 0x00F4_0000;
        const uint nativeGetTarget = 0x00F5_2201;
        const uint nativeFreeTarget = 0x00F5_2207;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            nativeGetTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(bitMap, new byte[0x40]);
        bus.MapWritableMemory(plane0, new byte[0x10]);
        bus.MapWritableMemory(plane1, new byte[0x10]);
        bus.MapWritableMemory(allocationBase, new byte[0x1000]);
        bus.MapWritableMemory(tags, new byte[0x20]);

        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        bus.WriteByte(plane0, 0x80, 0);
        bus.WriteByte(plane1, 0x40, 0);

        var nextAllocation = allocationBase;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => { });
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var firstAllocate = new M68kCpuState { A = { [1] = 0, [2] = bitMap } };
        var secondAllocate = new M68kCpuState { A = { [1] = 0, [2] = bitMap } };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocSpriteDataA)),
            firstAllocate));
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AllocSpriteDataA)),
            secondAllocate));
        var first = firstAllocate.D[0];
        var second = secondAllocate.D[0];
        Assert.NotEqual(0u, first);
        Assert.NotEqual(0u, second);

        bus.WriteLong(tags, GraphicsLayouts.GsTagAttached);
        bus.WriteLong(tags + 4u, second);
        bus.WriteLong(tags + 8u, 0);
        var get = new M68kCpuState
        {
            A = { [0] = first, [1] = tags },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 701
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            get));
        Assert.Equal(0u, get.D[0]);
        Assert.Equal(701, get.Cycles);
        Assert.Equal((ushort)0, bus.ReadWord(first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, bus.ReadWord(second + (uint)GraphicsLayouts.SimpleSpriteNum));

        // Distinct but overlapping ExtSprite envelopes must not be claimed by
        // the portable overlay: leave the captured Kickstart vector and all
        // pair state untouched for the native/provider owner.
        bus.WriteLong(tags + 4u, first + 2u);
        var overlapping = new M68kCpuState
        {
            A = { [0] = first, [1] = tags },
            D = { [0] = 0xACED_1234u },
            Cycles = 702,
            ProgramCounter = 0x0012_39FE
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            overlapping));
        Assert.Equal(nativeGetTarget, overlapping.ProgramCounter);
        Assert.Equal(0xACED_1234u, overlapping.D[0]);
        Assert.Equal(702, overlapping.Cycles);
        Assert.Equal((ushort)0, bus.ReadWord(first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, bus.ReadWord(second + (uint)GraphicsLayouts.SimpleSpriteNum));

        // An odd attached envelope is not portable-owned; the original
        // Kickstart JMP remains the native/provider fallback.
        bus.WriteLong(tags + 4u, 0x00F4_0001u);
        var malformed = new M68kCpuState
        {
            A = { [0] = first, [1] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 703,
            ProgramCounter = 0x0012_3A01
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetExtSpriteA)),
            malformed));
        Assert.Equal(nativeGetTarget, malformed.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, malformed.D[0]);
        Assert.Equal(703, malformed.Cycles);

        var free = new M68kCpuState
        {
            A = { [2] = first },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 705
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(705, free.Cycles);

        var foreignFree = new M68kCpuState
        {
            A = { [2] = 0x00F6_0000u },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 707,
            ProgramCounter = 0x0012_3A07
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeSpriteData)),
            foreignFree));
        Assert.Equal(nativeFreeTarget, foreignFree.ProgramCounter);
        Assert.Equal(0xDEAD_BEEFu, foreignFree.D[0]);
        Assert.Equal(707, foreignFree.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesGuestGelsMaintenanceAndTailChainsMalformedStructures()
    {
        const uint imageBase = 0x00E8_F000;
        const uint nativeBase = 0x00E9_0000;
        const uint guestBase = 0x00EA_0000;
        const uint head = guestBase + 0x000;
        const uint tail = guestBase + 0x100;
        const uint gelsInfo = guestBase + 0x200;
        const uint collisionTable = guestBase + 0x300;
        const uint rastPort = guestBase + 0x400;
        const uint sprite = guestBase + 0x500;
        const uint imageData = guestBase + 0x700;
        const uint borderLine = guestBase + 0x780;
        const uint collisionMask = guestBase + 0x800;
        const uint nativeInitGelsTarget = 0x00EB_1701;
        const uint nativeSetCollisionTarget = 0x00EB_1707;
        const uint nativeInitMasksTarget = 0x00EB_170D;
        const uint nativeAddVSpriteTarget = 0x00EB_1713;
        const uint nativeRemVSpriteTarget = 0x00EB_1719;
        const uint nativeSortGListTarget = 0x00EB_171F;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGels)),
            nativeInitGelsTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetCollision)),
            nativeSetCollisionTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitMasks)),
            nativeInitMasksTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddVSprite)),
            nativeAddVSpriteTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemVSprite)),
            nativeRemVSpriteTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SortGList)),
            nativeSortGListTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(guestBase, new byte[0x1000]);

        bus.WriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            collisionTable);
        bus.WriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
            gelsInfo);
        bus.WriteWord(
            sprite + (uint)GraphicsLayouts.VSpriteFlags,
            (ushort)(GraphicsLayouts.VSpriteFlag | GraphicsLayouts.VSpriteSystemFlags));
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 20);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var init = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 701
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGels)),
            init));
        Assert.Equal(0u, init.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(701, init.Cycles);

        var collision = new M68kCpuState
        {
            A = { [0] = 0x1234_5678u, [1] = gelsInfo },
            D = { [0] = 2u },
            Cycles = 703
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetCollision)),
            collision));
        Assert.Equal(0u, collision.D[0]);
        Assert.Equal(0x1234_5678u, bus.ReadLong(collisionTable + 8));
        Assert.Equal(703, collision.Cycles);

        var add = new M68kCpuState
        {
            A = { [0] = sprite, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 705
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddVSprite)),
            add));
        Assert.Equal(0u, add.D[0]);
        Assert.Equal(
            GraphicsLayouts.VSpriteFlag,
            bus.ReadWord(sprite + (uint)GraphicsLayouts.VSpriteFlags));
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(705, add.Cycles);

        var sort = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 707
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SortGList)),
            sort));
        Assert.Equal(0u, sort.D[0]);
        Assert.Equal(707, sort.Cycles);

        var remove = new M68kCpuState
        {
            A = { [0] = sprite },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 709
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemVSprite)),
            remove));
        Assert.Equal(0u, remove.D[0]);
        Assert.Equal(0u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(709, remove.Cycles);

        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteFlags, GraphicsLayouts.VSpriteFlag);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteHeight, 1);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteWidth, 1);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteDepth, 1);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteImageData, imageData);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteBorderLine, borderLine);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteCollMask, collisionMask);
        bus.WriteWord(imageData, 0x8000);

        var masks = new M68kCpuState
        {
            A = { [0] = sprite },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 711
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitMasks)),
            masks));
        Assert.Equal(0u, masks.D[0]);
        Assert.Equal((ushort)0x8000, bus.ReadWord(borderLine));
        Assert.Equal((ushort)0x8000, bus.ReadWord(collisionMask));
        Assert.Equal(711, masks.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0, [2] = 0 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 713,
            ProgramCounter = 0x0012_3871
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGels)),
            malformed));
        Assert.Equal(nativeInitGelsTarget, malformed.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformed.D[0]);
        Assert.Equal(713, malformed.Cycles);

        var malformedSort = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0x5A5A_A5A5u },
            Cycles = 715,
            ProgramCounter = 0x0012_3877
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SortGList)),
            malformedSort));
        Assert.Equal(nativeSortGListTarget, malformedSort.ProgramCounter);
        Assert.Equal(0x5A5A_A5A5u, malformedSort.D[0]);
        Assert.Equal(715, malformedSort.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesAnimationStateAndMasksWithTailChainBoundary()
    {
        const uint imageBase = 0x00DC_F000;
        const uint nativeBase = 0x00DD_0000;
        const uint guestBase = 0x00DE_0000;
        const uint head = guestBase + 0x000;
        const uint tail = guestBase + 0x100;
        const uint gelsInfo = guestBase + 0x200;
        const uint rastPort = guestBase + 0x300;
        const uint animOb = guestBase + 0x500;
        const uint component = guestBase + 0x600;
        const uint bob = guestBase + 0x700;
        const uint vSprite = guestBase + 0x800;
        const uint secondBob = guestBase + 0xD00;
        const uint secondVSprite = guestBase + 0xE00;
        const uint animKey = guestBase + 0x900;
        const uint imageData = guestBase + 0xA00;
        const uint borderLine = guestBase + 0xB00;
        const uint collisionMask = guestBase + 0xC00;
        const uint nativeInitGelsTarget = 0x00DF_1801;
        const uint nativeAddAnimObTarget = 0x00DF_1807;
        const uint nativeAnimateTarget = 0x00DF_180D;
        const uint nativeInitGMasksTarget = 0x00DF_1813;
        const uint nativeAddBobTarget = 0x00DF_1819;
        const uint nativeRemIBobTarget = 0x00DF_181F;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGels)),
            nativeInitGelsTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddAnimOb)),
            nativeAddAnimObTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.Animate)),
            nativeAnimateTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGMasks)),
            nativeInitGMasksTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddBob)),
            nativeAddBobTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemIBob)),
            nativeRemIBobTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(guestBase, new byte[0x1800]);

        bus.WriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
            gelsInfo);
        bus.WriteLong(
            animOb + (uint)GraphicsLayouts.AnimObHeadComp,
            component);
        bus.WriteLong(
            component + (uint)GraphicsLayouts.AnimCompAnimBob,
            bob);
        bus.WriteWord(
            component + (uint)GraphicsLayouts.AnimCompTimeSet,
            3);
        bus.WriteWord(
            component + (uint)GraphicsLayouts.AnimCompXTrans,
            64);
        bus.WriteWord(
            component + (uint)GraphicsLayouts.AnimCompYTrans,
            64);
        bus.WriteLong(
            bob + (uint)GraphicsLayouts.BobVSprite,
            vSprite);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteWidth, 1);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteHeight, 1);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteDepth, 1);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteX, 10);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteY, 4);
        bus.WriteLong(secondBob + (uint)GraphicsLayouts.BobVSprite, secondVSprite);
        bus.WriteWord(secondVSprite + (uint)GraphicsLayouts.VSpriteY, 20);
        bus.WriteWord(secondVSprite + (uint)GraphicsLayouts.VSpriteX, 30);
        bus.WriteLong(animOb + (uint)GraphicsLayouts.AnimObX, 640);
        bus.WriteLong(animOb + (uint)GraphicsLayouts.AnimObY, 128);
        bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 640);
        bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 128);
        bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObXVel, 64);
        bus.WriteWord(animOb + (uint)GraphicsLayouts.AnimObYVel, 0);
        bus.WriteLong(animKey, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var init = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 801
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGels)),
            init));
        Assert.Equal(0u, init.D[0]);

        var add = new M68kCpuState
        {
            A = { [0] = animOb, [1] = animKey, [2] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 803
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddAnimOb)),
            add));
        Assert.Equal(0u, add.D[0]);
        Assert.Equal(animOb, bus.ReadLong(animKey));
        Assert.Equal(bob, bus.ReadLong(vSprite + (uint)GraphicsLayouts.VSpriteVSBob));
        Assert.Equal(803, add.Cycles);

        var animate = new M68kCpuState
        {
            A = { [0] = animKey, [1] = rastPort },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 805
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.Animate)),
            animate));
        Assert.Equal(0u, animate.D[0]);
        Assert.Equal((ushort)640,
            bus.ReadWord(animOb + (uint)GraphicsLayouts.AnimObOldX));
        Assert.Equal((ushort)704,
            bus.ReadWord(animOb + (uint)GraphicsLayouts.AnimObX));
        Assert.Equal(805, animate.Cycles);

        var addBob = new M68kCpuState
        {
            A = { [0] = secondBob, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 806
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddBob)),
            addBob));
        Assert.Equal(0u, addBob.D[0]);
        Assert.Equal(secondBob,
            bus.ReadLong(secondVSprite + (uint)GraphicsLayouts.VSpriteVSBob));
        Assert.Equal(806, addBob.Cycles);

        var remBob = new M68kCpuState
        {
            A = { [0] = secondBob, [1] = rastPort, [2] = 0 },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 807
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemIBob)),
            remBob));
        Assert.Equal(0u, remBob.D[0]);
        Assert.Equal(0u,
            bus.ReadLong(secondVSprite + (uint)GraphicsLayouts.VSpriteVSBob));
        Assert.Equal(807, remBob.Cycles);

        bus.WriteLong(bob + (uint)GraphicsLayouts.BobImageShadow, collisionMask);
        bus.WriteLong(vSprite + (uint)GraphicsLayouts.VSpriteImageData, imageData);
        bus.WriteLong(vSprite + (uint)GraphicsLayouts.VSpriteBorderLine, borderLine);
        bus.WriteLong(vSprite + (uint)GraphicsLayouts.VSpriteCollMask, 0);
        bus.WriteWord(imageData, 0x8000);

        var masks = new M68kCpuState
        {
            A = { [0] = animOb },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 808
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGMasks)),
            masks));
        Assert.Equal(0u, masks.D[0]);
        Assert.Equal((ushort)0x8000, bus.ReadWord(borderLine));
        Assert.Equal((ushort)0x8000, bus.ReadWord(collisionMask));
        Assert.Equal(808, masks.Cycles);

        bus.MapReadOnlyMemory(borderLine, new byte[2]);
        var readOnlyMasks = new M68kCpuState
        {
            A = { [0] = animOb },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 809,
            ProgramCounter = 0x0012_3879
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.InitGMasks)),
            readOnlyMasks));
        Assert.Equal(nativeInitGMasksTarget, readOnlyMasks.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, readOnlyMasks.D[0]);
        Assert.Equal(809, readOnlyMasks.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0, [2] = 0 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 810,
            ProgramCounter = 0x0012_387D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddAnimOb)),
            malformed));
        Assert.Equal(nativeAddAnimObTarget, malformed.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformed.D[0]);
        Assert.Equal(810, malformed.Cycles);

        var malformedRemBob = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort, [2] = 0 },
            D = { [0] = 0x5A5A_A5A5u },
            Cycles = 812,
            ProgramCounter = 0x0012_3881
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemIBob)),
            malformedRemBob));
        Assert.Equal(nativeRemIBobTarget, malformedRemBob.ProgramCounter);
        Assert.Equal(0x5A5A_A5A5u, malformedRemBob.D[0]);
        Assert.Equal(812, malformedRemBob.Cycles);
    }

    [Fact]
    public void NativeOverlayRoutesOwnedAnimationBuffersAndTailChainsForeignState()
    {
        const uint imageBase = 0x00D0_F000;
        const uint nativeBase = 0x00D1_0000;
        const uint guestBase = 0x00D2_0000;
        const uint allocationBase = 0x00D3_0000;
        const uint bitMap = guestBase + 0x000;
        const uint plane = guestBase + 0x100;
        const uint rastPort = guestBase + 0x200;
        const uint animOb = guestBase + 0x400;
        const uint component = guestBase + 0x500;
        const uint bob = guestBase + 0x600;
        const uint vSprite = guestBase + 0x700;
        const uint imageData = guestBase + 0x800;
        const uint foreignAnimOb = guestBase + 0xA00;
        const uint nativeGetTarget = 0x00D4_1901;
        const uint nativeFreeTarget = 0x00D4_1907;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetGBuffers)),
            nativeGetTarget);
        WriteJmp(image, imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeGBuffers)),
            nativeFreeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(guestBase, new byte[0x1000]);
        bus.MapWritableMemory(allocationBase, new byte[0x1000]);

        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        bus.WriteLong(animOb + (uint)GraphicsLayouts.AnimObHeadComp, component);
        bus.WriteLong(component + (uint)GraphicsLayouts.AnimCompAnimBob, bob);
        bus.WriteLong(bob + (uint)GraphicsLayouts.BobVSprite, vSprite);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteWidth, 1);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteHeight, 1);
        bus.WriteByte(vSprite + (uint)GraphicsLayouts.VSpriteDepth, 1, 0);
        bus.WriteLong(vSprite + (uint)GraphicsLayouts.VSpriteImageData, imageData);
        bus.WriteWord(imageData, 0x8000);

        var nextAllocation = allocationBase;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (bytes, _) =>
            {
                var address = nextAllocation;
                nextAllocation += unchecked((uint)((bytes + 3) & ~3));
                return address;
            },
            freeMemory: (_, _) => frees++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var get = new M68kCpuState
        {
            A = { [0] = animOb, [1] = rastPort },
            D = { [0] = 0u },
            Cycles = 901
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetGBuffers)),
            get));
        Assert.Equal(1u, get.D[0]);
        Assert.NotEqual(0u, bus.ReadLong(bob + (uint)GraphicsLayouts.BobSaveBuffer));
        Assert.NotEqual(0u, bus.ReadLong(bob + (uint)GraphicsLayouts.BobImageShadow));
        Assert.NotEqual(0u, bus.ReadLong(vSprite + (uint)GraphicsLayouts.VSpriteBorderLine));
        Assert.NotEqual(0u, bus.ReadLong(vSprite + (uint)GraphicsLayouts.VSpriteCollMask));
        Assert.Equal(901, get.Cycles);

        var saveBuffer = bus.ReadLong(
            bob + (uint)GraphicsLayouts.BobSaveBuffer);
        bus.WriteWord(saveBuffer, 0xA55A);
        bus.WriteWord(
            vSprite + (uint)GraphicsLayouts.VSpriteFlags,
            GraphicsLayouts.VSpriteBackSaved);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteOldX, 0);
        bus.WriteWord(vSprite + (uint)GraphicsLayouts.VSpriteOldY, 0);
        var readOnlyRasterBytes = ReadBusBytes(bus, plane, sizeof(ushort));
        bus.MapReadOnlyMemory(plane, readOnlyRasterBytes);
        var readOnlyRasterFree = new M68kCpuState
        {
            A = { [0] = animOb, [1] = rastPort },
            D = { [0] = 0xBADC0DEu },
            Cycles = 902,
            ProgramCounter = 0x0012_387D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeGBuffers)),
            readOnlyRasterFree));
        Assert.Equal(nativeFreeTarget, readOnlyRasterFree.ProgramCounter);
        Assert.Equal(0xBADC0DEu, readOnlyRasterFree.D[0]);
        Assert.Equal(902, readOnlyRasterFree.Cycles);
        Assert.Equal(0, frees);
        bus.MapWritableMemory(plane, readOnlyRasterBytes);

        var readOnlyFreeField = vSprite +
            (uint)GraphicsLayouts.VSpriteBorderLine;
        var readOnlyFreeBytes = ReadBusBytes(
            bus,
            readOnlyFreeField,
            sizeof(uint));
        bus.MapReadOnlyMemory(readOnlyFreeField, readOnlyFreeBytes);
        var readOnlyFree = new M68kCpuState
        {
            A = { [0] = animOb, [1] = rastPort },
            D = { [0] = 0xCAFEBABEu },
            Cycles = 902,
            ProgramCounter = 0x0012_387F
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeGBuffers)),
            readOnlyFree));
        Assert.Equal(nativeFreeTarget, readOnlyFree.ProgramCounter);
        Assert.Equal(0xCAFEBABEu, readOnlyFree.D[0]);
        Assert.Equal(902, readOnlyFree.Cycles);
        Assert.Equal(0, frees);

        bus.MapWritableMemory(readOnlyFreeField, readOnlyFreeBytes);

        var free = new M68kCpuState
        {
            A = { [0] = animOb, [1] = rastPort },
            D = { [0] = 0u },
            Cycles = 903
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeGBuffers)),
            free));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(0u, bus.ReadLong(bob + (uint)GraphicsLayouts.BobSaveBuffer));
        Assert.Equal(0u, bus.ReadLong(bob + (uint)GraphicsLayouts.BobImageShadow));
        Assert.Equal(0u, bus.ReadLong(vSprite + (uint)GraphicsLayouts.VSpriteBorderLine));
        Assert.Equal(0u, bus.ReadLong(vSprite + (uint)GraphicsLayouts.VSpriteCollMask));
        Assert.Equal(4, frees);
        Assert.Equal(903, free.Cycles);

        var readOnlySaveBuffer = bob +
            (uint)GraphicsLayouts.BobSaveBuffer;
        bus.MapReadOnlyMemory(
            readOnlySaveBuffer,
            ReadBusBytes(bus, readOnlySaveBuffer, sizeof(uint)));
        var readOnlyGet = new M68kCpuState
        {
            A = { [0] = animOb, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 904,
            ProgramCounter = 0x0012_3881
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetGBuffers)),
            readOnlyGet));
        Assert.Equal(nativeGetTarget, readOnlyGet.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, readOnlyGet.D[0]);
        Assert.Equal(904, readOnlyGet.Cycles);
        Assert.Equal(0u, bus.ReadLong(readOnlySaveBuffer));
        Assert.Equal(4, frees);

        var foreign = new M68kCpuState
        {
            A = { [0] = foreignAnimOb, [1] = rastPort },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 905,
            ProgramCounter = 0x0012_3883
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.FreeGBuffers)),
            foreign));
        Assert.Equal(nativeFreeTarget, foreign.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, foreign.D[0]);
        Assert.Equal(905, foreign.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 907,
            ProgramCounter = 0x0012_3889
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.GetGBuffers)),
            malformed));
        Assert.Equal(nativeGetTarget, malformed.ProgramCounter);
        Assert.Equal(0xA5A5_5A5Au, malformed.D[0]);
        Assert.Equal(907, malformed.Cycles);
    }

    [Fact]
    public void PolyDrawConnectsGuestCoordinatePairsAndLeavesTheFinalPenPosition()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint points = 0x300;
        memory.TryWriteWord(points, 1);
        memory.TryWriteWord(points + 2, 1);
        memory.TryWriteWord(points + 4, 1);
        memory.TryWriteWord(points + 6, 4);
        memory.TryWriteWord(points + 8, 4);
        memory.TryWriteWord(points + 10, 4);

        Assert.Equal(0, core.PolyDraw(0x20, 3, points));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 1));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 4));
        Assert.Equal((short)4, unchecked((short)ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)4, unchecked((short)ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(0, core.PolyDraw(0x20, 0, 0));
        Assert.Equal(-1, core.PolyDraw(0x20, 1, uint.MaxValue));
    }

    [Fact]
    public void PolyDrawRejectsNullAndOddPointTablesBeforeReadingGuestBytes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.Move(rastPort, 1, 1));
        var originalX = ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX);
        var originalY = ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY);

        // The host test memory deliberately exposes both addresses.  The
        // portable boundary must still preserve the native NULL/address-error
        // ownership split instead of decoding a foreign point stream.
        Assert.True(memory.TryWriteWord(0, 2));
        Assert.True(memory.TryWriteWord(2, 2));
        Assert.True(memory.TryWriteWord(0x301, 2));
        Assert.True(memory.TryWriteWord(0x303, 2));

        Assert.Equal(-1, core.PolyDraw(rastPort, 1, 0));
        Assert.Equal(-1, core.PolyDraw(rastPort, 1, 0x301));
        Assert.Equal(originalX, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(originalY, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(0, core.ReadPixel(rastPort, 2, 2));
    }

    [Fact]
    public void PolyDrawDrawsTheFirstSegmentFromTheExistingCurrentPen()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint points = 0x300;

        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.True(memory.TryWriteWord(points, 3));
        Assert.True(memory.TryWriteWord(points + 2, 0));

        // Native PolyDraw is a Draw loop, so the first pair is an endpoint
        // and the caller's current pen supplies the segment origin.  An
        // implicit Move would leave every pixel in this line untouched.
        Assert.Equal(0, core.PolyDraw(rastPort, 1, points));
        for (short x = 0; x <= 3; x++)
            Assert.Equal(3, core.ReadPixel(rastPort, x, 0));
        Assert.Equal((short)3, ReadSignedWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void PolyDrawPreflightMatchesFreshMoveAndMajorAxisPatternPhase()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint points = 0x300;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0x8000));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));
        Assert.True(memory.TryWriteWord(points, 0));
        Assert.True(memory.TryWriteWord(points + 2, 0));
        Assert.True(memory.TryWriteWord(points + 4, 3));
        Assert.True(memory.TryWriteWord(points + 6, 1));

        // PolyDraw's first Draw uses the caller's current pen and consumes
        // the same major-axis phase as the actual Draw calls it models.
        Assert.Equal(0, core.PolyDraw(rastPort, 2, points));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(
            (byte)12,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void PolyDrawPreflightsTheCompletePointStreamBeforeChangingTheRastPort()
    {
        var memory = new FakeMemory(0x800);
        var core = CreateCore(memory);
        const uint points = 0x7FC;

        Assert.Equal(0, core.Move(0x20, 5, 6));
        Assert.True(memory.TryWriteWord(points, 1));
        Assert.True(memory.TryWriteWord(points + 2, 1));

        // The first point is readable, but the second point begins exactly at
        // the end of the guest envelope.  PolyDraw must fail before moving to
        // the first point or publishing any partial line.
        Assert.Equal(-1, core.PolyDraw(0x20, 2, points));
        Assert.Equal((short)5, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)6, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 1));
    }

    [Fact]
    public void PolyDrawPreflightsEveryLineBeforePublishingAnEarlierSegment()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint points = 0x300;

        Assert.Equal(0, core.Move(0x20, 5, 6));
        // Plane zero has one readable row left in the guest envelope.  Its
        // next row is outside memory, so a later in-raster segment exposes a
        // real destination failure rather than ordinary clipping.
        Assert.True(memory.TryWriteLong(
            0x100u + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FFE));
        Assert.True(memory.TryWriteWord(points, 1));
        Assert.True(memory.TryWriteWord(points + 2, 0));
        Assert.True(memory.TryWriteWord(points + 4, 2));
        Assert.True(memory.TryWriteWord(points + 6, 0));
        Assert.True(memory.TryWriteWord(points + 8, 2));
        Assert.True(memory.TryWriteWord(points + 10, 1));

        // The first segment is drawable, but the second reaches the
        // malformed later plane row.
        // The complete PolyDraw must fail before publishing even that first
        // segment or moving the guest cursor.
        Assert.Equal(-1, core.PolyDraw(0x20, 3, points));
        Assert.Equal((short)5, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)6, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 2, 0));
    }

    [Fact]
    public void PolyDrawWithZeroWriteMaskSkipsHugeLineWalksButPublishesState()
    {
        var memory = new FakeMemory(0x50000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint points = 0x8000;
        const uint plane = 0x4FFF8;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));

        // A maximal connected point stream alternates endpoints at the
        // signed-WORD extremes. The zero-mask path must not run one full
        // Bresenham walk for every point (which would be billions of host
        // iterations); it must still consume the stream and publish the last
        // cursor position and line phase.
        for (var index = 0; index < ushort.MaxValue; index++)
        {
            var coordinate = (index & 1) == 0 ? short.MaxValue : short.MinValue;
            var address = points + (uint)(index * 4);
            Assert.True(memory.TryWriteWord(address, unchecked((ushort)coordinate)));
            Assert.True(memory.TryWriteWord(address + 2, unchecked((ushort)coordinate)));
        }

        Assert.Equal(0, core.PolyDraw(rastPort, ushort.MaxValue, points));
        Assert.Equal(
            (short)short.MaxValue,
            unchecked((short)ReadWord(
                memory,
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(
            (short)short.MaxValue,
            unchecked((short)ReadWord(
                memory,
                rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState();
        state.A[0] = points;
        state.A[1] = rastPort;
        state.D[0] = ushort.MaxValue;

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.PolyDraw));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void PolyDrawWithZeroEffectiveMaskDoesNotReadPublicPensAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x400;
        const uint points = 0x500;

        static void Prepare(
            GraphicsLibraryCore core,
            FakeMemory backing,
            uint rastPort,
            uint bitMap,
            uint plane,
            uint points)
        {
            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(backing.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                2));
            Assert.True(backing.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                8));
            Assert.True(backing.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                plane));
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.True(backing.TryWriteWord(points, 3));
            Assert.True(backing.TryWriteWord(points + 2, 0));
        }

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Prepare(core, backing, rastPort, bitMap, plane, points);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);

        Assert.Equal(0, core.PolyDraw(rastPort, 1, points));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((short)3, unchecked((short)ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)0, unchecked((short)ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((byte)0, ReadByte(backing, plane));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        Prepare(mappedCore, mappedBacking, rastPort, bitMap, plane, points);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte) * 2u);

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = points, [1] = rastPort },
            D = { [0] = 1, [1] = 0xA5A5_5A5Au },
            Cycles = 73
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.PolyDraw));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(73, state.Cycles);
        Assert.Equal(0, mappedMemory.FaultedReadCount);
        Assert.Equal((byte)0, ReadByte(mappedBacking, plane));
    }

    [Fact]
    public void PolyDrawRejectsAnAggregateBresenhamWalkBeforeDestinationProbe()
    {
        var memory = new FakeMemory(0x50000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x400;
        const uint points = 0x8000;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            8));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            unchecked((ushort)short.MaxValue)));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            unchecked((ushort)short.MaxValue)));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            GraphicsLayouts.RastPortFirstDot));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));
        Assert.True(memory.TryWriteByte(plane, 0x5A));

        // Every segment crosses the complete signed-WORD range.  Reading the
        // point stream is bounded, but walking all 65,535 Bresenham segments
        // would exceed the portable transactional host-work contract by
        // several billion samples.
        for (var index = 0; index < ushort.MaxValue; index++)
        {
            var coordinate = (index & 1) == 0 ? short.MinValue : short.MaxValue;
            var address = points + (uint)(index * 4);
            Assert.True(memory.TryWriteWord(address, unchecked((ushort)coordinate)));
            Assert.True(memory.TryWriteWord(address + 2, unchecked((ushort)coordinate)));
        }

        Assert.Equal(-1, core.PolyDraw(rastPort, ushort.MaxValue, points));
        Assert.Equal(
            (short)short.MaxValue,
            unchecked((short)ReadWord(
                memory,
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(
            (short)short.MaxValue,
            unchecked((short)ReadWord(
                memory,
                rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(
            (byte)15,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = points, [1] = rastPort },
            D = { [0] = ushort.MaxValue, [1] = 0xCAFE_BABEu },
            Cycles = 173
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.PolyDraw));
        Assert.Equal(ushort.MaxValue, state.D[0]);
        Assert.Equal(0xCAFE_BABEu, state.D[1]);
        Assert.Equal(173, state.Cycles);
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreservePolyDrawAggregateDecline()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint points = 0x8000;
        const uint plane = 0x50000;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(points, new byte[ushort.MaxValue * 4]);
            bus.MapWritableMemory(plane, new byte[0x100]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
            bus.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1, 0);
            bus.WriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
                unchecked((ushort)short.MaxValue));
            bus.WriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
                unchecked((ushort)short.MaxValue));
            bus.WriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                GraphicsLayouts.RastPortFirstDot);
            bus.WriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                15,
                0);
            bus.WriteByte(plane, 0x5A, 0);

            for (var index = 0; index < ushort.MaxValue; index++)
            {
                var coordinate = (index & 1) == 0 ? short.MinValue : short.MaxValue;
                var address = points + (uint)(index * 4);
                bus.WriteWord(address, unchecked((ushort)coordinate));
                bus.WriteWord(address + 2, unchecked((ushort)coordinate));
            }
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = points, [1] = rastPort },
            D = { [0] = ushort.MaxValue, [1] = 0xCAFE_BABEu },
            Cycles = 181
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = points, [1] = rastPort },
            D = { [0] = ushort.MaxValue, [1] = 0xCAFE_BABEu },
            Cycles = 181
        };

        direct.Invoke(directState, (int)GraphicsLvo.PolyDraw);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.PolyDraw)),
            overlayState));

        Assert.Equal(ushort.MaxValue, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(0xCAFE_BABEu, directState.D[1]);
        Assert.Equal(directState.D[1], overlayState.D[1]);
        Assert.Equal(181, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal((byte)0x5A, directBus.ReadByte(plane));
        Assert.Equal(directBus.ReadByte(plane), overlayBus.ReadByte(plane));
        Assert.Equal(
            directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX),
            overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            directBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY),
            overlayBus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
    }

    [Fact]
    public void DrawHonorsLinePatternForJam1AndJam2Modes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        Assert.Equal(0, core.SetRast(0x20, 0));
        Assert.Equal(0, core.SetDrawMode(0x20, 0));
        Assert.True(memory.TryWriteWord(0x20u + (uint)GraphicsLayouts.RastPortLinePattern, 0xA000));
        // SetDrPt() is a macro which publishes the initial preshift of 15;
        // model that guest-visible state explicitly in the portable fixture.
        Assert.True(memory.TryWriteByte(0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount, 15));
        Assert.Equal(0, core.Move(0x20, 0, 0));
        Assert.Equal(0, core.Draw(0x20, 3, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 3, 0));

        Assert.Equal(0, core.SetDrawMode(0x20, 1));
        Assert.Equal(0, core.SetBPen(0x20, 2));
        Assert.True(memory.TryWriteWord(0x20u + (uint)GraphicsLayouts.RastPortLinePattern, 0xA000));
        Assert.True(memory.TryWriteByte(0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount, 15));
        Assert.Equal(0, core.Move(0x20, 0, 1));
        Assert.Equal(0, core.Draw(0x20, 3, 1));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 1));
        Assert.Equal(2, core.ReadPixel(0x20, 1, 1));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 1));
        Assert.Equal(2, core.ReadPixel(0x20, 3, 1));

        Assert.Equal(0, core.SetRast(0x20, 0));
        Assert.Equal(0, core.SetDrawMode(0x20, 4));
        Assert.True(memory.TryWriteWord(0x20u + (uint)GraphicsLayouts.RastPortLinePattern, 0xA000));
        Assert.True(memory.TryWriteByte(0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount, 15));
        Assert.Equal(0, core.Move(0x20, 0, 2));
        Assert.Equal(0, core.Draw(0x20, 3, 2));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 2));
        Assert.Equal(0, core.ReadPixel(0x20, 2, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 2));
    }

    [Fact]
    public void SetDrPtPublishesPatternFreshLineAndFirstPatternPhaseAtomically()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(GraphicsLayouts.RastPortNoCrossFill | GraphicsLayouts.RastPortOneDot)));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            3));

        // SetDrPt is the classic gfxmacros.h helper, not an LVO.  Its
        // guest-visible contract is nevertheless shared by every line
        // renderer: replace LinePtrn, set FRST_DOT, and publish preshift 15.
        Assert.Equal(0, core.SetDrPt(rastPort, 0xA000));
        Assert.Equal(
            (ushort)0xA000,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePattern));
        Assert.Equal(
            (ushort)(GraphicsLayouts.RastPortNoCrossFill |
                     GraphicsLayouts.RastPortOneDot |
                     GraphicsLayouts.RastPortFirstDot),
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            (byte)15,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void SetDrPtRollsBackPatternFlagsAndPhaseWhenPublicationFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort oldPattern = 0x1357;
        const ushort oldFlags = (ushort)(GraphicsLayouts.RastPortNoCrossFill |
                                         GraphicsLayouts.RastPortOneDot);
        const byte oldPatternCount = 6;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            oldPattern));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            oldPatternCount));

        // Pattern (2 bytes), flags (2 bytes), then the phase byte: fail the
        // phase publication after the first four writes have succeeded.
        memory.FailOnNextByteWrite(5);

        Assert.Equal(-1, core.SetDrPt(rastPort, 0xA000));
        Assert.Equal(oldPattern,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePattern));
        Assert.Equal(oldFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(oldPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void SetDrPtRestoresPatternAndFlagsAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort oldPattern = 0x1357;
        const ushort oldFlags = (ushort)(GraphicsLayouts.RastPortNoCrossFill |
                                         GraphicsLayouts.RastPortOneDot);
        const byte oldPatternCount = 6;
        var patternAddress = rastPort + (uint)GraphicsLayouts.RastPortLinePattern;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteWord(patternAddress, oldPattern));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            oldPatternCount));

        // The first pattern WORD publication accepts only its high byte and
        // then rejects the operation. The rollback must bypass that same
        // rejected WORD path, after which a clean retry must still work.
        memory.PartialWordAddress = patternAddress;

        Assert.Equal(-1, core.SetDrPt(rastPort, 0xA000));
        Assert.Equal(oldPattern, ReadWord(backing, patternAddress));
        Assert.Equal(
            oldFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            oldPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.SetDrPt(rastPort, 0xA000));
        Assert.Equal((ushort)0xA000, ReadWord(backing, patternAddress));
        Assert.Equal(
            (ushort)(oldFlags | GraphicsLayouts.RastPortFirstDot),
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            (byte)15,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void SetAfPtPublishesPointerAndSignedHeightExponentAtomically()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            0x3456));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            2));

        // Negative exponents select a multicolour pattern.  SetAfPt stores
        // the raw signed BYTE; it does not inspect or dereference the table.
        Assert.Equal(0, core.SetAfPt(rastPort, 0x8123, -4));
        Assert.Equal(
            0x8123u,
            ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn));
        Assert.Equal(
            unchecked((byte)-4),
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz));

        // Resetting the macro with NULL and exponent zero is also a plain
        // guest-field publication; no pattern-table mapping is required.
        Assert.Equal(0, core.SetAfPt(rastPort, 0, 0));
        Assert.Equal(
            0u,
            ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn));
        Assert.Equal(
            (byte)0,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz));
    }

    [Fact]
    public void SetAfPtRestoresPointerAndHeightWhenSecondPublicationFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint oldAreaPattern = 0x1357;
        const byte oldAreaPatternSize = 3;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn,
            oldAreaPattern));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            oldAreaPatternSize));

        // The pointer publication consumes four byte writes; reject the
        // following AreaPtSz byte and require the helper to restore both
        // fields before returning its failure status.
        memory.FailOnNextByteWrite(5);

        Assert.Equal(-1, core.SetAfPt(rastPort, 0x2468, -2));
        Assert.Equal(
            oldAreaPattern,
            ReadLong(backing, rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn));
        Assert.Equal(
            oldAreaPatternSize,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz));
    }

    [Fact]
    public void SetAfPtRestoresTheOldPointerAfterRejectedPartialLongPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectLongWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint oldAreaPattern = 0x8013_5700;
        const byte oldAreaPatternSize = 3;
        var patternAddress = rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn;

        Assert.True(backing.TryWriteLong(patternAddress, oldAreaPattern));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz,
            oldAreaPatternSize));

        // A partial APTR publication must be restored byte-wise when the
        // bridge rejects the repeated LONG used by conventional rollback.
        memory.PartialLongAddress = patternAddress;
        Assert.Equal(-1, core.SetAfPt(rastPort, 0x2468, -2));
        Assert.Equal(oldAreaPattern, ReadLong(backing, patternAddress));
        Assert.Equal(
            oldAreaPatternSize,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz));

        memory.PartialLongAddress = null;
        Assert.Equal(0, core.SetAfPt(rastPort, 0x2468, -2));
        Assert.Equal(0x2468u, ReadLong(backing, patternAddress));
    }

