    [Fact]
    public void SetOPenRestoresFlagsAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const byte oldOutlinePen = 3;
        const ushort oldFlags = GraphicsLayouts.RastPortNoCrossFill;
        var flagsAddress = rastPort + (uint)GraphicsLayouts.RastPortFlags;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
            oldOutlinePen));
        Assert.True(backing.TryWriteWord(flagsAddress, oldFlags));

        // SetOPen publishes AOlPen first, then the Flags WORD. Reject the
        // latter after its high byte lands; byte-wise rollback must restore
        // both fields and leave a clean retry possible.
        memory.PartialWordAddress = flagsAddress;

        Assert.Equal(-1, core.SetOPen(rastPort, 9));
        Assert.Equal(
            oldOutlinePen,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(oldFlags, ReadWord(backing, flagsAddress));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.SetOPen(rastPort, 9));
        Assert.Equal(
            (byte)9,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal(
            (ushort)(oldFlags | GraphicsLayouts.RastPortAreaOutline),
            ReadWord(backing, flagsAddress));
    }

