        memory.PartialWordAddress = null;
        Assert.Equal(0, core.BoundaryOff(rastPort));
        Assert.Equal(
            (ushort)(oldFlags & ~GraphicsLayouts.RastPortAreaOutline),
            ReadWord(backing, flagsAddress));
    }

