        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetBPen(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2|COMPLEMENT
