        Assert.Equal(0, mappedCore.ReadPixel(rastPort, 3, 0));
    }

    [Fact]
    public void DrawAndPolyDrawDeclinePrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint points = 0x300;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        static void SeedPrivatePens(
            FakeMemory backing,
            RangeReadFaultMemory memory,
            uint rastPort,
            uint plane0,
            uint plane1)
        {
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.True(backing.TryWriteByte(plane0, 0x66));
            Assert.True(backing.TryWriteByte(plane1, 0x99));
            // DrawMode, FgPen, and BgPen are covered by one contiguous fault
            // range. A private-pen decline must return before probing any of
            // those public drawing fields.
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte) * 4u);
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Assert.True(backing.TryWriteWord(points, 3));
            Assert.True(backing.TryWriteWord(points + 2, 0));
            SeedPrivatePens(backing, memory, rastPort, plane0, plane1);

            Assert.Equal(-1, core.Draw(rastPort, 3, 0));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x66, ReadByte(backing, plane0));
            Assert.Equal((byte)0x99, ReadByte(backing, plane1));
            memory.FailReads(points, sizeof(uint));
            Assert.Equal(-1, core.PolyDraw(rastPort, 1, points));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x66, ReadByte(backing, plane0));
            Assert.Equal((byte)0x99, ReadByte(backing, plane1));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Assert.True(backing.TryWriteWord(points, 3));
            Assert.True(backing.TryWriteWord(points + 2, 0));
            SeedPrivatePens(backing, memory, rastPort, plane0, plane1);

            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            var draw = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 3, [1] = 0 },
                Cycles = 41
            };
            Assert.False(adapter.TryInvoke(draw, (int)GraphicsLvo.Draw));
            Assert.Equal(3u, draw.D[0]);
            Assert.Equal(41, draw.Cycles);
            Assert.Equal(0, memory.FaultedReadCount);

            memory.FailReads(points, sizeof(uint));
            var polyDraw = new M68kCpuState
            {
                A = { [0] = points, [1] = rastPort },
                D = { [0] = 1 },
                Cycles = 43
            };
            Assert.False(adapter.TryInvoke(polyDraw, (int)GraphicsLvo.PolyDraw));
            Assert.Equal(1u, polyDraw.D[0]);
            Assert.Equal(43, polyDraw.Cycles);
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x66, ReadByte(backing, plane0));
            Assert.Equal((byte)0x99, ReadByte(backing, plane1));
        }
    }

