    [Fact]
    public void PenAndDrawModeSettersRestartTheLinePatternAtBitFifteen()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        var phase = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        Assert.True(memory.TryWriteByte(phase, 4));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.Equal((byte)15, ReadByte(memory, phase));

        Assert.True(memory.TryWriteByte(phase, 2));
        Assert.Equal(0, core.SetBPen(rastPort, 4));
        Assert.Equal((byte)15, ReadByte(memory, phase));

        Assert.True(memory.TryWriteByte(phase, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1));
        Assert.Equal((byte)15, ReadByte(memory, phase));
    }

    [Fact]
    public void RastPortMintermsFollowClassicPenAndDrawModeRules()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        var minterms = rastPort + (uint)GraphicsLayouts.RastPortMinterms;

        Assert.True(core.InitializeRastPort(rastPort));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal((byte)0xCA, ReadByte(memory, minterms + (uint)plane));

        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal((byte)0xCA, ReadByte(memory, minterms));
        for (var plane = 1; plane < 8; plane++)
            Assert.Equal((byte)0x0A, ReadByte(memory, minterms + (uint)plane));

        Assert.Equal(0, core.SetBPen(rastPort, 2));
        Assert.Equal((byte)0x3A, ReadByte(memory, minterms + 1u));

        // JAM1 substitutes the constant B=1 input (minterm selector 2).
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.Equal((byte)0xEA, ReadByte(memory, minterms));
        Assert.Equal((byte)0x2A, ReadByte(memory, minterms + 1u));

        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal((byte)0x9A, ReadByte(memory, minterms + (uint)plane));

        Assert.Equal(0, core.SetDrawMode(rastPort, 6));
        for (var plane = 0; plane < 8; plane++)
            Assert.Equal((byte)0x6A, ReadByte(memory, minterms + (uint)plane));

        Assert.Equal(0, core.SetABPenDrMd(rastPort, 0xAA, 0x55, 1));
        for (var plane = 0; plane < 8; plane++)
        {
            var expected = (plane & 1) == 0 ? (byte)0x3A : (byte)0xCA;
            Assert.Equal(expected, ReadByte(memory, minterms + (uint)plane));
        }
    }

    [Fact]
    public void MoveStartsAFreshLineAndDrawUsesMajorAxisPatternPhase()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0x8000));
        // SetDrPt() publishes bit 15 as the first pattern sample.
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));

        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortFirstDot,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(0, core.Draw(rastPort, 3, 1));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 1, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 2, 1));
        Assert.Equal(0, core.ReadPixel(rastPort, 3, 1));
        // The line advances by max(abs(dx), abs(dy)) = 3, not by its four
        // emitted samples, so the next preshift is 12.
        Assert.Equal(
            (byte)12,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        // Move() starts a new segment even though the prior line left a
        // non-zero pattern phase.  In COMPLEMENT mode the fresh origin must
        // therefore be toggled instead of being treated as a shared hole.
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            12));
        Assert.Equal(0, core.Move(rastPort, 0, 2));
        Assert.Equal(0, core.Draw(rastPort, 1, 2));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 0, 2));
    }

    [Fact]
    public void MoveRestartsLinePatternAtTheFirstBit()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort oldFlags = 0x0200;

        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            4));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));

        Assert.Equal(0, core.Move(rastPort, 7, 8));
        Assert.Equal(
            (byte)15,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (short)7,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            (short)8,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(
            (ushort)(oldFlags | GraphicsLayouts.RastPortFirstDot),
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void MoveRestoresFreshLineFlagWhenTheFlagWriteFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const ushort oldFlags = 0x1200;

        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            1));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            2));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            7));

        // X, Y, and the fresh-line pattern phase publish before the first
        // byte of the FRST_DOT update; require the complete four-field state
        // to roll back.
        memory.FailOnNextByteWrite(6);
        Assert.Equal(-1, core.Move(rastPort, 8, 9));
        Assert.Equal((short)1, ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((short)2, ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));
        Assert.Equal(
            (byte)7,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(oldFlags, ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

