    [Fact]
    public void DrawConsumesFirstDotForConnectedComplementLines()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)GraphicsLayouts.RastPortFirstDot));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));

        var initial0 = core.ReadPixel(rastPort, 0, 0);
        var initial1 = core.ReadPixel(rastPort, 1, 0);
        var initial2 = core.ReadPixel(rastPort, 2, 0);
        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(0, core.Draw(rastPort, 2, 0));
        Assert.NotEqual(initial0, core.ReadPixel(rastPort, 0, 0));
        Assert.NotEqual(initial1, core.ReadPixel(rastPort, 1, 0));
        var firstEnd = core.ReadPixel(rastPort, 2, 0);
        Assert.NotEqual(initial2, firstEnd);
        Assert.Equal((ushort)0, ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        // The second connected line keeps the shared endpoint at its first
        // value rather than complementing it back.
        var beforeNew3 = core.ReadPixel(rastPort, 3, 0);
        Assert.Equal(0, core.Draw(rastPort, 4, 0));
        Assert.Equal(firstEnd, core.ReadPixel(rastPort, 2, 0));
        Assert.NotEqual(beforeNew3, core.ReadPixel(rastPort, 3, 0));
        Assert.NotEqual(beforeNew3, core.ReadPixel(rastPort, 4, 0));
    }

    [Fact]
    public void DrawKeepsTheSharedVertexWriteForConnectedJam2Lines()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));

        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(0, core.Draw(rastPort, 2, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 2, 0));

        // Make the shared endpoint observably different before the connected
        // segment. Native JAM2 Draw() writes that first dot again, whereas a
        // blanket "skip shared endpoint" shortcut would leave this zero.
        Assert.Equal(0, core.SetAPen(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.Equal(0, core.WritePixel(rastPort, 2, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 2, 0));

        Assert.Equal(0, core.SetAPen(rastPort, 3));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1));
        Assert.Equal(0, core.Draw(rastPort, 4, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 2, 0));
    }

    [Fact]
    public void DrawUndoesAConnectedComplementVertexAfterPatternPhaseWrapsToZero()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));

        Assert.Equal(0, core.Move(rastPort, 0, 0));
        // A 15-pixel segment consumes the initial phase 15 through 1 and
        // leaves the next connected segment at phase zero.
        Assert.Equal(0, core.Draw(rastPort, 15, 0));
        var shared = core.ReadPixel(rastPort, 15, 0);
        Assert.NotEqual(0, shared);
        Assert.Equal((byte)0, ReadByte(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        Assert.Equal(0, core.Draw(rastPort, 17, 0));
        // The second Draw samples and then undoes its shared start dot even
        // though the line phase wrapped to zero, preserving the first
        // segment's endpoint value.
        Assert.Equal(shared, core.ReadPixel(rastPort, 15, 0));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 16, 0));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 17, 0));
    }

    [Fact]
    public void DrawPreservesAConnectedComplementVertexOnAJam2PatternZeroSample()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2 | COMPLEMENT
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0x8000));

        // The first segment consumes pattern bits 15 and 14.  The shared
        // endpoint is therefore followed by a connected segment whose first
        // sample is pattern-zero and is sourced from BPen.  COMPLEMENT still
        // toggles that JAM2 sample, but the shared vertex remains owned by the
        // preceding segment and must be toggled back.
        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(0, core.Draw(rastPort, 1, 0));
        var shared = core.ReadPixel(rastPort, 1, 0);
        Assert.NotEqual(0, shared);

        Assert.Equal(0, core.Draw(rastPort, 2, 0));
        Assert.Equal(
            shared,
            core.ReadPixel(rastPort, 1, 0));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 2, 0));
    }

