        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(GraphicsLayouts.RastPortOneDot | GraphicsLayouts.RastPortFirstDot)));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));

        Assert.Equal(0, core.Move(rastPort, 2, 0));
        Assert.Equal(0, core.Draw(rastPort, 4, 5));

        // A steep line has Y as its major axis.  ONE_DOT therefore emits one
        // changed pixel on each raster row, while FRST_DOT is consumed by the
        // completed line and ONE_DOT remains a persistent RastPort mode.
        for (short y = 0; y <= 5; y++)
        {
            var changed = 0;
            for (short x = 0; x < 8; x++)
            {
                if (core.ReadPixel(rastPort, x, y) != 0)
                    changed++;
            }

            Assert.Equal(1, changed);
        }

        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortOneDot,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void DrawOneDotModeEmitsOnlyOneDotPerHorizontalRaster()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            (ushort)(GraphicsLayouts.RastPortOneDot | GraphicsLayouts.RastPortFirstDot)));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            15));

        // The ordinary shallow Bresenham walk visits two samples on each of
        // rows 0, 1, and 2.  ONE_DOT is the blitter SING mode and keeps only
        // the first sample on each horizontal raster, not every major-axis
        // sample.
        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(0, core.Draw(rastPort, 5, 2));

        Assert.Equal(3, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(0, core.ReadPixel(rastPort, 1, 0));
        Assert.Equal(3, core.ReadPixel(rastPort, 2, 1));
        Assert.Equal(0, core.ReadPixel(rastPort, 3, 1));
        Assert.Equal(3, core.ReadPixel(rastPort, 4, 2));
        Assert.Equal(0, core.ReadPixel(rastPort, 5, 2));
        Assert.Equal(
            (byte)10,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)GraphicsLayouts.RastPortOneDot,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void DrawVisibilityAdmissionClipsOffRasterSamplesAndReusesConnectedUndo()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.Equal(0, core.Move(rastPort, -2, 0));

        var visibilityCalls = new List<(int X, int Y)>();
        bool IsVisible(int x, int y)
        {
            visibilityCalls.Add((x, y));
            return true;
        }

        // The first segment starts outside the bitmap.  Admission must be
        // restricted to the visible logical cells, while its traversal still
        // advances the guest endpoint and line phase.
        Assert.Equal(
            0,
            GraphicsRasterOperations.Draw(
                memory,
                rastPort,
                1,
                0,
                pixelVisible: IsVisible));

        // A connected COMPLEMENT segment probes and publishes its shared
        // vertex once, then performs the undo using that already-admitted
        // visibility result.  A stateful layer predicate must not be asked a
        // second time for the same connected cell.
        Assert.Equal(
            0,
            GraphicsRasterOperations.Draw(
                memory,
                rastPort,
                2,
                0,
                pixelVisible: IsVisible));

        // Each in-bitmap cell is classified once per Draw transaction. The
        // shared endpoint is legitimately reclassified by the next
        // connected Draw, but preflight and publication do not duplicate it.
        Assert.Equal(
            4,
            visibilityCalls.Count);
        Assert.All(visibilityCalls, call =>
        {
            Assert.InRange(call.X, 0, 2);
            Assert.Equal(0, call.Y);
        });

        // Drop the explicit layer predicate only for observing the backing
        // bitmap after the provider-owned draw has completed.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 0, 0));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 1, 0));
        Assert.NotEqual(0, core.ReadPixel(rastPort, 2, 0));
    }

    [Fact]
    public void LayeredDrawReusesVisibilityBetweenPreflightAndPublication()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.Equal(0, core.Move(rastPort, 0, 0));

        var visibilityCalls = 0;
        bool IsVisible(int x, int y)
        {
            _ = x;
            _ = y;
            visibilityCalls++;
            // A provider that changes its answer after preflight exposes a
            // split transaction in the old path: both samples are admitted
            // during planning, then hidden during publication.
            return visibilityCalls <= 2;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.Draw(
                memory,
                rastPort,
                1,
                0,
                pixelVisible: IsVisible));

        // Preflight and publication share the two cached decisions, so both
        // admitted cells are committed and the provider is called once per
        // logical destination.
        Assert.Equal(2, visibilityCalls);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.Equal(1, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(1, core.ReadPixel(rastPort, 1, 0));
    }

    [Theory]
    [InlineData(false, 0xFF)]
    [InlineData(true, 0xFF)]
    [InlineData(false, 0)]
    [InlineData(true, 0)]
    public void LayeredDrawFirstDotPolicyPreservesIncomingComplementAndLogicalAdvance(
        bool consumeFirstDot,
        int writeMask)
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.Equal(0, core.SetRast(rastPort, 0));
        Assert.Equal(0, core.SetDrawMode(rastPort, 2));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            (byte)writeMask));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.Equal(0, core.Move(rastPort, 0, 0));

        Assert.Equal(
            0,
            GraphicsRasterOperations.Draw(
                memory,
                rastPort,
                2,
                0,
                pixelVisible: static (_, _) => true,
                consumeFirstDot: consumeFirstDot));
        Assert.Equal(
            consumeFirstDot ? (ushort)0 : (ushort)GraphicsLayouts.RastPortFirstDot,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal((byte)13, ReadByte(
            memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((ushort)2, ReadWord(
            memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)0, ReadWord(
            memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentY));

        // Retention only controls the committed flag. The first Draw still
        // sees the incoming fresh-line bit and complements its first sample;
        // the next Draw sees that retained bit rather than inventing a
        // connected shared endpoint from the already-advanced pattern phase.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer, 0));
        var drawnPixel = writeMask == 0 ? 0 : 3;
        Assert.Equal(drawnPixel, core.ReadPixel(rastPort, 0, 0));
        Assert.Equal(drawnPixel, core.ReadPixel(rastPort, 2, 0));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180));
        Assert.Equal(
            0,
            GraphicsRasterOperations.Draw(
                memory,
                rastPort,
                4,
                0,
                pixelVisible: static (_, _) => true));
        Assert.Equal((ushort)0, ReadWord(
            memory, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal((byte)11, ReadByte(
            memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((ushort)4, ReadWord(
            memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer, 0));
        Assert.Equal(consumeFirstDot ? drawnPixel : 0,
            core.ReadPixel(rastPort, 2, 0));
        Assert.Equal(drawnPixel, core.ReadPixel(rastPort, 4, 0));
    }

    [Fact]
    public void LayeredWritePixelClipsBeforeProviderOwnedPenAdmission()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        var visibilityCalls = 0;
        bool IsVisible(int x, int y)
        {
            visibilityCalls++;
            return true;
        }

        // The explicit provider path owns the logical clipping decision.
        // The off-raster cell must therefore return the classic -1 result
        // without reading the provider-owned FgPen or asking the visibility
        // predicate to classify an impossible bitmap destination.
        Assert.True(
            GraphicsRasterOperations.TryWritePixel(
                memory,
                rastPort,
                -1,
                0,
                IsVisible,
                out var result));
        Assert.Equal(-1, result);
        Assert.Equal(0, visibilityCalls);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal(0, ReadByte(backing, 0x400));
        Assert.Equal(0, ReadByte(backing, 0x500));
    }

    [Fact]
    public void ClearEolAndClearScreenUseTextGeometryAndJam2BackgroundPen()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        Assert.Equal(0, core.SetFont(0x20, 0x300, fonts));
        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(0, core.SetBPen(0x20, 2));
        Assert.Equal(0, core.SetDrawMode(0x20, 1));
        Assert.Equal(0, core.Move(0x20, 2, 5));

        Assert.Equal(0, core.ClearEOL(0x20));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 2));
        Assert.Equal(2, core.ReadPixel(0x20, 2, 2));
        Assert.Equal(2, core.ReadPixel(0x20, 15, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 4));

        Assert.Equal(0, core.SetDrawMode(0x20, 2));
        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(0, core.ClearScreen(0x20));
        // COMPLEMENT without JAM2 clears to pen zero even when BPen is
        // non-zero.
        Assert.Equal(0, core.ReadPixel(0x20, 2, 2));
        Assert.Equal(0, core.ReadPixel(0x20, 15, 7));

        // The native bgfill_pen() rule tests the JAM2 bit itself.  Combined
        // JAM2 modes therefore still select BPen for ClearEOL/ClearScreen;
        // they are not reduced to the clean base-mode value 1.
        Assert.Equal(0, core.SetDrawMode(0x20, 3)); // JAM2 | COMPLEMENT
        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(0, core.ClearEOL(0x20));
        // ClearEOL leaves the combined draw mode active; COMPLEMENT toggles
        // the selected BPen source, so the prefilled pen-3 raster becomes 0.
        Assert.Equal(0, core.ReadPixel(0x20, 2, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 5));

        Assert.Equal(0, core.SetDrawMode(0x20, 5)); // JAM2 | INVERSVID
        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(0, core.ClearEOL(0x20));
        Assert.Equal(2, core.ReadPixel(0x20, 2, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 5));
    }

    [Fact]
    public void ClearEolUsesGuestTextFontHeightBeforeCachedTxHeight()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;

        Assert.Equal(0, core.SetFont(rastPort, font, new FakeFontBackend()));
        Assert.Equal(0, core.SetRast(rastPort, 3));
        Assert.Equal(0, core.SetBPen(rastPort, 2));
        Assert.Equal(0, core.SetDrawMode(rastPort, 1));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            4));
        // Deliberately stale cache state: the selected guest TextFont is four
        // rows high, while TxHeight still describes only one row.
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            1));
        Assert.Equal(0, core.Move(rastPort, 2, 5));

        Assert.Equal(0, core.ClearEOL(rastPort));
        Assert.Equal(2, core.ReadPixel(rastPort, 15, 5));
        Assert.Equal(3, core.ReadPixel(rastPort, 15, 6));

        // The register gateway must expose the same guest-font geometry and
        // retain its normal void-vector D0/cycle contract.
        Assert.Equal(0, core.SetRast(rastPort, 3));
        Assert.Equal(0, core.Move(rastPort, 2, 5));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 83
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ClearEOL));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(83, state.Cycles);
        Assert.Equal(2, core.ReadPixel(rastPort, 15, 5));
        Assert.Equal(3, core.ReadPixel(rastPort, 15, 6));
    }

    [Fact]
    public void ClearVectorsLeaveAnOddGuestFontPointerToTheNativeBoundary()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint patternCount = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        static (FakeMemory Memory, GraphicsLibraryCore Core) Prepare(
            uint rastPort,
            uint font)
        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            var fonts = new FakeFontBackend();

            Assert.Equal(0, core.SetFont(rastPort, font, fonts));
            Assert.Equal(0, core.SetRast(rastPort, 3));
            Assert.Equal(0, core.SetBPen(rastPort, 2));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));
            // Corrupt the selected TextFont after SetFont.  ClearEOL and
            // ClearScreen must not reinterpret this malformed odd pointer as
            // the synthetic cached-height fallback.
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortFont,
                font + 1));
            return (memory, core);
        }

        var direct = Prepare(rastPort, font);
        Assert.Equal(-1, direct.Core.ClearEOL(rastPort));
        Assert.Equal((byte)4, ReadByte(direct.Memory, patternCount));
        Assert.Equal(3, direct.Core.ReadPixel(rastPort, 0, 0));

        direct = Prepare(rastPort, font);
        Assert.Equal(-1, direct.Core.ClearScreen(rastPort));
        Assert.Equal((byte)4, ReadByte(direct.Memory, patternCount));
        Assert.Equal(3, direct.Core.ReadPixel(rastPort, 0, 0));

        foreach (var vector in new[] { GraphicsLvo.ClearEOL, GraphicsLvo.ClearScreen })
        {
            var mapped = Prepare(rastPort, font);
            var adapter = new CopperStartGraphicsRegisterAdapter(mapped.Core);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 47
            };

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(47, state.Cycles);
            Assert.Equal((byte)4, ReadByte(mapped.Memory, patternCount));
            Assert.Equal(3, mapped.Core.ReadPixel(rastPort, 0, 0));
        }
    }

    [Fact]
    public void ClearVectorsRejectATextRowTopOutsideTheSignedWordEnvelope()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint patternCount = rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount;

        static (FakeMemory Memory, GraphicsLibraryCore Core) Prepare(
            uint rastPort,
            uint font)
        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            Assert.Equal(0, core.SetFont(rastPort, font, new FakeFontBackend()));
            Assert.Equal(0, core.SetRast(rastPort, 3));

            // cp_y - TxBaseline = -65535, while the 32768-row text band
            // ends at -32768. The bottom endpoint alone fits a signed WORD;
            // the top endpoint does not and must not wrap into a visible row.
            Assert.True(memory.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortCurrentY,
                unchecked((ushort)short.MinValue)));
            Assert.True(memory.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
                0x7FFF));
            Assert.True(memory.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
                0x8000));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
                4));
            return (memory, core);
        }

        foreach (var clear in new Func<GraphicsLibraryCore, int>[]
        {
            core => core.ClearEOL(rastPort),
            core => core.ClearScreen(rastPort)
        })
        {
            var direct = Prepare(rastPort, font);
            Assert.Equal(-1, clear(direct.Core));
            Assert.Equal((byte)4, ReadByte(direct.Memory, patternCount));
            Assert.Equal(3, direct.Core.ReadPixel(rastPort, 1, 1));
        }

        foreach (var vector in new[] { GraphicsLvo.ClearEOL, GraphicsLvo.ClearScreen })
        {
            var mapped = Prepare(rastPort, font);
            var adapter = new CopperStartGraphicsRegisterAdapter(mapped.Core);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0xCAFE_BABEu },
                Cycles = 53
            };

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(53, state.Cycles);
            Assert.Equal((byte)4, ReadByte(mapped.Memory, patternCount));
            Assert.Equal(3, mapped.Core.ReadPixel(rastPort, 1, 1));
        }
    }

    [Fact]
    public void ClearOperationsRestartLinePatternPhaseLikeTheirClassicPenPath()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var phase = 0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount;

        Assert.Equal(0, core.SetFont(0x20, 0x300, new FakeFontBackend()));
        Assert.True(memory.TryWriteByte(phase, 4));
        Assert.Equal(0, core.ClearEOL(0x20));
