    [Fact]
    public void ClearOperationsRestoreLinePatternPhaseWhenItsFinalPublicationFails()
    {
        static void AssertClearRollback(Func<IGraphicsMemory, int> clear, uint phaseAddress)
        {
            var backing = new FakeMemory(0x2000);
            var memory = new FailingByteWriteMemory(backing);
            var core = CreateCore(memory);

            Assert.Equal(0, core.SetFont(0x20, 0x300, new FakeFontBackend()));
            Assert.True(backing.TryWriteByte(
                0x20u + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.True(backing.TryWriteByte(phaseAddress, 4));
            memory.FailOnNextByteWrite(1);

            Assert.Equal(-1, clear(memory));
            Assert.Equal((byte)4, ReadByte(backing, phaseAddress));
        }

        AssertClearRollback(
            memory => GraphicsRasterOperations.ClearEOL(memory, 0x20),
            0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount);
        AssertClearRollback(
            memory => GraphicsRasterOperations.ClearScreen(memory, 0x20),
            0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount);
    }

