    [Fact]
    public void LayeredEraseRectSkipsProviderHiddenRectangleBeforePenAdmission()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        _ = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.True(backing.TryWriteByte(plane0, 0x5A));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            4));

        // APen/BPen belong to the provider-owned context for this layered
        // destination.  A fully hidden rectangle must not admit either pen.
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            (uint)(GraphicsLayouts.RastPortBgPen - GraphicsLayouts.RastPortFgPen + 1));

        Assert.Equal(
            0,
            GraphicsRasterOperations.EraseRect(
                memory,
                rastPort,
                0,
                0,
                7,
                3,
                pixelVisible: static (_, _) => false));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((byte)0x5A, ReadByte(backing, plane0));
        Assert.Equal(
            (byte)4,
            ReadByte(
                backing,
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void LayeredEraseRectReusesVisibilityAcrossOuterSnapshotAndNestedFill()
    {
        var memory = new FakeMemory(0x2000);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x400;
        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));
        Assert.True(memory.TryWriteByte(plane, 0xFF));

        var providerCalls = new Dictionary<(int X, int Y), int>();
        bool IsVisible(int x, int y)
        {
            var key = (x, y);
            providerCalls.TryGetValue(key, out var calls);
            providerCalls[key] = calls + 1;
            return calls == 0;
        }

        Assert.Equal(
            0,
            GraphicsRasterOperations.EraseRect(
                memory,
                rastPort,
                0,
                0,
                7,
                0,
                pixelVisible: IsVisible));

        Assert.Equal(8, providerCalls.Count);
        Assert.All(providerCalls.Values, calls => Assert.Equal(1, calls));
        Assert.Equal((byte)0, ReadByte(memory, plane));
    }

