        Assert.True(memory.TryWriteByte(phase, 4));
        Assert.Equal(0, core.ScrollRaster(0x20, 1, 0, 0, 0, 7, 0));
        Assert.Equal((byte)15, ReadByte(memory, phase));

        Assert.True(memory.TryWriteByte(phase, 4));
