    [Fact]
    public void ZeroDisplacementScrollsAreNoOpsForPixelsAndLinePatternPhase()
    {
        static void AssertNoOp(
            Func<GraphicsLibraryCore, int> scroll,
            FakeMemory memory,
            GraphicsLibraryCore core,
            uint phase)
        {
            Assert.Equal(0, core.SetAPen(0x20, 3));
            Assert.Equal(0, core.WritePixel(0x20, 4, 3));
            Assert.True(memory.TryWriteByte(phase, 4));

            Assert.Equal(0, scroll(core));
            Assert.Equal(3, core.ReadPixel(0x20, 4, 3));
            Assert.Equal((byte)4, ReadByte(memory, phase));
        }

        var normalMemory = new FakeMemory(0x2000);
        var normalCore = CreateCore(normalMemory);
        var normalPhase = 0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount;
        AssertNoOp(
            core => core.ScrollRaster(0x20, 0, 0, 0, 0, 7, 7),
            normalMemory,
            normalCore,
            normalPhase);

        var backgroundMemory = new FakeMemory(0x2000);
        var backgroundCore = CreateCore(backgroundMemory);
        var backgroundPhase = 0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount;
        AssertNoOp(
            core => core.ScrollRasterBF(0x20, 0, 0, 0, 0, 7, 7),
            backgroundMemory,
            backgroundCore,
            backgroundPhase);
    }

    [Fact]
    public void ScrollOperationsRestoreLinePatternPhaseWhenTheirFinalPublicationFails()
    {
        static void AssertScrollRollback(
            Func<IGraphicsMemory, int> scroll,
            uint phaseAddress)
        {
            var backing = new FakeMemory(0x2000);
            var memory = new FailingByteWriteMemory(backing);

            Assert.True(backing.TryWriteByte(
                0x20u + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.True(backing.TryWriteByte(phaseAddress, 4));
            memory.FailOnNextByteWrite(1);

            Assert.Equal(-1, scroll(memory));
            Assert.Equal((byte)4, ReadByte(backing, phaseAddress));
        }

        AssertScrollRollback(
            memory => GraphicsRasterOperations.ScrollRaster(memory, 0x20, 1, 0, 0, 0, 7, 0),
            0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount);
        AssertScrollRollback(
            memory => GraphicsRasterOperations.ScrollRasterBF(memory, 0x20, 1, 0, 0, 0, 7, 0),
            0x20u + (uint)GraphicsLayouts.RastPortLinePatternCount);
    }

