    [Fact]
    public void WritePixelObeysInverseVideoAndComplementMintermSelection()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetBPen(rastPort, 2));

        // The implicit WritePixel source cell is selected.  JAM1 and JAM2
        // therefore deposit APen, while COMPLEMENT toggles every selected
        // destination plane regardless of the pen value.
        foreach (var mode in new byte[] { 0, 1, 2, 3 })
        {
            Assert.True(memory.TryWriteByte(plane0, 0));
            Assert.True(memory.TryWriteByte(plane1, 0));
            Assert.Equal(0, core.SetDrawMode(rastPort, mode));
            Assert.Equal(0, core.WritePixel(rastPort, 0, 0));
            Assert.Equal(mode is 2 or 3 ? 3 : 1, core.ReadPixel(rastPort, 0, 0));
        }

        // INVERSVID flips that implicit source cell to zero.  JAM1 leaves it
        // untouched, JAM2 deposits BPen, and inverse COMPLEMENT has no
        // selected cell to complement.
        foreach (var (mode, expected) in new[]
                 {
                     (4, 3),
                     (5, 2),
                     (6, 3),
                     (7, 3)
                 })
        {
            Assert.True(memory.TryWriteByte(plane0, 0xC0));
            Assert.True(memory.TryWriteByte(plane1, 0xC0));
            Assert.Equal(0, core.SetDrawMode(rastPort, (byte)mode));
            Assert.Equal(0, core.WritePixel(rastPort, 0, 0));
            Assert.Equal(expected, core.ReadPixel(rastPort, 0, 0));
        }
    }

    [Fact]
    public void WritePixelDeclinesPrivateNoPensWithoutReadingPublicForegroundAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        // The resident WritePixel path uses a private graphics-context colour
        // sidecar when RPF_NO_PENS is set.  The portable core has no such
        // sidecar, so it must decline before probing FgPen or touching the
        // planar destination.  The direct and register-adapter paths must
        // make the same ownership decision.
        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.True(backing.TryWriteByte(plane0, 0xA5));
            Assert.True(backing.TryWriteByte(plane1, 0x5A));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte));

            Assert.Equal(-1, core.WritePixel(rastPort, 0, 0));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0xA5, ReadByte(backing, plane0));
            Assert.Equal((byte)0x5A, ReadByte(backing, plane1));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.True(backing.TryWriteByte(plane0, 0xA5));
            Assert.True(backing.TryWriteByte(plane1, 0x5A));
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte));

            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 0, [1] = 0 },
                Cycles = 57
            };

            Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WritePixel));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(57, state.Cycles);
            Assert.Equal((byte)0xA5, ReadByte(backing, plane0));
            Assert.Equal((byte)0x5A, ReadByte(backing, plane1));
        }
    }

    [Fact]
    public void WritePixelRestoresEarlierPlanesWhenALaterPlaneWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.True(backing.TryWriteByte(plane0, 0));
        Assert.True(backing.TryWriteByte(plane1, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 3));

        // Plane zero publishes first; fail plane one and require the helper
        // to restore the earlier write before returning the documented error.
        memory.FailOnNextByteWrite(2);
        Assert.Equal(-1, core.WritePixel(rastPort, 0, 0));
        Assert.Equal((byte)0, ReadByte(backing, plane0));
        Assert.Equal((byte)0, ReadByte(backing, plane1));
    }

    [Fact]
    public void DrawRestoresEarlierPixelsAndRastPortStateWhenAPlanarWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.True(backing.TryWriteByte(plane0, 0));
        Assert.True(backing.TryWriteByte(plane1, 0));
        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        var originalFlags = ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags);
        var originalPatternCount = ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount);

        // Two planes are written for the first pixel and plane zero is
        // written for the second; fail the second pixel's plane-one write.
        memory.FailOnNextByteWrite(4);
        Assert.Equal(-1, core.Draw(rastPort, 1, 0));
        Assert.Equal((byte)0, ReadByte(backing, plane0));
        Assert.Equal((byte)0, ReadByte(backing, plane1));
        Assert.Equal(originalFlags, ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(originalPatternCount, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal((short)0, unchecked((short)ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)0, unchecked((short)ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
    }

    [Fact]
    public void DrawRestoresCursorAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;
        var cursorAddress = rastPort + (uint)GraphicsLayouts.RastPortCurrentX;

        Assert.True(backing.TryWriteByte(plane0, 0));
        Assert.True(backing.TryWriteByte(plane1, 0));
        Assert.Equal(0, core.Move(rastPort, 0, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 3));
        var originalFlags = ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags);
        var originalPatternCount = ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount);

        // Draw publishes the destination pixels before its final CurrentX
        // WORD. Accept only that WORD's high byte, reject the call, and
        // require the transaction rollback to restore both pixels and state.
        memory.PartialWordAddress = cursorAddress;

        Assert.Equal(-1, core.Draw(rastPort, 1, 0));
        Assert.Equal((byte)0, ReadByte(backing, plane0));
        Assert.Equal((byte)0, ReadByte(backing, plane1));
        Assert.Equal((short)0, ReadSignedWord(backing, cursorAddress));
        Assert.Equal(
            originalFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
        Assert.Equal(
            originalPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.Draw(rastPort, 1, 0));
        Assert.Equal((short)1, ReadSignedWord(backing, cursorAddress));
    }

    [Fact]
    public void SetRastRestoresEarlierRowsAndPlanesWhenAWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        for (var offset = 0; offset < 16; offset++)
        {
            Assert.True(backing.TryWriteByte(plane0 + (uint)offset, 0x5A));
            Assert.True(backing.TryWriteByte(plane1 + (uint)offset, 0xA5));
        }

        // The first pixel completes both planes; fail during the next pixel
        // and require the complete raster snapshot to be restored.
        memory.FailOnNextByteWrite(4);
        Assert.Equal(-1, core.SetRast(rastPort, 0));
        Assert.Equal((byte)0x5A, ReadByte(backing, plane0));
        Assert.Equal((byte)0x5A, ReadByte(backing, plane0 + 1u));
        Assert.Equal((byte)0xA5, ReadByte(backing, plane1));
        Assert.Equal((byte)0xA5, ReadByte(backing, plane1 + 1u));
    }

