    [Fact]
    public void FixedTextLengthRejectsWrappedRastPortAddresses()
    {
        var memory = new FakeMemory(0x100);
        var core = CreateCore(memory);
        const uint wrappedRastPort = 0xFFFF_FFF0u;

        // The unchecked addresses below alias low guest memory.  The
        // portable boundary must reject the original high pointer before it
        // can observe those wrapped fields.
        Assert.True(memory.TryWriteWord(
            unchecked(wrappedRastPort + (uint)GraphicsLayouts.RastPortTextWidth),
            1));
        Assert.True(memory.TryWriteWord(
            unchecked(wrappedRastPort + (uint)GraphicsLayouts.RastPortTextSpacing),
            0));

        Assert.Equal(-1, core.TextLength(wrappedRastPort, 1));
    }

    [Fact]
    public void RastPortScalarVectorsRejectWrappedHighGuestAddresses()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint wrappedRastPort = 0xFFFF_FFF0u;

        // Populate the low aliases that unchecked 32-bit addition would
        // otherwise expose.  The original high RastPort must fail closed for
        // both scalar state and cursor updates, leaving those aliases alone.
        memory.WriteByte(0x09, 7);
        memory.WriteByte(0x18, 0xFF);
        memory.WriteByte(0x14, 0xAA);
        memory.WriteByte(0x15, 0xBB);
        memory.WriteByte(0x16, 0xCC);
        memory.WriteByte(0x17, 0xDD);
        memory.WriteByte(0x1E, 3);

        Assert.Equal(-1, core.SetAPen(wrappedRastPort, 2));
        Assert.Equal(-1, core.SetWriteMask(wrappedRastPort, 1));
        Assert.Equal(-1, core.GetAPen(wrappedRastPort));
        Assert.Equal(-1, core.Move(wrappedRastPort, 4, 5));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = wrappedRastPort },
            D = { [0] = 0xDEAD_BEEFu }
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetAPen));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);

        Assert.True(memory.TryReadByte(0x09, out var lowPen));
        Assert.True(memory.TryReadByte(0x18, out var lowMask));
        Assert.True(memory.TryReadByte(0x1E, out var lowPatternCount));
        Assert.True(memory.TryReadByte(0x14, out var lowXHigh));
        Assert.True(memory.TryReadByte(0x15, out var lowXLow));
        Assert.True(memory.TryReadByte(0x16, out var lowYHigh));
        Assert.True(memory.TryReadByte(0x17, out var lowYLow));
        Assert.Equal((byte)7, lowPen);
        Assert.Equal((byte)0xFF, lowMask);
        Assert.Equal((byte)3, lowPatternCount);
        Assert.Equal((byte)0xAA, lowXHigh);
        Assert.Equal((byte)0xBB, lowXLow);
        Assert.Equal((byte)0xCC, lowYHigh);
        Assert.Equal((byte)0xDD, lowYLow);

        // Initialization and tag queries use the same checked RastPort
        // envelope.  Their source fields must not satisfy themselves from
        // the low aliases exposed by the wrapping memory provider.
        Assert.False(GraphicsRasterOperations.InitializeRastPort(memory, wrappedRastPort));

        const uint tags = 0x80;
        const uint result = 0xA0;
        memory.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagWriteMask);
        memory.WriteLong(tags + 4u, result);
        memory.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        memory.WriteLong(tags + 12u, 0);
        memory.WriteLong(result, 0xA5A5_5A5Au);

        Assert.False(GraphicsRastPortAttributeOperations.Get(
            memory,
            wrappedRastPort,
            tags,
            new FakeFontBackend()));
        Assert.True(memory.TryReadLong(result, out var untouchedResult));
        Assert.Equal(0xA5A5_5A5Au, untouchedResult);
    }

    [Fact]
    public void TextMetricsRejectWrappedRastPortAndConstraintAddresses()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x400;
        const uint extent = 0x500;
        const uint wrappedRastPort = 0xFFFF_FFF0u;
        const uint wrappedConstraint = 0xFFFF_FFF8u;

        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        memory.WriteByte(text, (byte)'A');

        // These low aliases would satisfy the old unchecked metric reads.
        memory.WriteLong(
            unchecked(wrappedRastPort + (uint)GraphicsLayouts.RastPortFont),
            font);
        memory.WriteWord(
            unchecked(wrappedRastPort + (uint)GraphicsLayouts.RastPortTextSpacing),
            0);
        memory.WriteWord(unchecked(wrappedConstraint + 0), 8);
        memory.WriteWord(unchecked(wrappedConstraint + 2), 3);
        memory.WriteWord(unchecked(wrappedConstraint + 4), 0);
        memory.WriteWord(unchecked(wrappedConstraint + 6), unchecked((ushort)-3));
        memory.WriteWord(unchecked(wrappedConstraint + 8), 7);
        memory.WriteWord(unchecked(wrappedConstraint + 10), unchecked((ushort)-1));

        Assert.False(core.TryTextLength(wrappedRastPort, text, 1, fonts, out _));
        Assert.Equal(
            -1,
            core.TextFit(
                rastPort,
                text,
                1,
                extent,
                wrappedConstraint,
                1,
                8,
                2,
                fonts));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent, [3] = wrappedConstraint },
            D = { [0] = 1, [1] = 1, [2] = 8, [3] = 3 }
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
    }

    [Fact]
    public void TextMetricsRejectWrappedGuestTextSpansButAcceptTheInclusiveAddressEnd()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint extent = 0x500;
        ushort ReadWordAt(uint address)
        {
            Assert.True(memory.TryReadWord(address, out var value));
            return value;
        }

        byte ReadByteAt(uint address)
        {
            Assert.True(memory.TryReadByte(address, out var value));
            return value;
        }

        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0);
        memory.WriteByte(uint.MaxValue, (byte)'A');

        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            memory.WriteByte(extent + (uint)offset, 0xA5);

        // The last byte of the 32-bit guest address space is a valid
        // one-character string.  The span guard must not reject that
        // inclusive endpoint merely because the next byte would wrap.
        Assert.Equal(0, core.TextExtent(rastPort, uint.MaxValue, 1, extent, fonts));
        Assert.Equal((ushort)4, ReadWordAt(extent + (uint)GraphicsLayouts.TextExtentWidth));

        // A two-byte ULONG request would cross 0xffffffff.  Reject it before
        // the metric loop can consume a wrapped low alias, and keep both the
        // metric result and the reverse-direction result unmodified.
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            memory.WriteByte(extent + (uint)offset, 0x5A);

        Assert.Equal(-1, core.TextLength(rastPort, uint.MaxValue, 2, fonts));
        Assert.Equal(-1, core.TextExtent(rastPort, uint.MaxValue, 2, extent, fonts));
        Assert.Equal(
            -1,
            core.TextFit(rastPort, 1, 3, extent, 0, -1, 8, 3, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0x5A, ReadByteAt(extent + (uint)offset));
    }

    [Fact]
    public void TextMetricsRejectUnboundedCoreCountsButGatewayUsesLowWords()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x400;
        const uint extent = 0x500;
        const uint constraint = 0x600;
        const uint hugeCount = 0x8000_0000u;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            0));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteWord(constraint + 0, 32));
        Assert.True(memory.TryWriteWord(constraint + 2, 3));
        Assert.True(memory.TryWriteWord(constraint + 4, 0));
        Assert.True(memory.TryWriteWord(constraint + 6, unchecked((ushort)-3)));
        Assert.True(memory.TryWriteWord(constraint + 8, 31));
        Assert.True(memory.TryWriteWord(constraint + 10, unchecked((ushort)-1)));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.True(memory.TryWriteByte(extent + (uint)offset, 0x5A));

        // The span endpoint is still inside the 32-bit guest address space;
        // the rejection is specifically the portable character-walk budget,
        // not the address-wrap guard.
        Assert.Equal(-1, core.TextLength(rastPort, text, hugeCount, fonts));
        Assert.Equal(-1, core.TextExtent(rastPort, text, hugeCount, extent, fonts));
        Assert.Equal(
            -1,
            core.TextFit(rastPort, text, hugeCount, extent, constraint, 1, 8, 3, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0x5A, ReadByte(memory, extent + (uint)offset));

        // The register vectors expose WORD/UWORD counts.  Clear the selected
        // font so the low-word-only zero request reaches the cached metric
        // path after the direct widened-count checks above.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            0));

        var textLengthState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = hugeCount },
            Cycles = 43
        };
        Assert.True(adapter.TryInvoke(textLengthState, (int)GraphicsLvo.TextLength));
        Assert.Equal(0u, textLengthState.D[0]);
        Assert.Equal(43, textLengthState.Cycles);

        var textFitState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent, [3] = constraint },
            D = { [0] = hugeCount, [1] = 1, [2] = 8, [3] = 3 },
            Cycles = 43
        };
        Assert.True(adapter.TryInvoke(textFitState, (int)GraphicsLvo.TextFit));
        Assert.Equal(0u, textFitState.D[0]);
        Assert.Equal(43, textFitState.Cycles);
    }

    [Fact]
    public void TextMetricVectorsRejectOddTextExtentAddresses()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
