        const uint oddExtent = 0x341;

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.True(memory.TryWriteByte(oddExtent + (uint)offset, 0xA5));

        Assert.Equal(-1, core.TextExtent(rastPort, text, 1, oddExtent, fonts));
        Assert.Equal(-1, core.TextFit(rastPort, text, 1, oddExtent, 0, 1, 8, 3, fonts));
        Assert.Equal(-1, core.FontExtent(font, oddExtent, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
