    [Fact]
    public void TextStateVectorsRejectOddRastPortAddresses()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint oddRastPort = 0x121;
        const uint font = 0x300;
        const uint text = 0x340;
        const uint extent = 0x380;

        // The host memory model can byte-address this object, but a native
        // 68000 cannot legally consume a word/long RastPort at an odd base.
        // Populate enough fields to prove the rejection is an ownership
        // boundary rather than an incidental unmapped-memory failure.
        Assert.True(memory.TryWriteLong(oddRastPort + (uint)GraphicsLayouts.RastPortFont, font));
        Assert.True(memory.TryWriteWord(oddRastPort + (uint)GraphicsLayouts.RastPortTextWidth, 3));
        Assert.True(memory.TryWriteWord(oddRastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0));
        Assert.True(memory.TryWriteByte(oddRastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 0));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.True(memory.TryWriteByte(extent + (uint)offset, 0xA5));

        Assert.Equal(-1, core.SetFont(oddRastPort, font, fonts));
        Assert.Equal(-1, core.AskSoftStyle(oddRastPort, fonts));
        Assert.Equal(-1, core.SetSoftStyle(oddRastPort, 1, 1, fonts));
        Assert.Equal(-1, core.TextLength(oddRastPort, text, 1, fonts));
        Assert.Equal(-1, core.TextExtent(oddRastPort, text, 1, extent, fonts));
        Assert.Equal(-1, core.TextFit(oddRastPort, text, 1, extent, 0, 1, 8, 3, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0xA5, ReadByte(memory, extent + (uint)offset));

        // The fixed-metric register fallback must observe the same boundary;
        // otherwise the host adapter could claim an odd RastPort when its
        // Font field is NULL and only cached width/spacing are needed.
        Assert.True(memory.TryWriteLong(oddRastPort + (uint)GraphicsLayouts.RastPortFont, 0));
        var state = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 1, [1] = 0xCAFE_BABEu },
            Cycles = 77
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextLength));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(77, state.Cycles);
    }

    [Fact]
    public void DrawingStateVectorsRejectOddRastPortAddresses()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint oddRastPort = 0x121;

        Assert.True(memory.TryWriteByte(
            oddRastPort + (uint)GraphicsLayouts.RastPortFgPen,
            2));
        Assert.True(memory.TryWriteByte(
            oddRastPort + (uint)GraphicsLayouts.RastPortBgPen,
            3));
        Assert.True(memory.TryWriteByte(
            oddRastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            1));
        Assert.True(memory.TryWriteByte(
            oddRastPort + (uint)GraphicsLayouts.RastPortMask,
            0x0F));
        Assert.True(memory.TryWriteByte(
            oddRastPort + (uint)GraphicsLayouts.RastPortOutlinePen,
            4));
        Assert.True(memory.TryWriteWord(
            oddRastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            10));
        Assert.True(memory.TryWriteWord(
            oddRastPort + (uint)GraphicsLayouts.RastPortCurrentY,
            11));

        // These operations all consume RastPort byte/word state. The shared
        // helpers must reject the odd base before a host byte-addressable
        // memory model can publish a drawing-state mutation.
        Assert.Equal(-1, core.SetAPen(oddRastPort, 7));
        Assert.Equal(-1, core.SetBPen(oddRastPort, 8));
        Assert.Equal(-1, core.SetDrawMode(oddRastPort, 2));
        Assert.Equal(-1, core.GetAPen(oddRastPort));
        Assert.Equal(-1, core.GetBPen(oddRastPort));
        Assert.Equal(-1, core.GetDrawMode(oddRastPort));
        Assert.Equal(-1, core.SetABPenDrMd(oddRastPort, 7, 8, 2));
        Assert.Equal(-1, core.SetWriteMask(oddRastPort, 3));
        Assert.Equal(-1, core.SetMaxPen(oddRastPort, 7));
        // SetMaxPen(0) returns before touching RastPort->Mask in the
        // Kickstart implementation, so an odd host-readable address still
        // has a successful field-free no-op.
        Assert.Equal(0, core.SetMaxPen(oddRastPort, 0));
        Assert.Equal(-1, core.GetMaxPen(oddRastPort));
        Assert.Equal(-1, core.GetOutlinePen(oddRastPort));
        Assert.Equal(-1, core.SetOutlinePen(oddRastPort, 6));
        Assert.Equal(-1, core.Move(oddRastPort, 20, 21));

        Assert.Equal((byte)2, ReadByte(
            memory,
            oddRastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)3, ReadByte(
            memory,
            oddRastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)1, ReadByte(
            memory,
            oddRastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        Assert.Equal((byte)0x0F, ReadByte(
            memory,
            oddRastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal((ushort)10, ReadWord(
            memory,
            oddRastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)11, ReadWord(
            memory,
            oddRastPort + (uint)GraphicsLayouts.RastPortCurrentY));

        var setPen = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 7 },
            Cycles = 83
        };
        Assert.False(adapter.TryInvoke(setPen, (int)GraphicsLvo.SetAPen));
        Assert.Equal(7u, setPen.D[0]);
        Assert.Equal(83, setPen.Cycles);

        var zeroMaxPen = new M68kCpuState
        {
            A = { [0] = oddRastPort },
            D = { [0] = 0 },
            Cycles = 87
        };
        Assert.True(adapter.TryInvoke(zeroMaxPen, (int)GraphicsLvo.SetMaxPen));
        Assert.Equal(0u, zeroMaxPen.D[0]);
        Assert.Equal(87, zeroMaxPen.Cycles);

        var move = new M68kCpuState
        {
            A = { [1] = oddRastPort },
            D = { [0] = 20, [1] = 21 },
            Cycles = 89
        };
        Assert.False(adapter.TryInvoke(move, (int)GraphicsLvo.Move));
        Assert.Equal(20u, move.D[0]);
        Assert.Equal(89, move.Cycles);
    }

    [Fact]
    public void DrawingStateSettersRejectOddAndNullRastPortsBeforeHostProbe()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new ReadTrackingMemory(backing);
        var core = CreateCore(memory);
        memory.ReadCount = 0;

        // A host byte-addressable mapping at either address must not turn a
        // NULL or odd guest RastPort into a claimed compatibility setter. The
        // shared field helpers must reject the ownership boundary before the
        // first host read, matching the native 68000 address/alignment path.
        Assert.Equal(-1, core.SetAPen(0, 7));
        Assert.Equal(0, memory.ReadCount);

        Assert.Equal(-1, core.SetAPen(0x121, 7));
        Assert.Equal(0, memory.ReadCount);
    }

