    }

    [Fact]
    public void ReadPixelArray8StagesSourceSamplesWhenOutputAliasesAPlanarSource()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x800;
        const uint bitMap = 0x1000;
        const uint plane = 0x1200;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0x01));
        WritePlanarBitmap(memory, bitMap, plane, 0, rows: 1, depth: 1);
        // Pixel 0 is set; pixel 7 is clear.  A streaming read that writes
        // byte-per-pen output back into this same plane would turn the low
        // bit into one while it is still decoding pixel 7.
        Assert.True(memory.TryWriteByte(plane, 0x80));
        Assert.True(memory.TryWriteByte(plane + 1, 0));

        Assert.Equal(8, core.ReadPixelArray8(
            rastPort,
            0,
            0,
            7,
            0,
            plane,
            0));
        Assert.Equal((byte)1, ReadByte(memory, plane));
        for (var index = 1u; index < 8; index++)
            Assert.Equal((byte)0, ReadByte(memory, plane + index));

        // Re-run through the CopperStart register boundary as well.  The
        // adapter must observe the same staged source result and count.
        Assert.True(memory.TryWriteByte(plane, 0x80));
        for (var index = 1u; index < 8; index++)
            Assert.True(memory.TryWriteByte(plane + index, 0xEE));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = plane },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 0 },
            Cycles = 913
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ReadPixelArray8));
        Assert.Equal(8u, state.D[0]);
        Assert.Equal(913, state.Cycles);
        Assert.Equal((byte)1, ReadByte(memory, plane));
        for (var index = 1u; index < 8; index++)
            Assert.Equal((byte)0, ReadByte(memory, plane + index));
    }

    [Fact]
    public void PixelArrayRegisterVectorsDecodeUwordCoordinatesAndCounts()
    {
        var memory = new FakeMemory(0x20000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint array = 0x10000;

        // ReadPixelLine8 and WritePixelLine8 declare their coordinate/count
        // arguments as UWORDs.  A high-bit value therefore remains a large
        // non-negative request at the native register boundary; it must not
        // become a negative coordinate or a rejected width merely because
        // the host implementation uses signed arithmetic internally.
        var read = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 0x7FFFu },
            Cycles = 741
        };

        Assert.True(adapter.TryInvoke(read, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(16u, read.D[0]);
        Assert.Equal(741, read.Cycles);

        var write = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 0x7FFFu },
            Cycles = 743
        };

        Assert.True(adapter.TryInvoke(write, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(16u, write.D[0]);
        Assert.Equal(743, write.Cycles);

        var highBit = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0xFFFF_0001u, [1] = 0xCAFE_FFFFu, [2] = 1 },
            Cycles = 745
        };

        // The one-pixel request is fully staged even though its unsigned
        // origin lies outside the small test bitmap.  The V36 line helper
        // reports the actual pixels read after clipping and consumes the low
        // words without allowing high-register residue to change them.
        Assert.True(adapter.TryInvoke(highBit, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(0u, highBit.D[0]);
        Assert.Equal(745, highBit.Cycles);
    }

    [Fact]
    public void PixelArray8ClipsToPlanarBitmapAndRejectsMalformedRanges()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint array = 0x900;
        Assert.True(memory.TryWriteByte(array, 1));
        Assert.True(memory.TryWriteByte(array + 1, 2));
        Assert.True(memory.TryWriteByte(array + 2, 3));

        Assert.Equal(1, core.WritePixelLine8(0x20, 15, 0, 3, array, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 15, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 14, 0));
        Assert.Equal(1, core.ReadPixelLine8(0x20, 15, 0, 3, array, 0));
        Assert.Equal((byte)1, ReadByte(memory, array));
        Assert.Equal((byte)0, ReadByte(memory, array + 1));
        Assert.Equal((byte)0, ReadByte(memory, array + 2));

        // The same clipped line must preserve its actual plotted/read count
        // through the CopperStart register boundary without changing the
        // cycle state.  This is the mapped 68k-facing half of the contract.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var mapped = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 15, [1] = 0, [2] = 3 },
            Cycles = 997
        };
        Assert.True(adapter.TryInvoke(mapped, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(1u, mapped.D[0]);
        Assert.Equal(997, mapped.Cycles);
        mapped.D[0] = 15;
        Assert.True(adapter.TryInvoke(mapped, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(1u, mapped.D[0]);
        Assert.Equal(997, mapped.Cycles);

        // Array helpers return the clipped pixel count across all rows, not
        // the requested rectangle area.  Their padded source/destination
        // envelope still covers the complete logical request.
        Assert.True(memory.TryWriteByte(array + 0, 2));
        Assert.True(memory.TryWriteByte(array + 1, 3));
        Assert.True(memory.TryWriteByte(array + 2, 4));
        Assert.True(memory.TryWriteByte(array + 16, 3));
        Assert.Equal(2, core.WritePixelArray8(0x20, 15, 0, 17, 1, array, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 15, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 15, 1));

        const uint clippedReadBack = 0xA00;
        for (var index = 0; index < 32; index++)
            Assert.True(memory.TryWriteByte(clippedReadBack + (uint)index, 0xEE));
        Assert.Equal(2, core.ReadPixelArray8(0x20, 15, 0, 17, 1, clippedReadBack, 0));
        Assert.Equal((byte)2, ReadByte(memory, clippedReadBack));
        Assert.Equal((byte)0, ReadByte(memory, clippedReadBack + 1));
        Assert.Equal((byte)0, ReadByte(memory, clippedReadBack + 2));
        Assert.Equal((byte)3, ReadByte(memory, clippedReadBack + 16));

        Assert.Equal(-1, core.WritePixelArray8(0x20, 4, 3, 3, 4, array, 0));
        Assert.Equal(-1, core.ReadPixelLine8(0x20, 0, 0, 3, 0, 0));
    }

    [Fact]
    public void ReadPixelLineStatusAdmissionDoesNotConsumeTheWriteMask()
    {
        var backing = new FakeMemory(0x2000);
        const uint array = 0x900;
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);

        for (var offset = 0u; offset < 16; offset++)
            Assert.True(memory.TryWriteByte(array + offset, 0xEE));

        // ReadPixelLine8 samples the linked BitMap and publishes the caller's
        // byte array; the RastPort write mask is not part of that ABI.  Keep
        // the mask unreadable to prove the status-aware/register path does
        // not claim a dependency that the direct portable body never reads.
        memory.FailReads(
            0x20u + (uint)GraphicsLayouts.RastPortMask,
            sizeof(byte));

        Assert.Equal(4, core.ReadPixelLine8(0x20, 0, 0, 4, array, 0));
        Assert.True(core.TryReadPixelLine8(
            0x20,
            0,
            0,
            4,
            array,
            0,
            out var statusResult));
        Assert.Equal(4, statusResult);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var mapped = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 1217
        };
        Assert.True(adapter.TryInvoke(mapped, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(4u, mapped.D[0]);
        Assert.Equal(1217, mapped.Cycles);
    }

    [Fact]
    public void PixelArrayStatusAdmissionSkipsMalformedBitmapProbeForFullyClippedRequests()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitMap = 0x100;
        const uint readArray = 0x900;
        const uint writeArray = 0xA00;

        // The portable bodies only probe bitmap pixels that fall inside the
        // requested rectangle.  Keep the first declared plane malformed so a
        // status adapter that unconditionally probes (0,0) would decline the
        // otherwise valid, fully clipped request.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x2000));
        for (var offset = 0u; offset < 16; offset++)
        {
            Assert.True(memory.TryWriteByte(readArray + offset, 0xEE));
            Assert.True(memory.TryWriteByte(writeArray + offset, 3));
        }

        const int x = 100;
        const int y = 100;
        Assert.Equal(0, core.ReadPixelLine8(0x20, x, y, 1, readArray, 0));
        Assert.Equal((byte)0, ReadByte(memory, readArray));
        Assert.Equal(0, core.WritePixelLine8(0x20, x, y, 1, writeArray, 0));
        Assert.Equal((byte)3, ReadByte(memory, writeArray));
        Assert.Equal(0, core.ReadPixelArray8(0x20, x, y, x, y, readArray, 0));
        Assert.Equal(0, core.WritePixelArray8(0x20, x, y, x, y, writeArray, 0));

        Assert.True(core.TryReadPixelLine8(
            0x20,
            x,
            y,
            1,
            readArray,
            0,
            out var readLineStatus));
        Assert.Equal(0, readLineStatus);
        Assert.True(core.TryWritePixelLine8(
            0x20,
            x,
            y,
            1,
            writeArray,
            0,
            out var writeLineStatus));
        Assert.Equal(0, writeLineStatus);
        Assert.True(core.TryReadPixelArray8(
            0x20,
            x,
            y,
            x,
            y,
            readArray,
            0,
            out var readArrayStatus));
        Assert.Equal(0, readArrayStatus);
        Assert.True(core.TryWritePixelArray8(
            0x20,
            x,
            y,
            x,
            y,
            writeArray,
            0,
            out var writeArrayStatus));
        Assert.Equal(0, writeArrayStatus);

        // Exercise the guest register boundary and the native-overlay route.
        // Both should preserve the same zero clipped count and leave the
        // malformed, untouched plane outside their admission decision.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var mapped = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = readArray },
            D = { [0] = x, [1] = y, [2] = 1 },
            Cycles = 1171
        };
        Assert.True(adapter.TryInvoke(mapped, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(0u, mapped.D[0]);
        Assert.Equal(1171, mapped.Cycles);

        var nativeOverlay = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = writeArray },
            D = { [0] = x, [1] = y, [2] = x, [3] = y },
            Cycles = 1173
        };
        Assert.True(adapter.TryInvoke(
            nativeOverlay,
            (int)GraphicsLvo.WritePixelArray8,
            nativeOverlay: true));
        Assert.Equal(0u, nativeOverlay.D[0]);
        Assert.Equal(1173, nativeOverlay.Cycles);
        Assert.Equal((byte)3, ReadByte(memory, writeArray));
    }

    [Fact]
    public void PixelLineZeroWidthClaimsAnEmptyNoOpBeforeBitmapArrayOrTemporaryValidation()
    {
        var memory = new FakeMemory(0x200);
        const uint rastPort = 0x20;

        // Only the RastPort layer field is present.  A zero-width line has
        // no bitmap, chunky array, or temporary-rastport cell to consume;
        // the portable owner must therefore claim the documented empty
        // request after establishing that the RastPort is non-layered.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        var core = CreateCoreWithoutRasterStorage(memory);

        Assert.Equal(0, core.ReadPixelLine8(
            rastPort,
            short.MaxValue,
            short.MaxValue,
            0,
            0,
            0x1F0));
        Assert.Equal(0, core.WritePixelLine8(
            rastPort,
            short.MinValue,
            short.MinValue,
            0,
            0x1F0,
            0x1F4));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var read = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0x1F4, [2] = 0 },
            D = { [0] = 0xFFFF, [1] = 0xFFFF, [2] = 0 },
            Cycles = 1881
        };
        Assert.True(adapter.TryInvoke(read, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(0u, read.D[0]);
        Assert.Equal(1881, read.Cycles);

        var write = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0x1F4, [2] = 0x1F0 },
            D = { [0] = 0, [1] = 0, [2] = 0 },
            Cycles = 1883
        };
        Assert.True(adapter.TryInvoke(write, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(0u, write.D[0]);
        Assert.Equal(1883, write.Cycles);
    }

    [Fact]
    public void PixelArray8RejectsAEndpointSpanThatCannotFitTheGuestUlongContract()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint array = 0x900;

        Assert.True(memory.TryWriteByte(array, 0xA5));

        // The pure host boundary accepts int coordinates so CopperScreen and
        // provider tests can exercise the conversion without a CPU register
        // wrapper.  A full signed-int endpoint span is 2^32 pixels; narrowing
        // that value to uint would produce zero and incorrectly claim a
        // successful no-op.
        Assert.Equal(
            -1,
            core.WritePixelArray8(
                0x20,
                int.MinValue,
                0,
                int.MaxValue,
                0,
                array,
                0));
        Assert.Equal(
            -1,
            core.ReadPixelArray8(
                0x20,
                0,
                int.MinValue,
                0,
                int.MaxValue,
                array,
                0));
        Assert.Equal((byte)0xA5, ReadByte(memory, array));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 0));

        // The public register ABI carries UWORD endpoints.  Its maximum
        // 65536-by-65536 request is still structurally unrepresentable for
        // the bounded portable staging buffer and must remain a claimed
        // failure (-1), not a narrowed zero-sized success.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 0xFFFF, [3] = 0xFFFF }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ReadPixelArray8));
        Assert.Equal(uint.MaxValue, state.D[0]);

        // A span one pixel below ULONG_MAX still rounds past the largest
        // representable padded row.  Keep the row-rounding check explicit so
        // it cannot wrap to a small stride before the guest-array envelope is
        // validated.
        Assert.Equal(
            -1,
            core.WritePixelArray8(
                0x20,
                int.MinValue,
                0,
                int.MaxValue - 2,
                0,
                array,
                0));
        Assert.Equal((byte)0xA5, ReadByte(memory, array));
    }

    [Fact]
    public void PixelArray8PreflightsGuestArraysAndAllDestinationPlanes()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint array = 0x1FF0;

        // The first row is mapped, but the second padded row starts exactly
        // at the end of guest memory.  A failed write must not expose row 0.
        Assert.True(memory.TryWriteByte(array, 3));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(-1, core.WritePixelArray8(0x20, 0, 0, 0, 1, array, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 0));

        // A readable first plane is not enough: reject a malformed later
        // plane before changing the first one.
        Assert.True(memory.TryWriteLong(0x100u + (uint)GraphicsLayouts.BitMapPlanes + 4u, 0x2000));
        Assert.True(memory.TryWriteByte(0x900, 3));
        Assert.Equal(-1, core.WritePixelLine8(0x20, 0, 0, 1, 0x900, 0));
        Assert.Equal((byte)0, ReadByte(memory, 0x400));
    }

    [Fact]
    public void PixelArrayStatusAdmissionRejectsMalformedIntersectingLaterPlane()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        const uint array = 0x900;

        // Plane 1 row 0 is readable, but the second row touched by the
        // request is not. A first-sample admission probe would claim the
        // vector and only discover the malformed later row after dispatch.
        memory.FailReads(0x502, 1);
        Assert.True(backing.TryWriteByte(array, 3));
        Assert.True(backing.TryWriteByte(array + 16, 3));

        Assert.Equal(
            -1,
            core.WritePixelArray8(0x20, 0, 0, 0, 1, array, 0));
        Assert.Equal((byte)0, ReadByte(backing, 0x400));
        Assert.False(core.TryWritePixelArray8(
            0x20,
            0,
            0,
            0,
            1,
            array,
            0,
            out var writeStatus));
        Assert.Equal(-1, writeStatus);

        Assert.False(core.TryReadPixelArray8(
            0x20,
            0,
            0,
            0,
            1,
            array,
            0,
            out var readStatus));
        Assert.Equal(-1, readStatus);

        // The register gateway keeps D0/cycles untouched when the portable
        // owner declines, leaving the malformed request to the native path.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var mapped = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 1 },
            Cycles = 1971
        };
        Assert.False(adapter.TryInvoke(mapped, (int)GraphicsLvo.WritePixelArray8));
        Assert.Equal(0u, mapped.D[0]);
        Assert.Equal(1971, mapped.Cycles);
    }

    [Fact]
    public void PixelArrayWritesWithZeroWriteMaskSkipHugeSourceAndPlaneWalks()
    {
        static void ConfigureLargeMaskedRaster(GraphicsLibraryCore core, FakeMemory memory)
        {
            const uint rastPort = 0x20;
            const uint bitMap = 0x100;

            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            // A 65536-column x 65535-row bitmap is representable by the
            // guest WORD geometry, but its only plane and source array are
            // mapped for a few bytes.  Zero-mask writes must not stage or
            // probe the enormous source/destination envelope.
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                8192));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                ushort.MaxValue));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                0x1FF8));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0));
        }

        var directMemory = new FakeMemory(0x2000);
        var directCore = CreateCore(directMemory);
        ConfigureLargeMaskedRaster(directCore, directMemory);
        // A zero effective mask remains a bounded no-op and plots no pixels.
        Assert.Equal(0, directCore.WritePixelLine8(0x20, 0, 0, 32768, 0x1FF8, 0));
        Assert.Equal(
            0,
            directCore.WritePixelArray8(0x20, 0, 0, 32767, 32767, 0x1FF8, 0));
        Assert.Equal(
            0,
            directCore.WriteChunkyPixels(0x20, 0, 0, 32767, 32767, 0x1FF8, 32768));

        var gatewayMemory = new FakeMemory(0x2000);
        var gatewayCore = CreateCore(gatewayMemory);
        ConfigureLargeMaskedRaster(gatewayCore, gatewayMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(gatewayCore);

        var line = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = 0x1FF8 },
            D = { [0] = 32768, [1] = 0, [2] = 32767 },
            Cycles = 901
        };
        Assert.True(adapter.TryInvoke(line, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(0u, line.D[0]);
        Assert.Equal(901, line.Cycles);

        var array = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = 0x1FF8 },
            D = { [0] = 0, [1] = 0, [2] = 32767, [3] = 32767 },
            Cycles = 902
        };
        Assert.True(adapter.TryInvoke(array, (int)GraphicsLvo.WritePixelArray8));
        Assert.Equal(0u, array.D[0]);
        Assert.Equal(902, array.Cycles);

        var chunky = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = 0x1FF8 },
            D = { [0] = 0, [1] = 0, [2] = 32767, [3] = 32767, [4] = 32768 },
            Cycles = 903
        };
        Assert.True(adapter.TryInvoke(chunky, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0u, chunky.D[0]);
        Assert.Equal(903, chunky.Cycles);
    }

    [Fact]
    public void PixelArrayHelpersRejectAggregateWorkBeforeStagingAndPreserveOverlayOwnership()
    {
        static void ConfigureLargeRaster(GraphicsLibraryCore core, FakeMemory memory)
        {
            const uint rastPort = 0x20;
            const uint bitMap = 0x100;
            const uint plane = 0x1FF0;

            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                4096));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                32768));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                plane));
            Assert.True(memory.TryWriteByte(plane, 0));
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                1));
        }

        var backing = new FakeMemory(0x2000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        ConfigureLargeRaster(core, backing);
        var baselinePlaneReads = memory.TrackedReadCount;

        // 32768 * 32768 logical pixels fit the guest signed coordinate
        // envelope, but the padded-array probe, staging, planar snapshot,
        // and publication passes exceed the bounded portable host budget.
        // The pure path must decline before it reads the first plane byte.
        Assert.Equal(
            -1,
            core.ReadPixelArray8(0x20, 0, 0, 32767, 32767, 0x1800, 0));
        Assert.Equal(
            -1,
            core.WritePixelArray8(0x20, 0, 0, 32767, 32767, 0x1800, 0));
        Assert.Equal(
            -1,
            core.ReadPixelLine8(0x20, 0, 0, 32768, 0x1800, 0));
        Assert.Equal(
            -1,
            core.WritePixelLine8(0x20, 0, 0, 32768, 0x1800, 0));
        Assert.Equal(
            -1,
            core.WriteChunkyPixels(0x20, 0, 0, 32767, 32767, 0x1800, 32768));
        Assert.Equal(baselinePlaneReads + 2, memory.TrackedReadCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = 0x1800 },
            D = { [0] = 0, [1] = 0, [2] = 32767, [3] = 32767 },
            Cycles = 971
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WritePixelArray8));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(971, state.Cycles);
        // The status adapter performs no destination probe before the
        // aggregate admission check; it must not enter the large plane walk.
        Assert.Equal(baselinePlaneReads + 2, memory.TrackedReadCount);

        var overlayState = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = 0x1800 },
            D = { [0] = 0, [1] = 0, [2] = 32767, [3] = 32767 },
            Cycles = 973
        };
        Assert.False(adapter.TryInvoke(
            overlayState,
            (int)GraphicsLvo.WritePixelArray8,
            nativeOverlay: true));
        Assert.Equal(0u, overlayState.D[0]);
        Assert.Equal(973, overlayState.Cycles);
        Assert.Equal(baselinePlaneReads + 2, memory.TrackedReadCount);
    }

    [Fact]
    public void PixelArrayWritesWithMaskOutsideBitmapDepthSkipHugeSourceAndPlaneWalks()
    {
        static void ConfigureHighOnlyMaskedRaster(GraphicsLibraryCore core, FakeMemory memory)
        {
            const uint rastPort = 0x20;
            const uint bitMap = 0x100;

            Assert.True(core.InitializeRastPort(rastPort));
            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortBitMap,
                bitMap));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                8192));
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapRows,
                ushort.MaxValue));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                0x1FF8));
            // Plane 0 is the only declared destination.  A high-only mask
            // must therefore take the same bounded no-op path as Mask == 0.
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0x80));
        }

        var directMemory = new FakeMemory(0x2000);
        var directCore = CreateCore(directMemory);
        ConfigureHighOnlyMaskedRaster(directCore, directMemory);
        Assert.Equal(0, directCore.WritePixelLine8(0x20, 0, 0, 32768, 0x1FF8, 0));
        Assert.Equal(
            0,
            directCore.WritePixelArray8(0x20, 0, 0, 32767, 32767, 0x1FF8, 0));
        Assert.Equal(
            0,
            directCore.WriteChunkyPixels(0x20, 0, 0, 32767, 32767, 0x1FF8, 32768));

        var gatewayMemory = new FakeMemory(0x2000);
        var gatewayCore = CreateCore(gatewayMemory);
        ConfigureHighOnlyMaskedRaster(gatewayCore, gatewayMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(gatewayCore);

        var line = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = 0x1FF8 },
            D = { [0] = 32768, [1] = 0, [2] = 32767 },
            Cycles = 911
        };
        Assert.True(adapter.TryInvoke(line, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(0u, line.D[0]);
        Assert.Equal(911, line.Cycles);

        var array = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = 0x1FF8 },
            D = { [0] = 0, [1] = 0, [2] = 32767, [3] = 32767 },
            Cycles = 912
        };
        Assert.True(adapter.TryInvoke(array, (int)GraphicsLvo.WritePixelArray8));
        Assert.Equal(0u, array.D[0]);
        Assert.Equal(912, array.Cycles);

        var chunky = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = 0x1FF8 },
            D = { [0] = 0, [1] = 0, [2] = 32767, [3] = 32767, [4] = 32768 },
            Cycles = 913
        };
        Assert.True(adapter.TryInvoke(chunky, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0u, chunky.D[0]);
        Assert.Equal(913, chunky.Cycles);
    }

    [Fact]
    public void PixelArrayRegisterVectorsLeaveMalformedPlanarEndpointsUnclaimed()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        // Keep the RastPort envelope and layer link readable so the failure
        // reaches the planar decoder. An odd BytesPerRow is not a standard
        // planar endpoint; the native/provider boundary must retain it.
        Assert.True(memory.TryWriteWord(
            0x100u + (uint)GraphicsLayouts.BitMapBytesPerRow,
            1));
        Assert.True(memory.TryWriteByte(
            0x100u + (uint)GraphicsLayouts.BitMapFlags,
            0x08)); // BMF_STANDARD

        var vectors = new[]
        {
            GraphicsLvo.ReadPixelLine8,
            GraphicsLvo.WritePixelLine8,
            GraphicsLvo.ReadPixelArray8,
            GraphicsLvo.WritePixelArray8
        };

        foreach (var vector in vectors)
        {
            var state = new M68kCpuState
            {
                A = { [0] = 0x20, [1] = 0, [2] = 0x900 },
                D =
                {
                    [0] = 0xCAFE_BABEu,
                    [1] = 0,
                    [2] = 1,
                    [3] = 0
                },
                Cycles = 733
            };

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(0xCAFE_BABEu, state.D[0]);
            Assert.Equal(733, state.Cycles);
        }

        // A structurally valid header is still not a native planar endpoint
        // when a declared plane cannot be probed. Keep the result split from
        // the valid-RastPort/unmapped-array case above.
        Assert.True(memory.TryWriteWord(
            0x100u + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteLong(
            0x100u + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            0x2000));
        var missingPlane = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = 0x900 },
            // Keep the low word at the first pixel so the valid range
            // intersects the bitmap; upper-register residue is not part of
            // the UWORD coordinate ABI.
            D = { [0] = 0x1357_0000u, [1] = 0, [2] = 1 },
            Cycles = 734
        };
        Assert.False(adapter.TryInvoke(missingPlane, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(0x1357_0000u, missingPlane.D[0]);
        Assert.Equal(734, missingPlane.Cycles);
    }

    [Fact]
    public void PixelArray8RejectsAReadableLogicalByteWithTruncatedPadding()
    {
        var memory = new FakeMemory(0x10000);
        var core = CreateCore(memory);
        const uint array = 0xFFF8;

        // A one-pixel line still reserves one complete 16-byte RASSIZE row.
        // Only the logical byte is mapped here; the padded envelope crosses
        // the guest-memory end and must be rejected before plane zero changes.
        Assert.True(memory.TryWriteByte(array, 1));
        Assert.Equal(-1, core.WritePixelLine8(0x20, 0, 0, 1, array, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 0));
    }

    [Fact]
    public void WritePixelArray8RestoresEarlierPixelsWhenALaterPlaneWriteFails()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint array = 0x900;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        for (var index = 0u; index < 8; index++)
            Assert.True(backing.TryWriteByte(array + index, 0xFF));
        Assert.True(backing.TryWriteByte(plane0, 0xA5));
        Assert.True(backing.TryWriteByte(plane1, 0x5A));
        memory.FailOnNextByteWrite(4);

        Assert.Equal(-1, core.WritePixelArray8(0x20, 0, 0, 7, 0, array, 0));
        Assert.Equal((byte)0xA5, ReadByte(backing, plane0));
        Assert.Equal((byte)0x5A, ReadByte(backing, plane1));
    }

    [Fact]
    public void WritePixelArray8StagesSourceBeforeOverlappingPlanarWrites()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint array = 0x3FF;

        // The source starts one byte before plane zero.  Publishing pixel 0
        // therefore writes the byte used by source pixel 1; conversion must
        // consume the original array values before that destination write.
        Assert.True(memory.TryWriteByte(array, 1));
        Assert.True(memory.TryWriteByte(array + 1, 0));
        Assert.Equal(2, core.WritePixelArray8(0x20, 0, 0, 1, 0, array, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 0));
    }

    [Fact]
    public void ReadPixelArray8PreflightsTruncatedOutputArray()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint array = 0x1FF0;

        Assert.True(memory.TryWriteByte(array, 0xEE));
        Assert.Equal(-1, core.ReadPixelArray8(0x20, 0, 0, 0, 1, array, 0));
        Assert.Equal((byte)0xEE, ReadByte(memory, array));
    }

    [Fact]
    public void ReadPixelArray8RestoresEarlierOutputBytesWhenALaterWriteFails()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint array = 0x900;

        Assert.True(backing.TryWriteByte(0x400, 0xF0));
        for (var index = 0u; index < 8; index++)
            Assert.True(backing.TryWriteByte(array + index, 0xEE));
        memory.FailOnNextByteWrite(3);

        Assert.Equal(-1, core.ReadPixelArray8(0x20, 0, 0, 7, 0, array, 0));
        for (var index = 0u; index < 8; index++)
            Assert.Equal((byte)0xEE, ReadByte(backing, array + index));
    }

    [Fact]
    public void PixelArray8ValidatesAnExplicitTemporaryRastPortEnvelope()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint temporaryRastPort = 0x600;
        const uint temporaryBitMap = 0x680;
        const uint temporaryPlane0 = 0x800;
        const uint temporaryPlane1 = 0x900;
        const uint array = 0xA00;

        Assert.True(memory.TryWriteLong(
            temporaryRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(memory.TryWriteLong(
            temporaryRastPort + (uint)GraphicsLayouts.RastPortBitMap,
            temporaryBitMap));
        Assert.True(memory.TryWriteWord(
            temporaryBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            temporaryBitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            temporaryBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));
        Assert.True(memory.TryWriteLong(
            temporaryBitMap + (uint)GraphicsLayouts.BitMapPlanes,
            temporaryPlane0));
        Assert.True(memory.TryWriteLong(
            temporaryBitMap + (uint)GraphicsLayouts.BitMapPlanes + 4,
            temporaryPlane1));
        Assert.True(memory.TryWriteByte(array, 1));
        Assert.True(memory.TryWriteByte(array + 1, 2));

        Assert.Equal(
            2,
            core.WritePixelLine8(0x20, 0, 0, 2, array, temporaryRastPort));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 1, 0));

        // A malformed explicit workspace must be declined before the first
        // destination plane changes.  The zero temporary-RastPort form used
        // by the host-only conversion path remains supported separately.
        Assert.True(memory.TryWriteLong(
            temporaryRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x1234));
        Assert.True(memory.TryWriteByte(array, 3));
        Assert.Equal(
            -1,
            core.WritePixelLine8(0x20, 0, 0, 1, array, temporaryRastPort));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));

        // The temporary RastPort itself is a native word/longword structure.
        // A host mapping at an odd address must not let the portable helper
        // reinterpret it and claim the request before the resident/provider
        // address-error path can run.
        const uint oddTemporaryRastPort = 0x601;
        Assert.True(memory.TryWriteLong(
            oddTemporaryRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(memory.TryWriteLong(
            oddTemporaryRastPort + (uint)GraphicsLayouts.RastPortBitMap,
            temporaryBitMap));
        Assert.Equal(
            -1,
            core.WritePixelLine8(0x20, 0, 0, 1, array, oddTemporaryRastPort));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));

        // The register-facing status adapters must decline the same malformed
        // native workspace for every V36 array vector, while preserving the
        // classic -1 result for the direct portable operation.
        Assert.False(core.TryReadPixelLine8(
            0x20,
            0,
            0,
            1,
            array,
            oddTemporaryRastPort,
            out var oddReadLineStatus));
        Assert.Equal(-1, oddReadLineStatus);
        Assert.False(core.TryWritePixelLine8(
            0x20,
            0,
            0,
            1,
            array,
            oddTemporaryRastPort,
            out var oddWriteLineStatus));
        Assert.Equal(-1, oddWriteLineStatus);
        Assert.False(core.TryReadPixelArray8(
            0x20,
            0,
            0,
            0,
            0,
            array,
            oddTemporaryRastPort,
            out var oddReadArrayStatus));
        Assert.Equal(-1, oddReadArrayStatus);
        Assert.False(core.TryWritePixelArray8(
            0x20,
            0,
            0,
            0,
            0,
            array,
            oddTemporaryRastPort,
            out var oddWriteArrayStatus));
        Assert.Equal(-1, oddWriteArrayStatus);
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));

        // A host memory model can expose an odd temporary BitMap address,
        // but native 68k word fields cannot be read from it.  Decline before
        // touching the destination when that workspace envelope is malformed.
        const uint oddTemporaryBitMap = 0x681;
        Assert.True(memory.TryWriteLong(
            temporaryRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0));
        Assert.True(memory.TryWriteLong(
            temporaryRastPort + (uint)GraphicsLayouts.RastPortBitMap,
            oddTemporaryBitMap));
        Assert.True(memory.TryWriteWord(
            oddTemporaryBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            oddTemporaryBitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            oddTemporaryBitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));
        Assert.Equal(
            -1,
            core.WritePixelLine8(0x20, 0, 0, 1, array, temporaryRastPort));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
    }

    [Fact]
    public void PixelArray8AcceptsExplicitTemporaryRastPortEndingAtGuestMaximumAcrossDirectAndMappedPaths()
    {
        const uint temporaryRastPort = 0xFFFF_FFF8;
        const uint temporaryBitMap = 0x680;
        const uint temporaryPlane0 = 0x800;
        const uint temporaryPlane1 = 0x900;
        const uint array = 0xA00;

        static (WrappingMemory Memory, GraphicsLibraryCore Core) CreateWorkspace(
            uint temporaryRastPort,
            uint temporaryBitMap,
            uint temporaryPlane0,
            uint temporaryPlane1,
            uint array)
        {
            var memory = new WrappingMemory();
            var core = CreateCore(memory);
            memory.WriteLong(
                0x20 + (uint)GraphicsLayouts.RastPortLayer,
                0);
            memory.WriteByte(
                0x100 + (uint)GraphicsLayouts.BitMapFlags,
                0);
            for (var row = 0u; row < 8; row++)
            {
                memory.WriteByte(0x400 + row * 2, 0);
                memory.WriteByte(0x400 + row * 2 + 1, 0);
                memory.WriteByte(0x500 + row * 2, 0);
                memory.WriteByte(0x500 + row * 2 + 1, 0);
            }

            memory.WriteLong(
                temporaryRastPort + (uint)GraphicsLayouts.RastPortLayer,
                0);
            memory.WriteLong(
                temporaryRastPort + (uint)GraphicsLayouts.RastPortBitMap,
                temporaryBitMap);
            WritePlanarBitmap(memory, temporaryBitMap, temporaryPlane0, temporaryPlane1, rows: 1);
            memory.WriteByte(
                temporaryBitMap + (uint)GraphicsLayouts.BitMapFlags,
                0);
            memory.WriteByte(temporaryPlane0, 0);
            memory.WriteByte(temporaryPlane0 + 1, 0);
            memory.WriteByte(temporaryPlane1, 0);
            memory.WriteByte(temporaryPlane1 + 1, 0);
            for (var offset = 0u; offset < 16; offset++)
                memory.WriteByte(array + offset, 0);
            memory.WriteByte(array, 1);
            memory.WriteByte(array + 1, 2);
            return (memory, core);
        }

        var (directMemory, directCore) = CreateWorkspace(
            temporaryRastPort,
            temporaryBitMap,
            temporaryPlane0,
            temporaryPlane1,
            array);
        Assert.Equal(
            2,
            directCore.WritePixelLine8(
                0x20,
                0,
                0,
                2,
                array,
                temporaryRastPort));
        Assert.Equal(1, directCore.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, directCore.ReadPixel(0x20, 1, 0));
        Assert.True(directMemory.TryReadLong(
            temporaryRastPort + (uint)GraphicsLayouts.RastPortBitMap,
            out var directTemporaryBitMap));
        Assert.Equal(temporaryBitMap, directTemporaryBitMap);

        var (_, mappedCore) = CreateWorkspace(
            temporaryRastPort,
            temporaryBitMap,
            temporaryPlane0,
            temporaryPlane1,
            array);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = temporaryRastPort, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 2 },
            Cycles = 421
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(2u, state.D[0]);
        Assert.Equal(421, state.Cycles);
        Assert.Equal(1, mappedCore.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, mappedCore.ReadPixel(0x20, 1, 0));

        // A base whose BitMap link would cross the 32-bit guest envelope is
        // still available to a native/provider owner and must not wrap into
        // the low memory workspace.
        const uint crossingTemporaryRastPort = 0xFFFF_FFFC;
        Assert.Equal(
            -1,
            mappedCore.WritePixelLine8(
                0x20,
                0,
                0,
                2,
                array,
                crossingTemporaryRastPort));
        Assert.Equal(1, mappedCore.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, mappedCore.ReadPixel(0x20, 1, 0));

        state.A[1] = crossingTemporaryRastPort;
        state.D[0] = 0xCAFE_BABEu;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(421, state.Cycles);
        Assert.Equal(1, mappedCore.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, mappedCore.ReadPixel(0x20, 1, 0));
    }

    [Fact]
    public void WriteChunkyPixelsUsesExplicitStrideAndSignedCoordinates()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint array = 0xB00;
        Assert.True(memory.TryWriteByte(array + 0, 1));
        Assert.True(memory.TryWriteByte(array + 1, 2));
        Assert.True(memory.TryWriteByte(array + 2, 3));
        Assert.True(memory.TryWriteByte(array + 3, 0));
        Assert.True(memory.TryWriteByte(array + 6, 3));
        Assert.True(memory.TryWriteByte(array + 7, 2));
        Assert.True(memory.TryWriteByte(array + 8, 1));
        Assert.True(memory.TryWriteByte(array + 9, 0));

        Assert.Equal(8, core.WriteChunkyPixels(0x20, 2, 6, 5, 7, array, 6));
        Assert.Equal(1, core.ReadPixel(0x20, 2, 6));
        Assert.Equal(2, core.ReadPixel(0x20, 3, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 6));
        Assert.Equal(0, core.ReadPixel(0x20, 5, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 7));
        Assert.Equal(2, core.ReadPixel(0x20, 3, 7));
        Assert.Equal(1, core.ReadPixel(0x20, 4, 7));
        Assert.Equal(0, core.ReadPixel(0x20, 5, 7));
        Assert.Equal(-1, core.WriteChunkyPixels(0x20, 0, 0, 3, 0, array, 3));

        // WriteChunkyPixels declares bytesperrow as a signed LONG.  A
        // negative stride is malformed even when its bit pattern would look
        // like a large positive ULONG to the host implementation.
        Assert.Equal(
            -1,
            core.WriteChunkyPixels(
                0x20,
                0,
                0,
                0,
                0,
                array,
                int.MinValue));
    }

    [Fact]
    public void WriteChunkyPixelsRegisterPreservesSignedLongCoordinates()
    {
        var memory = new FakeMemory(0x8000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x4000;
        const uint array = 0x1000;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0x01));
        // 8192 planar bytes describe the complete 65536-pixel logical row;
        // the selected coordinates deliberately sit above the signed WORD
        // range so the mapped LONG ABI cannot be mistaken for V36 UWORD
        // pixel-array geometry.
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8192));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(memory.TryWriteByte(array, 1));
        Assert.True(memory.TryWriteByte(array + 1, 0));

        Assert.Equal(
            2,
            core.WriteChunkyPixels(
                rastPort,
                32768,
                0,
                32769,
                0,
                array,
                2));
        Assert.Equal((byte)0x80, ReadByte(memory, plane + 4096));
        Assert.Equal((byte)0x00, ReadByte(memory, plane + 4097));

        Assert.True(memory.TryWriteByte(plane + 4096, 0));
        Assert.True(memory.TryWriteByte(plane + 4097, 0));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = array },
            D =
            {
                [0] = 32768,
                [1] = 0,
                [2] = 32769,
                [3] = 0,
                [4] = 2
            },
            Cycles = 1887
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1887, state.Cycles);
        Assert.Equal((byte)0x80, ReadByte(memory, plane + 4096));
        Assert.Equal((byte)0x00, ReadByte(memory, plane + 4097));
    }

    [Fact]
    public void WriteChunkyPixelsRegisterRejectsNegativeLongStrideWithoutClaiming()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint array = 0xB00;
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 0x8000_0000u },
            Cycles = 977,
            ProgramCounter = 0x1234
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(977, state.Cycles);
        Assert.Equal(0x1234u, state.ProgramCounter);
    }

    [Fact]
    public void WriteChunkyPixelsStatusAdmissionRejectsMalformedLaterPlane()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        const uint array = 0x900;

        // The first row of plane 1 is readable, but its second row crosses
        // the guest-memory boundary.  A status-aware writer must probe the
        // complete selected plane region before claiming the void vector;
        // otherwise plane 0 could be published before the later plane is
        // known to be usable.
        Assert.True(memory.TryWriteWord(
            0x100u + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.True(memory.TryWriteLong(
            0x100u + (uint)GraphicsLayouts.BitMapPlanes + 4,
            0x3FFEu));
        for (var offset = 0u; offset < 32; offset++)
            Assert.True(memory.TryWriteByte(array + offset, 1));

        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.WriteChunkyPixels(0x20, 0, 0, 1, 1, array, 2));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = array },
            D = { [0] = 0xCAFE_BABEu, [1] = 0, [2] = 1, [3] = 1, [4] = 2 },
            Cycles = 2331,
            ProgramCounter = 0x4567
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(2331, state.Cycles);
        Assert.Equal(0x4567u, state.ProgramCounter);
        Assert.Equal((byte)0, ReadByte(memory, 0x400));
    }

    [Fact]
    public void WriteChunkyPixelsStatusAdmissionIgnoresUnconsumedPadding()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        const uint array = 0x900;

        Assert.True(memory.TryWriteWord(
            0x100u + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.True(memory.TryWriteByte(array + 0, 1));
        Assert.True(memory.TryWriteByte(array + 1, 2));
        Assert.True(memory.TryWriteByte(array + 8, 3));
        Assert.True(memory.TryWriteByte(array + 9, 0));

        // bytesPerRow is eight, but the portable V40 body consumes only the
        // two logical pixels in each row.  Keep the six padding bytes of the
        // first row unavailable to prove that status admission follows the
        // actual source access envelope rather than the V36 RASSIZE rule.
        memory.FailReads(array + 2, 6);

        Assert.Equal(4, core.WriteChunkyPixels(0x20, 0, 0, 1, 1, array, 8));

        Assert.True(core.TryWriteChunkyPixels(
            0x20,
            0,
            0,
            1,
            1,
            array,
            8,
            out var result));
        Assert.Equal(4, result);
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 1, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 1));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 1, [3] = 1, [4] = 8 },
            Cycles = 2441
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(2441, state.Cycles);
    }

    [Fact]
    public void WriteChunkyPixelsStatusAdmissionRejectsSourceBeforeDestinationProbe()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressRangeReadFaultMemory(
            backing,
            trackedStart: 0x400,
            trackedBytes: 2,
            faultStart: 0x900,
            faultBytes: 1);
        var core = CreateCore(memory);
        const uint array = 0x900;

        // The source byte is malformed while the first destination plane is
        // readable.  The direct V40 body consumes the source row before it
        // probes the destination, so status admission must leave the plane
        // untouched and must not even observe that destination range.
        Assert.True(backing.TryWriteByte(array, 1));
        Assert.False(core.TryWriteChunkyPixels(
            0x20,
            0,
            0,
            0,
            0,
            array,
            1,
            out var result));
        Assert.Equal(GraphicsRasterOperations.Failure, result);
        Assert.Equal(1, memory.FaultedReadCount);
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal((byte)0, ReadByte(backing, 0x400));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [2] = array },
            D = { [0] = 0xCAFE_BABEu, [1] = 0, [2] = 0, [3] = 0, [4] = 1 },
            Cycles = 2497,
            ProgramCounter = 0x5678
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WriteChunkyPixels));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(2497, state.Cycles);
        Assert.Equal(0x5678u, state.ProgramCounter);
    }

    [Fact]
    public void PixelArrayWriterStatusAdmissionValidatesSourceBeforeDestinationProbe()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressRangeReadFaultMemory(
            backing,
            trackedStart: 0x400,
            trackedBytes: 2,
            faultStart: 0x900,
            faultBytes: 1);
        var core = CreateCore(memory);
        const uint array = 0x900;

        // The V36 writer bodies validate the complete padded caller row
        // before WriteRows snapshots the selected planar destination.  A
        // A mapped source fault must publish the direct -1 result without
        // observing the destination plane first.
        Assert.True(backing.TryWriteByte(array, 1));
        Assert.True(core.TryWritePixelLine8(
            0x20,
            0,
            0,
            1,
            array,
            0,
            out var lineResult));
        Assert.Equal(GraphicsRasterOperations.Failure, lineResult);
        Assert.Equal(1, memory.FaultedReadCount);
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal((byte)0, ReadByte(backing, 0x400));

        // The rectangular V36 writer shares the same source-before-plane
        // body order; keep its status adapter aligned as well.
        Assert.True(core.TryWritePixelArray8(
            0x20,
            0,
            0,
            0,
            0,
            array,
            0,
            out var arrayResult));
        Assert.Equal(GraphicsRasterOperations.Failure, arrayResult);
        Assert.Equal(2, memory.FaultedReadCount);
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal((byte)0, ReadByte(backing, 0x400));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0xCAFE_BABEu, [1] = 0, [2] = 1 },
            Cycles = 2513,
            ProgramCounter = 0x6789
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(0xFFFF_FFFFu, state.D[0]);
        Assert.Equal(2513, state.Cycles);
        Assert.Equal(0x6789u, state.ProgramCounter);
    }

    [Fact]
    public void PixelArrayReadStatusAdmissionValidatesOutputBeforePlanarProbe()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new AddressRangeReadFaultMemory(
            backing,
            trackedStart: 0x400,
            trackedBytes: 2,
            faultStart: 0x900,
            faultBytes: 1);
        var core = CreateCore(memory);
        const uint array = 0x900;

        // ReadPixelLine8 and ReadPixelArray8 preflight the padded caller
        // output before ReadRows samples the planar source.  A mapped output
        // fault still owns the valid RastPort and publishes -1, but must not
        // observe the selected plane first.
        Assert.True(backing.TryWriteByte(array, 0xEE));
        Assert.True(core.TryReadPixelLine8(
            0x20,
            0,
            0,
            1,
            array,
            0,
            out var lineResult));
        Assert.Equal(GraphicsRasterOperations.Failure, lineResult);
        Assert.Equal(1, memory.FaultedReadCount);
        Assert.Equal(0, memory.TrackedReadCount);

        Assert.True(core.TryReadPixelArray8(
            0x20,
            0,
            0,
            0,
            0,
            array,
            0,
            out var arrayResult));
        Assert.Equal(GraphicsRasterOperations.Failure, arrayResult);
        Assert.Equal(2, memory.FaultedReadCount);
        Assert.Equal(0, memory.TrackedReadCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0xCAFE_BABEu, [1] = 0, [2] = 1 },
            Cycles = 2531,
            ProgramCounter = 0x789A
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ReadPixelLine8));
        Assert.Equal(0xFFFF_FFFFu, state.D[0]);
        Assert.Equal(2531, state.Cycles);
        Assert.Equal(0x789Au, state.ProgramCounter);
        Assert.Equal(3, memory.FaultedReadCount);
        Assert.Equal(0, memory.TrackedReadCount);
    }

    [Fact]
    public void PixelArrayWritesHonorTheDestinationRastPortMask()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x300;
        const uint plane0 = 0x500;
        const uint plane1 = 0x600;
        const uint array = 0x700;

        WritePlanarBitmap(memory, bitMap, plane0, plane1, rows: 1, depth: 2);
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0x01);
        memory.TryWriteByte(array, 0x03);
        memory.TryWriteByte(array + 1, 0x03);

        Assert.Equal(2, core.WritePixelLine8(rastPort, 0, 0, 2, array, 0));
        Assert.Equal((byte)0xC0, ReadByte(memory, plane0));
        Assert.Equal((byte)0x00, ReadByte(memory, plane1));
    }

    [Fact]
    public void RasterVectorsRejectAnOddLinkedBitMapHeaderBeforeWriting()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint oddBitMap = 0x301;
        const uint plane = 0x500;

        WritePlanarBitmap(memory, oddBitMap, plane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortBitMap,
            oddBitMap));
        Assert.True(memory.TryWriteByte(plane, 0x5A));

        // BitMap word fields are native 68k data.  A host byte-addressable
        // memory model must not make an odd linked header look portable.
        Assert.Equal(-1, core.WritePixel(rastPort, 0, 0));
        Assert.Equal((byte)0x5A, ReadByte(memory, plane));
    }

    [Fact]
    public void PixelArray8VectorsUseA0RasterPortAndPreserveLayerAndRtgFallbacks()
    {
        var memory = new FakeMemory(0x3000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgRastPort: address => address == 0x20);
        const uint array = 0x900;
        Assert.True(memory.TryWriteByte(array, 2));
        Assert.True(memory.TryWriteByte(array + 1, 3));

        var write = new M68kCpuState
        {
            A = { [0] = 0x20, [1] = 0, [2] = array },
            D = { [0] = 0, [1] = 0, [2] = 2 }
        };
        Assert.False(adapter.TryInvoke(write, (int)GraphicsLvo.WritePixelLine8));

        var nonRtgAdapter = new CopperStartGraphicsRegisterAdapter(core);
        Assert.True(nonRtgAdapter.TryInvoke(write, (int)GraphicsLvo.WritePixelLine8));
        Assert.Equal(2u, write.D[0]);
        Assert.Equal(2, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 0));

        Assert.True(memory.TryWriteLong(0x20u + (uint)GraphicsLayouts.RastPortLayer, 0x180));
        Assert.False(nonRtgAdapter.TryInvoke(write, (int)GraphicsLvo.WritePixelLine8));
    }

    [Fact]
    public void CombinedPenModeWriteMaskAndOutlinePenUpdateRastPortState()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.True(memory.TryWriteByte(0x20u + (uint)GraphicsLayouts.RastPortOutlinePen, 3));
        // These vectors consume ULONG arguments even though the guest
        // RastPort stores byte-sized pen/mode fields.
        Assert.Equal(0, core.SetABPenDrMd(0x20, 0xA5_000005, 0xB6_000006, 0xC7_000002));
        Assert.Equal(5, core.GetAPen(0x20));
        Assert.Equal(6, core.GetBPen(0x20));
        Assert.Equal(2, core.GetDrawMode(0x20));
        Assert.Equal(0, core.SetAPen(0x20, 0xD8_000009));
        Assert.Equal(9, core.GetAPen(0x20));
        Assert.Equal(0, core.SetBPen(0x20, 0xE9_00000A));
        Assert.Equal(10, core.GetBPen(0x20));
        Assert.Equal(0, core.SetDrawMode(0x20, 0xFA_000001));
        Assert.Equal(1, core.GetDrawMode(0x20));
        Assert.Equal(0, core.SetWriteMask(0x20, 0x01));
        Assert.Equal((byte)0x01, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortMask));

        // SetWriteMask is a ULONG vector, while rp_Mask is a byte in the
        // guest RastPort.  The portable seam must accept the full register
        // value and retain only the documented low-byte state.
        Assert.Equal(0, core.SetWriteMask(0x20, 0xA5_0003C7));
        Assert.Equal((byte)0xC7, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortMask));

        Assert.Equal(3, core.GetOutlinePen(0x20));
        // SetOutlinePen consumes a ULONG pen at the public vector boundary,
        // while AOlPen remains the classic byte-sized RastPort field.
        Assert.Equal(3, core.SetOutlinePen(0x20, 0xA5_000007));
        Assert.Equal(7, core.GetOutlinePen(0x20));
        Assert.Equal((ushort)GraphicsLayouts.RastPortAreaOutline,
            ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortFlags));

        // SetRast also consumes ULONG pen input while retaining the
        // byte-sized planar pen semantics.
        Assert.Equal(0, core.SetRast(0x20, 0xB6_000002));
        Assert.Equal(2, core.ReadPixel(0x20, 0, 0));
    }

    [Fact]
    public void SoftStyleVectorsTrackAlgorithmicStyleAndSetFontClearsIt()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();

        Assert.Equal(0, core.SetFont(0x20, 0x300, fonts));
        Assert.Equal(-1, core.AskSoftStyle(0x20, fonts));
        Assert.Equal(4, core.SetSoftStyle(0x20, 4, 0xFF, fonts));
        Assert.Equal((byte)4, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal(0, core.SetSoftStyle(0x20, 0, 4, fonts));
        Assert.Equal((byte)0, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));

        Assert.Equal(4, core.SetSoftStyle(0x20, 4, 0xFF, fonts));
        Assert.Equal(0, core.SetFont(0x20, 0x300, fonts));
        Assert.Equal((byte)0, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));
    }

    [Fact]
    public void SoftStylePreservesIntrinsicBitsAndPublishesTheCompleteAlgoStyleByte()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(3, 3, 3, 0, style: 0x02),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL)
            });

        Assert.Equal(0, core.SetFont(0x20, 0x300, fonts));
        Assert.Equal(-3, core.AskSoftStyle(0x20, fonts));

        // Bit 1 is intrinsic bold and cannot be changed; bit 3 is outside
        // Text's three rendering transforms but is still part of the classic
        // byte-sized AlgoStyle contract.
        Assert.Equal(0x0A, core.SetSoftStyle(0x20, 0x08, 0x0A, fonts));
        Assert.Equal((byte)0x08, ReadByte(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));

        Assert.Equal(0x02, core.SetSoftStyle(0x20, 0, 0x0A, fonts));
        Assert.Equal((byte)0, ReadByte(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));
    }

    [Fact]
    public void SetFontRestoresTheOldFontCacheWhenALateWordWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;

        Assert.True(backing.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0x200));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle, 7));
        Assert.True(backing.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 9));
        Assert.True(backing.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth, 10));
        Assert.True(backing.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 11));
        Assert.True(backing.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 12));

        // Font pointer, height, width, then fail the baseline word.  The
        // complete cache transaction must restore the previous font metrics
        // while leaving AlgoStyle and TxSpacing untouched.
        memory.FailOnNextByteWrite(10);
        Assert.Equal(-1, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0x200u, ReadLong(backing, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((byte)7, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)9, ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)10, ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)11, ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal((ushort)12, ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextSpacing));
    }

    [Fact]
    public void SetFontRestoresTheOldFontPointerAfterRejectedPartialLongPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectLongWriteMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        var fontField = rastPort + (uint)GraphicsLayouts.RastPortFont;

        Assert.True(backing.TryWriteLong(fontField, 0x200));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            7));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            9));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth,
            10));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
            11));

        // The first font-pointer LONG publishes three bytes and then
        // declines. Byte-wise rollback must restore the old pointer even
        // though a repeated LONG publication is rejected by the adapter.
        memory.PartialLongAddress = fontField;
        Assert.Equal(-1, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0x200u, ReadLong(backing, fontField));
        Assert.Equal((byte)7, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)9, ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)10, ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)11, ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));

        memory.PartialLongAddress = null;
        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0x300u, ReadLong(backing, fontField));
    }

    [Fact]
    public void SetFontPreservesCallerOwnedTextSpacing()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(9, 7, 6, 3),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(7, 9, 7, 0)
            });
        const uint rastPort = 0x20;

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            unchecked((ushort)-2)));

        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(
            unchecked((ushort)-2),
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextSpacing));
        Assert.Equal(
            (ushort)9,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(
            (ushort)7,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal(
            (ushort)6,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void SetFontDoesNotReadUnrelatedTextStateAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;

        var directBacking = new FakeMemory(0x2000);
        Assert.True(directBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            0x200));
        Assert.True(directBacking.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            7));
        Assert.True(directBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            9));
        Assert.True(directBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth,
            10));
        Assert.True(directBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
            11));
        Assert.True(directBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            12));

        var directMemory = new RangeReadFaultMemory(directBacking);
        directMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortTextFlags,
            sizeof(byte));
        directMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            sizeof(ushort));
        var directCore = CreateCore(directMemory);

        Assert.Equal(0, directCore.SetFont(rastPort, font, new FakeFontBackend()));
        Assert.Equal(
            font,
            ReadLong(directBacking, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal(
            (byte)0,
            ReadByte(directBacking, rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal(
            (ushort)3,
            ReadWord(directBacking, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(
            (ushort)3,
            ReadWord(directBacking, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal(
            (ushort)3,
            ReadWord(directBacking, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal(
            (ushort)12,
            ReadWord(directBacking, rastPort + (uint)GraphicsLayouts.RastPortTextSpacing));

        var mappedBacking = new FakeMemory(0x2000);
        WriteFontHeader(mappedBacking, font, 0, ySize: 4, style: 0, flags: 0);
        Assert.True(mappedBacking.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            0x200));
        Assert.True(mappedBacking.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            6));
        Assert.True(mappedBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            9));
        Assert.True(mappedBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth,
            10));
        Assert.True(mappedBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
            11));
        Assert.True(mappedBacking.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            13));

        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortTextFlags,
            sizeof(byte));
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            sizeof(ushort));
        var mappedCore = CreateCore(mappedMemory);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = font, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 59
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(59, state.Cycles);
        Assert.Equal(
            font,
            ReadLong(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal(
            (byte)0,
            ReadByte(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal(
            (ushort)4,
            ReadWord(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(
            (ushort)8,
            ReadWord(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal(
            (ushort)7,
            ReadWord(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
        Assert.Equal(
            (ushort)13,
            ReadWord(mappedBacking, rastPort + (uint)GraphicsLayouts.RastPortTextSpacing));
    }

