    [Fact]
    public void TextRestoresLineStateWhenItsFinalMovePublicationFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        const ushort oldFlags = 0x0200;
        var fonts = new FakeFontBackend();

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            4));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));

        // The final Move-equivalent writes CurrentX as a word, then the
        // fresh-line phase.  Reject that phase byte and require all state to
        // return to its pre-Text values.
        memory.FailOnNextByteWrite(3);
        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(
            (short)0,
            ReadSignedWord(backing, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            (byte)4,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            oldFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void TextRestoresCursorAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        const ushort oldFlags = 0x0200;
        const short oldCursorX = 8;
        const byte oldPatternCount = 4;
        var fonts = new FakeFontBackend();
        var cursorAddress = rastPort + (uint)GraphicsLayouts.RastPortCurrentX;

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.Equal(0, core.Move(rastPort, oldCursorX, 5));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            oldPatternCount));
        Assert.True(backing.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            oldFlags));

        // Text's final cursor advance is four pixels for the fake 'A'. The
        // bridge accepts only the high byte of that WORD and rejects the
        // operation; the failure journal must restore the old cursor and
        // leave the call retryable.
        memory.PartialWordAddress = cursorAddress;

        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(oldCursorX, ReadSignedWord(backing, cursorAddress));
        Assert.Equal(
            oldPatternCount,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            oldFlags,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
        Assert.Equal((short)(oldCursorX + 4), ReadSignedWord(backing, cursorAddress));
        Assert.Equal(
            (byte)15,
            ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(
            (ushort)(oldFlags | GraphicsLayouts.RastPortFirstDot),
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortFlags));
    }

    [Fact]
    public void VariableTextSpacingTracksLeftMovementInExtentFitAndJam2Text()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(
                4,
                4,
                2,
                0,
                flags: 0x20,
                hasCharSpace: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                // The glyph advances four pixels, then TxSpacing moves the
                // consumed cell two pixels to the left.
                [(byte)'A'] = new GraphicsGlyph(1, 1, 4, 0x8000000000000000UL)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.True(memory.TryWriteWord(
            0x20u + (uint)GraphicsLayouts.RastPortTextSpacing,
            unchecked((ushort)-6)));

        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((short)-2, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-2, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        // The alternate TextFit width is the rendered envelope.  A width of
        // three cannot contain the six-pixel [-2,3] envelope even though the
        // signed cursor advance is -2; the exact envelope width admits it.
        Assert.Equal(0, core.TextFit(0x20, text, 1, extent, 0, 1, 3, 4, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal(1, core.TextFit(0x20, text, 1, extent, 0, 1, 6, 4, fonts));
        Assert.Equal((short)-2, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-2, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        Assert.Equal(0, core.SetAPen(0x20, 1));
        Assert.Equal(0, core.SetBPen(0x20, 2));
        Assert.Equal(0, core.SetDrawMode(0x20, 1));
        Assert.Equal(0, core.Move(0x20, 4, 2));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal(2, core.ReadPixel(0x20, 2, 0));
        Assert.Equal(1, core.ReadPixel(0x20, 4, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 7, 0));

        // Underline uses the same complete movement envelope, including the
        // negative spacing cell to the left of the glyph.
        Assert.Equal(1, core.SetSoftStyle(0x20, 1, 1, fonts));
        Assert.Equal(0, core.Move(0x20, 4, 2));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal(1, core.ReadPixel(0x20, 2, 3));
        Assert.Equal(1, core.ReadPixel(0x20, 7, 3));
    }

