    [Fact]
    public void TextComplementJam2ComplementsTemplateWithoutReadingStrikeAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;

        static void Seed(FakeMemory memory, uint rastPort, uint font, uint text)
        {
            Assert.True(memory.TryWriteByte(text, (byte)'A'));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontYSize,
                2));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontXSize,
                4));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontBaseline,
                1));
            Assert.True(memory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontFlags,
                0));
            Assert.True(memory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontLoChar,
                (byte)'A'));
            Assert.True(memory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontHiChar,
                (byte)'A'));
            // The first strike row is addressable; the second row lies just
            // beyond guest memory.  JAM2|COMPLEMENT must use metric geometry
            // and complement the complete template without touching it.
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharData,
                0x1FFF));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontModulo,
                1));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharLoc,
                0));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharSpace,
                0));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharKern,
                0));
            Assert.True(memory.TryWriteByte(0x1FFF, 0xFF));

            Assert.True(memory.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortFont,
                font));
            // Seed both selected destination planes so the regression proves
            // this is a toggle rather than a foreground repaint.
            Assert.True(memory.TryWriteByte(0x400, 0xFF));
            Assert.True(memory.TryWriteByte(0x402, 0xFF));
            Assert.True(memory.TryWriteByte(0x404, 0xFF));
            Assert.True(memory.TryWriteByte(0x406, 0xFF));
            Assert.True(memory.TryWriteByte(0x500, 0xFF));
            Assert.True(memory.TryWriteByte(0x502, 0xFF));
            Assert.True(memory.TryWriteByte(0x504, 0xFF));
            Assert.True(memory.TryWriteByte(0x506, 0xFF));
        }

        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            Seed(memory, rastPort, font, text);
            var fonts = new GraphicsMemoryFontBackend(memory);

            Assert.Equal(0, core.SetFont(rastPort, font, fonts));
            Assert.Equal(0, core.SetDrawMode(rastPort, 3));
            Assert.Equal(0, core.Move(rastPort, 0, 3));
            Assert.Equal(3, core.ReadPixel(rastPort, 0, 2));
            Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
            Assert.Equal(0, core.ReadPixel(rastPort, 0, 2));
            Assert.Equal(0, core.ReadPixel(rastPort, 3, 3));
            Assert.Equal(3, core.ReadPixel(rastPort, 0, 1));
        }

        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            Seed(memory, rastPort, font, text);
            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            var setFont = new M68kCpuState
            {
                A = { [0] = font, [1] = rastPort }
            };
            Assert.True(adapter.TryInvoke(setFont, (int)GraphicsLvo.SetFont));
            Assert.Equal(0, core.SetDrawMode(rastPort, 3));
            Assert.Equal(0, core.Move(rastPort, 0, 3));

            var state = new M68kCpuState
            {
                A = { [0] = text, [1] = rastPort },
                D = { [0] = 1 }
            };
            Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(0, core.ReadPixel(rastPort, 0, 2));
            Assert.Equal(0, core.ReadPixel(rastPort, 3, 3));
            Assert.Equal(3, core.ReadPixel(rastPort, 0, 1));
        }
    }

