            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(0, 0, 0, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.SetDrawMode(0x20, 1)); // JAM2
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal((short)0, ReadSignedWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void TextMetricExtentsIncludeAlgorithmicBoldAndItalicEnvelope()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        const uint constraint = 0x380;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(6, 2, 4, 0, boldSmear: 2),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(2, 1, 2, 0xC000000000000000UL)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        Assert.Equal(2, core.SetSoftStyle(0x20, 2, 2, fonts));
        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((short)3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        Assert.Equal(4, core.SetSoftStyle(0x20, 4, 7, fonts));
        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((short)-1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentWidth, 8);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentHeight, 6);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinX, 0);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinY, unchecked((ushort)-4));
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxX, 1);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxY, 1);
        Assert.Equal(0, core.TextFit(0x20, text, 1, extent, constraint, 1, 8, 6, fonts));
    }

    [Fact]
    public void TextFitRejectsAnExplicitConstraintThatExcludesTheCurrentOrigin()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        const uint constraint = 0x380;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(3, 4, 2, 0, hasCharKern: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                // Kerning moves the strike to x=2; although its one-pixel
                // envelope is contained by [2,3], Kickstart requires an
                // explicit TextExtent constraint to include x=0.
                [(byte)'A'] = new GraphicsGlyph(1, 1, 2, 2, 0, 0, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentWidth, 4);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentHeight, 3);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinX, 2);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinY, unchecked((ushort)-2));
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxX, 3);
        memory.TryWriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxY, 0);

        Assert.Equal(0, core.TextFit(0x20, text, 1, extent, constraint, 1, 99, 99, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));
    }

    [Fact]
    public void TextFitShortCircuitsAnExplicitVerticalNoFitBeforeDecodingGlyphs()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        const uint constraint = 0x380;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 2, 3, 0),
            new Dictionary<byte, GraphicsGlyph>());

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        // The box is one row too short vertically.  The only text byte has
        // no decoded glyph on purpose: native TextFit returns an empty fit
        // before it asks the font backend for any character when this
        // explicit vertical envelope is impossible.
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentWidth,
            99));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentHeight,
            2));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMinX,
            0));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMinY,
            unchecked((ushort)-2)));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMaxX,
            99));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMaxY,
            0));

        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.True(memory.TryWriteByte(extent + (uint)offset, 0x5A));

        Assert.Equal(
            0,
            core.TextFit(0x20, text, 1, extent, constraint, 1, 99, 99, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal((byte)0, ReadByte(memory, extent + (uint)offset));
    }

    [Fact]
    public void TextMetricsRetainThePenOriginBeforePositiveFirstCharacterKerning()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        const uint constraint = 0x380;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(3, 4, 2, 0, hasCharKern: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                // The strike starts two pixels to the right of the pen, but
                // the movement envelope still begins at the pen origin.
                [(byte)'A'] = new GraphicsGlyph(1, 1, 2, 2, 0, 0, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((ushort)4, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentWidth,
            4));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentHeight,
            3));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMinX,
            0));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMinY,
            unchecked((ushort)-2)));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMaxX,
            3));
        Assert.True(memory.TryWriteWord(
            constraint + (uint)GraphicsLayouts.TextExtentMaxY,
            0));

        Assert.Equal(
            1,
            core.TextFit(0x20, text, 1, extent, constraint, 1, 99, 99, fonts));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));
    }

    [Fact]
    public void TextFitPublishesOnlyTheAcceptedPrefixExtentAfterARejectedGlyph()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(3, 2, 2, 0, flags: 0x20),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(2, 1, 2, 0, 0, 0, 0),
                // This second proportional strike exceeds the alternate
                // width box.  Its bounds must not leak into the one-character
                // extent returned for the accepted prefix.
                [(byte)'B'] = new GraphicsGlyph(12, 1, 2, 0, 0, 0, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteByte(text + 1, (byte)'B'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        Assert.Equal(1, core.TextFit(0x20, text, 2, extent, 0, 1, 4, 3, fonts));
        Assert.Equal((ushort)2, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)3, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)-2, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinY));
        Assert.Equal((short)1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxY));
    }

