    [Fact]
    public void EmptyProportionalTextExtentKeepsTheMovementCellAndStyleEnvelope()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(
                6,
                2,
                4,
                0,
                boldSmear: 2,
                flags: 0x20), // FPF_PROPORTIONAL
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(2, 1, 2, 0xC000000000000000UL)
            });

