        Assert.Equal(7, core.SetSoftStyle(0x20, 7, 7, fonts));
        Assert.Equal(0, core.TextExtent(0x20, 0, 0, extent, fonts));

        // Proportional TextExtent starts with the zero-width movement cell
        // (MaxX=0) and then applies bold (+2) and italic (+Baseline/2), while
