        Assert.Equal((short)1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxY));
    }

    [Fact]
    public void ItalicTextShearsFromTheFontBaselineWhenGlyphHeightDiffers()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        ulong rows = 0;
        for (var row = 0; row < 5; row++)
            rows |= 1UL << (63 - (row * 8));

        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(5, 1, 2, 0),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(1, 5, 1, rows)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(4, core.SetSoftStyle(0x20, 4, 4, fonts));
        Assert.Equal(0, core.Move(0x20, 5, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        // Baseline two produces shifts +1, 0, 0, -1, -1.  Using the glyph
        // height here would incorrectly keep the top rows too far right.
        Assert.Equal(3, core.ReadPixel(0x20, 6, 3));
        Assert.Equal(3, core.ReadPixel(0x20, 5, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 5, 5));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 7));
    }

