    [Fact]
    public void Jam1TextDoesNotRequireBackgroundPenStorageAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;

        var backing = new FakeMemory(0x2000);
        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();

        // The direct core path uses the fake backend, whereas the register
        // adapter decodes the guest TextFont from memory. Supply the same
        // minimal fixed-cell strike for the mapped half of this test.
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            3));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontXSize,
            3));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBaseline,
            3));
        Assert.True(backing.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontLoChar,
            (byte)'A'));
        Assert.True(backing.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontHiChar,
            (byte)'A'));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0xA00));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            1));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharLoc,
            0));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharSpace,
            0));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharKern,
            0));
        Assert.True(backing.TryWriteByte(0xA00, 0xE0));
        Assert.True(backing.TryWriteByte(0xA01, 0xA0));
        Assert.True(backing.TryWriteByte(0xA02, 0xE0));

        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.Equal(0, core.Move(rastPort, 0, 5));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0)); // JAM1
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            sizeof(byte));

        // JAM1 only paints source-one glyph cells with FgPen.  The native
        // template path does not consume the unrelated BPen byte.
        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 2));

        for (var offset = 0u; offset < 16; offset++)
        {
            Assert.True(backing.TryWriteByte(0x400u + offset, 0));
            Assert.True(backing.TryWriteByte(0x500u + offset, 0));
        }

        Assert.Equal(0, core.Move(rastPort, 0, 5));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 41
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(41, state.Cycles);
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 2));
    }

    [Fact]
    public void Jam1TextWithAnAllZeroGlyphDoesNotRequireForegroundPenAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;

        var zeroGlyph = new GraphicsGlyph(3, 3, 4, 0);
        var directFonts = new TableFontBackend(
            new GraphicsFontMetrics(
                3,
                3,
                3,
                0,
                loChar: (byte)'A',
                hiChar: (byte)'A'),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = zeroGlyph
            });

        var backing = new FakeMemory(0x2000);
        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        Assert.Equal(0, core.SetFont(rastPort, font, directFonts));
        Assert.Equal(0, core.Move(rastPort, 0, 5));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0)); // JAM1
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        // A zero-source JAM1 template has no foreground destination cells;
        // it still advances the cursor, but must not claim FgPen.
        Assert.Equal(0, core.Text(rastPort, text, 1, directFonts));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal(0, core.ReadPixel(rastPort, 0, 2));
        Assert.Equal(4, unchecked((short)ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));

        // The mapped adapter decodes the same all-zero guest strike.  Keep
        // its FgPen fault active to prove the register boundary shares the
        // field-level admission rule and still clears D0 on success.
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            3));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontXSize,
            3));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBaseline,
            3));
        Assert.True(backing.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontLoChar,
            (byte)'A'));
        Assert.True(backing.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontHiChar,
            (byte)'A'));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0xA00));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            1));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharLoc,
            0));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharSpace,
            0));
        Assert.True(backing.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharKern,
            0));
        Assert.True(backing.TryWriteByte(0xA00, 0));
        Assert.True(backing.TryWriteByte(0xA01, 0));
        Assert.True(backing.TryWriteByte(0xA02, 0));

        Assert.Equal(0, core.Move(rastPort, 0, 5));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [1] = 0xCAFE_BABEu },
            Cycles = 73
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0xCAFE_BABEu, state.D[1]);
        Assert.Equal(73, state.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal(0, core.ReadPixel(rastPort, 0, 2));
    }

    [Fact]
    public void TextComplementJam2DoesNotRequireBackgroundPenStorageAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;

        static void Prepare(
            GraphicsLibraryCore core,
            FakeMemory memory,
            uint rastPort,
            uint font,
            uint text,
            IGraphicsFontBackend fonts)
        {
            Assert.True(memory.TryWriteByte(text, (byte)'A'));
            // The direct core path uses the injected fake backend, while the
            // register adapter reconstructs its guest-memory backend. Keep
            // both paths on the same valid fixed-cell TextFont envelope.
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontYSize,
                3));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontXSize,
                3));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontBaseline,
                3));
            Assert.True(memory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontLoChar,
                (byte)'A'));
            Assert.True(memory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontHiChar,
                (byte)'A'));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharData,
                0xA00));
            Assert.True(memory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontModulo,
                1));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharLoc,
                0));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharSpace,
                0));
            Assert.True(memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharKern,
                0));
            Assert.True(memory.TryWriteByte(0xA00, 0xE0));
            Assert.True(memory.TryWriteByte(0xA01, 0xA0));
            Assert.True(memory.TryWriteByte(0xA02, 0xE0));
            Assert.Equal(0, core.SetFont(rastPort, font, fonts));
            Assert.Equal(0, core.Move(rastPort, 0, 5));
            Assert.Equal(0, core.SetDrawMode(rastPort, 3)); // JAM2 | COMPLEMENT
        }

        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        Prepare(core, backing, rastPort, font, text, fonts);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            sizeof(byte));
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(3, core.ReadPixel(rastPort, 0, 2));
        Assert.Equal(3, core.ReadPixel(rastPort, 2, 2));

        var mappedBacking = new FakeMemory(0x2000);
        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        var mappedCore = CreateCore(mappedMemory);
        var mappedFonts = new FakeFontBackend();
        Prepare(mappedCore, mappedBacking, rastPort, font, text, mappedFonts);
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortBgPen,
            sizeof(byte));
        mappedMemory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            sizeof(byte));

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 47
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(47, state.Cycles);
        Assert.Equal(3, mappedCore.ReadPixel(rastPort, 0, 2));
        Assert.Equal(3, mappedCore.ReadPixel(rastPort, 2, 2));
    }

    [Fact]
    public void TextDeclinesPrivateNoPensBeforePublicPenReadsAcrossDirectAndMappedPaths()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        static void Seed(
            FakeMemory backing,
            RangeReadFaultMemory memory,
            uint rastPort,
            uint font,
            uint text,
            uint plane0,
            uint plane1)
        {
            Assert.True(backing.TryWriteLong(
                rastPort + (uint)GraphicsLayouts.RastPortFont,
                font));
            Assert.True(backing.TryWriteByte(text, (byte)'A'));
            Assert.True(backing.TryWriteWord(
                rastPort + (uint)GraphicsLayouts.RastPortFlags,
                (ushort)GraphicsLayouts.RastPortNoPens));
            Assert.True(backing.TryWriteByte(plane0, 0x5A));
            Assert.True(backing.TryWriteByte(plane1, 0xA5));

            // Text's provider/private-colour decline must happen before the
            // public DrawMode/FgPen/BgPen bytes are probed.
            memory.FailReads(
                rastPort + (uint)GraphicsLayouts.RastPortFgPen,
                sizeof(byte) * 4u);
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, memory, rastPort, font, text, plane0, plane1);

            Assert.Equal(-1, core.Text(
                rastPort,
                text,
                1,
                new FakeFontBackend()));
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x5A, ReadByte(backing, plane0));
            Assert.Equal((byte)0xA5, ReadByte(backing, plane1));
        }

        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = CreateCore(memory);
            Seed(backing, memory, rastPort, font, text, plane0, plane1);

            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            var state = new M68kCpuState
            {
                A = { [0] = text, [1] = rastPort },
                D = { [0] = 0x1234_5678u },
                Cycles = 73
            };

            Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
            Assert.Equal(0x1234_5678u, state.D[0]);
            Assert.Equal(73, state.Cycles);
            Assert.Equal(0, memory.FaultedReadCount);
            Assert.Equal((byte)0x5A, ReadByte(backing, plane0));
            Assert.Equal((byte)0xA5, ReadByte(backing, plane1));
        }
    }

    [Fact]
    public void TextLeavesColorFontsToTheirNativeProviderBeforePlanarWrites()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(
                3,
                3,
                3,
                0,
                style: 0x40,
                loChar: (byte)'A',
                hiChar: (byte)'A'),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL)
            });

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, 0, 3));

        // FSF_COLORFONT selects ColorTextFont's multi-plane strike ABI. The
        // standard planar path must decline before glyph/destination work so
        // a resident or provider-owned color renderer can claim the vector.
        Assert.Equal(-1, core.Text(0x20, text, 1, fonts));
        Assert.Equal((short)0, ReadSignedWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 2));
    }

    [Fact]
    public void TextLeavesAntialiasColorFontsToTheProviderBeforePublicDrawState()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFlags,
            0));

        // If the portable path tried to reinterpret the antialias strike as
        // a planar color font, these public draw-state/pen reads would be
        // observable.  The provider decision must happen first.
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            4);

        var fonts = new AntialiasColorFontBackend();
        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(0, memory.FaultedReadCount);
        Assert.Equal((short)0, ReadSignedWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 91
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(91, state.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
    }

    [Fact]
    public void MemoryColorTextFontComposesPickedPlanesIntoThePlanarRastPort()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint charLoc = 0x700;
        const uint plane0 = 0x900;
        const uint plane1 = 0xA00;

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteLong(
            0x20u + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            2));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontStyle,
            0x40));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontFlags,
            0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontXSize,
            8));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBaseline,
            2));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontLoChar,
            (byte)'A'));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontHiChar,
            (byte)'A'));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            plane0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            2));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharLoc,
            charLoc));

        // Character A and the default glyph both occupy a two-pixel strike.
        Assert.True(memory.TryWriteWord(charLoc, 0));
        Assert.True(memory.TryWriteWord(charLoc + 2, 2));
        Assert.True(memory.TryWriteWord(charLoc + 4, 0));
        Assert.True(memory.TryWriteWord(charLoc + 6, 2));

        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.ColorTextFontFlags,
            1)); // CT_COLORFONT
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontDepth,
            2));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontForegroundColor,
            0xFF));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontLowColor,
            0));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontHighColor,
            3));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontPlanePick,
            0x03));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontPlaneOnOff,
            0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.ColorTextFontCharacterData,
            plane0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.ColorTextFontCharacterData + 4u,
            plane1));

        // Row 0 is color 1 then color 2; row 1 is color 3 in both columns.
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane0 + 2u, 0xC0));
        Assert.True(memory.TryWriteByte(plane1, 0x40));
        Assert.True(memory.TryWriteByte(plane1 + 2u, 0xC0));

        var fonts = new GraphicsMemoryFontBackend(memory);
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, 0, 2));
        Assert.Equal(0, core.SetDrawMode(0x20, 0)); // JAM1
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        Assert.Equal(1, core.ReadPixel(0x20, 3, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 4, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 1));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 1));
        Assert.Equal((short)8, ReadSignedWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX));

        // A grey ColorTextFont does not set CTF_MAPCOLOR.  Even when its
        // ctf_FgColor names a source value, the planar color must stay at the
        // declared source index rather than being replaced by the RastPort
        // APen.  This is the pure/core path.
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.ColorTextFontFlags,
            2)); // CT_GREYFONT, CTF_MAPCOLOR clear
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontForegroundColor,
            1));
        for (var offset = 0u; offset < 16; offset++)
        {
            Assert.True(memory.TryWriteByte(0x400u + offset, 0));
            Assert.True(memory.TryWriteByte(0x500u + offset, 0));
        }

        Assert.Equal(0, core.Move(0x20, 0, 2));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal(1, core.ReadPixel(0x20, 3, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 4, 0));

        // Restore a mapped color font for the register-boundary checks.
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.ColorTextFontFlags,
            1)); // CT_COLORFONT / CTF_MAPCOLOR
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontForegroundColor,
            byte.MaxValue));

        // The register adapter constructs the same guest-memory font backend
        // used by CopperStart's mapped path.  Clear the destination and prove
        // the 68k SetFont/Text vectors preserve the color composition.
        for (var offset = 0u; offset < 16; offset++)
        {
            Assert.True(memory.TryWriteByte(0x400u + offset, 0));
            Assert.True(memory.TryWriteByte(0x500u + offset, 0));
        }

        Assert.Equal(0, core.Move(0x20, 0, 2));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = font, [1] = 0x20 },
            D = { [0] = 1 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));
        Assert.Equal(0u, state.D[0]);

        state.A[0] = text;
        state.A[1] = 0x20;
        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1, core.ReadPixel(0x20, 3, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 4, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 1));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 1));

        // CTF_MAPCOLOR also requires ctf_FgColor to lie inside the declared
        // ctf_Low..ctf_High range.  An out-of-range value remains the source
        // color on the mapped/register path.
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontForegroundColor,
            4));
        for (var offset = 0u; offset < 16; offset++)
        {
            Assert.True(memory.TryWriteByte(0x400u + offset, 0));
            Assert.True(memory.TryWriteByte(0x500u + offset, 0));
        }

        Assert.Equal(0, core.Move(0x20, 0, 2));
        state.A[0] = text;
        state.A[1] = 0x20;
        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(1, core.ReadPixel(0x20, 3, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 4, 0));

        // The designated source color is remapped to the current APen.  The
        // same guest metadata is consumed by both the pure and register paths.
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.ColorTextFontForegroundColor,
            1));
        for (var offset = 0u; offset < 16; offset++)
        {
            Assert.True(memory.TryWriteByte(0x400u + offset, 0));
            Assert.True(memory.TryWriteByte(0x500u + offset, 0));
        }

        Assert.Equal(0, core.Move(0x20, 0, 2));
        state.A[0] = text;
        state.A[1] = 0x20;
        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 4, 0));
    }

    [Fact]
    public void TextTruncatesTheCursorAtThePlanarRastPortBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint font = 0x300;
        const uint text = 0x320;
        memory.TryWriteByte(text, (byte)'A');

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, 14, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        // The test bitmap is 16 pixels wide.  The glyph advances from x=14
        // to x=18, but the public RastPort current position is clipped to
        // the drawing boundary instead of wrapping a signed word.
        Assert.Equal((short)16, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(3, core.ReadPixel(0x20, 14, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 15, 2));
    }

    [Fact]
    public void TextTruncatesTheCursorAtTheLeftPlanarRastPortBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint font = 0x300;
        const uint text = 0x320;
        memory.TryWriteByte(text, (byte)'A');

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, -5, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        // The four-pixel movement cell finishes at x=-1.  Text clips the
        // public current position to the left edge instead of publishing a
        // negative coordinate after the run crossed the RastPort boundary.
        Assert.Equal((short)0, ReadSignedWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void TextFailsClosedWhenAnInRangePlaneCannotBeWritten()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint font = 0x300;
        const uint text = 0x320;
        memory.TryWriteByte(text, (byte)'A');
        memory.TryWriteLong(0x100u + (uint)GraphicsLayouts.BitMapPlanes, 0x2000);

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(-1, core.Text(0x20, text, 1, fonts));
    }

    [Fact]
    public void TextWithZeroWriteMaskSkipsAFullGlyphCellWalk()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(
                ushort.MaxValue,
                ushort.MaxValue,
                0,
                1),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(
                    ushort.MaxValue,
                    ushort.MaxValue,
                    1,
                    0,
                    0,
                    0,
                    0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.Equal(0, core.SetWriteMask(rastPort, 0));

        // The glyph cell is large enough to make the old per-pixel
        // destination planning impractical.  With no selected planes Text
        // still consumes the character and publishes the clipped cursor,
        // but must not inspect every glyph cell or destination byte.
        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(
            (short)1,
            ReadSignedWord(
                memory,
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal(
            (byte)15,
            ReadByte(
                memory,
                rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));

        // Bits above the one declared bitmap plane are also an effective
        // zero mask. The same maximal glyph must remain a bounded cursor-only
        // operation rather than entering its cell walk.
        Assert.Equal(0, core.SetWriteMask(rastPort, 0x80));
        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
    }

    [Fact]
    public void ZeroEffectiveMaskTextUsesMetricGlyphsWithoutReadingTheStrike()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint rastPort = 0x20;
        const uint font = 0x600;
        const uint text = 0x320;

        // The TextFont header and fixed-cell movement contract are readable,
        // but tf_CharData deliberately points outside the guest image.  A
        // zero effective write mask has no bitmap publication to perform, so
        // Text should use the metric glyph envelope for cursor movement and
        // leave the strike read to the native/provider owner.
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            3));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontXSize,
            4));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBaseline,
            2));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontLoChar,
            (byte)'A'));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontHiChar,
            (byte)'A'));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0x9000));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            1));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetWriteMask(rastPort, 0));

        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(
            (short)4,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));

        // The register gateway has the same zero-mask metric-only admission;
        // restore the cursor so the mapped call exercises the same boundary.
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            0));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [1] = 0xA5A5_5A5Au },
            Cycles = 83
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(83, state.Cycles);
        Assert.Equal(
            (short)4,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));

        // A nonzero public mask can still have no destination plane when its
        // bits lie above the bitmap depth.  The direct and mapped paths must
        // retain the same metric-only strike boundary in that form.
        Assert.Equal(0, core.SetWriteMask(rastPort, 0x80));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            0));
        Assert.Equal(0, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(
            (short)4,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));

        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX,
            0));
        var highMaskState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [1] = 0x5A5A_A5A5u },
            Cycles = 97
        };

        Assert.True(adapter.TryInvoke(highMaskState, (int)GraphicsLvo.Text));
        Assert.Equal(0u, highMaskState.D[0]);
        Assert.Equal(97, highMaskState.Cycles);
        Assert.Equal(
            (short)4,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void TextRejectsAnOversizedZeroMaskCharacterStreamBeforeGlyphDecode()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        const uint oversizedCount = 0x8000_0000u;
        var fonts = new CountingFontBackend();

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.Equal(0, core.SetWriteMask(rastPort, 0));

        // With no selected planes the call would otherwise enter the
        // cursor-only character loop.  Decline the ULONG stream before even
        // asking the font backend for its first glyph.
        Assert.Equal(-1, core.Text(rastPort, text, oversizedCount, fonts));
        Assert.Equal(0, fonts.GlyphRequests);
        Assert.Equal(
            (short)0,
            ReadSignedWord(memory, rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void TextRejectsAnUnstageableGlyphCellWalkBeforeDestinationPreflight()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(
                ushort.MaxValue,
                ushort.MaxValue,
                0,
                0),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(
                    ushort.MaxValue,
                    ushort.MaxValue,
                    1,
                    0,
                    0,
                    0,
                    0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            1));

        // The guest glyph is valid inline data, but its declared cell would
        // require more than Int32.MaxValue host samples. Text must decline
        // before entering the nested row/column destination walk.
        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [1] = 0xCAFE_BABEu },
            Cycles = 43
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(43, state.Cycles);
    }

    [Fact]
    public void TextRejectsSelectedPlaneAggregateWorkBeforeReadingTheDestination()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint font = 0x300;
        const uint text = 0x320;

        // The glyph has a one-bit strike but a large signed CharSpace cell.
        // This keeps glyph preflight small while the eight selected planes
        // make the rollback/publication journal exceed the shared host-work
        // contract.  The destination byte is mapped deliberately: the
        // aggregate admission must decline before it is read.
        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2048));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            8192));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            8));
        for (var plane = 0; plane < 8; plane++)
        {
            Assert.True(backing.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                0x1FF0));
        }
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
            0));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF));

        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(8192, 1, 0, 0, hasCharSpace: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(
                    1,
                    8192,
                    16384,
                    0,
                    0,
                    0,
                    0)
            });

        Assert.Equal(0, core.SetFont(rastPort, font, fonts));
        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));
        Assert.Equal(0, memory.TrackedReadCount);
        Assert.Equal(
            (short)0,
            ReadSignedWord(
                backing,
                rastPort + (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayRejectTextSelectedPlaneAggregateWorkBeforeDestinationRead()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint bitMap = 0x200;
        const uint font = 0x300;
        const uint charLoc = 0x400;
        const uint charSpace = 0x420;
        const uint text = 0x440;
        const uint charData = 0x10000;
        const uint nativeTarget = 0x00FE_1A01;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Text)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(charLoc, new byte[16]);
            bus.MapWritableMemory(charSpace, new byte[4]);
            bus.MapWritableMemory(text, new byte[] { (byte)'A' });
            bus.MapWritableMemory(charData, new byte[8192]);

            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2048);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8192);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8, 0);
            for (var plane = 0; plane < 8; plane++)
            {
                bus.WriteLong(
                    bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                    0xDEAD_AD00);
            }

            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF, 0);
            bus.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);

            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8192);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 0);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBoldSmear, 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);
            bus.WriteWord(charLoc, 0);
            bus.WriteWord(charLoc + 2u, 1);
            bus.WriteWord(charLoc + 4u, 0);
            bus.WriteWord(charLoc + 6u, 1);
            bus.WriteWord(charSpace, 16384);
            bus.WriteWord(charSpace + 2u, 16384);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [5] = 0xA5A5_5A5Au },
            Cycles = 713,
            ProgramCounter = 0x0012_38B1
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [5] = 0xA5A5_5A5Au },
            Cycles = 713,
            ProgramCounter = 0x0012_38B1
        };

        direct.Invoke(directState, (int)GraphicsLvo.Text);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Text)),
            overlayState));
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(1u, directState.D[0]);
        Assert.Equal(0xA5A5_5A5Au, directState.D[5]);
        Assert.Equal(directState.D[5], overlayState.D[5]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        Assert.Equal(nativeTarget, overlayState.ProgramCounter);
    }

    [Fact]
    public void TextRestoresEarlierGlyphPixelsAndCursorWhenAPlanarWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint text = 0x320;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.True(backing.TryWriteByte(plane0, 0));
        Assert.True(backing.TryWriteByte(plane1, 0));
        Assert.Equal(0, core.SetFont(rastPort, 0x300, fonts));
        Assert.Equal(0, core.Move(rastPort, 0, 5));

        // The first glyph pixel publishes both planes; fail the next pixel's
        // second plane and require Text to restore the complete operation.
        memory.FailOnNextByteWrite(4);
        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));
        Assert.Equal((byte)0, ReadByte(backing, plane0));
        Assert.Equal((byte)0, ReadByte(backing, plane1));
        Assert.Equal((short)0, unchecked((short)ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
    }

    [Fact]
    public void PolyDrawRestoresEarlierLinesAndStateWhenALaterLineWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint points = 0x600;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;

        Assert.True(backing.TryWriteWord(points, 0));
        Assert.True(backing.TryWriteWord(points + 2u, 0));
        Assert.True(backing.TryWriteWord(points + 4u, 1));
        Assert.True(backing.TryWriteWord(points + 6u, 0));
        Assert.True(backing.TryWriteWord(points + 8u, 2));
        Assert.True(backing.TryWriteWord(points + 10u, 0));
        Assert.True(backing.TryWriteByte(plane0, 0));
        Assert.True(backing.TryWriteByte(plane1, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 3));

        // Move to the first point (four writes), draw the first two-pixel
        // segment (four pixel bytes plus five state bytes), then fail the
        // second plane of the final point in the next segment.
        memory.FailOnNextByteWrite(15);
        Assert.Equal(-1, core.PolyDraw(rastPort, 3, points));
        Assert.Equal((byte)0, ReadByte(backing, plane0));
        Assert.Equal((byte)0, ReadByte(backing, plane1));
        Assert.Equal((short)0, unchecked((short)ReadWord(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)15, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void PolyDrawRestoresCursorAfterRejectedPartialWordPublication()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint points = 0x600;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;
        var cursorAddress = rastPort + (uint)GraphicsLayouts.RastPortCurrentX;

        Assert.True(backing.TryWriteWord(points, 1));
        Assert.True(backing.TryWriteWord(points + 2u, 0));
        Assert.True(backing.TryWriteByte(plane0, 0));
        Assert.True(backing.TryWriteByte(plane1, 0));
        Assert.Equal(0, core.SetAPen(rastPort, 3));

        // The nested Draw reaches its final CurrentX WORD after publishing
        // the segment. Reject that WORD after its high byte lands and require
        // the outer PolyDraw journal to preserve the original chain state.
        memory.PartialWordAddress = cursorAddress;

        Assert.Equal(-1, core.PolyDraw(rastPort, 1, points));
        Assert.Equal((byte)0, ReadByte(backing, plane0));
        Assert.Equal((byte)0, ReadByte(backing, plane1));
        Assert.Equal((short)0, ReadSignedWord(backing, cursorAddress));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.PolyDraw(rastPort, 1, points));
        Assert.Equal((short)1, ReadSignedWord(backing, cursorAddress));
    }

    [Fact]
    public void TextPreflightsEveryGlyphBeforePublishingPlanarWrites()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteByte(text + 1, (byte)'B'));

        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(3, 3, 3, 0),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL),
                // The first row is addressable, but the remaining rows fall
                // beyond the guest memory envelope.  Without the complete
                // Text preflight, A would be visible before B fails.
                [(byte)'B'] = new GraphicsGlyph(3, 3, 4, 0, 0x1FFF, 1, 0)
            });

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(-1, core.Text(0x20, text, 2, fonts));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 2));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 2));
        Assert.Equal((short)0, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
    }

    [Fact]
    public void TextPreflightsEveryDestinationRowBeforePublishingPlanarWrites()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint bitMap = 0x100;
        const uint plane0 = 0x400;

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        // Text starts at y=2.  The first two rows of plane 1 are mapped, but
        // the third row crosses the guest-memory boundary.  A per-pixel
        // guard would publish the first rows before discovering that fault.
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u,
            0x1FF9));
        Assert.True(memory.TryWriteByte(plane0 + 4u, 0x5A));
        Assert.True(memory.TryWriteByte(0x1FFD, 0xA5));
        Assert.True(memory.TryWriteByte(0x1FFF, 0xA5));

        var fonts = new FakeFontBackend();
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(-1, core.Text(0x20, text, 1, fonts));

        Assert.Equal((byte)0x5A, ReadByte(memory, plane0 + 4u));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0x1FFD));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0x1FFF));
        Assert.Equal((short)0, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
    }

    [Fact]
    public void TextRejectsAnUnrepresentableGlyphAdvanceBeforeRendering()
