    [Fact]
    public void ScrollRasterRejectsAggregateWorkBeforeStagingTheSource()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new AddressReadTrackingMemory(backing, 0x1FF0);
        var core = CreateCore(memory);
        const uint bitMap = 0x100;

        Assert.True(backing.TryWriteLong(
            0x20u + (uint)GraphicsLayouts.RastPortBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            8190));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            ushort.MaxValue));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(backing.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            0x1FF0));
        Assert.True(backing.TryWriteByte(
            0x20u + (uint)GraphicsLayouts.RastPortMask,
            1));

        // The visible destination is structurally representable but exceeds
        // the four-pass portable scroll budget. The source plane is left
        // unmapped on purpose: an early guard must decline before staging a
        // source pixel or probing that plane.
        Assert.Equal(
            -1,
            core.ScrollRaster(
                0x20,
                1,
                1,
                0,
                0,
                short.MaxValue,
                short.MaxValue));
        Assert.Equal(0, memory.TrackedReadCount);
    }

