    [Fact]
    public void TextHonorsInverseVideoForJam1AndJam2()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint font = 0x300;
        const uint text = 0x320;
        memory.TryWriteByte(text, (byte)'A');

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.SetAPen(0x20, 1));
        Assert.Equal(0, core.SetBPen(0x20, 2));
        Assert.Equal(0, core.SetRast(0x20, 0));
        Assert.Equal(0, core.SetDrawMode(0x20, 4));
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 2));
        Assert.Equal(1, core.ReadPixel(0x20, 3, 2));

        Assert.Equal(0, core.SetRast(0x20, 0));
        Assert.Equal(0, core.SetDrawMode(0x20, 5));
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal(2, core.ReadPixel(0x20, 0, 2));
        Assert.Equal(1, core.ReadPixel(0x20, 3, 2));
    }

    [Fact]
    public void TextInverseModesCoverEmptyFontRowsLikeTheTemplateCell()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 1, 2, 0),
            new Dictionary<byte, GraphicsGlyph>
            {
                // The strike occupies one row, but the font cell is four
                // rows tall.  Native Text builds a full-height template, so
                // the remaining rows are source-zero background cells.
                [(byte)'A'] = new GraphicsGlyph(1, 1, 4, 0x8000000000000000UL)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal((ushort)4, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(0, core.SetAPen(0x20, 1));
        Assert.Equal(0, core.SetDrawMode(0x20, 4)); // JAM1 | INVERSVID
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        // The empty fourth row is part of the inverse-video background cell,
        // even though the decoded glyph strike itself has only one row.
        Assert.Equal(1, core.ReadPixel(0x20, 3, 6));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 6));
        Assert.Equal(1, core.ReadPixel(0x20, 0, 3));

        Assert.Equal(0, core.SetRast(0x20, 0));
        Assert.Equal(0, core.SetDrawMode(0x20, 6)); // COMPLEMENT | INVERSVID
        Assert.Equal(0, core.Move(0x20, 0, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        // COMPLEMENT|INVERSVID leaves the source glyph pixel untouched but
        // complements the source-zero background in the same empty row.
        Assert.Equal(3, core.ReadPixel(0x20, 0, 4));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 5));
        Assert.Equal(3, core.ReadPixel(0x20, 1, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 3));
    }

    [Fact]
    public void GuestTextFontDecoderReadsBitPackedProportionalGlyphs()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new GraphicsMemoryFontBackend(memory);
        memory.TryWriteWord(0x100u + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        const uint font = 0x600;
        const uint charData = 0x700;
        const uint charLoc = 0x800;
        const uint charSpace = 0x900;
        const uint charKern = 0xA00;
        const uint text = 0xB00;

        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0x04);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'B');
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 2);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);

        // A starts at bit one and is five pixels wide; B starts at bit nine.
        memory.TryWriteWord(charLoc, 1);
        memory.TryWriteWord(charLoc + 2, 5);
        memory.TryWriteWord(charLoc + 4, 9);
        memory.TryWriteWord(charLoc + 6, 3);
        memory.TryWriteWord(charSpace, 6);
        memory.TryWriteWord(charSpace + 2, 4);
        memory.TryWriteWord(charKern, unchecked((ushort)-1));
        memory.TryWriteWord(charKern + 2, 0);
        memory.TryWriteByte(charData, 0x54); // A: 10101
        memory.TryWriteByte(charData + 1, 0x70); // B: 111
        memory.TryWriteByte(charData + 2, 0x28); // A second row: 01010
        memory.TryWriteByte(charData + 3, 0x40); // B second row: 100
        memory.TryWriteByte(text, (byte)'A');
        memory.TryWriteByte(text + 1, (byte)'B');

        Assert.True(fonts.TryGetMetrics(font, out var metrics));
        Assert.Equal((ushort)4, metrics.Height);
        Assert.Equal((ushort)8, metrics.Width);
        Assert.Equal((ushort)3, metrics.Baseline);
        Assert.Equal((byte)0x04, metrics.Flags);
        Assert.True(fonts.TryGetGlyph(font, (byte)'A', out var glyphA));
        Assert.True(glyphA.TryIsSet(memory, 0, 0, out var a0) && a0);
        Assert.True(glyphA.TryIsSet(memory, 1, 0, out var a1) && !a1);
        Assert.Equal(6, glyphA.Advance);
        Assert.Equal((short)-1, glyphA.Kerning);
        Assert.True(fonts.TryGetGlyph(font, (byte)'B', out var glyphB));
        Assert.True(glyphB.TryIsSet(memory, 0, 0, out var b0) && b0);

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.True(memory.TryWriteWord(0x20u + (uint)GraphicsLayouts.RastPortTextSpacing, 1));
        Assert.Equal((ushort)1, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortTextSpacing));
        Assert.Equal(12, core.TextLength(0x20, text, 2, fonts));
        const uint extent = 0xC00;
        Assert.Equal(0, core.TextExtent(0x20, text, 2, extent, fonts));
        Assert.Equal((ushort)12, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-1, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)10, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal(1, core.TextFit(0x20, text, 2, extent, 0, 1, 10, 4, fonts));
        Assert.Equal(0, core.Move(0x20, 10, 5));
        Assert.Equal(0, core.Text(0x20, text, 2, fonts));
        // TextLength excludes the initial negative kern, so Text publishes
        // the same 11-pixel advance from the starting X of 10.
        Assert.Equal(22, unchecked((short)ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal(3, core.ReadPixel(0x20, 9, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 11, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 16, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 17, 2));
        Assert.Equal(3, core.ReadPixel(0x20, 18, 2));
    }

    [Fact]
    public void GuestFontDecoderRejectsOddWordMetricTablesBeforeMetricsOrGlyphReads()
    {
        foreach (var oddTable in new[] { "CharLoc", "CharSpace", "CharKern" })
        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            var fonts = new GraphicsMemoryFontBackend(memory);
            const uint font = 0x600;
            const uint charData = 0x700;
            const uint charLoc = 0x800;
            const uint charSpace = 0x900;
            const uint charKern = 0xA00;
            const uint rastPort = 0x20;
            const uint text = 0xB00;
            const uint extent = 0xC00;

            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
            memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
            memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
            memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
            memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharLoc,
                oddTable == "CharLoc" ? charLoc + 1 : charLoc);
            memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharSpace,
                oddTable == "CharSpace" ? charSpace + 1 : charSpace);
            memory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharKern,
                oddTable == "CharKern" ? charKern + 1 : charKern);
            memory.TryWriteWord(charLoc, 0);
            memory.TryWriteWord(charLoc + 2, 1);
            memory.TryWriteWord(charLoc + 4, 0);
            memory.TryWriteWord(charLoc + 6, 1);
            memory.TryWriteWord(charSpace, 1);
            memory.TryWriteWord(charSpace + 2, 1);
            memory.TryWriteWord(charKern, 0);
            memory.TryWriteWord(charKern + 2, 0);
            memory.TryWriteByte(charData, 0x80);
            memory.TryWriteByte(text, (byte)'A');
            memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            memory.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);
            for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
                memory.TryWriteByte(extent + (uint)offset, 0xA5);

            // A host byte adapter can see the odd table bytes, but native
            // 68000 WORD reads cannot. Reject the complete font before a
            // metrics or glyph operation can observe a shifted table.
            Assert.False(fonts.HasMetrics(font), oddTable);
            Assert.False(fonts.HasMetrics(font + 1), "odd TextFont base");
            Assert.False(fonts.TryGetMetrics(font, out _), oddTable);
            Assert.False(fonts.TryGetGlyph(font, (byte)'A', out _), oddTable);
            Assert.Equal(-1, core.SetFont(rastPort, font, fonts));
            Assert.Equal(-1, core.TextLength(rastPort, text, 1, fonts));
            Assert.Equal(-1, core.FontExtent(font, extent, fonts));
            for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
                Assert.Equal((byte)0xA5, ReadByte(memory, extent + (uint)offset));
        }
    }

    [Fact]
    public void HostRegisterAdapterLeavesOddWordMetricTablesForNativeOwnership()
    {
        foreach (var oddOffset in new[]
        {
            GraphicsLayouts.TextFontCharLoc,
            GraphicsLayouts.TextFontCharSpace,
            GraphicsLayouts.TextFontCharKern
        })
        {
            var memory = new FakeMemory(0x2000);
            var core = CreateCore(memory);
            var adapter = new CopperStartGraphicsRegisterAdapter(core);
            const uint font = 0x600;
            const uint charData = 0x700;
            const uint charLoc = 0x800;
            const uint charSpace = 0x900;
            const uint charKern = 0xA00;
            const uint rastPort = 0x20;
            const uint text = 0xB00;

            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
            memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
            memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
            memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
            memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
            memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
            memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
            memory.TryWriteLong(font + (uint)oddOffset, oddOffset switch
            {
                GraphicsLayouts.TextFontCharLoc => charLoc + 1u,
                GraphicsLayouts.TextFontCharSpace => charSpace + 1u,
                _ => charKern + 1u
            });
            memory.TryWriteWord(charLoc, 0);
            memory.TryWriteWord(charLoc + 2, 1);
            memory.TryWriteWord(charLoc + 4, 0);
            memory.TryWriteWord(charLoc + 6, 1);
            memory.TryWriteWord(charSpace, 1);
            memory.TryWriteWord(charSpace + 2, 1);
            memory.TryWriteWord(charKern, 0);
            memory.TryWriteWord(charKern + 2, 0);
            memory.TryWriteByte(charData, 0x80);
            memory.TryWriteByte(text, (byte)'A');
            memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            memory.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);

            var state = new M68kCpuState
            {
                A = { [0] = text, [1] = rastPort },
                D = { [0] = 1, [1] = 0xBADC_0DEu },
                Cycles = 271
            };
            Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextLength));
            Assert.Equal(1u, state.D[0]);
            Assert.Equal(271, state.Cycles);
        }
    }

    [Fact]
    public void RomOverlayLeavesOddWordMetricTablesForNativeOwnership()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;

        foreach (var oddOffset in new[]
        {
            GraphicsLayouts.TextFontCharLoc,
            GraphicsLayouts.TextFontCharSpace,
            GraphicsLayouts.TextFontCharKern
        })
        {
            const uint font = 0x1000;
            const uint charData = 0x1100;
            const uint charLoc = 0x1200;
            const uint charSpace = 0x1300;
            const uint charKern = 0x1400;
            const uint rastPort = 0x1500;
            const uint text = 0x1600;
            var bus = new AmigaBus();
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(font, new byte[0x80]);
            bus.MapWritableMemory(charData, new byte[0x100]);
            bus.MapWritableMemory(charLoc, new byte[0x100]);
            bus.MapWritableMemory(charSpace, new byte[0x100]);
            bus.MapWritableMemory(charKern, new byte[0x100]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(text, new byte[0x20]);

            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A', 0);
            bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A', 0);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
            bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, charSpace);
            bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, charKern);
            bus.WriteLong(
                font + (uint)oddOffset,
                oddOffset switch
                {
                    GraphicsLayouts.TextFontCharLoc => charLoc + 1u,
                    GraphicsLayouts.TextFontCharSpace => charSpace + 1u,
                    _ => charKern + 1u
                });
            bus.WriteWord(charLoc, 0);
            bus.WriteWord(charLoc + 2, 1);
            bus.WriteWord(charLoc + 4, 0);
            bus.WriteWord(charLoc + 6, 1);
            bus.WriteWord(charSpace, 1);
            bus.WriteWord(charSpace + 2, 1);
            bus.WriteWord(charKern, 0);
            bus.WriteWord(charKern + 2, 0);
            bus.WriteByte(charData, 0x80, 0);
            bus.WriteByte(text, (byte)'A', 0);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
            bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 0);

            using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
            Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
            var state = new M68kCpuState
            {
                A = { [0] = text, [1] = rastPort },
                D = { [0] = 1, [1] = 0xCAFE_BABEu },
                Cycles = 283
            };
            var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.TextLength));
            Assert.True(bus.TryInvokeHostGatewayAt(address, state));
            Assert.Equal(1u, state.D[0]);
            Assert.Equal(0xCAFE_BABEu, state.D[1]);
            Assert.Equal(283, state.Cycles);
        }
    }

    [Fact]
    public void GuestTextFontDecoderUsesTheFinalGlyphForTextButNotFontExtent()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint charData = 0x700;
        const uint charLoc = 0x800;
        const uint text = 0x900;

        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);

        // The second CharLoc entry is the default glyph following the A entry.
        memory.TryWriteWord(charLoc, 0);
        memory.TryWriteWord(charLoc + 2, 1);
        memory.TryWriteWord(charLoc + 4, 0);
        memory.TryWriteWord(charLoc + 6, 3);
        memory.TryWriteByte(charData, 0xE0);
        memory.TryWriteByte(text, (byte)'B');

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.True(fonts.TryGetGlyph(font, (byte)'B', out var defaultGlyph));
        Assert.Equal((ushort)3, defaultGlyph.Width);
        Assert.Equal(8, defaultGlyph.Advance);
        Assert.Equal(8, core.TextLength(0x20, text, 1, fonts));
        const uint defaultExtent = 0x980;
        Assert.Equal(0, core.FontExtent(font, defaultExtent, fonts));
        Assert.Equal((ushort)8, ReadWord(memory, defaultExtent + (uint)GraphicsLayouts.TextExtentWidth));
        // The fallback glyph still serves Text/TextLength for an out-of-range
        // byte, but FontExtent only covers the declared A character.
        Assert.Equal((short)0, ReadSignedWord(memory, defaultExtent + (uint)GraphicsLayouts.TextExtentMaxX));
        Assert.Equal(0, core.Move(0x20, 0, 3));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));
        Assert.Equal(0, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(0, core.ReadPixel(0x20, 1, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 0));
        Assert.Equal((short)8, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
    }

    [Fact]
    public void GuestTextFontDecoderReadsTheDefaultSlotForAFullByteRange()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint charData = 0x700;

        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 0);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, byte.MaxValue);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 64);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);

        // With a one-pixel fixed cell, table index 256 starts at bit 256.
        memory.TryWriteByte(charData + 32, 0x80);

