        Assert.Equal((ushort)1, glyph.Width);
        Assert.Equal((ushort)1, glyph.Height);
        Assert.Equal((ushort)256, glyph.BitOffset);
        Assert.True(glyph.TryIsSet(memory, 0, 0, out var set) && set);
    }

