    [Fact]
    public void TextAcceptsAnUnsignedFixedCellAdvanceAboveSignedWordRange()
    {
        var memory = new FakeMemory(0x200000);
        var core = CreateCore(memory);
        const uint font = 0x600;
        const uint glyphData = 0x2000;
        const uint text = 0x30000;

        // tf_XSize is an unsigned WORD.  A 40000-pixel fixed cell is unusual
        // but guest-valid; the one-pixel strike is centered in that cell.
        memory.TryWriteWord(0x100u + (uint)GraphicsLayouts.BitMapBytesPerRow, 6000);
        memory.TryWriteWord(0x100u + (uint)GraphicsLayouts.BitMapRows, 1);
        memory.TryWriteByte(glyphData, 0x80);
        memory.TryWriteByte(text, (byte)'A');

        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(1, 40000, 0, 0),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(1, 1, 40000, 0, glyphData, 1, 0)
            });

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        // The strike is centered at (40000 - 1) / 2.  The public cursor is
        // still clipped to the signed RastPort coordinate range.
        Assert.Equal(3, core.ReadPixel(0x20, 19999, 0));
        Assert.Equal((short)32767, ReadSignedWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX));

        var reverseFonts = new TableFontBackend(
            new GraphicsFontMetrics(1, 40000, 0, 0, flags: 0x04),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(1, 1, -40000, 0, glyphData, 1, 0)
            });
        Assert.Equal(0, core.SetFont(0x20, font, reverseFonts));
        Assert.Equal(-40000, core.TextLength(0x20, text, 1, reverseFonts));
        const uint reverseExtent = 0x31000;
        Assert.Equal(0, core.TextExtent(0x20, text, 1, reverseExtent, reverseFonts));
        Assert.Equal(
            unchecked((ushort)-40000),
            ReadWord(memory, reverseExtent + (uint)GraphicsLayouts.TextExtentWidth));
    }

    [Fact]
    public void ReversePathTextRendersTheGlyphCellToTheLeftAndUnderlinesItsAdvance()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint glyphData = 0x700;
        memory.TryWriteByte(text, (byte)'A');
        memory.TryWriteByte(glyphData, 0xE0);
        memory.TryWriteByte(glyphData + 1, 0xA0);
        memory.TryWriteByte(glyphData + 2, 0xE0);

        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 3, 2, 0, flags: 0x04),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(3, 3, -3, 0, glyphData, 1, 0)
            });

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(1, core.SetSoftStyle(0x20, 1, 1, fonts));
        Assert.Equal(0, core.Move(0x20, 5, 5));
        Assert.Equal(0, core.Text(0x20, text, 1, fonts));

        // A reverse-path glyph consumes three pixels to the left of the
        // original pen position, and its underline follows that same cell.
        Assert.Equal(3, core.ReadPixel(0x20, 2, 3));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 3));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 3));
        Assert.Equal(3, core.ReadPixel(0x20, 2, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 3, 6));
        Assert.Equal(3, core.ReadPixel(0x20, 4, 6));
        Assert.Equal((short)2, unchecked((short)ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortCurrentX)));
    }

    [Fact]
    public void ReversePathTextMetricsFollowTheNegativeMovementCell()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 3, 2, 0, flags: 0x04),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(3, 3, -3, 0, 0, 1, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((short)-3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)-1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));

        Assert.Equal(1, core.TextFit(0x20, text, 1, extent, 0, 1, 3, 4, fonts));
        Assert.Equal((short)-3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-3, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)-1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));
    }

    [Fact]
    public void GuestTextFontDecoderRejectsGlyphThatExceedsItsModuloRow()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint charData = 0x700;
        const uint charLoc = 0x800;

        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);

        // A one-byte row cannot contain a five-bit glyph beginning at bit 6.
        memory.TryWriteWord(charLoc, 6);
        memory.TryWriteWord(charLoc + 2, 5);
        memory.TryWriteByte(charData, 0xFC);

        Assert.False(fonts.TryGetGlyph(font, (byte)'A', out _));
    }

