    [Fact]
    public void AskFontCopiesAReadableZeroHeightFontWithoutApplyingLifecycleAdmission()
    {
        const uint rastPort = 0x20;
        const uint font = 0x600;
        const uint textAttr = 0x400;
        const uint name = 0xF000_0000u;
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        // AskFont only observes the four public TextFont fields below.  The
        // name pointer need not be dereferenced, and a zero YSize is copied
        // verbatim even though lifecycle/rendering admission rejects it.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontName,
            name));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            0));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontStyle,
            0x05));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontFlags,
            0xA0));

        Assert.Equal(0, core.AskFont(rastPort, textAttr));
        Assert.Equal(name, ReadLong(memory, textAttr + (uint)GraphicsLayouts.TextAttrName));
        Assert.Equal((ushort)0, ReadWord(memory, textAttr + (uint)GraphicsLayouts.TextAttrYSize));
        Assert.Equal((byte)0x05, ReadByte(memory, textAttr + (uint)GraphicsLayouts.TextAttrStyle));
        Assert.Equal((byte)0xA0, ReadByte(memory, textAttr + (uint)GraphicsLayouts.TextAttrFlags));

        var direct = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 307
        };
        Assert.True(adapter.TryInvoke(direct, (int)GraphicsLvo.AskFont));
        Assert.Equal(0u, direct.D[0]);
        Assert.Equal(307, direct.Cycles);

        var mapped = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 313
        };
        Assert.True(adapter.TryInvoke(
            mapped,
            (int)GraphicsLvo.AskFont,
            nativeOverlay: true));
        Assert.Equal(0u, mapped.D[0]);
        Assert.Equal(313, mapped.Cycles);
    }

