    [Fact]
    public void AskFontRestoresTextAttrWhenALateOutputByteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x400;
        WriteFontHeader(backing, font, name, ySize: 9, style: 0x02, flags: 0x01);
        WriteAscii(backing, name, "topaz.font");
        Assert.True(backing.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font));
        for (var offset = 0; offset < GraphicsLayouts.TextAttrSize; offset++)
            Assert.True(backing.TryWriteByte(textAttr + (uint)offset, (byte)(0x70 + offset)));

        // Name writes four bytes; fail the second byte of the YSize word.
        memory.FailOnNextByteWrite(6);
        Assert.Equal(-1, core.AskFont(rastPort, textAttr));
        for (var offset = 0; offset < GraphicsLayouts.TextAttrSize; offset++)
            Assert.Equal((byte)(0x70 + offset), ReadByte(backing, textAttr + (uint)offset));
    }

    [Fact]
    public void FontLifecycleMatchesAddedFontsTracksAccessorsAndRemovesAvailability()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x400;
        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "topaz.font");
        memory.TryWriteLong(textAttr + (uint)GraphicsLayouts.TextAttrName, name);
        memory.TryWriteWord(textAttr + (uint)GraphicsLayouts.TextAttrYSize, 9);
        memory.TryWriteByte(textAttr + (uint)GraphicsLayouts.TextAttrStyle, 0);
        memory.TryWriteByte(textAttr + (uint)GraphicsLayouts.TextAttrFlags, 1);

        Assert.Equal(0, core.AddFont(font, fonts));
        Assert.Equal(GraphicsLayouts.TextFontNodeTypeFont,
            ReadByte(memory, font + (uint)GraphicsLayouts.TextFontNodeType));
        Assert.Equal((ushort)0, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(font, core.OpenFont(textAttr, fonts));
        Assert.Equal((ushort)1, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
        // RemFont removes future availability, but an already-open pointer
        // remains closeable until its accessor count reaches zero.
        Assert.Equal(0, core.RemFont(font, fonts));
        Assert.Equal(0u, core.OpenFont(textAttr, fonts));
        Assert.Equal(0, core.CloseFont(font, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(0, core.AddFont(font, fonts));
        Assert.Equal(font, core.OpenFont(textAttr, fonts));
        Assert.Equal(0, core.CloseFont(font, fonts));
        Assert.Equal(0, core.RemFont(font, fonts));
        Assert.Equal(0u, core.OpenFont(textAttr, fonts));
    }

    [Fact]
    public void CloseFontRemovesLastAccessorForNonRomFontFromGuestListAcrossDirectAndRegisterBoundaries()
    {
        var memory = new FakeMemory(0x8000);
        var allocator = new FakeAllocator();
        const uint gfxBase = 0x1000;
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x400;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 0);
        WriteAscii(memory, name, "guest-list.font");
        WriteTextAttr(memory, textAttr, name, ySize: 9, style: 0, flags: 0);

        var guestList = new GraphicsGuestFontListBackend(memory, gfxBase);
        Assert.True(guestList.Initialize(0));

        // Publish the node through a separate owner so the matcher being
        // exercised sees it as a resident native-list font, not as a font
        // inserted into its private compatibility registry.
        var publisher = new GraphicsMemoryFontBackend(memory, allocator, fontList: guestList);
        Assert.True(publisher.TryAdd(font));

        var fonts = new GraphicsMemoryFontBackend(memory, allocator, fontList: guestList);
        Assert.True(fonts.TryOpen(textAttr, out var opened));
        Assert.Equal(font, opened);
        Assert.Equal((ushort)1, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.True(fonts.TryClose(opened));
        Assert.Equal((ushort)0, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.True(guestList.TryEnumerate(out var afterDirectClose));
        Assert.Empty(afterDirectClose);

        // Re-publish through a fresh owner, then exercise the same native
        // resident-list removal through the CopperStart register ABI.
        var secondPublisher = new GraphicsMemoryFontBackend(memory, allocator, fontList: guestList);
        Assert.True(secondPublisher.TryAdd(font));
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core, fontList: guestList);
        var openState = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 271
        };
        Assert.True(adapter.TryInvoke(openState, (int)GraphicsLvo.OpenFont));
        Assert.Equal(font, openState.D[0]);

        var closeState = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 277
        };
        Assert.True(adapter.TryInvoke(closeState, (int)GraphicsLvo.CloseFont));
        Assert.Equal(0u, closeState.D[0]);
        Assert.Equal(277, closeState.Cycles);
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
    }

    [Fact]
    public void OpenFontAcceptsReadableZeroSizedRequestAcrossDirectAndRegisterBoundaries()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x400;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "zero-request.font");
        WriteTextAttr(memory, textAttr, name, ySize: 0, style: 0, flags: 1);
        Assert.Equal((ushort)0, ReadWord(memory, textAttr + (uint)GraphicsLayouts.TextAttrYSize));
        Assert.Equal((ushort)9, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontYSize));
        Assert.True(GraphicsFontOperations.TryReadTextAttributes(memory, textAttr, out var requestAttributes));
        Assert.Equal((ushort)0, requestAttributes.YSize);
        Assert.True(GraphicsFontOperations.TryReadTextFontAttributes(memory, font, out var fontAttributes));
        Assert.Equal((ushort)9, fontAttributes.YSize);
        Assert.True(fonts.TryAdd(font));
        const uint targetAttr = 0x700;
        WriteTextAttr(memory, targetAttr, name, ySize: 9, style: 0, flags: 1);
        Assert.True(fonts.TryWeighTAMatch(textAttr, targetAttr, 0, out var textAttrWeight));
        Assert.Equal((short)31615, textAttrWeight);

        Assert.Equal(font, core.OpenFont(textAttr, fonts));
        Assert.Equal((ushort)1, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(0, core.CloseFont(font, fonts));

        var add = new M68kCpuState { A = { [1] = font } };
        Assert.True(adapter.TryInvoke(add, (int)GraphicsLvo.AddFont));
        var state = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 229
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.OpenFont));
        Assert.Equal(font, state.D[0]);
        Assert.Equal(229, state.Cycles);
        var close = new M68kCpuState { A = { [1] = font } };
        Assert.True(adapter.TryInvoke(close, (int)GraphicsLvo.CloseFont));
    }

    [Fact]
    public void FontTextAttributeAndTextFontBasesRequireNativeWordAlignment()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), display);
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint evenTextAttr = 0x400;
        const uint oddTextAttr = 0x421;
        const uint rastPort = 0x800;
        const uint oddFont = 0xA01;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "topaz.font");
        WriteTextAttr(memory, evenTextAttr, name, ySize: 9, style: 0, flags: 1);
        Assert.True(fonts.TryAdd(font));

        // TextAttr and TextFont contain word/long fields.  An odd base must
        // remain available to the native 68000/provider path instead of
        // being byte-decoded by the portable matcher.
        WriteTextAttr(memory, oddTextAttr, name, ySize: 9, style: 0, flags: 1);
        Assert.Equal(0u, core.OpenFont(oddTextAttr, fonts));

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            oddFont));
        Assert.Equal(-1, core.AskFont(rastPort, evenTextAttr));
        Assert.Equal(name, ReadLong(memory, evenTextAttr + (uint)GraphicsLayouts.TextAttrName));
        Assert.Equal((ushort)9, ReadWord(memory, evenTextAttr + (uint)GraphicsLayouts.TextAttrYSize));
        Assert.Equal((byte)0, ReadByte(memory, evenTextAttr + (uint)GraphicsLayouts.TextAttrStyle));
        Assert.Equal((byte)1, ReadByte(memory, evenTextAttr + (uint)GraphicsLayouts.TextAttrFlags));

        // The register gateway must preserve D0/cycles when the odd guest
        // request is declined, just as a native address-error/provider
        // boundary would.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = oddTextAttr },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 77
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.OpenFont));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(77, state.Cycles);
    }

    [Fact]
    public void RemFontHonorsTextFontExtensionNoRemoveFlagWithoutMutatingAvailability()
    {
        var memory = new FakeMemory(0x4000);
