    [Fact]
    public void FontLifecycleRejectsOddTextFontExtensionPointersBeforeNativeWordReads()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var fontList = new GraphicsGuestFontListBackend(memory, 0x1000);
        Assert.True(fontList.Initialize(0));
        var fonts = new GraphicsMemoryFontBackend(memory, allocator, fontList: fontList);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core, fontList: fontList);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint oddExtension = 0x901;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "odd-extension.font");
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontExtension,
            oddExtension));
        // FakeMemory deliberately keeps the odd envelope readable.  The
        // portable lifecycle must still leave the address-error/provider
        // boundary intact before reading the extension's WORD/LONG fields.
        Assert.True(memory.TryWriteWord(
            oddExtension + (uint)GraphicsLayouts.TextFontExtensionMatchWord,
            0xF00D));
        Assert.True(memory.TryWriteByte(
            oddExtension + (uint)GraphicsLayouts.TextFontExtensionFlags0,
            0));
        Assert.True(memory.TryWriteLong(
            oddExtension + (uint)GraphicsLayouts.TextFontExtensionBackPtr,
            font));

        Assert.True(fonts.TryAdd(font));
        Assert.False(fonts.TryRemove(font));
        Assert.False(fonts.TryStrip(font));
        Assert.Equal(oddExtension,
            ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0,
            (byte)(ReadByte(memory, font + (uint)GraphicsLayouts.TextFontFlags) & 0x80));

        var state = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 233
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.RemFont, nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(233, state.Cycles);
        Assert.Equal(oddExtension,
            ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
    }

    [Fact]
    public void CloseFontRejectsOddTextFontPointersBeforeAccessorMutation()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        const uint oddFont = 0x601;
        var fonts = new GraphicsMemoryFontBackend(
            memory,
            allocator,
            defaultFont: () => oddFont);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        // FakeMemory deliberately permits an odd WORD envelope.  The portable
        // boundary must nevertheless leave it to the native 68000/provider
        // path instead of decrementing tf_Accessors byte-wise.
        Assert.True(memory.TryWriteWord(
            oddFont + (uint)GraphicsLayouts.TextFontAccessors,
            1));
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.CloseFont(oddFont, fonts));
        Assert.Equal(
            (ushort)1,
            ReadWord(memory, oddFont + (uint)GraphicsLayouts.TextFontAccessors));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = oddFont },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 239
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.CloseFont));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(239, state.Cycles);
        Assert.Equal(
            (ushort)1,
            ReadWord(memory, oddFont + (uint)GraphicsLayouts.TextFontAccessors));
    }

    [Fact]
    public void RemFontRejectsOddTextFontPointersBeforeRetiringTheFont()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        const uint oddFont = 0x601;
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        // FakeMemory deliberately permits odd accesses.  RemFont must not
        // turn such an address into a removed public font by reading its
        // byte-shifted accessor and extension fields.
        Assert.True(memory.TryWriteWord(
            oddFont + (uint)GraphicsLayouts.TextFontAccessors,
            0));
        Assert.True(memory.TryWriteByte(
            oddFont + (uint)GraphicsLayouts.TextFontFlags,
            0x21));
        Assert.Equal(
            GraphicsRasterOperations.Failure,
            core.RemFont(oddFont, fonts));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, oddFont + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(
            (byte)0x21,
            ReadByte(memory, oddFont + (uint)GraphicsLayouts.TextFontFlags));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = oddFont },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 241
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.RemFont));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(241, state.Cycles);
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, oddFont + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(
            (byte)0x21,
            ReadByte(memory, oddFont + (uint)GraphicsLayouts.TextFontFlags));
    }

