    [Fact]
    public void RemFontStripsOwnedExtensionAndReleasesItsAllocation()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(memory, font, name, ySize: 9, style: 0x04, flags: 1);
        WriteAscii(memory, name, "remove-owned.font");

        Assert.True(fonts.TryExtend(font, 0));
        var extension = ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension);
        Assert.NotEqual(0u, extension);
        Assert.True(fonts.TryAdd(font));

        Assert.True(fonts.TryRemove(font));
        Assert.Equal(0u, ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x04, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(extension, allocator.LastFreedAddress);
    }

    [Fact]
    public void RemFontRestoresAvailabilityWhenOwnedStripFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new FakeAllocator();
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(backing, font, name, ySize: 9, style: 0x04, flags: 1);
        WriteAscii(backing, name, "remove-retry.font");
        Assert.True(fonts.TryExtend(font, 0));

        var extension = ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension);
        Assert.True(fonts.TryAdd(font));

        // AddFont has consumed four byte writes.  RemFont's flag write is
        // first, then StripFont's four-byte extension detach; fail its final
        // byte so the registration rollback path is exercised.
        memory.FailOnNextByteWrite(5);
        Assert.False(fonts.TryRemove(font));
        Assert.Equal(extension, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x84, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal((ushort)0, ReadWord(backing, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(0, allocator.FreeCount);

        Assert.True(fonts.TryRemove(font));
        Assert.Equal(0u, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Fact]
    public void RemFontRestoresAccessorAfterRejectedRepeatedWordRollback()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new PartialThenRejectLongAndDeferredWordWriteMemory(backing);
        var allocator = new FakeAllocator();
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(backing, font, name, ySize: 9, style: 0x04, flags: 1);
        WriteAscii(backing, name, "remove-accessor-retry.font");

        Assert.True(fonts.TryExtend(font, 0));
        var extension = ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension);
        Assert.True(fonts.TryAdd(font));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontAccessors,
            2));

        memory.PartialLongAddress = font + (uint)GraphicsLayouts.TextFontExtension;
        memory.DeferredWordAddress = font + (uint)GraphicsLayouts.TextFontAccessors;
        memory.ArmDeferredWordFailure = true;

        Assert.False(fonts.TryRemove(font));
        Assert.Equal(extension, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal(
            (ushort)2,
            ReadWord(backing, font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(0, allocator.FreeCount);

        memory.PartialLongAddress = null;
        memory.ArmDeferredWordFailure = false;
        Assert.True(fonts.TryRemove(font));
        Assert.Equal(0u, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal(1, allocator.FreeCount);
    }

