    [Fact]
    public void OpenFontRestoresAccessorAfterRejectedIncrementWord()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x700;
        WriteFontHeader(backing, font, name, ySize: 9, style: 0x04, flags: 1);
        WriteAscii(backing, name, "open-accessor-retry.font");
        WriteTextAttr(backing, textAttr, name, ySize: 9, style: 0x04, flags: 0);

        Assert.True(fonts.TryAdd(font));
        Assert.True(backing.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontAccessors,
            0x00FF));
        memory.PartialWordAddress = font + (uint)GraphicsLayouts.TextFontAccessors;

        Assert.False(fonts.TryOpen(textAttr, out _));
