    [Fact]
    public void OpenFontUsesKickstartWeightTamatchOrderingAndSourceRules()
    {
        var memory = new FakeMemory(0x12000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint name = 0x1000;
        const uint textAttr = 0x1100;
        const uint exact = 0x2000;
        const uint styleMismatch = 0x2100;
        const uint sizeMismatch = 0x2200;
        const uint disk = 0x2300;
        const uint diskRevPath = 0x2400;
        const byte bold = 1 << 1;
        const byte diskFlag = 1 << 1;
        const byte revPathFlag = 1 << 2;
        const byte designedFlag = 1 << 6;

        WriteAscii(memory, name, "match.font");
        WriteFontHeader(memory, styleMismatch, name, ySize: 10, style: 0, flags: 0);
        WriteFontHeader(memory, sizeMismatch, name, ySize: 9, style: bold, flags: 0);
        WriteFontHeader(memory, exact, name, ySize: 10, style: bold, flags: 0);
        WriteFontHeader(memory, disk, name, ySize: 10, style: bold,
            flags: (byte)(diskFlag | designedFlag));
        WriteFontHeader(memory, diskRevPath, name, ySize: 10, style: bold,
            flags: (byte)(diskFlag | revPathFlag));
        Assert.True(fonts.TryAdd(styleMismatch));
        Assert.True(fonts.TryAdd(sizeMismatch));
        Assert.True(fonts.TryAdd(exact));
        Assert.True(fonts.TryAdd(disk));
        Assert.True(fonts.TryAdd(diskRevPath));

        WriteTextAttr(memory, textAttr, name, ySize: 10, style: bold, flags: 0);
        Assert.Equal(exact, fonts.TryOpen(textAttr, out var opened) ? opened : 0u);
        Assert.True(fonts.TryClose(opened));
        // The last CloseFont accessor already removes non-ROM fonts from
        // future matching, so an explicit RemFont is now a rejected duplicate.
        Assert.False(fonts.TryRemove(exact));

        // ROM/DISK are source bits, not ordinary Hamming-distance style
        // preferences.  With the exact ROM-like candidate removed, the disk
        // font remains an equally good match.
        Assert.Equal(disk, fonts.TryOpen(textAttr, out opened) ? opened : 0u);
        Assert.True(fonts.TryClose(opened));
        // Disk fonts are non-ROM too; re-publicize the candidate for the
        // following designed-request comparison after CloseFont removes it.
        Assert.True(fonts.TryAdd(disk));

        // A designed request accepts a disk-backed designed variant but not a
        // constructed font.  REVPATH remains a hard incompatibility.
        WriteTextAttr(memory, textAttr, name, ySize: 10, style: bold, flags: designedFlag);
        Assert.Equal(disk, fonts.TryOpen(textAttr, out opened) ? opened : 0u);
        Assert.True(fonts.TryClose(opened));
        Assert.False(fonts.TryRemove(disk));

        // Size is considered before style: an exact-size plain font beats a
        // one-pixel-nearer bold font when no exact style candidate exists.
        WriteTextAttr(memory, textAttr, name, ySize: 10, style: bold, flags: 0);
        Assert.Equal(styleMismatch, fonts.TryOpen(textAttr, out opened) ? opened : 0u);
        Assert.True(fonts.TryClose(opened));

        WriteTextAttr(memory, textAttr, name, ySize: 10, style: bold, flags: revPathFlag);
        Assert.Equal(diskRevPath, fonts.TryOpen(textAttr, out opened) ? opened : 0u);
        Assert.True(fonts.TryClose(opened));
    }

    [Fact]
    public void OpenFontMatchesResidentNodeNamesWithoutOpenDiskFontPathStripping()
    {
        var memory = new FakeMemory(0x12000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint residentName = 0x1000;
        const uint requestName = 0x1100;
        const uint textAttr = 0x1200;
        const uint font = 0x2000;

        // OpenFont searches the resident TextFonts list.  Its comparison is
        // against the node name as stored; a path-bearing TextAttr is for
        // OpenDiskFont and must not be reduced to a basename here.
        WriteAscii(memory, residentName, "FONTS:match.font");
        WriteAscii(memory, requestName, "match.font");
        WriteFontHeader(memory, font, residentName, ySize: 9, style: 0, flags: 1);
        Assert.True(fonts.TryAdd(font));

        WriteTextAttr(memory, textAttr, requestName, ySize: 9, style: 0, flags: 1);
        Assert.False(fonts.TryOpen(textAttr, out var opened));
        Assert.Equal(0u, opened);

        // An exact resident name remains selectable, including its explicit
        // path and case, which preserves the guest Exec node comparison.
        Assert.True(memory.TryWriteLong(
            textAttr + (uint)GraphicsLayouts.TextAttrName,
            residentName));
        Assert.True(fonts.TryOpen(textAttr, out opened));
        Assert.Equal(font, opened);
        Assert.True(fonts.TryClose(opened));
    }

    [Fact]
    public void WeighTAMatchAcceptsDiskFontForDesignedRequest()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint requested = 0x100;
        const uint target = 0x120;
        const byte bold = 1 << 1;
        const byte diskFlag = 1 << 1;
        const byte designedFlag = 1 << 6;

        WriteTextAttr(memory, requested, 0, ySize: 10, style: bold, flags: designedFlag);
        WriteTextAttr(memory, target, 0, ySize: 10, style: bold,
            flags: (byte)(diskFlag | designedFlag));

        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var designedWeight));
        Assert.Equal((short)32767, designedWeight);

        Assert.True(memory.TryWriteByte(
            target + (uint)GraphicsLayouts.TextAttrFlags,
            diskFlag));
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var diskWeight));
        Assert.Equal((short)32767, diskWeight);

        // A non-disk constructed candidate remains unsuitable for a designed
        // request, preserving the source-qualified rule.
        Assert.True(memory.TryWriteByte(
            target + (uint)GraphicsLayouts.TextAttrFlags,
            0));
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var constructedWeight));
        Assert.Equal((short)0, constructedWeight);
    }

    [Fact]
    public void OpenFontUsesTaggedDeviceDpiAspectRatioAndRejectsMalformedRequestTags()
    {
        var memory = new FakeMemory(0x4000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint name = 0x100;
        const uint textAttr = 0x200;
        const uint equivalent = 0x300;
        const uint mismatched = 0x400;
        const uint equivalentExtension = 0x500;
        const uint mismatchedExtension = 0x540;
        const uint requestedTags = 0x600;
        const uint equivalentTags = 0x620;
        const uint mismatchedTags = 0x640;

        WriteAscii(memory, name, "dpi.font");
        WriteFontHeader(memory, equivalent, name, ySize: 10, style: 0x80, flags: 0);
        WriteFontHeader(memory, mismatched, name, ySize: 10, style: 0x80, flags: 0);
        Assert.True(memory.TryWriteLong(equivalent + (uint)GraphicsLayouts.TextFontExtension, equivalentExtension));
        Assert.True(memory.TryWriteLong(mismatched + (uint)GraphicsLayouts.TextFontExtension, mismatchedExtension));
        Assert.True(memory.TryWriteLong(equivalentExtension + (uint)GraphicsLayouts.TextFontExtensionTags, equivalentTags));
        Assert.True(memory.TryWriteLong(mismatchedExtension + (uint)GraphicsLayouts.TextFontExtensionTags, mismatchedTags));
        WriteTag(memory, requestedTags, 0x8000_0001, (75u << 16) | 50u);
        WriteTag(memory, requestedTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteTag(memory, equivalentTags, 0x8000_0001, (150u << 16) | 100u);
        WriteTag(memory, equivalentTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteTag(memory, mismatchedTags, 0x8000_0001, (50u << 16) | 50u);
        WriteTag(memory, mismatchedTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.True(fonts.TryAdd(equivalent));
        Assert.True(fonts.TryAdd(mismatched));
        WriteTextAttr(memory, textAttr, name, ySize: 10, style: 0x80, flags: 0);
        Assert.True(memory.TryWriteLong(textAttr + (uint)GraphicsLayouts.TextAttrSize, requestedTags));

        Assert.True(fonts.TryOpen(textAttr, out var opened));
        Assert.Equal(equivalent, opened);
        Assert.True(fonts.TryClose(opened));

        // A tagged request promises a valid suffix.  A truncated tag item is
        // a failed OpenFont request, not an untagged fallback.
        Assert.True(memory.TryWriteLong(textAttr + (uint)GraphicsLayouts.TextAttrSize, 0x3FF8));
        Assert.True(memory.TryWriteLong(0x3FF8, 0x8000_0001));
        Assert.False(fonts.TryOpen(textAttr, out opened));
        Assert.Equal(0u, opened);
    }

    [Fact]
    public void WeighTAMatchUsesGuestAttributesAndRegisterAbiAndFailsClosed()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint requested = 0x100;
        const uint target = 0x120;

        WriteTextAttr(memory, requested, 0, ySize: 10, style: 0x02, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 10, style: 0x02, flags: 0);
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0x1FFC, out var exactWeight));
        Assert.Equal((short)32767, exactWeight);

        var state = new M68kCpuState
        {
            A = { [0] = requested, [1] = target, [2] = 0x1FFC }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(32767u, state.D[0]);

        memory.TryWriteByte(target + (uint)GraphicsLayouts.TextAttrStyle, 0);
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var styleWeight));
        Assert.InRange(styleWeight, 0, (short)32766);

        Assert.False(fonts.TryWeighTAMatch(0x1FFC, target, 0, out var malformedWeight));
        Assert.Equal((short)0, malformedWeight);
        state.A[0] = 0x1FFC;
        state.D[0] = 0xDEADBEEF;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(0xDEADBEEFu, state.D[0]);
    }

    [Fact]
    public void WeighTAMatchAcceptsReadableZeroSizedAttributesAcrossDispatchBoundaries()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint requested = 0x100;
        const uint target = 0x120;

        WriteTextAttr(memory, requested, 0, ySize: 0, style: 0x02, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 0, style: 0x02, flags: 0);

        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var directWeight));
        Assert.Equal((short)32767, directWeight);

        var state = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 223
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(32767u, state.D[0]);
        Assert.Equal(223, state.Cycles);

        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_4401;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
        bus.MapWritableMemory(requested, new byte[GraphicsLayouts.TextAttrSize]);
        bus.MapWritableMemory(target, new byte[GraphicsLayouts.TextAttrSize]);
        bus.WriteWord(requested + (uint)GraphicsLayouts.TextAttrYSize, 0);
        bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrStyle, 0x02, 0);
        bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);
        bus.WriteWord(target + (uint)GraphicsLayouts.TextAttrYSize, 0);
        bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrStyle, 0x02, 0);
        bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        var mapped = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 227
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            mapped));
        Assert.Equal(32767u, mapped.D[0]);
        Assert.Equal(227, mapped.Cycles);
    }

    [Fact]
    public void WeighTAMatchDoesNotReadUnusedNamePointers()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint requested = 0x100;
        const uint target = 0x120;

        WriteTextAttr(backing, requested, 0xDEAD_BEEFu, ySize: 10, style: 0x02, flags: 0);
        WriteTextAttr(backing, target, 0xCAFE_BABEu, ySize: 10, style: 0x02, flags: 0);

        // The autodoc explicitly excludes ta_Name from the metric. A fault
        // on the request's name longword must therefore not change an exact
        // score; OpenFont still uses its separate full-name decoder.
        memory.FailReads(requested + (uint)GraphicsLayouts.TextAttrName, sizeof(uint));

        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var weight));
        Assert.Equal((short)32767, weight);
    }

    [Fact]
    public void WeighTAMatchUsesSignedWordSizeDifferenceLikeKickstart()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint requested = 0x100;
        const uint target = 0x120;

        // WeighTAMatch sign-extends each TextAttr.ta_YSize before taking
        // the difference.  $FFFF and $0001 are therefore two signed WORD
        // units apart, not 65534 unsigned units apart.
        WriteTextAttr(memory, requested, 0, ySize: 0xFFFF, style: 0, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 0x0001, style: 0, flags: 0);

        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var weight));
        Assert.Equal((short)(32767 - 64), weight);
    }

    [Fact]
    public void WeighTAMatchPreservesNativeSignedWordSizePenaltyAcrossDispatchBoundaries()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint requested = 0x100;
        const uint target = 0x120;

        // The native implementation stores the upward size penalty in a
        // signed WORD.  A 256-pixel delta therefore turns 256 << 7 into
        // $8000, and the returned metric is the wrapped WORD $FFFF (-1),
        // rather than a host-int zero/no-match result.
        WriteTextAttr(memory, requested, 0, ySize: 1, style: 0, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 257, style: 0, flags: 0);
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var directWeight));
        Assert.Equal((short)-1, directWeight);

        var state = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 229
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(0xFFFF_FFFFu, state.D[0]);
        Assert.Equal(229, state.Cycles);

        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FA_4401;
        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
        bus.MapWritableMemory(requested, new byte[GraphicsLayouts.TextAttrSize]);
        bus.MapWritableMemory(target, new byte[GraphicsLayouts.TextAttrSize]);
        bus.WriteWord(requested + (uint)GraphicsLayouts.TextAttrYSize, 1);
        bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrStyle, 0, 0);
        bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);
        bus.WriteWord(target + (uint)GraphicsLayouts.TextAttrYSize, 257);
        bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrStyle, 0, 0);
        bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));
        var mapped = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 233
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            mapped));
        Assert.Equal(0xFFFF_FFFFu, mapped.D[0]);
        Assert.Equal(233, mapped.Cycles);
    }

    [Fact]
    public void WeighTAMatchUsesTaggedDeviceDpiAspectRatiosAndValidatesChains()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint requested = 0x100;
        const uint target = 0x120;
        const uint requestedTags = 0x180;
        const uint equivalentTargetTags = 0x1A0;
        const uint mismatchedTargetTags = 0x1C0;

        WriteTextAttr(memory, requested, 0, ySize: 10, style: 0x82, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 10, style: 0x02, flags: 0);
        Assert.True(memory.TryWriteLong(requested + (uint)GraphicsLayouts.TextAttrSize, requestedTags));

        // TA_DeviceDPI is an aspect ratio: 75:50 and 150:100 are equivalent
        // even though their raw values differ.
        WriteTag(memory, requestedTags, 0x8000_0001, (75u << 16) | 50u);
        WriteTag(memory, requestedTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteTag(memory, equivalentTargetTags, 0x8000_0001, (150u << 16) | 100u);
        WriteTag(memory, equivalentTargetTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteTag(memory, mismatchedTargetTags, 0x8000_0001, (50u << 16) | 50u);
        WriteTag(memory, mismatchedTargetTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.True(fonts.TryWeighTAMatch(requested, target, equivalentTargetTags, out var equivalentWeight));
        Assert.Equal((short)32767, equivalentWeight);
        Assert.True(fonts.TryWeighTAMatch(requested, target, mismatchedTargetTags, out var mismatchedWeight));
        Assert.InRange(mismatchedWeight, (short)1, (short)(equivalentWeight - 1));

        // An ordinary TextAttr does not promise a tta_Tags suffix, so the
        // target tag pointer is intentionally not dereferenced in that mode.
        WriteTextAttr(memory, requested, 0, ySize: 10, style: 0x02, flags: 0);
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0x1FFC, out var untaggedWeight));
        Assert.Equal((short)32767, untaggedWeight);

        // A tagged request does promise the suffix; a truncated list must
        // fail closed rather than return a score based on partial input.
        WriteTextAttr(memory, requested, 0, ySize: 10, style: 0x82, flags: 0);
        Assert.True(memory.TryWriteLong(requested + (uint)GraphicsLayouts.TextAttrSize, 0x1FFCu));
        Assert.True(memory.TryWriteLong(0x1FFCu, 0x8000_0001u));
        Assert.False(fonts.TryWeighTAMatch(requested, target, equivalentTargetTags, out var malformedWeight));
        Assert.Equal((short)0, malformedWeight);
    }

    [Fact]
    public void TaggedWeighTAMatchJumpsOverLargeTagSkip()
    {
        var memory = new FakeMemory(0x10000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint requested = 0x100;
        const uint target = 0x120;
        const uint requestedTags = 0x180;
        const uint targetTags = 0x200;
        const uint targetDeviceDpi = targetTags + 8u + (4096u * 8u);

        WriteTextAttr(memory, requested, 0, ySize: 10, style: 0x82, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 10, style: 0x02, flags: 0);
        Assert.True(memory.TryWriteLong(
            requested + (uint)GraphicsLayouts.TextAttrSize,
            requestedTags));
        WriteTag(memory, requestedTags, 0x8000_0001, (75u << 16) | 50u);
        WriteTag(memory, requestedTags + 8u, GraphicsRastPortAttributeOperations.TagDone, 0);

        // TAG_SKIP counts complete following TagItems. The target DPI item
        // is intentionally beyond the bounded ordinary-item budget; the
        // decoder must jump to it instead of consuming 4096 loop iterations.
        WriteTag(memory, targetTags, GraphicsRastPortAttributeOperations.TagSkip, 4096);
        WriteTag(memory, targetDeviceDpi, 0x8000_0001, (150u << 16) | 100u);
        WriteTag(memory, targetDeviceDpi + 8u, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var untaggedTargetWeight));
        Assert.Equal((short)32767, untaggedTargetWeight);
        Assert.True(fonts.TryWeighTAMatch(requested, target, targetTags, out var weight));
        Assert.Equal((short)32767, weight);

        var state = new M68kCpuState
        {
            A = { [0] = requested, [1] = target, [2] = targetTags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 293
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(32767u, state.D[0]);
        Assert.Equal(293, state.Cycles);
    }

    [Fact]
    public void TaggedWeighTAMatchAcceptsTheFinalGuestTagItemAndRejectsImplicitWrap()
    {
        var memory = new WrappingMemory();
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint requested = 0x800;
        const uint target = 0x820;
        const uint tags = 0xFFFF_FFF8u;

        memory.WriteLong(requested + (uint)GraphicsLayouts.TextAttrName, 0);
        memory.WriteWord(requested + (uint)GraphicsLayouts.TextAttrYSize, 10);
        memory.WriteByte(requested + (uint)GraphicsLayouts.TextAttrStyle, 0x82);
        memory.WriteByte(requested + (uint)GraphicsLayouts.TextAttrFlags, 0);
        memory.WriteLong(requested + (uint)GraphicsLayouts.TextAttrSize, tags);
        memory.WriteLong(target + (uint)GraphicsLayouts.TextAttrName, 0);
        memory.WriteWord(target + (uint)GraphicsLayouts.TextAttrYSize, 10);
        memory.WriteByte(target + (uint)GraphicsLayouts.TextAttrStyle, 0x02);
        memory.WriteByte(target + (uint)GraphicsLayouts.TextAttrFlags, 0);

        // A terminal TagItem exactly occupies FFFFFFF8..FFFFFFFF.  The
        // tagged request is readable and must score normally.
        memory.WriteLong(tags, GraphicsRastPortAttributeOperations.TagDone);
        memory.WriteLong(tags + 4u, 0);
        Assert.True(fonts.TryWeighTAMatch(requested, target, 0, out var terminalWeight));
        Assert.Equal((short)32767, terminalWeight);

        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var validState = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 271
        };
        Assert.True(adapter.TryInvoke(validState, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(32767u, validState.D[0]);
        Assert.Equal(271, validState.Cycles);

        // A non-terminal item at the same address cannot wrap its implicit
        // continuation through low memory, even when the host map exposes
        // every wrapped byte.
        memory.WriteLong(tags, 0x8000_0001u);
        memory.WriteLong(tags + 4u, (75u << 16) | 50u);
        Assert.False(fonts.TryWeighTAMatch(requested, target, 0, out var wrappedWeight));
        Assert.Equal((short)0, wrappedWeight);

        memory.WriteLong(requested + (uint)GraphicsLayouts.TextAttrSize, tags);
        var malformedState = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 277
        };
        Assert.False(adapter.TryInvoke(malformedState, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(0x1357_9BDFu, malformedState.D[0]);
        Assert.Equal(277, malformedState.Cycles);
    }

    [Fact]
    public void WeighTAMatchTaggedRequestValidatesSuffixWhenTargetTagsAreAbsent()
    {
        var memory = new FakeMemory(0x2000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint requested = 0x100;
        const uint target = 0x120;
        const uint malformedTags = 0x1FF0;

        WriteTextAttr(memory, requested, 0, ySize: 10, style: 0x82, flags: 0);
        WriteTextAttr(memory, target, 0, ySize: 10, style: 0x02, flags: 0);
        Assert.True(memory.TryWriteLong(
            requested + (uint)GraphicsLayouts.TextAttrSize,
            malformedTags));
        // A malformed TAG_MORE continuation is readable, but its odd target
        // cannot be a guest TagItem list. A tagged request must not become a
        // valid untagged score merely because the target has no tag list
        // (A2 == 0).
        Assert.True(memory.TryWriteLong(malformedTags, 2u));
        Assert.True(memory.TryWriteLong(malformedTags + 4u, malformedTags + 1u));

        Assert.False(fonts.TryWeighTAMatch(requested, target, 0, out var directWeight));
        Assert.Equal((short)0, directWeight);

        var state = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 719
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WeighTAMatch));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(719, state.Cycles);
    }

    [Fact]
    public void WeighTAMatchMalformedGuestAttributesRemainAvailableToNativeOverlay()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint requested = 0x100;
        const uint target = 0x120;
        const uint malformedTags = 0x1FF0;
        const uint nativeTarget = 0x00FA_4401;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
                nativeTarget);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(graphicsBase, new byte[0xA0]);
            bus.MapWritableMemory(requested, new byte[0x20]);
            bus.MapWritableMemory(target, new byte[0x20]);
            bus.MapWritableMemory(malformedTags, new byte[8]);
            bus.WriteLong(requested + (uint)GraphicsLayouts.TextAttrName, 0);
            bus.WriteWord(requested + (uint)GraphicsLayouts.TextAttrYSize, 10);
            bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrStyle, 0x02, 0);
            bus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);
            bus.WriteLong(target + (uint)GraphicsLayouts.TextAttrName, 0);
            bus.WriteWord(target + (uint)GraphicsLayouts.TextAttrYSize, 10);
            bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrStyle, 0x02, 0);
            bus.WriteByte(target + (uint)GraphicsLayouts.TextAttrFlags, 0, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directValid = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 607
        };
        var overlayValid = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 607
        };
        direct.Invoke(directValid, (int)GraphicsLvo.WeighTAMatch);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            overlayValid));
        Assert.Equal((uint)32767, directValid.D[0]);
        Assert.Equal(directValid.D[0], overlayValid.D[0]);
        Assert.Equal(directValid.Cycles, overlayValid.Cycles);

        overlayBus.WriteByte(requested + (uint)GraphicsLayouts.TextAttrStyle, 0x82, 0);
        overlayBus.WriteLong(
            requested + (uint)GraphicsLayouts.TextAttrSize,
            malformedTags);
        overlayBus.WriteLong(malformedTags, 2u);
        overlayBus.WriteLong(malformedTags + 4u, malformedTags + 1u);
        var taggedMalformed = new M68kCpuState
        {
            A = { [0] = requested, [1] = target },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 611,
            ProgramCounter = 0x0012_3344
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            taggedMalformed));
        Assert.Equal(nativeTarget, taggedMalformed.ProgramCounter);
        Assert.Equal(0x2468_ACEEu, taggedMalformed.D[0]);
        Assert.Equal(611, taggedMalformed.Cycles);

        var malformed = new M68kCpuState
        {
            // Use an odd address so this remains an address-error/provider
            // envelope independent of the host bus's default RAM mapping.
            A = { [0] = 0x1FFD, [1] = target },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 613,
            ProgramCounter = 0x0012_4455
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.WeighTAMatch)),
            malformed));
        Assert.Equal(nativeTarget, malformed.ProgramCounter);
        Assert.Equal(0x1357_9BDFu, malformed.D[0]);
        Assert.Equal(613, malformed.Cycles);
    }

    [Fact]
    public void FontLifecycleFailsClosedForMalformedRequestsAccessorOverflowAndAllocationFailure()
    {
        var memory = new FakeMemory(0x4000);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x400;
        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "safe.font");

        var fonts = new GraphicsMemoryFontBackend(memory);
        Assert.True(fonts.TryAdd(font));
        WriteTextAttr(memory, textAttr, 0x4000, ySize: 9, style: 0, flags: 0);
        Assert.False(fonts.TryOpen(textAttr, out var malformedOpen));
        Assert.Equal(0u, malformedOpen);
        Assert.Equal((ushort)0, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));

        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontAccessors,
            ushort.MaxValue));
        WriteTextAttr(memory, textAttr, name, ySize: 9, style: 0, flags: 0);
        Assert.False(fonts.TryOpen(textAttr, out var overflowOpen));
        Assert.Equal(0u, overflowOpen);
        Assert.Equal(ushort.MaxValue, ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));

        var failingAllocator = new BitmapAllocator { FailAfterAllocations = 0 };
        var failingFonts = new GraphicsMemoryFontBackend(memory, failingAllocator);
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontAccessors,
            0));
        Assert.False(failingFonts.TryExtend(font, 0x900));
        Assert.Equal(0u, ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Empty(failingAllocator.Freed);
    }

    [Fact]
    public void FontLifecycleRejectsCharLocFontWithoutReadableStrikeStorage()
    {
        var memory = new FakeMemory(0x4000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint name = 0x500;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "broken.font");

        // CharLoc is populated, but CharData/Modulo describe no readable
        // strike.  The node must not become selectable merely because its
        // proportional location table is non-null.
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            0));

        Assert.False(fonts.HasMetrics(font));
        Assert.False(fonts.TryAdd(font));
    }

    [Fact]
    public void FontLifecycleRejectsStrikeStorageOutsideGuestMemory()
    {
        var memory = new FakeMemory(0x4000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint name = 0x500;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "unmapped-strike.font");

        // Keep the TextFont header and CharLoc table readable, but place the
        // packed strike row beyond the guest memory envelope.  Pointer
        // non-nullness alone must not make this malformed font selectable.
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0x4000));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            1));
        Assert.True(memory.TryWriteWord(0xA00, 0));
        Assert.True(memory.TryWriteWord(0xA02, 8));

        Assert.False(fonts.HasMetrics(font));
        Assert.False(fonts.TryAdd(font));
    }

    [Fact]
    public void FontLifecycleRejectsStrikeWhoseFinalRowLeavesGuestMemory()
    {
        var memory = new FakeMemory(0x4000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint name = 0x500;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "last-row-unmapped.font");

        // The first strike byte remains readable, but the final row implied
        // by tf_YSize/tf_Modulo crosses the guest-memory boundary. Admission
        // must fail before AddFont/OpenFont can publish this node.
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0x3FFC));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            1));

        Assert.False(fonts.HasMetrics(font));
        Assert.False(fonts.TryAdd(font));
    }

    [Fact]
    public void FontLifecycleRejectsProportionalTableMissingItsDefaultEntry()
    {
        var memory = new FakeMemory(0x4000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint font = 0x600;
        const uint name = 0x500;

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "truncated-table.font");

        // LoChar..HiChar is the normal 96-byte range, plus one default glyph
        // entry. The first CharLoc word is readable, but the declared table
        // crosses the guest-memory boundary before that final entry.
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharLoc,
            0x3F00));

        Assert.False(fonts.HasMetrics(font));
        Assert.False(fonts.TryAdd(font));
    }

    [Fact]
    public void GuestGfxBaseFontListPublishesDefaultLinksAndRemovedState()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint font = 0x600;
        const uint name = 0x500;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fonts = new GraphicsMemoryFontBackend(memory, defaultFont: () => font, fontList: list);
        WriteFontHeader(memory, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(memory, name, "topaz.font");

        Assert.True(list.Initialize(0));
        Assert.True(list.SetDefaultFont(font));
        Assert.Equal(font, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont));
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));

        Assert.True(fonts.TryAdd(font));
        Assert.False(fonts.TryAdd(font));
        Assert.Equal(GraphicsLayouts.TextFontNodeTypeFont,
            ReadByte(memory, font + (uint)GraphicsLayouts.TextFontNodeType));
        Assert.Equal(font, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, font));
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFonts,
            ReadLong(memory, font + 4));
        Assert.Equal((byte)1, (byte)(ReadByte(memory, font + (uint)GraphicsLayouts.TextFontFlags) & 0x7F));

        Assert.True(fonts.TryRemove(font));
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFonts,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred));
        Assert.Equal(0u, ReadLong(memory, font));
        Assert.Equal(0u, ReadLong(memory, font + 4));
        Assert.Equal((byte)0x80, (byte)(ReadByte(memory, font + (uint)GraphicsLayouts.TextFontFlags) & 0x80));
        Assert.False(fonts.TryRemove(font));
    }

    [Fact]
    public void GuestGfxBaseFontListEnumeratesResidentNodesAndRejectsCycles()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint firstFont = 0x600;
        const uint secondFont = 0x700;
        const uint firstName = 0x500;
        const uint secondName = 0x580;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);

        WriteFontHeader(memory, firstFont, firstName, ySize: 8, style: 0, flags: 1);
        WriteFontHeader(memory, secondFont, secondName, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, firstName, "resident-one.font");
        WriteAscii(memory, secondName, "resident-two.font");
        Assert.True(list.Initialize(0));
        Assert.True(fonts.TryAdd(firstFont));
        Assert.True(fonts.TryAdd(secondFont));
        Assert.True(list.SetDefaultFont(firstFont));

        Assert.True(list.TryEnumerate(out var residentFonts));
        Assert.Equal(new[] { firstFont, secondFont }, residentFonts);
        Assert.True(list.TryGetDefaultFont(out var defaultFont));
        Assert.Equal(firstFont, defaultFont);

        // A cycle must never be handed to OpenFont's matcher.  The bounded
        // list reader declines before returning a partial candidate array.
        Assert.True(memory.TryWriteLong(secondFont, firstFont));
        Assert.False(list.TryEnumerate(out _));
    }

    [Fact]
    public void OpenFontRejectsResidentNodeWhoseStrikeBecomesMalformed()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint font = 0x600;
        const uint name = 0x500;
        const uint textAttr = 0x400;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);

        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "resident.font");
        Assert.True(list.Initialize(0));
        Assert.True(fonts.TryAdd(font));
        Assert.True(list.SetDefaultFont(font));

        // The node is already resident, so the list links remain structurally
        // valid even after an external/native owner corrupts the strike
        // envelope.  OpenFont must not publish it as selectable and leave its
        // accessor count untouched.
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            0));
        WriteTextAttr(memory, textAttr, name, ySize: 9, style: 0, flags: 0);

        Assert.False(fonts.TryOpen(textAttr, out var opened));
        Assert.Equal(0u, opened);
        Assert.Equal((ushort)0,
            ReadWord(memory, font + (uint)GraphicsLayouts.TextFontAccessors));
    }

    [Fact]
    public void GuestGfxBaseFontListRebindsLifecycleWritesToTheSelectedNativeBase()
    {
        var memory = new FakeMemory(0x4000);
        const uint hostBase = 0x1000;
        const uint nativeBase = 0x1800;
        const uint font = 0x600;
        const uint name = 0x500;
        var list = new GraphicsGuestFontListBackend(memory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(memory, nativeBase);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);
        WriteFontHeader(memory, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(memory, name, "rebind.font");

        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));
        Assert.True(list.TryRebind(nativeBase));
        Assert.Equal(nativeBase, list.BaseAddress);

        Assert.True(fonts.TryAdd(font));
        Assert.Equal(font, ReadLong(memory, nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, font));
        Assert.Equal(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));

        Assert.True(fonts.TryRemove(font));
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            ReadLong(memory, nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.True(list.TryRebind(hostBase));
        Assert.Equal(hostBase, list.BaseAddress);
    }

    [Fact]
    public void NativeOverlayRebindsGuestFontListAndRestoresItOnDispose()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        bus.MapWritableMemory(imageBase, new byte[0x2000]);
        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));

        using var services = CreateHostGraphicsServices(memory, fontList: list);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        Assert.Equal(nativeBase, list.BaseAddress);
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));

        services.Dispose();
        Assert.Equal(hostBase, list.BaseAddress);
    }

    [Fact]
    public void NativeOverlayDisposeRetainsPendingSidecarHandoffUntilGuestPointerCanBeCleared()
    {
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint database = 0x00FB_0000;
        var bus = new AmigaBus();
        bus.MapWritableMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(nativeBase, new byte[0x300]);
        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        Assert.True(nativeSetup.Initialize(0));
        var monitorList = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0,
            0);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0,
            0);

        var allocations = 0;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            memory,
            allocateMemory: (bytes, _) =>
            {
                Assert.Equal(GraphicsDisplayDatabase.NativeDatabaseSize, bytes);
                allocations++;
                bus.MapWritableMemory(database, new byte[bytes]);
                return database;
            },
            freeMemory: (_, _) => frees++);

        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        var field = nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        Assert.Equal(database, bus.ReadLong(field));
        Assert.Equal(1, allocations);

        // A provider/image handoff may leave the public APTR readable but
        // temporarily refuse writes. Dispose must not discard the native
        // binding or free the still-reachable private database in that state.
        bus.MapReadOnlyMemory(field, new byte[]
        {
            unchecked((byte)(database >> 24)),
            unchecked((byte)(database >> 16)),
            unchecked((byte)(database >> 8)),
            unchecked((byte)database)
        });
        services.Dispose();
        Assert.Equal(database, bus.ReadLong(field));
        Assert.Equal(0, frees);

        // The guest boundary becomes writable again. A second teardown pass
        // must complete the retained release, rebind, and free exactly once.
        bus.MapWritableMemory(field, new byte[]
        {
            unchecked((byte)(database >> 24)),
            unchecked((byte)(database >> 16)),
            unchecked((byte)(database >> 8)),
            unchecked((byte)database)
        });
        services.Dispose();
        Assert.Equal(0u, bus.ReadLong(field));
        Assert.Equal(1, frees);
    }

    [Fact]
    public void NativeOverlayRoutesFontListMutationToReboundNativeBase()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint font = 0x00FB_0000;
        const uint name = 0x00FB_0100;
        const uint charData = 0x00FB_0200;

        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        // The native GfxBase positive image is writable guest state.  Map it
        // after the ROM image so it wins only for the positive data range;
        // the negative vector slots remain backed by the read-only image.
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(font, new byte[0x80]);
        bus.MapWritableMemory(name, new byte[0x20]);
        bus.MapWritableMemory(charData, new byte[0x100]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        bus.WriteByte(name, (byte)'n', 0);
        bus.WriteByte(name + 1, (byte)'a', 0);
        bus.WriteByte(name + 2, (byte)'t', 0);
        bus.WriteByte(name + 3, (byte)'i', 0);
        bus.WriteByte(name + 4, (byte)'v', 0);
        bus.WriteByte(name + 5, (byte)'e', 0);
        bus.WriteByte(name + 6, (byte)'.', 0);
        bus.WriteByte(name + 7, (byte)'f', 0);
        bus.WriteByte(name + 8, (byte)'o', 0);
        bus.WriteByte(name + 9, (byte)'n', 0);
        bus.WriteByte(name + 10, (byte)'t', 0);
        bus.WriteByte(name + 11, 0, 0);

        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));

        using var services = CreateHostGraphicsServices(memory, fontList: list);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        Assert.Equal(nativeBase, list.BaseAddress);
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.True(new GraphicsMemoryFontBackend(guestMemory).HasMetrics(font));

        var add = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 211
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddFont)),
            add));
        Assert.Equal(0u, add.D[0]);
        Assert.Equal(211, add.Cycles);
        Assert.Equal(font,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(font));
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFonts,
            bus.ReadLong(font + 4));
        Assert.Equal(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));

        var remove = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 223
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemFont)),
            remove));
        Assert.Equal(0u, remove.D[0]);
        Assert.Equal(223, remove.Cycles);
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal((byte)0x80,
            (byte)(bus.ReadByte(font + (uint)GraphicsLayouts.TextFontFlags) & 0x80));
    }

    [Fact]
    public void NativeOverlayRemFontPreflightsGuestListPublicationBeforeMutation()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        const uint gfxBase = 0x1000;
        const uint font = 0x600;
        const uint name = 0x500;

        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        Assert.True(list.Initialize(0));
        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "native-rem.font");
        var publisher = new GraphicsMemoryFontBackend(memory, allocator, fontList: list);
        Assert.True(publisher.TryAdd(font));

        var writesBeforeDecline = memory.WriteCount;
        var originalHead = ReadLong(
            memory,
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead);
        var originalTailPred = ReadLong(
            memory,
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred);
        var originalFontLinks = ReadLong(memory, font);
        var originalFontPred = ReadLong(memory, font + 4);
        var originalFlags = ReadByte(
            memory,
            font + (uint)GraphicsLayouts.TextFontFlags);

        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            fontList: list,
            isWritableMemoryRange: (address, byteCount) =>
                address != font + (uint)GraphicsLayouts.TextFontFlags ||
                byteCount != sizeof(byte));
        var state = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 431,
            ProgramCounter = 0x0012_3A91
        };

        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.RemFont,
            nativeOverlay: true));
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(431, state.Cycles);
        Assert.Equal(0x0012_3A91u, state.ProgramCounter);
        Assert.Equal(writesBeforeDecline, memory.WriteCount);
        Assert.Equal(
            originalHead,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(
            originalTailPred,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred));
        Assert.Equal(originalFontLinks, ReadLong(memory, font));
        Assert.Equal(originalFontPred, ReadLong(memory, font + 4));
        Assert.Equal(
            originalFlags,
            ReadByte(memory, font + (uint)GraphicsLayouts.TextFontFlags));
    }

