    [Fact]
    public void NativeOverlaySetRPAttrsResolvesNullFontFromReboundGfxBase()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint font = 0x00FB_0000;
        const uint name = 0x00FB_0100;
        const uint charData = 0x00FB_0200;
        const uint rastPort = 0x00FB_0400;
        const uint tags = 0x00FB_0500;

        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(font, new byte[0x80]);
        bus.MapWritableMemory(name, new byte[0x20]);
        bus.MapWritableMemory(charData, new byte[0x100]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(tags, new byte[0x10]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        foreach (var (index, value) in "default.font".Select((value, index) => (index, value)))
            bus.WriteByte(name + (uint)index, (byte)value, 0);
        bus.WriteByte(name + (uint)"default.font".Length, 0, 0);

        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));
        Assert.True(nativeSetup.SetDefaultFont(font));

        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagFont);
        bus.WriteLong(tags + 4, 0);
        bus.WriteLong(tags + 8, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12, 0);

        using var services = CreateHostGraphicsServices(memory, fontList: list);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        Assert.Equal(nativeBase, list.BaseAddress);

        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 181
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.SetRPAttrsA)),
            state));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(181, state.Cycles);
        Assert.Equal(
            font,
            bus.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal(
            (ushort)8,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(
            (ushort)8,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal(
            (ushort)7,
            bus.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void NativeOverlayOpensAndClosesResidentFontFromReboundList()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint font = 0x00FB_0000;
        const uint name = 0x00FB_0100;
        const uint charData = 0x00FB_0200;
        const uint textAttr = 0x00FB_0400;
        const uint nativeOpenTarget = 0x00FC_1303;

        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            nativeOpenTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(font, new byte[0x80]);
        bus.MapWritableMemory(name, new byte[0x40]);
        bus.MapWritableMemory(charData, new byte[0x100]);
        bus.MapWritableMemory(textAttr, new byte[GraphicsLayouts.TextAttrSize]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        // This resident node is deliberately non-ROM: native CloseFont must
        // remove it from the rebound TextFonts list when the final accessor
        // closes.
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBoldSmear, 1);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);
        for (var index = 0; index < "resident.font".Length; index++)
            bus.WriteByte(name + (uint)index, (byte)"resident.font"[index], 0);
        bus.WriteByte(name + (uint)"resident.font".Length, 0, 0);
        bus.WriteLong(textAttr + (uint)GraphicsLayouts.TextAttrName, name);
        // The native request decoder accepts zero height; the selected
        // resident TextFont still carries its valid nonzero strike.
        bus.WriteWord(textAttr + (uint)GraphicsLayouts.TextAttrYSize, 0);
        bus.WriteByte(textAttr + (uint)GraphicsLayouts.TextAttrStyle, 0, 0);
        bus.WriteByte(textAttr + (uint)GraphicsLayouts.TextAttrFlags, 1, 0);

        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        var nativePublisher = new GraphicsMemoryFontBackend(guestMemory, fontList: nativeSetup);
        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));
        Assert.True(nativePublisher.TryAdd(font));
        Assert.True(nativeSetup.SetDefaultFont(font));

        using var services = CreateHostGraphicsServices(memory, fontList: list);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var open = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 233
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            open));
        Assert.Equal(font, open.D[0]);
        Assert.Equal((byte)0,
            bus.ReadByte(font + (uint)GraphicsLayouts.TextFontFlags));
        Assert.Equal((ushort)1,
            bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.True(list.TryEnumerate(out var residentBeforeClose));
        Assert.Contains(font, residentBeforeClose);
        Assert.Equal(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(hostBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));

        var close = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 239
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            close));
        Assert.Equal(0u, close.D[0]);
        Assert.Equal((ushort)0,
            bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));

        // Once the resident links become cyclic, the mapped OpenFont slot
        // must return to native Kickstart/provider ownership instead of
        // scoring a partial candidate list.
        bus.WriteLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead, font);
        bus.WriteLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred, font);
        bus.WriteLong(font, font);
        bus.WriteLong(font + 4u, font);
        var malformed = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0x0BAD_F00Du },
            Cycles = 241,
            ProgramCounter = 0x0012_3809
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            malformed));
        Assert.Equal(nativeOpenTarget, malformed.ProgramCounter);
        Assert.Equal(0x0BAD_F00Du, malformed.D[0]);
        Assert.Equal(241, malformed.Cycles);
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyResidentFontBeforeAccessorPublication()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint font = 0x00FB_0000;
        const uint name = 0x00FB_0100;
        const uint charData = 0x00FB_0200;
        const uint textAttr = 0x00FB_0400;
        const uint nativeTarget = 0x00FC_1303;

        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(font, new byte[0x80]);
        bus.MapWritableMemory(name, new byte[0x40]);
        bus.MapWritableMemory(charData, new byte[0x100]);
        bus.MapWritableMemory(textAttr, new byte[GraphicsLayouts.TextAttrSize]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 0, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBoldSmear, 1);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);
        for (var index = 0; index < "resident.font".Length; index++)
            bus.WriteByte(name + (uint)index, (byte)"resident.font"[index], 0);
        bus.WriteByte(name + (uint)"resident.font".Length, 0, 0);
        bus.WriteLong(textAttr + (uint)GraphicsLayouts.TextAttrName, name);
        bus.WriteWord(textAttr + (uint)GraphicsLayouts.TextAttrYSize, 0);
        bus.WriteByte(textAttr + (uint)GraphicsLayouts.TextAttrStyle, 0, 0);
        bus.WriteByte(textAttr + (uint)GraphicsLayouts.TextAttrFlags, 1, 0);

        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var hostList = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeList = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        var nativePublisher = new GraphicsMemoryFontBackend(guestMemory, fontList: nativeList);
        Assert.True(hostList.Initialize(0));
        Assert.True(nativeList.Initialize(0));
        Assert.True(nativePublisher.TryAdd(font));
        Assert.True(nativeList.SetDefaultFont(font));

        using var services = CreateHostGraphicsServices(memory, fontList: hostList);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var originalFont = Enumerable.Range(0, 0x80)
            .Select(offset => bus.ReadByte(font + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(font, originalFont);

        var state = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 251,
            ProgramCounter = 0x0012_3811
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(251, state.Cycles);
        Assert.Equal(
            (ushort)0,
            bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.True(hostList.TryEnumerate(out var resident));
        Assert.Contains(font, resident);
    }

    [Fact]
    public void NativeOverlayExtendsAndStripsResidentFontWithReboundList()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint font = 0x00FB_0000;
        const uint name = 0x00FB_0100;
        const uint charData = 0x00FB_0200;
        const uint extension = 0x00FC_0000;
        const uint extendTarget = 0x00FC_1307;
        const uint stripTarget = 0x00FC_130B;

        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ExtendFont)),
            extendTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.StripFont)),
            stripTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(font, new byte[0x80]);
        bus.MapWritableMemory(name, new byte[0x40]);
        bus.MapWritableMemory(charData, new byte[0x100]);
        bus.MapWritableMemory(extension, new byte[0x40]);

        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1, 0);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBoldSmear, 1);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 0x80);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);
        for (var index = 0; index < "resident.font".Length; index++)
            bus.WriteByte(name + (uint)index, (byte)"resident.font"[index], 0);
        bus.WriteByte(name + (uint)"resident.font".Length, 0, 0);

        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        var nativePublisher = new GraphicsMemoryFontBackend(guestMemory, fontList: nativeSetup);
        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));
        Assert.True(nativePublisher.TryAdd(font));
        Assert.True(nativeSetup.SetDefaultFont(font));

        var allocations = 0;
        var frees = 0;
        using var services = CreateHostGraphicsServices(
            memory,
            allocateMemory: (_, _) =>
            {
                allocations++;
                return extension;
            },
            freeMemory: (_, _) => frees++,
            fontList: list);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var extend = new M68kCpuState
        {
            A = { [0] = font },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 251
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ExtendFont)),
            extend));
        Assert.Equal(1u, extend.D[0]);
        Assert.Equal(251, extend.Cycles);
        Assert.Equal(1, allocations);
        Assert.Equal(extension,
            bus.ReadLong(font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x80,
            bus.ReadByte(font + (uint)GraphicsLayouts.TextFontStyle));

        var strip = new M68kCpuState
        {
            A = { [0] = font },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 257
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.StripFont)),
            strip));
        Assert.Equal(0u, strip.D[0]);
        Assert.Equal(257, strip.Cycles);
        Assert.Equal(1, frees);
        Assert.Equal(0u,
            bus.ReadLong(font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0,
            bus.ReadByte(font + (uint)GraphicsLayouts.TextFontStyle));

        // A cyclic native list must never let the mapped extension vectors
        // allocate or detach a host-owned extension.  The original target
        // remains the owner of the malformed call.
        bus.WriteLong(font, font);
        var malformed = new M68kCpuState
        {
            A = { [0] = font },
            D = { [0] = 0x0BAD_F00Du },
            Cycles = 263,
            ProgramCounter = 0x0012_380D
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ExtendFont)),
            malformed));
        Assert.Equal(extendTarget, malformed.ProgramCounter);
        Assert.Equal(0x0BAD_F00Du, malformed.D[0]);
        Assert.Equal(263, malformed.Cycles);
        Assert.Equal(1, allocations);
        Assert.Equal(1, frees);
    }

    [Fact]
    public void NativeOverlayLeavesFontListVectorsNativeWithoutGuestListBackend()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint target = 0x00FC_1203;
        const uint removeTarget = 0x00FC_1207;
        const uint openTarget = 0x00FC_120B;
        const uint closeTarget = 0x00FC_120F;
        const uint extendTarget = 0x00FC_1213;
        const uint stripTarget = 0x00FC_1217;
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddFont)),
            target);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemFont)),
            removeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            openTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            closeTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ExtendFont)),
            extendTarget);
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.StripFont)),
            stripTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        // The native overlay has no rebound guest TextFonts list, but the
        // NULL-handle form is still a complete CloseFont no-op and must not
        // be tail-chained merely because the non-NULL lifecycle owner is
        // unavailable.
        var closeNull = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 223,
            ProgramCounter = 0x0012_3804
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            closeNull));
        Assert.Equal(0u, closeNull.D[0]);
        Assert.Equal(223, closeNull.Cycles);
        Assert.Equal(0x0012_3804u, closeNull.ProgramCounter);

        var stripNull = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0x2468_ACF0u },
            Cycles = 225,
            ProgramCounter = 0x0012_3804
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.StripFont)),
            stripNull));
        Assert.Equal(0u, stripNull.D[0]);
        Assert.Equal(225, stripNull.Cycles);
        Assert.Equal(0x0012_3804u, stripNull.ProgramCounter);

        var state = new M68kCpuState
        {
            A = { [1] = 0x00F0_1000u },
            D = { [0] = 0x1234_5678u },
            Cycles = 227,
            ProgramCounter = 0x0012_3805
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.AddFont)),
            state));
        Assert.Equal(target, state.ProgramCounter);
        Assert.Equal(0x1234_5678u, state.D[0]);
        Assert.Equal(227, state.Cycles);

        var remove = new M68kCpuState
        {
            A = { [1] = 0x00F0_1000u },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 229,
            ProgramCounter = 0x0012_3806
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemFont)),
            remove));
        Assert.Equal(removeTarget, remove.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, remove.D[0]);
        Assert.Equal(229, remove.Cycles);

        var open = new M68kCpuState
        {
            A = { [0] = 0x00F0_2000u },
            D = { [0] = 0x0BAD_F00Du },
            Cycles = 231,
            ProgramCounter = 0x0012_3807
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            open));
        Assert.Equal(openTarget, open.ProgramCounter);
        Assert.Equal(0x0BAD_F00Du, open.D[0]);
        Assert.Equal(231, open.Cycles);

        var close = new M68kCpuState
        {
            A = { [1] = 0x00F0_3000u },
            D = { [0] = 0x0D15_EA5Eu },
            Cycles = 233,
            ProgramCounter = 0x0012_3808
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            close));
        Assert.Equal(closeTarget, close.ProgramCounter);
        Assert.Equal(0x0D15_EA5Eu, close.D[0]);
        Assert.Equal(233, close.Cycles);

        var extend = new M68kCpuState
        {
            A = { [0] = 0x00F0_4000u },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 235,
            ProgramCounter = 0x0012_3809
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.ExtendFont)),
            extend));
        Assert.Equal(extendTarget, extend.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, extend.D[0]);
        Assert.Equal(235, extend.Cycles);

        var strip = new M68kCpuState
        {
            A = { [0] = 0x00F0_5000u },
            D = { [0] = 0x0D15_EA5Eu },
            Cycles = 237,
            ProgramCounter = 0x0012_380A
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.StripFont)),
            strip));
        Assert.Equal(stripTarget, strip.ProgramCounter);
        Assert.Equal(0x0D15_EA5Eu, strip.D[0]);
        Assert.Equal(237, strip.Cycles);
    }

    [Fact]
    public void GuestGfxBaseFontListRestoresInitializationWhenDefaultPublicationFailsLate()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        const uint gfxBase = 0x1000;
        for (var offset = 0; offset < 0x12; offset++)
            Assert.True(backing.TryWriteByte(gfxBase + 0x8C + (uint)offset, (byte)(0x30 + offset)));

        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        // Header links/type/pad consume fourteen bytes; fail the second
        // byte of the four-byte DefaultFont publication.
        memory.FailOnNextByteWrite(16);
        Assert.False(list.Initialize(0x600));
        for (var offset = 0; offset < 0x12; offset++)
            Assert.Equal((byte)(0x30 + offset), ReadByte(backing, gfxBase + 0x8C + (uint)offset));
    }

    [Fact]
    public void GuestGfxBaseFontListRestoresDefaultFontWhenTheLongWriteFailsLate()
    {
        var backing = new FakeMemory(0x2000);
        var setup = new GraphicsGuestFontListBackend(backing, 0x1000);
        Assert.True(setup.Initialize(0x500));
        var memory = new FailingByteWriteMemory(backing);
        var list = new GraphicsGuestFontListBackend(memory, 0x1000);
        memory.FailOnNextByteWrite(2);
        Assert.False(list.SetDefaultFont(0x600));
        Assert.Equal(0x500u, ReadLong(backing, 0x109A));
    }

    [Fact]
    public void GuestGfxBaseFontListRejectsInteriorCycleBeforeAddOrRemoveMutation()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint firstFont = 0x600;
        const uint secondFont = 0x700;
        const uint newFont = 0x800;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);
        Assert.True(list.Initialize(0));

        var listAddress = gfxBase + (uint)GraphicsLayouts.GfxBaseTextFonts;
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead,
            firstFont));
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred,
            secondFont));
        Assert.True(memory.TryWriteLong(firstFont, secondFont));
        Assert.True(memory.TryWriteLong(firstFont + 4u, listAddress));
        // The interior cycle is locally linked but never reaches the tail.
        Assert.True(memory.TryWriteLong(secondFont, firstFont));
        Assert.True(memory.TryWriteLong(secondFont + 4u, firstFont));
        Assert.True(memory.TryWriteLong(newFont, 0));
        Assert.True(memory.TryWriteLong(newFont + 4u, 0));

        Assert.False(list.TryEnumerate(out _));
        Assert.False(fonts.TryAdd(newFont));
        Assert.False(fonts.TryRemove(firstFont));
        Assert.Equal(firstFont, ReadLong(
            memory,
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(secondFont, ReadLong(
            memory,
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred));
        Assert.Equal(secondFont, ReadLong(memory, firstFont));
        Assert.Equal(firstFont, ReadLong(memory, secondFont));
        Assert.Equal(0u, ReadLong(memory, newFont));
        Assert.Equal(0u, ReadLong(memory, newFont + 4u));
    }

    [Fact]
    public void GuestGfxBaseFontListRejectsMalformedExistingLinks()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint font = 0x600;
        const uint name = 0x500;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);
        WriteFontHeader(memory, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(memory, name, "topaz.font");
        Assert.True(list.Initialize(0));

        // A non-empty list must have a first node whose predecessor is the
        // list header and a last node whose successor is the tail sentinel.
        Assert.True(memory.TryWriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead, 0x3000));
        Assert.False(fonts.TryAdd(font));
        Assert.Equal(0u, ReadLong(memory, font));
        Assert.Equal(0u, ReadLong(memory, font + 4));
    }

    [Fact]
    public void GuestGfxBaseFontListRejectsOddGuestPointersBeforeMutation()
    {
        var memory = new FakeMemory(0x4000);
        const uint gfxBase = 0x1000;
        const uint evenFont = 0x600;
        const uint oddFont = 0x601;
        const uint name = 0x500;
        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);

        WriteFontHeader(memory, evenFont, name, ySize: 8, style: 0, flags: 1);
        WriteFontHeader(memory, oddFont, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(memory, name, "topaz.font");
        Assert.True(list.Initialize(0));

        var emptyHead = ReadLong(
            memory,
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead);
        var emptyTailPred = ReadLong(
            memory,
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred);
        Assert.False(list.SetDefaultFont(oddFont));
        Assert.Equal(0u, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultFont));
        Assert.False(fonts.TryAdd(oddFont));
        Assert.Equal(emptyHead, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(emptyTailPred, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred));

        var tail = gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail;
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead,
            oddFont));
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred,
            oddFont));
        Assert.True(memory.TryWriteLong(oddFont, tail));
        Assert.True(memory.TryWriteLong(oddFont + 4, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFonts));

        Assert.False(list.TryEnumerate(out _));
        Assert.False(fonts.TryRemove(oddFont));
        Assert.Equal(oddFont, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(oddFont, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred));
    }

    [Fact]
    public void NativeOverlayTailChainsOddReboundFontListNodeBeforeRemFont()
    {
        const uint hostBase = 0x00F9_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint imageBase = 0x00F9_F000;
        const uint oddFont = 0x00FB_0001;
        const uint nativeTarget = 0x00FC_1301;
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemFont)),
            nativeTarget);

        var bus = new AmigaBus();
        bus.MapWritableMemory(hostBase, new byte[0xA0]);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(nativeBase, new byte[0xA0]);
        bus.MapWritableMemory(0x00FB_0000, new byte[0x100]);
        var memory = new HostGuestMemory(bus);
        var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
        var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
        var nativeSetup = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
        Assert.True(list.Initialize(0));
        Assert.True(nativeSetup.Initialize(0));

        var nativeList = nativeBase + (uint)GraphicsLayouts.GfxBaseTextFonts;
        var nativeTail = nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTail;
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead,
            oddFont);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred,
            oddFont);
        bus.WriteLong(oddFont, nativeTail);
        bus.WriteLong(oddFont + 4, nativeList);

        using var services = CreateHostGraphicsServices(memory, fontList: list);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        var state = new M68kCpuState
        {
            A = { [1] = oddFont },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 277,
            ProgramCounter = 0x0012_3A91
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.RemFont)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(277, state.Cycles);
        Assert.Equal(oddFont, bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsHead));
        Assert.Equal(oddFont, bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseTextFontsTailPred));
    }

    [Fact]
    public void GuestGfxBaseFontListRestoresLinksWhenAddFontFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var setup = new GraphicsGuestFontListBackend(backing, 0x1000);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(backing, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(backing, name, "topaz.font");
        Assert.True(setup.Initialize(0));

        var memory = new FailingByteWriteMemory(backing);
        var list = new GraphicsGuestFontListBackend(memory, 0x1000);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);
        // Fail the second byte of the GfxBase tail-predecessor write after
        // the font and sentinel links have already started publishing.
        memory.FailOnNextByteWrite(14);
        Assert.False(fonts.TryAdd(font));
        Assert.Equal(0x1090u, ReadLong(backing, 0x108C));
        Assert.Equal(0x108Cu, ReadLong(backing, 0x1094));
        Assert.Equal(0u, ReadLong(backing, font));
        Assert.Equal(0u, ReadLong(backing, font + 4));
        Assert.Equal((byte)0, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontNodeType));
        Assert.Equal((byte)1, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontFlags));

        Assert.True(fonts.TryAdd(font));
    }

    [Fact]
    public void GuestGfxBaseFontListRestoresLinksWhenRemFontFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var setup = new GraphicsGuestFontListBackend(backing, 0x1000);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(backing, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(backing, name, "topaz.font");
        Assert.True(setup.Initialize(0));

        var memory = new FailingByteWriteMemory(backing);
        var list = new GraphicsGuestFontListBackend(memory, 0x1000);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);
        Assert.True(fonts.TryAdd(font));
        // The one-node remove writes the predecessor and successor links,
        // then the head.  Fail the second byte of that head publication.
        memory.FailOnNextByteWrite(10);
        Assert.False(fonts.TryRemove(font));
        Assert.Equal(font, ReadLong(backing, 0x108C));
        Assert.Equal(font, ReadLong(backing, 0x1094));
        Assert.Equal(0u, ReadLong(backing, 0x1090));
        Assert.Equal(0x1090u, ReadLong(backing, font));
        Assert.Equal(0x108Cu, ReadLong(backing, font + 4));
        Assert.Equal((byte)1, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontFlags));

        Assert.True(fonts.TryRemove(font));
    }

    [Fact]
    public void GuestGfxBaseFontListRollsBackWhenFinalEmptySentinelPublicationFails()
    {
        var backing = new FakeMemory(0x4000);
        var setup = new GraphicsGuestFontListBackend(backing, 0x1000);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(backing, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(backing, name, "topaz.font");
        Assert.True(setup.Initialize(0));

        var memory = new FailingByteWriteMemory(backing);
        var list = new GraphicsGuestFontListBackend(memory, 0x1000);
        var fonts = new GraphicsMemoryFontBackend(memory, fontList: list);
        Assert.True(fonts.TryAdd(font));

        // A one-node removal publishes the predecessor/successor links,
        // head/tail sentinels, detached font links, and FPF_REMOVED before
        // the final canonical empty-list head write.  Reject that last
        // publication and require the complete guest list/font state to be
        // restored for a later retry.
        memory.FailOnNextByteWrite(26);
        Assert.False(fonts.TryRemove(font));
        Assert.Equal(font, ReadLong(backing, 0x108C));
        Assert.Equal(font, ReadLong(backing, 0x1094));
        Assert.Equal(0u, ReadLong(backing, 0x1090));
        Assert.Equal(0x1090u, ReadLong(backing, font));
        Assert.Equal(0x108Cu, ReadLong(backing, font + 4));
        Assert.Equal((byte)1, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontFlags));

        Assert.True(fonts.TryRemove(font));
        Assert.Equal(0x1090u, ReadLong(backing, 0x108C));
        Assert.Equal(0x108Cu, ReadLong(backing, 0x1094));
    }

