    [Fact]
    public void ExtendFontBuildsAnOwnedGuestExtensionAndStripReleasesIt()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint tags = 0x900;
        WriteFontHeader(memory, font, name, ySize: 8, style: 0x04, flags: 1);

        Assert.True(core.ExtendFont(font, tags, fonts));
        var extension = ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension);
        Assert.NotEqual(0u, extension);
        Assert.Equal((byte)0x84, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal((ushort)0xF00D, ReadWord(memory, extension + (uint)GraphicsLayouts.TextFontExtensionMatchWord));
        Assert.Equal(font, ReadLong(memory, extension + (uint)GraphicsLayouts.TextFontExtensionBackPtr));
        var clonedTags = ReadLong(memory, extension + (uint)GraphicsLayouts.TextFontExtensionTags);
        Assert.NotEqual(tags, clonedTags);
        Assert.Equal(0u, ReadLong(memory, clonedTags));
        Assert.Equal(0u, ReadLong(memory, clonedTags + 4u));
        Assert.Equal(0u, ReadLong(memory, extension + (uint)GraphicsLayouts.TextFontExtensionOrigReplyPort));
        Assert.True(core.ExtendFont(font, tags + 4, fonts));
        Assert.Equal(0, core.StripFont(font, fonts));
        Assert.Equal(0u, ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x04, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal(extension, allocator.LastFreedAddress);
    }

    [Fact]
    public void ExtendFontClonesGuestTagItemsBeforePublishingTheOwnedExtension()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint tags = 0x900;
        const uint deviceDpiTag = 0x8000_0001u;
        WriteFontHeader(memory, font, name, ySize: 8, style: 0, flags: 1);
        Assert.True(memory.TryWriteLong(tags, deviceDpiTag));
        Assert.True(memory.TryWriteLong(tags + 4u, 0x0060_0060u));
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        Assert.True(memory.TryWriteLong(tags + 12u, 0));

        Assert.True(fonts.TryExtend(font, tags));
        var extension = ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension);
        var clonedTags = ReadLong(memory, extension + (uint)GraphicsLayouts.TextFontExtensionTags);
        Assert.NotEqual(tags, clonedTags);
        Assert.Equal(deviceDpiTag, ReadLong(memory, clonedTags));
        Assert.Equal(0x0060_0060u, ReadLong(memory, clonedTags + 4u));

        // The caller may reuse or release its original tag storage after
        // ExtendFont returns; the owned extension must retain the snapshot.
        Assert.True(memory.TryWriteLong(tags + 4u, 0x0001_0001u));
        Assert.Equal(0x0060_0060u, ReadLong(memory, clonedTags + 4u));

        Assert.True(fonts.TryStrip(font));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(extension, allocator.LastFreedAddress);
    }

    [Fact]
    public void ExtendFontJumpsOverLargeTagSkipBeforeCloning()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new FakeAllocator();
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint tags = 0x900;
        const uint deviceDpiTag = tags + 8u + (4096u * 8u);
        const uint deviceDpi = 0x8000_0001u;

        WriteFontHeader(memory, font, name, ySize: 8, style: 0, flags: 1);
        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.TagSkip, 4096);
        WriteTag(memory, deviceDpiTag, deviceDpi, 0x0060_0060);
        WriteTag(memory, deviceDpiTag + 8u, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.True(fonts.TryExtend(font, tags));
        var extension = ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension);
        var clonedTags = ReadLong(memory, extension + (uint)GraphicsLayouts.TextFontExtensionTags);
        Assert.Equal(deviceDpi, ReadLong(memory, clonedTags));
        Assert.Equal(0x0060_0060u, ReadLong(memory, clonedTags + 4u));
        Assert.Equal(GraphicsRastPortAttributeOperations.TagDone, ReadLong(memory, clonedTags + 8u));
        Assert.True(fonts.TryStrip(font));
    }

    [Fact]
    public void ExtendFontRejectsMalformedGuestTagChainBeforeAllocating()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(memory, font, name, ySize: 8, style: 0x04, flags: 1);

        // The final eight-byte TagItem crosses the mapped guest boundary.
        Assert.False(core.ExtendFont(font, 0x3FFC, fonts));
        Assert.Equal(0u, ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x04, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void ExtendFontRejectsOddAlignedGuestTagListBeforeAllocating()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(memory, font, name, ySize: 8, style: 0x04, flags: 1);

        // FakeMemory permits byte-addressed reads, but a native 68k TagItem
        // list cannot begin at an odd address.  The portable lifecycle must
        // leave the font and allocator untouched for that provider boundary.
        Assert.False(core.ExtendFont(font, 0x901, fonts));
        Assert.Equal(0u, ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x04, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void TaggedWeighTAMatchRejectsOddContinuationBeforeScoring()
    {
        var memory = new FakeMemory(0x4000);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint requested = 0x200;
        const uint target = 0x300;
        const uint name = 0x500;
        const uint oddTags = 0x901;
        const uint targetTags = 0xA00;

        WriteTextAttr(memory, requested, name, ySize: 8, style: 0x80, flags: 1);
        WriteTextAttr(memory, target, name, ySize: 8, style: 0, flags: 1);
        Assert.True(memory.TryWriteLong(requested + (uint)GraphicsLayouts.TextAttrSize, oddTags));
        // The continuation bytes are readable on purpose; only their ABI
        // alignment makes this request malformed.
        Assert.True(memory.TryWriteLong(oddTags, 0));
        Assert.True(memory.TryWriteLong(oddTags + 4u, 0));
        Assert.True(memory.TryWriteLong(targetTags, 0));
        Assert.True(memory.TryWriteLong(targetTags + 4u, 0));

        Assert.False(fonts.TryWeighTAMatch(requested, target, targetTags, out _));
    }

