    [Fact]
    public void ExtendFontRestoresRecycledExtensionAfterPartialBacklinkPublication()
    {
        var backing = new FakeMemory(0x4000);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint extension = 0x1000;
        WriteFontHeader(backing, font, name, ySize: 8, style: 0x04, flags: 1);
        WriteAscii(backing, name, "topaz.font");

        var originalExtension = new byte[GraphicsLayouts.TextFontExtensionSize + 8];
        for (var offset = 0; offset < originalExtension.Length; offset++)
        {
            originalExtension[offset] = (byte)(0x40 + offset);
            Assert.True(backing.TryWriteByte(extension + (uint)offset, originalExtension[offset]));
        }

        var memory = new PartialThenRejectLongWriteMemory(backing)
        {
            PartialLongAddress = font + (uint)GraphicsLayouts.TextFontExtension
        };
        var allocator = new SequenceAddressAllocator(extension);
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);

        // ExtendFont fully prepares the recycled extension, then the font
        // backlink accepts only three bytes and rejects the LONG. Both the
        // extension and the font fields must return to their pre-call bytes.
        Assert.False(fonts.TryExtend(font, 0));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(0u, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x04, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontStyle));
        for (var offset = 0; offset < originalExtension.Length; offset++)
            Assert.Equal(originalExtension[offset], ReadByte(backing, extension + (uint)offset));

        // A clean backend instance can reuse the same guest envelope after
        // the failed publication; no tagged extension residue survives.
        memory.PartialLongAddress = null;
        var retryAllocator = new SequenceAddressAllocator(extension);
        var retryFonts = new GraphicsMemoryFontBackend(memory, retryAllocator);
        Assert.True(retryFonts.TryExtend(font, 0));
        Assert.Equal(extension, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.True(retryFonts.TryStrip(font));
        Assert.Equal(1, retryAllocator.FreeCount);
    }

