        Assert.False(fonts.TryStrip(font));
        Assert.Equal(extension, ReadLong(backing, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal((byte)0x84, ReadByte(backing, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal(0, allocator.FreeCount);

        memory.PartialLongAddress = null;
        Assert.True(fonts.TryStrip(font));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Fact]
    public void StripFontLeavesExternalExtensionAndStyleOwnershipUntouched()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var fonts = new GraphicsMemoryFontBackend(memory, allocator);
        const uint font = 0x600;
        const uint name = 0x500;
        const uint externalExtension = 0x1200;
        const byte externalStyle = 0x84;
        WriteFontHeader(memory, font, name, ySize: 8, style: externalStyle, flags: 1);
        Assert.True(memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontExtension, externalExtension));

        // An extension already installed by another owner is accepted by
        // ExtendFont, but StripFont must not detach or free that memory.
        Assert.True(core.ExtendFont(font, 0x900, fonts));
        Assert.Equal(0, allocator.FreeCount);
        Assert.Equal(0, core.StripFont(font, fonts));
        Assert.Equal(externalExtension, ReadLong(memory, font + (uint)GraphicsLayouts.TextFontExtension));
        Assert.Equal(externalStyle, ReadByte(memory, font + (uint)GraphicsLayouts.TextFontStyle));
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void MetricQueriesUseScalarTablesWithoutStrikeAdmission()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint rastPort = 0x20;
        const uint font = 0x600;
        const uint text = 0x700;
        const uint extent = 0x800;

        // The resident metric vectors consume the TextFont scalar header and
        // fixed-cell movement only.  They do not require tf_CharData,
        // tf_Modulo, or a nonzero tf_YSize; those fields belong to glyph
        // rendering/lifecycle admission instead.
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontYSize,
            0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontXSize,
            5));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontBaseline,
            0));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontLoChar,
            (byte)'A'));
        Assert.True(memory.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontHiChar,
            (byte)'A'));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharData,
            0));
        Assert.True(memory.TryWriteWord(
            font + (uint)GraphicsLayouts.TextFontModulo,
            0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharLoc,
            0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharSpace,
            0));
        Assert.True(memory.TryWriteLong(
            font + (uint)GraphicsLayouts.TextFontCharKern,
            0));
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            0));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));

        Assert.Equal(6, core.TextLength(rastPort, text, 1, fonts));
        Assert.Equal(0, core.TextExtent(rastPort, text, 1, extent, fonts));
        Assert.Equal((ushort)6, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)0, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)5, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)-1, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxY)));
        Assert.Equal(
            1,
            core.TextFit(
                rastPort,
                text,
                1,
                extent,
                0,
                1,
                6,
                0,
                fonts));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var directState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1u },
            Cycles = 37
        };
        Assert.True(adapter.TryInvoke(directState, (int)GraphicsLvo.TextLength));
        Assert.Equal(6u, directState.D[0]);
        Assert.Equal(37, directState.Cycles);

        var mappedState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent },
            D = { [0] = 1u, [1] = 1u, [2] = 6u, [3] = 0u },
            Cycles = 41
        };
        Assert.True(adapter.TryInvoke(
            mappedState,
            (int)GraphicsLvo.TextExtent,
            nativeOverlay: true));
        Assert.Equal(0u, mappedState.D[0]);
        Assert.Equal(41, mappedState.Cycles);
        Assert.Equal((ushort)6, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));

        // Rendering still uses the stricter strike admission and therefore
        // remains available to the native/provider owner for this sparse
        // zero-height font.
        Assert.Equal(-1, core.Text(rastPort, text, 1, fonts));
    }

    [Fact]
    public void TextExtentFontExtentAndTextFitWriteGuestTextExtentStructures()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        const uint emptyExtent = 0x380;
        memory.TryWriteByte(text, (byte)'A');
        memory.TryWriteByte(text + 1, (byte)'A');

        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        // A non-empty string must have a valid guest address.  The cached
        // TextLength overload remains available for callers that do not pass
        // a decoded font, but decoded metric paths fail closed instead of
        // treating address zero as a readable character stream.
        Assert.Equal(-1, core.TextLength(0x20, 0, 1, fonts));
        Assert.Equal(-1, core.TextExtent(0x20, 0, 1, extent, fonts));
        Assert.Equal(-1, core.TextFit(0x20, 0, 1, extent, 0, 1, 8, 3, fonts));
        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((ushort)4, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)3, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)-3, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinY)));
        Assert.Equal((short)3, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX)));
        Assert.Equal((short)-1, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxY)));

        Assert.Equal(0, core.FontExtent(font, extent, fonts));
        // FontExtent follows the one-character TextLength advance, not only
        // the bitmap cell width.  The fake glyph's CharSpace is four pixels.
        Assert.Equal((ushort)4, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)3, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));

        const uint explicitConstraint = 0x3C0;
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentWidth, 1);
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentHeight, 1);
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentMinX, 0);
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentMinY, unchecked((ushort)-3));
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentMaxX, 3);
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentMaxY, unchecked((ushort)-1));
        // The explicit TextExtent itself is only 1x1, so it rejects this
        // 4x3 glyph even though the alternate dimensions are ignored when
        // an explicit rectangle is supplied.
        Assert.Equal(0, core.TextFit(0x20, text, 1, extent, explicitConstraint, 1, 1, 1, fonts));

        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentWidth, 4);
        memory.TryWriteWord(explicitConstraint + (uint)GraphicsLayouts.TextExtentHeight, 3);
        // A narrower alternate rendering box is ignored because the explicit
        // extent is active; the 4x3 rectangle therefore admits the glyph.
        Assert.Equal(
            1,
            core.TextFit(
                0x20,
                text,
                1,
                extent,
                explicitConstraint,
                1,
                1,
                3,
                fonts));
        Assert.Equal(
            1,
            core.TextFit(
                0x20,
                text,
                1,
                extent,
                explicitConstraint,
                1,
                4,
                3,
                fonts));

        Assert.Equal(1, core.TextFit(0x20, text, 1, extent, 0, 1, 4, 3, fonts));
        Assert.Equal((ushort)4, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));

        // The alternate rendering box uses its literal dimensions when no
        // explicit TextExtent is supplied.  A zero width therefore admits no
        // glyph; it is not treated as an omitted constraint.
        Assert.Equal(0, core.TextFit(0x20, text, 1, emptyExtent, 0, 1, 0, 3, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, emptyExtent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)0, ReadWord(memory, emptyExtent + (uint)GraphicsLayouts.TextExtentHeight));

        Assert.Equal(0, core.TextFit(0x20, text, 1, emptyExtent, 0, 1, 3, 3, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, emptyExtent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)0, ReadWord(memory, emptyExtent + (uint)GraphicsLayouts.TextExtentHeight));

        // TextFit's reverse form is anchored at the final character, not at
        // the first byte of the string.  Passing text+1 with direction -1
        // must therefore measure both A glyphs without touching text-1.
        Assert.Equal(2, core.TextFit(0x20, text + 1, 2, extent, 0, -1, 8, 3, fonts));
        Assert.Equal((ushort)8, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));

        // A spacing value that cancels the glyph advance reverses/stalls the
        // path.  Kickstart reports no fit and clears the output extent.
        Assert.True(memory.TryWriteWord(
            0x20u + (uint)GraphicsLayouts.RastPortTextSpacing,
            unchecked((ushort)-4)));
        Assert.Equal(0, core.TextFit(0x20, text, 2, extent, 0, 1, 8, 3, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));
    }

    [Fact]
    public void TextFitRejectsOutOfRangeAlternateConstraintDimensions()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 3, 3, 0),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(1, 1, 4, 0x8000000000000000UL)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        // TextFit's alternate width/height fields are documented as
        // 0..32767. They are ULONGs in the ABI, so the pure core must not
        // silently narrow an out-of-range value into a valid constraint.
        Assert.Equal(
            -1,
            core.TextFit(0x20, text, 1, extent, 0, 1, 0x0000_8000, 1, fonts));
        Assert.Equal(
            -1,
            core.TextFit(0x20, text, 1, extent, 0, 1, 1, 0x0000_8000, fonts));

        // A zero-length request has no rendering box to constrain.  The
        // classic routine returns an empty extent without consulting the
        // alternate dimensions, so the ULONG range guard applies only to a
        // non-empty string.
        Assert.Equal(
            0,
            core.TextFit(0x20, 0, 0, extent, 0, 1, 0x0000_8000, 0x0000_8000, fonts));
        Assert.Equal((ushort)0, ReadWord(
            memory,
            extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal(
            0,
            core.TextFit(0x20, 0, 0, extent, 0x1FFF, 1, 1, 1, fonts));
        Assert.Equal((ushort)0, ReadWord(
            memory,
            extent + (uint)GraphicsLayouts.TextExtentWidth));

    }

    [Fact]
    public void EmptyTextFitDoesNotConsumeSpacingOrStyleFields()
    {
        var backing = new FakeMemory(0x2000);
        var setup = CreateCore(backing);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint extent = 0x340;

        Assert.Equal(0, setup.SetFont(rastPort, font, fonts));
        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            sizeof(ushort));

        // Kickstart's zero-count path publishes an empty result without
        // touching TxSpacing or AlgoStyle.  A fault in TxSpacing must not
        // convert this valid query into a native/provider fallback.
        Assert.Equal(
            0,
            GraphicsTextOperations.TextFit(
                memory,
                rastPort,
                0,
                0,
                extent,
                0,
                1,
                0x0000_8000,
                0x0000_8000,
                fonts));
        Assert.Equal(
            (ushort)0,
            ReadWord(backing, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal(
            (ushort)0,
            ReadWord(backing, extent + (uint)GraphicsLayouts.TextExtentHeight));
    }

    [Fact]
    public void EmptyTextFitDoesNotRequireAReadableSelectedFont()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint extent = 0x100;

        // The selected font is provider-owned and outside this portable
        // memory image.  Kickstart's zero-count TextFit path only publishes
        // the empty result, so it must not steal the request by decoding that
        // font or consulting the optional constraint.
        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            0x1800));
        Assert.True(memory.TryWriteWord(extent + (uint)GraphicsLayouts.TextExtentWidth, 0xAAAA));
        Assert.Equal(
            0,
            core.TextFit(rastPort, 0, 0, extent, 0x1FFC, 1, 0x8000, 0x8000, new FakeFontBackend()));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal(0, ReadByte(memory, extent + (uint)offset));
    }

    [Fact]
    public void HostRegisterAdapterAcceptsEmptyTextFitWithAnEvenUnreadableRastPort()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint extent = 0x100;

        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.True(memory.TryWriteByte(extent + (uint)offset, 0xA5));

        var state = new M68kCpuState
        {
            // TextFit's zero-length path does not consume the RastPort or
            // optional constraining extent.  An even, non-null RastPort must
            // therefore be accepted without decoding its (unreadable)
            // selected font; the result extent is still a required output.
            A = { [0] = 0, [1] = rastPort, [2] = extent, [3] = 0x1FFC },
            D = { [0] = 0, [1] = 1, [2] = 0x8000, [3] = 0x8000 },
            Cycles = 77
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(77, state.Cycles);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal(0, ReadByte(memory, extent + (uint)offset));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveEmptyTextFitWithoutReadableFont()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint rastPort = 0x100;
        const uint extent = 0x180;

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
            bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
            bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
            bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, 0x0018_0000);
            for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
                bus.WriteByte(extent + (uint)offset, 0xA5, 0);
        }

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort, [2] = extent, [3] = 0x1FFC },
            D = { [0] = 0, [1] = 1, [2] = 0x8000, [3] = 0x8000 },
            Cycles = 97
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = 0, [1] = rastPort, [2] = extent, [3] = 0x1FFC },
            D = { [0] = 0, [1] = 1, [2] = 0x8000, [3] = 0x8000 },
            Cycles = 97
        };

        direct.Invoke(directState, (int)GraphicsLvo.TextFit);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.TextFit));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
        {
            Assert.Equal(0, directBus.ReadByte(extent + (uint)offset));
            Assert.Equal(directBus.ReadByte(extent + (uint)offset), overlayBus.ReadByte(extent + (uint)offset));
        }
    }

    [Fact]
    public void TextFitTreatsKerningThatStallsTheCursorAsNoFit()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 3, 3, 0, hasCharKern: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                // CharKern is applied before CharSpace. The effective
                // movement is therefore zero even though CharSpace alone
                // is positive; TextFit must publish an empty fit.
                [(byte)'A'] = new GraphicsGlyph(1, 1, 4, -4, 0, 0, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        Assert.Equal(0, core.TextFit(0x20, text, 1, extent, 0, 1, 8, 3, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentHeight));
    }

    [Fact]
    public void TextFitClearsATooShortAlternateBoxBeforeWalkingMalformedText()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x340;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(4, 4, 3, 0),
            new Dictionary<byte, GraphicsGlyph>());

        // The character is deliberately absent from the provider. Native
        // TextFit rejects a box shorter than tf_YSize before it dereferences
        // the string/glyph stream, so this remains a successful zero-fit
        // instead of stealing the call as a malformed-font failure.
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.True(memory.TryWriteByte(extent + (uint)offset, 0xA5));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));
        Assert.Equal(0, core.TextFit(0x20, text, 1, extent, 0, 1, 8, 3, fonts));
        for (var offset = 0; offset < GraphicsLayouts.TextExtentSize; offset++)
            Assert.Equal(0, ReadByte(memory, extent + (uint)offset));
    }

    [Fact]
    public void FontExtentIncludesKerningBoundsAndUsesReversePathWidthDirection()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint font = 0x200;
        const uint extent = 0x300;
        var glyphs = new Dictionary<byte, GraphicsGlyph>
        {
            // The full CharSpace + CharKern movement contributes to the
            // normal-font width before the directional zero clamp.
            [(byte)'A'] = new GraphicsGlyph(3, 8, 4, -2, 0, 0, 0),
            // This glyph moves left overall and is ignored by the normal
            // width, while its right-side bitmap extent remains part of the
            // bound.
            [(byte)'B'] = new GraphicsGlyph(6, 8, -5, 1, 0, 0, 0)
        };

        Assert.Equal(0, core.FontExtent(
            font,
            extent,
            new TableFontBackend(
                new GraphicsFontMetrics(
                    8,
                    3,
                    6,
                    0,
                    loChar: (byte)'A',
                    hiChar: (byte)'B',
                    hasCharKern: true),
                glyphs)));
        Assert.Equal((ushort)2, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)-2, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)6, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX)));

        Assert.Equal(0, core.FontExtent(
            font,
            extent,
            new TableFontBackend(
                new GraphicsFontMetrics(
                    8,
                    10,
                    6,
                    0,
                    flags: 0x24,
                    loChar: (byte)'A',
                    hiChar: (byte)'B',
                    hasCharKern: true),
                glyphs)));
        Assert.Equal((short)-4, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth)));
        Assert.Equal((short)-2, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX)));
        Assert.Equal((short)6, unchecked((short)ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX)));
    }

    [Fact]
    public void FontExtentIgnoresTheOptionalTrailingDefaultGlyph()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint font = 0x200;
        const uint extent = 0x300;
        var fonts = new DefaultGlyphFontBackend(
            new GraphicsFontMetrics(
                8,
                3,
                6,
                0,
                loChar: (byte)'A',
                hiChar: (byte)'B'),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(2, 8, 2, 0, 0, 0, 0),
                [(byte)'B'] = new GraphicsGlyph(2, 8, 3, 0, 0, 0, 0)
            },
            new GraphicsGlyph(7, 8, 9, 0, 0, 0, 0));

        Assert.Equal(0, core.FontExtent(font, extent, fonts));
        // FontExtent covers only the declared LoChar..HiChar entries.  The
        // trailing table slot is the fallback used by Text for out-of-range
        // bytes and must not widen the font-wide envelope.
        Assert.Equal((ushort)3, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)0, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)1, ReadSignedWord(memory, extent + (uint)GraphicsLayouts.TextExtentMaxX));
    }

    [Fact]
    public void TextMetricsFailClosedOnAccumulatedWidthOverflow()
    {
        var memory = new FakeMemory(0x2000);
        var font = 0x300u;
        var text = 0x340u;
        var extent = 0x380u;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(1, 1, 1, 0, hasCharKern: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(1, 1, int.MaxValue, 0, 0, 0, 0)
            });

        Assert.True(memory.TryWriteLong(0x20u + (uint)GraphicsLayouts.RastPortFont, font));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteByte(text + 1, (byte)'A'));
        Assert.True(memory.TryWriteWord(extent + (uint)GraphicsLayouts.TextExtentWidth, 0xAAAA));

        Assert.Equal(-1, GraphicsTextOperations.TextExtent(memory, 0x20, text, 2, extent, fonts));
        Assert.Equal((ushort)0xAAAA, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
        // A zero-width alternate box is a valid constraint. TextFit therefore
        // returns an empty result before it needs to decode a later glyph;
        // the accumulated-overflow failure remains covered by TextExtent.
        Assert.Equal(0, GraphicsTextOperations.TextFit(memory, 0x20, text, 2, extent, 0, 1, 0, 0, fonts));
        Assert.Equal((ushort)0, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
    }

    [Fact]
    public void TextMetricsRejectAnAdvanceOutsideTheGuestCharSpaceWord()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x340;
        const uint extent = 0x380;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(1, 1, 1, 0, hasCharSpace: true),
            new Dictionary<byte, GraphicsGlyph>
            {
                // CharSpace is a signed guest WORD.  A host provider must not
                // turn a value outside that envelope into a claimed metric.
                [(byte)'A'] = new GraphicsGlyph(1, 1, 32768, 0, 0, 0, 0)
            });

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth,
            0xA55A));
        Assert.True(memory.TryWriteLong(
            0x20u + (uint)GraphicsLayouts.RastPortFont,
            font));

        Assert.Equal(-1, core.TextLength(0x20, text, 1, fonts));
        Assert.Equal(-1, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal(-1, core.TextFit(0x20, text, 1, extent, 0, 1, 64, 1, fonts));
        Assert.Equal((ushort)0xA55A, ReadWord(
            memory,
            extent + (uint)GraphicsLayouts.TextExtentWidth));
    }

    [Fact]
    public void TextExtentRejectsAComputedSignedRectangleOutsideTheGuestWordEnvelope()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint font = 0x300;
        const uint text = 0x340;
        const uint extent = 0x380;
        var fonts = new TableFontBackend(
            new GraphicsFontMetrics(1, 4, 1, 0),
            new Dictionary<byte, GraphicsGlyph>
            {
                [(byte)'A'] = new GraphicsGlyph(1, 1, 4, 0x8000000000000000UL)
            });

        Assert.True(memory.TryWriteLong(0x20u + (uint)GraphicsLayouts.RastPortFont, font));
        Assert.True(memory.TryWriteWord(
            0x20u + (uint)GraphicsLayouts.RastPortTextSpacing,
            unchecked((ushort)32764)));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.True(memory.TryWriteWord(
            extent + (uint)GraphicsLayouts.TextExtentWidth,
            0xA55A));

        // The resulting width is 32768, which is representable in the
        // UWORD width field, but MaxX would be 32767 only when the envelope
        // is exact.  One more pixel makes the signed Rectangle.MaxX overflow;
        // the complete result must remain untouched for native fallback.
        Assert.Equal(0, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((ushort)32768, ReadWord(
            memory,
            extent + (uint)GraphicsLayouts.TextExtentWidth));

        Assert.True(memory.TryWriteWord(
            0x20u + (uint)GraphicsLayouts.RastPortTextSpacing,
            unchecked((ushort)32765)));
        Assert.Equal(-1, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((ushort)32768, ReadWord(
            memory,
            extent + (uint)GraphicsLayouts.TextExtentWidth));
    }

