    [Fact]
    public void FontExtentPreflightsResultBeforeAskingFontBackendForMetrics()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var fonts = new CountingFontBackend();
        const uint font = 0x200;
        const uint truncatedExtent = 0x0FFB;

        // The final bytes of the packed 12-byte result lie beyond the guest
        // memory image.  FontExtent must reject the destination before it
        // asks a host/provider font backend to decode the selected font.
        Assert.Equal(-1, core.FontExtent(font, truncatedExtent, fonts));
        Assert.Equal(0, fonts.MetricsRequests);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = font, [1] = truncatedExtent },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 37
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FontExtent));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(37, state.Cycles);
        Assert.Equal(0, fonts.MetricsRequests);
    }

    [Fact]
    public void TextMetricResultsPreflightBeforeAskingFontBackendForMetrics()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var fonts = new CountingFontBackend();
        const uint rastPort = 0x20;
        const uint font = 0x200;
        const uint text = 0x320;
        const uint truncatedExtent = 0x0FFB;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));

        Assert.Equal(-1, core.TextExtent(
            rastPort,
            text,
            1,
            truncatedExtent,
            fonts));
        Assert.Equal(-1, core.TextFit(
            rastPort,
            text,
            1,
            truncatedExtent,
            0,
            1,
            8,
            3,
            fonts));
        Assert.Equal(0, fonts.MetricsRequests);
        Assert.Equal(0, fonts.GlyphRequests);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var textExtentState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = truncatedExtent },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 41
        };
        Assert.False(adapter.TryInvoke(textExtentState, (int)GraphicsLvo.TextExtent));
        Assert.Equal(0xCAFE_BABEu, textExtentState.D[0]);
        Assert.Equal(41, textExtentState.Cycles);

        var textFitState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = truncatedExtent },
            D = { [0] = 1, [1] = 1, [2] = 8, [3] = 3 },
            Cycles = 43
        };
        Assert.False(adapter.TryInvoke(textFitState, (int)GraphicsLvo.TextFit));
        Assert.Equal(1u, textFitState.D[0]);
        Assert.Equal(43, textFitState.Cycles);
        Assert.Equal(0, fonts.MetricsRequests);
        Assert.Equal(0, fonts.GlyphRequests);
    }

    [Fact]
    public void ViewActivationAndSynchronizationStayInsideTheDisplayBackendBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay { BeamPosition = 0x1234 };
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), new FakeBlitter(), display);

        Assert.Equal(0, core.LoadView(0x180));
        Assert.Equal(0x180u, display.PublishedView);
        Assert.Equal(0, core.WaitTOF());
        memory.TryWriteLong(0x1A0u + (uint)GraphicsLayouts.ViewPortRasInfo, 0x300);
        memory.TryWriteLong(0x300u + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(0x300u + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        memory.TryWriteWord(0x300u + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        memory.TryWriteWord(0x300u + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        Assert.Equal(0, core.WaitBOVP(0x1A0));
        Assert.Equal((ushort)0x1234, core.VBeamPos());
        Assert.True(display.WaitedForTopOfFrame);
        Assert.Equal(0x1A0u, display.WaitedForViewPort);
        Assert.Equal(-1, core.WaitBOVP(0x1FF8));
        Assert.Equal(0x1A0u, display.WaitedForViewPort);

        var publishedBeforeMalformedView = display.PublishedView;
        Assert.Equal(-1, core.LoadView(0x1FF8));
        Assert.Equal(publishedBeforeMalformedView, display.PublishedView);
    }

    [Fact]
    public void PortableLoadViewAcceptsCommonLores320x200GeneratedProgram()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display);
        const uint view = 0x0800;
        const uint viewPort = 0x0900;
        const uint rasInfo = 0x0A00;
        const uint bitMap = 0x0B00;
        const uint plane = 0x0C00;
        const uint copList = 0x0D00;
        const uint lofCprList = 0x0E00;
        const uint shfCprList = 0x0F00;
        const uint raw = 0x1000;

        Assert.True(memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort));
        Assert.True(memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewLoFCprList, lofCprList));
        Assert.True(memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewShFCprList, shfCprList));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, copList));
        Assert.True(memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320));
        Assert.True(memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo));
        Assert.True(memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 200));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane));
        Assert.True(memory.TryWriteLong(copList + (uint)GraphicsLayouts.CopListViewPort, viewPort));
        Assert.True(memory.TryWriteLong(copList + (uint)GraphicsLayouts.CopListCopPtr, raw));
        Assert.True(memory.TryWriteLong(copList + (uint)GraphicsLayouts.CopListCopLStart, raw));
        Assert.True(memory.TryWriteLong(copList + (uint)GraphicsLayouts.CopListCopSStart, raw));
        Assert.True(memory.TryWriteWord(copList + (uint)GraphicsLayouts.CopListCount, 12));
        Assert.True(memory.TryWriteWord(copList + (uint)GraphicsLayouts.CopListMaxCount, 12));
        foreach (var cprList in new[] { lofCprList, shfCprList })
        {
            Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListStart, raw));
            Assert.True(memory.TryWriteWord(cprList + (uint)GraphicsLayouts.CprListMaxCount, 12));
        }

        var generatedWords = new ushort[]
        {
            0x008E, 0x2C81,
            0x0090, 0xF4C1,
            0x0092, 0x0038,
            0x0094, 0x00D0,
            0x0108, 0x0000,
            0x010A, 0x0000,
            0x0100, 0x1000,
            0x0102, 0x0000,
            0x0104, 0x0000,
            0x00E0, (ushort)(plane >> 16),
            0x00E2, (ushort)plane,
            GraphicsLayouts.CopperEndWait, GraphicsLayouts.CopperEndMask
        };
        for (var index = 0; index < generatedWords.Length; index++)
            Assert.True(memory.TryWriteWord(raw + (uint)(index * sizeof(ushort)), generatedWords[index]));

        Assert.Equal(GraphicsRasterOperations.Success, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
    }

