    [Fact]
    public void WaitBovpAcceptsAnAssemblingViewportWithoutRasInfo()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;

        // WaitBOVP consumes viewport timing state.  Intuition may invoke it
        // while the viewport is assembled but before RasInfo is linked; a
        // null chain is therefore not a reason to divert the call to a
        // provider.  A present malformed chain remains covered by the
        // existing provider-boundary regression above.
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDyOffset,
            12));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0));

        Assert.Equal(GraphicsRasterOperations.Success, core.WaitBOVP(viewPort));
        Assert.Equal(viewPort, display.WaitedForViewPort);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 73
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WaitBOVP));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(73, state.Cycles);
        Assert.Equal(viewPort, display.WaitedForViewPort);
    }

    [Fact]
    public void WaitBovpRejectsNullViewPortEvenWhenAddressZeroLooksLikeAnEnvelope()
    {
        var memory = new WrappingMemory();
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);

        // Make page zero look like an assembling ViewPort.  A NULL
        // ViewPort remains an absent display object, so timing admission must
        // not notify the display backend merely because the host maps zero.
        memory.WriteWord(
            (uint)GraphicsLayouts.ViewPortDHeight,
            256);
        memory.WriteWord(
            (uint)GraphicsLayouts.ViewPortDyOffset,
            12);
        memory.WriteByte(
            (uint)GraphicsLayouts.ViewPortExtendedModes,
            0);
        memory.WriteWord(
            (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        memory.WriteLong(
            (uint)GraphicsLayouts.ViewPortRasInfo,
            0);

        Assert.False(GraphicsRasterOperations.ValidateViewPortForScroll(memory, 0));
        Assert.False(GraphicsRasterOperations.ValidateViewPortForWaitBovp(memory, 0));
        Assert.False(GraphicsRasterOperations.ValidateViewPortForModeQuery(memory, 0));
        Assert.Equal(GraphicsRasterOperations.Failure, core.WaitBOVP(0));
        Assert.Equal(0u, display.WaitedForViewPort);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0 },
            D = { [0] = 0xFACE_CAFEu },
            Cycles = 79,
            ProgramCounter = 0x0012_40D1
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WaitBOVP));
        Assert.Equal(0xFACE_CAFEu, state.D[0]);
        Assert.Equal(79, state.Cycles);
        Assert.Equal(0u, display.WaitedForViewPort);
    }

    [Fact]
    public void WaitBovpReadsOnlyTimingFieldsBeforeItsDisplayBoundary()
    {
        (FakeMemory Backing, RangeReadFaultMemory Memory, FakeDisplay Display, GraphicsLibraryCore Core, uint ViewPort) Prepare()
        {
            var backing = new FakeMemory(0x1000);
            var memory = new RangeReadFaultMemory(backing);
            var display = new FakeDisplay();
            var core = CreateCore(memory, display);
            const uint viewPort = 0x180;

            Assert.True(backing.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
                256));
            Assert.True(backing.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortDyOffset,
                12));
            Assert.True(backing.TryWriteByte(
                viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
                0));
            Assert.True(backing.TryWriteLong(
                viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                0));

            // The timing-only wait does not consume DWidth.  A full
            // ViewPort-envelope probe would fault here before reaching the
            // display boundary.
            memory.FailReads(
                viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
                sizeof(ushort));
            return (backing, memory, display, core, viewPort);
        }

        var direct = Prepare();
        Assert.Equal(GraphicsRasterOperations.Success, direct.Core.WaitBOVP(direct.ViewPort));
        Assert.Equal(direct.ViewPort, direct.Display.WaitedForViewPort);
        Assert.Equal(0, direct.Memory.FaultedReadCount);

        var mapped = Prepare();
        var adapter = new CopperStartGraphicsRegisterAdapter(mapped.Core);
        var state = new M68kCpuState
        {
            A = { [0] = mapped.ViewPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 73
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WaitBOVP));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(73, state.Cycles);
        Assert.Equal(mapped.ViewPort, mapped.Display.WaitedForViewPort);
        Assert.Equal(0, mapped.Memory.FaultedReadCount);
    }

    [Fact]
    public void DirectWaitTOFHonorsADecliningStatusSchedulerLikeTheMappedGateway()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FrameWaitStatusDisplay { Accept = false };
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display);

        // The direct compatibility entry must not turn a routing-only
        // status adapter into a fabricated successful wait.
        Assert.Equal(GraphicsRasterOperations.Failure, core.WaitTOF());
        Assert.Equal(1, display.StatusWaitCount);
        Assert.Equal(0, display.LegacyWaitCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 91
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.WaitTOF));
        Assert.Equal(0xA5A5_5A5Au, state.D[0]);
        Assert.Equal(91, state.Cycles);
        Assert.Equal(2, display.StatusWaitCount);

        display.Accept = true;
        Assert.Equal(GraphicsRasterOperations.Success, core.WaitTOF());
        Assert.Equal(3, display.StatusWaitCount);

        state.D[0] = 0x1357_9BDFu;
        state.Cycles = 91;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WaitTOF));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(99, state.Cycles);
        Assert.Equal(4, display.StatusWaitCount);
        Assert.Equal(0, display.LegacyWaitCount);
    }

    [Fact]
    public void LoadViewSkipsMalformedPayloadBehindHiddenViewPortAcrossDirectAndMappedPaths()
    {
        const uint view = 0x100;
        const uint hiddenViewPort = 0x180;
        const uint visibleViewPort = 0x1C0;

        static void BuildHiddenView(FakeMemory memory)
        {
            Assert.True(memory.TryWriteLong(
                view + (uint)GraphicsLayouts.ViewViewPort,
                hiddenViewPort));
            Assert.True(memory.TryWriteWord(
                hiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
                GraphicsModeIds.ViewPortHidden));
            Assert.True(memory.TryWriteLong(
                hiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
                visibleViewPort));
            // Resident traversal never consumes RasInfo for VP_HIDE nodes.
            Assert.True(memory.TryWriteLong(
                hiddenViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                0xFFFF_FFFFu));
            // The native LoadView ownership walk must mirror that same
            // display-time filter.  A foreign/malformed ColorMap on a hidden
            // node is not part of the portable publication envelope and must
            // not block the visible View from being loaded.
            Assert.True(memory.TryWriteLong(
                hiddenViewPort + (uint)GraphicsLayouts.ViewPortColorMap,
                0x001F_FFFEu));
            Assert.True(memory.TryWriteWord(
                visibleViewPort + (uint)GraphicsLayouts.ViewPortModes,
                0));
            Assert.True(memory.TryWriteLong(
                visibleViewPort + (uint)GraphicsLayouts.ViewPortNext,
                0));
            Assert.True(memory.TryWriteLong(
                visibleViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                0));
            Assert.True(memory.TryWriteLong(
                visibleViewPort + (uint)GraphicsLayouts.ViewPortColorMap,
                0));
        }

        var directMemory = new FakeMemory(0x2000);
        BuildHiddenView(directMemory);
        var directDisplay = new FakeDisplay();
        var directCore = new GraphicsLibraryCore(
            directMemory,
            new FakeAllocator(),
            new FakeBlitter(),
            directDisplay);

        Assert.Equal(0, directCore.LoadView(view));
        Assert.Equal(view, directDisplay.PublishedView);
        Assert.Equal(1, directDisplay.PublishCount);
        Assert.Equal(0, directCore.LoadView(view));
        Assert.Equal(1, directDisplay.PublishCount);

        var mappedMemory = new FakeMemory(0x2000);
        BuildHiddenView(mappedMemory);
        var mappedDisplay = new FakeDisplay();
        var mappedCore = new GraphicsLibraryCore(
            mappedMemory,
            new FakeAllocator(),
            new FakeBlitter(),
            mappedDisplay);
        var mappedAdapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 77
        };

        Assert.True(mappedAdapter.TryInvoke(state, (int)GraphicsLvo.LoadView));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(view, mappedDisplay.PublishedView);
        Assert.Equal(1, mappedDisplay.PublishCount);
    }

    [Fact]
    public void LoadViewRejectsOddNativeGraphicsBaseBeforeActiViewProbeAcrossDirectAndOverlayDispatch()
    {
        const uint oddGraphicsBase = 0x0101;
        const uint originalActiveView = 0x0444;

        var directMemory = new FakeMemory(0x2000);
        var directDisplay = new FakeDisplay();
        Assert.True(directMemory.TryWriteLong(
            oddGraphicsBase + (uint)GraphicsLayouts.GfxBaseActiView,
            originalActiveView));
        var directCore = new GraphicsLibraryCore(
            directMemory,
            new FakeAllocator(),
            new FakeBlitter(),
            directDisplay,
            graphicsLibraryBase: oddGraphicsBase);

        Assert.Equal(-1, directCore.LoadView(0));
        Assert.False(directCore.TryPublishNativeDisplayDatabase());
        Assert.Equal(0, directDisplay.PublishCount);
        Assert.Equal(
            originalActiveView,
            ReadLong(directMemory, oddGraphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));

        var overlayMemory = new FakeMemory(0x2000);
        var overlayDisplay = new FakeDisplay();
        Assert.True(overlayMemory.TryWriteLong(
            oddGraphicsBase + (uint)GraphicsLayouts.GfxBaseActiView,
            originalActiveView));
        var overlayCore = new GraphicsLibraryCore(
            overlayMemory,
            new FakeAllocator(),
            new FakeBlitter(),
            overlayDisplay,
            graphicsLibraryBase: oddGraphicsBase);
        var overlayAdapter = new CopperStartGraphicsRegisterAdapter(overlayCore);
        var state = new M68kCpuState
        {
            D = { [0] = 0x1357_9BDFu },
            Cycles = 77
        };

        Assert.False(overlayAdapter.TryInvoke(
            state,
            (int)GraphicsLvo.LoadView,
            nativeOverlay: true));
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(77, state.Cycles);
        Assert.Equal(0, overlayDisplay.PublishCount);
        Assert.Equal(
            originalActiveView,
            ReadLong(overlayMemory, oddGraphicsBase + (uint)GraphicsLayouts.GfxBaseActiView));
    }

