    {
        var bus = new AmigaBus();
        var publishedAddress = 0u;
        var publishedCycle = -1L;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            tryLoadView: state =>
            {
                publishedAddress = state.A[1];
                publishedCycle = state.Cycles;
                return true;
