    [Fact]
    public void ChangeViewPortBitMapPreservesViewportAwareRebuildBoundary()
    {
        var bus = new AmigaBus();
        var genericRebuilds = 0;
        var viewportRebuild = 0u;
        var genericTimedCycle = -1L;
        var viewportTimed = (Address: 0u, Cycle: -1L);
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            requestDisplayRebuild: () => genericRebuilds++,
            requestViewportDisplayRebuild: address => viewportRebuild = address,
            requestDisplayRebuildTimed: cycle => genericTimedCycle = cycle,
            requestViewportDisplayRebuildTimed: (address, cycle) =>
                viewportTimed = (address, cycle));

        var untimed = (IGraphicsViewportBitmapDisplayBackend)services.TimedDisplayBackend;
        untimed.ChangeViewPortBitMap(0x0180, 0x0200, 0);
        Assert.Equal(0x0180u, viewportRebuild);
        Assert.Equal(0, genericRebuilds);

        var timed = (IGraphicsTimedViewportBitmapDisplayBackend)services.TimedDisplayBackend;
        Assert.Equal(
            4321,
            timed.ChangeViewPortBitMap(0x0280, 0x0300, 0, 4321));
        Assert.Equal((0x0280u, 4321L), viewportTimed);
        Assert.Equal(-1, genericTimedCycle);
    }

    [Fact]
    public void LoadViewWalksTheEntireViewPortChainBeforePublishing()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint firstViewPort = 0x180;
        const uint secondViewPort = 0x220;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, firstViewPort);
        memory.TryWriteLong(firstViewPort + (uint)GraphicsLayouts.ViewPortNext, secondViewPort);
        memory.TryWriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        memory.TryWriteWord(firstViewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteWord(secondViewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);

        memory.TryWriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, 0x0FF8);
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);

        memory.TryWriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, firstViewPort);
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void LoadViewLeavesForeignColorMapToAnExplicitDisplayProvider()
    {
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint foreignColorMap = 0x300;

        var directMemory = new FakeMemory(0x1000);
        var directDisplay = new FakeDisplay();
        var directCore = CreateCore(directMemory, directDisplay);
        var directAdapter = new CopperStartGraphicsRegisterAdapter(directCore);
        Assert.True(directMemory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(directMemory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            foreignColorMap));
        Assert.True(directMemory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        Assert.True(directMemory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            320));
        Assert.True(directMemory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256));
        Assert.True(directMemory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0));

        Assert.Equal(-1, directCore.LoadView(view));
        Assert.Equal(0u, directDisplay.PublishedView);

        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 131
        };
        Assert.False(directAdapter.TryInvoke(state, (int)GraphicsLvo.LoadView));
        Assert.Equal(0xA5A5_5A5Au, state.D[0]);
        Assert.Equal(131, state.Cycles);

        // An explicit status-aware display owner remains the handoff point
        // for foreign maps; the native portable fallback is the only path
        // constrained by this registry-ownership check.
        var providerMemory = new FakeMemory(0x1000);
        const uint observedActiveView = 0x400;
        Assert.True(providerMemory.TryWriteLong(observedActiveView, 0));
        var providerDisplay = new StatusViewDisplay(
            providerMemory,
            observedActiveView)
        {
            Accept = true
        };
        var providerCore = new GraphicsLibraryCore(
            providerMemory,
            new BitmapAllocator(),
            new FakeBlitter(),
            providerDisplay);
        Assert.True(providerMemory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(providerMemory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            foreignColorMap));
        Assert.True(providerMemory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        Assert.True(providerMemory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            320));
        Assert.True(providerMemory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256));
        Assert.True(providerMemory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0));

        Assert.Equal(0, providerCore.LoadView(view, 137));
        Assert.Equal(view, providerDisplay.PublishedView);
        Assert.Equal(137, providerDisplay.ObservedCycle);
    }

    [Fact]
    public void LoadViewNullClearsThePublishedViewWithoutTouchingGuestMemory()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x180;

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);

        // NULL disables the current display and does not require a guest
        // View envelope.  The host publication boundary still receives the
        // clear so the guest-compatible ActiView state cannot go stale.
        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(0u, display.PublishedView);
        Assert.Equal(0u, ReadLong(memory, view + (uint)GraphicsLayouts.ViewViewPort));
    }

    [Fact]
    public void LoadViewPublishesOptionalNativeGfxBaseActiveViewLifecycle()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        const uint graphicsBase = 0x7000;
        const uint view = 0x180;
        var activeViewAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView;
        Assert.True(memory.TryWriteLong(activeViewAddress, 0xDEAD_BEEFu));

        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
        Assert.Equal(view, display.PublishedView);

        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(0u, ReadLong(memory, activeViewAddress));
        Assert.Equal(0u, display.PublishedView);

        // A malformed request must leave both the display and the native
        // active-view sidecar on the last successful publication.
        Assert.Equal(-1, core.LoadView(0xFFFC));
        Assert.Equal(0u, ReadLong(memory, activeViewAddress));
        Assert.Equal(0u, display.PublishedView);
    }

    [Fact]
    public void LoadViewPublishesTheAssociatedViewExtraMonitorAndFingerprintsChanges()
    {
        var memory = new FakeMemory(0x10000);
        const uint graphicsBase = 0x7000;
        const uint view = 0x0180;

        var monitorList = graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));

        var allocator = new SteppingAllocator(0x4000);
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.True(memory.TryWriteWord(
            view + (uint)GraphicsLayouts.ViewModes,
            GraphicsModeIds.ExtendedMode));
        Assert.True(core.GfxAssociate(view, viewExtra));

        var palMonitor = core.OpenMonitor(0, 0);
        var ntscMonitor = core.OpenMonitor(0, GraphicsModeIds.NtscMonitor);
        Assert.NotEqual(0u, palMonitor);
        Assert.NotEqual(0u, ntscMonitor);
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor,
            palMonitor));
        const ushort topLine = 17;
        Assert.True(memory.TryWriteWord(
            viewExtra + (uint)GraphicsLayouts.ViewExtraTopLine,
            topLine));
        Assert.Equal(viewExtra, core.GfxLookUp(view));
        Assert.Equal(
            GraphicsModeIds.ExtendedMode,
            ReadWord(memory, view + (uint)GraphicsLayouts.ViewModes));
        Assert.Equal(
            palMonitor,
            ReadLong(memory, viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor));

        var activeViewAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView;
        var currentMonitorAddress = graphicsBase +
                                     (uint)GraphicsLayouts.GfxBaseCurrentMonitor;
        var topLineAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseTopLine;
        Assert.True(memory.TryWriteLong(activeViewAddress, 0xDEAD_BEEFu));
        Assert.True(memory.TryWriteLong(currentMonitorAddress, 0xCAFE_BABEu));
        Assert.True(memory.TryWriteWord(topLineAddress, 0x1234));

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
        Assert.Equal(palMonitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));
        Assert.Equal(1, display.PublishCount);

        // Intuition/CopperStart RethinkDisplay can rebuild the active copper
        // stream without entering GraphicsLibraryCore.LoadView.  Its bounded
        // sidecar refresh must update the native tail without invoking a
        // second display publication.
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor,
            ntscMonitor));
        Assert.True(memory.TryWriteWord(
            viewExtra + (uint)GraphicsLayouts.ViewExtraTopLine,
            topLine + 1));
        Assert.True(memory.TryWriteLong(currentMonitorAddress, 0xABCD_1234u));
        Assert.True(memory.TryWriteWord(topLineAddress, 0x4321));
        Assert.True(core.TryRefreshNativeViewSidecars(view));
        Assert.Equal(ntscMonitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine + 1, ReadWord(memory, topLineAddress));
        Assert.Equal(1, display.PublishCount);

        // The same View pointer is not idempotent when its associated
        // ViewExtra selects a different monitor.  The monitor pointer is part
        // of the display-topology fingerprint and is republished atomically.
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor,
            ntscMonitor));
        Assert.True(memory.TryWriteWord(
            viewExtra + (uint)GraphicsLayouts.ViewExtraTopLine,
            topLine + 1));
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
        Assert.Equal(ntscMonitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine + 1, ReadWord(memory, topLineAddress));
        Assert.Equal(2, display.PublishCount);

        // Clearing the active View must relinquish the optional native tail
        // that this graphics instance published, not leave monitor timing
        // from the retired View visible to a later native caller.
        Assert.Equal(graphicsBase, core.RebindGraphicsLibraryBase(graphicsBase));
        Assert.True(core.TryClearNativeViewSidecars());
        Assert.Equal(0u, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(0, ReadWord(memory, topLineAddress));
        Assert.Equal(2, display.PublishCount);
        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(0u, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(0, ReadWord(memory, topLineAddress));
        Assert.Equal(3, display.PublishCount);

        // A later native/provider handoff may replace the tail fields while
        // this View is still active.  Teardown must preserve that replacement
        // instead of treating the old portable publication as authoritative.
        Assert.Equal(0, core.LoadView(view));
        const uint providerMonitor = 0x5AA5_3300u;
        const ushort providerTopLine = 0x5678;
        Assert.True(memory.TryWriteLong(currentMonitorAddress, providerMonitor));
        Assert.True(memory.TryWriteWord(topLineAddress, providerTopLine));
        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(providerMonitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(providerTopLine, ReadWord(memory, topLineAddress));
        Assert.Equal(5, display.PublishCount);
    }

    [Fact]
    public void NativeViewSidecarClearLeavesMalformedGfxBaseWithProvider()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        const uint graphicsBase = 0x7000;
        const uint view = 0x0180;
        const ushort topLine = 17;
        var monitorList = graphicsBase +
                          (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));

        var currentMonitorAddress = graphicsBase +
                                     (uint)GraphicsLayouts.GfxBaseCurrentMonitor;
        var topLineAddress = graphicsBase +
                             (uint)GraphicsLayouts.GfxBaseTopLine;
        var core = new GraphicsLibraryCore(
            memory,
            new SteppingAllocator(0x4000),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);
        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.True(memory.TryWriteWord(
            view + (uint)GraphicsLayouts.ViewModes,
            GraphicsModeIds.ExtendedMode));
        Assert.True(core.GfxAssociate(view, viewExtra));
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor,
            monitor));
        Assert.True(memory.TryWriteWord(
            viewExtra + (uint)GraphicsLayouts.ViewExtraTopLine,
            topLine));

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));

        // A provider may replace the native MonitorList envelope while the
        // sidecar values happen to remain unchanged.  The portable teardown
        // must relinquish ownership instead of clearing those values.
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            1));
        Assert.True(core.TryRefreshNativeViewSidecars(view));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(core.TryClearNativeViewSidecars());
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));
        Assert.Equal(1, display.PublishCount);
    }

    [Fact]
    public void LoadViewClearsOwnedMonitorSidecarsWhenSwitchingToAPlainView()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        const uint graphicsBase = 0x7000;
        const uint extendedView = 0x0180;
        const uint plainView = 0x0240;
        const ushort topLine = 17;
        var monitorList = graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));
        var currentMonitorAddress = graphicsBase +
                                    (uint)GraphicsLayouts.GfxBaseCurrentMonitor;
        var topLineAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseTopLine;
        var core = new GraphicsLibraryCore(
            memory,
            new SteppingAllocator(0x4000),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.True(memory.TryWriteWord(
            extendedView + (uint)GraphicsLayouts.ViewModes,
            GraphicsModeIds.ExtendedMode));
        Assert.True(core.GfxAssociate(extendedView, viewExtra));
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor,
            monitor));
        Assert.True(memory.TryWriteWord(
            viewExtra + (uint)GraphicsLayouts.ViewExtraTopLine,
            topLine));

        Assert.Equal(0, core.LoadView(extendedView));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));

        // The sidecar-only rethink seam still owns the same native admission
        // boundary as LoadView. An odd View must not be interpreted through
        // shifted bytes and accidentally clear the committed monitor timing.
        Assert.False(core.TryRefreshNativeViewSidecars(extendedView + 1u));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));

        // Intuition's RethinkDisplay path can publish the next View without
        // entering LoadView. Its sidecar refresh must retire the same owned
        // monitor timing without queuing a duplicate display publication.
        Assert.True(core.TryRefreshNativeViewSidecars(plainView));
        Assert.Equal(0u, ReadLong(memory, currentMonitorAddress));
        Assert.Equal((ushort)0, ReadWord(memory, topLineAddress));
        Assert.Equal(1, display.PublishCount);

        // The refresh retired the portable claim.  If a provider now writes
        // the same values that the old extended View used, a later blanking
        // request must still preserve them rather than trusting stale
        // ownership metadata and clearing the fields.
        Assert.True(memory.TryWriteLong(currentMonitorAddress, monitor));
        Assert.True(memory.TryWriteWord(topLineAddress, topLine));
        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));

        Assert.Equal(0, core.LoadView(extendedView));
        // This instance owns both values from the extended View.  A later
        // plain View has no ViewExtra sidecar and must not inherit monitor
        // timing from the retired view.
        Assert.Equal(0, core.LoadView(plainView));
        Assert.Equal(0u, ReadLong(memory, currentMonitorAddress));
        Assert.Equal((ushort)0, ReadWord(memory, topLineAddress));
        Assert.Equal(plainView, display.PublishedView);

        // A provider may take over the sidecar after the extended View was
        // published.  That replacement is not this instance's state to
        // clear when the next plain View becomes active.
        Assert.Equal(0, core.LoadView(extendedView));
        const uint providerMonitor = 0x5AA5_3300u;
        const ushort providerTopLine = 0x5678;
        Assert.True(memory.TryWriteLong(currentMonitorAddress, providerMonitor));
        Assert.True(memory.TryWriteWord(topLineAddress, providerTopLine));
        Assert.Equal(0, core.LoadView(plainView));
        Assert.Equal(providerMonitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(providerTopLine, ReadWord(memory, topLineAddress));

        // Timed LoadView uses the same ownership transaction.  It must not
        // retain monitor timing from the retired extended View merely because
        // the display publication is scheduled at a cycle boundary.
        Assert.Equal(0, core.LoadView(extendedView, 211));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(topLine, ReadWord(memory, topLineAddress));
        Assert.Equal(0, core.LoadView(plainView, 223));
        Assert.Equal(0u, ReadLong(memory, currentMonitorAddress));
        Assert.Equal((ushort)0, ReadWord(memory, topLineAddress));
    }

    [Fact]
    public void LoadViewRestoresCurrentMonitorWhenTheDisplayOwnerDeclines()
    {
        var memory = new FakeMemory(0x10000);
        const uint graphicsBase = 0x7000;
        const uint view = 0x0180;
        const uint monitor = 0x5000;
        const uint originalActiveView = 0xDEAD_BEEFu;
        const uint originalCurrentMonitor = 0xCAFE_BABEu;
        const ushort originalTopLine = 0x1234;
        const ushort requestedTopLine = 29;

        var monitorList = graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));

        var allocator = new SteppingAllocator(0x4000);
        var activeViewAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView;
        var currentMonitorAddress = graphicsBase +
                                     (uint)GraphicsLayouts.GfxBaseCurrentMonitor;
        var topLineAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseTopLine;
        Assert.True(memory.TryWriteLong(activeViewAddress, originalActiveView));
        Assert.True(memory.TryWriteLong(currentMonitorAddress, originalCurrentMonitor));
        Assert.True(memory.TryWriteWord(topLineAddress, originalTopLine));

        var display = new StatusViewDisplay(memory, activeViewAddress)
        {
            Accept = false
        };
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);
        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.True(memory.TryWriteWord(
            view + (uint)GraphicsLayouts.ViewModes,
            GraphicsModeIds.ExtendedMode));
        Assert.True(core.GfxAssociate(view, viewExtra));
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraMonitor,
            monitor));
        Assert.True(memory.TryWriteWord(
            viewExtra + (uint)GraphicsLayouts.ViewExtraTopLine,
            requestedTopLine));

        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(view, display.ObservedActiveView);
        Assert.Equal(originalActiveView, ReadLong(memory, activeViewAddress));
        Assert.Equal(
            originalCurrentMonitor,
            ReadLong(memory, currentMonitorAddress));
        Assert.Equal(originalTopLine, ReadWord(memory, topLineAddress));
        Assert.Equal(0u, display.PublishedView);

        display.Accept = true;
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(requestedTopLine, ReadWord(memory, topLineAddress));
        Assert.Equal(view, display.PublishedView);

        // A status-aware owner can decline a blank handoff.  The active View
        // and both native tail fields must remain coherent until it accepts.
        display.Accept = false;
        Assert.Equal(-1, core.LoadView(0));
        Assert.Equal(view, display.PublishedView);
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(requestedTopLine, ReadWord(memory, topLineAddress));

        display.Accept = true;
        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(0u, display.PublishedView);
        Assert.Equal(0u, ReadLong(memory, activeViewAddress));
        Assert.Equal(0u, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(0, ReadWord(memory, topLineAddress));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 91
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.LoadView));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(91, state.Cycles);
        Assert.Equal(monitor, ReadLong(memory, currentMonitorAddress));
        Assert.Equal(requestedTopLine, ReadWord(memory, topLineAddress));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void LoadViewPublishesNativeActiveViewBeforeStatusAwareDisplayHandoff()
    {
        var memory = new FakeMemory(0x10000);
        const uint graphicsBase = 0x7000;
        const uint view = 0x180;
        const uint originalView = 0xDEAD_BEEFu;
        var activeViewAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView;
        Assert.True(memory.TryWriteLong(activeViewAddress, originalView));

        var display = new StatusViewDisplay(memory, activeViewAddress)
        {
            Accept = false
        };
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        // The display owner observes the new ActiView while deciding whether
        // it can queue the hardware handoff.  A decline must restore the
        // previous sidecar and leave the display publication unchanged.
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(view, display.ObservedActiveView);
        Assert.Equal(originalView, ReadLong(memory, activeViewAddress));
        Assert.Equal(0u, display.PublishedView);

        display.Accept = true;
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, display.ObservedActiveView);
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void LoadViewRestoresNativeActiveViewAfterPartialCommitPublication()
    {
        var backing = new FakeMemory(0x10000);
        const uint graphicsBase = 0x7000;
        const uint view = 0x180;
        const uint activeViewAddress = graphicsBase +
                                       (uint)GraphicsLayouts.GfxBaseActiView;
        const uint originalView = 0xCAFE_BABEu;
        Assert.True(backing.TryWriteLong(activeViewAddress, originalView));

        var memory = new ProbeThenPartialLongWriteMemory(backing)
        {
            PartialLongAddress = activeViewAddress
        };
        var display = new StatusViewDisplay(backing, activeViewAddress)
        {
            Accept = true
        };
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        // The first write is the same-value writability probe. The commit
        // then partially publishes the requested View and rejects the LONG;
        // byte-wise rollback must restore the complete original sidecar.
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(originalView, ReadLong(backing, activeViewAddress));
        Assert.Equal(0u, display.PublishedView);

        memory.PartialLongAddress = null;
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, ReadLong(backing, activeViewAddress));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void TimedLoadViewPublishesNativeActiveViewBeforeDisplayHandoff()
    {
        var memory = new FakeMemory(0x10000);
