        Assert.Equal(view, display.ObservedActiveView);
        Assert.Equal(1234, display.ObservedCycle);
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
    }

    [Fact]
    public void RepeatedLoadViewRepairsAnEditedNativeGfxBaseActiveViewWithoutRepublishing()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        const uint graphicsBase = 0x7000;
        const uint view = 0x180;
        var activeViewAddress = graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView;
        Assert.True(memory.TryWriteLong(activeViewAddress, 0xDEAD_BEEFu));

        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);
        Assert.Equal(view, ReadLong(memory, activeViewAddress));

        // A native caller may have changed the public sidecar while the
        // display owner still has the same validated View.  The idempotent
        // path repairs the pointer but must not rebuild or queue the stream.
        Assert.True(memory.TryWriteLong(activeViewAddress, 0xCAFE_BABEu));
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);
        Assert.Equal(view, ReadLong(memory, activeViewAddress));
    }

