    [Fact]
    public void LoadViewDoesNotRepublishTheAlreadyActiveView()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x180;

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);

        // The native lifecycle compares the requested View pointer with the
        // active one before rebuilding or re-queueing its display stream.
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);

        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(2, display.PublishCount);
        Assert.Equal(0, core.LoadView(0));
        Assert.Equal(2, display.PublishCount);
    }

    [Fact]
    public void LoadViewRepublishesWhenTheActiveBitmapPlaneLinkChanges()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x220;
        const uint bitMap = 0x260;
        const uint firstPlane = 0x400;
        const uint secondPlane = 0x500;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, firstPlane);
        memory.TryWriteByte(firstPlane, 0xF0);
        memory.TryWriteByte(secondPlane, 0x0F);

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);

        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, secondPlane);
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(2, display.PublishCount);
    }

    [Fact]
    public void LoadViewAcceptsAValidMinimalDisplayPlaneAndHashesItsLink()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x600;
        const uint viewPort = 0x620;
        const uint rasInfo = 0x660;
        const uint bitMap = 0x680;
        const uint plane = 0x0FFE;

        Assert.True(core.InitializeView(view));
        Assert.True(core.InitializeViewPort(viewPort));
        Assert.True(core.InitializeRasInfo(rasInfo));
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            16));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            1));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));

        // The display row is exactly two bytes and ends at 0xFFFFFFFF.  A
        // valid LoadView must not require four bytes from pixel storage just
        // to decide whether this already-active View needs republishing.
        Assert.True(memory.TryWriteByte(plane, 0xF0));
        Assert.True(memory.TryWriteByte(plane + 1u, 0x0F));

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);

        // Pixel contents do not change the display topology, so an unchanged
        // plane link remains idempotent even when the row bytes are edited.
        Assert.True(memory.TryWriteByte(plane, 0xAA));
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(1, display.PublishCount);

        // Changing the link is a topology change and must invalidate the
        // signature even though the linked raster remains two bytes wide.
        const uint replacementPlane = 0x400;
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            replacementPlane));
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(2, display.PublishCount);
    }

    [Fact]
    public void LoadViewPublishesPreallocatedCopperResourcesAndRollsBackMalformedEnvelope()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x1200;
        const uint viewPort = 0x1280;
        const uint rasInfo = 0x1300;
        const uint bitMap = 0x1340;
        const uint plane = 0x1380;
        const uint copList = 0x1400;
        const uint rawCopper = 0x1480;
        const uint lofCprList = 0x1500;
        const uint shfCprList = 0x1520;

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewLoFCprList,
            lofCprList));
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewShFCprList,
            shfCprList));

        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
            copList));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortSprIns,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortClrIns,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortUCopIns,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            320));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDxOffset,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDyOffset,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            0));
        Assert.True(memory.TryWriteByte(
            viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));

        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
            0));
        Assert.True(memory.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
            0));

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        Assert.True(memory.TryWriteByte(plane, 0xA5));

        Assert.True(memory.TryWriteLong(
            copList + (uint)GraphicsLayouts.CopListViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            copList + (uint)GraphicsLayouts.CopListCopPtr,
            rawCopper));
        Assert.True(memory.TryWriteLong(
            copList + (uint)GraphicsLayouts.CopListCopLStart,
            rawCopper));
        Assert.True(memory.TryWriteLong(
            copList + (uint)GraphicsLayouts.CopListCopSStart,
            rawCopper));
        Assert.True(memory.TryWriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            0));
        Assert.True(memory.TryWriteWord(
            copList + (uint)GraphicsLayouts.CopListMaxCount,
            1));
        Assert.True(memory.TryWriteWord(rawCopper, GraphicsLayouts.CopperEndWait));
        Assert.True(memory.TryWriteWord(
            rawCopper + sizeof(ushort),
            GraphicsLayouts.CopperEndMask));

        foreach (var cprList in new[] { lofCprList, shfCprList })
        {
            Assert.True(memory.TryWriteLong(
                cprList + (uint)GraphicsLayouts.CprListNext,
                0));
            Assert.True(memory.TryWriteLong(
                cprList + (uint)GraphicsLayouts.CprListStart,
                rawCopper));
            Assert.True(memory.TryWriteWord(
                cprList + (uint)GraphicsLayouts.CprListMaxCount,
                1));
        }

        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
        Assert.Equal(1, display.PublishCount);

        // A malformed preallocated list must be rejected before the display
        // owner is called, preserving the already-active publication.
        Assert.True(memory.TryWriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            1));
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
        Assert.Equal(1, display.PublishCount);

        Assert.True(memory.TryWriteWord(
            copList + (uint)GraphicsLayouts.CopListCount,
            0));
        Assert.True(memory.TryWriteLong(
            shfCprList + (uint)GraphicsLayouts.CprListStart,
            rawCopper + sizeof(ushort)));
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
        Assert.Equal(1, display.PublishCount);
    }

    [Fact]
    public void LoadViewRejectsAPresentMalformedRasInfoBitMapBeforePublishing()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x220;
        const uint bitMap = 0x260;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);

        // A present bitmap link with zero geometry is malformed.
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);

        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.Equal(-1, core.LoadView(view));
