        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x400));
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void LoadViewRejectsAliasedViewAndRasInfoEnvelopesBeforePublishing()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        // This RasInfo starts inside the public View envelope.  Its fields
        // remain individually readable, but LoadView must not claim a chain
        // whose later display traversal could overwrite the root View.
        const uint aliasedRasInfo = 0x108;

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewLoFCprList,
            0));
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewShFCprList,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            320));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            200));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDxOffset,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDyOffset,
            0));
        Assert.True(memory.TryWriteByte(
            viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortDspIns,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortSprIns,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortClrIns,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortUCopIns,
            0));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            aliasedRasInfo));

        // The aliased node itself is a readable, otherwise-empty RasInfo.
        // Writing its fields also edits View's CPR links, which are legal
        // NULL values; only the envelope alias is malformed here.
        Assert.True(memory.TryWriteLong(
            aliasedRasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            aliasedRasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            0));
        Assert.True(memory.TryWriteWord(
            aliasedRasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
            0));
        Assert.True(memory.TryWriteWord(
            aliasedRasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
            0));

        Assert.Equal(GraphicsRasterOperations.Failure, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);
    }

    [Fact]
    public void LoadViewRejectsViewAliasingNativeGfxBasePublicationEnvelope()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay();
        const uint graphicsBase = 0x400;
        const uint view = graphicsBase;
        const uint viewPort = 0x800;
        const uint originalActiveView = 0xDEAD_BEEFu;
        var monitorList = graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            display,
            graphicsLibraryBase: graphicsBase);

        // The View is readable and otherwise displayable, but its envelope
        // starts at the native GfxBase.  LoadView must decline before the
        // ActiView/sidecar transaction can write through that alias.
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            320));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            1));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView,
            originalActiveView));

        Assert.Equal(GraphicsRasterOperations.Failure, core.LoadView(view));
        Assert.True(memory.TryReadLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView,
            out var activeView));
        Assert.Equal(
            originalActiveView,
            activeView);
        Assert.Equal(0u, display.PublishedView);
    }

    [Fact]
    public void LoadViewRejectsAnExtraRasInfoPlayfieldBeforePublishing()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint firstRasInfo = 0x220;
        const uint secondRasInfo = 0x280;
        const uint unexpectedThirdRasInfo = 0x2E0;
        const uint bitMap = 0x340;
        const uint plane = 0x400;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.DualPlayfieldMode);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
        memory.TryWriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, secondRasInfo);
        memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, unexpectedThirdRasInfo);
        memory.TryWriteLong(unexpectedThirdRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);

        foreach (var rasInfo in new[] { firstRasInfo, secondRasInfo, unexpectedThirdRasInfo })
        {
            memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
            memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
            memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        }

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);

        // Every node and its display bitmap is readable.  The only malformed
        // state is the third DUALPF RasInfo, so LoadView must decline before
        // replacing the active display publication.
        Assert.Equal(GraphicsRasterOperations.Failure, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);

        memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        Assert.Equal(GraphicsRasterOperations.Success, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void LoadViewRejectsDisplayPlaneStorageThatFallsOutsideGuestMemory()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x220;
        const uint bitMap = 0x260;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        // The first row is readable, but the second row crosses the end of
        // the guest memory envelope.  LoadView must reject before publishing.
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x1FFF);

        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);
    }

    [Fact]
    public void LoadViewRejectsNonWordAlignedDisplayBitmapRowsAndPlanes()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x220;
        const uint bitMap = 0x260;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortNext, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x400);

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 3);
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);

        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x401);
        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);

        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, 0x400);
        Assert.Equal(0, core.LoadView(view));
        Assert.Equal(view, display.PublishedView);
    }

    [Fact]
    public void MakeVPortAndMrgCopValidateGuestStructuresBeforeCallingCopperBoundary()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);

        Assert.Equal(0, core.MakeViewPort(view, viewPort));
        Assert.Equal(view, display.MadeView);
        Assert.Equal(viewPort, display.MadeViewPort);
        Assert.Equal(1, display.MakeCount);
        Assert.Equal(0, core.MergeCopperLists(view));
        Assert.Equal(view, display.MergedView);
        Assert.Equal(1, display.StatusMergeCount);

        Assert.Equal(GraphicsViewportStatuses.NoViewPortExtra, core.MakeViewPort(0xFFF8, viewPort));
        Assert.Equal(-1, core.MergeCopperLists(0xFFF8));
        Assert.Equal(1, display.MakeCount);
        Assert.Equal(1, display.StatusMergeCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { A = { [0] = 0xFFF8, [1] = viewPort } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.MakeVPort));
        Assert.Equal((uint)GraphicsViewportStatuses.NoViewPortExtra, state.D[0]);
    }

    [Fact]
    public void MakeVPortRejectsViewPortAndRasInfoAliasesBeforeCopperPublication()
    {
        static void WriteAssembledView(
            FakeMemory memory,
            uint view,
            uint viewPort,
            uint rasInfo,
            uint bitMap)
        {
            Assert.True(memory.TryWriteLong(
                view + (uint)GraphicsLayouts.ViewViewPort,
                viewPort));
            Assert.True(memory.TryWriteLong(
                viewPort + (uint)GraphicsLayouts.ViewPortNext,
                0));
            Assert.True(memory.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
                320));
            Assert.True(memory.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
                200));
            Assert.True(memory.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortDxOffset,
                0));
            Assert.True(memory.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortDyOffset,
                0));
            Assert.True(memory.TryWriteWord(
                viewPort + (uint)GraphicsLayouts.ViewPortModes,
                0));
            Assert.True(memory.TryWriteByte(
                viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
                0));
            Assert.True(memory.TryWriteLong(
                viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                rasInfo));
            Assert.True(memory.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoNext,
                0));
            Assert.True(memory.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
                bitMap));
            Assert.True(memory.TryWriteWord(
                rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
                0));
            Assert.True(memory.TryWriteWord(
                rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
                0));
        }

        var aliasedViewPortMemory = new FakeMemory(0x4000);
        var aliasedViewPortDisplay = new FakeDisplay();
        var aliasedViewPortCore = CreateCore(
            aliasedViewPortMemory,
            aliasedViewPortDisplay);
        const uint view = 0x100;
        const uint aliasedViewPort = 0x110;
        const uint rasInfo = 0x180;
        const uint bitMap = 0x240;
        WriteAssembledView(
            aliasedViewPortMemory,
            view,
            aliasedViewPort,
            rasInfo,
            bitMap);

        Assert.Equal(
            GraphicsViewportStatuses.NoDisplay,
            aliasedViewPortCore.MakeViewPort(view, aliasedViewPort));
        Assert.Equal(GraphicsRasterOperations.Failure, aliasedViewPortCore.MergeCopperLists(view));
        Assert.Equal(0, aliasedViewPortDisplay.MakeCount);
        Assert.Equal(0, aliasedViewPortDisplay.StatusMergeCount);
        Assert.Equal(0u, aliasedViewPortDisplay.MadeView);

        var aliasedRasInfoMemory = new FakeMemory(0x4000);
        var aliasedRasInfoDisplay = new FakeDisplay();
        var aliasedRasInfoCore = CreateCore(
            aliasedRasInfoMemory,
            aliasedRasInfoDisplay);
        const uint nonAliasedViewPort = 0x180;
        const uint aliasedRasInfo = 0x108;
        WriteAssembledView(
            aliasedRasInfoMemory,
            view,
            nonAliasedViewPort,
            aliasedRasInfo,
            bitMap);

        Assert.Equal(
            GraphicsViewportStatuses.NoDisplay,
            aliasedRasInfoCore.MakeViewPort(view, nonAliasedViewPort));
        Assert.Equal(GraphicsRasterOperations.Failure, aliasedRasInfoCore.MergeCopperLists(view));
        Assert.Equal(0, aliasedRasInfoDisplay.MakeCount);
        Assert.Equal(0, aliasedRasInfoDisplay.StatusMergeCount);
        Assert.Equal(0u, aliasedRasInfoDisplay.MadeView);

        var aliasedBitMapMemory = new FakeMemory(0x4000);
        var aliasedBitMapDisplay = new FakeDisplay();
        var aliasedBitMapCore = CreateCore(
            aliasedBitMapMemory,
            aliasedBitMapDisplay);
        const uint aliasedBitMapRasInfo = 0x1C0;
        const uint aliasedBitMap = 0x108;
        WriteAssembledView(
            aliasedBitMapMemory,
            view,
            nonAliasedViewPort,
            aliasedBitMapRasInfo,
            aliasedBitMap);

        Assert.Equal(
            GraphicsViewportStatuses.NoDisplay,
            aliasedBitMapCore.MakeViewPort(view, nonAliasedViewPort));
        Assert.Equal(GraphicsRasterOperations.Failure, aliasedBitMapCore.MergeCopperLists(view));
        Assert.Equal(0, aliasedBitMapDisplay.MakeCount);
        Assert.Equal(0, aliasedBitMapDisplay.StatusMergeCount);
        Assert.Equal(0u, aliasedBitMapDisplay.MadeView);
    }

    [Fact]
    public void MrgCopRejectsNullViewBeforeAZeroPageEnvelopeCanReachCopper()
    {
        var memory = new WrappingMemory();
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);

        // Populate a plausible page-zero View header.  The zero address is
        // still the public NULL sentinel; the shared guest-range envelope
        // must reject it before MrgCop can inspect the link or notify a
        // copper/display owner.
        for (var offset = 0; offset < GraphicsLayouts.ViewSize; offset++)
            memory.WriteByte((uint)offset, 0);
        memory.WriteLong(
            (uint)GraphicsLayouts.ViewViewPort,
            0x100);
        memory.WriteWord(0x100u + (uint)GraphicsLayouts.ViewPortModes, 0);
        memory.WriteLong(0x100u + (uint)GraphicsLayouts.ViewPortNext, 0);
        memory.WriteLong(
            0x100u + (uint)GraphicsLayouts.ViewPortRasInfo,
            0x180);
        for (var offset = 0; offset < GraphicsLayouts.RasInfoSize; offset++)
            memory.WriteByte(0x180u + (uint)offset, 0);

        Assert.Equal(GraphicsRasterOperations.Failure, core.MergeCopperLists(0));
        Assert.Equal(0, display.MergeCount);
        Assert.Equal(0, display.StatusMergeCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 719
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.MrgCop));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(719, state.Cycles);
        Assert.Equal(0, display.MergeCount);
        Assert.Equal(0, display.StatusMergeCount);
    }

    [Fact]
    public void VideoControlBatchItemsAppendAndReplayAtMakeVPort()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display, new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;
        const uint existingItems = 0x800;
        const uint addedItems = 0x840;
        const uint controlTags = 0x900;

        WriteTag(memory, existingItems, 0x8000_0005, 1); // BORDERBLANK_SET
        WriteTag(memory, existingItems + 8, 0, 0); // TAG_END
        WriteTag(memory, addedItems, 0x8000_0007, 1); // BORDERNOTRANS_SET
        WriteTag(memory, addedItems + 8, 0, 0); // TAG_END

        WriteTag(memory, controlTags, 0x8000_001E, existingItems); // BATCH_ITEMS_SET
        WriteTag(memory, controlTags + 8, 0x8000_001F, addedItems); // BATCH_ITEMS_ADD
        WriteTag(memory, controlTags + 16, 0, 0);
        Assert.True(core.VideoControl(colorMap, controlTags));
        Assert.Equal(existingItems, ReadLong(
            memory,
            colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));
        Assert.Equal(2u, ReadLong(memory, existingItems + 8)); // TAG_MORE
        Assert.Equal(addedItems, ReadLong(memory, existingItems + 12));

        WriteTag(memory, controlTags, 0x8000_000E, 1); // BATCH_CM_SET
        WriteTag(memory, controlTags + 8, 0, 0);
        Assert.True(core.VideoControl(colorMap, controlTags));
        Assert.Equal(
            (byte)0x10,
            (byte)(ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags) & 0x10));

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        Assert.Equal(
            (byte)0x0C,
            (byte)(ReadByte(memory, colorMap + (uint)GraphicsLayouts.ColorMapFlags) & 0x0C));
        Assert.Equal(1, display.MakeCount);
    }

    [Fact]
    public void VideoControlBatchAppendHonorsTagSkipBeforeFindingTheTerminalItem()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint existingItems = 0x800;
        const uint addedItems = 0x840;
        const uint controlTags = 0x900;

        WriteTag(memory, existingItems, 3, 1); // TAG_SKIP.
        WriteTag(memory, existingItems + 8, 0x8000_0005, 1); // skipped.
        WriteTag(memory, existingItems + 16, 0x8000_0007, 1); // retained.
        WriteTag(memory, existingItems + 24, 0, 0); // terminal item.
        WriteTag(memory, addedItems, 0x8000_0005, 1);
        WriteTag(memory, addedItems + 8, 0, 0);

        WriteTag(memory, controlTags, 0x8000_001E, existingItems); // SET.
        WriteTag(memory, controlTags + 8, 0x8000_001F, addedItems); // ADD.
        WriteTag(memory, controlTags + 16, 0, 0);

        Assert.True(core.VideoControl(colorMap, controlTags));
        Assert.Equal(2u, ReadLong(memory, existingItems + 24)); // TAG_MORE.
        Assert.Equal(addedItems, ReadLong(memory, existingItems + 28));
    }

    [Fact]
    public void VideoControlRejectsMalformedBatchAppendBeforePublishingTheHead()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint controlTags = 0x900;
        const uint malformedExistingItems = 0x1FFC;
        const uint addedItems = 0xA00;

        // The existing list exposes only its tag word; the data word lies
        // outside guest memory. SET must not publish the head if ADD cannot
        // safely locate the terminal slot.
        Assert.True(memory.TryWriteLong(malformedExistingItems, 0x8000_0005));
        WriteTag(memory, addedItems, 0, 0);
        WriteTag(memory, controlTags, 0x8000_001E, malformedExistingItems); // SET
        WriteTag(memory, controlTags + 8, 0x8000_001F, addedItems); // ADD
        WriteTag(memory, controlTags + 16, 0, 0);

        Assert.False(core.VideoControl(colorMap, controlTags));
        Assert.Equal(
            0u,
            ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));
    }

    [Fact]
    public void VideoControlRejectsMalformedAddedBatchBeforeLinkingIt()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint controlTags = 0x900;
        const uint existingItems = 0x800;
        const uint malformedAddedItems = 0x1FFC;

        WriteTag(memory, existingItems, 0, 0); // TAG_END
        Assert.True(memory.TryWriteLong(malformedAddedItems, 0x8000_0005));
        WriteTag(memory, controlTags, 0x8000_001E, existingItems); // SET
        WriteTag(memory, controlTags + 8, 0x8000_001F, malformedAddedItems); // ADD
        WriteTag(memory, controlTags + 16, 0, 0);

        Assert.False(core.VideoControl(colorMap, controlTags));
        Assert.Equal(
            0u,
            ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));
        Assert.Equal(0u, ReadLong(memory, existingItems));
    }

    [Fact]
    public void VideoControlRejectsOddOrTruncatedBatchAndAttachmentPointersAtomically()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint controlTags = 0x900;
        const uint viewPort = 0x300;

        WriteTag(memory, controlTags, 0x8000_001E, 0x801); // odd BATCH_ITEMS_SET
        WriteTag(memory, controlTags + 8, 0, 0);
        Assert.False(core.VideoControl(colorMap, controlTags));
        Assert.Equal(
            0u,
            ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));

        Assert.True(memory.TryWriteLong(0x1FFC, 0x8000_0005));
        WriteTag(memory, controlTags, 0x8000_001E, 0x1FFC); // data word truncated
        WriteTag(memory, controlTags + 8, 0, 0);
        Assert.False(core.VideoControl(colorMap, controlTags));
        Assert.Equal(
            0u,
            ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));

        WriteTag(memory, controlTags, 0x8000_000B, viewPort | 1u); // odd viewport
        WriteTag(memory, controlTags + 8, 0, 0);
        Assert.False(core.VideoControl(colorMap, controlTags));
        Assert.Equal(
            0u,
            ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapViewPort));
    }

    [Fact]
    public void VideoControlBatchItemsSetNullClearsTheStaticList()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory, allocator: new BitmapAllocator());
        var colorMap = core.GetColorMap(2);
        const uint controlTags = 0x900;
        const uint items = 0xA00;

        WriteTag(memory, items, 0, 0); // TAG_END
        WriteTag(memory, controlTags, 0x8000_001E, items); // SET
        WriteTag(memory, controlTags + 8, 0, 0);
        Assert.True(core.VideoControl(colorMap, controlTags));
        Assert.Equal(items, ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));

        WriteTag(memory, controlTags, 0x8000_001E, 0); // null SET clears
        WriteTag(memory, controlTags + 8, 0, 0);
        Assert.True(core.VideoControl(colorMap, controlTags));
        Assert.Equal(0u, ReadLong(memory, colorMap + (uint)GraphicsLayouts.ColorMapBatchItems));
    }

    [Fact]
    public void MakeVPortAcquiresAndReusesAViewPortExtraAssociation()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        Assert.True(memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo));
        Assert.True(memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0));
        Assert.True(memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        var firstExtra = core.GfxLookUp(viewPort);
        Assert.NotEqual(0u, firstExtra);
        Assert.Equal(
            viewPort,
            ReadLong(memory, firstExtra + (uint)GraphicsLayouts.ViewPortExtraViewPort));
        Assert.Equal(
            (ushort)1,
            ReadWord(memory, firstExtra + (uint)GraphicsLayouts.ViewPortExtraFlags));
        Assert.Empty(allocator.Freed);

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        Assert.Equal(firstExtra, core.GfxLookUp(viewPort));
        Assert.Empty(allocator.Freed);

        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        Assert.Equal(0u, core.GfxLookUp(viewPort));
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == firstExtra &&
                          allocation.Bytes == GraphicsLayouts.ViewPortExtraSize);
    }

    [Fact]
    public void GfxAssociateRestoresTemporaryFreeMeFlagAfterARejectedPartialWordWrite()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        Assert.True(backing.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort));
        Assert.True(backing.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo));
        Assert.True(backing.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0));
        Assert.True(backing.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4));
        Assert.True(backing.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        var temporaryExtra = core.GfxLookUp(viewPort);
        Assert.NotEqual(0u, temporaryExtra);
        var flagsAddress = temporaryExtra + (uint)GraphicsLayouts.ViewPortExtraFlags;
        memory.PartialWordAddress = flagsAddress;

        Assert.False(core.GfxAssociate(viewPort, temporaryExtra));
        Assert.Equal((ushort)1, ReadWord(backing, flagsAddress));
        Assert.Equal(temporaryExtra, core.GfxLookUp(viewPort));

        memory.PartialWordAddress = null;
        Assert.True(core.GfxAssociate(viewPort, temporaryExtra));
        Assert.Equal((ushort)0, ReadWord(backing, flagsAddress));
        Assert.Equal(temporaryExtra, core.GfxLookUp(viewPort));
    }

    [Fact]
    public void GfxAssociateLeavesTemporaryFreeMeFlagUntouchedWhenItCannotReadIt()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RejectingWordReadMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        Assert.True(backing.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort));
        Assert.True(backing.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo));
        Assert.True(backing.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0));
        Assert.True(backing.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4));
        Assert.True(backing.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        var temporaryExtra = core.GfxLookUp(viewPort);
        Assert.NotEqual(0u, temporaryExtra);
        var flagsAddress = temporaryExtra + (uint)GraphicsLayouts.ViewPortExtraFlags;
        memory.RejectWordReadAddress = flagsAddress;

        Assert.False(core.GfxAssociate(viewPort, temporaryExtra));
        Assert.Equal((ushort)1, ReadWord(backing, flagsAddress));
        Assert.Equal(temporaryExtra, core.GfxLookUp(viewPort));

        memory.RejectWordReadAddress = null;
        Assert.True(core.GfxAssociate(viewPort, temporaryExtra));
        Assert.Equal((ushort)0, ReadWord(backing, flagsAddress));
    }

    [Fact]
    public void MakeVPortDoesNotFreeACallerOwnedViewPortExtra()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        Assert.True(memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo));
        Assert.True(memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0));
        Assert.True(memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));

        var callerExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType);
        Assert.NotEqual(0u, callerExtra);
        Assert.True(core.GfxAssociate(viewPort, callerExtra));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        Assert.Equal(callerExtra, core.GfxLookUp(viewPort));
        Assert.DoesNotContain(
            allocator.Freed,
            allocation => allocation.Address == callerExtra);
    }

    [Fact]
    public void GfxAssociateRetriesDisplacedTemporaryViewPortExtraCleanup()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new ProbeThenPartialLongWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        Assert.True(backing.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort));
        Assert.True(backing.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo));
        Assert.True(backing.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0));
        Assert.True(backing.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4));
        Assert.True(backing.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        var temporaryExtra = core.GfxLookUp(viewPort);
        Assert.NotEqual(0u, temporaryExtra);
        var callerExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType);
        Assert.NotEqual(0u, callerExtra);

        memory.PartialLongAddress =
            temporaryExtra + (uint)GraphicsLayouts.ViewPortExtraViewPort;

        // The first write to the displaced node succeeds while Associate
        // moves the viewport to callerExtra; its immediate Free then sees a
        // partial/rejected second write.
        Assert.True(core.GfxAssociate(viewPort, callerExtra));
        Assert.Equal(callerExtra, core.GfxLookUp(viewPort));
        Assert.DoesNotContain(
            allocator.Freed,
            allocation => allocation.Address == temporaryExtra);

        memory.PartialLongAddress = null;
        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        Assert.Contains(
            allocator.Freed,
            allocation => allocation.Address == temporaryExtra &&
                          allocation.Bytes == GraphicsLayouts.ViewPortExtraSize);
        Assert.Equal(callerExtra, core.GfxLookUp(viewPort));
    }

