    [Fact]
    public void MakeVPortRestoresCopperLinksWhenAStatusBuilderPublishesThenFailsAcrossDirectAndMappedPaths()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var display = new FakeDisplayWithMakeStatus
        {
            MakeStatus = GraphicsViewportStatuses.NoDisplayInstructions,
            MutateLinksBeforeReturning = true
        };
        display.MutationMemory = memory;
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var originalLinks = new uint[] { 0x410, 0x510, 0x610, 0x710 };

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        for (var index = 0; index < offsets.Length; index++)
            Assert.True(memory.TryWriteLong(
                viewPort + (uint)offsets[index],
                originalLinks[index]));

        Assert.Equal(
            GraphicsViewportStatuses.NoDisplayInstructions,
            core.MakeViewPort(view, viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(
                originalLinks[index],
                ReadLong(memory, viewPort + (uint)offsets[index]));
        Assert.Equal(0u, core.GfxLookUp(viewPort));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 89
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.MakeVPort));
        Assert.Equal(
            (uint)GraphicsViewportStatuses.NoDisplayInstructions,
            state.D[0]);
        Assert.Equal(89, state.Cycles);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(
                originalLinks[index],
                ReadLong(memory, viewPort + (uint)offsets[index]));
        Assert.Equal(0u, core.GfxLookUp(viewPort));
    }

