    [Fact]
    public void MakeVPortRequiresTheSecondRasInfoForDualPlayfield()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint firstRasInfo = 0x1C0;
        const uint secondRasInfo = 0x220;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.DualPlayfieldMode);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
        memory.TryWriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);

        Assert.Equal(
            GraphicsViewportStatuses.NoDisplay,
            core.MakeViewPort(view, viewPort));
        Assert.Equal(0, display.MakeCount);
        Assert.Equal(0u, core.GfxLookUp(viewPort));

        memory.TryWriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, secondRasInfo);
        memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        memory.TryWriteWord(secondRasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        memory.TryWriteWord(secondRasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        Assert.Equal(1, display.MakeCount);
    }

    [Fact]
    public void MakeVPortRejectsAnExtraRasInfoPlayfieldBeforeCopperPublication()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint firstRasInfo = 0x1C0;
        const uint secondRasInfo = 0x220;
        const uint unexpectedThirdRasInfo = 0x280;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.DualPlayfieldMode);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);

        // The complete chain is readable and non-cyclic.  The failure is
        // specifically the documented DUALPF cardinality violation: a
        // viewport owns one primary and one companion RasInfo, not a third
        // copper playfield.
        memory.TryWriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, secondRasInfo);
        memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, unexpectedThirdRasInfo);
        memory.TryWriteLong(unexpectedThirdRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        foreach (var rasInfo in new[] { firstRasInfo, secondRasInfo, unexpectedThirdRasInfo })
        {
            memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);
            memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
            memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        }

        Assert.Equal(
            GraphicsViewportStatuses.NoDisplay,
            core.MakeViewPort(view, viewPort));
        Assert.Equal(0, display.MakeCount);
        Assert.Equal(0u, core.GfxLookUp(viewPort));
    }

    [Fact]
    public void MrgCopRejectsAnExtraRasInfoPlayfieldBeforeCopperMerge()
    {
        var memory = new FakeMemory(0x10000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint firstRasInfo = 0x1C0;
        const uint secondRasInfo = 0x220;
        const uint unexpectedThirdRasInfo = 0x280;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.DualPlayfieldMode);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
        memory.TryWriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, secondRasInfo);
        memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, unexpectedThirdRasInfo);
        memory.TryWriteLong(unexpectedThirdRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);

        foreach (var rasInfo in new[] { firstRasInfo, secondRasInfo, unexpectedThirdRasInfo })
        {
            memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);
            memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
            memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        }

        Assert.Equal(GraphicsRasterOperations.Failure, core.MergeCopperLists(view));
        Assert.Equal(0, display.MergeCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 127
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.MrgCop));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(127, state.Cycles);
        Assert.Equal(0, display.MergeCount);
    }

    [Fact]
    public void RomOverlayPreservesTheNoDisplayStatusForAnExtraRasInfoPlayfield()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint firstRasInfo = 0x300;
        const uint secondRasInfo = 0x380;
        const uint unexpectedThirdRasInfo = 0x400;
        var image = new byte[0x2000];

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(firstRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(secondRasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(
            unexpectedThirdRasInfo,
            new byte[GraphicsLayouts.RasInfoSize]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.DualPlayfieldMode);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, firstRasInfo);
        bus.WriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, secondRasInfo);
        bus.WriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, unexpectedThirdRasInfo);
        bus.WriteLong(unexpectedThirdRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);

        var makeCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            makeViewPort: _ =>
            {
                makeCalls++;
                return GraphicsViewportStatuses.Ok;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var direct = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 107,
            ProgramCounter = 0x0012_4401
        };
        services.Invoke(direct, (int)GraphicsLvo.MakeVPort);
        Assert.Equal(0, makeCalls);
        Assert.Equal(
            unchecked((uint)GraphicsViewportStatuses.NoDisplay),
            direct.D[0]);
        Assert.Equal(107, direct.Cycles);
        Assert.Equal(0x0012_4401u, direct.ProgramCounter);

        var mapped = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 109,
            ProgramCounter = 0x0012_4403
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.MakeVPort)),
            mapped));
        Assert.Equal(0, makeCalls);
        Assert.Equal(
            unchecked((uint)GraphicsViewportStatuses.NoDisplay),
            mapped.D[0]);
        Assert.Equal(0x0012_4403u, mapped.ProgramCounter);
        Assert.Equal(109, mapped.Cycles);
    }

