    [Fact]
    public void MrgCopSkipsMalformedHiddenViewPortPayloadAcrossDirectAndMappedPaths()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint hiddenViewPort = 0x180;

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            hiddenViewPort));
        Assert.True(memory.TryWriteWord(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortModes,
            0x2000)); // VP_HIDE
        Assert.True(memory.TryWriteLong(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        // Resident MrgCop never consumes this hidden node's RasInfo.  Keep
        // it deliberately malformed to prove the portable validator follows
        // the same public field envelope.
        Assert.True(memory.TryWriteLong(
            hiddenViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0xFFFF_FFFFu));

        Assert.Equal(GraphicsCopperOperations.MergeNoOp, core.MergeCopperLists(view));
        Assert.Equal(0, display.MergeCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xFFFF_FFFFu }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.MrgCop));
        Assert.Equal((uint)GraphicsCopperOperations.MergeNoOp, state.D[0]);
        Assert.Equal(0, display.MergeCount);
    }

    [Fact]
    public void MrgCopPropagatesStatusFromAStatusAwareCopperBoundary()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay { MergeStatus = GraphicsCopperOperations.MergeNoMemory };
        var core = CreateCore(memory, display);
        const uint view = 0x100;
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);

        Assert.Equal(GraphicsCopperOperations.MergeNoMemory, core.MergeCopperLists(view));
        Assert.Equal(1, display.StatusMergeCount);
        Assert.Equal(0, display.MergeCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { A = { [1] = view } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.MrgCop));
        Assert.Equal((uint)GraphicsCopperOperations.MergeNoMemory, state.D[0]);
        Assert.Equal(2, display.StatusMergeCount);
    }

    [Fact]
    public void MrgCopRestoresVisibleCopperLinksWhenAStatusBuilderPublishesThenFailsAcrossDirectAndMappedPaths()
    {
        var directMemory = new FakeMemory(0x2000);
        var mappedMemory = new FakeMemory(0x2000);
        const uint view = 0x1200;
        const uint firstViewPort = 0x1300;
        const uint secondViewPort = 0x1380;
        const uint firstRasInfo = 0x1400;
        const uint secondRasInfo = 0x1440;
        const uint firstBitMap = 0x1500;
        const uint secondBitMap = 0x1580;
        const uint firstPlane = 0x1700;
        const uint secondPlane = 0x1780;

        static void BuildView(
            FakeMemory memory,
            uint view,
            uint firstViewPort,
            uint secondViewPort,
            uint firstRasInfo,
            uint secondRasInfo,
            uint firstBitMap,
            uint secondBitMap,
            uint firstPlane,
            uint secondPlane)
        {
            memory.TryWriteLong(view + (uint)GraphicsLayouts.ViewViewPort, firstViewPort);
            memory.TryWriteLong(
                firstViewPort + (uint)GraphicsLayouts.ViewPortNext,
                secondViewPort);
            memory.TryWriteLong(secondViewPort + (uint)GraphicsLayouts.ViewPortNext, 0);

            foreach (var viewPort in new[] { firstViewPort, secondViewPort })
            {
                memory.TryWriteWord(
                    viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
                    8);
                memory.TryWriteWord(
                    viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
                    1);
                memory.TryWriteByte(
                    viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
                    0);
            }

            memory.TryWriteLong(
                firstViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                firstRasInfo);
            memory.TryWriteLong(
                secondViewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                secondRasInfo);

            memory.TryWriteLong(firstRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            memory.TryWriteLong(secondRasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
            memory.TryWriteLong(
                firstRasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
                firstBitMap);
            memory.TryWriteLong(
                secondRasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
                secondBitMap);

            foreach (var (bitMap, plane) in new[]
                     {
                         (firstBitMap, firstPlane),
                         (secondBitMap, secondPlane)
                     })
            {
                memory.TryWriteWord(
                    bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                    2);
                memory.TryWriteWord(
                    bitMap + (uint)GraphicsLayouts.BitMapRows,
                    1);
                memory.TryWriteByte(
                    bitMap + (uint)GraphicsLayouts.BitMapDepth,
                    1);
                memory.TryWriteLong(
                    bitMap + (uint)GraphicsLayouts.BitMapPlanes,
                    plane);
            }
        }

        BuildView(
            directMemory,
            view,
            firstViewPort,
            secondViewPort,
            firstRasInfo,
            secondRasInfo,
            firstBitMap,
            secondBitMap,
            firstPlane,
            secondPlane);
        BuildView(
            mappedMemory,
            view,
            firstViewPort,
            secondViewPort,
            firstRasInfo,
            secondRasInfo,
            firstBitMap,
            secondBitMap,
            firstPlane,
            secondPlane);

        var original = new Dictionary<uint, uint[]>();
        foreach (var viewPort in new[] { firstViewPort, secondViewPort })
        {
            var links = new uint[4];
            foreach (var (index, offset) in new[]
                     {
                         (0, GraphicsLayouts.ViewPortDspIns),
                         (1, GraphicsLayouts.ViewPortSprIns),
                         (2, GraphicsLayouts.ViewPortClrIns),
                         (3, GraphicsLayouts.ViewPortUCopIns)
                     })
            {
                links[index] = 0x9100u + (uint)(viewPort + (uint)(index * 0x10));
                directMemory.TryWriteLong(viewPort + (uint)offset, links[index]);
                mappedMemory.TryWriteLong(viewPort + (uint)offset, links[index]);
            }

            original[viewPort] = links;
        }

        var directDisplay = new FakeDisplayWithMakeStatus
        {
            MergeStatus = GraphicsCopperOperations.MergeNoMemory,
            MergeMutationMemory = directMemory,
            MergeMutationViewPorts = new[] { firstViewPort, secondViewPort },
            MutateMergeLinksBeforeReturning = true
        };
        var mappedDisplay = new FakeDisplayWithMakeStatus
        {
            MergeStatus = GraphicsCopperOperations.MergeNoMemory,
            MergeMutationMemory = mappedMemory,
            MergeMutationViewPorts = new[] { firstViewPort, secondViewPort },
            MutateMergeLinksBeforeReturning = true
        };
        var directCore = CreateCore(directMemory, directDisplay);
        var mappedCore = CreateCore(mappedMemory, mappedDisplay);

        Assert.Equal(
            GraphicsCopperOperations.MergeNoMemory,
            directCore.MergeCopperLists(view));
        Assert.Equal(
            GraphicsCopperOperations.MergeNoMemory,
            mappedCore.MergeCopperLists(view));

        foreach (var viewPort in new[] { firstViewPort, secondViewPort })
        {
            var links = original[viewPort];
            foreach (var (index, offset) in new[]
                     {
                         (0, GraphicsLayouts.ViewPortDspIns),
                         (1, GraphicsLayouts.ViewPortSprIns),
                         (2, GraphicsLayouts.ViewPortClrIns),
                         (3, GraphicsLayouts.ViewPortUCopIns)
                     })
            {
                Assert.Equal(
                    links[index],
                    ReadLong(directMemory, viewPort + (uint)offset));
                Assert.Equal(
                    links[index],
                    ReadLong(mappedMemory, viewPort + (uint)offset));
            }
        }

        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 173
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.MrgCop));
        Assert.Equal((uint)GraphicsCopperOperations.MergeNoMemory, state.D[0]);
        Assert.Equal(173, state.Cycles);
        Assert.Equal(2, mappedDisplay.MergeStatusCount);
    }

    [Fact]
    public void FreeCprListValidatesThePublicEnvelopeBeforeCallingTheOptionalResourceBoundary()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint cprList = 0x180;

        Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListNext, 0));
        Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListStart, 0x240));
        Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListMaxCount, 64));

        Assert.True(core.FreeCprList(cprList));
        Assert.Equal(cprList, display.FreedCprList);
        Assert.Equal(1, display.FreeCprListCount);

        Assert.True(core.FreeCprList(0));
        Assert.False(core.FreeCprList(cprList + 1));
        Assert.False(core.FreeCprList(0x0FF5));
        Assert.False(core.FreeCprList(0x0FF8));
        Assert.Equal(1, display.FreeCprListCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var oddState = new M68kCpuState
        {
            A = { [0] = cprList + 1 },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 157
        };
        Assert.False(adapter.TryInvoke(oddState, (int)GraphicsLvo.FreeCprList));
        Assert.Equal(0xDEAD_BEEFu, oddState.D[0]);
        Assert.Equal(157, oddState.Cycles);
        Assert.Equal(1, display.FreeCprListCount);

        var state = new M68kCpuState { A = { [0] = cprList }, D = { [0] = 0xFFFF_FFFF } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeCprList));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(2, display.FreeCprListCount);
    }

    [Fact]
    public void FreeCprListNullIsSuccessfulNoOp()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);

        Assert.True(core.FreeCprList(0));
        Assert.Equal(0, display.FreeCprListCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 41
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeCprList));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(41, state.Cycles);
        Assert.Equal(0, display.FreeCprListCount);
    }

    [Fact]
    public void FreeCprListRequiresAnExplicitOwnerAfterValidatingThePublicEnvelope()
    {
        var memory = new FakeMemory(0x1000);
        const uint cprList = 0x180;

        Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListNext, 0));
        Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListStart, 0x240));
        Assert.True(memory.TryWriteLong(cprList + (uint)GraphicsLayouts.CprListMaxCount, 64));

        var unownedCore = CreateCore(memory, new FakeDisplayWithoutCopper());
        Assert.False(unownedCore.FreeCprList(cprList));

        var statusDisplay = new FakeDisplayWithCopperResourceStatus();
        var ownedCore = CreateCore(memory, statusDisplay);
        Assert.False(ownedCore.FreeCprList(cprList));
        Assert.Equal(1, statusDisplay.TryFreeCprListCount);

        statusDisplay.Claim = true;
        Assert.True(ownedCore.FreeCprList(cprList));
        Assert.Equal(2, statusDisplay.TryFreeCprListCount);
    }

    [Fact]
    public void FreeVPortCopListsRestoresGuestLinksWhenTheStatusOwnerDeclines()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplayWithCopperResourceStatus();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var links = new uint[] { 0x400, 0x500, 0x600, 0x700 };
        for (var index = 0; index < offsets.Length; index++)
            Assert.True(memory.TryWriteLong(viewPort + (uint)offsets[index], links[index]));

        Assert.Equal(GraphicsRasterOperations.Failure, core.FreeViewPortCopLists(viewPort));
        Assert.Equal(1, display.TryFreeVPortCopListsCount);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(links[index], ReadLong(memory, viewPort + (uint)offsets[index]));

        display.Claim = true;
        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        Assert.Equal(2, display.TryFreeVPortCopListsCount);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(0u, ReadLong(memory, viewPort + (uint)offsets[index]));
    }

    [Fact]
    public void FreeVPortCopListsClaimsAnAlreadyEmptyViewportAsANoOp()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory, new FakeDisplayWithoutCopper());
        const uint viewPort = 0x180;

        // InitVPort's public copper links are already clear.  There is no
        // display-owned resource left to release, so the classic teardown is
        // a successful no-op even without an attached host resource owner.
        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        foreach (var offset in new[]
                 {
                     GraphicsLayouts.ViewPortDspIns,
                     GraphicsLayouts.ViewPortSprIns,
                     GraphicsLayouts.ViewPortClrIns,
                     GraphicsLayouts.ViewPortUCopIns
                 })
        {
            Assert.Equal(0u, ReadLong(memory, viewPort + (uint)offset));
        }

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 123
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeVPortCopLists));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(123, state.Cycles);
    }

    [Fact]
    public void NativeOverlayFreeVPortCopListsPreflightsTemporaryViewPortExtraTeardown()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RejectingLongWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var display = new FakeDisplayWithNativeCopperResourceStatus();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            display);
        const uint viewPort = 0x180;

        var temporaryExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType);
        Assert.NotEqual(0u, temporaryExtra);
        Assert.True(core.GfxAssociate(viewPort, temporaryExtra));
        Assert.True(backing.TryWriteWord(
            temporaryExtra + (uint)GraphicsLayouts.ViewPortExtraFlags,
            1));

        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var links = new uint[] { 0x410, 0x510, 0x610, 0x710 };
        for (var index = 0; index < offsets.Length; index++)
            Assert.True(backing.TryWriteLong(
                viewPort + (uint)offsets[index],
                links[index]));

        var backlink = temporaryExtra +
            (uint)GraphicsLayouts.ViewPortExtraViewPort;
        memory.RejectedAddress = backlink;
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, _) => address != backlink);
        var writesBeforeDecline = backing.WriteCount;
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 317,
            ProgramCounter = 0x0012_7A41
        };

        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.FreeVPortCopLists,
            nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(317, state.Cycles);
        Assert.Equal(0x0012_7A41u, state.ProgramCounter);
        Assert.Equal(writesBeforeDecline, backing.WriteCount);
        Assert.Equal(0, display.TryFreeVPortCopListsCount);
        Assert.Equal(temporaryExtra, core.GfxLookUp(viewPort));
        Assert.Empty(allocator.Freed);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(
                links[index],
                ReadLong(backing, viewPort + (uint)offsets[index]));
        Assert.Equal(
            viewPort,
            ReadLong(backing, backlink));
    }

    [Fact]
    public void UCopperListInitPublishesKickstartCopListAndIntermediateBufferLayout()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x200;
        const ushort instructionCount = 3;

        for (var offset = 0u; offset < (uint)GraphicsLayouts.UCopListSize; offset++)
            Assert.True(memory.TryWriteByte(userList + offset, 0xA5));

        var copList = core.UCopperListInit(userList, instructionCount);

        Assert.NotEqual(0u, copList);
        Assert.Equal(copList, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(copList, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(0u, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListNext));
        var instructions = ReadLong(memory, copList + (uint)GraphicsLayouts.CopListCopIns);
        Assert.NotEqual(0u, instructions);
        Assert.Equal(instructions, ReadLong(memory, copList + (uint)GraphicsLayouts.CopListCopPtr));
        Assert.Equal((ushort)0, ReadWord(memory, copList + (uint)GraphicsLayouts.CopListCount));
        Assert.Equal(instructionCount, ReadWord(memory, copList + (uint)GraphicsLayouts.CopListMaxCount));
        Assert.Equal((ushort)0, ReadWord(memory, copList + (uint)GraphicsLayouts.CopListDyOffset));
        Assert.Equal((ushort)0, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)0, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)0, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsArg1));
        Assert.Empty(allocator.Freed);
    }

    [Fact]
    public void UCopperListInitRejectsMalformedOrDuplicateListsAndRollsBackInternalAllocations()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        Assert.Equal(0u, core.UCopperListInit(0, 2));
        Assert.Equal(0u, core.UCopperListInit(0x3FF8, 2));
        Assert.Empty(allocator.Freed);

        const uint userList = 0x240;
        var first = core.UCopperListInit(userList, 2);
        Assert.NotEqual(0u, first);
        Assert.Equal(0u, core.UCopperListInit(userList, 2));
        Assert.Empty(allocator.Freed);

        var failingAllocator = new BitmapAllocator { FailAfterAllocations = 1 };
        var failingCore = new GraphicsLibraryCore(
            memory,
            failingAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, failingCore.UCopperListInit(0x280, 2));
        Assert.Single(failingAllocator.Freed);
        Assert.Equal((uint)GraphicsLayouts.CopListSize, failingAllocator.Freed[0].Bytes);
        Assert.Equal(GraphicsMemoryClass.Public, failingAllocator.Freed[0].MemoryClass);

        var adapterAllocator = new BitmapAllocator();
        var adapterCore = new GraphicsLibraryCore(
            memory,
            adapterAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(adapterCore);
        var state = new M68kCpuState
        {
            A = { [0] = 0x2C0 },
            D = { [0] = 2 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.UCopperListInit));
        Assert.NotEqual(0u, state.D[0]);
    }

    [Fact]
    public void UCopperListInitRejectsOddGuestAndInternalCopperEnvelopesBeforePublication()
    {
        var userMemory = new FakeMemory(0x4000);
        var userAllocator = new SequenceAddressAllocator(0x1000, 0x2000);
        var userCore = new GraphicsLibraryCore(
            userMemory,
            userAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, userCore.UCopperListInit(0x201, 1));
        Assert.Equal(0, userAllocator.FreeCount);

        var copListMemory = new FakeMemory(0x4000);
        var oddCopListAllocator = new SequenceAddressAllocator(0x1001);
        var oddCopListCore = new GraphicsLibraryCore(
            copListMemory,
            oddCopListAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, oddCopListCore.UCopperListInit(0x240, 1));
        Assert.Equal(1, oddCopListAllocator.FreeCount);

        var instructionMemory = new FakeMemory(0x4000);
        var oddInstructionAllocator = new SequenceAddressAllocator(0x1000, 0x2001);
        var oddInstructionCore = new GraphicsLibraryCore(
            instructionMemory,
            oddInstructionAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(0u, oddInstructionCore.UCopperListInit(0x280, 1));
        Assert.Equal(2, oddInstructionAllocator.FreeCount);
        Assert.Equal(0u, ReadLong(
            instructionMemory,
            0x280u + (uint)GraphicsLayouts.UCopListFirstCopList));
    }

    [Fact]
    public void UCopperListInitRestoresOwnerEnvelopeWhenPublicationFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x2F0;
        for (var offset = 0u; offset < (uint)GraphicsLayouts.UCopListSize; offset++)
            Assert.True(backing.TryWriteByte(userList + offset, (byte)(0x80 + offset)));

        // A one-instruction block publishes 72 initialization bytes before
        // the owner clear and links.  Fail the second byte of the final link.
        memory.FailOnNextByteWrite(90);
        Assert.Equal(0u, core.UCopperListInit(userList, 1));
        for (var offset = 0u; offset < (uint)GraphicsLayouts.UCopListSize; offset++)
            Assert.Equal((byte)(0x80 + offset), ReadByte(backing, userList + offset));
        Assert.Equal(2, allocator.Freed.Count);

        // No registry entry or partial owner publication remains; retry is
        // therefore allowed to allocate a fresh list.
        Assert.NotEqual(0u, core.UCopperListInit(userList, 1));
    }

    [Fact]
    public void UCopperListInitRestoresInternalBuffersAfterRejectedInitializationPointer()
    {
        var backing = new FakeMemory(0x5000);
        const uint userList = 0x200;
        const uint copList = 0x1000;
        const uint instructions = 0x1040;
        var originalCopList = new byte[GraphicsLayouts.CopListSize];
        for (var offset = 0; offset < originalCopList.Length; offset++)
        {
            originalCopList[offset] = (byte)(0x60 + offset);
            Assert.True(backing.TryWriteByte(copList + (uint)offset, originalCopList[offset]));
        }

        var originalInstructions = new byte[GraphicsLayouts.CopInsSize];
        for (var offset = 0; offset < originalInstructions.Length; offset++)
        {
            originalInstructions[offset] = (byte)(0xA0 + offset);
            Assert.True(backing.TryWriteByte(
                instructions + (uint)offset,
                originalInstructions[offset]));
        }

        var memory = new PartialThenRejectLongWriteMemory(backing)
        {
            PartialLongAddress = copList + (uint)GraphicsLayouts.CopListCopPtr
        };
        var allocator = new SequenceAddressAllocator(copList, instructions);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        // The CopList pointer is partially published during internal
        // initialization. Both internal public spans must return untouched.
        Assert.Equal(0u, core.UCopperListInit(userList, 1));
        Assert.Equal(2, allocator.FreeCount);
        for (var offset = 0; offset < originalCopList.Length; offset++)
            Assert.Equal(originalCopList[offset], ReadByte(backing, copList + (uint)offset));
        for (var offset = 0; offset < originalInstructions.Length; offset++)
            Assert.Equal(
                originalInstructions[offset],
                ReadByte(backing, instructions + (uint)offset));

        // Removing the fault permits the allocator to reuse the same spans;
        // the normal owner publication and teardown then remain available.
        memory.PartialLongAddress = null;
        var retryAllocator = new SequenceAddressAllocator(copList, instructions);
        var retryCore = new GraphicsLibraryCore(
            memory,
            retryAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var recovered = retryCore.UCopperListInit(userList, 1);
        Assert.Equal(copList, recovered);
        Assert.True(retryCore.FreeCopList(recovered));
        Assert.Equal(2, retryAllocator.FreeCount);
    }

    [Fact]
    public void UCopperListInitRestoresInternalBuffersWhenOwnerPublicationFailsLate()
    {
        var backing = new FakeMemory(0x5000);
        const uint userList = 0x200;
        const uint copList = 0x1000;
        const uint instructions = 0x1040;
        var originalUser = new byte[GraphicsLayouts.UCopListSize];
        for (var offset = 0; offset < originalUser.Length; offset++)
        {
            originalUser[offset] = (byte)(0x10 + offset);
            Assert.True(backing.TryWriteByte(userList + (uint)offset, originalUser[offset]));
        }

        var originalCopList = new byte[GraphicsLayouts.CopListSize];
        for (var offset = 0; offset < originalCopList.Length; offset++)
        {
            originalCopList[offset] = (byte)(0x60 + offset);
            Assert.True(backing.TryWriteByte(copList + (uint)offset, originalCopList[offset]));
        }

        var originalInstructions = new byte[GraphicsLayouts.CopInsSize];
        for (var offset = 0; offset < originalInstructions.Length; offset++)
        {
            originalInstructions[offset] = (byte)(0xA0 + offset);
            Assert.True(backing.TryWriteByte(
                instructions + (uint)offset,
                originalInstructions[offset]));
        }

        var memory = new PartialThenRejectLongWriteMemory(backing)
        {
            PartialLongAddress = userList + (uint)GraphicsLayouts.UCopListCopList
        };
        var allocator = new SequenceAddressAllocator(copList, instructions);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        // Internal initialization succeeds, the owner link is then partially
        // published, and the complete three-envelope transaction declines.
        Assert.Equal(0u, core.UCopperListInit(userList, 1));
        Assert.Equal(2, allocator.FreeCount);
        for (var offset = 0; offset < originalUser.Length; offset++)
            Assert.Equal(originalUser[offset], ReadByte(backing, userList + (uint)offset));
        for (var offset = 0; offset < originalCopList.Length; offset++)
            Assert.Equal(originalCopList[offset], ReadByte(backing, copList + (uint)offset));
        for (var offset = 0; offset < originalInstructions.Length; offset++)
            Assert.Equal(
                originalInstructions[offset],
                ReadByte(backing, instructions + (uint)offset));

        memory.PartialLongAddress = null;
        var retryAllocator = new SequenceAddressAllocator(copList, instructions);
        var retryCore = new GraphicsLibraryCore(
            memory,
            retryAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var recovered = retryCore.UCopperListInit(userList, 1);
        Assert.Equal(copList, recovered);
        Assert.True(retryCore.FreeCopList(recovered));
        Assert.Equal(2, retryAllocator.FreeCount);
    }

    [Fact]
    public void UserCopperInstructionVectorsWritePseudoInstructionsAndBumpSafely()
    {
        var memory = new FakeMemory(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x320;
        const ushort capacity = 3;
        var copList = core.UCopperListInit(userList, capacity);
        var instructions = ReadLong(memory, copList + (uint)GraphicsLayouts.CopListCopIns);

        Assert.True(core.CMove(userList, 0x00DFF180, 0x1234));
        Assert.Equal((ushort)0, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)0x0180, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)0x1234, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsArg1));
        Assert.Equal((ushort)0, ReadWord(memory, copList + (uint)GraphicsLayouts.CopListCount));
        Assert.Equal(instructions, ReadLong(memory, copList + (uint)GraphicsLayouts.CopListCopPtr));

        Assert.True(core.CBump(userList));
        Assert.Equal((ushort)1, ReadWord(memory, copList + (uint)GraphicsLayouts.CopListCount));
        Assert.Equal(instructions + (uint)GraphicsLayouts.CopInsSize, ReadLong(memory, copList + (uint)GraphicsLayouts.CopListCopPtr));

        var second = instructions + (uint)GraphicsLayouts.CopInsSize;
        Assert.True(core.CWait(userList, 42, 12));
        Assert.Equal((ushort)1, ReadWord(memory, second + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)42, ReadWord(memory, second + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)12, ReadWord(memory, second + (uint)GraphicsLayouts.CopInsArg1));
        Assert.True(core.CBump(userList));

        Assert.True(core.CEnd(userList));
        var end = instructions + (2u * (uint)GraphicsLayouts.CopInsSize);
        Assert.Equal((ushort)1, ReadWord(memory, end + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)10000, ReadWord(memory, end + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)255, ReadWord(memory, end + (uint)GraphicsLayouts.CopInsArg1));
        Assert.Equal(capacity, ReadWord(memory, copList + (uint)GraphicsLayouts.CopListCount));
        Assert.True(core.CBump(userList));
        var nextCopList = ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListCopList);
        Assert.NotEqual(copList, nextCopList);
        Assert.True(core.CMove(userList, 0x180, 0x5678));
        var nextInstructions = ReadLong(memory, nextCopList + (uint)GraphicsLayouts.CopListCopIns);
        Assert.Equal((ushort)0x5678, ReadWord(memory, nextInstructions + (uint)GraphicsLayouts.CopInsArg1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        Assert.True(memory.TryWriteLong(
            nextCopList + (uint)GraphicsLayouts.CopListCopPtr,
            0x3FF0));
        var forged = new M68kCpuState { A = { [1] = userList }, D = { [0] = 0x180, [1] = 0x5678 } };
        Assert.False(adapter.TryInvoke(forged, (int)GraphicsLvo.CMove));
        Assert.Equal((ushort)0x5678, ReadWord(memory, nextInstructions + (uint)GraphicsLayouts.CopInsArg1));
    }

    [Fact]
    public void UserCopperMoveAndWaitRestoreInstructionWhenALateWordWriteFails()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x320;
        var copList = core.UCopperListInit(userList, 1);
        var instructions = ReadLong(backing, copList + (uint)GraphicsLayouts.CopListCopIns);
        for (var offset = 0u; offset < (uint)GraphicsLayouts.CopInsSize; offset++)
            Assert.True(backing.TryWriteByte(instructions + offset, 0xCC));

        memory.FailOnNextByteWrite(4);
        Assert.False(core.CMove(userList, 0x180, 0x1234));
        for (var offset = 0u; offset < (uint)GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, instructions + offset));

        memory.FailOnNextByteWrite(4);
        Assert.False(core.CWait(userList, 42, 12));
        for (var offset = 0u; offset < (uint)GraphicsLayouts.CopInsSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, instructions + offset));
    }

    [Fact]
    public void UserCopperBumpRestoresHeaderWhenTheCountWriteFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x350;
        var copList = core.UCopperListInit(userList, 2);
        var originalPointer = ReadLong(backing, copList + (uint)GraphicsLayouts.CopListCopPtr);

        // CBump publishes CopPtr as one long and Count as one word.  Fail
        // the second byte of Count after CopPtr has already advanced.
        memory.FailOnNextByteWrite(5);
        Assert.False(core.CBump(userList));
        Assert.Equal(originalPointer, ReadLong(backing, copList + (uint)GraphicsLayouts.CopListCopPtr));
        Assert.Equal((ushort)0, ReadWord(backing, copList + (uint)GraphicsLayouts.CopListCount));
    }

    [Fact]
    public void UserCopperBlockRolloverRollsBackWhenTheNextBufferCannotBeAllocated()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new BitmapAllocator { FailAfterAllocations = 3 };
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x3A0;
        var firstCopList = core.UCopperListInit(userList, 1);
        Assert.NotEqual(0u, firstCopList);
        Assert.True(core.CMove(userList, 0x180, 1));
        Assert.True(core.CBump(userList));

        Assert.False(core.CBump(userList));
        Assert.Equal(firstCopList, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(0u, ReadLong(memory, firstCopList + (uint)GraphicsLayouts.CopListNext));
        Assert.Single(allocator.Freed);
        Assert.Equal((uint)GraphicsLayouts.CopListSize, allocator.Freed[0].Bytes);
    }

    [Fact]
    public void UserCopperBlockRolloverRestoresLinksWhenOwnerPublicationFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x3B0;
        var firstCopList = core.UCopperListInit(userList, 1);
        Assert.True(core.CMove(userList, 0x180, 1));
        Assert.True(core.CBump(userList));

        // The successor allocation clears/initializes 72 bytes, then the
        // current-list link is four bytes.  Fail the second byte of the
        // owner-list link after both earlier publications have started.
        memory.FailOnNextByteWrite(78);
        Assert.False(core.CBump(userList));
        Assert.Equal(firstCopList, ReadLong(backing, userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(0u, ReadLong(backing, firstCopList + (uint)GraphicsLayouts.CopListNext));
        Assert.Equal(2, allocator.Freed.Count);
        Assert.All(allocator.Freed, freed => Assert.Equal(GraphicsMemoryClass.Public, freed.MemoryClass));
    }

    [Fact]
    public void UserCopperInstructionAdapterUsesClassicA1D0D1Registers()
    {
        var memory = new FakeMemory(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint userList = 0x380;
        var init = new M68kCpuState { A = { [0] = userList }, D = { [0] = 2 } };
        Assert.True(adapter.TryInvoke(init, (int)GraphicsLvo.UCopperListInit));
        var copList = init.D[0];
        var instructions = ReadLong(memory, copList + (uint)GraphicsLayouts.CopListCopIns);

        var move = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0x180, [1] = 0xCAFE }
        };
        Assert.True(adapter.TryInvoke(move, (int)GraphicsLvo.CMove));
        Assert.Equal(0u, move.D[0]);
        Assert.Equal((ushort)0xCAFE, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsArg1));

        var bump = new M68kCpuState { A = { [1] = userList } };
        Assert.True(adapter.TryInvoke(bump, (int)GraphicsLvo.CBump));
        var wait = new M68kCpuState { A = { [1] = userList }, D = { [0] = 7, [1] = 8 } };
        Assert.True(adapter.TryInvoke(wait, (int)GraphicsLvo.CWait));
        Assert.Equal((ushort)7, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsSize + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)8, ReadWord(memory, instructions + (uint)GraphicsLayouts.CopInsSize + (uint)GraphicsLayouts.CopInsArg1));
    }

    [Fact]
    public void FreeCopListReleasesOnlyRegistryOwnedIntermediateBuffersAndClearsOwnerLinks()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x3E0;
        var copList = core.UCopperListInit(userList, 1);
        Assert.NotEqual(0u, copList);

        Assert.True(core.FreeCopList(copList));
        Assert.Equal(0u, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(0u, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(2, allocator.Freed.Count);
        Assert.All(allocator.Freed, freed => Assert.Equal(GraphicsMemoryClass.Public, freed.MemoryClass));
        Assert.False(core.FreeCopList(copList));
        Assert.False(core.CMove(userList, 0x180, 1));

        var adapterAllocator = new BitmapAllocator();
        var adapterCore = new GraphicsLibraryCore(
            memory,
            adapterAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(adapterCore);
        var init = new M68kCpuState { A = { [0] = 0x420 }, D = { [0] = 1 } };
        Assert.True(adapter.TryInvoke(init, (int)GraphicsLvo.UCopperListInit));
        var free = new M68kCpuState { A = { [0] = init.D[0] }, D = { [0] = 0xFFFFFFFF } };
        Assert.True(adapter.TryInvoke(free, (int)GraphicsLvo.FreeCopList));
        Assert.Equal(0u, free.D[0]);
    }

