    [Fact]
    public void NativeOverlayFreeCopListPreflightsTheOwnedUserListBeforeTeardown()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x200;

        var copList = core.UCopperListInit(userList, instructionCount: 2);
        Assert.NotEqual(0u, copList);
        var writesBeforeDecline = memory.WriteCount;
        var originalFirst = ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListFirstCopList);
        var originalCurrent = ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListCopList);

        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, byteCount) =>
                address != userList || byteCount != (uint)GraphicsLayouts.UCopListSize);
        var state = new M68kCpuState
        {
            A = { [0] = copList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 43,
            ProgramCounter = 0x0012_3705
        };

        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.FreeCopList,
            nativeOverlay: true));
        Assert.Equal(0x1357_9BDFu, state.D[0]);
        Assert.Equal(43, state.Cycles);
        Assert.Equal(0x0012_3705u, state.ProgramCounter);
        Assert.Equal(writesBeforeDecline, memory.WriteCount);
        Assert.Equal(originalFirst, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(originalCurrent, ReadLong(memory, userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void FreeCopListRestoresOwnerLinksWhenTheSecondClearFailsLate()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        const uint userList = 0x410;
        var copList = core.UCopperListInit(userList, 1);
        Assert.NotEqual(0u, copList);

        // The first owner link is four bytes; fail the second byte of the
        // second link after the clear has already started.
        memory.FailOnNextByteWrite(6);
        Assert.False(core.FreeCopList(copList));
        Assert.Equal(copList, ReadLong(backing, userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(copList, ReadLong(backing, userList + (uint)GraphicsLayouts.UCopListCopList));
        Assert.Empty(allocator.Freed);

        // The registry remains live and can be torn down cleanly on retry.
        Assert.True(core.FreeCopList(copList));
        Assert.Equal(2, allocator.Freed.Count);
    }

    [Fact]
    public void FreeVPortCopListsClearsAllGuestCopperLinksAndRejectsMalformedViewportRanges()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;

        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, 0x400));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns, 0x500));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns, 0x600));
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns, 0x700));

        Assert.Equal(0, core.FreeViewPortCopLists(viewPort));
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        Assert.Equal(viewPort, display.FreedViewPortCopLists);
        Assert.Equal(1, display.FreeViewPortCopListsCount);

        Assert.Equal(-1, core.FreeViewPortCopLists(0x0FF8));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        Assert.True(memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns, 0x400));
        var state = new M68kCpuState { A = { [0] = viewPort }, D = { [0] = 0xA5A5_A5A5 } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeVPortCopLists));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0u, ReadLong(memory, viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(2, display.FreeViewPortCopListsCount);
    }

    [Fact]
    public void FreeVPortCopListsRejectsAddressWrappingViewportBeforeTouchingLowMemory()
    {
        var memory = new WrappingMemory();
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0xFFFF_FFF0;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var values = new uint[] { 0x1122_3344, 0x5566_7788, 0x99AA_BBCC, 0xDDEE_FF00 };

        // An unchecked base-plus-offset calculation would wrap these public
        // links into low memory. Seed the wrapped targets so the regression
        // proves that the portable teardown declines before reading or
        // clearing unrelated guest words.
        for (var index = 0; index < offsets.Length; index++)
        {
            var wrappedAddress = unchecked(viewPort + (uint)offsets[index]);
            memory.WriteLong(wrappedAddress, values[index]);
        }

        Assert.Equal(GraphicsRasterOperations.Failure, core.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
        {
            var wrappedAddress = unchecked(viewPort + (uint)offsets[index]);
            Assert.Equal(values[index], ReadLong(memory, wrappedAddress));
        }
        Assert.Equal(0, display.FreeViewPortCopListsCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 91
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FreeVPortCopLists));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(91, state.Cycles);
    }

    [Fact]
    public void FreeVPortCopListsRestoresSparseLinksWhenTheFullViewportEnvelopeWraps()
    {
        const uint viewPort = 0xFFFF_FFE0;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var links = new uint[] { 0x1122_3344, 0x5566_7788, 0x99AA_BBCC, 0xDDEE_FF00 };

        // The four copper links still fit below $FFFFFFFF, while the
        // unrelated ViewPort tail does not.  With no display-resource owner,
        // FreeVPortCopLists must roll the links back after declining the
        // private ownership handoff; requiring ViewPortSize here would lose
        // that snapshot and leave the guest links cleared on failure.
        var directMemory = new WrappingMemory();
        for (var index = 0; index < offsets.Length; index++)
            directMemory.WriteLong(viewPort + (uint)offsets[index], links[index]);

        var directCore = CreateCore(directMemory, new FakeDisplayWithoutCopper());
        Assert.Equal(GraphicsRasterOperations.Failure, directCore.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(links[index], ReadLong(directMemory, viewPort + (uint)offsets[index]));

        var mappedMemory = new WrappingMemory();
        for (var index = 0; index < offsets.Length; index++)
            mappedMemory.WriteLong(viewPort + (uint)offsets[index], links[index]);

        var mappedCore = CreateCore(mappedMemory, new FakeDisplayWithoutCopper());
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 97
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FreeVPortCopLists));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(97, state.Cycles);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(links[index], ReadLong(mappedMemory, viewPort + (uint)offsets[index]));
    }

    [Fact]
    public void FreeVPortCopListsDoesNotConsumeUnrelatedViewportFieldsAcrossDirectAndMappedPaths()
    {
        const uint viewPort = 0x180;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var links = new uint[] { 0x400, 0x500, 0x600, 0x700 };

        var directBacking = new FakeMemory(0x1000);
        for (var index = 0; index < offsets.Length; index++)
            Assert.True(directBacking.TryWriteLong(viewPort + (uint)offsets[index], links[index]));

        // The native teardown only reads/writes the four public copper links.
        // An unrelated, unreadable ViewPort dimension must not make the
        // portable path claim failure before those links can be released.
        var directMemory = new RangeReadFaultMemory(directBacking);
        directMemory.FailReads(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            sizeof(ushort));
        var directDisplay = new FakeDisplay();
        var directCore = CreateCore(directMemory, directDisplay);

        Assert.Equal(0, directCore.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(0u, ReadLong(directBacking, viewPort + (uint)offsets[index]));

        var mappedBacking = new FakeMemory(0x1000);
        for (var index = 0; index < offsets.Length; index++)
            Assert.True(mappedBacking.TryWriteLong(viewPort + (uint)offsets[index], links[index]));

        var mappedMemory = new RangeReadFaultMemory(mappedBacking);
        mappedMemory.FailReads(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            sizeof(ushort));
        var mappedDisplay = new FakeDisplay();
        var mappedCore = CreateCore(mappedMemory, mappedDisplay);
        var adapter = new CopperStartGraphicsRegisterAdapter(mappedCore);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 73
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeVPortCopLists));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(73, state.Cycles);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(0u, ReadLong(mappedBacking, viewPort + (uint)offsets[index]));
    }

    [Fact]
    public void FreeVPortCopListsTreatsNullAsNativeNoOp()
    {
        var memory = new FakeMemory(0x1000);
