    [Fact]
    public void FreeVPortCopListsRestoresGuestLinksWhenATeardownWriteFails()
    {
        var backing = new FakeMemory(0x1000);
        const uint viewPort = 0x180;
        var values = new uint[] { 0x400, 0x500, 0x600, 0x700 };
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };

        for (var index = 0; index < offsets.Length; index++)
            Assert.True(backing.TryWriteLong(viewPort + (uint)offsets[index], values[index]));

        // Reject the second link only.  The first NULL write succeeds, then
        // the portable teardown must restore it before declining the call.
        var memory = new RejectingWriteMemory(
            backing,
            viewPort + (uint)GraphicsLayouts.ViewPortSprIns,
            viewPort + (uint)GraphicsLayouts.ViewPortSprIns + 4u);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);

        Assert.Equal(-1, core.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(values[index], ReadLong(backing, viewPort + (uint)offsets[index]));

        Assert.Equal(0, display.FreeViewPortCopListsCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xABCD_1234u },
            Cycles = 37
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FreeVPortCopLists));
        Assert.Equal(0xABCD_1234u, state.D[0]);
        Assert.Equal(37, state.Cycles);
    }

    [Fact]
    public void FreeVPortCopListsRestoresLinksAfterAPartialLongWrite()
    {
        var backing = new FakeMemory(0x1000);
        const uint viewPort = 0x180;
        var values = new uint[] { 0x400, 0x500, 0x600, 0x700 };
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };

        for (var index = 0; index < offsets.Length; index++)
            Assert.True(backing.TryWriteLong(viewPort + (uint)offsets[index], values[index]));

        // The adapter intentionally publishes two bytes and then rejects
        // every LONG write. Byte-wise rollback must still restore the whole
        // four-link envelope; a LONG-only rollback would fail the same way.
        var memory = new PartialLongWriteMemory(backing) { RejectLongWrites = true };
        var core = CreateCore(memory, new FakeDisplay());

        Assert.Equal(GraphicsRasterOperations.Failure, core.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(values[index], ReadLong(backing, viewPort + (uint)offsets[index]));

        memory.RejectLongWrites = false;
        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(0u, ReadLong(backing, viewPort + (uint)offsets[index]));
    }

    [Fact]
    public void FreeVPortCopListsRestoresLinksAfterAStatusDeclineRejectsRepeatedLongRollback()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new ProbeThenFailLongWriteMemory(backing);
        var display = new FakeDisplayWithCopperResourceStatus { Claim = false };
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        var offsets = new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        var firstLink = viewPort + (uint)offsets[0];
        var values = new uint[] { 0x1234_5678, 0x2345_6789, 0x3456_789A, 0x4567_89AB };
        memory.ProbeLongAddress = firstLink;
        for (var index = 0; index < offsets.Length; index++)
            Assert.True(backing.TryWriteLong(viewPort + (uint)offsets[index], values[index]));

        Assert.Equal(GraphicsRasterOperations.Failure, core.FreeViewPortCopLists(viewPort));
        Assert.Equal(1, display.TryFreeVPortCopListsCount);
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(values[index], ReadLong(backing, viewPort + (uint)offsets[index]));

        display.Claim = true;
        memory.ResetProbe();
        Assert.Equal(GraphicsRasterOperations.Success, core.FreeViewPortCopLists(viewPort));
        for (var index = 0; index < offsets.Length; index++)
            Assert.Equal(0u, ReadLong(backing, viewPort + (uint)offsets[index]));
    }

    [Fact]
    public void ScrollVPortValidatesEveryRasInfoNodeBeforeNotifyingDisplay()
    {
        var memory = new FakeMemory(0x1000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;

        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0x300);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 4);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 8);

        Assert.True(core.ScrollViewPort(viewPort));
        Assert.Equal(viewPort, display.ScrolledViewPort);

        // A second node that crosses the guest-memory boundary is rejected
        // without repeating the display notification.
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0x0FF8);
        Assert.False(core.ScrollViewPort(viewPort));
        Assert.Equal(1, display.ScrollCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 55
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ScrollVPort));
        Assert.Equal(0xA5A5_5A5Au, state.D[0]);
        Assert.Equal(55, state.Cycles);
        Assert.Equal(1, display.ScrollCount);
    }

    [Fact]
    public void ScrollVPortReadsOnlyTheRasInfoAndOffsetRefreshFields()
    {
        static (FakeMemory Backing, RangeReadFaultMemory Memory, GraphicsLibraryCore Core, uint ViewPort)
            Prepare()
        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = new GraphicsLibraryCore(
                memory,
                new FakeAllocator(),
                new FakeBlitter(),
                new FakeDisplay());
            const uint viewPort = 0x180;
            const uint rasInfo = 0x1C0;

            Assert.True(backing.TryWriteLong(
                viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                rasInfo));
            Assert.True(backing.TryWriteByte(
                viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
                0));
            Assert.True(backing.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoNext,
                0));
            Assert.True(backing.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
                0));
            Assert.True(backing.TryWriteWord(
                rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
                12));
            Assert.True(backing.TryWriteWord(
                rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
                24));

            // ScrollVPort refreshes the RasInfo offsets and does not consume
            // display geometry.  Fault the unrelated DWidth..Modes span;
            // the focused admission must still reach the display boundary.
            memory.FailReads(
                viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
                (uint)(GraphicsLayouts.ViewPortExtendedModes - GraphicsLayouts.ViewPortDWidth));
            return (backing, memory, core, viewPort);
        }

        var direct = Prepare();
        Assert.True(direct.Core.ScrollViewPort(direct.ViewPort));
        Assert.Equal(0, direct.Memory.FaultedReadCount);

        var mapped = Prepare();
        var adapter = new CopperStartGraphicsRegisterAdapter(mapped.Core);
        var state = new M68kCpuState
        {
            A = { [0] = mapped.ViewPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 177
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ScrollVPort));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(177, state.Cycles);
        Assert.Equal(0, mapped.Memory.FaultedReadCount);
    }

