    [Fact]
    public void HostCopperLifecycleForwardsOnlyRtgViewsToTheProvider()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var hostMemory = new HostGuestMemory(machine.Bus);
        const uint view = 0x500;
        const uint viewPort = 0x580;
        const uint rasInfo = 0x600;
        const uint rtgBitMap = 0x680;
        var mergeCalls = 0;
        var makeCalls = 0;

        machine.Bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        machine.Bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);

        using var services = CreateHostGraphicsServices(
            hostMemory,
            mergeCopperLists: state =>
            {
                mergeCalls++;
                return 0x1111u;
            },
            makeViewPort: state =>
            {
                makeCalls++;
                return 0x2222u;
            },
            isRtgBitMap: bitMap => bitMap == rtgBitMap);

        var merge = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 71
        };
        services.Invoke(merge, (int)GraphicsLvo.MrgCop);

        var make = new M68kCpuState
        {
            A = { [1] = viewPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 83
        };
        services.Invoke(make, (int)GraphicsLvo.MakeVPort);

        Assert.Equal(1, mergeCalls);
        Assert.Equal(1, makeCalls);
        Assert.Equal(0x1111u, merge.D[0]);
        Assert.Equal(0x2222u, make.D[0]);
        Assert.Equal(71, merge.Cycles);
        Assert.Equal(83, make.Cycles);
    }

    [Fact]
    public void HostCopperLifecycleLeavesMalformedStandardStateUnclaimed()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var hostMemory = new HostGuestMemory(machine.Bus);
        var mergeCalls = 0;
