            hostMemory,
            mergeCopperLists: _ =>
            {
                mergeCalls++;
                return 0x1111u;
            },
            makeViewPort: _ =>
            {
                makeCalls++;
                return 0x2222u;
            });

        var merge = new M68kCpuState
        {
            A = { [1] = 0x00FF_0000 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 97
        };
        services.Invoke(merge, (int)GraphicsLvo.MrgCop);

        var make = new M68kCpuState
        {
            A = { [1] = 0x00FF_0000 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 109
        };
        services.Invoke(make, (int)GraphicsLvo.MakeVPort);

        Assert.Equal(0, mergeCalls);
        Assert.Equal(0, makeCalls);
        Assert.Equal(0xCAFE_BABEu, merge.D[0]);
        Assert.Equal((uint)GraphicsViewportStatuses.NoViewPortExtra, make.D[0]);
        Assert.Equal(97, merge.Cycles);
        Assert.Equal(109, make.Cycles);
    }

