    [Fact]
    public void GetVPModeIDAcceptsASparseModeOnlyViewportThroughDirectAndCopperStart()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint viewPort = 0x180;

        // The resident no-ColorMap path derives the public mode from
        // vp_Modes.  Geometry is not part of that query, so an assembling
        // ViewPort may publish only the mode/ownership fields below.
        memory.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            0);
        memory.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        memory.WriteByte(
            viewPort + (uint)GraphicsLayouts.ViewPortExtendedModes,
            0);
        memory.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0);

        Assert.True(core.TryGetViewPortModeId(viewPort, out var directMode));
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode,
            directMode);

        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 173
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetVPModeID));
        Assert.Equal(directMode, state.D[0]);
        Assert.Equal(173, state.Cycles);
    }

