    [Fact]
    public void NativeViewPublicationDeclinesAnUnreadableOwnedColorMap()
    {
        var backing = new FakeMemory(0x10_000);
        var memory = new RangeReadFaultMemory(backing);
        var display = new FakeDisplay();
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            display);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = core.GetColorMap(2);
        Assert.NotEqual(0u, colorMap);

        const uint view = 0x100;
        const uint viewPort = 0x180;
        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            viewPort));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortNext,
            0));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            640));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0));

        // The registry still owns the address, but the guest envelope is no
        // longer readable.  Both mode lookup and direct LoadView must leave
        // the request available to the native/provider owner.
        memory.FailReads(colorMap, (uint)GraphicsLayouts.ColorMapSize);

        var modeState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 211
        };
        Assert.False(adapter.TryInvoke(modeState, (int)GraphicsLvo.GetVPModeID));
        Assert.Equal(0xA5A5_5A5Au, modeState.D[0]);
        Assert.Equal(211, modeState.Cycles);

        Assert.Equal(-1, core.LoadView(view));
        Assert.Equal(0u, display.PublishedView);
    }

