    [Fact]
    public void DisplayDatabaseEnumeratesSupportedPalNtscModesAndReportsAvailability()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        var handle = GraphicsModeIds.Invalid;
        var seen = new List<uint>();
        var seenHandles = new List<uint>();
        while ((handle = core.NextDisplayInfo(handle)) != GraphicsModeIds.Invalid)
        {
            // NextDisplayInfo returns the public ModeID key.  The valid zero
            // default-lores key is intentionally distinct from the private
            // nonzero FindDisplayInfo handle.
            var mode = handle;
            seen.Add(mode);
            seenHandles.Add(handle);
            var expectedHandle = mode == GraphicsModeIds.DefaultMonitor
                ? GraphicsDisplayDatabase.DefaultModeHandle
                : mode;
            Assert.Equal(expectedHandle, core.FindDisplayInfo(mode));
            Assert.Equal(0u, core.ModeNotAvailable(mode));
        }

        Assert.Equal(66, seen.Count);
        Assert.Equal(GraphicsModeIds.DefaultMonitor, seenHandles[0]);
        Assert.Equal(GraphicsModeIds.DefaultMonitor, seen[0]);
        Assert.Contains(GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode, seen);
        Assert.Contains(GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey, seen);
        Assert.Contains(GraphicsModeIds.NtscMonitor | GraphicsModeIds.SuperHiresLaceKey, seen);
        Assert.Contains(GraphicsModeIds.PalMonitor | GraphicsModeIds.HamMode, seen);
        Assert.Contains(GraphicsModeIds.PalMonitor | GraphicsModeIds.ExtraHalfBriteMode, seen);
        Assert.Contains(GraphicsModeIds.PalMonitor | GraphicsModeIds.DualPlayfieldMode, seen);
        Assert.Contains(GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresDualPlayfieldKey, seen);
        Assert.Contains(GraphicsModeIds.PalMonitor | GraphicsModeIds.DualPlayfieldMode | GraphicsModeIds.PlayfieldBitAssignment, seen);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor |
                GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey,
            seen[^1]);
        Assert.Equal(0u, core.FindDisplayInfo(0xDEAD_BEEFu));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoMonitor, core.ModeNotAvailable(0xDEAD_BEEFu));
        // INVALID_ID is the universal no-record sentinel, not a foreign
        // monitor request.  The query vectors own it and publish the
        // documented NULL/DI_AVAIL_NOMONITOR results.
        Assert.Equal(0u, core.FindDisplayInfo(GraphicsModeIds.Invalid));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoMonitor, core.ModeNotAvailable(GraphicsModeIds.Invalid));
        Assert.True(memory.TryWriteByte(0xC00, 0xA5));
        Assert.Equal(
            0,
            core.GetDisplayInfoData(
                0,
                0xC00,
                0x30,
                GraphicsDisplayDatabase.DtagDisp,
                GraphicsModeIds.Invalid));
        Assert.Equal((byte)0xA5, ReadByte(memory, 0xC00));
        Assert.Equal(0u, core.ModeNotAvailable(GraphicsModeIds.PalMonitor | GraphicsModeIds.HamMode));

        var defaultLoresHandle = core.FindDisplayInfo(GraphicsModeIds.DefaultMonitor);
        Assert.Equal(GraphicsDisplayDatabase.DefaultModeHandle, defaultLoresHandle);
        Assert.NotEqual(0u, defaultLoresHandle);
        Assert.Equal(0x30, core.GetDisplayInfoData(
            defaultLoresHandle,
            0xC00,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode));
        Assert.Equal(GraphicsModeIds.PalMonitor, ReadLong(memory, 0xC00 + 4));
        Assert.Equal(4u, ReadLong(memory, 0xC00 + 12));

        // Independently observed DISP/DIMS/MNTR header lengths exclude the
        // reserved terminator. NAME policy remains a separate investigation.
        var chunkCases = new[]
        {
            (GraphicsDisplayDatabase.DtagDims, 0x58u, 8u),
            (GraphicsDisplayDatabase.DtagMntr, 0x60u, 9u),
            (GraphicsDisplayDatabase.DtagName, 0x38u, 5u)
        };
        foreach (var (tag, size, length) in chunkCases)
        {
            Assert.Equal(
                tag switch
                {
                    GraphicsDisplayDatabase.DtagDims => 66,
                    GraphicsDisplayDatabase.DtagMntr => 88,
                    _ => (int)size
                },
                core.GetDisplayInfoData(
                    defaultLoresHandle,
                    0xC00,
                    size,
                    tag,
                    GraphicsModeIds.DefaultMonitor));
            Assert.Equal(length, ReadLong(memory, 0xC00 + 12));
        }

        var defaultMode = GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode;
        Assert.Equal(defaultMode, core.FindDisplayInfo(defaultMode));
        Assert.Equal(0u, core.ModeNotAvailable(defaultMode));
        Assert.Equal(0x30, core.GetDisplayInfoData(
            core.FindDisplayInfo(defaultMode),
            0xC00,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            defaultMode));
        Assert.Equal(GraphicsModeIds.PalMonitor | defaultMode, ReadLong(memory, 0xC00 + 4));

        // The optional ID is consulted only when the handle is null.  A
        // valid handle remains authoritative even if D2 names another mode.
        var palHandle = core.FindDisplayInfo(GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode);
        Assert.Equal(0x30, core.GetDisplayInfoData(
            palHandle,
            0xC00,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            defaultMode));
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode, ReadLong(memory, 0xC00 + 4));
        Assert.Equal(0x30, core.GetDisplayInfoData(
            0,
            0xC00,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            defaultMode));
        Assert.Equal(GraphicsModeIds.PalMonitor | defaultMode, ReadLong(memory, 0xC00 + 4));

        var find = new M68kCpuState { D = { [0] = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode } };
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.FindDisplayInfo));
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode, find.D[0]);

        find.D[0] = GraphicsModeIds.DefaultMonitor;
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.FindDisplayInfo));
        Assert.Equal(GraphicsDisplayDatabase.DefaultModeHandle, find.D[0]);

        find.D[0] = GraphicsModeIds.Invalid;
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.FindDisplayInfo));
        Assert.Equal(0u, find.D[0]);

        find.D[0] = GraphicsModeIds.Invalid;
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.ModeNotAvailable));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoMonitor, find.D[0]);

        find = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0xC00 },
            D =
            {
                [0] = 0x30,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = GraphicsModeIds.Invalid
            }
        };
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.GetDisplayInfoData));
        Assert.Equal(0u, find.D[0]);

        find = new M68kCpuState { D = { [0] = GraphicsModeIds.Invalid } };
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.NextDisplayInfo));
        Assert.Equal(GraphicsModeIds.DefaultMonitor, find.D[0]);
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.NextDisplayInfo));
        Assert.Equal(GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode, find.D[0]);

        // The mapped register path must preserve the public ModeID cursor
        // all the way through the native table, including the real zero key.
        // Keep the direct sequence as the oracle so a future CopperSharp68k
        // implementation can replace the host adapter without changing the
        // guest-visible enumeration order or termination value.
        var directCursor = GraphicsModeIds.Invalid;
        var mappedCursor = GraphicsModeIds.Invalid;
        var mappedModes = new List<uint>();
        while ((directCursor = core.NextDisplayInfo(directCursor)) != GraphicsModeIds.Invalid)
        {
            var mappedState = new M68kCpuState { D = { [0] = mappedCursor } };
            Assert.True(adapter.TryInvoke(mappedState, (int)GraphicsLvo.NextDisplayInfo));
            mappedCursor = mappedState.D[0];
            mappedModes.Add(mappedCursor);
            Assert.Equal(directCursor, mappedCursor);
        }

        var mappedEnd = new M68kCpuState { D = { [0] = mappedCursor } };
        Assert.True(adapter.TryInvoke(mappedEnd, (int)GraphicsLvo.NextDisplayInfo));
        mappedCursor = mappedEnd.D[0];
        Assert.Equal(GraphicsModeIds.Invalid, mappedCursor);
        Assert.Equal(66, mappedModes.Count);

        // FindDisplayInfo's zero-mode compatibility handle is private to the
        // database, but accepting it as a continuation cursor keeps older
        // host callers deterministic without ever publishing it as a mode ID.
        var privateCursor = new M68kCpuState
        {
            D = { [0] = GraphicsDisplayDatabase.DefaultModeHandle }
        };
        Assert.True(adapter.TryInvoke(privateCursor, (int)GraphicsLvo.NextDisplayInfo));
        Assert.Equal(GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode, privateCursor.D[0]);

        find.D[0] = GraphicsModeIds.PalMonitor | GraphicsModeIds.DoubleScanMode;
        Assert.True(adapter.TryInvoke(find, (int)GraphicsLvo.ModeNotAvailable));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoChips, find.D[0]);

        // A recognized PAL monitor part does not make every arbitrary mode
        // key native.  Leave provider-owned/extended keys unclaimed so a
        // future monitor or CyberGraphX patch can answer them.
        find.D[0] = GraphicsModeIds.PalMonitor | 0x0234u;
        Assert.False(adapter.TryInvoke(find, (int)GraphicsLvo.ModeNotAvailable));
        Assert.Equal(GraphicsModeIds.PalMonitor | 0x0234u, find.D[0]);
    }

    [Fact]
    public void DisplayDatabaseDoesNotClaimEcsSuperHiresOnOcsDisplayHardware()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay { SupportsEcsDisplay = false };
        var core = CreateCore(memory, display);
        var superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;

        Assert.Equal(superHires, core.FindDisplayInfo(superHires));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoChips, core.ModeNotAvailable(superHires));

        // The register gateway must carry the same active-chipset capability
        // into ModeNotAvailable; a mapped native caller must not see an ECS
        // SuperHires record as executable merely because the display record
        // itself remains enumerable.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var availability = new M68kCpuState
        {
            D = { [0] = superHires }
        };
        Assert.True(adapter.TryInvoke(availability, (int)GraphicsLvo.ModeNotAvailable));
        Assert.Equal(GraphicsDisplayDatabase.DiAvailNoChips, availability.D[0]);

        Assert.Equal(
            0x30,
            core.GetDisplayInfoData(
                superHires,
                0xC00,
                0x30,
                GraphicsDisplayDatabase.DtagDisp,
                superHires));
        Assert.Equal(
            (ushort)GraphicsDisplayDatabase.DiAvailNoChips,
            ReadWord(memory, 0xC00 + 0x10));

        var mode = GraphicsModeIds.Invalid;
        var sawSuperHires = false;
        while ((mode = core.NextDisplayInfo(mode)) != GraphicsModeIds.Invalid)
            sawSuperHires |= mode == superHires;

        Assert.True(sawSuperHires);
    }

    [Fact]
    public void DisplayDatabaseRejectsEcsSuperHiresDoubleBufferingOnOcsHardware()
    {
        const uint superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;

        // The display record remains enumerable on OCS, but its execution
        // capability is not. AllocDBufInfo must use the same availability
        // boundary as ModeNotAvailable/BestModeIDA rather than treating the
        // generic DIPF_IS_DBUFFER bit as sufficient.
        Assert.True(GraphicsDisplayDatabase.SupportsDoubleBuffering(
            superHires,
            defaultMonitorNtsc: false,
            supportsEcsDisplay: true));
        Assert.False(GraphicsDisplayDatabase.SupportsDoubleBuffering(
            superHires,
            defaultMonitorNtsc: false,
            supportsEcsDisplay: false));

        var hostMemory = new HostGuestMemory(new AmigaBus());
        const uint viewPort = 0x500;
        const uint rasInfo = 0x580;
        hostMemory.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo);
        hostMemory.WriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0);
        hostMemory.WriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            0);

        var allocations = 0;
        using var services = CreateHostGraphicsServices(
            hostMemory,
            getViewPortModeId: _ => superHires,
            supportsEcsDisplay: false,
            allocateMemory: (_, _) =>
            {
                allocations++;
                return 0x1800u;
            });
        var state = new M68kCpuState { A = { [0] = viewPort } };

        services.Invoke(state, (int)GraphicsLvo.AllocDBufInfo);

        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0, allocations);
    }

    [Fact]
    public void DisplayDatabaseResolvesDefaultDisplayInfoHandleForDoubleBuffering()
    {
        Assert.Equal(
            GraphicsDisplayDatabase.DefaultModeHandle,
            GraphicsDisplayDatabase.FindDisplayInfo(GraphicsModeIds.DefaultMonitor));

        Assert.True(GraphicsDisplayDatabase.SupportsDoubleBuffering(
            GraphicsDisplayDatabase.DefaultModeHandle,
            defaultMonitorNtsc: false,
            supportsEcsDisplay: false));
        Assert.True(GraphicsDisplayDatabase.SupportsDoubleBuffering(
            GraphicsDisplayDatabase.DefaultModeHandle,
            defaultMonitorNtsc: true,
            supportsEcsDisplay: false));
    }

    [Fact]
    public void DisplayDatabaseLeavesExtendedMonitorFamiliesToTheirProvider()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var foreignMonitors = new[]
        {
            GraphicsModeIds.VgaMonitor,
            GraphicsModeIds.A2024Monitor,
            GraphicsModeIds.ProtoMonitor,
            GraphicsModeIds.Euro72Monitor,
            GraphicsModeIds.Euro36Monitor,
            GraphicsModeIds.Super72Monitor,
            GraphicsModeIds.DblNtscMonitor,
            GraphicsModeIds.DblPalMonitor
        };

        foreach (var monitor in foreignMonitors)
        {
