        }
    }

    [Fact]
    public void DisplayDatabaseDoesNotSelectEcsSuperHiresOnOcsDisplayHardware()
    {
        var memory = new FakeMemory(0x3000);
        var display = new FakeDisplay { SupportsEcsDisplay = false };
        var core = CreateCore(memory, display);
        const uint superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        const uint tags = 0x900;

        WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagNominalWidth, 1280);
        WriteTag(memory, tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, 256);
        WriteTag(memory, tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth, 1280);
        WriteTag(memory, tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight, 256);
        WriteTag(memory, tags + 32, GraphicsDisplayDatabase.BidTagDepth, 2);
        WriteTag(memory, tags + 40, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(memory, tags + 48, 0, 0);

        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode,
            core.BestModeIDA(tags));

        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x240;
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            1280));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey));
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(memory.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset,
            0));
        Assert.True(memory.TryWriteWord(
            rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset,
            0));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            160));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            256));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            2));

        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode,
            core.CoerceMode(
                viewPort,
                GraphicsModeIds.PalMonitor,
                GraphicsDisplayDatabase.CoercePreserveColors));
        Assert.NotEqual(superHires, core.CoerceMode(
            viewPort,
            GraphicsModeIds.PalMonitor,
            GraphicsDisplayDatabase.CoercePreserveColors));
    }

    [Fact]
    public void DisplayDatabaseReturnsNativeDisplayInfoDimensionMonitorAndNameChunks()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode;
        const uint buffer = 0x800;
        var handle = core.FindDisplayInfo(mode);

        Assert.Equal(0x30, core.GetDisplayInfoData(
            handle,
            buffer,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            0));
        Assert.Equal(GraphicsDisplayDatabase.DtagDisp, ReadLong(memory, buffer));
        Assert.Equal(mode, ReadLong(memory, buffer + 4));
        Assert.Equal(4u, ReadLong(memory, buffer + 12));
        Assert.Equal((ushort)0, ReadWord(memory, buffer + 0x10));
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 0x16)); // Hires ticks/pixel
        Assert.Equal((ushort)70, ReadWord(memory, buffer + 0x1A)); // 70 ns pixels
        Assert.NotEqual(0u, ReadLong(memory, buffer + 0x12) & 1u);
        Assert.Equal((ushort)4096, ReadWord(memory, buffer + 0x1E)); // 4 bits per RGB component
        Assert.Equal((ushort)4, ReadWord(memory, buffer + 0x20)); // ECS standard sprites are 140 ns
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x22));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x28));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x29));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x2A));

        Assert.True(memory.TryWriteLong(buffer + 0x30, 0xA5A5A5A5));
        Assert.True(memory.TryWriteLong(buffer + 0x34, 0xA5A5A5A5));
        Assert.Equal(48, core.GetDisplayInfoData(
            handle,
            buffer,
            GraphicsDisplayDatabase.DisplayInfoChunkSize,
            GraphicsDisplayDatabase.DtagDisp,
            mode));
        Assert.Equal(4u, ReadLong(memory, buffer + 12));
        Assert.Equal((ushort)8, ReadWord(memory, buffer + 0x1C));
        Assert.Equal((ushort)4, ReadWord(memory, buffer + 0x20));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x22));
        Assert.Equal(0xA5A5A5A5u, ReadLong(memory, buffer + 0x30));
        Assert.Equal(0xA5A5A5A5u, ReadLong(memory, buffer + 0x34));

        Assert.Equal(66, core.GetDisplayInfoData(
            handle,
            buffer,
            0x58,
            GraphicsDisplayDatabase.DtagDims,
            mode));
        Assert.Equal((ushort)4, ReadWord(memory, buffer + 0x10));
        Assert.Equal((ushort)32, ReadWord(memory, buffer + 0x12));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x14));
        Assert.Equal((ushort)1008, ReadWord(memory, buffer + 0x16));
        Assert.Equal((ushort)1024, ReadWord(memory, buffer + 0x18));
        Assert.Equal((ushort)639, ReadWord(memory, buffer + 0x1E));
        Assert.Equal((ushort)511, ReadWord(memory, buffer + 0x20));
        Assert.Equal((short)-72, (short)ReadWord(memory, buffer + 0x22));
        Assert.Equal((short)-30, (short)ReadWord(memory, buffer + 0x24));
        Assert.Equal((ushort)651, ReadWord(memory, buffer + 0x26));
        Assert.Equal((ushort)535, ReadWord(memory, buffer + 0x28));

        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            0));
        Assert.Equal((ushort)44, ReadWord(memory, buffer + 0x18)); // monitor-family ViewResolution
        Assert.Equal((ushort)136, ReadWord(memory, buffer + 0x20)); // ViewPositionRange right
        Assert.Equal((ushort)57, ReadWord(memory, buffer + 0x22)); // ViewPositionRange bottom
        Assert.Equal((ushort)312, ReadWord(memory, buffer + 0x24)); // PAL physical rows
        Assert.Equal((ushort)226, ReadWord(memory, buffer + 0x26)); // 280 ns color clocks
        Assert.Equal((ushort)29, ReadWord(memory, buffer + 0x28)); // PAL minimum active row
        Assert.Equal((short)0, (short)ReadWord(memory, buffer + 0x2A)); // MCOMPAT_MIXED
        Assert.Equal((ushort)129, ReadWord(memory, buffer + 0x50)); // original ROM365 Point
        Assert.Equal((ushort)44, ReadWord(memory, buffer + 0x52));
        Assert.Equal(0x00029000u, ReadLong(memory, buffer + 0x54)); // family preferred mode, not input mode

        var monitorSpec = core.OpenMonitor(0, mode);
        Assert.NotEqual(0u, monitorSpec);
        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            mode));
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));

        // The portable default-monitor records use the same PAL timing
        // fallback as OpenMonitor(0,...), so DTAG_MNTR must retain the
        // resident PAL MonitorSpec when queried through a zero-monitor-part
        // ModeID.
        var defaultHandle = core.FindDisplayInfo(
            GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode);
        Assert.Equal(88, core.GetDisplayInfoData(
            defaultHandle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode));
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));

        Assert.Equal(0, core.CloseMonitor(monitorSpec));
        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            mode));
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));

        Assert.Equal(8, core.GetDisplayInfoData(
            handle,
            buffer,
            8,
            GraphicsDisplayDatabase.DtagName,
            0));
        Assert.Equal(GraphicsDisplayDatabase.DtagName, ReadLong(memory, buffer));
        // An unrecognized public tag is a valid zero-result query.  The
        // internal DTAG_VEC tag is covered separately as a provider-owned
        // boundary and must not be confused with this case.
        Assert.Equal(0, core.GetDisplayInfoData(handle, buffer, 0x30, 0x8000_5000u, 0));
        Assert.Equal(-1, core.GetDisplayInfoData(0xDEAD_BEEFu, buffer, 0x30, GraphicsDisplayDatabase.DtagDisp, 0));

        var state = new M68kCpuState
        {
            A = { [0] = handle, [1] = buffer },
            D = { [0] = 0x58, [1] = GraphicsDisplayDatabase.DtagDims, [2] = mode }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetDisplayInfoData));
        Assert.Equal(66u, state.D[0]);
    }

    [Fact]
    public void PrivateMonitorDriverRecordMutationPreservesSourceAndOpaqueFields()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;
        var handle = core.FindDisplayInfo(mode);

        Assert.Equal(88, core.GetDisplayInfoData(
            handle, buffer, 88, GraphicsDisplayDatabase.DtagMntr, mode));
        var baseline = ReadBytes(memory, buffer, 88);
        Assert.True(memory.TryWriteLong(buffer + 20, 0x12345678));
        var source = ReadBytes(memory, buffer, 88);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = buffer },
            D =
            {
                [0] = 88,
                [1] = GraphicsDisplayDatabase.DtagMntr,
                [2] = GraphicsModeIds.PalMonitor
            }
        };

        Assert.True(adapter.TryInvoke(state, GraphicsPrivateLvo.SetDisplayInfoData));
        Assert.Equal(68u, state.D[0]);
        Assert.Equal(source, ReadBytes(memory, buffer, 88));

        Assert.Equal(88, core.GetDisplayInfoData(
            handle, buffer, 88, GraphicsDisplayDatabase.DtagMntr, mode));
        var expected = baseline.ToArray();
        expected[20] = 0x12;
        expected[21] = 0x34;
        expected[22] = 0x56;
        expected[23] = 0x78;
        Assert.Equal(expected, ReadBytes(memory, buffer, 88));

        // The private prefix is not part of the returned count, but the
        // Mspc LONG at offset16 is included in a size-20 transfer.
        Assert.True(memory.TryWriteLong(buffer + 16, 0x87654321));
        state.D[0] = 20;
        Assert.True(adapter.TryInvoke(state, GraphicsPrivateLvo.SetDisplayInfoData));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(88, core.GetDisplayInfoData(
            handle, buffer, 88, GraphicsDisplayDatabase.DtagMntr, mode));
        Assert.Equal(0x87654321u, ReadLong(memory, buffer + 16));

        state.D[1] = 0x8000_5000u;
        Assert.False(adapter.TryInvoke(state, GraphicsPrivateLvo.SetDisplayInfoData));
        Assert.Equal(1u, state.D[0]);
    }

    [Fact]
    public async Task NativeMonitorPublicationAndReleaseAreSerialized()
    {
        var backing = new FakeMemory(0x20000);
        const uint graphics = 0x800;
        var image = GraphicsLibraryImageLayout.CreateGuestImage(
            graphics,
            0x264,
            0,
            0x264,
            40,
            68,
            "graphics.library",
            "graphics.library 40.68",
            GraphicsLibraryImageProfile.NativePal,
            true);
        Array.Copy(image, 0, backing.Bytes, (int)graphics, image.Length);

        var allocator = new BlockingNativeDatabaseAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            backing,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: graphics);

        var publish = Task.Run(core.TryPublishNativeDisplayDatabase);
        Assert.True(allocator.AllocationEntered.Wait(TimeSpan.FromSeconds(5)));

        var release = Task.Run(core.ReleaseNativeDisplayDatabase);
        // Without the monitor-state gate, release observes the not-yet-owned
        // candidate and returns early, leaving the later publication leaked.
        var earlyRelease = await Task.WhenAny(
            release,
            Task.Delay(TimeSpan.FromMilliseconds(100)));
        Assert.NotSame(release, earlyRelease);

        allocator.ContinueAllocation.Set();
        Assert.True(await publish);
        await release;
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(
            0u,
            ReadLong(
                backing,
                graphics + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
    }

    [Fact]
    public async Task NativeOverlayOpenMonitorKeepsRebindBehindAdmissionAndCommit()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;

        static void InitializeNativeMonitorList(FakeMemory target, uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeMonitorList(memory, firstBase);
        InitializeNativeMonitorList(memory, secondBase);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);
        using var admissionEntered = new ManualResetEventSlim();
        using var continueAdmission = new ManualResetEventSlim();
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (_, _) =>
            {
                admissionEntered.Set();
                Assert.True(continueAdmission.Wait(TimeSpan.FromSeconds(5)));
                return true;
            });
        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0 }
        };

        var open = Task.Run(() => adapter.TryInvoke(
            state,
            (int)GraphicsLvo.OpenMonitor,
            nativeOverlay: true));
        Assert.True(admissionEntered.Wait(TimeSpan.FromSeconds(5)));

        var rebind = Task.Run(() => core.RebindGraphicsLibraryBase(secondBase));
        var earlyCompletion = await Task.WhenAny(
            rebind,
            Task.Delay(TimeSpan.FromMilliseconds(100)));
        Assert.NotSame(rebind, earlyCompletion);

        continueAdmission.Set();
        Assert.True(await open);
        var monitor = state.D[0];
        Assert.NotEqual(0u, monitor);
        Assert.Equal(firstBase, await rebind);
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
        Assert.Equal(
            monitor,
            ReadLong(
                memory,
                secondBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
    }

    [Fact]
    public async Task NativeOverlayCloseMonitorKeepsRebindBehindAdmissionAndCommit()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;

        static void InitializeNativeMonitorList(FakeMemory target, uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeMonitorList(memory, firstBase);
        InitializeNativeMonitorList(memory, secondBase);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);

        using var admissionEntered = new ManualResetEventSlim();
        using var continueAdmission = new ManualResetEventSlim();
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (_, _) =>
            {
                admissionEntered.Set();
                Assert.True(continueAdmission.Wait(TimeSpan.FromSeconds(5)));
                return true;
            });
        var state = new M68kCpuState
        {
            A = { [0] = monitor },
            D = { [0] = 0xCAFE_BABEu }
        };

        var close = Task.Run(() => adapter.TryInvoke(
            state,
            (int)GraphicsLvo.CloseMonitor,
            nativeOverlay: true));
        Assert.True(admissionEntered.Wait(TimeSpan.FromSeconds(5)));

        var rebind = Task.Run(() => core.RebindGraphicsLibraryBase(secondBase));
        var earlyCompletion = await Task.WhenAny(
            rebind,
