        Assert.Equal(0u, state.D[0]);
        Assert.Equal(firstBase, await rebind);
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
        Assert.Equal(
            monitor,
            ReadLong(
                memory,
                secondBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            (ushort)0,
            ReadWord(
                memory,
                monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
