            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeMonitorList(memory, firstBase);
        InitializeNativeMonitorList(memory, secondBase);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);
        using var admissionEntered = new ManualResetEventSlim();
        using var continueAdmission = new ManualResetEventSlim();
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (_, _) =>
            {
                admissionEntered.Set();
                Assert.True(continueAdmission.Wait(TimeSpan.FromSeconds(5)));
                return true;
            });
        var state = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D =
            {
                [0] = GraphicsMonitorInfoImage.TransferSize,
                [1] = GraphicsDisplayDatabase.DtagMntr,
                [2] = mode
            }
