    [Fact]
    public async Task NativeOverlayChangeVPBitMapKeepsRebindBehindAdmissionAndCommit()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;
        const uint viewPort = 0x1800;
        const uint rasInfo = 0x1900;
        const uint currentBitMap = 0x2000;
        const uint nextBitMap = 0x2100;

        static void InitializeNativeMonitorList(FakeMemory target, uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(target.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(target.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeMonitorList(memory, firstBase);
        InitializeNativeMonitorList(memory, secondBase);
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            currentBitMap));
        foreach (var bitMap in new[] { currentBitMap, nextBitMap })
        {
            Assert.True(memory.TryWriteWord(
                bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
                2));
            Assert.True(memory.TryWriteByte(
                bitMap + (uint)GraphicsLayouts.BitMapDepth,
                1));
        }

        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);
        using var admissionEntered = new ManualResetEventSlim();
        using var continueAdmission = new ManualResetEventSlim();
        var association = rasInfo + (uint)GraphicsLayouts.RasInfoBitMap;
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, _) =>
            {
                if (address == association)
                {
                    admissionEntered.Set();
                    Assert.True(continueAdmission.Wait(TimeSpan.FromSeconds(5)));
                }

                return true;
            });
        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 131,
            ProgramCounter = 0x0012_3715
        };

        var change = Task.Run(() => adapter.TryInvoke(
            state,
            (int)GraphicsLvo.ChangeVPBitMap,
            nativeOverlay: true));
        Assert.True(admissionEntered.Wait(TimeSpan.FromSeconds(5)));

        var rebind = Task.Run(() => core.RebindGraphicsLibraryBase(secondBase));
        var earlyCompletion = await Task.WhenAny(
            rebind,
            Task.Delay(TimeSpan.FromMilliseconds(100)));
        Assert.NotSame(rebind, earlyCompletion);

        continueAdmission.Set();
        Assert.True(await change);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(131, state.Cycles);
        Assert.Equal(0x0012_3715u, state.ProgramCounter);
        Assert.Equal(nextBitMap, ReadLong(memory, association));
        Assert.Equal(firstBase, await rebind);
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
    }

