    [Fact]
    public void DisplayDatabaseLeavesInternalVectorChunksForMonitorProviders()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;

        // DTAG_VEC is explicitly internal-use-only in graphics/displayinfo.h.
        // A portable public query must not claim it with a zero result, or a
        // resident monitor/provider would never get a chance to publish its
        // private VecInfo record.
        Assert.Equal(
            GraphicsDisplayDatabase.Failure,
            core.GetDisplayInfoData(
                core.FindDisplayInfo(mode),
                buffer,
                0x60,
                GraphicsDisplayDatabase.DtagVec,
                mode));

        var state = new M68kCpuState
        {
            A = { [0] = core.FindDisplayInfo(mode), [1] = buffer },
            D =
            {
                [0] = 0x60,
                [1] = GraphicsDisplayDatabase.DtagVec,
                [2] = mode,
                [7] = 0xCAFE_BABEu
            }
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.GetDisplayInfoData));
        Assert.Equal(0x60u, state.D[0]);
        Assert.Equal(GraphicsDisplayDatabase.DtagVec, state.D[1]);
        Assert.Equal(mode, state.D[2]);
        Assert.Equal(0xCAFE_BABEu, state.D[7]);
    }

    [Fact]
    public void DisplayDatabaseTerminatesTruncatedNameChunks()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0x900;

        Assert.Equal(
            20,
            core.GetDisplayInfoData(
                core.FindDisplayInfo(mode),
                buffer,
                20,
                GraphicsDisplayDatabase.DtagName,
                0));

        Assert.Equal(GraphicsDisplayDatabase.DtagName, ReadLong(memory, buffer));
        Assert.Equal(mode, ReadLong(memory, buffer + 4));
        Assert.Equal((byte)'P', ReadByte(memory, buffer + 0x10));
        Assert.Equal((byte)'A', ReadByte(memory, buffer + 0x11));
        Assert.Equal((byte)'L', ReadByte(memory, buffer + 0x12));
        Assert.Equal(0, ReadByte(memory, buffer + 19));
    }

    [Fact]
    public void DisplayDatabaseLazilyPublishesTheResidentMonitorForDtagMntr()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FixedAddressAllocator(0x1800);
        var core = CreateCore(memory, allocator: allocator);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;

        // DTAG_MNTR returns the monitor-list object referenced by the
        // display record.  It is valid before an explicit OpenMonitor call;
        // the query creates a resident object with an open count of zero.
        Assert.Equal(
            88,
            core.GetDisplayInfoData(
                0,
                buffer,
                0x60,
                GraphicsDisplayDatabase.DtagMntr,
                mode));
        var monitorSpec = ReadLong(memory, buffer + 0x10);
        Assert.NotEqual(0u, monitorSpec);
        Assert.Equal((ushort)0,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);
        // The resident object is discoverable but not caller-open.  A close
        // without a matching OpenMonitor must fail without reclaiming or
        // mutating that zero-count node.
        Assert.Equal(1, core.CloseMonitor(monitorSpec));
        Assert.Equal((ushort)0,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);

        // An explicit open reuses that resident node and increments only its
        // public count; a second query does not create a duplicate object.
        Assert.Equal(monitorSpec, core.OpenMonitor(0, mode));
        Assert.Equal((ushort)1,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(monitorSpec, core.OpenMonitor(0, mode));
        Assert.Equal((ushort)2,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            88,
            core.GetDisplayInfoData(
                core.FindDisplayInfo(mode),
                buffer,
                0x60,
                GraphicsDisplayDatabase.DtagMntr,
                mode));
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));
        Assert.Equal((ushort)2,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = buffer },
            D =
            {
                [0] = 0x60,
                [1] = GraphicsDisplayDatabase.DtagMntr,
                [2] = mode
            }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetDisplayInfoData));
        Assert.Equal(88u, state.D[0]);
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));

        Assert.Equal(0, core.CloseMonitor(monitorSpec));
        Assert.Equal((ushort)1,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, core.CloseMonitor(monitorSpec));
        Assert.Equal((ushort)0,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
    }

    [Fact]
    public void DisplayDatabaseZeroSizedDtagMntrDoesNotCreateAResidentMonitor()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FixedAddressAllocator(0x1800);
        var core = CreateCore(memory, allocator: allocator);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;

        // A zero-sized query has no destination bytes.  It must not build the
        // monitor chunk merely to discover that there is nothing to copy,
        // because DTAG_MNTR construction can publish a resident MonitorSpec.
        Assert.Equal(
            0,
            core.GetDisplayInfoData(
                0,
                0xA00,
                0,
                GraphicsDisplayDatabase.DtagMntr,
                mode));
        Assert.Equal((byte)0,
            ReadByte(memory, 0x1800 +
                             (uint)GraphicsLayouts.MonitorSpecNodeType));
    }

    [Fact]
    public void DisplayDatabaseLazyResidentDoesNotRequireATemporaryCloseWrite()
    {
        var backing = new FakeMemory(0x4000);
        var allocator = new FixedAddressAllocator(0x1800);
        var memory = new RejectingMonitorCloseMemory(
            backing,
            0x1800u + (uint)GraphicsLayouts.MonitorSpecOpenCount);
        var core = CreateCore(memory, allocator: allocator);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;

        // A legacy temporary OpenMonitor/CloseMonitor implementation would
        // reach this rejected word write after publishing a count-one
        // resident.  The lazy DTAG_MNTR constructor must publish count zero
        // directly and therefore still return a stable resident pointer.
        Assert.Equal(
            88,
            core.GetDisplayInfoData(
                0,
                buffer,
                0x60,
                GraphicsDisplayDatabase.DtagMntr,
                mode));
        var monitorSpec = ReadLong(backing, buffer + 0x10);
        Assert.NotEqual(0u, monitorSpec);
        Assert.Equal((ushort)0,
            ReadWord(backing, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);
    }

    [Fact]
    public void DefaultMonitorDisplayDataAndMonitorSpecFollowActiveNtscProfile()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay { IsNtsc = true };
        var core = CreateCore(memory, display);
        const uint mode = GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;
        var handle = core.FindDisplayInfo(mode);

        Assert.Equal(mode, handle);
        Assert.Equal(66, core.GetDisplayInfoData(
            handle,
            buffer,
            0x58,
            GraphicsDisplayDatabase.DtagDims,
            mode));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x14));
        Assert.Equal((ushort)1024, ReadWord(memory, buffer + 0x18));
        Assert.Equal((ushort)199, ReadWord(memory, buffer + 0x20));

        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            mode));
        Assert.Equal((ushort)262, ReadWord(memory, buffer + 0x24));
        Assert.Equal((ushort)21, ReadWord(memory, buffer + 0x28));
        var residentMonitor = ReadLong(memory, buffer + 0x10);
        Assert.NotEqual(0u, residentMonitor);
        Assert.Equal((ushort)0,
            ReadWord(memory, residentMonitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        var monitorSpec = core.OpenMonitor(0, mode);
        Assert.Equal(residentMonitor, monitorSpec);
        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            mode));
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));
        Assert.Equal(0, core.CloseMonitor(monitorSpec));
        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            mode));
        Assert.Equal(monitorSpec, ReadLong(memory, buffer + 0x10));

        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 200);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5);
        Assert.Equal(
            GraphicsModeIds.NtscMonitor,
            core.CoerceMode(
                viewPort,
                0,
                GraphicsDisplayDatabase.CoercePreserveColors));

        const uint tags = 0x500;
        WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagNominalWidth, 640);
        WriteTag(memory, tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, 200);
        WriteTag(memory, tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth, 640);
        WriteTag(memory, tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight, 200);
        WriteTag(memory, tags + 32, GraphicsDisplayDatabase.BidTagDepth, 1);
        Assert.True(memory.TryWriteLong(tags + 40, 0));
        Assert.Equal(
            GraphicsModeIds.DefaultMonitor | GraphicsModeIds.HiresMode,
            core.BestModeIDA(tags));
    }

    [Fact]
    public void DisplayDatabaseExposesEcsSuperHiresGeometryThroughPureAndRegisterPaths()
    {
        var memory = new FakeMemory(0x3000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey;
        const uint buffer = 0xA00;
        var handle = core.FindDisplayInfo(mode);

        Assert.Equal(mode, handle);
        Assert.Equal(66, core.GetDisplayInfoData(
            handle,
            buffer,
            0x58,
            GraphicsDisplayDatabase.DtagDims,
            mode));
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 0x10));
        Assert.Equal((ushort)64, ReadWord(memory, buffer + 0x12));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x14));
        Assert.Equal((ushort)1008, ReadWord(memory, buffer + 0x16));
        Assert.Equal((ushort)1024, ReadWord(memory, buffer + 0x18));
        Assert.Equal((ushort)1279, ReadWord(memory, buffer + 0x1E));
        Assert.Equal((ushort)511, ReadWord(memory, buffer + 0x20));
        Assert.Equal((short)-144, (short)ReadWord(memory, buffer + 0x22));
        Assert.Equal((short)-30, (short)ReadWord(memory, buffer + 0x24));
        Assert.Equal((ushort)1295, ReadWord(memory, buffer + 0x26));
        Assert.Equal((ushort)535, ReadWord(memory, buffer + 0x28));

        var state = new M68kCpuState
        {
            A = { [0] = handle, [1] = buffer },
            D = { [0] = 0x30, [1] = GraphicsDisplayDatabase.DtagDisp, [2] = mode }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetDisplayInfoData));
        Assert.Equal(0x30u, state.D[0]);
        Assert.Equal(mode, ReadLong(memory, buffer + 4));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x16)); // 35 ns SuperHires pixels
        Assert.Equal((ushort)35, ReadWord(memory, buffer + 0x1A));
        Assert.Equal((ushort)4096, ReadWord(memory, buffer + 0x1E)); // 4 bits per RGB component in interlace
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 0x20)); // SuperHires sprites position at 70 ns
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x22));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x28));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x29));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x2A));
        Assert.Equal(0x0000_0010u, ReadLong(memory, buffer + 0x12) & 0x0000_0010u); // DIPF_IS_ECS
        Assert.NotEqual(0u, ReadLong(memory, buffer + 0x12) & 0x0000_0040u); // standard sprites remain available
        Assert.Equal(0u, ReadLong(memory, buffer + 0x12) & 0x0000_2000u); // attached sprites unavailable

        Assert.Equal(88, core.GetDisplayInfoData(
            handle,
            buffer,
            0x60,
            GraphicsDisplayDatabase.DtagMntr,
            mode));
        Assert.Equal((ushort)44, ReadWord(memory, buffer + 0x18)); // monitor-family resolution, not SuperHires pixel ticks
        Assert.Equal((ushort)312, ReadWord(memory, buffer + 0x24));
        Assert.Equal((ushort)226, ReadWord(memory, buffer + 0x26));
        Assert.Equal((ushort)29, ReadWord(memory, buffer + 0x28));

        const uint bestTags = 0x700;
        WriteTag(memory, bestTags, GraphicsDisplayDatabase.BidTagNominalWidth, 1280);
        WriteTag(memory, bestTags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, 256);
        WriteTag(memory, bestTags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth, 1280);
        WriteTag(memory, bestTags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight, 256);
        WriteTag(memory, bestTags + 32, GraphicsDisplayDatabase.BidTagDepth, 2);
        WriteTag(memory, bestTags + 40, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(memory, bestTags + 48, GraphicsDisplayDatabase.BidTagRedBits, 2);
        WriteTag(memory, bestTags + 56, GraphicsDisplayDatabase.BidTagBlueBits, 2);
        WriteTag(memory, bestTags + 64, GraphicsDisplayDatabase.BidTagGreenBits, 2);
        WriteTag(memory, bestTags + 72, 0, 0);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            core.BestModeIDA(bestTags));
    }

    [Fact]
    public void DisplayDatabaseBestModeHonorsColorComponentMinimumsAndSuperHiresInterlacePrecision()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint tags = 0x500;

        WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagNominalWidth, 1280);
        WriteTag(memory, tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, 256);
        WriteTag(memory, tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth, 1280);
        WriteTag(memory, tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight, 256);
        WriteTag(memory, tags + 32, GraphicsDisplayDatabase.BidTagDepth, 2);
        WriteTag(memory, tags + 40, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(memory, tags + 48, GraphicsDisplayDatabase.BidTagRedBits, 4);
        WriteTag(memory, tags + 56, GraphicsDisplayDatabase.BidTagBlueBits, 4);
        WriteTag(memory, tags + 64, GraphicsDisplayDatabase.BidTagGreenBits, 4);
        WriteTag(memory, tags + 72, 0, 0);

        // The four-bit request must not select progressive SuperHires.  A
        // lower-precision ordinary Hires mode may still be returned as the
        // closest geometry match by BestModeIDA.
        Assert.NotEqual(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            core.BestModeIDA(tags));

        WriteTag(memory, tags + 48, GraphicsDisplayDatabase.BidTagRedBits, 2);
        WriteTag(memory, tags + 56, GraphicsDisplayDatabase.BidTagBlueBits, 2);
        WriteTag(memory, tags + 64, GraphicsDisplayDatabase.BidTagGreenBits, 2);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            core.BestModeIDA(tags));

        const uint buffer = 0xA00;
        var progressive = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        Assert.Equal(progressive, core.FindDisplayInfo(progressive));
        Assert.Equal(0x30, core.GetDisplayInfoData(
            progressive,
            buffer,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            progressive));
        Assert.Equal((ushort)64, ReadWord(memory, buffer + 0x1E));
        Assert.Equal((byte)2, ReadByte(memory, buffer + 0x28));
        Assert.Equal((byte)2, ReadByte(memory, buffer + 0x29));
        Assert.Equal((byte)2, ReadByte(memory, buffer + 0x2A));

        var interlaced = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresLaceKey;
        Assert.Equal(interlaced, core.FindDisplayInfo(interlaced));
        Assert.Equal(0x30, core.GetDisplayInfoData(
            interlaced,
            buffer,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            interlaced));
        Assert.Equal((ushort)4096, ReadWord(memory, buffer + 0x1E));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x28));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x29));
        Assert.Equal((byte)4, ReadByte(memory, buffer + 0x2A));
    }

