    [Fact]
    public void DisplayDatabaseAndOpenMonitorShareScanTimingButNotViewPositionRange()
    {
        var memory = new FakeMemory(0x10000);
        var core = CreateCore(memory, allocator: new SequenceAddressAllocator(0x1000, 0x1200));
        const uint buffer = 0x7000;

        foreach (var (mode, pal) in new[]
        {
            (GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode, true),
            (GraphicsModeIds.NtscMonitor | GraphicsModeIds.HiresMode, false)
        })
        {
            var timing = GraphicsNativeMonitorTiming.For(pal);
            var monitor = core.OpenMonitor(0, mode);
            Assert.NotEqual(0u, monitor);

            Assert.Equal(
                88,
                core.GetDisplayInfoData(
                    core.FindDisplayInfo(mode),
                    buffer,
                    0x60,
                    GraphicsDisplayDatabase.DtagMntr,
                    mode));
            Assert.Equal(monitor, ReadLong(memory, buffer + 0x10));
            Assert.Equal(timing.TotalRows, ReadWord(memory, buffer + 0x24));
            Assert.Equal(timing.TotalColorClocks, ReadWord(memory, buffer + 0x26));
            Assert.Equal(timing.MinRow, ReadWord(memory, buffer + 0x28));
            Assert.Equal((ushort)0, ReadWord(memory, buffer + 0x2A));
            Assert.Equal((ushort)93, ReadWord(memory, buffer + 0x1C));
            Assert.Equal((ushort)(pal ? 29 : 21), ReadWord(memory, buffer + 0x1E));
            Assert.Equal((ushort)136, ReadWord(memory, buffer + 0x20));
            Assert.Equal((ushort)(pal ? 57 : 63), ReadWord(memory, buffer + 0x22));

            Assert.Equal(
                timing.TotalRows,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecTotalRows));
            Assert.Equal(
                timing.TotalColorClocks,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecTotalColorClocks));
            Assert.Equal(
                timing.DeniseMinDisplayColumn,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecDeniseMinDisplayColumn));
            Assert.Equal(
                timing.DeniseMaxDisplayColumn,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecDeniseMaxDisplayColumn));
            Assert.Equal(
                timing.BeamCon0,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecBeamCon0));
            Assert.Equal(
                timing.MinRow,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecMinRow));
            Assert.Equal(
                timing.LegalViewLeft,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecLegalView));
            Assert.Equal(
                timing.LegalViewTop,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecLegalView + 2));
            Assert.Equal(
                timing.LegalViewRight,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecLegalView + 4));
            Assert.Equal(
                timing.LegalViewBottom,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecLegalView + 6));

            Assert.Equal(0, core.CloseMonitor(monitor));
        }
    }

    [Fact]
    public void GetDisplayInfoDataRestoresTheGuestChunkWhenALateWriteFails()
    {
        var backing = new FakeMemory(0x3000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;

        for (var offset = 0; offset < 0x30; offset++)
            Assert.True(backing.TryWriteByte(buffer + (uint)offset, 0xCC));

        // The full destination admission probe has to complete first; fail
        // the third actual output byte so this remains a rollback test.
        memory.FailOnNextByteWrite(0x30 + 3);
        Assert.Equal(
            0,
            core.GetDisplayInfoData(
                core.FindDisplayInfo(mode),
                buffer,
                0x30,
                GraphicsDisplayDatabase.DtagDisp,
                mode));

        for (var offset = 0; offset < 0x30; offset++)
            Assert.Equal((byte)0xCC, ReadByte(backing, buffer + (uint)offset));
    }

    [Fact]
    public void GetDisplayInfoDataDoesNotAllocateAMonitorForAnUnwritableDestination()
    {
        var backing = new FakeMemory(0x3000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new FakeAllocator();
        var core = CreateCore(memory, allocator: allocator);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        const uint buffer = 0xA00;

        // DTAG_MNTR normally discovers a resident MonitorSpec lazily. A
        // failure at a later byte of the complete output envelope is still
        // not a monitor-open request, so admission must finish before the
        // allocation is allowed to occur.
        memory.FailOnNextByteWrite(24);
        Assert.Equal(
            0,
            core.GetDisplayInfoData(
                core.FindDisplayInfo(mode),
                buffer,
                0x60,
                GraphicsDisplayDatabase.DtagMntr,
                mode));
        Assert.Equal(0u, allocator.LastAllocatedBytes);
    }

    [Fact]
    public void BestModeIdTreatsZeroTagMoreAsTheEndOfTheTagList()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint tags = 0x600;

        WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagNominalWidth, 640);
        WriteTag(memory, tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, 200);
        WriteTag(memory, tags + 16, 2u, 0); // TAG_MORE with a null continuation

        var terminatedByMore = core.BestModeIDA(tags);
        Assert.NotEqual(GraphicsModeIds.Invalid, terminatedByMore);

        WriteTag(memory, tags + 16, 0, 0);
        Assert.Equal(terminatedByMore, core.BestModeIDA(tags));
    }

    [Fact]
    public void BestModeIdAcceptsACompleteTagItemAtTheGuestAddressEnd()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint tags = 0xFFFF_FFF8u;

        // The eight-byte TAG_END item occupies FFFFFFF8..FFFFFFFF exactly.
        // It is a legal aligned 68000 envelope even though the next list
        // address wraps to zero; a guard using max-8 would reject it before
        // the tag can terminate the request.
        memory.WriteLong(tags, 0);
        memory.WriteLong(tags + 4u, 0);

        var expected = core.BestModeIDA(0);
        Assert.NotEqual(GraphicsModeIds.Invalid, expected);
        Assert.Equal(expected, core.BestModeIDA(tags));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BestModeIDA));
        Assert.Equal(expected, state.D[0]);
        Assert.Equal(211, state.Cycles);
    }

    [Fact]
    public void BestModeIdRejectsANonTerminalTagItemThatWrapsItsContinuation()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint tags = 0xFFFF_FFF8u;

        // A final non-TAG_END item must not become a valid request merely
        // because the cursor wraps to zero after its complete envelope.
        memory.WriteLong(tags, GraphicsDisplayDatabase.BidTagNominalWidth);
        memory.WriteLong(tags + 4u, 640);

        Assert.Equal(GraphicsModeIds.Invalid, core.BestModeIDA(tags));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BestModeIDA));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(211, state.Cycles);
    }

    [Fact]
    public void GetDisplayInfoDataAcceptsTheFinalGuestByteAndRejectsCrossingOutput()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;
        var handle = core.FindDisplayInfo(mode);
        const uint exactBuffer = 0xFFFF_FFD0u;
        const uint crossingBuffer = 0xFFFF_FFD1u;
        const uint chunkSize = 0x30;

        // The complete DTAG_DISP chunk occupies FFFFFFD0..FFFFFFFF exactly.
        // The output buffer is byte-addressed, so an odd start is valid when
        // its inclusive end remains inside the 32-bit guest address space.
        for (var offset = 0u; offset < chunkSize; offset++)
            memory.WriteByte(crossingBuffer + offset, 0xA5);

        var state = new M68kCpuState
        {
            A = { [0] = handle, [1] = crossingBuffer },
            D =
            {
                [0] = chunkSize,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = mode,
                [7] = 0xCAFE_BABEu
            },
            Cycles = 211
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.GetDisplayInfoData));
        Assert.Equal(chunkSize, state.D[0]);
        Assert.Equal(0xCAFE_BABEu, state.D[7]);
        Assert.Equal(211, state.Cycles);
        // Only the in-range prefix is a guest byte.  The final logical byte
        // would alias address zero under permissive host arithmetic and must
        // never be consulted by the guarded writer.
        for (var offset = 0u; offset < chunkSize - 1u; offset++)
            Assert.Equal((byte)0xA5, ReadByte(memory, crossingBuffer + offset));

        for (var offset = 0u; offset < chunkSize; offset++)
            memory.WriteByte(exactBuffer + offset, 0xCC);

        Assert.Equal(
            (int)chunkSize,
            core.GetDisplayInfoData(
                handle,
                exactBuffer,
                chunkSize,
                GraphicsDisplayDatabase.DtagDisp,
                mode));
        Assert.Equal(GraphicsDisplayDatabase.DtagDisp, ReadLong(memory, exactBuffer));
        Assert.Equal(mode, ReadLong(memory, exactBuffer + 4u));
    }

    [Fact]
    public void GetDisplayInfoDataKeepsEcsMonitorDiscoveryWhenChipsAreUnavailable()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay { SupportsEcsDisplay = false };
        var core = CreateCore(memory, display);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        const uint buffer = 0x1200;
        var handle = core.FindDisplayInfo(mode);

        // The display record remains discoverable on an OCS host even though
        // the selected ECS SuperHires mode cannot execute on that chipset.
        // DTAG_DISP carries the no-chip availability result; DTAG_MNTR still
        // exposes the resident PAL timing object needed by mode databases and
        // native/provider takeover.
        Assert.Equal(
            48,
            core.GetDisplayInfoData(
                handle,
                buffer,
                GraphicsDisplayDatabase.DisplayInfoChunkSize,
                GraphicsDisplayDatabase.DtagDisp,
                mode));
        Assert.Equal(
            (ushort)GraphicsDisplayDatabase.DiAvailNoChips,
            ReadWord(memory, buffer + 0x10));

        Assert.Equal(
            88,
            core.GetDisplayInfoData(
                handle,
                buffer,
                0x60,
                GraphicsDisplayDatabase.DtagMntr,
                mode));
        var monitorSpec = ReadLong(memory, buffer + 0x10);
        Assert.NotEqual(0u, monitorSpec);
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            (ushort)312,
            ReadWord(memory, buffer + 0x24));
    }

    [Fact]
    public void DisplayDatabaseExposesEcsSuperHiresDualPlayfieldProperties()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresDualPlayfieldKey;
        const uint buffer = 0xB00;
        var handle = core.FindDisplayInfo(mode);

        Assert.Equal(mode, handle);
        Assert.Equal(66, core.GetDisplayInfoData(
            handle,
            buffer,
            0x58,
            GraphicsDisplayDatabase.DtagDims,
            mode));
        Assert.Equal((ushort)2, ReadWord(memory, buffer + 0x10));
        Assert.Equal((ushort)64, ReadWord(memory, buffer + 0x12));
        Assert.Equal((ushort)1, ReadWord(memory, buffer + 0x14));
        Assert.Equal((ushort)1008, ReadWord(memory, buffer + 0x16));
        Assert.Equal((ushort)1024, ReadWord(memory, buffer + 0x18));
        Assert.Equal((short)-144, (short)ReadWord(memory, buffer + 0x22));
        Assert.Equal((short)-15, (short)ReadWord(memory, buffer + 0x24));
        Assert.Equal((ushort)1295, ReadWord(memory, buffer + 0x26));
        Assert.Equal((ushort)267, ReadWord(memory, buffer + 0x28));

        Assert.Equal(0x30, core.GetDisplayInfoData(
            handle,
            buffer,
            0x30,
            GraphicsDisplayDatabase.DtagDisp,
            mode));
        var properties = ReadLong(memory, buffer + 0x12);
        Assert.NotEqual(0u, properties & 0x0000_0002u); // DIPF_IS_DUALPF
        Assert.NotEqual(0u, properties & 0x0000_0010u); // DIPF_IS_ECS
        Assert.NotEqual(0u, properties & 0x0000_0040u); // standard sprites remain available
        Assert.Equal(0u, properties & 0x0000_2000u); // attached sprites unavailable

        const uint tags = 0x500;
        WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagNominalWidth, 1280);
        WriteTag(memory, tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, 256);
        WriteTag(memory, tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth, 1280);
        WriteTag(memory, tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight, 256);
        WriteTag(memory, tags + 32, GraphicsDisplayDatabase.BidTagDepth, 2);
        WriteTag(memory, tags + 40, GraphicsDisplayDatabase.BidTagMonitorId, GraphicsModeIds.PalMonitor);
        WriteTag(memory, tags + 48, GraphicsDisplayDatabase.BidTagDipfMustHave, 0x0000_0002u);
        WriteTag(memory, tags + 56, GraphicsDisplayDatabase.BidTagDipfMustNotHave, 0);
        WriteTag(memory, tags + 64, GraphicsDisplayDatabase.BidTagRedBits, 2);
        WriteTag(memory, tags + 72, GraphicsDisplayDatabase.BidTagBlueBits, 2);
        WriteTag(memory, tags + 80, GraphicsDisplayDatabase.BidTagGreenBits, 2);
        WriteTag(memory, tags + 88, 0, 0);
        Assert.Equal(mode, core.BestModeIDA(tags));
    }

