        var standardModes = new[]
        {
            GraphicsModeIds.PalMonitor,
            GraphicsModeIds.NtscMonitor | GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.ExtraHalfBriteKey,
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresDualPlayfieldTwoKey
        };

        foreach (var mode in standardModes)
        {
            var handle = core.FindDisplayInfo(mode);
            Assert.Equal(mode, handle);
            Assert.Equal(
                0x30,
                core.GetDisplayInfoData(
                    handle,
                    buffer,
                    0x30,
                    GraphicsDisplayDatabase.DtagDisp,
                    mode));

            var properties = ReadLong(memory, buffer + 0x12);
            Assert.NotEqual(0u, properties & GraphicsDisplayDatabase.DipfIsSprites);
            Assert.NotEqual(0u, properties & GraphicsDisplayDatabase.DipfIsSpritesAttached);
            Assert.Equal(0u, properties & GraphicsDisplayDatabase.DipfIsEcs);
        }

        var superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        Assert.Equal(superHires, core.FindDisplayInfo(superHires));
