    [Fact]
    public void OpenAndCloseMonitorBuildNativePalNtscSpecsAndGuardForeignRequests()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new SteppingAllocator(0x1000);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint ntscName = 0x6000;
        WriteAscii(memory, ntscName, "ntsc.monitor");

        var ntsc = core.OpenMonitor(ntscName, GraphicsModeIds.PalMonitor);
        Assert.NotEqual(0u, ntsc);
        Assert.Equal((byte)18, ReadByte(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecNodeType));
        Assert.Equal((byte)2, ReadByte(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecNodeSubsystem));
        Assert.Equal((byte)4, ReadByte(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecNodeSubtype));
        Assert.Equal(ntscName, ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecNodeName));
        Assert.Equal((ushort)1, ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecFlags));
        Assert.Equal((ushort)262, ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecTotalRows));
        Assert.Equal((ushort)21, ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecMinRow));
        Assert.Equal((ushort)1, ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoDataBaseTail,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoDataBaseHead));
        Assert.Equal(
            ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoDataBase,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoDataBaseTailPred));
        Assert.Equal(
            0u,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoDataBaseTail));
        Assert.Equal(
            (byte)15,
            ReadByte(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreNodeType));
        Assert.Equal(
            ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreWaitQueue + 4,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreWaitQueue));
        Assert.Equal(
            0u,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreWaitQueue + 4));
        Assert.Equal(
            ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreWaitQueue,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreWaitQueue + 8));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreNestCount));
        Assert.Equal(
            0u,
            ReadLong(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreOwner));
        Assert.Equal(
            ushort.MaxValue,
            ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecDisplayInfoSemaphoreQueueCount));
        Assert.Equal(0, core.CloseMonitor(ntsc));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);

        WriteAscii(memory, ntscName, "NTSC.MONITOR");
        var uppercaseNtsc = core.OpenMonitor(ntscName, GraphicsModeIds.PalMonitor);
        Assert.Equal(0u, uppercaseNtsc);
        Assert.Equal((ushort)0, ReadWord(memory, ntsc + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        WriteAscii(memory, ntscName, "ntsc.monitor");

        var pal = core.OpenMonitor(0, GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode);
        Assert.NotEqual(0u, pal);
        Assert.Equal((ushort)2, ReadWord(memory, pal + (uint)GraphicsLayouts.MonitorSpecFlags));
        Assert.Equal((ushort)312, ReadWord(memory, pal + (uint)GraphicsLayouts.MonitorSpecTotalRows));
        Assert.Equal((ushort)0x20, ReadWord(memory, pal + (uint)GraphicsLayouts.MonitorSpecBeamCon0));
        Assert.Equal(0, core.CloseMonitor(pal));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { A = { [1] = ntscName }, D = { [0] = GraphicsModeIds.NtscMonitor } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.OpenMonitor));
        var adapterMonitor = state.D[0];
        Assert.NotEqual(0u, adapterMonitor);
        state.A[0] = adapterMonitor;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.CloseMonitor));
        Assert.Equal(0u, state.D[0]);

        state.A[1] = 0x7000;
        WriteAscii(memory, state.A[1], "vga.monitor");
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.OpenMonitor));
        Assert.Equal(1, core.CloseMonitor(0x1FF0));
    }

    [Fact]
    public void OpenMonitorNullNameAndZeroIdSelectsActiveDefaultAcrossPortablePaths()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new SteppingAllocator(0x1000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        Assert.Equal(0u, core.OpenMonitor(0, GraphicsModeIds.Invalid));
        var coreMonitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, coreMonitor);
        Assert.Equal(
            (ushort)2,
            ReadWord(memory, coreMonitor + (uint)GraphicsLayouts.MonitorSpecFlags));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var registerState = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0 }
        };
        Assert.True(adapter.TryInvoke(registerState, (int)GraphicsLvo.OpenMonitor));
        Assert.Equal(coreMonitor, registerState.D[0]);
        Assert.Equal(
            (ushort)2,
            ReadWord(memory, coreMonitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        registerState.A[0] = coreMonitor;
        Assert.True(adapter.TryInvoke(registerState, (int)GraphicsLvo.CloseMonitor));
        Assert.Equal(0u, registerState.D[0]);
        Assert.Equal(0, core.CloseMonitor(coreMonitor));

        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint nativeTarget = 0x00FE_1300;
        static Func<int, uint, uint> MapAllocator(AmigaBus bus, uint start)
        {
            var next = start;
            return (bytes, _) =>
            {
                var address = next;
                var length = Math.Max(bytes, 1);
                bus.MapWritableMemory(address, new byte[length]);
                next += (uint)((length + 3) & ~3);
                return address;
            };
        }

        var directBus = new AmigaBus();
        directBus.MapReadOnlyMemory(imageBase, new byte[0x2000]);
        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            allocateMemory: MapAllocator(directBus, 0x2000));
        var directState = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0 },
            Cycles = 613
        };
        direct.OpenMonitor(directState);
        Assert.NotEqual(0u, directState.D[0]);
        Assert.Equal(613, directState.Cycles);
        Assert.Equal(
            (ushort)2,
            directBus.ReadWord(directState.D[0] + (uint)GraphicsLayouts.MonitorSpecFlags));

        var overlayBus = new AmigaBus();
        var overlayImage = new byte[0x2000];
        WriteJmp(
            overlayImage,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor)),
            nativeTarget);
        overlayBus.MapReadOnlyMemory(imageBase, overlayImage);
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            allocateMemory: MapAllocator(overlayBus, 0x2000));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var overlayState = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0 },
            Cycles = 619
        };
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.OpenMonitor)),
            overlayState));
        Assert.NotEqual(0u, overlayState.D[0]);
        Assert.Equal(619, overlayState.Cycles);
        Assert.Equal(
            (ushort)2,
            overlayBus.ReadWord(overlayState.D[0] + (uint)GraphicsLayouts.MonitorSpecFlags));

        // The same NULL/zero request follows the active jumper profile
        // on an NTSC host. Keep this separate core instance so the PAL
        // resident above cannot accidentally satisfy the assertion.
        var ntscMemory = new FakeMemory(0x10000);
        var ntscAllocator = new SteppingAllocator(0x1800);
        var ntscCore = new GraphicsLibraryCore(
            ntscMemory,
            ntscAllocator,
            new FakeBlitter(),
            new FakeDisplay { IsNtsc = true });
        Assert.Equal(0u, ntscCore.OpenMonitor(0, GraphicsModeIds.Invalid));
        var ntscMonitor = ntscCore.OpenMonitor(0, 0);
        Assert.NotEqual(0u, ntscMonitor);
        Assert.Equal(
            (ushort)1,
            ReadWord(ntscMemory, ntscMonitor + (uint)GraphicsLayouts.MonitorSpecFlags));
        Assert.Equal(
            (ushort)262,
            ReadWord(ntscMemory, ntscMonitor + (uint)GraphicsLayouts.MonitorSpecTotalRows));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void OpenMonitorHostSelectorsMatchOriginalRomDefaultAndCanonicalNames(bool ntsc)
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new SteppingAllocator(0x1000),
            new FakeBlitter(), new FakeDisplay { IsNtsc = ntsc });
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(0, core.CloseMonitor(monitor));
        const uint nameAddress = 0x6000;
        var canonicalName = ntsc ? "ntsc.monitor" : "pal.monitor";
        foreach (var id in new[] { GraphicsModeIds.Invalid, 0xDEADBEEFu })
        foreach (var name in new[] { "default.monitor", "DEFAULT.MONITOR", canonicalName,
            canonicalName.ToUpperInvariant(), "unknown.monitor", "" })
        {
            WriteAscii(memory, nameAddress, name);
            var expected = name is "default.monitor" or "DEFAULT.MONITOR" || name == canonicalName;
            var opened = core.OpenMonitor(nameAddress, id);
            Assert.Equal(expected ? monitor : 0, opened);
            Assert.Equal(expected ? (ushort)1 : (ushort)0,
                ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
            if (opened != 0) Assert.Equal(0, core.CloseMonitor(opened));
        }
        Assert.Equal(0u, core.OpenMonitor(0, GraphicsModeIds.Invalid));
        Assert.Equal((ushort)0, ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(monitor, core.OpenMonitor(0, 0));
        Assert.Equal(0, core.CloseMonitor(monitor));
        var adapterState = new M68kCpuState { D = { [0] = GraphicsModeIds.Invalid } };
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        Assert.True(adapter.TryInvoke(adapterState, (int)GraphicsLvo.OpenMonitor));
        Assert.Equal(0u, adapterState.D[0]); // INVALID_ID is a complete NULL result, as in original ROM.
        adapterState.D[0] = 0xDEADBEEF;
        Assert.False(adapter.TryInvoke(adapterState, (int)GraphicsLvo.OpenMonitor));
        Assert.Equal(0xDEADBEEFu, adapterState.D[0]); // Unknown provider syntax still preserves the request.
    }

    [Theory]
    [InlineData(0u, 0xFFFFFFFFu)]
    [InlineData(0u, 0xDEADBEEFu)]
    [InlineData(0x2000u, 0xFFFFFFFFu)]
    [InlineData(0x2000u, 0xDEADBEEFu)]
    public void DirectOpenMonitorReturnsNullWhenNoProviderCanHandleTheRequest(uint name, uint displayId)
    {
        var bus = new AmigaBus();
        bus.MapWritableMemory(0x2000, System.Text.Encoding.ASCII.GetBytes("unknown.monitor\0"));
        var allocations = 0;
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus),
            allocateMemory: (_, _) => { allocations++; return 0; });
        var state = new M68kCpuState { A = { [1] = name }, D = { [0] = displayId, [1] = 0x12345678 }, Cycles = 619 };
        Assert.Equal(0u, services.OpenMonitor(state));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0x12345678u, state.D[1]);
        Assert.Equal(name, state.A[1]);
        Assert.Equal(619, state.Cycles);
        Assert.Equal(0, allocations);
    }

    [Fact]
    public void OpenMonitorModeIdPublishesAResidentCanonicalMonitorName()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new ResidentNameSequenceAllocator(0x2000, 0x2100);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        var monitor = core.OpenMonitor(0, GraphicsModeIds.PalMonitor);
        Assert.NotEqual(0u, monitor);

        var name = ReadLong(
            memory,
            monitor + (uint)GraphicsLayouts.MonitorSpecNodeName);
