        Assert.Equal((byte)'p', ReadByte(memory, name));
        Assert.Equal((byte)'a', ReadByte(memory, name + 1));
        Assert.Equal((byte)'l', ReadByte(memory, name + 2));
        Assert.Equal((byte)'.', ReadByte(memory, name + 3));
        Assert.Equal((byte)'m', ReadByte(memory, name + 4));
        Assert.Equal((byte)'o', ReadByte(memory, name + 5));
        Assert.Equal((byte)'n', ReadByte(memory, name + 6));
        Assert.Equal((byte)'i', ReadByte(memory, name + 7));
