    [Fact]
    public void OpenMonitorPublishesResidentSpecsIntoAFullNativeGfxBaseMonitorList()
    {
        var memory = new FakeMemory(0x10000);
        const uint gfxBase = 0x7000;
        var allocator = new SteppingAllocator(0x1000);

        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail));
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorList));
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));
        const uint displayDatabase = 0xCAFE_1234u;
        Assert.True(memory.TryWriteLong(
            gfxBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            displayDatabase));

        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: gfxBase);

        var pal = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, pal);
        var list = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        var tail = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail;
        Assert.Equal(pal, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(pal, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
        Assert.Equal(tail, ReadLong(memory, pal));
        Assert.Equal(list, ReadLong(memory, pal + 4u));
        Assert.Equal(pal, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor));
        // GfxBase.DisplayInfoDataBase is an APTR to the native/private
        // database object. OpenMonitor owns only MonitorList publication and
        // must not reinterpret the pointer field as embedded list storage.
        Assert.Equal(
            displayDatabase,
            ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));

        var ntsc = core.OpenMonitor(0, GraphicsModeIds.NtscMonitor);
        Assert.NotEqual(0u, ntsc);
        Assert.NotEqual(pal, ntsc);
        Assert.Equal(ntsc, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
        Assert.Equal(ntsc, ReadLong(memory, pal));
        Assert.Equal(pal, ReadLong(memory, ntsc + 4u));
        Assert.Equal(tail, ReadLong(memory, ntsc));

        Assert.Equal(0, core.CloseMonitor(pal));
        Assert.Equal(0, core.CloseMonitor(ntsc));
        Assert.Equal(pal, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(ntsc, ReadLong(memory, gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
    }

