        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        Assert.Equal(
            GraphicsMonitorOperations.CloseFailure,
            core.CloseMonitor(0x0201));
        Assert.Equal(
            GraphicsMonitorOperations.CloseFailure,
            core.CloseMonitor(uint.MaxValue - 1u));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        foreach (var monitorSpec in new[] { 0x0201u, uint.MaxValue - 1u })
        {
