        }
    }

    [Fact]
    public void OpenMonitorSharesResidentSpecAndCloseMonitorRetainsItForReopen()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new SteppingAllocator(0x1000);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        var first = core.OpenMonitor(0, GraphicsModeIds.PalMonitor);
        var second = core.OpenMonitor(0, GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode);
        Assert.NotEqual(0u, first);
        Assert.Equal(first, second);
        Assert.Equal(
            (ushort)2,
            ReadWord(memory, first + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);

        Assert.Equal(0, core.CloseMonitor(first));
        Assert.Equal(
            (ushort)1,
            ReadWord(memory, first + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);

        Assert.Equal(0, core.CloseMonitor(second));
        Assert.Equal(
            (ushort)0,
            ReadWord(memory, first + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);

        var reopened = core.OpenMonitor(0, GraphicsModeIds.PalMonitor);
        Assert.Equal(first, reopened);
        Assert.Equal(
            (ushort)1,
            ReadWord(memory, first + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, core.CloseMonitor(reopened));
        Assert.Equal(0, allocator.FreeCount);
        Assert.Equal(1, core.CloseMonitor(first));
    }

    [Fact]
    public void CloseMonitorPreservesSharedSpecWhenOpenCountWriteFails()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RejectingWordWriteMemory(backing, 0);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);

        memory.RejectedAddress = monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount;
        Assert.Equal(1, core.CloseMonitor(monitor));
        Assert.Equal(
            (ushort)1,
            ReadWord(backing, monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(0, allocator.FreeCount);

        memory.RejectedAddress = 0;
        Assert.Equal(0, core.CloseMonitor(monitor));
        Assert.Equal(0, allocator.FreeCount);
        Assert.Equal(
            (ushort)0,
            ReadWord(backing, monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
    }

    [Fact]
    public void OpenMonitorRestoresOpenCountAfterPartialWordPublication()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        var monitor = core.OpenMonitor(0, GraphicsModeIds.PalMonitor);
        Assert.NotEqual(0u, monitor);
        var openCount = monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount;
        Assert.Equal((ushort)1, ReadWord(backing, openCount));

        // The resident-open path accepts the high byte of the increment and
        // then rejects the WORD. OpenMonitor must restore both original bytes
        // so the next call can retry the same monitor without consuming a
        // phantom reference.
        memory.PartialWordAddress = openCount;
        Assert.Equal(0u, core.OpenMonitor(0, GraphicsModeIds.PalMonitor));
        Assert.Equal((ushort)1, ReadWord(backing, openCount));

        memory.PartialWordAddress = null;
        Assert.Equal(monitor, core.OpenMonitor(0, GraphicsModeIds.PalMonitor));
        Assert.Equal((ushort)2, ReadWord(backing, openCount));

        Assert.Equal(0, core.CloseMonitor(monitor));
        Assert.Equal(0, core.CloseMonitor(monitor));
        Assert.Equal((ushort)0, ReadWord(backing, openCount));
    }

    [Fact]
    public void CloseMonitorRestoresOpenCountAfterPartialWordPublication()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialThenRejectWordWriteMemory(backing);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        var monitor = core.OpenMonitor(0, GraphicsModeIds.PalMonitor);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(monitor, core.OpenMonitor(0, GraphicsModeIds.PalMonitor));
        var openCount = monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount;
        Assert.Equal((ushort)2, ReadWord(backing, openCount));

        // The decrement accepts the high byte and then rejects the WORD.
        // CloseMonitor must restore the original count before returning the
        // failure so the same reference can be closed after a retry.
        memory.PartialWordAddress = openCount;
        Assert.Equal(1, core.CloseMonitor(monitor));
        Assert.Equal((ushort)2, ReadWord(backing, openCount));

        memory.PartialWordAddress = null;
        Assert.Equal(0, core.CloseMonitor(monitor));
        Assert.Equal((ushort)1, ReadWord(backing, openCount));
        Assert.Equal(0, core.CloseMonitor(monitor));
        Assert.Equal((ushort)0, ReadWord(backing, openCount));
    }

    [Fact]
    public void OpenMonitorRestoresResidentEnvelopeWhenInitializationWriteFailsLate()
    {
        var backing = new FakeMemory(0x10000);
        const uint monitorAddress = 0x1000;
        var original = new byte[GraphicsLayouts.MonitorSpecSize];
        for (var offset = 0; offset < original.Length; offset++)
        {
            original[offset] = (byte)(0xA5 ^ offset);
            backing.Bytes[(int)(monitorAddress + (uint)offset)] = original[offset];
        }

        var memory = new FailingByteWriteMemory(backing);
        memory.FailOnNextByteWrite(24);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        Assert.Equal(0u, core.OpenMonitor(0, GraphicsModeIds.PalMonitor));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(monitorAddress, allocator.LastFreedAddress);

        for (var offset = 0; offset < original.Length; offset++)
        {
            Assert.Equal(
                original[offset],
                backing.Bytes[(int)(monitorAddress + (uint)offset)]);
        }
    }

    [Fact]
    public void OpenMonitorRestoresResidentEnvelopeWhenNativeListPublicationFailsLate()
    {
        var backing = new FakeMemory(0x10000);
        const uint monitorAddress = 0x1000;
        const uint gfxBase = 0x7000;
        var original = new byte[GraphicsLayouts.MonitorSpecSize];
        for (var offset = 0; offset < original.Length; offset++)
        {
            original[offset] = (byte)(0x5A ^ (offset * 3));
            backing.Bytes[(int)(monitorAddress + (uint)offset)] = original[offset];
        }

        var list = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        var tail = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail;
        var tailPred = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred;
        var defaultMonitor = gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor;
        Assert.True(backing.TryWriteLong(gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead, tail));
        Assert.True(backing.TryWriteLong(tail, 0));
        Assert.True(backing.TryWriteLong(tailPred, list));
        Assert.True(backing.TryWriteLong(defaultMonitor, 0));

        // The first native-list link writes succeed; reject the tail
        // predecessor update so publication fails after the resident node has
        // already been initialized and partially linked.
        var memory = new RejectingWriteMemory(backing, tailPred, tailPred + 4u);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: gfxBase);

        Assert.Equal(0u, core.OpenMonitor(0, GraphicsModeIds.PalMonitor));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(tail, ReadLong(backing, gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(list, ReadLong(backing, tailPred));
        Assert.Equal(0u, ReadLong(backing, defaultMonitor));

        for (var offset = 0; offset < original.Length; offset++)
        {
            Assert.Equal(
                original[offset],
                backing.Bytes[(int)(monitorAddress + (uint)offset)]);
        }
    }

    [Fact]
    public void OpenMonitorRestoresNativeListAfterAPartialLongPublication()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialLongWriteMemory(backing);
        const uint monitorAddress = 0x1000;
        const uint gfxBase = 0x7000;
        var original = new byte[GraphicsLayouts.MonitorSpecSize];
        for (var offset = 0; offset < original.Length; offset++)
        {
            original[offset] = (byte)(0x3C ^ (offset * 5));
            backing.Bytes[(int)(monitorAddress + (uint)offset)] = original[offset];
        }

        var list = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        var head = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead;
        var tail = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail;
        var tailPred = gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred;
        var defaultMonitor = gfxBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor;
        Assert.True(backing.TryWriteLong(head, list + 4u));
        Assert.True(backing.TryWriteLong(tail, 0));
        Assert.True(backing.TryWriteLong(tailPred, list));
        Assert.True(backing.TryWriteByte(
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(backing.TryWriteByte(
            gfxBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(backing.TryWriteLong(defaultMonitor, 0));

        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: gfxBase);

        // The tail-predecessor publication is after the monitor's two links
        // and the old list predecessor. Fail after two bytes so the complete
        // native list and the freshly initialized MonitorSpec are restored.
        memory.PartialLongAddress = tailPred;
        Assert.Equal(0u, core.OpenMonitor(0, GraphicsModeIds.PalMonitor));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(list + 4u, ReadLong(backing, head));
        Assert.Equal(0u, ReadLong(backing, tail));
        Assert.Equal(list, ReadLong(backing, tailPred));
        Assert.Equal(0u, ReadLong(backing, defaultMonitor));
        for (var offset = 0; offset < original.Length; offset++)
        {
            Assert.Equal(
                original[offset],
                backing.Bytes[(int)(monitorAddress + (uint)offset)]);
        }

        memory.PartialLongAddress = null;
        var monitor = core.OpenMonitor(0, GraphicsModeIds.PalMonitor);
        Assert.Equal(monitorAddress, monitor);
        Assert.Equal(monitor, ReadLong(backing, head));
        Assert.Equal(0u, ReadLong(backing, defaultMonitor));
    }

    [Fact]
    public void OpenMonitorAcceptsRegisteredEcsModeIdsWhenTheDisplayHardwareIsOcs()
    {
        var memory = new FakeMemory(0x4000);
        var allocator = new FakeAllocator();
        var display = new FakeDisplay { SupportsEcsDisplay = false };
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), display);

        var superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;
        var byId = core.OpenMonitor(0, superHires);
        Assert.NotEqual(0u, byId);
        Assert.Equal(0, core.CloseMonitor(byId));

        // Original-ROM OpenMonitor resolves the monitor even if this chipset
        // cannot execute that display mode. Named and ID opens share residency.
        const uint palName = 0x1800;
        WriteAscii(memory, palName, "pal.monitor");
        var monitor = core.OpenMonitor(palName, superHires);
        Assert.Equal(byId, monitor);
        Assert.Equal(0, core.CloseMonitor(monitor));
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void OpenMonitorHostIdSyntaxMatchesOriginalRomIndependentOfChipset(bool ntsc, bool ecs)
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new SteppingAllocator(0x1000),
            new FakeBlitter(), new FakeDisplay { IsNtsc = ntsc, SupportsEcsDisplay = ecs });
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(0, core.CloseMonitor(monitor));
        foreach (var key in new uint[] { 0, 4, 0x8000, 0x8004, 0x8020, 0x8024, 0x800, 0x804,
            0x80, 0x84, 0x400, 0x404, 0x8400, 0x8404, 0x8420, 0x8424, 0x440, 0x444,
            0x8440, 0x8444, 0x8460, 0x8464 })
        {
            foreach (var id in new[] { key, key | 0x1000u, key | (ntsc ? 0x11000u : 0x21000u) })
            {
                Assert.Equal(monitor, core.OpenMonitor(0, id));
                Assert.Equal((ushort)1, ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
                Assert.Equal(0, core.CloseMonitor(monitor));
                Assert.Equal((ushort)0, ReadWord(memory, monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
            }
            Assert.Equal(0u, core.OpenMonitor(0, key | (ntsc ? 0x10000u : 0x20000u)));
        }
        foreach (var key in new uint[] { 1, 2, 8, 0x20, 0x40, 0x100, 0x200, 0x2000, 0x4000, 0x8008, 0x8800, 0xFFFF })
            foreach (var family in new uint[] { 0, 0x1000, 0x11000, 0x21000, 0x31000 })
                Assert.Equal(0u, core.OpenMonitor(0, family | key));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void CoerceModeAssociatedSourceMatchesIndependentRom(bool ntsc)
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint tags = 0x100, viewport = 0x200, rasInfo = 0x280, bitmap = 0x300;
        var monitor = ntsc ? 0x11000u : 0x21000u;
        var colorMap = core.GetColorMap(256);
        Assert.NotEqual(0u, colorMap);
        memory.TryWriteLong(viewport + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitmap);
        memory.TryWriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 512);
        foreach (var mapState in new[] { 0, 1, 2 })
        foreach (var mode in new ushort[] { 0x8000, 0x0800, 0x0080, 0x0400 })
        foreach (var viewportMode in new ushort[] { mode, 0 })
        foreach (var width in new ushort[] { 320, 640 })
        foreach (var depth in new byte[] { 4, 5, 6, 7 })
        foreach (var flags in new uint[] { 0, 1 })
        {
            memory.TryWriteWord(viewport + (uint)GraphicsLayouts.ViewPortDWidth, width);
            memory.TryWriteWord(viewport + (uint)GraphicsLayouts.ViewPortDHeight, ntsc ? (ushort)200 : (ushort)256);
            memory.TryWriteWord(viewport + (uint)GraphicsLayouts.ViewPortModes, viewportMode);
            memory.TryWriteLong(viewport + (uint)GraphicsLayouts.ViewPortColorMap, mapState == 0 ? 0 : colorMap);
            memory.TryWriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, (ushort)(width / 8));
            memory.TryWriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, depth);
            if (mapState == 2)
            {
                WriteTag(memory, tags, 0x80000010, core.FindDisplayInfo(monitor | mode));
                WriteTag(memory, tags + 8, 0, 0);
                Assert.True(core.VideoControl(colorMap, tags));
            }
            var special = mapState == 2 && mode != 0x8000;
            var selectionWidth = mapState == 2 ? (mode == 0x8000 ? 640 : 320) : width;
            var expected = depth > (special ? 6 : 5) ? uint.MaxValue :
                monitor | (special ? mode : selectionWidth == 640 && depth == 4 ? 0x8000u : 0u);
            Assert.Equal(expected, core.CoerceMode(viewport, monitor, flags));
        }
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void BestModeAndCoerceDepthBoundariesMatchIndependentRom(bool ntsc)
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint tags = 0x100, viewport = 0x200, rasInfo = 0x280, bitmap = 0x300;
        var monitor = ntsc ? 0x11000u : 0x21000u;
        foreach (var depth in new uint[] { 4, 5, 6 })
        {
            WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagNominalWidth, 640);
            WriteTag(memory, tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight, ntsc ? 200u : 256u);
            WriteTag(memory, tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth, 640);
            WriteTag(memory, tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight, ntsc ? 200u : 256u);
            WriteTag(memory, tags + 32, GraphicsDisplayDatabase.BidTagDepth, depth);
            WriteTag(memory, tags + 40, GraphicsDisplayDatabase.BidTagMonitorId, monitor);
            Assert.Equal(depth == 6 ? uint.MaxValue : monitor | (depth == 4 ? 0x8000u : 0u),
                core.BestModeIDA(tags));
        }
        memory.TryWriteWord(viewport + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteLong(viewport + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitmap);
        memory.TryWriteWord(bitmap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        memory.TryWriteWord(bitmap + (uint)GraphicsLayouts.BitMapRows, 512);
        foreach (var height in new ushort[] { 256, 512 })
        foreach (var depth in new byte[] { 5, 6 })
        foreach (var flags in new uint[] { 0, 1 })
        {
            memory.TryWriteWord(viewport + (uint)GraphicsLayouts.ViewPortDHeight, height);
            memory.TryWriteByte(bitmap + (uint)GraphicsLayouts.BitMapDepth, depth);
            // Literal expectations captured from original PAL/NTSC 3.1 ROM,
            // independent of the replacement's mode records and scoring.
            Assert.Equal(depth == 6 ? uint.MaxValue : monitor | (height == 512 ? 4u : 0u),
                core.CoerceMode(viewport, monitor, flags));
        }
    }

    [Fact]
    public void CoerceModeSelectsNativeMonitorModesFromValidatedViewportGeometry()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;

        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5);

        Assert.Equal(
            GraphicsModeIds.PalMonitor,
            core.CoerceMode(
                viewPort,
                GraphicsModeIds.PalMonitor,
                GraphicsDisplayDatabase.CoercePreserveColors));

        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 512);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.InterlaceMode,
            core.CoerceMode(viewPort, GraphicsModeIds.PalMonitor, 0));
        Assert.Equal(
            GraphicsModeIds.PalMonitor,
            core.CoerceMode(
                viewPort,
                GraphicsModeIds.PalMonitor,
                GraphicsDisplayDatabase.CoerceAvoidFlicker));

        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 6);
        Assert.Equal(
            GraphicsModeIds.Invalid,
            core.CoerceMode(
                viewPort,
                GraphicsModeIds.PalMonitor,
                GraphicsDisplayDatabase.CoercePreserveColors));
        Assert.Equal(
            GraphicsModeIds.Invalid,
            core.CoerceMode(viewPort, GraphicsModeIds.PalMonitor, 0));

        // Restore a valid ordinary source for the flicker-avoidance check.
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D =
            {
                [0] = GraphicsModeIds.PalMonitor,
                [1] = GraphicsDisplayDatabase.CoerceAvoidFlicker
            }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.CoerceMode));
        Assert.Equal(GraphicsModeIds.PalMonitor, state.D[0]);

        // A complete native viewport with an eight-plane requirement is a
        // valid request even though this OCS/ECS database has no compatible
        // record.  CoerceMode must claim it and publish INVALID_ID.
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 8);
        state.D[0] = GraphicsModeIds.PalMonitor;
        state.D[1] = GraphicsDisplayDatabase.CoercePreserveColors;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.CoerceMode));
        Assert.Equal(GraphicsModeIds.Invalid, state.D[0]);

        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 6);
        state.D[0] = 0x0003_1000u;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.CoerceMode));
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, 0x3FF8);
        Assert.Equal(
            GraphicsModeIds.Invalid,
            core.CoerceMode(viewPort, GraphicsModeIds.PalMonitor, 0));
    }

    [Fact]
    public void OcsDisplayLeavesEcsSourceRequestsToTheNativeProvider()
    {
        var memory = new FakeMemory(0x4000);
        var display = new FakeDisplay { SupportsEcsDisplay = false };
        var core = CreateCore(memory, display);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint tags = 0x100;
        var superHires = GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey;

        // A readable SourceID identifies a real database record, but this
        // OCS display cannot execute ECS SuperHires.  The portable path must
        // leave the request unclaimed instead of publishing INVALID_ID.
        WriteTag(memory, tags, GraphicsDisplayDatabase.BidTagSourceId, superHires);
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        Assert.Equal(GraphicsModeIds.Invalid, core.BestModeIDA(tags));

        var best = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 607
        };
        Assert.False(adapter.TryInvoke(best, (int)GraphicsLvo.BestModeIDA));
        Assert.Equal(0xCAFE_BABEu, best.D[0]);
        Assert.Equal(607, best.Cycles);
    }

    [Fact]
    public void CoerceModeHonorsNativeViewportFeatureKeysAndRejectsUnsupportedModes()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;
        const uint bitMap = 0x300;
        const uint tags = 0x500;
        var colorMap = core.GetColorMap(256);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        memory.TryWriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 6);

        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HamMode);
        WriteTag(memory, tags, 0x80000010, core.FindDisplayInfo(GraphicsModeIds.PalMonitor | GraphicsModeIds.HamKey));
        WriteTag(memory, tags + 8, 0, 0);
        Assert.True(core.VideoControl(colorMap, tags));
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HamMode,
            core.CoerceMode(
                viewPort,
                GraphicsModeIds.PalMonitor,
                GraphicsDisplayDatabase.CoercePreserveColors));

        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.SuperHiresKey);
        WriteTag(memory, tags, 0x80000010, core.FindDisplayInfo(GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey));
        Assert.True(core.VideoControl(colorMap, tags));
        memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 1280);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 160);
        // SuperHires is a two-plane source on OCS/ECS; the preceding HAM
        // fixture's six planes are not a valid geometry-coercion input.
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.SuperHiresKey,
            core.CoerceMode(viewPort, GraphicsModeIds.PalMonitor, 0));

        memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.ExtendedMode);
        Assert.Equal(
            GraphicsModeIds.Invalid,
            core.CoerceMode(viewPort, GraphicsModeIds.PalMonitor, 0));
    }

    [Fact]
    public void GraphicsExtendedNodesAssociateViewAndViewportGuestState()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.Equal((byte)18, ReadByte(memory, viewExtra + (uint)GraphicsLayouts.ExtendedNodeType));
        Assert.Equal((byte)2, ReadByte(memory, viewExtra + (uint)GraphicsLayouts.ExtendedNodeSubsystem));
        Assert.Equal((byte)1, ReadByte(memory, viewExtra + (uint)GraphicsLayouts.ExtendedNodeSubtype));
        Assert.True(core.GfxAssociate(0x300, viewExtra));
        Assert.Equal(viewExtra, core.GfxLookUp(0x300));
        Assert.Equal(0x300u, ReadLong(memory, viewExtra + (uint)GraphicsLayouts.ViewExtraView));

        var viewPortExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType);
        Assert.NotEqual(0u, viewPortExtra);
        Assert.Equal((byte)2, ReadByte(memory, viewPortExtra + (uint)GraphicsLayouts.ExtendedNodeSubsystem));
        Assert.Equal((byte)2, ReadByte(memory, viewPortExtra + (uint)GraphicsLayouts.ExtendedNodeSubtype));
        Assert.True(core.GfxAssociate(0x300, viewPortExtra));
        Assert.Equal(0u, ReadLong(memory, viewExtra + (uint)GraphicsLayouts.ViewExtraView));
        Assert.Equal(viewPortExtra, core.GfxLookUp(0x300));
        Assert.Equal(0x300u, ReadLong(memory, viewPortExtra + (uint)GraphicsLayouts.ViewPortExtraViewPort));

        Assert.False(core.GfxAssociate(0, viewPortExtra));
        Assert.False(core.GfxAssociate(0x301, viewPortExtra));
        Assert.Equal(0u, core.GfxLookUp(0x301));
        Assert.True(core.GfxFree(viewExtra));
        Assert.True(core.GfxFree(viewPortExtra));
        Assert.Equal(0u, core.GfxLookUp(0x300));
        Assert.False(core.GfxFree(viewPortExtra));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState { D = { [0] = GraphicsExtendedNodeOperations.ViewExtraType } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GfxNew));
        var adapterNode = state.D[0];
        state.A[0] = 0x400;
        state.A[1] = adapterNode;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GfxAssociate));
        var lookupState = new M68kCpuState { A = { [0] = 0x400 } };
        Assert.True(adapter.TryInvoke(lookupState, (int)GraphicsLvo.GfxLookUp));
        Assert.Equal(adapterNode, lookupState.D[0]);
        state.A[0] = adapterNode;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GfxFree));

        state.D[0] = 5;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.GfxNew));
    }

    [Fact]
    public void GfxNewAllocatesEveryKickstartExtendedNodeTypeWithGuestMetadata()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var requests = new[]
        {
            (Type: GraphicsExtendedNodeOperations.ViewExtraType, Bytes: GraphicsLayouts.ViewExtraSize),
            (Type: GraphicsExtendedNodeOperations.ViewPortExtraType, Bytes: GraphicsLayouts.ViewPortExtraSize),
            (Type: GraphicsExtendedNodeOperations.SpecialMonitorType, Bytes: GraphicsLayouts.SpecialMonitorSize),
            (Type: GraphicsExtendedNodeOperations.MonitorSpecType, Bytes: GraphicsLayouts.MonitorSpecSize)
        };

        foreach (var request in requests)
        {
            var node = core.GfxNew(request.Type);
            Assert.NotEqual(0u, node);
            Assert.Equal((byte)18, ReadByte(memory, node + (uint)GraphicsLayouts.ExtendedNodeType));
            Assert.Equal((byte)2, ReadByte(memory, node + (uint)GraphicsLayouts.ExtendedNodeSubsystem));
            Assert.Equal((byte)request.Type, ReadByte(memory, node + (uint)GraphicsLayouts.ExtendedNodeSubtype));
            Assert.Equal(0u, core.GfxLookUp(node));
            Assert.True(core.GfxFree(node));
            Assert.Contains(
                allocator.Freed,
                allocation => allocation.Address == node &&
                              allocation.Bytes == (uint)request.Bytes &&
                              allocation.MemoryClass == GraphicsMemoryClass.Public);
        }

        Assert.Equal(0u, core.GfxNew(5));
    }

    [Fact]
    public void GraphicsExtendedNodesWithoutBacklinksStillSupportOpaqueAssociation()
    {
        var memory = new FakeMemory(0x20000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        foreach (var nodeType in new[]
        {
            GraphicsExtendedNodeOperations.SpecialMonitorType,
            GraphicsExtendedNodeOperations.MonitorSpecType
        })
        {
            var node = core.GfxNew(nodeType);
            Assert.NotEqual(0u, node);

            var firstPointer = 0x300u + nodeType * 0x20u;
            var secondPointer = firstPointer + 2u;
            Assert.True(core.GfxAssociate(firstPointer, node));
            Assert.Equal(node, core.GfxLookUp(firstPointer));

            // Re-association must not leave an opaque lookup entry pointing
            // at the same node through the old pointer.
            Assert.True(core.GfxAssociate(secondPointer, node));
            Assert.Equal(0u, core.GfxLookUp(firstPointer));
            Assert.Equal(node, core.GfxLookUp(secondPointer));

            Assert.True(core.GfxFree(node));
            Assert.Equal(0u, core.GfxLookUp(secondPointer));
        }

        // A caller may edit the public ViewExtra backlink directly.  Freeing
        // the owned node must still remove the registry's opaque entry.
        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.True(core.GfxAssociate(0x500, viewExtra));
        Assert.True(memory.TryWriteLong(
            viewExtra + (uint)GraphicsLayouts.ViewExtraView,
            0));
        Assert.True(core.GfxFree(viewExtra));
        Assert.Equal(0u, core.GfxLookUp(0x500));
    }

    [Fact]
    public void GfxNewRejectsOddOrWrappingExtendedNodeAllocations()
    {
        var memory = new FakeMemory(0x10000);

