            new FakeDisplay());
        Assert.Equal(
            0u,
            oddCore.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType));
        Assert.Equal(1, oddAllocator.FreeCount);

        var wrappingAllocator = new FixedAddressAllocator(uint.MaxValue - 1u);
        var wrappingCore = new GraphicsLibraryCore(
            memory,
            wrappingAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        Assert.Equal(
            0u,
            wrappingCore.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType));
        Assert.Equal(1, wrappingAllocator.FreeCount);
    }

    [Fact]
    public void GfxNewRestoresExistingEnvelopeWhenMetadataPublicationFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new FixedAddressAllocator(0x200);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        for (var offset = 0; offset < GraphicsLayouts.ViewExtraSize; offset++)
        {
            Assert.True(backing.TryWriteByte(
                0x200u + (uint)offset,
                (byte)(0xA0 + offset)));
        }

        // The fifth clear byte fails. The rollback must restore all original
        // bytes before the provisional public span is released.
        memory.FailOnNextByteWrite(5);
        Assert.Equal(
            0u,
            core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType));
        Assert.Equal(1, allocator.FreeCount);
        for (var offset = 0; offset < GraphicsLayouts.ViewExtraSize; offset++)
        {
            Assert.Equal(
                (byte)(0xA0 + offset),
                ReadByte(backing, 0x200u + (uint)offset));
        }
    }

    [Fact]
    public void GfxFreeRestoresTheGuestBacklinkWhenItsLateClearFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new FixedAddressAllocator(0x200);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());

        var node = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, node);
        const uint view = 0x300;
        Assert.True(core.GfxAssociate(view, node));
        Assert.Equal(view, ReadLong(backing, node + (uint)GraphicsLayouts.ViewExtraView));

        // GfxFree clears a public LONG. Fail on its third byte so the guest
        // write is partial; the teardown must restore the original backlink,
        // registry entry, and allocation ownership as one transaction.
        memory.FailOnNextByteWrite(3);
        Assert.False(core.GfxFree(node));
        Assert.Equal(view, ReadLong(backing, node + (uint)GraphicsLayouts.ViewExtraView));
        Assert.Equal(node, core.GfxLookUp(view));
        Assert.Equal(0, allocator.FreeCount);

        Assert.True(core.GfxFree(node));
        Assert.Equal(0u, core.GfxLookUp(view));
        Assert.Equal(1, allocator.FreeCount);
    }

