    [Fact]
    public void NativeGraphicsBaseRebindMovesExtendedNodesAndMonitorPublication()
    {
        var memory = new FakeMemory(0x20000);
        const uint compatibilityBase = 0x0100;
        const uint nativeBase = 0x0800;
        var compatibilityList = compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            compatibilityList + 4u));
        Assert.True(memory.TryWriteLong(
            compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            compatibilityList));
        Assert.True(memory.TryWriteByte(
            compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));

        var core = new GraphicsLibraryCore(
            memory,
            new SteppingAllocator(0x10000),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: compatibilityBase);

        Assert.Equal(compatibilityBase, core.RebindGraphicsLibraryBase(nativeBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(nativeBase));

        var node = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, node);
        Assert.Equal(
            nativeBase,
            ReadLong(memory, node + (uint)GraphicsLayouts.ExtendedNodeLibrary));

        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(
            monitor,
            ReadLong(memory, nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            monitor,
            ReadLong(memory, nativeBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor));
        Assert.Equal(
            0u,
            ReadLong(memory, monitor + (uint)GraphicsLayouts.MonitorSpecDisplayInfoDataBaseTail));
        Assert.Equal(
            compatibilityList + 4u,
            ReadLong(memory, compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
    }

    [Fact]
    public async Task NativeGraphicsBaseRebindWaitsForExtendedNodePublication()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;
        var allocator = new BlockingNativeDatabaseAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);

        var allocation = Task.Run(() => core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType));
        Assert.True(allocator.AllocationEntered.Wait(TimeSpan.FromSeconds(5)));

        // The node is still inside the allocator-backed publication
        // transaction. Rebind must not observe a half-initialized registry
        // entry and move only some of its guest fields to the new base.
        var rebind = Task.Run(() => core.RebindGraphicsLibraryBase(secondBase));
        var earlyCompletion = await Task.WhenAny(
            rebind,
            Task.Delay(TimeSpan.FromMilliseconds(100)));
        Assert.NotSame(rebind, earlyCompletion);

        allocator.ContinueAllocation.Set();
        var node = await allocation;
        Assert.NotEqual(0u, node);

        Assert.Equal(firstBase, await rebind);
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
        Assert.Equal(secondBase, ReadLong(memory, node +
            (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.True(core.GfxFree(node));
    }

    [Fact]
    public async Task HostDisplayTransactionGateKeepsRebindBehindTheWholeHandoff()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        using var handoffEntered = new ManualResetEventSlim();
        using var releaseHandoff = new ManualResetEventSlim();
        var handoff = Task.Run(() => adapter.WithMonitorStateLock(() =>
        {
            handoffEntered.Set();
            Assert.True(releaseHandoff.Wait(TimeSpan.FromSeconds(5)));
            return true;
        }));
        Assert.True(handoffEntered.Wait(TimeSpan.FromSeconds(5)));

        var rebind = Task.Run(() => core.RebindGraphicsLibraryBase(secondBase));
        var earlyCompletion = await Task.WhenAny(
            rebind,
            Task.Delay(TimeSpan.FromMilliseconds(100)));
        Assert.NotSame(rebind, earlyCompletion);

        releaseHandoff.Set();
        Assert.True(await handoff);
        Assert.Equal(firstBase, await rebind);
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
    }

    [Fact]
    public async Task NativeOverlayGfxFreeKeepsRebindBehindPreflightAndCommit()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);
        const uint view = 0x300;
        var node = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, node);
        Assert.True(core.GfxAssociate(view, node));

        using var preflightEntered = new ManualResetEventSlim();
        using var continuePreflight = new ManualResetEventSlim();
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (_, _) =>
            {
                preflightEntered.Set();
                Assert.True(continuePreflight.Wait(TimeSpan.FromSeconds(5)));
                return true;
            });
        var state = new M68kCpuState
        {
            A = { [0] = node },
            D = { [0] = 0xCAFE_BABEu }
        };

        var free = Task.Run(() => adapter.TryInvoke(
            state,
            (int)GraphicsLvo.GfxFree,
            nativeOverlay: true));
        Assert.True(preflightEntered.Wait(TimeSpan.FromSeconds(5)));

        var rebind = Task.Run(() => core.RebindGraphicsLibraryBase(secondBase));
        var earlyCompletion = await Task.WhenAny(
            rebind,
            Task.Delay(TimeSpan.FromMilliseconds(100)));
        Assert.NotSame(rebind, earlyCompletion);

        continuePreflight.Set();
        Assert.True(await free);
        Assert.Equal(firstBase, await rebind);
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
        Assert.Equal(0u, core.GfxLookUp(view));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void NativeGraphicsBaseRebindMovesExistingGuestLibraryBacklinksTransactionally()
    {
        var memory = new FakeMemory(0x20000);
        const uint compatibilityBase = 0x0100;
        const uint nativeBase = 0x0800;

        void InitializeNativeEnvelope(uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(memory.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(memory.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeEnvelope(compatibilityBase);
        InitializeNativeEnvelope(nativeBase);

        var core = new GraphicsLibraryCore(
            memory,
            new SteppingAllocator(0x10000),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: compatibilityBase);

        var extendedNode = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, extendedNode);
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(
            compatibilityBase,
            ReadLong(memory, extendedNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.Equal(
            compatibilityBase,
            ReadLong(memory, monitor + (uint)GraphicsLayouts.ExtendedNodeLibrary));

        Assert.Equal(compatibilityBase, core.RebindGraphicsLibraryBase(nativeBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(nativeBase));
        Assert.Equal(
            nativeBase,
            ReadLong(memory, extendedNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.Equal(
            nativeBase,
            ReadLong(memory, monitor + (uint)GraphicsLayouts.ExtendedNodeLibrary));

        var compatibilityList = compatibilityBase +
                                 (uint)GraphicsLayouts.GfxBaseMonitorList;
        var nativeList = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.Equal(
            compatibilityList + 4u,
            ReadLong(
                memory,
                compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            compatibilityList,
            ReadLong(
                memory,
                compatibilityBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
        Assert.Equal(
            monitor,
            ReadLong(memory, nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            monitor,
            ReadLong(
                memory,
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
        Assert.Equal(nativeList, ReadLong(memory, monitor + 4u));
        Assert.Equal(nativeList + 4u, ReadLong(memory, monitor));
    }

    [Theory]
    [InlineData("success")]
    [InlineData("old-partial")]
    [InlineData("new-partial")]
    [InlineData("foreign-destination")]
    [InlineData("borrowed-source")]
    public void NativeGraphicsBaseRebindMovesOnlyOwnedDefaultTransactionally(string scenario)
    {
        foreach (var ntsc in new[] { false, true })
        {
            const uint oldBase = 0x1000, newBase = 0x2000;
            var backing = new FakeMemory(0x10000);
            var memory = new PartialLongWriteMemory(backing);
            foreach (var address in new[] { oldBase, newBase })
            {
                var list = address + (uint)GraphicsLayouts.GfxBaseMonitorList;
                Assert.True(backing.TryWriteLong(list, list + 4));
                Assert.True(backing.TryWriteLong(list + 8, list));
            }
            var allocator = new SequenceAddressAllocator(0x4000);
            var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(),
                new FakeDisplay { IsNtsc = ntsc }, graphicsLibraryBase: oldBase);
            var monitor = core.OpenMonitor(0, 0);
            Assert.Equal(0x4000u, monitor);
            var oldField = oldBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor;
            var newField = newBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor;
            Assert.Equal(monitor, ReadLong(backing, oldField));
            if (scenario == "borrowed-source") Assert.True(backing.TryWriteLong(oldField, 0xDEADBEEF));
            if (scenario == "foreign-destination") Assert.True(backing.TryWriteLong(newField, 0xDEADBEEF));
            memory.PartialLongAddress = scenario switch
            { "old-partial" => oldField, "new-partial" => newField, _ => null };
            var before = backing.Bytes.ToArray();
            Assert.Equal(oldBase, core.RebindGraphicsLibraryBase(newBase));
            if (scenario is "old-partial" or "new-partial" or "foreign-destination")
            {
                Assert.True(core.IsBoundToGraphicsLibraryBase(oldBase));
                Assert.Equal(before, backing.Bytes);
                memory.PartialLongAddress = null;
                Assert.True(backing.TryWriteLong(newField, 0));
                Assert.Equal(oldBase, core.RebindGraphicsLibraryBase(newBase));
            }
            Assert.True(core.IsBoundToGraphicsLibraryBase(newBase));
            Assert.Equal(scenario == "borrowed-source" ? 0xDEADBEEFu : 0, ReadLong(backing, oldField));
            Assert.Equal(scenario == "borrowed-source" ? 0 : monitor, ReadLong(backing, newField));
            Assert.Equal(newBase, ReadLong(backing, monitor + GraphicsLayouts.ExtendedNodeLibrary));
            Assert.Equal((ushort)1, ReadWord(backing, monitor + GraphicsLayouts.MonitorSpecOpenCount));
            Assert.Equal(0, allocator.FreeCount);
        }
    }

    [Fact]
    public void NativeGraphicsBaseRebindRestoresBacklinksAfterAPartialLongWrite()
    {
        var backing = new FakeMemory(0x20000);
        var memory = new PartialLongWriteMemory(backing);
        const uint compatibilityBase = 0x0100;
        const uint nativeBase = 0x0800;

        void InitializeNativeEnvelope(uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(backing.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(backing.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeEnvelope(compatibilityBase);
        InitializeNativeEnvelope(nativeBase);

        var core = new GraphicsLibraryCore(
            memory,
            new SteppingAllocator(0x10000),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: compatibilityBase);
        var extendedNode = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, extendedNode);
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);

        var compatibilityHead = compatibilityBase +
                                (uint)GraphicsLayouts.GfxBaseMonitorListHead;
        var compatibilityTailPred = compatibilityBase +
                                    (uint)GraphicsLayouts.GfxBaseMonitorListTailPred;
        var nativeHead = nativeBase +
                         (uint)GraphicsLayouts.GfxBaseMonitorListHead;
        var nativeTailPred = nativeBase +
                             (uint)GraphicsLayouts.GfxBaseMonitorListTailPred;
        var originalNodeLibrary = ReadLong(
            backing,
            extendedNode + (uint)GraphicsLayouts.ExtendedNodeLibrary);
        var originalMonitorLibrary = ReadLong(
            backing,
            monitor + (uint)GraphicsLayouts.ExtendedNodeLibrary);
        var originalCompatibilityHead = ReadLong(backing, compatibilityHead);
        var originalCompatibilityTailPred = ReadLong(backing, compatibilityTailPred);
        var originalNativeHead = ReadLong(backing, nativeHead);
        var originalNativeTailPred = ReadLong(backing, nativeTailPred);

        // Extended-node backlinks publish first.  Fail the first monitor-list
        // LONG after its first two bytes land; both the monitor list and the
        // already-updated node backlink must be restored byte-wise.
        memory.PartialLongAddress = compatibilityHead;
        Assert.Equal(compatibilityBase, core.RebindGraphicsLibraryBase(nativeBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(compatibilityBase));
        Assert.Equal(
            originalNodeLibrary,
            ReadLong(backing, extendedNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.Equal(
            originalMonitorLibrary,
            ReadLong(backing, monitor + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.Equal(originalCompatibilityHead, ReadLong(backing, compatibilityHead));
        Assert.Equal(
            originalCompatibilityTailPred,
            ReadLong(backing, compatibilityTailPred));
        Assert.Equal(originalNativeHead, ReadLong(backing, nativeHead));
        Assert.Equal(originalNativeTailPred, ReadLong(backing, nativeTailPred));

        memory.PartialLongAddress = null;
        Assert.Equal(compatibilityBase, core.RebindGraphicsLibraryBase(nativeBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(nativeBase));
        Assert.Equal(
            nativeBase,
            ReadLong(backing, extendedNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.Equal(
            nativeBase,
            ReadLong(backing, monitor + (uint)GraphicsLayouts.ExtendedNodeLibrary));
    }

    [Fact]
    public void NativeGraphicsBaseRebindLeavesExistingBacklinksWhenNodePublicationRefuses()
    {
        var backing = new FakeMemory(0x20000);
        const uint compatibilityBase = 0x0100;
        const uint nativeBase = 0x0800;

        void InitializeNativeEnvelope(uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(backing.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(backing.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
        }

        InitializeNativeEnvelope(compatibilityBase);
        InitializeNativeEnvelope(nativeBase);

        var core = new GraphicsLibraryCore(
            new RejectingLongWriteMemory(backing),
            new SteppingAllocator(0x10000),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: compatibilityBase);
        var extendedNode = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, extendedNode);

        var memory = (RejectingLongWriteMemory)core.Memory;
        memory.RejectedAddress = extendedNode +
                                 (uint)GraphicsLayouts.ExtendedNodeLibrary;

        Assert.Equal(compatibilityBase, core.RebindGraphicsLibraryBase(nativeBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(compatibilityBase));
        Assert.False(core.IsBoundToGraphicsLibraryBase(nativeBase));
        Assert.Equal(
            compatibilityBase,
            ReadLong(backing, extendedNode + (uint)GraphicsLayouts.ExtendedNodeLibrary));

        memory.RejectedAddress = 0;
        Assert.True(core.GfxFree(extendedNode));
    }

    [Fact]
