            0));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            nativeList));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));

        var memory = new RejectingLongReadMemory(backing)
        {
            RejectedAddress = compatibilityBase +
                              (uint)GraphicsLayouts.GfxBaseMonitorListHead
        };
        var core = new GraphicsLibraryCore(
            memory,
            new SteppingAllocator(0x10000),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: compatibilityBase);
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(0u, ReadLong(backing, monitor));
        Assert.Equal(0u, ReadLong(backing, monitor + 4u));

        Assert.Equal(compatibilityBase, core.RebindGraphicsLibraryBase(nativeBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(nativeBase));
        Assert.Equal(
            monitor,
            ReadLong(backing, nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(nativeList, ReadLong(backing, monitor + 4u));
        Assert.Equal(nativeList + 4u, ReadLong(backing, monitor));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void NativeGraphicsBasePublishesAndReleasesPrivateDisplayDatabaseSidecar(bool ntsc)
    {
        var memory = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            0));

        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay { IsNtsc = ntsc },
            graphicsLibraryBase: nativeBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        var database = ReadLong(
            memory,
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase);
        Assert.Equal(0x4000u, database);
        Assert.Equal(ntsc ? 0x11000u : 0x21000u,
            ReadLong(memory, database + (uint)GraphicsDisplayDatabase.NativeDefaultMonitorIdOffset));
        Assert.Equal(0u, ReadLong(memory, database + (uint)GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset));
        Assert.Equal(0u, ReadLong(memory, database + (uint)GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset + 4));
        Assert.Equal(
            GraphicsDisplayDatabase.NativeDatabaseMagic,
            ReadLong(memory, database));
        Assert.Equal(
            GraphicsDisplayDatabase.NativeDatabaseVersion,
            ReadLong(memory, database + 4u));
        Assert.Equal(
            (uint)GraphicsDisplayDatabase.NativeDatabaseSize,
            ReadLong(memory, database + 8u));
        Assert.Equal(
            (uint)GraphicsDisplayDatabase.NativeDatabaseRecordCount,
            ReadLong(memory, database + 12u));
        Assert.Equal(
            GraphicsModeIds.DefaultMonitor,
            ReadLong(memory, database +
                (uint)GraphicsDisplayDatabase.NativeDatabaseHeaderSize));

        // Publication is idempotent and does not allocate a second private
        // object while the native GfxBase still points at the first one.
        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(0, allocator.FreeCount);

        Assert.True(core.ReleaseNativeDisplayDatabase());
        Assert.Equal(
            0u,
            ReadLong(memory, nativeBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Fact]
    public void NativeGraphicsBaseReleaseRetainsDatabaseWhenEnvelopeBecomesMalformed()
    {
        var memory = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        var databaseField = nativeBase +
                            (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        Assert.True(memory.TryWriteLong(databaseField, 0));

        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        var database = ReadLong(memory, databaseField);
        Assert.NotEqual(0u, database);

        // A malformed/provider envelope cannot authorize freeing a sidecar
        // that remains reachable through the native GfxBase field.
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            1));
        Assert.False(core.ReleaseNativeDisplayDatabase());
        Assert.Equal(database, ReadLong(memory, databaseField));
        Assert.Equal(0, allocator.FreeCount);

        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(core.ReleaseNativeDisplayDatabase());
        Assert.Equal(0u, ReadLong(memory, databaseField));
        Assert.Equal(1, allocator.FreeCount);
    }

