    [Fact]
    public void NativeGraphicsBaseReleasesOwnedDisplayDatabaseWhenGuestClearsTheAptr()
    {
        var memory = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            0));

        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(
            0x4000u,
            ReadLong(memory, nativeBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));

        // A native/provider teardown may clear the public APTR before the
        // bridge is disposed. The block is no longer guest-reachable, so the
        // instance that allocated it must reclaim it without touching the
        // cleared field or treating the missing pointer as a foreign object.
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            0));
        core.ReleaseNativeDisplayDatabase();

        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(
            0u,
            ReadLong(memory, nativeBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
    }

    [Fact]
    public void NativeGraphicsBaseRebindRollsBackPortableMonitorAfterMalformedDatabaseHandoff()
    {
        var memory = new FakeMemory(0x40000);
        const uint nativeBase = 0x0800;
        const uint providerMonitor = 0x2000;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        var providerSuccessor = list + 4u;
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            providerMonitor));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            providerMonitor));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDefaultMonitor,
            0));
        Assert.True(memory.TryWriteLong(providerMonitor, providerSuccessor));
        Assert.True(memory.TryWriteLong(providerMonitor + 4u, list));
        var databaseField = nativeBase +
                            (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        Assert.True(memory.TryWriteLong(databaseField, 0));

        var allocator = new SequenceAddressAllocator(0x4000, 0x8000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);
        Assert.True(core.TryPublishNativeDisplayDatabase());
        var database = ReadLong(memory, databaseField);
        var monitor = core.OpenMonitor(0, 0);
        Assert.NotEqual(0u, monitor);
        Assert.Equal(monitor, ReadLong(memory, providerMonitor));

        // The malformed provider envelope makes database detachment refuse
        // after the monitor transaction has staged its compact move.  The
        // rebind rollback must append the resident back behind the provider
        // node before returning the old binding.
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            1));
        Assert.Equal(nativeBase, core.RebindGraphicsLibraryBase(0));
        Assert.True(core.IsBoundToGraphicsLibraryBase(nativeBase));
        Assert.Equal(database, ReadLong(memory, databaseField));
        Assert.Equal(0, allocator.FreeCount);
        Assert.Equal(providerMonitor,
            ReadLong(memory, nativeBase +
                (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(monitor, ReadLong(memory, providerMonitor));
        Assert.Equal(providerMonitor, ReadLong(memory, monitor + 4u));
        Assert.Equal(monitor, ReadLong(memory,
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));

        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.Equal(nativeBase, core.RebindGraphicsLibraryBase(0));
        Assert.True(core.IsBoundToGraphicsLibraryBase(0));
        Assert.Equal(0u, ReadLong(memory, databaseField));
        Assert.Equal(1, allocator.FreeCount);
        Assert.Equal(providerSuccessor, ReadLong(memory, providerMonitor));
        Assert.Equal(providerMonitor, ReadLong(memory,
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
    }

    [Fact]
    public void NativeGraphicsBaseRebindDetachesOwnedDisplayDatabaseBeforeMovingPublication()
    {
        var memory = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;

        void InitializeNativeEnvelope(uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(memory.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(memory.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
            Assert.True(memory.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
                0));
        }

        InitializeNativeEnvelope(firstBase);
        InitializeNativeEnvelope(secondBase);

        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(
            0x4000u,
            ReadLong(memory, firstBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));

        Assert.Equal(firstBase, core.RebindGraphicsLibraryBase(secondBase));
        Assert.Equal(
            0u,
            ReadLong(memory, firstBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(1, allocator.FreeCount);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(
            0x4000u,
            ReadLong(memory, secondBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(1, allocator.FreeCount);

        core.ReleaseNativeDisplayDatabase();
        Assert.Equal(
            0u,
            ReadLong(memory, secondBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(2, allocator.FreeCount);
    }

    [Fact]
    public void NativeGraphicsBaseRebindKeepsTheOldBindingUntilSidecarCanBeClearedThenRetries()
    {
        var backing = new FakeMemory(0x20000);
        const uint firstBase = 0x0800;
        const uint secondBase = 0x1000;

        void InitializeNativeEnvelope(uint baseAddress)
        {
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list));
            Assert.True(backing.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0));
            Assert.True(backing.TryWriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0));
            Assert.True(backing.TryWriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
                0));
        }

        InitializeNativeEnvelope(firstBase);
        InitializeNativeEnvelope(secondBase);
        var memory = new RejectingLongWriteMemory(backing);
        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: firstBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        var oldField = firstBase +
                       (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        memory.RejectedAddress = oldField;

        Assert.Equal(firstBase, core.RebindGraphicsLibraryBase(secondBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(firstBase));
        Assert.False(core.IsBoundToGraphicsLibraryBase(secondBase));
        Assert.Equal(0x4000u, ReadLong(backing, oldField));
        Assert.Equal(0u, ReadLong(
            backing,
            secondBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(0, allocator.FreeCount);

        // Once the provider bridge accepts the APTR clear again, the same
        // rebind request must be retryable.  The old publication is detached
        // and freed exactly once before the registries move to the new base.
        memory.RejectedAddress = 0;
        // RebindGraphicsLibraryBase returns the previous base on both
        // successful and declined transitions, matching its existing ABI.
        Assert.Equal(firstBase, core.RebindGraphicsLibraryBase(secondBase));
        Assert.True(core.IsBoundToGraphicsLibraryBase(secondBase));
        Assert.False(core.IsBoundToGraphicsLibraryBase(firstBase));
        Assert.Equal(0u, ReadLong(backing, oldField));
        Assert.Equal(
            0u,
            ReadLong(
                backing,
                secondBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(1, allocator.FreeCount);

        var node = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, node);
        Assert.Equal(
            secondBase,
            ReadLong(backing, node + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.True(core.GfxFree(node));
    }

    [Fact]
    public void NativeDisplayDatabaseClearsAReusedAllocationBeforePublication()
    {
        var memory = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(memory.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        Assert.True(memory.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            0));

        const uint recycledAddress = 0x4000;
        for (var offset = 0; offset < GraphicsDisplayDatabase.NativeDatabaseSize; offset++)
            Assert.True(memory.TryWriteByte(recycledAddress + (uint)offset, 0xA5));

        var core = new GraphicsLibraryCore(
            memory,
            new FixedAddressAllocator(recycledAddress),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        for (var index = 0; index < GraphicsDisplayDatabase.NativeMonitorPositionCount; index++)
        {
            var record = recycledAddress + (uint)(GraphicsDisplayDatabase.NativeMonitorPositionsOffset +
                index * GraphicsDisplayDatabase.NativeMonitorPositionRecordSize);
            Assert.Equal(index == 0 ? 0x11000u : 0x21000u, ReadLong(memory, record));
            Assert.Equal(0x0081002Cu, ReadLong(memory, record + 4));
            Assert.Equal(0x0081002Cu, ReadLong(memory, record + 8));
        }
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(0, true)]
    [InlineData(1, true)]
    [InlineData(2, true)]
    public void NativeGraphicsMonitorPositionsSurviveOwnedTableLifecycle(int transition, bool rejectThenRetry = false)
    {
        var memory = new FakeMemory(0x20000);
        InitializeBase(0x800);
        InitializeBase(0x18000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(),
            new FakeDisplay(), graphicsLibraryBase: 0x800);
        Assert.True(core.TryPublishNativeDisplayDatabase());
        var field = 0x800u + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        var database = ReadLong(memory, field);
        var start = database + (uint)GraphicsDisplayDatabase.NativeMonitorPositionsOffset;
        memory.TryWriteLong(start + 4, 0xFFFE0007);
        memory.TryWriteLong(start + 16, 0x0009000A);
        if (rejectThenRetry)
        {
            memory.TryWriteLong(start + 12, 0); // malformed second record
            if (transition == 2)
                core.RebindGraphicsLibraryBase(0x18000);
            else
                core.ReleaseNativeDisplayDatabase();
            Assert.Equal(database, ReadLong(memory, field));
            Assert.Equal(0u, ReadLong(memory, 0x18000u + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
            Assert.Equal(0xFFFE0007u, ReadLong(memory, start + 4));
            Assert.Equal(0x0009000Au, ReadLong(memory, start + 16));
            memory.TryWriteLong(start + 12, 0x21000);
        }
        if (transition == 2)
        {
            core.RebindGraphicsLibraryBase(0x18000);
            Assert.Equal(0u, ReadLong(memory, field));
            field = 0x18000u + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        }
        else
        {
            if (transition == 1)
                memory.TryWriteLong(field, 0);
            core.ReleaseNativeDisplayDatabase();
            Assert.Equal(0u, ReadLong(memory, field));
        }
        Assert.True(core.TryPublishNativeDisplayDatabase());
        var next = ReadLong(memory, field) + (uint)GraphicsDisplayDatabase.NativeMonitorPositionsOffset;
        Assert.Equal(0xFFFE0007u, ReadLong(memory, next + 4));
        Assert.Equal(0x0009000Au, ReadLong(memory, next + 16));
        Assert.Equal(0x0081002Cu, ReadLong(memory, next + 8));
        Assert.Equal(0x0081002Cu, ReadLong(memory, next + 20));

        void InitializeBase(uint address)
        {
            var list = address + (uint)GraphicsLayouts.GfxBaseMonitorList;
            memory.TryWriteLong(list, list + 4);
            memory.TryWriteLong(list + 4, 0);
            memory.TryWriteLong(list + 8, list);
        }
    }

    [Theory]
    [InlineData(false, 0)]
    [InlineData(false, 1)]
    [InlineData(false, 2)]
    [InlineData(true, 0)]
    [InlineData(true, 1)]
    [InlineData(true, 2)]
    public void NativeGraphicsMonitorRegistrationStateSurvivesOwnedTableLifecycle(bool ntsc, int transition)
    {
        foreach (var pointers in new[] { (0u, 0u), (1u, 0xDEADBEEFu), (uint.MaxValue, 0xFFFFFF60u), (0x4001u, 0u) })
        {
            const uint graphics = 0x1000, nextBase = 0x2000;
            var memory = new FakeMemory(0x10000);
            foreach (var address in new[] { graphics, nextBase })
                GraphicsLibraryImageLayout.CreateGuestImage(address, 0x264, 0, 0x264, 40, 68,
                    "graphics.library", "graphics.library 40.68", GraphicsLibraryImageProfile.NativePal, true)
                    .CopyTo(memory.Bytes, (int)address);
            var allocator = new FixedAddressAllocator(0x4000);
            var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(),
                new FakeDisplay { IsNtsc = ntsc }, graphicsLibraryBase: graphics);
            Assert.True(core.TryPublishNativeDisplayDatabase());
            var database = ReadLong(memory, graphics + GraphicsLayouts.GfxBaseDisplayInfoDataBase);
            var positions = database + (uint)GraphicsDisplayDatabase.NativeMonitorPositionsOffset;
            Assert.True(memory.TryWriteLong(positions + 4, 0xFFF90009));
            Assert.True(memory.TryWriteLong(positions + 8, 0x8000FFFF));
            Assert.True(memory.TryWriteLong(positions + 16, 0xFFFF0001));
            Assert.True(memory.TryWriteLong(positions + 20, 0x000AFFF6));
            Assert.True(memory.TryWriteLong(database + (uint)GraphicsDisplayDatabase.NativeDefaultMonitorIdOffset,
                ntsc ? 0x21000u : 0x11000u));
            Assert.True(memory.TryWriteLong(database + (uint)GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset, pointers.Item1));
            Assert.True(memory.TryWriteLong(database + (uint)GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset + 4, pointers.Item2));
            var expected = memory.Bytes.AsSpan((int)positions,
                GraphicsDisplayDatabase.NativeDatabaseSize - GraphicsDisplayDatabase.NativeMonitorPositionsOffset).ToArray();
            if (transition == 2)
            {
                Assert.Equal(graphics, core.RebindGraphicsLibraryBase(nextBase));
                Assert.True(core.IsBoundToGraphicsLibraryBase(nextBase));
            }
            else
            {
                if (transition == 1) Assert.True(memory.TryWriteLong(graphics + GraphicsLayouts.GfxBaseDisplayInfoDataBase, 0));
                core.ReleaseNativeDisplayDatabase();
            }
            Assert.Equal(1, allocator.FreeCount);
            Assert.Equal(0u, ReadLong(memory, graphics + GraphicsLayouts.GfxBaseDisplayInfoDataBase));
            Assert.True(core.TryPublishNativeDisplayDatabase());
            var current = transition == 2 ? nextBase : graphics;
            database = ReadLong(memory, current + GraphicsLayouts.GfxBaseDisplayInfoDataBase);
            Assert.Equal(expected, memory.Bytes.AsSpan((int)database + GraphicsDisplayDatabase.NativeMonitorPositionsOffset,
                expected.Length).ToArray());
            Assert.Equal(88, core.GetDisplayInfoData(0, 0x8001, 88, GraphicsDisplayDatabase.DtagMntr, 0));
            Assert.Equal(ntsc ? pointers.Item2 : pointers.Item1, ReadLong(memory, 0x8011));
            Assert.False(core.IsOwnedMonitorSpec(pointers.Item1));
            Assert.False(core.IsOwnedMonitorSpec(pointers.Item2));
            Assert.Equal(0u, core.OpenMonitor(0, 0)); // DefaultMonitor is still absent
            core.ReleaseNativeDisplayDatabase();
            Assert.Equal(2, allocator.FreeCount);
        }
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    public void NativeGraphicsMonitorRegistrationCaptureRetainsOwnershipUntilAllFieldsAreReadable(int transition)
    {
        var position = GraphicsDisplayDatabase.NativeMonitorPositionsOffset;
        var family = GraphicsDisplayDatabase.NativeDefaultMonitorIdOffset;
        foreach (var field in new[] { position + 4, position + 8, position + 16, position + 20,
            family, family + 4, family + 8, -1 })
        {
            const uint graphics = 0x1000, nextBase = 0x2000;
            var backing = new FakeMemory(0x10000);
            var memory = new RejectingLongReadMemory(backing);
            foreach (var address in new[] { graphics, nextBase })
                GraphicsLibraryImageLayout.CreateGuestImage(address, 0x264, 0, 0x264, 40, 68,
                    "graphics.library", "graphics.library 40.68", GraphicsLibraryImageProfile.NativePal, true)
                    .CopyTo(backing.Bytes, (int)address);
            var allocator = new FixedAddressAllocator(0x4000);
            var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay(),
                graphicsLibraryBase: graphics);
            Assert.True(core.TryPublishNativeDisplayDatabase());
            const uint database = 0x4000;
            Assert.True(backing.TryWriteLong(database + (uint)family, field < 0 ? 0x31000u : 0x11000u));
            Assert.True(backing.TryWriteLong(database + (uint)family + 4, 0xDEADBEEF));
            Assert.True(backing.TryWriteLong(database + (uint)position + 4, 0xFFF90009));
            Assert.True(backing.TryWriteLong(database + (uint)position + 8, 0x8000FFFF));
            var pointer = graphics + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
            if (transition == 1) Assert.True(backing.TryWriteLong(pointer, 0));
            memory.RejectedAddress = field < 0 ? 0 : database + (uint)field;
            var before = backing.Bytes.ToArray();
            Transition();
            Assert.True(core.IsBoundToGraphicsLibraryBase(graphics));
            Assert.Equal(0, allocator.FreeCount);
            Assert.Equal(before, backing.Bytes);
            memory.RejectedAddress = 0;
            Assert.True(backing.TryWriteLong(database + (uint)family, 0x11000));
            Transition();
            Assert.Equal(1, allocator.FreeCount);
            Assert.True(core.TryPublishNativeDisplayDatabase());
            Assert.Equal(0x11000u, ReadLong(backing, database + (uint)family));
            Assert.Equal(0xDEADBEEFu, ReadLong(backing, database + (uint)family + 4));
            Assert.Equal(0xFFF90009u, ReadLong(backing, database + (uint)position + 4));
            Assert.Equal(0x8000FFFFu, ReadLong(backing, database + (uint)position + 8));

            void Transition()
            {
                if (transition == 2) Assert.Equal(graphics, core.RebindGraphicsLibraryBase(nextBase));
                else core.ReleaseNativeDisplayDatabase();
            }
        }
    }

    [Theory]
    [InlineData(-1)]
    [InlineData(0)]
    [InlineData(8)]
    [InlineData(12)]
    [InlineData(16)]
    [InlineData(20)]
    public void NativeGraphicsRuntimeDescriptorPublishesLastAndRetriesPartialWrites(int failingOffset)
    {
        var backing = new FakeMemory(0x20000);
        const uint address = 0x800;
        var image = GraphicsLibraryImageLayout.CreateGuestImage(address, 0x264, 0,
            0x264, 40, 68, "graphics.library", "graphics.library 40.68",
            GraphicsLibraryImageProfile.NativePal, true);
        Array.Copy(image, 0, backing.Bytes, (int)address, image.Length);
        var descriptor = address + 0x250;
        var memory = new PartialLongWriteMemory(backing);
        var descriptorWrites = new List<(uint Address, uint Value)>();
        memory.ObserveLongWrite = (target, value) =>
        {
            if (target >= descriptor && target < descriptor + 20)
                descriptorWrites.Add((target - descriptor, value));
            if (target == descriptor && value == 0x434D444Fu)
            {
                Assert.Equal(address, ReadLong(backing, descriptor + 8));
                Assert.Equal(0x4000u, ReadLong(backing, descriptor + 12));
                Assert.Equal((uint)GraphicsDisplayDatabase.NativeDatabaseSize, ReadLong(backing, descriptor + 16));
            }
        };
        if (failingOffset == 20)
            memory.RejectLongWrite = (target, value) => target == descriptor && value == 0x434D444Fu;
        else if (failingOffset >= 0)
            memory.PartialLongAddress = descriptor + (uint)failingOffset;
        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(),
            new FakeDisplay(), graphicsLibraryBase: address);
        var published = core.TryPublishNativeDisplayDatabase();
        Assert.Equal(failingOffset < 0, published);
        if (failingOffset < 0 || failingOffset == 20)
            Assert.Equal(new (uint Address, uint Value)[]
            {
                (0, 0), (8, address), (12, 0x4000),
                (16, (uint)GraphicsDisplayDatabase.NativeDatabaseSize), (0, 0x434D444F)
            }, descriptorWrites);
        if (!published)
        {
            Assert.Equal(0u, ReadLong(backing, descriptor));
            Assert.Equal(1u, ReadLong(backing, descriptor + 4));
            Assert.Equal(0u, ReadLong(backing, descriptor + 8));
            Assert.Equal(0u, ReadLong(backing, descriptor + 12));
            Assert.Equal(0u, ReadLong(backing, descriptor + 16));
            Assert.Equal(0, allocator.FreeCount);
            memory.PartialLongAddress = null;
            memory.RejectLongWrite = null;
            Assert.True(core.TryPublishNativeDisplayDatabase());
        }
        Assert.Equal(0x434D444Fu, ReadLong(backing, descriptor));
        Assert.Equal(address, ReadLong(backing, descriptor + 8));
        Assert.Equal(0x4000u, ReadLong(backing, descriptor + 12));
        Assert.Equal((uint)GraphicsDisplayDatabase.NativeDatabaseSize, ReadLong(backing, descriptor + 16));
        memory.PartialLongAddress = descriptor;
        Assert.False(core.ReleaseNativeDisplayDatabase());
        Assert.Equal(0, allocator.FreeCount);
        Assert.Equal(0x434D444Fu, ReadLong(backing, descriptor));
        Assert.Equal(0x4000u, ReadLong(backing, address + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        memory.PartialLongAddress = null;
        Assert.True(core.ReleaseNativeDisplayDatabase());
        Assert.Equal(0u, ReadLong(backing, descriptor));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Theory]
    [InlineData(0, false)]
    [InlineData(1, false)]
    [InlineData(2, false)]
    [InlineData(0, true)]
    [InlineData(1, true)]
    [InlineData(2, true)]
    public void NativeGraphicsRuntimeDescriptorInvalidatesAcrossRebindAndProviderReplacement(int action, bool failThenRetry)
    {
        var backing = new FakeMemory(0x20000);
        foreach (var address in new uint[] { 0x800, 0x1800 })
        {
            var image = GraphicsLibraryImageLayout.CreateGuestImage(address, 0x264, 0,
                0x264, 40, 68, "graphics.library", "graphics.library 40.68",
                GraphicsLibraryImageProfile.NativePal, true);
            Array.Copy(image, 0, backing.Bytes, (int)address, image.Length);
        }
        var memory = new PartialLongWriteMemory(backing);
        var allocator = new FixedAddressAllocator(0x4000);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(),
            new FakeDisplay(), graphicsLibraryBase: 0x800);
        Assert.True(core.TryPublishNativeDisplayDatabase());
        var field = 0x800u + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        const uint descriptor = 0xA50;
        if (action != 0)
            backing.TryWriteLong(field, 0xCAFE1234); // deliberately not mapped
        if (failThenRetry)
        {
            memory.PartialLongAddress = descriptor;
            Apply();
            Assert.Equal(0x434D444Fu, ReadLong(backing, descriptor));
            Assert.Equal(action == 0 ? 0x4000u : 0xCAFE1234u, ReadLong(backing, field));
            Assert.Equal(0, allocator.FreeCount);
            Assert.Equal(0u, ReadLong(backing, 0x1A50));
            memory.PartialLongAddress = null;
        }
        Apply();
        Assert.Equal(0u, ReadLong(backing, descriptor));
        Assert.Equal(action == 0 ? 0u : 0xCAFE1234u, ReadLong(backing, field));
        Assert.Equal(action == 0 ? 1 : 0, allocator.FreeCount);
        if (action == 0)
        {
            Assert.True(core.TryPublishNativeDisplayDatabase());
            Assert.Equal(0x434D444Fu, ReadLong(backing, 0x1A50));
            Assert.Equal(0x1800u, ReadLong(backing, 0x1A58));
            Assert.Equal(0x4000u, ReadLong(backing, 0x1A5C));
        }

        void Apply()
        {
            if (action == 0) core.RebindGraphicsLibraryBase(0x1800);
            else if (action == 1) core.TryPublishNativeDisplayDatabase();
            else core.ReleaseNativeDisplayDatabase();
        }
    }

    [Fact]
    public void NativeGraphicsMonitorPositionUpdatesOwnedGuestStateTransactionally()
    {
        var backing = new FakeMemory(0x20000);
        var memory = new PartialLongWriteMemory(backing);
        const uint nativeBase = 0x800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        backing.TryWriteLong(list, list + 4);
        backing.TryWriteLong(list + 4, 0);
        backing.TryWriteLong(list + 8, list);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(),
            new FakeBlitter(), new FakeDisplay(), graphicsLibraryBase: nativeBase);
        Assert.True(core.TrySetMonitorViewPosition(0x11000, 130, 46));
        var field = nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        var database = ReadLong(backing, field);
        var cell = database + (uint)GraphicsDisplayDatabase.NativeMonitorPositionsOffset + 4;
        Assert.Equal(0x0082002Eu, ReadLong(backing, cell));
        Assert.Equal(0x0081002Cu, ReadLong(backing, cell + 4));

        backing.TryWriteLong(cell, 0xFFFE0007);
        Assert.Equal(88, core.GetDisplayInfoData(0, 0x10000, 88, 0x80002000, 0x19000));
        Assert.Equal(0xFFFE0007u, ReadLong(backing, 0x10014));
        Assert.Equal(0x0081002Cu, ReadLong(backing, 0x10050));
        backing.TryWriteLong(cell + 4, 0x8000FFFF);
        Assert.Equal(88, core.GetDisplayInfoData(0, 0x10000, 88, 0x80002000, 0x19000));
        Assert.Equal(0xFFFE0007u, ReadLong(backing, 0x10014));
        Assert.Equal(0x8000FFFFu, ReadLong(backing, 0x10050));
        backing.TryWriteLong(cell + 4, 0x0081002C);
        Assert.True(core.TrySetMonitorViewPosition(0x11000, 3, null));
        Assert.Equal(0x00030007u, ReadLong(backing, cell));
        memory.PartialLongAddress = cell;
        Assert.False(core.TrySetMonitorViewPosition(0x11000, 9, 10));
        Assert.Equal(0x00030007u, ReadLong(backing, cell));
        memory.PartialLongAddress = null;
        backing.TryWriteLong(database + 4, 1);
        Assert.False(core.TrySetMonitorViewPosition(0x11000, 9, 10));
        Assert.Equal(0x00030007u, ReadLong(backing, cell));
        backing.TryWriteLong(database + 4, GraphicsDisplayDatabase.NativeDatabaseVersion);
        backing.TryWriteLong(field, 0x18000);
        Assert.False(core.TrySetMonitorViewPosition(0x11000, 9, 10));
        Assert.Equal(0x18000u, ReadLong(backing, field));
        Assert.Equal(0x00030007u, ReadLong(backing, cell));
        Assert.Equal(0x0081002Cu, ReadLong(backing, cell + 4));
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void NativeGraphicsDatabaseVersionThreePreservesPointsAndInitializesRegistration(bool ecs, bool ntsc)
    {
        var memory = new FakeMemory(0x20000);
        Assert.True(GraphicsDisplayDatabase.TryCreateNativeDatabase(memory,
            new FixedAddressAllocator(0x4000), ecs, out var database, defaultMonitorNtsc: ntsc));
        var nativeImage = GraphicsDisplayDatabase.CreateNativeDatabaseImage(ecs, ntsc);
        Assert.Equal(GraphicsDisplayDatabase.NativeDatabaseSize, nativeImage.Length);
        Assert.Equal(nativeImage, Enumerable.Range(0, nativeImage.Length)
            .Select(index => ReadByte(memory, database + (uint)index)));
        // Every construction owns its bytes; embedding/relocation may not
        // mutate a static template shared with another library instance.
        nativeImage[0] = 0;
        Assert.Equal((byte)0x43, GraphicsDisplayDatabase.CreateNativeDatabaseImage(ecs)[0]);
        Assert.Equal(3u, ReadLong(memory, database + 4));
        var registration = GraphicsDisplayDatabase.NativeDefaultMonitorIdOffset;
        Assert.Equal(GraphicsDisplayDatabase.NativeMonitorPositionsOffset + 24, registration);
        Assert.Equal(ntsc ? 0x11000u : 0x21000u, ReadLong(memory, database + (uint)registration));
        Assert.Equal(0u, ReadLong(memory, database + (uint)registration + 4));
        Assert.Equal(0u, ReadLong(memory, database + (uint)registration + 8));
        Assert.Equal(registration + 12, nativeImage.Length);
        Assert.Equal((uint)GraphicsDisplayDatabase.NativeDatabaseSize, ReadLong(memory, database + 8));
        for (var index = 0; index < 2; index++)
        {
            var record = database + (uint)(GraphicsDisplayDatabase.NativeMonitorPositionsOffset + index * 12);
            Assert.Equal(index == 0 ? 0x11000u : 0x21000u, ReadLong(memory, record));
            Assert.Equal(0x0081002Cu, ReadLong(memory, record + 4));
            Assert.Equal(0x0081002Cu, ReadLong(memory, record + 8));
            Assert.True(memory.TryWriteLong(record + 4, 0xFFFE0007));
            Assert.Equal(0x0081002Cu, ReadLong(memory, record + 8));
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void NativeGraphicsDatabasePublicationRegistersExistingHostResidents(bool ntsc, bool rebind)
    {
        foreach (var residents in new[] { 0, 1, 2, 3 })
        {
            var memory = new FakeMemory(0x20000);
            const uint oldBase = 0x1000, newBase = 0x2000;
            foreach (var address in new[] { oldBase, newBase })
            {
                var list = address + (uint)GraphicsLayouts.GfxBaseMonitorList;
                Assert.True(memory.TryWriteLong(list, list + 4));
                Assert.True(memory.TryWriteLong(list + 8, list));
            }
            var allocator = new SequenceAddressAllocator(0x4000, 0x5000, 0x6000);
            var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(),
                new FakeDisplay { IsNtsc = ntsc }, graphicsLibraryBase: oldBase);
            var monitors = new uint[2];
            for (var index = 0; index < 2; index++)
            {
                if ((residents & (1 << index)) == 0) continue;
                monitors[index] = core.OpenMonitor(0, index == 0 ? 0x11000u : 0x21000u);
                Assert.NotEqual(0u, monitors[index]);
                // Registration uses known family identity, not mutable names,
                // timing flags, reference count, or the public default pointer.
                Assert.True(memory.TryWriteWord(monitors[index] + GraphicsLayouts.MonitorSpecFlags, 0));
                Assert.True(memory.TryWriteLong(monitors[index] + GraphicsLayouts.MonitorSpecNodeName, uint.MaxValue));
            }
            if (rebind)
            {
                Assert.Equal(oldBase, core.RebindGraphicsLibraryBase(newBase));
                Assert.True(core.IsBoundToGraphicsLibraryBase(newBase));
            }
            var graphics = rebind ? newBase : oldBase;
            Assert.True(memory.TryWriteWord(graphics + 0x12, GraphicsLibraryImageLayout.NativeRuntimeImageSize));
            Assert.True(memory.TryWriteLong(graphics + 0x254, 1));
            Assert.True(core.TryPublishNativeDisplayDatabase());
            var database = ReadLong(memory, graphics + GraphicsLayouts.GfxBaseDisplayInfoDataBase);
            for (var index = 0; index < 2; index++)
            {
                var family = index == 0 ? 0x11000u : 0x21000u;
                var slot = database + (uint)GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset + (uint)index * 4;
                Assert.Equal(monitors[index], ReadLong(memory, slot));
                Assert.Equal(88, core.GetDisplayInfoData(0, 0x3001, 96, GraphicsDisplayDatabase.DtagMntr, family));
                Assert.Equal(monitors[index], ReadLong(memory, 0x3011));
                Assert.Equal(monitors[index], core.OpenMonitor(0, family));
                if (monitors[index] != 0)
                {
                    Assert.Equal((ushort)2, ReadWord(memory, monitors[index] + GraphicsLayouts.MonitorSpecOpenCount));
                    Assert.Equal(0, core.CloseMonitor(monitors[index]));
                }
                // Idempotent publication must not re-seed a guest-modified slot.
                Assert.True(memory.TryWriteLong(slot, 0xDEADBEEF));
                Assert.True(core.TryPublishNativeDisplayDatabase());
                Assert.Equal(0xDEADBEEFu, ReadLong(memory, slot));
            }
            core.ReleaseNativeDisplayDatabase();
            Assert.Equal(1, allocator.FreeCount); // database only, no resident adoption/free
            foreach (var monitor in monitors.Where(pointer => pointer != 0))
            {
                Assert.True(core.IsOwnedMonitorSpec(monitor));
                Assert.Equal((ushort)1, ReadWord(memory, monitor + GraphicsLayouts.MonitorSpecOpenCount));
            }
        }
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(false, true)]
    [InlineData(true, false)]
    [InlineData(true, true)]
    public void NativeGraphicsRegistrationTrailerFailureRestoresAllocationAndCanRetry(bool ecs, bool ntsc)
    {
        foreach (var field in new[] { 0, 4, 8 })
        {
            const uint heap = 0x4000;
            var backing = new FakeMemory(0x20000);
            var size = GraphicsDisplayDatabase.NativeDatabaseSize;
            backing.Bytes.AsSpan((int)heap, size).Fill(0xA5);
            var before = backing.Bytes.ToArray();
            var memory = new PartialLongWriteMemory(backing)
            { PartialLongAddress = heap + (uint)GraphicsDisplayDatabase.NativeDefaultMonitorIdOffset + (uint)field };
            var allocator = new FixedAddressAllocator(heap);
            Assert.False(GraphicsDisplayDatabase.TryCreateNativeDatabase(memory, allocator, ecs,
                out var failed, defaultMonitorNtsc: ntsc, ntscMonitor: 0xDEADBEEF, palMonitor: 1));
            Assert.Equal(0u, failed);
            Assert.Equal(1, allocator.FreeCount);
            Assert.Equal(before, backing.Bytes);
            memory.PartialLongAddress = null;
            Assert.True(GraphicsDisplayDatabase.TryCreateNativeDatabase(memory, allocator, ecs,
                out var database, defaultMonitorNtsc: ntsc, ntscMonitor: 0xDEADBEEF, palMonitor: 1));
            Assert.Equal(heap, database);
            var expected = GraphicsDisplayDatabase.CreateNativeDatabaseImage(ecs, ntsc);
            System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(
                expected.AsSpan(GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset), 0xDEADBEEF);
            System.Buffers.Binary.BinaryPrimitives.WriteUInt32BigEndian(
                expected.AsSpan(GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset + 4), 1);
            Assert.Equal(expected, backing.Bytes.AsSpan((int)heap, size).ToArray());
            Assert.Equal(1, allocator.FreeCount);
        }
    }

    [Theory]
    [InlineData("provider")]
    [InlineData("rebind")]
    [InlineData("backlink")]
    public void NativeGraphicsDatabasePublicationRechecksOwnershipAfterConstruction(string change)
    {
        const uint graphics = 0x1000, nextBase = 0x2000, monitor = 0x4000, candidate = 0x5000;
        var backing = new FakeMemory(0x20000);
        var memory = new PartialLongWriteMemory(backing);
        foreach (var address in new[] { graphics, nextBase })
        {
            var list = address + (uint)GraphicsLayouts.GfxBaseMonitorList;
            Assert.True(backing.TryWriteLong(list, list + 4));
            Assert.True(backing.TryWriteLong(list + 8, list));
        }
        var allocator = new SequenceAddressAllocator(monitor, candidate, 0x6000);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(),
            new FakeDisplay(), graphicsLibraryBase: graphics);
        Assert.Equal(monitor, core.OpenMonitor(0, 0x21000));
        Assert.True(backing.TryWriteWord(graphics + 0x12, GraphicsLibraryImageLayout.NativeRuntimeImageSize));
        Assert.True(backing.TryWriteLong(graphics + 0x254, 1));
        var field = graphics + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        var callbacks = 0;
        memory.ObserveLongWrite = (address, _) =>
        {
            if (address != candidate + (uint)GraphicsDisplayDatabase.NativeDefaultMonitorIdOffset) return;
            callbacks++;
            if (change == "provider") Assert.True(backing.TryWriteLong(field, 0xDEADBEEF));
            else if (change == "rebind")
            {
                Assert.Equal(graphics, core.RebindGraphicsLibraryBase(nextBase));
                Assert.True(core.IsBoundToGraphicsLibraryBase(nextBase));
            }
            else Assert.True(backing.TryWriteLong(monitor + GraphicsLayouts.ExtendedNodeLibrary, nextBase));
        };
        Assert.False(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(1, callbacks);
        Assert.Equal(change == "provider" ? 0xDEADBEEFu : 0, ReadLong(backing, field));
        Assert.Equal(0u, ReadLong(backing, graphics + 0x250));
        Assert.Equal(1, allocator.FreeCount);
        Assert.True(core.IsOwnedMonitorSpec(monitor));
        Assert.Equal((ushort)1, ReadWord(backing, monitor + GraphicsLayouts.MonitorSpecOpenCount));

        // Retry after the externally changed condition is repaired. The failed
        // candidate must never become a hidden ownership claim or be freed twice.
        memory.ObserveLongWrite = null;
        var current = change == "rebind" ? nextBase : graphics;
        Assert.True(backing.TryWriteLong(field, 0));
        Assert.True(backing.TryWriteLong(monitor + GraphicsLayouts.ExtendedNodeLibrary, current));
        Assert.True(backing.TryWriteWord(current + 0x12, GraphicsLibraryImageLayout.NativeRuntimeImageSize));
        Assert.True(backing.TryWriteLong(current + 0x254, 1));
        Assert.True(core.TryPublishNativeDisplayDatabase());
        var database = ReadLong(backing, current + GraphicsLayouts.GfxBaseDisplayInfoDataBase);
        Assert.Equal(0x6000u, database);
        Assert.Equal(monitor, ReadLong(backing, database + (uint)GraphicsDisplayDatabase.NativeMonitorRegistrationsOffset + 4));
        core.ReleaseNativeDisplayDatabase();
        Assert.Equal(2, allocator.FreeCount);
    }

    [Fact]
    public void NativeGraphicsBasePreservesProviderDisplayDatabaseAndRollsBackFailedPublish()
    {
        var backing = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u);
        backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0);
        backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list);
        backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0);
        backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0);
        const uint providerDatabase = 0xCAFE_1234u;
        backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            providerDatabase);

        var providerCore = new GraphicsLibraryCore(
            backing,
            new FixedAddressAllocator(0x4000),
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);
        Assert.True(providerCore.TryPublishNativeDisplayDatabase());
        Assert.Equal(
            providerDatabase,
            ReadLong(backing, nativeBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));

        // A guest write failure after sidecar initialization must free the
        // private block and leave the public APTR at its original zero value.
        backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase,
            0);
        var rejectingMemory = new RejectingLongWriteMemory(backing)
        {
            RejectedAddress = nativeBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase
        };
        var allocator = new FixedAddressAllocator(0x5000);
        var failingCore = new GraphicsLibraryCore(
            rejectingMemory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);
        Assert.False(failingCore.TryPublishNativeDisplayDatabase());
        Assert.Equal(
            0u,
            ReadLong(backing, nativeBase +
                (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Theory]
    [InlineData(-1)]
    [InlineData(0)]
    [InlineData(4)]
    [InlineData(8)]
    [InlineData(12)]
    [InlineData(16)]
    [InlineData(20)]
    public void NativeDisplayDatabaseRestoresItsGuestEnvelopeAfterPartialInitialization(int positionOffset)
    {
        var backing = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));
        var displayDatabaseField = nativeBase +
                                   (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        Assert.True(backing.TryWriteLong(displayDatabaseField, 0));

        const uint database = 0x4000;
        var original = new byte[GraphicsDisplayDatabase.NativeDatabaseSize];
        for (var offset = 0; offset < original.Length; offset++)
        {
            original[offset] = (byte)(0x30 + (offset & 0x3F));
            Assert.True(backing.TryWriteByte(database + (uint)offset, original[offset]));
        }

        var memory = new PartialLongWriteMemory(backing)
        {
            PartialLongAddress = positionOffset < 0 ? database + 4u :
                database + (uint)(GraphicsDisplayDatabase.NativeMonitorPositionsOffset + positionOffset)
        };
        var allocator = new FixedAddressAllocator(database);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);

        Assert.False(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(0u, ReadLong(backing, displayDatabaseField));
        Assert.Equal(1, allocator.FreeCount);
        for (var offset = 0; offset < original.Length; offset++)
        {
            Assert.Equal(
                original[offset],
                backing.Bytes[(int)database + offset]);
        }

        memory.PartialLongAddress = null;
        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(database, ReadLong(backing, displayDatabaseField));
        core.ReleaseNativeDisplayDatabase();
        Assert.Equal(2, allocator.FreeCount);
    }

    [Fact]
    public void NativeDisplayDatabaseRestoresTheGfxBasePointerAfterPartialPublication()
    {
        var backing = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));

        var displayDatabaseField = nativeBase +
                                   (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        Assert.True(backing.TryWriteLong(displayDatabaseField, 0));

        const uint database = 0x4000;
        var memory = new PartialLongWriteMemory(backing)
        {
            PartialLongAddress = displayDatabaseField
        };
        var allocator = new FixedAddressAllocator(database);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);

        // The APTR publication accepts its first two bytes and then rejects
        // the LONG.  The failed sidecar must not leave a dangling pointer to
        // the block that is released by the rollback.
        Assert.False(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(0u, ReadLong(backing, displayDatabaseField));
        Assert.Equal(1, allocator.FreeCount);

        memory.PartialLongAddress = null;
        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(database, ReadLong(backing, displayDatabaseField));
        core.ReleaseNativeDisplayDatabase();
        Assert.Equal(2, allocator.FreeCount);
    }

    [Fact]
    public void NativeDisplayDatabaseReleaseRestoresThePointerAfterPartialClear()
    {
        var backing = new FakeMemory(0x20000);
        const uint nativeBase = 0x0800;
        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            list + 4u));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0));
        Assert.True(backing.TryWriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            list));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0));
        Assert.True(backing.TryWriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0));

        var displayDatabaseField = nativeBase +
                                   (uint)GraphicsLayouts.GfxBaseDisplayInfoDataBase;
        Assert.True(backing.TryWriteLong(displayDatabaseField, 0));

        const uint database = 0x4000;
        var memory = new PartialLongWriteMemory(backing);
        var allocator = new FixedAddressAllocator(database);
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay(),
            graphicsLibraryBase: nativeBase);

        Assert.True(core.TryPublishNativeDisplayDatabase());
        Assert.Equal(database, ReadLong(backing, displayDatabaseField));

        // Teardown accepts the first three zero bytes and then rejects the
        // pointer LONG. The sidecar must remain allocated and reachable until
        // a later retry can clear the complete APTR.
        memory.PartialLongAddress = displayDatabaseField;
        core.ReleaseNativeDisplayDatabase();
        Assert.Equal(database, ReadLong(backing, displayDatabaseField));
        Assert.Equal(0, allocator.FreeCount);

        memory.PartialLongAddress = null;
        core.ReleaseNativeDisplayDatabase();
        Assert.Equal(0u, ReadLong(backing, displayDatabaseField));
        Assert.Equal(1, allocator.FreeCount);
    }

    [Fact]
    public void GraphicsExtendedNodeAssociationRestoresBothNodesWhenTheOldLinkCannotBeCleared()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RejectingLongWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        var viewPortExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.NotEqual(0u, viewPortExtra);
        Assert.True(core.GfxAssociate(0x300, viewExtra));
        Assert.Equal(viewExtra, core.GfxLookUp(0x300));

        memory.RejectedAddress = viewExtra + (uint)GraphicsLayouts.ViewExtraView;
        Assert.False(core.GfxAssociate(0x300, viewPortExtra));

        Assert.Equal(viewExtra, core.GfxLookUp(0x300));
        Assert.Equal(0x300u, ReadLong(backing, viewExtra + (uint)GraphicsLayouts.ViewExtraView));
        Assert.Equal(0u, ReadLong(backing, viewPortExtra + (uint)GraphicsLayouts.ViewPortExtraViewPort));

        memory.RejectedAddress = 0;
        Assert.True(core.GfxFree(viewExtra));
        Assert.True(core.GfxFree(viewPortExtra));
    }

    [Fact]
    public void GraphicsExtendedNodeAssociationRestoresPartialBacklinkWrites()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        var first = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        var second = core.GfxNew(GraphicsExtendedNodeOperations.ViewPortExtraType);
        Assert.NotEqual(0u, first);
        Assert.NotEqual(0u, second);
        const uint firstView = 0x300;
        const uint secondView = 0x400;
        Assert.True(core.GfxAssociate(firstView, first));

        // The new node backlink is a four-byte guest publication. A late
        // byte failure must restore its original zero and leave no lookup.
        memory.FailOnNextByteWrite(3);
        Assert.False(core.GfxAssociate(secondView, second));
        Assert.Equal(0u, ReadLong(backing, second + (uint)GraphicsLayouts.ViewPortExtraViewPort));
        Assert.Equal(0u, core.GfxLookUp(secondView));
        Assert.Equal(first, core.GfxLookUp(firstView));

        Assert.True(core.GfxAssociate(secondView, second));
        Assert.Equal(second, core.GfxLookUp(secondView));

        // Replacing the first association writes the new node first, then
        // clears the previous node. Fail during that second publication and
        // require both guest LONGs and both registry entries to roll back.
        memory.FailOnNextByteWrite(7);
        Assert.False(core.GfxAssociate(firstView, second));
        Assert.Equal(secondView, ReadLong(backing, second + (uint)GraphicsLayouts.ViewPortExtraViewPort));
        Assert.Equal(firstView, ReadLong(backing, first + (uint)GraphicsLayouts.ViewExtraView));
        Assert.Equal(first, core.GfxLookUp(firstView));
        Assert.Equal(second, core.GfxLookUp(secondView));

        Assert.True(core.GfxAssociate(firstView, second));
        Assert.Equal(0u, core.GfxLookUp(secondView));
        Assert.Equal(second, core.GfxLookUp(firstView));
        Assert.Equal(0u, ReadLong(backing, first + (uint)GraphicsLayouts.ViewExtraView));
        Assert.True(core.GfxFree(first));
        Assert.True(core.GfxFree(second));
    }

    [Fact]
    public void GraphicsExtendedNodeFreeDeclinesUnreadableAssociationWithoutLeavingStaleLookup()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RejectingLongReadMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        Assert.True(core.GfxAssociate(0x300, viewExtra));

        memory.RejectedAddress = viewExtra + (uint)GraphicsLayouts.ViewExtraView;
        Assert.False(core.GfxFree(viewExtra));
        Assert.Equal(viewExtra, core.GfxLookUp(0x300));
        Assert.DoesNotContain(
            allocator.Freed,
            allocation => allocation.Address == viewExtra);

        memory.RejectedAddress = 0;
        Assert.True(core.GfxFree(viewExtra));
        Assert.Equal(0u, core.GfxLookUp(0x300));
        Assert.Equal(0u, ReadLong(backing, viewExtra + (uint)GraphicsLayouts.ViewExtraView));
    }

