    [Fact]
    public void NativeOverlayGfxFreePreflightsOwnedAssociationBacklinkBeforePartialClear()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new PartialThenRejectLongWriteMemory(backing);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var viewExtra = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, viewExtra);
        const uint view = 0x300;
        Assert.True(core.GfxAssociate(view, viewExtra));

        var backlink = viewExtra + (uint)GraphicsLayouts.ViewExtraView;
        memory.PartialLongAddress = backlink;
        var writesBeforeDecline = backing.WriteCount;
        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, _) => address != backlink);
        var state = new M68kCpuState
        {
            A = { [0] = viewExtra },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 283,
            ProgramCounter = 0x0012_8B41
        };

        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.GfxFree,
            nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(283, state.Cycles);
        Assert.Equal(0x0012_8B41u, state.ProgramCounter);
        Assert.Equal(writesBeforeDecline, backing.WriteCount);
        Assert.Equal(viewExtra, core.GfxLookUp(view));
        Assert.Equal(view, ReadLong(backing, backlink));
        Assert.DoesNotContain(
            allocator.Freed,
            allocation => allocation.Address == viewExtra);
    }

