        Assert.True(backing.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            rasInfo));
        Assert.True(backing.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoNext,
            0));
        Assert.True(backing.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            bitMap));
        Assert.True(backing.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            4));
        Assert.True(backing.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));

        Assert.Equal(GraphicsViewportStatuses.Ok, core.MakeViewPort(view, viewPort));
        var temporaryExtra = core.GfxLookUp(viewPort);
        Assert.NotEqual(0u, temporaryExtra);
