        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isWritableMemoryRange: (address, _) => address != flagsAddress);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = temporaryExtra },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 307,
            ProgramCounter = 0x0012_8B61
        };

        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.GfxAssociate,
            nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(307, state.Cycles);
        Assert.Equal(0x0012_8B61u, state.ProgramCounter);
        Assert.Equal(writesBeforeDecline, backing.WriteCount);
        Assert.Equal((ushort)1, ReadWord(backing, flagsAddress));
        Assert.Equal(temporaryExtra, core.GfxLookUp(viewPort));
        Assert.DoesNotContain(
            allocator.Freed,
            allocation => allocation.Address == temporaryExtra);
    }

