    [Fact]
    public void GraphicsExtendedNodeFreeRequiresNativeMetadataBeforeRelease()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var node = core.GfxNew(GraphicsExtendedNodeOperations.ViewExtraType);
        Assert.NotEqual(0u, node);

        Assert.True(memory.TryWriteByte(
            node + (uint)GraphicsLayouts.ExtendedNodeSubsystem,
            0));

        Assert.False(core.GfxFree(node));
        Assert.DoesNotContain(allocator.Freed, allocation => allocation.Address == node);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = node },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 67
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.GfxFree, nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(67, state.Cycles);
        Assert.DoesNotContain(allocator.Freed, allocation => allocation.Address == node);

        Assert.True(memory.TryWriteByte(
            node + (uint)GraphicsLayouts.ExtendedNodeSubsystem,
            2));
        Assert.True(core.GfxFree(node));
        Assert.Contains(allocator.Freed, allocation => allocation.Address == node);
    }

    [Fact]
    public void SimpleSpriteOwnershipFollowsGuestNumFieldAndEightSpritePool()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint sprite = 0x200;

        Assert.Equal(0, core.GetSprite(sprite, -1));
        Assert.Equal((ushort)0, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(1, core.GetSprite(sprite, -1));
        Assert.Equal((ushort)1, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(-1, core.GetSprite(sprite, 0));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.False(core.FreeSprite(-1));
        Assert.True(core.FreeSprite(0));
        Assert.Equal(0, core.GetSprite(sprite, 0));
        Assert.Equal(-1, core.GetSprite(sprite, 8));

        var state = new M68kCpuState { A = { [0] = sprite }, D = { [0] = unchecked((uint)-1) } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetSprite));
        Assert.Equal(2u, state.D[0]);
        Assert.Equal((ushort)2, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteNum));

        state.D[0] = 2;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeSprite));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(2, core.GetSprite(sprite, 2));
    }

    [Fact]
    public void SimpleSpriteGetRestoresTheUnassignedNumberAfterARejectedWordWrite()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint sprite = 0x200;

        for (short number = 0; number < 8; number++)
            Assert.Equal(number, core.GetSprite(sprite, number));

        Assert.True(backing.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteNum,
            0x1234));

        // Fail the low byte after the sentinel high byte is accepted.  The
        // original caller-owned number must survive the failed publication.
        memory.FailOnNextByteWrite(2);
        Assert.Equal(-1, core.GetSprite(sprite, -1));
        Assert.Equal(
            (ushort)0x1234,
            ReadWord(backing, sprite + (uint)GraphicsLayouts.SimpleSpriteNum));

        for (short number = 0; number < 8; number++)
            Assert.True(core.FreeSprite(number));

        Assert.Equal(0, core.GetSprite(sprite, -1));
        Assert.Equal(
            (ushort)0,
            ReadWord(backing, sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
    }

    [Fact]
    public void SpriteVectorsLeaveOddGuestEnvelopesForTheNativeProvider()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint oddSprite = 0x201;

        Assert.True(memory.TryWriteByte(oddSprite, 0xA5));
        Assert.Equal(-1, core.GetSprite(oddSprite, -1));
        Assert.Equal((byte)0xA5, ReadByte(memory, oddSprite));

        Assert.True(memory.TryWriteWord(oddSprite + (uint)GraphicsLayouts.SimpleSpriteX, 7));
        Assert.True(memory.TryWriteWord(oddSprite + (uint)GraphicsLayouts.SimpleSpriteY, 8));
        Assert.False(core.MoveSprite(0, oddSprite, 20, 21));
        Assert.Equal((ushort)7, ReadWord(memory, oddSprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)8, ReadWord(memory, oddSprite + (uint)GraphicsLayouts.SimpleSpriteY));

        const uint oddViewPort = 0x301;
        Assert.False(core.MoveSprite(oddViewPort, 0x200, 1, 2));
    }

    [Fact]
    public void SimpleSpriteMoveAndChangeUpdateGuestStateWithViewportAndImageGuards()
    {
        var memory = new FakeMemory(0x1000);
        var spriteBackend = new RecordingSpriteBackend();
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            spriteBackend: spriteBackend);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint sprite = 0x200;
        const uint viewPort = 0x300;
        const uint image = 0x800;

        Assert.True(memory.TryWriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteHeight, 2));
        Assert.Equal(0, core.GetSprite(sprite, 0));
        Assert.True(core.MoveSprite(0, sprite, -12, 300));
        Assert.Equal((ushort)0xFFF4, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)300, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        Assert.Equal((0u, sprite, (short)-12, (short)300), Assert.Single(spriteBackend.Moves));

        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = sprite },
            D = { [0] = 123, [1] = 45 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.MoveSprite));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)123, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)45, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        Assert.Equal((viewPort, sprite, (short)123, (short)45), spriteBackend.Moves[1]);

        for (var offset = 0; offset < 16; offset++)
            Assert.True(memory.TryWriteByte(image + (uint)offset, (byte)(offset + 1)));
        Assert.True(core.ChangeSprite(viewPort, sprite, image));
        Assert.Equal(image, ReadLong(memory, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal((viewPort, sprite, image), Assert.Single(spriteBackend.Changes));

        state.A[2] = image;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeSprite));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(2, spriteBackend.Changes.Count);

        Assert.False(core.ChangeSprite(viewPort, sprite, 0xFF8));
        Assert.Equal(image, ReadLong(memory, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.False(core.MoveSprite(0xFF0, sprite, 1, 2));
    }

    [Fact]
    public void SimpleSpriteChangeRequiresTheCompleteImageSpanToBeDisplayDmaAddressable()
    {
        var backing = new FakeMemory(0x1000);
        var queriedRanges = new List<(uint Address, uint Bytes)>();
        var allowDma = false;
        var memory = new DisplayClassMemory(
            backing,
            (address, byteCount) =>
            {
                queriedRanges.Add((address, byteCount));
                return allowDma &&
                    (address == 0x700u || address == 0x780u) &&
                    byteCount == 16u;
            });
        var spriteBackend = new RecordingSpriteBackend();
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay(),
            spriteBackend: spriteBackend);
        const uint sprite = 0x200;
        const uint oldImage = 0x600;
        const uint image = 0x700;
        const uint secondImage = 0x780;

        Assert.True(memory.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            2));
        Assert.True(memory.TryWriteLong(
            sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            oldImage));
        for (var offset = 0; offset < 16; offset++)
        {
            Assert.True(memory.TryWriteByte(image + (uint)offset, (byte)(offset + 1)));
            Assert.True(memory.TryWriteByte(secondImage + (uint)offset, (byte)(0x80 + offset)));
        }

        // The sidecar is asked about the POS/CTL prefix plus every row before
        // ChangeSprite publishes the caller-owned image pointer.
        Assert.False(core.ChangeSprite(0, sprite, image));
        Assert.Equal((image, 16u), Assert.Single(queriedRanges));
        Assert.Equal(oldImage, ReadLong(backing, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Empty(spriteBackend.Changes);

        allowDma = true;
        Assert.True(core.ChangeSprite(0, sprite, image));
        Assert.Equal(image, ReadLong(backing, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal((0u, sprite, image), Assert.Single(spriteBackend.Changes));

        // A register decline is transparent to a native/provider overlay: the
        // caller's D0, cycle frame, and published pointer remain untouched.
        allowDma = false;
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = sprite, [2] = secondImage },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 77,
            ProgramCounter = 0x0012_40A1
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeSprite));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(77, state.Cycles);
        Assert.Equal(0x0012_40A1u, state.ProgramCounter);
        Assert.Equal(image, ReadLong(backing, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Single(spriteBackend.Changes);

        allowDma = true;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeSprite));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(secondImage, ReadLong(backing, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal(2, spriteBackend.Changes.Count);
    }

    [Fact]
    public void SimpleSpriteChangeRestoresTheImagePointerAfterARejectedRepeatedLongRollback()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new PartialThenRejectLongWriteMemory(backing);
        var core = CreateCore(memory);
        const uint sprite = 0x200;
        const uint viewPort = 0x300;
        const uint oldImage = 0x600;
        const uint newImage = 0x700;
        var imagePointer = sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData;
        memory.PartialLongAddress = imagePointer;

        Assert.True(backing.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            2));
        Assert.True(backing.TryWriteLong(imagePointer, oldImage));
        for (var offset = 0; offset < 16; offset++)
            Assert.True(backing.TryWriteByte(newImage + (uint)offset, (byte)(offset + 1)));

        Assert.False(core.ChangeSprite(viewPort, sprite, newImage));
        Assert.Equal(oldImage, ReadLong(backing, imagePointer));

        memory.PartialLongAddress = null;
        Assert.True(core.ChangeSprite(viewPort, sprite, newImage));
        Assert.Equal(newImage, ReadLong(backing, imagePointer));
    }

    [Fact]
    public void SimpleSpriteMoveRegeneratesPositionControlWordsInViewportCoordinateSpace()
    {
        var memory = new FakeMemory(0x1000);
        var core = new GraphicsLibraryCore(
            memory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        const uint sprite = 0x200;
        const uint viewPort = 0x300;
        const uint posCtlData = 0x400;

        Assert.True(memory.TryWriteLong(
            sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            posCtlData));
        Assert.True(memory.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            3));
        Assert.True(memory.TryWriteWord(posCtlData + 2u, GraphicsLayouts.SpriteAttachedFlag));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDxOffset,
            unchecked((ushort)4)));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDyOffset,
            unchecked((ushort)6)));
        Assert.True(memory.TryWriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode)));

        Assert.True(core.MoveSprite(viewPort, sprite, 9, 11));

        // (9 + 4) / 2 = 6 and (11 + 6) / 2 = 8 in the viewport's
        // hires/interlaced coordinate space.  The canonical View origin is
        // H=0x81,V=0x2C, and the attached bit must survive the rewrite.
        Assert.Equal((ushort)0x3443, ReadWord(memory, posCtlData));
        Assert.Equal((ushort)0x3781, ReadWord(memory, posCtlData + 2u));
        Assert.Equal((ushort)9, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)11, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteY));
    }

