        Assert.False(core.MoveSprite(0, sprite, 20, 21));
        Assert.Equal((ushort)7, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)8, ReadWord(memory, sprite + (uint)GraphicsLayouts.SimpleSpriteY));
    }

    [Fact]
    public void SimpleSpriteMoveRestoresCoordinatesAndPositionControlOnALateWriteFailure()
    {
        var backing = new FakeMemory(0x1000);
        const uint sprite = 0x200;
        const uint posCtlData = 0x400;
        Assert.True(backing.TryWriteLong(
            sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            posCtlData));
        Assert.True(backing.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            3));
        Assert.True(backing.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteX,
            7));
        Assert.True(backing.TryWriteWord(
            sprite + (uint)GraphicsLayouts.SimpleSpriteY,
            8));
        Assert.True(backing.TryWriteWord(posCtlData, 0x1234));
        Assert.True(backing.TryWriteWord(posCtlData + 2u, 0x5678));

        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        // X, Y, POS and CTL are each two byte writes.  Reject only the final
        // control byte so the transaction must restore every earlier field.
        memory.FailOnNextByteWrite(8);

        Assert.False(core.MoveSprite(0, sprite, 20, 21));
        Assert.Equal((ushort)7, ReadWord(backing, sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)8, ReadWord(backing, sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        Assert.Equal((ushort)0x1234, ReadWord(backing, posCtlData));
        Assert.Equal((ushort)0x5678, ReadWord(backing, posCtlData + 2u));
    }

