        Assert.False(core.ChangeSprite(0, sprite, newImage));
        Assert.Equal(oldImage, ReadLong(backing, sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
    }

    [Fact]
    public void ExtendedSpriteAllocationConvertsPlanarBitmapAndPreservesOwnedStorage()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;

        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane1, 0x40));

        var state = new M68kCpuState { A = { [1] = 0, [2] = bitMap }, D = { [0] = 0xDEAD_BEEFu } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var extSprite = state.D[0];
        Assert.NotEqual(0u, extSprite);
        Assert.Equal(2u, ReadWord(memory, extSprite + (uint)GraphicsLayouts.SimpleSpriteHeight));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, extSprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, ReadWord(memory, extSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth));
        var image = ReadLong(memory, extSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal((ushort)0x4000, ReadWord(memory, image + 4));
        Assert.Equal((ushort)0x8000, ReadWord(memory, image + 6));
        Assert.Equal((ushort)0, ReadWord(memory, image + 8));
        Assert.Equal((ushort)0, ReadWord(memory, image + 10));

        state.A[2] = extSprite;
        state.D[0] = 0xFFFF_FFFF;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeSpriteData));
        Assert.Equal(0u, state.D[0]);
        Assert.Collection(
            allocator.Freed,
            allocation =>
            {
                Assert.Equal(image, allocation.Address);
                Assert.Equal(16u, allocation.Bytes);
                Assert.Equal(GraphicsMemoryClass.Chip, allocation.MemoryClass);
            },
            allocation =>
            {
                Assert.Equal(extSprite, allocation.Address);
                Assert.Equal((uint)GraphicsLayouts.ExtSpriteSize, allocation.Bytes);
                Assert.Equal(GraphicsMemoryClass.Public, allocation.MemoryClass);
            });

        // FreeSpriteData is ownership-aware and must not free a foreign guest
        // envelope merely because its bytes happen to look valid.
        state.A[2] = 0x300;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeSpriteData));
        Assert.Equal(2, allocator.Freed.Count);
    }

    [Fact]
    public void ExtendedSpriteAllocationRestoresRecycledEnvelopesAfterLatePublicationFailure()
    {
        var backing = new FakeMemory(0x2000);
        const uint bitMap = 0x800;
        const uint plane0 = 0x900;
        const uint plane1 = 0x904;
        const uint extSprite = 0x200;
        const uint image = 0x400;
        const int imageBytes = 16;

        WritePlanarSpriteSource(backing, bitMap, plane0, plane1);
        var originalExtSprite = new byte[GraphicsLayouts.ExtSpriteSize];
        for (var offset = 0; offset < originalExtSprite.Length; offset++)
        {
            originalExtSprite[offset] = (byte)(0xA0 + offset);
            Assert.True(backing.TryWriteByte(
                extSprite + (uint)offset,
                originalExtSprite[offset]));
        }

        var originalImage = new byte[imageBytes];
        for (var offset = 0; offset < originalImage.Length; offset++)
        {
            originalImage[offset] = (byte)(0x50 + offset);
            Assert.True(backing.TryWriteByte(image + (uint)offset, originalImage[offset]));
        }

        var memory = new PartialThenRejectLongWriteMemory(backing)
        {
            PartialLongAddress = extSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData
        };
        var allocator = new SequenceAddressAllocator(extSprite, image);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());

        // The first publication writes only three bytes of the image pointer
        // and rejects the long write.  Both recycled envelopes must be put
        // back exactly as they were before the allocator call returns.
        Assert.Equal(0u, core.AllocSpriteDataA(bitMap, 0));
        Assert.Equal(2, allocator.FreeCount);
        for (var offset = 0; offset < originalExtSprite.Length; offset++)
            Assert.Equal(originalExtSprite[offset], ReadByte(backing, extSprite + (uint)offset));
        for (var offset = 0; offset < originalImage.Length; offset++)
            Assert.Equal(originalImage[offset], ReadByte(backing, image + (uint)offset));

        // A clean retry can reuse the same guest spans; no poisoned partial
        // publication remains to affect the normal ownership path.
        memory.PartialLongAddress = null;
        var retryAllocator = new SequenceAddressAllocator(extSprite, image);
        var retryCore = new GraphicsLibraryCore(
            memory,
            retryAllocator,
            new FakeBlitter(),
            new FakeDisplay());
        var recovered = retryCore.AllocSpriteDataA(bitMap, 0);
        Assert.Equal(extSprite, recovered);
        Assert.Equal(image, ReadLong(backing, recovered + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        retryCore.FreeSpriteData(recovered);
        Assert.Equal(2, retryAllocator.FreeCount);
    }

    [Fact]
    public void ExtendedSpriteTagsTreatNullTagMoreAsEndOfList()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;
        const uint tags = 0x800;

        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1));
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane1, 0x40));
        WriteTag(memory, tags, 2u, 0); // TAG_MORE with a null continuation.

        // A null TAG_MORE is the shared Utility.library end-of-list form, so
        // the standard portable path must accept the otherwise empty option
        // list and allocate the default two-row sprite image.
        var direct = core.AllocSpriteDataA(bitMap, tags);
        Assert.NotEqual(0u, direct);
        core.FreeSpriteData(direct);

        // The CopperStart register adapter must expose the same guest result.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = tags, [2] = bitMap },
            D = { [0] = 0xDEAD_BEEFu }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.NotEqual(0u, state.D[0]);
        core.FreeSpriteData(state.D[0]);
    }

    [Fact]
    public void ExtendedSpriteTagsAcceptTheFinalGuestItemAndRejectImplicitWrap()
    {
        var memory = new WrappingMemory();
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x410;
        const uint tags = 0xFFFF_FFF8u;

        for (var address = bitMap; address < bitMap + (uint)GraphicsLayouts.BitMapSize; address++)
            memory.WriteByte(address, 0);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        for (var offset = 0u; offset < 4; offset++)
        {
            memory.WriteByte(plane0 + offset, 0x80);
            memory.WriteByte(plane1 + offset, 0x40);
        }

        // The test allocator returns the public envelope at 0x1000 and the
        // chip image immediately after it.  Make those guest spans readable
        // so the allocation's transactional clear/probe can claim them.
        for (var address = 0x1000u; address < 0x1100u; address++)
            memory.WriteByte(address, 0);

        // A terminal TagItem exactly occupies the final eight guest bytes.
        memory.WriteLong(tags, GraphicsRastPortAttributeOperations.TagDone);
        memory.WriteLong(tags + 4u, 0);
        var state = new M68kCpuState
        {
            A = { [1] = tags, [2] = bitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 313
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var extSprite = state.D[0];
        Assert.NotEqual(0u, extSprite);
        Assert.Equal(313, state.Cycles);
        core.FreeSpriteData(extSprite);

        // A non-terminal item at the same address must not wrap through low
        // memory and turn a malformed option list into a valid allocation.
        memory.WriteLong(tags, GraphicsLayouts.SpriteAOutputHeight);
        memory.WriteLong(tags + 4u, 2);
        state.D[0] = 0x1357_9BDFu;
        state.Cycles = 317;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(317, state.Cycles);
        Assert.Equal(2, allocator.Freed.Count);
    }

    [Fact]
    public void ExtendedSpriteAllocationRequiresTheCompleteImageSpanToBeDisplayDmaAddressable()
    {
        var backing = new FakeMemory(0x10000);
        var queriedRanges = new List<(uint Address, uint Bytes)>();
        var memory = new DisplayClassMemory(
            backing,
            (address, byteCount) =>
            {
                queriedRanges.Add((address, byteCount));
                return false;
            });
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;

        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane1, 0x40));

        // A generated 16-pixel, two-row image occupies its eight-byte POS/CTL
        // prefix plus four bytes per row.  The sidecar is queried for that
        // complete span, while the public ExtSprite envelope remains public
        // memory and is not incorrectly subjected to display DMA admission.
        Assert.Equal(0u, core.AllocSpriteDataA(bitMap, 0));
        var queried = Assert.Single(queriedRanges);
        Assert.Equal(0x1010u, queried.Address);
        Assert.Equal(16u, queried.Bytes);
        Assert.Collection(
            allocator.Freed,
            allocation =>
            {
                Assert.Equal(0x1010u, allocation.Address);
                Assert.Equal(16u, allocation.Bytes);
                Assert.Equal(GraphicsMemoryClass.Chip, allocation.MemoryClass);
            },
            allocation =>
            {
                Assert.Equal(0x1000u, allocation.Address);
                Assert.Equal((uint)GraphicsLayouts.ExtSpriteSize, allocation.Bytes);
                Assert.Equal(GraphicsMemoryClass.Public, allocation.MemoryClass);
            });
    }

