    [Fact]
    public void ExtendedSpriteAllocationPadsNarrowBitmapsAndHonorsReplicationFactors()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x410;
        const uint tags = 0x600;

        // One byte per row describes an eight-pixel source.  The native
        // sprite envelope is still sixteen pixels wide, so the right half
        // must remain transparent for a 1:1 conversion.
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 1));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 4));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane0 + 1, 0x00));
        Assert.True(memory.TryWriteByte(plane0 + 2, 0x80));
        Assert.True(memory.TryWriteByte(plane0 + 3, 0x00));
        Assert.True(memory.TryWriteByte(plane1, 0x00));
        Assert.True(memory.TryWriteByte(plane1 + 1, 0x40));
        Assert.True(memory.TryWriteByte(plane1 + 2, 0x00));
        Assert.True(memory.TryWriteByte(plane1 + 3, 0x40));

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAOutputHeight));
        Assert.True(memory.TryWriteLong(tags + 4, 2));
        Assert.True(memory.TryWriteLong(tags + 8, 0));
        Assert.True(memory.TryWriteLong(tags + 12, 0));
        var state = new M68kCpuState { A = { [1] = tags, [2] = bitMap } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var oneToOne = state.D[0];
        var oneToOneImage = ReadLong(memory, oneToOne + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal((ushort)2, ReadWord(memory, oneToOne + (uint)GraphicsLayouts.SimpleSpriteHeight));
        Assert.Equal((ushort)0, ReadWord(memory, oneToOneImage + 4));
        Assert.Equal((ushort)0x8000, ReadWord(memory, oneToOneImage + 6));
        Assert.Equal((ushort)0x4000, ReadWord(memory, oneToOneImage + 8));
        Assert.Equal((ushort)0, ReadWord(memory, oneToOneImage + 10));
        FreeExtendedSprite(adapter, oneToOne);

        // Positive replication maps each output coordinate back to the
        // source with a right shift.  Two source pixels are therefore
        // repeated horizontally and vertically while the source remains
        // safely bounded by the requested output height.
        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAXReplication));
        Assert.True(memory.TryWriteLong(tags + 4, 1));
        Assert.True(memory.TryWriteLong(tags + 8, GraphicsLayouts.SpriteAYReplication));
        Assert.True(memory.TryWriteLong(tags + 12, 1));
        Assert.True(memory.TryWriteLong(tags + 16, GraphicsLayouts.SpriteAOutputHeight));
        Assert.True(memory.TryWriteLong(tags + 20, 4));
        Assert.True(memory.TryWriteLong(tags + 24, 0));
        Assert.True(memory.TryWriteLong(tags + 28, 0));

        state.A[1] = tags;
        state.D[0] = 0xDEAD_BEEFu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var replicated = state.D[0];
        var replicatedImage = ReadLong(memory, replicated + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal((ushort)4, ReadWord(memory, replicated + (uint)GraphicsLayouts.SimpleSpriteHeight));
        Assert.Equal((ushort)0, ReadWord(memory, replicatedImage + 4));
        Assert.Equal((ushort)0xC000, ReadWord(memory, replicatedImage + 6));
        Assert.Equal((ushort)0, ReadWord(memory, replicatedImage + 8));
        Assert.Equal((ushort)0xC000, ReadWord(memory, replicatedImage + 10));
        Assert.Equal((ushort)0x3000, ReadWord(memory, replicatedImage + 12));
        Assert.Equal((ushort)0, ReadWord(memory, replicatedImage + 14));
        Assert.Equal((ushort)0x3000, ReadWord(memory, replicatedImage + 16));
        Assert.Equal((ushort)0, ReadWord(memory, replicatedImage + 18));
        FreeExtendedSprite(adapter, replicated);

        // Negative replication samples every second source pixel/row.  The
        // same bounded mapper is used for both axes, so the first and third
        // source rows become the two requested output rows here.
        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAXReplication));
        Assert.True(memory.TryWriteLong(tags + 4, unchecked((uint)-1)));
        Assert.True(memory.TryWriteLong(tags + 8, GraphicsLayouts.SpriteAYReplication));
        Assert.True(memory.TryWriteLong(tags + 12, unchecked((uint)-1)));
        Assert.True(memory.TryWriteLong(tags + 16, GraphicsLayouts.SpriteAOutputHeight));
        Assert.True(memory.TryWriteLong(tags + 20, 2));
        Assert.True(memory.TryWriteLong(tags + 24, 0));
        Assert.True(memory.TryWriteLong(tags + 28, 0));

        state.A[1] = tags;
        state.D[0] = 0xCAFE_BABEu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var subsampled = state.D[0];
        var subsampledImage = ReadLong(memory, subsampled + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal((ushort)0, ReadWord(memory, subsampledImage + 4));
        Assert.Equal((ushort)0x8000, ReadWord(memory, subsampledImage + 6));
        Assert.Equal((ushort)0, ReadWord(memory, subsampledImage + 8));
        Assert.Equal((ushort)0x8000, ReadWord(memory, subsampledImage + 10));
        FreeExtendedSprite(adapter, subsampled);
    }

    [Fact]
    public void ExtendedSpriteAllocationSupportsWideHardwareFormsAndAttachedMarkers()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x420;
        const uint plane2 = 0x440;
        const uint plane3 = 0x460;
        const uint tags = 0x600;

        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 8));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 4));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 8, plane2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 12, plane3));

        // The low sprite plane has pixels at x=0, x=31 and x=63.  This
        // distinguishes the three 16-pixel words in a 64-pixel conversion.
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane0 + 3u, 0x01));
        Assert.True(memory.TryWriteByte(plane0 + 7u, 0x01));

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAWidth));
        Assert.True(memory.TryWriteLong(tags + 4u, 32));
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        var state = new M68kCpuState { A = { [1] = tags, [2] = bitMap } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var wide32 = state.D[0];
        Assert.NotEqual(0u, wide32);
        Assert.Equal((ushort)2, ReadWord(memory, wide32 + (uint)GraphicsLayouts.ExtSpriteWordWidth));
        var wide32Image = ReadLong(memory, wide32 + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal((ushort)0, ReadWord(memory, wide32Image + 4u));
        Assert.Equal((ushort)0x8000, ReadWord(memory, wide32Image + 6u));
        Assert.Equal((ushort)0, ReadWord(memory, wide32Image + 8u));
        Assert.Equal((ushort)1, ReadWord(memory, wide32Image + 10u));
        FreeExtendedSprite(adapter, wide32);

        // Attached conversion consumes planes 3/4 and publishes the V39
        // compatibility attach markers without changing the converted bits.
        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAWidth));
        Assert.True(memory.TryWriteLong(tags + 4u, 64));
        Assert.True(memory.TryWriteLong(tags + 8u, GraphicsLayouts.SpriteAAttached));
        Assert.True(memory.TryWriteLong(tags + 12u, 1));
        Assert.True(memory.TryWriteLong(tags + 16u, 0));
        state.A[1] = tags;
        state.D[0] = 0xDEAD_BEEFu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var wide64Attached = state.D[0];
        Assert.NotEqual(0u, wide64Attached);
        Assert.Equal((ushort)4, ReadWord(memory, wide64Attached + (uint)GraphicsLayouts.ExtSpriteWordWidth));
        Assert.Equal(GraphicsLayouts.SpriteAttachedFlag,
            ReadWord(memory, wide64Attached + (uint)GraphicsLayouts.ExtSpriteFlags));
        var wide64Image = ReadLong(memory, wide64Attached + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal(GraphicsLayouts.SpriteAttachedFlag, ReadWord(memory, wide64Image + 2u));
        Assert.Equal(GraphicsLayouts.SpriteAttachedFlag, ReadWord(memory, wide64Image + 4u));
        Assert.Equal(GraphicsLayouts.SpriteAttachedFlag, ReadWord(memory, wide64Image + 8u));
        FreeExtendedSprite(adapter, wide64Attached);
    }

    [Fact]
    public void ExtendedSpriteAllocationConvertsTheLegacyOldDataFormat()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint oldData = 0x200;
        const uint tags = 0x600;

        // SPRITEA_OldDataFormat addresses the two packed plane words per row
        // four bytes into the supplied pointer.  Width trims the source words
        // before the fixed 16-pixel sprite envelope is published.
        Assert.True(memory.TryWriteWord(oldData + 4u, 0xF0F0));
        Assert.True(memory.TryWriteWord(oldData + 6u, 0x0AA0));
        Assert.True(memory.TryWriteWord(oldData + 8u, 0x00F0));
        Assert.True(memory.TryWriteWord(oldData + 10u, 0xC300));
        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAWidth));
        Assert.True(memory.TryWriteLong(tags + 4u, 8));
        Assert.True(memory.TryWriteLong(tags + 8u, GraphicsLayouts.SpriteAOutputHeight));
        Assert.True(memory.TryWriteLong(tags + 12u, 2));
        Assert.True(memory.TryWriteLong(tags + 16u, GraphicsLayouts.SpriteAOldDataFormat));
        Assert.True(memory.TryWriteLong(tags + 20u, 1));
        Assert.True(memory.TryWriteLong(tags + 24u, 0));
        Assert.True(memory.TryWriteLong(tags + 28u, 0));

        var state = new M68kCpuState { A = { [1] = tags, [2] = oldData } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        var extSprite = state.D[0];
        Assert.NotEqual(0u, extSprite);
        Assert.Equal((ushort)2, ReadWord(memory, extSprite + (uint)GraphicsLayouts.SimpleSpriteHeight));
        Assert.Equal((ushort)1, ReadWord(memory, extSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth));

        var image = ReadLong(memory, extSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData);
        Assert.Equal((ushort)0x0A00, ReadWord(memory, image + 4u));
        Assert.Equal((ushort)0xF000, ReadWord(memory, image + 6u));
        Assert.Equal((ushort)0xC300, ReadWord(memory, image + 8u));
        Assert.Equal((ushort)0, ReadWord(memory, image + 10u));

        FreeExtendedSprite(adapter, extSprite);
    }

    [Fact]
    public void ExtendedSpriteOldDataFormatRejectsMissingHeightAndTruncatedRows()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint oldData = 0x200;
        const uint tags = 0x600;

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAOldDataFormat));
        Assert.True(memory.TryWriteLong(tags + 4u, 1));
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        Assert.True(memory.TryWriteLong(tags + 12u, 0));
        Assert.Equal(0u, core.AllocSpriteDataA(oldData, tags));
        Assert.Empty(allocator.Freed);

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.SpriteAOutputHeight));
        Assert.True(memory.TryWriteLong(tags + 4u, 2));
        Assert.True(memory.TryWriteLong(tags + 8u, GraphicsLayouts.SpriteAOldDataFormat));
        Assert.True(memory.TryWriteLong(tags + 12u, 1));
        Assert.True(memory.TryWriteLong(tags + 16u, 0));
        Assert.True(memory.TryWriteLong(tags + 20u, 0));
        Assert.Equal(0u, core.AllocSpriteDataA(0xFFFC, tags));
        Assert.Empty(allocator.Freed);
    }

    [Fact]
    public void ExtendedSpriteGetAndChangeHonorTagsAndRejectUnsupportedForms()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;
        const uint tags = 0x600;

        WritePlanarSpriteSource(memory, bitMap, plane0, plane1);
        var first = AllocateExtendedSprite(adapter, bitMap);
        var second = AllocateExtendedSprite(adapter, bitMap);

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.GsTagSpriteNum));
        Assert.True(memory.TryWriteLong(tags + 4, 3));
        Assert.True(memory.TryWriteLong(tags + 8, 0));
        Assert.True(memory.TryWriteLong(tags + 12, 0));

        var state = new M68kCpuState { A = { [0] = first, [1] = tags }, D = { [0] = 0xCAFE_BABEu } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetExtSpriteA));
        Assert.Equal(3u, state.D[0]);
        Assert.Equal((ushort)3, ReadWord(memory, first + (uint)GraphicsLayouts.SimpleSpriteNum));

        state.A[0] = 0;
        state.A[1] = first;
        state.A[2] = second;
        state.A[3] = 0;
        state.D[0] = 0x1234;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeExtSpriteA));
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(
            ReadLong(memory, second + (uint)GraphicsLayouts.SimpleSpritePosCtlData),
            ReadLong(memory, first + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal(
            ReadWord(memory, second + (uint)GraphicsLayouts.SimpleSpriteHeight),
            ReadWord(memory, first + (uint)GraphicsLayouts.SimpleSpriteHeight));

        // The bounded portable form intentionally rejects replication and
        // software/scan-doubled display requests instead of guessing.
        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.GsTagSoftSprite));
        Assert.True(memory.TryWriteLong(tags + 4, 1));
        Assert.True(memory.TryWriteLong(tags + 8, 0));
        state.A[0] = first;
        state.A[1] = tags;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetExtSpriteA));
        Assert.Equal(0xFFFF_FFFFu, state.D[0]);

        state.A[0] = first;
        state.A[1] = second;
        state.A[2] = 0;
        state.A[3] = tags;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ChangeExtSpriteA));
        Assert.Equal(0u, state.D[0]);

        FreeExtendedSprite(adapter, first);
        FreeExtendedSprite(adapter, second);
        Assert.Equal(4, allocator.Freed.Count);
    }

    [Fact]
    public void ExtendedSpriteGetWritesUnassignedNumberWhenTheValidPoolRequestFails()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(memory, new BitmapAllocator(), new FakeBlitter(), new FakeDisplay());
        const uint extSprite = 0x200;

        Assert.True(memory.TryWriteWord(
            extSprite + (uint)GraphicsLayouts.SimpleSpriteNum,
            0x1234));

        // Exhaust every hardware sprite through the same registry used by
        // GetExtSpriteA.  The ExtSprite envelope itself is still valid, so
        // this is an allocation failure rather than a provider/malformed
        // request handoff.
        for (short sprite = 0; sprite < 8; sprite++)
            Assert.Equal(sprite, core.GetSprite(extSprite, sprite));

        Assert.Equal(-1, core.GetExtSpriteA(extSprite, 0));
        Assert.Equal(
            ushort.MaxValue,
            ReadWord(memory, extSprite + (uint)GraphicsLayouts.SimpleSpriteNum));

        for (short sprite = 0; sprite < 8; sprite++)
            Assert.True(core.FreeSprite(sprite));
    }

    [Fact]
    public void ExtendedSpriteGetRestoresBothUnassignedNumbersAfterARejectedPairWrite()
    {
        var backing = new FakeMemory(0x1000);
        const uint first = 0x200;
        const uint second = 0x300;
        const uint tags = 0x600;

        Assert.True(backing.TryWriteWord(
            first + (uint)GraphicsLayouts.SimpleSpriteNum,
            0x1111));
        Assert.True(backing.TryWriteWord(
            second + (uint)GraphicsLayouts.SimpleSpriteNum,
            0x2222));
        Assert.True(backing.TryWriteLong(tags, GraphicsLayouts.GsTagAttached));
        Assert.True(backing.TryWriteLong(tags + 4u, second));
        Assert.True(backing.TryWriteLong(tags + 8u, 0));

        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        for (short sprite = 0; sprite < 8; sprite++)
            Assert.Equal(sprite, core.GetSprite(first, sprite));

        Assert.True(backing.TryWriteWord(
            first + (uint)GraphicsLayouts.SimpleSpriteNum,
            0x1111));
        Assert.True(backing.TryWriteWord(
            second + (uint)GraphicsLayouts.SimpleSpriteNum,
            0x2222));

        // The first number publishes successfully; reject the first byte of
        // the second number.  The failed pair publication must restore both
        // caller-owned values even though the allocation pool is exhausted.
        memory.FailOnNextByteWrite(3);
        Assert.Equal(-1, core.GetExtSpriteA(first, tags));
        Assert.Equal(
            (ushort)0x1111,
            ReadWord(backing, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(
            (ushort)0x2222,
            ReadWord(backing, second + (uint)GraphicsLayouts.SimpleSpriteNum));

        for (short sprite = 0; sprite < 8; sprite++)
            Assert.True(core.FreeSprite(sprite));

        // The restored envelopes remain retryable and the next pair request
        // publishes the normal 0/1 attachment numbers.
        Assert.Equal(0, core.GetExtSpriteA(first, tags));
        Assert.Equal(
            (ushort)0,
            ReadWord(backing, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(
            (ushort)1,
            ReadWord(backing, second + (uint)GraphicsLayouts.SimpleSpriteNum));
    }

    [Fact]
    public void ExtendedSpriteGetAllocatesAttachedPairAndPublishesOddSpriteMarker()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;
        const uint tags = 0x600;

        WritePlanarSpriteSource(memory, bitMap, plane0, plane1);
        var first = AllocateExtendedSprite(adapter, bitMap);
        var second = AllocateExtendedSprite(adapter, bitMap);
        var secondImage = ReadLong(memory, second + (uint)GraphicsLayouts.SimpleSpritePosCtlData);

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.GsTagAttached));
        Assert.True(memory.TryWriteLong(tags + 4u, second));
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        var state = new M68kCpuState
        {
            A = { [0] = first, [1] = tags },
            D = { [0] = 0xDEAD_BEEFu }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetExtSpriteA));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, ReadWord(memory, second + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(
            GraphicsLayouts.SpriteAttachedFlag,
            (ushort)(ReadWord(memory, second + (uint)GraphicsLayouts.ExtSpriteFlags) &
                GraphicsLayouts.SpriteAttachedFlag));
        Assert.Equal(
            GraphicsLayouts.SpriteAttachedFlag,
            (ushort)(ReadWord(memory, secondImage + 2u) & GraphicsLayouts.SpriteAttachedFlag));

        // A second request for the same pair fails without clearing either
        // public number or consuming a different pair.
        Assert.True(memory.TryWriteLong(tags + 8u, GraphicsLayouts.GsTagSpriteNum));
        Assert.True(memory.TryWriteLong(tags + 12u, 0));
        Assert.True(memory.TryWriteLong(tags + 16u, 0));
        state.D[0] = 0x1357_9BDFu;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetExtSpriteA));
        Assert.Equal(0xFFFF_FFFFu, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, ReadWord(memory, second + (uint)GraphicsLayouts.SimpleSpriteNum));

        FreeSpriteSlot(adapter, 0);
        FreeSpriteSlot(adapter, 1);
        FreeExtendedSprite(adapter, first);
        FreeExtendedSprite(adapter, second);
    }

    [Fact]
    public void ExtendedSpriteGetRejectsOverlappingAttachedEnvelopeWithoutReservation()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;
        const uint tags = 0x600;

        WritePlanarSpriteSource(memory, bitMap, plane0, plane1);
        var first = AllocateExtendedSprite(adapter, bitMap);
        var second = AllocateExtendedSprite(adapter, bitMap);

        Assert.True(memory.TryWriteLong(tags, GraphicsLayouts.GsTagAttached));
        Assert.True(memory.TryWriteLong(tags + 4u, first + 2u));
        Assert.True(memory.TryWriteLong(tags + 8u, 0));
        Assert.False(GraphicsSpriteOperations.IsValidGetExtSpriteRequest(memory, first, tags));
        var state = new M68kCpuState
        {
            A = { [0] = first, [1] = tags },
            D = { [0] = 0xA5A5_5A5Au }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetExtSpriteA));
        Assert.Equal(uint.MaxValue, state.D[0]);
        Assert.Equal(ushort.MaxValue, ReadWord(memory, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(ushort.MaxValue, ReadWord(memory, second + (uint)GraphicsLayouts.SimpleSpriteNum));

        // A non-overlapping second envelope is still eligible for the pair
        // allocation, proving the malformed request did not consume a pair.
        Assert.True(memory.TryWriteLong(tags + 4u, second));
        state.D[0] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetExtSpriteA));
        Assert.Equal((uint)0, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, ReadWord(memory, second + (uint)GraphicsLayouts.SimpleSpriteNum));

        FreeSpriteSlot(adapter, 0);
        FreeSpriteSlot(adapter, 1);
        FreeExtendedSprite(adapter, first);
        FreeExtendedSprite(adapter, second);
    }

    [Fact]
    public void ExtendedSpriteGetRestoresBothEnvelopesWhenAttachedPublicationFailsLate()
    {
        var backing = new FakeMemory(0x1000);
        const uint first = 0x200;
        const uint second = 0x300;
        const uint tags = 0x600;

        Assert.True(backing.TryWriteLong(first + (uint)GraphicsLayouts.SimpleSpritePosCtlData, 0));
        Assert.True(backing.TryWriteWord(first + (uint)GraphicsLayouts.SimpleSpriteNum, 0x1111));
        Assert.True(backing.TryWriteLong(second + (uint)GraphicsLayouts.SimpleSpritePosCtlData, 0));
        Assert.True(backing.TryWriteWord(second + (uint)GraphicsLayouts.SimpleSpriteNum, 0x2222));
        Assert.True(backing.TryWriteWord(second + (uint)GraphicsLayouts.ExtSpriteFlags, 0x0040));
        Assert.True(backing.TryWriteLong(tags, GraphicsLayouts.GsTagAttached));
        Assert.True(backing.TryWriteLong(tags + 4u, second));
        Assert.True(backing.TryWriteLong(tags + 8u, 0));

        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        // The first and second numbers consume four byte writes; reject the
        // first byte of the attached flags publication so rollback must
        // restore both envelopes before the call returns.
        memory.FailOnNextByteWrite(5);

        Assert.Equal(-1, core.GetExtSpriteA(first, tags));
        Assert.Equal((ushort)0x1111, ReadWord(backing, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)0x2222, ReadWord(backing, second + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)0x0040, ReadWord(backing, second + (uint)GraphicsLayouts.ExtSpriteFlags));

        // The failed transaction must also release the reserved pair.
        Assert.Equal(0, core.GetExtSpriteA(first, tags));
        Assert.Equal((ushort)0, ReadWord(backing, first + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)1, ReadWord(backing, second + (uint)GraphicsLayouts.SimpleSpriteNum));
    }

    [Fact]
    public void ExtendedSpriteChangeRestoresThePublicEnvelopeOnALateFieldFailure()
    {
        var backing = new FakeMemory(0x1000);
        const uint oldSprite = 0x200;
        const uint newSprite = 0x300;
        const uint oldImage = 0x600;
        const uint newImage = 0x700;

        Assert.True(backing.TryWriteLong(
            oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            oldImage));
        Assert.True(backing.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            5));
        Assert.True(backing.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.SimpleSpriteX,
            6));
        Assert.True(backing.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.SimpleSpriteY,
            7));
        Assert.True(backing.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.SimpleSpriteNum,
            8));
        Assert.True(backing.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth,
            2));
        Assert.True(backing.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.ExtSpriteFlags,
            9));

        Assert.True(backing.TryWriteLong(
            newSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            newImage));
        Assert.True(backing.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            2));
        Assert.True(backing.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.SimpleSpriteX,
            10));
        Assert.True(backing.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.SimpleSpriteY,
            11));
        Assert.True(backing.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.SimpleSpriteNum,
            12));
        Assert.True(backing.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth,
            1));
        Assert.True(backing.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.ExtSpriteFlags,
            13));
        for (var offset = 0; offset < 16; offset++)
            Assert.True(backing.TryWriteByte(newImage + (uint)offset, (byte)(offset + 1)));

        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        // The ExtSprite publication is one long followed by six words.
        memory.FailOnNextByteWrite(16);

        Assert.False(core.ChangeExtSpriteA(0, oldSprite, newSprite, 0));
        Assert.Equal(oldImage, ReadLong(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal((ushort)5, ReadWord(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpriteHeight));
        Assert.Equal((ushort)6, ReadWord(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)7, ReadWord(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpriteY));
        Assert.Equal((ushort)8, ReadWord(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal((ushort)2, ReadWord(backing, oldSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth));
        Assert.Equal((ushort)9, ReadWord(backing, oldSprite + (uint)GraphicsLayouts.ExtSpriteFlags));
    }

    [Fact]
    public void ExtendedSpriteChangeRequiresTheCompleteImageSpanToBeDisplayDmaAddressable()
    {
        var backing = new FakeMemory(0x2000);
        var queriedRanges = new List<(uint Address, uint Bytes)>();
        var allowDma = false;
        var memory = new DisplayClassMemory(
            backing,
            (address, byteCount) =>
            {
                queriedRanges.Add((address, byteCount));
                return allowDma && address == 0x700u && byteCount == 16u;
            });
        var core = CreateCore(memory);
        const uint oldSprite = 0x200;
        const uint newSprite = 0x300;
        const uint oldImage = 0x600;
        const uint newImage = 0x700;

        Assert.True(memory.TryWriteLong(
            oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            oldImage));
        Assert.True(memory.TryWriteWord(
            oldSprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            5));
        Assert.True(memory.TryWriteWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteX, 6));
        Assert.True(memory.TryWriteWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteY, 7));
        Assert.True(memory.TryWriteWord(oldSprite + (uint)GraphicsLayouts.SimpleSpriteNum, 2));
        Assert.True(memory.TryWriteWord(oldSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth, 1));
        Assert.True(memory.TryWriteWord(oldSprite + (uint)GraphicsLayouts.ExtSpriteFlags, 0));

        Assert.True(memory.TryWriteLong(
            newSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData,
            newImage));
        Assert.True(memory.TryWriteWord(
            newSprite + (uint)GraphicsLayouts.SimpleSpriteHeight,
            2));
        Assert.True(memory.TryWriteWord(newSprite + (uint)GraphicsLayouts.SimpleSpriteX, 10));
        Assert.True(memory.TryWriteWord(newSprite + (uint)GraphicsLayouts.SimpleSpriteY, 11));
        Assert.True(memory.TryWriteWord(newSprite + (uint)GraphicsLayouts.SimpleSpriteNum, 3));
        Assert.True(memory.TryWriteWord(newSprite + (uint)GraphicsLayouts.ExtSpriteWordWidth, 1));
        Assert.True(memory.TryWriteWord(newSprite + (uint)GraphicsLayouts.ExtSpriteFlags, 0));
        for (var offset = 0; offset < 16; offset++)
            Assert.True(memory.TryWriteByte(newImage + (uint)offset, (byte)(offset + 1)));

        Assert.False(core.ChangeExtSpriteA(0, oldSprite, newSprite, 0));
        Assert.Equal((newImage, 16u), Assert.Single(queriedRanges));
        Assert.Equal(oldImage, ReadLong(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));

        // A native overlay must be able to claim a non-DMA image without the
        // portable adapter consuming D0 or the caller's frame metadata.
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = oldSprite, [2] = newSprite, [3] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 91,
            ProgramCounter = 0x0012_40B1
        };
        Assert.False(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.ChangeExtSpriteA,
            nativeOverlay: true));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(91, state.Cycles);
        Assert.Equal(0x0012_40B1u, state.ProgramCounter);
        Assert.Equal(oldImage, ReadLong(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));

        allowDma = true;
        Assert.True(core.ChangeExtSpriteA(0, oldSprite, newSprite, 0));
        Assert.Equal(newImage, ReadLong(backing, oldSprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal(3, queriedRanges.Count);
        Assert.All(queriedRanges, range => Assert.Equal((newImage, 16u), range));
    }

    [Fact]
    public void ExtendedSpriteAllocationRejectsMalformedBitmapAndTagSpansWithoutLeaking()
    {
        var memory = new FakeMemory(0x10000);
        var allocator = new BitmapAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitMap = 0x200;
        const uint plane0 = 0x400;
        const uint plane1 = 0x404;

        WritePlanarSpriteSource(memory, bitMap, plane0, plane1);
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        var state = new M68kCpuState { A = { [1] = 0, [2] = bitMap } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.Equal(0u, state.D[0]);
        Assert.Empty(allocator.Freed);

        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        const uint truncatedTags = 0xFFFC;
        state.A[1] = truncatedTags;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.Equal(0u, state.D[0]);
        Assert.Empty(allocator.Freed);

        // Widths outside the native 16/32/64-pixel hardware forms are
        // rejected before either allocator call.
        const uint widthTags = 0x700;
        Assert.True(memory.TryWriteLong(widthTags, GraphicsLayouts.SpriteAWidth));
        Assert.True(memory.TryWriteLong(widthTags + 4, 48));
        Assert.True(memory.TryWriteLong(widthTags + 8, 0));
        state.A[1] = widthTags;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.Equal(0u, state.D[0]);
        Assert.Empty(allocator.Freed);

        // Replication factors outside the documented -2..2 range are
        // rejected before allocating either the public envelope or CHIP image.
        const uint replicationTags = 0x780;
        Assert.True(memory.TryWriteLong(replicationTags, GraphicsLayouts.SpriteAXReplication));
        Assert.True(memory.TryWriteLong(replicationTags + 4, 3));
        Assert.True(memory.TryWriteLong(replicationTags + 8, 0));
        Assert.True(memory.TryWriteLong(replicationTags + 12, 0));
        state.A[1] = replicationTags;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.Equal(0u, state.D[0]);
        Assert.Empty(allocator.Freed);
    }

    private static uint AllocateExtendedSprite(
        CopperStartGraphicsRegisterAdapter adapter,
        uint bitMap)
    {
        var state = new M68kCpuState { A = { [1] = 0, [2] = bitMap } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocSpriteDataA));
        Assert.NotEqual(0u, state.D[0]);
        return state.D[0];
    }

    private static void FreeExtendedSprite(
        CopperStartGraphicsRegisterAdapter adapter,
        uint extSprite)
    {
        var state = new M68kCpuState { A = { [2] = extSprite } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeSpriteData));
        Assert.Equal(0u, state.D[0]);
    }

    private static void FreeSpriteSlot(
        CopperStartGraphicsRegisterAdapter adapter,
        short sprite)
    {
        var state = new M68kCpuState { D = { [0] = unchecked((uint)(ushort)sprite) } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeSprite));
        Assert.Equal(0u, state.D[0]);
    }

    private static void WritePlanarSpriteSource(
        FakeMemory memory,
        uint bitMap,
        uint plane0,
        uint plane1)
    {
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
        Assert.True(memory.TryWriteByte(plane0, 0x80));
        Assert.True(memory.TryWriteByte(plane1, 0x40));
    }

    [Fact]
    public void InitGelsLinksSentinelsPreservesBoundsAndClearsBoundaryCollisionVector()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint head = 0x100;
        const uint tail = 0x180;
        const uint gelsInfo = 0x240;
        const uint collisionTable = 0x300;

        Assert.True(memory.TryWriteByte(gelsInfo + (uint)GraphicsLayouts.GelsInfoSpriteReserved, 0x03));
        Assert.True(memory.TryWriteWord(gelsInfo + (uint)GraphicsLayouts.GelsInfoLeftmost, 1));
        Assert.True(memory.TryWriteWord(gelsInfo + (uint)GraphicsLayouts.GelsInfoRightmost, 319));
        Assert.True(memory.TryWriteWord(gelsInfo + (uint)GraphicsLayouts.GelsInfoTopmost, 1));
        Assert.True(memory.TryWriteWord(gelsInfo + (uint)GraphicsLayouts.GelsInfoBottommost, 199));
        Assert.True(memory.TryWriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            collisionTable));
        Assert.True(memory.TryWriteLong(collisionTable, 0x1234_5678));
        Assert.True(memory.TryWriteByte(head, 0xAA));
        Assert.True(memory.TryWriteByte(tail, 0xBB));

        var state = new M68kCpuState { A = { [0] = head, [1] = tail, [2] = gelsInfo }, D = { [0] = 0xFFFF } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitGels));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(tail, ReadLong(memory, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, ReadLong(memory, head + (uint)GraphicsLayouts.VSpriteClearPath));
        Assert.Equal(head, ReadLong(memory, tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, ReadLong(memory, tail + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal((ushort)0x8000, ReadWord(memory, head + (uint)GraphicsLayouts.VSpriteOldY));
        Assert.Equal((ushort)0x8000, ReadWord(memory, head + (uint)GraphicsLayouts.VSpriteOldX));
        Assert.Equal((ushort)0x8000, ReadWord(memory, head + (uint)GraphicsLayouts.VSpriteY));
        Assert.Equal((ushort)0x8000, ReadWord(memory, head + (uint)GraphicsLayouts.VSpriteX));
        Assert.Equal((ushort)0x7FFF, ReadWord(memory, tail + (uint)GraphicsLayouts.VSpriteOldY));
        Assert.Equal((ushort)0x7FFF, ReadWord(memory, tail + (uint)GraphicsLayouts.VSpriteOldX));
        Assert.Equal((ushort)0x7FFF, ReadWord(memory, tail + (uint)GraphicsLayouts.VSpriteX));
        Assert.Equal(head, ReadLong(memory, gelsInfo + (uint)GraphicsLayouts.GelsInfoHead));
        Assert.Equal(tail, ReadLong(memory, gelsInfo + (uint)GraphicsLayouts.GelsInfoTail));
        Assert.Equal((byte)0x03, ReadByte(memory, gelsInfo + (uint)GraphicsLayouts.GelsInfoSpriteReserved));
        Assert.Equal((ushort)319, ReadWord(memory, gelsInfo + (uint)GraphicsLayouts.GelsInfoRightmost));
        Assert.Equal(0u, ReadLong(memory, collisionTable));

        state.D[0] = 4;
        state.A[0] = 0x1234_5678;
        state.A[1] = gelsInfo;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetCollision));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0x1234_5678u, ReadLong(memory, collisionTable + 16));

        state.D[0] = 16;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetCollision));
        Assert.Equal(0x1234_5678u, ReadLong(memory, collisionTable + 16));
    }

    [Fact]
    public void InitGelsRestoresSentinelsAndBoundsOnALatePublicationFailure()
    {
        var backing = new FakeMemory(0x2000);
        const uint head = 0x800;
        const uint tail = 0x900;
        const uint gelsInfo = 0xA00;
        const uint collisionTable = 0xB00;

        for (var offset = 0; offset < GraphicsLayouts.VSpriteSize; offset++)
        {
            Assert.True(backing.TryWriteByte(head + (uint)offset, 0xA1));
            Assert.True(backing.TryWriteByte(tail + (uint)offset, 0xB2));
        }

        for (var offset = 0; offset < GraphicsLayouts.GelsInfoSize; offset++)
            Assert.True(backing.TryWriteByte(gelsInfo + (uint)offset, 0xC3));

        for (var offset = 0; offset < 4; offset++)
            Assert.True(backing.TryWriteByte(collisionTable + (uint)offset, 0xD4));
        Assert.True(backing.TryWriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            collisionTable));

        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        // Two 0x3C-byte clears plus 49 bytes of sentinel/bounds publication.
        memory.FailOnNextByteWrite((GraphicsLayouts.VSpriteSize * 2) + 49);

        Assert.False(core.InitGels(head, tail, gelsInfo));
        for (var offset = 0; offset < GraphicsLayouts.VSpriteSize; offset++)
        {
            Assert.Equal((byte)0xA1, ReadByte(backing, head + (uint)offset));
            Assert.Equal((byte)0xB2, ReadByte(backing, tail + (uint)offset));
        }

        for (var offset = 0; offset < GraphicsLayouts.GelsInfoSize; offset++)
        {
            var expected = offset == GraphicsLayouts.GelsInfoCollisionHandler ? (byte)0 : (byte)0xC3;
            if (offset >= GraphicsLayouts.GelsInfoCollisionHandler &&
                offset < GraphicsLayouts.GelsInfoCollisionHandler + 4)
            {
                expected = (byte)((collisionTable >> (8 * (3 - (offset - GraphicsLayouts.GelsInfoCollisionHandler)))) & 0xFF);
            }

            Assert.Equal(expected, ReadByte(backing, gelsInfo + (uint)offset));
        }

        for (var offset = 0; offset < 4; offset++)
            Assert.Equal((byte)0xD4, ReadByte(backing, collisionTable + (uint)offset));
    }

    [Fact]
    public void SetCollisionRestoresTheRoutinePointerOnALateLongWriteFailure()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint gelsInfo = 0x240;
        const uint collisionTable = 0x300;
        const uint head = 0x100;
        const uint tail = 0x180;
        Assert.True(backing.TryWriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            collisionTable));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(backing.TryWriteLong(collisionTable + 16u, 0x1234_5678));

        memory.FailOnNextByteWrite(4);
        Assert.False(core.SetCollision(4, 0xCAFE_BABEu, gelsInfo));
        Assert.Equal(0x1234_5678u, ReadLong(backing, collisionTable + 16u));
    }

    [Fact]
    public void SetCollisionRestoresTheRoutinePointerAfterARejectedRepeatedLongRollback()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new PartialThenRejectLongWriteMemory(backing);
        var core = CreateCore(memory);
        const uint gelsInfo = 0x240;
        const uint collisionTable = 0x300;
        const uint head = 0x100;
        const uint tail = 0x180;
        var entry = collisionTable + 16u;
        memory.PartialLongAddress = entry;

        Assert.True(backing.TryWriteLong(
            gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler,
            collisionTable));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(backing.TryWriteLong(entry, 0x1234_5678));

        Assert.False(core.SetCollision(4, 0xCAFE_BABEu, gelsInfo));
        Assert.Equal(0x1234_5678u, ReadLong(backing, entry));

        memory.PartialLongAddress = null;
        Assert.True(core.SetCollision(4, 0xCAFE_BABEu, gelsInfo));
        Assert.Equal(0xCAFE_BABEu, ReadLong(backing, entry));
    }

    [Fact]
    public void InitMasksBuildsTrueVSpriteCollisionAndBorderMasks()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint sprite = 0x100;
        const uint image = 0x400;
        const uint border = 0x500;
        const uint collision = 0x600;

        Assert.True(memory.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteFlags, GraphicsLayouts.VSpriteFlag));
        Assert.True(memory.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteHeight, 2));
        Assert.True(memory.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteWidth, 1));
        Assert.True(memory.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteDepth, 2));
        Assert.True(memory.TryWriteLong(sprite + (uint)GraphicsLayouts.VSpriteImageData, image));
        Assert.True(memory.TryWriteLong(sprite + (uint)GraphicsLayouts.VSpriteBorderLine, border));
        Assert.True(memory.TryWriteLong(sprite + (uint)GraphicsLayouts.VSpriteCollMask, collision));
        Assert.True(memory.TryWriteWord(image, 0x8000));
        Assert.True(memory.TryWriteWord(image + 2, 0));
        Assert.True(memory.TryWriteWord(image + 4, 0x4000));
        Assert.True(memory.TryWriteWord(image + 6, 0x2000));

        var state = new M68kCpuState { A = { [0] = sprite }, D = { [0] = 0xCAFE } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitMasks));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)0xE000, ReadWord(memory, border));
        Assert.Equal((ushort)0xC000, ReadWord(memory, collision));
        Assert.Equal((ushort)0x2000, ReadWord(memory, collision + 2));

        // The portable foundation does not guess Bob image/shadow layout.
        Assert.True(memory.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteFlags, 0));
        Assert.False(core.InitMasks(sprite));
        Assert.Equal((ushort)0xE000, ReadWord(memory, border));
        Assert.Equal((ushort)0xC000, ReadWord(memory, collision));
    }

    [Fact]
    public void InitMasksRestoresBorderAndCollisionDestinationsOnALateWriteFailure()
    {
        var backing = new FakeMemory(0x1000);
        const uint sprite = 0x100;
        const uint image = 0x400;
        const uint border = 0x500;
        const uint collision = 0x600;

        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteFlags, GraphicsLayouts.VSpriteFlag));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteHeight, 2));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteWidth, 1));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteDepth, 2));
        Assert.True(backing.TryWriteLong(sprite + (uint)GraphicsLayouts.VSpriteImageData, image));
        Assert.True(backing.TryWriteLong(sprite + (uint)GraphicsLayouts.VSpriteBorderLine, border));
        Assert.True(backing.TryWriteLong(sprite + (uint)GraphicsLayouts.VSpriteCollMask, collision));
        Assert.True(backing.TryWriteWord(image, 0x8000));
        Assert.True(backing.TryWriteWord(image + 2u, 0));
        Assert.True(backing.TryWriteWord(image + 4u, 0x4000));
        Assert.True(backing.TryWriteWord(image + 6u, 0x2000));
        Assert.True(backing.TryWriteWord(border, 0xA1B2));
        Assert.True(backing.TryWriteWord(collision, 0xC3D4));
        Assert.True(backing.TryWriteWord(collision + 2u, 0xE5F6));

        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        // One border word and two collision words are six byte writes.
        memory.FailOnNextByteWrite(6);

        Assert.False(core.InitMasks(sprite));
        Assert.Equal((ushort)0xA1B2, ReadWord(backing, border));
        Assert.Equal((ushort)0xC3D4, ReadWord(backing, collision));
        Assert.Equal((ushort)0xE5F6, ReadWord(backing, collision + 2u));
    }

    [Fact]
    public void AddAndRemoveVSpriteMaintainSortedReciprocalGuestLinks()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x80;
        const uint gelsInfo = 0x240;
        const uint head = 0x300;
        const uint tail = 0x340;
        const uint first = 0x400;
        const uint second = 0x440;

        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortGelsInfo, gelsInfo));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(memory.TryWriteWord(first + (uint)GraphicsLayouts.VSpriteY, 10));
        Assert.True(memory.TryWriteWord(first + (uint)GraphicsLayouts.VSpriteX, 20));
        Assert.True(memory.TryWriteWord(second + (uint)GraphicsLayouts.VSpriteY, 10));
        Assert.True(memory.TryWriteWord(second + (uint)GraphicsLayouts.VSpriteX, 30));

        var state = new M68kCpuState { A = { [0] = second, [1] = rastPort }, D = { [0] = 0xFFFF } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AddVSprite));
        state.A[0] = first;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AddVSprite));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(first, ReadLong(memory, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(second, ReadLong(memory, first + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, ReadLong(memory, second + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(first, ReadLong(memory, second + (uint)GraphicsLayouts.VSpritePrev));

        // A linked VSprite cannot be added twice; removal requires reciprocal
        // neighbors and clears the removed guest links.
        state.A[0] = first;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.AddVSprite));
        Assert.True(memory.TryWriteWord(first + (uint)GraphicsLayouts.VSpriteY, 40));
        Assert.True(memory.TryWriteWord(second + (uint)GraphicsLayouts.VSpriteY, 5));
        state.A[1] = rastPort;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SortGList));
        Assert.Equal(second, ReadLong(memory, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(first, ReadLong(memory, second + (uint)GraphicsLayouts.VSpriteNext));

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RemVSprite));
        Assert.Equal(0u, ReadLong(memory, first + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(0u, ReadLong(memory, first + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(second, ReadLong(memory, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, ReadLong(memory, second + (uint)GraphicsLayouts.VSpritePrev));

        state.A[0] = head;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.RemVSprite));
    }

