    [Fact]
    public void AddVSpriteRestoresReciprocalLinksOnALateLongWriteFailure()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x80;
        const uint gelsInfo = 0x240;
        const uint head = 0x300;
        const uint tail = 0x340;
        const uint sprite = 0x400;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
            gelsInfo));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 20));

        // Four reciprocal long writes make up one insertion.  Reject only
        // the last byte so the earlier links must be restored.
        memory.FailOnNextByteWrite(16);
        Assert.False(core.AddVSprite(sprite, rastPort));
        Assert.Equal(tail, ReadLong(backing, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, ReadLong(backing, tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, ReadLong(backing, sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(0u, ReadLong(backing, sprite + (uint)GraphicsLayouts.VSpritePrev));
    }

    [Fact]
    public void AddVSpriteRestoresLinksAfterARejectedRepeatedLongRollback()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new ProbeThenFailLongWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x80;
        const uint gelsInfo = 0x240;
        const uint head = 0x310;
        const uint tail = 0x350;
        const uint sprite = 0x400;
        var spritePrev = sprite + (uint)GraphicsLayouts.VSpritePrev;
        var spriteNext = sprite + (uint)GraphicsLayouts.VSpriteNext;
        memory.ProbeLongAddress = spritePrev;
        memory.FailLongAddress = spriteNext;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
            gelsInfo));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10));
        Assert.True(backing.TryWriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 20));

        Assert.False(core.AddVSprite(sprite, rastPort));
        Assert.Equal(tail, ReadLong(backing, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, ReadLong(backing, tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(0u, ReadLong(backing, spritePrev));
        Assert.Equal(0u, ReadLong(backing, spriteNext));

        memory.FailLongAddress = null;
        memory.ResetProbe();
        Assert.True(core.AddVSprite(sprite, rastPort));
        Assert.Equal(head, ReadLong(backing, spritePrev));
        Assert.Equal(tail, ReadLong(backing, spriteNext));
    }

