    [Fact]
    public void SortGListRestoresTheOriginalOrderOnALateLongWriteFailure()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x80;
        const uint gelsInfo = 0x240;
        const uint head = 0x300;
        const uint tail = 0x340;
        const uint first = 0x400;
        const uint second = 0x440;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
            gelsInfo));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(backing.TryWriteWord(first + (uint)GraphicsLayouts.VSpriteY, 10));
        Assert.True(backing.TryWriteWord(first + (uint)GraphicsLayouts.VSpriteX, 20));
        Assert.True(backing.TryWriteWord(second + (uint)GraphicsLayouts.VSpriteY, 20));
        Assert.True(backing.TryWriteWord(second + (uint)GraphicsLayouts.VSpriteX, 30));
        Assert.True(core.AddVSprite(first, rastPort));
        Assert.True(core.AddVSprite(second, rastPort));

        // Reverse the sort order without changing the existing links.
        Assert.True(backing.TryWriteWord(first + (uint)GraphicsLayouts.VSpriteY, 30));
        Assert.True(backing.TryWriteWord(second + (uint)GraphicsLayouts.VSpriteY, 5));

        // Two nodes require six reciprocal-link long writes.  Reject the
        // final tail publication so the reordered prefix must be restored.
        memory.FailOnNextByteWrite(24);
        Assert.False(core.SortGList(rastPort));
        Assert.Equal(first, ReadLong(backing, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, ReadLong(backing, first + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(second, ReadLong(backing, first + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(first, ReadLong(backing, second + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(tail, ReadLong(backing, second + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(second, ReadLong(backing, tail + (uint)GraphicsLayouts.VSpritePrev));
    }

    [Fact]
    public void AddBobRestoresBobAndVSpriteStateOnALatePublicationFailure()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x80;
        const uint gelsInfo = 0x240;
        const uint head = 0x300;
        const uint tail = 0x340;
        const uint bob = 0x800;
        const uint vSprite = 0x900;

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortGelsInfo,
            gelsInfo));
        Assert.True(core.InitGels(head, tail, gelsInfo));
        Assert.True(backing.TryWriteLong(
            bob + (uint)GraphicsLayouts.BobVSprite,
            vSprite));
        Assert.True(backing.TryWriteWord(
            bob + (uint)GraphicsLayouts.BobFlags,
            GraphicsLayouts.BobFlagWaiting));
        Assert.True(backing.TryWriteWord(
            vSprite + (uint)GraphicsLayouts.VSpriteFlags,
            GraphicsLayouts.VSpriteFlag));
        Assert.True(backing.TryWriteLong(
            vSprite + (uint)GraphicsLayouts.VSpriteVSBob,
