        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteX, 20));

        // Bob flags, VSprite flags, and the owner pointer are eight byte
        // writes. Reject only the final pointer byte.
        memory.FailOnNextByteWrite(8);
        Assert.False(core.AddBob(bob, rastPort));
