            (ushort)GraphicsLayouts.VSpriteFlag,
            ReadWord(backing, vSprite + (uint)GraphicsLayouts.VSpriteFlags));
        Assert.Equal(0u, ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteVSBob));
        Assert.Equal(tail, ReadLong(backing, head + (uint)GraphicsLayouts.VSpriteNext));
    }

