        Assert.True(memory.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteWidth, 1));
        Assert.True(memory.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteHeight, 1));
        Assert.True(memory.TryWriteLong(animOb + (uint)GraphicsLayouts.AnimObX, 640));
        Assert.True(memory.TryWriteLong(animOb + (uint)GraphicsLayouts.AnimObY, 128));
        Assert.True(memory.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 640));
        Assert.True(memory.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 128));
        Assert.True(memory.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObXVel, 64));
        Assert.True(memory.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObYVel, 0));
        Assert.True(memory.TryWriteLong(animKey, 0));

        var state = new M68kCpuState
        {
            A = { [0] = animOb, [1] = animKey, [2] = rastPort },
            D = { [0] = 0xFFFF_FFFF }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AddAnimOb));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(animOb, ReadLong(memory, animKey));
        Assert.Equal((ushort)3, ReadWord(memory, component + (uint)GraphicsLayouts.AnimCompTimer));
        Assert.Equal(vSprite, ReadLong(memory, head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(bob, ReadLong(memory, vSprite + (uint)GraphicsLayouts.VSpriteVSBob));

        state.A[0] = animKey;
        state.A[1] = rastPort;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Animate));
        Assert.Equal((ushort)640, ReadWord(memory, animOb + (uint)GraphicsLayouts.AnimObOldX));
        Assert.Equal((ushort)704, ReadWord(memory, animOb + (uint)GraphicsLayouts.AnimObX));
        Assert.Equal((ushort)12, ReadWord(memory, vSprite + (uint)GraphicsLayouts.VSpriteX));
        Assert.Equal((ushort)3, ReadWord(memory, vSprite + (uint)GraphicsLayouts.VSpriteY));
        Assert.Equal((ushort)2, ReadWord(memory, component + (uint)GraphicsLayouts.AnimCompTimer));

        state.A[0] = bob;
        state.A[1] = rastPort;
        state.A[2] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RemIBob));
        Assert.Equal(0u, ReadLong(memory, vSprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(0u, ReadLong(memory, vSprite + (uint)GraphicsLayouts.VSpriteVSBob));
        Assert.Equal((ushort)0, ReadWord(memory, bob + (uint)GraphicsLayouts.BobFlags));
    }

    [Fact]
    public void AnimateRestoresAnimObStateWhenAdvanceFailsLate()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint animOb = 0x80;
        const uint animKey = 0x40;
        const uint rastPort = 0x20;

        Assert.True(backing.TryWriteLong(animKey, animOb));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObOldX, 0x1111));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObOldY, 0x2222));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 100));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 200));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObXVel, 10));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObYVel, 20));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObXAccel, 1));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObYAccel, 2));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObClock, 7));

        // OldX completes; fail the first byte of OldY and require every
        // previously published AnimOb word to be restored.
        memory.FailOnNextByteWrite(3);
        Assert.False(core.Animate(animKey, rastPort));
        Assert.Equal((ushort)0x1111, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObOldX));
        Assert.Equal((ushort)0x2222, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObOldY));
        Assert.Equal((ushort)100, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObX));
        Assert.Equal((ushort)200, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObY));
        Assert.Equal((ushort)10, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObXVel));
        Assert.Equal((ushort)20, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObYVel));
        Assert.Equal((ushort)7, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObClock));
    }

    [Fact]
    public void AnimateRestoresAdvanceWordsAfterARejectedRepeatedWordRollback()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new ProbeThenPartialWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint animOb = 0x80;
        const uint animKey = 0x40;
        const uint rastPort = 0x20;
        var oldXAddress = animOb + (uint)GraphicsLayouts.AnimObOldX;
        var oldYAddress = animOb + (uint)GraphicsLayouts.AnimObOldY;
        memory.PartialWordAddress = oldXAddress;
        memory.FailWordAddress = oldYAddress;

        Assert.True(backing.TryWriteLong(animKey, animOb));
        Assert.True(backing.TryWriteWord(oldXAddress, 0x1111));
        Assert.True(backing.TryWriteWord(oldYAddress, 0x2222));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 100));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 200));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObXVel, 10));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObYVel, 20));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObXAccel, 1));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObYAccel, 2));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObClock, 7));

        Assert.False(core.Animate(animKey, rastPort));
        Assert.Equal((ushort)0x1111, ReadWord(backing, oldXAddress));
        Assert.Equal((ushort)0x2222, ReadWord(backing, oldYAddress));
        Assert.Equal((ushort)100, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObX));
        Assert.Equal((ushort)200, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObY));

        memory.FailWordAddress = null;
        memory.ResetProbe();
        Assert.True(core.Animate(animKey, rastPort));
        Assert.Equal((ushort)100, ReadWord(backing, oldXAddress));
        Assert.Equal((ushort)200, ReadWord(backing, oldYAddress));
        Assert.Equal((ushort)110, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObX));
        Assert.Equal((ushort)220, ReadWord(backing, animOb + (uint)GraphicsLayouts.AnimObY));
    }

    [Fact]
    public void AnimateRestoresComponentPublicationWhenBobFlagsWriteFailsLate()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint animOb = 0x80;
        const uint animKey = 0x40;
        const uint rastPort = 0x20;
        const uint component = 0x100;
        const uint bob = 0x180;
        const uint vSprite = 0x1C0;

        Assert.True(backing.TryWriteLong(animKey, animOb));
        Assert.True(backing.TryWriteLong(animOb + (uint)GraphicsLayouts.AnimObHeadComp, component));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 640));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 128));
        Assert.True(backing.TryWriteLong(component + (uint)GraphicsLayouts.AnimCompAnimBob, bob));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompTimer, 1));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompTimeSet, 1));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompXTrans, 64));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompYTrans, 64));
        Assert.True(backing.TryWriteLong(bob + (uint)GraphicsLayouts.BobVSprite, vSprite));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteX, 0));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteY, 0));
        Assert.True(backing.TryWriteWord(bob + (uint)GraphicsLayouts.BobFlags, 0));

        // AdvanceAnimOb consumes fourteen byte writes.  The component timer,
        // VSprite X/Y, and Bob flags then consume eight; fail the final Bob
        // flags byte and require the component publication to roll back.
        memory.FailOnNextByteWrite(22);
        Assert.False(core.Animate(animKey, rastPort));
        Assert.Equal((ushort)1, ReadWord(backing, component + (uint)GraphicsLayouts.AnimCompTimer));
        Assert.Equal((ushort)0, ReadWord(backing, vSprite + (uint)GraphicsLayouts.VSpriteX));
        Assert.Equal((ushort)0, ReadWord(backing, vSprite + (uint)GraphicsLayouts.VSpriteY));
        Assert.Equal((ushort)0, ReadWord(backing, bob + (uint)GraphicsLayouts.BobFlags));
    }

    [Fact]
    public void AnimateRestoresComponentWordsAfterARejectedRepeatedTimerRollback()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new ProbeThenPartialWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint animOb = 0x80;
        const uint animKey = 0x40;
        const uint rastPort = 0x20;
        const uint component = 0x100;
        const uint bob = 0x180;
        const uint vSprite = 0x1C0;
        var timerAddress = component + (uint)GraphicsLayouts.AnimCompTimer;
        var xAddress = vSprite + (uint)GraphicsLayouts.VSpriteX;
        memory.PartialWordAddress = timerAddress;
        memory.FailWordAddress = xAddress;

        Assert.True(backing.TryWriteLong(animKey, animOb));
        Assert.True(backing.TryWriteLong(animOb + (uint)GraphicsLayouts.AnimObHeadComp, component));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObX, 640));
        Assert.True(backing.TryWriteWord(animOb + (uint)GraphicsLayouts.AnimObY, 128));
        Assert.True(backing.TryWriteLong(component + (uint)GraphicsLayouts.AnimCompAnimBob, bob));
        Assert.True(backing.TryWriteWord(timerAddress, 1));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompTimeSet, 1));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompXTrans, 64));
        Assert.True(backing.TryWriteWord(component + (uint)GraphicsLayouts.AnimCompYTrans, 64));
        Assert.True(backing.TryWriteLong(bob + (uint)GraphicsLayouts.BobVSprite, vSprite));
        Assert.True(backing.TryWriteWord(xAddress, 0));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteY, 0));
        Assert.True(backing.TryWriteWord(bob + (uint)GraphicsLayouts.BobFlags, 0));

        Assert.False(core.Animate(animKey, rastPort));
        Assert.Equal((ushort)1, ReadWord(backing, timerAddress));
        Assert.Equal((ushort)0, ReadWord(backing, xAddress));
        Assert.Equal((ushort)0, ReadWord(backing, vSprite + (uint)GraphicsLayouts.VSpriteY));
        Assert.Equal((ushort)0, ReadWord(backing, bob + (uint)GraphicsLayouts.BobFlags));

        memory.FailWordAddress = null;
        memory.ResetProbe();
        Assert.True(core.Animate(animKey, rastPort));
        Assert.Equal((ushort)0, ReadWord(backing, timerAddress));
        Assert.Equal((ushort)11, ReadWord(backing, xAddress));
        Assert.Equal((ushort)3, ReadWord(backing, vSprite + (uint)GraphicsLayouts.VSpriteY));
    }

