    [Fact]
    public void InitGMasksRestoresBobOwnerWhenMaskPublicationFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), new FakeBlitter(), new FakeDisplay());
        const uint animOb = 0x80;
        const uint component = 0x100;
        const uint bob = 0x180;
        const uint vSprite = 0x1C0;
        const uint imageData = 0x300;
        const uint borderLine = 0x340;
        const uint collMask = 0x360;

        Assert.True(backing.TryWriteLong(animOb + (uint)GraphicsLayouts.AnimObHeadComp, component));
        Assert.True(backing.TryWriteLong(component + (uint)GraphicsLayouts.AnimCompAnimBob, bob));
        Assert.True(backing.TryWriteLong(bob + (uint)GraphicsLayouts.BobVSprite, vSprite));
        Assert.True(backing.TryWriteLong(vSprite + (uint)GraphicsLayouts.VSpriteVSBob, 0x12345678));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteWidth, 1));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteHeight, 1));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteDepth, 1));
        Assert.True(backing.TryWriteLong(vSprite + (uint)GraphicsLayouts.VSpriteImageData, imageData));
        Assert.True(backing.TryWriteLong(vSprite + (uint)GraphicsLayouts.VSpriteBorderLine, borderLine));
        Assert.True(backing.TryWriteLong(vSprite + (uint)GraphicsLayouts.VSpriteCollMask, collMask));
        Assert.True(backing.TryWriteWord(imageData, 0xA55A));
        Assert.True(backing.TryWriteWord(borderLine, 0x1357));
        Assert.True(backing.TryWriteWord(collMask, 0x2468));

        // The owner long is written first; fail the second byte of the
        // following border word and require both public state and masks to
        // remain unchanged.
        memory.FailOnNextByteWrite(6);
        Assert.False(core.InitGMasks(animOb));
        Assert.Equal(0x12345678u, ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteVSBob));
        Assert.Equal((ushort)0x1357, ReadWord(backing, borderLine));
        Assert.Equal((ushort)0x2468, ReadWord(backing, collMask));
    }

    [Fact]
    public void FreeGBuffersRestoresOwnedPointersWhenLateClearFails()
    {
        var backing = new FakeMemory(0x8000);
        var memory = new FailingByteWriteMemory(backing);
        var allocator = new SteppingAllocator(0x5000);
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint rastPort = 0x80;
        const uint bitMap = 0x100;
        const uint animOb = 0x300;
        const uint component = 0x380;
        const uint bob = 0x400;
        const uint vSprite = 0x440;

        Assert.True(backing.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(backing.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2));
        Assert.True(backing.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1));
        Assert.True(backing.TryWriteLong(animOb + (uint)GraphicsLayouts.AnimObHeadComp, component));
        Assert.True(backing.TryWriteLong(component + (uint)GraphicsLayouts.AnimCompAnimBob, bob));
        Assert.True(backing.TryWriteLong(bob + (uint)GraphicsLayouts.BobVSprite, vSprite));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteWidth, 1));
        Assert.True(backing.TryWriteWord(vSprite + (uint)GraphicsLayouts.VSpriteHeight, 1));

        Assert.True(core.GetGBuffers(animOb, rastPort, 0));
        var save = ReadLong(backing, bob + (uint)GraphicsLayouts.BobSaveBuffer);
        var shadow = ReadLong(backing, bob + (uint)GraphicsLayouts.BobImageShadow);
        var border = ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteBorderLine);
        var mask = ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteCollMask);
        Assert.NotEqual(0u, save);
        Assert.NotEqual(0u, shadow);
        Assert.NotEqual(0u, border);
        Assert.NotEqual(0u, mask);

        // The first SaveBuffer clear completes; fail the second byte of the
        // ImageShadow clear and require all owned pointers to be restored.
        memory.FailOnNextByteWrite(6);
        Assert.False(core.FreeGBuffers(animOb, rastPort, 0));
        Assert.Equal(save, ReadLong(backing, bob + (uint)GraphicsLayouts.BobSaveBuffer));
        Assert.Equal(shadow, ReadLong(backing, bob + (uint)GraphicsLayouts.BobImageShadow));
        Assert.Equal(border, ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteBorderLine));
        Assert.Equal(mask, ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteCollMask));
        Assert.Equal(0, allocator.FreeCount);

        Assert.True(core.FreeGBuffers(animOb, rastPort, 0));
        Assert.Equal(4, allocator.FreeCount);
        Assert.Equal(0u, ReadLong(backing, bob + (uint)GraphicsLayouts.BobSaveBuffer));
        Assert.Equal(0u, ReadLong(backing, bob + (uint)GraphicsLayouts.BobImageShadow));
        Assert.Equal(0u, ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteBorderLine));
        Assert.Equal(0u, ReadLong(backing, vSprite + (uint)GraphicsLayouts.VSpriteCollMask));
    }

