    [Fact]
    public void HostGraphicsServicesForwardsValidatedSpriteProjectionTransitions()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        (uint ViewPort, uint Sprite, short X, short Y)? moved = null;
        (uint ViewPort, uint Sprite, uint Image)? changed = null;
        var services = CreateHostGraphicsServices(
            hostMemory,
            moveSprite: (viewPort, sprite, x, y) => moved = (viewPort, sprite, x, y),
            changeSprite: (viewPort, sprite, image) => changed = (viewPort, sprite, image));
        const uint sprite = 0x2000;
        const uint image = 0x3000;
        hostMemory.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteHeight, 2);
        for (var offset = 0; offset < 16; offset++)
            hostMemory.WriteByte(image + (uint)offset, (byte)(offset + 1));

        var state = new M68kCpuState
        {
            A = { [0] = 0, [1] = sprite },
            D = { [0] = 17, [1] = 29 }
        };
        services.Invoke(state, (int)GraphicsLvo.MoveSprite);
        Assert.Equal((0u, sprite, (short)17, (short)29), moved);
        Assert.Equal(0u, state.D[0]);

        state.A[2] = image;
        services.Invoke(state, (int)GraphicsLvo.ChangeSprite);
        Assert.Equal((0u, sprite, image), changed);
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void HostGraphicsServicesRoutesSoftAndScanDoubledExtSpritesToTheProviderBoundary()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        const uint extSprite = 0x2000;
        const uint replacement = 0x2020;
        const uint tags = 0x2040;
        (uint ExtSprite, uint Tags, short Requested, uint Attached, bool Soft, bool Scan)? getRequest = null;
        (uint ViewPort, uint OldSprite, uint NewSprite, uint Tags, uint Attached, bool Soft, bool Scan)? changeRequest = null;

        hostMemory.WriteLong(tags, GraphicsLayouts.GsTagSoftSprite);
        hostMemory.WriteLong(tags + 4u, 1);
        hostMemory.WriteLong(tags + 8u, 0);
        foreach (var address in new[] { extSprite, replacement })
        {
            hostMemory.WriteLong(address + (uint)GraphicsLayouts.SimpleSpritePosCtlData, 0);
            hostMemory.WriteWord(address + (uint)GraphicsLayouts.SimpleSpriteHeight, 1);
            hostMemory.WriteWord(address + (uint)GraphicsLayouts.SimpleSpriteNum, ushort.MaxValue);
            hostMemory.WriteWord(address + (uint)GraphicsLayouts.ExtSpriteWordWidth, 1);
        }

        var services = CreateHostGraphicsServices(
            hostMemory,
            tryGetExtSprite: (sprite, tagList, requested, attached, soft, scan) =>
            {
                getRequest = (sprite, tagList, requested, attached, soft, scan);
                return (true, 6);
            },
            tryChangeExtSprite: (viewPort, oldSprite, newSprite, tagList, attached, soft, scan) =>
            {
                changeRequest = (viewPort, oldSprite, newSprite, tagList, attached, soft, scan);
                return (true, true);
            });

        var state = new M68kCpuState
        {
            A = { [0] = extSprite, [1] = tags },
            D = { [0] = 0xDEAD_BEEFu }
        };
        services.Invoke(state, (int)GraphicsLvo.GetExtSpriteA);
        Assert.Equal(6u, state.D[0]);
        Assert.Equal((extSprite, tags, (short)-1, 0u, true, false), getRequest);

        state.A[0] = 0;
        state.A[1] = extSprite;
        state.A[2] = replacement;
        state.A[3] = tags;
        state.D[0] = 0x1234_5678u;
        services.Invoke(state, (int)GraphicsLvo.ChangeExtSpriteA);
        Assert.Equal(1u, state.D[0]);
        Assert.Equal((0u, extSprite, replacement, tags, 0u, true, false), changeRequest);
    }

    [Fact]
