    [Fact]
    public void ScalerDivMatchesBitMapScaleExtentArithmeticAndRejectsInvalidFactors()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        Assert.Equal((ushort)200, core.ScalerDiv(100, 2, 1));
        Assert.Equal((ushort)33, core.ScalerDiv(100, 1, 3));
        Assert.Equal((ushort)67, core.ScalerDiv(100, 2, 3));
        Assert.Equal((ushort)1, core.ScalerDiv(1, 1, 2));
        Assert.Equal((ushort)0, core.ScalerDiv(0, 2, 3));
        // The product is wider than UWORD, but the native ScalerDiv result
        // is word-sized and therefore exposes the low word rather than a
        // saturating $FFFF sentinel.
        Assert.Equal((ushort)0x8001, core.ScalerDiv(0x3FFF, 0x3FFF, 1));
        Assert.Equal((ushort)0, core.ScalerDiv(100, 1, 0));
        Assert.Equal((ushort)0, core.ScalerDiv(0x4000, 1, 1));

        var state = new M68kCpuState { D = { [0] = 640, [1] = 3, [2] = 2 } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ScalerDiv));
        Assert.Equal(960u, state.D[0]);

        var wrappingState = new M68kCpuState
        {
            D = { [0] = 0x3FFF, [1] = 0x3FFF, [2] = 1 }
        };
        Assert.True(adapter.TryInvoke(wrappingState, (int)GraphicsLvo.ScalerDiv));
        Assert.Equal(0x8001u, wrappingState.D[0]);
    }

    [Fact]
    public void BitMapScaleDeclinesZeroFactorsBeforePublishingExtentOrPixels()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x500;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(sourcePlane, 0x80));
        Assert.True(memory.TryWriteByte(destinationPlane, 0x5A));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 1,
            srcHeight: 1,
            xSrcFactor: 0,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0xAAAA));
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0xBBBB));

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)0xAAAA, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)0xBBBB, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        Assert.Equal((byte)0x5A, ReadByte(memory, destinationPlane));

        var state = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 431
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BitMapScale));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(431, state.Cycles);
    }

    [Fact]
    public void BitMapScaleRoundsFractionalDestinationExtentsLikeScalerDiv()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;

        WritePlanarBitmap(memory, source, 0x400, 0x500, rows: 4);
        WritePlanarBitmap(memory, destination, 0x600, 0x700, rows: 8);
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 3,
            srcHeight: 3,
            xSrcFactor: 2,
            xDestFactor: 3,
            ySrcFactor: 2,
            yDestFactor: 3);

        // 3 * 3 / 2 is 4.5; the native scaler rounds this to five in both
        // axes before sampling the source bitmap.
        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)5, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)5, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
    }

    [Fact]
    public void BitMapScaleUsesCenteredDdaSamplesForFractionalExpansion()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x500;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 3, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 5, depth: 1);

        // A single source pen at (0,1) makes the centered DDA schedule
        // observable without depending on any multi-plane packing details.
        Assert.True(memory.TryWriteByte(sourcePlane + 2, 0x80));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 3,
            srcHeight: 3,
            xSrcFactor: 2,
            xDestFactor: 3,
            ySrcFactor: 2,
            yDestFactor: 3);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)5, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)5, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));

        // The native centered DDA maps 3 source rows to 5 destination rows as
        // 0,0,1,2,2.  Only the middle destination row therefore carries the
        // source pen, and its x schedule 0,0,1,2,2 duplicates the first two
        // columns.
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane + 2));
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane + 4));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane + 6));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane + 8));
    }

    [Fact]
    public void BitMapScaleUsesFactorsRatherThanRoundedExtentsForTwoToOneExpansion()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x500;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);

        // With a 1:2 factor the native DDA maps destination columns to
        // source columns 0,0,1,1,2,2.  A pen at source x=1 must therefore
        // occupy destination x=2 and x=3 (0x30), not x=3 and x=4 as the
        // extent-derived schedule would produce.
        Assert.True(memory.TryWriteByte(sourcePlane, 0x40));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 3,
            srcHeight: 1,
            xSrcFactor: 1,
            xDestFactor: 2,
            ySrcFactor: 1,
            yDestFactor: 1);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)6, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((byte)0x30, ReadByte(memory, destinationPlane));
        Assert.Equal((byte)0x00, ReadByte(memory, destinationPlane + 1));
    }

    [Fact]
    public void BitMapScaleWritesRatioDerivedExtentAndCopiesPlanarPixels()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
