        WritePlanarBitmap(memory, source, sourcePlane0, sourcePlane1, rows: 2);
        WritePlanarBitmap(memory, destination, destinationPlane0, destinationPlane1, rows: 4);
        Assert.True(memory.TryWriteByte(sourcePlane0, 0xA0));
        Assert.True(memory.TryWriteByte(sourcePlane0 + 2, 0x50));
        Assert.True(memory.TryWriteByte(sourcePlane1, 0x60));
        Assert.True(memory.TryWriteByte(sourcePlane1 + 2, 0x30));
        Assert.True(memory.TryWriteByte(destinationPlane0, 0));
        Assert.True(memory.TryWriteByte(destinationPlane0 + 2, 0));
        Assert.True(memory.TryWriteByte(destinationPlane0 + 4, 0));
        Assert.True(memory.TryWriteByte(destinationPlane0 + 6, 0));
        Assert.True(memory.TryWriteByte(destinationPlane1, 0));
        Assert.True(memory.TryWriteByte(destinationPlane1 + 2, 0));
        Assert.True(memory.TryWriteByte(destinationPlane1 + 4, 0));
        Assert.True(memory.TryWriteByte(destinationPlane1 + 6, 0));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 4,
            xDestFactor: 8,
            ySrcFactor: 2,
            yDestFactor: 4);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)8, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)4, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        Assert.Equal((byte)0xCC, ReadByte(memory, destinationPlane0));
        Assert.Equal((byte)0xCC, ReadByte(memory, destinationPlane0 + 2));
        Assert.Equal((byte)0x33, ReadByte(memory, destinationPlane0 + 4));
        Assert.Equal((byte)0x33, ReadByte(memory, destinationPlane0 + 6));
        Assert.Equal((byte)0x3C, ReadByte(memory, destinationPlane1));
        Assert.Equal((byte)0x3C, ReadByte(memory, destinationPlane1 + 2));
        Assert.Equal((byte)0x0F, ReadByte(memory, destinationPlane1 + 4));
        Assert.Equal((byte)0x0F, ReadByte(memory, destinationPlane1 + 6));

        var state = new M68kCpuState { A = { [0] = bitScaleArgs }, D = { [0] = 0xA5A5_A5A5 } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BitMapScale));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void BitMapScaleUsesCanonicalRowInterleavedPlaneStrideDirectAndRegister()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane0 = 0x400;
        const uint destinationPlane0 = 0x600;

        // The public BytesPerRow is the aggregate row stride (two bytes per
        // plane, depth two).  Plane links point into the first row, so the
        // second source row begins at +4 and the second destination row at
        // +8 for the wider 32-pixel destination.
        WriteInterleavedBitmap(memory, source, sourcePlane0, 4, rows: 2, depth: 2);
        WriteInterleavedBitmap(memory, destination, destinationPlane0, 8, rows: 2, depth: 2);
        Assert.True(memory.TryWriteByte(sourcePlane0, 0x80));
        Assert.True(memory.TryWriteByte(sourcePlane0 + 2, 0x80));
        Assert.True(memory.TryWriteByte(sourcePlane0 + 4, 0x80));
        Assert.True(memory.TryWriteByte(sourcePlane0 + 6, 0x80));

        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 16,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 2,
            ySrcFactor: 1,
            yDestFactor: 1);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane0));
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane0 + 4));
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane0 + 8));
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane0 + 12));

        // Exercise the same guest vector through the CopperSharp-compatible
        // register adapter after restoring the destination transaction.
        for (var offset = 0u; offset < 16; offset++)
            Assert.True(memory.TryWriteByte(destinationPlane0 + offset, 0));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 16,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 2,
            ySrcFactor: 1,
            yDestFactor: 1);
        var state = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0xA5A5_A5A5 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BitMapScale));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane0 + 8));
        Assert.Equal((byte)0xC0, ReadByte(memory, destinationPlane0 + 12));
    }

    [Fact]
    public void BitMapScaleRejectsMalformedInterleavedPlaneLinksBeforeMutation()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane0 = 0x400;
        const uint destinationPlane0 = 0x500;

        WriteInterleavedBitmap(memory, source, sourcePlane0, 4, rows: 2, depth: 2);
        WriteInterleavedBitmap(memory, destination, destinationPlane0, 4, rows: 2, depth: 2);
        // Plane one must begin at its first-row slice (+2), not at a later
        // row or a separately allocated span, when BMF_INTERLEAVED is set.
        Assert.True(memory.TryWriteLong(
            source + (uint)GraphicsLayouts.BitMapPlanes + 4,
            sourcePlane0 + 8));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 16,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0xAAAA));
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0xBBBB));

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)0xAAAA, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)0xBBBB, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        Assert.Equal((byte)0, ReadByte(memory, destinationPlane0));
    }

    [Fact]
    public void BitMapScaleRejectsNullSourcePlanesBeforePublishingExtents()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane0 = 0x400;
        const uint destinationPlane0 = 0x500;
        const uint destinationPlane1 = 0x600;

        // BitMapScale consumes a standard planar source.  A missing declared
        // source plane is not the BltBitMap V36 constant-plane form and must
        // remain available to the native/provider owner.
        WritePlanarBitmap(memory, source, sourcePlane0, 0, rows: 1, depth: 2);
        WritePlanarBitmap(memory, destination, destinationPlane0, destinationPlane1, rows: 1, depth: 2);
        Assert.True(memory.TryWriteByte(sourcePlane0, 0x80));
        Assert.True(memory.TryWriteByte(destinationPlane0, 0xA5));
        Assert.True(memory.TryWriteByte(destinationPlane1, 0x5A));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 1,
            srcHeight: 1,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0xAAAA));
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0xBBBB));

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)0xAAAA, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)0xBBBB, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        Assert.Equal((byte)0xA5, ReadByte(memory, destinationPlane0));
        Assert.Equal((byte)0x5A, ReadByte(memory, destinationPlane1));

        var state = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 73
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BitMapScale));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(73, state.Cycles);
    }

    [Fact]
    public void BitMapScaleAcceptsCompactDepthSizedHeadersAtTheGuestMemoryEnd()
    {
        // The two depth-one headers end exactly at the mapped guest range;
        // bytes belonging only to unused plane links are intentionally absent.
        var memory = new FakeMemory(0x3DC);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x3C0;
        const uint destination = 0x3D0;
        const uint sourcePlane = 0x100;
        const uint destinationPlane = 0x120;

        WritePlanarBitmap(memory, source, sourcePlane, 0, rows: 1, depth: 1);
        WritePlanarBitmap(memory, destination, destinationPlane, 0, rows: 1, depth: 1);
        Assert.True(memory.TryWriteByte(sourcePlane, 0x80));
        Assert.True(memory.TryWriteByte(destinationPlane, 0));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 1,
            srcHeight: 1,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)1, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)1, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        Assert.Equal((byte)0x80, ReadByte(memory, destinationPlane));
    }

    [Fact]
    public void BitMapScaleAcceptsAPlaneLongwordEndingAtGuestMaximumThroughBothDispatches()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint bitScaleArgs = 0x40;
        const uint source = 0xFFFF_FFF4;
        const uint destination = 0x180;
        const uint sourcePlane = 0x200;
        const uint destinationPlane = 0x300;

        // For a depth-one bitmap, BitMap.Planes[0] occupies [base+8..base+11].
        // At this high base the final byte is exactly $FFFF_FFFF; the compact
        // header is valid even though its unused tail is outside the guest
        // address envelope.
        WriteWideBitmap(memory, source, sourcePlane, bytesPerRow: 2, rows: 1);
        WriteWideBitmap(memory, destination, destinationPlane, bytesPerRow: 2, rows: 1);
        memory.WriteByte(sourcePlane, 0x80);
        memory.WriteByte(sourcePlane + 1u, 0);
        memory.WriteByte(destinationPlane, 0);
        memory.WriteByte(destinationPlane + 1u, 0);
        WriteWideBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 1,
            srcHeight: 1,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((byte)0x80, ReadByte(memory, destinationPlane));

        // Restore the destination and run the same guest record through the
        // CopperStart register gateway. The mapped path must claim the same
        // inclusive plane-link envelope and normalize its void D0 result.
        memory.WriteByte(destinationPlane, 0);
        memory.WriteByte(destinationPlane + 1u, 0);
        memory.WriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0xA5A5);
        memory.WriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0x5A5A);
        var state = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 419
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.BitMapScale));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(419, state.Cycles);
        Assert.Equal((byte)0x80, ReadByte(memory, destinationPlane));
    }

    [Fact]
    public void BitMapScalePreservesEightPlanePenValuesThroughTransactionalStaging()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlanes = 0x400;
        const uint destinationPlanes = 0x800;
        const byte sourcePen = 0xA5;

        // Exercise the full native planar depth.  One-pixel source/destination
        // rectangles keep the expected pen easy to inspect while still
        // forcing BitMapScale to read/write all eight declared planes.
        Assert.True(memory.TryWriteWord(
            source + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            source + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            source + (uint)GraphicsLayouts.BitMapDepth,
            8));
        Assert.True(memory.TryWriteWord(
            destination + (uint)GraphicsLayouts.BitMapBytesPerRow,
            2));
        Assert.True(memory.TryWriteWord(
            destination + (uint)GraphicsLayouts.BitMapRows,
            1));
        Assert.True(memory.TryWriteByte(
            destination + (uint)GraphicsLayouts.BitMapDepth,
            8));

        for (var plane = 0; plane < 8; plane++)
        {
            var sourcePlane = sourcePlanes + (uint)(plane * 0x20);
            var destinationPlane = destinationPlanes + (uint)(plane * 0x20);
            Assert.True(memory.TryWriteLong(
                source + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                sourcePlane));
            Assert.True(memory.TryWriteLong(
                destination + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                destinationPlane));
            Assert.True(memory.TryWriteByte(
                sourcePlane,
                (sourcePen & (1 << plane)) != 0 ? (byte)0x80 : (byte)0));
            Assert.True(memory.TryWriteByte(destinationPlane, 0));
        }

        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 1,
            srcHeight: 1,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);

        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)1, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal((ushort)1, ReadWord(
            memory,
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        for (var plane = 0; plane < 8; plane++)
        {
            var destinationPlane = destinationPlanes + (uint)(plane * 0x20);
            var expected = (sourcePen & (1 << plane)) != 0 ? (byte)0x80 : (byte)0;
            Assert.Equal(expected, ReadByte(memory, destinationPlane));
        }
    }

    [Fact]
    public void BitMapScaleRestoresExtentAndDestinationWhenALatePlaneWriteFails()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane0 = 0x400;
        const uint sourcePlane1 = 0x500;
        const uint destinationPlane0 = 0x600;
        const uint destinationPlane1 = 0x700;

        WritePlanarBitmap(backing, source, sourcePlane0, sourcePlane1, rows: 2);
        WritePlanarBitmap(backing, destination, destinationPlane0, destinationPlane1, rows: 2);
        for (var row = 0u; row < 2; row++)
        {
            Assert.True(backing.TryWriteByte(sourcePlane0 + (row * 2u), 0xFF));
            Assert.True(backing.TryWriteByte(sourcePlane1 + (row * 2u), 0xFF));
            Assert.True(backing.TryWriteByte(destinationPlane0 + (row * 2u), 0xA5));
            Assert.True(backing.TryWriteByte(destinationPlane1 + (row * 2u), 0x5A));
        }

        WriteBitScaleArgs(
            backing,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 4,
            xDestFactor: 4,
            ySrcFactor: 2,
            yDestFactor: 2);
        Assert.True(backing.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0x1234));
        Assert.True(backing.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0x5678));

        // Four extent bytes are written first; fail during the next pixel's
        // second-plane write so both the extent and an earlier pixel require
        // rollback.
        memory.FailOnNextByteWrite(7);
        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal(
            (ushort)0x1234,
            ReadWord(backing, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal(
            (ushort)0x5678,
            ReadWord(backing, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        for (var row = 0u; row < 2; row++)
        {
            Assert.Equal((byte)0xA5, ReadByte(backing, destinationPlane0 + (row * 2u)));
            Assert.Equal((byte)0x5A, ReadByte(backing, destinationPlane1 + (row * 2u)));
        }
    }

    [Fact]
    public void BitMapScaleRestoresExtentAfterARejectedRepeatedWordRollback()
    {
        var backing = new FakeMemory(0x4000);
        var memory = new ProbeThenFailWordWriteMemory(backing);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane0 = 0x400;
        const uint sourcePlane1 = 0x500;
        const uint destinationPlane0 = 0x600;
        const uint destinationPlane1 = 0x700;

        WritePlanarBitmap(backing, source, sourcePlane0, sourcePlane1, rows: 2);
        WritePlanarBitmap(backing, destination, destinationPlane0, destinationPlane1, rows: 2);
        WriteBitScaleArgs(
            backing,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 4,
            xDestFactor: 4,
            ySrcFactor: 2,
            yDestFactor: 2);

        var widthAddress = bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth;
        var heightAddress = bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight;
        Assert.True(backing.TryWriteWord(widthAddress, 0x1234));
        Assert.True(backing.TryWriteWord(heightAddress, 0x5678));
        memory.ProbeWordAddress = widthAddress;
        memory.FailWordAddress = heightAddress;

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)0x1234, ReadWord(backing, widthAddress));
        Assert.Equal((ushort)0x5678, ReadWord(backing, heightAddress));

        memory.FailWordAddress = null;
        memory.ResetProbe();
        Assert.Equal(0, core.BitMapScale(bitScaleArgs));
        Assert.NotEqual((ushort)0x1234, ReadWord(backing, widthAddress));
        Assert.NotEqual((ushort)0x5678, ReadWord(backing, heightAddress));
    }

    [Fact]
    public void BitMapScaleRejectsMalformedOrRtgEndpointsBeforeMutatingExtent()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        WritePlanarBitmap(memory, source, 0x400, 0x500, rows: 2);
        WritePlanarBitmap(memory, destination, 0x600, 0x700, rows: 2);
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 2,
            ySrcFactor: 1,
            yDestFactor: 2);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0x1234));
        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal((ushort)0x1234, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));

        Assert.True(memory.TryWriteLong(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsFlags,
            1));
        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.True(memory.TryWriteLong(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsFlags,
            0));

        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: bitmap => bitmap == destination);
        var state = new M68kCpuState { A = { [0] = bitScaleArgs } };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.BitMapScale));
        Assert.Equal((ushort)0x1234, ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
    }

    [Fact]
    public void BitMapScaleRejectsAggregateDestinationWorkBeforeStagingAndPreservesOverlayOwnership()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sourcePlane = 0x10_000;
        const uint destinationPlane = 0x20_000;
        const ushort bytesPerRow = 8192;
        const ushort rows = 32767;

        // The guest bitmap width is 65536 pixels at this stride.  The
        // requested 65535x32767 destination is still representable in the
        // public WORD fields and each individual plane envelope is below the
        // 32-bit span limit, but the scaler would need more than three
        // Int32-sized logical passes (sample/probe, snapshot, write).
        WriteWideBitmap(memory, source, sourcePlane, bytesPerRow, rows);
        WriteWideBitmap(memory, destination, destinationPlane, bytesPerRow, rows);
        var planeBytes = (uint)bytesPerRow * rows;
        memory.WriteByte(sourcePlane, 0);
        memory.WriteByte(sourcePlane + planeBytes - 1u, 0);
        memory.WriteByte(destinationPlane, 0xA5);
        memory.WriteByte(destinationPlane + planeBytes - 1u, 0x5A);

        WriteWideBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 65535,
            srcHeight: rows,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);
        memory.WriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0x1234);
        memory.WriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0x5678);

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.True(memory.TryReadWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            out var publishedWidth));
        Assert.True(memory.TryReadWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            out var publishedHeight));
        Assert.True(memory.TryReadByte(destinationPlane, out var firstDestinationByte));
        Assert.True(memory.TryReadByte(
            destinationPlane + planeBytes - 1u,
            out var lastDestinationByte));
        Assert.Equal(
            (ushort)0x1234,
            publishedWidth);
        Assert.Equal(
            (ushort)0x5678,
            publishedHeight);
        Assert.Equal((byte)0xA5, firstDestinationByte);
        Assert.Equal((byte)0x5A, lastDestinationByte);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var directState = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 41
        };
        Assert.False(adapter.TryInvoke(directState, (int)GraphicsLvo.BitMapScale));
        Assert.Equal(0xCAFE_BABEu, directState.D[0]);
        Assert.Equal(41, directState.Cycles);

        // The ROM overlay has no instance-owned bitmap registrations for
        // these caller-owned endpoints.  It must leave the same request to
        // the captured native vector rather than claiming the boundedness
        // decline or mutating the caller's extent fields.
        var overlayState = new M68kCpuState
        {
            A = { [0] = bitScaleArgs },
            D = { [0] = 0x1357_2468u },
            Cycles = 43
        };
        Assert.False(adapter.TryInvoke(
            overlayState,
            (int)GraphicsLvo.BitMapScale,
            nativeOverlay: true));
        Assert.Equal(0x1357_2468u, overlayState.D[0]);
        Assert.Equal(43, overlayState.Cycles);
    }

    [Fact]
    public void BitMapScaleRejectsOddNativePlanePointersBeforePublishingExtents()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;

        // The host byte adapter can represent odd addresses, but the native
        // planar BitMapScale path must preserve the 68000 word-address rule.
        WritePlanarBitmap(memory, source, 0x401, 0x501, rows: 2);
        WritePlanarBitmap(memory, destination, 0x601, 0x701, rows: 2);
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0x1234));
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0x5678));

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal(
            (ushort)0x1234,
            ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal(
            (ushort)0x5678,
            ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
    }

    [Fact]
    public void BitMapScaleRejectsDistinctHeadersThatAliasPlanarStorage()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint source = 0x100;
        const uint destination = 0x180;
        const uint sharedPlane0 = 0x400;
        const uint sharedPlane1 = 0x500;

        WritePlanarBitmap(memory, source, sharedPlane0, sharedPlane1, rows: 2);
        // A second BitMap header is distinct, but both plane pointers alias
        // the source storage.  Scaling must fail closed before publishing
        // destination extents because the classic contract forbids overlap.
        WritePlanarBitmap(memory, destination, sharedPlane0, sharedPlane1, rows: 2);
        Assert.True(memory.TryWriteByte(sharedPlane0, 0xA5));
        Assert.True(memory.TryWriteByte(sharedPlane1, 0x5A));
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            source,
            destination,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0x1234));
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0x5678));

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal(
            (ushort)0x1234,
            ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal(
            (ushort)0x5678,
            ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
        Assert.Equal((byte)0xA5, ReadByte(memory, sharedPlane0));
        Assert.Equal((byte)0x5A, ReadByte(memory, sharedPlane1));
    }

    [Fact]
    public void BitMapScaleRejectsASharedBitmapHeaderEvenForDisjointRectangles()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint bitScaleArgs = 0x40;
        const uint bitMap = 0x100;

        // The source and destination rectangles are disjoint inside the
        // same 16-pixel-wide bitmap.  Kickstart still rejects the shared
        // BitMap header; BitMapScale is not an in-place scaler.
        WriteBitScaleArgs(
            memory,
            bitScaleArgs,
            bitMap,
            bitMap,
            srcWidth: 4,
            srcHeight: 2,
            xSrcFactor: 1,
            xDestFactor: 1,
            ySrcFactor: 1,
            yDestFactor: 1,
            destX: 8);
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth,
            0x1234));
        Assert.True(memory.TryWriteWord(
            bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight,
            0x5678));

        Assert.Equal(-1, core.BitMapScale(bitScaleArgs));
        Assert.Equal(
            (ushort)0x1234,
            ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestWidth));
        Assert.Equal(
            (ushort)0x5678,
            ReadWord(memory, bitScaleArgs + (uint)GraphicsLayouts.BitScaleArgsDestHeight));
    }

    [Fact]
    public void HostGetVPModeIDUsesTheProfileModeProviderBoundary()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        var services = CreateHostGraphicsServices(
            hostMemory,
            getViewPortModeId: viewPort => viewPort == 0x500 ? 0x0002_9004u : GraphicsModeIds.Invalid);
        const uint viewPort = 0x500;
        const uint rasInfo = 0x580;

        hostMemory.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        hostMemory.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        hostMemory.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);

        var state = new M68kCpuState { A = { [0] = viewPort } };
        services.Invoke(state, (int)GraphicsLvo.GetVPModeID);
        Assert.Equal(0x0002_9004u, state.D[0]);

        state.A[0] = 0x00FF_0000;
        state.D[0] = GraphicsModeIds.Invalid;
        services.Invoke(state, (int)GraphicsLvo.GetVPModeID);
        Assert.Equal(GraphicsModeIds.Invalid, state.D[0]);
    }

    [Fact]
    public void HostGetVPModeIDLeavesMalformedViewPortsForNativeFallback()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        using var services = CreateHostGraphicsServices(hostMemory);
        var state = new M68kCpuState
        {
            A = { [0] = 0x00FF_0000 },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 123
        };

        services.Invoke(state, (int)GraphicsLvo.GetVPModeID);

        Assert.Equal(0xA5A5_5A5Au, state.D[0]);
        Assert.Equal(123, state.Cycles);
    }

    [Fact]
    public void HostGetVPModeIDClaimsAnUnlinkedViewportDuringAssembly()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        using var services = CreateHostGraphicsServices(
            hostMemory,
            getViewPortModeId: _ => GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode);
        const uint viewPort = 0x500;

        hostMemory.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
            640);
        hostMemory.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortDHeight,
            256);
        hostMemory.WriteWord(
            viewPort + (uint)GraphicsLayouts.ViewPortModes,
            GraphicsModeIds.HiresMode);
        hostMemory.WriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
            0);

        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 123
        };

        services.Invoke(state, (int)GraphicsLvo.GetVPModeID);

        Assert.Equal(
            GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode,
            state.D[0]);
        Assert.Equal(123, state.Cycles);
    }

    [Fact]
    public void AllocDBufInfoInitializesPublicMessageEnvelopesAndFreeMirrorsTheSize()
    {
        var memory = new FakeMemory(0x2000);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(memory, allocator, new FakeBlitter(), new FakeDisplay());
        const uint viewPort = 0x180;
        const uint rasInfo = 0x1C0;

        memory.TryWriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, 0);

        var dbuf = core.AllocDBufInfo(viewPort);
        Assert.Equal(0x1000u, dbuf);
        Assert.Equal((ushort)GraphicsLayouts.ExecMessageSize,
            ReadWord(memory, dbuf + (uint)GraphicsLayouts.DBufInfoSafeMessage + (uint)GraphicsLayouts.ExecMessageLength));
        Assert.Equal((ushort)GraphicsLayouts.ExecMessageSize,
            ReadWord(memory, dbuf + (uint)GraphicsLayouts.DBufInfoDispMessage + (uint)GraphicsLayouts.ExecMessageLength));
        Assert.Equal(0, core.FreeDBufInfo(dbuf));
        Assert.Equal((uint)GraphicsLayouts.DBufInfoSize, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Public, allocator.LastFreedClass);
        Assert.Equal(-1, core.FreeDBufInfo(dbuf));
        Assert.Equal(1, allocator.FreeCount);
        // FreeDBufInfo(NULL) is the documented no-op form and must not ask
        // the allocator to release anything.
        Assert.Equal(0, core.FreeDBufInfo(0));
        Assert.Equal(1, allocator.FreeCount);
    }

