    [Fact]
    public void AllocDBufInfoReadsOnlyTheRasInfoAndStandardModeFields()
    {
        static (FakeMemory Backing, RangeReadFaultMemory Memory, GraphicsLibraryCore Core, uint ViewPort)
            Prepare()
        {
            var backing = new FakeMemory(0x2000);
            var memory = new RangeReadFaultMemory(backing);
            var core = new GraphicsLibraryCore(
                memory,
                new FakeAllocator(),
                new FakeBlitter(),
                new FakeDisplay());
            const uint viewPort = 0x180;
            const uint rasInfo = 0x1C0;

            Assert.True(backing.TryWriteLong(
                viewPort + (uint)GraphicsLayouts.ViewPortRasInfo,
                rasInfo));
            Assert.True(backing.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoNext,
                0));
            Assert.True(backing.TryWriteLong(
                rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
                0));

            // AllocDBufInfo needs the RasInfo chain and the standard-planar
            // ExtendedModes byte, but it does not consume viewport geometry.
            // Fault the unrelated scalar span before asking for the envelope.
            memory.FailReads(
                viewPort + (uint)GraphicsLayouts.ViewPortDWidth,
                (uint)(GraphicsLayouts.ViewPortExtendedModes - GraphicsLayouts.ViewPortDWidth));
            return (backing, memory, core, viewPort);
        }

        var direct = Prepare();
        var directAddress = direct.Core.AllocDBufInfo(direct.ViewPort);
        Assert.NotEqual(0u, directAddress);

        var mapped = Prepare();
        var adapter = new CopperStartGraphicsRegisterAdapter(mapped.Core);
        var state = new M68kCpuState
        {
            A = { [0] = mapped.ViewPort },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 149
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocDBufInfo));
        Assert.NotEqual(0u, state.D[0]);
        Assert.Equal(149, state.Cycles);
    }

