        Assert.Equal(4321, rebuiltCycle);
        Assert.Equal(4321, state.Cycles);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(nextBitMap, hostMemory.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
    }

    [Fact]
    public void HostChangeVPBitMapLeavesMalformedCallsUnclaimedButForwardsRtgCalls()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var memory = new HostGuestMemory(machine.Bus);
        var providerCalls = 0;
        var malformed = CreateHostGraphicsServices(
            memory,
            changeViewPortBitMap: (_, _) =>
            {
                providerCalls++;
                return 0x1234;
            });
        var malformedState = new M68kCpuState
        {
            A = { [0] = 0x500, [1] = 0x700, [2] = 0x900 },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 61
        };

        malformed.Invoke(malformedState, (int)GraphicsLvo.ChangeVPBitMap);

        Assert.Equal(0, providerCalls);
        Assert.Equal(0xDEAD_BEEFu, malformedState.D[0]);
        Assert.Equal(61, malformedState.Cycles);
        malformed.Dispose();

        const uint viewPort = 0xA00;
        const uint rasInfo = 0xA40;
        const uint rtgBitMap = 0xA80;
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        machine.Bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);
        var rtg = CreateHostGraphicsServices(
            memory,
            changeViewPortBitMap: (_, _) =>
            {
                providerCalls++;
                return 0x1234;
            },
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        var rtgState = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = 0xB00, [2] = 0xC00 },
            D = { [0] = 0x1111_2222u },
            Cycles = 73
        };

        rtg.Invoke(rtgState, (int)GraphicsLvo.ChangeVPBitMap);

        Assert.Equal(1, providerCalls);
        Assert.Equal(0x1234u, rtgState.D[0]);
        Assert.Equal(73, rtgState.Cycles);
    }

