    [Fact]
    public void HostChangeVPBitMapForwardsPreviousBitmapToDoubleBufferScheduler()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        var scheduled = new List<(uint ViewPort, uint Previous, uint Next, uint DBufInfo, long Cycle)>();
        const uint dbufInfo = 0x1800;
        var services = CreateHostGraphicsServices(
            hostMemory,
            scheduleDoubleBufferMessages: (viewPort, previous, next, dbufInfo, cycle) =>
                scheduled.Add((viewPort, previous, next, dbufInfo, cycle)),
            allocateMemory: (_, _) => dbufInfo);
        const uint viewPort = 0x500;
        const uint rasInfo = 0x580;
        const uint firstBitMap = 0x700;
        const uint nextBitMap = 0x780;

        hostMemory.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        hostMemory.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, firstBitMap);
        hostMemory.WriteWord(firstBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        hostMemory.WriteByte(firstBitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        hostMemory.WriteWord(nextBitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        hostMemory.WriteByte(nextBitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        for (var offset = 0; offset < GraphicsLayouts.DBufInfoSize; offset++)
            hostMemory.WriteByte(dbufInfo + (uint)offset, 0);

        var allocateState = new M68kCpuState { A = { [0] = viewPort } };
        services.Invoke(allocateState, (int)GraphicsLvo.AllocDBufInfo);
        Assert.Equal(dbufInfo, allocateState.D[0]);

        var state = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap, [2] = dbufInfo },
            Cycles = 77
        };
        services.Invoke(state, (int)GraphicsLvo.ChangeVPBitMap);

        var notification = Assert.Single(scheduled);
        Assert.Equal(viewPort, notification.ViewPort);
        Assert.Equal(firstBitMap, notification.Previous);
        Assert.Equal(nextBitMap, notification.Next);
        Assert.Equal(dbufInfo, notification.DBufInfo);
        Assert.Equal(77, notification.Cycle);
    }

    [Fact]
    public void HostRegisterAdapterMapsPureMemoryVectorsAndRoutesDisplayBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var display = new FakeDisplay();
        var core = CreateCore(memory, display);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState();
        state.A[1] = 0x20;

        state.D[0] = 5;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetAPen));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(5, core.GetAPen(0x20));

        state.D[0] = 12;
        state.D[1] = 3;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Move));
        Assert.Equal((ushort)12, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentX));
        Assert.Equal((ushort)3, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentY));

        // Exercise the register gateway with a standard-planar JAM2 line.
        // COMPLEMENT must apply to both the APen and BPen pattern samples,
        // including the source-zero cells that JAM2 takes from BPen.
        Assert.Equal(0, core.SetRast(0x20, 0));
        Assert.Equal(0, core.SetAPen(0x20, 1));
        Assert.Equal(0, core.SetBPen(0x20, 0));
        Assert.Equal(0, core.SetDrawMode(0x20, 3)); // JAM2|COMPLEMENT
        Assert.True(memory.TryWriteWord(
            0x20u + (uint)GraphicsLayouts.RastPortLinePattern,
            0xA000));
        state.D[0] = 0;
        state.D[1] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Move));
        state.D[0] = 3;
        state.D[1] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Draw));
        Assert.Equal(0u, state.D[0]);
        for (short x = 0; x < 4; x++)
            Assert.Equal(3, core.ReadPixel(0x20, x, 0));

        // Restore the pre-existing line state for the remainder of this
        // broad adapter smoke test.
        Assert.Equal(0, core.SetAPen(0x20, 5));
        Assert.Equal(0, core.SetBPen(0x20, 1));
        Assert.Equal(0, core.SetDrawMode(0x20, 1));
        Assert.True(memory.TryWriteWord(
            0x20u + (uint)GraphicsLayouts.RastPortLinePattern,
            0xFFFF));
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Move));
        state.D[0] = 12;
        state.D[1] = 3;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Move));
        state.D[0] = 2;
        state.D[1] = 2;
        state.D[2] = 3;
        state.D[3] = 3;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.RectFill));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1, core.ReadPixel(0x20, 2, 2));

        state.D[0] = 4;
        state.D[1] = 4;
        state.D[2] = 2;
        state.D[3] = 2;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.DrawEllipse));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1, core.ReadPixel(0x20, 4, 2));

        state.D[0] = 1;
        state.D[1] = 0;
        state.D[2] = 0;
        state.D[3] = 0;
        state.D[4] = 7;
        state.D[5] = 7;
        Assert.Equal(0, core.SetRast(0x20, 1));
        Assert.Equal(0, core.SetBPen(0x20, 2));
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.ScrollRasterBF));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(2, core.ReadPixel(0x20, 7, 0));

        memory.TryWriteLong(0x20u + (uint)GraphicsLayouts.RastPortLayer, 0x1234);
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.DrawEllipse));
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.ScrollRaster));
        memory.TryWriteLong(0x20u + (uint)GraphicsLayouts.RastPortLayer, 0);

        state.D[0] = 0;
        state.D[1] = 0;
        state.D[2] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));

        state.A[0] = 0x1200;
        state.D[0] = 2;
        state.D[1] = 17;
        state.D[2] = 9;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitBitMap));
        Assert.Equal((ushort)4, ReadWord(memory, 0x1200u + (uint)GraphicsLayouts.BitMapBytesPerRow));

        state.A[0] = 0x300;
        memory.TryWriteWord(0x300, 1);
        memory.TryWriteWord(0x302, 1);
        memory.TryWriteWord(0x304, 1);
        memory.TryWriteWord(0x306, 3);
        state.D[0] = 2;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.PolyDraw));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1, core.ReadPixel(0x20, 1, 1));
        Assert.Equal(1, core.ReadPixel(0x20, 1, 3));

        state.A[0] = 0x20;
        state.D[0] = 0xA5_000005;
        state.D[1] = 0xB6_000006;
        state.D[2] = 0xC7_000002;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetABPenDrMd));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)5, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)6, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)2, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortDrawMode));
        state.D[0] = 0xA5_0003C7;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetWriteMask));
        Assert.Equal(uint.MaxValue, state.D[0]);
        Assert.Equal((byte)0xC7, ReadByte(memory, 0x20u + (uint)GraphicsLayouts.RastPortMask));

        state.D[0] = 0xA5_000007;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetOutlinePen));
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetOutlinePen));
        Assert.Equal(7u, state.D[0]);

        state.A[0] = 0x20;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetAPen));
        Assert.Equal(5u, state.D[0]);

        state.A[1] = 0x180;
        state.Cycles = 37;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.LoadView));
        Assert.Equal(0x180u, display.PublishedView);
        Assert.Equal(0u, state.D[0]);

        state.A[1] = 0x00FF_0000;
        state.D[0] = 0xDEAD_BEEFu;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.LoadView));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(0x180u, display.PublishedView);

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WaitTOF));
        Assert.True(display.WaitedForTopOfFrame);
        Assert.Equal(37, state.Cycles);
        state.A[0] = 0x1A0;
        memory.TryWriteLong(0x1A0u + (uint)GraphicsLayouts.ViewPortRasInfo, 0x500);
        memory.TryWriteLong(0x500u + (uint)GraphicsLayouts.RasInfoNext, 0);
        memory.TryWriteLong(0x500u + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        memory.TryWriteWord(0x500u + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        memory.TryWriteWord(0x500u + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.WaitBOVP));
        Assert.Equal(0x1A0u, display.WaitedForViewPort);
        Assert.Equal(37, state.Cycles);

        state.D[0] = 17;
        state.D[1] = 3;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AllocRaster));
        Assert.Equal(0x1000u, state.D[0]);
        state.A[0] = state.D[0];
        state.D[0] = 17;
        state.D[1] = 3;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FreeRaster));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void FreeRasterRegisterAdapterConsumesItsDocumentedWordSizedDimensions()
    {
        var memory = new FakeMemory(0x100);
        var allocator = new FakeAllocator();
        var core = new GraphicsLibraryCore(
            memory,
            allocator,
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        var allocate = new M68kCpuState
        {
            D = { [0] = 17, [1] = 3 }
        };
        Assert.True(adapter.TryInvoke(
            allocate,
            (int)GraphicsLvo.AllocRaster,
            nativeOverlay: true));
        Assert.Equal(0x1000u, allocate.D[0]);

        var free = new M68kCpuState
        {
            A = { [0] = allocate.D[0] },
            // FreeRaster is D0:16/D1:16.  The high words must not alter the
            // width/height used to reconstruct the original RASSIZE span.
            D = { [0] = 0xCAFE_0011u, [1] = 0xBABE_0003u },
            Cycles = 41
        };
        Assert.True(adapter.TryInvoke(
            free,
            (int)GraphicsLvo.FreeRaster,
            nativeOverlay: true));
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(41, free.Cycles);
        Assert.Equal(0x1000u, allocator.LastFreedAddress);
        Assert.Equal(12u, allocator.LastFreedBytes);
        Assert.Equal(GraphicsMemoryClass.Chip, allocator.LastFreedClass);
    }

    [Fact]
    public void HostRegisterAdapterLeavesMalformedPlanarFloodForNativeOwnership()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [1] = 0x20 },
            D = { [0] = 0xCAFE_BABEu, [1] = 0x1234u, [2] = 0u },
            Cycles = 53
        };

        // The zeroed RastPort has no BitMap association, so the portable
        // Flood implementation cannot claim this request.  D0 and cycles
        // must remain available for the native/provider vector.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Flood));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(53, state.Cycles);
    }

    [Fact]
    public void SetRgb4RegisterAdaptersConsumeSignedWordPenIndices()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = core.GetColorMap(4);
        Assert.NotEqual(0u, colorMap);

        var colorMapState = new M68kCpuState
        {
            A = { [0] = colorMap },
            // SetRGB4CM's n argument is SHORT in the Kickstart ABI.  The
            // nonzero high word must not turn pen 2 into a huge index.
            D = { [0] = 0xCAFE_0002u, [1] = 0x0000_000Au, [2] = 5, [3] = 15 }
        };
        Assert.True(adapter.TryInvoke(colorMapState, (int)GraphicsLvo.SetRGB4CM));
        Assert.Equal(0u, colorMapState.D[0]);
        Assert.Equal(0xA5Fu, core.GetRGB4(colorMap, 2));

        const uint viewPort = 0x200;
        Assert.True(memory.TryWriteLong(
            viewPort + (uint)GraphicsLayouts.ViewPortColorMap,
            colorMap));
        var viewPortState = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xBEEF_0003u, [1] = 1, [2] = 2, [3] = 3 }
        };
        Assert.True(adapter.TryInvoke(viewPortState, (int)GraphicsLvo.SetRGB4));
        Assert.Equal(0u, viewPortState.D[0]);
        Assert.Equal(0x123u, core.GetRGB4(colorMap, 3));
    }

    [Fact]
    public void HostRegisterAdapterReturnsTheGetRgb4PaletteValue()
    {
        var memory = new FakeMemory(0x10000);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var colorMap = core.GetColorMap(4);
        Assert.NotEqual(0u, colorMap);
        Assert.True(core.SetRGB4CM(colorMap, 1, 0x0A, 0x05, 0x0F));

        var state = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1 },
            Cycles = 53
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetRGB4));
        Assert.Equal(0x0A5Fu, state.D[0]);
        Assert.Equal(53, state.Cycles);

        state.D[0] = 4;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.GetRGB4));
        Assert.Equal(4u, state.D[0]);
    }

    [Fact]
    public void GetRgb4ReadsOnlyTheRequestedColorTableWord()
    {
        var backing = new FakeMemory(0x10000);
        var memory = new RangeReadFaultMemory(backing);
        var core = new GraphicsLibraryCore(
            memory,
            new BitmapAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        var colorMap = core.GetColorMap(2);
        Assert.NotEqual(0u, colorMap);
        Assert.True(core.SetRGB4CM(colorMap, 1, 0x0A, 0x05, 0x0F));

        var lowColors = ReadLong(backing, colorMap + (uint)GraphicsLayouts.ColorMapLowColorBits);
        Assert.NotEqual(0u, lowColors);

        // GetRGB4's native contract is a ColorTable/count lookup.  A fault
        // in the optional V36 low-nibble table must not make a valid legacy
        // high-nibble read unclaimable.
        memory.FailReads(lowColors + 2, sizeof(ushort));
        Assert.Equal(0x0A5Fu, core.GetRGB4(colorMap, 1));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1 },
            Cycles = 61
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetRGB4));
        Assert.Equal(0x0A5Fu, state.D[0]);
        Assert.Equal(61, state.Cycles);
    }

    [Fact]
    public void HostRegisterAdapterUsesPolyDrawLowWordCountAbi()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x300, [1] = 0x20 },
            D = { [0] = 0x0000_FFFFu }
        };

        // Kickstart consumes the low 16 bits of PolyDraw's LONG count.  A
        // count of 0xFFFF is therefore a real (large) request, not a signed
        // negative no-op; the deliberately short guest buffer must fall
        // through without claiming the vector.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.PolyDraw));
        Assert.Equal(0x0000_FFFFu, state.D[0]);
    }

    [Fact]
    public void EmptyPolyDrawDoesNotRequireReadableRastPortOrPointTable()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = 0xFFFF_FFFEu, [1] = 0xFFFF_FFFFu },
            D = { [0] = 0x1234_0000u },
            Cycles = 71
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = 0xFFFF_FFFEu, [1] = 0xFFFF_FFFFu },
            D = { [0] = 0x1234_0000u },
            Cycles = 71
        };

        // Kickstart consumes only the low UWORD of PolyDraw's LONG count and
        // performs no guest dereference for an empty point stream.  The
        // direct host and mapped ROM-overlay paths must therefore both claim
        // this no-op even though neither endpoint is readable.
        direct.Invoke(directState, (int)GraphicsLvo.PolyDraw);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.PolyDraw));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(71, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
    }

    [Fact]
    public void EmptyTextDoesNotRequireReadableRastPortOrString()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
            bus.MapReadOnlyMemory(imageBase, new byte[0x2000]);

        using var direct = CreateHostGraphicsServices(new HostGuestMemory(directBus));
        using var overlay = CreateHostGraphicsServices(new HostGuestMemory(overlayBus));
        Assert.True(overlay.InstallKickstartRomOverlay(graphicsBase));

        var directState = new M68kCpuState
        {
            A = { [0] = 0xFFFF_FFFEu, [1] = 0xFFFF_FFFFu },
            D = { [0] = 0xABCD_0000u },
            Cycles = 73
        };
        var overlayState = new M68kCpuState
        {
            A = { [0] = 0xFFFF_FFFEu, [1] = 0xFFFF_FFFFu },
            D = { [0] = 0xABCD_0000u },
            Cycles = 73
        };

        // Text's signed WORD count is zero, so the standard-planar path must
        // claim the no-read empty request even though neither A0 nor A1 is
        // mapped.  The direct and mapped ROM-overlay gateways retain the
        // same void D0/cycle result.
        direct.Invoke(directState, (int)GraphicsLvo.Text);
        var address = unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.Text));
        Assert.True(overlayBus.TryInvokeHostGatewayAt(address, overlayState));
        Assert.Equal(0u, directState.D[0]);
        Assert.Equal(directState.D[0], overlayState.D[0]);
        Assert.Equal(73, directState.Cycles);
        Assert.Equal(directState.Cycles, overlayState.Cycles);
    }

    [Fact]
    public void HostRegisterAdapterLeavesMalformedRastPortSettersUnclaimed()
    {
        var memory = new FakeMemory(0x10000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint malformed = 0xFFF0;
        const uint sentinel = 0xDEAD_BEEFu;
        var vectors = new[]
        {
            GraphicsLvo.SetAPen,
            GraphicsLvo.SetBPen,
            GraphicsLvo.SetDrMd,
            GraphicsLvo.SetABPenDrMd,
            GraphicsLvo.SetWriteMask,
            GraphicsLvo.SetMaxPen,
            GraphicsLvo.SetOutlinePen,
            GraphicsLvo.SetSoftStyle
        };

        foreach (var vector in vectors)
        {
            var state = new M68kCpuState
            {
                A = { [0] = malformed, [1] = malformed },
                D = { [0] = sentinel, [1] = 2, [2] = 3 },
                Cycles = 47
            };

            Assert.False(adapter.TryInvoke(state, (int)vector), vector.ToString());
            Assert.Equal(sentinel, state.D[0]);
            Assert.Equal(47, state.Cycles);
        }
    }

