    [Fact]
    public void SoftStyleQueriesReadOnlyTheIntrinsicFontStyleByte()
    {
        const uint rastPort = 0x20;
        const uint font = 0x600;
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);

        Assert.True(backing.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            font));
        Assert.True(backing.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            0x08));
        Assert.True(backing.TryWriteByte(
            font + (uint)GraphicsLayouts.TextFontStyle,
            0x02));

        // YSize is not part of the resident AskSoftStyle/SetSoftStyle read
        // set. Faulting it makes the old full-metric admission fail while
        // leaving tf_Style readable for the exact scalar path.
        memory.FailReads(font + (uint)GraphicsLayouts.TextFontYSize, sizeof(ushort));

        var ask = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 211
        };
        Assert.True(adapter.TryInvoke(ask, (int)GraphicsLvo.AskSoftStyle));
        Assert.Equal(0xFFFF_FFFDu, ask.D[0]);
        Assert.Equal(211, ask.Cycles);

        var mappedAsk = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 217
        };
        Assert.True(adapter.TryInvoke(
            mappedAsk,
            (int)GraphicsLvo.AskSoftStyle,
            nativeOverlay: true));
        Assert.Equal(0xFFFF_FFFDu, mappedAsk.D[0]);
        Assert.Equal(217, mappedAsk.Cycles);

        var set = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x08, [1] = 0x0A },
            Cycles = 223
        };
        Assert.True(adapter.TryInvoke(set, (int)GraphicsLvo.SetSoftStyle));
        Assert.Equal(0x0Au, set.D[0]);
        Assert.Equal(0x08u, ReadByte(
            backing,
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        var mappedSet = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x08, [1] = 0x0A },
            Cycles = 229
        };
        Assert.True(adapter.TryInvoke(
            mappedSet,
            (int)GraphicsLvo.SetSoftStyle,
            nativeOverlay: true));
        Assert.Equal(0x0Au, mappedSet.D[0]);
        Assert.Equal(229, mappedSet.Cycles);
        Assert.Equal(0, memory.FaultedReadCount);
    }

    [Fact]
    public void HostProviderClassifiersRejectWrappedHighGuestAddresses()
    {
        var memory = new FakeMemory(0x200);
        var core = CreateCore(memory);
        const uint highAddress = 0xFFFF_FFFFu;
        const uint view = 0x20;
        const uint highViewPort = 0xFFFF_FFE0u;
        const uint rasInfo = 0xA0;
        const uint rtgBitMap = 0xC0;

        Assert.True(memory.TryWriteLong(
            view + (uint)GraphicsLayouts.ViewViewPort,
            highViewPort));
        Assert.True(memory.TryWriteLong(
            unchecked(highViewPort + (uint)GraphicsLayouts.ViewPortRasInfo),
            rasInfo));
        Assert.True(memory.TryWriteLong(
            rasInfo + (uint)GraphicsLayouts.RasInfoBitMap,
            rtgBitMap));

        var adapter = new CopperStartGraphicsRegisterAdapter(
            core,
            isRtgBitMap: bitMap => bitMap == rtgBitMap);

        Assert.False(adapter.IsProviderRastPort(highAddress));
        Assert.False(adapter.IsRtgViewForProvider(view));
    }

