    [Fact]
    public void HostRegisterAdapterLeavesMalformedDrawingOperationsToTheNativeBoundary()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint sentinel = 0xA55A_11EEu;

        void AssertFallsThrough(GraphicsLvo vector, Action<M68kCpuState> configure)
        {
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = sentinel }
            };
            configure(state);
            var originalD0 = state.D[0];

            Assert.False(adapter.TryInvoke(state, (int)vector));
            Assert.Equal(originalD0, state.D[0]);
        }

        // Use an invalid odd row stride.  The portable bitmap decoder must
        // reject every bitmap-writing vector before it publishes any partial
        // row, while the mapped RastPort remains a valid provider boundary.
        Assert.True(memory.TryWriteWord(
            0x100u + (uint)GraphicsLayouts.BitMapBytesPerRow,
            3));
        Assert.True(memory.TryWriteByte(
            0x100u + (uint)GraphicsLayouts.BitMapFlags,
            0x08)); // BMF_STANDARD
        // Each operation below reaches the portable core with a mapped,
        // non-layered RastPort, but its own guarded plan rejects the request.
        // The adapter must not convert that failure into a claimed void call;
        // native Kickstart or the active host/provider boundary still owns it.
        AssertFallsThrough(
            GraphicsLvo.Draw,
            state =>
            {
                state.D[0] = 0;
                state.D[1] = 0;
            });
        AssertFallsThrough(
            GraphicsLvo.AreaMove,
            state =>
            {
                state.D[0] = 1;
                state.D[1] = 1; // no AreaInfo is attached to this RastPort
            });
        var invertedRect = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3, [1] = 0, [2] = 2, [3] = 0, [4] = sentinel }
        };
        // Inverted RectFill geometry is an empty void operation even when
        // the bitmap's row stride would otherwise be malformed.  The
        // gateway must claim it without probing or mutating that bitmap.
        Assert.True(adapter.TryInvoke(invertedRect, (int)GraphicsLvo.RectFill));
        Assert.Equal(0u, invertedRect.D[0]);
        AssertFallsThrough(
            GraphicsLvo.DrawEllipse,
            state =>
            {
                state.D[0] = 4;
                state.D[1] = 4;
                state.D[2] = 0; // non-positive radius
                state.D[3] = 2;
            });
        foreach (var vector in new[] { GraphicsLvo.ScrollRaster, GraphicsLvo.ScrollRasterBF })
        {
            var invertedScroll = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = 1, [1] = 0, [2] = 3, [3] = 0, [4] = 2, [5] = 0, [6] = sentinel }
            };
            // Both void scroll vectors treat reversed bounds as an empty
            // operation, even though this fixture's bitmap row stride is
            // intentionally malformed.
            Assert.True(adapter.TryInvoke(invertedScroll, (int)vector));
            Assert.Equal(0u, invertedScroll.D[0]);
        }
        AssertFallsThrough(
            GraphicsLvo.PolyDraw,
            state =>
            {
                state.A[0] = 0x300;
                state.D[0] = 2;
            });
        AssertFallsThrough(GraphicsLvo.ClearEOL, _ => { });
        AssertFallsThrough(GraphicsLvo.ClearScreen, _ => { });
        AssertFallsThrough(
            GraphicsLvo.EraseRect,
            state =>
            {
                state.D[0] = 0;
                state.D[1] = 0;
                state.D[2] = 1;
                state.D[3] = 1;
            });

        AssertFallsThrough(
            GraphicsLvo.SetRast,
            state => state.D[0] = 1);
    }

    [Fact]
    public void HostRegisterAdapterLeavesLayeredRastPortDrawingToTheLayerProvider()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180));

        var state = new M68kCpuState
        {
            A =
            {
                [0] = 0x300,
                [1] = rastPort,
                [2] = 0x400
            },
            D =
            {
                [0] = 1,
                [1] = 1,
                [2] = 4,
                [3] = 4,
                [4] = 7,
                [5] = 7
            }
        };

        // Layer clipping, damage tracking, and backing-store selection are
        // owned by layers.library (or a future host/native provider).  The
        // portable planar path must not claim these vectors and draw into the
        // backing bitmap as if the RastPort were a plain one.
        var layeredVectors = new[]
        {
            GraphicsLvo.ClipBlit,
            GraphicsLvo.BltBitMapRastPort,
            GraphicsLvo.BltMaskBitMapRastPort,
            GraphicsLvo.BltPattern,
            GraphicsLvo.BltTemplate,
            GraphicsLvo.Draw,
            GraphicsLvo.AreaMove,
            GraphicsLvo.AreaDraw,
            GraphicsLvo.AreaEllipse,
            GraphicsLvo.AreaEnd,
            GraphicsLvo.ReadPixel,
            GraphicsLvo.WritePixel,
            GraphicsLvo.RectFill,
            GraphicsLvo.DrawEllipse,
            GraphicsLvo.ScrollRaster,
            GraphicsLvo.ScrollRasterBF,
            GraphicsLvo.Flood,
            GraphicsLvo.SetRast,
            GraphicsLvo.PolyDraw,
            GraphicsLvo.ClearEOL,
            GraphicsLvo.ClearScreen,
            GraphicsLvo.EraseRect,
            GraphicsLvo.ReadPixelLine8,
            GraphicsLvo.WritePixelLine8,
            GraphicsLvo.ReadPixelArray8,
            GraphicsLvo.WritePixelArray8,
            GraphicsLvo.WriteChunkyPixels,
            GraphicsLvo.Text
        };

        foreach (var vector in layeredVectors)
        {
            var usesA0RastPort = vector is
                GraphicsLvo.ReadPixelLine8 or
                GraphicsLvo.WritePixelLine8 or
                GraphicsLvo.ReadPixelArray8 or
                GraphicsLvo.WritePixelArray8 or
                GraphicsLvo.WriteChunkyPixels;
            if (usesA0RastPort)
                (state.A[0], state.A[1]) = (state.A[1], state.A[0]);

            state.D[0] = 1;
            Assert.False(
                adapter.TryInvoke(state, (int)vector),
                $"Layered RastPort vector {vector} must remain with the layer provider.");

            if (usesA0RastPort)
                (state.A[0], state.A[1]) = (state.A[1], state.A[0]);
        }
    }

    [Fact]
    public void HostGraphicsServicesLeavesDeclinedLayerVectorsUnclaimed()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);

        using var services = CreateHostGraphicsServices(memory);
        var state = new M68kCpuState
        {
            A = { [0] = 0x300, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 91
        };

        services.Invoke(state, (int)GraphicsLvo.Text);

        // Layer clipping belongs to the layer/native provider.  A declined
        // portable call must preserve the register and timing state so that
        // owner can execute the original vector.
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(91, state.Cycles);

        // The V36/V40 pixel-array family uses A0 for the RastPort (unlike
        // Text/Draw's A1 convention).  Keep that ABI explicit in the
        // declined-layer coverage as well.
        state.A[0] = rastPort;
        state.A[1] = 0x300;
        foreach (var vector in new[]
                 {
                     GraphicsLvo.ReadPixelLine8,
                     GraphicsLvo.WritePixelLine8,
                     GraphicsLvo.ReadPixelArray8,
                     GraphicsLvo.WritePixelArray8,
                     GraphicsLvo.WriteChunkyPixels
                 })
        {
            state.D[0] = 0xDEAD_BEEFu;
            services.Invoke(state, (int)vector);
            Assert.Equal(0xDEAD_BEEFu, state.D[0]);
            Assert.Equal(91, state.Cycles);
        }

    }

    [Fact]
    public void HostGraphicsServicesForwardsLayeredTextAndDrawToTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);
        var provider = new RecordingLayerRasterBackend();

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            A = { [0] = 0x300, [1] = rastPort },
            D = { [0] = 7, [1] = 9 },
            Cycles = 123
        };

        services.Invoke(state, (int)GraphicsLvo.Draw);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(123, state.Cycles);
        Assert.Equal((rastPort, (short)7, (short)9), provider.Drawn.Single());

        state.D[0] = 0xCAFE_0005u;
        services.Invoke(state, (int)GraphicsLvo.Text);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(123, state.Cycles);
        Assert.Equal((rastPort, 0x300u, (short)5), provider.TextRuns.Single());
    }

    [Fact]
    public void HostGraphicsServicesForwardsEmptyLayeredTextToTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);
        var provider = new RecordingLayerRasterBackend();

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            // A0 is intentionally unreadable: the empty Text contract must
            // reach the layer provider without touching the guest string.
            A = { [0] = 0xFFFF_FFFE, [1] = rastPort },
            D = { [0] = 0xCAFE_0000u },
            Cycles = 127
        };

        services.Invoke(state, (int)GraphicsLvo.Text);

        Assert.Equal(0u, state.D[0]);
        Assert.Equal(127, state.Cycles);
        Assert.Equal((rastPort, 0xFFFF_FFFEu, (short)0), provider.TextRuns.Single());
    }

    [Fact]
    public void DirectGraphicsServicesMoveUsesThePortableRastPortStateBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);

        using var services = CreateHostGraphicsServices(memory);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = unchecked((uint)(short)-13), [1] = 27, },
            Cycles = 61
        };

        // The direct host helper is used by CopperScreen/console paths in
        // addition to the normal LVO dispatcher.  It must reach the same
        // portable Move implementation, including FRST_DOT and line phase,
        // rather than maintaining a second byte-only state update.
        services.Move(state);

        Assert.Equal(0u, state.D[0]);
        Assert.Equal(61, state.Cycles);
        Assert.Equal((short)-13, unchecked((short)memory.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)27, unchecked((short)memory.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal((byte)15, memory.ReadByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.True((memory.ReadWord(rastPort + (uint)GraphicsLayouts.RastPortFlags) &
            GraphicsLayouts.RastPortFirstDot) != 0);
    }

    [Fact]
    public void DirectGraphicsServicesTextAndDrawingHelpersUsePortableRasterOperations()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;
        const uint font = 0x600;
        const uint charData = 0x700;
        const uint text = 0x800;

        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[0x20]);
        bus.MapWritableMemory(plane1, new byte[0x20]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charData, new byte[4]);
        bus.MapWritableMemory(text, new byte[1]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 3);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0); // JAM1
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);

        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 3);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        memory.WriteByte(charData, 0xE0);
        memory.WriteByte(charData + 1, 0xA0);
        memory.WriteByte(charData + 2, 0xE0);
        memory.WriteByte(text, (byte)'A');

        using var services = CreateHostGraphicsServices(memory);

        var move = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 3 },
            Cycles = 73
        };
        services.Move(move);
        Assert.Equal(73, move.Cycles);

        var drawText = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1 },
            Cycles = 73
        };
        services.Text(drawText);
        Assert.Equal(0u, drawText.D[0]);
        Assert.Equal(73, drawText.Cycles);
        Assert.Equal((short)3, unchecked((short)memory.ReadWord(
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((byte)0xE0, memory.ReadByte(plane0 + 6));
        Assert.Equal((byte)0xE0, memory.ReadByte(plane1 + 6));

        var draw = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 5, [1] = 6 },
            Cycles = 73
        };
        services.Move(new M68kCpuState { A = { [1] = rastPort }, D = { [0] = 4, [1] = 6 }, Cycles = 73 });
        services.Draw(draw);
        Assert.Equal(0u, draw.D[0]);
        Assert.Equal(73, draw.Cycles);
        Assert.NotEqual((byte)0, memory.ReadByte(plane0 + 12));

        var fill = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 2, [3] = 1 },
            Cycles = 73
        };
        services.RectFill(fill);
        Assert.Equal(0u, fill.D[0]);
        Assert.Equal(73, fill.Cycles);
        Assert.NotEqual((byte)0, memory.ReadByte(plane0));
    }

    [Fact]
    public void DirectGraphicsServicesClearEolUsesMappedGuestFontHeight()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;
        const uint font = 0x600;

        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane0, new byte[0x20]);
        bus.MapWritableMemory(plane1, new byte[0x20]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, plane1);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 1);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 3);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentY, 5);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortCurrentX, 2);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1); // JAM2
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        for (var offset = 0; offset < 16; offset++)
        {
            memory.WriteByte(plane0 + (uint)offset, 0xFF);
            memory.WriteByte(plane1 + (uint)offset, 0xFF);
        }

        using var services = CreateHostGraphicsServices(memory);
        var clear = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 97
        };
        services.Invoke(clear, (int)GraphicsLvo.ClearEOL);
        Assert.Equal(0u, clear.D[0]);
        Assert.Equal(97, clear.Cycles);

        var rowFive = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 15, [1] = 5 }
        };
        services.Invoke(rowFive, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(2u, rowFive.D[0]);

        var rowSix = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 15, [1] = 6 }
        };
        services.Invoke(rowSix, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(3u, rowSix.D[0]);

        // The mapped gateway must retain the same JAM2-bit rule for a
        // combined mode, not fall back to pen zero when COMPLEMENT is set.
        for (var offset = 0; offset < 16; offset++)
        {
            memory.WriteByte(plane0 + (uint)offset, 0xFF);
            memory.WriteByte(plane1 + (uint)offset, 0xFF);
        }

        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 3);
        var combinedModeClear = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 101
        };
        services.Invoke(combinedModeClear, (int)GraphicsLvo.ClearEOL);
        Assert.Equal(0u, combinedModeClear.D[0]);
        Assert.Equal(101, combinedModeClear.Cycles);

        var combinedModeRow = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = 5 }
        };
        services.Invoke(combinedModeRow, (int)GraphicsLvo.ReadPixel);
        Assert.Equal(0u, combinedModeRow.D[0]);
    }

    [Fact]
    public void DirectGraphicsServicesTextMetricHelpersUsePortableMetricBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint font = 0x300;
        const uint charData = 0x400;
        const uint text = 0x500;
        const uint extent = 0x600;
        const uint constraint = 0x700;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(charData, new byte[2]);
        bus.MapWritableMemory(text, new byte[2]);
        bus.MapWritableMemory(extent, new byte[GraphicsLayouts.TextExtentSize]);
        bus.MapWritableMemory(constraint, new byte[GraphicsLayouts.TextExtentSize]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 4);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 3);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 3);
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.WriteByte(charData, 0xE0);
        memory.WriteByte(charData + 1u, 0xE0);
        memory.WriteByte(text, (byte)'A');
        memory.WriteByte(text + 1u, (byte)'A');
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);

        using var services = CreateHostGraphicsServices(memory);
        var setFont = new M68kCpuState
        {
            A = { [0] = font, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 173
        };
        services.SetFont(setFont);
        Assert.Equal(0u, setFont.D[0]);
        Assert.Equal(173, setFont.Cycles);

        var askSoftStyle = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 175
        };
        services.AskSoftStyle(askSoftStyle);
        Assert.Equal(0xFFFF_FFFFu, askSoftStyle.D[0]);
        Assert.Equal(175, askSoftStyle.Cycles);

        var setSoftStyle = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 5, [1] = 7 },
            Cycles = 177
        };
        services.SetSoftStyle(setSoftStyle);
        Assert.Equal(5u, setSoftStyle.D[0]);
        Assert.Equal(177, setSoftStyle.Cycles);
        Assert.Equal(5, memory.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        var textExtent = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent },
            D = { [0] = 2, [1] = 0x1357_9BDFu },
            Cycles = 181
        };
        services.TextExtent(textExtent);
        Assert.Equal(0u, textExtent.D[0]);
        Assert.Equal(181, textExtent.Cycles);
        Assert.Equal((ushort)8, memory.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));

        memory.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentWidth, 5);
        memory.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentHeight, 4);
        memory.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinX, 0);
        memory.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMinY, unchecked((ushort)-3));
        memory.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxX, 4);
        memory.WriteWord(constraint + (uint)GraphicsLayouts.TextExtentMaxY, 0);
        var textFit = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent, [3] = constraint },
            D = { [0] = 2, [1] = 1, [2] = 5, [3] = 4 },
            Cycles = 191
        };
        services.TextFit(textFit);
        Assert.Equal(1u, textFit.D[0]);
        Assert.Equal(191, textFit.Cycles);

        var fontExtent = new M68kCpuState
        {
            A = { [0] = font, [1] = extent },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 197
        };
        services.FontExtent(fontExtent);
        Assert.Equal(0u, fontExtent.D[0]);
        Assert.Equal(197, fontExtent.Cycles);
        Assert.Equal((ushort)3, memory.ReadWord(extent + (uint)GraphicsLayouts.TextExtentWidth));

        var malformed = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort, [2] = extent + 1u },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 211
        };
        services.TextExtent(malformed);
        Assert.Equal(0xDEAD_BEEFu, malformed.D[0]);
        Assert.Equal(211, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesPixelAndShapeHelpersUsePortableDrawingBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint plane = 0x400;
        const uint points = 0x500;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[0x40]);
        bus.MapWritableMemory(points, new byte[8]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 16);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextHeight, 4);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextBaseline, 2);
        memory.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortFlags, GraphicsLayouts.RastPortFirstDot);

        using var services = CreateHostGraphicsServices(memory);
        var write = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = 3 },
            Cycles = 223
        };
        services.WritePixel(write);
        Assert.Equal(0u, write.D[0]);
        Assert.Equal(223, write.Cycles);

        var read = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = 3 },
            Cycles = 227
        };
        services.ReadPixel(read);
        Assert.Equal(1u, read.D[0]);
        Assert.Equal(227, read.Cycles);

        memory.WriteWord(points, 6);
        memory.WriteWord(points + 2u, 2);
        memory.WriteWord(points + 4u, 6);
        memory.WriteWord(points + 6u, 6);
        var move = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = 2 },
            Cycles = 229
        };
        services.Move(move);
        Assert.Equal(0u, move.D[0]);

        var polyDraw = new M68kCpuState
        {
            A = { [0] = points, [1] = rastPort },
            D = { [0] = 2, [1] = 0x1357_9BDFu },
            Cycles = 233
        };
        services.PolyDraw(polyDraw);
        Assert.Equal(0u, polyDraw.D[0]);
        Assert.Equal(233, polyDraw.Cycles);

        var ellipse = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 8, [1] = 8, [2] = 3, [3] = 2 },
            Cycles = 239
        };
        services.DrawEllipse(ellipse);
        Assert.Equal(0u, ellipse.D[0]);
        Assert.Equal(239, ellipse.Cycles);
        Assert.Contains(Enumerable.Range(0, 0x40), offset => memory.ReadByte(plane + (uint)offset) != 0);

        var moveForClear = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = 2 },
            Cycles = 243
        };
        services.Move(moveForClear);
        var clearEol = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 247
        };
        services.ClearEOL(clearEol);
        Assert.Equal(0u, clearEol.D[0]);
        Assert.Equal(247, clearEol.Cycles);

        var clearScreen = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 251
        };
        services.ClearScreen(clearScreen);
        Assert.Equal(0u, clearScreen.D[0]);
        Assert.Equal(251, clearScreen.Cycles);

        var eraseRect = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 1, [2] = 4, [3] = 4 },
            Cycles = 257
        };
        services.EraseRect(eraseRect);
        Assert.Equal(0u, eraseRect.D[0]);
        Assert.Equal(257, eraseRect.Cycles);

        var scroll = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 15, [5] = 15 },
            Cycles = 263
        };
        services.ScrollRaster(scroll);
        Assert.Equal(0u, scroll.D[0]);
        Assert.Equal(263, scroll.Cycles);

        var scrollBf = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0, [3] = 0, [4] = 15, [5] = 15 },
            Cycles = 269
        };
        services.ScrollRasterBF(scrollBf);
        Assert.Equal(0u, scrollBf.D[0]);
        Assert.Equal(269, scrollBf.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [1] = 0xF000_0000u },
            D = { [0] = 0xDEAD_BEEFu, [1] = 0x2468_ACE0u },
            Cycles = 241
        };
        services.WritePixel(malformed);
        Assert.Equal(0xDEAD_BEEFu, malformed.D[0]);
        Assert.Equal(241, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesAreaAndFloodHelpersUsePortableDrawingBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint plane = 0x400;
        const uint areaInfo = 0x500;
        const uint areaStorage = 0x600;
        const uint areaPattern = 0x700;
        const uint temporaryRaster = 0x800;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[0x40]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(areaStorage, new byte[0x40]);
        bus.MapWritableMemory(areaPattern, new byte[2]);
        bus.MapWritableMemory(temporaryRaster, new byte[0x40]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 0);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaInfo, areaInfo);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, areaPattern);
        memory.WriteWord(areaPattern, 0xFFFF);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 0);

        using var services = CreateHostGraphicsServices(
            memory,
            allocateMemory: (_, _) => temporaryRaster,
            freeMemory: (_, _) => { });
        var initArea = new M68kCpuState
        {
            A = { [0] = areaInfo, [1] = areaStorage },
            D = { [0] = 8, [1] = 0xDEAD_BEEFu },
            Cycles = 277
        };
        services.InitArea(initArea);
        Assert.Equal(0u, initArea.D[0]);
        Assert.Equal(277, initArea.Cycles);

        foreach (var (vector, x, y, cycles) in new[]
        {
            (GraphicsLvo.AreaMove, (short)1, (short)1, 281L),
            (GraphicsLvo.AreaDraw, (short)6, (short)1, 283L),
            (GraphicsLvo.AreaDraw, (short)6, (short)6, 287L),
            (GraphicsLvo.AreaDraw, (short)1, (short)6, 293L)
        })
        {
            var state = new M68kCpuState
            {
                A = { [1] = rastPort },
                D = { [0] = unchecked((uint)(ushort)x), [1] = unchecked((uint)(ushort)y) },
                Cycles = cycles
            };
            if (vector == GraphicsLvo.AreaMove)
                services.AreaMove(state);
            else
                services.AreaDraw(state);
            Assert.Equal(0u, state.D[0]);
            Assert.Equal(cycles, state.Cycles);
        }

        var areaEnd = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 299
        };
        services.AreaEnd(areaEnd);
        Assert.Equal(0u, areaEnd.D[0]);
        Assert.Equal(299, areaEnd.Cycles);
        Assert.Equal((ushort)0, memory.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoCount));
        Assert.NotEqual((byte)0, memory.ReadByte(plane + 6));

        var clearEllipse = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0 },
            Cycles = 303
        };
        services.SetRast(clearEllipse);
        Assert.Equal(0u, clearEllipse.D[0]);

        var areaEllipse = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 4, [1] = 4, [2] = 2, [3] = 2 },
            Cycles = 305
        };
        services.AreaEllipse(areaEllipse);
        Assert.Equal(0u, areaEllipse.D[0]);
        Assert.Equal(305, areaEllipse.Cycles);

        var ellipseEnd = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 306
        };
        services.AreaEnd(ellipseEnd);
        Assert.Equal(0u, ellipseEnd.D[0]);
        Assert.Equal(306, ellipseEnd.Cycles);
        Assert.NotEqual((byte)0, memory.ReadByte(plane + 4));

        var clear = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0 },
            Cycles = 301
        };
        services.SetRast(clear);
        Assert.Equal(0u, clear.D[0]);

        var flood = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 1, [2] = 1, [3] = 0xCAFE_BABEu },
            Cycles = 307
        };
        services.Flood(flood);
        Assert.Equal(1u, flood.D[0]);
        Assert.Equal(307, flood.Cycles);
        Assert.Equal((byte)0xFF, memory.ReadByte(plane));

        var malformed = new M68kCpuState
        {
            A = { [1] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu, [1] = 2 },
            Cycles = 311
        };
        services.AreaMove(malformed);
        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(311, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesBltPatternUsesPortablePatternBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint plane = 0x400;
        const uint areaPattern = 0x500;
        const uint stencil = 0x600;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[0x20]);
        bus.MapWritableMemory(areaPattern, new byte[4]);
        bus.MapWritableMemory(stencil, new byte[4]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortAreaPtrn, areaPattern);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortAreaPtSz, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1);
        memory.WriteWord(areaPattern, 0xAAAA);
        memory.WriteWord(areaPattern + 2u, 0x5555);
        memory.WriteByte(stencil, 0xF0);
        memory.WriteByte(stencil + 2u, 0x0F);

        using var services = CreateHostGraphicsServices(memory);
        var bltPattern = new M68kCpuState
        {
            A = { [0] = stencil, [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 1, [4] = 2 },
            Cycles = 317
        };
        services.BltPattern(bltPattern);
        Assert.Equal(0u, bltPattern.D[0]);
        Assert.Equal(317, bltPattern.Cycles);
        Assert.Equal((byte)0xA0, memory.ReadByte(plane));
        Assert.Equal((byte)0x05, memory.ReadByte(plane + 2u));

        // BltPattern's byteCount is a signed WORD in D4.  A non-positive low
        // word is therefore invalid even when the caller leaves unrelated
        // high-word residue in the 68k register.
        memory.WriteByte(plane, 0);
        memory.WriteByte(plane + 2u, 0);
        var highWordResidue = new M68kCpuState
        {
            A = { [0] = stencil, [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 2, [4] = 0x8000_0000u },
            Cycles = 318
        };
        services.BltPattern(highWordResidue);
        Assert.Equal(0u, highWordResidue.D[0]);
        Assert.Equal(318, highWordResidue.Cycles);
        Assert.Equal((byte)0, memory.ReadByte(plane));
        Assert.Equal((byte)0, memory.ReadByte(plane + 2u));

        var negativeLowWord = new M68kCpuState
        {
            A = { [0] = stencil, [1] = rastPort },
            D = { [0] = 0, [1] = 0, [2] = 7, [3] = 2, [4] = 0xCAFE_FFFEu },
            Cycles = 318
        };
        services.BltPattern(negativeLowWord);
        Assert.Equal(0u, negativeLowWord.D[0]);
        Assert.Equal(318, negativeLowWord.Cycles);
        Assert.Equal((byte)0, memory.ReadByte(plane));
        Assert.Equal((byte)0, memory.ReadByte(plane + 2u));

        var malformed = new M68kCpuState
        {
            A = { [0] = stencil, [1] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu, [1] = 0, [2] = 7, [3] = 1, [4] = 0 },
            Cycles = 319
        };
        services.BltPattern(malformed);
        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(319, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesTemplateAndClearBlitsUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint plane = 0x400;
        const uint template = 0x500;
        const uint clearSpan = 0x600;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(plane, new byte[0x20]);
        bus.MapWritableMemory(template, new byte[4]);
        bus.MapWritableMemory(clearSpan, new byte[8]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 0);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1);
        memory.WriteByte(template, 0xA0);
        memory.WriteByte(template + 2u, 0x50);

        using var services = CreateHostGraphicsServices(memory);
        var bltTemplate = new M68kCpuState
        {
            A = { [0] = template, [1] = rastPort },
            D = { [0] = 0, [1] = 2, [2] = 0, [3] = 0, [4] = 8, [5] = 2 },
            Cycles = 323
        };
        services.BltTemplate(bltTemplate);
        Assert.Equal(0u, bltTemplate.D[0]);
        Assert.Equal(323, bltTemplate.Cycles);
        Assert.Equal((byte)0xA0, memory.ReadByte(plane));
        Assert.Equal((byte)0x50, memory.ReadByte(plane + 2u));

        memory.WriteByte(clearSpan, 0xFF);
        memory.WriteByte(clearSpan + 1u, 0xFF);
        memory.WriteByte(clearSpan + 2u, 0xFF);
        memory.WriteByte(clearSpan + 3u, 0xFF);
        var bltClear = new M68kCpuState
        {
            A = { [1] = clearSpan },
            D = { [0] = 4, [1] = 0, [2] = 0xCAFE_BABEu },
            Cycles = 329
        };
        services.BltClear(bltClear);
        Assert.Equal(0u, bltClear.D[0]);
        Assert.Equal(329, bltClear.Cycles);
        Assert.Equal((byte)0, memory.ReadByte(clearSpan));
        Assert.Equal((byte)0, memory.ReadByte(clearSpan + 3u));

        var malformed = new M68kCpuState
        {
            A = { [0] = template, [1] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu, [1] = 2, [2] = 0, [3] = 0, [4] = 8, [5] = 1 },
            Cycles = 331
        };
        services.BltTemplate(malformed);
        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(331, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesBitmapBlitsUsePortableAndProviderBoundaries()
    {
        var bus = new AmigaBus();
        const uint sourceBitMap = 0x200;
        const uint destinationBitMap = 0x300;
        const uint sourcePlane = 0x400;
        const uint destinationPlane = 0x500;
        const uint sourceRastPort = 0x600;
        const uint destinationRastPort = 0x700;
        bus.MapWritableMemory(sourceBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(destinationBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(sourcePlane, new byte[0x20]);
        bus.MapWritableMemory(destinationPlane, new byte[0x20]);
        bus.MapWritableMemory(sourceRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(destinationRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);

        foreach (var bitMap in new[] { sourceBitMap, destinationBitMap })
        {
            memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
            memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
            memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        }
        memory.WriteLong(sourceBitMap + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane);
        memory.WriteLong(destinationBitMap + (uint)GraphicsLayouts.BitMapPlanes, destinationPlane);
        memory.WriteByte(sourcePlane, 0xFF);
        memory.WriteByte(sourcePlane + 2u, 0xFF);
        memory.WriteLong(sourceRastPort + (uint)GraphicsLayouts.RastPortBitMap, sourceBitMap);
        memory.WriteLong(destinationRastPort + (uint)GraphicsLayouts.RastPortBitMap, destinationBitMap);

        using var services = CreateHostGraphicsServices(memory);
        var bltBitMap = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 8, [5] = 2, [6] = 0x0001_00C0u, [7] = 0x0001_0001u },
            Cycles = 337
        };
        services.BltBitMap(bltBitMap);
        Assert.Equal(1u, bltBitMap.D[0]);
        Assert.Equal(337, bltBitMap.Cycles);
        Assert.Equal((byte)0xFF, memory.ReadByte(destinationPlane));

        var clipBlit = new M68kCpuState
        {
            A = { [0] = sourceRastPort, [1] = destinationRastPort },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 8, [5] = 2, [6] = 0x0001_00C0u },
            Cycles = 341
        };
        services.ClipBlit(clipBlit);
        Assert.Equal(0u, clipBlit.D[0]);
        Assert.Equal(341, clipBlit.Cycles);

        var bitMapRastPort = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationRastPort },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 8, [5] = 2, [6] = 0x0001_00C0u },
            Cycles = 347
        };
        services.BltBitMapRastPort(bitMapRastPort);
        Assert.Equal(1u, bitMapRastPort.D[0]);
        Assert.Equal(347, bitMapRastPort.Cycles);

        var providerCalls = 0;
        using var providerServices = CreateHostGraphicsServices(
            memory,
            bltBitMap: state =>
            {
                providerCalls++;
                state.D[0] = 0x55;
                return state.D[0];
            },
            isRtgBitMap: address => address == sourceBitMap);
        var providerState = new M68kCpuState
        {
            A = { [0] = sourceBitMap, [1] = destinationBitMap },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 349
        };
        providerServices.BltBitMap(providerState);
        Assert.Equal(0x55u, providerState.D[0]);
        Assert.Equal(349, providerState.Cycles);
        Assert.Equal(1, providerCalls);
    }

    [Fact]
    public void DirectGraphicsServicesBitMapLifecycleHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        var nextAllocation = 0x1000u;
        var frees = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var span = unchecked((uint)Math.Max(bytes, 1));
            nextAllocation += (span + 3u) & ~3u;
            bus.MapWritableMemory(address, new byte[Math.Max(bytes, 1)]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++);

        var allocate = new M68kCpuState
        {
            A = { [0] = 0 },
            // AllocBitMap's public dimensions are ULONGs. Keep this lifecycle
            // control at 17x2; full-width rejection has its own dimension matrix.
            D = { [0] = 17u, [1] = 2u, [2] = 2, [3] = 0x05 },
            Cycles = 481
        };
        services.AllocBitMap(allocate);
        var bitMap = allocate.D[0];
        Assert.NotEqual(0u, bitMap);
        Assert.Equal(481, allocate.Cycles);

        var width = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [1] = 8 },
            Cycles = 487
        };
        services.GetBitMapAttr(width);
        Assert.Equal(32u, width.D[0]);
        Assert.Equal(487, width.Cycles);

        var flags = new M68kCpuState { A = { [0] = bitMap }, D = { [1] = 12 } };
        services.GetBitMapAttr(flags);
        Assert.Equal(0x0Cu, flags.D[0]);

        var free = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 491
        };
        services.FreeBitMap(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(491, free.Cycles);
        Assert.True(frees >= 2);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 8u, [1] = 8u },
            Cycles = 499
        };
        services.GetBitMapAttr(malformed);
        Assert.Equal(8u, malformed.D[0]);
        Assert.Equal(499, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesExtendedNodeHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        var nextAllocation = 0x1000u;
        var frees = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var span = unchecked((uint)Math.Max(bytes, 1));
            nextAllocation += (span + 3u) & ~3u;
            bus.MapWritableMemory(address, new byte[Math.Max(bytes, 1)]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++,
            graphicsLibraryBase: 0x00F9_0000u);

        var newView = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewExtraType, [1] = 0x1111_2222u },
            Cycles = 503
        };
        services.GfxNew(newView);
        var viewExtra = newView.D[0];
        Assert.NotEqual(0u, viewExtra);
        Assert.Equal(503, newView.Cycles);
        Assert.Equal((byte)18, bus.ReadByte(viewExtra + (uint)GraphicsLayouts.ExtendedNodeType));
        Assert.Equal((byte)2, bus.ReadByte(viewExtra + (uint)GraphicsLayouts.ExtendedNodeSubsystem));
        Assert.Equal((byte)GraphicsExtendedNodeOperations.ViewExtraType,
            bus.ReadByte(viewExtra + (uint)GraphicsLayouts.ExtendedNodeSubtype));
        Assert.Equal(0x00F9_0000u, bus.ReadLong(viewExtra + (uint)GraphicsLayouts.ExtendedNodeLibrary));
        Assert.Equal(0u, bus.ReadLong(viewExtra + (uint)GraphicsLayouts.ViewExtraView));

        var associateView = new M68kCpuState
        {
            A = { [0] = 0x500, [1] = viewExtra },
            D = { [0] = 0x3333_4444u },
            Cycles = 509
        };
        services.GfxAssociate(associateView);
        Assert.Equal(0u, associateView.D[0]);
        Assert.Equal(509, associateView.Cycles);
        Assert.Equal(0x500u, bus.ReadLong(viewExtra + (uint)GraphicsLayouts.ViewExtraView));

        var lookup = new M68kCpuState
        {
            A = { [0] = 0x500 },
            D = { [0] = 0x5555_6666u },
            Cycles = 511
        };
        services.GfxLookUp(lookup);
        Assert.Equal(viewExtra, lookup.D[0]);
        Assert.Equal(511, lookup.Cycles);

        var newViewPort = new M68kCpuState
        {
            D = { [0] = GraphicsExtendedNodeOperations.ViewPortExtraType },
            Cycles = 517
        };
        services.GfxNew(newViewPort);
        var viewPortExtra = newViewPort.D[0];
        Assert.NotEqual(0u, viewPortExtra);
        Assert.Equal(517, newViewPort.Cycles);
        Assert.Equal((byte)GraphicsExtendedNodeOperations.ViewPortExtraType,
            bus.ReadByte(viewPortExtra + (uint)GraphicsLayouts.ExtendedNodeSubtype));

        var replace = new M68kCpuState
        {
            A = { [0] = 0x500, [1] = viewPortExtra },
            D = { [0] = 0x7777_8888u },
            Cycles = 521
        };
        services.GfxAssociate(replace);
        Assert.Equal(0u, replace.D[0]);
        Assert.Equal(521, replace.Cycles);
        Assert.Equal(0u, bus.ReadLong(viewExtra + (uint)GraphicsLayouts.ViewExtraView));
        Assert.Equal(0x500u, bus.ReadLong(viewPortExtra + (uint)GraphicsLayouts.ViewPortExtraViewPort));

        var replacedLookup = new M68kCpuState { A = { [0] = 0x500 }, D = { [0] = 0x9999_AAAAu } };
        services.GfxLookUp(replacedLookup);
        Assert.Equal(viewPortExtra, replacedLookup.D[0]);

        var freeView = new M68kCpuState
        {
            A = { [0] = viewExtra },
            D = { [0] = 0xBBBB_CCCCu },
            Cycles = 523
        };
        services.GfxFree(freeView);
        Assert.Equal(0u, freeView.D[0]);
        Assert.Equal(523, freeView.Cycles);

        var freeViewPort = new M68kCpuState
        {
            A = { [0] = viewPortExtra },
            D = { [0] = 0xDDDD_EEEEu },
            Cycles = 527
        };
        services.GfxFree(freeViewPort);
        Assert.Equal(0u, freeViewPort.D[0]);
        Assert.Equal(527, freeViewPort.Cycles);
        Assert.Equal(0u, services.GfxLookUp(new M68kCpuState { A = { [0] = 0x500 } }));
        Assert.Equal(2, frees);

        var unsupported = new M68kCpuState { D = { [0] = 5u }, Cycles = 529 };
        services.GfxNew(unsupported);
        Assert.Equal(5u, unsupported.D[0]);
        Assert.Equal(529, unsupported.Cycles);

        var foreignFree = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x1234_5678u },
            Cycles = 531
        };
        services.GfxFree(foreignFree);
        Assert.Equal(0x1234_5678u, foreignFree.D[0]);
        Assert.Equal(531, foreignFree.Cycles);

        var malformedAssociate = new M68kCpuState
        {
            A = { [0] = 0x501, [1] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 533
        };
        services.GfxAssociate(malformedAssociate);
        Assert.Equal(0x89AB_CDEFu, malformedAssociate.D[0]);
        Assert.Equal(533, malformedAssociate.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesDisplayDatabaseAndMonitorHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint buffer = 0x400;
        bus.MapWritableMemory(buffer, new byte[0x100]);
        var nextAllocation = 0x1000u;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var span = unchecked((uint)Math.Max(bytes, 1));
            nextAllocation += (span + 3u) & ~3u;
            bus.MapWritableMemory(address, new byte[Math.Max(bytes, 1)]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate);
        var mode = GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode;

        var find = new M68kCpuState { D = { [0] = mode }, Cycles = 541 };
        services.FindDisplayInfo(find);
        Assert.Equal(mode, find.D[0]);
        Assert.Equal(541, find.Cycles);

        var next = new M68kCpuState
        {
            D = { [0] = GraphicsModeIds.Invalid },
            Cycles = 547
        };
        services.NextDisplayInfo(next);
        Assert.Equal(GraphicsModeIds.DefaultMonitor, next.D[0]);
        Assert.Equal(547, next.Cycles);

        var availability = new M68kCpuState { D = { [0] = mode }, Cycles = 551 };
        services.ModeNotAvailable(availability);
        Assert.Equal(0u, availability.D[0]);
        Assert.Equal(551, availability.Cycles);

        var display = new M68kCpuState
        {
            A = { [0] = mode, [1] = buffer },
            D =
            {
                [0] = GraphicsDisplayDatabase.DisplayInfoChunkSize,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = mode
            },
            Cycles = 557
        };
        services.GetDisplayInfoData(display);
        Assert.Equal(48u, display.D[0]);
        Assert.Equal(GraphicsDisplayDatabase.DtagDisp, bus.ReadLong(buffer));
        Assert.Equal(mode, bus.ReadLong(buffer + 4u));
        Assert.Equal(557, display.Cycles);

        var open = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = mode, [1] = 0xDEAD_BEEFu },
            Cycles = 563
        };
        services.OpenMonitor(open);
        var monitor = open.D[0];
        Assert.NotEqual(0u, monitor);
        Assert.Equal(563, open.Cycles);
        Assert.Equal((ushort)1, bus.ReadWord(monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        var reopen = new M68kCpuState { D = { [0] = mode }, Cycles = 569 };
        services.OpenMonitor(reopen);
        Assert.Equal(monitor, reopen.D[0]);
        Assert.Equal((ushort)2, bus.ReadWord(monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(569, reopen.Cycles);

        var close = new M68kCpuState
        {
            A = { [0] = monitor },
            D = { [0] = 0x1234_5678u },
            Cycles = 571
        };
        services.CloseMonitor(close);
        Assert.Equal(0u, close.D[0]);
        Assert.Equal((ushort)1, bus.ReadWord(monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(571, close.Cycles);

        services.CloseMonitor(close);
        Assert.Equal(0u, close.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(monitor + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        var malformedFind = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 577
        };
        services.FindDisplayInfo(malformedFind);
        Assert.Equal(0xDEAD_BEEFu, malformedFind.D[0]);
        Assert.Equal(577, malformedFind.Cycles);

        var malformedData = new M68kCpuState
        {
            A = { [0] = mode, [1] = 0xF000_0000u },
            D =
            {
                [0] = GraphicsDisplayDatabase.DisplayInfoChunkSize,
                [1] = GraphicsDisplayDatabase.DtagDisp,
                [2] = mode
            },
            Cycles = 581
        };
        services.GetDisplayInfoData(malformedData);
        Assert.Equal((uint)GraphicsDisplayDatabase.DisplayInfoChunkSize, malformedData.D[0]);
        Assert.Equal(581, malformedData.Cycles);

        var malformedClose = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 587
        };
        services.CloseMonitor(malformedClose);
        Assert.Equal(0x89AB_CDEFu, malformedClose.D[0]);
        Assert.Equal(587, malformedClose.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesModeSelectionHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint tags = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        bus.MapWritableMemory(tags, new byte[0x60]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);

        bus.WriteLong(tags + 0, GraphicsDisplayDatabase.BidTagNominalWidth);
        bus.WriteLong(tags + 4, 640);
        bus.WriteLong(tags + 8, GraphicsDisplayDatabase.BidTagNominalHeight);
        bus.WriteLong(tags + 12, 200);
        bus.WriteLong(tags + 16, GraphicsDisplayDatabase.BidTagDesiredWidth);
        bus.WriteLong(tags + 20, 640);
        bus.WriteLong(tags + 24, GraphicsDisplayDatabase.BidTagDesiredHeight);
        bus.WriteLong(tags + 28, 200);
        bus.WriteLong(tags + 32, GraphicsDisplayDatabase.BidTagDepth);
        bus.WriteLong(tags + 36, 5);
        bus.WriteLong(tags + 40, GraphicsDisplayDatabase.BidTagMonitorId);
        bus.WriteLong(tags + 44, GraphicsModeIds.PalMonitor);
        bus.WriteLong(tags + 48, 0);

        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, GraphicsModeIds.HiresMode);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5, 0);

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            isRtgBitMap: address => address == bitMap);

        var best = new M68kCpuState
        {
            A = { [0] = tags },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 593
        };
        services.BestModeIDA(best);
        Assert.Equal(GraphicsModeIds.PalMonitor, best.D[0]);
        Assert.Equal(593, best.Cycles);

        var coerce = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = GraphicsModeIds.PalMonitor, [1] = GraphicsDisplayDatabase.CoercePreserveColors },
            Cycles = 599
        };
        services.CoerceMode(coerce);
        Assert.Equal(GraphicsModeIds.PalMonitor, coerce.D[0]);
        Assert.Equal(599, coerce.Cycles);

        // The provider callback marks this viewport's bitmap as RTG-owned;
        // the portable ModeID query must decline without changing D0/cycles.
        var rtgMode = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 601
        };
        using var providerServices = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            isRtgBitMap: address => address == bitMap);
        providerServices.GetVPModeID(rtgMode);
        Assert.Equal(0x1234_5678u, rtgMode.D[0]);
        Assert.Equal(601, rtgMode.Cycles);

        // A second host without the provider marker proves the native query.
        using var nativeServices = CreateHostGraphicsServices(new HostGuestMemory(bus));
        var nativeMode = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 607
        };
        nativeServices.GetVPModeID(nativeMode);
        Assert.Equal(GraphicsModeIds.PalMonitor | GraphicsModeIds.HiresMode, nativeMode.D[0]);
        Assert.Equal(607, nativeMode.Cycles);

        var malformedBest = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 613
        };
        services.BestModeIDA(malformedBest);
        Assert.Equal(0x89AB_CDEFu, malformedBest.D[0]);
        Assert.Equal(613, malformedBest.Cycles);

        var malformedCoerce = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = GraphicsModeIds.PalMonitor, [1] = GraphicsDisplayDatabase.CoercePreserveColors },
            Cycles = 617
        };
        services.CoerceMode(malformedCoerce);
        Assert.Equal(GraphicsModeIds.PalMonitor, malformedCoerce.D[0]);
        Assert.Equal(617, malformedCoerce.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesDoubleBufferAndViewportBitmapHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint currentBitMap = 0x400;
        const uint nextBitMap = 0x500;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(currentBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(nextBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 640);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, GraphicsModeIds.HiresMode);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, currentBitMap);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        foreach (var bitMap in new[] { currentBitMap, nextBitMap })
        {
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 40);
            bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
            bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 5, 0);
        }

        var nextAllocation = 0x1000u;
        var frees = 0;
        var rebuilds = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var span = unchecked((uint)Math.Max(bytes, 1));
            nextAllocation += (span + 3u) & ~3u;
            bus.MapWritableMemory(address, new byte[Math.Max(bytes, 1)]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            requestDisplayRebuild: () => rebuilds++,
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++);

        var allocate = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 619
        };
        services.AllocDBufInfo(allocate);
        var dbufInfo = allocate.D[0];
        Assert.NotEqual(0u, dbufInfo);
        Assert.Equal(619, allocate.Cycles);
        Assert.Equal(
            (ushort)GraphicsLayouts.ExecMessageSize,
            bus.ReadWord(dbufInfo + (uint)GraphicsLayouts.DBufInfoSafeMessage + (uint)GraphicsLayouts.ExecMessageLength));
        Assert.Equal(
            (ushort)GraphicsLayouts.ExecMessageSize,
            bus.ReadWord(dbufInfo + (uint)GraphicsLayouts.DBufInfoDispMessage + (uint)GraphicsLayouts.ExecMessageLength));

        var change = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap, [2] = dbufInfo },
            D = { [0] = 0x1234_5678u },
            Cycles = 623
        };
        services.ChangeVPBitMap(change);
        Assert.Equal(0u, change.D[0]);
        Assert.Equal(nextBitMap, bus.ReadLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap));
        Assert.Equal(1, rebuilds);
        Assert.Equal(623, change.Cycles);

        var free = new M68kCpuState
        {
            A = { [0] = 0xA0A0_A0A1u, [1] = dbufInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 629
        };
        services.FreeDBufInfo(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(629, free.Cycles);
        Assert.Equal(1, frees);

        var providerCalls = 0;
        using var providerServices = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            changeViewPortBitMap: (_, _) =>
            {
                providerCalls++;
                return 0xA000u;
            },
            isRtgBitMap: address => address == nextBitMap);
        var providerChange = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = nextBitMap },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 631
        };
        providerServices.ChangeVPBitMap(providerChange);
        Assert.Equal(0xA000u, providerChange.D[0]);
        Assert.Equal(1, providerCalls);
        Assert.Equal(631, providerChange.Cycles);

        var malformedFree = new M68kCpuState
        {
            A = { [0] = 0, [1] = 0xF000_0000u },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 637
        };
        services.FreeDBufInfo(malformedFree);
        Assert.Equal(0x2468_ACEDu, malformedFree.D[0]);
        Assert.Equal(637, malformedFree.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesCopperLifecycleHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        const uint cprList = 0x800;
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(cprList, new byte[GraphicsLayouts.CprListSize]);
        bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);

        var nextAllocation = 0x1000u;
        var frees = 0;
        var cprFrees = 0;
        var freeViewPortCalls = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var span = unchecked((uint)Math.Max(bytes, 1));
            nextAllocation += (span + 3u) & ~3u;
            bus.MapWritableMemory(address, new byte[Math.Max(bytes, 1)]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++,
            freeCprList: _ => cprFrees++,
            freeVPortCopLists: _ => freeViewPortCalls++);

        var make = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 641
        };
        services.MakeVPort(make);
        Assert.Equal(0u, make.D[0]);
        Assert.Equal(641, make.Cycles);

        var extra = services.GfxLookUp(new M68kCpuState { A = { [0] = viewPort } });
        Assert.NotEqual(0u, extra);
        Assert.Equal((ushort)1, bus.ReadWord(extra + (uint)GraphicsLayouts.ViewPortExtraFlags));

        var merge = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1234_5678u },
            Cycles = 647
        };
        services.MrgCop(merge);
        Assert.Equal(0u, merge.D[0]);
        Assert.Equal(647, merge.Cycles);

        var free = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 653
        };
        services.FreeVPortCopLists(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(653, free.Cycles);
        Assert.Equal(1, freeViewPortCalls);
        Assert.Equal(1, frees);
        Assert.Equal(0u, services.GfxLookUp(new M68kCpuState { A = { [0] = viewPort } }));

        var freeCpr = new M68kCpuState
        {
            A = { [0] = cprList },
            D = { [0] = 0x1234_5678u },
            Cycles = 655
        };
        services.FreeCprList(freeCpr);
        Assert.Equal(0u, freeCpr.D[0]);
        Assert.Equal(655, freeCpr.Cycles);
        Assert.Equal(1, cprFrees);

        var providerCalls = 0;
        using var providerServices = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            makeViewPort: state =>
            {
                providerCalls++;
                return 0xB000u;
            },
            mergeCopperLists: state =>
            {
                providerCalls++;
                return 0xC000u;
            },
            isRtgBitMap: address => address == bitMap);
        var providerMake = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0x1111_2222u },
            Cycles = 659
        };
        providerServices.MakeVPort(providerMake);
        Assert.Equal(0xB000u, providerMake.D[0]);
        Assert.Equal(659, providerMake.Cycles);

        var providerMerge = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x3333_4444u },
            Cycles = 661
        };
        providerServices.MrgCop(providerMerge);
        Assert.Equal(0xC000u, providerMerge.D[0]);
        Assert.Equal(661, providerMerge.Cycles);
        Assert.Equal(2, providerCalls);

        var malformedMake = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u, [1] = 0xF000_1000u },
            D = { [0] = 0x5555_6666u },
            Cycles = 667
        };
        services.MakeVPort(malformedMake);
        Assert.Equal((uint)GraphicsViewportStatuses.NoViewPortExtra, malformedMake.D[0]);
        Assert.Equal(667, malformedMake.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesUserCopperHelpersUsePortableOwnershipBoundary()
    {
        var bus = new AmigaBus();
        const uint userList = 0x100;
        const uint allocationBase = 0x1000;
        bus.MapWritableMemory(userList, new byte[GraphicsLayouts.UCopListSize]);

        var nextAllocation = allocationBase;
        var frees = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var length = Math.Max(bytes, 1);
            nextAllocation += ((uint)length + 0x0Fu) & ~0x0Fu;
            bus.MapWritableMemory(address, new byte[length]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++);

        var init = new M68kCpuState
        {
            A = { [0] = userList },
            D = { [0] = 2 },
            Cycles = 757
        };
        services.UCopperListInit(init);
        var copList = init.D[0];
        Assert.NotEqual(0u, copList);
        Assert.Equal(757, init.Cycles);
        Assert.Equal(copList, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(copList, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListCopList));

        var move = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0x00DF_F180u, [1] = 0x1234 },
            Cycles = 761
        };
        services.CMove(move);
        Assert.Equal(0u, move.D[0]);
        Assert.Equal(761, move.Cycles);
        var instructions = bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopIns);
        Assert.Equal((ushort)0, bus.ReadWord(instructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)0x0180, bus.ReadWord(instructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)0x1234, bus.ReadWord(instructions + (uint)GraphicsLayouts.CopInsArg1));

        var bump = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 763
        };
        services.CBump(bump);
        Assert.Equal(0u, bump.D[0]);
        Assert.Equal(763, bump.Cycles);
        Assert.Equal((ushort)1, bus.ReadWord(copList + (uint)GraphicsLayouts.CopListCount));

        var wait = new M68kCpuState
        {
            A = { [1] = userList },
            D = { [0] = 42, [1] = 12 },
            Cycles = 767
        };
        services.CWait(wait);
        Assert.Equal(0u, wait.D[0]);
        Assert.Equal(767, wait.Cycles);
        var nextInstructions = bus.ReadLong(copList + (uint)GraphicsLayouts.CopListCopPtr);
        Assert.Equal((ushort)1, bus.ReadWord(nextInstructions + (uint)GraphicsLayouts.CopInsOpCode));
        Assert.Equal((ushort)42, bus.ReadWord(nextInstructions + (uint)GraphicsLayouts.CopInsArg0));
        Assert.Equal((ushort)12, bus.ReadWord(nextInstructions + (uint)GraphicsLayouts.CopInsArg1));

        var free = new M68kCpuState
        {
            A = { [0] = copList },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 773
        };
        services.FreeCopList(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(773, free.Cycles);
        Assert.Equal(2, frees);
        Assert.Equal(0u, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListFirstCopList));
        Assert.Equal(0u, bus.ReadLong(userList + (uint)GraphicsLayouts.UCopListCopList));

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 779
        };
        services.FreeCopList(malformed);
        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(779, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesRegionHelpersUsePortableOwnershipBoundary()
    {
        var bus = new AmigaBus();
        const uint rectangle = 0x200;
        const uint clipRectangle = 0x220;
        const uint secondRectangle = 0x240;
        bus.MapWritableMemory(rectangle, new byte[GraphicsLayouts.RectangleSize]);
        bus.MapWritableMemory(clipRectangle, new byte[GraphicsLayouts.RectangleSize]);
        bus.MapWritableMemory(secondRectangle, new byte[GraphicsLayouts.RectangleSize]);

        static void WriteRectangle(AmigaBus bus, uint address, short left, short top, short right, short bottom)
        {
            bus.WriteWord(address + 0u, unchecked((ushort)left));
            bus.WriteWord(address + 2u, unchecked((ushort)top));
            bus.WriteWord(address + 4u, unchecked((ushort)right));
            bus.WriteWord(address + 6u, unchecked((ushort)bottom));
        }

        bool ContainsRegion(uint region, short x, short y)
        {
            var originX = unchecked((short)bus.ReadWord(region + (uint)GraphicsLayouts.RegionBounds));
            var originY = unchecked((short)bus.ReadWord(region + (uint)GraphicsLayouts.RegionBounds + 2u));
            var node = bus.ReadLong(region + (uint)GraphicsLayouts.RegionRectangle);
            for (var count = 0; node != 0 && count < 4096; count++)
            {
                var minX = originX + unchecked((short)bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds));
                var minY = originY + unchecked((short)bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 2u));
                var maxX = originX + unchecked((short)bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 4u));
                var maxY = originY + unchecked((short)bus.ReadWord(node + (uint)GraphicsLayouts.RegionRectangleBounds + 6u));
                if (x >= minX && x <= maxX && y >= minY && y <= maxY)
                    return true;

                node = bus.ReadLong(node + (uint)GraphicsLayouts.RegionRectangleNext);
            }

            return false;
        }

        WriteRectangle(bus, rectangle, 1, 1, 5, 5);
        WriteRectangle(bus, clipRectangle, 2, 2, 4, 4);
        WriteRectangle(bus, secondRectangle, 4, 4, 6, 6);

        var nextAllocation = 0x1000u;
        var frees = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var length = Math.Max(bytes, 1);
            nextAllocation += ((uint)length + 0x0Fu) & ~0x0Fu;
            bus.MapWritableMemory(address, new byte[length]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++);

        var newRegion = new M68kCpuState { D = { [0] = 0xCAFE_BABEu }, Cycles = 787 };
        services.NewRegion(newRegion);
        var region = newRegion.D[0];
        Assert.NotEqual(0u, region);
        Assert.Equal(787, newRegion.Cycles);

        var add = new M68kCpuState
        {
            A = { [0] = region, [1] = rectangle },
            D = { [0] = 0x1111_2222u },
            Cycles = 791
        };
        services.OrRectRegion(add);
        Assert.Equal(1u, add.D[0]);
        Assert.True(ContainsRegion(region, 1, 1));
        Assert.True(ContainsRegion(region, 5, 5));
        Assert.Equal(791, add.Cycles);

        var intersect = new M68kCpuState
        {
            A = { [0] = region, [1] = clipRectangle },
            D = { [0] = 0x3333_4444u },
            Cycles = 793
        };
        services.AndRectRegion(intersect);
        Assert.Equal(0u, intersect.D[0]);
        Assert.False(ContainsRegion(region, 1, 1));
        Assert.True(ContainsRegion(region, 4, 4));

        var sourceState = new M68kCpuState { D = { [0] = 0x5555_6666u }, Cycles = 797 };
        services.NewRegion(sourceState);
        var source = sourceState.D[0];
        var sourceAdd = new M68kCpuState
        {
            A = { [0] = source, [1] = secondRectangle },
            Cycles = 799
        };
        services.OrRectRegion(sourceAdd);
        Assert.Equal(1u, sourceAdd.D[0]);

        var union = new M68kCpuState
        {
            A = { [0] = source, [1] = region },
            D = { [0] = 0x7777_8888u },
            Cycles = 803
        };
        services.OrRegionRegion(union);
        Assert.Equal(1u, union.D[0]);
        Assert.True(ContainsRegion(region, 6, 6));
        Assert.Equal(803, union.Cycles);

        var xor = new M68kCpuState
        {
            A = { [0] = source, [1] = region },
            Cycles = 809
        };
        services.XorRegionRegion(xor);
        Assert.Equal(1u, xor.D[0]);

        var clearRect = new M68kCpuState
        {
            A = { [0] = region, [1] = secondRectangle },
            D = { [0] = 0x9999_AAAAu },
            Cycles = 811
        };
        services.ClearRectRegion(clearRect);
        Assert.Equal(1u, clearRect.D[0]);
        Assert.False(ContainsRegion(region, 6, 6));

        var clear = new M68kCpuState
        {
            A = { [0] = source },
            D = { [0] = 0xBBBB_CCCCu },
            Cycles = 817
        };
        services.ClearRegion(clear);
        Assert.Equal(0u, clear.D[0]);
        Assert.Equal(0u, bus.ReadLong(source + (uint)GraphicsLayouts.RegionRectangle));

        var dispose = new M68kCpuState
        {
            A = { [0] = region },
            D = { [0] = 0xDDDD_EEEEu },
            Cycles = 821
        };
        services.DisposeRegion(dispose);
        Assert.Equal(0u, dispose.D[0]);
        Assert.Equal(821, dispose.Cycles);
        Assert.True(frees >= 3);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 823
        };
        services.DisposeRegion(malformed);
        Assert.Equal(0x1357_9BDFu, malformed.D[0]);
        Assert.Equal(823, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesColorMapHelpersUsePortableRgbBoundary()
    {
        var bus = new AmigaBus();
        const uint rgb32Output = 0x900;
        bus.MapWritableMemory(rgb32Output, new byte[0x40]);

        var nextAllocation = 0x1000u;
        var frees = 0;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var length = Math.Max(bytes, 1);
            nextAllocation += ((uint)length + 0x0Fu) & ~0x0Fu;
            bus.MapWritableMemory(address, new byte[length]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: (_, _) => frees++);

        var allocate = new M68kCpuState
        {
            D = { [0] = 4, [1] = 0xCAFE_BABEu },
            Cycles = 829
        };
        services.GetColorMap(allocate);
        var colorMap = allocate.D[0];
        Assert.NotEqual(0u, colorMap);
        Assert.Equal(829, allocate.Cycles);
        Assert.Equal((ushort)4, bus.ReadWord(colorMap + (uint)GraphicsLayouts.ColorMapCount));

        var setRgb4 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1, [1] = 0x0A, [2] = 0x05, [3] = 0x0F },
            Cycles = 833
        };
        services.SetRGB4CM(setRgb4);
        Assert.Equal(0u, setRgb4.D[0]);
        Assert.Equal(833, setRgb4.Cycles);

        var getRgb4 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 1 },
            Cycles = 839
        };
        services.GetRGB4(getRgb4);
        Assert.Equal(0x0A5Fu, getRgb4.D[0]);
        Assert.Equal(839, getRgb4.Cycles);

        var setRgb32 = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 2, [1] = 0xAB00_0000u, [2] = 0x3412_0000u, [3] = 0xFF80_0000u },
            Cycles = 841
        };
        services.SetRGB32CM(setRgb32);
        Assert.Equal(0u, setRgb32.D[0]);
        Assert.Equal(841, setRgb32.Cycles);

        var getRgb32 = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = rgb32Output },
            D = { [0] = 1, [1] = 2, [2] = 0xDEAD_BEEFu },
            Cycles = 843
        };
        services.GetRGB32(getRgb32);
        Assert.Equal(0u, getRgb32.D[0]);
        Assert.Equal(843, getRgb32.Cycles);
        Assert.Equal(0xA0A0_A0A0u, bus.ReadLong(rgb32Output));
        Assert.Equal(0x5050_5050u, bus.ReadLong(rgb32Output + 4u));
        Assert.Equal(0xF0F0_F0F0u, bus.ReadLong(rgb32Output + 8u));
        Assert.Equal(0xABAB_ABABu, bus.ReadLong(rgb32Output + 12u));
        Assert.Equal(0x3434_3434u, bus.ReadLong(rgb32Output + 16u));
        Assert.Equal(0xFFFF_FFFFu, bus.ReadLong(rgb32Output + 20u));

        var free = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0x1234_5678u },
            Cycles = 847
        };
        services.FreeColorMap(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(847, free.Cycles);
        Assert.Equal(3, frees);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 851
        };
        services.FreeColorMap(malformed);
        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(851, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesViewportPaletteHelpersUsePortableRgbBoundary()
    {
        var bus = new AmigaBus();
        const uint viewPort = 0x200;
        const uint rgb4 = 0x900;
        const uint rgb32 = 0xA00;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rgb4, new byte[0x20]);
        bus.MapWritableMemory(rgb32, new byte[0x40]);

        var nextAllocation = 0x1000u;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var length = Math.Max(bytes, 1);
            nextAllocation += ((uint)length + 0x0Fu) & ~0x0Fu;
            bus.MapWritableMemory(address, new byte[length]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: static (_, _) => { });

        var allocate = new M68kCpuState { D = { [0] = 4 } };
        services.GetColorMap(allocate);
        var colorMap = allocate.D[0];
        Assert.NotEqual(0u, colorMap);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, colorMap);

        bus.WriteWord(rgb4, 0x0123);
        bus.WriteWord(rgb4 + 2, 0x0ABC);
        var loadRgb4 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rgb4 },
            D = { [0] = 2, [1] = 0xCAFE_BABEu },
            Cycles = 857
        };
        services.LoadRGB4(loadRgb4);
        Assert.Equal(0u, loadRgb4.D[0]);
        Assert.Equal(857, loadRgb4.Cycles);

        var getFirst = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 0 } };
        services.GetRGB4(getFirst);
        Assert.Equal(0x0123u, getFirst.D[0]);
        var getSecond = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 1 } };
        services.GetRGB4(getSecond);
        Assert.Equal(0x0ABCu, getSecond.D[0]);

        var setRgb4 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 2, [1] = 0x0D, [2] = 0x06, [3] = 0x01 },
            Cycles = 863
        };
        services.SetRGB4(setRgb4);
        Assert.Equal(0u, setRgb4.D[0]);
        Assert.Equal(863, setRgb4.Cycles);
        var getSet = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 2 } };
        services.GetRGB4(getSet);
        Assert.Equal(0x0D61u, getSet.D[0]);

        bus.WriteLong(rgb32, (1u << 16) | 1u);
        bus.WriteLong(rgb32 + 4, 0xAB00_0000u);
        bus.WriteLong(rgb32 + 8, 0x3400_0000u);
        bus.WriteLong(rgb32 + 12, 0xFF00_0000u);
        bus.WriteLong(rgb32 + 16, 0);
        var loadRgb32 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = rgb32 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 869
        };
        services.LoadRGB32(loadRgb32);
        Assert.Equal(0u, loadRgb32.D[0]);
        Assert.Equal(869, loadRgb32.Cycles);
        var getLoaded32 = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 1 } };
        services.GetRGB4(getLoaded32);
        Assert.Equal(0xA3Fu, getLoaded32.D[0]);

        var setRgb32 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 3, [1] = 0x1200_0000u, [2] = 0x5600_0000u, [3] = 0xAB00_0000u },
            Cycles = 877
        };
        services.SetRGB32(setRgb32);
        Assert.Equal(0u, setRgb32.D[0]);
        Assert.Equal(877, setRgb32.Cycles);
        var getSet32 = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 3 } };
        services.GetRGB4(getSet32);
        Assert.Equal(0x15Au, getSet32.D[0]);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u, [1] = 0xF000_1000u },
            D = { [0] = 1, [1] = 0xDEAD_BEEFu },
            Cycles = 883
        };
        services.LoadRGB4(malformed);
        Assert.Equal(1u, malformed.D[0]);
        Assert.Equal(883, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesViewportPaletteHelpersPreserveRtgProviderBoundary()
    {
        var bus = new AmigaBus();
        const uint viewPort = 0x400;
        const uint rasInfo = 0x440;
        const uint rtgBitMap = 0x480;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(rtgBitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);

        var loadCalls = 0;
        var setCalls = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            loadRgb4: _ => loadCalls++,
            setRgb4: _ => setCalls++,
            isRtgBitMap: bitMap => bitMap == rtgBitMap);

        var loadRgb4 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = 0x900 },
            D = { [0] = 1, [1] = 0xCAFE_BABEu },
            Cycles = 887
        };
        services.LoadRGB4(loadRgb4);
        Assert.Equal(1, loadCalls);
        Assert.Equal(0u, loadRgb4.D[0]);
        Assert.Equal(887, loadRgb4.Cycles);

        var setRgb4 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 2, [1] = 0x0F, [2] = 0x02, [3] = 0x01 },
            Cycles = 889
        };
        services.SetRGB4(setRgb4);
        Assert.Equal(1, setCalls);
        Assert.Equal(0u, setRgb4.D[0]);
        Assert.Equal(889, setRgb4.Cycles);

        var loadRgb32 = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = 0xA00 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 891
        };
        services.LoadRGB32(loadRgb32);
        Assert.Equal(0x1357_9BDFu, loadRgb32.D[0]);
        Assert.Equal(891, loadRgb32.Cycles);

        var setRgb32 = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 2, [1] = 0xAB00_0000u, [2] = 0x3400_0000u, [3] = 0xFF00_0000u },
            Cycles = 893
        };
        services.SetRGB32(setRgb32);
        Assert.Equal(2u, setRgb32.D[0]);
        Assert.Equal(893, setRgb32.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesPalettePenHelpersUsePortableOwnershipBoundary()
    {
        var bus = new AmigaBus();
        const uint tags = 0x900;
        bus.MapWritableMemory(tags, new byte[0x20]);

        var nextAllocation = 0x1000u;
        uint Allocate(int bytes, uint _)
        {
            var address = nextAllocation;
            var length = Math.Max(bytes, 1);
            nextAllocation += ((uint)length + 0x0Fu) & ~0x0Fu;
            bus.MapWritableMemory(address, new byte[length]);
            return address;
        }

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: Allocate,
            freeMemory: static (_, _) => { });

        var allocate = new M68kCpuState { D = { [0] = 4 } };
        services.GetColorMap(allocate);
        var colorMap = allocate.D[0];
        Assert.NotEqual(0u, colorMap);

        var attach = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = 0x400 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 907
        };
        services.AttachPalExtra(attach);
        Assert.Equal(0u, attach.D[0]);
        Assert.Equal(907, attach.Cycles);

        var obtain = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = uint.MaxValue, [1] = 0xFFFF_FFFFu, [2] = 0, [3] = 0, [4] = 0 },
            Cycles = 911
        };
        services.ObtainPen(obtain);
        Assert.Equal(3u, obtain.D[0]);
        Assert.Equal(911, obtain.Cycles);

        var find = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 0xDEAD_BEEFu, [1] = 0xFFFF_FFFFu, [2] = 0, [3] = 0, [4] = 3 },
            Cycles = 913
        };
        services.FindColor(find);
        Assert.Equal(3u, find.D[0]);
        Assert.Equal(913, find.Cycles);

        var release = new M68kCpuState
        {
            A = { [0] = colorMap },
            D = { [0] = 3, [1] = 0x1357_9BDFu },
            Cycles = 917
        };
        services.ReleasePen(release);
        Assert.Equal(0u, release.D[0]);
        Assert.Equal(917, release.Cycles);

        var best = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = 0 },
            D = { [0] = 0xFFFF_FFFFu, [1] = 0x1200_0000u, [2] = 0x3400_0000u, [3] = 0x5600_0000u },
            Cycles = 919
        };
        services.ObtainBestPenA(best);
        Assert.Equal(3u, best.D[0]);
        Assert.Equal(919, best.Cycles);

        var bestRelease = new M68kCpuState { A = { [0] = colorMap }, D = { [0] = 0 } };
        services.ReleasePen(bestRelease);
        Assert.Equal(0u, bestRelease.D[0]);

        bus.WriteLong(tags, 0x8000_0005u); // VTAG_BORDERBLANK_SET
        bus.WriteLong(tags + 4, 1);
        bus.WriteLong(tags + 8, 0);
        var video = new M68kCpuState
        {
            A = { [0] = colorMap, [1] = tags },
            D = { [0] = 0xABCD_EF01u },
            Cycles = 923
        };
        services.VideoControl(video);
        Assert.Equal(0u, video.D[0]);
        Assert.Equal(923, video.Cycles);
        Assert.Equal((byte)0x04, bus.ReadByte(colorMap + (uint)GraphicsLayouts.ColorMapFlags));

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x2468_ACE0u, [1] = 1, [2] = 2, [3] = 3, [4] = 3 },
            Cycles = 929
        };
        services.FindColor(malformed);
        Assert.Equal(uint.MaxValue, malformed.D[0]);
        Assert.Equal(929, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesSpriteAndGelsHelpersUsePortableGuestBoundary()
    {
        var bus = new AmigaBus();
        const uint guestBase = 0xEA00;
        const uint head = guestBase;
        const uint tail = guestBase + 0x100;
        const uint gelsInfo = guestBase + 0x200;
        const uint collisionTable = guestBase + 0x300;
        const uint rastPort = guestBase + 0x400;
        const uint sprite = guestBase + 0x500;
        const uint imageData = guestBase + 0x700;
        bus.MapWritableMemory(guestBase, new byte[0x1000]);

        bus.WriteLong(gelsInfo + (uint)GraphicsLayouts.GelsInfoCollisionHandler, collisionTable);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteY, 10);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.VSpriteX, 20);
        bus.WriteWord(sprite + (uint)GraphicsLayouts.SimpleSpriteHeight, 1);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData, imageData);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));

        var get = new M68kCpuState
        {
            A = { [0] = sprite },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 937
        };
        services.GetSprite(get);
        Assert.Equal(0u, get.D[0]);
        Assert.Equal((ushort)0, bus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteNum));
        Assert.Equal(937, get.Cycles);

        var move = new M68kCpuState
        {
            A = { [0] = 0, [1] = sprite },
            D = { [0] = 12, [1] = 34 },
            Cycles = 941
        };
        services.MoveSprite(move);
        Assert.Equal(0u, move.D[0]);
        Assert.Equal((ushort)12, bus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteX));
        Assert.Equal((ushort)34, bus.ReadWord(sprite + (uint)GraphicsLayouts.SimpleSpriteY));
        Assert.Equal(941, move.Cycles);

        var change = new M68kCpuState
        {
            A = { [0] = 0, [1] = sprite, [2] = imageData },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 943
        };
        services.ChangeSprite(change);
        Assert.Equal(0u, change.D[0]);
        Assert.Equal(imageData, bus.ReadLong(sprite + (uint)GraphicsLayouts.SimpleSpritePosCtlData));
        Assert.Equal(943, change.Cycles);

        var free = new M68kCpuState { D = { [0] = 0 }, Cycles = 947 };
        services.FreeSprite(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(947, free.Cycles);

        var init = new M68kCpuState
        {
            A = { [0] = head, [1] = tail, [2] = gelsInfo },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 953
        };
        services.InitGels(init);
        Assert.Equal(0u, init.D[0]);
        Assert.Equal(tail, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(head, bus.ReadLong(tail + (uint)GraphicsLayouts.VSpritePrev));
        Assert.Equal(953, init.Cycles);

        var collision = new M68kCpuState
        {
            A = { [0] = 0x1234_5678u, [1] = gelsInfo },
            D = { [0] = 2 },
            Cycles = 957
        };
        services.SetCollision(collision);
        Assert.Equal(0u, collision.D[0]);
        Assert.Equal(0x1234_5678u, bus.ReadLong(collisionTable + 8));
        Assert.Equal(957, collision.Cycles);

        var add = new M68kCpuState
        {
            A = { [0] = sprite, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 961
        };
        // The simple-sprite image pointer shares the first VSprite link word;
        // clear the link pair before reusing this guest envelope as a VSprite.
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpriteNext, 0);
        bus.WriteLong(sprite + (uint)GraphicsLayouts.VSpritePrev, 0);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortGelsInfo, gelsInfo);
        services.AddVSprite(add);
        Assert.Equal(0u, add.D[0]);
        Assert.Equal(sprite, bus.ReadLong(head + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(tail, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(961, add.Cycles);

        var sort = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 967
        };
        services.SortGList(sort);
        Assert.Equal(0u, sort.D[0]);
        Assert.Equal(967, sort.Cycles);

        var remove = new M68kCpuState
        {
            A = { [0] = sprite },
            D = { [0] = 0x2468_ACEEu },
            Cycles = 971
        };
        services.RemVSprite(remove);
        Assert.Equal(0u, remove.D[0]);
        Assert.Equal(0u, bus.ReadLong(sprite + (uint)GraphicsLayouts.VSpriteNext));
        Assert.Equal(971, remove.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesBlitterHelpersUseExplicitSchedulerBoundary()
    {
        var bus = new AmigaBus();
        const uint node = 0x200;
        bus.MapWritableMemory(node, new byte[GraphicsLayouts.BltNodeSize]);
        bus.WriteLong(node + (uint)GraphicsLayouts.BltNodeFunction, 0x4000);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBlitSize, 0x1234);
        bus.WriteWord(node + (uint)GraphicsLayouts.BltNodeBeamSync, 0xFF80);

        var ownCount = 0;
        var disownCount = 0;
        var waitCount = 0;
        var queued = new List<(uint Address, bool BeamSynchronized, short BeamSync)>();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            ownBlitter: () => ownCount++,
            disownBlitter: () => disownCount++,
            waitBlit: () => waitCount++,
            submitQueuedBlit: (address, beamSynchronized, beamSync) =>
                queued.Add((address, beamSynchronized, beamSync)));

        var own = new M68kCpuState { D = { [0] = 0xFFFF_FFFFu }, Cycles = 977 };
        services.OwnBlitter(own);
        var wait = new M68kCpuState { D = { [0] = 0xFFFF_FFFFu }, Cycles = 979 };
        services.WaitBlit(wait);
        var disown = new M68kCpuState { D = { [0] = 0xFFFF_FFFFu }, Cycles = 983 };
        services.DisownBlitter(disown);

        Assert.Equal(1, ownCount);
        Assert.Equal(1, waitCount);
        Assert.Equal(1, disownCount);
        Assert.Equal(0u, own.D[0]);
        Assert.Equal(0u, wait.D[0]);
        Assert.Equal(0u, disown.D[0]);
        Assert.Equal(977, own.Cycles);
        Assert.Equal(979, wait.Cycles);
        Assert.Equal(983, disown.Cycles);

        var qblit = new M68kCpuState { A = { [1] = node }, D = { [0] = 0xFFFF_FFFFu }, Cycles = 987 };
        services.QBlit(qblit);
        var qbsBlit = new M68kCpuState { A = { [1] = node }, D = { [0] = 0xFFFF_FFFFu }, Cycles = 991 };
        services.QBSBlit(qbsBlit);

        Assert.Equal(0u, qblit.D[0]);
        Assert.Equal(0u, qbsBlit.D[0]);
        Assert.Equal(987, qblit.Cycles);
        Assert.Equal(991, qbsBlit.Cycles);
        Assert.Equal(
            new[]
            {
                (node, false, (short)-128),
                (node, true, (short)-128)
            },
            queued);
    }

    [Fact]
    public void DirectGraphicsServicesLayerHelpersUseExplicitProviderBoundary()
    {
        var bus = new AmigaBus();
        var calls = new List<string>();
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            lockLayerRom: address => calls.Add($"lock:{address:X}"),
            attemptLockLayerRom: address =>
            {
                calls.Add($"try:{address:X}");
                return address == 0x120;
            },
            unlockLayerRom: address => calls.Add($"unlock:{address:X}"),
            syncSBitMap: address =>
            {
                calls.Add($"sync:{address:X}");
                return address == 0x120;
            },
            copySBitMap: address =>
            {
                calls.Add($"copy:{address:X}");
                return address == 0x120;
            });

        var lockState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x120 },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 997
        };
        services.LockLayerRom(lockState);
        Assert.Equal(0u, lockState.D[0]);
        Assert.Equal(997, lockState.Cycles);

        var tryState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x120 },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 1001
        };
        services.AttemptLockLayerRom(tryState);
        Assert.Equal(1u, tryState.D[0]);
        Assert.Equal(1001, tryState.Cycles);

        var rejectedState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x121 },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 1003
        };
        services.AttemptLockLayerRom(rejectedState);
        Assert.Equal(0xFFFF_FFFFu, rejectedState.D[0]);
        Assert.Equal(1003, rejectedState.Cycles);

        var syncState = new M68kCpuState
        {
            A = { [0] = 0x120 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 1007
        };
        services.SyncSBitMap(syncState);
        Assert.Equal(0u, syncState.D[0]);
        Assert.Equal(1007, syncState.Cycles);

        var copyState = new M68kCpuState
        {
            A = { [0] = 0x120 },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 1011
        };
        services.CopySBitMap(copyState);
        Assert.Equal(0u, copyState.D[0]);
        Assert.Equal(1011, copyState.Cycles);

        var unlockState = new M68kCpuState
        {
            A = { [0] = 0xDEAD_BEEFu, [5] = 0x120 },
            D = { [0] = 0xFFFF_FFFFu },
            Cycles = 1013
        };
        services.UnlockLayerRom(unlockState);
        Assert.Equal(0u, unlockState.D[0]);
        Assert.Equal(1013, unlockState.Cycles);

        Assert.Equal(
            new[] { "lock:120", "try:120", "sync:120", "copy:120", "unlock:120" },
            calls);
    }

    [Fact]
    public void DirectGraphicsServicesMaskedBlitUsesPortablePlanarBoundary()
    {
        var bus = new AmigaBus();
        const uint source = 0x300;
        const uint destination = 0x380;
        const uint rastPort = 0x420;
        const uint sourcePlane = 0x500;
        const uint destinationPlane = 0x600;
        const uint blitMask = 0x800;
        bus.MapWritableMemory(source, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(destination, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(sourcePlane, new byte[0x20]);
        bus.MapWritableMemory(destinationPlane, new byte[0x20]);
        bus.MapWritableMemory(blitMask, new byte[0x20]);
        bus.WriteWord(source + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(source + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(source + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(source + (uint)GraphicsLayouts.BitMapPlanes, sourcePlane);
        bus.WriteWord(destination + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        bus.WriteWord(destination + (uint)GraphicsLayouts.BitMapRows, 2);
        bus.WriteByte(destination + (uint)GraphicsLayouts.BitMapDepth, 1, 0);
        bus.WriteLong(destination + (uint)GraphicsLayouts.BitMapPlanes, destinationPlane);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, destination);
        bus.WriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0xFF,
            0);
        bus.WriteByte(sourcePlane, 0xF0, 0);
        bus.WriteByte(destinationPlane, 0xAA, 0);
        bus.WriteByte(blitMask, 0xCC, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        var state = new M68kCpuState
        {
            A = { [0] = source, [1] = rastPort, [2] = blitMask },
            D = { [0] = 0, [1] = 0, [2] = 0, [3] = 0, [4] = 8, [5] = 1, [6] = 0xC0 },
            Cycles = 1017
        };
        services.BltMaskBitMapRastPort(state);

        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0xE2, bus.ReadByte(destinationPlane));
        Assert.Equal(1017, state.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u, [1] = rastPort, [2] = blitMask },
            D = { [0] = 0x1357_9BDFu, [1] = 0, [2] = 0, [3] = 0, [4] = 8, [5] = 1, [6] = 0xC0 },
            Cycles = 1021
        };
        services.BltMaskBitMapRastPort(malformed);
        Assert.Equal(0x1357_9BDFu, malformed.D[0]);
        Assert.Equal(1021, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesTimingHelpersUsePortableCycleBoundary()
    {
        var bus = new AmigaBus();
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        bus.MapWritableMemory(rasInfo, new byte[GraphicsLayouts.RasInfoSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);

        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            waitTof: state => state.Cycles += 5,
            waitForViewportBottom: (_, cycle) => cycle + 7,
            beamPosition: cycle => (ushort)(cycle + 3));

        var tof = new M68kCpuState
        {
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 673
        };
        services.WaitTOF(tof);
        Assert.Equal(0u, tof.D[0]);
        Assert.Equal(678, tof.Cycles);

        var bovp = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 681
        };
        services.WaitBOVP(bovp);
        Assert.Equal(0u, bovp.D[0]);
        Assert.Equal(688, bovp.Cycles);

        var beam = new M68kCpuState
        {
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 691
        };
        services.VBeamPos(beam);
        Assert.Equal(694u, beam.D[0]);
        Assert.Equal(691, beam.Cycles);

        using var providerServices = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            waitForViewportBottom: (_, cycle) => cycle + 13,
            isRtgBitMap: address => address == bitMap);
        var providerBovp = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 697
        };
        providerServices.WaitBOVP(providerBovp);
        Assert.Equal(0x89AB_CDEFu, providerBovp.D[0]);
        Assert.Equal(697, providerBovp.Cycles);

        var malformedBovp = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 701
        };
        services.WaitBOVP(malformedBovp);
        Assert.Equal(0x2468_ACEDu, malformedBovp.D[0]);
        Assert.Equal(701, malformedBovp.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesViewportTimingAndChipRevisionHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint view = 0x100;
        const uint viewPort = 0x200;
        const uint rasInfo = 0x300;
        const uint bitMap = 0x400;
        bus.MapWritableMemory(view, new byte[GraphicsLayouts.ViewSize]);
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
