        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDWidth, 320);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 256);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDxOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDyOffset, 0);
        bus.WriteWord(viewPort + (uint)GraphicsLayouts.ViewPortModes, 0);
        bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoNext, 0);
        bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, bitMap);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        bus.WriteWord(rasInfo + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 4);
        bus.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 256);
        bus.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1, 0);

        var rebuilds = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            requestDisplayRebuild: () => rebuilds++,
            calcIvg: (_, _) => 19,
            setChipRev: requested => requested | 0x100u);

        var scroll = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 709
        };
        services.ScrollVPort(scroll);
        Assert.Equal(0u, scroll.D[0]);
        Assert.Equal(709, scroll.Cycles);
        Assert.Equal(1, rebuilds);

        var calc = new M68kCpuState
        {
            A = { [0] = view, [1] = viewPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 713
        };
        services.CalcIVG(calc);
        Assert.Equal(19u, calc.D[0]);
        Assert.Equal(713, calc.Cycles);

        var chip = new M68kCpuState
        {
            D = { [0] = 3, [1] = 0xDEAD_BEEFu },
            Cycles = 719
        };
        services.SetChipRev(chip);
        Assert.Equal(0x103u, chip.D[0]);
        Assert.Equal(719, chip.Cycles);

        using var providerServices = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            requestDisplayRebuild: () => rebuilds++,
            isRtgBitMap: address => address == bitMap);
        var providerScroll = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 727
        };
        providerServices.ScrollVPort(providerScroll);
        Assert.Equal(0x89AB_CDEFu, providerScroll.D[0]);
        Assert.Equal(727, providerScroll.Cycles);

        var malformedCalc = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u, [1] = viewPort },
            D = { [0] = 0x2468_ACEDu },
            Cycles = 733
        };
        services.CalcIVG(malformedCalc);
        Assert.Equal(0x2468_ACEDu, malformedCalc.D[0]);
        Assert.Equal(733, malformedCalc.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesRastPortAttributeHelpersUsePortableTransactionalBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x100;
        const uint setTags = 0x300;
        const uint getTags = 0x400;
        const uint outputs = 0x500;
        const uint rollbackTags = 0x600;
        const uint font = 0x700;
        const uint fontStrike = 0x800;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(setTags, new byte[0x70]);
        bus.MapWritableMemory(getTags, new byte[0x60]);
        bus.MapWritableMemory(outputs, new byte[0x40]);
        bus.MapWritableMemory(rollbackTags, new byte[0x20]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(fontStrike, new byte[0x20]);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32, 0);
        bus.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127, 0);
        bus.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, fontStrike);
        bus.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        bus.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);

        void WriteTag(uint address, uint tag, uint data)
        {
            bus.WriteLong(address, tag);
            bus.WriteLong(address + 4u, data);
        }

        WriteTag(setTags + 0x00, GraphicsRastPortAttributeOperations.RptagAPen, 7);
        WriteTag(setTags + 0x08, GraphicsRastPortAttributeOperations.RptagBPen, 2);
        WriteTag(setTags + 0x10, GraphicsRastPortAttributeOperations.RptagDrMd, 1);
        WriteTag(setTags + 0x18, GraphicsRastPortAttributeOperations.RptagWriteMask, 7);
        WriteTag(setTags + 0x20, GraphicsRastPortAttributeOperations.RptagOutlinePen, 6);
        WriteTag(setTags + 0x28, GraphicsRastPortAttributeOperations.RptagMaxPen, 3);
        WriteTag(setTags + 0x30, GraphicsRastPortAttributeOperations.RptagSoftStyle, 4);
        WriteTag(setTags + 0x38, GraphicsRastPortAttributeOperations.TagDone, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        var set = new M68kCpuState
        {
            A = { [0] = setTags, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 739
        };
        services.SetRPAttrsA(set);
        Assert.Equal(0u, set.D[0]);
        Assert.Equal(739, set.Cycles);
        Assert.Equal((byte)7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)2, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)1, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode));
        Assert.Equal((byte)3, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal((byte)6, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortOutlinePen));
        Assert.Equal((byte)4, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));

        WriteTag(getTags + 0x00, GraphicsRastPortAttributeOperations.RptagAPen, outputs + 0x00);
        WriteTag(getTags + 0x08, GraphicsRastPortAttributeOperations.RptagBPen, outputs + 0x04);
        WriteTag(getTags + 0x10, GraphicsRastPortAttributeOperations.RptagDrMd, outputs + 0x08);
        WriteTag(getTags + 0x18, GraphicsRastPortAttributeOperations.RptagWriteMask, outputs + 0x0C);
        WriteTag(getTags + 0x20, GraphicsRastPortAttributeOperations.RptagOutlinePen, outputs + 0x10);
        WriteTag(getTags + 0x28, GraphicsRastPortAttributeOperations.RptagMaxPen, outputs + 0x14);
        WriteTag(getTags + 0x30, GraphicsRastPortAttributeOperations.RptagSoftStyle, outputs + 0x18);
        WriteTag(getTags + 0x38, GraphicsRastPortAttributeOperations.TagDone, 0);

        var get = new M68kCpuState
        {
            A = { [0] = getTags, [1] = rastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 743
        };
        services.GetRPAttrsA(get);
        Assert.Equal(0u, get.D[0]);
        Assert.Equal(743, get.Cycles);
        Assert.Equal(7u, bus.ReadLong(outputs + 0x00));
        Assert.Equal(2u, bus.ReadLong(outputs + 0x04));
        Assert.Equal(1u, bus.ReadLong(outputs + 0x08));
        Assert.Equal(3u, bus.ReadLong(outputs + 0x0C));
        Assert.Equal(6u, bus.ReadLong(outputs + 0x10));
        Assert.Equal(4u, bus.ReadLong(outputs + 0x14));
        Assert.Equal(uint.MaxValue, bus.ReadLong(outputs + 0x18));

        WriteTag(rollbackTags + 0x00, GraphicsRastPortAttributeOperations.RptagAPen, 9);
        WriteTag(rollbackTags + 0x08, GraphicsRastPortAttributeOperations.RptagFont, 0);
        WriteTag(rollbackTags + 0x10, GraphicsRastPortAttributeOperations.TagDone, 0);
        var rollbackSet = new M68kCpuState
        {
            A = { [0] = rollbackTags, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 749
        };
        services.SetRPAttrsA(rollbackSet);
        Assert.Equal(0xDEAD_BEEFu, rollbackSet.D[0]);
        Assert.Equal(7u, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal(749, rollbackSet.Cycles);

        WriteTag(rollbackTags + 0x00, GraphicsRastPortAttributeOperations.RptagAPen, outputs);
        WriteTag(rollbackTags + 0x08, GraphicsRastPortAttributeOperations.RptagFont, 0xF000_0000u);
        WriteTag(rollbackTags + 0x10, GraphicsRastPortAttributeOperations.TagDone, 0);
        bus.WriteLong(outputs, 0xA5A5_A5A5u);
        var rollbackGet = new M68kCpuState
        {
            A = { [0] = rollbackTags, [1] = rastPort },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 751
        };
        services.GetRPAttrsA(rollbackGet);
        Assert.Equal(0x89AB_CDEFu, rollbackGet.D[0]);
        Assert.Equal(0xA5A5_A5A5u, bus.ReadLong(outputs));
        Assert.Equal(751, rollbackGet.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesBitmapUtilityHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint raster = 0x600;
        bus.MapWritableMemory(raster, new byte[0x40]);
        var freeCount = 0;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (_, _) => raster,
            freeMemory: (_, _) => freeCount++);

        var allocate = new M68kCpuState
        {
            D = { [0] = 16, [1] = 2 },
            Cycles = 467
        };
        services.AllocRaster(allocate);
        Assert.Equal(raster, allocate.D[0]);
        Assert.Equal(467, allocate.Cycles);

        var free = new M68kCpuState
        {
            A = { [0] = raster },
            D = { [0] = 16, [1] = 2 },
            Cycles = 469
        };
        services.FreeRaster(free);
        Assert.Equal(0u, free.D[0]);
        Assert.Equal(469, free.Cycles);
        Assert.Equal(1, freeCount);

        var scaler = new M68kCpuState
        {
            D = { [0] = 100, [1] = 2, [2] = 1 },
            Cycles = 473
        };
        services.ScalerDiv(scaler);
        Assert.Equal(200u, scaler.D[0]);
        Assert.Equal(473, scaler.Cycles);

        var malformedScale = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 479
        };
        services.BitMapScale(malformedScale);
        Assert.Equal(0xA5A5_5A5Au, malformedScale.D[0]);
        Assert.Equal(479, malformedScale.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesRastPortStateHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));

        var initialize = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0x0102_0304u },
            Cycles = 433
        };
        services.InitRastPort(initialize);
        Assert.Equal(0u, initialize.D[0]);
        Assert.Equal(433, initialize.Cycles);

        var setPensMode = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 5, [1] = 6, [2] = 2 },
            Cycles = 439
        };
        services.SetABPenDrMd(setPensMode);
        Assert.Equal(0u, setPensMode.D[0]);
        Assert.Equal(439, setPensMode.Cycles);

        var getForeground = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 0x1111_2222u },
            Cycles = 443
        };
        services.GetAPen(getForeground);
        Assert.Equal(5u, getForeground.D[0]);
        Assert.Equal(443, getForeground.Cycles);

        var getBackground = new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0x3333_4444u } };
        services.GetBPen(getBackground);
        Assert.Equal(6u, getBackground.D[0]);

        var getMode = new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0x5555_6666u } };
        services.GetDrMd(getMode);
        Assert.Equal(2u, getMode.D[0]);

        var setMask = new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0xA5_0003C7u }, Cycles = 449 };
        Assert.Equal(uint.MaxValue, services.SetWriteMask(setMask));
        Assert.Equal(uint.MaxValue, setMask.D[0]);
        Assert.Equal(449, setMask.Cycles);
        Assert.Equal((byte)0xC7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));

        var setMaxPen = new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 12 }, Cycles = 451 };
        services.SetMaxPen(setMaxPen);
        Assert.Equal(0u, setMaxPen.D[0]);
        Assert.Equal(451, setMaxPen.Cycles);

        var setOutline = new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 9 }, Cycles = 457 };
        services.SetOutlinePen(setOutline);
        Assert.Equal(0xFFu, setOutline.D[0]);
        Assert.Equal(457, setOutline.Cycles);

        var getOutline = new M68kCpuState { A = { [0] = rastPort }, D = { [0] = 0x7777_8888u } };
        services.GetOutlinePen(getOutline);
        Assert.Equal(9u, getOutline.D[0]);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 461
        };
        services.GetAPen(malformed);
        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(461, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesSetRpAttrsWriteMaskKeepsOnlyTheGuestByte()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint tags = 0x300;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(tags, new byte[0x10]);
        bus.WriteLong(tags, GraphicsRastPortAttributeOperations.RptagWriteMask);
        bus.WriteLong(tags + 4u, 0xA5_0003C7u);
        bus.WriteLong(tags + 8u, GraphicsRastPortAttributeOperations.TagDone);
        bus.WriteLong(tags + 12u, 0);

        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
