        };

        services.SetRPAttrsA(state);

        Assert.Equal(0u, state.D[0]);
        Assert.Equal(461, state.Cycles);
        Assert.Equal((byte)0xC7, bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
    }

    [Fact]
    public void DirectGraphicsServicesFontLifecycleHelpersUsePortableBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint font = 0x400;
        const uint name = 0x600;
        const uint textAttr = 0x700;
        const uint taggedTextAttr = 0x780;
        const uint charData = 0x900;
        const uint extension = 0xB00;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
        bus.MapWritableMemory(name, new byte[0x20]);
        bus.MapWritableMemory(textAttr, new byte[GraphicsLayouts.TextAttrSize + 4]);
        bus.MapWritableMemory(taggedTextAttr, new byte[GraphicsLayouts.TextAttrSize + 4]);
        bus.MapWritableMemory(charData, new byte[0x40]);
        bus.MapWritableMemory(extension, new byte[0x100]);
        var memory = new HostGuestMemory(bus);

        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 8);
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0);
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontFlags, 1);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 8);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 7);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontBoldSmear, 1);
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, 32);
        memory.WriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, 127);
        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.WriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, 0);
        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontCharSpace, 0);
        memory.WriteLong(font + (uint)GraphicsLayouts.TextFontCharKern, 0);

        var fontName = "topaz.font";
        for (var index = 0; index < fontName.Length; index++)
            memory.WriteByte(name + (uint)index, (byte)fontName[index]);
        memory.WriteByte(name + (uint)fontName.Length, 0);
        memory.WriteLong(textAttr + (uint)GraphicsLayouts.TextAttrName, name);
        memory.WriteWord(textAttr + (uint)GraphicsLayouts.TextAttrYSize, 8);
        memory.WriteByte(textAttr + (uint)GraphicsLayouts.TextAttrStyle, 0);
        memory.WriteByte(textAttr + (uint)GraphicsLayouts.TextAttrFlags, 1);
        memory.WriteLong(taggedTextAttr + (uint)GraphicsLayouts.TextAttrName, name);
        memory.WriteWord(taggedTextAttr + (uint)GraphicsLayouts.TextAttrYSize, 8);
        memory.WriteByte(taggedTextAttr + (uint)GraphicsLayouts.TextAttrStyle, 0x80);
        memory.WriteByte(taggedTextAttr + (uint)GraphicsLayouts.TextAttrFlags, 1);
        memory.WriteLong(taggedTextAttr + (uint)GraphicsLayouts.TextAttrSize, 0x901);

        var frees = 0;
        using var services = CreateHostGraphicsServices(
            memory,
            allocateMemory: (_, _) => extension,
            freeMemory: (_, _) => frees++);

        var weight = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = textAttr },
            D = { [0] = 0x0101_0202u },
            Cycles = 397
        };
        services.WeighTAMatch(weight);
        Assert.Equal(32767u, weight.D[0]);
        Assert.Equal(397, weight.Cycles);

        var add = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0x1111_2222u },
            Cycles = 401
        };
        services.AddFont(add);
        Assert.Equal(0u, add.D[0]);
        Assert.Equal(401, add.Cycles);

        var malformedTagged = new M68kCpuState
        {
            A = { [0] = taggedTextAttr },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 402
        };
        services.OpenFont(malformedTagged);
        Assert.Equal(0xCAFE_BABEu, malformedTagged.D[0]);
        Assert.Equal(402, malformedTagged.Cycles);

        var open = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0x3333_4444u },
            Cycles = 403
        };
        services.OpenFont(open);
        Assert.Equal(font, open.D[0]);
        Assert.Equal(403, open.Cycles);
        Assert.Equal((ushort)1, memory.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortFont, font);
        var ask = new M68kCpuState
        {
            A = { [0] = textAttr, [1] = rastPort },
            D = { [0] = 0x5555_6666u },
            Cycles = 407
        };
        services.AskFont(ask);
        Assert.Equal(0u, ask.D[0]);
        Assert.Equal(407, ask.Cycles);
        Assert.Equal(name, memory.ReadLong(textAttr + (uint)GraphicsLayouts.TextAttrName));

        var close = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0x7777_8888u },
            Cycles = 409
        };
        services.CloseFont(close);
        Assert.Equal(0u, close.D[0]);
        Assert.Equal(409, close.Cycles);
        Assert.Equal((ushort)0, memory.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        var extend = new M68kCpuState
        {
            A = { [0] = font, [1] = 0 },
            D = { [0] = 0x9999_AAAAu },
            Cycles = 413
        };
        services.ExtendFont(extend);
        Assert.Equal(1u, extend.D[0]);
        Assert.Equal(413, extend.Cycles);
        Assert.Equal(extension, memory.ReadLong(font + (uint)GraphicsLayouts.TextFontExtension));

        var strip = new M68kCpuState
        {
            A = { [0] = font },
            D = { [0] = 0xBBBB_CCCCu },
            Cycles = 419
        };
        services.StripFont(strip);
        Assert.Equal(0u, strip.D[0]);
        Assert.Equal(419, strip.Cycles);
        Assert.Equal(1, frees);
        Assert.Equal(0u, memory.ReadLong(font + (uint)GraphicsLayouts.TextFontExtension));

        var remove = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xDDDD_EEEEu },
            Cycles = 421
        };
        services.RemFont(remove);
        Assert.Equal(0u, remove.D[0]);
        Assert.Equal(421, remove.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = 0xF000_0000u },
            D = { [0] = 0x1234_5678u },
            Cycles = 431
        };
        services.OpenFont(malformed);
        Assert.Equal(0x1234_5678u, malformed.D[0]);
        Assert.Equal(431, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesPixelArrayHelpersUsePortableConversionBoundary()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint bitMap = 0x300;
        const uint planes = 0x400;
        const uint sourceLine = 0x600;
        const uint destinationLine = 0x700;
        const uint sourceArray = 0x800;
        const uint destinationArray = 0x900;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(planes, new byte[0x200]);
        bus.MapWritableMemory(sourceLine, new byte[0x40]);
        bus.MapWritableMemory(destinationLine, new byte[0x40]);
        bus.MapWritableMemory(sourceArray, new byte[0x100]);
        bus.MapWritableMemory(destinationArray, new byte[0x100]);
        var memory = new HostGuestMemory(bus);

        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 2);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, planes);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4u, planes + 0x100u);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.WriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3);
        memory.WriteByte(sourceLine, 1);
        memory.WriteByte(sourceLine + 1u, 2);
        memory.WriteByte(sourceLine + 2u, 3);
        memory.WriteByte(sourceArray, 1);
        memory.WriteByte(sourceArray + 1u, 2);
        memory.WriteByte(sourceArray + 2u, 3);
        memory.WriteByte(sourceArray + 16u, 3);
        memory.WriteByte(sourceArray + 17u, 2);
        memory.WriteByte(sourceArray + 18u, 1);

        using var services = CreateHostGraphicsServices(memory);
        var writeLine = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceLine },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 353
        };
        services.WritePixelLine8(writeLine);
        Assert.Equal(4u, writeLine.D[0]);
        Assert.Equal(353, writeLine.Cycles);

        var readLine = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = destinationLine },
            D = { [0] = 0, [1] = 0, [2] = 4 },
            Cycles = 359
        };
        services.ReadPixelLine8(readLine);
        Assert.Equal(4u, readLine.D[0]);
        Assert.Equal(359, readLine.Cycles);
        Assert.Equal((byte)1, memory.ReadByte(destinationLine));
        Assert.Equal((byte)2, memory.ReadByte(destinationLine + 1u));

        var writeArray = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2 },
            Cycles = 361
        };
        services.WritePixelArray8(writeArray);
        Assert.Equal(8u, writeArray.D[0]);
        Assert.Equal(361, writeArray.Cycles);

        var readArray = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = destinationArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2 },
            Cycles = 367
        };
        services.ReadPixelArray8(readArray);
        Assert.Equal(8u, readArray.D[0]);
        Assert.Equal(367, readArray.Cycles);

        var chunky = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = sourceArray },
            D = { [0] = 0, [1] = 0, [2] = 3, [3] = 2, [4] = 16 },
            Cycles = 373
        };
        services.WriteChunkyPixels(chunky);
        Assert.Equal(0u, chunky.D[0]);
        Assert.Equal(373, chunky.Cycles);

        var malformed = new M68kCpuState
        {
            A = { [0] = rastPort, [2] = 0xF000_0000u },
            D = { [0] = 0x89AB_CDEFu, [1] = 0, [2] = 4 },
            Cycles = 379
        };
        services.WritePixelLine8(malformed);
        // A valid portable RastPort owns the call even when the caller's
        // byte array is unmapped; the classic failure result is -1 in D0.
        Assert.Equal(0xFFFF_FFFFu, malformed.D[0]);
        Assert.Equal(379, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesLayeredRasterHelpersStayWithTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        const uint layer = 0x180;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, layer);

        var provider = new RecordingLayerRasterBackend();
        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);

        var text = new M68kCpuState
        {
            A = { [0] = 0x300, [1] = rastPort },
            D = { [0] = 0xCAFE_0005u, },
            Cycles = 91
        };
        services.Text(text);
        Assert.Equal(0u, text.D[0]);
        Assert.Equal(91, text.Cycles);
        Assert.Equal((rastPort, 0x300u, (short)5), provider.TextRuns.Single());

        var draw = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 7, [1] = 9 },
            Cycles = 91
        };
        services.Draw(draw);
        Assert.Equal(0u, draw.D[0]);
        Assert.Equal(91, draw.Cycles);
        Assert.Equal((rastPort, (short)7, (short)9), provider.Drawn.Single());

        var setRast = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 3 },
            Cycles = 91
        };
        services.SetRast(setRast);
        Assert.Equal(0u, setRast.D[0]);
        Assert.Equal(91, setRast.Cycles);
        Assert.Equal((rastPort, 3u), provider.Rasters.Single());

        var fill = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 2, [2] = 11, [3] = 12 },
            Cycles = 91
        };
        services.RectFill(fill);
        Assert.Equal(0u, fill.D[0]);
        Assert.Equal(91, fill.Cycles);
        Assert.Equal(
            (rastPort, (short)1, (short)2, (short)11, (short)12),
            provider.RectFills.Single());
    }

    [Fact]
    public void DirectGraphicsServicesLeavesDeclinedLayerGatewayBlitsUnclaimed()
    {
        var bus = new AmigaBus();
        const uint sourceRastPort = 0x200;
        const uint destinationRastPort = 0x280;
        const uint layer = 0x180;
        bus.MapWritableMemory(
            sourceRastPort,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(
            destinationRastPort,
            new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.WriteLong(
            sourceRastPort + (uint)GraphicsLayouts.RastPortLayer,
            layer);
        bus.WriteLong(
            destinationRastPort + (uint)GraphicsLayouts.RastPortLayer,
            layer + 0x20u);

        var clipBlitCalls = 0;
        var bitmapRastPortCalls = 0;
        var provider = new RecordingLayerGatewayBackend
        {
            RasterLvo = GraphicsLvo.ClipBlit,
            ClaimRaster = false
        };
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            clipBlit: _ =>
            {
                clipBlitCalls++;
                return 1;
            },
            bltBitMapRastPort: _ =>
            {
                bitmapRastPortCalls++;
                return 1;
            },
            layers: provider);

        var clip = new M68kCpuState
        {
            A = { [0] = sourceRastPort, [1] = destinationRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        services.ClipBlit(clip);
        Assert.Equal(0xCAFE_BABEu, clip.D[0]);
        Assert.Equal(211, clip.Cycles);
        Assert.Equal(0, clipBlitCalls);

        var bitmapRastPort = new M68kCpuState
        {
            A = { [0] = 0x300, [1] = destinationRastPort },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 223
        };
        services.BltBitMapRastPort(bitmapRastPort);
        Assert.Equal(0x1357_9BDFu, bitmapRastPort.D[0]);
        Assert.Equal(223, bitmapRastPort.Cycles);
        Assert.Equal(0, bitmapRastPortCalls);
    }

