    [Fact]
    public void DirectGraphicsServicesStructureInitializersShareTheAtomicPortableBoundary()
    {
        var bus = new AmigaBus();
        const uint bitMap = 0x2C0;
        const uint areaInfo = 0x340;
        const uint areaBuffer = 0x400;
        const uint tmpRas = 0x500;
        const uint tmpBuffer = 0x580;
        bus.MapWritableMemory(bitMap, new byte[GraphicsLayouts.BitMapSize]);
        bus.MapWritableMemory(areaInfo, new byte[GraphicsLayouts.AreaInfoSize]);
        bus.MapWritableMemory(areaBuffer, new byte[20]);
        bus.MapWritableMemory(tmpRas, new byte[GraphicsLayouts.TmpRasSize]);
        bus.MapWritableMemory(tmpBuffer, new byte[64]);
        var memory = new HostGuestMemory(bus);
        for (var offset = 0; offset < GraphicsLayouts.BitMapSize; offset++)
            memory.WriteByte(bitMap + (uint)offset, 0xCC);
        for (var offset = 0; offset < GraphicsLayouts.AreaInfoSize; offset++)
            memory.WriteByte(areaInfo + (uint)offset, 0xCC);
        for (var offset = 0; offset < GraphicsLayouts.TmpRasSize; offset++)
            memory.WriteByte(tmpRas + (uint)offset, 0xCC);

        using var services = CreateHostGraphicsServices(memory);
        var bitMapState = new M68kCpuState
        {
            A = { [0] = bitMap },
            D = { [0] = 2, [1] = 320, [2] = 200, [3] = 0xCAFE_BABEu },
            Cycles = 139
        };
        services.InitBitMap(bitMapState);

        Assert.Equal(0u, bitMapState.D[0]);
        Assert.Equal(139, bitMapState.Cycles);
        Assert.Equal(40, memory.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow));
        Assert.Equal(200, memory.ReadWord(bitMap + (uint)GraphicsLayouts.BitMapRows));
        Assert.Equal((byte)0x08, memory.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapFlags));
        Assert.Equal(2, memory.ReadByte(bitMap + (uint)GraphicsLayouts.BitMapDepth));
        // InitBitMap publishes the envelope fields while retaining caller-owned
        // plane links for the subsequent allocation/attachment step.
        Assert.Equal(0xCCCC_CCCCu, memory.ReadLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes));

        var areaState = new M68kCpuState
        {
            A = { [0] = areaInfo, [1] = areaBuffer },
            D = { [0] = 4, [1] = 0x1357_9BDFu },
            Cycles = 149
        };
        services.InitArea(areaState);

        Assert.Equal(0u, areaState.D[0]);
        Assert.Equal(149, areaState.Cycles);
        Assert.Equal(areaBuffer, memory.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorTable));
        Assert.Equal(areaBuffer, memory.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoVectorPointer));
        Assert.Equal(areaBuffer + 16u, memory.ReadLong(areaInfo + (uint)GraphicsLayouts.AreaInfoFlagTable));
        Assert.Equal(4, memory.ReadWord(areaInfo + (uint)GraphicsLayouts.AreaInfoMaxCount));

        var tmpState = new M68kCpuState
        {
            A = { [0] = tmpRas, [1] = tmpBuffer },
            D = { [0] = 64, [1] = 0x2468_ACE0u },
            Cycles = 157
        };
        services.InitTmpRas(tmpState);

        Assert.Equal(0u, tmpState.D[0]);
        Assert.Equal(157, tmpState.Cycles);
        Assert.Equal(tmpBuffer, memory.ReadLong(tmpRas + (uint)GraphicsLayouts.TmpRasRasPtr));
        Assert.Equal(64u, memory.ReadLong(tmpRas + (uint)GraphicsLayouts.TmpRasByteCount));

        var malformed = new M68kCpuState
        {
            A = { [0] = bitMap + 1u },
            D = { [0] = 0x89AB_CDEFu },
            Cycles = 163
        };
        services.InitBitMap(malformed);

        Assert.Equal(0x89AB_CDEFu, malformed.D[0]);
        Assert.Equal(163, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesInitVPortUsesThePortableLifecycleAndProjectionBoundary()
    {
        var bus = new AmigaBus();
        const uint viewPort = 0x240;
        bus.MapWritableMemory(viewPort, new byte[GraphicsLayouts.ViewPortSize]);
        var memory = new HostGuestMemory(bus);
        for (var offset = 0; offset < GraphicsLayouts.ViewPortSize; offset++)
            memory.WriteByte(viewPort + (uint)offset, 0xCC);

        var projected = 0u;
        using var services = CreateHostGraphicsServices(
            memory,
            initializeCompatibilityViewPort: address => projected = address);
        var state = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 113
        };

        services.InitVPort(state);

        Assert.Equal(viewPort, projected);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(113, state.Cycles);
        Assert.Equal(0u, memory.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortNext));
        Assert.Equal(0u, memory.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap));
        Assert.Equal(0u, memory.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortDspIns));
        Assert.Equal(0u, memory.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortSprIns));
        Assert.Equal(0u, memory.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortClrIns));
        Assert.Equal(0u, memory.ReadLong(viewPort + (uint)GraphicsLayouts.ViewPortUCopIns));
        Assert.Equal(
            GraphicsLayouts.ViewPortDefaultSpritePriorities,
            memory.ReadByte(viewPort + (uint)GraphicsLayouts.ViewPortSpritePriorities));

        projected = 0;
        var malformed = new M68kCpuState
        {
            A = { [0] = viewPort + 1u },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 127
        };

        services.InitVPort(malformed);

        Assert.Equal(0u, projected);
        Assert.Equal(0x1357_9BDFu, malformed.D[0]);
        Assert.Equal(127, malformed.Cycles);
    }

    [Fact]
    public void DirectGraphicsServicesLoadViewUsesTheSchedulerLifecycleBoundary()
    {
        var bus = new AmigaBus();
        var memory = new HostGuestMemory(bus);
        var published = uint.MaxValue;
        using var services = CreateHostGraphicsServices(
            memory,
            loadView: state => published = state.A[1]);
        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 131
        };

        services.LoadView(state);

        Assert.Equal(0u, published);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(131, state.Cycles);

        published = uint.MaxValue;
        var malformed = new M68kCpuState
        {
            A = { [1] = 1 },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 137
        };

        services.LoadView(malformed);

        Assert.Equal(uint.MaxValue, published);
        Assert.Equal(0x1357_9BDFu, malformed.D[0]);
        Assert.Equal(137, malformed.Cycles);
    }

