    [Fact]
    public void HostGraphicsServicesForwardsLayeredClearAndScrollToTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);
        var provider = new RecordingLayerRasterBackend();

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 2, [1] = unchecked((uint)(short)-3), [2] = 4, [3] = 5, [4] = 17, [5] = 23 },
            Cycles = 191
        };

        services.Invoke(state, (int)GraphicsLvo.ScrollRaster);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(191, state.Cycles);
        Assert.Equal((rastPort, (short)2, (short)-3, (short)4, (short)5, (short)17, (short)23),
            provider.Scrolls.Single());

        state.D[0] = unchecked((uint)(short)-6);
        state.D[1] = 7;
        state.D[2] = 8;
        state.D[3] = 9;
        state.D[4] = 25;
        state.D[5] = 31;
        services.Invoke(state, (int)GraphicsLvo.ScrollRasterBF);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(191, state.Cycles);
        Assert.Equal((rastPort, (short)-6, (short)7, (short)8, (short)9, (short)25, (short)31),
            provider.ScrollBackfills.Single());

        state.D[0] = 0xDEAD_BEEFu;
        services.Invoke(state, (int)GraphicsLvo.ClearEOL);
        Assert.Equal(0u, state.D[0]);
        services.Invoke(state, (int)GraphicsLvo.ClearScreen);
        Assert.Equal(0u, state.D[0]);

        state.D[0] = 1;
        state.D[1] = 2;
        state.D[2] = 29;
        state.D[3] = 37;
        services.Invoke(state, (int)GraphicsLvo.EraseRect);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((rastPort, (short)1, (short)2, (short)29, (short)37),
            provider.Erasures.Single());
        Assert.Equal(1, provider.ClearEolCount);
        Assert.Equal(1, provider.ClearScreenCount);
    }

    [Fact]
    public void HostGraphicsServicesForwardsLayeredAreaFloodAndPolyDrawToTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);
        var provider = new RecordingLayerRasterBackend { FloodResult = 1 };

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            A = { [0] = 0x500, [1] = rastPort },
            D = { [0] = 3, [1] = 4 },
            Cycles = 211
        };

        services.Invoke(state, (int)GraphicsLvo.PolyDraw);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(211, state.Cycles);
        Assert.Equal((rastPort, (ushort)3, 0x500u), provider.PolyDraws.Single());

        state.D[0] = 7;
        state.D[1] = 8;
        services.Invoke(state, (int)GraphicsLvo.AreaMove);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((rastPort, (short)7, (short)8), provider.AreaMoves.Single());

        state.D[0] = 9;
        state.D[1] = 10;
        services.Invoke(state, (int)GraphicsLvo.AreaDraw);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((rastPort, (short)9, (short)10), provider.AreaDraws.Single());

        state.D[0] = 20;
        state.D[1] = 21;
        state.D[2] = 6;
        state.D[3] = 5;
        services.Invoke(state, (int)GraphicsLvo.AreaEllipse);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((rastPort, (short)20, (short)21, (short)6, (short)5),
            provider.AreaEllipses.Single());

        services.Invoke(state, (int)GraphicsLvo.AreaEnd);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(1, provider.AreaEndCount);

        state.D[0] = 12;
        state.D[1] = 13;
        state.D[2] = 1;
        services.Invoke(state, (int)GraphicsLvo.Flood);
        Assert.Equal(1u, state.D[0]);
        Assert.Equal((rastPort, 1u, (short)12, (short)13), provider.Floods.Single());
    }

    [Fact]
    public void HostGraphicsServicesForwardsEmptyLayeredPolyDrawToTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);
        var provider = new RecordingLayerRasterBackend();

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            // The empty stream must not dereference the point table; the
            // provider still owns the readable layered RastPort boundary.
            A = { [0] = 0xFFFF_FFFEu, [1] = rastPort },
            D = { [0] = 0xCAFE_0000u },
            Cycles = 223
        };

        services.Invoke(state, (int)GraphicsLvo.PolyDraw);

        Assert.Equal(0u, state.D[0]);
        Assert.Equal(223, state.Cycles);
        Assert.Equal((rastPort, (ushort)0, 0xFFFF_FFFEu), provider.PolyDraws.Single());
    }

