    [Fact]
    public void HostGraphicsServicesNormalizesUBYTEMintermsForLayeredBlits()
    {
        var bus = new AmigaBus();
        const uint sourceRastPort = 0x240;
        const uint destinationRastPort = 0x200;
        bus.MapWritableMemory(sourceRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        bus.MapWritableMemory(destinationRastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(
            sourceRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x190);
        memory.WriteLong(
            destinationRastPort + (uint)GraphicsLayouts.RastPortLayer,
            0x180);
        var provider = new RecordingLayerRasterBackend { BltResult = 1 };

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            A = { [0] = sourceRastPort, [1] = destinationRastPort, [2] = 0x700 },
            D = { [0] = 1, [1] = 2, [2] = 3, [3] = 4, [4] = 17, [5] = 19, [6] = 0x0001_00CAu },
            Cycles = 227
        };

        services.Invoke(state, (int)GraphicsLvo.ClipBlit);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(227, state.Cycles);
        Assert.Equal(
            (sourceRastPort, (short)1, (short)2, destinationRastPort, (short)3,
                (short)4, (short)17, (short)19, (byte)0xCA),
            provider.ClipBlits.Single());

        state.A[0] = 0x600;
        state.D[0] = 5;
        state.D[1] = 6;
        state.D[2] = 7;
        state.D[3] = 8;
        state.D[4] = 21;
        state.D[5] = 23;
        state.D[6] = 0x0002_00CCu;
        services.Invoke(state, (int)GraphicsLvo.BltBitMapRastPort);
        Assert.Equal(1u, state.D[0]);
        Assert.Equal(
            (0x600u, (short)5, (short)6, destinationRastPort, (short)7, (short)8,
                (short)21, (short)23, (byte)0xCC),
            provider.BltBitMapRastPorts.Single());

        state.A[0] = 0x600;
        state.A[2] = 0x800;
        state.D[0] = 9;
        state.D[1] = 10;
        state.D[2] = 11;
        state.D[3] = 12;
        state.D[4] = 25;
        state.D[5] = 27;
        state.D[6] = 0x0003_00F0u;
        services.Invoke(state, (int)GraphicsLvo.BltMaskBitMapRastPort);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(
            (0x600u, (short)9, (short)10, destinationRastPort, (short)11,
                (short)12, (short)25, (short)27, (byte)0xF0, 0x800u),
            provider.BltMaskBitMapRastPorts.Single());

        state.A[0] = 0x900;
        state.D[0] = 13;
        state.D[1] = 14;
        state.D[2] = 31;
        state.D[3] = 33;
        state.D[4] = 0x0001_0002u;
        services.Invoke(state, (int)GraphicsLvo.BltPattern);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(
            (destinationRastPort, 0x900u, (short)13, (short)14, (short)31,
                (short)33, (short)2),
            provider.Patterns.Single());

        state.A[0] = 0xA00;
        state.D[0] = 2;
        state.D[1] = 6;
        state.D[2] = 15;
        state.D[3] = 17;
        state.D[4] = 29;
        state.D[5] = 35;
        services.Invoke(state, (int)GraphicsLvo.BltTemplate);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(
            (0xA00u, (short)2, (short)6, destinationRastPort, (short)15,
                (short)17, (short)29, (short)35),
            provider.Templates.Single());
    }

    [Fact]
    public void HostGraphicsServicesForwardsTypedLayeredPixelArraysToTheLayerProvider()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);
        memory.WriteLong(rastPort + (uint)GraphicsLayouts.RastPortLayer, 0x180);
        var provider = new RecordingLayerRasterBackend
        {
            PixelLineResult = 7,
            PixelArrayResult = 12
        };

        using var services = CreateHostGraphicsServices(memory, layerRaster: provider);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort, [1] = 0x300, [2] = 0x400 },
            D = { [0] = 3, [1] = 4, [2] = 5, [3] = 6, [4] = 7 },
            Cycles = 271
        };

        services.Invoke(state, (int)GraphicsLvo.ReadPixelLine8);
        Assert.Equal(7u, state.D[0]);
        Assert.Equal(271, state.Cycles);
        Assert.Equal(
            (rastPort, (ushort)3, (ushort)4, (ushort)5, 0x400u, 0x300u),
            provider.ReadPixelLines.Single());

        state.D[0] = 8;
        state.D[1] = 9;
        state.D[2] = 10;
        services.Invoke(state, (int)GraphicsLvo.WritePixelLine8);
        Assert.Equal(7u, state.D[0]);
        Assert.Equal(
            (rastPort, (ushort)8, (ushort)9, (ushort)10, 0x400u, 0x300u),
            provider.WritePixelLines.Single());

        state.D[0] = 11;
        state.D[1] = 12;
        state.D[2] = 13;
        state.D[3] = 14;
        services.Invoke(state, (int)GraphicsLvo.ReadPixelArray8);
        Assert.Equal(12u, state.D[0]);
        Assert.Equal(
            (rastPort, (ushort)11, (ushort)12, (ushort)13, (ushort)14, 0x400u, 0x300u),
            provider.ReadPixelArrays.Single());

        state.D[0] = 15;
        state.D[1] = 16;
        state.D[2] = 17;
        state.D[3] = 18;
        services.Invoke(state, (int)GraphicsLvo.WritePixelArray8);
        Assert.Equal(12u, state.D[0]);
        Assert.Equal(
            (rastPort, (ushort)15, (ushort)16, (ushort)17, (ushort)18, 0x400u, 0x300u),
            provider.WritePixelArrays.Single());

        state.D[0] = unchecked((uint)-21);
        state.D[1] = unchecked((uint)-22);
        state.D[2] = 23;
        state.D[3] = 24;
        state.D[4] = 25;
        services.Invoke(state, (int)GraphicsLvo.WriteChunkyPixels);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(
            (rastPort, -21, -22, 23, 24, 0x400u, 25),
            provider.ChunkyPixelWrites.Single());
    }

