    [Fact]
    public void HostGraphicsServicesLeavesMalformedTextAndSetFontUnclaimed()
    {
        var bus = new AmigaBus();
        const uint rastPort = 0x200;
        bus.MapWritableMemory(rastPort, new byte[GraphicsLayouts.RastPortMinimumSize]);
        var memory = new HostGuestMemory(bus);

        using var services = CreateHostGraphicsServices(memory);
        var state = new M68kCpuState
        {
            A = { [0] = 0x300, [1] = rastPort },
            D = { [0] = 2 },
            Cycles = 326
        };

        // No guest font is installed, so the portable Text path declines.
        // The host service must leave the original vector unclaimed.
        services.Invoke(state, (int)GraphicsLvo.Text);
        Assert.Equal(2u, state.D[0]);
        Assert.Equal(326, state.Cycles);

        state.A[0] = 0x600;
        state.D[0] = 0xDEAD_BEEFu;
        state.Cycles = 327;
        services.Invoke(state, (int)GraphicsLvo.SetFont);
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(327, state.Cycles);
        Assert.Equal(0u, memory.ReadLong(rastPort + (uint)GraphicsLayouts.RastPortFont));
    }

    [Fact]
    public void InvalidInitVPortDoesNotInvokeTheHostDisplayProjection()
    {
        var hostMemory = new HostGuestMemory(new AmigaBus());
        var projectionCalls = 0;
        var services = CreateHostGraphicsServices(
            hostMemory,
            initializeCompatibilityViewPort: _ => projectionCalls++);

        var state = new M68kCpuState
        {
            A = { [0] = 0x00FF_0000 },
            D = { [0] = 0xDEAD_BEEFu }
        };
        services.Invoke(state, (int)GraphicsLvo.InitVPort);
        Assert.Equal(0, projectionCalls);
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);

