    [Fact]
    public void StripFontRejectsOddTextFontPointersBeforeExtensionReads()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var fonts = new GraphicsMemoryFontBackend(memory);
        const uint oddFont = 0x601;

        // FakeMemory deliberately makes the byte-shifted extension field
        // readable. The portable boundary must still leave an odd TextFont
        // pointer to the native 68000/provider path.
        Assert.True(memory.TryWriteLong(
            oddFont + (uint)GraphicsLayouts.TextFontExtension,
            0));
        Assert.Equal(-1, core.StripFont(oddFont, fonts));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = oddFont },
            D = { [0] = 0x5A5A_A5A5u },
            Cycles = 131
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.StripFont));
        Assert.Equal(0x5A5A_A5A5u, state.D[0]);
        Assert.Equal(131, state.Cycles);
    }

