    [Fact]
    public void HostRegisterAdapterLeavesMalformedFontLifecycleCallsUnclaimed()
    {
        var memory = new FakeMemory(0x10000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint malformed = 0xFFF0;
        const uint sentinel = 0xA5A5_5A5Au;

        foreach (var vector in new[]
        {
            GraphicsLvo.CloseFont,
            GraphicsLvo.AddFont,
            GraphicsLvo.RemFont
        })
        {
            var state = new M68kCpuState
            {
                A = { [1] = malformed },
                D = { [0] = sentinel },
                Cycles = 59
            };

            Assert.False(adapter.TryInvoke(state, (int)vector), vector.ToString());
            Assert.Equal(sentinel, state.D[0]);
            Assert.Equal(59, state.Cycles);
        }

        var strip = new M68kCpuState
        {
            A = { [0] = malformed },
            D = { [0] = sentinel },
            Cycles = 61
        };
        Assert.False(adapter.TryInvoke(strip, (int)GraphicsLvo.StripFont));
        Assert.Equal(sentinel, strip.D[0]);
        Assert.Equal(61, strip.Cycles);

        var extend = new M68kCpuState
        {
            A = { [0] = malformed, [1] = 0 },
            D = { [0] = sentinel },
            Cycles = 63
        };
        Assert.False(adapter.TryInvoke(extend, (int)GraphicsLvo.ExtendFont));
        Assert.Equal(sentinel, extend.D[0]);
        Assert.Equal(63, extend.Cycles);
    }

