    [Fact]
    public void HostRegisterAdapterClaimsZeroLengthTextWithoutReadingGuestPointers()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            // Neither pointer is mapped. A zero-length Text call must still
            // be the successful void no-op established by the portable core.
            A = { [0] = 0xFFFF_FFFCu, [1] = 0xFFFF_FFF0u },
            D = { [0] = 0u }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
    }

    [Fact]
    public void HostRegisterAdapterClaimsTextVectorsForDecodedGuestFonts()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint font = 0x600;
        const uint charData = 0x700;
        const uint charLoc = 0x800;
        const uint text = 0x900;
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        memory.TryWriteWord(charLoc, 0);
        memory.TryWriteWord(charLoc + 2, 1);
        // The slot after HiChar is the Text fallback glyph.  Give it a much
        // wider bitmap so the register-gateway regression catches accidental
        // inclusion in FontExtent's declared-range envelope.
        memory.TryWriteWord(charLoc + 4, 0);
        memory.TryWriteWord(charLoc + 6, 8);
        memory.TryWriteByte(charData, 0x80);
        memory.TryWriteByte(text, (byte)'A');
        memory.TryWriteByte(text + 1, (byte)'A');

        var state = new M68kCpuState { A = { [0] = font, [1] = 0x20 }, D = { [0] = 1 } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));
        Assert.Equal(0u, state.D[0]);

        state.A[0] = 0;
        state.D[0] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.AskSoftStyle));
        Assert.Equal(uint.MaxValue, state.D[0]);
        state.D[0] = 4;
        state.D[1] = 0xFF;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetSoftStyle));
        Assert.Equal(4u, state.D[0]);

        state.A[0] = text;
        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextLength));
        Assert.Equal(1u, state.D[0]);

        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)1, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentX));

        // Text's documented D0 input is a signed WORD.  High-word residue is
        // outside the ABI and must not turn a one-character call into a
        // huge guest-memory span.
        state.D[0] = 0x0001_0001;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)2, ReadWord(memory, 0x20u + (uint)GraphicsLayouts.RastPortCurrentX));

        state.A[0] = text;
        state.A[2] = 0xA00;
        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextExtent));
        Assert.Equal((ushort)1, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentWidth));

        // A zero-length metric query has no string bytes to dereference;
        // retain the core's empty-string result at the 68k gateway while
        // non-empty calls still reject a null guest pointer.
        state.A[0] = 0;
        state.D[0] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextExtent));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((ushort)1, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentHeight));
        Assert.Equal((short)0, ReadSignedWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentMinX));
        Assert.Equal((short)-1, ReadSignedWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentMinY));
        Assert.Equal((short)-1, ReadSignedWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentMaxX));
        Assert.Equal((short)-1, ReadSignedWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentMaxY));

        // TextExtent also receives a signed WORD count.  A high-word-only
        // residue therefore becomes the documented zero-length query.
        state.D[0] = 0x0001_0000;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextExtent));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentWidth));

        state.A[0] = text;
        state.D[1] = 1;
        state.D[2] = 1;
        state.D[3] = 1;
        state.D[0] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(1u, state.D[0]);

        // The no-extent TextFit form exposes UWORD dimensions, but Kickstart
        // accepts only 0..32767.  A low-word value of 0x8000 remains rejected.
        state.D[0] = 1;
        state.D[2] = 0x0000_8000;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(1u, state.D[0]);
        state.D[2] = 1;

        state.A[0] = 0;
        // A zero-length request has no constraining rectangle to read.  Keep
        // an unreadable nonzero A3 here to prove the gateway preserves that
        // empty-request ownership boundary instead of probing an unused
        // optional input.
        state.A[3] = 0x1FFC;
        state.D[0] = 0;
        state.D[1] = 1;
        state.D[2] = 0;
        state.D[3] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((ushort)0, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentWidth));

        state.A[0] = text + 1;
        state.A[3] = 0;
        state.D[0] = 2;
        state.D[1] = unchecked((uint)-1);
        state.D[2] = 2;
        state.D[3] = 1;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(2u, state.D[0]);
        Assert.Equal((ushort)2, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentWidth));

        // The optional A3 is still required for a non-empty request when it
        // is supplied; only the empty-request path may leave it unreadable.
        state.A[0] = text;
        state.A[3] = 0x1FFC;
        state.D[0] = 1;
        state.D[1] = 1;
        state.D[2] = 1;
        state.D[3] = 1;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(1u, state.D[0]);
        state.A[3] = 0;

        state.A[0] = font;
        state.A[1] = 0xA00;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.FontExtent));
        Assert.Equal((ushort)1, ReadWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentWidth));
        Assert.Equal((short)0, ReadSignedWord(memory, 0xA00u + (uint)GraphicsLayouts.TextExtentMaxX));

        // Text's complete guest stream preflight must reach the native/font
        // provider when the final byte crosses the memory envelope instead
        // of being reported as a successful void call.
        state.A[0] = 0x1FFF;
        state.D[0] = 2;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.Text));
        Assert.Equal(2u, state.D[0]);

        state.A[1] = 0x20;
        state.D[0] = 2;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextLength));
        Assert.Equal(2u, state.D[0]);

        state.A[2] = 0xA00;
        state.D[0] = 2;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextExtent));
        Assert.Equal(2u, state.D[0]);

        state.D[1] = 1;
        state.D[2] = 1;
        state.D[3] = 1;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(2u, state.D[0]);

        state.A[0] = font;
        state.A[1] = 0x1FF8;
        state.D[0] = 0xCAFE_BABEu;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.FontExtent));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);

        // SetFont preflights only the fields it consumes or publishes.  A
        // valid decoded font paired with a RastPort whose final cached metric
        // word is truncated remains provider-owned and cannot publish a
        // partial font switch; unrelated bytes after TxBaseline are not part
        // of this ownership boundary.
        state.A[0] = font;
        state.A[1] = 0x1FC2;
        state.D[0] = 0xDEAD_BEEFu;
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
    }

    [Fact]
    public void HostRegisterAdapterLeavesUndecodableNonNullTextLengthFontUnclaimed()
    {
        var memory = new FakeMemory(0x400);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint text = 0x100;
        const uint foreignFont = 0x1800;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            foreignFont));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth,
            3));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            1));
        Assert.True(memory.TryWriteByte(text, (byte)'A'));

        var state = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 77
        };

        // A non-null foreign/undecodable TextFont must not be reinterpreted
        // as the cached fixed-metric compatibility state.  Leave D0 and the
        // cycle boundary untouched for native Kickstart/provider ownership.
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.TextLength));
        Assert.Equal(0xCAFE_BABEu, state.D[0]);
        Assert.Equal(77, state.Cycles);
    }

    [Fact]
    public void HostRegisterAdapterUsesTextFitLowWordFields()
    {
        var memory = new FakeMemory(0x12_000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint font = 0x300;
        const uint charData = 0x900;
        const uint charLoc = 0xA00;
        const uint text = 0x1000;
        const uint extent = 0xB00;

        WriteFontHeader(memory, font, 0, ySize: 1, style: 0, flags: 0);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        memory.TryWriteWord(charLoc, 0);
        memory.TryWriteWord(charLoc + 2, 1);
        memory.TryWriteByte(charData, 0x80);
        for (var index = 0u; index < 0x2000; index++)
            memory.TryWriteByte(text + index, (byte)'A');

        var state = new M68kCpuState
        {
            A = { [0] = font, [1] = 0x20 },
            D = { [0] = 1 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));

        state.A[0] = text;
        state.A[1] = 0x20;
        state.A[2] = extent;
        state.A[3] = 0;

        state.A[0] = text;
        state.D[0] = 0x0001_0002;
        state.D[1] = 0x0001_0001;
        state.D[2] = 0x0001_7FFF;
        state.D[3] = 0x0001_0001;

        // TextFit's strLen/width/height are UWORDs and direction is a signed
        // WORD.  High-word residue must not change the low-word request.
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.TextFit));
        Assert.Equal(2u, state.D[0]);
    }

