    [Fact]
    public void SetRPAttrsFontDoesNotRequireUnrelatedTxSpacingRead()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new RangeReadFaultMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint tags = 0x600;

        Assert.True(core.InitializeRastPort(rastPort));
        Assert.True(memory.TryWriteLong(tags, GraphicsRastPortAttributeOperations.RptagFont));
        Assert.True(memory.TryWriteLong(tags + 4u, font));
        Assert.True(memory.TryWriteLong(
            tags + 8u,
            GraphicsRastPortAttributeOperations.TagDone));

        // RPTAG_Font follows SetFont's exact field envelope.  A fault in the
        // unrelated caller-owned TxSpacing word must not make SetRPAttrsA
        // decline an otherwise valid font/cache update.
        memory.FailReads(
            rastPort + (uint)GraphicsLayouts.RastPortTextSpacing,
            sizeof(ushort));

        Assert.True(core.SetRPAttrs(rastPort, tags, fonts));
        Assert.Equal(font, ReadLong(backing, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal(
            (ushort)3,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(
            (ushort)3,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal(
            (ushort)3,
            ReadWord(backing, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void HostRegisterAdapterKeepsSoftStyleInputsLongWordWide()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint font = 0x600;
        const uint charData = 0x700;
        const uint charLoc = 0x800;

        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, 1);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontXSize, 1);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontBaseline, 1);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontStyle, 0);
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontLoChar, (byte)'A');
        memory.TryWriteByte(font + (uint)GraphicsLayouts.TextFontHiChar, (byte)'A');
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharData, charData);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontModulo, 1);
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontCharLoc, charLoc);
        memory.TryWriteWord(charLoc, 0);
        memory.TryWriteWord(charLoc + 2, 1);
        memory.TryWriteByte(charData, 0x80);

        var state = new M68kCpuState { A = { [0] = font, [1] = 0x20 } };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetFont));

        // SetSoftStyle's D0/D1 arguments are ULONGs.  Only their low byte
        // reaches the guest AlgoStyle byte, while high bits must not be
        // silently treated as a truncated/empty request by the adapter.
        state.D[0] = 0xCAFE_BA04u;
        state.D[1] = 0x1357_2404u;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetSoftStyle));
        Assert.Equal(0x04u, state.D[0]);
        Assert.Equal((byte)0x04, ReadByte(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortAlgoStyle));
    }

