    [Fact]
    public void HostRegisterAdapterInitRastPortUsesTheGuestFontListDefault()
    {
        var memory = new FakeMemory(0x4000);
        var core = CreateCore(memory);
        const uint gfxBase = 0x1000;
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(memory, font, name, ySize: 9, style: 0, flags: 1);
        WriteAscii(memory, name, "guest-default.font");

        var list = new GraphicsGuestFontListBackend(memory, gfxBase);
        var fontBackend = new GraphicsMemoryFontBackend(memory, fontList: list);
        Assert.True(list.Initialize(0));
        Assert.True(fontBackend.TryAdd(font));
        Assert.True(list.SetDefaultFont(font));

        // No compatibility callback is supplied.  InitRastPort must still
        // resolve the guest GfxBase DefaultFont through the rebound list,
        // exactly as SetFont(NULL) does in the mapped native path.
        var adapter = new CopperStartGraphicsRegisterAdapter(core, fontList: list);
        var state = new M68kCpuState
        {
            A = { [1] = 0x20 },
            D = { [0] = 0xCAFE_BABEu }
        };

        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.InitRastPort));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(font, ReadLong(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((ushort)9, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)8, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)7, ReadWord(
            memory,
            0x20u + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void NativeOverlayInitRastPortLeavesHostDefaultWithoutGuestListToKickstart()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint font = 0x600;
        const uint name = 0x500;
        WriteFontHeader(memory, font, name, ySize: 8, style: 0, flags: 1);
        WriteAscii(memory, name, "host-default.font");
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            Assert.True(memory.TryWriteByte(rastPort + (uint)offset, 0xCC));

        // A native overlay may only resolve InitRastPort's default through
        // the rebound guest GfxBase TextFonts/DefaultFont list.  The host
        // compatibility callback is deliberately not a native owner.
        var adapter = new CopperStartGraphicsRegisterAdapter(core, () => font);
        var state = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 341
        };

        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.InitRastPort, nativeOverlay: true));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(341, state.Cycles);
        for (var offset = 0; offset < GraphicsLayouts.RastPortMinimumSize; offset++)
            Assert.Equal((byte)0xCC, ReadByte(memory, rastPort + (uint)offset));
    }

    [Fact]
