    [Fact]
    public void RastPortAttributeVectorsRejectOddRastPortBasesBeforeCollectingTags()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new ReadTrackingMemory(backing);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint oddRastPort = 0x121;
        const uint setTags = 0x300;
        const uint getTags = 0x320;
        const uint result = 0x500;

        WriteTag(backing, setTags, GraphicsRastPortAttributeOperations.RptagAPen, 7);
        WriteTag(backing, setTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        WriteTag(backing, getTags, GraphicsRastPortAttributeOperations.RptagAPen, result);
        WriteTag(backing, getTags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        Assert.True(backing.TryWriteLong(result, 0xDEAD_BEEFu));

        memory.ReadCount = 0;
        Assert.False(core.SetRPAttrs(oddRastPort, setTags, new FakeFontBackend()));
        Assert.Equal(0, memory.ReadCount);

        memory.ReadCount = 0;
        Assert.False(core.GetRPAttrs(oddRastPort, getTags, new FakeFontBackend()));
        Assert.Equal(0, memory.ReadCount);
        Assert.Equal(0xDEAD_BEEFu, ReadLong(backing, result));

        var setState = new M68kCpuState
        {
            A = { [0] = setTags, [1] = oddRastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 203
        };
        Assert.False(adapter.TryInvoke(setState, (int)GraphicsLvo.SetRPAttrsA));
        Assert.Equal(0xCAFE_BABEu, setState.D[0]);
        Assert.Equal(203, setState.Cycles);

        var getState = new M68kCpuState
        {
            A = { [0] = getTags, [1] = oddRastPort },
            D = { [0] = 0x1234_5678u },
            Cycles = 205
        };
        Assert.False(adapter.TryInvoke(getState, (int)GraphicsLvo.GetRPAttrsA));
        Assert.Equal(0x1234_5678u, getState.D[0]);
        Assert.Equal(205, getState.Cycles);
    }

    [Fact]
    public void RastPortAttributeSetRestoresEarlierTagsWhenALaterSetterFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        memory.FailOnNextByteWrite(3);
        const uint rastPort = 0x20;
        const uint tags = 0x300;

        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortBgPen, 2));
        Assert.True(backing.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount, 9));
        WriteTag(backing, tags, GraphicsRastPortAttributeOperations.RptagAPen, 5);
        WriteTag(backing, tags + 8, GraphicsRastPortAttributeOperations.RptagBPen, 6);
        WriteTag(backing, tags + 16, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.False(core.SetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.Equal((byte)1, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)2, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortBgPen));
        Assert.Equal((byte)9, ReadByte(backing, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
    }

    [Fact]
    public void RastPortAttributeSetRestoresMintermsWhenALaterTagFails()
    {
        var memory = new FakeMemory(0x1200);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tags = 0x300;
        const uint invalidFont = 0;

        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            9));
        for (var index = 0; index < 8; index++)
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)index,
                (byte)(0x80 + index)));

        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.RptagAPen, 5);
        WriteTag(memory, tags + 8, GraphicsRastPortAttributeOperations.RptagFont, invalidFont);
        WriteTag(memory, tags + 16, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.False(core.SetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.Equal((byte)1, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)9, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var index = 0; index < 8; index++)
            Assert.Equal(
                (byte)(0x80 + index),
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)index));
    }

    [Fact]
    public void RastPortAttributeSetRestoresAlgoStyleWhenALaterFontTagFails()
    {
        var memory = new FakeMemory(0x1200);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tags = 0x300;
        const uint validFont = 0x600;
        const uint invalidFont = 0;
        const byte originalStyle = 0x07;

        Assert.True(memory.TryWriteLong(
            rastPort + (uint)GraphicsLayouts.RastPortFont,
            0x500));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle,
            originalStyle));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextHeight,
            11));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextWidth,
            12));
        Assert.True(memory.TryWriteWord(
            rastPort + (uint)GraphicsLayouts.RastPortTextBaseline,
            13));

        // The first font tag succeeds and clears AlgoStyle.  The second is
        // intentionally invalid, so the tag-list transaction must restore
        // the complete font/cache/style envelope published by the first.
        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.RptagFont, validFont);
        WriteTag(memory, tags + 8, GraphicsRastPortAttributeOperations.RptagFont, invalidFont);
        WriteTag(memory, tags + 16, GraphicsRastPortAttributeOperations.TagDone, 0);

        Assert.False(core.SetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.Equal(
            0x500u,
            ReadLong(memory, rastPort + (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal(
            originalStyle,
            ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal(
            (ushort)11,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal(
            (ushort)12,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal(
            (ushort)13,
            ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortTextBaseline));
    }

