    [Fact]
    public void HostRegisterAttributeSetPreservesMintermsWhenALaterTagFails()
    {
        var memory = new FakeMemory(0x1200);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint tags = 0x300;
        const uint invalidFont = 0;

        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            1));
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount,
            9));
        for (var index = 0; index < 8; index++)
            Assert.True(memory.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)index,
                (byte)(0x90 + index)));

        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.RptagAPen, 5);
        WriteTag(memory, tags + 8, GraphicsRastPortAttributeOperations.RptagFont, invalidFont);
        WriteTag(memory, tags + 16, GraphicsRastPortAttributeOperations.TagDone, 0);

        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0xDEAD_BEEFu }
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetRPAttrsA));
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal((byte)1, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortFgPen));
        Assert.Equal((byte)9, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        for (var index = 0; index < 8; index++)
            Assert.Equal(
                (byte)(0x90 + index),
                ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortMinterms + (uint)index));
    }

    [Fact]
    public void RastPortAttributeGetRestoresEarlierOutputsWhenALaterOutputFails()
    {
        var backing = new FakeMemory(0x1000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tags = 0x300;
        const uint firstResult = 0x500;
        const uint secondResult = 0x510;

        Assert.True(backing.TryWriteLong(firstResult, 0xAAAA_AAAAu));
        Assert.True(backing.TryWriteLong(secondResult, 0xBBBB_BBBBu));
        WriteTag(backing, tags, GraphicsRastPortAttributeOperations.RptagAPen, firstResult);
        WriteTag(backing, tags + 8, GraphicsRastPortAttributeOperations.RptagBPen, secondResult);
        WriteTag(backing, tags + 16, GraphicsRastPortAttributeOperations.TagDone, 0);

        // The first result consumes four byte writes.  Fail at the first byte
        // of the second result, then allow the rollback writes to complete.
        memory.FailOnNextByteWrite(5);
        Assert.False(core.GetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.Equal(0xAAAA_AAAAu, ReadLong(backing, firstResult));
        Assert.Equal(0xBBBB_BBBBu, ReadLong(backing, secondResult));
    }

    [Fact]
    public void RastPortAttributeGetRejectsOutputEnvelopesThatWrapAtGuestBoundary()
    {
        var memory = new WrappingMemory();
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint tags = 0x100;
        const uint wrappedResult = uint.MaxValue - 1u;

        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortFgPen,
            5));
        Assert.True(memory.TryWriteLong(
            tags,
            GraphicsRastPortAttributeOperations.RptagAPen));
        Assert.True(memory.TryWriteLong(tags + 4, wrappedResult));
        Assert.True(memory.TryWriteLong(
            tags + 8,
            GraphicsRastPortAttributeOperations.TagDone));
        Assert.True(memory.TryWriteLong(tags + 12, 0));

        // The wrapping provider intentionally exposes the address arithmetic
        // hazard: without a complete-envelope guard, TryWriteLong would write
        // the final two bytes at ULONG 0/1 and falsely claim the vector.
        memory.WriteByte(wrappedResult, 0xAA);
        memory.WriteByte(uint.MaxValue, 0xBB);
        memory.WriteByte(0, 0xCC);
        memory.WriteByte(1, 0xDD);

        Assert.False(core.GetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.True(memory.TryReadByte(0, out var lowZero));
        Assert.True(memory.TryReadByte(1, out var lowOne));
        Assert.True(memory.TryReadByte(wrappedResult, out var highLast));
        Assert.True(memory.TryReadByte(uint.MaxValue, out var highEnd));
        Assert.Equal((byte)0xCC, lowZero);
        Assert.Equal((byte)0xDD, lowOne);
        Assert.Equal((byte)0xAA, highLast);
        Assert.Equal((byte)0xBB, highEnd);
    }

    [Fact]
    public void SetMaxPenPublishesTheClassicMaskAndTreatsZeroAsANoop()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint result = 0x300;
        const uint tags = 0x340;

        var state = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 3 }
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetMaxPen));
        Assert.Equal((byte)3, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortMask));

        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.RptagMaxPen, result);
        WriteTag(memory, tags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        state.A[0] = tags;
        state.A[1] = rastPort;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetRPAttrsA));
        Assert.Equal(4u, ReadLong(memory, result));

        // A later nonzero request publishes the complete mask implied by the
        // new maximum, even when a prior SetMaxPen call narrowed it.
        state.A[0] = rastPort;
        state.D[0] = 0xFF;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetMaxPen));
        Assert.Equal((byte)0xFF, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortMask));

        // maxpen == 0 is a documented no-op, not a request for a one-plane
        // mask; preserve the state published by the preceding call.
        state.D[0] = 0;
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.SetMaxPen));
        Assert.Equal((byte)0xFF, ReadByte(memory, rastPort + (uint)GraphicsLayouts.RastPortMask));
    }

    [Fact]
    public void GetRPAttrsMaxPenReportsTheExclusivePenLimitForEmptyAndSparseMasks()
    {
        var memory = new FakeMemory(0x1000);
        var core = CreateCore(memory);
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        const uint rastPort = 0x20;
        const uint tags = 0x300;
        const uint result = 0x380;

        // RPTAG_MaxPen reports the number of usable pen values.  A zero
        // write mask is the resident 256-pen sentinel, not a zero limit.
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0));
        WriteTag(memory, tags, GraphicsRastPortAttributeOperations.RptagMaxPen, result);
        WriteTag(memory, tags + 8, GraphicsRastPortAttributeOperations.TagDone, 0);
        Assert.True(core.GetRPAttrs(rastPort, tags, new FakeFontBackend()));
        Assert.Equal(0x100u, ReadLong(memory, result));

        // The limit is derived from the highest mask bit, so a non-contiguous
        // mask still exposes the same exclusive range used by the resident
        // GetRPAttrsA implementation.
        Assert.True(memory.TryWriteByte(
            rastPort + (uint)GraphicsLayouts.RastPortMask,
            0x05));
        var state = new M68kCpuState
        {
            A = { [0] = tags, [1] = rastPort },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 211
        };
        Assert.True(adapter.TryInvoke(state, (int)GraphicsLvo.GetRPAttrsA));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(211, state.Cycles);
        Assert.Equal(8u, ReadLong(memory, result));
    }

    [Fact]
    public void SetMaxPenZeroReturnsBeforeRastPortAccessAcrossDirectAndMappedPaths()
    {
        var backing = new FakeMemory(0x100);
        var memory = new ReadTrackingMemory(backing);
        var core = CreateCore(memory);

        // The resident implementation branches on maxpen before touching
        // the RastPort.  Preserve that observable no-op for both NULL and an
        // odd guest address rather than forcing a provider/native fallback
        // through an unrelated Mask read.
        Assert.Equal(0, core.SetMaxPen(0, 0));
        Assert.Equal(0, memory.ReadCount);

        memory.ReadCount = 0;
        Assert.Equal(0, core.SetMaxPen(0x21, 0));
        Assert.Equal(0, memory.ReadCount);

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = 0x21 },
            D = { [0] = 0 },
            Cycles = 97
        };
        Assert.True(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.SetMaxPen,
            nativeOverlay: true));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(97, state.Cycles);
        Assert.Equal(0, memory.ReadCount);
    }

    [Fact]
    public void SetMaxPenNonzeroWritesMaskWithoutReadingItAcrossDirectAndMappedPaths()
    {
        var backing = new FakeMemory(0x1000);
        const uint rastPort = 0x20;
        var mask = rastPort + (uint)GraphicsLayouts.RastPortMask;
        Assert.True(backing.TryWriteByte(mask, 0x03));

        var memory = new RangeReadFaultMemory(backing);
        memory.FailReads(mask, 1);
        var core = CreateCore(memory);

        // The resident nonzero path derives and writes the new mask; it does
        // not need the previous byte. A read fault at Mask must therefore not
        // move this valid writable request to native/provider ownership.
        Assert.Equal(0, core.SetMaxPen(rastPort, 0x0F));
        Assert.True(backing.TryReadByte(mask, out var directMask));
        Assert.Equal((byte)0x0F, directMask);

        Assert.True(backing.TryWriteByte(mask, 0x01));
        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 0x1F },
            Cycles = 123
        };
        Assert.True(adapter.TryInvoke(
            state,
            (int)GraphicsLvo.SetMaxPen,
            nativeOverlay: true));
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(123, state.Cycles);
        Assert.True(backing.TryReadByte(mask, out var mappedMask));
        Assert.Equal((byte)0x1F, mappedMask);
    }

    [Fact]
    public void SetMaxPenDeclinesValuesOutsideTheClassicByteRange()
    {
        var memory = new FakeMemory(0x1000);
        const uint rastPort = 0x20;
        var mask = rastPort + (uint)GraphicsLayouts.RastPortMask;

        // SetMaxPen's documented ULONG input is a pen value in the
        // inclusive range 0..255.  A larger request must remain available to
        // native/provider ownership instead of being silently narrowed to
        // the same 0xFF mask as a valid 255 request.
        var core = CreateCore(memory);
        Assert.True(memory.TryWriteByte(mask, 0x0F));
        Assert.Equal(-1, core.SetMaxPen(rastPort, 0x100));
        Assert.Equal((byte)0x0F, ReadByte(memory, mask));

        var adapter = new CopperStartGraphicsRegisterAdapter(core);
        var state = new M68kCpuState
        {
            A = { [0] = rastPort },
            D = { [0] = 0x100 },
            Cycles = 137
        };
        Assert.False(adapter.TryInvoke(state, (int)GraphicsLvo.SetMaxPen));
        Assert.Equal(0x100u, state.D[0]);
        Assert.Equal(137, state.Cycles);
        Assert.Equal((byte)0x0F, ReadByte(memory, mask));
    }

    [Fact]
    public void GraphicsServicesDispatchesMigratedVectorsThroughTheHostAdapter()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var hostMemory = new HostGuestMemory(machine.Bus);
        var publishedView = 0u;
        var waitedCycle = -1L;
        var waitedViewPort = 0u;
        var waitedBovpCycle = -1L;
        var allocatedBytes = -1;
        var allocatedFlags = 0u;
        var freedAddress = 0u;
        var freedBytes = -1;
        var services = CreateHostGraphicsServices(
            hostMemory,
            waitTof: callbackState =>
            {
                waitedCycle = callbackState.Cycles;
                callbackState.Cycles += 5;
            },
            loadView: callbackState => publishedView = callbackState.A[1],
            beamPosition: _ => 277,
            waitForViewportBottom: (viewPort, cycle) =>
            {
                waitedViewPort = viewPort;
                waitedBovpCycle = cycle;
                return cycle + 7;
            },
            allocateMemory: (bytes, flags) =>
            {
                allocatedBytes = bytes;
                allocatedFlags = flags;
                return 0x1800;
            },
            freeMemory: (address, bytes) =>
            {
                freedAddress = address;
                freedBytes = bytes;
            });
        const uint rastPort = 0x400;

        var state = new M68kCpuState { A = { [1] = rastPort, }, D = { [0] = 7 } };
        services.Invoke(state, (int)GraphicsLvo.SetAPen);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal((byte)7, machine.Bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));

        services.Invoke(state, (int)GraphicsLvo.InitRastPort);
        Assert.Equal((byte)0xFF, machine.Bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortMask));
        Assert.Equal((byte)0xFF, machine.Bus.ReadByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen));

        machine.Bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextWidth, 8);
        machine.Bus.WriteWord(rastPort + (uint)GraphicsLayouts.RastPortTextSpacing, 1);
        state.D[0] = 3;
        services.Invoke(state, (int)GraphicsLvo.TextLength);
        Assert.Equal(27u, state.D[0]);

        state.A[1] = 0x180;
        state.Cycles = 91;
        services.Invoke(state, (int)GraphicsLvo.LoadView);
        Assert.Equal(0x180u, publishedView);
        Assert.Equal(0u, state.D[0]);

        // A malformed standard View must remain available to a native ROM
        // implementation.  GraphicsServices must not route it through the
        // legacy host callback after the portable validator declines it.
        state.A[1] = 0x00FF_0000;
        state.D[0] = 0xDEAD_BEEFu;
        state.Cycles = 97;
        services.Invoke(state, (int)GraphicsLvo.LoadView);
        Assert.Equal(0x180u, publishedView);
        Assert.Equal(0xDEAD_BEEFu, state.D[0]);
        Assert.Equal(97, state.Cycles);

        state.Cycles = 107;
        services.Invoke(state, (int)GraphicsLvo.WaitTOF);
        Assert.Equal(107, waitedCycle);
        Assert.Equal(112, state.Cycles);
        Assert.Equal(0u, state.D[0]);

        services.Invoke(state, (int)GraphicsLvo.VBeamPos);
        Assert.Equal(277u, state.D[0]);

        state.A[0] = 0x222;
        machine.Bus.WriteLong(0x222u + (uint)GraphicsLayouts.ViewPortRasInfo, 0x300);
        machine.Bus.WriteLong(0x300u + (uint)GraphicsLayouts.RasInfoNext, 0);
        machine.Bus.WriteLong(0x300u + (uint)GraphicsLayouts.RasInfoBitMap, 0);
        machine.Bus.WriteWord(0x300u + (uint)GraphicsLayouts.RasInfoRxOffset, 0);
        machine.Bus.WriteWord(0x300u + (uint)GraphicsLayouts.RasInfoRyOffset, 0);
        state.Cycles = 120;
        services.Invoke(state, (int)GraphicsLvo.WaitBOVP);
        Assert.Equal(0x222u, waitedViewPort);
        Assert.Equal(120, waitedBovpCycle);
        Assert.Equal(127, state.Cycles);
        Assert.Equal(0u, state.D[0]);

        state.D[0] = 17;
        state.D[1] = 3;
        services.Invoke(state, (int)GraphicsLvo.AllocRaster);
        Assert.Equal(0x1800u, state.D[0]);
        Assert.Equal(12, allocatedBytes);
        Assert.Equal(0x2u, allocatedFlags); // MEMF_CHIP

        state.A[0] = state.D[0];
        state.D[0] = 17;
        state.D[1] = 3;
        services.Invoke(state, (int)GraphicsLvo.FreeRaster);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(0x1800u, freedAddress);
        Assert.Equal(12, freedBytes);
    }

    [Fact]
    public void GraphicsServicesForwardsOnlyRtgLoadViewDeclinesToTheProvider()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var memory = new HostGuestMemory(machine.Bus);
        const uint view = 0x240;
        const uint viewPort = 0x280;
        const uint rasInfo = 0x2C0;
        const uint rtgBitMap = 0x300;
        var publishedView = 0u;

        machine.Bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        machine.Bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);

        using var services = CreateHostGraphicsServices(
            memory,
            loadView: callbackState => publishedView = callbackState.A[1],
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        var state = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xABCD_1234u },
            Cycles = 53
        };

        services.Invoke(state, (int)GraphicsLvo.LoadView);

        Assert.Equal(view, publishedView);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(53, state.Cycles);
    }

    [Fact]
    public void GraphicsServicesUsesStatusAwareRtgLoadViewProviderAcrossEntryPoints()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var memory = new HostGuestMemory(machine.Bus);
        const uint view = 0x240;
        const uint viewPort = 0x280;
        const uint rasInfo = 0x2C0;
        const uint rtgBitMap = 0x300;
        var calls = 0;
        var accept = false;

        machine.Bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        machine.Bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);

        using var services = CreateHostGraphicsServices(
            memory,
            tryLoadView: _ =>
            {
                calls++;
                return accept;
            },
            isRtgBitMap: bitMap => bitMap == rtgBitMap);

        var declined = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0xABCD_1234u },
            Cycles = 61
        };
        services.Invoke(declined, (int)GraphicsLvo.LoadView);

        Assert.Equal(1, calls);
        Assert.Equal(0xABCD_1234u, declined.D[0]);
        Assert.Equal(61, declined.Cycles);

        accept = true;
        var accepted = new M68kCpuState
        {
            A = { [1] = view },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 67
        };
        services.LoadView(accepted);

        Assert.Equal(2, calls);
        Assert.Equal(0u, accepted.D[0]);
        Assert.Equal(67, accepted.Cycles);
    }

    [Fact]
    public void GraphicsServicesForwardsNullLoadViewWhenActiveViewIsRtg()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var memory = new HostGuestMemory(machine.Bus);
        const uint graphicsBase = 0x100;
        const uint view = 0x240;
        const uint viewPort = 0x280;
        const uint rasInfo = 0x2C0;
        const uint rtgBitMap = 0x300;
        var calls = 0;
        var publishedView = 0xFFFF_FFFFu;

        machine.Bus.WriteLong(
            graphicsBase + (uint)GraphicsLayouts.GfxBaseActiView,
            view);
        machine.Bus.WriteLong(view + (uint)GraphicsLayouts.ViewViewPort, viewPort);
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        machine.Bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);

        using var services = CreateHostGraphicsServices(
            memory,
            graphicsLibraryBase: graphicsBase,
            tryLoadView: state =>
            {
                calls++;
                publishedView = state.A[1];
                return true;
            },
            isRtgBitMap: bitMap => bitMap == rtgBitMap);

        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 79,
            ProgramCounter = 0x0012_3456
        };

        services.LoadView(state);

        Assert.Equal(1, calls);
        Assert.Equal(0u, publishedView);
        Assert.Equal(0u, state.D[0]);
        Assert.Equal(79, state.Cycles);
        Assert.Equal(0x0012_3456u, state.ProgramCounter);
    }

    [Fact]
    public void GraphicsServicesLeavesMalformedPaletteCallsUnclaimed()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var memory = new HostGuestMemory(machine.Bus);
        var loadCalls = 0;
        var setCalls = 0;
        const uint viewPort = 0x340;
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0xDEAD);

        using var services = CreateHostGraphicsServices(
            memory,
            loadRgb4: _ => loadCalls++,
            setRgb4: _ => setCalls++);
        var load = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = 0x500 },
            D = { [0] = 1, [1] = 0x0F, [2] = 0x02, [3] = 0x01 },
            Cycles = 71
        };

        services.Invoke(load, (int)GraphicsLvo.LoadRGB4);

        Assert.Equal(0, loadCalls);
        Assert.Equal(1u, load.D[0]);
        Assert.Equal(71, load.Cycles);

        var set = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 1, [1] = 0x0F, [2] = 0x02, [3] = 0x01 },
            Cycles = 83
        };

        services.Invoke(set, (int)GraphicsLvo.SetRGB4);

        Assert.Equal(0, setCalls);
        Assert.Equal(1u, set.D[0]);
        Assert.Equal(83, set.Cycles);
    }

    [Fact]
    public void GraphicsServicesForwardsRtgPaletteDeclinesToTheProvider()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var memory = new HostGuestMemory(machine.Bus);
        var loadCalls = 0;
        var setCalls = 0;
        const uint viewPort = 0x400;
        const uint rasInfo = 0x440;
        const uint rtgBitMap = 0x480;

        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortRasInfo, rasInfo);
        machine.Bus.WriteLong(rasInfo + (uint)GraphicsLayouts.RasInfoBitMap, rtgBitMap);
        machine.Bus.WriteLong(viewPort + (uint)GraphicsLayouts.ViewPortColorMap, 0xDEAD);

        using var services = CreateHostGraphicsServices(
            memory,
            loadRgb4: _ => loadCalls++,
            setRgb4: _ => setCalls++,
            isRtgBitMap: bitMap => bitMap == rtgBitMap);
        var load = new M68kCpuState
        {
            A = { [0] = viewPort, [1] = 0x500 },
            D = { [0] = 1 },
            Cycles = 101
        };
        services.Invoke(load, (int)GraphicsLvo.LoadRGB4);

        var set = new M68kCpuState
        {
            A = { [0] = viewPort },
            D = { [0] = 1 },
            Cycles = 113
        };
        services.Invoke(set, (int)GraphicsLvo.SetRGB4);

        Assert.Equal(1, loadCalls);
        Assert.Equal(1, setCalls);
        Assert.Equal(0u, load.D[0]);
        Assert.Equal(0u, set.D[0]);
        Assert.Equal(101, load.Cycles);
        Assert.Equal(113, set.Cycles);
    }

