    [Fact]
    public void GraphicsServicesLeavesForeignBitmapOwnershipToNativeOrRtgProviders()
    {
        using var machine = new Machine(MachineOptions.ForProfile(MachineProfile.A500Pal512KBoot));
        var hostMemory = new HostGuestMemory(machine.Bus);
        var freed = 0u;
        var attrCalls = 0;
        using var services = CreateHostGraphicsServices(
            hostMemory,
            getBitMapAttr: (_, _) =>
            {
                attrCalls++;
                return 0xA5A5u;
            },
            isRtgBitMap: static bitMap => bitMap == 0x500u,
            freeBitMap: bitMap => freed = bitMap);

        var foreignFree = new M68kCpuState
        {
            A = { [0] = 0xFF00_0000u },
            D = { [0] = 0x1122_3344u },
            Cycles = 73
        };
        services.Invoke(foreignFree, (int)GraphicsLvo.FreeBitMap);
        Assert.Equal(0u, freed);
        Assert.Equal(0x1122_3344u, foreignFree.D[0]);
        Assert.Equal(73, foreignFree.Cycles);

        var rtgFree = new M68kCpuState
        {
            A = { [0] = 0x500u },
            D = { [0] = 0x5566_7788u },
            Cycles = 79
        };
        services.Invoke(rtgFree, (int)GraphicsLvo.FreeBitMap);
        Assert.Equal(0x500u, freed);
        Assert.Equal(0u, rtgFree.D[0]);
        Assert.Equal(79, rtgFree.Cycles);

        var foreignAttr = new M68kCpuState
        {
            A = { [0] = 0xFF00_0000u },
            D = { [0] = 0xA5A5_5A5Au, [1] = 8u },
            Cycles = 83
        };
        services.Invoke(foreignAttr, (int)GraphicsLvo.GetBitMapAttr);
        Assert.Equal(0, attrCalls);
        Assert.Equal(0xA5A5_5A5Au, foreignAttr.D[0]);
        Assert.Equal(83, foreignAttr.Cycles);
    }

