    }

    [Theory]
    [InlineData((short)192, (byte)0x00, (byte)0xFF, (byte)15)]
    [InlineData((short)193, (byte)0x80, (byte)0x7F, (byte)14)]
    [InlineData((short)194, (byte)0x80, (byte)0x7F, (byte)13)]
    [InlineData((short)195, (byte)0xC0, (byte)0x3F, (byte)12)]
    [InlineData((short)196, (byte)0xC0, (byte)0x3F, (byte)11)]
    [InlineData((short)197, (byte)0xE0, (byte)0x1F, (byte)10)]
    [InlineData((short)198, (byte)0xE0, (byte)0x1F, (byte)9)]
    [InlineData((short)199, (byte)0xF0, (byte)0x0F, (byte)8)]
    public void PortableDrawBpr14ShallowEndpointsPublishCompleteClippedRaster(
        short targetX,
        byte rowZeroTail,
        byte rowOneHead,
        byte expectedPatternCount)
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x400;

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            14));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        for (uint index = 0; index < 28; index++)
            Assert.True(memory.TryWriteByte(plane + index, 0));

        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.Equal(0, core.Move(rastPort, 0, 0));

        Assert.Equal(0, GraphicsRasterOperations.Draw(memory, rastPort, targetX, 1));
        for (uint index = 0; index < 12; index++)
            Assert.Equal((byte)0xFF, ReadByte(memory, plane + index));
        Assert.Equal(rowZeroTail, ReadByte(memory, plane + 12u));
        for (uint index = 13; index < 26; index++)
            Assert.Equal((byte)0x00, ReadByte(memory, plane + index));
        Assert.Equal(rowOneHead, ReadByte(memory, plane + 26u));
        Assert.Equal((byte)0xFF, ReadByte(memory, plane + 27u));
        Assert.Equal(targetX, unchecked((short)ReadWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)1, unchecked((short)ReadWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(expectedPatternCount, ReadByte(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(0, ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags) &
            GraphicsLayouts.RastPortFirstDot);
    }

    [Theory]
    [InlineData((short)184, (byte)7)]
    [InlineData((short)185, (byte)6)]
    [InlineData((short)186, (byte)5)]
    [InlineData((short)187, (byte)4)]
    [InlineData((short)188, (byte)3)]
    [InlineData((short)189, (byte)2)]
    [InlineData((short)190, (byte)1)]
    [InlineData((short)191, (byte)0)]
    [InlineData((short)207, (byte)0)]
    public void PortableDrawBpr13ShallowEndpointsPublishCompleteClippedRaster(
        short targetX,
        byte expectedPatternCount)
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane = 0x400;

        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            13));
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapRows,
            2));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapDepth,
            1));
        Assert.True(memory.TryWriteLong(
            bitMap + (uint)GraphicsLayouts.BitMapPlanes,
            plane));
        for (uint index = 0; index < 26; index++)
            Assert.True(memory.TryWriteByte(plane + index, 0));

        Assert.Equal(0, core.SetAPen(rastPort, 1));
        Assert.Equal(0, core.SetWriteMask(rastPort, 1));
        Assert.Equal(0, core.SetDrawMode(rastPort, 0));
        Assert.Equal(0, core.Move(rastPort, 0, 0));

        Assert.Equal(0, GraphicsRasterOperations.Draw(memory, rastPort, targetX, 1));
        var expected = new byte[26];
        var firstRowSamples = checked((int)((targetX + 1) >> 1));
        for (var x = 0; x < 104; x++)
        {
            var row = x < firstRowSamples ? 0 : 1;
            var offset = (row * 13) + (x >> 3);
            expected[offset] |= (byte)(1 << (7 - (x & 7)));
        }

        for (uint index = 0; index < expected.Length; index++)
            Assert.Equal(expected[index], ReadByte(memory, plane + index));
        Assert.Equal(targetX, unchecked((short)ReadWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentX)));
        Assert.Equal((short)1, unchecked((short)ReadWord(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortCurrentY)));
        Assert.Equal(expectedPatternCount, ReadByte(
            memory,
            rastPort + (uint)GraphicsLayouts.RastPortLinePatternCount));
        Assert.Equal(0, ReadWord(memory, rastPort + (uint)GraphicsLayouts.RastPortFlags) &
            GraphicsLayouts.RastPortFirstDot);
    }


    [Fact]
    public void PortableContractSignaturesDoNotLeakHostOrCyberGraphicsTypes()
    {
        var assembly = typeof(GraphicsLibraryCore).Assembly;
        var portableTypes = assembly.GetTypes()
            .Where(type => type.Namespace?.StartsWith("CopperMod.Amiga.CopperStart.Graphics.Portable", StringComparison.Ordinal) == true)
            .ToArray();

        Assert.NotEmpty(portableTypes);

        foreach (var type in portableTypes)
        {
            foreach (var memberType in GetSignatureTypes(type))
            {
                var name = memberType.FullName ?? memberType.Name;
                Assert.DoesNotContain("M68kCpuState", name, StringComparison.Ordinal);
                Assert.DoesNotContain("HostGuestMemory", name, StringComparison.Ordinal);
                Assert.DoesNotContain("CyberGraphics", name, StringComparison.Ordinal);
                Assert.DoesNotContain("Avalonia", name, StringComparison.Ordinal);
            }
        }
    }

    private static IEnumerable<Type> GetSignatureTypes(Type type)
    {
        yield return type;

        foreach (var field in type.GetFields(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic))
            yield return field.FieldType;

        foreach (var property in type.GetProperties(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic))
            yield return property.PropertyType;

        foreach (var constructor in type.GetConstructors(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic))
        {
            foreach (var parameter in constructor.GetParameters())
                yield return parameter.ParameterType;
        }

        foreach (var method in type.GetMethods(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic))
        {
            yield return method.ReturnType;
            foreach (var parameter in method.GetParameters())
                yield return parameter.ParameterType;
        }
    }

    private static GraphicsLibraryCore CreateCore(
        IGraphicsMemory memory,
        IGraphicsDisplayBackend? display = null,
        IGraphicsAllocatorBackend? allocator = null)
    {
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint plane0 = 0x400;
        const uint plane1 = 0x500;
        memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2);
        memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 8);
        memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0);
        memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 0xFF);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 3);
        memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1);
        memory.TryWriteWord(rastPort + (uint)GraphicsLayouts.RastPortLinePattern, 0xFFFF);
        return new GraphicsLibraryCore(
            memory,
            allocator ?? new FakeAllocator(),
            new FakeBlitter(),
            display ?? new FakeDisplay());
    }

    private static void AssertCompleteBpr14ShallowRaster(
        AmigaBus bus,
        uint plane,
        uint targetX)
    {
        var expected = new byte[28];
        var firstRowSamples = checked((int)((targetX + 1) >> 1));
        for (var x = 0; x < 112; x++)
        {
            var row = x < firstRowSamples ? 0 : 1;
            var offset = row * 14 + (x >> 3);
            expected[offset] |= (byte)(1 << (7 - (x & 7)));
        }

        for (uint offset = 0; offset < expected.Length; offset++)
            Assert.Equal(expected[offset], bus.ReadByte(plane + offset));
    }

