        Assert.True(memory.TryWriteWord(viewPort + (uint)GraphicsLayouts.ViewPortDHeight, 200));
    }

    private static GraphicsServices CreateHostGraphicsServices(
        HostGuestMemory memory,
        Action<M68kCpuState>? waitTof = null,
        Action<M68kCpuState>? loadView = null,
        Func<M68kCpuState, bool>? tryLoadView = null,
        Func<long, ushort>? beamPosition = null,
        Func<uint, long, long>? waitForViewportBottom = null,
        Func<int, uint, uint>? allocateMemory = null,
        Action<uint, int>? freeMemory = null,
        Action<uint>? initializeCompatibilityViewPort = null,
        Action? requestDisplayRebuild = null,
        Func<uint, uint>? getViewPortModeId = null,
        Func<uint, uint, uint>? getBitMapAttr = null,
        Func<uint, bool>? isRtgBitMap = null,
        Func<M68kCpuState, uint>? allocBitMap = null,
        Action<uint>? freeCprList = null,
        Func<uint, bool>? tryFreeCprList = null,
        Action<uint>? freeVPortCopLists = null,
        Func<uint, bool>? tryFreeVPortCopLists = null,
        Func<uint, bool>? syncSBitMap = null,
        Func<uint, bool>? copySBitMap = null,
        Func<uint, uint, ushort>? calcIvg = null,
        Func<uint, uint>? setChipRev = null,
        Action<uint, uint, uint, uint, long>? scheduleDoubleBufferMessages = null,
        Action<M68kCpuState>? loadRgb4 = null,
        Action<M68kCpuState>? setRgb4 = null,
        Action<M68kCpuState>? setRgb32 = null,
        Action<uint, uint>? drawGList = null,
        Action<uint>? doCollision = null,
        Action<uint, uint, uint>? remIBob = null,
        Action<uint>? waitForBeginningOfVerticalBlank = null,
        Action<uint, uint, short, short>? moveSprite = null,
        Action<uint, uint, uint>? changeSprite = null,
        Action? ownBlitter = null,
        Action? disownBlitter = null,
        Action? waitBlit = null,
        Action<uint>? submitBlit = null,
        Action<uint, bool, short>? submitQueuedBlit = null,
        Action<uint>? cancelDoubleBufferMessages = null,
        IGraphicsLayerRasterBackend? layerRaster = null,
        Func<uint, uint, uint>? changeViewPortBitMap = null,
        Func<M68kCpuState, uint>? bltBitMap = null,
        Func<M68kCpuState, uint>? clipBlit = null,
        Func<M68kCpuState, uint>? bltBitMapRastPort = null,
        Action<uint>? freeBitMap = null,
        Action<uint>? requestViewportDisplayRebuild = null,
        Action<long>? requestDisplayRebuildTimed = null,
        Action<uint, long>? requestViewportDisplayRebuildTimed = null,
        Func<M68kCpuState, uint>? mergeCopperLists = null,
        Func<M68kCpuState, uint>? makeViewPort = null,
        IGraphicsFontListBackend? fontList = null,
        uint graphicsLibraryBase = 0,
        Action<uint>? lockLayerRom = null,
        Func<uint, bool>? attemptLockLayerRom = null,
        Action<uint>? unlockLayerRom = null,
        Func<bool>? preferProviderBitMapAllocations = null,
        bool allowGuestOwnedDbufInfo = false,
        Func<bool>? tryOwnBlitter = null,
        Func<bool>? tryDisownBlitter = null,
        Func<bool>? tryWaitBlit = null,
        Func<uint, bool, short, bool>? trySubmitQueuedBlit = null,
        IGraphicsTimedBlitterBackend? timedBlitter = null,
        Func<uint, uint, short, uint, bool, bool, (bool Handled, int SpriteNumber)>? tryGetExtSprite = null,
        Func<uint, uint, uint, uint, uint, bool, bool, (bool Handled, bool Success)>? tryChangeExtSprite = null,
        IGraphicsLayerBackend? layers = null,
        Func<uint, uint, bool>? isDisplayDmaRange = null,
        Func<uint>? ensureCompatibilityFont = null,
        bool defaultMonitorNtsc = false,
        bool supportsEcsDisplay = true)
    {
        static uint Zero(M68kCpuState state) => 0;
        static void NoOp(M68kCpuState state) { }
        static uint ZeroPair(uint first, uint second) => 0;
        static uint EnsureHost() => 0;
        static void Free(uint address) { }
        static uint ZeroAttr(uint address, uint attribute) => 0;

        var context = new CopperStartGraphicsContext(
            memory,
            waitTof,
            static (_, _, _) => { },
            static _ => { },
            requestDisplayRebuild,
            initializeCompatibilityViewPort ?? (static _ => { }),
            address => memory.IsMapped(address, GraphicsLayouts.RastPortMinimumSize),
            ensureCompatibilityFont ?? EnsureHost,
            static (_, _) => { },
            bltBitMap ?? Zero,
            clipBlit ?? Zero,
            bltBitMapRastPort ?? Zero,
            allocBitMap ?? Zero,
            freeBitMap ?? Free,
            getBitMapAttr ?? ZeroAttr,
            changeViewPortBitMap ?? ZeroPair,
            mergeCopperLists ?? Zero,
            makeViewPort ?? Zero,
            loadView,
            loadRgb4 ?? NoOp,
            setRgb4 ?? NoOp,
            EnsureHost,
            NoOp,
            NoOp,
            NoOp,
            NoOp,
            beamPosition,
            waitForViewportBottom,
            allocateMemory,
            freeMemory,
            getViewPortModeId,
            isRtgBitMap,
            null,
            freeCprList,
            freeVPortCopLists,
            fontList,
            syncSBitMap,
            copySBitMap,
            calcIvg,
            setChipRev,
            scheduleDoubleBufferMessages,
            drawGList,
            doCollision,
            remIBob,
            null,
            null,
            waitForBeginningOfVerticalBlank,
            moveSprite,
            changeSprite,
            ownBlitter,
            disownBlitter,
            waitBlit,
            submitBlit,
            submitQueuedBlit,
            cancelDoubleBufferMessages,
            layerRaster,
            tryLoadView: tryLoadView,
            requestViewportDisplayRebuild: requestViewportDisplayRebuild,
            graphicsLibraryBase: graphicsLibraryBase,
            lockLayerRom: lockLayerRom,
            attemptLockLayerRom: attemptLockLayerRom,
            unlockLayerRom: unlockLayerRom,
            requestDisplayRebuildTimed: requestDisplayRebuildTimed,
            requestViewportDisplayRebuildTimed: requestViewportDisplayRebuildTimed,
            tryFreeCprList: tryFreeCprList,
            tryFreeVPortCopLists: tryFreeVPortCopLists,
            preferProviderBitMapAllocations: preferProviderBitMapAllocations,
            tryOwnBlitter: tryOwnBlitter,
            tryDisownBlitter: tryDisownBlitter,
            tryWaitBlit: tryWaitBlit,
            trySubmitQueuedBlit: trySubmitQueuedBlit,
            timedBlitter: timedBlitter,
            tryGetExtSprite: tryGetExtSprite,
            tryChangeExtSprite: tryChangeExtSprite,
            isDisplayDmaRange: isDisplayDmaRange,
            defaultMonitorNtsc: defaultMonitorNtsc,
            supportsEcsDisplay: supportsEcsDisplay,
            setRgb32: setRgb32);
        return new GraphicsServices(
            context,
            allowGuestOwnedDbufInfo: allowGuestOwnedDbufInfo,
            layers: layers);
    }

    private static void WriteJmp(byte[] image, uint imageBase, uint vectorAddress, uint target)
    {
        var offset = checked((int)(vectorAddress - imageBase));
        image[offset] = 0x4E;
        image[offset + 1] = 0xF9;
        image[offset + 2] = unchecked((byte)(target >> 24));
        image[offset + 3] = unchecked((byte)(target >> 16));
        image[offset + 4] = unchecked((byte)(target >> 8));
        image[offset + 5] = unchecked((byte)target);
    }

    private static byte[] ReadBusBytes(AmigaBus bus, uint address, int length)
    {
        var bytes = new byte[length];
        for (var index = 0; index < length; index++)
            bytes[index] = bus.ReadByte(address + (uint)index);
        return bytes;
    }

    private static void WritePointer(
        AmigaBus bus,
        uint highRegisterAddress,
        uint pointer,
        ref long cycle)
    {
        bus.WriteWord(
            highRegisterAddress,
            (ushort)(pointer >> 16),
            ref cycle,
            AmigaBusAccessKind.CpuDataWrite);
        bus.WriteWord(
            highRegisterAddress + 2,
            (ushort)pointer,
            ref cycle,
            AmigaBusAccessKind.CpuDataWrite);
    }

    private static ushort ReadWord(FakeMemory memory, uint address)
    {
        Assert.True(memory.TryReadWord(address, out var value));
        return value;
    }

    private static void WritePlanarBitmap(
        IGraphicsMemory memory,
        uint bitMap,
        uint plane0,
        uint plane1,
        ushort rows,
        byte depth = 2)
    {
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, rows));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, depth));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane0));
        if (depth > 1)
            Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, plane1));
    }

    private static void WriteInterleavedBitmap(
        IGraphicsMemory memory,
        uint bitMap,
        uint firstPlane,
        ushort aggregateBytesPerRow,
        ushort rows,
        byte depth)
    {
        Assert.True(depth > 0 && aggregateBytesPerRow % depth == 0);
        Assert.True(memory.TryWriteWord(
            bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow,
            aggregateBytesPerRow));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, rows));
        Assert.True(memory.TryWriteByte(
            bitMap + (uint)GraphicsLayouts.BitMapFlags,
            (byte)(1u << 2)));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, depth));
        var planeBytesPerRow = (uint)(aggregateBytesPerRow / depth);
        for (var plane = 0; plane < depth; plane++)
        {
            Assert.True(memory.TryWriteLong(
                bitMap + (uint)GraphicsLayouts.BitMapPlanes + (uint)(plane * 4),
                firstPlane + (uint)plane * planeBytesPerRow));
        }
    }

    private static void WriteWideBitmap(
        WrappingMemory memory,
        uint bitMap,
        uint plane,
        ushort bytesPerRow,
        ushort rows)
    {
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, bytesPerRow);
        memory.WriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, rows);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapFlags, 0);
        memory.WriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 1);
        memory.WriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, plane);
    }

    private static void WriteWideBitScaleArgs(
        WrappingMemory memory,
        uint address,
        uint source,
        uint destination,
        ushort srcWidth,
        ushort srcHeight,
        ushort xSrcFactor,
        ushort xDestFactor,
        ushort ySrcFactor,
        ushort yDestFactor)
    {
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcX, 0);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcY, 0);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcWidth, srcWidth);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcHeight, srcHeight);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsXSrcFactor, xSrcFactor);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsYSrcFactor, ySrcFactor);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestX, 0);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestY, 0);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestWidth, 0);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestHeight, 0);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsXDestFactor, xDestFactor);
        memory.WriteWord(address + (uint)GraphicsLayouts.BitScaleArgsYDestFactor, yDestFactor);
        memory.WriteLong(address + (uint)GraphicsLayouts.BitScaleArgsSrcBitMap, source);
        memory.WriteLong(address + (uint)GraphicsLayouts.BitScaleArgsDestBitMap, destination);
        memory.WriteLong(address + (uint)GraphicsLayouts.BitScaleArgsFlags, 0);
    }

    private static void WriteBitScaleArgs(
        FakeMemory memory,
        uint address,
        uint source,
        uint destination,
        ushort srcWidth,
        ushort srcHeight,
        ushort xSrcFactor,
        ushort xDestFactor,
        ushort ySrcFactor,
        ushort yDestFactor,
        ushort destX = 0,
        ushort destY = 0)
    {
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcX, 0));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcY, 0));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcWidth, srcWidth));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsSrcHeight, srcHeight));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsXSrcFactor, xSrcFactor));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsYSrcFactor, ySrcFactor));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestX, destX));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestY, destY));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestWidth, 0));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsDestHeight, 0));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsXDestFactor, xDestFactor));
        Assert.True(memory.TryWriteWord(address + (uint)GraphicsLayouts.BitScaleArgsYDestFactor, yDestFactor));
        Assert.True(memory.TryWriteLong(address + (uint)GraphicsLayouts.BitScaleArgsSrcBitMap, source));
        Assert.True(memory.TryWriteLong(address + (uint)GraphicsLayouts.BitScaleArgsDestBitMap, destination));
        Assert.True(memory.TryWriteLong(address + (uint)GraphicsLayouts.BitScaleArgsFlags, 0));
    }

    private static void WriteTag(FakeMemory memory, uint address, uint tag, uint value)
    {
        Assert.True(memory.TryWriteLong(address, tag));
        Assert.True(memory.TryWriteLong(address + 4, value));
    }

