    {
        Assert.True(memory.TryWriteLong(textAttr + (uint)GraphicsLayouts.TextAttrName, name));
        Assert.True(memory.TryWriteWord(textAttr + (uint)GraphicsLayouts.TextAttrYSize, ySize));
