    private static void WriteFontHeader(
        FakeMemory memory,
        uint font,
        uint name,
        ushort ySize,
        byte style,
        byte flags)
    {
        memory.TryWriteLong(font + (uint)GraphicsLayouts.TextFontName, name);
        memory.TryWriteWord(font + (uint)GraphicsLayouts.TextFontYSize, ySize);
