    private static void WriteAscii(FakeMemory memory, uint address, string value)
    {
        for (var index = 0; index < value.Length; index++)
            Assert.True(memory.TryWriteByte(address + (uint)index, (byte)value[index]));

        Assert.True(memory.TryWriteByte(address + (uint)value.Length, 0));
    }

    private static byte ReadByte(IGraphicsMemory memory, uint address)
    {
        Assert.True(memory.TryReadByte(address, out var value));
        return value;
    }

    private static byte[] ReadBytes(IGraphicsMemory memory, uint address, uint length)
    {
        var bytes = new byte[checked((int)length)];
        for (var index = 0u; index < length; index++)
            bytes[index] = ReadByte(memory, address + index);
        return bytes;
    }

    private static short ReadSignedWord(FakeMemory memory, uint address)
        => unchecked((short)ReadWord(memory, address));

    private static void WriteRectangle(
        FakeMemory memory,
        uint address,
        short minX,
        short minY,
        short maxX,
        short maxY)
    {
        Assert.True(memory.TryWriteWord(
            address + (uint)GraphicsLayouts.RectangleMinX,
            unchecked((ushort)minX)));
        Assert.True(memory.TryWriteWord(
            address + (uint)GraphicsLayouts.RectangleMinY,
            unchecked((ushort)minY)));
        Assert.True(memory.TryWriteWord(
            address + (uint)GraphicsLayouts.RectangleMaxX,
            unchecked((ushort)maxX)));
        Assert.True(memory.TryWriteWord(
            address + (uint)GraphicsLayouts.RectangleMaxY,
            unchecked((ushort)maxY)));
    }

    private static bool RegionContains(
        FakeMemory memory,
        uint region,
        short x,
        short y)
    {
        var originX = ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds);
        var originY = ReadSignedWord(memory, region + (uint)GraphicsLayouts.RegionBounds + 2u);
        var node = ReadLong(memory, region + (uint)GraphicsLayouts.RegionRectangle);
        for (var count = 0; node != 0 && count < 4096; count++)
        {
            var minX = originX + ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds);
            var minY = originY + ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds + 2);
            var maxX = originX + ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds + 4);
            var maxY = originY + ReadSignedWord(memory, node + (uint)GraphicsLayouts.RegionRectangleBounds + 6);
            if (x >= minX && x <= maxX && y >= minY && y <= maxY)
                return true;

            node = ReadLong(memory, node + (uint)GraphicsLayouts.RegionRectangleNext);
        }

        return false;
    }

    private static uint ReadLong(IGraphicsMemory memory, uint address)
    {
        Assert.True(memory.TryReadLong(address, out var value));
        return value;
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveMonitorLifecycleParityAgainstFullNativeEnvelope()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint monitorVectorTarget = 0x00FC_2200;
        const uint firstMonitorAllocation = 0x00FB_0000;

        static void InitializeNativeBase(AmigaBus bus, uint baseAddress)
        {
            bus.MapWritableMemory(
                baseAddress,
                new byte[GraphicsLayouts.GfxBaseNativeSize]);
            var list = baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorList;
            bus.WriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
                list + 4u);
            bus.WriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
                0);
            bus.WriteLong(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
                list);
            bus.WriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListType,
                0,
                0);
            bus.WriteByte(
                baseAddress + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
                0,
                0);
        }

        static Func<int, uint, uint> CreateAllocator(
            AmigaBus bus,
            uint initialAddress)
        {
            var nextAddress = initialAddress;
            return (byteCount, _) =>
            {
                var address = nextAddress;
                nextAddress = checked(
                    address + ((((uint)byteCount) + 1u) & ~1u) + 0x20u);
                bus.MapWritableMemory(
                    address,
                    new byte[checked((int)byteCount)]);
                return address;
            };
        }

        var directBus = new AmigaBus();
        var overlayBus = new AmigaBus();
        foreach (var bus in new[] { directBus, overlayBus })
        {
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
                monitorVectorTarget);
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseMonitor)),
                monitorVectorTarget + 2u);
            bus.MapReadOnlyMemory(imageBase, image);
            InitializeNativeBase(bus, nativeBase);
        }

        using var direct = CreateHostGraphicsServices(
            new HostGuestMemory(directBus),
            graphicsLibraryBase: nativeBase,
            allocateMemory: CreateAllocator(directBus, firstMonitorAllocation));
        using var overlay = CreateHostGraphicsServices(
            new HostGuestMemory(overlayBus),
            graphicsLibraryBase: nativeBase,
            allocateMemory: CreateAllocator(overlayBus, firstMonitorAllocation));
        Assert.True(overlay.InstallKickstartRomOverlay(nativeBase));

        var directOpen = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor, [1] = 0xDEAD_BEEFu },
            Cycles = 401
        };
        var overlayOpen = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor, [1] = 0xDEAD_BEEFu },
            Cycles = 401
        };
        direct.Invoke(directOpen, (int)GraphicsLvo.OpenMonitor);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
            overlayOpen));

        Assert.NotEqual(0u, directOpen.D[0]);
        Assert.NotEqual(0u, overlayOpen.D[0]);
        Assert.Equal(0xDEAD_BEEFu, directOpen.D[1]);
        Assert.Equal(directOpen.D[1], overlayOpen.D[1]);
        Assert.Equal(directOpen.Cycles, overlayOpen.Cycles);
        Assert.Equal(
            (ushort)1,
            directBus.ReadWord(
            directOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            (ushort)1,
            overlayBus.ReadWord(
                overlayOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            directOpen.D[0],
            directBus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            overlayOpen.D[0],
            overlayBus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));

        var directReopen = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor },
            Cycles = 409
        };
        var overlayReopen = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor },
            Cycles = 409
        };
        direct.Invoke(directReopen, (int)GraphicsLvo.OpenMonitor);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
            overlayReopen));
        Assert.Equal(directOpen.D[0], directReopen.D[0]);
        Assert.Equal(overlayOpen.D[0], overlayReopen.D[0]);
        Assert.Equal(
            (ushort)2,
            directBus.ReadWord(
                directOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            (ushort)2,
            overlayBus.ReadWord(
                overlayOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        var directClose = new M68kCpuState
        {
            A = { [0] = directOpen.D[0] },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 419
        };
        var overlayClose = new M68kCpuState
        {
            A = { [0] = overlayOpen.D[0] },
            D = { [0] = 0x1357_9BDFu },
            Cycles = 419
        };
        direct.Invoke(directClose, (int)GraphicsLvo.CloseMonitor);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseMonitor)),
            overlayClose));
        Assert.Equal(0u, directClose.D[0]);
        Assert.Equal(directClose.D[0], overlayClose.D[0]);
        Assert.Equal(directClose.Cycles, overlayClose.Cycles);
        Assert.Equal(
            (ushort)1,
            directBus.ReadWord(
                directOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            (ushort)1,
            overlayBus.ReadWord(
                overlayOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));

        var directCloseLast = new M68kCpuState
        {
            A = { [0] = directOpen.D[0] },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 431
        };
        var overlayCloseLast = new M68kCpuState
        {
            A = { [0] = overlayOpen.D[0] },
            D = { [0] = 0x2468_ACE0u },
            Cycles = 431
        };
        direct.Invoke(directCloseLast, (int)GraphicsLvo.CloseMonitor);
        Assert.True(overlayBus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseMonitor)),
            overlayCloseLast));
        Assert.Equal(0u, directCloseLast.D[0]);
        Assert.Equal(directCloseLast.D[0], overlayCloseLast.D[0]);
        Assert.Equal(directCloseLast.Cycles, overlayCloseLast.Cycles);
        Assert.Equal(
            (ushort)0,
            directBus.ReadWord(
                directOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            (ushort)0,
            overlayBus.ReadWord(
                overlayOpen.D[0] + (uint)GraphicsLayouts.MonitorSpecOpenCount));
        Assert.Equal(
            directOpen.D[0],
            directBus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            overlayOpen.D[0],
            overlayBus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
    }

    [Fact]
    public void NativeOverlayRebindsAndAppendsAfterPreexistingProviderMonitor()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint providerMonitor = 0x00FB_0000;
        const uint firstAllocation = 0x00FB_1000;
        const uint nativeTarget = 0x00FC_2400;

        var bus = new AmigaBus();
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
            nativeTarget);
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(
            nativeBase,
            new byte[GraphicsLayouts.GfxBaseNativeSize]);

        var list = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        var providerSuccessor = list + 4u;
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead,
            providerMonitor);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTail,
            0);
        bus.WriteLong(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred,
            providerMonitor);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListType,
            0,
            0);
        bus.WriteByte(
            nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListPad,
            0,
            0);
        bus.MapWritableMemory(providerMonitor, new byte[GraphicsLayouts.MonitorSpecSize]);
        bus.WriteLong(providerMonitor, providerSuccessor);
        bus.WriteLong(providerMonitor + 4u, list);

        var nextAllocation = firstAllocation;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (byteCount, _) =>
            {
                var address = nextAllocation;
                nextAllocation = checked(address + (uint)byteCount + 0x20u);
                bus.MapWritableMemory(address, new byte[byteCount]);
                return address;
            },
            graphicsLibraryBase: 0);

        // A resident/provider MonitorSpec is already linked.  Overlay
        // admission must still recognize the full native envelope, rebind
        // the portable registry to this base, and append its own node after
        // the provider-owned one instead of silently using the compact base.
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));

        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor },
            Cycles = 463,
            ProgramCounter = 0x0012_3741
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
            state));
        Assert.NotEqual(0u, state.D[0]);
        Assert.NotEqual(providerMonitor, state.D[0]);
        Assert.Equal(463, state.Cycles);
        Assert.Equal(
            providerMonitor,
            bus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            state.D[0],
            bus.ReadLong(providerMonitor));
        Assert.Equal(
            providerMonitor,
            bus.ReadLong(state.D[0] + 4u));
        Assert.Equal(
            state.D[0],
            bus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));

        // Teardown must detach only the portable node and restore the
        // provider-owned list, even though the native list was linked before
        // overlay admission.
        services.Dispose();
        Assert.Equal(
            providerMonitor,
            bus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
        Assert.Equal(
            providerSuccessor,
            bus.ReadLong(providerMonitor));
        Assert.Equal(
            providerMonitor,
            bus.ReadLong(
                nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListTailPred));
    }

    [Fact]
    public void NativeOverlayOpenMonitorPreflightsReadOnlyNativeBaseBeforeAllocation()
    {
        const uint imageBase = 0x00F9_F000;
        const uint nativeBase = 0x00FA_0000;
        const uint monitorSpec = 0x00FB_0000;
        const uint nativeTarget = 0x00FC_2300;

        static void PutLong(byte[] image, int offset, uint value)
        {
            image[offset] = (byte)(value >> 24);
            image[offset + 1] = (byte)(value >> 16);
            image[offset + 2] = (byte)(value >> 8);
            image[offset + 3] = (byte)value;
        }

        var vectorImage = new byte[0x2000];
        WriteJmp(
            vectorImage,
            imageBase,
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
            nativeTarget);

        var nativeImage = new byte[GraphicsLayouts.GfxBaseNativeSize];
        var monitorList = nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorList;
        PutLong(
            nativeImage,
            GraphicsLayouts.GfxBaseMonitorListHead,
            monitorList + 4u);
        PutLong(nativeImage, GraphicsLayouts.GfxBaseMonitorListTail, 0);
        PutLong(
            nativeImage,
            GraphicsLayouts.GfxBaseMonitorListTailPred,
            monitorList);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, vectorImage);
        // The native list is structurally valid but provider-owned/read-only.
        // OpenMonitor must decline before it asks the compatibility allocator
        // for a resident MonitorSpec.
        bus.MapReadOnlyMemory(nativeBase, nativeImage);

        var allocationCalls = 0;
        var freeCalls = 0;
        var trackMonitorAllocations = false;
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            graphicsLibraryBase: nativeBase,
            allocateMemory: (byteCount, _) =>
            {
                if (trackMonitorAllocations)
                    allocationCalls++;

                if (byteCount == GraphicsLayouts.MonitorSpecSize)
                {
                    bus.MapWritableMemory(monitorSpec, new byte[byteCount]);
                    return monitorSpec;
                }

                var sidecar = 0x00FB_1000u;
                bus.MapWritableMemory(sidecar, new byte[byteCount]);
                return sidecar;
            },
            freeMemory: (_, _) => freeCalls++);
        Assert.True(services.InstallKickstartRomOverlay(nativeBase));
        allocationCalls = 0;
        freeCalls = 0;
        trackMonitorAllocations = true;

        var state = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor, [1] = 0xDEAD_BEEFu },
            Cycles = 457,
            ProgramCounter = 0x0012_3721
        };

        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenMonitor)),
            state));
        Assert.Equal(nativeTarget, state.ProgramCounter);
        Assert.Equal(GraphicsModeIds.PalMonitor, state.D[0]);
        Assert.Equal(0xDEAD_BEEFu, state.D[1]);
        Assert.Equal(457, state.Cycles);
        Assert.Equal(0, allocationCalls);
        Assert.Equal(0, freeCalls);
        Assert.Equal(
            monitorList + 4u,
            bus.ReadLong(nativeBase + (uint)GraphicsLayouts.GfxBaseMonitorListHead));
    }

    [Fact]
    public void NativeOverlayDeclinesReadOnlyOwnedMonitorBeforeClosePublication()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint monitorSpec = 0x1000;
        const uint closeTarget = 0x00FA_F401;
        var image = new byte[0x2000];
        WriteJmp(
            image,
            imageBase,
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CloseMonitor)),
            closeTarget);

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        bus.MapWritableMemory(monitorSpec, new byte[GraphicsLayouts.MonitorSpecSize]);
        using var services = CreateHostGraphicsServices(
            new HostGuestMemory(bus),
            allocateMemory: (byteCount, _) =>
            {
                Assert.Equal(GraphicsLayouts.MonitorSpecSize, byteCount);
                return monitorSpec;
            });
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        var open = new M68kCpuState
        {
            A = { [1] = 0 },
            D = { [0] = GraphicsModeIds.PalMonitor },
            Cycles = 443
        };
        services.Invoke(open, (int)GraphicsLvo.OpenMonitor);
        Assert.Equal(monitorSpec, open.D[0]);
        var originalOpenCount = bus.ReadWord(
            monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount);
        Assert.Equal((ushort)1, originalOpenCount);

        var readOnlyEnvelope = Enumerable.Range(0, GraphicsLayouts.MonitorSpecSize)
            .Select(offset => bus.ReadByte(monitorSpec + (uint)offset))
            .ToArray();
        bus.MapReadOnlyMemory(monitorSpec, readOnlyEnvelope);

        var close = new M68kCpuState
        {
            A = { [0] = monitorSpec },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 449,
            ProgramCounter = 0x0012_3711
        };
        Assert.True(bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)graphicsBase + (int)GraphicsLvo.CloseMonitor)),
            close));
        Assert.Equal(closeTarget, close.ProgramCounter);
        Assert.Equal(0xCAFE_BABEu, close.D[0]);
        Assert.Equal(449, close.Cycles);
        Assert.Equal(
            originalOpenCount,
            bus.ReadWord(monitorSpec + (uint)GraphicsLayouts.MonitorSpecOpenCount));
    }

    [Fact]
    public void NativeOverlayAndHostGatewayPreserveFontLifecycleParity()
    {
        const uint imageBase = 0x00F9_F000;
        const uint hostBase = 0x00F8_0000;
        const uint nativeBase = 0x00FA_0000;
        const uint font = 0x00FB_0000;
        const uint name = 0x00FB_0100;
        const uint charData = 0x00FB_0200;
        const uint charLoc = 0x00FB_0400;
        const uint textAttr = 0x00FB_0600;

        static (GraphicsServices Services, HostGuestMemory Memory, AmigaBus Bus) CreateFontPath(
            bool overlayPath,
            uint imageBase,
            uint hostBase,
            uint nativeBase,
            uint font,
            uint name,
            uint charData,
            uint charLoc,
            uint textAttr)
        {
            var bus = new AmigaBus();
            var image = new byte[0x2000];
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
                0x00FC_1100);
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
                0x00FC_1200);
            bus.MapReadOnlyMemory(imageBase, image);
            bus.MapWritableMemory(hostBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
            bus.MapWritableMemory(nativeBase, new byte[GraphicsLayouts.GfxBaseNativeSize]);
            bus.MapWritableMemory(font, new byte[GraphicsLayouts.TextFontMinimumSize]);
            bus.MapWritableMemory(name, new byte[0x40]);
            bus.MapWritableMemory(charData, new byte[0x200]);
            bus.MapWritableMemory(charLoc, new byte[0x200]);
            bus.MapWritableMemory(textAttr, new byte[GraphicsLayouts.TextAttrSize]);

            var memory = new HostGuestMemory(bus);
            var guestMemory = new CopperStartGraphicsMemoryAdapter(memory);
            var list = new GraphicsGuestFontListBackend(guestMemory, hostBase);
            var nativeList = new GraphicsGuestFontListBackend(guestMemory, nativeBase);
            Assert.True(list.Initialize(0));
            Assert.True(nativeList.Initialize(0));

            guestMemory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontName,
                name);
            guestMemory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontYSize,
                8);
            guestMemory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontStyle,
                0);
            guestMemory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontFlags,
                1);
            guestMemory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontXSize,
                8);
            guestMemory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontBaseline,
                7);
            guestMemory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontBoldSmear,
                1);
            guestMemory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontLoChar,
                32);
            guestMemory.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontHiChar,
                127);
            for (var index = 0; index < "parity.font".Length; index++)
            {
                guestMemory.TryWriteByte(
                    name + (uint)index,
                    (byte)"parity.font"[index]);
            }
            guestMemory.TryWriteByte(
                name + (uint)"parity.font".Length,
                0);
            guestMemory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharData,
                charData);
            guestMemory.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontModulo,
                1);
            guestMemory.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharLoc,
                charLoc);
            for (var index = 0; index <= 96; index++)
            {
                guestMemory.TryWriteWord(
                    charLoc + (uint)(index * 2),
                    unchecked((ushort)(index * 8)));
            }

            guestMemory.TryWriteLong(
                textAttr + (uint)GraphicsLayouts.TextAttrName,
                name);
            guestMemory.TryWriteWord(
                textAttr + (uint)GraphicsLayouts.TextAttrYSize,
                8);
            guestMemory.TryWriteByte(
                textAttr + (uint)GraphicsLayouts.TextAttrStyle,
                0);
            guestMemory.TryWriteByte(
                textAttr + (uint)GraphicsLayouts.TextAttrFlags,
                0);

            var fonts = new GraphicsMemoryFontBackend(
                guestMemory,
                fontList: list);
            var nativeFonts = new GraphicsMemoryFontBackend(
                guestMemory,
                fontList: nativeList);
            if (overlayPath)
            {
                Assert.True(nativeFonts.TryAdd(font));
                Assert.True(nativeList.SetDefaultFont(font));
            }
            else
            {
                Assert.True(fonts.TryAdd(font));
                Assert.True(list.SetDefaultFont(font));
            }

            var services = CreateHostGraphicsServices(
                memory,
                fontList: list);
            if (overlayPath)
                Assert.True(services.InstallKickstartRomOverlay(nativeBase));

            return (services, memory, bus);
        }

        var direct = CreateFontPath(
            overlayPath: false,
            imageBase,
            hostBase,
            nativeBase,
            font,
            name,
            charData,
            charLoc,
            textAttr);
        var overlay = CreateFontPath(
            overlayPath: true,
            imageBase,
            hostBase,
            nativeBase,
            font,
            name,
            charData,
            charLoc,
            textAttr);

        var directOpen = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 307
        };
        var overlayOpen = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0xA5A5_5A5Au },
            Cycles = 307
        };

        using var directServices = direct.Services;
        using var overlayServices = overlay.Services;

        var unopenedResidentClose = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xBADC_0FFEu },
            Cycles = 301,
            ProgramCounter = 0x0012_4301
        };
        Assert.True(overlay.Bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            unopenedResidentClose));
        Assert.Equal(0x00FC_1200u, unopenedResidentClose.ProgramCounter);
        Assert.Equal(0xBADC_0FFEu, unopenedResidentClose.D[0]);
        Assert.Equal(301, unopenedResidentClose.Cycles);
        Assert.Equal(
            (ushort)0,
            overlay.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        directServices.Invoke(directOpen, (int)GraphicsLvo.OpenFont);
        Assert.True(overlay.Bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            overlayOpen));
        Assert.Equal(font, directOpen.D[0]);
        Assert.Equal(directOpen.D[0], overlayOpen.D[0]);
        Assert.Equal(directOpen.Cycles, overlayOpen.Cycles);
        Assert.Equal(
            (ushort)1,
            direct.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(
            (ushort)1,
            overlay.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        var directReopen = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0x1234_5678u },
            Cycles = 313
        };
        var overlayReopen = new M68kCpuState
        {
            A = { [0] = textAttr },
            D = { [0] = 0x1234_5678u },
            Cycles = 313
        };
        directServices.Invoke(directReopen, (int)GraphicsLvo.OpenFont);
        Assert.True(overlay.Bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.OpenFont)),
            overlayReopen));
        Assert.Equal(font, directReopen.D[0]);
        Assert.Equal(directReopen.D[0], overlayReopen.D[0]);
        Assert.Equal(directReopen.Cycles, overlayReopen.Cycles);
        Assert.Equal(
            (ushort)2,
            direct.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(
            (ushort)2,
            overlay.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        var directClose = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 317
        };
        var overlayClose = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xCAFE_BABEu },
            Cycles = 317
        };
        directServices.Invoke(directClose, (int)GraphicsLvo.CloseFont);
        Assert.True(overlay.Bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            overlayClose));
        Assert.Equal(0u, directClose.D[0]);
        Assert.Equal(directClose.D[0], overlayClose.D[0]);
        Assert.Equal(directClose.Cycles, overlayClose.Cycles);
        Assert.Equal(
            (ushort)1,
            direct.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(
            (ushort)1,
            overlay.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        var directCloseLast = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 331
        };
        var overlayCloseLast = new M68kCpuState
        {
            A = { [1] = font },
            D = { [0] = 0xDEAD_BEEFu },
            Cycles = 331
        };
        directServices.Invoke(directCloseLast, (int)GraphicsLvo.CloseFont);
        Assert.True(overlay.Bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            overlayCloseLast));
        Assert.Equal(0u, directCloseLast.D[0]);
        Assert.Equal(directCloseLast.D[0], overlayCloseLast.D[0]);
        Assert.Equal(directCloseLast.Cycles, overlayCloseLast.Cycles);
        Assert.Equal(
            (ushort)0,
            direct.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));
        Assert.Equal(
            (ushort)0,
            overlay.Bus.ReadWord(font + (uint)GraphicsLayouts.TextFontAccessors));

        var foreignClose = new M68kCpuState
        {
            A = { [1] = 0x00FB_0800u },
            D = { [0] = 0xFACE_C0DEu },
            Cycles = 337,
            ProgramCounter = 0x0012_4401
        };
        Assert.True(overlay.Bus.TryInvokeHostGatewayAt(
            unchecked((uint)((int)nativeBase + (int)GraphicsLvo.CloseFont)),
            foreignClose));
        Assert.Equal(0x00FC_1200u, foreignClose.ProgramCounter);
        Assert.Equal(0xFACE_C0DEu, foreignClose.D[0]);
        Assert.Equal(337, foreignClose.Cycles);
    }

    [Fact]
    public void NativeOverlayLeavesLayerLockVectorsToKickstartWithoutALayerProvider()
    {
        const uint imageBase = 0x00F8_F000;
        const uint graphicsBase = 0x00F9_0000;
        const uint layer = 0x120;
        var image = new byte[0x2000];
        var targets = new Dictionary<GraphicsLvo, uint>
        {
            [GraphicsLvo.LockLayerRom] = 0x00FA_2100,
            [GraphicsLvo.AttemptLockLayerRom] = 0x00FA_2200,
            [GraphicsLvo.UnlockLayerRom] = 0x00FA_2300
        };
        foreach (var pair in targets)
        {
            WriteJmp(
                image,
                imageBase,
                unchecked((uint)((int)graphicsBase + (int)pair.Key)),
                pair.Value);
        }

        var bus = new AmigaBus();
        bus.MapReadOnlyMemory(imageBase, image);
        using var services = CreateHostGraphicsServices(new HostGuestMemory(bus));
        Assert.True(services.InstallKickstartRomOverlay(graphicsBase));

        foreach (var pair in targets)
        {
            var state = new M68kCpuState
            {
                A = { [5] = layer },
                D = { [0] = 0xBEEF_1234u },
                Cycles = 359,
                ProgramCounter = 0x0012_4501
            };

            Assert.True(bus.TryInvokeHostGatewayAt(
                unchecked((uint)((int)graphicsBase + (int)pair.Key)),
                state));
            Assert.Equal(pair.Value, state.ProgramCounter);
            Assert.Equal(0xBEEF_1234u, state.D[0]);
            Assert.Equal(359, state.Cycles);
        }
    }

    [Fact]
    public void PortableRegionRejectsMalformedPredecessorBeforeClippingMutation()
    {
        var memory = new FakeMemory(0x1000);
        var allocator = new SequenceAddressAllocator();
        const uint region = 0x100;
        const uint node = 0x200;
        const uint rectangle = 0x300;

        Assert.True(memory.TryWriteWord(region + (uint)GraphicsLayouts.RegionBounds +
            (uint)GraphicsLayouts.RectangleMinX, 0));
        Assert.True(memory.TryWriteWord(region + (uint)GraphicsLayouts.RegionBounds +
            (uint)GraphicsLayouts.RectangleMinY, 0));
        Assert.True(memory.TryWriteWord(region + (uint)GraphicsLayouts.RegionBounds +
            (uint)GraphicsLayouts.RectangleMaxX, 4));
        Assert.True(memory.TryWriteWord(region + (uint)GraphicsLayouts.RegionBounds +
            (uint)GraphicsLayouts.RectangleMaxY, 4));
        Assert.True(memory.TryWriteLong(
            region + (uint)GraphicsLayouts.RegionRectangle, node));
        Assert.True(memory.TryWriteLong(
            node + (uint)GraphicsLayouts.RegionRectangleNext, 0));
        Assert.True(memory.TryWriteLong(
            node + (uint)GraphicsLayouts.RegionRectanglePrevious, 0x3F0));
        Assert.True(memory.TryWriteWord(
            node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinX, 0));
        Assert.True(memory.TryWriteWord(
            node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMinY, 0));
        Assert.True(memory.TryWriteWord(
            node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxX, 4));
        Assert.True(memory.TryWriteWord(
            node + (uint)GraphicsLayouts.RegionRectangleBounds +
            (uint)GraphicsLayouts.RectangleMaxY, 4));
        Assert.True(memory.TryWriteWord(
            rectangle + (uint)GraphicsLayouts.RectangleMinX, 1));
        Assert.True(memory.TryWriteWord(
            rectangle + (uint)GraphicsLayouts.RectangleMinY, 1));
        Assert.True(memory.TryWriteWord(
            rectangle + (uint)GraphicsLayouts.RectangleMaxX, 2));
        Assert.True(memory.TryWriteWord(
            rectangle + (uint)GraphicsLayouts.RectangleMaxY, 2));

        var before = memory.Bytes.ToArray();
        var writesBefore = memory.WriteCount;

        Assert.False(GraphicsRegionOperations.AndRectRegion(
            memory, allocator, region, rectangle));
        Assert.Equal(writesBefore, memory.WriteCount);
        Assert.Equal(before, memory.Bytes);
    }

    private sealed class RejectingWriteMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private readonly uint _firstRejected;
        private readonly uint _endRejected;

        internal RejectingWriteMemory(FakeMemory backing, uint firstRejected, uint endRejected)
        {
            _backing = backing;
            _firstRejected = firstRejected;
            _endRejected = endRejected;
        }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
            => IsRejected(address) ? false : _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => IsRejected(address) || IsRejected(address + 1u)
                ? false
                : _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
            => IsRejected(address) ||
               IsRejected(address + 1u) ||
               IsRejected(address + 2u) ||
               IsRejected(address + 3u)
                ? false
                : _backing.TryWriteLong(address, value);

        private bool IsRejected(uint address)
            => address >= _firstRejected && address < _endRejected;
    }

    private sealed class RejectingWordReadMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;

        internal RejectingWordReadMemory(FakeMemory backing)
            => _backing = backing;

