    }

    private sealed class PartialLongWriteMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;

        internal PartialLongWriteMemory(FakeMemory backing)
            => _backing = backing;

        internal bool RejectLongWrites { get; set; }
        internal uint? PartialLongAddress { get; set; }
        internal Func<uint, uint, bool>? RejectLongWrite { get; set; }
        internal Action<uint, uint>? ObserveLongWrite { get; set; }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
        {
            ObserveLongWrite?.Invoke(address, value);
            if (!RejectLongWrites && PartialLongAddress != address &&
                RejectLongWrite?.Invoke(address, value) != true)
                return _backing.TryWriteLong(address, value);

            _ = _backing.TryWriteByte(address, (byte)(value >> 24));
            _ = _backing.TryWriteByte(address + 1u, (byte)(value >> 16));
            return false;
        }
    }

    private sealed class ProbeThenPartialLongWriteMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private bool _probeCompleted;

        internal ProbeThenPartialLongWriteMemory(FakeMemory backing)
            => _backing = backing;

        internal uint? PartialLongAddress { get; set; }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
        {
            if (PartialLongAddress != address)
                return _backing.TryWriteLong(address, value);

            if (!_probeCompleted)
            {
                _probeCompleted = true;
                return _backing.TryWriteLong(address, value);
            }

            // Model a bridge that accepts the first three bytes of the
            // requested LONG and then rejects all later LONG writes to the
            // same field. Byte writes remain available for transaction
            // rollback, as they do on sparse guest adapters.
            _ = _backing.TryWriteByte(address, (byte)(value >> 24));
            _ = _backing.TryWriteByte(address + 1u, (byte)(value >> 16));
            _ = _backing.TryWriteByte(address + 2u, (byte)(value >> 8));
            return false;
        }
    }

    private sealed class ProbeThenFailLongWriteMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private bool _probeCompleted;

        internal ProbeThenFailLongWriteMemory(FakeMemory backing)
            => _backing = backing;

        internal uint? ProbeLongAddress { get; set; }
        internal uint? FailLongAddress { get; set; }

        internal void ResetProbe()
            => _probeCompleted = false;

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
        {
            if (address == ProbeLongAddress)
            {
                if (!_probeCompleted)
                {
                    _probeCompleted = true;
                    return _backing.TryWriteLong(address, value);
                }

                WriteFirstThreeBytes(address, value);
                return false;
            }

            if (address == FailLongAddress)
            {
                WriteFirstThreeBytes(address, value);
                return false;
            }

            return _backing.TryWriteLong(address, value);
        }

        private void WriteFirstThreeBytes(uint address, uint value)
        {
            _ = _backing.TryWriteByte(address, (byte)(value >> 24));
            _ = _backing.TryWriteByte(address + 1u, (byte)(value >> 16));
            _ = _backing.TryWriteByte(address + 2u, (byte)(value >> 8));
        }
    }

