    private sealed class PartialThenRejectLongAndDeferredWordWriteMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private bool _partialLongPublished;
        private int _deferredWordWrites;

        internal PartialThenRejectLongAndDeferredWordWriteMemory(FakeMemory backing)
            => _backing = backing;

        internal uint? PartialLongAddress { get; set; }

        internal uint? DeferredWordAddress { get; set; }

        internal bool ArmDeferredWordFailure { get; set; }

        internal bool RejectDeferredWordImmediately { get; set; }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
        {
            if (!ArmDeferredWordFailure || address != DeferredWordAddress)
                return _backing.TryWriteWord(address, value);

            // The fallback AddFont publication is allowed to set the
            // accessor word to zero. The following restoration is the
            // repeated WORD that this adapter rejects after accepting its
            // high byte; byte-wise rollback must therefore bypass it.
            if (!RejectDeferredWordImmediately && _deferredWordWrites++ == 0)
                return _backing.TryWriteWord(address, value);

            _ = _backing.TryWriteByte(address, (byte)(value >> 8));
            return false;
        }

        public bool TryWriteLong(uint address, uint value)
        {
            if (address != PartialLongAddress)
                return _backing.TryWriteLong(address, value);

            if (!_partialLongPublished)
            {
                _partialLongPublished = true;
                _ = _backing.TryWriteByte(address, (byte)(value >> 24));
                _ = _backing.TryWriteByte(address + 1u, (byte)(value >> 16));
                _ = _backing.TryWriteByte(address + 2u, (byte)(value >> 8));
            }

            return false;
        }
    }

