                : _backing.TryWriteLong(address, value);
    }

    private sealed class RejectingLongReadMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;

        internal RejectingLongReadMemory(FakeMemory backing)
            => _backing = backing;

        internal uint RejectedAddress { get; set; }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
        {
            if (address == RejectedAddress)
            {
                value = 0;
                return false;
            }

            return _backing.TryReadLong(address, out value);
        }

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
            => _backing.TryWriteLong(address, value);
    }

    private sealed class FailingByteWriteMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private int? _failOnWrite;
        private bool _failed;

        internal FailingByteWriteMemory(FakeMemory backing)
        {
            _backing = backing;
        }

        private int WriteCount { get; set; }

        internal void FailOnNextByteWrite(int additionalWrites)
        {
            _failOnWrite = WriteCount + additionalWrites;
            _failed = false;
        }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
        {
            WriteCount++;
            if (!_failed && WriteCount == _failOnWrite)
            {
                _failed = true;
                return false;
            }

            return _backing.TryWriteByte(address, value);
        }

        public bool TryWriteWord(uint address, ushort value)
            => TryWriteByte(address, (byte)(value >> 8)) &&
               TryWriteByte(address + 1u, (byte)value);

        public bool TryWriteLong(uint address, uint value)
            => TryWriteByte(address, (byte)(value >> 24)) &&
               TryWriteByte(address + 1u, (byte)(value >> 16)) &&
               TryWriteByte(address + 2u, (byte)(value >> 8)) &&
               TryWriteByte(address + 3u, (byte)value);
    }

    private sealed class AddressWriteFaultMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private readonly uint _targetAddress;
        private bool _rejected;

        internal AddressWriteFaultMemory(FakeMemory backing, uint targetAddress)
        {
            _backing = backing;
            _targetAddress = targetAddress;
        }

        internal int TargetWriteCount { get; private set; }

        // A value of int.MaxValue leaves the adapter fault-free.  Otherwise
        // the next write after this many successful target writes is rejected
        // once, and subsequent rollback writes are allowed through.
        internal int RejectAfterTargetWrites { get; set; } = int.MaxValue;

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
            => _backing.TryReadWord(address, out value);

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
        {
            if (address == _targetAddress)
            {
                if (!_rejected && TargetWriteCount >= RejectAfterTargetWrites)
                {
                    _rejected = true;
                    return false;
                }

                TargetWriteCount++;
            }

            return _backing.TryWriteByte(address, value);
        }

        public bool TryWriteWord(uint address, ushort value)
            => TryWriteByte(address, (byte)(value >> 8)) &&
               TryWriteByte(address + 1u, (byte)value);

        public bool TryWriteLong(uint address, uint value)
            => TryWriteByte(address, (byte)(value >> 24)) &&
               TryWriteByte(address + 1u, (byte)(value >> 16)) &&
               TryWriteByte(address + 2u, (byte)(value >> 8)) &&
               TryWriteByte(address + 3u, (byte)value);
    }

    private sealed class PatternReadFaultMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private readonly uint _pattern;
        private readonly uint _destinationPlane;
        private bool _faultPatternReads;

        internal PatternReadFaultMemory(
            FakeMemory backing,
            uint pattern,
            uint destinationPlane)
        {
            _backing = backing;
            _pattern = pattern;
            _destinationPlane = destinationPlane;
        }

        public bool TryReadByte(uint address, out byte value)
            => _backing.TryReadByte(address, out value);

        public bool TryReadWord(uint address, out ushort value)
        {
            if (_faultPatternReads && address == _pattern)
            {
                value = 0;
                return false;
            }

            return _backing.TryReadWord(address, out value);
        }

        public bool TryReadLong(uint address, out uint value)
            => _backing.TryReadLong(address, out value);

        public bool TryWriteByte(uint address, byte value)
        {
            var result = _backing.TryWriteByte(address, value);
            if (result && address == _destinationPlane)
                _faultPatternReads = true;
            return result;
        }

        public bool TryWriteWord(uint address, ushort value)
            => TryWriteByte(address, (byte)(value >> 8)) &&
               TryWriteByte(address + 1u, (byte)value);

        public bool TryWriteLong(uint address, uint value)
            => TryWriteByte(address, (byte)(value >> 24)) &&
               TryWriteByte(address + 1u, (byte)(value >> 16)) &&
               TryWriteByte(address + 2u, (byte)(value >> 8)) &&
               TryWriteByte(address + 3u, (byte)value);
    }

    private sealed class ReadTrackingMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;

        internal ReadTrackingMemory(FakeMemory backing)
            => _backing = backing;

        internal int ReadCount { get; set; }

        public bool TryReadByte(uint address, out byte value)
        {
            ReadCount++;
            return _backing.TryReadByte(address, out value);
        }

        public bool TryReadWord(uint address, out ushort value)
        {
            ReadCount++;
            return _backing.TryReadWord(address, out value);
        }

        public bool TryReadLong(uint address, out uint value)
        {
            ReadCount++;
            return _backing.TryReadLong(address, out value);
        }

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
            => _backing.TryWriteLong(address, value);
    }

    private sealed class AddressReadTrackingMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private readonly uint _trackedAddress;

        internal AddressReadTrackingMemory(FakeMemory backing, uint trackedAddress)
        {
            _backing = backing;
            _trackedAddress = trackedAddress;
        }

        internal int TrackedReadCount { get; private set; }

        public bool TryReadByte(uint address, out byte value)
        {
            Track(address, 1);
            return _backing.TryReadByte(address, out value);
        }

        public bool TryReadWord(uint address, out ushort value)
        {
            Track(address, 2);
            return _backing.TryReadWord(address, out value);
        }

        public bool TryReadLong(uint address, out uint value)
        {
            Track(address, 4);
            return _backing.TryReadLong(address, out value);
        }

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
            => _backing.TryWriteLong(address, value);

        private void Track(uint address, uint byteCount)
        {
            if (address <= _trackedAddress &&
                _trackedAddress - address < byteCount)
            {
                TrackedReadCount++;
            }
        }
    }

    private sealed class RangeReadFaultMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private uint _firstFault;
        private uint _endFault;
        private bool _failReads;

        internal RangeReadFaultMemory(FakeMemory backing)
            => _backing = backing;

        internal int FaultedReadCount { get; private set; }

        internal void FailReads(uint address, uint byteCount)
        {
            _firstFault = address;
            _endFault = checked(address + byteCount);
            _failReads = true;
        }

        public bool TryReadByte(uint address, out byte value)
        {
            if (IsFault(address))
            {
                value = 0;
                return false;
            }

            return _backing.TryReadByte(address, out value);
        }

        public bool TryReadWord(uint address, out ushort value)
        {
            if (IsFault(address) || IsFault(unchecked(address + 1u)))
            {
                value = 0;
                return false;
            }

            return _backing.TryReadWord(address, out value);
        }

        public bool TryReadLong(uint address, out uint value)
        {
            if (IsFault(address) ||
                IsFault(unchecked(address + 1u)) ||
                IsFault(unchecked(address + 2u)) ||
                IsFault(unchecked(address + 3u)))
            {
                value = 0;
                return false;
            }

            return _backing.TryReadLong(address, out value);
        }

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
            => _backing.TryWriteLong(address, value);

        private bool IsFault(uint address)
        {
            var faulted = _failReads && address >= _firstFault && address < _endFault;
            if (faulted)
                FaultedReadCount++;

            return faulted;
        }
    }

    private sealed class AddressRangeReadFaultMemory : IGraphicsMemory
    {
        private readonly FakeMemory _backing;
        private readonly uint _trackedStart;
        private readonly uint _trackedEnd;
        private readonly uint _faultStart;
        private readonly uint _faultEnd;

        internal AddressRangeReadFaultMemory(
            FakeMemory backing,
            uint trackedStart,
            uint trackedBytes,
            uint faultStart,
            uint faultBytes)
        {
            _backing = backing;
            _trackedStart = trackedStart;
            _trackedEnd = checked(trackedStart + trackedBytes);
            _faultStart = faultStart;
            _faultEnd = checked(faultStart + faultBytes);
        }

        internal int FaultedReadCount { get; private set; }
        internal int TrackedReadCount { get; private set; }

        public bool TryReadByte(uint address, out byte value)
        {
            Track(address, 1);
            if (IsFault(address))
            {
                value = 0;
                return false;
            }

            return _backing.TryReadByte(address, out value);
        }

        public bool TryReadWord(uint address, out ushort value)
        {
            Track(address, 2);
            if (IsFault(address) || IsFault(unchecked(address + 1u)))
            {
                value = 0;
                return false;
            }

            return _backing.TryReadWord(address, out value);
        }

        public bool TryReadLong(uint address, out uint value)
        {
            Track(address, 4);
            if (IsFault(address) ||
                IsFault(unchecked(address + 1u)) ||
                IsFault(unchecked(address + 2u)) ||
                IsFault(unchecked(address + 3u)))
            {
                value = 0;
                return false;
            }

            return _backing.TryReadLong(address, out value);
        }

        public bool TryWriteByte(uint address, byte value)
            => _backing.TryWriteByte(address, value);

        public bool TryWriteWord(uint address, ushort value)
            => _backing.TryWriteWord(address, value);

        public bool TryWriteLong(uint address, uint value)
            => _backing.TryWriteLong(address, value);

        private void Track(uint address, uint byteCount)
        {
            var end = (ulong)address + byteCount;
            if (address < _trackedEnd &&
                end > _trackedStart)
            {
                TrackedReadCount++;
            }
        }

        private bool IsFault(uint address)
        {
            var faulted = address >= _faultStart && address < _faultEnd;
            if (faulted)
                FaultedReadCount++;

            return faulted;
        }
    }

    private sealed class FakeMemory : IGraphicsMemory
    {
        internal FakeMemory(int size) => Bytes = new byte[size];

        internal byte[] Bytes { get; }
        internal int WriteCount { get; private set; }

        public bool TryReadByte(uint address, out byte value)
        {
            if (address >= Bytes.Length)
            {
                value = 0;
                return false;
            }

            value = Bytes[(int)address];
            return true;
        }

        public bool TryReadWord(uint address, out ushort value)
        {
            if (address > (uint)(Bytes.Length - 2))
            {
                value = 0;
                return false;
            }

            var offset = (int)address;
            value = (ushort)((Bytes[offset] << 8) | Bytes[offset + 1]);
            return true;
        }

        public bool TryReadLong(uint address, out uint value)
        {
            if (address > (uint)(Bytes.Length - 4))
            {
                value = 0;
                return false;
            }

            var offset = (int)address;
            value = ((uint)Bytes[offset] << 24)
                | ((uint)Bytes[offset + 1] << 16)
                | ((uint)Bytes[offset + 2] << 8)
                | Bytes[offset + 3];
            return true;
        }

        public bool TryWriteByte(uint address, byte value)
        {
            if (address >= Bytes.Length)
                return false;

            WriteCount++;
            Bytes[(int)address] = value;
            return true;
        }

        public bool TryWriteWord(uint address, ushort value)
        {
            if (address > (uint)(Bytes.Length - 2))
                return false;

            WriteCount++;
            var offset = (int)address;
            Bytes[offset] = (byte)(value >> 8);
            Bytes[offset + 1] = (byte)value;
            return true;
        }

        public bool TryWriteLong(uint address, uint value)
        {
            if (address > (uint)(Bytes.Length - 4))
                return false;

            WriteCount++;
            var offset = (int)address;
            Bytes[offset] = (byte)(value >> 24);
            Bytes[offset + 1] = (byte)(value >> 16);
            Bytes[offset + 2] = (byte)(value >> 8);
            Bytes[offset + 3] = (byte)value;
            return true;
        }
    }

