    private sealed class WrappingMemory : IGraphicsMemory
    {
        private readonly Dictionary<uint, byte> _bytes = new();

        internal void WriteByte(uint address, byte value)
            => _bytes[address] = value;

        internal void WriteWord(uint address, ushort value)
        {
            WriteByte(address, (byte)(value >> 8));
            WriteByte(unchecked(address + 1u), (byte)value);
        }

        internal void WriteLong(uint address, uint value)
        {
            WriteByte(address, (byte)(value >> 24));
            WriteByte(unchecked(address + 1u), (byte)(value >> 16));
            WriteByte(unchecked(address + 2u), (byte)(value >> 8));
            WriteByte(unchecked(address + 3u), (byte)value);
        }

        public bool TryReadByte(uint address, out byte value)
            => _bytes.TryGetValue(address, out value);

        public bool TryReadWord(uint address, out ushort value)
        {
            if (!TryReadByte(address, out var high) ||
                !TryReadByte(unchecked(address + 1u), out var low))
            {
                value = 0;
                return false;
            }

            value = (ushort)((high << 8) | low);
            return true;
        }

        public bool TryReadLong(uint address, out uint value)
        {
            if (!TryReadByte(address, out var b0) ||
                !TryReadByte(unchecked(address + 1u), out var b1) ||
                !TryReadByte(unchecked(address + 2u), out var b2) ||
                !TryReadByte(unchecked(address + 3u), out var b3))
            {
                value = 0;
                return false;
            }

            value = ((uint)b0 << 24) |
                    ((uint)b1 << 16) |
                    ((uint)b2 << 8) |
                    b3;
            return true;
        }

        public bool TryWriteByte(uint address, byte value)
        {
            WriteByte(address, value);
            return true;
        }

        public bool TryWriteWord(uint address, ushort value)
        {
            WriteWord(address, value);
            return true;
        }

        public bool TryWriteLong(uint address, uint value)
        {
            WriteLong(address, value);
            return true;
        }
    }

    private sealed class FakeAllocator : IGraphicsAllocatorBackend
    {
        internal uint LastAllocatedBytes { get; private set; }
        internal GraphicsMemoryClass LastAllocatedClass { get; private set; }
        internal uint LastFreedAddress { get; private set; }
        internal uint LastFreedBytes { get; private set; }
        internal GraphicsMemoryClass LastFreedClass { get; private set; }
        internal int FreeCount { get; private set; }

        public bool TryAllocate(uint byteCount, GraphicsMemoryClass memoryClass, out uint address)
        {
            LastAllocatedBytes = byteCount;
            LastAllocatedClass = memoryClass;
            address = 0x1000;
            return byteCount != 0;
        }

        public void Free(uint address, uint byteCount, GraphicsMemoryClass memoryClass)
        {
            LastFreedAddress = address;
            LastFreedBytes = byteCount;
            LastFreedClass = memoryClass;
            FreeCount++;
        }
    }

    private sealed class FixedAddressAllocator : IGraphicsAllocatorBackend
    {
        private readonly uint _address;

        internal FixedAddressAllocator(uint address)
            => _address = address;

        internal int FreeCount { get; private set; }

        public bool TryAllocate(
            uint byteCount,
            GraphicsMemoryClass memoryClass,
            out uint address)
        {
            address = byteCount == 0 ? 0 : _address;
            return address != 0;
        }

        public void Free(
            uint address,
            uint byteCount,
            GraphicsMemoryClass memoryClass)
            => FreeCount++;
    }

    private sealed class BlockingNativeDatabaseAllocator : IGraphicsAllocatorBackend
    {
        private readonly uint _address;

        internal BlockingNativeDatabaseAllocator(uint address)
            => _address = address;

        internal ManualResetEventSlim AllocationEntered { get; } = new();
        internal ManualResetEventSlim ContinueAllocation { get; } = new();
        internal int FreeCount;

        public bool TryAllocate(
            uint byteCount,
            GraphicsMemoryClass memoryClass,
            out uint address)
        {
            AllocationEntered.Set();
            if (!ContinueAllocation.Wait(TimeSpan.FromSeconds(5)))
            {
                address = 0;
                return false;
            }

            address = byteCount == 0 ? 0 : _address;
            return address != 0;
        }

        public void Free(
            uint address,
            uint byteCount,
            GraphicsMemoryClass memoryClass)
            => Interlocked.Increment(ref FreeCount);
    }

