    private sealed class SteppingAllocator : IGraphicsAllocatorBackend
    {
        private uint _next;

        internal SteppingAllocator(uint first) => _next = first;

        internal int FreeCount { get; private set; }

        public bool TryAllocate(uint byteCount, GraphicsMemoryClass memoryClass, out uint address)
        {
            address = _next;
            if (byteCount == 0 || _next > uint.MaxValue - byteCount - 0x10u)
            {
                address = 0;
                return false;
            }

            _next += byteCount + 0x10u;
            return true;
        }

        public void Free(uint address, uint byteCount, GraphicsMemoryClass memoryClass)
            => FreeCount++;
    }

    private sealed class BitmapAllocator : IGraphicsAllocatorBackend
    {
        internal sealed record Allocation(uint Address, uint Bytes, GraphicsMemoryClass MemoryClass);

        private uint _nextAddress = 0x1000;
        private int _allocationCount;

        internal int FailAfterAllocations { get; init; } = int.MaxValue;
        internal List<Allocation> Freed { get; } = new();

        public bool TryAllocate(uint byteCount, GraphicsMemoryClass memoryClass, out uint address)
        {
            address = 0;
            if (byteCount == 0 || _allocationCount >= FailAfterAllocations)
                return false;

            address = _nextAddress;
            _nextAddress += (byteCount + 3u) & ~3u;
            _allocationCount++;
            return true;
        }

        public void Free(uint address, uint byteCount, GraphicsMemoryClass memoryClass)
            => Freed.Add(new Allocation(address, byteCount, memoryClass));
    }

    private sealed class RejectingInterleavedAllocator : IGraphicsAllocatorBackend
    {
        internal sealed record Allocation(uint Address, uint Bytes, GraphicsMemoryClass MemoryClass);

        private readonly uint _rejectedBytes;
        private uint _nextAddress = 0x1000;

        internal RejectingInterleavedAllocator(uint planeBytesToReject)
            => _rejectedBytes = planeBytesToReject;

        internal List<Allocation> Freed { get; } = new();

        public bool TryAllocate(uint byteCount, GraphicsMemoryClass memoryClass, out uint address)
        {
            if (memoryClass == GraphicsMemoryClass.Chip && byteCount == _rejectedBytes)
            {
                address = 0;
                return false;
            }

            address = _nextAddress;
            _nextAddress += (byteCount + 3u) & ~3u;
            return byteCount != 0;
        }

        public void Free(uint address, uint byteCount, GraphicsMemoryClass memoryClass)
            => Freed.Add(new Allocation(address, byteCount, memoryClass));
    }

    private sealed class DecliningInterleavedAllocator : IGraphicsAllocatorBackend
    {
        internal sealed record Allocation(uint Address, uint Bytes, GraphicsMemoryClass MemoryClass);

        private uint _nextAddress = 0x1000;
        internal List<Allocation> Freed { get; } = new();

        public bool TryAllocate(uint byteCount, GraphicsMemoryClass memoryClass, out uint address)
        {
            if (memoryClass == GraphicsMemoryClass.Chip && byteCount == 24)
            {
                // Deliberately violate the usual false-status/out-zero
                // convention so the portable boundary's cleanup is tested.
                address = 0x2000;
                return false;
            }

            address = _nextAddress;
            _nextAddress += (byteCount + 3u) & ~3u;
            return byteCount != 0;
        }

        public void Free(uint address, uint byteCount, GraphicsMemoryClass memoryClass)
            => Freed.Add(new Allocation(address, byteCount, memoryClass));
    }

    private sealed class DecliningRegionAllocator : IGraphicsAllocatorBackend
    {
        internal sealed record Allocation(uint Address, uint Bytes, GraphicsMemoryClass MemoryClass);

        private readonly bool _declineHeader;
        private readonly bool _declineFirstNode;
        private uint _nextAddress = 0x1000;
        private int _allocationCount;

        internal DecliningRegionAllocator(
            bool declineHeader = false,
            bool declineFirstNode = false)
        {
            _declineHeader = declineHeader;
            _declineFirstNode = declineFirstNode;
        }

        internal List<Allocation> Freed { get; } = new();

        public bool TryAllocate(uint byteCount, GraphicsMemoryClass memoryClass, out uint address)
        {
            if (memoryClass == GraphicsMemoryClass.Public &&
                ((_declineHeader && _allocationCount == 0 && byteCount == GraphicsLayouts.RegionSize) ||
                 (_declineFirstNode && _allocationCount == 1 && byteCount == GraphicsLayouts.RegionRectangleSize)))
            {
                address = _allocationCount == 0 ? 0x1000u : 0x2000u;
                _allocationCount++;
                return false;
            }

            address = _nextAddress;
            _nextAddress += (byteCount + 3u) & ~3u;
            _allocationCount++;
            return byteCount != 0;
        }

        public void Free(uint address, uint byteCount, GraphicsMemoryClass memoryClass)
            => Freed.Add(new Allocation(address, byteCount, memoryClass));
    }

    [Fact]
    public void RastPortOutlineAndMoveSettersFailAtomicallyOnTruncatedGuestState()
    {
        // The outline pen byte is mapped, but the Flags word at 0x20 is not.
        var outlineMemory = new FakeMemory(0x20);
        var outlineCore = new GraphicsLibraryCore(
            outlineMemory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        Assert.True(outlineMemory.TryWriteByte((uint)GraphicsLayouts.RastPortOutlinePen, 3));
        Assert.Equal(-1, outlineCore.SetOutlinePen(0, 7));
        Assert.Equal((byte)3, ReadByte(outlineMemory, (uint)GraphicsLayouts.RastPortOutlinePen));

        // CurrentX is mapped, while CurrentY is truncated out of the guest
        // range.  A failed Move must not expose only its new X coordinate.
        var moveMemory = new FakeMemory(0x26);
        var moveCore = new GraphicsLibraryCore(
            moveMemory,
            new FakeAllocator(),
            new FakeBlitter(),
            new FakeDisplay());
        Assert.True(moveMemory.TryWriteWord((uint)GraphicsLayouts.RastPortCurrentX, 4));
        Assert.Equal(-1, moveCore.Move(0, 9, 10));
        Assert.Equal((short)4, ReadSignedWord(moveMemory, (uint)GraphicsLayouts.RastPortCurrentX));
    }

    [Fact]
    public void SetFontFailsAtomicallyWhenTheCachedMetricSpanIsTruncated()
    {
        var memory = new FakeMemory(0x40);
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), new FakeBlitter(), new FakeDisplay());
        var fonts = new FakeFontBackend();

        Assert.True(memory.TryWriteLong((uint)GraphicsLayouts.RastPortFont, 0x1111));
        Assert.True(memory.TryWriteByte((uint)GraphicsLayouts.RastPortAlgoStyle, 0x22));
        Assert.True(memory.TryWriteWord((uint)GraphicsLayouts.RastPortTextHeight, 0x3333));
        Assert.True(memory.TryWriteWord((uint)GraphicsLayouts.RastPortTextWidth, 0x4444));
        Assert.True(memory.TryWriteWord((uint)GraphicsLayouts.RastPortTextBaseline, 0x5555));

        // TxSpacing at 0x40 is outside this guest range.  None of the earlier
        // font/cache fields may change when the complete update is impossible.
        Assert.Equal(-1, core.SetFont(0, 0x300, fonts));
        Assert.Equal(0x1111u, ReadLong(memory, (uint)GraphicsLayouts.RastPortFont));
        Assert.Equal((byte)0x22, ReadByte(memory, (uint)GraphicsLayouts.RastPortAlgoStyle));
        Assert.Equal((ushort)0x3333, ReadWord(memory, (uint)GraphicsLayouts.RastPortTextHeight));
        Assert.Equal((ushort)0x4444, ReadWord(memory, (uint)GraphicsLayouts.RastPortTextWidth));
        Assert.Equal((ushort)0x5555, ReadWord(memory, (uint)GraphicsLayouts.RastPortTextBaseline));
    }

    [Fact]
    public void ZeroEffectiveWriteMaskDoesNotRequireForegroundPenForDrawAndText()
    {
        const uint rastPort = 0x20;
        const uint font = 0x300;
        const uint text = 0x320;
        const uint foregroundPen =
            rastPort + (uint)GraphicsLayouts.RastPortFgPen;

        static (FakeMemory Backing, RangeReadFaultMemory Memory, GraphicsLibraryCore Core)
            Prepare(uint rastPort, uint font, uint text, uint foregroundPen)
        {
            var backing = new FakeMemory(0x2000);
            var setup = CreateCore(backing);
            var fonts = new FakeFontBackend();
            Assert.Equal(0, setup.SetFont(rastPort, font, fonts));
            Assert.True(backing.TryWriteByte(text, (byte)'A'));
            // Give the mapped gateway the same small fixed-cell font that
            // the direct fake backend exposes.
            Assert.True(backing.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontYSize,
                3));
            Assert.True(backing.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontXSize,
                3));
            Assert.True(backing.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontBaseline,
                3));
            Assert.True(backing.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontLoChar,
                (byte)'A'));
            Assert.True(backing.TryWriteByte(
                font + (uint)GraphicsLayouts.TextFontHiChar,
                (byte)'A'));
            Assert.True(backing.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharData,
                0xA00));
            Assert.True(backing.TryWriteWord(
                font + (uint)GraphicsLayouts.TextFontModulo,
                1));
            Assert.True(backing.TryWriteLong(
                font + (uint)GraphicsLayouts.TextFontCharLoc,
                0));
            Assert.True(backing.TryWriteByte(0xA00, 0xE0));
            Assert.True(backing.TryWriteByte(0xA01, 0xA0));
            Assert.True(backing.TryWriteByte(0xA02, 0xE0));
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortMask,
                0));
            Assert.True(backing.TryWriteByte(
                rastPort + (uint)GraphicsLayouts.RastPortDrawMode,
                0)); // JAM1: only FgPen would be needed for a real write.

            var memory = new RangeReadFaultMemory(backing);
            memory.FailReads(foregroundPen, sizeof(byte));
            var core = new GraphicsLibraryCore(
                memory,
                new FakeAllocator(),
                new FakeBlitter(),
                new FakeDisplay());
            return (backing, memory, core);
        }

        var directDraw = Prepare(rastPort, font, text, foregroundPen);
        Assert.Equal(0, directDraw.Core.Draw(rastPort, 1, 0));
        Assert.Equal(0, directDraw.Memory.FaultedReadCount);
        Assert.Equal((byte)0, ReadByte(directDraw.Backing, 0x400));

        var mappedDraw = Prepare(rastPort, font, text, foregroundPen);
        var drawAdapter = new CopperStartGraphicsRegisterAdapter(mappedDraw.Core);
        var drawState = new M68kCpuState
        {
            A = { [1] = rastPort },
            D = { [0] = 1, [1] = 0, [2] = 0xCAFE_BABEu },
            Cycles = 37
        };
        Assert.True(drawAdapter.TryInvoke(drawState, (int)GraphicsLvo.Draw));
        Assert.Equal(0u, drawState.D[0]);
        Assert.Equal(37, drawState.Cycles);
        Assert.Equal(0, mappedDraw.Memory.FaultedReadCount);
        Assert.Equal((byte)0, ReadByte(mappedDraw.Backing, 0x400));

        var directText = Prepare(rastPort, font, text, foregroundPen);
        var directFonts = new FakeFontBackend();
        Assert.Equal(0, directText.Core.Text(rastPort, text, 1, directFonts));
        Assert.Equal(0, directText.Memory.FaultedReadCount);
        Assert.Equal((byte)0, ReadByte(directText.Backing, 0x400));

        var mappedText = Prepare(rastPort, font, text, foregroundPen);
        var textAdapter = new CopperStartGraphicsRegisterAdapter(mappedText.Core);
        var textState = new M68kCpuState
        {
            A = { [0] = text, [1] = rastPort },
            D = { [0] = 1, [1] = 0xCAFE_BABEu },
            Cycles = 41
        };
        Assert.True(textAdapter.TryInvoke(textState, (int)GraphicsLvo.Text));
        Assert.Equal(0u, textState.D[0]);
        Assert.Equal(41, textState.Cycles);
        Assert.Equal(0, mappedText.Memory.FaultedReadCount);
        Assert.Equal((byte)0, ReadByte(mappedText.Backing, 0x400));
    }

    [Fact]
    public void ZeroWriteMaskMakesPlanarPrimitivesSuccessfulNoOps()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);

        Assert.Equal(0, core.SetRast(0x20, 3));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 0));
        Assert.Equal(0, core.SetWriteMask(0x20, 0));

        Assert.Equal(0, core.WritePixel(0x20, 0, 0));
        Assert.Equal(0, core.RectFill(0x20, 0, 0, 1, 1));
        Assert.Equal(0, core.Move(0x20, 0, 0));
        Assert.Equal(0, core.Draw(0x20, 1, 0));
        Assert.Equal(3, core.ReadPixel(0x20, 0, 0));
    }

    [Fact]
    public void MultiPlanePixelWritePreflightsEverySelectedPlane()
    {
        var memory = new FakeMemory(0x1000);
        var core = new GraphicsLibraryCore(memory, new FakeAllocator(), new FakeBlitter(), new FakeDisplay());
        const uint rastPort = 0x20;
        const uint bitMap = 0x100;
        const uint firstPlane = 0x200;

        Assert.True(memory.TryWriteLong(rastPort + (uint)GraphicsLayouts.RastPortBitMap, bitMap));
        Assert.True(memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortFgPen, 1));
        Assert.True(memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortDrawMode, 1));
        Assert.True(memory.TryWriteByte(rastPort + (uint)GraphicsLayouts.RastPortMask, 3));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapBytesPerRow, 2));
        Assert.True(memory.TryWriteWord(bitMap + (uint)GraphicsLayouts.BitMapRows, 1));
        Assert.True(memory.TryWriteByte(bitMap + (uint)GraphicsLayouts.BitMapDepth, 2));
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes, firstPlane));
        // The second plane pointer is nonzero but outside the guest memory.
        Assert.True(memory.TryWriteLong(bitMap + (uint)GraphicsLayouts.BitMapPlanes + 4, 0x2000));

        Assert.Equal(-1, core.WritePixel(rastPort, 0, 0));
        Assert.Equal((byte)0, ReadByte(memory, firstPlane));
    }

    [Fact]
    public void TextExtentDoesNotPartiallyPublishIntoATruncatedGuestResult()
    {
        var memory = new FakeMemory(0x2000);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint text = 0x320;
        const uint extent = 0x1FFB;

        Assert.True(memory.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, 0x300, fonts));
        Assert.True(memory.TryWriteWord(extent + (uint)GraphicsLayouts.TextExtentWidth, 0xAAAA));

        // The final TextExtent fields would lie beyond the guest range.
        Assert.Equal(-1, core.TextExtent(0x20, text, 1, extent, fonts));
        Assert.Equal((ushort)0xAAAA, ReadWord(memory, extent + (uint)GraphicsLayouts.TextExtentWidth));
    }

    [Fact]
    public void TextExtentRestoresTheGuestResultWhenALateWordWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint text = 0x320;
        const uint extent = 0x600;

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.True(backing.TryWriteByte(extent + (uint)index, (byte)(0xA0 + index)));
        Assert.Equal(0, core.SetFont(0x20, 0x300, fonts));

        // Width completes; fail the second byte of the height word and
        // require the full twelve-byte result to return to its old contents.
        memory.FailOnNextByteWrite(3);
        Assert.Equal(-1, core.TextExtent(0x20, text, 1, extent, fonts));
        for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
            Assert.Equal((byte)(0xA0 + index), ReadByte(backing, extent + (uint)index));
    }

    [Fact]
    public void TextFitAndFontExtentRestoreTheGuestResultWhenALateWordWriteFails()
    {
        var backing = new FakeMemory(0x2000);
        var memory = new FailingByteWriteMemory(backing);
        var core = CreateCore(memory);
        var fonts = new FakeFontBackend();
        const uint font = 0x300;
        const uint text = 0x320;
        const uint extent = 0x600;

        Assert.True(backing.TryWriteByte(text, (byte)'A'));
        Assert.Equal(0, core.SetFont(0x20, font, fonts));

        void SeedResult(byte value)
        {
            for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
                Assert.True(backing.TryWriteByte(extent + (uint)index, unchecked((byte)(value + index))));
        }

        void AssertResult(byte value)
        {
            for (var index = 0; index < GraphicsLayouts.TextExtentSize; index++)
                Assert.Equal(unchecked((byte)(value + index)), ReadByte(backing, extent + (uint)index));
        }

        // Width completes; fail the second byte of the height WORD. Both
        // vectors must restore the complete caller-owned result envelope,
        // not just the fields written before the failed store.
        SeedResult(0xA0);
        memory.FailOnNextByteWrite(3);
        Assert.Equal(-1, core.TextFit(0x20, text, 1, extent, 0, 1, 8, 3, fonts));
        AssertResult(0xA0);

        SeedResult(0xB0);
        memory.FailOnNextByteWrite(3);
        Assert.Equal(-1, core.FontExtent(font, extent, fonts));
        AssertResult(0xB0);
    }

    private sealed class FakeFontBackend : IGraphicsFontBackend
    {
        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = new GraphicsFontMetrics(
                3,
                3,
                3,
                0,
                loChar: (byte)'A',
                hiChar: (byte)'A');
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            glyph = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL);
            return fontAddress != 0 && character == (byte)'A';
        }
    }

    private sealed class AntialiasColorFontBackend :
        IGraphicsFontBackend,
        IGraphicsColorFontBackend
    {
        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = new GraphicsFontMetrics(
                3,
                3,
                3,
                0,
                style: 0x40,
                loChar: (byte)'A',
                hiChar: (byte)'A');
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            glyph = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL);
            return fontAddress != 0 && character == (byte)'A';
        }

        public bool TryGetColorFont(uint fontAddress, out GraphicsColorFontInfo colorFont)
        {
            colorFont = new GraphicsColorFontInfo(
                flags: 1 << 2, // CT_ANTIALIAS: provider/native-owned form
                depth: 1,
                foregroundColor: byte.MaxValue,
                lowColor: 0,
                highColor: 1,
                planePick: 1,
                planeOnOff: 0,
                planeData: new[] { 0x600u });
            return fontAddress != 0;
        }

        public bool TryGetColorGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
            => TryGetGlyph(fontAddress, character, out glyph);
    }

    private sealed class CountingHiddenColorFontBackend :
        IGraphicsFontBackend,
        IGraphicsColorFontBackend
    {
        internal int ColorFontRequests { get; private set; }

        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = new GraphicsFontMetrics(
                3,
                3,
                3,
                0,
                style: 0x40,
                loChar: (byte)'A',
                hiChar: (byte)'A');
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            glyph = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL);
            return fontAddress != 0 && character == (byte)'A';
        }

        public bool TryGetColorFont(uint fontAddress, out GraphicsColorFontInfo colorFont)
        {
            ColorFontRequests++;
            colorFont = default;
            return false;
        }

        public bool TryGetColorGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
            => TryGetGlyph(fontAddress, character, out glyph);
    }

    private sealed class PartialHiddenColorFontBackend :
        IGraphicsFontBackend,
        IGraphicsColorFontBackend
    {
        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = new GraphicsFontMetrics(
                3,
                3,
                3,
                0,
                style: 0x40,
                loChar: (byte)'A',
                hiChar: (byte)'A');
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            // The normal TextFont strike is intentionally empty; the
            // ColorTextFont plane below supplies the visible source bits.
            glyph = new GraphicsGlyph(
                width: 3,
                height: 3,
                advance: 4,
                kerning: 0,
                charData: 0,
                modulo: 2,
                bitOffset: 0);
            return fontAddress != 0 && character == (byte)'A';
        }

        public bool TryGetColorFont(uint fontAddress, out GraphicsColorFontInfo colorFont)
        {
            colorFont = new GraphicsColorFontInfo(
                flags: 1,
                depth: 1,
                foregroundColor: byte.MaxValue,
                lowColor: 0,
                highColor: 1,
                planePick: 1,
                planeOnOff: 0,
                planeData: new[] { 0x1FFEu });
            return fontAddress != 0;
        }

        public bool TryGetColorGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
            => TryGetGlyph(fontAddress, character, out glyph);
    }

    private sealed class DefaultFontBackend : IGraphicsFontBackend
    {
        private readonly uint _defaultFont;

        internal DefaultFontBackend(uint defaultFont)
        {
            _defaultFont = defaultFont;
        }

        public bool TryGetDefaultFont(out uint fontAddress)
        {
            fontAddress = _defaultFont;
            return fontAddress != 0;
        }

        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = new GraphicsFontMetrics(
                9,
                8,
                7,
                0,
                loChar: (byte)'A',
                hiChar: (byte)'A');
            return fontAddress == _defaultFont;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            glyph = default;
            return false;
        }
    }

    private sealed class CountingFontBackend : IGraphicsFontBackend
    {
        internal int MetricsRequests { get; private set; }
        internal int GlyphRequests { get; private set; }

        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            MetricsRequests++;
            metrics = new GraphicsFontMetrics(3, 3, 3, 0, loChar: (byte)'A', hiChar: (byte)'A');
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            GlyphRequests++;
            glyph = new GraphicsGlyph(3, 3, 4, 0xE0A0E00000000000UL);
            return fontAddress != 0 && character == (byte)'A';
        }
    }

    private sealed class TableFontBackend : IGraphicsFontBackend
    {
        private readonly GraphicsFontMetrics _metrics;
        private readonly IReadOnlyDictionary<byte, GraphicsGlyph> _glyphs;

        internal TableFontBackend(
            GraphicsFontMetrics metrics,
            IReadOnlyDictionary<byte, GraphicsGlyph> glyphs)
        {
            _metrics = metrics;
            _glyphs = glyphs;
        }

        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = _metrics;
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            glyph = default;
            return fontAddress != 0 && _glyphs.TryGetValue(character, out glyph);
        }
    }

    private sealed class DefaultGlyphFontBackend : IGraphicsFontBackend
    {
        private readonly GraphicsFontMetrics _metrics;
        private readonly IReadOnlyDictionary<byte, GraphicsGlyph> _glyphs;
        private readonly GraphicsGlyph _defaultGlyph;

        internal DefaultGlyphFontBackend(
            GraphicsFontMetrics metrics,
            IReadOnlyDictionary<byte, GraphicsGlyph> glyphs,
            GraphicsGlyph defaultGlyph)
        {
            _metrics = metrics;
            _glyphs = glyphs;
            _defaultGlyph = defaultGlyph;
        }

        public bool TryGetMetrics(uint fontAddress, out GraphicsFontMetrics metrics)
        {
            metrics = _metrics;
            return fontAddress != 0;
        }

        public bool TryGetGlyph(uint fontAddress, byte character, out GraphicsGlyph glyph)
        {
            glyph = default;
            return fontAddress != 0 && _glyphs.TryGetValue(character, out glyph);
        }

        public bool TryGetDefaultGlyph(uint fontAddress, out GraphicsGlyph glyph)
        {
            glyph = _defaultGlyph;
            return fontAddress != 0;
        }
    }

    private sealed class FakeBlitter : IGraphicsBlitterBackend, IGraphicsQueuedBlitterBackend
    {
        internal int OwnCount { get; private set; }
        internal int DisownCount { get; private set; }
        internal int WaitCount { get; private set; }
        internal List<(uint Address, bool BeamSynchronized, short BeamSync)> Queued { get; } = new();

        public void Own() => OwnCount++;
        public void Disown() => DisownCount++;
        public void Wait() => WaitCount++;
        public void Submit(uint operationAddress) { }
        public void SubmitQueued(uint operationAddress, bool beamSynchronized, short beamSync)
            => Queued.Add((operationAddress, beamSynchronized, beamSync));
    }

    private sealed class RecordingGelsBackend : IGraphicsGelsBackend
    {
        internal int CollisionCount { get; private set; }
        internal List<(uint RastPort, uint ViewPort)> Drawn { get; } = new();
        internal List<(uint First, uint Second, uint Routine)> Collisions { get; } = new();
        internal List<(uint Sprite, ushort Flags, uint Routine)> Boundaries { get; } = new();

        public void DrawGList(uint rastPort, uint viewPort)
            => Drawn.Add((rastPort, viewPort));

        public void DoCollision(uint rastPort)
            => CollisionCount++;

        public void RemIBob(uint bob, uint rastPort, uint viewPort) { }

        public void DispatchCollision(uint firstVSprite, uint secondVSprite, uint routineAddress)
            => Collisions.Add((firstVSprite, secondVSprite, routineAddress));

        public void DispatchBoundary(uint vSprite, ushort boundaryFlags, uint routineAddress)
            => Boundaries.Add((vSprite, boundaryFlags, routineAddress));
    }

    private sealed class MutatingGelsBackend : IGraphicsGelsBackend
    {
        private readonly IGraphicsMemory _memory;
        private readonly uint _plane;

        internal MutatingGelsBackend(IGraphicsMemory memory, uint plane)
        {
            _memory = memory;
            _plane = plane;
        }

        public void DrawGList(uint rastPort, uint viewPort)
            => _memory.TryWriteWord(_plane, 0xFFFF);

        public void DoCollision(uint rastPort) { }
        public void RemIBob(uint bob, uint rastPort, uint viewPort) { }
        public void DispatchCollision(uint firstVSprite, uint secondVSprite, uint routineAddress) { }
        public void DispatchBoundary(uint vSprite, ushort boundaryFlags, uint routineAddress) { }
    }

    private sealed class RecordingSpriteBackend : IGraphicsSpriteBackend
    {
        internal List<(uint ViewPort, uint Sprite, short X, short Y)> Moves { get; } = new();
        internal List<(uint ViewPort, uint Sprite, uint Image)> Changes { get; } = new();

        public void MoveSprite(uint viewPort, uint sprite, short x, short y)
            => Moves.Add((viewPort, sprite, x, y));

