    private sealed class RecordingLayerGatewayBackend :
        IGraphicsLayerBackend,
        IGraphicsLayerRasterBackend,
        IGraphicsLayerGatewayBackend
    {
        internal M68kHostGatewayResult LockResult { get; init; }
        internal GraphicsLvo? RasterLvo { get; init; }
        internal bool ClaimRaster { get; init; } = true;
        internal List<(GraphicsLvo Lvo, uint Layer)> CompanionCalls { get; } = new();
        internal List<(GraphicsLvo Lvo, uint RastPort)> RasterCalls { get; } = new();

        public void Lock(uint layerAddress) { }
        public bool TryLock(uint layerAddress) => true;
        public void Unlock(uint layerAddress) { }
        public bool SyncSuperBitMap(uint layerAddress) => true;
        public bool CopySuperBitMap(uint layerAddress) => true;

        public bool TryDraw(uint rastPortAddress, short x, short y)
        {
            RasterCalls.Add((GraphicsLvo.Draw, rastPortAddress));
            return RasterLvo == GraphicsLvo.Draw;
        }

        public bool TryText(uint rastPortAddress, uint textAddress, short length)
            => RasterLvo == GraphicsLvo.Text;

        public bool TryInvokeGraphicsRaster(
            M68kCpuState state,
            GraphicsLvo lvo,
            out M68kHostGatewayResult result)
        {
            if (RasterLvo == lvo)
            {
                RasterCalls.Add((lvo, state.A[1]));
            }

            if (ClaimRaster && RasterLvo == lvo)
            {
                state.D[0] = 0;
                result = M68kHostGatewayResult.Completed;
                return true;
            }

            result = M68kHostGatewayResult.Completed;
            return false;
        }

        public bool TryInvokeGraphicsCompanion(
            M68kCpuState state,
            GraphicsLvo lvo,
            out M68kHostGatewayResult result)
        {
            CompanionCalls.Add((lvo, state.A[5]));
            switch (lvo)
            {
                case GraphicsLvo.LockLayerRom:
                    state.D[0] = 0;
                    result = LockResult;
                    return true;
                case GraphicsLvo.AttemptLockLayerRom:
                    state.D[0] = 1;
                    result = M68kHostGatewayResult.Completed;
                    return true;
                case GraphicsLvo.UnlockLayerRom:
                    state.D[0] = 0;
                    result = M68kHostGatewayResult.Completed;
                    return true;
                default:
                    result = M68kHostGatewayResult.Completed;
                    return false;
            }
        }
    }

