    private sealed class BlockingPaletteDisplay : IGraphicsDisplayBackend, IGraphicsPaletteBackend
    {
        internal ManualResetEventSlim FirstEntered { get; } = new();
        internal ManualResetEventSlim SecondEntered { get; } = new();
        internal ManualResetEventSlim Release { get; } = new();
        internal int Active;
        internal int MaxActive;
        internal int CallCount;

        public void PublishView(uint viewAddress) { }
        public void WaitForTopOfFrame() { }
        public void WaitForBeginningOfVerticalBlank(uint viewPortAddress) { }
        public ushort GetBeamPosition() => 0;

        public void LoadRgb4(uint viewPortAddress, uint colorsAddress, short count)
        {
            var active = Interlocked.Increment(ref Active);
            Interlocked.Increment(ref CallCount);
            while (true)
            {
                var observed = Volatile.Read(ref MaxActive);
                if (observed >= active ||
                    Interlocked.CompareExchange(ref MaxActive, active, observed) == observed)
                    break;
            }

            if (CallCount == 1)
                FirstEntered.Set();
            else
                SecondEntered.Set();

            Release.Wait(TimeSpan.FromSeconds(10));
            Interlocked.Decrement(ref Active);
        }

        public void SetRgb4(uint viewPortAddress, short index, byte red, byte green, byte blue) { }
    }

