    private sealed class FakeDisplayWithMakeStatus :
        IGraphicsDisplayBackend,
        IGraphicsCopperBackend,
        IGraphicsCopperBuildResourceStatusBackend,
        IGraphicsCopperBuildStatusBackend,
        IGraphicsCopperMergeStatusBackend
    {
        internal int MakeStatus { get; set; }
        internal int MakeStatusCount { get; private set; }
        internal IGraphicsMemory? MutationMemory { get; set; }
        internal bool MutateLinksBeforeReturning { get; set; }
        internal int MergeStatus { get; set; } = GraphicsCopperOperations.MergeOk;
        internal int MergeStatusCount { get; private set; }
        internal IGraphicsMemory? MergeMutationMemory { get; set; }
        internal uint[]? MergeMutationViewPorts { get; set; }
        internal bool MutateMergeLinksBeforeReturning { get; set; }

        public bool HasExplicitMakeVPortOwner => true;

        public void PublishView(uint viewAddress) { }
        public void WaitForTopOfFrame() { }
        public void WaitForBeginningOfVerticalBlank(uint viewPortAddress) { }
        public ushort GetBeamPosition() => 0;
        public void MakeViewPort(uint viewAddress, uint viewPortAddress) { }
        public void MergeCopperLists(uint viewAddress) { }
        public int MakeViewPortStatus(uint viewAddress, uint viewPortAddress)
        {
            MakeStatusCount++;
            if (MutateLinksBeforeReturning && MutationMemory is not null)
            {
                foreach (var (offset, value) in new[]
                         {
                             (GraphicsLayouts.ViewPortDspIns, 0xA410u),
                             (GraphicsLayouts.ViewPortSprIns, 0xA510u),
                             (GraphicsLayouts.ViewPortClrIns, 0xA610u),
                             (GraphicsLayouts.ViewPortUCopIns, 0xA710u)
                         })
                {
                    _ = MutationMemory.TryWriteLong(
                        viewPortAddress + (uint)offset,
                        value);
                }
            }

            return MakeStatus;
        }

        public int MergeCopperListsStatus(uint viewAddress)
        {
            _ = viewAddress;
            MergeStatusCount++;
            if (MutateMergeLinksBeforeReturning && MergeMutationMemory is not null)
            {
                var viewPorts = MergeMutationViewPorts ?? Array.Empty<uint>();
                for (var index = 0; index < viewPorts.Length; index++)
                {
                    var viewPortAddress = viewPorts[index];
                    foreach (var (offset, value) in new[]
                             {
                                 (GraphicsLayouts.ViewPortDspIns, 0xB410u),
                                 (GraphicsLayouts.ViewPortSprIns, 0xB510u),
                                 (GraphicsLayouts.ViewPortClrIns, 0xB610u),
                                 (GraphicsLayouts.ViewPortUCopIns, 0xB710u)
                             })
                    {
                        _ = MergeMutationMemory.TryWriteLong(
                            viewPortAddress + (uint)offset,
                            value + (uint)(index * 0x1000));
                    }
                }
            }

            return MergeStatus;
        }
    }

