        internal StatusViewDisplay(IGraphicsMemory memory, uint activeViewAddress)
        {
            _memory = memory;
            _activeViewAddress = activeViewAddress;
        }

        internal bool Accept { get; set; }
        internal uint ObservedActiveView { get; private set; }
        internal long ObservedCycle { get; private set; }
        internal uint PublishedView { get; private set; }

        public void PublishView(uint viewAddress)
            => PublishedView = viewAddress;

        public bool TryPublishView(uint viewAddress, long cycle)
        {
            _memory.TryReadLong(_activeViewAddress, out var activeView);
            ObservedActiveView = activeView;
            ObservedCycle = cycle;
            if (Accept)
                PublishedView = viewAddress;

            return Accept;
        }

        public void WaitForTopOfFrame() { }
