    private sealed class BlockingScrollDisplay :
        IGraphicsDisplayBackend,
        IGraphicsViewportDisplayBackend
    {
        private readonly ManualResetEventSlim _providerEntered;
        private readonly ManualResetEventSlim _continueProvider;

        internal BlockingScrollDisplay(
            ManualResetEventSlim providerEntered,
            ManualResetEventSlim continueProvider)
        {
            _providerEntered = providerEntered;
            _continueProvider = continueProvider;
        }

        internal uint ScrolledViewPort { get; private set; }

        public void PublishView(uint viewAddress) { }
        public void WaitForTopOfFrame() { }
        public void WaitForBeginningOfVerticalBlank(uint viewPortAddress) { }
        public ushort GetBeamPosition() => 0;

        public void ScrollViewPort(uint viewPortAddress)
        {
            ScrolledViewPort = viewPortAddress;
            _providerEntered.Set();
            if (!_continueProvider.Wait(TimeSpan.FromSeconds(5)))
                throw new TimeoutException("ScrollVPort provider was not released.");
        }
    }

